local function destroyHubGui()
    local pg = LP and LP:FindFirstChild("PlayerGui")
    if not pg then
        return
    end
    for _, name in ipairs({ "NodeHubNeonUI", "NodeHubDropdownOverlay", "STEALEGG_PERF_HUD" }) do
        local old = pg:FindFirstChild(name)
        if old then
            pcall(function()
                old:Destroy()
            end)
        end
    end
end

local function stopLoaded(loaded)
    if type(loaded) ~= "table" then
        return
    end
    for _, mod in pairs(loaded) do
        if type(mod) == "table" then
            if type(mod.setEnabled) == "function" then
                pcall(mod.setEnabled, false)
            end
            if type(mod.Stop) == "function" then
                pcall(mod.Stop, mod)
            end
        end
    end
end

