local function safePlayerFileName(name)
    local s = tostring(name or "player")
    s = s:gsub("[^%w%-_.]", "_")
    s = s:gsub("_+", "_")
    if s == "" or s == "_" then
        s = "player"
    end
    return s:sub(1, 48)
end

local function playerSavePath()
    return SAVE_DIR .. "/" .. safePlayerFileName(LP and LP.Name) .. ".json"
end

