-- PlayerGui utama. CoreGui/gethui dibersihkan kalau ada sisa lama.
local function destroyNamedGui(name)
    local pg = PlayerGui:FindFirstChild(name)
    if pg then
        pcall(function()
            pg:Destroy()
        end)
    end
    pcall(function()
        if typeof(gethui) == "function" then
            local hui = gethui()
            local old = hui and hui:FindFirstChild(name)
            if old then
                old:Destroy()
            end
        end
    end)
    pcall(function()
        local cg = game:GetService("CoreGui")
        local old = cg:FindFirstChild(name)
        if old then
            old:Destroy()
        end
    end)
    -- sisa host lama (kalau ada)
    pcall(function()
        local host = workspace:FindFirstChild(LOADING_HOST_NAME)
        if host then
            host:Destroy()
        end
    end)
end

