    do
        local fpsAcc, fpsFrames, lastAt = 0, 0, 0
        local env = (type(getgenv) == "function" and getgenv()) or _G
        local function sessionClock()
            local job = tostring(game.JobId or "")
            if env.__StealEggHudJob ~= job or type(env.__StealEggHudT0) ~= "number" then
                env.__StealEggHudJob = job
                env.__StealEggHudT0 = os.clock()
            end
            local sec = math.max(0, math.floor(os.clock() - env.__StealEggHudT0))
            local h = math.floor(sec / 3600)
            local m = math.floor((sec % 3600) / 60)
            local s = sec % 60
            if h > 0 then
                return string.format("%d:%02d:%02d", h, m, s)
            end
            return string.format("%d:%02d", m, s)
        end
        local function readPing()
            local ok, v = pcall(function()
                if LP and type(LP.GetNetworkPing) == "function" then
                    return LP:GetNetworkPing() * 1000
                end
                return nil
            end)
            if ok and type(v) == "number" then
                return math.max(0, math.floor(v + 0.5))
            end
            return 0
        end
        if self._headerFpsConn then
            pcall(function()
                self._headerFpsConn:Disconnect()
            end)
        end
        self._headerFpsConn = RunService.Heartbeat:Connect(function(dt)
            if not fpsLbl or not fpsLbl.Parent then
                return
            end
            local show = env.PERF_HUD_ENABLED ~= false
            fpsLbl.Visible = show
            if show ~= true then
                return
            end
            fpsAcc += dt
            fpsFrames += 1
            local now = os.clock()
            if (now - lastAt) < 0.5 then
                return
            end
            lastAt = now
            local fps = (fpsAcc > 0) and math.floor((fpsFrames / fpsAcc) + 0.5) or 0
            fpsAcc = 0
            fpsFrames = 0
            fpsLbl.Text = string.format(
                '<font color="#FFE34D"><b>%d</b></font> FPS  ·  <font color="#FFE34D"><b>%s</b></font>  ·  %dms',
                fps,
                sessionClock(),
                readPing()
            )
        end)
    end

