-- API: REGISTER SUB TAB
-- ======================
function MainUI:RegisterSubTab(mainKey, subKey, label, builderFn, order, opts)
    if type(order) == "table" then
        opts = order
        order = opts.order
    end
    opts = type(opts) == "table" and opts or {}
    self.subTabs[mainKey] = self.subTabs[mainKey] or {}
    self.subTabs[mainKey][subKey] = {
        label   = label or subKey,
        order   = order or 1,
        builder = builderFn,
        icon    = opts.icon,
    }

    -- kalau mainKey sedang aktif, rebuild bar subtab
    if self.activeMainKey == mainKey then
        self:_rebuildSubTabs(mainKey)
    end
end

-- INTERNAL: rebuild bar sub tab untuk 1 mainKey
-- INTERNAL: rebuild bar sub tab untuk 1 mainKey
function MainUI:_rebuildSubTabs(mainKey)
    -- hapus tombol lama
    for _, child in ipairs(self.subBar:GetChildren()) do
        if child:IsA("TextButton") then
            child:Destroy()
        end
    end
    self.subTabButtons = {}

    local list = self.subTabs[mainKey]
    if not list then return end

    -- sort by order
    local arr = {}
    for sk, info in pairs(list) do
        table.insert(arr, { key = sk, info = info })
    end
    table.sort(arr, function(a,b)
        return (a.info.order or 1) < (b.info.order or 1)
    end)

    ----------------------------------------------------------------
    -- AUTO WIDTH: makin banyak sub tab → makin kecil
    ----------------------------------------------------------------
    local count = #arr
    local baseWidth = 80
    local minWidth  = 73
    local maxWidth  = 120
    local btnWidth  = baseWidth

    if count > 0 then
        if count <= 4 then
            btnWidth = baseWidth
        else
            local shrinkStep = 8
            btnWidth = baseWidth - (count - 4) * shrinkStep
        end
        btnWidth = math.clamp(btnWidth, minWidth, maxWidth)
    end

    ----------------------------------------------------------------
    -- BUILD BUTTONS: style D (glow border)
    ----------------------------------------------------------------
    for _, item in ipairs(arr) do
        local subKey = item.key
        local info   = item.info

        local hasIcon = type(info.icon) == "string" and info.icon ~= ""
        local thisWidth = hasIcon and 32 or btnWidth

        local btn = Instance.new("TextButton")
        btn.Name = "Sub_" .. subKey
        btn.AutoButtonColor = false
        btn.Size = UDim2.new(0, thisWidth, 1, 0)
        btn.BackgroundColor3 = COLOR_PANEL
        btn.BackgroundTransparency = SUBTAB_BG_TRANSPARENCY
        btn.BorderSizePixel = 0
        btn.Text = hasIcon and "" or info.label
        btn.TextSize = 12
        btn.Font = Enum.Font.GothamBold
        btn.TextTruncate = Enum.TextTruncate.AtEnd
        btn.TextColor3 = COLOR_GRAY_TEXT            -- non-aktif default
        btn.LayoutOrder = info.order or 1
        btn.Parent = self.subBar
        createCorner(btn, 999)

        local iconImg = nil
        if hasIcon then
            iconImg = Instance.new("ImageLabel")
            iconImg.Name = "Icon"
            iconImg.BackgroundTransparency = 1
            iconImg.AnchorPoint = Vector2.new(0.5, 0.5)
            iconImg.Position = UDim2.new(0.5, 0, 0.5, 0)
            iconImg.Size = UDim2.new(0, 18, 0, 18)
            iconImg.Image = info.icon
            iconImg.ImageColor3 = COLOR_GRAY_TEXT
            iconImg.ScaleType = Enum.ScaleType.Fit
            iconImg.ZIndex = btn.ZIndex + 1
            iconImg.Parent = btn
        end

        -- border neon / ghost
        local stroke = createStroke(btn, Color3.fromRGB(90,90,90), 1, 0.5)
        -- Transparency 0.5 → ghost, non-aktif

        self.subTabButtons[subKey] = {
            button = btn,
            stroke = stroke,
            icon = iconImg,
        }

        -- hover effect: sedikit terang kalau belum aktif
        btn.MouseEnter:Connect(function()
            if self.activeSubKey ~= subKey then
                tweenColor(btn, "TextColor3", Color3.fromRGB(220,220,220))
                if iconImg then
                    tweenColor(iconImg, "ImageColor3", Color3.fromRGB(220,220,220))
                end
                stroke.Transparency = 0.3
            end
        end)

        btn.MouseLeave:Connect(function()
            if self.activeSubKey ~= subKey then
                tweenColor(btn, "TextColor3", COLOR_GRAY_TEXT)
                if iconImg then
                    tweenColor(iconImg, "ImageColor3", COLOR_GRAY_TEXT)
                end
                stroke.Transparency = 0.5
            end
        end)

        btn.MouseButton1Click:Connect(function()
            self:_setActiveSubTab(mainKey, subKey)
        end)
    end
end


function MainUI:_applySubTabVisual(activeSubKey)
    local style = self.subTabStyle or "pill"

        ----------------------------------------------------------------
    -- STYLE D: glow neon capsule border
    ----------------------------------------------------------------
    for sKey, pack in pairs(self.subTabButtons) do
        local btn    = pack.button
        local stroke = pack.stroke

        if sKey == activeSubKey then
            -- 🔥 AKTIF → border neon kuning, teks kuning
            tweenColor(btn, "BackgroundColor3", Color3.fromRGB(16,16,16))
            btn.BackgroundTransparency = SUBTAB_BG_ACTIVE_TRANSPARENCY
            tweenColor(btn, "TextColor3", COLOR_YELLOW)
            if pack.icon then
                tweenColor(pack.icon, "ImageColor3", COLOR_YELLOW)
            end

            if stroke then
                stroke.Color        = COLOR_YELLOW
                stroke.Thickness    = 2
                stroke.Transparency = 0     -- full terlihat
            end
        else
            -- 🌑 NON-AKTIF → border abu ghost, teks abu
            tweenColor(btn, "BackgroundColor3", COLOR_PANEL)
            btn.BackgroundTransparency = SUBTAB_BG_TRANSPARENCY
            tweenColor(btn, "TextColor3", COLOR_GRAY_TEXT)
            if pack.icon then
                tweenColor(pack.icon, "ImageColor3", COLOR_GRAY_TEXT)
            end

            if stroke then
                stroke.Color        = Color3.fromRGB(90,90,90)
                stroke.Thickness    = 1
                stroke.Transparency = 0.5   -- ghost
            end
        end
    end

end

-- ======================
-- API: SET ACTIVE MAIN TAB
-- ======================
function MainUI:SetActiveMainTab(key)
    self.activeMainKey = key

    for name, btn in pairs(self.mainTabButtons) do
        local underline = btn:FindFirstChild("Underline")
        if name == key then
            tweenColor(btn, "TextColor3", COLOR_YELLOW)
            if underline then
                underline.Size = UDim2.new(1, -16, 0, 2)
                underline.BackgroundTransparency = 0
            end
        else
            tweenColor(btn, "TextColor3", COLOR_WHITE)
            if underline then
                underline.Size = UDim2.new(0, 0, 0, 2)
                underline.BackgroundTransparency = 0.35
            end
        end
    end

    self:_rebuildSubTabs(key)

    -- pick pertama berdasarkan order
    local list = self.subTabs[key]
    if list then
        local firstKey
        local firstOrder = math.huge
        for sk, info in pairs(list) do
            local o = info.order or 1
            if o < firstOrder then
                firstOrder = o
                firstKey = sk
            end
        end
        if firstKey then
            self:_setActiveSubTab(key, firstKey)
        end
    end

end

-- INTERNAL: set active sub tab + panggil builder
function MainUI:_setActiveSubTab(mainKey, subKey)
    self.activeSubKey = subKey

    ----------------------------------------------------------------
    -- STYLE D: glow neon capsule border
    ----------------------------------------------------------------
    for sKey, pack in pairs(self.subTabButtons) do
        local btn    = pack.button
        local stroke = pack.stroke

        if sKey == subKey then
            -- 🔥 AKTIF → border neon kuning, teks kuning
            tweenColor(btn, "BackgroundColor3", Color3.fromRGB(16,16,16))
            btn.BackgroundTransparency = SUBTAB_BG_ACTIVE_TRANSPARENCY
            tweenColor(btn, "TextColor3", COLOR_YELLOW)

            if stroke then
                stroke.Color        = COLOR_YELLOW
                stroke.Thickness    = 2
                stroke.Transparency = 0     -- full terlihat
            end
        else
            -- 🌑 NON-AKTIF → border abu ghost, teks abu
            tweenColor(btn, "BackgroundColor3", COLOR_PANEL)
            btn.BackgroundTransparency = SUBTAB_BG_TRANSPARENCY
            tweenColor(btn, "TextColor3", COLOR_GRAY_TEXT)

            if stroke then
                stroke.Color        = Color3.fromRGB(90,90,90)
                stroke.Thickness    = 1
                stroke.Transparency = 0.5   -- ghost
            end
        end
    end

    ----------------------------------------------------------------
    -- sisanya tetap sama
    ----------------------------------------------------------------
    self:ClearSubContent()

    local info = self.subTabs[mainKey] and self.subTabs[mainKey][subKey]
    if info and info.builder then
        local ok, err = pcall(info.builder)
        if not ok then
            -- keep F9 clean
            self:CreateRowLabel(self.content, "Tab error: " .. tostring(err))
        end
    end

end


-- ======================
-- API: CLEAR SUB CONTENT
-- ======================
function MainUI:ClearSubContent()
    local prevSuppress = self._suppressAutosave
    self._suppressAutosave = true
    if type(self._pendingInputCommits) == "table" then
        for _, fn in ipairs(self._pendingInputCommits) do
            pcall(fn)
        end
        self._pendingInputCommits = {}
    end

    for _, child in ipairs(self.content:GetChildren()) do
        if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then
            child:Destroy()
        end
    end
    self._suppressAutosave = prevSuppress
end


function MainUI:CloseDropdownOverlays()
    local root = self._sg or self.right or PlayerGui
    if not root then return end
    for _, desc in ipairs(root:GetDescendants()) do
        if desc.Name == "NodeHubDropdownOverlay" or desc.Name == "NodeHubModeOverlay" then
            pcall(function() desc:Destroy() end)
        end
    end
end


function MainUI:BeginContentLayoutSuspend()
    self._contentLayoutSuspend = (tonumber(self._contentLayoutSuspend) or 0) + 1
    -- Suppress deferred dropdown initial onChanged while bulk-building a heavy tab.
    self._skipDropdownInitialNotify = true
end

function MainUI:EndContentLayoutSuspend()
    local n = (tonumber(self._contentLayoutSuspend) or 1) - 1
    if n < 0 then n = 0 end
    self._contentLayoutSuspend = n
    if n > 0 then return end
    task.defer(function()
        self._skipDropdownInitialNotify = false
    end)
end

function MainUI:RefreshContentLayout()
end


-- Status on the section header (right of title, left of arrow). One line: Value · detail
local HEADER_STATUS_W = 260
local HEADER_H = 26

local function headerStatusEmpty(s)
    s = tostring(s or "")
    return s == "" or s == "—" or s == "-"
end

local function attachHeaderStatus(ui, header, titleLabel, statusOpts)
    if type(statusOpts) ~= "table" then
        statusOpts = {}
    end
    local valueNow = tostring(statusOpts.value or statusOpts.text or "Idle")
    local detailNow = tostring(statusOpts.detail or "")
    local styleNow = statusOpts.style or "muted"

    titleLabel.Size = UDim2.new(1, -(HEADER_STATUS_W + 36), 1, 0)

    local host = Instance.new("Frame")
    host.Name = "HeaderStatus"
    host.BackgroundTransparency = 1
    host.AnchorPoint = Vector2.new(1, 0.5)
    host.Position = UDim2.new(1, -28, 0.5, 0)
    host.Size = UDim2.new(0, HEADER_STATUS_W, 1, -4)
    host.ZIndex = (header.ZIndex or 2) + 1
    host.Active = false
    host.Parent = header

    local valueLbl = Instance.new("TextLabel")
    valueLbl.Name = "Value"
    valueLbl.BackgroundTransparency = 1
    valueLbl.Size = UDim2.new(1, 0, 1, 0)
    valueLbl.Position = UDim2.new(0, 0, 0, 0)
    valueLbl.Font = Enum.Font.GothamMedium
    valueLbl.TextXAlignment = Enum.TextXAlignment.Right
    valueLbl.TextYAlignment = Enum.TextYAlignment.Center
    valueLbl.TextSize = 11
    valueLbl.TextTruncate = Enum.TextTruncate.AtEnd
    valueLbl.Active = false
    valueLbl.ZIndex = host.ZIndex
    valueLbl.Parent = host
    applyRowLabelStyle(valueLbl, styleNow)
    valueLbl.TextSize = 11

    local function composed()
        if headerStatusEmpty(detailNow) then
            return valueNow
        end
        if string.lower(detailNow) == string.lower(valueNow) then
            return valueNow
        end
        return valueNow .. " · " .. detailNow
    end

    local function layout()
        header.Size = UDim2.new(1, 0, 0, HEADER_H)
        valueLbl.Text = composed()
    end

    layout()

    local api = {}

    function api.get()
        return valueNow
    end

    function api.set(value, _silent)
        valueNow = tostring(value or "Idle")
        layout()
        return valueNow
    end

    function api.setCaption(_text)
        return ""
    end

    function api.setDetail(text)
        detailNow = tostring(text or "")
        layout()
        return detailNow
    end

    function api.setStyle(key)
        styleNow = key or "muted"
        applyRowLabelStyle(valueLbl, styleNow)
        valueLbl.TextSize = 11
        return styleNow
    end

    function api.getDetail()
        return detailNow
    end

    ui:_bindWidget(statusOpts.id, "status", api, statusOpts.persist == true, header)
    api.row = header
    return api
end

function MainUI:CreateSection(title, defaultExpanded)
    local opts = {}
    if type(title) == "table" then
        opts = title
        title = opts.title or opts.label
        if opts.expanded ~= nil then
            defaultExpanded = opts.expanded
        elseif defaultExpanded == nil then
            defaultExpanded = opts.defaultExpanded
        end
    end
    local showHeader = opts.header ~= false and title ~= false and title ~= ""
    title = (type(title) == "string" and title ~= "") and title or "Section"

    -- kalau nggak diisi, default = tutup
    if defaultExpanded == nil then
        defaultExpanded = false
    end

    -- Root section frame (auto height)
    local section = Instance.new("Frame")
    section.Name = "Section_" .. title
    section.BackgroundTransparency = 1
    section.Size = UDim2.new(1, 0, 0, 0)
    section.AutomaticSize = Enum.AutomaticSize.Y
    section.LayoutOrder = #self.content:GetChildren() + 1
    section.Parent = self.content

    local sectionLayout = Instance.new("UIListLayout")
    sectionLayout.FillDirection = Enum.FillDirection.Vertical
    sectionLayout.SortOrder = Enum.SortOrder.LayoutOrder
    sectionLayout.Padding = UDim.new(0, 2)
    sectionLayout.Parent = section

    -- Header (clickable, buat buka/tutup)
    local header, arrow, titleLabel, statusApi
    if showHeader then
        header = Instance.new("TextButton")
        header.Name = "Header"
        header.AutoButtonColor = false
        header.BackgroundColor3 = COLOR_PANEL_ALT
        header.BackgroundTransparency = tonumber(self._sectionTransparency) or DEFAULT_SECTION_BG_TRANSPARENCY
        header.Size = UDim2.new(1, 0, 0, 26)
        header.LayoutOrder = 1
        header.ZIndex = 2
        header.Text = ""
        header.BorderSizePixel = 0
        header.Parent = section
        createCorner(header, 8)
        createStroke(header, COLOR_YELLOW, 1, 0.3)

        titleLabel = Instance.new("TextLabel")
        titleLabel.Name = "Title"
        titleLabel.BackgroundTransparency = 1
        titleLabel.Size = UDim2.new(1, -40, 1, 0)
        titleLabel.Position = UDim2.new(0, 10, 0, 0)
        titleLabel.Font = Enum.Font.GothamBold
        titleLabel.TextXAlignment = Enum.TextXAlignment.Left
        titleLabel.TextYAlignment = Enum.TextYAlignment.Center
        titleLabel.TextTruncate = Enum.TextTruncate.AtEnd
        titleLabel.TextSize = 13
        titleLabel.TextColor3 = COLOR_YELLOW
        titleLabel.Text = title
        titleLabel.Active = false
        titleLabel.Parent = header

        arrow = Instance.new("TextLabel")
        arrow.Name = "Arrow"
        arrow.BackgroundTransparency = 1
        arrow.Size = UDim2.new(0, 20, 1, 0)
        arrow.Position = UDim2.new(1, -26, 0, 0)
        arrow.Font = Enum.Font.GothamBold
        arrow.TextSize = 14
        arrow.TextXAlignment = Enum.TextXAlignment.Center
        arrow.TextColor3 = COLOR_GRAY_TEXT
        arrow.Text = "▼"
        arrow.Active = false
        arrow.Parent = header

        if opts.status then
            statusApi = attachHeaderStatus(self, header, titleLabel, opts.status)
        end
    end

    -- Body tempat isi section nanti
    local body = Instance.new("Frame")
    body.Name = "Body"
    body.BackgroundTransparency = 1
    body.Size = UDim2.new(1, 0, 0, 0)
    body.LayoutOrder = 2
    body.ZIndex = 1
    body.AutomaticSize = Enum.AutomaticSize.Y
    body.ClipsDescendants = true
    body.Parent = section

    local bodyPad = Instance.new("UIPadding")
    bodyPad.PaddingTop = UDim.new(0, 8)
    bodyPad.PaddingBottom = UDim.new(0, 10)
    bodyPad.PaddingLeft = UDim.new(0, 2)
    bodyPad.PaddingRight = UDim.new(0, 2)
    bodyPad.Parent = body

    local bodyLayout = Instance.new("UIListLayout")
    bodyLayout.FillDirection = Enum.FillDirection.Vertical
    bodyLayout.SortOrder = Enum.SortOrder.LayoutOrder
    bodyLayout.Padding = UDim.new(0, 8)
    bodyLayout.Parent = body

    -- state buka/tutup
    local expanded = defaultExpanded

    local function setExpanded(on)
        expanded = on == true
        body.Visible = expanded
        if arrow then
            arrow.Text = expanded and "▼" or "▶"
        end

        if expanded then
            body.AutomaticSize = Enum.AutomaticSize.Y
            body.Size = UDim2.new(1, 0, 0, 0)
        else
            body.AutomaticSize = Enum.AutomaticSize.None
            body.Size = UDim2.new(1, 0, 0, 0)
        end
    end

    if header then
        header.MouseButton1Click:Connect(function()
            setExpanded(not expanded)
        end)
        header.MouseEnter:Connect(function()
            tweenColor(header, "BackgroundColor3", Color3.fromRGB(24, 24, 24))
        end)
        header.MouseLeave:Connect(function()
            tweenColor(header, "BackgroundColor3", COLOR_PANEL_ALT)
        end)
    end

    setExpanded(showHeader ~= true or defaultExpanded == true)

    return body, setExpanded, statusApi
end

function MainUI:CreateGroup(parent, opts)
    opts = opts or {}
    local group = Instance.new("Frame")
    group.Name = "FieldGroup"
    group.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    group.BackgroundTransparency = 0.93
    group.BorderSizePixel = 0
    group.Size = UDim2.new(1, 0, 0, 0)
    group.AutomaticSize = Enum.AutomaticSize.Y
    group.LayoutOrder = tonumber(opts.order) or (#parent:GetChildren() + 1)
    group.Parent = parent
    group:SetAttribute("FieldGroup", true)
    createCorner(group, 10)

    local pad = Instance.new("UIPadding")
    pad.PaddingTop = UDim.new(0, 2)
    pad.PaddingBottom = UDim.new(0, 2)
    pad.PaddingLeft = UDim.new(0, 10)
    pad.PaddingRight = UDim.new(0, 10)
    pad.Parent = group

    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 0)
    list.Parent = group

    return group
end



function MainUI:ApplyRowLabelStyle(label, styleKeyOrOpts)
    return applyRowLabelStyle(label, styleKeyOrOpts)
end

function MainUI:GetRowLabelThemes()
    return ROW_LABEL_THEMES
end

----------------------------------------------------------
-- ROW: LABEL / STATUS / DETAILS
-- CreateRowLabel(parent, text, desc, order, styleKey)
-- CreateRowLabel(parent, { text=, detail=, style=, wrap=, id=, persist=false, order= })
-- Return: row, title, api
----------------------------------------------------------
function MainUI:CreateRowLabel(parent, text, desc, order, styleKey)
    local opts = {}
    if _isOpts(text) then
        opts = text
        text = opts.text or opts.label or ""
        desc = opts.detail or opts.desc
        order = opts.order or order
        styleKey = opts.style or opts.styleKey or styleKey
    end

    local wrap = opts.wrap == true
    local styleNow = styleKey or "default"
    local textNow = tostring(text or "")
    local detailNow = (desc and tostring(desc)) or ""

    local row = Instance.new("Frame")
    row.Name = "RowLabel"
    row.BackgroundTransparency = 1
    row.Size = UDim2.new(1, 0, 0, (detailNow ~= "" and 36) or 22)
    row.AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None
    row.LayoutOrder = order or (#parent:GetChildren() + 1)
    row.Parent = parent

    local title = Instance.new("TextLabel")
    title.Name = "Title"
    title.BackgroundTransparency = 1
    title.Position = UDim2.new(0, 0, 0, 0)
    title.Size = UDim2.new(1, 0, 0, wrap and 0 or 18)
    title.AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None
    title.Font = Enum.Font.Gotham
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextYAlignment = Enum.TextYAlignment.Center
    title.TextSize = 12
    title.Text = textNow
    title.TextWrapped = wrap
    title.TextTruncate = wrap and Enum.TextTruncate.None or Enum.TextTruncate.AtEnd
    title.Parent = row
    applyRowLabelStyle(title, styleNow)

    local sub
    if detailNow ~= "" then
        sub = Instance.new("TextLabel")
        sub.Name = "Detail"
        sub.BackgroundTransparency = 1
        sub.Position = UDim2.new(0, 0, 0, 18)
        sub.Size = UDim2.new(1, 0, 0, wrap and 0 or 14)
        sub.AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None
        sub.Font = Enum.Font.Gotham
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.TextSize = 11
        sub.Text = detailNow
        sub.TextWrapped = wrap
        sub.TextTruncate = wrap and Enum.TextTruncate.None or Enum.TextTruncate.AtEnd
        sub.Parent = row
        applyRowLabelStyle(sub, opts.detailStyle or "detail")
    end

    local function layout()
        local hasDetail = sub and sub.Text ~= ""
        if wrap then
            row.AutomaticSize = Enum.AutomaticSize.Y
            return
        end
        row.Size = UDim2.new(1, 0, 0, hasDetail and 36 or 22)
    end

    local api = {}

    function api.get()
        return textNow
    end

    function api.set(value, _silent)
        textNow = tostring(value or "")
        title.Text = textNow
        return textNow
    end

    function api.getDetail()
        return detailNow
    end

    function api.setDetail(value)
        detailNow = tostring(value or "")
        if detailNow == "" then
            if sub then
                sub.Text = ""
                sub.Visible = false
            end
        else
            if not sub then
                sub = Instance.new("TextLabel")
                sub.Name = "Detail"
                sub.BackgroundTransparency = 1
                sub.Position = UDim2.new(0, 0, 0, 18)
                sub.Size = UDim2.new(1, 0, 0, 14)
                sub.Font = Enum.Font.Gotham
                sub.TextXAlignment = Enum.TextXAlignment.Left
                sub.TextSize = 11
                sub.TextWrapped = wrap
                sub.Parent = row
                applyRowLabelStyle(sub, opts.detailStyle or "detail")
            end
            sub.Visible = true
            sub.Text = detailNow
        end
        layout()
        return detailNow
    end

    function api.setStyle(key)
        styleNow = key or "default"
        applyRowLabelStyle(title, styleNow)
        return styleNow
    end

    self:_bindWidget(opts.id, "label", api, opts.persist == true, row)
    api.row = row
    attachVisibility(api, row)
    return row, title, api
end

----------------------------------------------------------
-- ROW: STATUS  caption kiri + value kanan + detail opsional
-- CreateRowStatus(parent, { caption="Status", value="Idle", style="live", detail="", id= })
----------------------------------------------------------
function MainUI:CreateRowStatus(parent, opts)
    opts = _isOpts(opts) and opts or {}
    local captionNow = tostring(opts.caption or opts.label or "Status")
    local valueNow = tostring(opts.value or opts.text or "-")
    local detailNow = tostring(opts.detail or "")
    local styleNow = opts.style or "live"

    local grouped = isFieldGroup(parent)
    local row = Instance.new("Frame")
    row.Name = "RowStatus"
    row.BorderSizePixel = 0
    row.Size = UDim2.new(1, 0, 0, detailNow ~= "" and 44 or 36)
    row.LayoutOrder = opts.order or (#parent:GetChildren() + 1)
    row.Parent = parent
    attachGroupDivider(row, parent)
    if grouped then
        row.BackgroundTransparency = 1
    else
        row.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        row.BackgroundTransparency = 0.93
        createCorner(row, 10)
        local statusPad = Instance.new("UIPadding")
        statusPad.PaddingLeft = UDim.new(0, 12)
        statusPad.PaddingRight = UDim.new(0, 12)
        statusPad.Parent = row
    end

    local caption = Instance.new("TextLabel")
    caption.Name = "Caption"
    caption.BackgroundTransparency = 1
    caption.Position = UDim2.new(0, 0, 0, 0)
    caption.Size = UDim2.new(0.38, 0, 0, 18)
    caption.Font = Enum.Font.Gotham
    caption.TextXAlignment = Enum.TextXAlignment.Left
    caption.TextSize = 11
    caption.Text = captionNow
    caption.TextTruncate = Enum.TextTruncate.AtEnd
    caption.Parent = row
    applyRowLabelStyle(caption, "muted")

    local valueLbl = Instance.new("TextLabel")
    valueLbl.Name = "Value"
    valueLbl.BackgroundTransparency = 1
    valueLbl.Position = UDim2.new(0.38, 0, 0, 0)
    valueLbl.Size = UDim2.new(0.62, 0, 0, 18)
    valueLbl.Font = Enum.Font.GothamMedium
    valueLbl.TextXAlignment = Enum.TextXAlignment.Right
    valueLbl.TextSize = 12
    valueLbl.Text = valueNow
    valueLbl.TextTruncate = Enum.TextTruncate.AtEnd
    valueLbl.Parent = row
    applyRowLabelStyle(valueLbl, styleNow)

    local detailLbl
    local function ensureDetail()
        if detailLbl then return detailLbl end
        detailLbl = Instance.new("TextLabel")
        detailLbl.Name = "Detail"
        detailLbl.BackgroundTransparency = 1
        detailLbl.Position = UDim2.new(0, 0, 0, 18)
        detailLbl.Size = UDim2.new(1, 0, 0, 14)
        detailLbl.Font = Enum.Font.Gotham
        detailLbl.TextXAlignment = Enum.TextXAlignment.Left
        detailLbl.TextSize = 11
        detailLbl.TextTruncate = Enum.TextTruncate.AtEnd
        detailLbl.Parent = row
        applyRowLabelStyle(detailLbl, "detail")
        return detailLbl
    end

    if detailNow ~= "" then
        ensureDetail().Text = detailNow
    end

    local function layout()
        row.Size = UDim2.new(1, 0, 0, (detailNow ~= "" and 44) or 40)
        if detailLbl then
            detailLbl.Visible = detailNow ~= ""
        end
    end

    local api = {}

    function api.get()
        return valueNow
    end

    function api.set(value, _silent)
        valueNow = tostring(value or "-")
        valueLbl.Text = valueNow
        return valueNow
    end

    function api.setCaption(text)
        captionNow = tostring(text or "")
        caption.Text = captionNow
        return captionNow
    end

    function api.setDetail(text)
        detailNow = tostring(text or "")
        if detailNow ~= "" then
            ensureDetail().Text = detailNow
        elseif detailLbl then
            detailLbl.Text = ""
        end
        layout()
        return detailNow
    end

    function api.setStyle(key)
        styleNow = key or "live"
        applyRowLabelStyle(valueLbl, styleNow)
        return styleNow
    end

    function api.getDetail()
        return detailNow
    end

    self:_bindWidget(opts.id, "status", api, opts.persist == true, row)
    api.row = row
    attachVisibility(api, row)
    return row, api
end

----------------------------------------------------------
-- ROW: BUTTON
-- CreateRowButton(parent, text, onClick, order, kind)
-- CreateRowButton(parent, { text=, onClick=, kind=, id=, order= })
----------------------------------------------------------
function MainUI:CreateRowButton(parent, text, onClick, order, kind)
    local opts = {}
    if _isOpts(text) then
        opts = text
        text = opts.text or opts.label or "Button"
        onClick = opts.onClick or onClick
        order = opts.order or order
        kind = opts.kind or kind
    end
    kind = kind or "normal"

    local row = Instance.new("Frame")
    row.Name = "RowButton"
    row.BackgroundTransparency = 1
    row.Size = UDim2.new(1, 0, 0, 28)
    row.LayoutOrder = order or (#parent:GetChildren() + 1)
    row.Parent = parent

    local bg = COLOR_PANEL_ALT
    local fg = COLOR_WHITE
    local strokeT, strokeTr = 1, 0.45
    if kind == "primary" then
        bg = COLOR_YELLOW
        fg = COLOR_PANEL
        strokeT, strokeTr = 1, 0.2
    elseif kind == "danger" then
        bg = Color3.fromRGB(72, 18, 18)
        fg = Color3.fromRGB(255, 170, 170)
        strokeT, strokeTr = 1, 0.35
    end

    local btn = Instance.new("TextButton")
    btn.Name = "Button"
    btn.AutoButtonColor = false
    btn.BackgroundColor3 = bg
    btn.Size = UDim2.new(1, 0, 0, 24)
    btn.Position = UDim2.new(0, 0, 0.5, -12)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 12
    btn.TextColor3 = fg
    btn.Text = tostring(text or "Button")
    btn.Parent = row
    createCorner(btn, 7)
    createStroke(btn, COLOR_YELLOW, strokeT, strokeTr)

    btn.MouseButton1Click:Connect(function()
        if type(onClick) == "function" then
            pcall(onClick)
        end
    end)

    local api = {}
    function api.get()
        return btn.Text
    end
    function api.set(value)
        btn.Text = tostring(value or "")
        return btn.Text
    end
    function api.fire()
        if type(onClick) == "function" then
            pcall(onClick)
        end
    end

    self:_bindWidget(opts.id, "button", api, false, row)
    api.row = row
    attachVisibility(api, row)
    return row, api
end

----------------------------------------------------------
-- ROW: TOGGLE (pill kanan)
--
-- Return: row, setGet, api
--   setGet(value, silent)  — set state; silent=true tidak panggil onChanged
--   api.set / api.setOn / api.setOff / api.get — sama, untuk dipakai di modul lain
--
-- momentary (arg7):
--   true  = ON lalu auto OFF setelah 1 detik (mode pulse)
--   number = ON lalu auto OFF setelah N detik
-- Untuk auto OFF setelah event eksternal (mis. save selesai), pakai api.setOff(true)
----------------------------------------------------------
function MainUI:CreateRowToggle(parent, labelText, initial, onChanged, order, labelStyle, momentary)
    local opts = {}
    if _isOpts(labelText) then
        opts = labelText
        labelText = opts.label or opts.text or "Toggle"
        initial = opts.initial
        onChanged = opts.onChanged or onChanged
        order = opts.order or order
        labelStyle = opts.style or opts.labelStyle or labelStyle
        momentary = opts.momentary
    elseif _isOpts(momentary) then
        opts = momentary
        momentary = opts.momentary
    end
    local grouped = isFieldGroup(parent)
    local row = Instance.new("Frame")
    row.Name = "RowToggle"
    row.BorderSizePixel = 0
    row.Size = UDim2.new(1, 0, 0, grouped and ROW_H_GROUP or ROW_H)
    row.LayoutOrder = order or (#parent:GetChildren() + 1)
    row.Parent = parent
    attachGroupDivider(row, parent)
    if grouped then
        row.BackgroundTransparency = 1
    else
        row.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        row.BackgroundTransparency = 0.93
        createCorner(row, 10)
        local pad = Instance.new("UIPadding")
        pad.PaddingLeft = UDim.new(0, 12)
        pad.PaddingRight = UDim.new(0, 12)
        pad.Parent = row
    end

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.BackgroundTransparency = 1
    label.Position = UDim2.new(0, 0, 0, 0)
    label.Size = UDim2.new(1, -58, 1, 0)
    label.Font = Enum.Font.GothamMedium
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextSize = 12
    label.TextColor3 = COLOR_TITLE
    label.Text = labelText or "Toggle"
    label.Parent = row
    applyRowLabelStyle(label, labelStyle or "toggle")
    if not labelStyle then
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 12
        label.TextColor3 = COLOR_TITLE
    end

    local toggleBtn = Instance.new("TextButton")
    toggleBtn.Name = "Toggle"
    toggleBtn.AutoButtonColor = false
    toggleBtn.BackgroundColor3 = Color3.fromRGB(30,30,30)
    toggleBtn.Size = UDim2.new(0, 48, 0, 20)
    toggleBtn.Position = UDim2.new(1, -48, 0.5, -10)
    toggleBtn.Text = ""
    toggleBtn.BorderSizePixel = 0
    toggleBtn.Parent = row
    createCorner(toggleBtn, 10)
    createStroke(toggleBtn, Color3.fromRGB(60,60,60), 1, 0.6)

    local knob = Instance.new("Frame")
    knob.Name = "Knob"
    knob.Size = UDim2.new(0, 18, 0, 18)
    knob.Position = UDim2.new(0, 1, 0, 1)
    knob.BackgroundColor3 = Color3.fromRGB(220,220,220)
    knob.BorderSizePixel = 0
    knob.Parent = toggleBtn
    createCorner(knob, 9)

    local state = initial and true or false
    local bgTween = nil

    local function stopBgTween()
        if bgTween then
            pcall(function() bgTween:Cancel() end)
            bgTween = nil
        end
    end

    local function applyState(animate)
        stopBgTween()
        if state then
            knob.Position = UDim2.new(1, -19, 0, 1)
            if animate then
                bgTween = TweenService:Create(
                    toggleBtn,
                    TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundColor3 = COLOR_YELLOW }
                )
                bgTween:Play()
            else
                toggleBtn.BackgroundColor3 = COLOR_YELLOW
            end
        else
            knob.Position = UDim2.new(0, 1, 0, 1)
            if animate then
                bgTween = TweenService:Create(
                    toggleBtn,
                    TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundColor3 = Color3.fromRGB(30, 30, 30) }
                )
                bgTween:Play()
            else
                toggleBtn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
            end
        end
    end

    applyState(false)

    toggleBtn.MouseButton1Click:Connect(function()
        local pulseSec = nil
        if momentary == true then
            pulseSec = 1
        elseif type(momentary) == "number" and momentary > 0 then
            pulseSec = momentary
        end

        if pulseSec then
            if state then
                return
            end
            state = true
            applyState(true)
            if onChanged then
                pcall(onChanged, true)
            end
            task.delay(pulseSec, function()
                state = false
                applyState(false)
            end)
            return
        end

        state = not state
        applyState(true)
        if onChanged then
            onChanged(state)
        end
        if opts.id then
            self:_touchConfig(opts.id, state)
        end
    end)

    -- getter/setter
    local function setGet(value, silent)
        if value ~= nil then
            state = value and true or false
            applyState(false)

            if (not silent) and onChanged then
                onChanged(state)
            end
        end

        return state
    end

    local api = {}

    function api.get()
        return state
    end

    function api.set(value, silent)
        return setGet(value, silent)
    end

    function api.setOn(silent)
        return setGet(true, silent)
    end

    function api.setOff(silent)
        return setGet(false, silent)
    end

    self:_bindWidget(opts.id, "toggle", api, opts.persist, row)
    api.row = row
    attachVisibility(api, row)
    return row, setGet, api
end

----------------------------------------------------------
-- ROW: INPUT (text box dengan label kiri)
-- FIX:
--  ✅ text tidak keluar box (clip + padding)
--  ✅ bisa truncate "..." kalau kepanjangan
--  ✅ clearOnFocus opsional (arg5 boolean)
--  ✅ clearOnFocus=true: klik → kosong; klik pergi tanpa ngetik → restore (tidak commit "")
--  ✅ allow empty kalau user memang sengaja mengosongkan (touched=true)
--
-- Signature:
--   CreateRowInput(parent, label, defaultText, onChanged, [clearOnFocusOrOrder], [maybeOrder])
--   arg5 number  => order
--   arg5 boolean => clearOnFocus (true=clear seperti lama, false=tidak clear)
----------------------------------------------------------
function MainUI:CreateRowInput(parent, labelText, defaultText, onChanged, noClearOrOrder, maybeOrder)
    local opts = {}
    if _isOpts(labelText) then
        opts = labelText
        labelText = opts.label or opts.text or "Input"
        defaultText = opts.initial or opts.value or opts.defaultText
        onChanged = opts.onChanged or onChanged
        noClearOrOrder = opts.clearOnFocus
        if noClearOrOrder == nil and type(opts.noClear) == "boolean" then
            noClearOrOrder = not opts.noClear
        end
        maybeOrder = opts.order
    elseif _isOpts(maybeOrder) then
        opts = maybeOrder
        maybeOrder = opts.order
    elseif _isOpts(noClearOrOrder) and noClearOrOrder.id then
        opts = noClearOrOrder
        noClearOrOrder = opts.clearOnFocus
        maybeOrder = opts.order
    end
    local order = nil
    local clearOnFocus = true

    if type(noClearOrOrder) == "number" then
        order = noClearOrOrder
    elseif type(noClearOrOrder) == "boolean" then
        clearOnFocus = (noClearOrOrder == true)
        order = maybeOrder
    else
        clearOnFocus = true
        order = maybeOrder
    end

    local hintText = type(opts.hintText) == "string" and opts.hintText or ""
    local hasHint = hintText ~= ""
    local ctrlW = math.max(72, math.floor(tonumber(opts.controlWidth) or ROW_CTRL_W))

    local grouped = isFieldGroup(parent)
    local row = Instance.new("Frame")
    row.Name = "RowInput"
    row.BorderSizePixel = 0
    row.Size = UDim2.new(1, 0, 0, grouped and ROW_H_GROUP or (hasHint and ROW_H_HINT or ROW_H))
    row.LayoutOrder = order or (#parent:GetChildren() + 1)
    row.Parent = parent
    attachGroupDivider(row, parent)
    if grouped then
        row.BackgroundTransparency = 1
    else
        row.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        row.BackgroundTransparency = 0.93
        createCorner(row, 10)
        local pad = Instance.new("UIPadding")
        pad.PaddingLeft = UDim.new(0, 12)
        pad.PaddingRight = UDim.new(0, 12)
        pad.Parent = row
    end

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.BackgroundTransparency = 1
    label.Font = Enum.Font.GothamMedium
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextSize = 12
    label.TextColor3 = COLOR_TITLE
    label.Text = labelText or "Input"
    label.Parent = row
    if hasHint and not grouped then
        label.Position = UDim2.new(0, 0, 0, 0)
        label.Size = UDim2.new(1, -(ctrlW + 10), 0, 22)
        label.TextYAlignment = Enum.TextYAlignment.Bottom
    else
        label.Position = UDim2.new(0, 0, 0, 0)
        label.Size = UDim2.new(1, -(ctrlW + 10), 1, 0)
        label.TextYAlignment = Enum.TextYAlignment.Center
    end

    local currentValue = (defaultText ~= nil) and tostring(defaultText) or ""
    local beforeFocusValue = currentValue
    local liveText = currentValue
    local committed = false

    local box = Instance.new("TextBox")
    box.Name = "Input"
    box.BackgroundColor3 = COLOR_CTRL_BG
    box.Size = UDim2.new(0, ctrlW, 0, ROW_CTRL_H)
    box.Position = UDim2.new(1, -ctrlW, 0.5, -math.floor(ROW_CTRL_H * 0.5))
    box.Font = Enum.Font.Gotham
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.ClearTextOnFocus = false -- biar kita kontrol sendiri
    box.TextSize = 12
    box.TextColor3 = COLOR_TITLE
    box.PlaceholderText = ""
    box.ClipsDescendants = true
    box.Parent = row

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft  = UDim.new(0, 6)
    pad.PaddingRight = UDim.new(0, 6)
    pad.Parent = box

    pcall(function()
        box.TextTruncate = Enum.TextTruncate.AtEnd
    end)

    createCorner(box, 8)
    createStroke(box, COLOR_CTRL_STROKE, 1, 0.42)

    if hasHint and not grouped then
        local hint = Instance.new("TextLabel")
        hint.Name = "Hint"
        hint.BackgroundTransparency = 1
        hint.Position = UDim2.new(0, 0, 0, 26)
        hint.Size = UDim2.new(1, -(ctrlW + 10), 0, 16)
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 10
        hint.TextColor3 = COLOR_HINT
        hint.TextWrapped = false
        hint.TextTruncate = Enum.TextTruncate.AtEnd
        hint.TextXAlignment = Enum.TextXAlignment.Left
        hint.TextYAlignment = Enum.TextYAlignment.Top
        hint.Text = hintText
        hint.Parent = row
    end

    local function trim(s)
        s = tostring(s or "")
        return (s:gsub("^%s+", ""):gsub("%s+$", ""))
    end

    -- touched detection (lebih aman)
    local touched = false
    local internalSet = false

    local function setBoxText(v)
        internalSet = true
        box.Text = v
        internalSet = false
    end

    setBoxText(currentValue)

    local function restoreBeforeFocus()
        local restore = beforeFocusValue
        if restore == nil or restore == "" then
            restore = currentValue
        end
        setBoxText(restore)
        liveText = restore
    end

    local function commitPending()
        if committed then return end

        -- Masih fokus + clearOnFocus kosong tanpa ketik → jangan commit "" (pindah tab / flush)
        if box and box.Parent and box:IsFocused() and not touched then
            return
        end

        local newText = liveText
        if box and box.Parent then
            newText = trim(box.Text)
        end
        newText = trim(newText)

        -- clearOnFocus saja, user tidak ngetik → anggap batal, restore nilai lama
        if not touched then
            restoreBeforeFocus()
            return
        end

        if newText == trim(currentValue) then return end

        committed = true
        currentValue = newText
        liveText = newText
        if box and box.Parent then
            setBoxText(currentValue)
        end
        if onChanged then
            onChanged(currentValue)
        end
        if opts.id then
            self:_touchConfig(opts.id, currentValue)
        end
    end

    box:GetPropertyChangedSignal("Text"):Connect(function()
        if internalSet then return end
        liveText = trim(box.Text)
        if box:IsFocused() then
            touched = true
        end
    end)

    box.Focused:Connect(function()
        tweenColor(box, "BackgroundColor3", Color3.fromRGB(24,24,24))
        beforeFocusValue = currentValue
        touched = false
        committed = false

        if clearOnFocus and trim(box.Text) == trim(currentValue) then
            setBoxText("")
            liveText = ""
        end
    end)

    box.FocusLost:Connect(function(enterPressed)
        tweenColor(box, "BackgroundColor3", Color3.fromRGB(18,18,18))

        -- Klik saja tanpa ngetik (termasuk setelah clearOnFocus) → kembalikan nilai lama
        if not touched then
            restoreBeforeFocus()
            return
        end

        commitPending()
    end)

    box.Destroying:Connect(commitPending)

    self._pendingInputCommits = self._pendingInputCommits or {}
    table.insert(self._pendingInputCommits, commitPending)

    row.Destroying:Connect(function()
        for i = #self._pendingInputCommits, 1, -1 do
            if self._pendingInputCommits[i] == commitPending then
                table.remove(self._pendingInputCommits, i)
                break
            end
        end
    end)

    local function setGet(value)
        if value ~= nil then
            currentValue = tostring(value)
            liveText = currentValue
            committed = false
            setBoxText(currentValue)
        end
        return currentValue
    end

    local api = {}
    function api.get()
        if box and box.Parent then
            local t = trim(box.Text)
            if t ~= "" then
                return t
            end
        end
        return currentValue
    end
    function api.set(value, silent)
        local nextValue = tostring(value or "")
        currentValue = nextValue
        liveText = nextValue
        committed = false
        setBoxText(nextValue)
        if (not silent) and onChanged then
            pcall(onChanged, nextValue)
        end
        return currentValue
    end

    self:_bindWidget(opts.id, "input", api, opts.persist, row)
    api.row = row
    attachVisibility(api, row)
    return row, setGet, commitPending, api
end


----------------------------------------------------------
-- ROW: DROPDOWN (single / multi) dgn overlay + search
----------------------------------------------------------
-- ROW: DROPDOWN (single / multi) dgn overlay + search
----------------------------------------------------------
-- opts:
-- {
--   label       = "Target Player",
--   placeholder = "Select...",
--   mode        = "single" / "multi"  (default: "single")
--   getItems    = function() return { "A", "B" } end
--                -- ATAU langsung table: { "A","B" } / { {key="a",name="A"}, ... }
--   initial     =   -- SINGLE: "key" / "name"
--                 -- MULTI : { [key]=true, [key2]=true }
--   onChanged   = function(mode, selected) end
--   emptyUntilSearch = false  -- true: list kosong sampai user ketik search
--   deferItemLoad = false     -- true: skip scan getItems saat create; load saat dropdown dibuka
--   preserveItemOrder = false -- true: urutan dari getItems (pakai index / item.sort / item.order)
--   maxResults  = nil         -- number: batas item (mis. 10)
--   searchGetItems = function(query) return {} end  -- override sumber item saat search
--   searchPlaceholder = "Search..."
--   hintText    = "..."       -- muted caption under the title (left); ignored inside FieldGroup
--   controlWidth = 176        -- right-column width (shared with CreateRowInput)
--   layout      = "split" / "card" / "stack" / "inline"  (default: split)
-- }
function MainUI:CreateRowDropdown(parent, opts)
    opts = opts or {}
    local mode        = (opts.mode == "multi") and "multi" or "single"
    local labelText   = opts.label or "Dropdown"
    local panelTitle  = opts.panelTitle or opts.dropdownTitle or labelText
    local placeholder = opts.placeholder or "Select..."
    local emptyUntilSearch = opts.emptyUntilSearch == true
    local deferItemLoad = opts.deferItemLoad == true
    local preserveItemOrder = opts.preserveItemOrder == true
    local maxResults = tonumber(opts.maxResults)
    local searchGetItems = opts.searchGetItems

    local api = {}
    local itemsLoaded = false

    -- Sumber item bisa function atau table
    local itemsSource = opts.getItems or {}

    local function getItemsList()
        if type(itemsSource) == "function" then
            local ok, res = pcall(itemsSource)
            if ok and type(res) == "table" then
                return res
            else
                -- keep F9 clean
                return {}
            end
        elseif type(itemsSource) == "table" then
            return itemsSource
        else
            -- keep F9 clean
            return {}
        end
    end

    local function coerceSingleKey(value)
        if value == nil then return nil end
        if type(value) == "table" then
            for k, v in pairs(value) do
                if v == true or v == 1 or v == "true" then
                    return tostring(k)
                end
            end
            return nil
        end
        local key = tostring(value)
        if key:match("^table:%s*0x") then
            return nil
        end
        return key ~= "" and key or nil
    end

    local onChanged   = opts.onChanged
    local onClose     = opts.onClose

    -- state
    local currentItems = {}
    local keyToLabel   = {}

    local selectedKey  = nil
    local selectedMap  = {}

    if mode == "single" then
        selectedKey = coerceSingleKey(opts.initial)
    else
        if type(opts.initial) == "table" then
            for k, v in pairs(opts.initial) do
                if v == true or v == 1 or v == "true" then
                    selectedMap[tostring(k)] = true
                end
            end
        end
    end

    local function persistSelection()
        local id = opts.id
        if type(id) ~= "string" or id == "" then
            return
        end
        if mode == "single" then
            self:_touchConfig(id, selectedKey)
            return
        end
        local copy = {}
        for k, v in pairs(selectedMap) do
            if v then
                copy[k] = true
            end
        end
        self:_touchConfig(id, copy)
    end

    ------------------------------------------------------
    -- ROW + LABEL + BUTTON
    -- split (default): title + hint left, dropdown pill right, inside a card
    -- card: title / control / hint stacked
    -- stack / inline: legacy
    ------------------------------------------------------
    local layoutMode = opts.layout
    if layoutMode ~= "inline" and layoutMode ~= "stack" and layoutMode ~= "card" then
        layoutMode = "split"
    end
    local isCard = layoutMode == "card"
    local isSplit = layoutMode == "split"
    local isStack = layoutMode == "stack"
    local grouped = isFieldGroup(parent)
    local hintText = opts.hintText
    if type(hintText) ~= "string" then
        hintText = ""
    end
    -- Compact group: one height, no caption under title (keeps dropdown/input/toggle aligned).
    if grouped then
        hintText = ""
    end
    local hasHint = hintText ~= ""
    local hintPlaced = false
    local CTRL_W = math.max(72, math.floor(tonumber(opts.controlWidth) or ROW_CTRL_W))

    local row = Instance.new("Frame")
    row.Name = "RowDropdown"
    row.BorderSizePixel = 0
    row.LayoutOrder = tonumber(opts.order) or (#parent:GetChildren() + 1)
    row.Parent = parent
    attachGroupDivider(row, parent)
    if isCard then
        row.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        row.BackgroundTransparency = 0.93
        row.Size = UDim2.new(1, 0, 0, 0)
        row.AutomaticSize = Enum.AutomaticSize.Y
        createCorner(row, 10)
        local col = Instance.new("UIListLayout")
        col.FillDirection = Enum.FillDirection.Vertical
        col.HorizontalAlignment = Enum.HorizontalAlignment.Left
        col.SortOrder = Enum.SortOrder.LayoutOrder
        col.Padding = UDim.new(0, 6)
        col.Parent = row
        local cardPad = Instance.new("UIPadding")
        cardPad.PaddingTop = UDim.new(0, 10)
        cardPad.PaddingBottom = UDim.new(0, 10)
        cardPad.PaddingLeft = UDim.new(0, 12)
        cardPad.PaddingRight = UDim.new(0, 12)
        cardPad.Parent = row
    elseif isSplit then
        row.AutomaticSize = Enum.AutomaticSize.None
        if grouped then
            row.BackgroundTransparency = 1
            row.Size = UDim2.new(1, 0, 0, ROW_H_GROUP)
        else
            row.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            row.BackgroundTransparency = 0.93
            row.Size = UDim2.new(1, 0, 0, hasHint and ROW_H_HINT or ROW_H)
            createCorner(row, 10)
            local splitPad = Instance.new("UIPadding")
            splitPad.PaddingLeft = UDim.new(0, 12)
            splitPad.PaddingRight = UDim.new(0, 12)
            splitPad.Parent = row
        end
    elseif isStack then
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1, 0, 0, 0)
        row.AutomaticSize = Enum.AutomaticSize.Y
    else
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1, 0, 0, 34)
        row.AutomaticSize = Enum.AutomaticSize.None
    end

    local rowPad
    if isStack then
        local col = Instance.new("UIListLayout")
        col.FillDirection = Enum.FillDirection.Vertical
        col.HorizontalAlignment = Enum.HorizontalAlignment.Left
        col.SortOrder = Enum.SortOrder.LayoutOrder
        col.Padding = UDim.new(0, 4)
        col.Parent = row

        rowPad = Instance.new("UIPadding")
        rowPad.PaddingTop = UDim.new(0, 4)
        rowPad.PaddingBottom = UDim.new(0, 10)
        rowPad.Parent = row
    end

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.BackgroundTransparency = 1
    label.Text = labelText
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextTruncate = Enum.TextTruncate.AtEnd
    label.LayoutOrder = 1
    label.Parent = row
    applyRowLabelStyle(label, opts.labelStyle or "default")
    if isCard then
        label.Size = UDim2.new(1, 0, 0, 14)
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 12
        label.TextColor3 = COLOR_TITLE
        label.TextYAlignment = Enum.TextYAlignment.Center
    elseif isSplit then
        label.Position = UDim2.new(0, 0, 0, hasHint and 8 or 0)
        label.Size = UDim2.new(1, -(CTRL_W + 10), hasHint and 0 or 1, hasHint and 16 or 0)
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 12
        label.TextColor3 = COLOR_TITLE
        label.TextYAlignment = hasHint and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
    elseif isStack then
        label.Position = UDim2.new(0, 0, 0, 0)
        label.Size = UDim2.new(1, 0, 0, 14)
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 11
        label.TextColor3 = COLOR_TITLE
        label.TextYAlignment = Enum.TextYAlignment.Bottom
    else
        label.Position = UDim2.new(0, 0, 0, 0)
        label.Size = UDim2.new(0.6, 0, 1, 0)
        label.Font = Enum.Font.Gotham
        label.TextSize = 12
        label.TextYAlignment = Enum.TextYAlignment.Center
    end

    local button = Instance.new("TextButton")
    button.Name = "DropdownButton"
    button.AutoButtonColor = false
    button.BackgroundColor3 = (isCard or isSplit) and Color3.fromRGB(10, 10, 12) or COLOR_CTRL_BG
    button.Font = Enum.Font.Gotham
    button.TextSize = 11
    button.TextColor3 = COLOR_PLACEHOLDER
    button.TextTruncate = Enum.TextTruncate.AtEnd
    button.LayoutOrder = 2
    button.Parent = row
    if isCard then
        button.Size = UDim2.new(1, 0, 0, 30)
        button.Position = UDim2.new(0, 0, 0, 0)
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Text = placeholder
    elseif isSplit then
        button.Size = UDim2.new(0, CTRL_W, 0, 28)
        button.Position = UDim2.new(1, -CTRL_W, 0.5, -14)
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Text = placeholder
    elseif isStack then
        button.Size = UDim2.new(1, 0, 0, 28)
        button.Position = UDim2.new(0, 0, 0, 0)
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Text = placeholder
    else
        button.Size = UDim2.new(0.4, 0, 1, -8)
        button.Position = UDim2.new(0.60, 0, 0, 3)
        button.TextXAlignment = Enum.TextXAlignment.Center
        button.Text = "  " .. placeholder
    end
    createCorner(button, isCard and 8 or 8)
    local btnStroke = createStroke(
        button,
        (isCard or isSplit) and Color3.fromRGB(255, 255, 255) or COLOR_CTRL_STROKE,
        1,
        (isCard or isSplit) and 0.88 or 0.42
    )
    if isCard or isSplit then
        local restColor = Color3.fromRGB(10, 10, 12)
        local hoverColor = Color3.fromRGB(22, 22, 26)
        button.MouseEnter:Connect(function()
            button.BackgroundColor3 = hoverColor
        end)
        button.MouseLeave:Connect(function()
            button.BackgroundColor3 = restColor
        end)
    else
        wireCtrlHover(button, btnStroke)
    end
    if isCard or isSplit or isStack then
        local btnPad = Instance.new("UIPadding")
        btnPad.PaddingLeft = UDim.new(0, 10)
        btnPad.PaddingRight = UDim.new(0, 34)
        btnPad.Parent = button
    end

    if (isCard or isSplit) and hasHint then
        local hint = Instance.new("TextLabel")
        hint.Name = "Hint"
        hint.BackgroundTransparency = 1
        hint.Size = UDim2.new(1, (isSplit or isCard) and -(isSplit and (CTRL_W + 10) or 0) or 0, 0, isCard and 14 or 16)
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 10
        hint.TextColor3 = COLOR_HINT
        hint.TextWrapped = false
        hint.TextTruncate = Enum.TextTruncate.AtEnd
        hint.TextXAlignment = Enum.TextXAlignment.Left
        hint.TextYAlignment = Enum.TextYAlignment.Top
        hint.Text = hintText
        if isCard then
            hint.LayoutOrder = 3
        else
            hint.Position = UDim2.new(0, 0, 0, 26)
        end
        hint.Parent = row
        hintPlaced = true
    end

    local arrow = Instance.new("TextLabel")
    arrow.Name = "Arrow"
    arrow.BackgroundTransparency = 1
    arrow.Size = UDim2.new(0, 16, 1, 0)
    arrow.Position = UDim2.new(1, -18, 0, 0)
    arrow.Font = Enum.Font.GothamBold
    arrow.TextSize = 10
    arrow.TextXAlignment = Enum.TextXAlignment.Center
    arrow.TextColor3 = Color3.fromRGB(150, 150, 156)
    arrow.Text = "▼"
    arrow.Parent = button

    local ignoreOpen = false
    local allowClear = opts.clearable ~= false
    local clearBtn = Instance.new("TextButton")
    clearBtn.Name = "Clear"
    clearBtn.AutoButtonColor = false
    clearBtn.BackgroundTransparency = 1
    clearBtn.Size = UDim2.new(0, 16, 0, 16)
    clearBtn.Position = UDim2.new(1, -34, 0.5, -8)
    clearBtn.Font = Enum.Font.GothamBold
    clearBtn.TextSize = 12
    clearBtn.Text = "x"
    clearBtn.TextColor3 = Color3.fromRGB(160, 160, 160)
    clearBtn.ZIndex = (button.ZIndex or 1) + 1
    clearBtn.Visible = false
    clearBtn.Parent = button

    local function hasSelection()
        if mode == "single" then
            return selectedKey ~= nil and tostring(selectedKey) ~= ""
        end
        for _, on in pairs(selectedMap) do
            if on then
                return true
            end
        end
        return false
    end

    local function updateClearButton()
        clearBtn.Visible = allowClear and hasSelection()
    end

    local function normalizeItem(e)
        if type(e) == "table" then
            local key = e.key or e.name or e.label
            local lbl = e.name or e.label
            if type(key) == "table" then
                key = key.key or key.name or key.label
            end
            if type(lbl) == "table" then
                lbl = lbl.name or lbl.label or lbl.key
            end
            if lbl == nil then
                lbl = key
            end
            key = tostring(key or "")
            lbl = tostring(lbl or key)
            if lbl:match("^table:%s*0x") then
                lbl = key
            end
            if key:match("^table:%s*0x") then
                key = ""
                lbl = ""
            end
            local icon = e.icon or e.image
            if type(icon) == "number" then
                icon = "rbxassetid://" .. tostring(math.floor(icon))
            elseif type(icon) == "string" and icon:match("^%d+$") then
                icon = "rbxassetid://" .. icon
            end
            return key, lbl, icon
        else
            local key = tostring(e)
            return key, key, nil
        end
    end

    local function syncItemLabels()
        keyToLabel = {}
        for _, e in ipairs(getItemsList() or {}) do
            local k, lbl = normalizeItem(e)
            keyToLabel[k] = lbl
        end
        itemsLoaded = true
        if type(opts.labelForKey) == "function" then
            if mode == "multi" then
                for k, on in pairs(selectedMap) do
                    if on and not keyToLabel[k] then
                        local ok, lbl = pcall(opts.labelForKey, k)
                        if ok and type(lbl) == "string" and lbl ~= "" then
                            keyToLabel[k] = lbl
                        end
                    end
                end
            elseif mode == "single" and selectedKey and not keyToLabel[selectedKey] then
                local ok, lbl = pcall(opts.labelForKey, selectedKey)
                if ok and type(lbl) == "string" and lbl ~= "" then
                    keyToLabel[selectedKey] = lbl
                end
            end
        end
    end

    local function resolveItemLabel(key)
        key = tostring(key or "")
        if key == "" or key:match("^table:%s*0x") then return "" end
        if keyToLabel[key] and keyToLabel[key] ~= "" then
            return keyToLabel[key]
        end
        if type(opts.labelForKey) == "function" then
            local ok, lbl = pcall(opts.labelForKey, key)
            if ok and type(lbl) == "string" and lbl ~= "" then
                keyToLabel[key] = lbl
                return lbl
            end
        end
        return key
    end

    local function refreshButtonText()
        local compact = isCard or isSplit or isStack
        local prefix = compact and "" or "  "
        local emptyColor = COLOR_PLACEHOLDER
        local filledColor = Color3.fromRGB(236, 236, 240)

        local function paint(isEmpty)
            button.TextColor3 = isEmpty and emptyColor or filledColor
        end

        if mode == "single" then
            if not selectedKey then
                button.Text = prefix .. placeholder
                paint(true)
            else
                button.Text = prefix .. resolveItemLabel(selectedKey)
                paint(false)
            end
            updateClearButton()
            return
        end

        local names = {}
        for k, on in pairs(selectedMap) do
            if on then
                table.insert(names, resolveItemLabel(k))
            end
        end
        table.sort(names)

        if #names == 0 then
            button.Text = prefix .. placeholder
            paint(true)
            updateClearButton()
            return
        end

        local maxChars = (isCard or isStack) and 40 or (isSplit and 20 or 25)
        local total = table.concat(names, ", ")
        if #total <= maxChars then
            button.Text = prefix .. total
            paint(false)
            updateClearButton()
            return
        end

        local shown, used = {}, 0
        for i, name in ipairs(names) do
            local part = (i == 1) and name or (", " .. name)
            if used + #part > maxChars then break end
            table.insert(shown, name)
            used += #part
        end
        local rest = #names - #shown
        local txt = table.concat(shown, ", ")
        if rest > 0 then
            txt ..= (" +%d"):format(rest)
        end
        button.Text = prefix .. txt
        paint(false)
        updateClearButton()
    end

    local function resolveSelectedKey(key)
        if not key or mode ~= "single" then
            return key
        end
        key = tostring(key)
        if keyToLabel[key] then
            return key
        end
        local lower = key:lower()
        for k, lbl in pairs(keyToLabel) do
            if k:lower() == lower or lbl:lower() == lower then
                return k
            end
        end
        local compact = lower:gsub("[^%w]", "")
        for k, lbl in pairs(keyToLabel) do
            if k:lower():gsub("[^%w]", "") == compact then
                return k
            end
            if lbl:lower():gsub("[^%w]", "") == compact then
                return k
            end
        end
        return key
    end

local function openDropdown()
