    --------------------------------------------------
    -- REBUILD LIST (SAMA KAYAK KODEMU SEBELUMNYA)
    --------------------------------------------------
    local function trimSearchText(s)
        return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    local rebuildGen = 0

local function rebuildList()
    rebuildGen += 1
    local myGen = rebuildGen

    currentItems = {}
    keyToLabel   = {}
    local onDeleteItem = opts.onDeleteItem

    local rawItems = {}
    local searchMessage = nil
    local qTrim = trimSearchText(search.Text)
    local useSearchProvider = type(searchGetItems) == "function"
    if useSearchProvider then
        if emptyUntilSearch and qTrim == "" then
            -- Keep pinned/saved getItems visible even before typing (e.g. Mail Multi
            -- saved recipients stay listed when unselected).
            rawItems = getItemsList() or {}
        else
            local ok, res = pcall(searchGetItems, qTrim)
            if myGen ~= rebuildGen then return end
            if ok and type(res) == "table" then
                rawItems = res
                searchMessage = res._searchMessage or res.searchMessage
            else
                rawItems = {}
                if not ok then
                    searchMessage = "Search error. Coba lagi."
                end
            end
        end
    else
        rawItems = getItemsList() or {}
    end

    if myGen ~= rebuildGen then return end

  -- build items + label map (dedupe by key)
    local itemKeysSeen = {}
    for idx, e in ipairs(rawItems) do
        local k, lbl, icon = normalizeItem(e)
        if k ~= "" and not itemKeysSeen[k] then
            itemKeysSeen[k] = true
            local sortKey = nil
            if type(e) == "table" then
                sortKey = tonumber(e.order) or tonumber(e.sort)
            end
            if not sortKey and preserveItemOrder then
                sortKey = idx
            elseif not sortKey and type(e) == "table" then
                sortKey = tonumber(e.key)
            end
            table.insert(currentItems, { key = k, label = lbl, icon = icon, sortKey = sortKey })
            keyToLabel[k] = lbl
        end
    end

    -- Jangan panggil getItemsList() lagi (Pets: BuildInventoryItems 2000 entry).
    -- searchGetItems perlu pool tersimpan terpisah; selain itu rawItems sudah lengkap.
    if useSearchProvider then
        for _, e in ipairs(getItemsList() or {}) do
            local k, lbl = normalizeItem(e)
            if k ~= "" and lbl ~= "" then
                keyToLabel[k] = keyToLabel[k] or lbl
            end
        end
    end

    local knownKeys = {}
    for _, info in ipairs(currentItems) do
        knownKeys[info.key] = true
    end
    if mode == "multi" then
        for k, on in pairs(selectedMap) do
            if on and not knownKeys[k] then
                local lbl = resolveItemLabel(k)
                table.insert(currentItems, { key = k, label = lbl })
                keyToLabel[k] = lbl
                knownKeys[k] = true
            end
        end
    elseif mode == "single" and selectedKey and not knownKeys[selectedKey] then
        local lbl = resolveItemLabel(selectedKey)
        table.insert(currentItems, { key = selectedKey, label = lbl })
        keyToLabel[selectedKey] = lbl
    end

    if myGen ~= rebuildGen then return end

    -- clear old list children (buttons/labels/frames)
    for _, c in ipairs(list:GetChildren()) do
        if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then
            c:Destroy()
        end
    end

    local q = (search.Text or ""):lower()

    -- helper: check selected
    local function isSelected(k)
        if mode == "single" then
            return selectedKey == k
        else
            return selectedMap[k] == true
        end
    end

    local function showSearchHint(text, isError)
        local hintItem = Instance.new("TextLabel")
        hintItem.Name = isError and "SearchErrorHint" or "EmptySearchHint"
        hintItem.BackgroundTransparency = 1
        hintItem.Size = UDim2.new(1, 0, 0, 40)
        hintItem.Font = Enum.Font.Gotham
        hintItem.TextSize = 11
        hintItem.TextColor3 = isError and Color3.fromRGB(255, 140, 140) or COLOR_GRAY_TEXT
        hintItem.TextWrapped = true
        hintItem.TextXAlignment = Enum.TextXAlignment.Center
        hintItem.Text = tostring(text or "")
        hintItem.LayoutOrder = 0
        hintItem.ZIndex = 101
        hintItem.Parent = list
    end

    if emptyUntilSearch and qTrim == "" and #currentItems == 0 then
        showSearchHint("Type to search...", false)
        return
    end

    -- filter + split selected/rest
    local picked, rest = {}, {}
    for _, info in ipairs(currentItems) do
        local lbl = tostring(info.label or "")
        local low = lbl:lower()
        local passFilter = useSearchProvider or q == "" or low:find(q, 1, true)
        if passFilter then
            if isSelected(info.key) then
                table.insert(picked, info)
            else
                table.insert(rest, info)
            end
        end
    end

    -- optional: sort per group biar rapi (numeric order > label A-Z)
    local function bySort(a, b)
        local sa, sb = a.sortKey, b.sortKey
        if sa and sb and sa ~= sb then return sa < sb end
        if sa and not sb then return true end
        if sb and not sa then return false end
        return tostring(a.label):lower() < tostring(b.label):lower()
    end
    table.sort(picked, bySort)
    table.sort(rest, bySort)

    -- merge: selected dulu
    local ordered = {}
    for _, v in ipairs(picked) do table.insert(ordered, v) end
    for _, v in ipairs(rest)   do table.insert(ordered, v) end

    if maxResults and maxResults > 0 and #ordered > maxResults then
        local capped = {}
        for i = 1, maxResults do
            capped[i] = ordered[i]
        end
        ordered = capped
    end

    if useSearchProvider and qTrim ~= "" and type(searchMessage) == "string" and searchMessage ~= "" then
        -- Error/hint saat hasil remote kosong; tetap tampil di atas list tersimpan (multi).
        if #ordered == 0 then
            showSearchHint(searchMessage, true)
            return
        end
        showSearchHint(searchMessage, true)
    elseif useSearchProvider and qTrim ~= "" and #ordered == 0 then
        showSearchHint("Username tidak ditemukan. Pakai exact Roblox username.", true)
        return
    end

    local idx = 0
    local rowGap = 3
    local function syncCanvas()
        list.CanvasSize = UDim2.new(0, 0, 0, math.max(0, idx * (22 + rowGap)))
    end

    -- render (batch + yield: buka Pets list 100+ row jangan 1 frame)
    for _, info in ipairs(ordered) do
        if myGen ~= rebuildGen then return end

        local k   = info.key
        local lbl = info.label
        local icon = info.icon

        idx += 1

        local rowH = (icon and icon ~= "") and 26 or 22
        local textPad = 6

        local btnItem = Instance.new("TextButton")
        btnItem.Name = "Item_" .. tostring(k)
        btnItem.AutoButtonColor = false
        btnItem.BackgroundColor3 = Color3.fromRGB(22,22,22)
        btnItem.Size = UDim2.new(1, 0, 0, rowH)
        btnItem.Text = ""
        btnItem.Font = Enum.Font.Gotham
        btnItem.TextXAlignment = Enum.TextXAlignment.Center
        btnItem.TextSize = 12
        btnItem.TextColor3 = Color3.fromRGB(220,220,220)
        btnItem.LayoutOrder = idx
        btnItem.ZIndex = 101
        btnItem.Parent = list
        createCorner(btnItem, 4)

        if icon and icon ~= "" then
            local img = Instance.new("ImageLabel")
            img.Name = "Icon"
            img.BackgroundTransparency = 1
            img.Size = UDim2.new(0, 18, 0, 18)
            img.Position = UDim2.new(0, 6, 0.5, -9)
            img.Image = icon
            img.ScaleType = Enum.ScaleType.Fit
            img.ZIndex = 102
            img.Parent = btnItem
            textPad = 28
        end
        
        local txt = Instance.new("TextLabel")
txt.BackgroundTransparency = 1
txt.Size = onDeleteItem and UDim2.new(1, -(textPad + 30), 1, 0) or UDim2.new(1, -textPad, 1, 0)
txt.Position = UDim2.new(0, textPad, 0, 0)
txt.Font = Enum.Font.Gotham
txt.TextXAlignment = onDeleteItem and Enum.TextXAlignment.Left or Enum.TextXAlignment.Center
txt.TextSize = 12
txt.TextColor3 = Color3.fromRGB(220,220,220)
txt.Text = tostring(lbl)
txt.ZIndex = 102
txt.Parent = btnItem

local deleting = false
if onDeleteItem then
    local del = Instance.new("TextButton")
    del.Name = "DeleteButton"
    del.Size = UDim2.new(0, 20, 0, 20)
    del.Position = UDim2.new(1, -24, 0.5, -10)
    del.BackgroundColor3 = Color3.fromRGB(45, 20, 20)
    del.AutoButtonColor = false
    del.Text = "X"
    del.Font = Enum.Font.GothamBold
    del.TextSize = 11
    del.TextColor3 = Color3.fromRGB(255,255,255)
    del.ZIndex = 103
    del.Active = true
    del.Parent = btnItem

    createCorner(del, 5)
    createStroke(del, Color3.fromRGB(255,80,80), 1, 0.3)

del.MouseButton1Click:Connect(function()
    deleting = true

    selectedMap[k] = nil
    if selectedKey == k then
        selectedKey = nil
    end

    if onDeleteItem then
        pcall(function()
            onDeleteItem(k, info)
        end)
    end

    if mode == "single" and not selectedKey then
        for _, e in ipairs(getItemsList() or {}) do
            local kk = normalizeItem(e)
            if kk and kk ~= k then
                selectedKey = kk
                break
            end
        end
        if not selectedKey then
            for _, e in ipairs(getItemsList() or {}) do
                local kk = normalizeItem(e)
                if kk then
                    selectedKey = kk
                    break
                end
            end
        end
    end

    refreshButtonText()
    rebuildList()

    task.defer(function()
        deleting = false
    end)
end)
end

        local function applyVisual()
            if mode == "single" then
if selectedKey == k then
    tweenColor(btnItem, "BackgroundColor3", COLOR_YELLOW)

    btnItem.TextColor3 = COLOR_PANEL
    txt.TextColor3 = COLOR_PANEL
else
    tweenColor(btnItem, "BackgroundColor3", Color3.fromRGB(22,22,22))

    btnItem.TextColor3 = Color3.fromRGB(220,220,220)
    txt.TextColor3 = Color3.fromRGB(220,220,220)
end
            else
if selectedMap[k] then
    tweenColor(btnItem, "BackgroundColor3", COLOR_YELLOW)

    btnItem.TextColor3 = COLOR_PANEL
    txt.TextColor3 = COLOR_PANEL
else
    tweenColor(btnItem, "BackgroundColor3", Color3.fromRGB(22,22,22))

    btnItem.TextColor3 = Color3.fromRGB(220,220,220)
    txt.TextColor3 = Color3.fromRGB(220,220,220)
end
            end
        end
        applyVisual()

        btnItem.MouseButton1Click:Connect(function()
                if deleting then
        return
    end
            if mode == "single" then
                selectedKey = k
                refreshButtonText()
                if onChanged then
                    onChanged("single", selectedKey)
                end
                persistSelection()
                overlay:Destroy()
            else
                selectedMap[k] = not selectedMap[k]
                refreshButtonText()
                if onChanged then
                    local copy = {}
                    for kk, vv in pairs(selectedMap) do
                        if vv then copy[kk] = true end
                    end
                    onChanged("multi", copy)
                end
                persistSelection()
                -- Jangan rebuildList() di sini: destroy+recreate semua tombol pet = spike.
                applyVisual()
                return
            end
        end)

        if idx % 40 == 0 then
            syncCanvas()
            task.wait()
            if myGen ~= rebuildGen then return end
        end
    end
    syncCanvas()
end


    local searchDebounceToken = 0
    -- searchGetItems (Roblox username lookup) pakai debounce lebih lama biar gak spam API
    local searchDebounceSec = (type(searchGetItems) == "function") and 0.45 or 0.15
    search:GetPropertyChangedSignal("Text"):Connect(function()
        searchDebounceToken += 1
        local token = searchDebounceToken
        task.delay(searchDebounceSec, function()
            if token ~= searchDebounceToken then return end
            rebuildList()
        end)
    end)

    --------------------------------------------------
    -- CLOSE HANDLER (X & KLIK DI LUAR PANEL)
    --------------------------------------------------
    local UserInputService = game:GetService("UserInputService")

    local function closeOverlay()
        if api then
            api._rebuildOpenList = nil
        end
        if onClose then
            pcall(onClose)
        end
        if overlay and overlay.Parent then
            overlay:Destroy()
        end
    end

    closeBtn.MouseButton1Click:Connect(closeOverlay)

    overlay.MouseButton1Click:Connect(function()
        local mousePos = UserInputService:GetMouseLocation()
        local pPos = panel.AbsolutePosition
        local pSize = panel.AbsoluteSize

        local x, y = mousePos.X, mousePos.Y
        local insideX = x >= pPos.X and x <= pPos.X + pSize.X
        local insideY = y >= pPos.Y and y <= pPos.Y + pSize.Y

        -- kalau klik di LUAR panel → close, kalau di dalam panel → abaikan
        if not (insideX and insideY) then
            closeOverlay()
        end
    end)

    search.Text = ""
    if api then
        api._rebuildOpenList = rebuildList
    end
    rebuildList()
end




    button.MouseEnter:Connect(function()
        tweenColor(button, "BackgroundColor3", Color3.fromRGB(24,24,24))
    end)
    button.MouseLeave:Connect(function()
        tweenColor(button, "BackgroundColor3", Color3.fromRGB(18,18,18))
    end)
    button.MouseButton1Click:Connect(function()
        if ignoreOpen then
            return
        end
        openDropdown()
    end)

    if deferItemLoad then
        refreshButtonText()
    else
        syncItemLabels()
        if mode == "single" and selectedKey then
            selectedKey = resolveSelectedKey(selectedKey)
        end
        refreshButtonText()
    end

    if mode == "multi" and type(onChanged) == "function" and next(selectedMap) then
        task.defer(function()
            if self._skipDropdownInitialNotify == true then
                return
            end
            local copy = {}
            for k, v in pairs(selectedMap) do
                if v then copy[k] = true end
            end
            if next(copy) then
                onChanged("multi", copy)
            end
        end)
    elseif mode == "single" and type(onChanged) == "function" and selectedKey then
        task.defer(function()
            if self._skipDropdownInitialNotify == true then
                return
            end
            onChanged("single", selectedKey)
        end)
    end

    function api.getMode()
        return mode
    end

    function api.setMode(newMode)
        if newMode == "multi" then
            mode = "multi"
        else
            mode = "single"
        end
        refreshButtonText()
    end

    function api.setSelected(value, silent)
        if mode == "single" then
            selectedKey = coerceSingleKey(value)
        else
            selectedMap = {}
            if type(value) == "table" then
                for k, v in pairs(value) do
                    if v == true or v == 1 or v == "true" then
                        selectedMap[tostring(k)] = true
                    elseif type(k) == "number" and v ~= nil then
                        selectedMap[tostring(v)] = true
                    end
                end
            elseif value ~= nil then
                selectedMap[tostring(value)] = true
            end
        end
        refreshButtonText()
        if silent ~= true and type(onChanged) == "function" then
            if mode == "single" then
                pcall(onChanged, "single", selectedKey)
            else
                pcall(onChanged, "multi", selectedMap)
            end
        end
        if silent ~= true then
            persistSelection()
        end
    end

    function api.getSelected()
        if mode == "single" then
            return selectedKey
        else
            local copy = {}
            for k, v in pairs(selectedMap) do
                if v then copy[k] = true end
            end
            return copy
        end
    end

    function api.setLabel(text)
        if typeof(label) == "Instance" then
            label.Text = tostring(text or "")
        end
    end

    function api.refreshLabel()
        refreshButtonText()
    end

    function api.refreshItems()
        -- deferItemLoad: jangan BuildInventoryItems 2000 pet hanya karena sync/refresh
        -- (dropdown belum pernah dibuka → itemsLoaded=false).
        if deferItemLoad and not itemsLoaded then
            refreshButtonText()
            return
        end
        syncItemLabels()
        refreshButtonText()
        if type(api._rebuildOpenList) == "function" then
            pcall(api._rebuildOpenList)
        end
    end

    function api.clear(silent)
        if mode == "single" then
            api.setSelected(nil, silent)
        else
            api.setSelected({}, silent)
        end
    end

    clearBtn.MouseButton1Click:Connect(function()
        ignoreOpen = true
        api.clear(false)
        task.defer(function()
            ignoreOpen = false
        end)
    end)

    local bindApi = {
        get = api.getSelected,
        set = function(value, silent)
            api.setSelected(value, silent)
        end,
        getSelected = api.getSelected,
        setSelected = api.setSelected,
        refreshItems = api.refreshItems,
        refreshLabel = api.refreshLabel,
        setLabel = api.setLabel,
        clear = api.clear,
        row = row,
    }
    self:_bindWidget(opts.id, "dropdown", bindApi, opts.persist, row)
    api.row = row

    local outer = row
    if hasHint and not hintPlaced then
        local hint = Instance.new("TextLabel")
        hint.Name = "Hint"
        hint.BackgroundTransparency = 1
        hint.Size = UDim2.new(1, 0, 0, 0)
        hint.AutomaticSize = Enum.AutomaticSize.Y
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 10
        hint.TextColor3 = COLOR_HINT
        hint.TextWrapped = true
        hint.TextXAlignment = Enum.TextXAlignment.Left
        hint.TextYAlignment = Enum.TextYAlignment.Top
        hint.Text = hintText
        hint.LayoutOrder = 3

        if isStack then
            local hintPad = Instance.new("UIPadding")
            hintPad.PaddingLeft = UDim.new(0, 2)
            hintPad.Parent = hint
            if rowPad then
                rowPad.PaddingBottom = UDim.new(0, 14)
            end
            hint.Parent = row
        else
            local savedOrder = row.LayoutOrder
            outer = Instance.new("Frame")
            outer.Name = "RowDropdownWrap"
            outer.BackgroundTransparency = 1
            outer.Size = UDim2.new(1, 0, 0, 0)
            outer.AutomaticSize = Enum.AutomaticSize.Y
            outer.LayoutOrder = savedOrder
            outer.Parent = parent

            row.LayoutOrder = 1
            row.Parent = outer

            local wrapLayout = Instance.new("UIListLayout")
            wrapLayout.FillDirection = Enum.FillDirection.Vertical
            wrapLayout.SortOrder = Enum.SortOrder.LayoutOrder
            wrapLayout.Padding = UDim.new(0, 4)
            wrapLayout.Parent = outer

            hint.LayoutOrder = 2
            hint.Parent = outer
        end
    end

    attachVisibility(api, outer)
    if type(bindApi) == "table" then
        bindApi.root = outer
        bindApi.setVisible = api.setVisible
        bindApi.getVisible = api.getVisible
    end
    return outer, api
end

function MainUI:OpenModePicker(items, currentId, onChosen, titleText)
    -- items: { {id="auto", label="AUTO - ..."}, ... }
    -- currentId: string (misal "auto")
    -- onChosen(id): callback

    -- ROOT GUI (bukan cuma panel kanan)


    local parentGui = self._sg or PlayerGui   -- ⬅️ ScreenGui
    local parentFrame = parentGui             -- ⬅️ pakai ini, bukan self.right

    --------------------------------------------------
    -- OVERLAY DI DALAM ROOT UI
    --------------------------------------------------
    local overlay = Instance.new("TextButton")
    overlay.Name = "NodeHubModeOverlay"
    overlay.BackgroundColor3 = Color3.fromRGB(0,0,0)
    overlay.BackgroundTransparency = 0.25
    overlay.AutoButtonColor = false
    overlay.BorderSizePixel = 0
    overlay.Text = ""
    overlay.Size = UDim2.new(1, 0, 1, 0)         -- full screen
    overlay.Position = UDim2.new(0, 0, 0, 0)
    overlay.ZIndex = 98
    overlay.Active = true
    overlay.Parent = parentGui     

    --------------------------------------------------
    -- PANEL TENGAH
    --------------------------------------------------
    local panel = Instance.new("Frame")
    panel.Name = "ModePanel"
    panel.Size = UDim2.new(0, 300, 0, 260) -- lebar default, nanti diubah
    panel.AnchorPoint = Vector2.new(0.5, 0.5)
    panel.Position = UDim2.new(0.5, 0, 0.5, 0)
    panel.BackgroundColor3 = COLOR_PANEL
    panel.ZIndex = 99
    panel.Active = true
    panel.Parent = overlay
    createCorner(panel, 10)
    createStroke(panel, COLOR_YELLOW, 1, 0.3)

    local pad = Instance.new("UIPadding")
    pad.PaddingTop    = UDim.new(0, 8)
    pad.PaddingBottom = UDim.new(0, 8)
    pad.PaddingLeft   = UDim.new(0, 8)
    pad.PaddingRight  = UDim.new(0, 8)
    pad.Parent = panel

    --------------------------------------------------
    -- CLOSE BUTTON
    --------------------------------------------------
    local closeBtn = Instance.new("TextButton")
    closeBtn.Size = UDim2.new(0, 22, 0, 22)
    closeBtn.AnchorPoint = Vector2.new(1, 0)
    closeBtn.Position = UDim2.new(1, 2, 0, 0)
    closeBtn.BackgroundColor3 = Color3.fromRGB(18,18,18)
    closeBtn.AutoButtonColor = false
    closeBtn.BorderSizePixel = 0
    closeBtn.Text = "X"
    closeBtn.Font = Enum.Font.GothamBold
    closeBtn.TextSize = 12
    closeBtn.TextColor3 = COLOR_WHITE
    closeBtn.ZIndex = 101
    closeBtn.Parent = panel
    createCorner(closeBtn, 6)
    createStroke(closeBtn, COLOR_YELLOW, 1, 0.4)

    --------------------------------------------------
    -- TITLE + SEARCH
    --------------------------------------------------
    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Size = UDim2.new(1, -24, 0, 20)
    title.Position = UDim2.new(0, 0, 0, 0)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 13
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextColor3 = COLOR_YELLOW
    title.Text = tostring(titleText or "Select Mode")
    title.ZIndex = 100
    title.Parent = panel

    local search = Instance.new("TextBox")
    search.Name = "SearchBox"
    search.Size = UDim2.new(1, 0, 0, 24)
    search.Position = UDim2.new(0, 0, 0, 24)
    search.BackgroundColor3 = Color3.fromRGB(18,18,18)
    search.PlaceholderText = "Search..."
    search.ClearTextOnFocus = false
    search.Font = Enum.Font.Gotham
    search.TextSize = 12
    search.TextXAlignment = Enum.TextXAlignment.Center
    search.TextColor3 = Color3.fromRGB(230,230,230)
    search.ZIndex = 100
    search.Parent = panel
    createCorner(search, 6)
    createStroke(search, Color3.fromRGB(60,60,60), 1, 0.6)

    --------------------------------------------------
    -- LIST
    --------------------------------------------------
    local list = Instance.new("ScrollingFrame")
    list.Name = "List"
    list.Size = UDim2.new(1, 0, 1, -56)
    list.Position = UDim2.new(0, 0, 0, 52)
    list.BackgroundTransparency = 1
    list.ScrollBarThickness = 4
    list.ScrollBarImageTransparency = 0
    list.AutomaticCanvasSize = Enum.AutomaticSize.Y
    list.CanvasSize = UDim2.new(0, 0, 0, 0)
    list.ZIndex = 100
    list.Parent = panel

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 3)
    layout.Parent = list

    --------------------------------------------------
    -- CLOSE HANDLER
    --------------------------------------------------
    local function closeOverlay()
        if overlay and overlay.Parent then
            overlay:Destroy()
        end
    end

    closeBtn.MouseButton1Click:Connect(closeOverlay)

    local UIS = game:GetService("UserInputService")
    overlay.MouseButton1Click:Connect(function()
        local mp   = UIS:GetMouseLocation()
        local pPos = panel.AbsolutePosition
        local pSz  = panel.AbsoluteSize

        local insideX = mp.X >= pPos.X and mp.X <= pPos.X + pSz.X
        local insideY = mp.Y >= pPos.Y and mp.Y <= pPos.Y + pSz.Y
        if not (insideX and insideY) then
            closeOverlay()
        end
    end)

    --------------------------------------------------
    -- HITUNG LEBAR PANEL DARI TEKS TERPANJANG
    --------------------------------------------------
    --------------------------------------------------
-- HITUNG LEBAR PANEL DARI TEKS TERPANJANG
--------------------------------------------------
local function resizePanelWidthFromItems()
    if not TextService or not TextService.GetTextSize then
        panel.Size = UDim2.new(0, 300, 0, 260)
        return
    end

    local maxWidth  = 0
    local font      = Enum.Font.Gotham
    local textSize  = 11

    for _, opt in ipairs(items or {}) do
        local id   = tostring(opt.id)
        local text = opt.label or id
        local full = string.format("  [%s]  %s", id, text)

        local bounds = TextService:GetTextSize(
            full,
            textSize,
            font,
            Vector2.new(10000, 24)
        )

        if bounds.X > maxWidth then
            maxWidth = bounds.X
        end
    end

    -- hitung padding kiri/kanan dari UIPadding panel
    local padLeft  = pad and pad.PaddingLeft and pad.PaddingLeft.Offset or 0
    local padRight = pad and pad.PaddingRight and pad.PaddingRight.Offset or 0

    -- sedikit margin ekstra di kiri/kanan button
    local extraMargin = 15

    local desiredWidth = maxWidth + padLeft + padRight + extraMargin

    -- MIN & MAX LEBAR PANEL
    desiredWidth = math.clamp(desiredWidth, 340, 680)

    -- tinggi tetap 260
    panel.Size = UDim2.new(0, desiredWidth, 0, 290)
end


    resizePanelWidthFromItems()

    --------------------------------------------------
    -- REBUILD LIST
    --------------------------------------------------
    local function rebuildList()
        for _, c in ipairs(list:GetChildren()) do
            if c:IsA("TextButton") then
                c:Destroy()
            end
        end

        local q   = string.lower(search.Text or "")
        local idx = 0
        local cur = tostring(currentId or "")

        for _, opt in ipairs(items or {}) do
            local id   = tostring(opt.id)
            local text = opt.label or id
            local low  = string.lower(text)

            if q == "" or string.find(low, q, 1, true) then
                idx += 1

                local btn = Instance.new("TextButton")
                btn.Name = "Item_" .. id
                btn.AutoButtonColor = false
                btn.BackgroundColor3 = (id == cur)
                    and COLOR_YELLOW
                    or Color3.fromRGB(22,22,22)

                btn.Size = UDim2.new(1, 0, 0, 24)
                btn.Text = string.format("  %s", text)
                btn.Font = Enum.Font.Gotham
                btn.TextXAlignment = Enum.TextXAlignment.Left
                btn.TextSize = 12
                btn.TextColor3 = (id == cur)
                    and COLOR_PANEL
                    or Color3.fromRGB(220,220,220)
                btn.LayoutOrder = idx
                btn.ZIndex = 101

                -- jangan di-"..." (biar full, panel sudah dilebarkan)
                btn.TextTruncate = Enum.TextTruncate.None

                btn.Parent = list
                createCorner(btn, 4)

                btn.MouseButton1Click:Connect(function()
                    currentId = id
                    if onChosen then
                        onChosen(id)
                    end
                    closeOverlay()
                end)
            end
        end
    end

    search:GetPropertyChangedSignal("Text"):Connect(rebuildList)
    search.Text = ""
    rebuildList()
end


----------------------------------------------------------
-- RULE LIST  (search + colored summary + chip + on/off + delete)
-- CreateRuleList(parent, {
--   id, title, searchPlaceholder, emptyText, visibleRows,
--   getItems = function() return { { id, enabled, parts, chips } } end,
--   formatItem = function(rule, index) return view end, -- optional
--   onToggle, onDelete, onPartClick, persist
-- })
-- parts: { { text=, color= or style="kg", kind= } }
-- chips: { { text=, style=, onClick= } }
----------------------------------------------------------
function MainUI:CreateRuleList(parent, opts)
    opts = _isOpts(opts) and opts or {}
    local ROW_H = 26
    local ROW_PAD = 4
    local VISIBLE = math.max(1, tonumber(opts.visibleRows) or 6)
    local items = type(opts.items) == "table" and opts.items or {}

    local function currentItems()
        if type(opts.getItems) == "function" then
            local ok, res = pcall(opts.getItems)
            if ok and type(res) == "table" then
                return res
            end
        end
        return items
    end

    local function partColor(part)
        if type(part) ~= "table" then
            return RULE_PART_COLORS.default
        end
        if typeof(part.color) == "Color3" then
            return part.color
        end
        local key = tostring(part.style or part.kind or "")
        return RULE_PART_COLORS[key]
            or (ROW_LABEL_THEMES[key] and ROW_LABEL_THEMES[key].color)
            or RULE_PART_COLORS.default
    end

    local function viewOf(rule, index)
        if type(opts.formatItem) == "function" then
            local ok, view = pcall(opts.formatItem, rule, index)
            if ok and type(view) == "table" then
                return view
            end
        end
        if type(rule) ~= "table" then
            return { id = tostring(index), parts = { { text = tostring(rule or "") } }, enabled = true }
        end
        return {
            id = tostring(rule.id or index),
            enabled = rule.enabled ~= false,
            parts = type(rule.parts) == "table" and rule.parts or { { text = tostring(rule.text or rule.id or index) } },
            chips = type(rule.chips) == "table" and rule.chips or nil,
        }
    end

    local root = Instance.new("Frame")
    root.Name = "RowRuleList"
    root.BackgroundTransparency = 1
    root.Size = UDim2.new(1, 0, 0, 0)
    root.AutomaticSize = Enum.AutomaticSize.Y
    root.LayoutOrder = opts.order or (#parent:GetChildren() + 1)
    root.Parent = parent

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 6)
    layout.Parent = root

    local titleLbl = Instance.new("TextLabel")
    titleLbl.Name = "Title"
    titleLbl.BackgroundTransparency = 1
    titleLbl.Size = UDim2.new(1, 0, 0, 16)
    titleLbl.LayoutOrder = 1
    titleLbl.Font = Enum.Font.Gotham
    titleLbl.TextSize = 12
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.Text = tostring(opts.title or "Saved Rules")
    titleLbl.Parent = root
    applyRowLabelStyle(titleLbl, "list")

    local searchWrap = Instance.new("Frame")
    searchWrap.Name = "SearchWrap"
    searchWrap.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
    searchWrap.BorderSizePixel = 0
    searchWrap.Size = UDim2.new(1, 0, 0, 24)
    searchWrap.LayoutOrder = 2
    searchWrap.Parent = root
    createCorner(searchWrap, 6)
    createStroke(searchWrap, Color3.fromRGB(50, 50, 50), 1, 0.45)

    local searchBox = Instance.new("TextBox")
    searchBox.Name = "Search"
    searchBox.BackgroundTransparency = 1
    searchBox.Size = UDim2.new(1, -12, 1, 0)
    searchBox.Position = UDim2.new(0, 6, 0, 0)
    searchBox.Font = Enum.Font.Gotham
    searchBox.TextSize = 12
    searchBox.TextColor3 = Color3.fromRGB(230, 230, 230)
    searchBox.PlaceholderText = tostring(opts.searchPlaceholder or "Search rules...")
    searchBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 110)
    searchBox.TextXAlignment = Enum.TextXAlignment.Left
    searchBox.ClearTextOnFocus = false
    searchBox.Text = ""
    searchBox.Parent = searchWrap

    local function listHeight(count)
        local rows = math.clamp(count, 1, VISIBLE)
        return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + 10
    end

    local listScroll = Instance.new("ScrollingFrame")
    listScroll.Name = "Rules"
    listScroll.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    listScroll.BorderSizePixel = 0
    listScroll.LayoutOrder = 3
    listScroll.Size = UDim2.new(1, 0, 0, listHeight(0))
    listScroll.ScrollBarThickness = 4
    listScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    listScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
    listScroll.ClipsDescendants = true
    listScroll.Parent = root
    createCorner(listScroll, 6)
    createStroke(listScroll, Color3.fromRGB(40, 40, 40), 1, 0.5)

    local listPad = Instance.new("UIPadding")
    listPad.PaddingTop = UDim.new(0, 5)
    listPad.PaddingBottom = UDim.new(0, 5)
    listPad.PaddingLeft = UDim.new(0, 5)
    listPad.PaddingRight = UDim.new(0, 5)
    listPad.Parent = listScroll

    local listLayout = Instance.new("UIListLayout")
    listLayout.FillDirection = Enum.FillDirection.Vertical
    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    listLayout.Padding = UDim.new(0, ROW_PAD)
    listLayout.Parent = listScroll

    local function clearRows()
        for _, ch in ipairs(listScroll:GetChildren()) do
            if ch:IsA("Frame") or (ch:IsA("TextLabel") and ch.Name == "EmptyHint") then
                ch:Destroy()
            end
        end
    end

    local function mountParts(parentFrame, parts, rule)
        local wrap = Instance.new("Frame")
        wrap.Name = "Parts"
        wrap.BackgroundTransparency = 1
        wrap.Size = UDim2.new(1, 0, 1, 0)
        wrap.ClipsDescendants = true
        wrap.Parent = parentFrame

        local hl = Instance.new("UIListLayout")
        hl.FillDirection = Enum.FillDirection.Horizontal
        hl.VerticalAlignment = Enum.VerticalAlignment.Center
        hl.SortOrder = Enum.SortOrder.LayoutOrder
        hl.Parent = wrap

        for i, part in ipairs(parts or {}) do
            local txt = tostring((type(part) == "table" and part.text) or part or "")
            if txt ~= "" then
            local clickable = type(part) == "table" and part.kind ~= nil and type(opts.onPartClick) == "function"
            local inst
            if clickable then
                inst = Instance.new("TextButton")
                inst.AutoButtonColor = false
                inst.BackgroundTransparency = 1
                inst.MouseButton1Click:Connect(function()
                    pcall(opts.onPartClick, rule, part)
                end)
            else
                inst = Instance.new("TextLabel")
                inst.BackgroundTransparency = 1
            end
            inst.Name = "Part" .. i
            inst.LayoutOrder = i
            inst.AutomaticSize = Enum.AutomaticSize.X
            inst.Size = UDim2.new(0, 0, 1, 0)
            inst.Font = Enum.Font.Gotham
            inst.TextSize = 11
            inst.TextXAlignment = Enum.TextXAlignment.Left
            inst.Text = txt
            inst.TextColor3 = partColor(part)
            inst.Parent = wrap
            end
        end
    end

    local function buildRow(index, rule)
        local view = viewOf(rule, index)
        local enabled = view.enabled ~= false
        local item = Instance.new("Frame")
        item.Name = "Item_" .. tostring(view.id or index)
        item.BackgroundColor3 = enabled and Color3.fromRGB(22, 22, 22) or Color3.fromRGB(16, 16, 16)
        item.Size = UDim2.new(1, 0, 0, ROW_H)
        item.LayoutOrder = index
        item.Parent = listScroll
        createCorner(item, 5)

        local showToggle = opts.showToggle ~= false
        local chips = view.chips or {}
        local chipW = (#chips > 0) and 34 or 0
        local onW = showToggle and 34 or 0
        local delW = 22
        local gap = 4
        local rightW = delW + (onW > 0 and (gap + onW) or 0) + (chipW > 0 and (gap + chipW) or 0)

        local idxLbl = Instance.new("TextLabel")
        idxLbl.BackgroundTransparency = 1
        idxLbl.Size = UDim2.new(0, 20, 1, 0)
        idxLbl.Position = UDim2.new(0, 6, 0, 0)
        idxLbl.Font = Enum.Font.GothamBold
        idxLbl.TextSize = 11
        idxLbl.TextXAlignment = Enum.TextXAlignment.Left
        idxLbl.Text = tostring(index) .. "."
        idxLbl.TextColor3 = enabled and COLOR_YELLOW or Color3.fromRGB(90, 90, 90)
        idxLbl.Parent = item

        local summary = Instance.new("Frame")
        summary.BackgroundTransparency = 1
        summary.Position = UDim2.new(0, 26, 0, 0)
        summary.Size = UDim2.new(1, -rightW - 32, 1, 0)
        summary.Parent = item
        mountParts(summary, view.parts, rule)

        local x = 4
        local del = Instance.new("TextButton")
        del.Name = "Delete"
        del.AutoButtonColor = true
        del.BackgroundColor3 = Color3.fromRGB(150, 40, 40)
        del.Size = UDim2.new(0, delW, 0, 18)
        del.AnchorPoint = Vector2.new(1, 0.5)
        del.Position = UDim2.new(1, -x, 0.5, 0)
        del.Font = Enum.Font.GothamBold
        del.TextSize = 14
        del.TextColor3 = Color3.fromRGB(255, 255, 255)
        del.Text = "-"
        del.Parent = item
        createCorner(del, 4)
        x = x + delW + gap

        del.MouseButton1Click:Connect(function()
            if type(opts.onDelete) == "function" then
                pcall(opts.onDelete, rule, view.id)
            end
        end)

        if showToggle then
            local onBtn = Instance.new("TextButton")
            onBtn.Name = "OnOff"
            onBtn.AutoButtonColor = true
            onBtn.BackgroundColor3 = enabled and COLOR_YELLOW or Color3.fromRGB(48, 48, 48)
            onBtn.Size = UDim2.new(0, onW, 0, 18)
            onBtn.AnchorPoint = Vector2.new(1, 0.5)
            onBtn.Position = UDim2.new(1, -x, 0.5, 0)
            onBtn.Font = Enum.Font.GothamBold
            onBtn.TextSize = 9
            onBtn.TextColor3 = enabled and COLOR_PANEL or Color3.fromRGB(150, 150, 150)
            onBtn.Text = enabled and "ON" or "OFF"
            onBtn.Parent = item
            createCorner(onBtn, 5)
            x = x + onW + gap
            onBtn.MouseButton1Click:Connect(function()
                if type(opts.onToggle) == "function" then
                    pcall(opts.onToggle, rule, not enabled)
                end
            end)
        end

        if #chips > 0 then
            local chip = chips[1]
            local chipBtn = Instance.new("TextButton")
            chipBtn.Name = "Chip"
            chipBtn.AutoButtonColor = true
            chipBtn.BackgroundColor3 = Color3.fromRGB(48, 34, 72)
            chipBtn.Size = UDim2.new(0, chipW, 0, 18)
            chipBtn.AnchorPoint = Vector2.new(1, 0.5)
            chipBtn.Position = UDim2.new(1, -x, 0.5, 0)
            chipBtn.Font = Enum.Font.GothamBold
            chipBtn.TextSize = 10
            chipBtn.TextColor3 = Color3.fromRGB(220, 175, 255)
            chipBtn.Text = tostring(chip.text or "")
            chipBtn.Parent = item
            createCorner(chipBtn, 5)
            chipBtn.MouseButton1Click:Connect(function()
                if type(chip.onClick) == "function" then
                    pcall(chip.onClick, rule)
                elseif type(opts.onChipClick) == "function" then
                    pcall(opts.onChipClick, rule, chip)
                end
            end)
        end
    end

    local function refresh()
        clearRows()
        local q = string.lower(tostring(searchBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
        local all = currentItems()
        local shown = {}
        for i, rule in ipairs(all) do
            local view = viewOf(rule, i)
            local blob = string.lower(tostring(view.id or ""))
            for _, part in ipairs(view.parts or {}) do
                blob = blob .. " " .. string.lower(tostring(part.text or ""))
            end
            if q == "" or string.find(blob, q, 1, true) then
                shown[#shown + 1] = { index = i, rule = rule }
            end
        end

        listScroll.Size = UDim2.new(1, 0, 0, listHeight(#shown))

        if #shown == 0 then
            local empty = Instance.new("TextLabel")
            empty.Name = "EmptyHint"
            empty.BackgroundTransparency = 1
            empty.Size = UDim2.new(1, 0, 0, ROW_H)
            empty.Font = Enum.Font.Gotham
            empty.TextSize = 11
            empty.TextColor3 = Color3.fromRGB(130, 130, 136)
            empty.Text = (#all == 0)
                and tostring(opts.emptyText or "Belum ada rule.")
                or "Tidak ada rule cocok search."
            empty.Parent = listScroll
            return
        end

        for _, entry in ipairs(shown) do
            buildRow(entry.index, entry.rule)
        end
    end

    local debounce = 0
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        debounce += 1
        local token = debounce
        task.delay(0.12, function()
            if token == debounce then
                refresh()
            end
        end)
    end)

    local api = {}
    function api.get()
        return currentItems()
    end
    function api.set(list, _silent)
        if type(list) == "table" then
            items = list
            if type(opts.onLoad) == "function" then
                pcall(opts.onLoad, list)
            end
        end
        refresh()
        return currentItems()
    end
    function api.refresh()
        refresh()
    end

    refresh()
    self:_bindWidget(opts.id, "rules", api, opts.persist, root)
    api.row = root
    attachVisibility(api, root)
    return root, api
end

----------------------------------------------------------
-- RULE FORM  (mode multi dropdown + hide/unhide field rows)
-- CreateRuleForm(parent, {
--   id, label, placeholder, hintText, persist,
--   modes = { { key="zone", name="Zone" }, ... },
--   initial = { zone = true },
--   onChanged = function(selectedMap) end,
-- })
-- api.attach(key, fieldApi, onHide)
-- api.has(key) / api.getModes() / api.apply()
----------------------------------------------------------
function MainUI:CreateRuleForm(parent, opts)
    opts = _isOpts(opts) and opts or {}
    local modes = type(opts.modes) == "table" and opts.modes or {}
    local selected = {}
    if type(opts.initial) == "table" then
        for k, v in pairs(opts.initial) do
            if v == true or v == 1 or v == "true" then
                selected[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil then
                selected[tostring(v)] = true
            end
        end
    end
    local fields = {}

    local api = {}

    local function copySelected()
        local out = {}
        for key, on in pairs(selected) do
            if on == true then
                out[key] = true
            end
        end
        return out
    end

    function api.apply()
        for key, rec in pairs(fields) do
            local show = selected[tostring(key)] == true
            local fieldApi = rec and rec.api
            if type(fieldApi) == "table" and type(fieldApi.setVisible) == "function" then
                pcall(fieldApi.setVisible, show)
            elseif type(fieldApi) == "table" then
                local root = fieldApi.root or fieldApi.row
                if root then
                    root.Visible = show
                end
            end
            if show ~= true and rec.visible == true and type(rec.onHide) == "function" then
                pcall(rec.onHide)
            end
            rec.visible = show == true
        end
    end

    function api.has(key)
        return selected[tostring(key or "")] == true
    end

    function api.getModes()
        return copySelected()
    end

    function api.attach(key, fieldApi, onHide)
        key = tostring(key or "")
        if key == "" or type(fieldApi) ~= "table" then
            return api
        end
        local show = selected[key] == true
        fields[key] = { api = fieldApi, onHide = onHide, visible = show }
        if type(fieldApi.setVisible) == "function" then
            pcall(fieldApi.setVisible, show)
        elseif fieldApi.root or fieldApi.row then
            local root = fieldApi.root or fieldApi.row
            root.Visible = show
        end
        return api
    end

    local _, modeApi = self:CreateRowDropdown(parent, {
        id = opts.id,
        label = opts.label or "Rule Fields",
        placeholder = opts.placeholder or "Pick fields...",
        hintText = opts.hintText or "Pilih field, baru input muncul.",
        mode = "multi",
        clearable = true,
        persist = opts.persist,
        preserveItemOrder = true,
        initial = selected,
        getItems = function()
            return modes
        end,
        onChanged = function(a, b)
            local map = {}
            if a == "multi" and type(b) == "table" then
                map = b
            elseif type(a) == "table" then
                map = a
            elseif type(b) == "table" then
                map = b
            end
            selected = {}
            for k, v in pairs(map) do
                if v == true or v == 1 or v == "true" then
                    selected[tostring(k)] = true
                elseif type(k) == "number" and v ~= nil then
                    selected[tostring(v)] = true
                end
            end
            api.apply()
            if type(opts.onChanged) == "function" then
                pcall(opts.onChanged, copySelected())
            end
        end,
    })

    if type(modeApi) == "table" and type(modeApi.getSelected) == "function" then
        local ok, cur = pcall(modeApi.getSelected)
        if ok and type(cur) == "table" then
            selected = {}
            for k, v in pairs(cur) do
                if v == true then
                    selected[tostring(k)] = true
                end
            end
        end
    end

    api.modeApi = modeApi
    api.get = function()
        return copySelected()
    end
    api.set = function(value, silent)
        selected = {}
        if type(value) == "table" then
            for k, v in pairs(value) do
                if v == true or v == 1 or v == "true" then
                    selected[tostring(k)] = true
                elseif type(k) == "number" and v ~= nil then
                    selected[tostring(v)] = true
                end
            end
        end
        if type(modeApi) == "table" and type(modeApi.setSelected) == "function" then
            pcall(modeApi.setSelected, copySelected(), silent == true)
        end
        api.apply()
        return copySelected()
    end

    local root = (type(modeApi) == "table" and (modeApi.root or modeApi.row)) or parent
    attachVisibility(api, root)
    api.row = root
    return root, api
end

function MainUI:_noteGuiActivity()
    self._lastGuiActivity = os.clock()
end

function MainUI:_guiHitAt(x, y)
    local sg = self._sg
    if not sg or not sg.Parent then
        return false
    end
    local ok, objs = pcall(function()
        return PlayerGui:GetGuiObjectsAtPosition(x, y)
    end)
    if not ok or type(objs) ~= "table" then
        return false
    end
    local mini = self._miniBtn
    for i = 1, #objs do
        local o = objs[i]
        if o and o:IsDescendantOf(sg) then
            if mini and (o == mini or o:IsDescendantOf(mini)) then
                -- icon minimize: restore sudah handle sendiri
            elseif o:IsA("GuiObject") and o.Visible ~= false then
                -- skip overlay full-screen (Active=false, bukan panel)
                if o.Name ~= "NodeHubOverlay" then
                    return true
                end
            end
        end
    end
    return false
end

function MainUI:_startIdleAutoMinimize()
    if self._idleMinimizeStarted == true then
        return
    end
    self._idleMinimizeStarted = true

    if self._idleInputConn then
        pcall(function()
            self._idleInputConn:Disconnect()
        end)
        self._idleInputConn = nil
    end

    self._idleInputConn = UserInputService.InputBegan:Connect(function(input)
        if self.isMinimized == true or self._autoMinimizeEnabled == false then
            return
        end
        local uit = input.UserInputType
        if uit == Enum.UserInputType.MouseButton1
            or uit == Enum.UserInputType.MouseButton2
            or uit == Enum.UserInputType.Touch then
            local p = input.Position
            if self:_guiHitAt(p.X, p.Y) then
                self:_noteGuiActivity()
            end
            return
        end
        if uit == Enum.UserInputType.Keyboard then
            local focused = UserInputService:GetFocusedTextBox()
            if focused and self.mainFrame and focused:IsDescendantOf(self.mainFrame) then
                self:_noteGuiActivity()
            end
        end
    end)

    task.spawn(function()
        while self._sg and self._sg.Parent do
            task.wait(1)
            if self._autoMinimizeEnabled ~= false
                and self.isMinimized ~= true then
                local idleSec = tonumber(self._autoMinimizeIdleSec) or 30
                if idleSec < 5 then
                    idleSec = 5
                end
                local last = tonumber(self._lastGuiActivity) or 0
                if (os.clock() - last) >= idleSec then
                    self:_setMinimized(true)
                end
            end
        end
        self._idleMinimizeStarted = false
        if self._idleInputConn then
            pcall(function()
                self._idleInputConn:Disconnect()
            end)
            self._idleInputConn = nil
        end
    end)
end

function MainUI:_setMinimized(state)
    state = state and true or false
    self.isMinimized = state

    if state then
        -- MINIMIZE: tutup panel utama, buka icon
        if self.overlay then
            self.overlay.Visible = false
        end
        if self.mainFrame then
            self.mainFrame.Visible = false
        end
        if self._miniBtn then
            self._miniBtn.Visible = true
        end
    else
        -- RESTORE: buka panel utama, tutup icon
        self:_noteGuiActivity()
        if self.overlay then
            self.overlay.Visible = true
            self.overlay.BackgroundTransparency = tonumber(self._overlayTransparency) or DEFAULT_OVERLAY_BG_TRANSPARENCY
        end
        if self.mainFrame then
            self.mainFrame.Visible = true
            self.mainFrame.BackgroundTransparency = tonumber(self._panelTransparency) or DEFAULT_PANEL_BG_TRANSPARENCY
        end
        if self._miniBtn then
            self._miniBtn.Visible = false
        end
        -- refresh scale supaya teks tidak buram setelah restore
        if type(self._updateScale) == "function" then
            pcall(self._updateScale)
            task.defer(function()
                if type(self._updateScale) == "function" then
                    pcall(self._updateScale)
                end
            end)
        end
    end
end

function MainUI:Minimize()
    self:_setMinimized(true)
end

function MainUI:Restore()
    self:_setMinimized(false)
end

function MainUI:SetAutoMinimize(enabled, idleSec)
    self._autoMinimizeEnabled = enabled ~= false
    if idleSec ~= nil then
        local n = tonumber(idleSec)
        if n and n >= 5 then
            self._autoMinimizeIdleSec = n
        end
    end
    if self._autoMinimizeEnabled then
        self:_noteGuiActivity()
        self:_startIdleAutoMinimize()
    end
end

function MainUI:GetTransparency()
    return {
        panel = tonumber(self._panelTransparency) or DEFAULT_PANEL_BG_TRANSPARENCY,
        overlay = tonumber(self._overlayTransparency) or DEFAULT_OVERLAY_BG_TRANSPARENCY,
        section = tonumber(self._sectionTransparency) or DEFAULT_SECTION_BG_TRANSPARENCY,
    }
end

function MainUI:ApplyTransparency(opts)
    opts = type(opts) == "table" and opts or {}
    if opts.panel ~= nil then
        local panel = _clamp01(opts.panel, DEFAULT_PANEL_BG_TRANSPARENCY)
        self._panelTransparency = panel
        -- section selalu ikut panel
        self._sectionTransparency = panel
    elseif opts.section ~= nil then
        local panel = _clamp01(opts.section, DEFAULT_PANEL_BG_TRANSPARENCY)
        self._panelTransparency = panel
        self._sectionTransparency = panel
    end
    -- backdrop fixed full clear
    self._overlayTransparency = DEFAULT_OVERLAY_BG_TRANSPARENCY

    if self.mainFrame then
        self.mainFrame.BackgroundTransparency = self._panelTransparency
    end
    if self.overlay then
        self.overlay.BackgroundTransparency = self._overlayTransparency
    end

    -- update section header yang sudah terbuat
    local content = self.content
    if content then
        for _, ch in ipairs(content:GetDescendants()) do
            if ch:IsA("TextButton") and ch.Name == "Header" then
                ch.BackgroundTransparency = self._sectionTransparency
            end
        end
    end

    return self:GetTransparency()
end

function MainUI:SetTransparency(panelOrOpts, _overlay, _section)
    if type(panelOrOpts) == "table" then
        return self:ApplyTransparency(panelOrOpts)
    end
    return self:ApplyTransparency({
        panel = panelOrOpts,
    })
end

