local function wrapEggCmds(mod)
    if type(mod) ~= "table" then
        return mod
    end
    if type(mod.GetAreaEggSnapshot) == "function" or type(mod.RequestCarryAreaEgg) == "function" then
        return mod
    end
    if type(mod.ReadFieldEggs) ~= "function" then
        return mod
    end
    local wrap = {}
    setmetatable(wrap, { __index = mod })
    wrap.GetAreaEggSnapshot = mod.ReadFieldEggs
    wrap.RequestAreaEggSnapshot = function()
        if type(mod.SyncFieldEggs) == "function" then
            pcall(mod.SyncFieldEggs)
        end
        return mod.ReadFieldEggs()
    end
    wrap.RequestCarryAreaEgg = mod.CarryFieldEgg
    wrap.RequestNestTransfer = mod.CarryFieldEgg
    wrap.DropFieldEgg = mod.DropFieldEgg
    wrap.GetAreaEggRecord = mod.ReadFieldEgg
    wrap.RequestPlaceEgg = mod.PlantEgg
    wrap.RequestHatchEgg = mod.BeginHatch
    wrap.RequestCompleteHatchEgg = mod.FinishHatch
    wrap.RequestEquipTool = mod.WearEggTool
    wrap.RequestUnequipTool = mod.DoffEggTool
    wrap.GetOwnerRuntimeRecords = mod.ReadOwnerEggs
    wrap.RequestRuntimeSnapshot = mod.SyncOwnedEggs
    wrap.RequestLocalEggRecord = mod.FetchEggRecord
    wrap.AreaEggCarryStateChanged = mod.CarryChanged
    wrap.AreaEggClaimed = mod.FieldClaimed
    wrap.AreaEggUpdated = mod.FieldShifted
    wrap.AreaEggSnapshotUpdated = mod.FieldRefreshed
    wrap.AreaEggRemoved = mod.FieldGone
    return wrap
end

local function wrapPlotCmds(mod)
    if type(mod) ~= "table" then
        return mod
    end
    if type(mod.GetPlotData) == "function" then
        return mod
    end
    if type(mod.ResolvePlot) ~= "function" then
        return mod
    end
    local wrap = {}
    setmetatable(wrap, { __index = mod })
    wrap.GetPlotData = mod.ResolvePlot
    -- Dump PlotState.ContainsLocalPoint: PlotFolder:GetBoundingBox XZ.
    -- PlotFolder can be Folder (no GetBoundingBox) — use ToUpdate Model.
    wrap.ContainsLocalPoint = function(pos)
        if typeof(pos) ~= "Vector3" then
            return false
        end
        if type(mod.ContainsLocalPoint) == "function" then
            local ok, v = pcall(mod.ContainsLocalPoint, pos)
            if ok then
                return v == true
            end
        end
        local ok, data = pcall(mod.ResolvePlot)
        if not ok or type(data) ~= "table" then
            return false
        end
        local folder = data.PlotFolder
        local inst = folder
        if typeof(folder) == "Instance" and not folder:IsA("Model") then
            local tu = folder:FindFirstChild("ToUpdate")
            inst = (tu and tu:IsA("Model")) and tu or folder
        end
        if typeof(inst) ~= "Instance" then
            return false
        end
        local okBox, cf, size = pcall(function()
            return inst:GetBoundingBox()
        end)
        if not okBox or typeof(cf) ~= "CFrame" or typeof(size) ~= "Vector3" then
            return false
        end
        local localPos = cf:PointToObjectSpace(pos)
        local half = size * 0.5
        return math.abs(localPos.X) <= half.X and math.abs(localPos.Z) <= half.Z
    end
    wrap.IsWorldPositionWithinLocalPlotBounds = wrap.ContainsLocalPoint
    wrap.GetRespawnPointCFrame = mod.FindRespawnCFrame
    wrap.GetMySlot = mod.ResolveLocalSlot
    wrap.GetPlotsFolder = mod.ResolveFolder
    wrap.GetLocalYourBaseBillboard = mod.FindLocalBaseSign
    wrap.GetSlotOwner = mod.LookupOwner
    wrap.OnAnyPlotUpdated = mod.PlotChanged
    wrap.OnLocalPlotUpdated = mod.LocalPlotChanged
    return wrap
end

