local function wrapNetwork(remotes)
    if type(remotes) ~= "table" then
        return remotes
    end
    if type(remotes.Fire) == "function" then
        return remotes
    end
    local function resolve(name)
        name = tostring(name or "")
        if name == "Bat:Activate" then
            return remotes.BatSwing and remotes.BatSwing.Trigger
        end
        if name == "Eggs: AreaEggCarryState" then
            return remotes.EggWorld and remotes.EggWorld.FieldEggCarry
        end
        if name == "Eggs: AreaEggClaimFeedback" then
            return remotes.EggWorld and remotes.EggWorld.FieldEggRedeemVerdict
        end
        if name == "AssetInventory: SellAsset" then
            return remotes.PetSatchel and remotes.PetSatchel.SellPet
        end
        if name == "AssetInventory: SellAllAssets" then
            return remotes.PetSatchel and remotes.PetSatchel.SellEveryPet
        end
        if name == "AssetInventory: SetFavorite" then
            return remotes.PetSatchel and remotes.PetSatchel.WriteFavourite
        end
        if name == "Backpack: GetAutoSellState" then
            return remotes.Haul and remotes.Haul.FetchAutoSell
        end
        if name == "Backpack: SetAutoSellState" then
            return remotes.Haul and remotes.Haul.WriteAutoSell
        end
        if name == "Backpack: EquipBest" or name == "Backpack: WearBest" then
            return remotes.Haul and remotes.Haul.WearBest
        end
        if name == "Backpack: GetEquipBestStatus" or name == "Backpack: FetchWearBestStatus" then
            return remotes.Haul and remotes.Haul.FetchWearBestStatus
        end
        if name == "FuseMachine: InsertMob" then
            return remotes.Fusery and remotes.Fusery.LoadPet
        end
        if name == "FuseMachine: RemoveMob" then
            return remotes.Fusery and remotes.Fusery.EjectPet
        end
        if name == "FuseMachine: StartFuse" then
            return remotes.Fusery and remotes.Fusery.BeginFuse
        end
        if name == "FuseMachine: CompleteReveal" then
            return remotes.Fusery and remotes.Fusery.FinishReveal
        end
        if name == "FuseMachine: AcknowledgeInfo" then
            return remotes.Fusery and remotes.Fusery.ConfirmBriefing
        end
        if name == "Trails: RequestPurchase" then
            return remotes.Trailwear and remotes.Trailwear.AskPurchase
        end
        if name == "Trails: RequestSelect" or name == "Trails: RequestEquip" then
            return remotes.Trailwear and remotes.Trailwear.AskChoose
        end
        if name == "Trails: RequestUnequip" then
            return remotes.Trailwear and remotes.Trailwear.AskDoff
        end
        if name == "Index: RequestClaimAll" then
            return remotes.Codex and remotes.Codex.AskRedeemAll
        end
        if name == "Index: RequestClaimLimitedEggReward" then
            return remotes.Codex and remotes.Codex.AskRedeemLimitedEgg
        end
        if name == "Index: RequestClaim" then
            return remotes.Codex and remotes.Codex.AskRedeem
        end
        return nil
    end
    local wrap = {}
    setmetatable(wrap, { __index = remotes })
    wrap.Fire = function(name, ...)
        local inst = resolve(name)
        if inst and type(inst.FireServer) == "function" then
            inst:FireServer(...)
            return true
        end
        return false
    end
    wrap.Invoke = function(name, ...)
        local inst = resolve(name)
        if inst and type(inst.InvokeServer) == "function" then
            return inst:InvokeServer(...)
        end
        return nil
    end
    wrap.Fired = function(name)
        local inst = resolve(name)
        if inst and inst.OnClientEvent then
            return inst.OnClientEvent
        end
        return {
            Connect = function()
                return {
                    Disconnect = function()
                    end,
                }
            end,
        }
    end
    return wrap
end

local function wrapGetPrice(mod)
    if type(mod) == "function" then
        return mod
    end
    if type(mod) ~= "table" then
        return mod
    end
    local eggRec
    return function(item)
        if type(item) ~= "table" then
            return 0
        end
        if item.AssetCategory ~= nil then
            eggRec = eggRec or M.require("Library.Util.EggItemUtil")
            if type(eggRec) == "table" and type(eggRec.SellPrice) == "function" then
                local ok, n = pcall(eggRec.SellPrice, item)
                if ok then
                    return tonumber(n) or 0
                end
            end
        end
        local fn = mod.SalePrice or mod.GetPriceValueForItem
        if type(fn) == "function" then
            local ok, n = pcall(fn, item)
            if ok then
                return tonumber(n) or 0
            end
        end
        return 0
    end
end

-- Live Shared.Save: Peek / Await / IsLoaded. Dump lama: Get / Cache / ProfileReady.
local function wrapSave(mod)
    if type(mod) ~= "table" then
        return mod
    end
    if type(mod.Get) == "function" then
        return mod
    end
    if type(mod.Peek) ~= "function" and type(mod.Await) ~= "function" then
        return mod
    end
    local wrap = {}
    setmetatable(wrap, { __index = mod })
    wrap.Get = function(player, wait)
        if type(mod.Peek) == "function" then
            local ok, data = pcall(mod.Peek, player)
            if not ok or type(data) ~= "table" then
                ok, data = pcall(mod.Peek)
            end
            if ok and type(data) == "table" then
                return data
            end
        end
        if wait ~= false and type(mod.Await) == "function" then
            local ok, data = pcall(mod.Await, player)
            if not ok or type(data) ~= "table" then
                ok, data = pcall(mod.Await)
            end
            if ok and type(data) == "table" then
                return data
            end
        end
        return nil
    end
    wrap.Cache = function()
        local LP = Players.LocalPlayer
        local bag = {}
        local data
        if type(mod.Peek) == "function" then
            local ok, rec = pcall(mod.Peek, LP)
            if ok and type(rec) == "table" then
                data = rec
            else
                ok, rec = pcall(mod.Peek)
                if ok and type(rec) == "table" then
                    data = rec
                end
            end
        end
        if type(data) == "table" and LP ~= nil then
            bag[LP] = data
        end
        return bag
    end
    wrap.ProfileReady = mod.Loaded
    return wrap
end

local function wrapRequired(rel, mod)
    if rel == "Library.Client.EggCmds" then
        return wrapEggCmds(mod)
    end
    if rel == "Library.Client.PlotCmds" then
        return wrapPlotCmds(mod)
    end
    if rel == "Library.Util.EggItemUtil" then
        return wrapEggItemUtil(mod)
    end
    if rel == "Library.Util.GetPriceValueForItem" then
        return wrapGetPrice(mod)
    end
    if rel == "Library.Util.AssetItemUtil" or rel == "Library.Util.AssetItemSerialization" then
        return wrapAssetItems(mod)
    end
    if rel == "Library.Util.AssetGenerationUtil" then
        return wrapAssetEarnings(mod)
    end
    if rel == "Library.Modules.Mutations" then
        return wrapMutations(mod)
    end
    if rel == "Library.Util.GuardAreaLookupUtil" then
        return wrapGuardArea(mod)
    end
    if rel == "Library.Util.AreaEggSlotIdentity" then
        return wrapSlotIdentity(mod)
    end
    if rel == "Library.Client.Network" then
        return wrapNetwork(mod)
    end
    if rel == "Library.Client.Save" then
        return wrapSave(mod)
    end
    return mod
end

local function walkPath(path, waitSec)
    local roots = { ReplicatedStorage }
    if typeof(cloneref) == "function" then
        local cloned
        pcall(function()
            cloned = cloneref(ReplicatedStorage)
        end)
        if cloned ~= nil and cloned ~= ReplicatedStorage then
            roots[#roots + 1] = cloned
        end
    end
    local lastErr
    for _, root in ipairs(roots) do
        local cur = root
        local miss = false
        for part in string.gmatch(path, "[^%.]+") do
            local nxt = cur:FindFirstChild(part)
            if not nxt and waitSec > 0 then
                nxt = cur:WaitForChild(part, waitSec)
            end
            if not nxt then
                lastErr = "missing " .. part
                miss = true
                break
            end
            cur = nxt
        end
        if not miss then
            return cur
        end
        waitSec = 0
    end
    return nil, lastErr
end

local function findLoaded(name)
    if typeof(getloadedmodules) ~= "function" then
        return nil
    end
    local ok, list = pcall(getloadedmodules)
    if not (ok and type(list) == "table") then
        return nil
    end
    for _, inst in ipairs(list) do
        if typeof(inst) == "Instance" and inst.Name == name then
            return inst
        end
    end
    return nil
end

local function findNil(name)
    if typeof(getnilinstances) ~= "function" then
        return nil
    end
    local ok, list = pcall(getnilinstances)
    if not (ok and type(list) == "table") then
        return nil
    end
    for _, inst in ipairs(list) do
        if typeof(inst) == "Instance" and inst.Name == name and inst:IsA("ModuleScript") then
            return inst
        end
    end
    return nil
end

function M.require(rel, waitSec)
    rel = tostring(rel or "")
    waitSec = tonumber(waitSec) or 0
    local cached = reqCache[rel]
    if cached ~= nil then
        return cached
    end
    local paths = PATH_ALIASES[rel] or { rel }
    local lastErr
    for i, path in ipairs(paths) do
        local waitHere = 0
        if waitSec > 0 and i == 1 then
            waitHere = math.min(waitSec, 4)
        end
        local inst, err = walkPath(path, waitHere)
        if inst then
            local ok, mod = pcall(require, inst)
            if ok then
                mod = wrapRequired(rel, mod)
                reqCache[rel] = mod
                M.lastRequireErr = nil
                return mod
            end
            lastErr = tostring(mod)
        else
            lastErr = err or lastErr
        end
    end
    local names
    if rel == "Library.Client.EggCmds" then
        names = { "EggState" }
    elseif rel == "Library.Client.PlotCmds" then
        names = { "PlotState" }
    elseif rel == "Library.Client.Network" then
        names = { "Remotes" }
    elseif rel == "Library.Util.AssetGenerationUtil" then
        names = { "AssetEarnings", "AssetGenerationUtil" }
    elseif rel == "Library.Util.EggItemUtil" then
        names = { "EggRecords", "EggItemUtil" }
    end
    if names then
        for _, name in ipairs(names) do
            local inst = findLoaded(name) or findNil(name)
            if inst then
                local ok, mod = pcall(require, inst)
                if ok then
                    mod = wrapRequired(rel, mod)
                    reqCache[rel] = mod
                    M.lastRequireErr = nil
                    return mod
                end
                lastErr = tostring(mod)
            end
        end
    end
    M.lastRequireErr = lastErr or "not found"
    return nil
end

-- Profile player: jangan Cache[LP] polos. Di HP cloneref LP ≠ key asli → Egg/Pet 0.
-- Jangan anggap {} siap: Get() sebelum ProfileReady = tas kosong palsu (kadang 0).
local saveWaitJob = nil
local saveWaitOn = false

local function mapCount(t)
    if type(t) ~= "table" then
        return 0
    end
    local n = 0
    pcall(function()
        for _ in pairs(t) do
            n += 1
        end
    end)
    return n
end

local function saveScore(data)
    if type(data) ~= "table" then
        return -1
    end
    return mapCount(data.EggInventory) + mapCount(data.Inventory) + mapCount(data.EquippedAssets)
end

function M.playerSave(opts)
    local Save = M.require("Library.Client.Save")
    if type(Save) ~= "table" then
        return nil
    end
    local allowWait = type(opts) == "table" and opts.wait == true
    local LP = Players.LocalPlayer
    local uid = 0
    pcall(function()
        uid = tonumber(LP and LP.UserId) or 0
    end)

    local function fromCache()
        if type(Save.Cache) ~= "function" then
            return nil
        end
        local okC, bag = pcall(Save.Cache)
        if not (okC and type(bag) == "table") then
            return nil
        end
        local best, bestN = nil, -1
        local function consider(rec)
            local n = saveScore(rec)
            if n > bestN then
                best = rec
                bestN = n
            end
        end
        if LP ~= nil then
            consider(bag[LP])
        end
        for plr, rec in pairs(bag) do
            if type(rec) == "table" then
                local id = 0
                pcall(function()
                    id = tonumber(plr.UserId) or 0
                end)
                if uid ~= 0 and id == uid then
                    consider(rec)
                end
            end
        end
        return best, bestN
    end

    local function readNow()
        local best, bestN = nil, -1
        local function consider(data)
            local n = saveScore(data)
            if n > bestN then
                best = data
                bestN = n
            end
        end
        if type(Save.Peek) == "function" then
            local ok, data = pcall(Save.Peek)
            if ok then
                consider(data)
            end
            if LP ~= nil then
                ok, data = pcall(Save.Peek, LP)
                if ok then
                    consider(data)
                end
            end
        end
        if type(Save.Await) == "function" and bestN < 1 then
            local ok, data = pcall(Save.Await, LP)
            if ok then
                consider(data)
            end
        end
        local cached, cachedN = fromCache()
        if (cachedN or -1) > bestN then
            best, bestN = cached, cachedN
        end
        if type(Save.Get) == "function" then
            local ok, data = pcall(Save.Get)
            if ok then
                local n = saveScore(data)
                if n > bestN then
                    best, bestN = data, n
                end
            end
            if LP ~= nil and bestN < 1 then
                ok, data = pcall(Save.Get, LP, true)
                if ok and saveScore(data) > bestN then
                    best, bestN = data, saveScore(data)
                end
            end
        end
        return best, bestN
    end

    local data, score = readNow()
    if score < 1 and allowWait then
        local job = tostring(game.JobId or "")
        if saveWaitJob ~= job then
            if saveWaitOn then
                local tSpin = os.clock()
                while saveWaitOn and os.clock() - tSpin < 3 do
                    task.wait(0.08)
                end
                data, score = readNow()
            else
                saveWaitOn = true
                local done = false
                local conn
                pcall(function()
                    local sig = Save.ProfileReady
                    if type(sig) == "table" and type(sig.Connect) == "function" then
                        conn = sig:Connect(function()
                            done = true
                        end)
                    end
                end)
                local t0 = os.clock()
                while os.clock() - t0 < 2.6 do
                    if done then
                        break
                    end
                    data, score = readNow()
                    if score > 0 then
                        break
                    end
                    task.wait(0.12)
                end
                if conn then
                    pcall(function()
                        conn:Disconnect()
                    end)
                end
                saveWaitJob = job
                saveWaitOn = false
                if score < 1 then
                    data, score = readNow()
                end
            end
        end
    end
    return data
end

function M.directoryOf(mod)
    if type(mod) ~= "table" then
        return nil
    end
    if type(mod.Directory) == "table" then
        return mod.Directory
    end
    return mod
end

function M.sameId(a, b)
    a = tostring(a or "")
    b = tostring(b or "")
    if a == "" or b == "" then
        return false
    end
    return a == b or string.lower(a) == string.lower(b)
end

-- CherryBlossom == "Cherry Blossom". Snapshot AreaId vs Directory key sering beda spasi.
function M.areaToken(s)
    s = string.lower(tostring(s or ""))
    s = s:gsub("[%s%p_]+", "")
    return s
end

function M.sameArea(a, b)
    if M.sameId(a, b) then
        return true
    end
    local ta = M.areaToken(a)
    local tb = M.areaToken(b)
    return ta ~= "" and ta == tb
end

function M.dropdownValue(a, b)
    if a == "single" or a == "multi" then
        return b
    end
    if b ~= nil then
        return b
    end
    return a
end

function M.flagOn(v)
    if v == true or v == 1 then
        return true
    end
    if type(v) == "string" then
        local s = string.lower((tostring(v):gsub("^%s+", ""):gsub("%s+$", "")))
        return s == "true" or s == "1" or s == "on" or s == "yes"
    end
    return false
end

function M.canonicalMutation(raw)
    raw = tostring(raw or "")
    if raw == "" then
        return raw
    end
    M._mutCanon = M._mutCanon or {}
    local cached = M._mutCanon[raw]
    if cached then
        return cached
    end
    local low = string.lower((raw:gsub("^%s+", ""):gsub("%s+$", "")))
    if low == "none" or low == "normal" or low == "no mutation" or low == "nomutation" then
        M._mutCanon[raw] = "None"
        return "None"
    end
    local id = raw
    local mod = M.require("Library.Modules.Mutations")
    if type(mod) == "table" then
        if type(mod.IsKnown) == "function" then
            local ok, known = pcall(mod.IsKnown, raw)
            if ok and known == true then
                M._mutCanon[raw] = raw
                return raw
            end
        end
        local allFn = mod.All or mod.GetMutations
        if type(allFn) == "function" then
            local ok, cat = pcall(allFn)
            if ok and type(cat) == "table" then
                if type(cat[raw]) == "table" then
                    id = tostring(cat[raw].Id or cat[raw].Name or raw)
                    M._mutCanon[raw] = id
                    return id
                end
                for key, spec in pairs(cat) do
                    if type(spec) == "table" then
                        local sid = tostring(spec.Id or spec.Name or key)
                        local label = tostring(spec.Label or spec.DisplayOverride or "")
                        if sid == raw or string.lower(sid) == low then
                            id = sid
                            break
                        end
                        if label ~= "" and (label == raw or string.lower(label) == low) then
                            id = sid
                            break
                        end
                    elseif type(key) == "string" and string.lower(key) == low then
                        id = key
                        break
                    end
                end
            end
        end
    end
    if id == raw then
        if low == "bloom" or low == "sakura" then
            id = "Sakura"
        elseif low == "spirit bloom" or low == "spiritbloom" or low == "greatbloom" or low == "great bloom" then
            id = "GreatBloom"
        end
    end
    M._mutCanon[raw] = id
    return id
end

function M.mutationLabel(raw)
    local id = M.canonicalMutation(raw)
    if id == "" or id == "None" then
        return "Normal"
    end
    local mod = M.require("Library.Modules.Mutations")
    if type(mod) == "table" then
        local fn = mod.LabelOf or mod.GetDisplayName
        if type(fn) == "function" then
            local ok, label = pcall(fn, id)
            if ok and type(label) == "string" and label ~= "" then
                return label
            end
        end
        local allFn = mod.All or mod.GetMutations
        if type(allFn) == "function" then
            local ok, cat = pcall(allFn)
            local spec = ok and type(cat) == "table" and (cat[id] or cat[raw])
            if type(spec) == "table" then
                local label = spec.Label or spec.DisplayOverride
                if type(label) == "string" and label ~= "" then
                    return label
                end
            end
        end
    end
    if id == "Sakura" then
        return "Bloom"
    end
    if id == "GreatBloom" then
        return "Spirit Bloom"
    end
    return tostring(raw ~= "" and raw or id)
end

function M.sameMutation(a, b)
    return M.canonicalMutation(a) == M.canonicalMutation(b)
end

function M.mutationPicked(name, selected)
    if type(selected) ~= "table" then
        return false
    end
    name = tostring(name or "")
    if selected[name] == true or selected[string.lower(name)] == true then
        return true
    end
    local id = M.canonicalMutation(name)
    if id ~= "" and selected[id] == true then
        return true
    end
    for key, on in pairs(selected) do
        if on == true and M.sameMutation(name, key) then
            return true
        end
    end
    return false
end

function M.parseKeyMap(value)
    local nextMap = {}
    if type(value) ~= "table" then
        if type(value) == "string" and value ~= "" and value ~= "single" and value ~= "multi" then
            nextMap[value] = true
        end
        return nextMap
    end
    if #value > 0 then
        for _, key in ipairs(value) do
            nextMap[tostring(key)] = true
        end
        return nextMap
    end
    for key, on in pairs(value) do
        if on == true or on == 1 or on == "true" then
            nextMap[tostring(key)] = true
        elseif type(key) == "number" and on ~= nil and on ~= false then
            nextMap[tostring(on)] = true
        end
    end
    return nextMap
end

function M.eggCall(name, ...)
    local EggCmds = M.require("Library.Client.EggCmds", 2)
    if type(EggCmds) ~= "table" then
        return false, "EggCmds missing" .. (M.lastRequireErr and (" · " .. M.lastRequireErr) or "")
    end
    local fn = EggCmds[name]
    if type(fn) ~= "function" and name == "RequestCarryAreaEgg" then
        fn = EggCmds.CarryFieldEgg or EggCmds.RequestNestTransfer
    end
    if type(fn) ~= "function" then
        return false, "EggCmds." .. tostring(name) .. " missing"
    end
    local ok, a, b, c = pcall(fn, ...)
    if not ok then
        return false, tostring(a)
    end
    return true, a, b, c
end

function M.objectsAreas()
    local function from(root)
        return root and root:FindFirstChild("Areas")
    end
    -- Live: World.Areas. __OBJECTS sudah tidak ada → GuardAreas nil → avoid guard mati.
    return from(Workspace:FindFirstChild("World"))
        or from(Workspace:FindFirstChild("__OBJECTS"))
end

function M.guardAreasFolder()
    local areas = M.objectsAreas()
    return areas and areas:FindFirstChild("GuardAreas")
end

function M.separationLine()
    local areas = M.objectsAreas()
    local line = areas and areas:FindFirstChild("SeparationLine")
    if line and line:IsA("BasePart") then
        return line
    end
    return nil
