function M.startArea()
    local function from(root)
        local areas = root and root:FindFirstChild("Areas")
        if not areas then
            return nil
        end
        return areas:FindFirstChild("StartArea") or areas:FindFirstChild("StartArea", true)
    end
    return from(Workspace:FindFirstChild("World"))
        or from(Workspace:FindFirstChild("__OBJECTS"))
end

-- First load: World.Areas.StartArea (live) atau __OBJECTS (lama).
function M.waitStartArea(timeout)
    timeout = tonumber(timeout) or 8
    if timeout < 0 then
        timeout = 0
    end
    local have = M.startArea()
    if have then
        return have
    end
    local deadline = os.clock() + timeout
    local function remain()
        return math.max(0.05, deadline - os.clock())
    end
    local world = Workspace:FindFirstChild("World")
    if not world and timeout > 0 then
        world = Workspace:WaitForChild("World", remain())
    end
    local areas = world and world:FindFirstChild("Areas")
    if world and not areas and os.clock() < deadline then
        areas = world:WaitForChild("Areas", remain())
    end
    local inst = areas and (areas:FindFirstChild("StartArea") or areas:FindFirstChild("StartArea", true))
    if inst then
        return inst
    end
    local objects = Workspace:FindFirstChild("__OBJECTS")
    if not objects and os.clock() < deadline then
        objects = Workspace:WaitForChild("__OBJECTS", remain())
    end
    if not objects then
        return M.startArea()
    end
    areas = objects:FindFirstChild("Areas")
    if not areas and os.clock() < deadline then
        areas = objects:WaitForChild("Areas", remain())
    end
    if not areas then
        return M.startArea()
    end
    inst = areas:FindFirstChild("StartArea") or areas:FindFirstChild("StartArea", true)
    if inst then
        return inst
    end
    if os.clock() < deadline then
        inst = areas:WaitForChild("StartArea", remain())
    end
    return inst or M.startArea()
end

local function eggDisplayName(category, config)
    if type(config) == "table" then
        local name = config.DisplayName or config.Name or config._id
        if type(name) == "string" and name ~= "" then
            return name
        end
    end
    return tostring(category)
end

local function rarityLabel(config)
    if type(config) ~= "table" or type(config.Rarity) ~= "table" then
        return ""
    end
    local r = config.Rarity
    return tostring(r._id or r.DisplayName or r.Name or "")
end

local function eachDrop(dropTable, fn)
    if type(dropTable) ~= "table" then
        return
    end
    for _, drop in pairs(dropTable) do
        if type(drop) == "table" then
            local category = drop[1] or drop.Category
            local weight = tonumber(drop[2] or drop.Weight) or 0
            fn(category, weight)
        end
    end
end

function M.buildCatalog()
    local areaDir = M.directoryOf(M.require("Directory.Areas"))
    local assetDir = M.directoryOf(M.require("Directory.Assets"))
    if type(assetDir) ~= "table" then
        assetDir = {}
    end

    local areas = {}
    local eggs = {}
    local byArea = {}
    local byKey = {}

    if type(areaDir) == "table" then
        for areaId, area in pairs(areaDir) do
            if type(area) == "table" and type(area.DropTable) == "table" then
                local areaName = tostring(area.DisplayName or areaId)
                local sortOrder = AREA_ORDER[tostring(areaId)] or 50
                if type(area.Rarity) == "table" then
                    sortOrder = tonumber(area.Rarity.RarityNumber) or sortOrder
                end
                local entries = {}
                eachDrop(area.DropTable, function(category, weight)
                    if category == nil or weight <= 0 then
                        return
                    end
                    local config = assetDir[category]
                    if type(config) == "table" and config.DontRoll == true then
                        return
                    end
                    local rarityNum = 0
                    if type(config) == "table" and type(config.Rarity) == "table" then
                        rarityNum = tonumber(config.Rarity.RarityNumber) or 0
                    end
                    local item = {
                        key = tostring(category),
                        name = eggDisplayName(category, config),
                        rarity = rarityLabel(config),
                        rarityNumber = rarityNum,
                        dropWeight = (type(config) == "table" and tonumber(config.DropWeight)) or weight,
                        areaId = tostring(areaId),
                        areaName = areaName,
                    }
                    entries[#entries + 1] = item
                    eggs[#eggs + 1] = item
                    byKey[item.key] = item
                end)
                table.sort(entries, function(a, b)
                    if a.rarityNumber ~= b.rarityNumber then
                        return a.rarityNumber < b.rarityNumber
                    end
                    if a.dropWeight == b.dropWeight then
                        return a.key < b.key
                    end
                    return a.dropWeight > b.dropWeight
                end)
                if #entries > 0 then
                    local id = tostring(areaId)
                    areas[#areas + 1] = {
                        key = id,
                        name = areaName,
                        sortOrder = sortOrder,
                    }
                    byArea[id] = entries
                    byArea[string.lower(id)] = entries
                    byArea[string.lower(areaName)] = entries
                    local tok = M.areaToken(id)
                    if tok ~= "" then
                        byArea[tok] = entries
                    end
                end
            end
        end
    end

    local folder = M.guardAreasFolder()
    if folder then
        for _, child in ipairs(folder:GetChildren()) do
            if child:IsA("Model") then
                local already = byArea[child.Name] ~= nil
                if not already then
                    for _, area in ipairs(areas) do
                        if M.sameArea(area.key, child.Name) or M.sameArea(area.name, child.Name) then
                            already = true
                            byArea[child.Name] = byArea[area.key] or {}
                            break
                        end
                    end
                end
                if not already then
                    areas[#areas + 1] = {
                        key = child.Name,
                        name = child.Name,
                        sortOrder = AREA_ORDER[child.Name] or 80,
                    }
                    byArea[child.Name] = byArea[child.Name] or {}
                end
            end
        end
    end

    table.sort(areas, function(a, b)
        if a.sortOrder == b.sortOrder then
            return a.name < b.name
        end
        return a.sortOrder < b.sortOrder
    end)

    M._catalog = {
        areas = areas,
        eggs = eggs,
        byArea = byArea,
        byKey = byKey,
        ok = #areas > 0,
    }
    return M._catalog
end

function M.getCatalog()
    if type(M._catalog) ~= "table" or M._catalog.ok ~= true then
        M.buildCatalog()
    end
    return M._catalog
end

function M.resolveAreaKey(tier)
    local cat = M.getCatalog()
    tier = tostring(tier or "")
    if tier == "" or tier == "single" or tier == "multi" then
        return nil
    end
    if type(cat) == "table" and type(cat.areas) == "table" then
        for _, area in ipairs(cat.areas) do
            if M.sameArea(area.key, tier) or M.sameArea(area.name, tier) then
                return area.key
            end
        end
    end
    return tier
end

function M.listAreaItems()
    local cat = M.getCatalog()
    local items = {}
    if type(cat) == "table" and type(cat.areas) == "table" then
        for _, area in ipairs(cat.areas) do
            items[#items + 1] = { key = area.key, name = area.name }
        end
    end
    return items
end

function M.listEggItems(selectedAreas)
    local cat = M.getCatalog()
    local items = {}
    if type(cat) ~= "table" or type(cat.byArea) ~= "table" then
        return items
    end
    local sources = {}
    local filter = type(selectedAreas) == "table" and selectedAreas or nil
    if filter == nil or next(filter) == nil then
        if type(cat.areas) == "table" then
            for _, area in ipairs(cat.areas) do
                sources[#sources + 1] = cat.byArea[area.key]
            end
        end
    else
        for areaId in pairs(filter) do
            local key = M.resolveAreaKey(areaId) or areaId
            sources[#sources + 1] = cat.byArea[key] or cat.byArea[tostring(areaId)]
        end
    end
    local seen = {}
    for _, source in ipairs(sources) do
        if type(source) == "table" then
            for _, egg in ipairs(source) do
                if not seen[egg.key] then
                    seen[egg.key] = true
                    local label = egg.name
                    if egg.rarity ~= "" then
                        label = egg.name .. " · " .. egg.rarity
                    end
                    items[#items + 1] = { key = egg.key, name = label }
                end
            end
        end
    end
    return items
end

function M.assetConfig(category)
    if category == nil then
        return nil
    end
    local dir = M.directoryOf(M.require("Directory.Assets"))
    if type(dir) ~= "table" then
        return nil
    end
    local ok, cfg = pcall(function()
        return dir[category] or dir[tostring(category)]
    end)
    if ok and type(cfg) == "table" then
        return cfg
    end
    return nil
end

function M.eggRarityNumber(category)
    if category == nil then
        return 0
    end
    local cfg = M.assetConfig(category)
    if type(cfg) == "table" and type(cfg.Rarity) == "table" then
        return tonumber(cfg.Rarity.RarityNumber) or 0
    end
    local cat = M.getCatalog()
    local byKey = cat and cat.byKey
    local item = type(byKey) == "table" and byKey[tostring(category)]
    if type(item) == "table" then
        return tonumber(item.rarityNumber) or 0
    end
    return 0
end

G.StealEggCore = M
return M
 end,          required = true },
    { key = "Speed",     name = "Speed",         factory = function() -- StealEgg speed — quiet VerticalTrajectory + HardHorizontalTeleport.
-- Jangan wrap FireServer / namecall / __newindex (BAC / rusak VT).
-- Cari HHT/VT: filtergc constant (Playback / ArcModel / AxisDelta). getgc cuma cadangan.
-- Ganti file ini dengan output Luraph, atau simpan sebagai speed_luraph.lua (stitch vilih itu dulu).

local G = (getgenv and getgenv()) or _G
local M = {}
G.StealEggSpeed = M
G.__StealEggVtQuiet = nil
G.__StealEggHhtQuiet = nil
-- Idle: hook Playback sekali per JobId, orig native.
-- Mute HHT HANYA di jendela CFrame FAR (SnapUntil) — Last=Now + skip orig.
-- Mute se-sesi FarOn + getgc tiap steal = hop 60s + spike CPU.
G.__StealEggHhtOff = true
-- Deteksi BAC: Playback ON, hook ekstra OFF (WCall/warn, mouse, idle FireServer).
-- FPS lite auto ON. Teleport AFK block ON.
G.__StealEggSkipExtraHooks = true
G.__StealEggHhtPulse = 1
G.__StealEggHhtLastPulse = 0
G.__StealEggHhtJob = nil
G.__StealEggVtArmBusy = nil
G.__StealEggVtWatchOn = nil
G.__StealEggVtLastScan = nil
G.__StealEggVtWaitWarn = nil
G.__StealEggVtScanFails = nil
G.__StealEggRelocateMute = nil
G.__StealEggTpDest = nil
G.__StealEggTpApplying = nil

-- Status terakhir buat Move.ArmIntegrity / dump.
M._last = {
    vt = 0,
    hht = 0,
    hf = "nil",
    getgc = "nil",
    clone = "nil",
    err = nil,
    at = 0,
}

-- Buffer kalau StealEggDbg belum hidup (Speed load sebelum Move).
local pend = {}
function M.FlushLog()
    local fn = G.StealEggDbg
    if type(fn) ~= "function" then
        return false
    end
    for i = 1, #pend do
        pcall(fn, "VT-QUIET", pend[i])
    end
    table.clear(pend)
    return true
end

local function flushPend()
    M.FlushLog()
end

local function log(msg)
    if G.__StealEggMoveDebug ~= true then
        return
    end
    msg = tostring(msg or "")
    local fn = G.StealEggDbg
    if type(fn) == "function" then
        flushPend()
        pcall(fn, "VT-QUIET", msg)
    else
        pend[#pend + 1] = msg
        if #pend > 80 then
            table.remove(pend, 1)
        end
    end
end

-- getgc menyapu seluruh heap: sekali panggil = spike. Kalau scan berturut-turut
-- tidak menemukan hook apa pun, jaraknya dinaikkan supaya tidak spike tiap 2.5s
-- selamanya di executor yang memang tidak punya fungsi targetnya.
local SCAN_GAP = { 2.5, 5, 15, 60 }

local function scanGap()
    if G.__StealEggVtQuiet ~= true or G.__StealEggWanted == true then
        return 1.2
    end
    local fails = tonumber(G.__StealEggVtScanFails) or 0
    return SCAN_GAP[math.min(fails + 1, #SCAN_GAP)]
end

local function scanMark(progress)
    if progress == true then
        G.__StealEggVtScanFails = 0
    else
        G.__StealEggVtScanFails = (tonumber(G.__StealEggVtScanFails) or 0) + 1
    end
end

local function hf()
    return hookfunction or hookfunc or replaceclosure
end

local function envSnap()
    local h = hf()
    M._last.hf = type(h)
    M._last.getgc = typeof(getgc)
    local cl = type(clonefunction)
    if cl == "nil" then
        cl = type(clonefunc)
    end
    M._last.clone = cl
    return M._last.hf, M._last.getgc, M._last.clone
end

local function wrap(f)
    if type(newcclosure) == "function" then
        return newcclosure(f)
    end
    return f
end

local function isVt(t)
    if type(t) ~= "table" then
        return false
    end
    local a, b, c
    pcall(function()
        a = rawget(t, "Step")
        b = rawget(t, "RecordCorrection")
        c = rawget(t, "Suspend") or rawget(t, "Reset")
    end)
    return type(a) == "function" and type(b) == "function" and type(c) == "function"
end

local function isSeg(t)
    if type(t) ~= "table" then
        return false
    end
    local a, b
    pcall(function()
        a = rawget(t, "Evaluate")
        b = rawget(t, "RecordOwnedContext")
    end)
    return type(a) == "function" and type(b) == "function"
end

local function isBag(t)
    if type(t) ~= "table" then
        return false
    end
    local vt, vs
    pcall(function()
        vt = rawget(t, "VerticalTrajectory") or rawget(t, "ArcModel") or t.ArcModel
        vs = rawget(t, "VerticalSegment") or rawget(t, "AxisDelta") or t.AxisDelta
    end)
    return isVt(vt) or isSeg(vs)
end

local function hookStep(fn, owner)
    if type(fn) ~= "function" then
        return false
    end
    local stub = wrap(function()
        return { Reason = nil, PreferredTarget = nil }
    end)
    local h = hf()
    local ok = false
    if type(h) == "function" then
        ok = pcall(h, fn, stub)
    end
    if not ok and type(owner) == "table" then
        ok = pcall(rawset, owner, "Step", stub)
    end
    return ok == true
end

local function hookEval(fn, owner)
    if type(fn) ~= "function" then
        return false
    end
    local stub = wrap(function()
        return nil
    end)
    local h = hf()
    local ok = false
    if type(h) == "function" then
        ok = pcall(h, fn, stub)
    end
    if not ok and type(owner) == "table" then
        ok = pcall(rawset, owner, "Evaluate", stub)
    end
    return ok == true
end

local function hasC(fn, needle)
    if type(fn) ~= "function" or type(needle) ~= "string" then
        return false
    end
    if type(getconstants) == "function" then
        local ok, cs = pcall(getconstants, fn)
        if ok and type(cs) == "table" then
            for _, c in pairs(cs) do
                if c == needle then
                    return true
                end
            end
        end
    end
    -- Executor ini: tes live ketemu 7 HHT via debug.getconstant, getconstants sering kosong.
    if type(debug) == "table" and type(debug.getconstant) == "function" then
        for i = 1, 36 do
            local ok, c = pcall(debug.getconstant, fn, i)
            if not ok then
                break
            end
            if c == needle then
                return true
            end
        end
    end
    return false
end

local hookedHht = {}
-- Persist across script reload: supaya Refresh bisa ganti stub lama → hard-mute baru.
local persistHht = G.__StealEggHhtHooked
if type(persistHht) ~= "table" then
    persistHht = {}
    G.__StealEggHhtHooked = persistHht
end
local hhtOrigs = G.__StealEggHhtOrigs
if type(hhtOrigs) ~= "table" then
    hhtOrigs = {}
    G.__StealEggHhtOrigs = hhtOrigs
end

local function cloneFn(fn)
    if type(clonefunction) == "function" then
        local ok, c = pcall(clonefunction, fn)
        if ok and type(c) == "function" then
            return c
        end
    end
    if type(clonefunc) == "function" then
        local ok, c = pcall(clonefunc, fn)
        if ok and type(c) == "function" then
            return c
        end
    end
    return nil
end

-- Saat quiet: ganti LastObservedSample (jangan mutate table freeze),
-- velocity ikut RootPart. Jangan Last=Now selama glide pulang.
local function quietPlayback(state)
    if type(state) ~= "table" then
        return false
    end
    local root = rawget(state, "RootPart")
    if typeof(root) ~= "Instance" then
        root = nil
        pcall(function()
            local char = state.Character or (state.Player and state.Player.Character)
            if char then
                root = char:FindFirstChild("HumanoidRootPart")
            end
        end)
    end
    local did = false
    -- Pin CFrame sebelum Last=Now: rubber balik SoftTouch di-frame manapun
    -- (3fps / 60fps sama) ditarik ke dest di luar 52st, bukan ke telur.
    local holdUntil = tonumber(G.__StealEggHoldUntil) or 0
    if holdUntil > 0 then
        if os.clock() < holdUntil and typeof(root) == "Instance" then
            local dest = G.__StealEggHoldDest
            if typeof(dest) == "Vector3" then
                local gpos = G.__StealEggHoldGuard
                local safeR = tonumber(G.__StealEggHoldSafeR) or 52
                local inside = true
                if typeof(gpos) == "Vector3" then
                    local dx = root.Position.X - gpos.X
                    local dz = root.Position.Z - gpos.Z
                    inside = math.sqrt(dx * dx + dz * dz) < safeR
                end
                if inside then
                    -- Max 22st: hop 52+ st sambil gendong = server drop telur.
                    pcall(function()
                        local dx = dest.X - root.Position.X
                        local dz = dest.Z - root.Position.Z
                        local mag = math.sqrt(dx * dx + dz * dz)
                        local step = mag
                        if step > 22 then
                            step = 22
                        end
                        local nx = root.Position.X
                        local nz = root.Position.Z
                        if mag > 0.5 then
                            nx = nx + dx / mag * step
                            nz = nz + dz / mag * step
                        end
                        local rot = root.CFrame - root.CFrame.Position
                        root.CFrame = CFrame.new(nx, root.Position.Y, nz) * rot
                        root.AssemblyLinearVelocity = Vector3.zero
                    end)
                    did = true
                else
                    G.__StealEggHoldDest = Vector3.new(root.Position.X, dest.Y, root.Position.Z)
                end
            end
        else
            G.__StealEggHoldUntil = 0
            G.__StealEggHoldDest = nil
            G.__StealEggHoldGuard = nil
        end
    end
    if G.__StealEggHhtAdopt == true then
        pcall(function()
            state.LastObservedSample = nil
            state.LastSample = nil
        end)
        G.__StealEggHhtAdopt = false
        did = true
    elseif typeof(root) == "Instance" then
        local last = rawget(state, "LastObservedSample")
        local nxt = {}
        if type(last) == "table" then
            pcall(function()
                for k, v in pairs(last) do
                    nxt[k] = v
                end
            end)
        end
        local pos = root.Position
        local cf = root.CFrame
        local vel = root.AssemblyLinearVelocity
        local ang = root.AssemblyAngularVelocity
        nxt.Position = pos
        nxt.CFrame = cf
        nxt.LinearVelocity = vel
        nxt.AssemblyLinearVelocity = vel
        nxt.AngularVelocity = ang
        nxt.Timestamp = workspace:GetServerTimeNow()
        pcall(function()
            state.LastObservedSample = nxt
            state.LastSample = nxt
        end)
        did = true
    end
    if rawget(state, "CorrectionContext") ~= nil then
        pcall(function()
            state.CorrectionContext = nil
        end)
        did = true
    end
    if rawget(state, "MovementMode") == "Correcting" then
        pcall(function()
            state.MovementMode = "Trusted"
        end)
        did = true
    end
    local ev = rawget(state, "Evidence")
    if type(ev) == "table" and tonumber(ev.Teleport) and ev.Teleport > 0 then
        pcall(function()
            ev.Teleport = 0
        end)
        did = true
    end
    return did
end

local function hhtReady()
    return G.__StealEggHhtOff == true or G.__StealEggHhtQuiet == true
end

-- Pack (1) mute di TpHold/MoveQuiet. Instant: FarOn = sesi steal penuh.
-- Bukan Busy: loop Wait/no-match sering nyalakan Busy di luar steal.
local function wantQuiet()
    if G.__StealEggHhtOff == true then
        return false
    end
    local untilT = tonumber(G.__StealEggHhtSnapUntil) or 0
    if untilT > 0 and os.clock() < untilT then
        return true
    end
    return G.__StealEggSnapMute == true
        or G.__StealEggRelocateMute == true
end

-- Last=Now dari snap sampai Release (carry). Orig tetap jalan.
-- Pulse pendek 0.4s = Playback lihat FAR pas awal gendong → rubber.
local snapGen = 0
function M.PulseSnapMute(sec)
    if G.__StealEggHhtOff == true then
        return
    end
    G.__StealEggSnapMute = true
    if G.__StealEggHhtSnapArmed == true then
        return
    end
    sec = tonumber(sec)
    if sec == nil or sec < 0.12 then
        sec = 0.4
    elseif sec > 0.55 then
        sec = 0.55
    end
    snapGen += 1
    local g = snapGen
    task.delay(sec, function()
        if g == snapGen and G.__StealEggHhtSnapArmed ~= true then
            G.__StealEggSnapMute = false
        end
    end)
end
G.__StealEggPulseSnapMute = function(sec)
    return M.PulseSnapMute(sec)
end

-- Global: stub Playback (termasuk hasil hook load sebelumnya) selalu panggil ini.
G.__StealEggHhtApply = function(state)
    if not wantQuiet() then
        return false
    end
    return quietPlayback(state)
end

local function isHhtFn(fn)
    if type(fn) ~= "function" then
        return false
    end
    local src = ""
    pcall(function()
        src = tostring(debug.info(fn, "s") or "")
    end)
    if src == "[C]" then
        return false
    end
    return hasC(fn, "HardHorizontalTeleport")
end

-- filtergc: puluhan µs–ms. getgc(): sapu 70k+ fn. Cadangan kalau filtergc kosong.
local function filterFns(spec)
    local list = {}
    if type(filtergc) ~= "function" or type(spec) ~= "table" then
        return list
    end
    local function take(res)
        if type(res) == "function" then
            list[#list + 1] = res
        elseif type(res) == "table" then
            for _, v in pairs(res) do
                if type(v) == "function" then
                    list[#list + 1] = v
                end
            end
        end
    end
    local ok, res = pcall(filtergc, "function", spec, false)
    if ok then
        take(res)
    end
    -- Jangan filtergc(..., true): sapu semua table = 100–1000ms di HP.
    return list
end

local function srcHas(fn, needle)
    if type(fn) ~= "function" or type(needle) ~= "string" then
        return false
    end
    local src = ""
    pcall(function()
        src = tostring(debug.info(fn, "s") or "")
    end)
    return src ~= "" and string.find(src, needle, 1, true) ~= nil
end

local function fnName(fn)
    local n = ""
    pcall(function()
        n = tostring(debug.info(fn, "n") or "")
    end)
    return n
end

-- Must keep the original Playback closure. `local orig = fn` then hookfunction(fn, stub)
-- makes orig==stub on this executor → C stack overflow (log: ContentCatalog.Playback).
local function hookHht(fn)
    if type(fn) ~= "function" then
        return false, "not_fn"
    end
    if hookedHht[fn] == true then
        return true, "already"
    end
    local orig = cloneFn(fn)
    if type(orig) ~= "function" then
        -- Tanpa clonefunction, hookfunction sering balikin stub ke orig → overflow.
        return false, "no_clone"
    end
    local busy = false
    local stub
    stub = wrap(function(a, b, ...)
        if busy then
            return
        end
        G.__StealEggHhtHits = (tonumber(G.__StealEggHhtHits) or 0) + 1
        -- Ambil record anti-cheat dari Playback (bukan getgc) — getgc = spike CPU.
        if type(a) == "table" and rawget(a, "Evidence") ~= nil then
            local pl = rawget(a, "Player")
            if pl == nil or pl == game.Players.LocalPlayer then
                G.__StealEggAcRecord = a
            end
        end
        -- Jangan skip orig. Skip + FAR CFrame = hop 60s (0.55s pun cukup).
        -- SnapUntil: Last=Now lalu orig (detektor HHT diam, sample tetap hidup).
        if wantQuiet() and type(a) == "table" then
            local apply = G.__StealEggHhtApply
            if type(apply) == "function" then
                pcall(apply, a)
            end
        end
        G.__StealEggHhtPass = (tonumber(G.__StealEggHhtPass) or 0) + 1
        if type(orig) ~= "function" or orig == stub then
            return
        end
        busy = true
        local ok, r1, r2, r3 = pcall(orig, a, b, ...)
        busy = false
        if not ok then
            return
        end
        return r1, r2, r3
    end)
    local h = hf()
    if type(h) ~= "function" then
        return false, "no_hf"
    end
    local ok, ret = pcall(h, fn, stub)
    if not ok then
        return false, "hf_err:" .. tostring(ret)
    end
    if type(orig) ~= "function" and type(ret) == "function" and ret ~= stub then
        orig = ret
    end
    if type(orig) ~= "function" or orig == stub then
        return false, "orig_lost"
    end
    hookedHht[fn] = true
    hookedHht[stub] = true
    persistHht[fn] = true
    persistHht[stub] = true
    hhtOrigs[fn] = orig
    G.__StealEggHhtOrigs = hhtOrigs
    return true, "ok"
end

local function origFromStub(stub)
    if type(stub) ~= "function" then
        return nil
    end
    if type(debug) ~= "table" or type(debug.getupvalue) ~= "function" then
        return nil
    end
    for i = 1, 24 do
        local ok, name, val = pcall(debug.getupvalue, stub, i)
        if not ok then
            break
        end
        local fn = val
        if type(name) == "function" and val == nil then
            fn = name
        end
        if type(fn) == "function" and fn ~= stub and isHhtFn(fn) then
            return fn
        end
    end
    return nil
end

-- Cabut stub HHT → Playback native. Wajib saat HhtOff: hook clone tetap
-- bikin 0 sample meski wantQuiet=false.
function M.RestoreHhtNative()
    local h = hf()
    local n = 0
    local seen = {}
    local function putBack(fn, orig)
        if type(fn) ~= "function" or seen[fn] == true then
            return
        end
        seen[fn] = true
        if type(restorefunction) == "function" then
            if pcall(restorefunction, fn) then
                n += 1
                return
            end
        end
        if type(h) == "function" and type(orig) == "function" and orig ~= fn then
            if pcall(h, fn, orig) then
                n += 1
            end
        end
    end
    for fn, orig in pairs(hhtOrigs) do
        putBack(fn, orig)
    end
    for fn in pairs(persistHht) do
        local orig = hhtOrigs[fn] or origFromStub(fn)
        putBack(fn, orig)
    end
    table.clear(hookedHht)
    table.clear(persistHht)
    table.clear(hhtOrigs)
    G.__StealEggHhtHooked = persistHht
    G.__StealEggHhtOrigs = hhtOrigs
    G.__StealEggHhtQuiet = false
    G.__StealEggSnapMute = false
    G.__StealEggRelocateMute = nil
    G.__StealEggHhtForceRefresh = false
    G.__StealEggHhtSnapArmed = false
    G.__StealEggHhtLastPulse = 0
    G.__StealEggHhtSnapUntil = 0
    G.__StealEggHhtOff = true
    return n
end

-- Arm hook Playback sebelum bait. Quiet hanya saat FarOn/TpHold (wantQuiet).
function M.PreArmHht()
    G.__StealEggHhtOff = false
    G.__StealEggHhtForceRefresh = true
    return M.Arm()
end

-- Instant FarOn sudah mute. Cadangan: SnapMute + hook.
function M.ArmHhtForSnap(sec)
    G.__StealEggHhtOff = false
    G.__StealEggHhtSnapArmed = true
    G.__StealEggHhtForceRefresh = true
    M.PulseSnapMute(sec)
    return M.Arm()
end

-- Jangan cabut hook. getgc lagi = spike CPU. SnapUntil=0 → orig native.
function M.ReleaseHhtAfterCarry()
    snapGen += 1
    G.__StealEggSnapMute = false
    G.__StealEggRelocateMute = nil
    G.__StealEggHhtSnapUntil = 0
    G.__StealEggHhtSnapArmed = false
    G.__StealEggHoldUntil = 0
    G.__StealEggHoldDest = nil
    G.__StealEggHoldGuard = nil
    log("hht release-carry keep-hook")
    return 0
end

local function rebindPersistedHht()
    local n = 0
    local list = {}
    for fn in pairs(persistHht) do
        -- Hanya identity asli (punya constant HHT), bukan stub hasil hook.
        if type(fn) == "function" and isHhtFn(fn) then
            list[#list + 1] = fn
        end
    end
    for i = 1, #list do
        local fn = list[i]
        hookedHht[fn] = nil
        local okH = hookHht(fn)
        if okH then
            n += 1
        end
    end
    return n
end

local function hookHhtFns()
    local n, seen, fail = 0, 0, "none"
    n += rebindPersistedHht()
    local function eatFn(fn)
        if type(fn) ~= "function" or isHhtFn(fn) ~= true then
            return
        end
        seen += 1
        local okH, why = hookHht(fn)
        if okH then
            n += 1
        else
            fail = tostring(why or "fail")
        end
    end
    local light = filterFns({ Constants = { "HardHorizontalTeleport" } })
    for i = 1, #light do
        eatFn(light[i])
    end
    -- Jangan getgc cadangan. Itu BAC-9511 (sampling; kena kalau Playback belum ada).
    if seen == 0 and n == 0 then
        return 0, "no_hht_fn"
    end
    if n == 0 then
        return 0, fail
    end
    return n, "ok"
end

function M.RefreshHht()
    if G.__StealEggHhtOff == true then
        return true
    end
    -- Jalur stall di Move memanggil ini langsung, dulu tanpa cooldown apa pun,
    -- jadi tiap trip jauh bisa memicu getgc penuh. Pakai gap yang sama.
    local now = os.clock()
    local last = tonumber(G.__StealEggVtLastScan)
    if last ~= nil and now - last < scanGap() then
        return G.__StealEggHhtQuiet == true
    end
    G.__StealEggVtLastScan = now
    flushPend()
    local n, why = hookHhtFns()
    n = tonumber(n) or 0
    scanMark(n > 0)
    G.__StealEggHhtRefreshAt = os.clock()
    if n > 0 then
        G.__StealEggHhtQuiet = true
        M._last.hht = n
        M._last.err = tostring(why or "ok")
        log(string.format(
            "hht refresh n=%d why=%s hits=%s",
            n,
            tostring(why),
            tostring(G.__StealEggHhtHits or 0)
        ))
        return true
    end
    log(string.format("hht refresh 0 why=%s hits=%s", tostring(why), tostring(G.__StealEggHhtHits or 0)))
    return G.__StealEggHhtQuiet == true
end

local function hookGcFns()
    local n = 0
    local vtMsg = filterFns({ Constants = { "Vertical trajectory must exist after takeoff evaluation" } })
    for i = 1, #vtMsg do
        if hookStep(vtMsg[i]) then
            n += 1
        end
    end
    local hvts = filterFns({ Constants = { "HardVerticalTeleport" } })
    for i = 1, #hvts do
        local fn = hvts[i]
        if fnName(fn) == "Evaluate" or srcHas(fn, "AxisDelta") or srcHas(fn, "VerticalSegment") then
            if hookEval(fn) then
                n += 1
            end
        end
    end
    return n
end

local function scanGc()
    -- Sengaja kosong. getgc(true) di sini = BAC-9511.
    return {}, {}
end

function M.Armed()
    return G.__StealEggVtQuiet == true and hhtReady()
end

function M.Status()
    flushPend()
    envSnap()
    return {
        vt = G.__StealEggVtQuiet == true,
        hht = hhtReady(),
        hhtOff = G.__StealEggHhtOff == true,
        vtN = tonumber(M._last.vt) or 0,
        hhtN = tonumber(M._last.hht) or 0,
        hf = M._last.hf,
        getgc = M._last.getgc,
        clone = M._last.clone,
        err = M._last.err,
        at = M._last.at,
    }
end

function M.Arm()
    flushPend()
    if G.__StealEggHhtOff == true then
        pcall(M.RestoreHhtNative)
        G.__StealEggHhtQuiet = false
        G.__StealEggHhtForceRefresh = false
    end
    local now = os.clock()
    local forceHht = G.__StealEggHhtOff ~= true and (
        G.__StealEggHhtForceRefresh == true
        or (type(G.__StealEggHhtRefreshAt) ~= "number")
        or (now - G.__StealEggHhtRefreshAt > 45)
    )
    if G.__StealEggVtQuiet == true and hhtReady() and forceHht ~= true then
        return true
    end
    if G.__StealEggVtArmBusy == true then
        return G.__StealEggVtQuiet == true and hhtReady()
    end
    -- VT belum: jangan hormati gap 60s (itu bikin kadang mati / kadang aman).
    if G.__StealEggVtQuiet == true
        and forceHht ~= true
        and type(G.__StealEggVtLastScan) == "number"
        and now - G.__StealEggVtLastScan < scanGap()
    then
        return hhtReady()
    end
    -- Baru dikonsumsi di sini: kalau dibuang sebelum gap dicek, permintaan
    -- refresh dari jalur stall hilang tanpa pernah dijalankan.
    G.__StealEggHhtForceRefresh = false
    G.__StealEggVtLastScan = now
    G.__StealEggVtArmBusy = true
    local thf, tgc, tcl = envSnap()
    local n = tonumber(M._last.vt) or 0
    local hn = tonumber(M._last.hht) or 0
    local whyHht = M._last.err

    if G.__StealEggVtQuiet ~= true then
        local ok, hooked = pcall(hookGcFns)
        if ok then
            n = tonumber(hooked) or 0
        else
            M._last.err = "vt_gc:" .. tostring(hooked)
            log("vt scan fail " .. tostring(hooked))
        end
        -- Cadangan getgc(true)/scanGc = BAC-9511. Ulang filtergc saja, tanpa sapu heap.
        if n == 0 then
            for _ = 1, 3 do
                task.wait(0.12)
                local okR, hookedR = pcall(hookGcFns)
                if okR then
                    n = tonumber(hookedR) or 0
                end
                if n > 0 then
                    break
                end
            end
        end
        M._last.vt = n
        if n > 0 then
            G.__StealEggVtQuiet = true
            log(string.format("vt armed x%d hf=%s getgc=%s", n, thf, tgc))
        else
            log(string.format("vt MISS hf=%s getgc=%s err=%s", thf, tgc, tostring(M._last.err or "-")))
        end
    end

    if G.__StealEggHhtOff == true then
        local restored = 0
        pcall(function()
            restored = tonumber(M.RestoreHhtNative()) or 0
        end)
        hn = 0
        whyHht = "hht_off"
        M._last.hht = 0
        M._last.err = whyHht
        G.__StealEggHhtQuiet = false
        G.__StealEggHhtRefreshAt = now
        G.__StealEggHhtForceRefresh = false
        if G.__StealEggHhtOffLogged ~= true then
            G.__StealEggHhtOffLogged = true
            log(string.format("hht OFF · native Playback restore=%d", restored))
        elseif restored > 0 then
            log(string.format("hht OFF restore=%d", restored))
        end
    elseif G.__StealEggHhtQuiet ~= true or forceHht == true then
        local okH, countOrWhy, why = pcall(hookHhtFns)
        if okH then
            hn = tonumber(countOrWhy) or 0
            whyHht = tostring(why or "none")
        else
            hn = 0
            whyHht = "hht_err:" .. tostring(countOrWhy)
        end
        M._last.hht = hn
        M._last.err = whyHht
        G.__StealEggHhtRefreshAt = now
        if hn > 0 then
            G.__StealEggHhtQuiet = true
            log(string.format("hht armed x%d clone=%s force=%s", hn, tcl, tostring(forceHht == true)))
        else
            if G.__StealEggFarOn ~= true then
                for _ = 1, 3 do
                    task.wait(0.15)
                    local okR, nR, whyR = pcall(hookHhtFns)
                    if okR then
                        hn = tonumber(nR) or 0
                        whyHht = tostring(whyR or whyHht)
                    end
                    if hn > 0 then
                        break
                    end
                end
                M._last.hht = hn
                M._last.err = whyHht
            end
            if hn > 0 then
                G.__StealEggHhtQuiet = true
                log(string.format("hht armed x%d clone=%s retry", hn, tcl))
            else
                log(string.format("hht MISS why=%s hf=%s clone=%s (no getgc)", tostring(whyHht), thf, tcl))
            end
        end
    end

    M._last.at = os.clock()
    G.__StealEggVtArmBusy = false
    local okAll = G.__StealEggVtQuiet == true and hhtReady()
    -- Produktif = setelah scan semuanya armed. Refresh 45s yang sukses tetap
    -- dihitung produktif, sedangkan target yang tidak pernah ada di executor
    -- ini (VT atau HHT) akan menaikkan gap sampai 60s.
    scanMark(okAll)
    log(string.format(
        "arm done vt=%s(%d) hht=%s(%d) ok=%s fails=%d gap=%.1f",
        tostring(G.__StealEggVtQuiet == true),
        tonumber(M._last.vt) or 0,
        tostring(hhtReady()),
        tonumber(M._last.hht) or 0,
        tostring(okAll),
        tonumber(G.__StealEggVtScanFails) or 0,
        scanGap()
    ))
    if okAll then
        return true
    end
    if type(G.__StealEggVtWaitWarn) ~= "number" then
        G.__StealEggVtWaitWarn = os.clock()
    end
    return false
end

function M.WaitArmed(sec)
    sec = tonumber(sec) or 2
    if sec < 0.4 then
        sec = 0.4
    elseif sec > 4 then
        sec = 4
    end
    G.__StealEggVtScanFails = 0
    G.__StealEggHhtForceRefresh = true
    local t0 = os.clock()
    local jumped = false
    while os.clock() - t0 < sec do
        if G.__StealEggVtQuiet == true then
            G.__StealEggHhtForceRefresh = false
            return true
        end
        pcall(M.Arm)
        if G.__StealEggVtQuiet == true then
            G.__StealEggHhtForceRefresh = false
            return true
        end
        if jumped ~= true and (os.clock() - t0) > 0.35 then
            jumped = true
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                local h = lp and lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                if h and h.Health > 0 then
                    h.Jump = true
                end
            end)
        end
        task.wait(0.12)
    end
    G.__StealEggHhtForceRefresh = false
    return G.__StealEggVtQuiet == true
end

do
    local thf, tgc, tcl = envSnap()
    -- Langsung arm VT+HHT di load. Delay/background = steal pertama gagal.
    G.__StealEggHhtOff = false
    G.__StealEggArmYield = false
    G.__StealEggHhtJob = tostring(game.JobId)
    G.__StealEggHhtForceRefresh = true
    G.__StealEggVtDeepScan = false
    log(string.format("mod load hf=%s getgc=%s clone=%s filtergc-only", thf, tgc, tcl))
    pcall(M.Arm)
    G.__StealEggHhtForceRefresh = false
end

if G.__StealEggVtWatchOn ~= true then
    G.__StealEggVtWatchOn = true
end

return M
 end,         required = true },
    { key = "Integrity", name = "Integrity",     factory = function() --[[
  StealEgg integrity — mute Character integrity spam (RAM DevConsole)
  + drop IntegrityViolation / CorrectionStarted FireServer saat Instant/FAR.

  Port dari MaxEarnSteal/integrity_patcher.lua, flag Node:
    __StealEggFarOn / __StealEggTpHold / __StealEggBusy / __StealEggMoveQuiet
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local G = (getgenv and getgenv()) or _G
local M = {
    armed = false,
    netArmed = false,
    logMuted = false,
    wcallArmed = false,
    wcallMuted = 0,
    patched = 0,
    dropped = 0,
    muted = 0,
    err = nil,
    mode = nil,
}
G.StealEggIntegrity = M

local function log(msg)
    local fn = G.StealEggDbg
    if type(fn) == "function" then
        pcall(fn, "INTEGRITY", msg)
    end
end

local TARGET_TOKENS = {
    ["X-16"] = true,
    ["Character integrity sampling was intercepted"] = true,
    ["Character integrity evaluator returned an invalid completion receipt"] = true,
    ["Character integrity movement evaluation failed"] = true,
    ["Character integrity execution was interrupted"] = true,
    ["Invalid character state mutation scope"] = true,
    ["Invalid ground-contact mutation scope"] = true,
}

local function isIntegrityLog(s)
    if type(s) ~= "string" then
        return false
    end
    if TARGET_TOKENS[s] then
        return true
    end
    return string.find(s, "Character integrity", 1, true) ~= nil
        or string.find(s, "Invalid character state mutation", 1, true) ~= nil
        or string.find(s, "Invalid ground-contact mutation", 1, true) ~= nil
        or string.find(s, "invalid completion receipt", 1, true) ~= nil
end

local function isViolationEndpoint(s)
    if type(s) ~= "string" then
        return false
    end
    return s:find("IntegrityViolation", 1, true) ~= nil
        or s:find("CorrectionStarted", 1, true) ~= nil
        or s:find("RequestCharacterReset", 1, true) ~= nil
        or s:find("InvalidMovementSample", 1, true) ~= nil
end

local function isAllowListedRemote(self)
    if typeof(self) ~= "Instance" then
        return false
    end
    local full = ""
    pcall(function()
        full = self:GetFullName()
    end)
    if full == "" then
        full = self.Name or ""
    end
    return full:find("GuardPatrol", 1, true)
        or full:find("GuardOnboarding", 1, true)
        or full:find("ForestStrike", 1, true)
        or full:find("ProbeSatchel", 1, true)
        or full:find("ClientKit", 1, true)
        or full:find("Analytics", 1, true)
        or full:find("EggWorld", 1, true)
        or full:find("AwayEarnings", 1, true)
        or full:find("RigSync", 1, true)
        or full:find("AreaEgg", 1, true)
        or full:find("EggCmds", 1, true)
end

-- Hanya pulse SnapMute (~0.55s tulis CFrame). FarOn se-sesi drop sample → hop 60s.
local function farActive()
    return G.__StealEggSnapMute == true
        or G.__StealEggRelocateMute == true
end

local function shouldDropFire(self, ...)
    if farActive() ~= true then
        return false
    end
    -- Ketat: hanya endpoint violation eksplisit.
    -- Broad match "Integrity"/"Correction"/"ClientCharacter" sempat drop
    -- remote save/sync → "Something went wrong fetching save" (267).
    local n = select("#", ...)
    for i = 1, n do
        local a = select(i, ...)
        if type(a) == "string" and isViolationEndpoint(a) then
            return true
        end
    end
    -- Opt-in full mute (berbahaya). Default OFF.
    if G.__StealEggFullFireMute == true then
        if isAllowListedRemote(self) then
            return false
        end
        return true
    end
    return false
end

G.__StealEggShouldDropFire = shouldDropFire

-- WCall = xpcall wrapper; ErrorHandler selalu debug.traceback → CPU spike.
-- Swallow integrity error SEBELUM traceback/warn.
local function armWCallMute()
    if G.__StealEggWCallMuted == true then
        return true
    end
    local hf = hookfunction or hookfunc
    if type(hf) ~= "function" then
        return false
    end
    local mod
    pcall(function()
        local ug = ReplicatedStorage:FindFirstChild("UserGenerated")
        local lang = ug and ug:FindFirstChild("Lang")
        mod = lang and lang:FindFirstChild("WCall")
    end)
    if not mod then
        return false
    end
    local okReq, wcall = pcall(require, mod)
    if not okReq or type(wcall) ~= "function" then
        return false
    end
    local ok = pcall(function()
        local old
        local wrap = function(fn, ...)
            return xpcall(fn, function(err)
                local s = tostring(err or "")
                if isIntegrityLog(s) then
                    M.muted += 1
                    M.wcallMuted = (tonumber(M.wcallMuted) or 0) + 1
                    return
                end
                -- Mirror ErrorHandler asli (tanpa lewat old, supaya tidak double).
                warn(s .. "\nStack Begin\n" .. debug.traceback(nil, 3) .. "Stack End")
            end, ...)
        end
        if type(newcclosure) == "function" then
            wrap = newcclosure(wrap)
        end
        old = hf(wcall, wrap)
    end)
    if ok then
        G.__StealEggWCallMuted = true
        M.wcallArmed = true
        return true
    end
    return false
end

local function armLogMute()
    if M.logMuted == true and G.__StealEggWCallMuted == true then
        return true
    end

    armWCallMute()

    -- Mute warn() backup (kalau ada path lain selain WCall).
    local hf = hookfunction or hookfunc
    if M.logMuted ~= true and type(hf) == "function" and type(warn) == "function" then
        local oldWarn
        local ok = pcall(function()
            local wrap = function(...)
                local a1 = ...
                if isIntegrityLog(tostring(a1 or "")) then
                    M.muted += 1
                    return
                end
                return oldWarn(...)
            end
            if type(newcclosure) == "function" then
                wrap = newcclosure(wrap)
            end
            oldWarn = hf(warn, wrap)
        end)
        if ok then
            M.logMuted = true
        end
    end
    return M.logMuted == true or G.__StealEggWCallMuted == true
end

local function patchClosures()
    local getgc = getgc or get_gc_objects
    local getconstants = (debug and debug.getconstants) or getconstants
    local getstack = (debug and debug.getstack) or getstack
    local setstack = (debug and debug.setstack) or setstack
    local hf = hookfunction or hookfunc
    if type(getgc) ~= "function" or type(hf) ~= "function" then
        return 0, "no getgc/hookfunction"
    end

    local patched = 0
    local okScan, scanErr = pcall(function()
        for _, value in pairs(getgc(true)) do
            if type(value) == "function" then
                local isLua = true
                if type(islclosure) == "function" then
                    isLua = islclosure(value) == true
                end
                local isExec = false
                if type(isexecutorclosure) == "function" then
                    isExec = isexecutorclosure(value) == true
                end
                if isLua and not isExec and type(getconstants) == "function" then
                    local success, constants = pcall(getconstants, value)
                    if success and type(constants) == "table" then
                        local shouldPatch = false
                        for _, constant in pairs(constants) do
                            if type(constant) == "string" and TARGET_TOKENS[constant] then
                                shouldPatch = true
                                break
                            end
                        end
                        if shouldPatch then
                            local oldHook
                            local wrap = function(...)
                                if type(getstack) == "function" and type(setstack) == "function" then
                                    -- Level 1–3: executor/SF beda frame depth.
                                    for level = 1, 3 do
                                        local stackSuccess, stack = pcall(getstack, level)
                                        if stackSuccess and type(stack) == "table" then
                                            for index, stackVal in pairs(stack) do
                                                if type(stackVal) == "string" and TARGET_TOKENS[stackVal] then
                                                    pcall(setstack, level, index, nil)
                                                end
                                            end
                                        end
                                    end
                                end
                                return oldHook(...)
                            end
                            if type(newcclosure) == "function" then
                                wrap = newcclosure(wrap)
                            end
                            oldHook = hf(value, wrap)
                            patched += 1
                        end
                    end
                end
            end
        end
    end)
    if not okScan then
        return 0, tostring(scanErr)
    end
    return patched, nil
end

local function armNamecallFilter()
    if G.__StealEggIntegrityNamecall then
        return true, "already"
    end
    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false, "no hookmetamethod"
    end
    local ok, err = pcall(function()
        local old
        old = hookmetamethod(
            game,
            "__namecall",
            newcclosure(function(self, ...)
                local method = getnamecallmethod()
                if method == "FireServer" or method == "fireServer" then
                    local dropFn = G.__StealEggShouldDropFire
                    if type(dropFn) == "function" and dropFn(self, ...) then
                        M.dropped += 1
                        return
                    end
                end
                return old(self, ...)
            end)
        )
    end)
    if not ok then
        return false, tostring(err)
    end
    G.__StealEggIntegrityNamecall = true
    M.mode = "namecall"
    return true, "namecall"
end

local function armNetworkFire()
    if G.__StealEggIntegrityNetFire then
        return true, "already"
    end
    local candidates = {}
    local function tryRequire(inst)
        if not inst then
            return
        end
        local ok, mod = pcall(require, inst)
        if ok and type(mod) == "table" and type(mod.Fire) == "function" then
            candidates[#candidates + 1] = mod
        end
    end
    pcall(function()
        local lib = ReplicatedStorage:FindFirstChild("Library")
        local client = lib and lib:FindFirstChild("Client")
        tryRequire(client and client:FindFirstChild("Network"))
    end)
    if type(getloadedmodules) == "function" then
        pcall(function()
            for _, m in ipairs(getloadedmodules()) do
                if m.Name == "Network" then
                    tryRequire(m)
                end
            end
        end)
    end
    local hooked = 0
    for _, Network in ipairs(candidates) do
        if not G.__StealEggIntegrityNetFire then
            local rawFire = Network.Fire
            Network.Fire = function(endpoint, ...)
                -- Samakan gate dengan namecall (genv predicate live-updatable).
                if type(endpoint) == "string" and isViolationEndpoint(endpoint) and farActive() == true then
                    M.dropped += 1
                    return
                end
                return rawFire(endpoint, ...)
            end
            G.__StealEggIntegrityNetFire = true
            hooked += 1
            M.mode = (M.mode or "") .. "+network"
        end
    end
    return hooked > 0, "n=" .. tostring(hooked)
end

function M.Arm()
    if G.__StealEggSkipExtraHooks == true then
        M.armed = true
        log("skip extra · WCall/warn off, Playback tetap")
        return true
    end
    armLogMute()
    armWCallMute()

    -- Jangan getgc(true) di load (freeze). Jangan namecall (BAC). Instant butuh VT dari speed.lua.
    if not M.armed then
        M.armed = true
        M.patched = 0
        log("closures skipped (no getgc true)")
    end

    if G.__StealEggWantFireHook == true then
        local okNc, ncMsg = armNamecallFilter()
        log("namecall ok=" .. tostring(okNc) .. " · " .. tostring(ncMsg))
        local okNet, netMsg = armNetworkFire()
        log("Network.Fire ok=" .. tostring(okNet) .. " · " .. tostring(netMsg))
        M.netArmed = okNc or okNet
    end

    log(string.format(
        "armed · closures=%d · wcall=%s · net=%s · muted=%d · wcallMuted=%d · dropped=%d",
        tonumber(M.patched) or 0,
        tostring(G.__StealEggWCallMuted == true),
        tostring(M.netArmed),
        tonumber(M.muted) or 0,
        tonumber(M.wcallMuted) or 0,
        tonumber(M.dropped) or 0
    ))
    return M.armed == true or M.logMuted == true or M.netArmed == true or G.__StealEggWCallMuted == true
end

function M.Status()
    return {
        armed = M.armed,
        net = M.netArmed,
        logMuted = M.logMuted,
        wcall = G.__StealEggWCallMuted == true,
        patched = M.patched,
        muted = M.muted,
        wcallMuted = M.wcallMuted or 0,
        dropped = M.dropped,
        mode = M.mode,
        err = M.err,
    }
end

-- Auto-arm sekali saat load (jangan tunggu steal).
task.defer(function()
    pcall(M.Arm)
end)

return M
 end,     required = true },
    { key = "Move",      name = "Move",          factory = function() -- StealEgg travel
-- walk  : WalkSpeed = angka Speed UI, Humanoid:MoveTo, tanpa CFrame
-- glide : geser CFrame XZ pada angka Speed, WalkSpeed ikut angka itu (atap AC)
-- teleport : Instant hop CFrame (Forest bait tetap)

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G

-- Ragdoll Forest: Playback ImpulseContext (HHT native skip, tanpa skip orig).
-- Jaga sampai pad supaya rubber/drop plot tidak mulai saat pulang.
local function keepRagdoll()
    return G.__StealEggKeepRag == true
end

-- Scrambled egg / guard lempar ke atas. Glide yang slam CFrame lantai +
-- ChangeState(Running) + kickOffBelt tiap tick = VerticalTrajectory +
-- WCall debug.traceback → CPU 800%. Diam sampai mendarat.
local function slipFromEgg(hum, hrp, keepSpeed)
    if not hum then
        return
    end
    local pad = Vector3.new(515, 71, -363)
    local y = hrp and hrp.Position.Y or pad.Y
    pcall(function()
        hum.PlatformStand = false
        hum.Sit = false
        if tonumber(keepSpeed) and keepSpeed >= 16 then
            hum.WalkSpeed = keepSpeed
        end
        hum:MoveTo(Vector3.new(pad.X, y, pad.Z))
    end)
end

local function eggSlip(opts)
    local reason = tostring(type(opts) == "table" and opts.reason or "")
    if reason ~= "egg" and reason ~= "stand-egg" then
        return false
    end
    local wild = G.StealEggWild
    local carrying = type(wild) == "table" and type(wild._carry) == "table" and wild._carry.IsCarrying == true
    if carrying ~= true then
        return false
    end
    local ui = string.lower(tostring(type(opts) == "table" and opts.uiMode or ""))
    if ui == "" then
        ui = string.lower(tostring(type(wild) == "table" and wild.moveMode or ""))
    end
    return ui == "walk" or ui == "glide"
end

local function knockAirborne(hrp, hum)
    local rt = LP and LP:GetAttribute("RagdollEndTime")
    if type(rt) == "number" then
        local now = 0
        pcall(function()
            now = workspace:GetServerTimeNow()
        end)
        if rt - now > 0 then
            return true
        end
    end
    if hum then
        local st
        pcall(function()
            st = hum:GetState()
        end)
        -- Freefall/FallingDown sesudah timer ragdoll habis = sisa state, bukan di udara.
        -- Kalau ikut dihitung airborne, walk/glide diam di telur dan carry tidak terkirim.
        if st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.Flying
        then
            return true
        end
    end
    if hrp and typeof(hrp.Position) == "Vector3" and hrp.Position.Y > 90 then
        return true
    end
    return false
end

local M = {
    MODE_ITEMS = {
        { key = "glide", name = "Glide" },
        { key = "walk", name = "Walk" },
        { key = "teleport", name = "Teleport" },
    },
    mode = "glide",
    speed = 600,
}

local VALID = { glide = true, walk = true, teleport = true }
local ARRIVE_OK = 5
local GLIDE_Y = 70.5
local GLIDE_LAND_Y = 70.7
local GLIDE_MAX_SEC = 25
local GLIDE_DEFAULT_SPEED = 600
local GLIDE_RUBBER_WAIT = 0.45
-- Pakai dt nyata supaya stud/detik sama di HP 40 FPS maupun PC 60 FPS.
-- (Dulu GLIDE_MAX_DT=0.018 → efektif speed ≈ speed×FPS×0.018: @40FPS cuma ~72%,
--  @15FPS ~27%. Boss/glide HP terasa lambat padahal FPS "bagus".)
-- Cap STEP (bukan dt) supaya lag spike tidak lompat ratusan stud (Impact Flight).
local GLIDE_SPIKE_DT = 0.08
local GLIDE_STEP_DT = 0.05
-- Instant: batas satu hop CFrame. >220 st/tick = server Relocate.
local INSTANT_HOP_MAX = 200
-- Instant: satu rumus, semua fps, tanpa input hop.
-- Server mengukur jarak per frame (live: 85 aman di 5fps + 300fps, 95 masih rubber).
-- Di 10fps Auto (~940) langkahnya cuma ~94, jadi cap ini tidak kepakai.
-- Di 5fps speed×dt jauh di atas cap, jadi mentok ke cap — itu yang rubber.
-- Langkah frame = min(speed UI × dt, 85).
local INSTANT_HOP_CAP = 85
local function instantHopSafe(speed, dt)
    local spd = tonumber(speed) or 941
    local frame = tonumber(dt)
    if type(frame) ~= "number" or frame <= 0 then
        frame = tonumber(G.__StealEggDtEma) or 0.0167
    end
    return math.min(INSTANT_HOP_CAP, spd * frame)
end
-- Dump Impact: AllowedHorizontalSpeed = WalkSpeed * SpeedMultiplier + SpeedFlatAllowance
-- Dump TreadmillUtil.MAX_WALK_SPEED = 300 (SpeedPower applied WS)
-- Slow Mode = malus di live WS. Auto pakai SpeedPower, bukan 16.
local GLIDE_TRUST_WS = 250
local ACCOUNT_MAX_WS = 300
local LEGAL_SPEED_MULT = 3.7
local AUTO_MIN_SPEED = 600
-- Batas kotak Manual. Jarak per frame tetap dijaga INSTANT_HOP_CAP,
-- jadi angka besar di sini efektifnya = 85 × fps.
local AUTO_MAX_SPEED = 5000
local gen = 0
local savedWalkSpeed = nil
local getChar, getHRP, getHum

local prev = G.StealEggMove
if type(prev) == "table" and prev ~= M and type(prev.Stop) == "function" then
    pcall(prev.Stop)
end
G.StealEggMove = M

-- Log OFF default (publish). StealEggSetDebug(true) dari konsol kalau perlu.
local DEBUG = false
M.debug = DEBUG
G.__StealEggMoveDebug = DEBUG
G.__StealEggFarDebug = DEBUG
-- Debug gerak: steal_move_track.txt (workspace root + NodeStealEgg/)
-- steal_trace.txt = tracer Potassium (HOOK/INVOKE). Node GOTO ikut ke situ kalau tracer hidup.
-- Dump: StealEggMove.DumpDebug()  /  MoveTrackDump()  /  StealEggDump()
local SAVE_DIR = (type(G.__StealEggSaveDir) == "string" and G.__StealEggSaveDir ~= "" and G.__StealEggSaveDir) or "NodeStealEgg"
local DBG_FILE = SAVE_DIR .. "/steal_move_track.txt"
local DBG_FILE_ROOT = "steal_move_track.txt"
local DBG_LIMIT = 6000
local dbgLogs = {}
local dbgSeq = 0
local dbgDirty = false
local dbgLastSave = 0
local travel = nil
local travelHB = nil
local travelLastPos = nil

local function v3(p)
    if typeof(p) == "CFrame" then
        p = p.Position
    end
    if typeof(p) ~= "Vector3" then
        return "?"
    end
    return string.format("V3(%.1f,%.1f,%.1f)", p.X, p.Y, p.Z)
end

local function dbgExtra()
    local hrp = type(getHRP) == "function" and getHRP() or nil
    local hum = type(getHum) == "function" and getHum() or nil
    local parts = {}
    if hrp then
        parts[#parts + 1] = "got=" .. v3(hrp.Position)
        parts[#parts + 1] = "anc=" .. tostring(hrp.Anchored)
    else
        parts[#parts + 1] = "got=NO_HRP"
        parts[#parts + 1] = "char=" .. tostring(getChar() ~= nil)
    end
    local hp = hum and tonumber(hum.Health) or -1
    local maxHp = hum and tonumber(hum.MaxHealth) or 0
    local st = "nil"
    if hum then
        local ok, s = pcall(function()
            return hum:GetState()
        end)
        if ok then
            st = tostring(s):gsub("Enum.HumanoidStateType.", "")
        end
    end
    parts[#parts + 1] = string.format("hp=%.0f/%.0f", hp, maxHp)
    parts[#parts + 1] = "st=" .. st
    parts[#parts + 1] = "busy=" .. tostring(G.__StealEggBusy == true)
    parts[#parts + 1] = "claiming=" .. tostring(G.__StealEggClaiming == true)
    parts[#parts + 1] = "steal=" .. tostring(G.__StealEggWanted == true or G.__StealEggLoopOn == true)
    do
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Owner) == "function" then
            local who = d.Owner()
            if who then
                parts[#parts + 1] = "own=" .. tostring(who)
            end
        end
    end
    if travel and travel.reason then
        parts[#parts + 1] = "why=" .. tostring(travel.reason)
    end
    local hatch = G.StealEggHatch
    if type(hatch) == "table" and hatch._placeBusy == true then
        parts[#parts + 1] = "place=1"
    end
    local fuse = G.StealEggFuse
    if type(fuse) == "table" and fuse._busy == true then
        parts[#parts + 1] = "fuse=1"
    end
    local carry = G.__StealEggCarry
    if type(carry) == "table" then
        parts[#parts + 1] = "carry=" .. tostring(carry.IsCarrying == true)
        if carry.Uid ~= nil then
            parts[#parts + 1] = "uid=" .. tostring(carry.Uid)
        end
    end
    return " | " .. table.concat(parts, " ")
end

local function dbgSave(force)
    if not dbgDirty or typeof(writefile) ~= "function" then
        return
    end
    if force ~= true and os.clock() - dbgLastSave < 0.25 then
        return
    end
    dbgLastSave = os.clock()
    dbgDirty = false
    if type(makefolder) == "function" then
        pcall(makefolder, SAVE_DIR)
    end
    local body = table.concat(dbgLogs, "\n") .. "\n"
    pcall(writefile, DBG_FILE, body)
    pcall(writefile, DBG_FILE_ROOT, body)
end

local function dbg(tag, msg)
    if G.__StealEggMoveDebug ~= true then
        return
    end
    tag = tostring(tag or "?")
    dbgSeq += 1
    local line = string.format("[%0.3f #%d][%s] %s%s", os.clock(), dbgSeq, tag, tostring(msg), dbgExtra())
    local n = #dbgLogs
    if n >= DBG_LIMIT then
        dbgLogs[1 + ((dbgSeq - 1) % DBG_LIMIT)] = line
    else
        dbgLogs[n + 1] = line
    end
    dbgDirty = true
    dbgSave()
    local mark = G.StealTraceMark
    if type(mark) == "function" then
        pcall(mark, tag, msg)
    end
end

G.StealEggDbg = dbg

local function stopTravelHB()
    if travelHB then
        pcall(function()
            travelHB:Disconnect()
        end)
        travelHB = nil
    end
    travelLastPos = nil
end

local function startTravelHB()
    stopTravelHB()
    local last = 0
    travelHB = RunService.Heartbeat:Connect(function()
        if not travel then
            return
        end
        local now = os.clock()
        if now - last < 0.18 then
            return
        end
        last = now
        local hrp = getHRP()
        local p = hrp and hrp.Position
        if not p then
            dbg("POS", "no_hrp reason=" .. tostring(travel.reason or "-"))
            return
        end
        local want = travel.want
        local xz = -1
        if typeof(want) == "Vector3" then
            xz = Vector3.new(p.X - want.X, 0, p.Z - want.Z).Magnitude
        end
        local moved = ""
        if travelLastPos then
            moved = string.format(" d=%.1f", (p - travelLastPos).Magnitude)
        end
        travelLastPos = p
        dbg("POS", string.format("reason=%s xzGoal=%.1f want=%s%s", tostring(travel.reason or "-"), xz, v3(want), moved))
    end)
end

function M.DumpDebug()
    dbgDirty = true
    dbgLastSave = 0
    dbgSave()
    return dbgLogs
end

-- Nyalakan / matikan log tanpa reload. Semua modul ikut karena mereka lewat
-- G.StealEggDbg yang baca flag yang sama.
function M.SetDebug(on)
    on = on == true
    M.debug = on
    G.__StealEggMoveDebug = on
    G.__StealEggFarDebug = on
    if on then
        dbg("BOOT", "DEBUG ON → " .. DBG_FILE_ROOT .. " + " .. DBG_FILE)
        dbgSave(true)
    else
        stopTravelHB()
        dbgSave(true)
    end
    return on
end

G.StealEggSetDebug = M.SetDebug

G.MoveTrackDump = function()
    return M.DumpDebug()
end
G.StealEggDump = G.MoveTrackDump

function M.NormalizeMode(mode)
    mode = tostring(mode or "glide"):lower()
    if VALID[mode] then
        return mode
    end
    return "glide"
end

function M.SetMode(mode)
    M.mode = M.NormalizeMode(mode)
    if M.mode == "glide" and (tonumber(M.speed) or 0) < 200 then
        M.speed = GLIDE_DEFAULT_SPEED
    end
    return M.mode
end

local function speedFromSave()
    local Core = G.StealEggCore
    if type(Core) ~= "table" or type(Core.require) ~= "function" then
        return nil
    end
    local Util = Core.require("Shared.Util.TreadmillUtil")
    if type(Util) ~= "table" or type(Util.SpeedPowerToWalkSpeed) ~= "function" then
        return nil
    end
    local Save = Core.require("Library.Client.Save")
    local data
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, d = pcall(Save.Get)
        if ok and type(d) == "table" then
            data = d
        else
            ok, d = pcall(Save.Get, LP, false)
            if ok and type(d) == "table" then
                data = d
            end
        end
    end
    local power = data and tonumber(data.SpeedPower)
    if not power then
        return nil
    end
    local ok, ws = pcall(Util.SpeedPowerToWalkSpeed, power)
    ws = ok and tonumber(ws) or nil
    if not ws then
        return nil
    end
    return math.clamp(ws, 8, ACCOUNT_MAX_WS)
end

local function isInflatedWs(n)
    n = tonumber(n)
    if not n then
        return true
    end
    if math.abs(n - GLIDE_TRUST_WS) < 1.5 then
        return true
    end
    if n > ACCOUNT_MAX_WS + 0.5 then
        return true
    end
    return false
end

local function trustWsForSpeed(speed)
    return math.max(8, tonumber(speed) or GLIDE_TRUST_WS)
end

-- Account WalkSpeed from SpeedPower. Ignore Slow Mode + WS yang kita inflate pas travel.
function M.RealWalkSpeed()
    local saveWs = speedFromSave()
    local hum = getHum()
    local live = hum and tonumber(hum.WalkSpeed)
    local saved = tonumber(savedWalkSpeed)
    if isInflatedWs(live) then
        live = nil
        if saved and isInflatedWs(saved) ~= true then
            live = saved
        end
    end
    if saveWs and live and live < saveWs * 0.55 then
        live = nil
    end
    local n = saveWs or 16
    if live and live >= 8 then
        n = math.max(n, live)
    end
    return n
end

-- Pulihkan WalkSpeed akun (SpeedPower). Jangan 16 / 0 sisa FAR freeze.
function M.ApplyAccountWalkSpeed()
    local hum = getHum()
    if not hum or (tonumber(hum.Health) or 0) <= 0 then
        return false
    end
    local real = tonumber(M.RealWalkSpeed()) or 16
    if real < 16 then
        real = 16
    end
    local live = tonumber(hum.WalkSpeed) or 0
    if live < 8 or live + 0.5 < real * 0.55 or isInflatedWs(live) then
        pcall(function()
            hum.WalkSpeed = real
        end)
        return true
    end
    return false
end

-- Auto = SpeedPower → WalkSpeed (abaikan Slow Mode) × 3.7, min 600, cap 1500.
-- Akun baru WS 16 → 64 terlalu pelan SoftTouch; floor 600.
function M.ResolveAutoSpeed(want)
    local fromAccount = math.max(8, M.RealWalkSpeed() * LEGAL_SPEED_MULT)
    local cap = math.clamp(math.max(fromAccount, AUTO_MIN_SPEED), AUTO_MIN_SPEED, AUTO_MAX_SPEED)
    want = tonumber(want)
    if want == nil then
        return cap
    end
    return math.clamp(math.min(want, cap), AUTO_MIN_SPEED, AUTO_MAX_SPEED)
end

-- Walk/glide auto: lantai 250. WS akun di atas 250 dipakai apa adanya.
function M.WalkGlideAutoSpeed()
    local ws = tonumber(M.RealWalkSpeed()) or 0
    if ws < 250 then
        return 250
    end
    return ws
end

-- Auto walk/glide = WalkGlideAutoSpeed. Auto teleport = max(SpeedPower × 3.7, 600).
-- Manual = angka kotak Move Speed.
function M.WantWalkSpeed()
    local wild = G.StealEggWild
    local mode = "manual"
    local want = tonumber(M.speed)
    if type(wild) == "table" then
        mode = string.lower(tostring(wild.speedMode or "manual"))
        want = tonumber(wild.moveSpeed) or want
    end
    if mode == "auto" then
        local moveMode = string.lower(tostring(type(wild) == "table" and wild.moveMode or M.mode or ""))
        if moveMode == "walk" or moveMode == "glide" then
            return M.WalkGlideAutoSpeed()
        end
        return M.ResolveAutoSpeed()
    end
    return math.clamp(want or 16, 8, AUTO_MAX_SPEED)
end

function M.GetMode()
    return M.NormalizeMode(M.mode)
end

function M.SetSpeed(n)
    n = tonumber(n) or 40
    if n < 8 then
        n = 8
    end
    M.speed = n
    return n
end

getChar = function()
    return LP and LP.Character
end

getHRP = function()
    local c = getChar()
    local h = c and (c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart)
    return (h and h:IsA("BasePart")) and h or nil
end

getHum = function()
    local c = getChar()
    return c and c:FindFirstChildOfClass("Humanoid") or nil
end

local function humState(hum)
    if not hum then
        return nil
    end
    local ok, st = pcall(function()
        return hum:GetState()
    end)
    return ok and st or nil
end

-- Guard / bat / void / load-fall all end here. Do not require MaxHealth:
-- chip damage must not pause steal. Only Health<=0 / Dead / missing char.
function M.IsDead()
    local char = getChar()
    local hum = getHum()
    if not char or char.Parent == nil then
        return true
    end
    if not hum or hum.Parent == nil then
        return true
    end
    if (tonumber(hum.Health) or 0) <= 0 then
        return true
    end
    return humState(hum) == Enum.HumanoidStateType.Dead
end

local function floorUnder(hrp, distDown)
    if not hrp then
        return nil
    end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local char = getChar()
    params.FilterDescendantsInstances = char and { char } or {}
    local hit = workspace:Raycast(
        hrp.Position + Vector3.new(0, 3, 0),
        Vector3.new(0, -(tonumber(distDown) or 56), 0),
        params
    )
    if hit and hit.Instance and hit.Instance.CanCollide == true then
        return hit
    end
    return nil
end

-- Alive + not falling through void. Freefall above a floor (jump) is OK.
function M.IsPlayable()
    if M.IsDead() then
        return false
    end
    local hrp = getHRP()
    local hum = getHum()
    if not hrp or not hum then
        return false
    end
    local st = humState(hum)
    if st == Enum.HumanoidStateType.Dead then
        return false
    end
    if st == Enum.HumanoidStateType.Freefall or st == Enum.HumanoidStateType.FallingDown then
        -- Lab scramble Y ~-129. Jangan anggap void. Void beneran jauh di bawah.
        if hrp.Position.Y < 20 then
            return true
        end
        if hrp.Position.Y < 58 then
            return false
        end
    end
    return true
end

function M.WaitPlayable(shouldRun, timeout)
    local limit = tonumber(timeout) or 60
    local t0 = os.clock()
    while os.clock() - t0 < limit do
        if type(shouldRun) == "function" then
            local ok, v = pcall(shouldRun)
            if ok and v == false then
                return false
            end
        end
        if M.IsPlayable() then
            task.wait(0.12)
            if M.IsPlayable() then
                G.__StealEggDead = false
                return true
            end
        end
        task.wait(0.08)
    end
    return M.IsPlayable() == true
end

-- Setelah mati → spawn: lompat 1x (unstuck lantai / physics).
local spawnJumpPending = false
local spawnJumpBusy = false

function M.SpawnJumpOnce(char)
    if spawnJumpBusy == true then
        return true
    end
    if spawnJumpPending ~= true then
        return false
    end
    spawnJumpBusy = true
    spawnJumpPending = false
    char = char or getChar()
    local okJump = false
    pcall(function()
        if typeof(char) ~= "Instance" then
            return
        end
        local hum = char:FindFirstChildOfClass("Humanoid") or getHum()
        if not hum then
            pcall(function()
                hum = char:WaitForChild("Humanoid", 0.6)
            end)
        end
        local hrp = char:FindFirstChild("HumanoidRootPart") or getHRP()
        if not hrp then
            pcall(function()
                hrp = char:WaitForChild("HumanoidRootPart", 0.6)
            end)
        end
        if not hum or not hrp then
            return
        end
        if M.IsDead() then
            return
        end
        local y0 = hrp.Position.Y
        local st0 = humState(hum)
        -- Sudah berdiri di lantai: jangan tahan 3 detik lompat spawn.
        if y0 > 62 and y0 < 90
            and st0 ~= Enum.HumanoidStateType.Freefall
            and st0 ~= Enum.HumanoidStateType.FallingDown
            and st0 ~= Enum.HumanoidStateType.Dead
        then
            return
        end
        local t0 = os.clock()
        while os.clock() - t0 < 0.45 do
            if M.IsDead() then
                return
            end
            local st = humState(hum)
            if st == Enum.HumanoidStateType.Running
                or st == Enum.HumanoidStateType.RunningNoPhysics
                or st == Enum.HumanoidStateType.Landed then
                break
            end
            if hrp.Position.Y > 65
                and st ~= Enum.HumanoidStateType.Freefall
                and st ~= Enum.HumanoidStateType.FallingDown then
                break
            end
            task.wait(0.05)
        end
        if M.IsDead() then
            return
        end
        hum.Sit = false
        hum.PlatformStand = false
        hum.Jump = true
        hum:ChangeState(Enum.HumanoidStateType.Jumping)
        okJump = true
        dbg("LIFE", "spawn jump")
        task.wait(0.08)
        hum.Jump = false
        local tLand = os.clock()
        while os.clock() - tLand < 0.4 do
            if M.IsDead() then
                return
            end
            hrp = char:FindFirstChild("HumanoidRootPart") or getHRP() or hrp
            local st = humState(hum)
            local y = hrp and hrp.Position.Y or 0
            if (st == Enum.HumanoidStateType.Running or st == Enum.HumanoidStateType.Landed)
                and y > 62
                and y < 78 then
                break
            end
            task.wait(0.05)
        end
        pcall(function()
            if hrp then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end
        end)
        dbg("LIFE", "spawn landed")
    end)
    spawnJumpBusy = false
    return okJump
end

local function dist(a, b)
    local pa = typeof(a) == "CFrame" and a.Position or a
    local pb = typeof(b) == "CFrame" and b.Position or b
    if typeof(pa) ~= "Vector3" or typeof(pb) ~= "Vector3" then
        return math.huge
    end
    return (pa - pb).Magnitude
end

local function zeroVel(hrp)
    if not hrp then
        return
    end
    pcall(function()
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
end

local function setCf(hrp, cf)
    if not hrp or typeof(cf) ~= "CFrame" then
        return false
    end
    if travel then
        travel.want = cf.Position
    end
    local from = hrp.Position
    -- Mute HHT hanya Instant ragdoll snap egg. Hop 85 biasa harus kelihatan server.
    if typeof(from) == "Vector3" and typeof(cf) == "CFrame"
        and G.__StealEggInstantRagSnap == true
    then
        local jump = Vector3.new(cf.Position.X - from.X, 0, cf.Position.Z - from.Z).Magnitude
        if jump > 28 then
            local pulse = G.__StealEggPulseSnapMute
            if type(pulse) == "function" then
                pcall(pulse, 0.55)
            else
                G.__StealEggSnapMute = true
                task.delay(0.55, function()
                    G.__StealEggSnapMute = false
                end)
            end
        end
    end
    local ok = pcall(function()
        hrp.CFrame = cf
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
    return ok == true
end

local function stillRun(opts)
    if M.IsDead() then
        return false
    end
    if type(opts) == "table" then
        local want = opts.owner
        if want ~= nil then
            local d = G.StealEggDispatch
            if type(d) == "table" and type(d.Owner) == "function" then
                local who = d.Owner()
                if who ~= nil and who ~= want then
                    return false
                end
            end
        end
        if type(opts.shouldRun) == "function" then
            local ok, v = pcall(opts.shouldRun)
            if ok and v == false then
                return false
            end
        end
    end
    return true
end

local function liveGoalPos(opts, current)
    if type(opts) ~= "table" or type(opts.goalFn) ~= "function" then
        return current, true
    end
    local ok, g = pcall(opts.goalFn)
    if not ok or g == nil then
        return current, false
    end
    if typeof(g) == "CFrame" then
        return g.Position, true
    end
    if typeof(g) == "Vector3" then
        return g, true
    end
    return current, false
end

local function travelArrive(opts)
    local n = type(opts) == "table" and tonumber(opts.arrive)
    if n and n >= 1 then
        return n
    end
    return ARRIVE_OK
end

local function beltPadPos()
    local p = G.__StealEggPadPos
    if typeof(p) == "Vector3" then
        return p
    end
    local renders = workspace:FindFirstChild("__ClientTreadmillRenders")
    local root = renders and renders:FindFirstChild("Root", true)
    if root and root:IsA("BasePart") then
        p = root.Position
        G.__StealEggPadPos = p
        return p
    end
    return nil
end

-- Event: Workspace.AdminTreadmill di StartArea. Jangan pakai G.__StealEggPadPos (itu plot).
local function adminPadPos()
    local p = G.__StealEggAdminPadPos
    local hit = tonumber(G.__StealEggAdminPadHit) or 22
    if typeof(p) == "Vector3" then
        return p, hit
    end
    local inst = workspace:FindFirstChild("AdminTreadmill")
    if typeof(inst) ~= "Instance" then
        return nil, hit
    end
    if inst:IsA("BasePart") then
        p = inst.Position
        hit = math.max(inst.Size.X, inst.Size.Z) * 0.5 + 10
    else
        local ok, cf, size = pcall(function()
            return inst:GetBoundingBox()
        end)
        if ok and typeof(cf) == "CFrame" then
            p = cf.Position
            if typeof(size) == "Vector3" then
                hit = math.max(size.X, size.Z) * 0.5 + 10
            end
        else
            local part = inst:FindFirstChildWhichIsA("BasePart", true)
            if part and part:IsA("BasePart") then
                p = part.Position
                hit = math.max(part.Size.X, part.Size.Z) * 0.5 + 10
            end
        end
    end
    if typeof(p) == "Vector3" then
        G.__StealEggAdminPadPos = p
        G.__StealEggAdminPadHit = math.clamp(hit, 12, 20)
        return p, G.__StealEggAdminPadHit
    end
    return nil, hit
end

local function farmingBeltNow()
    if type(travel) == "table" and tostring(travel.reason or "") == "treadmill" then
        return true
    end
    local wild = G.StealEggWild
    return type(wild) == "table" and wild._farmingBelt == true
end

-- WASD lewat Humanoid selalu dipotong anti-cheat setelah skrip sempat
-- teleport/steal: WalkSpeed tetap ~210, perpindahan nyata ~20 (terukur).
-- Dorongan ini HANYA memakai kecepatan akun (SpeedPower → WalkSpeed),
-- bukan angka Move Speed UI. Move Speed tetap khusus GoTo.
M.manualBoost = false
local manualQuiet = false
local manualHB = nil
local manualGen = 0

local function manualClear()
    if manualQuiet ~= true then
        return
    end
    manualQuiet = false
    -- Jangan cabut flag kalau GoTo sedang memakai yang sama.
    if travel ~= nil then
        return
    end
    G.__StealEggMoveQuiet = false
    G.__StealEggTpHold = false
end

local function scriptOwnsBody()
    if travel ~= nil then
        return true
    end
    local d = G.StealEggDispatch
    if type(d) ~= "table" or type(d.Owner) ~= "function" then
        return false
    end
    local who = d.Owner()
    return who == "steal" or who == "claim" or who == "boss"
end

local function manualAssist()
    if M.manualBoost ~= true or scriptOwnsBody() == true then
        manualClear()
        return
    end
    local hum = getHum()
    local hrp = getHRP()
    if not hum or not hrp or (tonumber(hum.Health) or 0) <= 0 then
        manualClear()
        return
    end
    if hum.Sit == true or hum.SeatPart ~= nil or hrp.Anchored == true then
        manualClear()
        return
    end
    if farmingBeltNow() == true or G.__StealEggOnBelt == true then
        manualClear()
        return
    end
    local dir = hum.MoveDirection
    local flat = Vector3.new(dir.X, 0, dir.Z)
    if flat.Magnitude < 0.05 then
        manualClear()
        return
    end
    local st = hum:GetState()
    if st == Enum.HumanoidStateType.Freefall or st == Enum.HumanoidStateType.FallingDown then
        return
    end
    local want = tonumber(M.RealWalkSpeed()) or 16
    if want > ACCOUNT_MAX_WS then
        want = ACCOUNT_MAX_WS
    end
    if hrp.Position.Y > 90 then
        want = math.min(want, 32)
    end
    if want <= 8 then
        manualClear()
        return
    end
    if manualQuiet ~= true then
        manualQuiet = true
        -- Tanpa hook dulu, velocity 800+ langsung dibunuh anti-cheat (terukur).
        pcall(M.ArmIntegrity)
        G.__StealEggMoveQuiet = true
        G.__StealEggTpHold = true
    end
    flat = flat.Unit
    pcall(function()
        local vy = hrp.AssemblyLinearVelocity.Y
        hrp.AssemblyLinearVelocity = Vector3.new(flat.X * want, vy, flat.Z * want)
    end)
end

function M.SetManualBoost(on)
    M.manualBoost = on ~= false
    if M.manualBoost ~= true then
        manualClear()
    end
    return M.manualBoost
end

function M.StartManualBoost()
    manualGen += 1
    local my = manualGen
    if manualHB then
        pcall(function()
            manualHB:Disconnect()
        end)
        manualHB = nil
    end
    manualHB = RunService.Heartbeat:Connect(function()
        if manualGen ~= my then
            return
        end
        manualAssist()
    end)
    return manualHB
end

-- Farm boleh injek pad tujuan. Steal / hub: jangan.
local function wantThisPad(pad, hit)
    if type(travel) ~= "table" or tostring(travel.reason or "") ~= "treadmill" then
        return false
    end
    local w = travel.want
    if typeof(w) ~= "Vector3" or typeof(pad) ~= "Vector3" then
        return false
    end
    return Vector3.new(w.X - pad.X, 0, w.Z - pad.Z).Magnitude <= (tonumber(hit) or 16) + 8
end

local function travelTick(opts)
    if type(opts) == "table" and type(opts.onTick) == "function" then
        pcall(opts.onTick)
    end
    local hrp = getHRP()
    local pos = hrp and hrp.Position
    -- Hanya mesh admin (~10st). Jangan Y>74: plot/home Y=74–76 jadi Physics (log: terbang + stuck).
    -- Jangan unstick plot treadmill: pulang lewat pad sendiri.
    local ap, ah = adminPadPos()
    local onPad = false
    if typeof(pos) == "Vector3" and typeof(ap) == "Vector3" then
        onPad = Vector3.new(pos.X - ap.X, 0, pos.Z - ap.Z).Magnitude <= 10
    end
    -- Slam Y>90 cuma anti-launch treadmill. Saat steal/carry/scramble,
    -- ragdoll/telur melempar ke atas — CFrame lantai + vy=-16 + AskDoff
    -- tiap tick = freeze + CPU spike (integrity traceback).
    local stealBusy = G.__StealEggFarOn == true
        or G.__StealEggBusy == true
        or G.__StealEggClaiming == true
        or G.__StealEggDecoyOn == true
    local launched = knockAirborne(hrp, getHum())
    if stealBusy ~= true and launched ~= true and farmingBeltNow() ~= true and hrp and typeof(pos) == "Vector3" then
        if onPad == true or pos.Y > 90 then
            pcall(function()
                local vel = hrp.AssemblyLinearVelocity
                local vy = math.min(vel.Y, 0)
                if pos.Y > 90 then
                    vy = -16
                end
                hrp.AssemblyLinearVelocity = Vector3.new(vel.X, vy, vel.Z)
            end)
        end
        if pos.Y > 95 then
            local wild = G.StealEggWild
            if type(wild) == "table" and type(wild.kickOffBelt) == "function" then
                pcall(wild.kickOffBelt)
                dbg("BELT", "launch Y=" .. string.format("%.1f", pos.Y))
            end
        end
    end
    if farmingBeltNow() == true then
        if typeof(ap) == "Vector3" and wantThisPad(ap, ah) then
            return
        end
        local pad = beltPadPos()
        if typeof(pad) == "Vector3" and wantThisPad(pad, 16) then
            return
        end
    end
    local stuck = G.__StealEggOnBelt == true and farmingBeltNow() ~= true
    if stuck ~= true then
        stuck = onPad == true and wantThisPad(ap, ah) ~= true
    end
    if stuck ~= true then
        return
    end
    local t = os.clock()
    if t - (tonumber(M._lastPadDoff) or 0) < 0.2 then
        return
    end
    M._lastPadDoff = t
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.kickOffBelt) == "function" then
        pcall(wild.kickOffBelt)
        dbg("BELT", "move unstick pad reason=" .. tostring(travel and travel.reason or "-"))
    end
    pcall(function()
        if hrp then
            local vel = hrp.AssemblyLinearVelocity
            hrp.AssemblyLinearVelocity = Vector3.new(vel.X, math.min(vel.Y, 0), vel.Z)
        end
    end)
end

-- Game auto AskWearStill kalau ray 8 stud ke bawah kena TreadmillBottom.
-- Jangan lintas pad. Kalau sudah injek: belok ke samping (bukan jump).
-- Admin treadmill di StartArea: belok Z, jangan T-plot slide (pad di jalan).
local function padAvoid(from, dest)
    if typeof(from) ~= "Vector3" or typeof(dest) ~= "Vector3" then
        return dest
    end
    local onBelt = G.__StealEggOnBelt == true
    local function avoidOne(pad, hit, isAdmin)
        if typeof(pad) ~= "Vector3" then
            return dest
        end
        if wantThisPad(pad, hit) then
            return dest
        end
        local keep = math.max((tonumber(hit) or 16) + 8, 22)
        local function sideOf(p)
            if isAdmin == true then
                -- Jalan Z~-363. dest.Z home/plot (~-166) jangan dipakai — itu nembus yard.
                local roadZ = from.Z
                if math.abs(dest.Z - p.Z) < 40 then
                    roadZ = dest.Z
                end
                local east = Vector3.new(p.X + keep, dest.Y, roadZ)
                local west = Vector3.new(p.X - keep, dest.Y, roadZ)
                if math.abs(dest.X - east.X) <= math.abs(dest.X - west.X) then
                    return east
                end
                return west
            end
            local to = Vector3.new(dest.X - from.X, 0, dest.Z - from.Z)
            local right = Vector3.new(-to.Z, 0, to.X)
            if right.Magnitude < 0.08 then
                right = Vector3.new(from.X - p.X, 0, from.Z - p.Z)
            end
            if right.Magnitude < 0.08 then
                right = Vector3.new(1, 0, 0)
            else
                right = right.Unit
            end
            local a = Vector3.new(p.X + right.X * keep, dest.Y, p.Z + right.Z * keep)
            local b = Vector3.new(p.X - right.X * keep, dest.Y, p.Z - right.Z * keep)
            local da = (from.X - a.X) * (from.X - a.X) + (from.Z - a.Z) * (from.Z - a.Z)
            local db = (from.X - b.X) * (from.X - b.X) + (from.Z - b.Z) * (from.Z - b.Z)
            if da <= db then
                return a
            end
            return b
        end
        local dFrom = Vector3.new(from.X - pad.X, 0, from.Z - pad.Z).Magnitude
        if isAdmin == true and math.abs(from.Z - pad.Z) > 50 and math.abs(dest.Z - pad.Z) > 50 then
            return dest
        end
        local roadish = isAdmin == true or math.abs(from.Z - pad.Z) < 30
        if onBelt == true or dFrom <= hit then
            if roadish then
                return sideOf(pad)
            end
            local dz = dest.Z - from.Z
            if math.abs(dz) > 18 then
                local sign = dz >= 0 and 1 or -1
                return Vector3.new(from.X, dest.Y, pad.Z + sign * keep)
            end
            return sideOf(pad)
        end
        local abx = dest.X - from.X
        local abz = dest.Z - from.Z
        local ab2 = abx * abx + abz * abz
        local t = 0
        if ab2 > 1e-4 then
            t = math.clamp(((pad.X - from.X) * abx + (pad.Z - from.Z) * abz) / ab2, 0, 1)
        end
        local cx = from.X + abx * t
        local cz = from.Z + abz * t
        local dSeg = math.sqrt((pad.X - cx) * (pad.X - cx) + (pad.Z - cz) * (pad.Z - cz))
        if dSeg <= hit then
            if roadish then
                return sideOf(pad)
            end
            local dz = dest.Z - from.Z
            if math.abs(dz) > 18 then
                local sign = dz >= 0 and 1 or -1
                return Vector3.new(from.X, dest.Y, pad.Z + sign * keep)
            end
            return sideOf(pad)
        end
        return dest
    end
    local ap, ah = adminPadPos()
    dest = avoidOne(ap, ah, true)
    local skipPlotPad = farmingBeltNow() == true
        or (type(travel) == "table" and tostring(travel.reason or "") == "home")
        or G.__StealEggClaiming == true
    if skipPlotPad ~= true then
        dest = avoidOne(beltPadPos(), 16, false)
    end
    if onBelt == true and typeof(ap) ~= "Vector3" and typeof(beltPadPos()) ~= "Vector3" then
        dest = avoidOne(from, 16, true)
    end
    return dest
end

-- opts.steer(from, dest) → Vector3 aim. Arrival tetap ke dest asli.
-- Gate dulu pakai dest asli (egg/hub), baru hindari pad. Unstick T-plot: Z ke jalan, bukan X ke tembok.
local function steerAim(from, dest, opts)
    if typeof(from) ~= "Vector3" or typeof(dest) ~= "Vector3" then
        return dest
    end
    local raw = dest
    local aim = dest
    if type(opts) == "table" and type(opts.steer) == "function" then
        local ok, v = pcall(opts.steer, from, raw)
        if ok and typeof(v) == "Vector3" then
            aim = v
        end
    end
    aim = padAvoid(from, aim)
    if type(travel) == "table" then
        local mag = Vector3.new(raw.X - from.X, 0, raw.Z - from.Z).Magnitude
        local sp = travel.stallPos
        if typeof(sp) ~= "Vector3" or Vector3.new(from.X - sp.X, 0, from.Z - sp.Z).Magnitude > 5 then
            travel.stallPos = from
            travel.stallAt = os.clock()
        elseif mag > 12 and (os.clock() - (travel.stallAt or 0)) > 0.55
            and not (type(opts) == "table"
                and (opts.reason == "egg" or opts.reason == "home")
                and (opts.mode == "walk" or opts.mode == "glide"
                    or opts.uiMode == "walk" or opts.uiMode == "glide"))
        then
            if travel.rubberAt and (os.clock() - travel.rubberAt) < 1.2 then
                return aim
            end
            local zGap = math.abs(from.Z - raw.Z)
            local xGap = math.abs(from.X - raw.X)
            -- Off-road: naik/turun ke jalan dulu. Geser X di tembok = nabrak 9s (log: 549,-446).
            if zGap > 24 then
                local signZ = raw.Z >= from.Z and 1 or -1
                aim = Vector3.new(from.X, aim.Y, from.Z + 40 * signZ)
            elseif xGap > 14 then
                local sign = raw.X >= from.X and 1 or -1
                aim = Vector3.new(from.X + 40 * sign, aim.Y, from.Z)
            elseif xGap > 6 then
                aim = Vector3.new(from.X, aim.Y, aim.Z)
            else
                aim = Vector3.new(from.X, aim.Y, raw.Z)
            end
            travel.stallPos = from
            travel.stallAt = os.clock()
            travel.unstickN = (tonumber(travel.unstickN) or 0) + 1
            if travel.unstickN >= 4 then
                travel.stuck = true
            end
            dbg("MOVE", "unstick slide")
        end
    end
    return aim
end

local function releasePose(hrp, hum, wasAnchored)
    zeroVel(hrp)
    pcall(function()
        if hrp then
            hrp.Anchored = wasAnchored == true
        end
        if hum then
            if keepRagdoll() ~= true then
                hum.PlatformStand = false
            end
            hum.AutoRotate = true
        end
    end)
    zeroVel(hrp)
end

-- dump_full ArcModel.Step: kalau IsSupported, Reason=nil. Kalau Flight/VerticalRise
-- PreferredTarget = StartSample → karakter ditarik balik ke awal glide.
-- Live floor is around Y -364, not hub-era 70.7. Ray from current Y, far down.
-- Never snap a deep map onto GLIDE_LAND_Y — that poses the character in the sky.
local function floorStandY(hrp, hum, x, z, fallbackY, opts)
    local forcedY = type(opts) == "table" and tonumber(opts.landY)
    if forcedY ~= nil then
        return forcedY, true
    end
    local yNow = hrp and tonumber(hrp.Position.Y)
    fallbackY = tonumber(fallbackY) or yNow or GLIDE_LAND_Y
    do
        local last = M._floor
        if type(last) == "table"
            and math.abs((tonumber(last.x) or 0) - x) < 8
            and math.abs((tonumber(last.z) or 0) - z) < 8
            and (os.clock() - (tonumber(last.at) or 0)) < 0.12
        then
            return last.y, last.ok == true
        end
    end
    if yNow and yNow < 20 then
        fallbackY = yNow
    end
    local char = getChar()
    local ex = {}
    if char then
        ex[#ex + 1] = char
    end
    if type(opts) == "table" then
        if typeof(opts.excludeRay) == "Instance" then
            ex[#ex + 1] = opts.excludeRay
        elseif type(opts.excludeRay) == "table" then
            for _, inst in ipairs(opts.excludeRay) do
                if typeof(inst) == "Instance" then
                    ex[#ex + 1] = inst
                end
            end
        end
    end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = ex
    local fromY = (yNow or fallbackY) + 12
    local hit = workspace:Raycast(Vector3.new(x, fromY, z), Vector3.new(0, -420, 0), params)
    if not hit then
        hit = workspace:Raycast(Vector3.new(x, fromY + 80, z), Vector3.new(0, -520, 0), params)
    end
    local function remember(y, ok)
        M._floor = { x = x, z = z, y = y, ok = ok == true, at = os.clock() }
        return y, ok == true
    end
    if not hit or not hit.Instance or hit.Instance.CanCollide ~= true then
        return remember(fallbackY, false)
    end
    local hip = (hum and tonumber(hum.HipHeight)) or 2
    local half = (hrp and hrp.Size.Y * 0.5) or 1
    local y = hit.Position.Y + hip + half
    if yNow and math.abs(y - yNow) > 8 then
        return remember(yNow, false)
    end
    if math.abs(y - fallbackY) > 18 then
        return remember(fallbackY, false)
    end
    return remember(y, true)
end

-- BigFroot/Speed: CFrame XZ 600/s, Y lantai, Running, WS tinggi, tanpa noclip.
-- Node noclip + Y 70.5 di dalam part + WS 16 → VerticalTrajectory Reset → balik plot.
local function goGlide(goalCf, speed, opts)
    local hrp = getHRP()
    local hum = getHum()
    if not hrp then
        dbg("GOTO", "glide no_char")
        return false, "no_char"
    end
    opts = type(opts) == "table" and opts or {}
    speed = tonumber(speed) or M.speed or GLIDE_DEFAULT_SPEED
    if speed < 8 then
        speed = 8
    end
    local myGen = gen
    local goal = goalCf.Position
    local holdY = floorStandY(hrp, hum, hrp.Position.X, hrp.Position.Z, hrp.Position.Y, opts)
    local nativeWs = opts.nativeWalkSpeed == true
    local oldWs = hum and tonumber(hum.WalkSpeed) or 16
    if isInflatedWs(oldWs) then
        oldWs = tonumber(M.RealWalkSpeed()) or oldWs
    end
    savedWalkSpeed = oldWs
    -- Glide steal: WalkSpeed = angka Speed (MaxEarn 900). Bukan WS akun —
    -- CFrame 900 + WS 257 = Relocate.
    local keepWs = math.clamp(speed, 16, 1500)
    if nativeWs == true then
        keepWs = tonumber((type(M.RealWalkSpeed) == "function" and M.RealWalkSpeed()) or nil) or oldWs
        if keepWs < 16 then
            keepWs = math.max(oldWs, 16)
        end
    end

    pcall(function()
        if hum then
            hum.Sit = false
            hum.AutoRotate = true
            hum.WalkSpeed = keepWs or (tonumber(M.RealWalkSpeed()) or 16)
            if keepRagdoll() == true then
                hum.PlatformStand = true
            else
                hum.PlatformStand = false
                pcall(function()
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
        end
        hrp.Anchored = false
    end)
    zeroVel(hrp)

    local function xzMag(p)
        return Vector3.new(goal.X - p.X, 0, goal.Z - p.Z).Magnitude
    end

    local function waitHrp()
        local tWait = os.clock()
        while os.clock() - tWait < 2.5 do
            if gen ~= myGen or not stillRun(opts) then
                return nil
            end
            local r = getHRP()
            if r then
                pcall(function()
                    r.Anchored = false
                end)
                return r
            end
            task.wait(0.05)
        end
        return getHRP()
    end

    local function poseAt(root, dest)
        local rot = root.CFrame - root.CFrame.Position
        setCf(root, CFrame.new(dest) * rot)
    end

    local function restoreWs()
        if gen ~= myGen then
            return
        end
        pcall(function()
            local h = getHum()
            if h then
                local real = tonumber((type(M.RealWalkSpeed) == "function" and M.RealWalkSpeed()) or nil)
                local back = real
                if not back or back < 16 then
                    back = (oldWs and oldWs >= 16 and isInflatedWs(oldWs) ~= true) and oldWs or 16
                elseif oldWs and isInflatedWs(oldWs) ~= true and oldWs > back then
                    back = oldWs
                end
                h.WalkSpeed = back
            end
        end)
        savedWalkSpeed = nil
    end

    local arrive = travelArrive(opts)
    if type(arrive) ~= "number" then
        arrive = ARRIVE_OK
    end

    local function landAt(ok, msg)
        if M.IsDead() then
            restoreWs()
            return false, "dead"
        end
        hrp = getHRP()
        pcall(function()
            local h = getHum()
            local r = hrp or getHRP()
            if eggSlip(opts) then
                slipFromEgg(h, r, speed)
                return
            end
            if h then
                h:Move(Vector3.zero, false)
                if r then
                    h:MoveTo(r.Position)
                end
            end
            if r then
                r.Anchored = false
                local vy = r.AssemblyLinearVelocity.Y
                r.AssemblyLinearVelocity = Vector3.new(0, vy, 0)
                r.AssemblyAngularVelocity = Vector3.zero
            end
        end)
        restoreWs()
        return ok, msg
    end
    local hold = opts.hold == true
    if (not hold) and hrp and xzMag(hrp.Position) <= arrive then
        return landAt(true, "arrive")
    end

    local d0 = hrp and xzMag(hrp.Position) or 200
    local timeout = math.clamp((d0 / math.max(speed, 40)) + 12, 8, GLIDE_MAX_SEC)
    if hold then
        timeout = tonumber(opts.timeout) or math.max(timeout, 16)
    end
    local t0 = os.clock()
    local lastWant = nil
    -- Instant (FAR/claim): resep MaxEarn di semua fps —
    --  · dt nyata, hop = min(speed×dt, INSTANT_HOP_CAP), velocity 0.
    --  · Speed = angka UI; yang dibatasi hanya jarak per frame.
    --  · frame pertama langsung melangkah (tanpa tunggu Heartbeat): guard
    --    bangun 0.63 s, di 5 fps satu frame = 0.2 s.
    --  · FPS rendah: steer dibatasi ±20° (hop besar + belok tajam = tembok).
    -- Instant hop 85 hanya FAR/teleport. Window Impulse walk/glide bukan hop —
    -- isWindow() true malah bikin glide loncat 85 st/frame + drift.
    local instant = G.__StealEggFarOn == true or G.__StealEggClaiming == true
        or (opts.legalHop == true and G.__StealEggFarOn == true)
    local firstStep = instant

    while os.clock() - t0 < timeout do
        if gen ~= myGen or not stillRun(opts) then
            break
        end
        if travel and travel.stuck == true then
            restoreWs()
            return false, "stuck"
        end
        if M.IsDead() then
            dbg("GOTO", "glide dead")
            restoreWs()
            return false, "dead"
        end
        hrp = getHRP() or waitHrp()
        if not hrp then
            dbg("GOTO", "glide lost_hrp")
            break
        end
        hum = getHum()
        -- Setelah bait Forest: ragdoll = jendela gerak. Jangan diam nunggu mendarat.
        if opts.throughRagdoll ~= true and knockAirborne(hrp, hum) then
            lastWant = nil
            RunService.Heartbeat:Wait()
            continue
        end
        if nativeWs == true then
            -- Jangan turunkan CFrame speed ke ResolveAutoSpeed (decoy butuh 750+ + WS native).
            if keepWs and hum then
                pcall(function()
                    hum.WalkSpeed = keepWs
                end)
            end
        end
        local okGoal
        goal, okGoal = liveGoalPos(opts, goal)
        if not okGoal then
            break
        end
        if travel then
            travel.want = goal
        end
        local pos = hrp.Position
        -- Instant: geseran fisika dari velocity bukan rubber → ambang 400.
        local yanked = lastWant and (pos - lastWant).Magnitude > (instant and 400 or 50)
        if yanked then
            dbg("RUBBER", string.format("want=%s got=%s d=%.0f", v3(lastWant), v3(pos), (pos - lastWant).Magnitude))
            lastWant = nil
            if travel then
                travel.rubberAt = os.clock()
            end
            if instant == true then
            zeroVel(hrp)
            pcall(function()
                hrp.Anchored = false
            end)
            local waitT = os.clock()
            local rubberWait = 0
            if opts.skipRubberWait ~= true then
                rubberWait = GLIDE_RUBBER_WAIT
            end
            while rubberWait > 0 and os.clock() - waitT < rubberWait do
                if gen ~= myGen or not stillRun(opts) then
                    restoreWs()
                    return false, "rubber_abort"
                end
                RunService.Heartbeat:Wait()
            end
            if rubberWait > 0 then
                t0 = t0 + (os.clock() - waitT)
            end
            end
        else
        local mag = xzMag(pos)
        if mag <= arrive then
            if hold then
                holdY = floorStandY(hrp, hum, goal.X, goal.Z, holdY, opts)
                local parked = Vector3.new(goal.X, holdY, goal.Z)
                poseAt(hrp, parked)
                lastWant = parked
                travelTick(opts)
                RunService.Heartbeat:Wait()
                continue
            else
                return landAt(true, "glide")
            end
        end
            local dt
            if firstStep then
                -- Langkah pertama di frame ini juga, pakai dt rata-rata terakhir.
                firstStep = false
                dt = tonumber(G.__StealEggDtEma) or 0.0167
            else
                dt = RunService.Heartbeat:Wait()
            end
            if typeof(dt) ~= "number" or dt <= 0 then
                dt = tonumber(G.__StealEggDtEma) or 0.0167
            elseif instant then
                -- Pakai dt nyata. Jangan ganti dt kecil jadi 0.0167
                -- (cap 0 / 300fps → gerak 5× + rubber).
                if dt > 0.34 then
                    dt = 0.34
                end
            else
                local spike = GLIDE_SPIKE_DT
                if instant or G.__StealEggBusy == true then
                    spike = 0.05
                end
                if dt > spike then
                    dt = spike
                end
            end
        if gen ~= myGen or not stillRun(opts) then
            break
        end
        hrp = getHRP() or waitHrp()
        if not hrp then
            dbg("GOTO", "glide lost_hrp after step")
            break
        end
        hum = getHum()
        goal, okGoal = liveGoalPos(opts, goal)
        if not okGoal then
            break
        end
        if travel then
            travel.want = goal
        end
        pos = hrp.Position
        mag = xzMag(pos)
        if mag <= arrive then
            if hold then
                holdY = floorStandY(hrp, hum, goal.X, goal.Z, holdY, opts)
                local parked = Vector3.new(goal.X, holdY, goal.Z)
                poseAt(hrp, parked)
                lastWant = parked
                travelTick(opts)
            else
                return landAt(true, "glide")
            end
        else
            local lowFps = instant and dt > 0.06
            local base = pos
            local aim = steerAim(base, goal, opts)
            local carryingNow = G.__StealEggClaiming == true
            do
                local c = G.__StealEggCarry
                if type(c) == "table" and c.IsCarrying == true then
                    carryingNow = true
                end
            end
            -- Teleport steal/pulang: jangan cap ±20° — itu yang bikin nabrak guard.
            local stealHop = carryingNow == true
                or G.__StealEggFarOn == true
                or G.__StealEggBusy == true
                or G.__StealEggStealFlow == true
            if lowFps and aim ~= goal and stealHop ~= true then
                -- Avoid Traps/Guards tetap jalan di FPS rendah, tapi sudut belok
                -- dibatasi ±20°: hop 146 st dengan belok tajam = geser samping
                -- puluhan stud → masuk tembok koridor (live 3265,-432).
                local dDir = Vector3.new(goal.X - base.X, 0, goal.Z - base.Z)
                local sDir = Vector3.new(aim.X - base.X, 0, aim.Z - base.Z)
                if dDir.Magnitude > 0.05 and sDir.Magnitude > 0.05 then
                    dDir = dDir.Unit
                    sDir = sDir.Unit
                    local cosA = math.clamp(dDir:Dot(sDir), -1, 1)
                    local maxA = math.rad(20)
                    if math.acos(cosA) > maxA then
                        local sign = (dDir.X * sDir.Z - dDir.Z * sDir.X) >= 0 and 1 or -1
                        local c, s = math.cos(maxA), math.sin(maxA) * sign
                        local lim = Vector3.new(dDir.X * c - dDir.Z * s, 0, dDir.X * s + dDir.Z * c)
                        aim = base + lim * math.max(mag, 1)
                    end
                end
            end
            local flat = Vector3.new(aim.X - base.X, 0, aim.Z - base.Z)
            if flat.Magnitude < 0.05 then
                flat = Vector3.new(goal.X - base.X, 0, goal.Z - base.Z)
                if flat.Magnitude < 0.05 then
                    if hold then
                        travelTick(opts)
                    else
                        return landAt(true, "glide")
                    end
                end
            end
            if flat.Magnitude >= 0.05 then
                local dir = flat.Unit
                local cap = speed
                if hold == true and mag < 48 then
                    cap = math.min(speed, 72)
                end
                local hopSafe = instantHopSafe(speed, dt)
                if instant then
                    -- Batas server = jarak per TICK, bukan speed. Hop ≤ hopSafe
                    -- di semua fps; speed UI dipakai penuh selama frame cukup.
                    cap = math.min(cap, hopSafe / dt)
                end
                -- maxStep ≈ 50ms worth: jaga stud/s di FPS rendah, blok lompatan spike.
                local maxStep = math.max(24, cap * GLIDE_STEP_DT)
                if instant then
                    maxStep = hopSafe
                end
                -- Sidestep: samping kecil, hop maju tetap hopSafe (jangan 28 st → 140 st/s).
                local aimDist = flat.Magnitude
                local step = math.min(cap * dt, mag, (hold == true and mag < 48) and 8 or maxStep, aimDist)
                do
                    local dDir = Vector3.new(goal.X - base.X, 0, goal.Z - base.Z)
                    if instant == true and dDir.Magnitude > 0.05 and step > 1 then
                        dDir = dDir.Unit
                        local latV = dir * step - dDir * (dir:Dot(dDir) * step)
                        local latCap = dt > 0.06 and 12 or 22
                        if latV.Magnitude > latCap then
                            latV = latV.Unit * latCap
                            local move = dDir * step + latV
                            if move.Magnitude > 0.05 then
                                dir = move.Unit
                            end
                        end
                    end
                end
                local nx = base.X + dir.X * step
                local nz = base.Z + dir.Z * step
                local ny, okFloor = floorStandY(hrp, hum, nx, nz, holdY, opts)
                if okFloor == true then
                    holdY = ny
                end
                local dest = Vector3.new(nx, holdY, nz)
                pcall(function()
                    hrp.Anchored = false
                    if hum then
                        hum.WalkSpeed = keepWs or (tonumber(M.RealWalkSpeed()) or 16)
                        if keepRagdoll() ~= true then
                            hum.PlatformStand = false
                        end
                    end
                end)
                -- Velocity SELALU 0 (poseAt/setCf sudah men-nol-kan). Semua
                -- kasus bersih (Manual 300, 60fps 941, MaxEarn hop 48) velocity 0;
                -- velocity dilaporkan 675 @15fps = rubber (live).
                poseAt(hrp, dest)
                lastWant = dest
                travelTick(opts)
            end
        end
        end
    end

    if M.IsDead() then
        restoreWs()
        dbg("GOTO", "glide dead")
        return false, "dead"
    end
    if gen ~= myGen then
        dbg("GOTO", "glide abort gen")
    elseif stillRun(opts) ~= true then
        dbg("GOTO", "glide abort shouldRun")
    end
    restoreWs()
    hrp = getHRP()
    if hrp and xzMag(hrp.Position) <= (arrive + 10) then
        return landAt(true, "glide")
    end
    return false, "not_arrive"
end

    -- Walk: MoveTo + angka Speed. Glide: geser, bukan disamakan jadi walk.
local function walkUiSpeed(opts)
    opts = type(opts) == "table" and opts or {}
    local n = tonumber(opts.speed)
    if not n or n < 8 then
        n = tonumber(M.WantWalkSpeed()) or tonumber(M.speed) or 16
    end
    -- Jangan kali SpeedMultiplier. Server sudah memotong jatah
    -- (WalkSpeed * SpeedMultiplier). Kali lagi = pulang lebih pelan
    -- dari Max Earn, guard menyalip.
    return math.clamp(n, 16, 1500)
end

local function goWalk(goalCf, speed, opts)
    local hrp = getHRP()
    local hum = getHum()
    if not hrp or not hum then
        return false, "no_char"
    end
    opts = type(opts) == "table" and opts or {}
    local want = walkUiSpeed(opts)
    if tonumber(speed) and tonumber(speed) >= 8 then
        want = math.clamp(tonumber(speed), 16, 1500)
    end
    speed = want
    local goal = goalCf.Position
    local myGen = gen
    local accountWs = tonumber(M.RealWalkSpeed()) or 16
    if accountWs < 16 then
        accountWs = 16
    end
    local oldWs = tonumber(hum.WalkSpeed) or accountWs
    if isInflatedWs(oldWs) then
        oldWs = accountWs
    end
    savedWalkSpeed = oldWs

    pcall(function()
        hum.Sit = false
        hum.AutoRotate = true
        hum.PlatformStand = false
        hum.WalkSpeed = speed
        hrp.Anchored = false
    end)

    local function restoreWs()
        if gen ~= myGen then
            return
        end
        pcall(function()
            local h = getHum()
            local r = getHRP()
            if h then
                local real = tonumber((type(M.RealWalkSpeed) == "function" and M.RealWalkSpeed()) or nil)
                local back = real
                if not back or back < 16 then
                    back = (oldWs and oldWs >= 16 and isInflatedWs(oldWs) ~= true) and oldWs or 16
                elseif oldWs and oldWs >= 16 and isInflatedWs(oldWs) ~= true and oldWs > back then
                    back = oldWs
                end
                if eggSlip(opts) then
                    slipFromEgg(h, r, speed)
                    return
                end
                h:Move(Vector3.zero, false)
                if r then
                    h:MoveTo(r.Position)
                end
                h.WalkSpeed = back
            end
            if r then
                local v = r.AssemblyLinearVelocity
                r.AssemblyLinearVelocity = Vector3.new(0, v.Y, 0)
                r.AssemblyAngularVelocity = Vector3.zero
            end
        end)
        savedWalkSpeed = nil
    end

    local function xzMag()
        hrp = getHRP()
        if not hrp then
            return math.huge, nil
        end
        local p = hrp.Position
        return Vector3.new(goal.X - p.X, 0, goal.Z - p.Z).Magnitude, p
    end

    local arrive = travelArrive(opts)
    local hold = opts.hold == true
    local finished = false
    local mag0 = xzMag()
    if (not hold) and mag0 <= arrive then
        restoreWs()
        return true, "arrive"
    end

    local timeout = math.clamp((mag0 / math.max(speed, 8)) + 8, 8, 45)
    if hold then
        timeout = tonumber(opts.timeout) or math.max(timeout, 16)
    end
    local t0 = os.clock()
    local lastMag = mag0

    while os.clock() - t0 < timeout do
        if gen ~= myGen or not stillRun(opts) then
            break
        end
        if travel and travel.stuck == true then
            restoreWs()
            return false, "stuck"
        end
        if M.IsDead() then
            restoreWs()
            return false, "dead"
        end
        local okGoal
        goal, okGoal = liveGoalPos(opts, goal)
        if not okGoal then
            break
        end
        if travel then
            travel.want = goal
        end
        local mag, pos = xzMag()
        if not pos then
            break
        end
        if lastMag and mag > lastMag + 120 then
            dbg("RUBBER", string.format("walk yank mag=%.0f→%.0f", lastMag, mag))
            lastMag = mag
        end
        -- Lewat tujuan (WS tinggi): jangan putar balik.
        if mag < 22 and lastMag < 28 and mag > lastMag + 0.8 then
            restoreWs()
            if mag <= math.max(arrive * 5, 12) then
                return true, "walk"
            end
            return false, "overshoot"
        end
        lastMag = mag
        if mag <= arrive then
            if hold then
                travelTick(opts)
            else
                finished = true
                break
            end
        end
        hrp = getHRP()
        hum = getHum()
        if not hrp or not hum then
            break
        end
        RunService.Heartbeat:Wait()
        goal, okGoal = liveGoalPos(opts, goal)
        if not okGoal then
            break
        end
        mag, pos = xzMag()
        if not pos then
            break
        end
        if lastMag and mag > lastMag + 120 then
            dbg("RUBBER", string.format("walk yank mag=%.0f→%.0f", lastMag, mag))
            lastMag = mag
        end
        lastMag = mag
        if mag <= arrive then
            if hold then
                travelTick(opts)
            else
                finished = true
                break
            end
        end
        travelTick(opts)
        local aim = steerAim(pos, goal, opts)
        local useSpeed = speed
        local toGoal = Vector3.new(goal.X - pos.X, 0, goal.Z - pos.Z)
        local toAim = Vector3.new(aim.X - pos.X, 0, aim.Z - pos.Z)
        if toGoal.Magnitude > 8 and toAim.Magnitude < toGoal.Magnitude * 0.98 then
            local g = toGoal.Unit
            local lat = toAim - g * g:Dot(toAim)
            if lat.Magnitude > 80 then
                lat = lat.Unit * 80
            end
            local far = pos + g * toGoal.Magnitude + lat
            aim = Vector3.new(far.X, pos.Y, far.Z)
        end
        local aimAt = Vector3.new(aim.X, hrp.Position.Y, aim.Z)
        pcall(function()
            hrp.Anchored = false
            hum.WalkSpeed = useSpeed
            local st = hum:GetState()
            if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll then
                return
            end
            hum:MoveTo(aimAt)
        end)
        if travel then
            travel.want = Vector3.new(aim.X, hrp.Position.Y, aim.Z)
        end
        if hold then
            travelTick(opts)
        end
    end

    restoreWs()

    hrp = getHRP()
    if finished or (hrp and Vector3.new(hrp.Position.X - goal.X, 0, hrp.Position.Z - goal.Z).Magnitude <= (arrive + 4)) then
        return true, "walk"
    end
    return false, "not_arrive"
end

local function setTpHold(on)
    G.__StealEggTpHold = on == true
end

-- Separate from glide/walk. Default: hop 72st along road (long PivotTo can void on MuMu).
-- longSnap (egg/home steal): one big CFrame jump like Speed Hub / StealFix recipe.
-- HHT soft-quiet: TpHold (teleport) + MoveQuiet (semua mode GoTo). Keep Y on loaded floor.
local TP_HOP = 35
local TP_HOP_WAIT = 0.07
local TP_MAX_SEC = 22

local function goTeleport(goalCf, _speed, opts)
    local hrp = getHRP()
    local hum = getHum()
    if not hrp then
        dbg("GOTO", "teleport no_char")
        return false, "no_char"
    end
    opts = type(opts) == "table" and opts or {}
    local longSnap = opts.longSnap == true
    local keepAnchored = opts.keepAnchored == true
    local hopMax = tonumber(opts.hopMax)
    if hopMax == nil or hopMax <= 0 then
        hopMax = longSnap and 1e9 or TP_HOP
    end
    local hopWait = tonumber(opts.hopWait)
    if hopWait == nil or hopWait < 0 then
        hopWait = longSnap and 0.02 or TP_HOP_WAIT
    end
    setTpHold(true)
    -- Skip getgc saat FAR/decoy (sudah armed).
    if G.__StealEggFarOn ~= true and G.__StealEggDecoyOn ~= true then
        pcall(M.ArmIntegrity)
    elseif G.__StealEggVtQuiet ~= true or (G.__StealEggHhtOff ~= true and G.__StealEggHhtQuiet ~= true) then
        pcall(M.ArmIntegrity)
    end
    local myGen = gen
    local goal = goalCf.Position
    local arrive = travelArrive(opts)
    if type(arrive) ~= "number" then
        arrive = ARRIVE_OK
    end
    local t0 = os.clock()

    local function xzMag(p, dest)
        dest = dest or goal
        return Vector3.new(dest.X - p.X, 0, dest.Z - p.Z).Magnitude
    end

    local function hopY(x, z, yNow)
        local forcedY = tonumber(opts.landY)
        if forcedY ~= nil then
            return forcedY
        end
        yNow = tonumber(yNow) or GLIDE_LAND_Y
        local char = getChar()
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local ex = { char }
        if typeof(opts.excludeRay) == "Instance" then
            ex[#ex + 1] = opts.excludeRay
        elseif type(opts.excludeRay) == "table" then
            for _, inst in ipairs(opts.excludeRay) do
                if typeof(inst) == "Instance" then
                    ex[#ex + 1] = inst
                end
            end
        end
        params.FilterDescendantsInstances = ex
        local hit = workspace:Raycast(Vector3.new(x, yNow + 10, z), Vector3.new(0, -36, 0), params)
        if not hit or not hit.Instance or hit.Instance.CanCollide ~= true then
            return yNow
        end
        local hip = (hum and tonumber(hum.HipHeight)) or 2
        local half = (hrp and hrp.Size.Y * 0.5) or 1
        local y = hit.Position.Y + hip + half
        if math.abs(y - yNow) > 10 then
            return yNow
        end
        return y
    end

    local function snapTo(x, z)
        hrp = getHRP()
        hum = getHum()
        if not hrp then
            return false
        end
        local y = hopY(x, z, hrp.Position.Y)
        pcall(function()
            if hum then
                hum.Sit = false
                if keepRagdoll() ~= true then
                    hum.PlatformStand = false
                end
            end
            -- Home-freeze steal: tetap Anchored supaya physics tidak jatuh saat big snap.
            hrp.Anchored = keepAnchored == true
        end)
        local rot = hrp.CFrame - hrp.CFrame.Position
        setCf(hrp, CFrame.new(x, y, z) * rot)
        zeroVel(hrp)
        if keepAnchored == true then
            pcall(function()
                hrp.Anchored = true
            end)
        end
        return true
    end

    local function done()
        if gen ~= myGen then
            return
        end
        setTpHold(false)
    end

    if M.IsDead() then
        done()
        return false, "dead"
    end

    while os.clock() - t0 < TP_MAX_SEC do
        if gen ~= myGen or not stillRun(opts) then
            done()
            return false, "cancelled"
        end
        if M.IsDead() then
            done()
            return false, "dead"
        end
        local okGoal
        goal, okGoal = liveGoalPos(opts, goal)
        if not okGoal then
            break
        end
        hrp = getHRP()
        if not hrp then
            break
        end
        local from = hrp.Position
        local dEgg = xzMag(from)
        if dEgg <= arrive then
            travelTick(opts)
            local settleT = os.clock()
            -- Boss hop: skipLandWait → settle singkat (0.35s tiap goTo bikin lambat).
            local settleNeed = longSnap and 0.06 or 0.35
            if opts.skipLandWait == true then
                settleNeed = 0.05
            end
            while os.clock() - settleT < settleNeed do
                if gen ~= myGen or not stillRun(opts) then
                    break
                end
                if opts.hold == true then
                    goal, okGoal = liveGoalPos(opts, goal)
                    if okGoal then
                        snapTo(goal.X, goal.Z)
                    end
                end
                travelTick(opts)
                RunService.Heartbeat:Wait()
            end
            if opts.hold == true then
                local holdT = tonumber(opts.timeout) or 8
                local tHold = os.clock()
                while os.clock() - tHold < holdT do
                    if gen ~= myGen or not stillRun(opts) then
                        break
                    end
                    goal, okGoal = liveGoalPos(opts, goal)
                    if okGoal then
                        snapTo(goal.X, goal.Z)
                    end
                    travelTick(opts)
                    RunService.Heartbeat:Wait()
                end
            end
            done()
            return true, "teleport"
        end

        local aim = goal
        if longSnap ~= true and type(opts.steer) == "function" then
            local ok, v = pcall(opts.steer, from, goal)
            if ok and typeof(v) == "Vector3" then
                aim = v
            end
        end
        if longSnap ~= true then
            aim = padAvoid(from, aim)
        end
        local dx = aim.X - from.X
        local dz = aim.Z - from.Z
        local step = Vector3.new(dx, 0, dz).Magnitude
        if step > hopMax then
            local k = hopMax / step
            aim = Vector3.new(from.X + dx * k, from.Y, from.Z + dz * k)
        elseif step < 0.4 then
            aim = Vector3.new(goal.X, from.Y, goal.Z)
        end
        if travel then
            travel.want = Vector3.new(aim.X, from.Y, aim.Z)
        end
        if not snapTo(aim.X, aim.Z) then
            break
        end
        travelTick(opts)
        local waitT = os.clock()
        while os.clock() - waitT < hopWait do
            if gen ~= myGen or not stillRun(opts) then
                done()
                return false, "cancelled"
            end
            RunService.Heartbeat:Wait()
        end
        hrp = getHRP()
        if hrp and longSnap ~= true then
            local moved = Vector3.new(hrp.Position.X - aim.X, 0, hrp.Position.Z - aim.Z).Magnitude
            if moved > 40 then
                dbg("RUBBER", string.format("tp hop d=%.1f egg=%.1f", moved, xzMag(hrp.Position)))
                local rubberWait = 0
                if opts.skipRubberWait ~= true then
                    rubberWait = GLIDE_RUBBER_WAIT
                end
                local rubberT = os.clock()
                while rubberWait > 0 and os.clock() - rubberT < rubberWait do
                    if gen ~= myGen or not stillRun(opts) then
                        done()
                        return false, "rubber_abort"
                    end
                    RunService.Heartbeat:Wait()
                end
            end
        end
    end

    hrp = getHRP()
    local ok = hrp ~= nil and xzMag(hrp.Position) <= arrive
    if ok then
        travelTick(opts)
    end
    done()
    return ok, ok and "teleport" or "not_arrive"
end

function M.ArmIntegrity()
    local integ = G.StealEggIntegrity
    if type(integ) == "table" and type(integ.Arm) == "function" then
        pcall(integ.Arm)
    end
    local sp = G.StealEggSpeed
    if type(sp) == "table" and type(sp.FlushLog) == "function" then
        pcall(sp.FlushLog)
    end
    -- Sudah armed: skip. Belum: Arm sync (spike OK), jangan background.
    if G.__StealEggVtQuiet == true
        and (G.__StealEggHhtOff == true or G.__StealEggHhtQuiet == true)
        and G.__StealEggHhtForceRefresh ~= true
    then
        return true
    end
    if type(sp) ~= "table" or type(sp.Arm) ~= "function" then
        return G.__StealEggVtQuiet == true and (G.__StealEggHhtOff == true or G.__StealEggHhtQuiet == true)
    end
    G.__StealEggArmYield = false
    local ok, v = pcall(sp.Arm)
    return ok == true and v == true
end

function M.GoTo(goal, opts)
    opts = type(opts) == "table" and opts or {}
    local cf = goal
    if typeof(goal) == "Vector3" then
        cf = CFrame.new(goal)
    end
    if typeof(cf) ~= "CFrame" then
        return false, "bad_goal"
    end
    if not stillRun(opts) then
        dbg("GOTO", "cancelled before start reason=" .. tostring(opts.reason or "-"))
        return false, "cancelled"
    end
    do
        local d = G.StealEggDispatch
        local want = opts.owner
        if type(d) == "table" and type(d.Owner) == "function" then
            local who = d.Owner()
            if who ~= nil and want ~= nil and who ~= want then
                dbg("GOTO", "not owner have=" .. tostring(who) .. " want=" .. tostring(want))
                return false, "not_owner"
            end
        end
    end
    if M.IsDead() then
        dbg("GOTO", "dead before start reason=" .. tostring(opts.reason or "-"))
        return false, "dead"
    end
    if not M.IsPlayable() then
        dbg("GOTO", "not playable reason=" .. tostring(opts.reason or "-"))
        return false, "not_playable"
    end
    -- Setelah spawn/lompat: tunggu mendarat. Walk 1500 di udara nembus tembok plot.
    -- Arena boss: skip — dodge selalu Jump, dan tunggu 1.6s di tiap hop kristal
    -- membuat fight loop macet (tidak ayun).
    if opts.skipLandWait ~= true then
        local hum0 = getHum()
        local st0 = humState(hum0)
        if st0 == Enum.HumanoidStateType.Freefall
            or st0 == Enum.HumanoidStateType.FallingDown
            or st0 == Enum.HumanoidStateType.Jumping then
            dbg("GOTO", "wait land reason=" .. tostring(opts.reason or "-"))
            local tLand = os.clock()
            while os.clock() - tLand < 0.45 do
                if not stillRun(opts) or M.IsDead() then
                    return false, "cancelled"
                end
                st0 = humState(getHum())
                if st0 ~= Enum.HumanoidStateType.Freefall
                    and st0 ~= Enum.HumanoidStateType.FallingDown
                    and st0 ~= Enum.HumanoidStateType.Jumping then
                    break
                end
                task.wait(0.05)
            end
            zeroVel(getHRP())
        end
    end
    local mode = M.NormalizeMode(opts.mode or M.mode)
    local uiMode = tostring(opts.uiMode or "")
    if uiMode == "" then
        local w = G.StealEggWild
        if type(w) == "table" then
            uiMode = tostring(w.moveMode or "")
        end
    end
    uiMode = string.lower(uiMode)
    if uiMode == "instant" or uiMode == "far" or uiMode == "decoy" or uiMode == "freeze" then
        uiMode = "teleport"
    elseif uiMode ~= "walk" and uiMode ~= "glide" and uiMode ~= "teleport" then
        uiMode = mode
    end
    local stealLegs = uiMode == "walk" or uiMode == "glide"
    -- Walk = MoveTo. Glide = geser CFrame + WalkSpeed angka Speed. Bukan disatukan.
    local reason0 = tostring(opts.reason or "")
    local ragGo = false
    do
        local Ir = G.StealEggInstant
        if type(Ir) == "table" and type(Ir.ragdollLeft) == "function" then
            local okR, left = pcall(Ir.ragdollLeft)
            ragGo = okR == true and tonumber(left) ~= nil and left > 0.12
        end
    end
    if opts.throughRagdoll == true then
        ragGo = true
    end
    local homeLegs = false
    if uiMode == "teleport"
        and (reason0 == "home" or reason0 == "safe" or reason0 == "claim"
            or G.__StealEggClaiming == true
            or ragGo == true)
    then
        homeLegs = true
    end
    if (reason0 == "egg" or reason0 == "stand-egg" or reason0 == "hit" or reason0 == "start-area")
        and uiMode ~= "teleport"
        and G.__StealEggFarOn ~= true
        and G.__StealEggClaiming ~= true
    then
        homeLegs = false
    end
    -- ArmIntegrity/getgc mahal. Saat FAR/decoy sudah di-arm di beginFarSession —
    -- jangan ulang tiap GoTo (spike CPU ~1000ms di phone).
    if opts.skipIntegrity ~= true and homeLegs ~= true then
        if G.__StealEggFarOn ~= true and G.__StealEggDecoyOn ~= true then
            pcall(M.ArmIntegrity)
        elseif G.__StealEggVtQuiet ~= true or (G.__StealEggHhtOff ~= true and G.__StealEggHhtQuiet ~= true) then
            pcall(M.ArmIntegrity)
        end
    end
    gen += 1
    local speed = tonumber(opts.speed) or M.speed
    if stealLegs ~= true and opts.nativeWalkSpeed == true and mode ~= "walk" and mode ~= "teleport" then
        if opts.lockGlideSpeed ~= true then
            speed = M.ResolveAutoSpeed()
            local copy = {}
            for k, v in pairs(opts) do
                copy[k] = v
            end
            copy.nativeWalkSpeed = true
            copy.speed = speed
            opts = copy
        end
    end
    local from = getHRP()
    travel = {
        mode = mode,
        reason = opts.reason or "-",
        want = cf.Position,
        t0 = os.clock(),
    }
    -- Walk/glide: ImpulseContext seperti MaxEarn (Playback skip cek, orig tetap).
    -- Jangan TpHold — itu mode teleport.
    G.__StealEggMoveQuiet = true
    if stealLegs == true then
        G.__StealEggLegsWalk = true
        G.__StealEggTpHold = false
        local Iw = G.StealEggInstant
        if type(Iw) == "table" and type(Iw.armMoveWindow) == "function" then
            pcall(Iw.armMoveWindow)
        end
    else
        G.__StealEggLegsWalk = false
        G.__StealEggTpHold = true
    end
    do
        -- Stall refresh getgc MAHAL. Jangan di trip pendek (claim dekat hub/safezone)
        -- — Playback sering belum nembak hits dalam 0.7s → false stall → freeze.
        local reason = tostring(opts.reason or "")
        local shortTrip = false
        local fromP = from and from.Position
        if typeof(fromP) == "Vector3" and typeof(cf) == "CFrame" then
            shortTrip = Vector3.new(cf.Position.X - fromP.X, 0, cf.Position.Z - fromP.Z).Magnitude < 220
        end
        local skipStall = opts.skipStall == true
            or shortTrip
            or reason == "home"
            or reason == "start-area"
            or reason == "pet-area"
            or reason == "safe"
            or reason == "scramble"
            or G.__StealEggFarOn == true
            or G.__StealEggBusy == true
            or G.__StealEggClaiming == true
            or (tonumber(G.__StealEggHhtHits) or 0) > 0
        if skipStall ~= true and G.__StealEggHhtOff ~= true then
            local hits0 = tonumber(G.__StealEggHhtHits) or 0
            task.spawn(function()
                task.wait(1.2)
                if G.__StealEggMoveQuiet ~= true then
                    return
                end
                local hits = tonumber(G.__StealEggHhtHits) or 0
                if hits > hits0 then
                    return
                end
                dbg("VT-QUIET", string.format("hht hits stall %d→%d · refresh", hits0, hits))
                G.__StealEggHhtForceRefresh = true
                local sp = G.StealEggSpeed
                if type(sp) == "table" and type(sp.RefreshHht) == "function" then
                    pcall(sp.RefreshHht)
                elseif type(sp) == "table" and type(sp.Arm) == "function" then
                    pcall(sp.Arm)
                end
            end)
        end
    end
    if G.__StealEggMoveDebug == true then
        startTravelHB()
    end
    dbg("GOTO", string.format(
        "%s reason=%s spd=%.0f from=%s goal=%s quiet=1",
        mode,
        tostring(opts.reason or "-"),
        speed,
        v3(from and from.Position),
        v3(cf.Position)
    ))
    local I = G.StealEggInstant
    local hadWin = false
    if type(I) == "table" and type(I.isWindow) == "function" then
        local okW, on = pcall(I.isWindow)
        hadWin = okW == true and on == true
    end
    local winOn = hadWin
    if homeLegs == true and stealLegs ~= true and ragGo ~= true and type(I) == "table" then
        local armFn = I.armMoveSession or I.armMoveWindow
        if type(armFn) == "function" then
            local okA, v = pcall(armFn)
            winOn = (okA == true and v == true) or hadWin
        end
    end
    local ok, msg = false, "fail"
    local okRun, runErr = pcall(function()
        if uiMode == "walk" then
            ok, msg = goWalk(cf, speed, opts)
        elseif uiMode == "glide" then
            local copy = {}
            for k, v in pairs(opts) do
                copy[k] = v
            end
            copy.nativeWalkSpeed = false
            copy.lockGlideSpeed = true
            copy.legalHop = false
            ok, msg = goGlide(cf, speed, copy)
        elseif homeLegs == true and (winOn == true or ragGo == true) then
            local copy = {}
            for k, v in pairs(opts) do
                copy[k] = v
            end
            copy.legalHop = true
            copy.skipRubberWait = true
            copy.skipStall = true
            copy.nativeWalkSpeed = true
            copy.lockGlideSpeed = true
            copy.throughRagdoll = ragGo == true or copy.throughRagdoll == true
            ok, msg = goGlide(cf, speed, copy)
        elseif mode == "walk" then
            ok, msg = goWalk(cf, speed, opts)
        elseif mode == "teleport" then
            ok, msg = goTeleport(cf, speed, opts)
        else
            ok, msg = goGlide(cf, speed, opts)
        end
    end)
    G.__StealEggMoveQuiet = false
    G.__StealEggTpHold = false
    stopTravelHB()
    if not okRun then
        dbg("GOTO", "err " .. tostring(runErr))
        travel = nil
        return false, "err"
    end
    local hrp = getHRP()
    dbg("GOTO-END", string.format(
        "%s %s sec=%.2f got=%s",
        tostring(ok),
        tostring(msg),
        os.clock() - (travel and travel.t0 or os.clock()),
        v3(hrp and hrp.Position)
    ))
    travel = nil
    if G.__StealEggMoveDebug == true then
        dbgDirty = true
        dbgLastSave = 0
        dbgSave()
    end
    return ok, msg
end

function M.StopRaw()
    gen += 1
    G.__StealEggTpHold = false
    G.__StealEggMoveQuiet = false
    stopTravelHB()
    travel = nil
    local hrp = getHRP()
    local hum = getHum()
    -- Don't CFrame a corpse — that holds respawn (HP bar stuck at 0).
    if not M.IsDead() then
        -- Decoy-TP: real body harus tetap unanchored; "freeze" = decoy+cam saja.
        releasePose(hrp, hum, false)
    else
        pcall(function()
            if hrp then
                hrp.Anchored = false
            end
            if hum then
                hum.PlatformStand = false
            end
        end)
    end
    if savedWalkSpeed ~= nil then
        pcall(function()
            if hum then
                local real = tonumber(M.RealWalkSpeed()) or 16
                local back = savedWalkSpeed
                if not back or back < 8 or isInflatedWs(back) or (real and back + 0.5 < real * 0.55) then
                    back = math.max(16, real)
                end
                hum.WalkSpeed = back
            end
        end)
        savedWalkSpeed = nil
    elseif hum then
        pcall(M.ApplyAccountWalkSpeed)
    end
    dbg("STOP", "Move.Stop")
end

function M.Stop()
    if M.IsDead() == true then
        return M.StopRaw()
    end
    local d = G.StealEggDispatch
    if type(d) == "table" then
        if d._preempting == true then
            return M.StopRaw()
        end
        local who = type(d.Owner) == "function" and d.Owner() or nil
        if who == "steal" or who == "claim" then
            dbg("STOP", "ignored owner=" .. tostring(who))
            return
        end
    end
    return M.StopRaw()
end

local function bindLife(char)
    if typeof(char) ~= "Instance" then
        return
    end
    task.spawn(function()
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then
            pcall(function()
                hum = char:WaitForChild("Humanoid", 8)
            end)
        end
        if not hum then
            return
        end
        G.__StealEggDead = (tonumber(hum.Health) or 0) <= 0
        hum.Died:Connect(function()
            G.__StealEggDead = true
            G.__StealEggSpawnCool = os.clock() + 4.5
            spawnJumpPending = true
            dbg("LIFE", "Died — abort travel")
            pcall(M.Stop)
        end)
        hum.HealthChanged:Connect(function(hp)
            if (tonumber(hp) or 0) <= 0 then
                G.__StealEggDead = true
                pcall(M.Stop)
            elseif M.IsPlayable() then
                G.__StealEggDead = false
            end
        end)
    end)
end

local function startLifeWatch()
    -- F4/reload: handler lama tetap hidup di getgenv. Naikkan gen supaya
    -- CharacterAdded tua jadi no-op, lalu pasang yang baru (tanpa getgc).
    G.__StealEggLifeGen = (tonumber(G.__StealEggLifeGen) or 0) + 1
    local LIFE_GEN = G.__StealEggLifeGen
    G.__StealEggLifeWatch = true
    bindLife(LP.Character)
    LP.CharacterAdded:Connect(function(char)
        if G.__StealEggLifeGen ~= LIFE_GEN then
            return
        end
        G.__StealEggDead = false
        G.__StealEggCharAt = os.clock()
        G.__StealEggSpawnCool = os.clock() + 3.2
        dbg("LIFE", "CharacterAdded")
        pcall(function()
            M.Stop()
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:Move(Vector3.zero, false)
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hum:MoveTo(hrp.Position)
                end
            end
        end)
        bindLife(char)
        -- Jangan getgc / Arm / sapu FX di respawn. Hook sudah dari boot; scan = freeze.
        task.spawn(function()
            if G.__StealEggLifeGen ~= LIFE_GEN then
                return
            end
            local inBoss = LP:GetAttribute("InBossArena") == true
                or (typeof(char) == "Instance" and char:GetAttribute("InBossArena") == true)
            if inBoss == true then
                spawnJumpPending = false
                return
            end
            local tWait = os.clock()
            while os.clock() - tWait < 0.8 do
                if G.__StealEggLifeGen ~= LIFE_GEN then
                    return
                end
                if char.Parent and char:FindFirstChild("HumanoidRootPart") then
                    break
                end
                task.wait(0.05)
            end
            M.SpawnJumpOnce(char)
        end)
    end)
    LP.CharacterRemoving:Connect(function()
        if G.__StealEggLifeGen ~= LIFE_GEN then
            return
        end
        G.__StealEggDead = true
        G.__StealEggSpawnCool = os.clock() + 4.5
        spawnJumpPending = true
        dbg("LIFE", "CharacterRemoving — abort travel")
        pcall(M.Stop)
    end)
end

startLifeWatch()
-- Jalan WASD = Humanoid game. Jangan timpa velocity tiap Heartbeat.

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local Core = G.StealEggCore
    local mode = values["steal.wild.moveMode"]
    if type(Core) == "table" and type(Core.dropdownValue) == "function" then
        mode = Core.dropdownValue(mode) or mode
    end
    if type(mode) == "string" then
        mode = string.lower(mode)
        if mode == "walk" or mode == "glide" or mode == "teleport" then
            M.SetMode(mode)
        end
    end
    local speed = tonumber(values["steal.wild.moveSpeed"])
    if speed then
        M.SetSpeed(speed)
    end
end

return M
 end,          required = true },
    { key = "Dispatch",  name = "Dispatch",      factory = function() -- Satu pemilik kaki. Bukan antrian destinasi.
-- Prioritas: claim > steal match/carry > scramble (pintu/farm) > steal idle pad
-- Rank steal = scramble 90. Steal yang lagi match merebut scramble.
-- Steal idle di pad HARUS melepas kaki; scrambleTakesIdleSteal.
-- Boss tetap 80. Claim dikecualikan supaya telur yang digendong sampai pad.
-- Janji temu itu sekarang ada dua lapis, dan keduanya perlu:
--   Reserve/Unreserve -> hak MULAI. Selama pesanan hidup, yang lain tidak boleh
--       mengambil leg baru walau rank-nya lebih tinggi. Ini yang membuat scramble
--       kebagian giliran; kunci saja tidak pernah cukup karena scramble butuh kaki
--       lebih dulu untuk sampai ke biome.
--   Pin/Unpin -> hak SELESAI. Yang sudah mulai tidak boleh direbut di tengah.
-- Claim dikecualikan dari keduanya supaya telur yang digendong tetap disetor.
-- Claim tetap teratas supaya telur yang sedang digendong sampai ke pad dulu.

local G = (getgenv and getgenv()) or _G

local RANK = {
    claim = 100,
    steal = 90,
    scramble = 90,
    boss = 80,
    place = 50,
    index = 50,
    sell = 40,
    fuse = 40,
    -- Mutation shard cuma hop sebentar ke telur di plot lalu balik. Nilainya
    -- kecil dan bisa ditunda kapan saja, jadi ia tidak boleh memotong siapa pun
    -- kecuali belt.
    mutation = 30,
    belt = 10,
}

local M = {
    _owner = nil,
    _token = 0,
    _preempting = false,
    -- Kunci sementara: pemilik menyatakan kaki tidak boleh direbut, bahkan oleh
    -- rank yang lebih tinggi. Ini "mekanisme janji temu" yang disebut di atas.
    -- Dipakai HANYA saat merebut merugikan semua pihak. Contoh nyatanya boss di
    -- arena terbang: dari sana steal tidak bisa mencuri apa pun, jadi menarik
    -- badan keluar membatalkan dua pekerjaan sekaligus, lalu boss membunuh diri
    -- untuk kembali dan steal kehilangan perjalanannya. Itulah tarik-ulur yang
    -- terlihat di log sebagai "kaki direbut steal di tengah tempur" berulang.
    _pin = nil,
    -- Pesanan giliran. Kunci di atas hanya melindungi yang SUDAH mulai, jadi ia
    -- tidak pernah menolong boss: boss butuh kaki lebih dulu untuk sampai ke
    -- arena, dan rank 80 tidak bisa mengambilnya dari steal yang 90. Akibatnya
    -- terlihat di log sebagai boss terdaftar di arena (InBossArena true) sambil
    -- badannya dibawa steal berkeliling zona, lalu boss membunuh diri untuk
    -- kembali dan kehilangan kaki lagi.
    -- Pesanan menutup lubang itu: selama hidup, pihak lain tidak boleh MULAI
    -- leg baru walau rank-nya lebih tinggi, sehingga pemesan kebagian giliran
    -- begitu pemilik sekarang selesai. Claim dikecualikan, sebab telur yang
    -- sedang digendong harus tetap bisa disetor.
    _reserve = nil,
    -- Dibuka supaya alat debug tidak perlu menyalin tabelnya. Salinan pasti
    -- melenceng begitu angka di sini diubah.
    RANK = RANK,
}

local prev = G.StealEggDispatch
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev._owner = nil
    end)
end
G.StealEggDispatch = M

local function rankOf(who)
    return tonumber(RANK[tostring(who or "")]) or 0
end

local function eventLocked()
    -- Scramble lock tidak menahan steal: match telur harus bisa merebut kaki.
    local boss = G.StealEggBoss
    if type(boss) ~= "table" or type(boss.isLocked) ~= "function" then
        return false
    end
    local ok, locked = pcall(boss.isLocked)
    return ok == true and locked == true
end

function M.RankOf(who)
    return rankOf(who)
end

-- Kunci selalu berbatas waktu. Tanpa tenggat, satu galat di pemegangnya
-- membuat kaki tersangkut sampai skrip dimuat ulang — kegagalan yang jauh
-- lebih mahal daripada tarik-ulur yang mau dicegah.
local function pinLive()
    local p = M._pin
    if type(p) ~= "table" then
        return nil
    end
    if os.clock() > (tonumber(p.deadline) or 0) then
        M._pin = nil
        return nil
    end
    -- Kunci tanpa pemilik tidak punya arti, dan bisa terjadi kalau Release
    -- dipanggil dari jalur lain.
    if M._owner == nil or M._owner.who ~= p.who then
        M._pin = nil
        return nil
    end
    return p
end

-- Hanya pemilik kaki yang sedang berjalan boleh memasang kunci, dan hanya
-- untuk dirinya sendiri.
function M.Pin(who, seconds)
    who = tostring(who or "")
    if who == "" or M._owner == nil or M._owner.who ~= who then
        return false
    end
    local sec = math.clamp(tonumber(seconds) or 0, 0, 420)
    if sec <= 0 then
        M._pin = nil
        return true
    end
    M._pin = { who = who, deadline = os.clock() + sec }
    return true
end

function M.Unpin(who)
    who = tostring(who or "")
    if M._pin ~= nil and who ~= "" and M._pin.who ~= who then
        return false
    end
    M._pin = nil
    return true
end

function M.Pinned()
    local p = pinLive()
    return p ~= nil and p.who or nil
end

-- Pesanan juga selalu berbatas waktu, alasannya sama seperti kunci: satu galat
-- di pemesannya tidak boleh mematikan semua fitur lain sampai reload.
local function reserveLive()
    local r = M._reserve
    if type(r) ~= "table" then
        return nil
    end
    if os.clock() > (tonumber(r.deadline) or 0) then
        M._reserve = nil
        return nil
    end
    return r
end

-- grace disimpan untuk kompatibilitas pemanggil lama, tapi Hold tidak lagi
-- memotong pemilik yang sedang jalan. Memotong steal di tengah adalah sumber
-- tarik-ulur dengan boss. Giliran datang begitu pemilik melepaskan sendiri.
function M.Reserve(who, seconds, grace)
    who = tostring(who or "")
    if who == "" then
        return false
    end
    local sec = math.clamp(tonumber(seconds) or 0, 0, 600)
    if sec <= 0 then
        return M.Unreserve(who)
    end
    local r = reserveLive()
    if r ~= nil and r.who ~= who then
        return false
    end
    if r == nil then
        M._reserve = {
            who = who,
            deadline = os.clock() + sec,
            graceUntil = os.clock() + math.clamp(tonumber(grace) or 10, 0, 60),
        }
        return true
    end
    r.deadline = os.clock() + sec
    return true
end

function M.Unreserve(who)
    who = tostring(who or "")
    if M._reserve ~= nil and who ~= "" and M._reserve.who ~= who then
        return false
    end
    M._reserve = nil
    return true
end

function M.Reserved()
    local r = reserveLive()
    return r ~= nil and r.who or nil
end

local function moveMod()
    return G.StealEggMove
end

local function stopRaw()
    local mv = moveMod()
    if type(mv) ~= "table" then
        return
    end
    local fn = mv.StopRaw
    if type(fn) ~= "function" then
        fn = mv.Stop
    end
    if type(fn) == "function" then
        M._preempting = true
        pcall(fn)
        M._preempting = false
    end
end

function M.Owner()
    return M._owner and M._owner.who or nil
end

function M.Token()
    return M._owner and M._owner.token or 0
end

function M.Is(who)
    return M._owner ~= nil and M._owner.who == tostring(who or "")
end

local function stealFlowBusy()
    if G.__StealEggClaiming == true
        or G.__StealEggFarOn == true
        or G.__StealEggDecoyOn == true
        or G.__StealEggBusy == true
    then
        return true
    end
    local wild = G.StealEggWild
    if type(wild) ~= "table" then
        return false
    end
    if wild._busy == true then
        return true
    end
    if type(wild.isCarrying) == "function" then
        local ok, yes = pcall(wild.isCarrying)
        if ok == true and yes == true then
            return true
        end
    end
    local st = wild._status
    if type(st) == "table" then
        local t = tostring(st.text or "")
        if t == "Going" or t == "Steal" or t == "Guard" or t == "Home"
            or t == "Claim" or t == "Claiming" or t == "Hit"
        then
            return true
        end
    end
    return false
end

local function stealIdle()
    return stealFlowBusy() ~= true
end

local function stealHasLiveMatch()
    if os.clock() < (tonumber(G.__StealEggBagFullUntil) or 0) then
        return false
    end
    if G.__StealEggClaiming == true or G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
        return true
    end
    if G.__StealEggBusy == true then
        return true
    end
    local wild = G.StealEggWild
    if type(wild) ~= "table" then
        return false
    end
    -- DropWall / spawn ≤5s: steal harus merebut scramble meski match belum ada.
    if G.__StealEggResetGo == true then
        return true
    end
    if type(wild.resetRace) == "function" then
        local okr, race = pcall(wild.resetRace)
        if okr == true and race == true then
            return true
        end
    end
    if type(wild.wallHold) == "function" then
        local okh, hold = pcall(wild.wallHold)
        if okh == true and hold == true then
            return true
        end
    end
    if wild._busy == true then
        return true
    end
    if type(wild.isCarrying) == "function" then
        local okc, yes = pcall(wild.isCarrying)
        if okc == true and yes == true then
            return true
        end
    end
    if type(wild.hasRuleTarget) == "function" then
        local ok, hit = pcall(wild.hasRuleTarget)
        return ok == true and hit == true
    end
    return false
end

-- Rank sama 90. Hanya match rule / carry / FAR yang boleh merebut scramble.
-- Bahan rift + idle pad bukan match.
local function stealTakesScramble(who)
    return who == "steal"
        and M._owner ~= nil
        and M._owner.who == "scramble"
        and stealHasLiveMatch() == true
end

-- Rank sama 90. Steal yang lagi idle di pad jangan nahan kaki: scramble harus
-- bisa pergi ke pintu cave. Match/carry tetap merebut scramble.
local function scrambleTakesIdleSteal(who)
    return who == "scramble" and M._owner ~= nil and M._owner.who == "steal" and stealIdle() == true
end

function M.Can(who)
    who = tostring(who or "")
    if who == "" then
        return false
    end
    if M._owner ~= nil and M._owner.who == who then
        return true
    end
    -- Cek pesanan HARUS mendahului jalan pintas "kaki kosong berarti boleh".
    -- Kaki kosong justru satu-satunya momen yang dijaga pesanan: kalau di situ
    -- jawabannya masih boleh, steal mengambil leg berikutnya dan pesanan boss
    -- tidak pernah berarti apa-apa.
    local r = reserveLive()
    -- Steal + claim tidak dihalangi pesanan. Rank steal 90, dan kalau rule
    -- steal sedang match ia harus jalan dulu — pesanan boss (80) tidak boleh
    -- mengantri di depan.
    -- Kecuali boss sudah di arena: reset telur tidak boleh merebut kaki.
    if who == "steal" and eventLocked() then
        return false
    end
    if r ~= nil and r.who ~= who and who ~= "claim" and who ~= "steal" then
        return false
    end
    if M._owner == nil then
        return true
    end
    if stealTakesScramble(who) then
        return true
    end
    if scrambleTakesIdleSteal(who) then
        return true
    end
    if pinLive() ~= nil then
        return false
    end
    return rankOf(who) > rankOf(M._owner.who)
end

function M.mayStop()
    if M._preempting == true then
        return true
    end
    return true
end

function M.Hold(who)
    who = tostring(who or "")
    if who == "" then
        return false
    end
    if M._owner and M._owner.who == who then
        return true
    end
    -- Pesanan orang lain menutup pintu, termasuk saat kaki sedang kosong. Justru
    -- kaki kosong itu momen yang dijaga: di situlah pemesan mengambil gilirannya.
    local r = reserveLive()
    if who == "steal" and eventLocked() then
        return false
    end
    if r ~= nil and r.who ~= who and who ~= "claim" and who ~= "steal" then
        return false
    end
    if stealTakesScramble(who) then
        M._pin = nil
        stopRaw()
    elseif scrambleTakesIdleSteal(who) then
        M._pin = nil
        stopRaw()
    else
        if M._owner and pinLive() ~= nil then
            return false
        end
        if M._owner and rankOf(who) <= rankOf(M._owner.who) then
            -- Jangan potong steal di tengah. Pemesan menunggu sampai pemilik
            -- melepaskan sendiri. Memotong di sini adalah sumber tarik-ulur:
            -- boss merebut, steal merebut balik, karakter dibunuh untuk masuk arena.
            return false
        end
        if M._owner then
            stopRaw()
        end
    end
    M._token += 1
    M._owner = {
        who = who,
        token = M._token,
        at = os.clock(),
    }
    G.__StealEggMoveOwner = who
    return true
end

function M.Release(who)
    who = tostring(who or "")
    if M._owner == nil then
        return true
    end
    if who ~= "" and M._owner.who ~= who then
        return false
    end
    M._pin = nil
    M._owner = nil
    G.__StealEggMoveOwner = nil
    return true
end

function M.GoTo(who, dest, opts)
    if M.Hold(who) ~= true then
        return false, "busy"
    end
    local mv = moveMod()
    if type(mv) ~= "table" or type(mv.GoTo) ~= "function" then
        return false, "no move"
    end
    opts = type(opts) == "table" and opts or {}
    opts.owner = who
    local token = M._token
    local userRun = opts.shouldRun
    opts.shouldRun = function()
        if M._owner == nil or M._owner.who ~= who or M._token ~= token then
            return false
        end
        if type(userRun) == "function" and userRun() == false then
            return false
        end
        return true
    end
    return mv.GoTo(dest, opts)
end

function M.Stop(who)
    who = tostring(who or "")
    if M._owner ~= nil and who ~= "" and M._owner.who ~= who then
        return false
    end
    stopRaw()
    return true
end

return M
 end,    required = true },
