G.__StealEggFarDebug = false
EGG._farLog = {}
EGG._farSeq = 0
EGG._farSaveAt = 0
EGG._farDirty = false
EGG.farTraceFile = "far_steal_trace.txt"
EGG.farTraceDir = "NodeStealEgg"

function EGG.farTraceFlush(force)
    if EGG.farDebug ~= true and G.__StealEggFarDebug ~= true and G.__StealEggMoveDebug ~= true then
        return
    end
    if EGG._farDirty ~= true or typeof(writefile) ~= "function" then
        return
    end
    if force ~= true and (os.clock() - (tonumber(EGG._farSaveAt) or 0)) < 0.2 then
        return
    end
    EGG._farSaveAt = os.clock()
    EGG._farDirty = false
    local dir = tostring(EGG.farTraceDir or "NodeStealEgg")
    if type(makefolder) == "function" then
        pcall(makefolder, dir)
    end
    local body = table.concat(EGG._farLog, "\n") .. "\n"
    pcall(writefile, dir .. "/" .. tostring(EGG.farTraceFile), body)
    pcall(writefile, tostring(EGG.farTraceFile), body)
end

function EGG.farTrace(tag, msg)
    if EGG.farDebug ~= true and G.__StealEggFarDebug ~= true and G.__StealEggMoveDebug ~= true then
        return
    end
    EGG._farSeq = (tonumber(EGG._farSeq) or 0) + 1
    local pos = "?"
    pcall(function()
        local r = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if r then
            pos = string.format("%.0f,%.0f,%.0f", r.Position.X, r.Position.Y, r.Position.Z)
        end
    end)
    local line = string.format(
        "[%.3f #%d][%s] %s | far=%s pos=%s",
        os.clock(),
        EGG._farSeq,
        tostring(tag or "?"),
        tostring(msg or ""),
        tostring(G.__StealEggFarOn == true),
        pos
    )
    local n = #EGG._farLog
    if n >= 2500 then
        table.remove(EGG._farLog, 1)
    end
    EGG._farLog[#EGG._farLog + 1] = line
    EGG._farDirty = true
    EGG.farTraceFlush()
end

