local function skipEggUid(uid, why)
    uid = tostring(uid or "")
    if uid == "" then
        return
    end
    M._badEggUid = uid
    local hold = 20
    if tostring(why or ""):find("rubber", 1, true) then
        hold = 45
        G.__StealEggRubberUntil = os.clock() + 5
    elseif tostring(why or ""):find("no-hit", 1, true) or tostring(why or ""):find("no bait", 1, true) then
        -- Guard miss / umpan: jangan blacklist target steal (sendirian tetap retry).
        hold = 2
    end
    M._badEggUntil = os.clock() + hold
    dbg("STEAL", "skip uid=" .. uid .. " " .. tostring(why or "") .. " " .. tostring(hold) .. "s")
end

local function eggIsSkipped(uid)
    uid = tostring(uid or "")
    if uid == "" or tostring(M._badEggUid) ~= uid then
        return false
    end
    if os.clock() >= (tonumber(M._badEggUntil) or 0) then
        return false
    end
    -- Telur drop / prefer: jangan blacklist, harus di-regrab di tempat.
    if tostring(M._preferUid or "") == uid then
        return false
    end
    return true
end
EGG.skipEggUid = skipEggUid

