local function leakyStatus(s)
    s = string.lower(tostring(s or ""))
    if s == "" then
        return false
    end
    return string.find(s, "request", 1, true)
        or string.find(s, "startarea", 1, true)
        or string.find(s, "eggcmds", 1, true)
        or string.find(s, "cframe", 1, true)
        or string.find(s, "key=", 1, true)
        or string.find(s, "xz=", 1, true)
        or string.find(s, "3d=", 1, true)
        or string.find(s, "glide", 1, true)
        or string.find(s, "remote", 1, true)
        or string.find(s, "slot", 1, true)
        or string.find(s, "uid", 1, true)
        or string.find(s, "invoke", 1, true)
        or string.find(s, "network", 1, true)
        or string.find(s, "trap ahead", 1, true)
        or string.find(s, "guard ahead", 1, true)
        or string.find(s, "rules on", 1, true)
        or string.find(s, "rules off", 1, true)
