local function flowHint(detail)
    local low = string.lower(tostring(detail or ""))
    low = string.gsub(low, "^%s+", "")
    low = string.gsub(low, "%s+$", "")
    if FLOW_HINT[low] then
        return FLOW_HINT[low]
    end
    for key, hint in pairs(FLOW_HINT) do
        if #key >= 4 and string.find(low, key, 1, true) then
            return hint
        end
    end
    if string.find(low, "belt", 1, true) or string.find(low, "treadmill", 1, true) then
        return "leave"
    end
    if string.find(low, "drop", 1, true) then
        return "drop"
    end
    if string.find(low, "claim", 1, true) then
        return "claim"
    end
    if string.find(low, "guard", 1, true) or string.find(low, "pukul", 1, true) then
        return "no hit"
    end
    if string.find(low, "legs held", 1, true) then
        return "busy"
    end
    return nil
end

local function cleanEggName(raw)
    raw = tostring(raw or "")
    raw = string.gsub(raw, "^%s*%[%d+/%d+%]%s*", "")
    raw = string.gsub(raw, "^%s+", "")
    raw = string.gsub(raw, "%s+$", "")
    -- Ambil segmen sebelum | / ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢
    local name = string.match(raw, "^([^|]+)")
    name = name and string.gsub(name, "%s+$", "") or raw
    name = string.gsub(name, "%s*ÃƒÆ’Ã¢â‚¬â€%d+%s*$", "")
    name = string.gsub(name, "%s*x%d+%s*$", "")
    if name == "" or leakyStatus(name) or #name > 28 then
        return nil
    end
    -- Tolak angka murni / tag teknis
    if string.match(name, "^[%d%./%s%[%]]+$") then
        return nil
    end
    return name
end

local function publicDetail(text, detail)
    detail = tostring(detail or "")
    if detail == "" or detail == "-" or detail == "—" then
        return "-"
    end
    text = tostring(text or "")
    local hint = flowHint(detail)
    if text == "Steal" or text == "Stolen" or text == "Claim" or text == "Looking"
        or text == "On" or text == "Target" or text == "Placed" or text == "Place"
        or text == "Going"
    then
        local name = cleanEggName(detail)
        if name then
            return name
        end
        if hint then
            return hint
        end
        if text == "Claim" then
            return "claim"
        end
        return "-"
    end
    if hint then
        return hint
    end
    local name = cleanEggName(detail)
    if name then
        return name
    end
    if leakyStatus(detail) then
        return "-"
    end
    if #detail > 22 then
        return "-"
    end
    return detail
end

local function emit(text, style, detail)
    local rawText = tostring(text or "Idle")
    local rawDetail = tostring(detail or "-")
    if rawText == "Avoid" then
        dbg("UI", rawText .. " | " .. rawDetail)
        return
    end
    local pubText = STATUS_LABEL[rawText] or rawText
    local pubDetail = publicDetail(rawText, rawDetail)
    do
        local spd = 0
        if type(M.liveSpeed) == "function" then
            local ok, n = pcall(M.liveSpeed)
            if ok then
                spd = tonumber(n) or 0
            end
        end
        if spd > 0 then
            local tag = tostring(math.floor(spd + 0.5)) .. " st/s"
            if pubDetail == "" or pubDetail == "-" or pubDetail == "—" then
                pubDetail = tag
            elseif string.find(pubDetail, "st/s", 1, true) == nil then
                pubDetail = pubDetail .. " · " .. tag
            end
        end
    end
    M._status = {
        text = pubText,
        style = style or "muted",
        detail = pubDetail,
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
    if style == "warn" or style == "error" or style == "success"
        or rawText == "Claim" or rawText == "Home" or rawText == "Denied" or rawText == "Stolen" or rawText == "Steal"
        or rawText == "Going" or rawText == "Wait" or rawText == "Error" or rawText == "Failed"
    then
        local uiKey = rawText .. "|" .. rawDetail .. "|" .. tostring(style)
        local now = os.clock()
        if M._lastUiDbgKey ~= uiKey or (now - (tonumber(M._lastUiDbgAt) or 0)) >= 0.5 then
            M._lastUiDbgKey = uiKey
            M._lastUiDbgAt = now
            dbg("UI", rawText .. " | " .. rawDetail)
        end
    end
end

function EGG.stealTickWait(kind)
    local lite = G.__StealEggLiteOn == true
    if kind == "busy" then
        return lite and 0.32 or 0.22
    end
    if kind == "empty" then
        return lite and 1.05 or 0.85
    end
    if kind == "after" then
        if type(EGG.eggBagFull) == "function" then
            local ok, full = pcall(EGG.eggBagFull)
            if ok == true and full == true then
                return 0.85
            end
        end
        return lite and 0.7 or 0.4
    end
    return lite and 0.4 or 0.22
end

local function emitIfChanged(text, style, detail)
    local st = M._status
    text = tostring(text or "Idle")
    style = style or "muted"
    detail = tostring(detail or "-")
    if st and st.text == text and st.style == style and st.detail == detail then
        return
    end
    emit(text, style, detail)
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

local function waitUntil(pred, timeout)
    if pred() then
        return true
    end
    local limit = tonumber(timeout) or 8
    local t0 = os.clock()
    while M.enabled and GEN == G.__StealEggWildGen and os.clock() - t0 < limit do
        if pred() then
            return true
        end
        task.wait()
    end
    return pred()
end

local function stopHold()
    local conn = G.__StealEggHoldConn or M._holdConn
    if conn then
        pcall(function()
            conn:Disconnect()
        end)
    end
    G.__StealEggHoldConn = nil
    M._holdConn = nil
end

local function getRoot()
    local char = LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function isTrapped()
    local char = LP.Character
    return char ~= nil and char:GetAttribute("IsTrapped") == true
end

local function getSeparationLine()
    return Core.separationLine()
end

local function getGuardAreasFolder()
    return Core.guardAreasFolder()
end

local function getAreaModel(areaId)
    local folder = getGuardAreasFolder()
    if not folder or areaId == nil then
        return nil
    end
    areaId = tostring(areaId)
    local hit = folder:FindFirstChild(areaId)
    if hit then
        return hit
    end
    local key = M.resolveAreaKey(areaId)
    if key and key ~= areaId then
        hit = folder:FindFirstChild(key)
        if hit then
            return hit
        end
    end
    for _, child in ipairs(folder:GetChildren()) do
        if Core.sameArea(child.Name, areaId) or (key and Core.sameArea(child.Name, key)) then
            return child
        end
    end
    return nil
end

local function isGameplaySide(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local line = getSeparationLine()
    if not line then
        return true
    end
    if type(GM.GuardAreaLookupUtil) == "table" then
        local fn = GM.GuardAreaLookupUtil.IsInGameplaySide or GM.GuardAreaLookupUtil.IsPastLine
        if type(fn) == "function" then
            local ok, v = pcall(fn, line, pos)
        if ok then
            return v == true
            end
        end
    end
    return line.CFrame.LookVector:Dot(pos - line.Position) > 0
end

local function guardInfo(areaId)
    local area = getAreaModel(areaId)
    if not area then
        return nil, "no area"
    end
    local guard = area:FindFirstChild("Guard")
    if not guard then
        return nil, "no guard"
    end
    local state = guard:GetAttribute("GuardState")
    if type(state) ~= "string" or state == "" then
        if guard:GetAttribute("Sleeping") == true then
            state = "Sleeping"
        else
            state = "Idle"
        end
    end
    return guard, state
end

local function decodeWorldPos(v)
    if typeof(v) == "Vector3" then
        return v
    end
    if typeof(v) == "CFrame" then
        return v.Position
    end
    if type(v) ~= "table" then
        return nil
    end
    if v.Position ~= nil then
        local p = decodeWorldPos(v.Position)
        if p then
            return p
        end
    end
    local x = tonumber(v.X or v[1])
    local y = tonumber(v.Y or v[2])
    local z = tonumber(v.Z or v[3])
    if x and y and z then
        return Vector3.new(x, y, z)
    end
    return nil
end

local function worldPosition(inst)
    if typeof(inst) ~= "Instance" then
        return nil
    end
    if inst:IsA("BasePart") then
        return inst.Position
    end
    if inst:IsA("Model") then
        if inst.PrimaryPart then
            return inst.PrimaryPart.Position
        end
        local ok, cf = pcall(function()
            return inst:GetPivot()
        end)
        if ok and typeof(cf) == "CFrame" then
            return cf.Position
        end
        local part = inst:FindFirstChildWhichIsA("BasePart", true)
        if part then
            return part.Position
        end
    end
    return nil
end

-- Dump GuardComponent: attack hanya Chasing + player yang curi telur area itu.
-- Avoid 1 guard area telur saja (bukan semua). Speed gerak tidak diubah di sini.
local GUARD_HIT_BY_AREA = {
    Forest = 2.5,
    Lake = 3,
    Desert = 4,
    Jungle = 3,
    Snow = 3,
    Volcano = 5,
    ["Abyss Ocean"] = 5,
    Prehistoric = 7,
    Cosmic = 4,
    ["Cherry Blossom"] = 7,
    ["Titan Temple"] = 7,
}
local GUARD_SPEED_BY_AREA = {
    Forest = 16,
    Lake = 35,
    Desert = 62,
    Jungle = 82,
    Snow = 98,
    Volcano = 113,
    ["Abyss Ocean"] = 130,
    Prehistoric = 152,
    Cosmic = 200,
    ["Cherry Blossom"] = 222,
    ["Titan Temple"] = 229.5,
}
local STEER = {
    look = 320,
    behind = 110,
    guard = 34,
    trap = 18,
    maxLat = 42,
    predict = 0.65,
    kind = nil,
    key = nil,
    sign = 1,
    exits = nil,
    exitsAt = 0,
}

local function xzDist(a, b)
    return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
end

-- Hanya state yang bisa menuju attack (ReturningHome tidak attack).
local function guardActiveState(state)
    return state == "Chasing"
        or state == "Waking"
        or state == "RetrievingEgg"
end

-- Area guard relevan: telur digendong / target steal terakhir.
local function relevantGuardAreaId()
    if M._carry.IsCarrying == true then
        local a = M._carry.AreaId
        if type(a) == "string" and a ~= "" then
            return a
        end
    end
    local info = M._lastInfo
    if type(info) == "table" then
        local a = info.areaId or info.AreaId
        if type(a) == "string" and a ~= "" then
            return a
        end
    end
    -- AreaId kosong: guard yang kejar kita (bukan Forest).
    if M._carry.IsCarrying == true or G.__StealEggClaiming == true then
        local folder = getGuardAreasFolder()
        local myId = tostring(LP.UserId)
        if folder then
            for _, area in ipairs(folder:GetChildren()) do
                if tostring(area.Name) ~= "Forest" then
                    local g = area:FindFirstChild("Guard")
                    if g then
                        local tid = tostring(g:GetAttribute("TargetPlayer") or "")
                        local wid = tostring(g:GetAttribute("WakeTargetPlayer") or "")
                        if tid == myId or wid == myId then
                            return area.Name
                        end
                    end
                end
            end
        end
    end
    return nil
end

local function pushGuardObstacle(out, guard, areaFallbackName)
    if not guard then
        return
    end
    local state = tostring(guard:GetAttribute("GuardState") or "")
    local sleeping = guard:GetAttribute("Sleeping") == true or state == "Sleeping"
    local carrying = M._carry.IsCarrying == true or G.__StealEggClaiming == true
    -- Dulu: Sleeping di-skip total. Steal saat tidur = berdiri di SoftTouch;
    -- guard bangun ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ hit ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ egg drop (HP lebih parah karena glide lambat).
    -- Saat gendong: SoftTouch zona tetap dihindari meski guard masih tidur.
    local areaIdEarly = tostring(guard:GetAttribute("AreaId") or areaFallbackName or "")
    -- Forest = umpan. Jangan dihindari.
    if areaIdEarly == "Forest" then
        return
    end
    local wantArea = relevantGuardAreaId()
    local relevant = false
    if wantArea ~= nil and areaIdEarly ~= "" then
        if type(Core.sameArea) == "function" then
            local okA, yesA = pcall(Core.sameArea, areaIdEarly, wantArea)
            relevant = okA == true and yesA == true
        end
        if relevant ~= true then
            relevant = tostring(areaIdEarly) == tostring(wantArea)
        end
    end
    local myId = tostring(LP.UserId)
    local targetingUs = tostring(guard:GetAttribute("TargetPlayer") or "") == myId
        or tostring(guard:GetAttribute("WakeTargetPlayer") or "") == myId
    -- Tidur di nest: jangan dihindari waktu ambil telur. Gendong/kejar baru belok.
    if sleeping == true and carrying ~= true and targetingUs ~= true then
        return
    end
    -- Idle di gerbang plot telur yang di-steal/carry tetap dihindari
    -- (depan ke nest / belakang ke home). Dulu di-skip → nabrak.
    if sleeping ~= true and guardActiveState(state) ~= true and targetingUs ~= true then
        if carrying ~= true and relevant ~= true then
        return
        end
    end
    local root = guard:FindFirstChild("HumanoidRootPart") or guard.PrimaryPart
    local pos = (root and root.Position) or worldPosition(guard)
    if typeof(pos) ~= "Vector3" then
        return
    end
    local areaId = tostring(guard:GetAttribute("AreaId") or areaFallbackName or "")
    local hit = tonumber(GUARD_HIT_BY_AREA[areaId]) or 10
    local baseSpd = tonumber(GUARD_SPEED_BY_AREA[areaId]) or 80
    local active = sleeping == true or guardActiveState(state) or targetingUs or relevant == true
    local mult = 1
    if sleeping == true and carrying == true then
        -- SoftTouch volume ~ overlap segera lepas telur; radius besar + kabur.
        -- HP/FPS rendah: zona lebih lebar biar GoTo tidak nyerempet lagi.
        mult = 1
        hit = math.max(hit, 32)
    elseif state == "Chasing" then
        mult = targetingUs and 3 or 2
        if carrying == true then
            hit = math.max(hit, 26)
        end
    elseif state == "Waking" then
        mult = 1.8
    elseif state == "RetrievingEgg" then
        mult = 1.5
    end
    local spd = baseSpd * mult
    local predT = STEER.predict + (targetingUs and 0.35 or (active and 0.2 or 0))
    if sleeping == true and carrying == true then
        predT = 0
    end
    local vel = Vector3.zero
    if root and root:IsA("BasePart") and sleeping ~= true then
        local v = root.AssemblyLinearVelocity
        vel = Vector3.new(v.X, 0, v.Z)
        if vel.Magnitude < 2 and targetingUs then
            local toMe = getRoot()
            if toMe then
                local d = Vector3.new(toMe.Position.X - pos.X, 0, toMe.Position.Z - pos.Z)
                if d.Magnitude > 1 then
                    vel = d.Unit * spd
                end
            end
        elseif vel.Magnitude > spd * 1.4 then
            vel = vel.Unit * spd
        end
    end
    local lead = math.clamp(spd * 0.12, 8, 36)
    if targetingUs then
        lead = lead + 10
    end
    if sleeping == true and carrying == true then
        lead = lead + 18
    end
    out[#out + 1] = {
        pos = pos,
        pred = pos + vel * predT,
        radius = hit + 8 + lead * 0.35,
        kind = "guard",
        active = active == true,
        targeting = targetingUs or (sleeping == true and carrying == true),
        state = sleeping and "Sleeping" or state,
        softTouch = sleeping == true and carrying == true,
    }
end

-- Bata koridor. 1 raycast, jarak cap. Jangan di pathHits tiap sidestep (freeze).
function STEER.hitsWall(from, to)
    if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" then
        return false
    end
    local delta = Vector3.new(to.X - from.X, 0, to.Z - from.Z)
    local mag = delta.Magnitude
    if mag < 2 then
        return false
    end
    if mag > 72 then
        mag = 72
    end
    if os.clock() - (tonumber(STEER._wallAt) or 0) < 0.1 then
        return false
    end
    STEER._wallAt = os.clock()
    local origin = Vector3.new(from.X, from.Y + 4, from.Z)
    local params = STEER._ray
    if params == nil then
        params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        STEER._ray = params
    end
    params.FilterDescendantsInstances = { LP.Character }
    local ok, hit = pcall(function()
        return Workspace:Raycast(origin, delta.Unit * mag, params)
    end)
    if ok ~= true or hit == nil then
        return false
    end
    if typeof(hit) ~= "RaycastResult" and (type(hit) ~= "table" or hit.Instance == nil) then
        return false
    end
    if hit.Normal and hit.Normal.Y > 0.55 then
        return false
    end
    local inst = hit.Instance
    if not inst or inst.CanCollide ~= true then
        return false
    end
    local p = inst
    local n = 0
    while p and p ~= Workspace and n < 6 do
        n += 1
        local nm = tostring(p.Name)
        if nm == "Guard" or nm == "GuardAreas" or nm == "ForestGuardStaging"
            or nm == "PlacedTrap" or string.find(nm, "Trap", 1, true)
            or string.find(nm, "Egg", 1, true)
        then
            return false
        end
        p = p.Parent
    end
    return true
end

function M.hitsWall(from, to)
    return STEER.hitsWall(from, to) == true
end

local function pathHits(from, to, list)
    local flat = Vector3.new(to.X - from.X, 0, to.Z - from.Z)
    local mag = flat.Magnitude
    if mag < 0.05 then
        return false
    end
    local u = flat.Unit
    for _, obs in ipairs(list) do
        local toObs = Vector3.new(obs.pos.X - from.X, 0, obs.pos.Z - from.Z)
        local along = u:Dot(toObs)
        if along > -8 and along < mag + 4 then
            local t = math.clamp(along, 0, mag)
            local closest = from + u * t
            if xzDist(closest, obs.pos) < obs.radius then
                return true
            end
        end
        if obs.pred and typeof(obs.pred) == "Vector3" then
            local toPred = Vector3.new(obs.pred.X - from.X, 0, obs.pred.Z - from.Z)
            local alongP = u:Dot(toPred)
            if alongP > -8 and alongP < mag + 4 then
                local t = math.clamp(alongP, 0, mag)
                local closest = from + u * t
                if xzDist(closest, obs.pred) < obs.radius then
                    return true
                end
            end
        end
    end
    return false
end

-- Gerbang reset area. Telur dibuat ulang tepat di DayStartsAt, tapi dindingnya
-- baru dijatuhkan 5 detik sesudahnya: 2s WallCountdownDelayAfterDayStarts lalu
-- 3s WallCountdownSeconds. Orang di luar harus nunggu DropWall; yang sudah di
-- sisi gameplay boleh ambil telur baru tanpa nunggu. Penjaga masuk server
-- nyala +0,25s sesudah dinding jatuh - itu jendela race-nya.
STEER.wallMod = nil
-- nil, bukan 0: skrip yang dimuat saat os.clock() masih di bawah 5 akan membuat
-- percobaan require pertama terlewat kalau nilainya 0, dan gerbangnya diam-diam
-- dianggap terbuka selama beberapa detik pertama.
STEER.wallAt = nil
STEER.wallSealedAt = 0
STEER.wallOpenAt = 0
STEER.dayStartsAt = nil
STEER.wallDropAt = nil
STEER.wallGo = false
STEER.stageBusy = false
STEER.resetHooked = false

function STEER.noteDayStarts(t)
    t = tonumber(t)
    if t == nil then
        return
    end
    STEER.dayStartsAt = t
    local delay = 2
    local count = 3
    local cfg = Core.require("Data.AreaEggResetCycle")
    if type(cfg) == "table" then
        delay = tonumber(cfg.WallCountdownDelayAfterDayStartsSeconds) or 2
        count = tonumber(cfg.WallCountdownSeconds) or 3
    end
    STEER.wallDropAt = t + delay + count
end

function STEER.untilSpawn()
    STEER.hookResetSignals()
    local now = tonumber(Workspace:GetServerTimeNow()) or 0
    local day = tonumber(STEER.dayStartsAt)
    if day then
        return day - now
    end
    local cycle = Core.require("Shared.Util.AreaEggCycle")
    if type(cycle) == "table" and type(cycle.SecondsUntilReset) == "function" then
        local ok, sec = pcall(cycle.SecondsUntilReset, now)
        if ok == true and tonumber(sec) and sec > 0 then
            return tonumber(sec)
        end
    end
    return nil
end

function STEER.untilWall()
    STEER.hookResetSignals()
    local drop = tonumber(STEER.wallDropAt)
    local now = tonumber(Workspace:GetServerTimeNow()) or 0
    if drop then
        return drop - now
    end
    local spawn = STEER.untilSpawn()
    if type(spawn) == "number" then
        local delay = 2
        local count = 3
        local cfg = Core.require("Data.AreaEggResetCycle")
        if type(cfg) == "table" then
            delay = tonumber(cfg.WallCountdownDelayAfterDayStartsSeconds) or 2
            count = tonumber(cfg.WallCountdownSeconds) or 3
        end
        return spawn + delay + count
    end
    return nil
end

function STEER.instantPrep(shouldRun)
    local I = G.StealEggInstant
    if type(I) ~= "table" then
        return
    end
    -- Ragdoll sisa steal: jangan glide Forest (freeze 3–5s).
    if type(I.ragdollLeft) == "function" then
        local okR, left = pcall(I.ragdollLeft)
        if okR == true and tonumber(left) and left > 0.05 then
            return
        end
    end
    if STEER.wallGo == true or G.__StealEggResetGo == true then
        if type(I.preStage) == "function" then
            pcall(I.preStage, shouldRun)
        end
        return
    end
    if type(I.stageForest) == "function" then
        pcall(I.stageForest, shouldRun)
        return
    end
    if type(I.preArm) == "function" then
        pcall(I.preArm)
    end
end

function STEER.markWallOpen()
    if STEER.wallSealedAt ~= 0 then
        dbg("WALL", string.format("gerbang terbuka | tersegel %.1fs", os.clock() - STEER.wallSealedAt))
    else
        dbg("WALL", "gerbang terbuka")
    end
    STEER.wallSealedAt = 0
    STEER.wallOpenAt = os.clock()
    STEER.wallGo = true
    G.__StealEggResetGo = true
    G.__StealEggPlaceWindow = false
    -- Jangan nil snapRecs: ReadFieldEggs deep-copy semua record = freeze ~1s
    -- di thread steal. FieldRefreshed mengganti cache.
    -- Cukup untuk umpan penjaga + steal pertama + setor. 1,2s terlalu pendek:
    -- flag mati di tengah rantai, pulang pakai TP, telur drop di pad.
    task.delay(6, function()
        STEER.wallGo = false
        G.__StealEggResetGo = false
    end)
end

function STEER.hookResetSignals()
    if STEER.resetHooked == true then
        return
    end
    pcall(function()
        local es = Core.require("Client.EggState")
        if type(es) ~= "table" then
            return
        end
        STEER.resetHooked = true
        if es.ResetCountdown ~= nil then
            if G.__StealEggResetCdConn then
                pcall(function()
                    G.__StealEggResetCdConn:Disconnect()
                end)
            end
            G.__StealEggResetCdConn = es.ResetCountdown:Connect(function(payload)
                local day = type(payload) == "table" and tonumber(payload.DayStartsAt)
                if day then
                    STEER.noteDayStarts(day)
                    dbg("WALL", string.format("reset countdown | day=%.1f", day))
                end
            end)
        end
        local refreshed = es.FieldRefreshed or es.AreaEggSnapshotUpdated
        if refreshed ~= nil then
            if G.__StealEggFieldSnapConn then
                pcall(function()
                    G.__StealEggFieldSnapConn:Disconnect()
                end)
            end
            G.__StealEggFieldSnapConn = refreshed:Connect(function(snap)
                if type(snap) ~= "table" or type(snap.Records) ~= "table" then
                    return
                end
                EGG.snapRecs = snap.Records
                EGG.snapAt = os.clock()
                local n = #snap.Records
                local prev = tonumber(EGG._snapN) or 0
                if n > prev + 12 then
                    -- Burst spawn: pause FPS DescendantAdded, jangan sapu FX telur baru.
                    G.__StealEggSpawnCool = os.clock() + 1.2
                end
                EGG._snapN = n
                local now = os.clock()
                if now - (tonumber(STEER._lootAt) or 0) < 0.45 then
                    return
                end
                STEER._lootAt = now
                local hasLoot = false
                for i = 1, n do
                    local uid = tostring(snap.Records[i] and snap.Records[i].Uid or "")
                    if uid ~= "" and string.find(uid, "FirstAreaEgg_", 1, true) ~= 1 then
                        hasLoot = true
                        break
                    end
                end
                if hasLoot then
                    G.__StealEggSpawnGo = true
                end
            end)
        end
    end)
end

function STEER.resetSoon()
    STEER.hookResetSignals()
    local nowC = os.clock()
    if (nowC - (tonumber(STEER._soonAt) or 0)) < 0.25 then
        return STEER._soonV == true
    end
    STEER._soonAt = nowC
    STEER._soonV = false
    if STEER.wallGo == true or G.__StealEggResetGo == true then
        STEER._soonV = true
        return true
    end
    local cycle = Core.require("Shared.Util.AreaEggCycle")
    if type(cycle) == "table" and type(cycle.IsRunning) == "function" then
        local okRun, running = pcall(cycle.IsRunning)
        if okRun == true and running == false then
            return false
        end
    end
    local spawn = STEER.untilSpawn()
    if type(spawn) == "number" and spawn > 0 and spawn <= 5 then
        STEER._soonV = true
        return true
    end
    local wall = STEER.untilWall()
    if type(wall) == "number" and wall > -0.2 and wall <= 5.2 then
        STEER._soonV = true
        return true
    end
    STEER._soonV = false
    return false
end

function STEER.resetRace()
    if STEER.resetSoon() == true then
        return true
    end
    local mod = STEER.wallGet()
    if mod == nil then
        return false
    end
    local ok, sealed = pcall(mod.IsSealed)
    return ok == true and sealed == true
end

function STEER.wallGet()
    STEER.hookResetSignals()
    if STEER.wallMod ~= nil then
        return STEER.wallMod
    end
    -- Require yang gagal (versi game beda) tidak boleh mematikan steal: gerbang
    -- dianggap terbuka, dan percobaan require diulang paling cepat 5 detik sekali.
    if STEER.wallAt ~= nil and (os.clock() - STEER.wallAt) < 5 then
        return nil
    end
    STEER.wallAt = os.clock()
    local mod = Core.require("Client.AreaEggResetWall")
    if type(mod) ~= "table" or type(mod.IsSealed) ~= "function" then
        return nil
    end
    STEER.wallMod = mod
    -- Signal .Changed: DropWall harus ketahuan di frame yang sama, bukan
    -- ketahuan belakangan dari poll 0,12s.
    pcall(function()
        if G.__StealEggWallConn then
            pcall(function()
                G.__StealEggWallConn:Disconnect()
            end)
        end
        G.__StealEggWallConn = mod.Changed:Connect(function(sealed)
            if sealed == true then
                STEER.wallSealedAt = os.clock()
                STEER.wallOpenAt = 0
                STEER.wallGo = false
                G.__StealEggResetGo = false
                dbg("WALL", "tersegel")
                pcall(function()
                    local cycle = Core.require("Shared.Util.AreaEggCycle")
                    local now = Workspace:GetServerTimeNow()
                    if type(cycle) == "table"
                        and type(cycle.IsNightPhase) == "function"
                        and cycle.IsNightPhase(now) == true
                        and type(cycle.NextResetTime) == "function"
                    then
                        STEER.noteDayStarts(cycle.NextResetTime(now))
                    end
                end)
            else
                STEER.markWallOpen()
            end
        end)
    end)
    return mod
end

-- true selama steal harus ditahan. Alasannya dipulangkan sebagai nilai kedua
-- supaya status UI bisa membedakan "masih tersegel" dari "baru terbuka".
function STEER.wallHold()
    local mod = STEER.wallGet()
    if mod == nil then
        return false, nil
    end
    local ok, sealed = pcall(mod.IsSealed)
    if ok ~= true then
        return false, nil
    end
    if sealed == true then
        if STEER.wallSealedAt == 0 then
            STEER.wallSealedAt = os.clock()
            dbg("WALL", "gerbang reset tersegel | steal ditahan")
        end
        STEER.wallOpenAt = 0
        -- Sudah di sisi gameplay (bukan cuma nge-camp di pad): dinding cuma
        -- nahan orang luar. Tunggu DropWall di sini kalah 5 detik dari pemain
        -- yang sudah di hutan saat telur spawn.
        local root = getRoot()
        if root and isGameplaySide(root.Position) == true then
            local pad = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
            if xzDist(root.Position, pad) > 45 then
                local day = tonumber(STEER.dayStartsAt)
                local now = tonumber(Workspace:GetServerTimeNow()) or 0
                if day == nil or now >= day then
                    return false, nil
                end
            end
        end
        return true, "gate"
    end
    if STEER.wallSealedAt ~= 0 then
        STEER.markWallOpen()
    end
    local grace = tonumber(EGG.wallGrace) or 0
    if grace > 0 and STEER.wallOpenAt ~= 0 and (os.clock() - STEER.wallOpenAt) < grace then
        return true, "gate open"
    end
    return false, nil
end

function M.wallHold()
    -- Instant: nunggu telur spawn DAN DropWall. Forest bait belum bisa di-steal
    -- sebelum dinding turun — jalan lebih awal cuma buang waktu.
    local mode = tostring(M.moveMode or ""):lower()
    if mode == "teleport" or mode == "instant" or mode == "decoy" or mode == "freeze" or mode == "far" then
        -- Gendong/claim: jangan nahan, pulang.
        if G.__StealEggClaiming == true or (type(M._carry) == "table" and M._carry.IsCarrying == true) then
            M._wallWhy = nil
            return false
        end
        STEER.wallGet()
        -- DropWall sudah sinyal: jalan sekarang. Jangan nunggu sisa untilWall.
        if STEER.wallGo == true or G.__StealEggResetGo == true then
            M._wallWhy = nil
            return false
        end
        local spawn = STEER.untilSpawn()
        local wall = STEER.untilWall()
        local sealed = false
        do
            local mod = STEER.wallMod or STEER.wallGet()
            if type(mod) == "table" and type(mod.IsSealed) == "function" then
                local okS, s = pcall(mod.IsSealed)
                sealed = okS == true and s == true
            end
        end
        if type(spawn) == "number" and spawn > 0 and spawn <= 5 then
            M._wallWhy = string.format("prep %.0fs", spawn)
            return true
        end
        -- Hanya jendela DropWall (~5s setelah spawn). untilWall 179s = sisa siklus, bukan gerbang.
        local dropping = type(wall) == "number" and wall > 0.05 and wall <= 5.2
        if dropping == true and (type(spawn) ~= "number" or spawn <= 0) then
            M._wallWhy = string.format("wall %.0fs", wall)
            return true
        end
        if sealed == true and (type(spawn) ~= "number" or spawn <= 0)
            and (type(wall) ~= "number" or wall <= 5.2)
        then
            M._wallWhy = "gate"
            return true
        end
        M._wallWhy = nil
        return false
    end
    local hold, why = STEER.wallHold()
    M._wallWhy = why
    return hold == true
end

function M.resetRace()
    return STEER.resetRace() == true
end

function STEER.padFor(kind)
    if kind == "trap" or kind == "portal" then
        return STEER.trap
    end
    return STEER.guard
end

local function listSteerObstacles(carrying)
    local moveMode = string.lower(tostring(M.moveMode or ""))
    local cache = STEER._obs
    if type(cache) == "table"
        and cache.carry == (carrying == true)
        and cache.mode == moveMode
        and cache.guards == (M.avoidGuards == true)
        and cache.traps == (M.avoidTraps == true)
        and (os.clock() - (tonumber(STEER._obsAt) or 0)) < 0.2
    then
        return cache.list
    end
    local out = {}
    -- Portal Scramble Boss di peta. Walk/glide selalu menghindar, tanpa toggle.
    if moveMode == "walk" or moveMode == "glide" then
        local portal = Workspace:FindFirstChild("ScrambleArenaPortal")
        local part = portal and portal:FindFirstChild("Portal")
        if part and part:IsA("BasePart") then
            local hx = math.max(part.Size.X, part.Size.Z) * 0.5
            if hx > 36 then
                hx = 36
            end
            out[#out + 1] = {
                pos = part.Position,
                radius = hx + 12,
                kind = "portal",
                active = true,
            }
        end
    end
    -- Avoid trap: semua gerak. TrapActive=true = sudah jepit, skip.
    if M.avoidTraps == true then
        local ok, tagged = pcall(function()
            return game:GetService("CollectionService"):GetTagged("PlacedTrap")
        end)
        if ok and type(tagged) == "table" then
            for _, trap in ipairs(tagged) do
                if trap.Parent and trap:GetAttribute("TrapActive") ~= true and trap:GetAttribute("Owner") ~= LP.Name then
                    local hit = trap:FindFirstChild("Hitbox")
                    local part = (hit and hit:IsA("BasePart") and hit) or (trap:IsA("BasePart") and trap) or nil
                    if part then
                        local hx = math.max(part.Size.X, part.Size.Z) * 0.5
                        out[#out + 1] = {
                            pos = part.Position,
                            radius = hx + 8,
                            kind = "trap",
                            active = true,
                        }
                    end
                end
            end
        end
    end
    -- Guard ikut toggle Avoid Guards. Steal yang sedang jalan tidak memaksa belok.
    if M.avoidGuards == true then
        local wantArea = relevantGuardAreaId()
        local pushed = nil
        if wantArea and tostring(wantArea) ~= "Forest" then
            local area = getAreaModel(wantArea)
            if area then
                pushGuardObstacle(out, area:FindFirstChild("Guard"), area.Name)
                pushed = tostring(area.Name)
            end
        end
        -- Guard yang kejar dari depan / belakang / arah home, bukan cuma AreaId telur.
        local folder = getGuardAreasFolder()
        local myId = tostring(LP.UserId)
        if folder then
            for _, area in ipairs(folder:GetChildren()) do
                local name = tostring(area.Name)
                if name ~= "Forest" and name ~= pushed then
                    local g = area:FindFirstChild("Guard")
                    if g then
                        local tid = tostring(g:GetAttribute("TargetPlayer") or "")
                        local wid = tostring(g:GetAttribute("WakeTargetPlayer") or "")
                        if tid == myId or wid == myId then
                            pushGuardObstacle(out, g, name)
                        end
                    end
                end
            end
        end
    end
    STEER._obs = {
        list = out,
        carry = carrying == true,
        mode = moveMode,
        guards = M.avoidGuards == true,
        traps = M.avoidTraps == true,
    }
    STEER._obsAt = os.clock()
    return out
end

local function steerAround(from, dest)
    local carrying = M._carry.IsCarrying == true or G.__StealEggClaiming == true
    -- Gendong: jangan matikan belok di yard. Skip ini yang bikin ke-hit guard dekat pad.
    if G.__StealEggClaiming == true and carrying ~= true then
        local home = M._homePos
        if typeof(home) == "Vector3" and xzDist(from, home) < 58 then
            STEER.kind = nil
            STEER.key = nil
            return dest
        end
    end
    -- Guard mati: lurus, kecuali walk/glide yang tetap menghindar portal.
    local moveMode = string.lower(tostring(M.moveMode or ""))
    local legs = moveMode == "walk" or moveMode == "glide"
    if M.avoidTraps ~= true and M.avoidGuards ~= true and legs ~= true then
        STEER.kind = nil
        STEER.key = nil
        return dest
    end
    if typeof(from) ~= "Vector3" or typeof(dest) ~= "Vector3" then
        return dest
    end
    if typeof(STEER._aimP) == "Vector3"
        and typeof(STEER._aimFrom) == "Vector3"
        and (os.clock() - (tonumber(STEER._aimAt) or 0)) < 0.08
        and xzDist(from, STEER._aimFrom) < 10
        and xzDist(dest, STEER._aimDest or dest) < 28
    then
        return STEER._aimP
    end
    local toDest = Vector3.new(dest.X - from.X, 0, dest.Z - from.Z)
    local dist = toDest.Magnitude
    if dist < 3 then
        STEER.kind = nil
        STEER.key = nil
        return dest
    end
    local dir = toDest.Unit
    local obstacles = listSteerObstacles(carrying)
    if #obstacles == 0 then
        STEER.kind = nil
        STEER.key = nil
        return dest
    end
    local best, bestScore
    for _, obs in ipairs(obstacles) do
        local pad = STEER.padFor(obs.kind)
        if obs.targeting == true then
            pad = pad + 12
        elseif obs.active == true then
            pad = pad + 8
        end
        local dangerR = obs.radius + pad
        local dNow = xzDist(from, obs.pos)
        local toObs = Vector3.new(obs.pos.X - from.X, 0, obs.pos.Z - from.Z)
        local ahead = dir:Dot(toObs)
        local hit = false
        if dNow < dangerR then
            hit = true
        end
        local look = obs.kind == "portal" and 240 or 88
        if not hit and ahead > -28 and ahead < look and ahead < dist + 6 then
            local along = math.clamp(ahead, 0, dist)
            if xzDist(from + dir * along, obs.pos) < dangerR then
                hit = true
            end
        end
        if not hit and obs.pred and typeof(obs.pred) == "Vector3" then
            local dPred = xzDist(from, obs.pred)
            if dPred < dangerR then
                hit = true
            else
                local toPred = Vector3.new(obs.pred.X - from.X, 0, obs.pred.Z - from.Z)
                local aheadP = dir:Dot(toPred)
                local lookP = obs.kind == "portal" and 240 or 88
                if aheadP > -28 and aheadP < lookP and aheadP < dist + 6 then
                    local along = math.clamp(aheadP, 0, dist)
                    if xzDist(from + dir * along, obs.pred) < dangerR then
                        hit = true
                    end
                end
            end
        end
        if hit then
            local score = dNow
            if ahead > 0 then
                score = score - 15
            end
            if obs.targeting == true then
                score = score - 40
            elseif obs.kind == "trap" or obs.kind == "portal" then
                score = score - 55
            elseif obs.active == true then
                score = score - 20
            end
            if bestScore == nil or score < bestScore then
                bestScore = score
                best = obs
                best._pad = pad
            end
        end
    end
    if not best then
        STEER.kind = nil
        STEER.key = nil
        return dest
    end
    local right = Vector3.new(-dir.Z, 0, dir.X)
    if right.Magnitude < 0.01 then
        return dest
    end
    right = right.Unit
    local toBest = Vector3.new(best.pos.X - from.X, 0, best.pos.Z - from.Z)
    local key = string.format("%s:%.0f:%.0f", best.kind, best.pos.X / 12, best.pos.Z / 12)
    -- Sign = menjauh dari guard (depan / belakang). Nempel: jangan persist sign lama.
    local awaySign = right:Dot(toBest) > 0 and -1 or 1
    local pad = best._pad or STEER.padFor(best.kind)
    local dNowBest = xzDist(from, best.pos)
    local dangerBest = best.radius + pad
    local close = dNowBest < (dangerBest + 22)
    if close or STEER.key ~= key then
        STEER.key = key
        STEER.sign = awaySign
    end
    local widen = (best.active == true or best.targeting == true or carrying == true) and 10 or 0
    local alongPush = dist
    if close then
        widen = math.min(widen + 6, 16)
    end
    local sideCap = 20
    if best.kind == "portal" then
        sideCap = dangerBest
    elseif best.kind == "trap" then
        sideCap = dNowBest < dangerBest and 18 or 14
    elseif dNowBest < dangerBest then
        sideCap = 26
    end
    local latAmt = math.min(best.radius + pad + widen, sideCap)
    local function straight()
        return Vector3.new(from.X + dir.X * alongPush, dest.Y, from.Z + dir.Z * alongPush)
    end
    local function aimAt(sign)
        local along = alongPush
        local p = from + right * sign * latAmt + dir * along
        return Vector3.new(p.X, dest.Y, p.Z)
    end
    local aim = aimAt(STEER.sign)
    if pathHits(from, aim, obstacles) or STEER.hitsWall(from, aim) == true then
        STEER.sign = -STEER.sign
        aim = aimAt(STEER.sign)
        if best.kind == "portal" then
            if STEER.hitsWall(from, aim) == true then
                STEER.sign = -STEER.sign
                aim = aimAt(STEER.sign)
            end
        elseif pathHits(from, aim, obstacles) or STEER.hitsWall(from, aim) == true then
            aim = straight()
        end
    end
    if STEER.kind ~= best.kind then
        STEER.kind = best.kind
        local label = "guard ahead"
        if best.kind == "trap" then
            label = "trap ahead"
        elseif best.kind == "portal" then
            label = "portal"
        elseif best.targeting == true then
            label = "guard chase"
        elseif best.state == "Waking" then
            label = "guard wake"
        end
        emitIfChanged("Avoid", "live", label)
    end
    STEER._aimFrom, STEER._aimDest, STEER._aimAt = from, dest, os.clock()
    STEER._aimP = aim
    return aim
end

local function distTo(pos)
    local root = getRoot()
    if not root or typeof(pos) ~= "Vector3" then
        return math.huge
    end
    return (root.Position - pos).Magnitude
end

local function distXZ(pos)
    local root = getRoot()
    if not root or typeof(pos) ~= "Vector3" then
        return math.huge
    end
    local p = root.Position
    return Vector3.new(p.X - pos.X, 0, p.Z - pos.Z).Magnitude
end

local function nearEgg(pos)
    -- Egg Y ~15 di atas HRP. Cek XZ saja supaya walk tidak deny "3d=15".
    return distXZ(pos) <= EGG.near
end

local function standOnEgg(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    -- isCarryingUid / stealMode didefinisikan lebih bawah. Panggil dari sini = nil
    -- dan stealTarget mati (Going | -) tepat saat sudah di telur.
    local carried = type(M._carry) == "table" and M._carry.IsCarrying == true
    if carried then
        local uid = tostring(M._carry.Uid or "")
        if uid:find("FirstAreaEgg_", 1, true) ~= 1 then
            return true
        end
    end
    local root = getRoot()
    if not root then
        return false
    end
    local mode = string.lower(tostring(M.moveMode or ""))
    local legs = mode == "walk" or mode == "glide"
    local grab = legs and (tonumber(EGG.walkGrab) or 12) or (tonumber(EGG.near) or 2.5)
    if distXZ(pos) <= grab then
        if not legs then
            pcall(function()
                root.Anchored = false
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
        return true
    end
    local win = 0
    if type(EGG.ragdollLeft) == "function" then
        local okW, left = pcall(EGG.ragdollLeft)
        if okW then
            win = tonumber(left) or 0
        end
    end
    if win > 0.15 and type(EGG.plantAtEgg) == "function"
        and mode == "teleport"
        and G.__StealEggFarOn ~= true
        and G.__StealEggBusy ~= true
        and G.__StealEggClaiming ~= true
    then
        return EGG.plantAtEgg(pos) == true
    end
    local Move = getMove()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return distXZ(pos) <= EGG.near
    end
    local ok = false
    pcall(function()
        ok = Move.GoTo(CFrame.new(pos.X, pos.Y + 2.2, pos.Z), {
            mode = "walk",
            uiMode = mode ~= "" and mode or "walk",
            reason = "stand-egg",
            skipRubberWait = true,
            skipLandWait = true,
            arrive = grab,
        }) == true
    end)
    return ok == true or distXZ(pos) <= EGG.near
end

function EGG.kickOffEgg()
    local mode = string.lower(tostring(M.moveMode or ""))
    if mode ~= "walk" and mode ~= "glide" then
        return
    end
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    local root = getRoot()
    if not hum then
        return
    end
    local pad = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
    local y = root and root.Position.Y or pad.Y
    pcall(function()
        hum.PlatformStand = false
        hum.Sit = false
        hum:MoveTo(Vector3.new(pad.X, y, pad.Z))
    end)
end

function EGG.stopMove()
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Stop) == "function" then
        pcall(d.Stop, "steal")
        return
    end
    local Move = getMove()
    if Move and type(Move.StopRaw) == "function" then
        pcall(Move.StopRaw)
    elseif Move and type(Move.Stop) == "function" then
        pcall(Move.Stop)
    end
end

function EGG.settleAt(pos)
    if typeof(pos) ~= "Vector3" then
        return
    end
    EGG.stopMove()
    standOnEgg(pos)
    local root = getRoot()
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if root then
        pcall(function()
            root.Anchored = false
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    if hum then
        pcall(function()
            hum.PlatformStand = false
            hum.Sit = false
        end)
    end
end

function EGG.waitGround(maxSec)
    maxSec = tonumber(maxSec) or 0.3
    local t0 = os.clock()
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    while os.clock() - t0 < maxSec do
        if not hum or hum.Health <= 0 then
            return false
        end
        local st = hum:GetState()
        if st == Enum.HumanoidStateType.Running
            or st == Enum.HumanoidStateType.Landed
            or st == Enum.HumanoidStateType.RunningNoPhysics then
            return true
        end
        task.wait(0.03)
    end
    return hum ~= nil and hum.Health > 0
end

-- Hanya saat server "Get closer": loncat 1x + settle. Jangan jump tiap sampai egg.
function EGG.resyncCloser(pos)
    if typeof(pos) ~= "Vector3" then
        return
    end
    if os.clock() - EGG.lastResync < 0.4 then
        return
    end
    EGG.lastResync = os.clock()
    EGG.settleAt(pos)
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then
        return
    end
    dbg("STEAL", string.format("resync closer xz=%.1f", distXZ(pos)))
    pcall(function()
        hum.Jump = true
    end)
    task.wait(0.07)
    pcall(function()
        hum.Jump = false
    end)
    EGG.waitGround(0.35)
    EGG.settleAt(pos)
end

