local function hasMapFilter(map)
    return type(map) == "table" and next(map) ~= nil
end

local function copyMap(value)
    return Core.parseKeyMap(value)
end

local function mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function newRuleId()
    return "wr" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

local function clampMutMode(mode)
    mode = tostring(mode or "any")
    if mode == "none" or mode == "has" or mode == "pick" or mode == "any" then
        return mode
    end
    return "any"
end

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "dc", 1e33 },
        { "no", 1e30 },
        { "oc", 1e27 },
        { "sp", 1e24 },
        { "sx", 1e21 },
        { "qi", 1e18 },
        { "qa", 1e15 },
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

local function clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or ""))
    if fallback == "below" then
        return "below"
    end
    return "above"
end

local function unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

local function wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

local function parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or "above"), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(txt)
    end
    return n, clampCompareMode(explicitMode, "above"), unsignedRuleText(txt)
end

local function parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or "above"), (raw == "" and "0" or unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(raw)
    end
    return n, clampCompareMode(explicitMode, "above"), unsignedRuleText(raw)
end

local function isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

local function sanitizeRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = parseSignedRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local mutations = copyMap(rule.mutations)
    local mutMode = clampMutMode(rule.mutMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "zone", "rarity", "egg", "mutation", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        areas = copyMap(rule.areas),
        eggs = copyMap(rule.eggs),
        rarities = copyMap(rule.rarities),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
        mutMode = mutMode,
        mutations = mutations,
    }
end

function M.sanitizeRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = sanitizeRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

function M.setRules(list)
    M.rules = M.sanitizeRules(list)
    return M.rules
end

function M.enabledRules()
    local now = os.clock()
    if type(M._enabledBag) == "table" and (now - (tonumber(M._enabledAt) or 0)) < 0.6 then
        return M._enabledBag
    end
    local out = {}
    for _, rule in ipairs(M.rules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    M._enabledBag = out
    M._enabledAt = now
    return out
end

function M.ruleCounts()
    local total = #M.rules
    local on = #M.enabledRules()
    return total, on
end

local function assetDir()
    if type(GM.Assets) ~= "table" then
        return nil
    end
    if type(GM.Assets.Directory) == "table" then
        return GM.Assets.Directory
    end
    return GM.Assets
end

local function getSave()
    if type(Core) == "table" and type(Core.playerSave) == "function" then
        local ok, data = pcall(Core.playerSave)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(GM.Save) == "table" and type(GM.Save.Get) == "function" then
        local ok, data = pcall(GM.Save.Get)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(GM.Save) == "table" and type(GM.Save.Cache) == "function" then
        local okC, bag = pcall(GM.Save.Cache)
        if okC and type(bag) == "table" then
            local data = bag[LP]
            if type(data) == "table" then
                return data
            end
            local uid = tonumber(LP and LP.UserId) or 0
            for plr, rec in pairs(bag) do
                if type(rec) == "table" then
                    local id = 0
                    pcall(function()
                        id = tonumber(plr.UserId) or 0
                    end)
                    if uid ~= 0 and id == uid then
                        return rec
                    end
                end
            end
        end
    end
    if type(GM.Save) ~= "table" or type(GM.Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(GM.Save.Get, LP, true)
    if ok then
        return data
    end
    return nil
end

local EGG_BAG_CAP = 115

function EGG.eggBagUsed()
    local data = getSave()
    local n = 0
    if type(data) == "table" and type(data.EggInventory) == "table" then
        for _, rec in pairs(data.EggInventory) do
            if type(rec) == "table" then
                n += 1
            end
        end
    end
    return n
end

function EGG.eggBagFree()
    return math.max(0, EGG_BAG_CAP - EGG.eggBagUsed())
end

function EGG.eggBagFull()
    if os.clock() < (tonumber(G.__StealEggBagFullUntil) or 0) then
        return true
    end
    return EGG.eggBagFree() <= 0
end

function EGG.markBagFull()
    G.__StealEggBagFullUntil = os.clock() + 8
    G.__StealEggPlaceWindow = true
    G.__StealEggBusy = false
    M._busy = false
    pcall(function()
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            d.Release("steal")
        end
    end)
    pcall(function()
        if type(EGG.endFarSession) == "function" then
            EGG.endFarSession("bag-full")
        elseif type(EGG.restoreMove) == "function" then
            EGG.restoreMove("bag-full")
        end
    end)
end

local function eggMeta(category)
    category = tostring(category or "")
    local cfg = type(Core.assetConfig) == "function" and Core.assetConfig(category) or nil
    if type(cfg) ~= "table" then
        local dir = assetDir()
        cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)]) or nil
    end
    if type(cfg) == "table" then
        local name = tostring(cfg.DisplayName or cfg.Name or cfg._id or category)
        local rarity = ""
        local rarityNum = 0
        if type(cfg.Rarity) == "table" then
            rarity = tostring(cfg.Rarity._id or cfg.Rarity.DisplayName or cfg.Rarity.Name or "")
            rarityNum = tonumber(cfg.Rarity.RarityNumber) or 0
        end
        if name == "" then
            name = category ~= "" and category or "egg"
        end
        return name, rarity, rarityNum
    end
    local cat = M.getCatalog()
    local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[category]
    if type(item) == "table" then
        return tostring(item.name or category), tostring(item.rarity or ""), tonumber(item.rarityNumber) or 0
    end
    return category ~= "" and category or "egg", "", M.eggRarityNumber(category)
end

local function areaMeta(areaId)
    areaId = tostring(areaId or "")
    local key = M.resolveAreaKey(areaId) or areaId
    local cat = M.getCatalog()
    if type(cat) == "table" and type(cat.areas) == "table" then
        for _, area in ipairs(cat.areas) do
            if Core.sameArea(area.key, key) or Core.sameArea(area.key, areaId) or Core.sameArea(area.name, areaId) then
                return tostring(area.name or area.key), tostring(area.key)
            end
        end
    end
    return areaId, key
end

local function mutationNames(data)
    local out, seen = {}, {}
    local function add(name)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        out[#out + 1] = name
    end
    if type(data) ~= "table" then
        return out
    end
    if type(data.Mutations) == "table" then
        for _, name in ipairs(data.Mutations) do
            add(name)
        end
        for _, name in pairs(data.Mutations) do
            if type(name) == "string" then
                add(name)
            end
        end
    end
    add(data.BaseMutation)
    add(data.muts and data.muts[1])
    if type(data.muts) == "table" then
        for _, name in ipairs(data.muts) do
            add(name)
        end
    end
    return out
end

local function itemKg(category, scale)
    scale = tonumber(scale) or 0
    category = tostring(category or "")
    if category == "" then
        return 0
    end
    if type(GM.EggItemUtil) == "table" and type(GM.EggItemUtil.GetWeightKgForScale) == "function" then
        local ok, kg = pcall(GM.EggItemUtil.GetWeightKgForScale, category, scale)
        if ok then
            return tonumber(kg) or 0
        end
    end
    if type(GM.AssetItemUtil) == "table" then
        local fn = GM.AssetItemUtil.GetVisualWeightKg or GM.AssetItemUtil.WeightKg
        if type(fn) == "function" then
            local ok, kg = pcall(fn, {
            Category = category,
            Scale = scale,
            Mutations = {},
        })
        if ok then
            return tonumber(kg) or 0
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local weight = type(cfg) == "table" and tonumber(cfg.ModelWeight) or 1
    return weight * math.max(scale, 0) ^ 3
end

local function sizeEarnMulti(scale)
    scale = tonumber(scale) or 0
    if scale <= 0 then
        return 0
    end
    if scale <= 5 then
        return scale ^ 1.85
    end
    return (scale / 5) ^ 1.2 * 19.637875755794113
end

local function mutEarnMulti(muts)
    if type(GM.Mutations) == "table" then
        local fn = GM.Mutations.GetTotalMutationsEarningMulti or GM.Mutations.EarningsFor
        if type(fn) == "function" then
            local ok, n = pcall(fn, muts or {})
        if ok then
            return math.max(1, tonumber(n) or 1)
            end
        end
    end
    return 1
end

local function eggToAsset(rec)
    if type(rec) ~= "table" then
        return nil
    end
    if type(GM.EggItemUtil) == "table" and type(GM.EggItemUtil.BuildAssetItemData) == "function" then
        local ok, item = pcall(GM.EggItemUtil.BuildAssetItemData, rec)
        if ok and type(item) == "table" then
            return item
        end
    end
    return {
        Category = rec.AssetCategory or rec.category,
        Scale = rec.AssetScale or rec.Scale,
        Mutations = type(rec.Mutations) == "table" and rec.Mutations or (type(rec.muts) == "table" and rec.muts or {}),
        BaseMutation = rec.BaseMutation,
        Gender = rec.AssetGender,
        EyeColor = rec.AssetEyeColor,
        ColorSeed = rec.AssetColorSeed,
        ColorIndex = rec.AssetColorIndex,
        Personality = rec.AssetPersonality,
        IsStolenDNA = rec.IsStolenDNA,
    }
end

function EGG.atClaimPad()
    if G.__StealEggClaiming == true or os.clock() < (tonumber(G.__StealEggClaimCool) or 0) then
        return true
    end
    local root = getRoot()
    local pad = EGG.padPos
    if root == nil or typeof(pad) ~= "Vector3" then
        return false
    end
    local dx = root.Position.X - pad.X
    local dz = root.Position.Z - pad.Z
    return (dx * dx + dz * dz) <= (90 * 90)
end

local function itemRate(rec, saveData)
    local asset = eggToAsset(rec)
    if type(asset) ~= "table" or type(asset.Category) ~= "string" or asset.Category == "" then
        return 0
    end
    -- Di pad: GetRate semua telur field = freeze ~1s. Pakai rate direktori.
    -- Mutation minta rate asli (M._descExact): telur plot sedikit, bukan scan field.
    if EGG.atClaimPad() == true and M._descExact ~= true then
        local dir = assetDir()
        local cfg = type(dir) == "table" and dir[asset.Category]
        local base = type(cfg) == "table" and tonumber(cfg.EarningRate) or 0
        local n = math.round(base * sizeEarnMulti(asset.Scale) * mutEarnMulti(asset.Mutations))
        return math.max(n, 0)
    end
    saveData = saveData or M._rateSave or getSave()
    if type(GM.AssetGenerationUtil) == "table" then
        local rateFn = GM.AssetGenerationUtil.GetRate or GM.AssetGenerationUtil.RatePerSecond
        if type(rateFn) == "function" then
            local rebirth = type(saveData) == "table" and tonumber(saveData.Rebirth) or 0
            local passes = type(saveData) == "table" and saveData.Gamepasses or nil
            local products = type(saveData) == "table" and saveData.Products or nil
            local ok, n = pcall(rateFn, asset, rebirth or 0, passes, products)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
        local mutOnly = GM.AssetGenerationUtil.GetBaseRateMutationOnly or GM.AssetGenerationUtil.MutationOnlyRatePerSecond
        if type(mutOnly) == "function" then
            local ok, n = pcall(mutOnly, asset)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and dir[asset.Category]
    local base = type(cfg) == "table" and tonumber(cfg.EarningRate) or 0
    local n = math.round(base * sizeEarnMulti(asset.Scale) * mutEarnMulti(asset.Mutations))
    return math.max(n, 0)
end

local function itemPrice(rec, rate)
    if EGG.atClaimPad() == true and M._descExact ~= true then
        return math.max(0, (tonumber(rate) or 0) * 100)
    end
    if type(GM.EggItemUtil) == "table" and type(GM.EggItemUtil.SellPrice) == "function" then
        local ok, n = pcall(GM.EggItemUtil.SellPrice, rec)
        if ok then
            local price = tonumber(n) or 0
            if price > 0 then
                return price
            end
        end
    end
    local asset = eggToAsset(rec)
    if type(asset) == "table" and type(GM.GetPriceValueForItem) == "function" then
        local ok, n = pcall(GM.GetPriceValueForItem, rec)
        if not ok then
            ok, n = pcall(GM.GetPriceValueForItem, asset)
        end
        if ok then
            local price = tonumber(n) or 0
            if price > 0 then
                return price
            end
        end
    end
    return math.max(0, (tonumber(rate) or 0) * 100)
end

local _descCache, _descCacheAt = {}, 0
function M.describeRecord(rec, exact)
    rec = type(rec) == "table" and rec or {}
    local now = os.clock()
    if now - _descCacheAt > 12 then
        local atPad = EGG.atClaimPad() == true
        if atPad ~= true then
            _descCache = {}
            _descCacheAt = now
        end
    end
    local muts = mutationNames(rec)
    -- Tanpa Uid: spawn reset = telur baru, spesies sama → GetRate/SellPrice 1× bukan 80×.
    local key = tostring(rec.AssetCategory or rec.category or "")
        .. ":"
        .. tostring(rec.AreaId or rec.areaId or "")
        .. ":"
        .. tostring(rec.AssetScale or rec.Scale)
        .. ":"
        .. tostring(rec.HasParasite == true)
        .. ":"
        .. tostring(rec.IsStolenDNA == true)
        .. ":"
        .. table.concat(muts, ",")
    local hit = exact == true and _descCache["x:" .. key] or nil
    if exact ~= true then
        hit = _descCache[key]
    end
    if type(hit) == "table" and (exact ~= true or now - (tonumber(hit._exactAt) or 0) < 12) then
        return hit
    end
    local category = tostring(rec.AssetCategory or rec.category or "")
    local areaId = tostring(rec.AreaId or rec.areaId or "")
    local name, rarity, rarityNum = eggMeta(category)
    local areaName = areaMeta(areaId)
    local rate, price
    if exact == true then
        M._descExact = true
        local okRP, r, p = pcall(function()
            local n = itemRate(rec)
            return n, itemPrice(rec, n)
        end)
        M._descExact = false
        if okRP then
            rate, price = r, p
        else
            rate, price = 0, 0
        end
    else
        rate = itemRate(rec)
        price = itemPrice(rec, rate)
    end
    local info = {
        category = category,
        areaId = areaId,
        name = name,
        rarity = rarity,
        rarityNum = rarityNum,
        areaName = areaName,
        kg = itemKg(category, rec.AssetScale or rec.Scale or rec.kg),
        rate = rate,
        price = price,
        muts = muts,
        stolen = rec.IsStolenDNA == true,
        scale = tonumber(rec.AssetScale or rec.Scale) or 0,
        hasParasite = rec.HasParasite == true,
    }
    if exact == true then
        info._exactAt = now
        _descCache["x:" .. key] = info
    elseif EGG.atClaimPad() ~= true then
        _descCache[key] = info
    end
    return info
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    local units = {
        { 1e33, "Dc" },
        { 1e30, "No" },
        { 1e27, "Oc" },
        { 1e24, "Sp" },
        { 1e21, "Sx" },
        { 1e18, "Qi" },
        { 1e15, "Qa" },
        { 1e12, "T" },
        { 1e9, "B" },
        { 1e6, "M" },
        { 1e3, "k" },
    }
    for _, u in ipairs(units) do
        if abs >= u[1] then
            return string.format("%.1f%s", n / u[1], u[2])
        end
    end
    if abs >= 10 or n == math.floor(n) then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

local function fmtKg(n)
    n = tonumber(n) or 0
    if n >= 10 then
        return string.format("%.0fkg", n)
    end
    return string.format("%.1fkg", n)
end

local function mutLabel(muts)
    if type(muts) ~= "table" or #muts == 0 then
        return "Normal"
    end
    local names = {}
    for i, name in ipairs(muts) do
        names[i] = (type(Core.mutationLabel) == "function" and Core.mutationLabel(name)) or tostring(name)
    end
    return table.concat(names, " + ")
end

function M.targetSummary(info, dist)
    info = type(info) == "table" and info or {}
    return tostring(info.name or info.category or "egg")
end

local function matchesArea(areaId, areas, areaName)
    if not hasMapFilter(areas) then
        return true
    end
    areaId = tostring(areaId or "")
    areaName = tostring(areaName or "")
    if areaId == "" and areaName == "" then
        return false
    end
    if areaId ~= "" and areas[areaId] == true then
        return true
    end
    if areaName ~= "" and areas[areaName] == true then
        return true
    end
    local key = M.resolveAreaKey(areaId ~= "" and areaId or areaName)
    if key ~= nil and areas[key] == true then
        return true
    end
    for picked, on in pairs(areas) do
        if on == true or on == 1 or on == "true" then
            if Core.sameArea(picked, areaId) or Core.sameArea(picked, areaName) then
                return true
            end
            local pickedKey = M.resolveAreaKey(picked)
            if pickedKey and (Core.sameArea(pickedKey, areaId) or Core.sameArea(pickedKey, areaName) or Core.sameArea(pickedKey, key)) then
        return true
    end
    end
    end
    return false
end

local function matchesEggs(category, eggs)
    if not hasMapFilter(eggs) then
        return true
    end
    category = tostring(category or "")
    if category == "" then
        return false
    end
    return eggs[category] == true or eggs[string.lower(category)] == true
end

local function matchesRarity(rarityNum, rarityId, rarities)
    if not hasMapFilter(rarities) then
        return true
    end
    rarityNum = tonumber(rarityNum) or 0
    rarityId = tostring(rarityId or "")
    if rarities[tostring(rarityNum)] == true then
        return true
    end
    if rarityId ~= "" and (rarities[rarityId] == true or rarities[string.lower(rarityId)] == true) then
        return true
    end
    return false
end

local function matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "below" then
        return value <= n
    end
    return value >= n
end

local function matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if hasMapFilter(selected) then
        local wantNone = false
        local hasPick = false
        for key, on in pairs(selected) do
            if on == true then
                if isNoMutationKey(key) then
                    wantNone = true
                else
                    hasPick = true
                end
            end
        end
        if wantNone and not hasPick then
            return not has
        end
        if hasPick then
            for i = 1, #names do
                local name = names[i]
                if type(Core.mutationPicked) == "function" then
                    if Core.mutationPicked(name, selected) then
                        return true
                    end
                elseif selected[name] == true or selected[string.lower(tostring(name))] == true then
                    return true
                end
            end
            if wantNone and not has then
                return true
            end
            return false
        end
        return true
    end
    local mode = clampMutMode(rule and rule.mutMode)
    if mode == "none" then
        return not has
    end
    if mode == "has" then
        return has
    end
    if mode == "pick" then
        return false
    end
    return true
end

local function ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

-- Kategori ini termasuk bahan resep Rift yang belum dipunya. Ditaruh di EGG,
-- bukan sebagai local baru, supaya batas 200 local per scope bundle tidak jebol.
function EGG.riftNeeds(category)
    local rift = G.StealEggRift
    if type(rift) ~= "table" or rift.enabled ~= true then
        return false
    end
    category = tostring(category or "")
    if category == "" or type(rift.needsSteal) ~= "function" then
        return false
    end
    local ok, yes = pcall(rift.needsSteal, category)
    return ok == true and yes == true
end

-- Index/Rift filler bukan rule match. Scramble butuh kaki → filler OFF.
function EGG.sideStealOk()
    local scramble = G.StealEggScramble
    if type(scramble) ~= "table" or scramble.enabled ~= true then
        return true
    end
    if scramble._busy == true or scramble._want == true then
        return false
    end
    if type(scramble.wantsWork) == "function" then
        local ok, want = pcall(scramble.wantsWork)
        if ok == true and want == true then
            return false
        end
    end
    return true
end

function EGG.riftFillerOk()
    return EGG.sideStealOk() == true
end

local function indexNeedsCategory(category)
    local idx = G.StealEggIndexComplete
    if type(idx) ~= "table" or idx.enabled ~= true then
        return false
    end
    category = tostring(category or "")
    if category == "" then
        return false
    end
    if type(idx.needsSteal) ~= "function" then
        return false
    end
    local ok, yes = pcall(idx.needsSteal, category)
    return ok == true and yes == true
end

function M.ruleMatches(rule, info)
    if type(rule) ~= "table" or type(info) ~= "table" then
        return false
    end
    if ruleFieldOn(rule, "zone") and not matchesArea(info.areaId, rule.areas, info.areaName) then
        return false
    end
    if ruleFieldOn(rule, "egg") and not matchesEggs(info.category, rule.eggs) then
        return false
    end
    if ruleFieldOn(rule, "rarity") and not matchesRarity(info.rarityNum, info.rarity, rule.rarities) then
        return false
    end
    if ruleFieldOn(rule, "kg") and not matchesSigned(info.kg, rule.kg, rule.kgMode) then
        return false
    end
    if ruleFieldOn(rule, "rate") and not matchesSigned(info.rate, rule.rate, rule.rateMode) then
        return false
    end
    if ruleFieldOn(rule, "price") and not matchesSigned(info.price, rule.price, rule.priceMode) then
        return false
    end
    if ruleFieldOn(rule, "mutation") and not matchesMutation(info.muts, rule) then
        return false
    end
    return true
end

function M.infoMatchesEnabled(info)
    if type(info) ~= "table" then
        return false
    end
    local rules = M.enabledRules()
    if type(rules) ~= "table" or #rules == 0 then
        return true
    end
    for _, rule in ipairs(rules) do
        if M.ruleMatches(rule, info) then
            return true
        end
    end
    return false
end

function M.areaAllowed(areaId)
    local enabled = M.enabledRules()
    -- Empty rules or all-off: semua area. Filter hanya kalau ada rule yang ON.
    if #enabled == 0 then
        return true
    end
    for _, rule in ipairs(enabled) do
        if matchesArea(areaId, rule.areas) then
            return true
        end
    end
    return false
end

function M.eggAllowed(category, areaId, rec)
    local info
    if type(category) == "table" then
        rec = category
        category = rec.AssetCategory or rec.category
        areaId = rec.AreaId or rec.areaId
    end
    do
        local uid = type(rec) == "table" and tostring(rec.Uid or "") or ""
        if uid:find("FirstAreaEgg_", 1, true) == 1 then
            return false, nil
        end
    end
    -- Rules ON + no match: jangan describeRecord semua telur dulu.
    -- Filter egg/zone murah; kg/rate/price tetap butuh describe.
    if type(rec) == "table" then
        local enabled = M.enabledRules()
        if type(enabled) == "table" and #enabled > 0 then
            local cat = tostring(rec.AssetCategory or rec.category or category or "")
            local aid = tostring(rec.AreaId or rec.areaId or areaId or "")
            local maybe = false
            for i = 1, #enabled do
                local rule = enabled[i]
                if (not ruleFieldOn(rule, "egg") or matchesEggs(cat, rule.eggs))
                    and (not ruleFieldOn(rule, "zone") or matchesArea(aid, rule.areas))
                then
                    maybe = true
                    break
                end
            end
            if maybe ~= true then
                local idx = G.StealEggIndexComplete
                local hunt = type(idx) == "table" and idx.enabled == true
                if hunt ~= true and EGG.riftFillerOk() ~= true then
                    return false, nil
                end
            end
        end
        info = M.describeRecord(rec)
        if type(info) ~= "table" then
            return false, nil
        end
    else
        info = {
            category = tostring(category or ""),
            areaId = tostring(areaId or ""),
            name = select(1, eggMeta(category)),
            rarity = select(2, eggMeta(category)),
            rarityNum = M.eggRarityNumber(category),
            kg = 0,
            rate = 0,
            price = 0,
            muts = {},
        }
    end
    -- FirstArea sudah di-skip di atas.
    local enabled = M.enabledRules()
    -- Index: rule OFF = hanya missing. Rule ON = rule + egg yang belum di index.
    local idx = G.StealEggIndexComplete
    local huntIndex = type(idx) == "table" and idx.enabled == true
        and type(idx.wantsIndexSteal) == "function"
    if huntIndex then
        local okh, yes = pcall(idx.wantsIndexSteal)
        huntIndex = okh and yes == true
    end
    if huntIndex and #enabled == 0 then
        local cat = tostring(info and info.category or category or "")
        local need = true
        if type(idx.needsSteal) == "function" then
            local okm, miss = pcall(idx.needsSteal, cat)
            need = okm and miss == true
        elseif type(idx.isMissing) == "function" then
            local okm, miss = pcall(idx.isMissing, cat)
            need = okm and miss == true
        end
        if need then
            return true, info
        end
        if EGG.riftNeeds(cat) and EGG.riftFillerOk() == true then
            info.riftOnly = true
            return true, info
        end
        return false, info
    end
    -- Empty or all-off = semua egg, urut Grab Order. Bukan "jangan steal".
    if #enabled == 0 then
        return true, info
    end
    -- Rule dulu. Index jangan nyelip sebelum rule (itu yang bikin Mammoth
    -- dikejar padahal rate rule tidak match).
    for _, rule in ipairs(enabled) do
        if M.ruleMatches(rule, info) then
            return true, info
        end
    end
    local cat = tostring(info and info.category or category or "")
    if huntIndex and EGG.sideStealOk() == true and indexNeedsCategory(cat) then
        info.indexOnly = true
        return true, info
    end
    -- Auto Rift: bahan resep hanya idle-filler, bukan rule match.
    if EGG.riftNeeds(cat) and EGG.riftFillerOk() == true then
        info.riftOnly = true
        return true, info
    end
    return false, info
end

function M.liveSpeed()
    -- XZ nyata: velocity fisik, atau geser posisi/dt (hop CFrame velocity-nya 0).
    local char = LP.Character
    local r = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
    local now = os.clock()
    local vel = 0
    if typeof(r) == "Instance" then
        local v = r.AssemblyLinearVelocity
        if typeof(v) == "Vector3" then
            vel = Vector3.new(v.X, 0, v.Z).Magnitude
        end
        local pos = r.Position
        local last = M._spdPos
        local lastT = tonumber(M._spdAt)
        if typeof(last) == "Vector3" and lastT and (now - lastT) > 0.02 and (now - lastT) < 1.2 then
            local d = Vector3.new(pos.X - last.X, 0, pos.Z - last.Z).Magnitude / (now - lastT)
            if d > vel then
                vel = d
            end
        end
        M._spdPos = pos
        M._spdAt = now
    end
    local ema = tonumber(M._spdEma)
    if ema then
        vel = ema * 0.55 + vel * 0.45
    end
    M._spdEma = vel
    return math.floor(vel + 0.5)
end

if G.__StealEggSpdConn then
    pcall(function()
        G.__StealEggSpdConn:Disconnect()
    end)
    G.__StealEggSpdConn = nil
end
G.__StealEggSpdConn = RunService.Heartbeat:Connect(function()
    local now = os.clock()
    if (now - (tonumber(M._spdUiAt) or 0)) < 0.2 then
        return
    end
    M._spdUiAt = now
    local spd = M.liveSpeed()
    local st = M._status
    if type(st) ~= "table" then
        return
    end
    local det = tostring(st.detail or "")
    local tag = tostring(spd) .. " st/s"
    local nextDet
    if string.find(det, "st/s", 1, true) then
        nextDet = string.gsub(det, "%d+ st/s", tag, 1)
    elseif spd > 0 then
        if det == "" or det == "-" or det == "—" then
            nextDet = tag
        else
            nextDet = det .. " · " .. tag
        end
    else
        return
    end
    if nextDet == det then
        return
    end
    st.detail = nextDet
    if type(M._onStatus) == "function" then
        pcall(M._onStatus, st)
    end
end)

function M.idleDetail()
    local cached = EGG._pickCache
    if type(cached) == "table" then
        local pick = cached[1]
        if pick and pick.info then
            return tostring(pick.info.name or pick.info.category or "-")
        end
        local visible = tonumber(cached[3]) or 0
        local matched = tonumber(cached[4]) or 0
        if visible > 0 and matched <= 0 then
            return "no match"
        end
        return "-"
    end
    local pick, _, visible, matched = M.bestMatch()
    if pick and pick.info then
        return tostring(pick.info.name or pick.info.category or "-")
    end
    visible = tonumber(visible) or 0
    matched = tonumber(matched) or 0
    if visible > 0 and matched <= 0 then
        return "no match"
    end
    return "-"
end

function M.listMutationItems()
    GM.Mutations = GM.Mutations or Core.require("Library.Modules.Mutations")
    local items, seen = {}, {}
    local function add(name, label)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        items[#items + 1] = { key = name, name = tostring(label or name) }
    end
    if type(GM.Mutations) == "table" then
        local listFn = GM.Mutations.GetMutations or GM.Mutations.All
        if type(listFn) == "function" then
            local ok, list = pcall(listFn)
            if ok and type(list) == "table" then
                for key, info in pairs(list) do
                    if type(info) == "table" then
                        local name = info.Id or info.Name or info._id or key
                        local label = ""
                        if type(info.Label) == "string" and info.Label ~= "" then
                            label = info.Label
                        elseif type(info.DisplayOverride) == "string" and info.DisplayOverride ~= "" then
                            label = info.DisplayOverride
                        end
                        if label == "" and type(Core.mutationLabel) == "function" then
                            label = Core.mutationLabel(name)
                        end
                        if label == "" then
                            local prettyFn = GM.Mutations.GetDisplayName or GM.Mutations.LabelOf
                            if type(prettyFn) == "function" then
                                local ok2, pretty = pcall(prettyFn, name)
                            if ok2 and type(pretty) == "string" and pretty ~= "" then
                                label = pretty
                            end
                        end
                        end
                        add(name, label ~= "" and label or name)
                    elseif type(key) == "string" then
                        add(key, key)
                    end
                end
            end
        end
        if #items == 0 then
            local names = GM.Mutations.MutationNames or GM.Mutations.IdSet
            if type(names) == "table" then
                for name in pairs(names) do
                add(name, name)
                end
            end
        end
    end
    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    table.insert(items, 1, { key = EGG.NO_MUTATION, name = EGG.NO_MUTATION })
    return items
end

local function rarityName(key)
    key = tostring(key or "")
    for _, item in ipairs(Core.RARITY_ITEMS) do
        if tostring(item.key) == key then
            local name = tostring(item.name or key)
            local pretty = name:match("^%d+%s*%S%s+(.+)$")
            return pretty or name
        end
    end
    return key
end

local function joinNames(keys, lookup, limit)
    limit = tonumber(limit) or 2
    if type(keys) ~= "table" or #keys == 0 then
        return nil
    end
    if #keys > limit then
        return tostring(#keys)
    end
    local names = {}
    for i, key in ipairs(keys) do
        names[i] = lookup and lookup(key) or key
    end
    return table.concat(names, ", ")
end

function M.formatRule(rule)
    rule = sanitizeRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " | ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    local areaKeys = mapKeyList(rule.areas)
    local eggKeys = mapKeyList(rule.eggs)
    local rarityKeys = mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = mapKeyList(rule.mutations)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            zone = #areaKeys > 0,
            egg = #eggKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = (tonumber(rule.price) or 0) > 0,
            mutation = #mutKeys > 0,
        }
    end
    if fields.zone then
        if #areaKeys == 0 then
            add("All zones", "zone")
        elseif #areaKeys > 2 then
            add(tostring(#areaKeys) .. " zones", "zone")
        else
            add(joinNames(areaKeys, function(key)
                return (areaMeta(key))
            end), "zone")
        end
    end
    if fields.egg then
        if #eggKeys == 0 then
            add("All eggs", "fruit")
        elseif #eggKeys > 2 then
            add(tostring(#eggKeys) .. " eggs", "fruit")
        else
            add(joinNames(eggKeys, function(key)
                return (eggMeta(key))
            end), "fruit")
        end
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(joinNames(rarityKeys, rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.kg then
        if kg > 0 then
            if rule.kgMode == "below" then
                add("below " .. fmtKg(kg), "kg")
            else
                add("above " .. fmtKg(kg), "kg")
            end
        else
            add("Any kg", "kg")
        end
    end
    if fields.rate then
        if rate > 0 then
            if rule.rateMode == "below" then
                add("below " .. fmtNum(rate) .. "/s", "price")
            else
                add("above " .. fmtNum(rate) .. "/s", "price")
            end
        else
            add("Any earn", "price")
        end
    end
    if fields.price then
        if price > 0 then
            if rule.priceMode == "below" then
                add("below $" .. fmtNum(price), "price")
            else
                add("above $" .. fmtNum(price), "price")
            end
        else
            add("Any $", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            local mode = clampMutMode(rule.mutMode)
            if mode == "none" then
                add("Normal", "mut")
            elseif mode == "has" then
                add("Mutated", "mut")
            elseif mode == "pick" then
                add("Picked mut", "mut")
            else
                add("Any mut", "mut")
            end
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = isNoMutationKey(key) and "Normal" or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    if #parts == 0 then
        add("Any egg", "default")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

function EGG.markDropSnap(uid)
    local mode = string.lower(tostring(M.moveMode or ""))
    if mode ~= "walk" and mode ~= "glide" then
        return
    end
    uid = tostring(uid or "")
    if uid == "" or uid:find("FirstAreaEgg_", 1, true) == 1 then
        return
    end
    M._dropSnap = true
    M._preferUid = uid
end

local function applyCarryPayload(st)
    if type(st) ~= "table" then
        return
    end
    local was = M._carry.IsCarrying == true
    local oldUid = M._carry.Uid
    M._carry.IsCarrying = st.IsCarrying == true
    M._carry.Uid = st.Uid
    M._carry.AreaId = st.AreaId
    M._carry.AssetCategory = st.AssetCategory
    -- Denda berat telur. Dipakai jatah kecepatan pulang mode Instant: jalan
    -- pulang di atas jatah ini membuat server melempar kita dari pad tepat saat
    -- tiba dan setorannya tidak pernah terdaftar.
    M._carry.SpeedMultiplier = tonumber(st.SpeedMultiplier) or 1
    if st.IsCarrying ~= true then
        local dropUid = st.Uid
        if dropUid == nil then
            dropUid = oldUid
        end
        if dropUid ~= nil then
            local du = tostring(dropUid)
            if du:find("FirstAreaEgg_", 1, true) == 1 then
                if tostring(M._preferUid or ""):find("FirstAreaEgg_", 1, true) == 1 then
                    M._preferUid = nil
                end
            else
                M._preferUid = du
                EGG.markDropSnap(du)
            end
        end
    else
        M._holdAt = os.clock()
    end
    if was ~= (st.IsCarrying == true) or tostring(oldUid) ~= tostring(st.Uid) then
        dbg("CARRY", string.format(
            "payload carrying=%s->%s uid=%s->%s cat=%s",
            tostring(was),
            tostring(st.IsCarrying == true),
            tostring(oldUid),
            tostring(st.Uid),
            tostring(st.AssetCategory)
        ))
    end
end

local function getEggRecord(uid)
    if uid == nil or tostring(uid) == "" then
        return nil
    end
    if type(GM.EggCmds) ~= "table" then
        GM.EggCmds = getEggCmds()
    end
    if type(GM.EggCmds) == "table" and type(GM.EggCmds.GetAreaEggRecord) == "function" then
        local ok, rec = pcall(GM.EggCmds.GetAreaEggRecord, tostring(uid))
        if ok and type(rec) == "table" then
            return rec
        end
    end
    local ok, rec = Core.eggCall("GetAreaEggRecord", tostring(uid))
    if ok and type(rec) == "table" then
        return rec
    end
    return nil
end

local function recordIsDropped(rec)
    if type(rec) ~= "table" then
        return false
    end
    local state = rec.State
    return state == AreaStates.Dropped or state == "Dropped"
end

-- Event carry sering telat. Snapshot lokal (GetAreaEggRecord) sudah Dropped
-- lebih dulu - jangan nunggu AreaEggCarryStateChanged baru ambil.
local function syncCarryFromRecord()
    if M._carry.IsCarrying ~= true then
        return false
    end
    local uid = M._carry.Uid
    if uid == nil or tostring(uid) == "" then
        return false
    end
    local rec = getEggRecord(uid)
    if type(rec) ~= "table" then
        return false
    end
    local state = rec.State
    -- Slot = telur di tangan / backpack. Bukan drop, jangan clear (log: batal home).
        if state == AreaStates.Dropped or state == "Dropped" then
        -- Snapshot Dropped kadang datang lebih dulu dari CarryChanged.
        -- 0.8s terlalu lama: telur sudah di tanah, kita masih anggap gendong.
        local held = tonumber(M._holdAt) or 0
        if os.clock() - held < 0.12 then
            return false
        end
        M._carry.IsCarrying = false
            M._preferUid = tostring(uid)
        EGG.markDropSnap(uid)
        dbg("CARRY", "syncFromRecord clear state=" .. tostring(state) .. " uid=" .. tostring(uid))
        return true
        end
    if state == AreaStates.Claimed or state == "Claimed"
        or state == AreaStates.GuardCarried or state == "GuardCarried"
    then
        M._carry.IsCarrying = false
        dbg("CARRY", "syncFromRecord clear state=" .. tostring(state) .. " uid=" .. tostring(uid))
        return true
    end
    return false
end

local function hookLifeDebug()
    if M._lifeDbgHooked == true then
        return
    end
    M._lifeDbgHooked = true
    local function bind(char)
        if typeof(char) ~= "Instance" then
            return
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then
            pcall(function()
                hum = char:WaitForChild("Humanoid", 3)
            end)
        end
        if hum then
            hum.Died:Connect(function()
                if M._carry.IsCarrying ~= true then
                    M._claimed = nil
                end
                dbg("LIFE", string.format(
                    "Died carry=%s uid=%s claimed=%s busy=%s claiming=%s",
                    tostring(M._carry.IsCarrying == true),
                    tostring(M._carry.Uid),
                    tostring(M._claimed ~= nil),
                    tostring(G.__StealEggBusy == true),
                    tostring(G.__StealEggClaiming == true)
                ))
                pcall(function()
                    if type(EGG.endFarSession) == "function" then
                        EGG.endFarSession("died")
                    end
                end)
            end)
        end
    end
    bind(LP.Character)
    LP.CharacterAdded:Connect(function(char)
        dbg("LIFE", "CharacterAdded")
        bind(char)
    end)
    LP.CharacterRemoving:Connect(function()
        dbg("LIFE", string.format(
            "CharacterRemoving carry=%s uid=%s",
            tostring(M._carry.IsCarrying == true),
            tostring(M._carry.Uid)
        ))
    end)
end

local function hookCarryState()
    hookLifeDebug()
    if M._carryHooked then
        return
    end
    if type(GM.EggCmds) ~= "table" then
        GM.EggCmds = getEggCmds()
    end
    if type(GM.EggCmds) ~= "table" then
        return
    end
    M._carryHooked = true
        if GM.EggCmds.AreaEggCarryStateChanged ~= nil then
            pcall(function()
                GM.EggCmds.AreaEggCarryStateChanged:Connect(function(st)
                    applyCarryPayload(st)
                end)
            end)
        end
        if GM.EggCmds.AreaEggClaimed ~= nil then
            pcall(function()
                GM.EggCmds.AreaEggClaimed:Connect(function(st)
                    dbg("CLAIM", "AreaEggClaimed uid=" .. tostring(type(st) == "table" and st.Uid))
                    M._claimed = st
                    M._carry.IsCarrying = false
                    M._preferUid = nil
                end)
            end)
        end
        if GM.EggCmds.AreaEggUpdated ~= nil then
            pcall(function()
                GM.EggCmds.AreaEggUpdated:Connect(function(rec)
                    if type(rec) ~= "table" then
                        return
                    end
                    local uid = rec.Uid
                    if uid == nil then
                        return
                    end
                    if M._carry.IsCarrying == true and tostring(M._carry.Uid) == tostring(uid) then
                        if recordIsDropped(rec)
                            or rec.State == AreaStates.Claimed or rec.State == "Claimed"
                        then
                            M._carry.IsCarrying = false
                            if recordIsDropped(rec) then
                                M._preferUid = tostring(uid)
                            end
                            dbg("CARRY", "AreaEggUpdated drop/slot/claim uid=" .. tostring(uid) .. " state=" .. tostring(rec.State))
                        end
                    end
                end)
            end)
        end
    if type(GM.Network) == "table" and type(GM.Network.Fired) == "function" then
        pcall(function()
            GM.Network.Fired("Eggs: AreaEggClaimFeedback"):Connect(function(st)
                dbg("CLAIM", "ClaimFeedback uid=" .. tostring(type(st) == "table" and st.Uid))
                M._claimed = st
                M._carry.IsCarrying = false
                M._preferUid = nil
            end)
        end)
        pcall(function()
            GM.Network.Fired("Eggs: AreaEggCarryState"):Connect(function(st)
                applyCarryPayload(st)
            end)
        end)
    end
end

local function isCarryingUid(uid)
    syncCarryFromRecord()
    if M._carry.IsCarrying ~= true then
        return false
    end
    if uid == nil or tostring(uid) == "" then
        return true
    end
    return tostring(M._carry.Uid) == tostring(uid)
end

local function waitUntilCarrying(uid, timeout, shouldRun)
    uid = tostring(uid or "")
    if isCarryingUid(uid) then
        return true
    end
    local limit = tonumber(timeout) or 0.5
    local t0 = os.clock()
    while os.clock() - t0 < limit do
        if type(shouldRun) == "function" and shouldRun() == false then
            return false
        end
        if isCarryingUid(uid) then
            return true
        end
        task.wait()
    end
    return isCarryingUid(uid)
end

local function stillHolding(uid, shouldRun)
    return function()
        if type(shouldRun) == "function" and shouldRun() == false then
            return false
        end
        if M._claimed ~= nil then
            return true
        end
        return isCarryingUid(uid)
    end
end

local cachedPlotData = nil

local function plotHasYourBase(folder)
    if typeof(folder) ~= "Instance" then
        return false
    end
    local sign = folder:FindFirstChild("PlotSign")
    local att = sign and sign:FindFirstChild("Attachment")
    local gui = att and att:FindFirstChild("YourBase")
    return gui ~= nil and gui:IsA("BillboardGui")
end

local function plotDataFromFolder(folder, slot)
    if typeof(folder) ~= "Instance" then
        return nil
    end
    local toUpdate = folder:FindFirstChild("ToUpdate")
    local pet = toUpdate and toUpdate:FindFirstChild("PetArea")
    local center = folder:FindFirstChild("CenterPoint")
    if not (pet and pet:IsA("BasePart") and center and center:IsA("BasePart")) then
        return nil
    end
    local spawn = folder:FindFirstChild("SpawnPoint")
    local cf
    if spawn and spawn:IsA("BasePart") then
        cf = spawn.CFrame
    end
    return {
        Slot = slot,
        PlotFolder = folder,
        PetArea = pet,
        CenterPoint = center,
        RespawnPointCFrame = cf,
    }
end

local function scanWorkspacePlot()
    local plots = Workspace:FindFirstChild("Plots")
    if not plots then
        return nil
    end
    for _, folder in ipairs(plots:GetChildren()) do
        if plotHasYourBase(folder) then
            local data = plotDataFromFolder(folder, tonumber(folder.Name) or folder.Name)
            if data then
        return data
            end
        end
    end
    return nil
end

local function getPlotData()
    if type(GM.PlotCmds) ~= "table" then
        GM.PlotCmds = Core.require("Library.Client.PlotCmds")
    end
    local fn = type(GM.PlotCmds) == "table" and (GM.PlotCmds.GetPlotData or GM.PlotCmds.ResolvePlot)
    if type(fn) == "function" then
        local ok, data = pcall(fn)
        if ok and type(data) == "table" then
            cachedPlotData = data
            return data
        end
    end
    local scanned = scanWorkspacePlot()
    if scanned then
        cachedPlotData = scanned
        return scanned
    end
    return cachedPlotData
end

local function getPlotHome()
    local data = getPlotData()
    if not data then
        return nil
    end
    local center = worldPosition(data.CenterPoint)
    if center then
        return center
    end
    local pet = worldPosition(data.PetArea)
    if pet then
        return pet
    end
    local cf = data.RespawnPointCFrame
    if typeof(cf) == "CFrame" then
        return cf.Position
    end
    local spawn = data.PlotFolder and data.PlotFolder:FindFirstChild("SpawnPoint")
    if spawn and spawn:IsA("BasePart") then
        return spawn.Position
    end
    return nil
end

local function captureHome()
    local plot = getPlotHome()
    if plot then
        M._homePos = plot
        return plot
    end
    if M._homePos then
        return M._homePos
    end
    local root = getRoot()
    if root and not isGameplaySide(root.Position) then
        M._homePos = root.Position
    end
    return M._homePos
end

local function traceMark(tag, msg)
    local fn = G.StealTraceMark
    if type(fn) == "function" then
        pcall(fn, tag, msg)
    end
end

local function setCharCFrame(dest, reason)
    if G.__StealEggClaiming == true and reason ~= "home" and reason ~= "safe" then
        return false
    end
    local root = getRoot()
    if not root or typeof(dest) ~= "CFrame" then
        return false
    end
    local from = root.Position
    local p = dest.Position
    if reason ~= "home" and reason ~= "egg" and (from - p).Magnitude < 3.5 then
        return true
    end
    traceMark("NODE", string.format(
        "%s V3(%.1f,%.1f,%.1f) ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ V3(%.1f,%.1f,%.1f)",
        tostring(reason or "tp"),
        from.X, from.Y, from.Z,
        p.X, p.Y, p.Z
    ))
    local ok = pcall(function()
        root.CFrame = dest
    end)
    return ok == true
end

local function getMove()
    local mv = G.StealEggMove
    if type(mv) == "table" and type(mv.GoTo) == "function" then
        return mv
    end
    return nil
end

local function stealWanted(seq)
    return G.__StealEggWanted == true
        and (seq == nil or seq == G.__StealEggSeq)
        and GEN == G.__StealEggWildGen
        and M.enabled == true
end

-- Guard / bat / void / load-fall: same pause. Steal stays ON.
local function isDead()
    local mv = getMove()
    if type(mv) == "table" and type(mv.IsDead) == "function" then
        local ok, v = pcall(mv.IsDead)
        if ok then
            return v == true
        end
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    return char == nil or hum == nil or (tonumber(hum.Health) or 0) <= 0
end

local function isPlayable()
    local mv = getMove()
    if type(mv) == "table" and type(mv.IsPlayable) == "function" then
        local ok, v = pcall(mv.IsPlayable)
        if ok then
            return v == true
        end
    end
    return isDead() ~= true
end

local function waitPlayable(shouldRun)
    local mv = getMove()
    if type(mv) == "table" and type(mv.WaitPlayable) == "function" then
        local ok, v = pcall(mv.WaitPlayable, shouldRun, 60)
        return ok == true and v == true
    end
    local t0 = os.clock()
    while os.clock() - t0 < 60 do
        if type(shouldRun) == "function" and shouldRun() == false then
            return false
        end
        if isPlayable() then
            return true
        end
        task.wait(0.1)
    end
    return isPlayable()
end

local function recoverIfDead(shouldRun)
    if isPlayable() then
        return true
    end
    local mv = getMove()
    if type(mv) == "table" and type(mv.Stop) == "function" then
        pcall(mv.Stop)
    end
    emit("Life", "warn", "waiting respawn")
    dbg("LIFE", "wait respawn")
    local ok = waitPlayable(shouldRun)
    if ok == true and isPlayable() then
        emit("Life", "success", "respawned")
        dbg("LIFE", "playable again")
        if type(mv) == "table" and type(mv.SpawnJumpOnce) == "function" then
            pcall(mv.SpawnJumpOnce, LP.Character)
        end
        pcall(captureHome)
        return true
    end
    return false
end

local function stealMode()
    -- Admin abuse nyala: teleport. Mati: walk. Abaikan pilihan glide di UI.
    local abuse = workspace:GetAttribute("Event_AdminAbuse") == true
    local mode = abuse and "teleport" or "walk"
    M.moveMode = mode
    return mode
end

local function speedMode()
    local mode = tostring(M.speedMode or "manual"):lower()
    if mode == "auto" then
        return "auto"
    end
    return "manual"
end

if G.__StealEggAdminConn then
    pcall(function()
        G.__StealEggAdminConn:Disconnect()
    end)
end
G.__StealEggAdminConn = workspace:GetAttributeChangedSignal("Event_AdminAbuse"):Connect(function()
    local wild = G.StealEggWild
    if type(wild) == "table" then
        wild.moveMode = workspace:GetAttribute("Event_AdminAbuse") == true and "teleport" or "walk"
    end
end)

local function resolveTravelSpeed(Move)
    if speedMode() ~= "auto" then
        return tonumber(M.moveSpeed) or 600, false
    end
    if stealMode() == "walk" or stealMode() == "glide" then
        if type(Move) == "table" and type(Move.WalkGlideAutoSpeed) == "function" then
            local ok, n = pcall(Move.WalkGlideAutoSpeed)
            if ok and tonumber(n) then
                return tonumber(n), true
            end
        end
        return 250, true
    end
    if type(Move) ~= "table" then
        return tonumber(M.moveSpeed) or 600, true
    end
    if type(Move.ResolveAutoSpeed) == "function" then
        local ok, n = pcall(Move.ResolveAutoSpeed)
        if ok and tonumber(n) then
            return tonumber(n), true
        end
    end
    return tonumber(M.moveSpeed) or 600, true
end

local START_NEAR = 28
local _hubCf

local function resolveStartAreaInst()
    local inst = Core.startArea and Core.startArea() or nil
    if typeof(inst) == "Instance" then
        return inst
    end
    local areas = Core.objectsAreas and Core.objectsAreas()
    if typeof(areas) == "Instance" then
        inst = areas:FindFirstChild("StartArea") or areas:FindFirstChild("StartArea", true)
        if typeof(inst) == "Instance" then
            return inst
        end
    end
    return nil
end

-- Pivot / PrimaryPart, not GetBoundingBox: a half-streamed model box can sit inside
-- the leaderboard/fence corner (first-load wall). After toggle, the instance exists.
local function startAreaCFrame()
    local inst = resolveStartAreaInst()
    if typeof(inst) ~= "Instance" then
        return _hubCf
    end
    local cf
    if inst:IsA("BasePart") then
        cf = CFrame.new(inst.Position + Vector3.new(0, inst.Size.Y * 0.5 + 3, 0))
    elseif inst:IsA("Model") then
        local primary = inst.PrimaryPart
        if primary then
            cf = CFrame.new(primary.Position + Vector3.new(0, 3, 0))
        else
            local pivot = inst:GetPivot()
            if typeof(pivot) == "CFrame" then
                cf = pivot + Vector3.new(0, 3, 0)
            end
        end
    end
    if typeof(cf) ~= "CFrame" then
        local part = inst:FindFirstChildWhichIsA("BasePart", true)
        if part then
            cf = CFrame.new(part.Position + Vector3.new(0, 3, 0))
        end
    end
    if typeof(cf) == "CFrame" then
        local apos, ahalf = M.adminPadBox and M.adminPadBox()
        if typeof(apos) == "Vector3" then
            local hubP = cf.Position
            local clear = math.min((tonumber(ahalf) or 12) + 18, 28)
            if Vector3.new(hubP.X - apos.X, 0, hubP.Z - apos.Z).Magnitude < clear then
                local nx = apos.X + clear
                cf = CFrame.new(nx, hubP.Y, hubP.Z)
                local key = string.format("%.0f:%.0f", apos.X, nx)
                if M._adminHubKey ~= key then
                    M._adminHubKey = key
                    dbg("VIA", string.format(
                        "admin hub shift pad=V3(%.1f,%.1f,%.1f) r=%.0f from=V3(%.1f,%.1f,%.1f) to=V3(%.1f,%.1f,%.1f)",
                        apos.X,
                        apos.Y,
                        apos.Z,
                        clear,
                        hubP.X,
                        hubP.Y,
                        hubP.Z,
                        nx,
                        hubP.Y,
                        hubP.Z
                    ))
                end
            end
        end
        _hubCf = cf
    end
    return cf or _hubCf
end

local function waitStartAreaCFrame(timeout, shouldRun)
    local cached = startAreaCFrame()
    if typeof(cached) == "CFrame" then
        return cached
    end
    local limit = tonumber(timeout) or 8
    local t0 = os.clock()
    emit("Move", "live", "waiting")
    while os.clock() - t0 < limit do
        if type(shouldRun) == "function" and shouldRun() == false then
            return nil
        end
        if Core.waitStartArea then
            pcall(Core.waitStartArea, 0.2)
        end
        local cf = startAreaCFrame()
        if typeof(cf) == "CFrame" then
            return cf
        end
        task.wait(0.1)
    end
    return startAreaCFrame()
end

local function xzNear(a, b, range)
    if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then
        return false
    end
    return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude <= (range or START_NEAR)
end

-- Kotak plot sendiri. Dipakai supaya place/belt di yard tidak ditarik ke jalan hub.
function STEER.inOwnPlot(p, pad)
    if typeof(p) ~= "Vector3" then
        return false
    end
    local now = os.clock()
    if now - (tonumber(STEER.ownBoxAt) or 0) > 0.8 or typeof(STEER.ownBoxCf) ~= "CFrame" then
        local data = getPlotData()
        local folder = type(data) == "table" and data.PlotFolder
        local inst = folder
        if typeof(folder) == "Instance" and not folder:IsA("Model") then
            local tu = folder:FindFirstChild("ToUpdate")
            if tu and tu:IsA("Model") then
                inst = tu
            end
        end
        if typeof(inst) == "Instance" then
            local ok, cf, size = pcall(function()
                return inst:GetBoundingBox()
            end)
            if ok and typeof(cf) == "CFrame" and typeof(size) == "Vector3" then
                STEER.ownBoxCf = cf
                STEER.ownBoxSize = size
                STEER.ownBoxAt = now
            end
        end
        local pet = type(data) == "table" and data.PetArea
        if typeof(STEER.ownBoxCf) ~= "CFrame" and typeof(pet) == "Instance" and pet:IsA("BasePart") then
            STEER.ownBoxCf = pet.CFrame
            STEER.ownBoxSize = pet.Size + Vector3.new(48, 0, 48)
            STEER.ownBoxAt = now
        end
    end
    if typeof(STEER.ownBoxCf) ~= "CFrame" or typeof(STEER.ownBoxSize) ~= "Vector3" then
        return false
    end
    pad = tonumber(pad) or 16
    local lp = STEER.ownBoxCf:PointToObjectSpace(p)
    local half = STEER.ownBoxSize * 0.5
    return math.abs(lp.X) <= half.X + pad and math.abs(lp.Z) <= half.Z + pad
end

-- Hub 543.5,-362.8. Yard utara: turun ke jalan dulu. Home di distrik plot: lurus dest.
-- destOffÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢Z hub cuma buat telur jauh. Log: home 428,-482 stuck di Z -362 (plot 1 orang).
local function plotGateAim(from, dest)
    if typeof(from) ~= "Vector3" or typeof(dest) ~= "Vector3" then
        return dest
    end
    local carrying = (type(M._carry) == "table" and M._carry.IsCarrying == true)
        or G.__StealEggClaiming == true
    -- Sudah di plot sendiri / tujuan PetArea-pad sendiri: lurus. Jangan tarik Z hub.
    -- Kecuali gendong: lurus dari Forest/plot T = nabrak guard + pojok pagar.
    if carrying ~= true and STEER.inOwnPlot(dest, 48) == true then
        local here = STEER.inOwnPlot(from, 80) == true
            or Vector3.new(from.X - dest.X, 0, from.Z - dest.Z).Magnitude < 150
        if here == true then
            return dest
        end
    end
    local hub = startAreaCFrame()
    if typeof(hub) ~= "CFrame" then
        return dest
    end
    local hubP = hub.Position
    local road = STEER.maxLat
    local xGap = math.abs(from.X - dest.X)
    local fromOff = math.abs(from.Z - hubP.Z) > road
    local destOff = math.abs(dest.Z - hubP.Z) > road
    local fromNorth = from.Z > hubP.Z + road
    local destNorth = dest.Z > hubP.Z + road
    local fromSouth = from.Z < hubP.Z - road
    local destSouth = dest.Z < hubP.Z - road
    local far = math.abs(dest.X - hubP.X) > 400
    -- Plot T milik sendiri: yard utara buntu. Jangan geser X di Z yard.
    -- Spawn di plot orang: turun ke jalan di X itu, jangan ke pusat hub (muter tengah).
    if fromNorth and destNorth ~= true then
        if destOff ~= true and carrying ~= true then
            emitIfChanged("Move", "live", "dest")
            return dest
        end
        emitIfChanged("Move", "live", "road")
        return Vector3.new(from.X, dest.Y, hubP.Z)
    end
    -- Plot selatan jalan. Naik ke jalan dulu, jangan diagonal / jangan pusat hub.
    if fromSouth and destSouth ~= true then
        if destOff ~= true and carrying ~= true then
            emitIfChanged("Move", "live", "dest")
            return dest
        end
        emitIfChanged("Move", "live", "road")
        return Vector3.new(from.X, dest.Y, hubP.Z)
    end
    -- Sama sisi jalan, X beda = plot orang. Diagonal Leviathan 748,-405 = GuardHit + mati.
    if xGap > 40 then
        if fromSouth and destSouth then
            emitIfChanged("Move", "live", "road")
            return Vector3.new(from.X, dest.Y, hubP.Z)
        end
        if fromNorth and destNorth then
            emitIfChanged("Move", "live", "road")
            return Vector3.new(from.X, dest.Y, hubP.Z)
        end
    end
    -- Dari jalan ke yard plot: geser X di Z jalan dulu (jangan cut 522,-363 ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ 748,-405).
    if destOff and fromOff ~= true and xGap > 18 then
        emitIfChanged("Move", "live", "road")
        return Vector3.new(dest.X, dest.Y, hubP.Z)
    end
    -- Plot sendiri X gap ~45 (log: 568ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢522). Threshold 80 = diagonal nabrak pagar Z~-298.
    -- ClosestExitPoint ada di yard - kalau ditarik ke situ, Z zigzag roadÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬Âexit.
    if destNorth and xGap > 18 then
        local home = getPlotHome()
        local mine = typeof(home) == "Vector3"
            and Vector3.new(from.X - home.X, 0, from.Z - home.Z).Magnitude < 180
        if fromNorth and mine then
            return dest
        end
        emitIfChanged("Move", "live", "road")
        if fromNorth or fromSouth then
            return Vector3.new(from.X, dest.Y, hubP.Z)
        end
        return Vector3.new(dest.X, dest.Y, hubP.Z)
    end
    if far ~= true then
        return dest
    end
    if os.clock() - (STEER.exitsAt or 0) > 1.5 then
        STEER.exitsAt = os.clock()
        local list = {}
        local folder = getGuardAreasFolder()
        if folder then
            for _, area in ipairs(folder:GetChildren()) do
                local bounds = area:FindFirstChild("Bounds")
                local exitp = area:FindFirstChild("ClosestExitPoint")
                if bounds and bounds:IsA("BasePart") and exitp and exitp:IsA("BasePart") then
                    local cx, hs = bounds.Position.X, bounds.Size.X * 0.5
                    list[#list + 1] = {
                        x0 = cx - hs,
                        x1 = cx + hs,
                        ez = exitp.Position.Z,
                    }
                end
            end
        end
        STEER.exits = list
    end
    local exits = STEER.exits
    local destArea
    if type(exits) == "table" then
        for i = 1, #exits do
            local e = exits[i]
            if dest.X >= e.x0 - 24 and dest.X <= e.x1 + 24 then
                destArea = e
            end
        end
    end
    if destArea and xGap > 40 then
        emitIfChanged("Move", "live", "exit")
        local ez = destArea.ez
        local sign = dest.X >= from.X and 1 or -1
        if ez > hubP.Z + 10 and from.X < hubP.X + 150 and sign > 0 then
            return Vector3.new(math.min(dest.X, hubP.X + 180), dest.Y, hubP.Z)
        end
        if xGap > 80 then
            return Vector3.new(dest.X, dest.Y, hubP.Z)
        end
        local xGo = dest.X
        if math.abs(from.Z - ez) > 12 then
            xGo = from.X + 90 * sign
            if sign > 0 then
                xGo = math.min(xGo, dest.X)
            else
                xGo = math.max(xGo, dest.X)
            end
        end
        return Vector3.new(xGo, dest.Y, ez)
    end
    if destOff and not fromOff and xGap > 8 then
        emitIfChanged("Move", "live", "road")
        return Vector3.new(dest.X, dest.Y, hubP.Z)
    end
    if fromOff and xGap > 8 and destOff ~= true then
        emitIfChanged("Move", "live", "road")
        if from.X > hubP.X + 1200 then
            return Vector3.new(dest.X, dest.Y, from.Z)
        end
        return Vector3.new(dest.X, dest.Y, hubP.Z)
    end
    return dest
end

function M.steerPlot(from, dest)
    -- Jalan hub dulu, TETAP sidestep guard telur steal/carry.
    -- Dulu gated ~= dest return lurus → nabrak guard di gerbang plot.
    local gated = plotGateAim(from, dest)
    return steerAround(from, gated)
end
M.steerAround = steerAround
M.plotGate = plotGateAim

local function travelTo(dest, reason, shouldRun, extra)
    if isDead() then
        return false
    end
    -- Saat claim pin home: blok gerak ke egg (dump thrash eggÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬Âhome).
    if G.__StealEggClaiming == true and reason ~= "home" and reason ~= "safe" and reason ~= "pet-area" then
        return false
    end
    if typeof(dest) == "Vector3" then
        dest = CFrame.new(dest + Vector3.new(0, 3, 0))
    end
    if typeof(dest) ~= "CFrame" then
        return false
    end
    local mode = stealMode()
    -- Walk/glide: kaki MoveTo + WalkSpeed UI. Jangan Instant CFrame pulang.
    -- Instant teleport tetap goSteer / carryHome.
    if mode == "teleport" then
        mode = "glide"
    end
    local Move = getMove()
    if type(Move) == "table" then
        local speed, nativeWs = resolveTravelSpeed(Move)
        pcall(function()
            Move.SetMode(mode)
            Move.SetSpeed(speed)
        end)
        local opts = {
            mode = mode,
            uiMode = stealMode(),
            speed = speed,
            speedMode = speedMode(),
            nativeWalkSpeed = stealMode() == "teleport",
            lockGlideSpeed = stealMode() ~= "walk",
            reason = reason,
            shouldRun = shouldRun,
            steer = M.steerPlot,
            -- Walk/glide steal: satu tujuan, seperti Max Earn (telur 1.5, pad 6).
            arrive = (reason == "egg" and (stealMode() == "teleport" and EGG.arrive or 1.5))
                or ((reason == "home" and (stealMode() == "walk" or stealMode() == "glide")) and 6)
                or nil,
            owner = (function()
                local d = G.StealEggDispatch
                if type(d) == "table" and type(d.Owner) == "function" then
                    return d.Owner()
                end
                return nil
            end)(),
        }
        if reason == "start-area" then
            opts.goalFn = startAreaCFrame
        end
        if type(extra) == "table" then
            for k, v in pairs(extra) do
                if v ~= nil and k ~= "longSnap" then
                    opts[k] = v
                end
            end
        end
        opts.longSnap = nil
        -- Instant: glide Speed UI. Jangan turunkan ke walk akun. Walk UI tetap walk.
        if stealMode() ~= "walk"
            and (stealMode() == "teleport" or G.__StealEggFarOn == true or opts.mode == "teleport")
        then
            if opts.mode ~= "walk" then
                opts.mode = "glide"
                mode = "glide"
            end
        end
        -- Instant teleport: glide Speed UI. Steal glide: geser, WalkSpeed = angka Speed.
        if (opts.mode or mode) == "glide" and stealMode() == "teleport" then
            opts.nativeWalkSpeed = true
            opts.lockGlideSpeed = true
            opts.skipRubberWait = true
            opts.skipStall = true
            opts.skipIntegrity = G.__StealEggVtQuiet == true
            pcall(function()
                Move.SetMode("glide")
                Move.SetSpeed(tonumber(opts.speed) or speed)
            end)
        elseif (opts.mode or mode) == "glide" then
            opts.nativeWalkSpeed = false
            opts.lockGlideSpeed = true
            opts.skipStall = true
            opts.skipIntegrity = G.__StealEggVtQuiet == true
        end
        -- Claim glide: geser CFrame saat gendong = Relocate, setoran tidak masuk.
        -- Speed tetap angka yang sama. Kakinya MoveTo, sama seperti walk.
        if stealMode() == "glide" and reason == "home" then
            mode = "walk"
            opts.mode = "walk"
            opts.nativeWalkSpeed = false
            opts.lockGlideSpeed = false
            pcall(function()
                Move.SetMode("walk")
                Move.SetSpeed(tonumber(opts.speed) or speed)
            end)
        end
        local fromPos = getRoot() and getRoot().Position
        local ok = Move.GoTo(dest, opts)
        local pd = G.StealEggPlaceDbg
        if type(pd) == "function" then
            local h = G.StealEggHatch
            if type(h) == "table" and h._placeBusy == true then
                local now = getRoot() and getRoot().Position
                pcall(pd, "travelTo", string.format(
                    "reason=%s ok=%s mode=%s from=%s dest=%s got=%s",
                    tostring(reason),
                    tostring(ok),
                    tostring(mode),
                    typeof(fromPos) == "Vector3" and string.format("%.1f,%.1f,%.1f", fromPos.X, fromPos.Y, fromPos.Z) or "-",
                    string.format("%.1f,%.1f,%.1f", dest.Position.X, dest.Position.Y, dest.Position.Z),
                    typeof(now) == "Vector3" and string.format("%.1f,%.1f,%.1f", now.X, now.Y, now.Z) or "-"
                ))
            end
        end
        if ok ~= true then
            dbg("DENY", "GoTo false reason=" .. tostring(reason))
        end
        return ok == true
    end
    if stealMode() == "walk" or stealMode() == "glide" then
        return false
    end
    return setCharCFrame(dest, reason)
end

-- Awal steal: selalu ke StartArea dulu kalau belum di atasnya (jangan lurus ke egg = nabrak).
-- Setelah carry: StartArea dulu, baru home. Sudah di plot: jangan muter StartArea.
-- Jangan fallback lurus ke dest kalau StartArea belum ada (first-load wall).
local function travelViaStartArea(dest, reason, shouldRun, extra)
    if typeof(dest) == "Vector3" then
        dest = CFrame.new(dest + Vector3.new(0, 3, 0))
    end
    if typeof(dest) ~= "CFrame" then
        return false
    end
    local hub = waitStartAreaCFrame(8, shouldRun)
    if typeof(hub) ~= "CFrame" then
        emit("Move", "warn", "waiting")
        return false
    end
    local root = getRoot()
    local from = root and root.Position
    if typeof(from) ~= "Vector3" then
        local t0 = os.clock()
        while os.clock() - t0 < 3 do
            if type(shouldRun) == "function" and shouldRun() == false then
                return false
            end
            root = getRoot()
            from = root and root.Position
            if typeof(from) == "Vector3" then
                break
            end
            task.wait(0.1)
        end
    end
    -- Default: jangan ke hub. from nil (char belum siap) jangan lurus ke egg.
    local needHub = false
    local atDest, atHub, dDest, dHub = false, false, -1, -1
    if typeof(from) == "Vector3" then
        atDest = xzNear(from, dest.Position, 32)
        atHub = xzNear(from, hub.Position, 12)
        local onRoad = math.abs(from.Z - hub.Position.Z) < 40
        if reason == "treadmill" then
            -- Pad plot / admin: lurus ke dest. Hub dulu = muter tengah lalu pad.
            needHub = false
        elseif reason == "home" or reason == "pet-area" then
            -- Treadmill sebelah PetArea: xz 32 ÃƒÂ¢Ã¢â‚¬Â°Ã‚Â  sudah di rumah. Masih di pad = belum sampai.
            if M.isOverTreadmillPad and M.isOverTreadmillPad() == true then
                atDest = false
            else
                atDest = xzNear(from, dest.Position, 8)
            end
            dDest = Vector3.new(from.X - dest.Position.X, 0, from.Z - dest.Position.Z).Magnitude
            dHub = Vector3.new(from.X - hub.Position.X, 0, from.Z - hub.Position.Z).Magnitude
            -- Place/pulang dari plot sendiri: lurus dest. Hub dulu = muter pad tengah.
            needHub = false
            if STEER.inOwnPlot(from, 80) ~= true and atDest ~= true and atHub ~= true and onRoad ~= true then
                needHub = dHub < dDest
            end
        else
            -- Egg drop di kaki / di belakang: jangan muter StartArea dulu.
            dDest = Vector3.new(from.X - dest.Position.X, 0, from.Z - dest.Position.Z).Magnitude
            dHub = Vector3.new(from.X - hub.Position.X, 0, from.Z - hub.Position.Z).Magnitude
            needHub = atHub ~= true and atDest ~= true and onRoad ~= true and dHub < dDest
            -- Yard plot (jauh dari jalan). 20ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“40st di sisi jalan = masih koridor, lurus ke egg.
            local yard = 80
            if from.Z > hub.Position.Z + yard and dest.Position.Z < hub.Position.Z + 40 then
                needHub = atHub ~= true and atDest ~= true and onRoad ~= true
            end
            if from.Z < hub.Position.Z - yard and dest.Position.Z > hub.Position.Z - 40 then
                needHub = atHub ~= true and atDest ~= true and onRoad ~= true
            end
        end
    end
    -- LongSnap teleport saja yang boleh skip hub di koridor. Combo walk/glide tetap via hub.
    if stealMode() == "teleport" and type(extra) == "table" and extra.longSnap == true
        and reason ~= "home" and reason ~= "pet-area" then
        if typeof(from) == "Vector3" and math.abs(from.Z - hub.Position.Z) <= 40 then
            needHub = false
        end
    end
    -- Walk/glide ke telur: wajib Start Area dulu, kecuali sudah di hub atau di telur.
    -- Telur jatuh karena hit: jangan muter pad. Langsung ke telur.
    if M._dropSnap == true and reason == "egg" then
        needHub = false
    elseif (stealMode() == "walk" or stealMode() == "glide")
        and reason == "egg"
        and atHub ~= true
        and atDest ~= true
    then
        local atPad = typeof(from) == "Vector3"
            and typeof(EGG.padPos) == "Vector3"
            and xzNear(from, EGG.padPos, 40) == true
        if atPad ~= true then
            needHub = true
        end
    end
    dbg("VIA", string.format(
        "reason=%s needHub=%s atDest=%s atHub=%s dDest=%.0f dHub=%.0f from=%s dest=%s",
        tostring(reason),
        tostring(needHub),
        tostring(atDest),
        tostring(atHub),
        dDest,
        dHub,
        typeof(from) == "Vector3" and string.format("V3(%.1f,%.1f,%.1f)", from.X, from.Y, from.Z) or "nil",
        string.format("V3(%.1f,%.1f,%.1f)", dest.Position.X, dest.Position.Y, dest.Position.Z)
    ))
    if needHub and (stealMode() == "walk" or stealMode() == "glide")
        and (reason == "egg" or reason == "hit")
    then
        -- Satu lari: lewat Start Area lalu telur. Jangan akhiri GoTo di hub
        -- (itu yang berhenti, lalu baru jalan lagi).
        local chain = {}
        if type(extra) == "table" then
            for k, v in pairs(extra) do
                chain[k] = v
            end
        end
        -- Sekali masuk Start Area, tujuan tetap telur. Kalau dibalik lagi ke hub
        -- tiap keluar radius 28, karakter muter di depan pad.
        local sawHub = false
        chain.goalFn = function()
            if sawHub ~= true then
                local here = getRoot()
                local p = here and here.Position
                if typeof(p) ~= "Vector3" or xzNear(p, hub.Position, START_NEAR) ~= true then
                    return hub
                end
                sawHub = true
            end
            return dest
        end
        return travelTo(dest, reason, shouldRun, chain)
    end
    if needHub then
        emit("Move", "live", "hub")
        local hubOk = travelTo(hub, "start-area", shouldRun)
        if type(shouldRun) == "function" and shouldRun() == false then
            return false
        end
        if isDead() then
            return false
        end
        local now = getRoot() and getRoot().Position
        local onHub = xzNear(now, hub.Position, START_NEAR)
        if hubOk ~= true and onHub ~= true then
            task.wait(0.2)
            if type(shouldRun) == "function" and shouldRun() == false then
                return false
            end
            if isDead() then
                return false
            end
            emit("Move", "live", "hub")
            hubOk = travelTo(hub, "start-area", shouldRun)
            now = getRoot() and getRoot().Position
            onHub = xzNear(now, hub.Position, START_NEAR)
        end
        -- Plot/belt (Z lebih selatan dari StartArea): jangan cut ke egg.
        -- GuardHitPlayer instant di ~X 680ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“720 Z -430.
        -- LongSnap skip hub: behind-refuse selalu gagal. Walk/glide combo: tetap guard.
        if (reason == "egg" or reason == "hit") then
            local snapSkip = stealMode() == "teleport" and type(extra) == "table" and extra.longSnap == true
            if snapSkip ~= true then
                now = getRoot() and getRoot().Position
                onHub = xzNear(now, hub.Position, START_NEAR)
                local behind = typeof(now) == "Vector3" and now.Z < hub.Position.Z - 24
                if onHub ~= true and behind == true then
                    dbg("VIA", "hub fail - refuse dest")
                    return false
                end
            end
        end
    end
    -- Dest dekat StartArea ÃƒÂ¢Ã¢â‚¬Â°Ã‚Â  sudah di dest. Setelah hub, tetap ke egg.
    return travelTo(dest, reason, shouldRun, extra)
end

local function treadmillRemotes()
    GM.Network = GM.Network or Core.require("Library.Client.Network")
    if type(GM.Network) == "table" and type(GM.Network.Treadmill) == "table" then
        return GM.Network.Treadmill
    end
    return nil
end

local function invokeTreadmill(name)
    local tm = treadmillRemotes()
    local rf = tm and tm[name]
    if (typeof(rf) == "Instance" or type(rf) == "table") and type(rf.InvokeServer) == "function" then
        local ok, a, b = pcall(function()
            return rf:InvokeServer()
        end)
        if ok then
            return a, b
        end
    end
    return nil
end

-- Dulu mute presentation.Stop() - itu reset CameraType ScriptableÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢Custom
-- di tengah FAR dan bikin steal/claim gagal (telur jatuh). Jangan sentuh lagi.
function M.muteTreadmillFx(_force)
end

function M.hookTreadmillFxMute()
end

local function hookBelt()
    if G.__StealEggBeltConn then
        return
    end
    local tm = treadmillRemotes()
    local ev = tm and tm.AssignedBeltShifted
    if not ev or not ev.OnClientEvent then
        return
    end
    G.__StealEggBeltConn = ev.OnClientEvent:Connect(function(id, _, _, _, _, isAdmin)
        M._onBelt = id ~= nil and id ~= false
        M._beltId = M._onBelt == true and id or nil
        M._adminBelt = M._onBelt == true and isAdmin == true
        G.__StealEggOnBelt = M._onBelt == true
        if M._onBelt == true and M._farmingBelt ~= true then
            -- Auto Treadmill sedang Hold("belt"): ini mount yang sah, jangan doff.
            local d = G.StealEggDispatch
            local who = type(d) == "table" and type(d.Owner) == "function" and d.Owner() or nil
            -- Mount baru boleh diakui sebagai farm kalau tidak ada fitur lain
            -- yang sedang memakai kaki. Syarat lamanya "who == belt ATAU
            -- autoTreadmill menyala", dan karena autoTreadmill hampir selalu
            -- menyala, mount nyasar di tengah perjalanan place pun ikut diakui
            -- sebagai farm. Begitu _farmingBelt menyala, kickOffBelt menolak
            -- turun - place terkunci di treadmill sampai jendelanya habis.
            local hold = G.__StealEggBeltHold
            local sideHold = type(hold) == "string" and hold ~= "" and hold ~= "home" and hold ~= "belt"
            local busy = who ~= nil and who ~= "belt"
            if sideHold == true then
                -- Mutation/place sedang pin belt: jangan adopt farm, doff saja.
                dbg("BELT", "hold=" .. tostring(hold) .. " - doff, no farm adopt")
                invokeTreadmill("AskDoff")
                local char = LP.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if hum then
                    pcall(function()
                        hum.Sit = false
                        hum.PlatformStand = false
                    end)
                end
            elseif busy ~= true and (who == "belt" or M.autoTreadmill == true) then
                M._farmingBelt = true
                dbg("BELT", "adopt mount | farm")
            else
            dbg("BELT", "accidental mount - doff admin=" .. tostring(isAdmin == true))
            -- Jangan Move.Stop: itu batal GoTo. AskDoff; Move belok keluar pad.
            invokeTreadmill("AskDoff")
            local char = LP.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function()
                    hum.Sit = false
                    hum.PlatformStand = false
                end)
            end
            end
        end
    end)
end

-- Dump: Workspace.AdminTreadmill (Tool) saat event globalAdminTreadmill.
-- AssignedBeltShifted(..., isAdmin). Plot TreadmillBottom tetap ada; admin di base.
local function firstBasePart(inst)
    if typeof(inst) ~= "Instance" then
        return nil
    end
    if inst:IsA("BasePart") then
        return inst
    end
    local named = inst:FindFirstChild("TreadmillBottom", true) or inst:FindFirstChild("Handle")
    if named and named:IsA("BasePart") then
        return named
    end
    local part = inst:FindFirstChildWhichIsA("BasePart", true)
    if part then
        return part
    end
    return nil
end

function M.adminPadBox()
    local inst = Workspace:FindFirstChild("AdminTreadmill")
    if typeof(inst) ~= "Instance" then
        G.__StealEggAdminPadPos = nil
        return nil
    end
    local part = firstBasePart(inst)
    local pos, half
    if part then
        pos = part.Position
        half = math.max(part.Size.X, part.Size.Z) * 0.5
    elseif inst:IsA("BasePart") then
        pos = inst.Position
        half = math.max(inst.Size.X, inst.Size.Z) * 0.5
    else
        local ok, cf, size = pcall(function()
            return inst:GetBoundingBox()
        end)
        if not (ok and typeof(cf) == "CFrame" and typeof(size) == "Vector3") then
            return nil
        end
        pos = Vector3.new(cf.Position.X, 70.7, cf.Position.Z)
        half = math.max(size.X, size.Z) * 0.5
    end
    half = math.clamp(half, 8, 16)
    G.__StealEggAdminPadPos = pos
    G.__StealEggAdminPadHit = half + 6
    return pos, half
end

local function plotTreadmillBottomPart()
    local data = getPlotData()
    local folder = data and data.PlotFolder
    if typeof(folder) == "Instance" then
        local bottom = folder:FindFirstChild("TreadmillBottom")
        if not bottom then
            bottom = folder:FindFirstChild("TreadmillBottom", true)
        end
        if bottom and bottom:IsA("BasePart") then
            return bottom
        end
    end
    local renders = Workspace:FindFirstChild("__ClientTreadmillRenders")
    if typeof(renders) == "Instance" then
        local root = renders:FindFirstChild("Root", true)
        if root and root:IsA("BasePart") then
            return root
        end
    end
    return nil
end

local function isOverPadPart(pos, part)
    if typeof(pos) ~= "Vector3" or typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return false
    end
    local rel = part.CFrame:PointToObjectSpace(pos)
    local half = part.Size * 0.5
    return math.abs(rel.X) <= half.X + 3
        and math.abs(rel.Z) <= half.Z + 3
        and rel.Y >= -2
        and rel.Y <= 12
end

local function isOverAdminPad(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local apos, ahalf = M.adminPadBox()
    if typeof(apos) ~= "Vector3" then
        return false
    end
    local xz = Vector3.new(pos.X - apos.X, 0, pos.Z - apos.Z).Magnitude
    return xz <= (ahalf or 10) + 4 and pos.Y <= apos.Y + 14 and pos.Y >= apos.Y - 6
end

-- Game auto AskWearStill if a down-ray of 8 studs hits TreadmillBottom.
-- Prioritas: AdminTreadmill kalau spawn di hub, baru belt plot sendiri.
local function isOverTreadmillPad(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    if isOverAdminPad(pos) then
        return true
    end
    local bottom = plotTreadmillBottomPart()
    if bottom and isOverPadPart(pos, bottom) then
        G.__StealEggPadPos = bottom.Position
        return true
    end
    return false
end

-- Helper belt di M.* - bukan local chunk (batas 200).
function M.wearingBelt()
    local char = LP.Character
    if not char then
        return false
    end
    if char:FindFirstChild("AdminTreadmill") ~= nil then
        return true
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum and (hum.Sit == true or hum.SeatPart ~= nil) then
        return true
    end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") then
            local n = string.lower(tostring(ch.Name))
            if string.find(n, "treadmill", 1, true) then
                return true
            end
        end
    end
    return false
end

function M.physicalOnBelt()
    local root = getRoot()
    if root and isOverTreadmillPad(root.Position) then
        return true
    end
    return M.wearingBelt() == true
end

-- Badan di pad / tool treadmill, ATAU server masih assign belt.
function M.beltStillOn()
    hookBelt()
    if M.physicalOnBelt() == true then
        return true
    end
    if M._onBelt == true or G.__StealEggOnBelt == true then
        return true
    end
    return false
end

function M.isOnBelt()
    return M.beltStillOn() == true
end

-- AssignedBeltShifted bisa nyangkut true setelah turun / Place tarik kandang.
-- Jangan hapus flag kalau badan masih di pad / masih pegang tool belt.
local function clearStaleBelt()
    if M.physicalOnBelt() == true then
        return false
    end
    if M._onBelt ~= true and G.__StealEggOnBelt ~= true then
        return false
    end
    dbg("BELT", "stale onBelt - not on pad")
    invokeTreadmill("AskDoff")
    M._onBelt = false
    M._beltId = nil
    M._adminBelt = false
    G.__StealEggOnBelt = false
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum.Sit = false
            hum.PlatformStand = false
        end)
    end
    return true
end

function M.isOverTreadmillPad()
    local root = getRoot()
    return root ~= nil and isOverTreadmillPad(root.Position)
end

local function treadmillStandCFrame()
    -- Prioritas: AdminTreadmill kalau ada/spawn di Workspace, baru belt plot.
    local apos = M.adminPadBox and select(1, M.adminPadBox())
    if typeof(apos) == "Vector3" then
        local y = tonumber(apos.Y) or 73.5
        if y > 75 or y < 68 then
            y = 73.5
        end
        return CFrame.new(apos.X, y, apos.Z)
    end
    local bottom = plotTreadmillBottomPart()
    if bottom then
        return CFrame.new(bottom.Position + Vector3.new(0, 4, 0))
    end
    return nil
end

local function ensureOffBelt(shouldRun)
    local function flattenLeaveVel()
        local root = getRoot()
        if not root then
            return
        end
        pcall(function()
            local v = root.AssemblyLinearVelocity
            local y = math.min(v.Y, 0)
            -- Jangan slam Y saat steal/carry (ragdoll/guard lempar = freeze).
            if G.__StealEggFarOn == true
                or G.__StealEggBusy == true
                or G.__StealEggClaiming == true
            then
                y = v.Y
            elseif root.Position.Y > 76 then
                y = -12
            end
            root.AssemblyLinearVelocity = Vector3.new(0, y, 0)
        end)
    end
    -- Dorong keluar hitbox pad. -6 stud sering masih di atas TreadmillBottom
    -- (game Heartbeat AskWearStill sinar 8 stud) jadi langsung remount.
    local function shoveOffPad()
        local root = getRoot()
        if not root or isOverTreadmillPad(root.Position) ~= true then
            return
        end
        pcall(function()
            local from = root.Position
            local pad = G.__StealEggAdminPadPos or G.__StealEggPadPos
            local dir
            if typeof(pad) == "Vector3" then
                dir = Vector3.new(from.X - pad.X, 0, from.Z - pad.Z)
                if dir.Magnitude < 0.5 then
                    dir = Vector3.new(-1, 0, 0)
                else
                    dir = dir.Unit
                end
            else
                dir = Vector3.new(-1, 0, 0)
            end
            local dest = from + dir * 22
            if stealMode() == "walk" or stealMode() == "glide" then
                local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if h then
                    h:MoveTo(Vector3.new(dest.X, from.Y, dest.Z))
                end
            else
                local rot = root.CFrame - root.CFrame.Position
                root.CFrame = CFrame.new(dest.X, from.Y, dest.Z) * rot
                root.AssemblyLinearVelocity = Vector3.zero
            end
        end)
    end
    local function pulseDoff()
        invokeTreadmill("AskDoff")
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function()
                hum.Sit = false
                hum.PlatformStand = false
                hum.Jump = true
            end)
        end
        flattenLeaveVel()
        shoveOffPad()
    end
    hookBelt()
    if M.beltStillOn() ~= true then
        M._farmingBelt = false
        return true
    end
    M._farmingBelt = false
    emit("Belt", "warn", "leaving treadmill")
    dbg("BELT", "AskDoff until off")
    local pd = G.StealEggPlaceDbg
    if type(pd) == "function" then
        pcall(pd, "ensureOffBelt", "start belt=" .. tostring(M._onBelt) .. " pad=" .. tostring(M.physicalOnBelt()))
    end
    local Move = getMove()
    if Move and type(Move.Stop) == "function" then
        pcall(Move.Stop)
    end
    local t0 = os.clock()
    local abort = false
    -- Jangan batal doff hanya karena shouldRun false: itu yang bikin
    -- steal jalan sambil server masih assign belt.
    while M.beltStillOn() == true and os.clock() - t0 < 6 do
        if type(shouldRun) == "function" and shouldRun() == false then
            abort = true
        end
        pulseDoff()
        task.wait(0.15)
    end
    flattenLeaveVel()
    if M.physicalOnBelt() == true then
        dbg("BELT", string.format(
            "still on after doff belt=%s pad=%s wear=%s",
            tostring(M._onBelt),
            tostring(getRoot() and isOverTreadmillPad(getRoot().Position)),
            tostring(M.wearingBelt())
        ))
        return false
    end
    if M._onBelt == true or G.__StealEggOnBelt == true then
        clearStaleBelt()
    end
    if M.physicalOnBelt() == true then
        return false
    end
    -- Heartbeat game bisa AskWearStill 1,25s kalau masih di atas Bottom.
    task.wait(0.1)
    if M.physicalOnBelt() == true then
        pulseDoff()
        task.wait(0.12)
        if M.physicalOnBelt() == true then
            dbg("BELT", "remounted after doff")
            return false
        end
    end
    dbg("BELT", "off treadmill ok")
    if abort == true then
        return false
    end
    return true
end

function M.ensureOffBelt(shouldRun)
    return ensureOffBelt(shouldRun)
end

function M.kickOffBelt()
    -- Place/mutation/index: selalu boleh turun, termasuk saat farm nyala.
    -- Dulu return false saat _farmingBelt ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Place stuck "Going" di treadmill.
    hookBelt()
    M._farmingBelt = false
    invokeTreadmill("AskDoff")
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum.Sit = false
            hum.PlatformStand = false
        end)
    end
    return true
end

-- Place/sell: tahan farm, turun belt, kerja di plot, lalu release supaya steal naik lagi.
function M.borrowBelt(reason)
    hookBelt()
    G.__StealEggBeltHold = tostring(reason or "plot")
    M._farmingBelt = false
    -- Berdiri di atas pad tanpa status onBelt tetap berbahaya: sinar 8 stud
    -- milik game memasang kita lagi begitu place mulai bergerak. Jadi yang
    -- diperiksa bukan hanya _onBelt, tapi juga posisinya. ensureOffBelt memang
    -- sudah menangani dua-duanya, termasuk mendorong badan keluar dari pad.
    local root = getRoot()
    local onPad = root ~= nil and isOverTreadmillPad(root.Position)
    if M.beltStillOn() ~= true then
        return true
    end
    return ensureOffBelt()
end

function M.releaseBelt()
    G.__StealEggBeltHold = nil
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Release) == "function" then
        local who = type(d.Owner) == "function" and d.Owner() or nil
        if who == "place" or who == "index" or who == "plot" then
            pcall(d.Release, who)
        end
    end
end

-- Hanya nahan treadmill saat Place/Index benar-benar kerja di plot.
-- Index "Idle | N missing" / bag masih ada telur ÃƒÂ¢Ã¢â‚¬Â°Ã‚Â  sedang place. Kalau nunggu
-- hasPlacePending, steal diam di kandang selamanya (status Going basi).
-- BeltHold "place" sisa ensureInPen setelah Idle empty jangan dianggap masih kerja.
local function placeKeepsPlot()
    local h = G.StealEggHatch
    local idx = G.StealEggIndexComplete
    local placing = type(h) == "table" and h._placeBusy == true
    local indexing = type(idx) == "table" and idx._busy == true
    if placing == true or indexing == true then
        return true
    end
    local hold = tostring(G.__StealEggBeltHold or "")
    if hold == "place" or hold == "index" or hold == "plot" then
        G.__StealEggBeltHold = nil
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, hold == "plot" and "place" or hold)
        end
    end
    return false
end

function M.beltYield()
    -- Mid Instant session: jangan putus chain ÃƒÆ’Ã¢â‚¬â€3 karena place/sell pending.
    if G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
        return false
    end
    local hold = G.__StealEggBeltHold
    -- goHomeNow nyetel "home" lalu lupa lepas ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ steal idle di PetArea.
    -- Place/index Idle empty juga sering nyisain hold "place".
    if hold == "home" or hold == "place" or hold == "index" or hold == "plot" then
        local h = G.StealEggHatch
        local idx = G.StealEggIndexComplete
        local placing = type(h) == "table" and h._placeBusy == true
        local indexing = type(idx) == "table" and idx._busy == true
        if placing ~= true and indexing ~= true then
            G.__StealEggBeltHold = nil
            local d = G.StealEggDispatch
            if type(d) == "table" and type(d.Release) == "function" then
                pcall(d.Release, hold == "plot" and "place" or hold)
            end
            hold = nil
        end
    end
    if hold then
        return true
    end
    local sell = G.StealEggSell
    if type(sell) == "table" and type(sell.pet) == "table" and sell.pet._busy == true then
        return true
    end
    local hatch = G.StealEggHatch
    if type(hatch) == "table" and hatch._placeBusy == true then
        return true
    end
    local idx = G.StealEggIndexComplete
    if type(idx) == "table" and idx._busy == true then
        return true
    end
    return false
end

-- Place/Index punya kerja di plot: belt harus minggir (jangan nunggu egg open).
-- Method M.* - hemat register chunk (batas 200 local).
function M.placeWantsLegs()
    local h = G.StealEggHatch
    if type(h) == "table" and h.placeEnabled == true then
        if h._placeBusy == true then
            return true
        end
        if type(h.hasPlacePending) == "function" then
            local ok, yes = pcall(h.hasPlacePending)
            if ok and yes == true then
                return true
            end
        end
    end
    local idx = G.StealEggIndexComplete
    if type(idx) == "table" and idx._busy == true then
        return true
    end
    return false
end

-- Mutation shard sedang kerja: jangan remount treadmill (rebutan Used ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬Â Belt).
-- Method M.* (bukan local function) - chunk sudah ~198 local, +1 = 200 limit ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ WildEgg=nil.
function M.mutationWantsLegs()
    if tostring(G.__StealEggBeltHold or "") == "mutation" then
        return true
    end
    local mut = G.StealEggMutation or (G.StealEggLoaded and G.StealEggLoaded.Mutation)
    if type(mut) ~= "table" or mut.enabled ~= true then
        return false
    end
    if type(mut.hasWork) == "function" then
        local ok, yes = pcall(mut.hasWork)
        if ok and yes == true then
            return true
        end
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Is) == "function" then
        local ok, mine = pcall(d.Is, "mutation")
        if ok and mine == true then
            return true
        end
    end
    return false
end

-- Place/Index busy: jangan diam di claim pad / safe zone. Tarik PetArea cepat
-- (dulu fungsi ini tidak dipanggil + early-return saat _placeBusy ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ freeze ~10s).
local lastStayPlotPull = 0

-- Hanya kalau scramble boleh pakai kaki. _busy/_want saja bukan alasan
-- merebut pulang / dekat telur: wantsWork sudah cek stealBlocksScramble.
local function scrambleNeedsLegs()
    local scramble = G.StealEggScramble
    if type(scramble) ~= "table" or scramble.enabled ~= true then
        return false
    end
    if type(scramble.wantsWork) == "function" then
        local ok, want = pcall(scramble.wantsWork)
        return ok == true and want == true
    end
    return false
end

local function stealIdleStayPlot(seq)
    if scrambleNeedsLegs() == true then
        return
    end
    if placeKeepsPlot() ~= true then
        return
    end
    if stealWanted(seq) ~= true or G.__StealEggBusy == true then
        return
    end
    local hatch = G.StealEggHatch
    if type(hatch) == "table" and type(hatch.plotAtCap) == "function" then
        local okf, full = pcall(hatch.plotAtCap)
        if okf and full == true then
            return
        end
    end
    emitIfChanged("Wait", "live", "plot")
    do
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "steal")
        end
    end
    local function still()
        return stealWanted(seq) == true
            and G.__StealEggBusy ~= true
            and placeKeepsPlot() == true
    end
    -- Thaw sisa FAR/claim (Anchored). restoreMove sering skip kalau flag belt salah.
    G.__StealEggTpHold = false
    G.__StealEggMoveQuiet = false
    do
        local root = getRoot()
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        pcall(function()
            if root then
                root.Anchored = false
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end
            if hum and (tonumber(hum.Health) or 0) > 0 then
                hum.PlatformStand = false
            end
        end)
    end
    local inPen = M.isOnPetArea() == true and M.isOverTreadmillPad() ~= true
    if inPen then
        task.wait(0.12)
        return
    end
    if os.clock() - lastStayPlotPull < 0.75 then
        task.wait(0.12)
        return
    end
    lastStayPlotPull = os.clock()
    dbg("IDLE", string.format(
        "wait-plot pull PetArea belt=%s placeBusy=%s idxBusy=%s",
        tostring(G.__StealEggBeltHold),
        tostring(type(hatch) == "table" and hatch._placeBusy == true),
        tostring(type(G.StealEggIndexComplete) == "table" and G.StealEggIndexComplete._busy == true)
    ))
    ensureOffBelt(still)
    if still() ~= true then
        return
    end
    if M.isOnPetArea() == true and M.isOverTreadmillPad() ~= true then
        return
    end
    -- Pakai M.ensureInPen (bukan getPetStandPos lokal) - defined later, OK di runtime.
    local why = "place"
    local idx = G.StealEggIndexComplete
    if type(idx) == "table" and idx._busy == true
        and not (type(hatch) == "table" and hatch._placeBusy == true)
    then
        why = "index"
    end
    -- Jendela Place: ensureInPen boleh jalan ke PetArea meski Steal ON.
    local hadWindow = G.__StealEggPlaceWindow == true
    G.__StealEggPlaceWindow = true
    local okPen = false
    if type(M.ensureInPen) == "function" then
        local ok, v = pcall(M.ensureInPen, why, still)
        okPen = ok == true and v == true
    end
    if hadWindow ~= true then
        G.__StealEggPlaceWindow = false
    end
    if type(EGG.restoreMove) == "function" then
        pcall(EGG.restoreMove, okPen and "wait-plot" or "wait-plot-miss")
    end
    if okPen ~= true then
        task.wait(0.15)
    end
end

local function farmTreadmill(shouldRun)
    -- Jangan rebut kaki Instant: farm belt memotong FAR ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ ForestHitAt 0 + steal fail.
    if G.__StealEggFarOn == true or G.__StealEggClaiming == true or G.__StealEggBusy == true then
        return false
    end
    -- Ada telur: jangan naik. Kalau sudah di belt, turun dulu (jangan Hold belt).
    if type(shouldRun) == "function" and shouldRun() == false then
        M._farmingBelt = false
        if M.beltStillOn() == true then
            ensureOffBelt(function()
                return true
            end)
        end
        return false
    end
    hookBelt()
    placeKeepsPlot()
    -- Place/Index pending + steal idle: JANGAN Hold belt. Place rank lebih tinggi.
    if M.placeWantsLegs() == true and M.canSideWork() == true then
        M._farmingBelt = false
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "belt")
        end
        return false
    end
    -- Mutation Used/Using: jangan rebut naik belt.
    if M.mutationWantsLegs() == true then
        M._farmingBelt = false
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "belt")
        end
        if M._onBelt == true or (getRoot() and isOverTreadmillPad(getRoot().Position)) then
            pcall(M.kickOffBelt)
        end
        return false
    end
    if M.beltYield() == true then
        return false
    end
    if placeKeepsPlot() then
        return false
    end
    if M.wallHold() == true then
        return false
    end
    if type(shouldRun) == "function" and shouldRun() == false then
        return false
    end
    do
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Hold) == "function" then
            if d.Hold("belt") ~= true then
                local who = type(d.Owner) == "function" and d.Owner() or nil
                if (who == "place" or who == "index") and placeKeepsPlot() ~= true then
                    pcall(d.Release, who)
                end
                if d.Hold("belt") ~= true then
                    return false
                end
            end
        end
    end
    local function dropBelt()
        M._farmingBelt = false
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "belt")
        end
    end
    clearStaleBelt()
    local apos, ahalf = M.adminPadBox()
    local wantAdmin = typeof(apos) == "Vector3"
    local beltLabel = wantAdmin and "admin treadmill" or "treadmill"
    local root = getRoot()
    -- Sudah di pad + belt: jangan restoreMove (itu unsit ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ berdiri tanpa lari).
    -- Admin spawn: kalau masih di belt plot, pindah ke admin.
    if M._onBelt == true and root and isOverTreadmillPad(root.Position) then
        if type(shouldRun) == "function" and shouldRun() == false then
            dropBelt()
            ensureOffBelt(function()
                return true
            end)
            return false
        end
        M._farmingBelt = true
        if wantAdmin == true then
            local xz = Vector3.new(root.Position.X - apos.X, 0, root.Position.Z - apos.Z).Magnitude
            if xz <= (ahalf or 10) + 4 then
                emitIfChanged("Belt", "live", beltLabel)
                return true
            end
            dbg("BELT", "switch to admin treadmill")
            invokeTreadmill("AskDoff")
            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function()
                    hum.Sit = false
                    hum.PlatformStand = false
                end)
            end
            local tOff = os.clock()
            while M._onBelt == true and os.clock() - tOff < 2.5 do
                if type(shouldRun) == "function" and shouldRun() == false then
                    dropBelt()
                    ensureOffBelt(function()
                        return true
                    end)
                    return false
                end
                invokeTreadmill("AskDoff")
                if hum then
                    pcall(function()
                        hum.Sit = false
                        hum.PlatformStand = false
                    end)
                end
                task.wait(0.15)
            end
        else
            emitIfChanged("Belt", "live", beltLabel)
            return true
        end
    end
    -- Di atas pad tapi belum AssignedBelt: pakai, jangan thaw dulu.
    if root and isOverTreadmillPad(root.Position) == true and M._onBelt ~= true then
        M._farmingBelt = true
        emitIfChanged("Belt", "live", "mounting")
        local tWear = os.clock()
        while M._onBelt ~= true and os.clock() - tWear < 3 do
            if type(shouldRun) == "function" and shouldRun() == false then
                dropBelt()
                ensureOffBelt(function()
                    return true
                end)
                return false
            end
            invokeTreadmill("AskWearStill")
            task.wait(0.2)
        end
        if M._onBelt == true then
            emitIfChanged("Belt", "live", beltLabel)
            return true
        end
    end
    if type(EGG.restoreMove) == "function" then
        pcall(EGG.restoreMove, "pre-belt")
    end
    local dest = treadmillStandCFrame()
    if typeof(dest) ~= "CFrame" then
        emit("Belt", "warn", "treadmill missing")
        dropBelt()
        return false
    end
    M._farmingBelt = true
    emit("Belt", "live", beltLabel)
    travelViaStartArea(dest, "treadmill", shouldRun)
    if type(shouldRun) == "function" and shouldRun() == false then
        dropBelt()
        if M.beltStillOn() == true then
            ensureOffBelt(function()
                return true
            end)
        end
        return false
    end
    root = getRoot()
    if M._onBelt == true and root and isOverTreadmillPad(root.Position) then
        emitIfChanged("Belt", "live", beltLabel)
        return true
    end
    local t0 = os.clock()
    while M._onBelt ~= true and os.clock() - t0 < 4 do
        if type(shouldRun) == "function" and shouldRun() == false then
            dropBelt()
            ensureOffBelt(function()
                return true
            end)
            return false
        end
        invokeTreadmill("AskWearStill")
        task.wait(0.25)
    end
    root = getRoot()
    if M._onBelt == true and root and isOverTreadmillPad(root.Position) then
        emitIfChanged("Belt", "live", beltLabel)
        return true
    end
    if M._onBelt == true then
        clearStaleBelt()
    end
    dropBelt()
    return false
end

function M.farmTreadmill(shouldRun)
    return farmTreadmill(shouldRun)
end

local function isEggTool(tool)
    return typeof(tool) == "Instance"
        and tool:IsA("Tool")
        and tool:GetAttribute("ItemType") == "AssetEgg"
end

local function isPetTool(tool)
    if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
        return false
    end
    local kind = tool:GetAttribute("ItemType")
    return kind == "Asset" or kind == "Pet" or kind == "Brainrot"
end

local function toolUid(tool)
    local uid = tool:GetAttribute("UID")
    if type(uid) == "string" and uid ~= "" then
        return uid
    end
    return nil
end

local function eggInventoryMap()
    local map = {}
    bindGame()
    local bag
    local data = getSave()
    if type(data) == "table" and type(data.EggInventory) == "table" then
        bag = data.EggInventory
    end
    if type(bag) ~= "table" and type(GM.Save) == "table" and type(GM.Save.Get) == "function" then
        local ok, d = pcall(GM.Save.Get)
        if ok and type(d) == "table" and type(d.EggInventory) == "table" then
            bag = d.EggInventory
        end
    end
    if type(bag) ~= "table" then
        return map
    end
    for uid, rec in pairs(bag) do
        if type(rec) == "table" then
            map[tostring(uid)] = rec
        end
    end
    return map
end

local function snapshotEggInventory()
    local map = eggInventoryMap()
    local set = {}
    for uid in pairs(map) do
        set[uid] = true
    end
    M._invBefore = set
    return set
end

local function stolenCategory()
    if type(M._stolen) == "table" and M._stolen.category then
        return tostring(M._stolen.category)
    end
    if M._carry.AssetCategory then
        return tostring(M._carry.AssetCategory)
    end
    if type(M._claimed) == "table" and M._claimed.AssetCategory then
        return tostring(M._claimed.AssetCategory)
    end
    return nil
end

local function findStolenEggTool(category)
    category = category or stolenCategory()
    local function match(parent)
        if not parent then
            return nil
        end
        for _, child in ipairs(parent:GetChildren()) do
            if isEggTool(child) then
                local cat = child:GetAttribute("AssetCategory") or child:GetAttribute("Category")
                if category == nil or tostring(cat) == tostring(category) then
                    return child, toolUid(child)
                end
            end
        end
        return nil
    end
    local tool, uid = match(LP.Character)
    if tool then
        return tool, uid
    end
    return match(LP:FindFirstChild("Backpack"))
end

local function findStolenEggUid(category)
    category = category or stolenCategory()
    local tool, toolId = findStolenEggTool(category)
    if toolId then
        return toolId, tool
    end

    local before = M._invBefore or {}
    local inv = eggInventoryMap()
    local fallbackNew = nil
    for uid, rec in pairs(inv) do
        if rec.Placement == nil then
            local catOk = category == nil or tostring(rec.AssetCategory) == tostring(category)
            local isNew = before[uid] ~= true
            if catOk and isNew then
                return uid, nil
            end
            if isNew then
                fallbackNew = fallbackNew or uid
            end
        end
    end
    if fallbackNew then
        return fallbackNew, nil
    end
    return nil, nil
end

local function characterEggUids()
    local uids = {}
    local char = LP.Character
    if not char then
        return uids
    end
    for _, child in ipairs(char:GetChildren()) do
        if isEggTool(child) then
            local uid = toolUid(child)
            if uid then
                uids[#uids + 1] = uid
            end
        end
    end
    return uids
end

local function unequipPets()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then
        return
    end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped and not isEggTool(equipped) then
        pcall(function()
            hum:UnequipTools()
        end)
        local uid = toolUid(equipped)
        if uid then
            Core.eggCall("RequestUnequipTool", uid)
        end
    end
end

local function getExitHomePos()
    local line = getSeparationLine()
    if line and line:IsA("BasePart") then
        return line.Position + Vector3.new(0, 3, 0) - line.CFrame.LookVector.Unit * 6
    end
    return getPlotHome()
end

local function getPetStandPos()
    local data = getPlotData()
    if type(data) ~= "table" then
        return getPlotHome()
    end
    local pet = data.PetArea
    if typeof(pet) == "Instance" then
        return pet.Position + Vector3.new(0, pet.Size.Y * 0.5 + 3, 0)
    end
    if typeof(data.CenterPoint) == "Instance" then
        return data.CenterPoint.Position + Vector3.new(0, 4, 0)
    end
    return getPlotHome()
end

local function inLocalPlotBounds(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    if type(GM.PlotCmds) == "table" then
        local fn = GM.PlotCmds.IsWorldPositionWithinLocalPlotBounds or GM.PlotCmds.ContainsLocalPoint
        if type(fn) == "function" then
            local ok, v = pcall(fn, pos)
            if ok and v == true then
                return true
            end
        end
    end
    local data = getPlotData()
    local folder = data and data.PlotFolder
    if typeof(folder) == "Instance" then
        local inst = folder
        if not folder:IsA("Model") then
            local tu = folder:FindFirstChild("ToUpdate")
            if tu and tu:IsA("Model") then
                inst = tu
            end
        end
        local ok, cf, size = pcall(function()
            return inst:GetBoundingBox()
        end)
        if ok and typeof(cf) == "CFrame" and typeof(size) == "Vector3" then
            local localPos = cf:PointToObjectSpace(pos)
            local half = size * 0.5
            return math.abs(localPos.X) <= half.X and math.abs(localPos.Z) <= half.Z
        end
    end
    return false
end

local function inLocalPlot()
    local root = getRoot()
    if not root then
        return false
    end
    return inLocalPlotBounds(root.Position)
end

function M.isOnStartArea()
    local root = getRoot()
    if not root then
        return false
    end
    local hub = startAreaCFrame()
    if typeof(hub) ~= "CFrame" then
        return false
    end
    return xzNear(root.Position, hub.Position, 22)
end

-- Plot home = dalam batas plot sendiri, bukan StartArea, bukan treadmill.
function M.inPlotHome()
    local root = getRoot()
    if not root then
        return false
    end
    if isOverTreadmillPad(root.Position) then
        return false
    end
    if M.isOnStartArea() == true then
        return false
    end
    return inLocalPlot() == true
end

local function standOnPetArea(data)
    local pos = getPetStandPos()
    if typeof(pos) ~= "Vector3" then
        return false
    end
    return travelTo(pos, "pet-area")
end

local function isOnPetAreaPos(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local data = getPlotData()
    local pet = data and data.PetArea
    if typeof(pet) ~= "Instance" then
        return inLocalPlotBounds(pos)
    end
    local localPos = pet.CFrame:PointToObjectSpace(pos)
    local half = pet.Size * 0.5
    return math.abs(localPos.X) <= half.X + 4
        and math.abs(localPos.Z) <= half.Z + 4
        and localPos.Y > -10
        and localPos.Y < half.Y + 24
end

function M.isOnPetArea()
    local root = getRoot()
    if not root then
        return false
    end
    if isOverTreadmillPad(root.Position) then
        return false
    end
    return isOnPetAreaPos(root.Position)
end

function M.getPlotData()
    return getPlotData()
end

-- Dump HeadToPen / HasReturnedToPen: PetArea (ÃƒÂ¢Ã¢â‚¬Â°Ã‚Â¤18) or plot bbox. Place must be on PetArea, not StartArea.
function M.ensureInPen(reason, shouldRun)
    local why = tostring(reason or "")
    local forPlace = why == "place" or why == "index"
    if G.__StealEggClaiming == true then
        return false
    end
    -- Place/index jangan Stop steal. Busy = lagi Going ke egg.
    if G.__StealEggBusy == true then
        return false
    end
    -- Steal ON + ada match: Place/Index jangan tarik PetArea (ganggu Going).
    if forPlace and M.enabled == true and G.__StealEggWanted == true and G.__StealEggPlaceWindow ~= true then
        if EGG.hasPick() == true or EGG.hasPickPos() == true then
            dbg("HOME", "skip place pen - steal has pick")
            return false
        end
    end
    do
        local who = "place"
        if why == "index" then
            who = "index"
        elseif why == "sell" then
            who = "sell"
        end
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Hold) == "function" and d.Hold(who) ~= true then
            return false
        end
    end
    if M._farmingBelt == true and why ~= "sell" then
        local h = G.StealEggHatch
        if type(h) == "table" and type(h.plotAtCap) == "function" then
            local ok, full = pcall(h.plotAtCap)
            if ok and full == true then
                return false
            end
        end
    end
    hookBelt()
    G.__StealEggBeltHold = why ~= "" and why or "plot"
    M._farmingBelt = false
    local function atHome()
        local root = getRoot()
        if not root then
            return false
        end
        if isOverTreadmillPad(root.Position) then
            return false
        end
        if M.isOnStartArea() == true then
            return false
        end
        if M.isOnPetArea() == true then
            return true
        end
        if forPlace then
            -- Dulu di sini nearPetArea(pos, 18). Angka 18 itu disalin dari
            -- MilestoneAdapter.HasReturnedToPen, yang ternyata cuma pelacak
            -- tutorial HeadToPen - bukan syarat menaruh telur sama sekali.
            -- Akibatnya nyata dan terukur: pad treadmill plot ini hanya 18,9
            -- stud dari tepi PetArea (pad 480,68,-487 vs PetArea 409,68,-523
            -- ukuran 112x49), jadi tanah tepat di sebelah pad sudah dihitung
            -- "sudah di kandang". Place turun belt, bergeser dua langkah, lalu
            -- berhenti - masih di dalam jangkauan sinar 8 stud yang membuat
            -- game memasang kita balik ke treadmill. Itulah tarik-menariknya.
            -- Menuntut benar-benar di PetArea sekaligus menjamin jauh dari pad.
            return isOnPetAreaPos(root.Position)
        end
        return inLocalPlot() == true
    end
    if atHome() then
        return true
    end
    local dStop = G.StealEggDispatch
    local own = type(dStop) == "table" and type(dStop.Owner) == "function" and dStop.Owner() or nil
    if own ~= "steal" and own ~= "claim" then
        local Move = getMove()
        if Move and type(Move.Stop) == "function" then
            pcall(Move.Stop)
        end
    end
    if M._onBelt == true then
        emit("Belt", "warn", "leaving treadmill")
        dbg("BELT", "AskDoff then walk off pad")
        invokeTreadmill("AskDoff")
    end
    if type(shouldRun) == "function" and shouldRun() == false then
        return false
    end
    if atHome() then
        return true
    end
    local pos = getPetStandPos()
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local function still()
        if type(shouldRun) == "function" and shouldRun() == false then
            return false
        end
        return true
    end
    local function doffTick()
        if M._onBelt == true then
            invokeTreadmill("AskDoff")
        end
    end
    -- Place selalu jalan/glide - jangan ikut steal Instant (CFrame plant).
    if forPlace and stealMode() == "teleport" then
        pcall(function()
            if type(EGG.endFarSession) == "function" then
                EGG.endFarSession("place-pen")
            end
        end)
        EGG.stopMove()
        G.__StealEggTpHold = false
        G.__StealEggMoveQuiet = false
        dbg("HOME", "place ignore Instant | walk PetArea")
    end
    -- Lurus ke PetArea. Via StartArea dari pad plot = muter ke jalan tengah.
    local petCf = CFrame.new(pos + Vector3.new(0, 3, 0))
    travelTo(petCf, "pet-area", still, { onTick = doffTick })
    if type(shouldRun) == "function" and shouldRun() == false then
        return false
    end
    if M._onBelt == true then
        invokeTreadmill("AskDoff")
    end
    if atHome() ~= true then
        travelTo(petCf, "pet-area", still, { onTick = doffTick })
    end
    return atHome()
end

local function localPlaceCFrame(data)
    local h = G.StealEggHatch
    if type(h) == "table" and type(h.nextPlaceCFrame) == "function" then
        local ok, cf = pcall(h.nextPlaceCFrame, data)
        if ok and typeof(cf) == "CFrame" then
            return cf
        end
        return nil
    end
    if type(data) ~= "table" then
        return nil
    end
    local pet = data.PetArea
    local center = data.CenterPoint
    if typeof(pet) ~= "Instance" or typeof(center) ~= "Instance" then
        return nil
    end
    local GRID = 2.25
    local half = pet.Size * 0.5
    local worldPos = (pet.CFrame * CFrame.new(-half.X + GRID * 0.5, half.Y, -half.Z + GRID * 0.5)).Position
    return center.CFrame:ToObjectSpace(CFrame.new(worldPos))
end

local function returnAndClaim(category)
    emit("Home", "live", "going home")
    local petPos = getPetStandPos()
    if petPos then
        travelViaStartArea(petPos, "pet-area")
    else
        local hub = startAreaCFrame()
        if hub then
            travelTo(hub, "start-area")
        end
    end

    local t0 = os.clock()
    while M.enabled and os.clock() - t0 < 8 do
        if M._carry.IsCarrying ~= true then
            local name = category
            if type(M._claimed) == "table" then
                name = M._claimed.DisplayName or M._claimed.AssetCategory or name
            end
            emit("Claim", "success", tostring(name or "egg"))
            task.wait(0.2)
            return true
        end
        if not inLocalPlot() and petPos then
            travelViaStartArea(petPos, "pet-area")
        end
        emit("Claim", "live", "carrying")
        task.wait(0.12)
    end

    emit("Denied", "warn", "claim timeout")
    return false
end

local function placeHeldEgg(preferCategory)
    if M.place ~= true then
        M._needPlace = false
        return true
    end

    preferCategory = preferCategory or stolenCategory()

    if M._carry.IsCarrying == true then
        if not returnAndClaim(preferCategory) then
            return false
        end
    end

    local data = getPlotData()
    if not data then
        emit("Denied", "warn", "plot missing")
        return false
    end

    unequipPets()
    emit("Place", "live", "egg steal | " .. tostring(preferCategory or "?"))
    standOnPetArea(data)

    local uid
    local t0 = os.clock()
    while M.enabled and os.clock() - t0 < 5 do
        uid = findStolenEggUid(preferCategory)
        if uid then
            break
        end
        emit("Place", "live", "waiting " .. tostring(preferCategory or "egg"))
        task.wait(0.15)
    end

    if not uid then
        emit("Denied", "warn", "egg not in inventory")
        return false
    end

    unequipPets()

    local hatch = G.StealEggHatch
    if type(hatch) == "table" and type(hatch.plotAtCap) == "function" then
        local okCap, full = pcall(hatch.plotAtCap)
        if okCap and full == true then
            emit("Denied", "warn", "plot full")
        return false
        end
    end

    local localCf = localPlaceCFrame(data)
    if typeof(localCf) ~= "CFrame" then
        emit("Denied", "warn", "no slot")
        return false
    end

    emit("Place", "live", tostring(preferCategory or "egg"))
    if M.inPlotHome() ~= true then
        emit("Denied", "warn", "need plot")
        return false
    end
    local ok, success, err = Core.eggCall("RequestPlaceEgg", uid, localCf)
    local function doffPlaceEgg()
        local char = LP.Character
        local tool = char and char:FindFirstChildWhichIsA("Tool")
        if not (tool and isEggTool(tool)) then
            return
        end
        local u = toolUid(tool)
        if u then
            Core.eggCall("RequestUnequipTool", u)
        end
        Core.eggCall("RequestUnequipTool")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function()
                hum:UnequipTools()
            end)
        end
    end
    if ok and success == true then
        local renderer = Core.require("Library.Client.Eggs.PlacedEggRenderer")
        if type(renderer) == "table" and type(renderer.Refresh) == "function" then
            pcall(renderer.Refresh)
        end
        M._needPlace = false
        M._stolen = nil
            emit("Placed", "success", tostring(preferCategory or "egg"))
        task.wait(0.2)
        doffPlaceEgg()
        return true
    end
    -- Plant gagal sering sisakan egg Wear di tangan ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ doff.
    task.wait(0.05)
    doffPlaceEgg()
    local why = tostring(err or success or "place failed")
    local low = string.lower(why)
    if string.find(low, "too many", 1, true) or string.find(low, "full", 1, true) or string.find(low, "many egg", 1, true) then
        if type(hatch) == "table" and type(hatch.rememberPlaceMax) == "function" then
            pcall(hatch.rememberPlaceMax)
        end
        emit("Denied", "warn", "plot full")
    else
        emit("Denied", "warn", "place failed")
    end
    return false
end

local function unequipOnce()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local uids = characterEggUids()
    if #uids == 0 then
        local uid = findStolenEggUid()
        if uid then
            uids = { uid }
        end
    end
    if M._stolen and M._stolen.carryUid then
        uids[#uids + 1] = tostring(M._stolen.carryUid)
    end
    local seen = {}
    for _, uid in ipairs(uids) do
        if uid and not seen[uid] then
            seen[uid] = true
            Core.eggCall("RequestUnequipTool", uid)
        end
    end
    Core.eggCall("RequestUnequipTool")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function plotHomeCFrame()
    local data = getPlotData()
    if type(data) == "table" then
        -- StealFix decoy/claim @ ~515,-363 = Spawn/Respawn. JANGAN PetArea dulu
        -- (PetArea ~428,-244 ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ decoy salah + stage Forest gagal di dump Node).
        local spawn = data.PlotFolder and data.PlotFolder:FindFirstChild("SpawnPoint")
        if spawn and spawn:IsA("BasePart") then
            return spawn.CFrame + Vector3.new(0, 3, 0)
        end
        if typeof(data.RespawnPointCFrame) == "CFrame" then
            return data.RespawnPointCFrame
        end
        local center = worldPosition(data.CenterPoint)
        if typeof(center) == "Vector3" then
            local hub = startAreaCFrame()
            local x, z = center.X, center.Z
            if typeof(hub) == "CFrame" then
                -- Tepi plot ke arah koridor telur (StealFix home).
                if hub.Position.X > center.X then
                    x = center.X + math.min(90, math.max(40, (hub.Position.X - center.X) * 0.12))
                end
                z = hub.Position.Z + math.clamp(center.Z - hub.Position.Z, -28, 28)
            end
            return CFrame.new(x, center.Y + 3, z)
        end
        local pet = getPetStandPos()
        if typeof(pet) == "Vector3" then
            return CFrame.new(pet + Vector3.new(0, 3, 0))
        end
    end
    local home = getPlotHome() or captureHome()
    if typeof(home) == "Vector3" then
        return CFrame.new(home + Vector3.new(0, 3, 0))
    end
    return nil
end

-- Forest claim pad (SF/MaxEarn ~515,74,-363) - bukan SpawnPoint plot (~492).
function EGG.claimPadCFrame()
    local padBase = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
    return CFrame.new(padBase.X, 74, padBase.Z)
end

-- Dari area egg jauh (Prehistoric/Cosmic): snap ke pad + hold singkat.
-- Lone FAR ke plot SpawnPoint sering rubber ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ stuck carry tanpa claim.
function EGG.recoverToClaimPad(shouldRun, why)
    local padCf = EGG.claimPadCFrame()
    local padPos = padCf.Position
    local root = getRoot()
    local d = 1e9
    if root then
        d = Vector3.new(root.Position.X - padPos.X, 0, root.Position.Z - padPos.Z).Magnitude
    end
    dbg("HOME", string.format("recover pad | %s d=%.0f", tostring(why or "?"), d))
    emit("Home", "live", "home")
    EGG.stopMove()
    G.__StealEggTpHold = true
    G.__StealEggMoveQuiet = true
    EGG.clearFarHold("recover-pre")
    local walked = false
    if type(EGG.walkHomeToPad) == "function" then
        walked = EGG.walkHomeToPad(Vector3.new(padPos.X, 71, padPos.Z), shouldRun) == true
    end
    EGG.clearFarHold("recover-done")
    root = getRoot()
    local okNow = walked == true or (root ~= nil and xzNear(root.Position, padPos, 140))
    if okNow then
        dbg("HOME", string.format("recover pad ok @%.0f,%.0f", root.Position.X, root.Position.Z))
        return true, padCf
    end
    dbg("DENY", string.format(
        "recover pad fail got=%s",
        root and string.format("%.0f,%.0f", root.Position.X, root.Position.Z) or "nil"
    ))
    return false, padCf
end

function STEER.nearPad(maxD)
    maxD = tonumber(maxD) or 36
    local pad = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
    local root = getRoot()
    if not root then
        return false, pad, 1e9
    end
    -- Spawn plot ~64st dari pad: jangan anggap sudah nge-camp gerbang.
    if M.isOnPetArea() == true or inLocalPlot() == true then
        return false, pad, xzDist(root.Position, pad)
    end
    local d = xzDist(root.Position, pad)
    return d <= maxD, pad, d
end

-- Siap di tepi gerbang sebelum DropWall. Instant: Forest + umpan, bukan pad.
function STEER.stagePad(shouldRun)
    do
        local mode = tostring(M.moveMode or ""):lower()
        if mode == "teleport" or mode == "instant" or mode == "decoy" or mode == "freeze" or mode == "far" then
            STEER.instantPrep(shouldRun)
            return
        end
    end
    if STEER.stageBusy == true then
        return
    end
    if G.__StealEggBusy == true or G.__StealEggClaiming == true or M._busy == true then
        return
    end
    do
        local scramble = G.StealEggScramble
        if scrambleNeedsLegs() == true then
            return
        end
        if type(scramble) == "table" and scramble.enabled == true and scramble._busy == true then
            return
        end
    end
    if isCarryingUid() == true then
        return
    end
    local near, pad = STEER.nearPad(36)
    if near == true then
        pcall(function()
            local I = G.StealEggInstant
            if type(I) == "table" and type(I.preArm) == "function" then
                I.preArm()
            end
        end)
        return
    end
    STEER.stageBusy = true
    task.spawn(function()
        if scrambleNeedsLegs() == true then
            STEER.stageBusy = false
            return
        end
        local okOff = ensureOffBelt(shouldRun) == true
        if scrambleNeedsLegs() == true then
            STEER.stageBusy = false
            return
        end
        if okOff == true and (type(shouldRun) ~= "function" or shouldRun() ~= false) then
            EGG.stopMove()
            local walked = false
            if type(EGG.walkHomeToPad) == "function" then
                walked = EGG.walkHomeToPad(Vector3.new(pad.X, pad.Y, pad.Z), function()
                    if scrambleNeedsLegs() == true then
                        return false
                    end
                    if type(shouldRun) == "function" then
                        return shouldRun() ~= false
                    end
                    return true
                end) == true
            end
            dbg("WALL", string.format("stage pad walk | ok=%s", tostring(walked)))
        end
        STEER.stageBusy = false
    end)
end

local function goHomeNow(shouldRun)
    -- Pulang gendong / claim: jangan batal karena outbreak. Scramble minggir.
    if scrambleNeedsLegs() == true
        and isCarryingUid() ~= true
        and G.__StealEggClaiming ~= true
        and G.__StealEggStealFlow ~= true
    then
        return nil
    end
    local dest = plotHomeCFrame()
    if typeof(dest) ~= "CFrame" then
        GM.PlotCmds = GM.PlotCmds or Core.require("Library.Client.PlotCmds")
        dest = plotHomeCFrame()
    end
    if typeof(dest) ~= "CFrame" then
        emit("Home", "warn", "plot missing")
        dbg("HOME", "plot missing | PlotCmds=" .. tostring(type(GM.PlotCmds)) .. " err=" .. tostring(Core.lastRequireErr))
        return nil
    end
    local p = dest.Position
    local root = getRoot()
    local from = root and root.Position
    local xz = -1
    if typeof(from) == "Vector3" then
        xz = Vector3.new(from.X - p.X, 0, from.Z - p.Z).Magnitude
    end
    dbg("HOME", string.format(
        "go inPlot=%s xz=%.0f dest=V3(%.1f,%.1f,%.1f) carry=%s",
        tostring(inLocalPlot()),
        xz,
        p.X, p.Y, p.Z,
        tostring(M._carry.IsCarrying == true)
    ))
    local pd = G.StealEggPlaceDbg
    if type(pd) == "function" then
        pcall(pd, "goHomeNow", string.format(
            "from=%s dest=%.1f,%.1f,%.1f xz=%.0f belt=%s farm=%s hold=%s",
            typeof(from) == "Vector3" and string.format("%.1f,%.1f,%.1f", from.X, from.Y, from.Z) or "-",
            p.X, p.Y, p.Z,
            xz,
            tostring(M._onBelt),
            tostring(M._farmingBelt),
            tostring(G.__StealEggBeltHold)
        ))
    end
    emit("Home", "live", "going home")
    M._farmingBelt = false
    local hold = tostring(G.__StealEggBeltHold or "")
    -- Place tarik kandang sambil steal Going ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ karakter diam di tengah plot.
    if (hold == "place" or hold == "index")
        and (G.__StealEggBusy == true or G.__StealEggClaiming == true)
    then
        dbg("HOME", "skip place pull - steal busy")
        return nil
    end
    if G.__StealEggBeltHold == nil then
        G.__StealEggBeltHold = "home"
    end
    do
        local d = G.StealEggDispatch
        local own = type(d) == "table" and type(d.Owner) == "function" and d.Owner() or nil
        if own ~= "steal" and own ~= "claim" then
            local Move = getMove()
            if Move and type(Move.Stop) == "function" then
                pcall(Move.Stop)
            end
        end
    end
    local function untilHome()
        if type(shouldRun) == "function" then
            return shouldRun() == true
        end
        return true
    end
    -- Instant teleport ATAU FAR/decoy: pulang Instant. Walk/glide gendong: MoveTo, bukan CFrame.
    local sideHome = hold == "place" or hold == "index" or hold == "sell" or hold == "rift"
    if not sideHome and (stealMode() == "teleport" or G.__StealEggFarOn == true or G.__StealEggDecoyOn == true) then
        local rootH = getRoot()
        if rootH and xzNear(rootH.Position, dest.Position, 28) then
            dbg("HOME", "already near plot | skip")
            return dest
        end
        dbg("HOME", "FAR | glide home")
        emit("Home", "live", "glide home")
        travelViaStartArea(dest, "home", untilHome, { mode = "glide", longSnap = false, skipRubberWait = true })
        return dest
    end
    if sideHome and (stealMode() == "teleport" or G.__StealEggFarOn == true) then
        dbg("HOME", "side work | skip Instant jump | walk")
        emit("Home", "live", "walk home")
    end
    -- Selalu turun belt. Jangan skip karena steal masih _farmingBelt.
    ensureOffBelt(shouldRun)
    local root2 = getRoot()
    if root2 and (M._onBelt == true or isOverTreadmillPad(root2.Position)) then
        local pet = getPetStandPos()
        if typeof(pet) == "Vector3" then
            travelTo(pet, "pet-area", untilHome)
        end
    end
    if type(shouldRun) == "function" and shouldRun() == false then
        return dest
    end
    -- Sudah dekat plot / di plot: jangan via hub (GoTo pendek + getgc = freeze dekat safezone).
    do
        local here = getRoot() and getRoot().Position
        if typeof(here) == "Vector3" then
            if inLocalPlot() == true or xzNear(here, dest.Position, 28) then
                dbg("HOME", "skip via-hub | already near plot")
                return dest
            end
            -- Dekat StartArea/safezone tapi plot barat: lurus home, jangan hop hub dulu.
            local hub = startAreaCFrame()
            if typeof(hub) == "CFrame"
                and xzNear(here, hub.Position, 40)
                and here.X < hub.Position.X - 8
            then
                dbg("HOME", "near hub | direct home")
                travelTo(dest, "home", untilHome)
                return dest
            end
        end
    end
    travelViaStartArea(dest, "home", untilHome)
    if type(pd) == "function" then
        local now = getRoot() and getRoot().Position
        pcall(pd, "goHomeNow:end", string.format(
            "got=%s belt=%s",
            typeof(now) == "Vector3" and string.format("%.1f,%.1f,%.1f", now.X, now.Y, now.Z) or "-",
            tostring(M._onBelt)
        ))
    end
    return dest
end

M.goHome = goHomeNow

-- Lepas TpHold / WalkSpeed 0 / Anchored setelah idle jump atau FAR selesai.
-- Tanpa ini: no-match ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ goHome FAR ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ karakter freeze di plot.
function EGG.restoreMove(why)
    why = tostring(why or "")
    if scrambleNeedsLegs() == true and why ~= "steal-off" and why ~= "dead" then
        return true
    end
    -- Hatch/Place jangan cabut quiet di tengah steal (lihat Instant.restoreMove).
    -- Busy saja ÃƒÂ¢Ã¢â‚¬Â°Ã‚Â  steal aktif (WaitÃƒâ€šÃ‚Â·no match + Owner boss sering Busy).
    local stealLive = G.__StealEggFarOn == true
        or G.__StealEggDecoyOn == true
        or G.__StealEggClaiming == true
        or isCarryingUid() == true
    if stealLive then
        local allow = why == "end-session"
            or why == "batch-done"
            or why == "batch-miss"
            or why == "steal-off"
            or why == "bag-full"
            or why == "dead"
            or why == "claim-fail"
            or why == "carry-miss"
            or why == "pre-target"
            or why == "no-match"
            or why == "idle-home"
            or why == "wait-plot"
            or why == "wait-plot-miss"
            or string.find(why, "end-", 1, true) == 1
        if not allow then
            return true
        end
    end
    -- Skip thaw hanya kalau benar-benar duduk di pad treadmill.
    -- Flag belt palsu (sisa claim) + return early = Anchored stuck di safe zone.
    -- Jangan hapus _onBelt kalau badan masih di pad / tool: steal lalu kira sudah lepas.
    if M.beltStillOn() == true then
        G.__StealEggTpHold = false
        G.__StealEggMoveQuiet = false
        return true
    end
    if G.__StealEggOnBelt == true or M._onBelt == true then
        G.__StealEggOnBelt = false
        M._onBelt = false
    end
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.restoreMove) == "function" and I._ready == true then
        return I.restoreMove(why)
    end
    G.__StealEggTpHold = false
    G.__StealEggMoveQuiet = false
    local root = getRoot()
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    pcall(function()
        if root then
            root.Anchored = false
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        if hum and (tonumber(hum.Health) or 0) > 0 then
            hum.PlatformStand = false
            hum.Sit = false
            local ws = 16
            local Move = getMove()
            if type(Move) == "table" and type(Move.RealWalkSpeed) == "function" then
                local ok, v = pcall(Move.RealWalkSpeed)
                if ok and tonumber(v) then
                    ws = math.max(16, tonumber(v))
                end
            end
            local live = tonumber(hum.WalkSpeed) or 0
            if live < 8 or live + 0.5 < ws * 0.55 then
                hum.WalkSpeed = ws
            end
        end
    end)
    return true
end
function M.restoreMove(why)
    return EGG.restoreMove(why)
end
