function EGG.snapLong(destCf, shouldRun)
    if typeof(destCf) ~= "CFrame" then
        return false
    end
    if isDead() then
        return false
    end
    if type(shouldRun) == "function" and shouldRun() == false then
        return false
    end
    local Move = getMove()
    if type(Move) == "table" and type(Move.ArmIntegrity) == "function" then
        pcall(Move.ArmIntegrity)
    end
    if type(Move) == "table" and type(Move.Stop) == "function" then
        pcall(Move.Stop)
    end
    G.__StealEggTpHold = true
    G.__StealEggMoveQuiet = true
    local root = getRoot()
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if not root then
        return false
    end
    local from0 = root.Position
    pcall(function()
        if hum then
            hum.WalkSpeed = 0
        end
    end)
    local p = destCf.Position
    local y = p.Y
    pcall(function()
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = LP.Character and { LP.Character } or {}
        local hit = Workspace:Raycast(Vector3.new(p.X, p.Y + 10, p.Z), Vector3.new(0, -36, 0), params)
        if hit and hit.Instance and hit.Instance.CanCollide == true then
            local hip = (hum and tonumber(hum.HipHeight)) or 2
            local half = root.Size.Y * 0.5
            local ny = hit.Position.Y + hip + half
            if math.abs(ny - p.Y) <= 10 then
                y = ny
            end
        end
    end)
    local target = Vector3.new(p.X, y, p.Z)
    local rot = root.CFrame - root.CFrame.Position
    pcall(function()
        root.Anchored = false
        if hum then
            hum.Sit = false
            hum.PlatformStand = false
            hum.WalkSpeed = 0
        end
        root.CFrame = CFrame.new(target.X, target.Y, target.Z) * rot
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        if hum then
            hum:ChangeState(Enum.HumanoidStateType.Physics)
        end
    end)
    -- Satu hop saja. Settle lebih lama (StealFix sinceLandÃƒÂ¢Ã¢â‚¬Â°Ã‹â€ 0.26 sebelum carry).
    task.wait(0.32)
    if isDead() then
        return false
    end
    root = getRoot()
    local ok = root ~= nil and xzNear(root.Position, target, 48) == true
    if ok ~= true then
        dbg("DENY", string.format(
            "snapLong rubber from=%.0f,%.0f want=%.0f,%.0f got=%s",
            from0.X, from0.Z, target.X, target.Z,
            root and string.format("%.0f,%.0f", root.Position.X, root.Position.Z) or "nil"
        ))
        return false
    end
    -- Confirm stick (server Relocate sering 0.1ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“0.25s setelah land).
    task.wait(0.12)
    root = getRoot()
    if root == nil or xzNear(root.Position, target, 56) ~= true then
        dbg("DENY", "snapLong late rubber")
        return false
    end
    hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    pcall(function()
        if hum then
            hum.WalkSpeed = 0
        end
    end)
    return true
end

-- Soft pin di home (claim). Tanpa koreksi loop yang thrash eggÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬Âhome.
function EGG.pinHome(homeCf)
    if typeof(homeCf) ~= "CFrame" then
        return false
    end
    local root = getRoot()
    if not root then
        return false
    end
    if xzNear(root.Position, homeCf.Position, 12) == true then
        return true
    end
    local Move = getMove()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false
    end
    local ok = false
    pcall(function()
        ok = Move.GoTo(homeCf, {
            mode = "walk",
            reason = "pin-home",
            skipRubberWait = true,
            skipLandWait = true,
            arrive = 12,
        }) == true
    end)
    return ok == true
end

-- Setelah carry: tahan di home sampai claim / timeout. Re-pin kalau server rubber ke egg.
function EGG.claimHoldHome(homeCf, shouldRun, seconds)
    seconds = tonumber(seconds) or 4
    if typeof(homeCf) ~= "CFrame" then
        return false
    end
    local Move = getMove()
    if type(Move) == "table" then
        if type(Move.Stop) == "function" then
            pcall(Move.Stop)
        end
        if type(Move.ArmIntegrity) == "function" then
            pcall(Move.ArmIntegrity)
        end
    end
    G.__StealEggClaiming = true
    G.__StealEggTpHold = true
    emit("Claim", "live", "pin home")
    EGG.pinHome(homeCf)
    task.wait(0.18)
    local t0 = os.clock()
    local nextPin = 0
    local sawCarry = isCarryingUid() == true
    while os.clock() - t0 < seconds do
        if M._claimed ~= nil then
            break
        end
        if isDead() then
            break
        end
        if type(shouldRun) == "function" and shouldRun() == false then
            break
        end
        local holding = isCarryingUid()
        if holding then
            sawCarry = true
        end
        local root = getRoot()
        if root then
            local atHome = inLocalPlot() == true or xzNear(root.Position, homeCf.Position, 20) == true
            if atHome ~= true and os.clock() >= nextPin then
                -- StealFix: jangan re-pin berkala (Node thrash). Max 1 koreksi total.
                nextPin = os.clock() + 999
                dbg("CLAIM", "one soft pin (no loop)")
                if type(Move) == "table" and type(Move.ArmIntegrity) == "function" then
                    pcall(Move.ArmIntegrity)
                end
                EGG.pinHome(homeCf)
            end
        end
        if sawCarry and holding ~= true then
            local tDrop = os.clock()
            while os.clock() - tDrop < 0.55 do
                if M._claimed ~= nil then
                    break
                end
                task.wait()
            end
            if M._claimed ~= nil then
                break
            end
            if inLocalPlot() == true then
                break
            end
            if isCarryingUid() ~= true then
                break
            end
        end
        task.wait(0.05)
    end
    G.__StealEggTpHold = false
    local ok = M._claimed ~= nil or (sawCarry == true and isCarryingUid() ~= true and inLocalPlot() == true)
    dbg("CLAIM", string.format(
        "hold end ok=%s claimed=%s carry=%s inPlot=%s",
        tostring(ok),
        tostring(M._claimed ~= nil),
        tostring(isCarryingUid() == true),
        tostring(inLocalPlot() == true)
    ))
    return ok == true
end


