function EGG.dbgSnap(why)
    if G.__StealEggFarOn == true or G.__StealEggBusy == true then
        return
    end
    local now = os.clock()
    if now - (tonumber(M._dbgSnapAt) or 0) < 1.2 then
        return
    end
    M._dbgSnapAt = now
    local root = getRoot()
    local pos = root and root.Position
    local home = plotHomeCFrame()
    local xz = -1
    if typeof(pos) == "Vector3" and typeof(home) == "CFrame" then
        xz = Vector3.new(pos.X - home.Position.X, 0, pos.Z - home.Position.Z).Magnitude
    end
    local recState = "-"
    if M._carry.Uid ~= nil then
        local rec = getEggRecord(M._carry.Uid)
        recState = type(rec) == "table" and tostring(rec.State) or "norec"
    end
    dbg("SNAP", string.format(
        "%s inPlot=%s xzHome=%.0f carry=%s rec=%s claimed=%s prefer=%s trapped=%s",
        tostring(why or "-"),
        tostring(inLocalPlot()),
        xz,
        tostring(M._carry.IsCarrying == true),
        recState,
        tostring(M._claimed ~= nil),
        tostring(M._preferUid or "-"),
        tostring(isTrapped())
    ))
end

local function resolveWorkspaceModel(uid)
    if uid == nil then
        return nil
    end
    uid = tostring(uid)
    local child = Workspace:FindFirstChild(uid)
    if child and child:IsA("Model") then
        return child
    end
    local folder = Workspace:FindFirstChild("AreaEggSlotsClient")
    if folder then
        local model = folder:FindFirstChild(uid)
        if model and model:IsA("Model") then
            return model
        end
    end
    return nil
end

local function targetEggLive(uid, model)
    uid = tostring(uid or "")
    if uid == "" then
        return false
    end
    if isCarryingUid(uid) then
        return true
    end
    local rec = getEggRecord(uid)
    if type(rec) == "table" then
        local st = rec.State
        if st == AreaStates.Slot or st == "Slot" then
            if (stealMode() == "walk" or stealMode() == "glide") and resolveWorkspaceModel(uid) == nil then
                return false
            end
            return true
        end
        if st == AreaStates.Dropped or st == "Dropped" then
            return true
        end
        if st == AreaStates.Carried or st == "Carried" then
            return tonumber(rec.CarrierUserId) == (LP and LP.UserId)
        end
        return false
    end
    if typeof(model) == "Instance" and model.Parent then
        return true
    end
    if typeof(model) == "Instance" and not model.Parent then
        local inst = resolveWorkspaceModel(uid)
        return typeof(inst) == "Instance" and inst.Parent ~= nil
    end
    return true
end

local function recordPos(rec)
    if type(rec) ~= "table" then
        return nil
    end
    local model = resolveWorkspaceModel(rec.Uid)
    local fromModel = worldPosition(model)
    if fromModel then
        return fromModel
    end
    local areaId = rec.AreaId or rec.areaId
    if type(areaId) == "string" and type(rec.NestId) == "string" and type(GM.AreaEggSlotIdentity) == "table" then
        local area = getAreaModel(areaId)
        if area and type(GM.AreaEggSlotIdentity.ResolveNest) == "function" then
            local ok, nest = pcall(GM.AreaEggSlotIdentity.ResolveNest, area, rec.NestId)
            if ok then
                local bottom = typeof(nest) == "Instance" and nest:FindFirstChild("EggSpotBottom")
                if bottom and bottom:IsA("BasePart") then
                    return bottom.Position
                end
                local nestPos = worldPosition(nest)
                if nestPos then
                    return nestPos
            end
        end
    end
    end
    local cfPos = decodeWorldPos(rec.BottomCFrame)
        or decodeWorldPos(rec.CFrame)
        or decodeWorldPos(rec.WorldCFrame)
        or decodeWorldPos(rec.Position)
    if cfPos then
        return cfPos
    end
    -- Nest belum ke-stream: jalan ke zona dulu, model muncul belakangan.
    if areaId ~= nil then
        local area = getAreaModel(areaId)
        local ap = area and worldPosition(area)
        if typeof(ap) == "Vector3" and inLocalPlotBounds(ap) ~= true then
            return ap
        end
    end
    return nil
end

local function recordActive(rec)
    if type(rec) ~= "table" then
        return false
    end
    local state = rec.State
    if state == nil then
        return true
    end
    if state == AreaStates.Slot or state == "Slot" then
        return true
    end
    if state == AreaStates.Dropped or state == "Dropped" then
        return true
    end
    -- Cache masih Carried padahal kita sudah drop: tetap target.
    -- Kalau player lain yang bawa, jangan treat sebagai Slot - itu bikin
    -- steal restart setiap frame (GOTO cancelled) alih-alih ambil egg lain.
    if (state == AreaStates.Carried or state == "Carried")
        and M._preferUid ~= nil
        and tostring(rec.Uid) == tostring(M._preferUid)
        and M._carry.IsCarrying ~= true
    then
        local carrierId = tonumber(rec.CarrierUserId)
        if carrierId == nil or carrierId == 0 or carrierId == (LP and LP.UserId) then
        return true
        end
    end
    return false
end

local function getSnapshotRecords()
    -- ReadFieldEggs deep-copy SEMUA record. Satu panggilan di spawn/claim = freeze ~1s.
    -- Pakai cache FieldRefreshed. Jangan baca ulang karena ttl habis.
    if type(EGG.snapRecs) == "table" and #EGG.snapRecs > 0 then
        return EGG.snapRecs
    end
    local now = os.clock()
    if now - (tonumber(EGG._readSnapAt) or 0) < 2.5 then
        return EGG.snapRecs or {}
    end
    -- Di pad/belt cache kosong jangan dikunci. nearestEgg vis=0 = Wait no match,
    -- zone rule yang sudah ON tidak pernah menggerakkan kaki.
    EGG._readSnapAt = now
    local recs = {}
    local ok, snap = Core.eggCall("GetAreaEggSnapshot")
    if ok and type(snap) == "table" and type(snap.Records) == "table" then
        recs = snap.Records
    end
    if #recs == 0 and type(snap) == "table" then
        local built = {}
        for _, rec in pairs(snap.Records or snap) do
            if type(rec) == "table" and rec.Uid ~= nil then
                built[#built + 1] = rec
            end
        end
        if #built > 0 then
            recs = built
        end
    end
    EGG.snapRecs = recs
    EGG.snapAt = now
    return recs
end

-- Sync ke server, lalu buang cache biar record baru langsung kepakai.
function EGG.sync()
    -- Jangan InvokeServer di tengah FAR - ngantri RequestCarry + CPU spike.
    if G.__StealEggFarOn == true or G.__StealEggClaiming == true or EGG.atClaimPad() == true then
        return false
    end
    if os.clock() - (tonumber(EGG._syncAt) or 0) < 6 then
        return false
    end
    EGG._syncAt = os.clock()
    -- Jangan kosongkan cache dulu: RequestAreaEggSnapshot nahan thread = freeze.
    task.spawn(function()
        Core.eggCall("RequestAreaEggSnapshot")
    end)
    return true
end

-- StealFix parallel: FirstArea Forest terdekat dari posisi stage (~597).
-- Bypass filter rarity (baseline deposit Dog). Return {uid,rec,pos,dist} atau nil.
function EGG.pickForestNear(origin, maxDist)
    if typeof(origin) ~= "Vector3" then
        return nil
    end
    maxDist = tonumber(maxDist) or 160
    local folder = Workspace:FindFirstChild("AreaEggSlotsClient")
    local forestHint = Vector3.new(597, 71, -317)
    local best, bestD
    for _, rec in ipairs(getSnapshotRecords()) do
        if recordActive(rec) then
            local fUid = tostring(rec.Uid or "")
            local area = tostring(rec.AreaId or rec.areaId or "")
            local isForest = area == "Forest" or string.find(area, "Forest", 1, true) ~= nil
            local isFirst = string.find(fUid, "FirstAreaEgg_", 1, true) == 1
            if isForest and isFirst and fUid ~= "" and eggIsSkipped(fUid) ~= true then
                local fPos = recordPos(rec)
                -- Snapshot Forest sering tanpa Position. Ambil model nest.
                if typeof(fPos) ~= "Vector3" and folder then
                    local inst = folder:FindFirstChild(fUid)
                    if inst == nil then
                        for _, ch in ipairs(folder:GetChildren()) do
                            local nm = tostring(ch.Name)
                            if nm == fUid or string.sub(nm, 1, #fUid) == fUid or string.find(nm, fUid, 1, true) then
                                inst = ch
                                break
                            end
                        end
                    end
                    fPos = worldPosition(inst)
                end
                if typeof(fPos) ~= "Vector3" then
                    fPos = forestHint
                end
                local d = Vector3.new(fPos.X - origin.X, 0, fPos.Z - origin.Z).Magnitude
                if d <= maxDist and (best == nil or d < bestD) then
                    bestD = d
                    best = { uid = fUid, rec = rec, pos = fPos, dist = d }
                end
            end
        end
    end
    return best
end

-- StealFix pad: tepi safezone/StartArea (~515,-363), ~91st dari Forest egg ke arah hub.
-- BUKAN PetArea (~428) dan BUKAN SpawnPoint plot (~492,-423 di dump Node).
function EGG.stealPadCFrame()
    local hub = startAreaCFrame()
    local hp = typeof(hub) == "CFrame" and hub.Position or nil
    local root = getRoot()
    local origin = hp or (root and root.Position)
    if typeof(origin) ~= "Vector3" then
        return plotHomeCFrame()
    end
    local forest = EGG.pickForestNear(origin, 520)
    if type(forest) ~= "table" or typeof(forest.pos) ~= "Vector3" then
        forest = EGG.pickForestNear(Vector3.new(origin.X + 80, origin.Y, origin.Z + 40), 520)
    end
    if type(forest) == "table" and typeof(forest.pos) == "Vector3" then
        local f = forest.pos
        local toward = Vector3.new(origin.X - f.X, 0, origin.Z - f.Z)
        if toward.Magnitude < 8 and typeof(hp) == "Vector3" then
            toward = Vector3.new(hp.X - f.X, 0, hp.Z - f.Z)
        end
        if toward.Magnitude > 8 then
            local pad = f + toward.Unit * 91
            local y = (typeof(hp) == "Vector3" and hp.Y) or (f.Y + 3)
            EGG._stealPadAt = os.clock()
            EGG._stealPad = CFrame.new(pad.X, y, pad.Z)
            return EGG._stealPad
        end
    end
    if typeof(hub) == "CFrame" then
        -- Fallback: sisi hub ke arah +X gameplay (koridor telur).
        local p = hub.Position
        EGG._stealPad = CFrame.new(p.X - 25, p.Y, p.Z)
        return EGG._stealPad
    end
    return plotHomeCFrame()
end

-- Belt idle: cukup cek snapshot+pos. Jangan nearestEgg penuh
-- (resolveWorkspaceModel / FindFirstChild prompt tiap telur = mahal di pad).
function EGG.cheapHasPickPos()
    local records = getSnapshotRecords()
    for _, rec in ipairs(records) do
        if recordActive(rec) and eggIsSkipped(rec.Uid) ~= true then
            local ok = select(1, M.eggAllowed(rec))
            if ok == true and typeof(recordPos(rec)) == "Vector3" then
                return true
            end
        end
    end
    return false
end

function EGG.farmRun(seq)
    if M.beltYield() == true or placeKeepsPlot() == true then
        return false
    end
    if G.__StealEggWanted ~= true
        or seq ~= G.__StealEggSeq
        or GEN ~= G.__StealEggWildGen
        or M.enabled ~= true
        or M.autoTreadmill ~= true then
        return false
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Owner) == "function" then
        local who = d.Owner()
        if who ~= nil and who ~= "belt" then
            return false
        end
    end
    -- Pakai hasPickPos (bukan cheap): sama seperti sebelum patch drop.
    return EGG.hasPickPos() ~= true
end

local function findPrompt(model, pos)
    if typeof(model) == "Instance" then
        local prompt = model:FindFirstChild("CarryAreaEgg", true)
        if prompt then
            return prompt
        end
        prompt = model:FindFirstChildWhichIsA("ProximityPrompt", true)
        if prompt then
            return prompt
        end
    end
    return nil
end

local function buildSlotKey(record, uid)
    uid = tostring(uid or "")
    if uid == "" or string.find(uid, "FirstAreaEgg_", 1, true) ~= 1 then
        return nil
    end
    -- Uid = FirstAreaEgg_{user}_{plot}_{AreaId}:{NestId} ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ SlotKey = AreaId:NestId
    local fromUid = string.match(uid, "^FirstAreaEgg_%-?%d+_%d+_(.+)$")
    if type(GM.AreaEggSlotIdentity) == "table" then
        local firstFn = GM.AreaEggSlotIdentity.IsFirstAreaUid or GM.AreaEggSlotIdentity.LooksLikeFirstAreaUid
        if type(firstFn) == "function" then
            local ok, isFirst = pcall(firstFn, GM.AreaEggSlotIdentity, uid)
            if not ok then
                ok, isFirst = pcall(firstFn, uid)
            end
            if ok and isFirst ~= true then
                return nil
            end
        end
        local areaId = type(record) == "table" and (record.AreaId or record.areaId) or nil
        local nestId = type(record) == "table" and (record.NestId or record.nestId) or nil
        if type(areaId) == "string" and type(nestId) == "string" then
            -- NestId kadang sudah "Forest:Slot_002" (= SlotKey); jangan double-prefix.
            if nestId:find(":", 1, true) then
                return nestId
            end
            local keyFn = GM.AreaEggSlotIdentity.BuildSlotKey or GM.AreaEggSlotIdentity.SlotKey
            if type(keyFn) == "function" then
                local ok, key = pcall(keyFn, areaId, nestId)
                if ok and type(key) == "string" and key ~= "" then
                    return key
                end
            end
            return areaId .. ":" .. nestId
        end
    end
    if type(fromUid) == "string" and fromUid ~= "" then
        return fromUid
    end
    return nil
end

local function invokeCarry(uid, slotKey)
    uid = tostring(uid or "")
    -- Dump baru: semua telur lewat EggState.CarryFieldEgg → AskFieldEggCarry.
    -- RequestCarryAreaEgg sudah tidak ada. RequestNestTransfer = taruh ke nest.
    local es = Core.require("Client.EggState")
    if type(es) == "table" and type(es.CarryFieldEgg) == "function" then
        local key = nil
        if uid:find("FirstAreaEgg_", 1, true) == 1 then
            key = slotKey
        end
        local ok, success, err = pcall(es.CarryFieldEgg, uid, key)
        if ok and success == true then
            return true, nil
        end
        local msg = tostring((ok and (err or success)) or success or "denied")
        if string.find(msg, "Already carrying", 1, true) then
            return true, nil
        end
        if ok then
            return false, msg
        end
    end
    local cmds = getEggCmds()
    if type(cmds) == "table" then
        local fn = cmds.RequestCarryAreaEgg or cmds.RequestNestTransfer
        if type(fn) == "function" then
            local ok, success, err = pcall(fn, uid, slotKey)
            if ok and success == true then
                return true, nil
            end
            return false, tostring((ok and (err or success)) or success or "denied")
        end
    end
    local ok, success, err = Core.eggCall("RequestCarryAreaEgg", uid, slotKey)
    if ok and success == true then
        return true, nil
    end
    return false, tostring((ok and (err or success)) or success or "denied")
end

local function requestCarry(uid, record)
    uid = tostring(uid or "")
    if uid == "" then
        return false, "no uid"
    end
    local isBait = uid:find("FirstAreaEgg_", 1, true) == 1
    -- FirstArea WAJIB FirstAreaSlotKey (dump CarryFieldEgg). Uid-only = Egg not found.
    local slotKey = nil
    if isBait or (stealMode() ~= "teleport" and G.__StealEggDecoyOn ~= true) then
        slotKey = buildSlotKey(record, uid)
    end
    local ok, err = invokeCarry(uid, slotKey)
    local msg = tostring(err or "")
    local miss = msg:find("Egg not found", 1, true) or msg:find("unavailable", 1, true)
    if ok ~= true and miss then
        if isBait ~= true then
            pcall(EGG.sync)
            task.wait(0.14)
            ok, err = invokeCarry(uid, nil)
            msg = tostring(err or "")
            dbg("STEAL", string.format(
                "RetryUidOnly uid=%s ok=%s err=%s",
                uid,
                tostring(ok),
                tostring(err)
            ))
        end
        if ok ~= true then
            local key2 = buildSlotKey(record, uid) or buildSlotKey(getEggRecord(uid), uid)
            if type(key2) == "string" and key2 ~= "" then
                ok, err = invokeCarry(uid, key2)
                msg = tostring(err or "")
                dbg("STEAL", string.format(
                    "RetrySlotKey uid=%s key=%s ok=%s err=%s",
                    uid,
                    tostring(key2),
                    tostring(ok),
                    tostring(err)
                ))
            end
        end
    end
    local dbgLine = string.format(
        "RequestCarry uid=%s key=%s ok=%s err=%s carrying=%s",
        uid,
        tostring(slotKey),
        tostring(ok),
        tostring(err),
        tostring(M._carry.IsCarrying == true)
    )
    local now = os.clock()
    if EGG._lastCarryDbg ~= dbgLine or (now - (tonumber(EGG._lastCarryDbgAt) or 0)) >= 0.5 then
        EGG._lastCarryDbg = dbgLine
        EGG._lastCarryDbgAt = now
        dbg("STEAL", dbgLine)
    end
    return ok, err
end

local function armStealPrompt(prompt)
    if typeof(prompt) ~= "Instance" or not prompt.Parent then
        return
    end
    -- Dump: HoldDuration 1.2, atau 0.25 kalau FastEggPickupTime. Kita 0 biar Triggered langsung.
    pcall(function()
        prompt.HoldDuration = 0
        prompt.RequiresLineOfSight = false
        if EGG._promptHideOn == true then
            -- UI tetap tersembunyi (dist 0); Enabled true sebentar biar fireproximityprompt jalan.
            prompt.MaxActivationDistance = 0
            prompt.Enabled = true
        else
            prompt.MaxActivationDistance = math.max(prompt.MaxActivationDistance, EGG.prompt)
            prompt.Enabled = true
        end
    end)
end

local function fireStealPrompt(prompt)
    armStealPrompt(prompt)
    if typeof(prompt) ~= "Instance" or not prompt.Parent then
        return
    end
    if typeof(fireproximityprompt) == "function" then
        pcall(fireproximityprompt, prompt, 0)
    else
        pcall(function()
            prompt:InputHoldBegin()
            prompt:InputHoldEnd()
        end)
    end
    if EGG._promptHideOn == true then
        EGG.hideOneStealPrompt(prompt)
    end
end

-- Auto Steal ON: sembunyikan prompt Steal Egg (CarryAreaEgg) biar tidak ganggu UI.
function EGG.isStealEggPrompt(inst)
    if typeof(inst) ~= "Instance" or not inst:IsA("ProximityPrompt") then
        return false
    end
    local n = tostring(inst.Name or "")
    -- Pintu cave / zone: jangan ikut di-hide Auto Steal.
    if n == "SecretZonePrompt" or string.find(n, "SecretZone", 1, true) then
        return false
    end
    local act = string.lower(tostring(inst.ActionText or ""))
    if act == "enter" or act == "exit" then
        return false
    end
    if n == "CarryAreaEgg" or n == "StealEgg" or n == "CarryEgg" then
        return true
    end
    local low = string.lower(n)
    if string.find(low, "carry", 1, true) and string.find(low, "egg", 1, true) then
        return true
    end
    -- Model telur lapangan sering namanya Uid / AreaEgg
    local p = inst.Parent
    if typeof(p) == "Instance" then
        local pn = tostring(p.Name or "")
        if string.find(pn, "AreaEgg", 1, true) or string.find(pn, "FirstAreaEgg_", 1, true) then
            return true
        end
        if p:GetAttribute("Uid") ~= nil or p:GetAttribute("AssetCategory") ~= nil then
            return true
        end
    end
    return false
end

function EGG.hideOneStealPrompt(prompt)
    if EGG.isStealEggPrompt(prompt) ~= true then
        return
    end
    if type(EGG._promptHide) ~= "table" then
        EGG._promptHide = {}
    end
    if EGG._promptHide[prompt] == nil then
        EGG._promptHide[prompt] = {
            Enabled = prompt.Enabled,
            MaxActivationDistance = tonumber(prompt.MaxActivationDistance) or 10,
        }
    end
    pcall(function()
        prompt.Enabled = false
        prompt.MaxActivationDistance = 0
    end)
end

local function hidePromptsUnder(root)
    if typeof(root) ~= "Instance" then
        return
    end
    if root:IsA("ProximityPrompt") then
        EGG.hideOneStealPrompt(root)
        return
    end
    for _, d in ipairs(root:GetDescendants()) do
        if d:IsA("ProximityPrompt") then
            EGG.hideOneStealPrompt(d)
        end
    end
end

function EGG.rehideKnownStealPrompts()
    if EGG._promptHideOn ~= true or type(EGG._promptHide) ~= "table" then
        return
    end
    for prompt in pairs(EGG._promptHide) do
        if typeof(prompt) == "Instance" and prompt.Parent then
            pcall(function()
                prompt.Enabled = false
                prompt.MaxActivationDistance = 0
            end)
        else
            EGG._promptHide[prompt] = nil
        end
    end
end

function EGG.scanHideStealPrompts()
    if EGG._promptHideOn ~= true then
        return
    end
    -- Jangan Workspace:GetDescendants() - map ~35k instance, 10ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“80ms CPU spike.
    local slots = Workspace:FindFirstChild("AreaEggSlotsClient")
    if slots then
        hidePromptsUnder(slots)
    end
    for _, ch in ipairs(Workspace:GetChildren()) do
        local n = tostring(ch.Name or "")
        local looksEgg = n == "CarryAreaEgg"
            or string.find(n, "FirstAreaEgg_", 1, true) ~= nil
            or string.find(n, "AreaEgg", 1, true) ~= nil
        if not looksEgg then
            local ok, uid = pcall(function()
                return ch:GetAttribute("Uid")
            end)
            looksEgg = ok == true and uid ~= nil
        end
        if looksEgg then
            hidePromptsUnder(ch)
        end
    end
end

function EGG.setStealPromptHide(on)
    on = on == true
    if type(EGG._promptHide) ~= "table" then
        EGG._promptHide = {}
    end
    if EGG._promptHideOn == on then
        if on then
            EGG.rehideKnownStealPrompts()
        end
        return
    end
    EGG._promptHideOn = on
    if EGG._promptHideConn then
        pcall(function()
            EGG._promptHideConn:Disconnect()
        end)
        EGG._promptHideConn = nil
    end
    if EGG._promptHideHB then
        pcall(function()
            EGG._promptHideHB:Disconnect()
        end)
        EGG._promptHideHB = nil
    end
    if on then
        dbg("PROMPT", "hide steal egg prompts")
        EGG.scanHideStealPrompts()
        EGG._promptHideConn = Workspace.DescendantAdded:Connect(function(inst)
            if EGG._promptHideOn ~= true then
                return
            end
            if inst:IsA("ProximityPrompt") then
                task.defer(EGG.hideOneStealPrompt, inst)
            end
        end)
        local lastRehide = 0
        EGG._promptHideHB = RunService.Heartbeat:Connect(function()
            if EGG._promptHideOn ~= true then
                return
            end
            -- Time-based: %180 di 5 FPS ÃƒÂ¢Ã¢â‚¬Â°Ã‹â€  36s antar rehide (dulu ~3s @60).
            local now = os.clock()
            if (now - lastRehide) < 3 then
                return
            end
            lastRehide = now
            EGG.rehideKnownStealPrompts()
        end)
    else
        dbg("PROMPT", "restore steal egg prompts")
        for prompt, saved in pairs(EGG._promptHide) do
            if typeof(prompt) == "Instance" and prompt.Parent then
                pcall(function()
                    prompt.Enabled = saved.Enabled ~= false
                    prompt.MaxActivationDistance = tonumber(saved.MaxActivationDistance) or 10
                end)
            end
        end
        EGG._promptHide = {}
    end
end

EGG.grabOrderKeys = {
    price = true,
    earn = true,
    kg = true,
    rarest = true,
    closest = true,
    common = true,
}

EGG.grabOrderAliases = {
    ["highest price first"] = "price",
    ["highest earn first"] = "earn",
    ["highest kg first"] = "kg",
    ["highest rarity first"] = "rarest",
    ["closest first"] = "closest",
    ["lowest rarity first"] = "common",
}

function EGG.clampGrabOrder(value)
    if type(value) == "table" then
        value = Core.dropdownValue("single", value) or Core.dropdownValue(value)
    end
    local key = string.lower(tostring(value or ""))
    if EGG.grabOrderKeys[key] then
        return key
    end
    return EGG.grabOrderAliases[key] or nil
end

function EGG.grabOrderScore(order, info, dist)
    dist = tonumber(dist) or math.huge
    local rarity = tonumber(info and info.rarityNum) or 0
    local kg = tonumber(info and info.kg) or 0
    local rate = tonumber(info and info.rate) or 0
    local price = tonumber(info and info.price) or 0
    if order == "rarest" then
        return rarity, -dist
    end
    if order == "common" then
        return -rarity, -dist
    end
    if order == "kg" then
        return kg, -dist
    end
    if order == "price" then
        return price, -dist
    end
    if order == "earn" then
        return rate, -dist
    end
    return -dist, rarity
end

-- Dump: Bat:Activate, range 15+2, cooldown 0.6s, drop egg via PlayerSlap.
-- Snapshot Carried + CarrierUserId = pemain yang bawa egg.
-- Stick chase di BELAKANG carrier. Swing snap ke DEPAN (LookVector * BAT.stick).
local BAT = {
    range = 15,
    hitTol = 2,
    cooldown = 0.72,
    activate = "Bat:Activate",
    stick = 1.6,
    traceSeq = 0,
    skipAt = 0,
}

local function playerFromUserId(userId)
    userId = tonumber(userId)
    if not userId then
        return nil
    end
    local ok, plr = pcall(function()
        return Players:GetPlayerByUserId(userId)
    end)
    if ok and plr then
        return plr
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p.UserId == userId then
            return p
        end
    end
    return nil
end

local function carrierHrp(plr)
    local char = plr and plr.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function isBatTool(tool)
    if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
        return false
    end
    if tool:GetAttribute("IsBat") == true then
            return true
        end
    local name = tool:GetAttribute("GearName")
    if type(name) ~= "string" then
        return false
    end
    local dir = GM.Gears and GM.Gears.Directory
    local cfg = dir and dir[name]
    return type(cfg) == "table" and cfg.BatControllerData ~= nil
end

local function batRank(tool)
    local bonus, force, tier = 0, 0, 0
    local name = tool and tool:GetAttribute("GearName")
    local dir = GM.Gears and GM.Gears.Directory
    local cfg = type(name) == "string" and dir and dir[name]
    local data = type(cfg) == "table" and cfg.BatControllerData
    if type(data) == "table" then
        bonus = tonumber(data.RangeBonus) or 0
        force = tonumber(data.Force) or 0
    end
    if type(cfg) == "table" then
        tier = tonumber(cfg.IndexBatTier) or 0
    end
    return bonus, force, tier
end

local function findBatTool()
    bindGame()
    local best, bb, bf, bt = nil, -1, -1, -1
    local function consider(parent)
        if not parent then
            return
        end
        for _, ch in ipairs(parent:GetChildren()) do
            if isBatTool(ch) then
                local b, f, t = batRank(ch)
                if b > bb or (b == bb and f > bf) or (b == bb and f == bf and t > bt) then
                    best, bb, bf, bt = ch, b, f, t
                end
            end
        end
    end
    consider(LP.Character)
    consider(LP:FindFirstChild("Backpack"))
    return best
end

local function batRange(tool)
    local bonus = 0
    if tool then
        local name = tool:GetAttribute("GearName")
        local cfg = GM.Gears and GM.Gears.Directory and name and GM.Gears.Directory[name]
        local data = type(cfg) == "table" and cfg.BatControllerData
        if type(data) == "table" then
            bonus = tonumber(data.RangeBonus) or 0
        end
    end
    local scalar = 1
    if Workspace:GetAttribute("DragonEggEventActive") == true then
        scalar = 2.5
    end
    return (BAT.range + BAT.hitTol + bonus) * scalar
end

local function equipBat(tool)
    if not isBatTool(tool) then
        return false
    end
    local char = LP.Character
    if not char then
        return false
    end
    if tool.Parent == char then
        return true
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)
    end
    if tool.Parent ~= char then
        pcall(function()
            tool.Parent = char
        end)
    end
    local t0 = os.clock()
    while os.clock() - t0 < 0.8 do
        if tool.Parent == LP.Character then
            return true
        end
        task.wait()
    end
    return tool.Parent == LP.Character
end

local function fireBat(targetPlr)
    if typeof(targetPlr) ~= "Instance" then
        return false
    end
    if type(GM.Network) ~= "table" then
        GM.Network = Core.require("Library.Client.Network")
    end
    local now = 0
    pcall(function()
        now = workspace:GetServerTimeNow()
    end)
    BAT.traceSeq = (BAT.traceSeq % 100000) + 1
    local trace = string.format("%d:%d:%d", LP.UserId, BAT.traceSeq, math.floor((now > 0 and now or os.clock()) * 1000))
    local rem = GM.Network
    local trig = rem and rem.BatSwing and rem.BatSwing.Trigger
    if trig and type(trig.FireServer) == "function" then
        local ok = pcall(function()
            trig:FireServer(targetPlr, trace)
        end)
        if ok then
            return true
        end
    end
    if rem and type(rem.Fire) == "function" then
        local ok = pcall(rem.Fire, BAT.activate, targetPlr, trace)
        if ok then
            return true
        end
    end
    return false
end

local function dist3(a, b)
    if not a or not b then
        return math.huge
    end
    return (a.Position - b.Position).Magnitude
end

local function stickFront(hrp, behind)
    if not hrp then
        return nil
    end
    local here = hrp.Position
    local look = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z)
    if look.Magnitude < 0.1 then
        look = Vector3.new(0, 0, -1)
    else
        look = look.Unit
    end
    local sign = behind == true and -1 or 1
    return here + look * (BAT.stick * sign)
end

local function facePart(part)
    local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not hrp or not part then
        return
    end
    local p = hrp.Position
    local look = Vector3.new(part.Position.X - p.X, 0, part.Position.Z - p.Z)
    if look.Magnitude < 0.05 then
        return
    end
    pcall(function()
        hrp.CFrame = CFrame.lookAt(p, p + look.Unit)
    end)
end

local function waitBatReady(tool, timeout)
    timeout = timeout or 0.8
    local t0 = os.clock()
    while os.clock() - t0 < timeout do
        if tool and tool.Parent == LP.Character and tool:GetAttribute("CooldownActive") ~= true then
            return true
        end
        task.wait()
    end
    return tool ~= nil and tool.Parent == LP.Character
end

local function inTaggedSafeZone(hrp)
    if not hrp then
        return false
    end
    local pos = hrp.Position
    local ok, tagged = pcall(function()
        return game:GetService("CollectionService"):GetTagged("SafeZone")
    end)
    if not ok or type(tagged) ~= "table" then
        return false
    end
    for _, part in ipairs(tagged) do
        if part:IsA("BasePart") then
            local rel = part.CFrame:PointToObjectSpace(pos)
            local half = part.Size * 0.5
            if math.abs(rel.X) <= half.X and math.abs(rel.Y) <= half.Y and math.abs(rel.Z) <= half.Z then
                return true
            end
        end
    end
    return false
end

local function batGameplayOk(plr)
    local hrp = carrierHrp(plr)
    if not hrp then
        return false
    end
    return isGameplaySide(hrp.Position) == true and inTaggedSafeZone(hrp) ~= true
end

local function recordStillCarriedBy(uid, userId)
    uid = tostring(uid or "")
    userId = tonumber(userId)
    for _, rec in ipairs(getSnapshotRecords()) do
        if tostring(rec.Uid) == uid then
            local st = rec.State
            if st == AreaStates.Dropped or st == "Dropped" then
                return false, rec
            end
            if st == AreaStates.Claimed or st == "Claimed" then
                return false, rec
            end
            if tonumber(rec.CarrierUserId) == userId then
                return true, rec
            end
            return false, rec
        end
    end
    return false, nil
end

local function playerHoldsEgg(plr, uid)
    local char = plr and plr.Character
    if not char then
        return false
    end
    uid = uid and tostring(uid) or nil
    local function isEggTool(tool)
        if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
            return false
        end
        if tool:GetAttribute("ItemType") ~= "AssetEgg" then
            return false
        end
        if uid == nil or uid == "" then
            return true
        end
        local tu = tool:GetAttribute("UID")
        return tu == nil or tostring(tu) == uid
    end
    for _, ch in ipairs(char:GetChildren()) do
        if isEggTool(ch) then
            return true
        end
    end
    return false
end

local function slapCarrier(target, shouldRun)
    local rec = target and target.rec
    local uid = rec and rec.Uid
    local plr = target and target.player or playerFromUserId(rec and rec.CarrierUserId)
    if not plr or plr == LP then
        emit("Hit", "warn", "carrier missing")
        return false
    end
    local tool = findBatTool()
    if not tool then
        emit("Hit", "warn", "no bat")
        return false
    end
    if not equipBat(tool) then
        emit("Hit", "warn", "equip bat failed")
        return false
    end
    local range = batRange(tool)
    local swingAt = range
    local summary = target.info and M.targetSummary(target.info) or "carrier"
    local gname = tostring(tool:GetAttribute("GearName") or tool.Name or "bat")
    emit("Hit", "live", string.format("%s | belakang %.1fst | range %.0f | %s", gname, BAT.stick, range, summary))
    local root0 = getRoot()
    if not root0 or isGameplaySide(root0.Position) ~= true then
        local hub = waitStartAreaCFrame(3, shouldRun)
        if typeof(hub) == "CFrame" then
            travelTo(hub, "start-area", shouldRun)
        end
    end
    local t0 = os.clock()
    local lastSwing = 0
    local lastSnap = 0
    local outcome = "timeout"
    local function chaseRun()
        if type(shouldRun) == "function" and shouldRun() == false then
            outcome = "stop"
            return false
        end
        if os.clock() - t0 >= 16 then
            outcome = "timeout"
            return false
        end
        if os.clock() - lastSnap > 0.8 then
            lastSnap = os.clock()
            task.spawn(function()
                EGG.sync()
            end)
        end
        local still, recNow = recordStillCarriedBy(uid, plr.UserId)
        if still == true or playerHoldsEgg(plr, uid) then
            return carrierHrp(plr) ~= nil
        end
        if recNow and (recNow.State == AreaStates.Dropped or recNow.State == "Dropped") then
            outcome = "dropped"
            return false
        end
        if recNow and (recNow.State == AreaStates.Claimed or recNow.State == "Claimed") then
            outcome = "lost"
            dbg("HIT", "chase claimed")
            return false
        end
        if recNow == nil then
            return carrierHrp(plr) ~= nil
        end
        outcome = "lost"
        dbg("HIT", "chase lost state=" .. tostring(recNow.State))
        return false
    end
    local function stickGoal()
        local h = carrierHrp(plr)
        if not h then
            return nil
        end
        return stickFront(h, true)
    end
    local function trySwing()
        local hrp = carrierHrp(plr)
    local root = getRoot()
        if not hrp or not root then
            return
        end
        if batGameplayOk(LP) ~= true or batGameplayOk(plr) ~= true then
            if os.clock() - BAT.skipAt > 0.6 then
                BAT.skipAt = os.clock()
                dbg("HIT", "skip safe-zone/hub")
            end
            return
        end
        local d = dist3(root, hrp)
        if d > swingAt + 10 then
            if os.clock() - BAT.skipAt > 0.6 then
                BAT.skipAt = os.clock()
                dbg("HIT", string.format("skip far 3d=%.1f range=%.1f", d, swingAt))
            end
            return
        end
        if tool:GetAttribute("CooldownActive") == true or os.clock() - lastSwing < BAT.cooldown then
            facePart(hrp)
            return
        end
        tool = findBatTool() or tool
        if not (tool and equipBat(tool)) then
            return
        end
        if tool.Parent ~= LP.Character or tool:GetAttribute("CooldownActive") == true then
            return
        end
        -- Tarik ke 1.6st di DEPAN HRP live, hadap carrier, lalu fire.
        local from = root.Position
        local to = hrp.Position
        local park = stickFront(hrp)
        if park then
            pcall(function()
                root.CFrame = CFrame.lookAt(
                    Vector3.new(park.X, from.Y, park.Z),
                    Vector3.new(to.X, from.Y, to.Z)
                )
            end)
        else
            facePart(hrp)
        end
        lastSwing = os.clock()
        local ok = fireBat(plr)
        dbg("HIT", string.format("swing 3d=%.1f range=%.1f fire=%s", d, range, tostring(ok)))
    end
    local hNow = carrierHrp(plr)
    if not hNow then
        emit("Hit", "warn", "carrier missing")
        return false
    end
    travelTo(hNow.CFrame, "hit", chaseRun, {
        goalFn = stickGoal,
        hold = true,
        arrive = BAT.stick + 8,
        timeout = 16,
        onTick = trySwing,
        steer = false,
    })
    if outcome == "dropped" then
        M._preferUid = tostring(uid)
        emit("Hit", "success", "egg dropped")
        return true
    end
    if outcome == "lost" then
        emit("Hit", "warn", "carrier lost egg")
        return false
    end
    if outcome == "stop" then
        return false
    end
    emit("Hit", "warn", "hit timeout")
    return false
end

local function nearestEgg(opts)
    opts = type(opts) == "table" and opts or {}
    local ttl = 0.38
    if G.__StealEggLiteOn == true or G.__StealEggFarOn == true or G.__StealEggBusy == true then
        ttl = 0.62
    end
    if opts.topN == nil then
        local age = os.clock() - (tonumber(EGG._pickCacheAt) or 0)
        local cached = EGG._pickCache
        if type(cached) == "table" and age < ttl then
            if opts.allowNoRoot == true or cached[1] ~= nil or getRoot() ~= nil then
                return cached[1], cached[2], cached[3], cached[4]
            end
        end
    end
    local function finishPick(a, b, c, d)
        if opts.topN == nil then
            EGG._pickCache = { a, b, c, d }
            EGG._pickCacheAt = os.clock()
        end
        return a, b, c, d
    end
    local root = getRoot()
    local origin = root and root.Position
    if typeof(origin) ~= "Vector3" and opts.allowNoRoot ~= true then
        return nil, nil, 0, 0
    end

    local visible, matched = 0, 0
    local records = getSnapshotRecords()
    local order = EGG.clampGrabOrder(M.grabOrder) or "earn"
    M.grabOrder = order
    if not M._rateSave or os.clock() - (M._rateSaveAt or 0) > 0.8 then
        M._rateSave = getSave()
        M._rateSaveAt = os.clock()
    end

    local prefer = tostring(M._preferUid or "")
    local cands = {}
    for _, rec in ipairs(records) do
        visible += 1
        if recordActive(rec) then
            if eggIsSkipped(rec.Uid) then
                -- skip: mati loop / bukan gameplay area
            else
            local ok, info = M.eggAllowed(rec)
            if ok then
                local dropped = recordIsDropped(rec)
                local legs = stealMode() == "walk" or stealMode() == "glide"
                if legs and dropped ~= true and resolveWorkspaceModel(rec.Uid) == nil then
                    ok = false
                end
            end
            if ok then
                matched += 1
                local pos = recordPos(rec)
                local dropped = recordIsDropped(rec)
                local preferred = prefer ~= "" and tostring(rec.Uid) == prefer
                if preferred and (typeof(pos) ~= "Vector3" or dropped ~= true) then
                    pos = worldPosition(resolveWorkspaceModel(rec.Uid)) or M._lastEggPos or origin
                end
                if typeof(pos) == "Vector3" or opts.allowNoRoot == true then
                    local dist = math.huge
                    if typeof(pos) == "Vector3" and typeof(origin) == "Vector3" then
                        dist = (pos - origin).Magnitude
                    end
                    cands[#cands + 1] = {
                        rec = rec,
                        info = info,
                        pos = pos,
                        dist = dist,
                        dropped = dropped == true,
                        preferred = preferred == true,
                        uid = tostring(rec.Uid or ""),
                    }
                end
            end
            end
        elseif M.hitCarriers == true then
            local st = rec.State
            if st == AreaStates.Carried or st == "Carried" then
                local carrierId = tonumber(rec.CarrierUserId)
                if carrierId and carrierId ~= LP.UserId then
                    local ok, info = M.eggAllowed(rec)
                    if ok then
                        matched += 1
                        local plr = playerFromUserId(carrierId)
                        local hrp = carrierHrp(plr)
                        if hrp and (typeof(origin) ~= "Vector3" or isGameplaySide(hrp.Position)) then
                            local pos = hrp.Position
                            local dist = math.huge
                            if typeof(origin) == "Vector3" then
                                dist = (pos - origin).Magnitude
                            end
                            local preferred = prefer ~= "" and tostring(rec.Uid) == prefer
                            cands[#cands + 1] = {
                                rec = rec,
                                info = info,
                                pos = pos,
                                dist = dist,
                                dropped = false,
                                preferred = preferred == true,
                                uid = tostring(rec.Uid or ""),
                                kind = "carrier",
                                player = plr,
                            }
                        end
                    end
                end
            end
        end
    end

    M._rateSave = nil

    if #cands == 0 then
        return finishPick(nil, nil, visible, matched)
    end

    -- Filler Index/Rift dibuang kalau scramble butuh kaki, atau kalau masih
    -- ada kandidat rule sungguhan.
    do
        local ruleCands = {}
        for _, c in ipairs(cands) do
            local inf = c.info
            local filler = type(inf) == "table" and (inf.riftOnly == true or inf.indexOnly == true)
            if not filler then
                ruleCands[#ruleCands + 1] = c
            end
        end
        if #ruleCands > 0 and #ruleCands < #cands then
            cands = ruleCands
        elseif EGG.sideStealOk() ~= true then
            cands = ruleCands
        end
    end
    if type(opts.skip) == "table" then
        local kept = {}
        for i = 1, #cands do
            local c = cands[i]
            if opts.skip[tostring(c.uid or "")] ~= true then
                kept[#kept + 1] = c
            end
        end
        cands = kept
    end
    if #cands == 0 then
        return finishPick(nil, nil, visible, 0)
    end

    table.sort(cands, function(a, b)
        if a.preferred ~= b.preferred then
            return a.preferred == true
        end
        local ia = indexNeedsCategory(a.info and a.info.category)
        local ib = indexNeedsCategory(b.info and b.info.category)
        if ia ~= ib then
            return ia == true
        end
        -- Slot / drop dulu. Hit carrier hanya kalau tidak ada telur di tanah.
        local ac = a.kind == "carrier"
        local bc = b.kind == "carrier"
        if ac ~= bc then
            return not ac
        end
        local ap, as = EGG.grabOrderScore(order, a.info, a.dist)
        local bp, bs = EGG.grabOrderScore(order, b.info, b.dist)
        if ap ~= bp then
            return ap > bp
        end
        if as ~= bs then
            return as > bs
        end
        return tostring(a.uid) < tostring(b.uid)
    end)

    local pick = cands[1]
    if tonumber(opts.topN) and tonumber(opts.topN) > 1 then
        local out = {}
        local want = math.clamp(math.floor(tonumber(opts.topN) or 3), 1, 3)
        for i = 1, #cands do
            local p = cands[i]
            if p.kind ~= "carrier" and typeof(p.pos) == "Vector3" then
                local model = resolveWorkspaceModel(p.rec.Uid)
                out[#out + 1] = {
                    rec = p.rec,
                    model = model,
                    prompt = findPrompt(model, p.pos),
                    pos = p.pos,
                    category = p.info and p.info.category or p.rec.AssetCategory,
                    areaId = p.info and p.info.areaId or p.rec.AreaId,
                    info = p.info,
                    uid = p.uid,
                    dist = p.dist,
                }
                if #out >= want then
                    break
                end
            end
        end
        return out, visible, matched
    end
    local model = resolveWorkspaceModel(pick.rec.Uid)
    local best = {
        rec = pick.rec,
        model = model,
        prompt = findPrompt(model, pick.pos),
        pos = pick.pos,
        category = pick.info and pick.info.category or pick.rec.AssetCategory,
        areaId = pick.info and pick.info.areaId or pick.rec.AreaId,
        info = pick.info,
        kind = pick.kind,
        player = pick.player,
        uid = pick.uid,
    }
    return finishPick(best, pick.dist, visible, matched)
end

function M.bestMatch()
    return nearestEgg({ allowNoRoot = true })
end

function M.hasRuleTarget()
    local now = os.clock()
    if now - (tonumber(M._hasRuleAt) or 0) < 0.4 then
        return M._hasRuleV == true
    end
    local stealOn = M.enabled == true
        or G.__StealEggWanted == true
        or G.__StealEggLoopOn == true
    if stealOn ~= true then
        M._hasRuleAt = now
        M._hasRuleV = false
        return false
    end
    -- Claim/pad: jangan nearestEgg + GetRate semua telur (freeze ~1s di safezone).
    if G.__StealEggClaiming == true or os.clock() < (tonumber(G.__StealEggClaimCool) or 0) then
        M._hasRuleAt = now
        M._hasRuleV = false
        return false
    end
    local pick
    local ok = pcall(function()
        pick = select(1, nearestEgg())
    end)
    local hit = ok == true and pick ~= nil
    if hit == true and type(pick.info) == "table" and (pick.info.riftOnly == true or pick.info.indexOnly == true) then
        hit = false
    end
    M._hasRuleAt = now
    M._hasRuleV = hit
    return hit
end

-- Place / Sell / Index: boleh jalan kalau karakter tidak sedang dipakai.
-- Auto Steal ON + masih ada egg match ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Place TUNGGU (jangan rebut kaki).
-- Pengecualian: __StealEggPlaceWindow (jendela singkat setelah batch teleport).
-- Treadmill / WaitÃƒâ€šÃ‚Â·no match BUKAN alasan nahan Place (belt rank 10 < place 50).
function M.canSideWork()
    -- Tas penuh: Sell harus dapat kaki meski steal masih ON + ada match di map.
    if type(EGG.eggBagFull) == "function" then
        local okf, full = pcall(EGG.eggBagFull)
        if okf == true and full == true then
            if scrambleNeedsLegs() == true then
                return false
            end
            return true
        end
    end
    if G.__StealEggBusy == true or G.__StealEggClaiming == true then
        return false
    end
    if M._busy == true then
        return false
    end
    if G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
        -- Mid Instant session (hide/cam) - jangan rebut karakter.
        return false
    end
    if isCarryingUid() == true then
        return false
    end
    do
        local scramble = G.StealEggScramble
        if type(scramble) == "table" and scramble.enabled == true then
            if scrambleNeedsLegs() == true then
                return false
            end
            if scramble._busy == true then
                return false
            end
            if type(scramble.isLocked) == "function" then
                local ok, locked = pcall(scramble.isLocked)
                if ok == true and locked == true then
                    return false
                end
            end
        end
    end
    -- Jendela reset: kaki dipakai nunggu gerbang, bukan place.
    if M.enabled == true and G.__StealEggWanted == true and STEER.resetRace() == true then
        return false
    end
    -- Steal masih hidup + ada target: Place/Sell jangan gasuke.
    -- Tas penuh: lepas kaki supaya Auto Sell jalan (bukan Wait·steal).
    local bagFullNow = false
    if type(EGG.eggBagFull) == "function" then
        local okf, full = pcall(EGG.eggBagFull)
        bagFullNow = okf == true and full == true
    end
    if bagFullNow ~= true then
        if M.enabled == true and G.__StealEggWanted == true and G.__StealEggPlaceWindow ~= true then
            if EGG.hasPick() == true or EGG.hasPickPos() == true then
                return false
            end
        end
    end
    return true
end

-- move.lua manggil shouldRun tiap Heartbeat. Scan penuh 60x/detik kemahalan,
-- jadi jawabannya dipakai ulang sebentar.
function EGG.gate(key, fn)
    local now = os.clock()
    local slot = EGG.gates[key]
    if slot == nil then
        slot = { at = 0, set = false }
        EGG.gates[key] = slot
    end
    if slot.set == true and now - slot.at < EGG.gateTtl then
        return slot.v
    end
    slot.at = now
    slot.set = true
    slot.v = fn()
    return slot.v
end

function EGG.scanPick()
    return select(1, nearestEgg()) ~= nil
end

function EGG.scanPickPos()
    local opts = getRoot() == nil and { allowNoRoot = true } or nil
    local pick = select(1, nearestEgg(opts))
    return pick ~= nil and typeof(pick.pos) == "Vector3"
end

function EGG.hasPick()
    return EGG.gate("pick", EGG.scanPick) == true
end

function EGG.hasPickPos()
    return EGG.gate("pickPos", EGG.scanPickPos) == true
end

function M.goTo(dest, reason, shouldRun, extra)
    return travelViaStartArea(dest, reason, shouldRun, extra)
end

-- Lompatan ke posisi (Y tetap).
function M.farSnapTo(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.farSnapTo) == "function" and I._ready == true then
        return I.farSnapTo(...)
    end
    return false
end

function M.isFarMode()
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.isFarMode) == "function" and I._ready == true then
        return I.isFarMode()
    end
    local mode = tostring(M.moveMode or ""):lower()
    return mode == "teleport" or mode == "instant" or mode == "far"
end
function M.stealPad()
    return EGG.stealPadCFrame()
end

function M.plotHome()
    return plotHomeCFrame()
end

function M.isCarrying()
    return isCarryingUid() == true
end

function M.holdingParasiteTool()
    local char = LP.Character
    if not char then
        return false
    end
    local inv = eggInventoryMap()
    for _, child in ipairs(char:GetChildren()) do
        if isEggTool(child) then
            local uid = tostring(toolUid(child) or "")
            local rec = uid ~= "" and inv[uid]
            if type(rec) == "table" and rec.HasParasite == true then
                return true, uid
            end
        end
    end
    return false
end

function M.isStealLocked()
    if G.__StealEggClaiming == true then
        return true
    end
    return M._busy == true
end

function M.equipEggUid(uid)
    uid = tostring(uid or "")
    if uid == "" then
        return false
    end
    unequipPets()
    Core.eggCall("RequestEquipTool", uid)
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if char and hum then
        local function wear(parent)
            if not parent then
                return false
            end
            for _, child in ipairs(parent:GetChildren()) do
                if isEggTool(child) and tostring(toolUid(child) or "") == uid then
                    if child.Parent ~= char then
                        pcall(function()
                            hum:EquipTool(child)
                        end)
                    end
                    return child.Parent == char
                end
            end
            return false
        end
        if wear(char) then
            return true
        end
        wear(LP:FindFirstChild("Backpack"))
    end
    local t0 = os.clock()
    while os.clock() - t0 < 0.9 do
        local ch = LP.Character
        if ch then
            for _, child in ipairs(ch:GetChildren()) do
                if isEggTool(child) and tostring(toolUid(child) or "") == uid then
                    return true
                end
            end
        end
        task.wait(0.05)
    end
    return false
end

function M.claimCarrying(shouldRun)
    hookCarryState()
    syncCarryFromRecord()
    if isCarryingUid() ~= true then
        return true
    end
    local run = shouldRun
    if type(run) ~= "function" then
        run = function()
            return true
        end
    end
    return claimAtHome(run) == true
end

-- Steal benar-benar jalan / ada match.
function M.isStealBlocking()
    if G.__StealEggBusy == true or G.__StealEggClaiming == true or M._busy == true then
        return true, "busy", "steal running"
    end
    local carry = M._carry
    if type(carry) == "table" and carry.IsCarrying == true then
        return true, "carry", "carrying"
    end
    local stealOn = M.enabled == true
        or G.__StealEggWanted == true
        or G.__StealEggLoopOn == true
    if stealOn == true then
        local pick
        local ok = pcall(function()
            pick = select(1, nearestEgg())
        end)
        if ok and pick ~= nil then
            local name = pick.info and pick.info.name or pick.category or "egg"
            return true, "eggs", tostring(name)
        end
    end
    return false
end

-- Hop ditahan: steal sedang gerak/carry/claim, ATAU steal ON dan ada telur lolos rule.
function M.shouldHoldHop()
    local hold, why, detail = M.isStealBlocking()
    if hold == true then
        return true, why, detail
    end
    local sell = G.StealEggSell
    if type(sell) == "table" and type(sell.pet) == "table" and sell.pet._busy == true then
        return true, "sell", "selling"
    end
    local scramble = G.StealEggScramble
    if type(scramble) == "table" and type(scramble.shouldHoldHop) == "function" then
        local okS, holdS, whyS, detS = pcall(scramble.shouldHoldHop)
        if okS == true and holdS == true then
            return true, tostring(whyS or "scramble"), tostring(detS or whyS or "scramble")
        end
    end
    local boss = G.StealEggBoss
    if type(boss) == "table" and type(boss.shouldHoldHop) == "function" then
        local okB, holdB, whyB, detB = pcall(boss.shouldHoldHop)
        if okB == true and holdB == true then
            return true, tostring(whyB or "boss"), tostring(detB or whyB or "boss")
        end
    end
    return false
end

-- Pulang ke pad sesudah telur di tangan. Melangkah dulu lewat Move.GoTo
-- (walkHomeToPad), jadi steer Avoid Traps / Avoid Guards tetap ikut dan
-- karakter benar-benar berjalan, bukan pindah seketika. Lompatan hanya dipakai
-- kalau jalannya gagal, supaya telurnya tidak tertinggal di lapangan.
local function homeToPad(padBase, padPos, homeRun, uid)
    local walked = false
    local mode = tostring(EGG.homeMove or "walk"):lower()
    if mode ~= "jump" and type(EGG.walkHomeToPad) == "function" then
        local homeTries = math.max(1, math.floor(tonumber(EGG.homeTries) or 10))
        for attempt = 1, homeTries do
            walked = EGG.walkHomeToPad(padBase, homeRun) == true
            if walked == true or isDead() then
                break
            end
            -- Masih memegang telurnya: cuma tersangkut, biar lompatan cadangan
            -- yang menyelesaikan. Terlepas: ambil lagi di tempat lalu lanjut.
            if isCarryingUid() then
                break
            end
            if type(EGG.regrabDropped) ~= "function" or EGG.regrabDropped(uid, homeRun) ~= true then
                break
            end
            dbg("CLAIM", string.format("telur di tangan lagi | lanjut jalan (coba %d/%d)", attempt + 1, homeTries))
        end
    end
    if walked == true then
        return true
    end
    dbg("CLAIM", "pad walk gagal | jangan snap pad (mati)")
    return false
end

local function waitClaim(homeCf, shouldRun)
    local info = M._lastInfo
    emit("Claim", "live", info and M.targetSummary(info) or "claiming")
    local sawCarry = M._carry.IsCarrying == true
    local t0 = os.clock()
    local pulled = false
    local claimWait = 2.5
    local holdExtra = 2.0
    if stealMode() == "teleport" or G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
        -- StealFix / MaxEarn: claim di pad. Chain next ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ budget lebih longgar.
        if EGG._chainNext == true then
            claimWait = tonumber(EGG.chainClaimWait) or 0.95
            holdExtra = 0.7
        else
            claimWait = tonumber(EGG.sfClaimWait) or 0.7
            holdExtra = 0.55
        end
    end
    if typeof(homeCf) ~= "CFrame" then
        dbg("CLAIM", "skip no home dest")
        return false
    end
    dbg("CLAIM", string.format("wait start %.2fs sawCarry=%s inPlot=%s pad=%s", claimWait, tostring(sawCarry), tostring(inLocalPlot()), tostring(homeCf.Position)))
    local lastHandoff = 0
    while GEN == G.__StealEggWildGen do
        local elapsed = os.clock() - t0
        local holding = isCarryingUid()
        if elapsed >= claimWait and not (holding == true and elapsed < claimWait + holdExtra) then
            break
        end
        if M._claimed ~= nil then
            dbg("CLAIM", "ok event")
            return true
        end
        if type(shouldRun) == "function" and shouldRun() == false then
            dbg("CLAIM", "wait abort shouldRun")
            return M._claimed ~= nil
        end
        if isDead() then
            dbg("CLAIM", "wait abort dead")
            return false
        end
        -- Jangan FireServer ForestHandoff. Deposited = telur balik ke sarang.
        if (stealMode() == "teleport" or G.__StealEggFarOn == true) and holding == true and (os.clock() - lastHandoff) > 0.12 then
            lastHandoff = os.clock()
            EGG.askForestHandoff(M._carry.Uid)
        end
        if typeof(homeCf) == "CFrame" and pulled ~= true then
            local root = getRoot()
            if root and (root.Position - homeCf.Position).Magnitude > 18 then
                if xzNear(root.Position, homeCf.Position, 32) then
                    pulled = true
                    dbg("CLAIM", "skip pull already xzNear32")
                else
                    pulled = true
                    local mag = (root.Position - homeCf.Position).Magnitude
                    dbg("CLAIM", "pull home mag=" .. string.format("%.0f", mag))
                    if stealMode() == "teleport" or G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
                        if mag > 80 then
                            EGG.recoverToClaimPad(shouldRun, "waitClaim-pull")
                        else
                            travelTo(homeCf, "home", shouldRun, { mode = "glide", longSnap = false, skipRubberWait = true })
                        end
                else
                    travelTo(homeCf, "home", shouldRun)
                    end
                end
            end
        end
        if M._claimed ~= nil then
            dbg("CLAIM", "ok event")
            return true
        end
        if holding then
            sawCarry = true
        elseif sawCarry then
            -- Server ambil telur: carry hilang dulu, ClaimFeedback belakangan (log: +40ms).
            local tDrop = os.clock()
            while os.clock() - tDrop < 0.12 do
                if M._claimed ~= nil then
                    dbg("CLAIM", "ok event after carry clear")
                    return true
                end
                if type(shouldRun) == "function" and shouldRun() == false then
                    break
                end
                task.wait()
            end
            if inLocalPlot() then
                M._preferUid = nil
                dbg("CLAIM", "ok carry cleared in plot")
                return true
            end
            -- FAR MaxEarn: claim di Forest pad - treat near-pad as OK
            if stealMode() == "teleport" or G.__StealEggFarOn == true then
                local root = getRoot()
                if root and xzNear(root.Position, homeCf.Position, 90) then
                    M._preferUid = nil
                    dbg("CLAIM", "ok carry cleared near pad")
                    return true
                end
            end
            dbg("CLAIM", "dropped mid-wait")
            return false
        end
        task.wait()
    end
    -- FAR timeout: masih di pad + sempat handoff = treat soft-ok jika claimed/carry hilang
    if (stealMode() == "teleport" or G.__StealEggFarOn == true) and M._claimed == nil then
        local root = getRoot()
        local atPad = root and xzNear(root.Position, homeCf.Position, 90)
        if atPad and isCarryingUid() ~= true and sawCarry == true then
            dbg("CLAIM", "timeout near-pad treat ok")
            return true
        end
        dbg("CLAIM", string.format("wait end claimed=%s carry=%s atPad=%s", tostring(M._claimed ~= nil), tostring(M._carry.IsCarrying == true), tostring(atPad)))
        return false
    end
    dbg("CLAIM", string.format("wait end claimed=%s carry=%s", tostring(M._claimed ~= nil), tostring(M._carry.IsCarrying == true)))
    return M._claimed ~= nil
end

local function claimAtHome(shouldRun)
    G.__StealEggClaiming = true
    G.__StealEggClaimCool = os.clock() + 2.5
    if not ensureOffBelt(shouldRun) then
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 5
        return false
    end
    -- Teleport: claim di Forest pad (SF/MaxEarn). Plot SpawnPoint FAR sering rubber.
    if stealMode() == "teleport" or G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
        local uid = tostring(M._carry and M._carry.Uid or "")
        if uid:find("FirstAreaEgg_", 1, true) == 1 then
            -- Umpan Forest. Bukan loot. Jangan claimFarPad (itu sempat drop umpan).
            dbg("CLAIM", "claimAtHome skip FirstArea bait uid=" .. uid:sub(1, 48))
            G.__StealEggClaiming = false
            G.__StealEggClaimCool = os.clock() + 5
            return false
        end
        local I = G.StealEggInstant
        if uid ~= "" and type(I) == "table" and type(I.claimFarPad) == "function" and I._ready == true then
            dbg("CLAIM", "claimAtHome ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Instant.claimFarPad uid=" .. uid)
            local ok = I.claimFarPad(uid, shouldRun, false)
            G.__StealEggClaiming = false
            G.__StealEggClaimCool = os.clock() + 5
            if ok == true or M._claimed ~= nil then
                EGG._claimFailN = 0
                return true
            end
            -- Claim gagal: backoff singkat. JANGAN skipEgg/dropÃƒÆ’Ã¢â‚¬â€2 - itu bikin max steal notif = 2.
            if isCarryingUid(uid) or isCarryingUid() then
                local fails = (tonumber(EGG._claimFailN) or 0) + 1
                EGG._claimFailN = fails
                dbg("DENY", string.format("claimFarPad fail | n=%d | retry", fails))
                task.wait(fails >= 3 and 0.85 or 0.35)
            end
            return false
        end
        local padOk, padCf = EGG.recoverToClaimPad(shouldRun, "claimAtHome")
        if typeof(padCf) == "CFrame" then
            if uid ~= "" then
                EGG.askForestHandoff(uid)
            end
            local ok = waitClaim(padCf, shouldRun)
            if ok ~= true and M._claimed == nil and isCarryingUid() then
                local root = getRoot()
                if root and xzNear(root.Position, padCf.Position, 90) ~= true then
                    dbg("CLAIM", "retry recover pad mid-claim")
                    EGG.recoverToClaimPad(shouldRun, "claim-retry")
                    if uid ~= "" then
                        EGG.askForestHandoff(uid)
                    end
                    ok = waitClaim(padCf, shouldRun)
                end
            end
            G.__StealEggClaiming = false
            G.__StealEggClaimCool = os.clock() + 5
            return ok == true or M._claimed ~= nil
        end
    end
    -- Walk/glide: claim di pad aman, bukan SpawnPoint plot.
    -- Sesudah claim, loop ambil telur berikutnya dari sini.
    if stealMode() == "walk" or stealMode() == "glide" then
        local padCf = EGG.claimPadCFrame()
        emit("Home", "live", "claiming")
        dbg("CLAIM", string.format(
            "walk/glide pad %.0f,%.0f",
            padCf.Position.X, padCf.Position.Z
        ))
        travelTo(padCf, "home", shouldRun)
        local padOk = waitClaim(padCf, shouldRun)
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 5
        return padOk == true or M._claimed ~= nil
    end
    local dest = goHomeNow(shouldRun)
    if typeof(dest) ~= "CFrame" then
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 5
        return false
    end
    if type(shouldRun) == "function" and shouldRun() == false and M._claimed == nil then
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 5
        return false
    end
    local ok = waitClaim(dest, shouldRun)
    G.__StealEggClaiming = false
    G.__StealEggClaimCool = os.clock() + 5
    return ok == true or M._claimed ~= nil
end

local function stealTarget(target, seq, opts)
    opts = type(opts) == "table" and opts or {}
    hookCarryState()

    local function running()
        if type(opts.shouldRun) == "function" then
            local ok, v = pcall(opts.shouldRun)
            return ok == true and v == true
        end
        return stealWanted(seq)
    end

    if not recoverIfDead(running) then
        return false
    end
    if not ensureOffBelt(running) then
        return false
    end

    syncCarryFromRecord()
    if isCarryingUid() then
        local holdUid = tostring(M._carry and M._carry.Uid or "")
        if holdUid:find("FirstAreaEgg_", 1, true) == 1 then
            dbg("STEAL", "umpan FirstArea di tangan | lanjut Instant, jangan claim")
        else
            dbg("STEAL", "already carrying ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ claim dulu uid=" .. holdUid)
            emit("Home", "live", "claiming")
            if claimAtHome(running) then
                emit("Stolen", "success", M._lastInfo and (M.targetSummary(M._lastInfo) .. " | claim") or "claim")
                return true
            end
            if isCarryingUid() then
                emit("Denied", "warn", "claim failed")
                return false
            end
            emit("Denied", "warn", "egg dropped before claim")
            if M._carry.Uid then
                M._preferUid = tostring(M._carry.Uid)
            end
            return false
        end
    end

    stopHold()

    M._claimed = nil

    if target.kind == "carrier" then
        local okHunt = false
        if M.hitCarriers == true then
            okHunt = slapCarrier(target, running) == true
        end
        if okHunt ~= true then
            return false
        end
        local uidDropped = target.rec and target.rec.Uid
        for _, r in ipairs(getSnapshotRecords()) do
            if tostring(r.Uid) == tostring(uidDropped) then
                target.rec = r
                target.pos = recordPos(r) or worldPosition(resolveWorkspaceModel(uidDropped)) or target.pos
                target.info = M.describeRecord(r) or target.info
                target.kind = nil
                break
            end
        end
        M._preferUid = tostring(uidDropped or "")
    end

    local rec = target.rec
    local info = target.info or (type(rec) == "table" and M.describeRecord(rec)) or nil
    M._lastInfo = info
    local uid = rec and rec.Uid
    local model = resolveWorkspaceModel(uid) or target.model
    local pos = worldPosition(model) or recordPos(rec) or target.pos
    local label = tostring((info and info.name) or target.category or uid or "egg")
    local summary = info and M.targetSummary(info, typeof(pos) == "Vector3" and distTo(pos) or nil) or label

    if typeof(pos) ~= "Vector3" then
        emit("Denied", "warn", "egg position missing")
        return false
    end
    if uid == nil or tostring(uid) == "" then
        emit("Denied", "warn", "egg missing")
        return false
    end
    uid = tostring(uid)
    if isCarryingUid() then
        emit("Claim", "live", "carrying")
        local carryUid = tostring(M._carry.Uid or uid)
        M._stolen = {
            category = tostring(target.category or M._carry.AssetCategory or label),
            carryUid = carryUid,
        }
        local homeRun = stillHolding(carryUid, running)
        return claimAtHome(homeRun) == true
    end
    if recordIsDropped(rec) then
        M._preferUid = uid
    end
    dbg("STEAL", string.format(
        "begin %s uid=%s xz=%.0f dropped=%s",
        summary,
        uid,
        distXZ(pos),
        tostring(recordIsDropped(rec) == true)
    ))

    M._lastEggPos = pos
    local eggCf = CFrame.new(pos + Vector3.new(0, 3, 0))
    local prompt = findPrompt(model, pos)
    armStealPrompt(prompt)
    emit("Move", "live", summary)

    local snapOn = true
    local eggGone = false
    local function stopSnap()
        snapOn = false
    end
    local function markGone()
        if eggGone then
            return
        end
        eggGone = true
        stopSnap()
        dbg("STEAL", "target gone uid=" .. uid)
        if tostring(M._preferUid) == uid then
            local goneRec = getEggRecord(uid)
            local cid = type(goneRec) == "table" and tonumber(goneRec.CarrierUserId)
            if cid and cid ~= (LP and LP.UserId) then
                M._preferUid = nil
            end
        end
        local dGone = G.StealEggDispatch
        if type(dGone) == "table" and type(dGone.Stop) == "function" then
            pcall(dGone.Stop, "steal")
        else
            local Move = getMove()
            if Move and type(Move.StopRaw) == "function" then
                pcall(Move.StopRaw)
            elseif Move and type(Move.Stop) == "function" then
                pcall(Move.Stop)
            end
        end
    end
    local function eggLive()
        model = resolveWorkspaceModel(uid) or model
        if isCarryingUid(uid) then
            return true
        end
        if targetEggLive(uid, model) then
            return true
        end
        markGone()
        return false
    end
    local function runningToEgg()
        if running() ~= true then
            stopSnap()
            return false
        end
        if eggGone then
            return false
        end
        return eggLive()
    end
    -- Cache lokal saja. RequestAreaEggSnapshot InvokeServer ngantri RequestCarry.
    task.spawn(function()
        while snapOn and running() do
            if snapOn and eggLive() ~= true then
                break
            end
            task.wait(0.2)
        end
    end)

    -- < 200st: invoke RequestCarry di jalan. Speed 1000 ÃƒÂ¢Ã¢â‚¬Â°Ã‹â€  0.2s; RTT ~0.3s
    -- jadi server sering cek posisi saat kita sudah di egg.
    local okNow, errNow = false, nil
    local holding = false
    local carryBusy = false
    local closerOnce = false
    local areaDeny = false
    local function markHold()
        holding = true
        M._holdAt = os.clock()
        -- Instant: jangan nulis IsCarrying palsu. Replica EggState yang sah.
        if stealMode() == "teleport" then
            return
        end
        if M._carry.IsCarrying ~= true then
            M._carry.IsCarrying = true
            M._carry.Uid = uid
        end
    end
    local function pulseCarry()
        if holding == true or carryBusy == true or eggGone then
            return
        end
        if isDead() then
            return
        end
        if isCarryingUid(uid) then
            markHold()
            return
        end
        pos = worldPosition(model) or recordPos(rec) or pos
        if typeof(pos) ~= "Vector3" then
            return
        end
        local d = distXZ(pos)
        -- Decoy: StealFix grant ~12st dari egg. Jangan spam AskCarry dari 50st+ (mid-glide jauh).
        local maxPulse = EGG.preCarry
        if stealMode() == "teleport" or G.__StealEggDecoyOn == true then
            maxPulse = tonumber(EGG.sfCarryNear) or 16
        end
        if d > maxPulse then
            return
        end
        -- Setelah Get closer, jangan spam jauh. Di dekat egg tetap retry.
        if closerOnce == true and d > (tonumber(EGG.sfCarryNear) or 16) then
            return
        end
        if areaDeny == true then
            return
        end
        -- Decoy Forest: jangan blok mid-glide (isGameplaySide sering false di edge).
        if stealMode() ~= "teleport" and G.__StealEggDecoyOn ~= true then
            local here = getRoot() and getRoot().Position
            if typeof(here) == "Vector3" and isGameplaySide(here) ~= true and d > 12 then
                return
            end
        end
        emit("Steal", "live", summary)
        carryBusy = true
        local function takeReply(ok, err)
            okNow, errNow = ok, err
            local msg = tostring(err or "")
            if ok == true or isCarryingUid(uid) then
                markHold()
            elseif msg:find("Get closer", 1, true) then
                closerOnce = true
            elseif msg:find("Egg not found", 1, true) then
                -- SF dump: deny ini normal; sync+retry di requestCarry. Jangan skip.
            elseif msg:find("Already carrying", 1, true) then
                markHold()
            end
            carryBusy = false
        end
        -- Di telur: panggil CarryFieldEgg di thread ini. Jangan fireproximityprompt
        -- (bisa nunggu terus) dan jangan spawn yang bikin carryBusy macet.
        if stealMode() ~= "teleport" and d <= (tonumber(EGG.walkGrab) or 6) then
            takeReply(requestCarry(uid, rec))
            if holding == true then
                EGG.kickOffEgg()
            else
                local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if hum and typeof(pos) == "Vector3" then
                    pcall(function()
                        hum.PlatformStand = false
                        hum.Sit = false
                        hum:MoveTo(pos)
                    end)
                end
            end
        else
            task.spawn(function()
                takeReply(requestCarry(uid, rec))
            end)
        end
    end
    local function toEgg()
        if holding == true then
        return false
    end
        return runningToEgg()
    end
    -- FAR (ex-Decoy): hide+cam ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Forest Guard ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ FAR snap rule egg ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ carry ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ claim
    local useTpSteal = stealMode() == "teleport"
    local eggExtra = {
        onTick = pulseCarry,
    }
    local function finishTpFreeze(why)
        if useTpSteal ~= true then
            return
        end
        if why == "after-carry" then
            emit("Home", "live", "home")
            task.wait(tonumber(EGG.sfRestore) or 0.12)
        elseif why == "parasite" then
            -- Event lanjut FAR snap ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ monster; jangan delay restore lama.
            emit("Home", "live", "home")
            task.wait(0.04)
        end
        EGG.endFarSession(why)
    end

    local travelOk = false
    local function legsHitDrop()
        if M._dropSnap == true and tostring(M._preferUid or "") == uid then
            return true
        end
        if recordIsDropped(rec) == true or recordIsDropped(getEggRecord(uid)) == true then
            return true
        end
        if M._carry.IsCarrying == true or tostring(M._preferUid or "") ~= uid then
            return false
        end
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            local st
            pcall(function()
                st = hum:GetState()
            end)
            if st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.Physics then
                return true
            end
        end
        local rt = LP:GetAttribute("RagdollEndTime")
        if type(rt) == "number" then
            local now = 0
            pcall(function()
                now = workspace:GetServerTimeNow()
            end)
            if rt - now > 0 then
                return true
            end
        end
        return false
    end
    local function snapToDroppedEgg()
        model = resolveWorkspaceModel(uid) or model
        pos = worldPosition(model) or recordPos(getEggRecord(uid) or rec) or pos
        if typeof(pos) ~= "Vector3" then
            return false
        end
        eggCf = CFrame.new(pos.X, pos.Y + 3, pos.Z)
        emit("Going", "live", "drop")
        dbg("STEAL", string.format("hit drop walk xz=%.0f", distXZ(pos)))
        local ok = travelViaStartArea(eggCf, "egg", toEgg, eggExtra)
        if distXZ(pos) <= (tonumber(EGG.walkGrab) or 12) then
            M._dropSnap = false
            return true
        end
        return ok == true
    end
    if useTpSteal then
        EGG._tpSnapFix = 0
        EGG._landAt = nil
        local rubberLeft = (tonumber(G.__StealEggRubberUntil) or 0) - os.clock()
        if rubberLeft > 0 then
            emit("Denied", "warn", "waiting")
            task.wait(math.min(rubberLeft, 2.5))
        return false
    end
        if EGG.beginFarSession(running) ~= true then
            emit("Denied", "warn", "session fail")
            return false
        end

        local function carryRaceFar(sec, whyTag)
            local carryUid = tostring(uid or "")
            local gap = tonumber(EGG.sfCarryGap) or 0.08
            local win = tonumber(sec) or 0.85
            local t0 = os.clock()
            emit("Steal", "live", summary .. (whyTag and (" | " .. whyTag) or ""))
            local p = findPrompt(resolveWorkspaceModel(carryUid), pos)
            while holding ~= true and running() and (os.clock() - t0) < win do
                if isCarryingUid(carryUid) or isCarryingUid() then
                    if isCarryingUid(carryUid) or tostring(M._carry.Uid) == carryUid then
                        uid = carryUid
                    end
                    markHold()
                    break
                end
                local mNow = resolveWorkspaceModel(carryUid)
                pos = worldPosition(mNow) or pos
                if typeof(pos) == "Vector3" then
                    eggCf = CFrame.new(pos.X, pos.Y + 2.2, pos.Z)
                    local dNow = distXZ(pos)
                    if carryBusy ~= true then
                        fireStealPrompt(p)
                        pulseCarry()
                        requestCarry(carryUid, rec or getEggRecord(carryUid))
                    end
                end
                task.wait(gap)
                p = findPrompt(resolveWorkspaceModel(carryUid), pos) or p
            end
        end

        local padCf = EGG.stealPadCFrame()
        local padPos = typeof(padCf) == "CFrame" and padCf.Position or Vector3.new(515, 71, -363)
        pos = worldPosition(model) or recordPos(rec) or pos
        local eggDist = 9999
        if typeof(pos) == "Vector3" then
            eggDist = Vector3.new(padPos.X - pos.X, 0, padPos.Z - pos.Z).Magnitude
        end
        local farGate = tonumber(EGG.farGate) or tonumber(EGG.sfFarDist) or 140

        if eggDist > farGate then
            emit("Going", "live", summary)
            if EGG.waitForestGuardHit(running, EGG.guardTimeout) ~= true then
                stopSnap()
                finishTpFreeze("no-guard")
                emit("Denied", "warn", "-")
                task.wait(0.35)
                return false
            end
            if isDead() then
                stopSnap()
                finishTpFreeze("dead")
                return false
            end
            pos = worldPosition(model) or recordPos(rec) or pos
            if typeof(pos) ~= "Vector3" then
                stopSnap()
                finishTpFreeze("no-pos")
                emit("Denied", "warn", "egg gone")
                return false
            end
            eggCf = CFrame.new(pos.X, 74, pos.Z)
            G.__StealEggTpHold = true
            G.__StealEggMoveQuiet = true
            if EGG.snapFarY74(pos, running, "rule", { keepY = true }) ~= true then
                stopSnap()
                finishTpFreeze("far-fail")
                G.__StealEggRubberUntil = os.clock() + 2.0
                emit("Denied", "warn", "-")
                task.wait(0.5)
                return false
            end
            closerOnce = false
            carryRaceFar(tonumber(EGG.sfFarCarryWindow) or 0.85, "FAR")
        else
            emit("Going", "live", summary)
            if typeof(pos) == "Vector3" then
                EGG.trustLandAt(pos)
            end
            G.__StealEggTpHold = true
            G.__StealEggMoveQuiet = true
            closerOnce = false
            carryRaceFar(tonumber(EGG.sfFarCarryWindow) or 0.85, "near")
        end

        if holding == true then
            travelOk = true
            dbg("HOLD", "FAR egg ok uid=" .. tostring(uid) .. " | pad claim")
            -- Skip jalur Node lama (carry window 2ÃƒÆ’Ã¢â‚¬â€ / travel checks) - langsung claim seperti MaxEarn
            M._preferUid = nil
            M._stolen = {
                category = tostring(target.category or M._carry.AssetCategory or label),
                carryUid = uid,
            }
            EGG.stopMove()
            local padBase = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
            local padPos = Vector3.new(padBase.X, 74, padBase.Z)
            G.__StealEggClaiming = true
            G.__StealEggTpHold = true
            G.__StealEggMoveQuiet = true
            local homeRun = stillHolding(uid, running)
            EGG.clearFarHold("pre-pad")
            emit("Home", "live", "claiming")
            local walkedHome = homeToPad(padBase, padPos, homeRun, uid)
            EGG.askForestHandoff(uid)
            local claimOk = false
            if isDead() ~= true and homeRun() then
                claimOk = waitClaim(CFrame.new(padPos), homeRun) == true
            end
            G.__StealEggClaiming = false
            G.__StealEggClaimCool = os.clock() + 5
            EGG.clearFarHold("after-claim")
            finishTpFreeze("after-carry")
            if claimOk or M._claimed ~= nil then
                dbg("CLAIM", "FAR success")
                emit("Stolen", "success", info and M.targetSummary(info) or label)
                return true
            end
            if isCarryingUid(uid) ~= true then
                M._preferUid = tostring(uid)
                emit("Move", "live", "dropped")
        return false
    end
            dbg("CLAIM", "FAR timeout still carrying")
            emit("Denied", "warn", "claim timeout")
            return false
        else
            travelOk = false
            dbg("DENY", "FAR carry miss uid=" .. tostring(uid))
            stopSnap()
            finishTpFreeze("carry-miss")
            emit("Denied", "warn", "carry failed")
            task.wait(0.35)
            return false
        end
        G.__StealEggTpHold = true
        G.__StealEggMoveQuiet = true
    else
        -- Walk/glide: lurus kaki Speed UI + MoveTo. Window Impulse seperti MaxEarn.
        if typeof(waitStartAreaCFrame(8, toEgg)) ~= "CFrame" then
            stopSnap()
            finishTpFreeze("no-hub")
            emit("Denied", "warn", "waiting")
            return false
        end
        G.__StealEggLegsWalk = true
        do
            local I = G.StealEggInstant
            if type(I) == "table" and type(I.armMoveWindow) == "function" then
                pcall(I.armMoveWindow)
            end
        end
        emit("Going", "live", summary)
        if legsHitDrop() then
            travelOk = snapToDroppedEgg()
        else
            travelOk = travelViaStartArea(eggCf, "egg", toEgg, eggExtra)
        end
    end
    if travelOk ~= true and holding ~= true and not nearEgg(pos)
        and not (useTpSteal ~= true and distXZ(pos) <= (tonumber(EGG.walkGrab) or 12)) then
        stopSnap()
        finishTpFreeze("travel-fail")
        -- Dump Node: failÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢retry 0.1s = DECOYÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬ÂRESTORE thrash. Backoff.
        task.wait(0.85)
        if areaDeny == true then
            emit("Denied", "warn", "gameplay area")
        else
            emit("Denied", "warn", "travel failed")
            dbg("DENY", string.format("travel abort uid=%s xz=%.0f", uid, distXZ(pos)))
        end
        return false
    end
    if isDead() then
        if distXZ(pos) < 80 then
            skipEggUid(uid, "died")
        end
        stopSnap()
        finishTpFreeze("dead")
        return false
    end
    if areaDeny == true and holding ~= true then
        stopSnap()
        finishTpFreeze("area-deny")
        emit("Denied", "warn", "gameplay area")
        return false
    end
    if holding == true then
        stopSnap()
    elseif eggGone or not runningToEgg() or isDead() then
        stopSnap()
        finishTpFreeze("gone")
        if eggGone then
            emitIfChanged("Looking", "live", summary)
        end
        return false
    else
        pos = worldPosition(model) or recordPos(rec) or pos
        if typeof(pos) == "Vector3" then
            eggCf = CFrame.new(pos.X, pos.Y + (useTpSteal and 2.2 or 3), pos.Z)
        end
        -- FAR: already landed via snap; no re-jump (thrash).
        local rootNow = getRoot()
        local tpAtEgg = useTpSteal == true and rootNow and typeof(pos) == "Vector3"
            and (nearEgg(pos) == true or xzNear(rootNow.Position, pos, 72) == true)
        if useTpSteal ~= true and distXZ(pos) > (tonumber(EGG.walkGrab) or 12) then
        if typeof(startAreaCFrame()) ~= "CFrame" then
                stopSnap()
                finishTpFreeze("no-hub2")
                emit("Denied", "warn", "waiting")
            return false
        end
            local legOk = legsHitDrop() and snapToDroppedEgg() or travelViaStartArea(eggCf, "egg", toEgg, eggExtra)
            if legOk ~= true and holding ~= true and distXZ(pos) > (tonumber(EGG.walkGrab) or 12) then
                stopSnap()
                finishTpFreeze("travel-fail2")
                emit("Denied", "warn", "travel failed")
                dbg("DENY", string.format("travel abort uid=%s xz=%.0f", uid, distXZ(pos)))
                return false
            end
        elseif useTpSteal == true and tpAtEgg ~= true and holding ~= true then
            skipEggUid(uid, "not at egg")
            stopSnap()
            finishTpFreeze("not-at-egg")
            task.wait(1.2)
            emit("Denied", "warn", "not at egg")
            return false
        end
        if useTpSteal ~= true then
            standOnEgg(pos)
        end
        if eggGone and holding ~= true then
            stopSnap()
            finishTpFreeze("gone2")
            emitIfChanged("Looking", "live", summary)
            return false
        end
        local atEgg = nearEgg(pos) == true or distXZ(pos) <= 16
        if holding ~= true and useTpSteal ~= true and atEgg ~= true then
            stopSnap()
            finishTpFreeze("not-at-egg")
            emit("Denied", "warn", "not at egg")
            dbg("DENY", string.format("belum sampai egg xz=%.0f 3d=%.0f", distXZ(pos), distTo(pos)))
        if type(G.BridgeDump) == "function" then
            pcall(G.BridgeDump)
        end
        return false
    end
        if holding ~= true and eggLive() ~= true then
            stopSnap()
            finishTpFreeze("not-live")
            emitIfChanged("Looking", "live", summary)
            return false
        end
        stopSnap()
    end

    EGG._carryTry = 0
    EGG._tpCloserFix = false
    if useTpSteal then
        EGG.stopMove()
        G.__StealEggTpHold = true
        G.__StealEggMoveQuiet = true
    end
    -- Walk/glide: jangan settle/waitGround. Ragdoll habis di nest = Relocate + diam, gak carry.
    prompt = findPrompt(model, pos) or prompt
    if useTpSteal ~= true then
        emit("Steal", "live", summary)
    end
    local tCarry = os.clock()
    while holding ~= true and carryBusy == true and os.clock() - tCarry < 0.5 do
        if isCarryingUid(uid) then
            markHold()
                break
            end
        task.wait()
    end
    -- StealFix: 2ÃƒÆ’Ã¢â‚¬â€ carry ~0.13s gap, window singkat lalu pulang.
    local carryWindow = useTpSteal and (tonumber(EGG.sfForestWindow) or 0.65) or 6
    local carryGap = useTpSteal and (tonumber(EGG.sfCarryGap) or 0.13) or 0.04
    while runningToEgg() and holding ~= true and os.clock() - tCarry < carryWindow do
        if isDead() then
            stopSnap()
            finishTpFreeze("dead-carry")
            return false
        end
        if isCarryingUid(uid) then
            markHold()
            break
        end
        if carryBusy == true then
            task.wait()
        else
            pos = worldPosition(model) or recordPos(rec) or pos
            if typeof(pos) == "Vector3" then
                eggCf = CFrame.new(pos.X, pos.Y + 2.2, pos.Z)
            end
            if useTpSteal then
                local r = getRoot()
                -- Trace: carry saat Freefall di egg; toleransi longgar (bukan 14st).
                if r and typeof(pos) == "Vector3" and xzNear(r.Position, pos, 64) ~= true then
                    dbg("DENY", "tp carry not-at-egg xz=" .. string.format("%.0f", distXZ(pos)))
                    skipEggUid(uid, "tp carry rubber")
                    break
                end
            elseif not nearEgg(pos) and distXZ(pos) > 16 then
                local legOk = legsHitDrop() and snapToDroppedEgg() or travelViaStartArea(eggCf, "egg", toEgg, eggExtra)
                if legOk ~= true and holding ~= true and not nearEgg(pos) and distXZ(pos) > 16 then
                    stopSnap()
                    finishTpFreeze("travel-fail3")
                    return false
                end
                if not runningToEgg() then
                    break
                end
            end
            EGG._carryTry = (EGG._carryTry or 0) + 1
        emit("Steal", "live", summary)
        okNow, errNow = requestCarry(uid, rec)
        local msg = tostring(errNow or "")
        local already = msg:find("Already carrying", 1, true) ~= nil
            local notFound = msg:find("Egg not found", 1, true) ~= nil
            if okNow == true or already or isCarryingUid(uid) then
                markHold()
                if useTpSteal ~= true then
                    EGG.kickOffEgg()
                end
            break
        end
            if notFound then
                if isCarryingUid(uid) then
                    markHold()
                else
                    markGone()
                end
                break
            end
            if msg:find("Get closer", 1, true) then
                if useTpSteal then
                    -- 1x plant saja. Resync/stand loop = thrash di dump.
                    if EGG._tpCloserFix ~= true and typeof(pos) == "Vector3" then
                        EGG._tpCloserFix = true
                        dbg("STEAL", "tp closer skip plant xz=" .. string.format("%.1f", distXZ(pos)))
                    else
                        local r = getRoot()
                        if r then
                            pcall(function()
                                r.AssemblyLinearVelocity = Vector3.zero
                                r.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end
                    end
                    task.wait(0.1)
                else
                    closerOnce = true
                    local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                    if h and typeof(pos) == "Vector3" then
                        pcall(function()
                            h.PlatformStand = false
                            h.Sit = false
                            h:MoveTo(pos)
                        end)
                    end
                    task.wait(0.08)
                end
            elseif msg:find("gameplay area", 1, true) then
                skipEggUid(uid, "gameplay area")
                break
            end
            task.wait(carryGap)
        end
    end
    stopSnap()

    if eggGone and holding ~= true then
        finishTpFreeze("gone-hold")
        emitIfChanged("Looking", "live", summary)
        return false
    end

    if holding then
        M._preferUid = nil
    end
    dbg("HOLD", string.format(
        "holding=%s ok=%s err=%s carry=%s sec=%.2f xz=%.0f tries=%s",
        tostring(holding),
        tostring(okNow),
        tostring(errNow),
        tostring(M._carry.IsCarrying == true),
        os.clock() - tCarry,
        distXZ(pos),
        tostring(EGG._carryTry or 0)
    ))

    if not holding then
        finishTpFreeze("carry-fail")
        emit("Denied", "warn", "carry failed")
        if useTpSteal then
            if recordIsDropped(getEggRecord(uid)) then
                M._preferUid = tostring(uid)
            else
                skipEggUid(uid, "tp carry fail")
            end
            task.wait(0.45)
        end
        if type(G.BridgeDump) == "function" then
            pcall(G.BridgeDump)
        end
        return false
    end

    M._stolen = {
        category = tostring(target.category or M._carry.AssetCategory or label),
        carryUid = uid,
    }

    -- Carry OK ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ clear egg-hold ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ lompat pad Y74 (settle 0.08) ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ handoff/claim
    if useTpSteal then
        EGG.stopMove()
        local Move = getMove()
        if type(Move) == "table" and type(Move.Stop) == "function" then
            pcall(Move.Stop)
        end
        -- MaxEarn fixed pad - jangan scan stealPad tiap claim (lambat)
        local padBase = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
        local padPos = Vector3.new(padBase.X, 74, padBase.Z)
    G.__StealEggClaiming = true
        G.__StealEggTpHold = true
        G.__StealEggMoveQuiet = true
        local homeRun = stillHolding(uid, running)
        EGG.clearFarHold("pre-pad")
        emit("Home", "live", "claiming")
        dbg("CLAIM", string.format("pulang ke pad %.0f,%.0f carry=%s", padPos.X, padPos.Z, tostring(isCarryingUid(uid))))
        local walkedHome = homeToPad(padBase, padPos, homeRun, uid)
        EGG.askForestHandoff(uid)
        local claimOk = false
        if isDead() ~= true and homeRun() then
            claimOk = waitClaim(CFrame.new(padPos), homeRun) == true
        end
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 5
        EGG.clearFarHold("after-claim")
        finishTpFreeze("after-carry")
        if claimOk or M._claimed ~= nil then
            dbg("CLAIM", "FAR success")
            emit("Stolen", "success", info and M.targetSummary(info) or label)
            return true
        end
        if isCarryingUid(uid) ~= true then
        M._preferUid = tostring(uid)
            emit("Move", "live", "dropped")
        return false
    end
        dbg("CLAIM", "FAR timeout still carrying")
        emit("Denied", "warn", "claim timeout")
        return false
    end

    local homeRun = stillHolding(uid, running)
    local claimOk = claimAtHome(homeRun) == true
    if claimOk then
        emit("Stolen", "success", info and M.targetSummary(info) or label)
        return true
    end
    if isCarryingUid(uid) ~= true then
        M._preferUid = tostring(uid)
        emit("Move", "live", "dropped")
        return false
    end
    if typeof(plotHomeCFrame()) ~= "CFrame" then
        emit("Denied", "warn", "plot missing")
        return false
    end
    emit("Denied", "warn", "claim timeout")
    return false
end

-- MaxEarn-style: claim di Forest pad. chainNext=true ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ keep hide/cam untuk hop berikutnya.
function EGG.plantPadHard(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.plantPadHard) == "function" and I._ready == true then
        return I.plantPadHard(...)
    end
    return false
end

function EGG.claimFarPad(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.claimFarPad) == "function" and I._ready == true then
        return I.claimFarPad(...)
    end
    return false
end

function EGG.carryRaceAt(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.carryRaceAt) == "function" and I._ready == true then
        return I.carryRaceAt(...)
    end
    return false
end

function EGG.refreshChainTarget(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.refreshChainTarget) == "function" and I._ready == true then
        return I.refreshChainTarget(...)
    end
    return false
end

function EGG.nextChainFill(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.nextChainFill) == "function" and I._ready == true then
        return I.nextChainFill(...)
    end
    return false
end
function EGG.farChainRun(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.farChainRun) == "function" and I._ready == true then
        return I.farChainRun(...)
    end
    return false
end
function EGG.stealFarChain(...)
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.stealFarChain) == "function" and I._ready == true then
        return I.stealFarChain(...)
    end
    return false
end
local function loop(seq)
    hookCarryState()
    STEER.hookResetSignals()
    captureHome()
    M.getCatalog()
    local pick = M.bestMatch()
    if pick and pick.info then
        emit("On", "live", M.targetSummary(pick.info))
    else
        emit("On", "live", "-")
    end
    if type(getEggCmds()) ~= "table" then
        emit("Error", "error", "not ready")
        dbg("LOOP", "EggCmds missing at start | " .. tostring(Core.lastRequireErr))
    else
        EGG.sync()
    end
    if not isPlayable() then
        emit("Life", "live", "waiting")
    end
    waitPlayable(function()
        return stealWanted(seq)
    end)
    waitStartAreaCFrame(10, function()
        return stealWanted(seq)
    end)

    local lastSnap = 0
    local idleEmptySince = nil
    local wentHomeIdle = false
    while G.__StealEggWanted == true and seq == G.__StealEggSeq and GEN == G.__StealEggWildGen and M.enabled do
        if not recoverIfDead(function()
            return stealWanted(seq)
        end) then
            task.wait(0.1)
        else
        do
            if scrambleNeedsLegs() == true
                and isCarryingUid() ~= true
                and M._busy ~= true
                and G.__StealEggFarOn ~= true
                and G.__StealEggClaiming ~= true
                and G.__StealEggStealFlow ~= true
            then
                local liveSteal = false
                if M.wallHold() ~= true then
                    local pick
                    pcall(function()
                        pick = select(1, nearestEgg())
                    end)
                    liveSteal = pick ~= nil
                        and typeof(pick.pos) == "Vector3"
                        and not (type(pick.info) == "table" and (pick.info.riftOnly == true or pick.info.indexOnly == true))
                end
                if liveSteal == true then
                    G.__StealEggStealFlow = true
                else
                    G.__StealEggStealFlow = false
                    local d = G.StealEggDispatch
                    if type(d) == "table" and type(d.Release) == "function" then
                        pcall(d.Release, "steal")
                    end
                    emitIfChanged("Wait", "live", "scramble")
                    task.wait(0.2)
                    continue
                end
            end
        end
        if G.__StealEggBusy == true or G.__StealEggClaiming == true then
            if G.__StealEggClaiming ~= true
                and M._busy ~= true
                and G.__StealEggBusy == true
            then
                dbg("LOOP", isCarryingUid() == true and "clear busy | claim dulu" or "clear stale busy")
                G.__StealEggBusy = false
            else
                EGG.dbgSnap("WAIT-LOCK")
                task.wait(EGG.stealTickWait("busy"))
            end
        else
            if type(GM.EggCmds) ~= "table" then
                GM.EggCmds = getEggCmds()
                if type(GM.EggCmds) == "table" then
                    dbg("LOOP", "EggCmds recovered")
                    hookCarryState()
                    EGG.sync()
                end
            end
            syncCarryFromRecord()
            local loopBaitUid = tostring(M._carry and M._carry.Uid or "")
            local holdingBait = isCarryingUid() == true
                and loopBaitUid:find("FirstAreaEgg_", 1, true) == 1
            local instantBusy = G.__StealEggFarOn == true
                or M._busy == true
                or G.__StealEggClaiming == true
            -- Zip: umpan bukan loot. Jangan parkir — steal memakai umpan ini.
            if isCarryingUid() and not (holdingBait and instantBusy ~= true) then
                if holdingBait then
                    dbg("LOOP", "hold FirstArea bait | skip claim")
                    task.wait(EGG.stealTickWait("busy"))
                else
                idleEmptySince = nil
                wentHomeIdle = false
                local d = G.StealEggDispatch
                if type(d) == "table" and type(d.Hold) == "function" then
                    pcall(d.Hold, "claim")
                end
                local carryInfo = M._lastInfo
                dbg("LOOP", "CARRY home uid=" .. tostring(M._carry.Uid))
                emit("Claim", "live", carryInfo and M.targetSummary(carryInfo) or "carrying")
                local carryUid = M._carry.Uid
                local loopRun = function()
                    return G.__StealEggWanted == true
                        and seq == G.__StealEggSeq
                        and GEN == G.__StealEggWildGen
                        and M.enabled == true
                end
                local homeRun = stillHolding(carryUid, loopRun)
                if claimAtHome(homeRun) then
                    -- claimed; loop continues
                elseif isCarryingUid() ~= true then
                    if carryUid then
                        M._preferUid = tostring(carryUid)
                    end
                    emit("Move", "live", "dropped")
                else
                    emit("Home", "warn", "plot missing")
                    task.wait(0.25)
                end
                if type(d) == "table" and type(d.Release) == "function" then
                    pcall(d.Release, "claim")
                end
                end
            else
                if holdingBait == true then
                    dbg("LOOP", "FirstArea bait | start steal")
                end
                clearStaleBelt()
                -- Jangan Release steal dulu: scramble nabrak dekat telur.
                -- Lepas kaki hanya kalau nearestEgg memang kosong (di bawah).
                -- Di belt: sync jarang. Scan tetap nearestEgg (jangan skip -
                -- cheap path sempat bikin miss target / claim kacau).
                local onBeltIdle = M._onBelt == true or M._farmingBelt == true
                local claimCool = os.clock() < (tonumber(G.__StealEggClaimCool) or 0)
                local target, dist, visible, matched = nearestEgg()
                if not target and claimCool then
                    emitIfChanged("Wait", "live", "claim")
                    task.wait(0.2)
                    continue
                end
                if not target then
                    local preview = target
                    local snapEvery = M._preferUid and 1.0 or 8
                    local racing = STEER.resetRace() == true
                    if G.__StealEggFarOn == true or G.__StealEggBusy == true then
                        snapEvery = 99
                    elseif racing then
                        -- Spawn countdown: hemat. Wall countdown: telur sudah ada
                        -- (FieldRefreshed). Jangan RequestAreaEggSnapshot 12×/detik.
                        local spawnLeft = STEER.untilSpawn()
                        local wallLeft = STEER.untilWall()
                        if (type(spawnLeft) == "number" and spawnLeft > 0.4)
                            or (type(wallLeft) == "number" and wallLeft > 0.45)
                        then
                        snapEvery = 2.5
                        else
                            snapEvery = 0.4
                        end
                    elseif onBeltIdle then
                        -- FieldRefreshed sudah isi cache; sync remote cuma tiap 10s.
                        snapEvery = M._preferUid and 1.0 or 10
                    elseif preview and typeof(preview.pos) ~= "Vector3" then
                        snapEvery = 0.4
                    end
                    if snapEvery < 90 and os.clock() - lastSnap > snapEvery then
                        if racing then
                            if EGG.snapRecs == nil then
                                EGG.sync()
                            end
                        else
                            EGG.sync()
                        end
                        lastSnap = os.clock()
                    end
                    if preview and preview.info then
                        emitIfChanged("Wait", "live", M.targetSummary(preview.info) .. " | no pos")
                    else
                        emitIfChanged("Wait", "live", "no match")
                    end
                    EGG.dbgSnap("WAIT")
                    G.__StealEggStealFlow = false
                    if scrambleNeedsLegs() == true then
                        do
                            local d = G.StealEggDispatch
                            if type(d) == "table" and type(d.Release) == "function" then
                                pcall(d.Release, "steal")
                            end
                        end
                    end

                    -- Tidak ada egg yang bisa di-steal: pulang plot. Masih ada egg: jangan pulang (StartArea cukup).
                    -- Tidak ada egg yang bisa di-steal (posisi ada). Snapshot match tanpa pos = idle/hop.
                    local noStealEgg = target == nil
                    if noStealEgg then
                        if tostring(M._preferUid or ""):find("FirstAreaEgg_", 1, true) == 1 then
                            M._preferUid = nil
                        end
                        if tostring(M._preferUid or "") ~= "" then
                            idleEmptySince = nil
                            wentHomeIdle = false
                            emitIfChanged("Wait", "live", "regrab drop")
                            if type(EGG.regrabDropped) == "function" then
                                pcall(EGG.regrabDropped, tostring(M._preferUid), function()
                                    return stealWanted(seq) == true
                                end)
                            end
                            task.wait(0.08)
                        else
                        -- FAR idle: jangan tinggal freeze (TpHold + WalkSpeed 0 dari snapLong home).
                        -- Treadmill: jangan thaw/unsit tiap tick - berdiri di pad tanpa lari.
                        local onBeltNow = M._onBelt == true or G.__StealEggOnBelt == true
                        if onBeltNow ~= true and scrambleNeedsLegs() ~= true then
                            if G.__StealEggFarOn == true
                                or G.__StealEggDecoyOn == true
                                or G.__StealEggTpHold == true
                                or M._homeFreeze == true
                            then
                                EGG.endFarSession("no-match")
                            end
                            EGG.restoreMove("no-match")
                        end
                        if scrambleNeedsLegs() == true then
                            emitIfChanged("Wait", "live", "scramble")
                            task.wait(0.2)
                        elseif M.wallHold() == true then
                            idleEmptySince = nil
                            wentHomeIdle = false
                            G.__StealEggPlaceWindow = false
                            STEER.stagePad(function()
                                return stealWanted(seq) == true
                            end)
                            emitIfChanged("Wait", "live", M._wallWhy or "gate")
                        elseif placeKeepsPlot() == true then
                            -- Place/Index busy: tarik PetArea (jangan diam di claim pad ~10s).
                            idleEmptySince = nil
                            wentHomeIdle = false
                            stealIdleStayPlot(seq)
                        elseif M.beltYield() == true then
                            idleEmptySince = nil
                            wentHomeIdle = false
                            emitIfChanged("Wait", "live", "busy")
                            task.wait(0.15)
                        elseif M.autoTreadmill == true then
                            idleEmptySince = nil
                            wentHomeIdle = false
                            -- Ada egg di tas buat Place: minggir dari belt, jangan nunggu match.
                            if M.placeWantsLegs() == true and M.canSideWork() == true then
                                M._farmingBelt = false
                                do
                                    local d = G.StealEggDispatch
                                    if type(d) == "table" and type(d.Release) == "function" then
                                        pcall(d.Release, "belt")
                                    end
                                end
                                stealIdleStayPlot(seq)
                                task.wait(0.25)
                            else
                            local farmOk = farmTreadmill(function()
                                return EGG.farmRun(seq)
                            end)
                            -- Stuck di steal/safe pad + gagal belt (kaki boss/place):
                            -- pulang plot. Jangan trigger saat masih perjalanan ke belt.
                            if farmOk ~= true and M._onBelt ~= true and M._farmingBelt ~= true
                                and wentHomeIdle ~= true then
                                local root = getRoot()
                                local pad = typeof(EGG.padPos) == "Vector3" and EGG.padPos or Vector3.new(515, 71, -363)
                                if root ~= nil and xzNear(root.Position, pad, 40) then
                                    emit("Home", "live", "no egg | leave pad")
                                    local idleRun = function()
                                        if G.__StealEggWanted ~= true
                                            or seq ~= G.__StealEggSeq
                                            or GEN ~= G.__StealEggWildGen
                                            or M.enabled ~= true then
                                            return false
                                        end
                                        return EGG.hasPick() ~= true
                                    end
                                    goHomeNow(idleRun)
                                    EGG.endFarSession("idle-home")
                                    EGG.restoreMove("idle-home")
                                    wentHomeIdle = true
                                    emitIfChanged("Idle", "muted", "no egg | at home")
                                end
                            end
                            task.wait((M._onBelt == true or M._farmingBelt == true) and 1.2 or 0.35)
                            end
                        else
                        if idleEmptySince == nil then
                            idleEmptySince = os.clock()
                        end
                        if wentHomeIdle ~= true and os.clock() - idleEmptySince >= 1.2 then
                            local root = getRoot()
                            local homeCf = plotHomeCFrame()
                            local atHome = false
                            if root then
                                if inLocalPlotBounds(root.Position) then
                                    atHome = true
                                elseif homeCf and xzNear(root.Position, homeCf.Position, 32) then
                                    atHome = true
                                end
                            end
                            if atHome then
                                wentHomeIdle = true
                                EGG.restoreMove("idle-home")
                                emitIfChanged("Idle", "muted", "no egg | at home")
                            else
                                emit("Home", "live", "going home")
                                local idleRun = function()
                                    if G.__StealEggWanted ~= true
                                        or seq ~= G.__StealEggSeq
                                        or GEN ~= G.__StealEggWildGen
                                        or M.enabled ~= true then
                                        return false
                                    end
                                    -- Egg muncul lagi: berhenti pulang, steal dari StartArea.
                                    return EGG.hasPick() ~= true
                                end
                                goHomeNow(idleRun)
                                -- FAR jump home set WS=0 + TpHold - thaw biar tidak freeze.
                                EGG.endFarSession("idle-home")
                                EGG.restoreMove("idle-home")
                                wentHomeIdle = true
                                emitIfChanged("Idle", "muted", "no egg | at home")
                            end
                            end
                        end
                        end
                    else
                        idleEmptySince = nil
                    end
                    if scrambleNeedsLegs() == true then
                        task.wait(0.15)
                    elseif STEER.resetRace() == true or M.wallHold() == true then
                        pcall(function()
                            if stealMode() == "teleport" then
                                STEER.instantPrep(function()
                                    return stealWanted(seq) == true and scrambleNeedsLegs() ~= true
                                end)
                            else
                                local I = G.StealEggInstant
                                if type(I) == "table" and type(I.preArm) == "function" then
                                    I.preArm()
                                end
                            end
                        end)
                        task.wait(0.2)
                    else
                        task.wait(EGG.stealTickWait("empty"))
                    end
                else
                    idleEmptySince = nil
                    wentHomeIdle = false
                    M._farmingBelt = false
                    -- Tas penuh: jangan spam steal. Idle + jendela Sell/Place.
                    local bagFull = os.clock() < (tonumber(G.__StealEggBagFullUntil) or 0)
                    if bagFull ~= true and type(EGG.eggBagFull) == "function" then
                        local okf, full = pcall(EGG.eggBagFull)
                        bagFull = okf == true and full == true
                    end
                    if bagFull then
                        if type(EGG.markBagFull) == "function" then
                            pcall(EGG.markBagFull)
                        else
                            G.__StealEggPlaceWindow = true
                            G.__StealEggBagFullUntil = os.clock() + 8
                        end
                        emitIfChanged("Idle", "muted", "bag full")
                        task.wait(0.35)
                    -- Teleport: jangan yield ke place di sini (putus chain 1–2/3).
                    -- Place dapat jendela setelah batch selesai.
                    elseif M.beltYield() == true and stealMode() ~= "teleport" then
                        dbg("IDLE", string.format(
                            "yield skip steal belt=%s idxBusy=%s placeBusy=%s",
                            tostring(G.__StealEggBeltHold),
                            tostring(type(G.StealEggIndexComplete) == "table" and G.StealEggIndexComplete._busy == true),
                            tostring(type(G.StealEggHatch) == "table" and G.StealEggHatch._placeBusy == true)
                        ))
                        emitIfChanged("Wait", "live", "place")
                        task.wait(0.15)
                    else
                    -- Match muncul saat farm: turun belt SEBELUM Hold/steal (semua mode).
                    local loopRun = function()
                        return G.__StealEggWanted == true
                            and seq == G.__StealEggSeq
                            and GEN == G.__StealEggWildGen
                            and M.enabled == true
                    end
                    local canSteal = true
                    if M.beltStillOn() == true or M._farmingBelt == true or M.wearingBelt() == true then
                        dbg("LOOP", "match | leave treadmill first")
                        emit("Belt", "warn", "leaving treadmill")
                        if ensureOffBelt(loopRun) ~= true then
                            canSteal = false
                            emitIfChanged("Wait", "live", "leave belt")
                            task.wait(0.2)
                        elseif M.beltStillOn() == true or M.wearingBelt() == true then
                            canSteal = false
                            emitIfChanged("Wait", "live", "leave belt")
                            task.wait(0.2)
                        end
                    end
                    if canSteal == true and M.wallHold() == true then
                        STEER.stagePad(function()
                            return stealWanted(seq) == true
                        end)
                        emitIfChanged("Wait", "live", M._wallWhy or "gate")
                        canSteal = false
                        task.wait(0.2)
                    end
                    if canSteal == true then
                    dbg("LOOP", string.format(
                        "STEAL %s uid=%s d=%.0f vis=%s match=%s",
                        tostring(target.info and target.info.name or target.category),
                        tostring(target.rec and target.rec.Uid),
                        tonumber(dist) or -1,
                        tostring(visible),
                        tostring(matched)
                    ))
                    do
                        local d = G.StealEggDispatch
                        if type(d) == "table" and type(d.Hold) == "function" then
                            local okh, got = pcall(d.Hold, "steal")
                            if okh ~= true or got ~= true then
                                local who = type(d.Owner) == "function" and d.Owner() or "?"
                                emitIfChanged("Wait", "warn", "legs held by " .. tostring(who))
                                canSteal = false
                            end
                        end
                    end
                    if canSteal ~= true then
                        task.wait(0.3)
                    elseif os.clock() < (tonumber(G.__StealEggBaitMissUntil) or 0) then
                        G.__StealEggStealFlow = false
                        G.__StealEggBusy = false
                        M._busy = false
                        if G.__StealEggFarOn == true then
                            local I = G.StealEggInstant
                            if type(I) == "table" and type(I.endFarSession) == "function" then
                                pcall(I.endFarSession, "bait-miss")
                            else
                                G.__StealEggFarOn = false
                            end
                        end
                        do
                            local d = G.StealEggDispatch
                            if type(d) == "table" and type(d.Release) == "function" then
                                pcall(d.Release, "steal")
                            end
                        end
                        task.wait(0.2)
                    else
                    G.__StealEggStealFlow = true
                    G.__StealEggBusy = true
                    M._busy = true
                    lastSnap = os.clock()
                    local ok, result
                    if stealMode() == "teleport" then
                        ok, result = pcall(EGG.stealFarChain, function()
                            return EGG.farChainRun(seq)
                        end, seq)
                    else
                        ok, result = pcall(stealTarget, target, seq)
                    end
                    M._busy = false
                    G.__StealEggBusy = false
                    if isCarryingUid() ~= true then
                        G.__StealEggStealFlow = false
                    end
                    do
                        local d = G.StealEggDispatch
                        if type(d) == "table" and type(d.Release) == "function" then
                            pcall(d.Release, "steal")
                        end
                    end
                    -- Teleport: jendela Place singkat setelah batch (jangan 2.5s - steal macet).
                    -- Hanya di sini Place boleh rebut kaki meski masih ada match.
                    if stealMode() == "teleport" then
                        local nextMatch = false
                        pcall(function()
                            nextMatch = EGG.hasPick() == true or EGG.hasPickPos() == true
                        end)
                        if nextMatch ~= true then
                        task.wait(0.08)
                        local hPlace = G.StealEggHatch
                        G.__StealEggPlaceWindow = true
                        local tPlace = os.clock() + 1.0
                        while os.clock() < tPlace do
                            if type(hPlace) == "table" and hPlace._placeBusy == true then
                                emitIfChanged("Wait", "live", "place")
                                task.wait(0.1)
                            elseif placeKeepsPlot() == true then
                                emitIfChanged("Wait", "live", "plot")
                                task.wait(0.1)
                            else
                                break
                            end
                            if stealWanted(seq) ~= true then
                                break
                            end
                        end
                        G.__StealEggPlaceWindow = false
                        -- Place masih nyangkut: lepas biar steal lanjut.
                        if type(hPlace) == "table" and hPlace._placeBusy == true then
                            hPlace._placeBusy = false
                            if type(hPlace.releaseBelt) == "function" then
                                pcall(hPlace.releaseBelt)
                            else
                                M.releaseBelt()
                            end
                            local d = G.StealEggDispatch
                            if type(d) == "table" and type(d.Release) == "function" then
                                pcall(d.Release, "place")
                            end
                        end
                        end
                    else
                    task.wait(EGG.stealTickWait("after"))
                    end
                    if not ok then
                        dbg("LOOP", "steal pcall fail | " .. tostring(result))
                        pcall(function()
                            if type(EGG.endFarSession) == "function" then
                                EGG.endFarSession("pcall")
                            end
                        end)
                        emit("Going", "warn", "-")
                    elseif result == true then
                        if stealMode() ~= "teleport" then
                            M._runs += 1
                            local info = target.info or M._lastInfo
                            emit("Stolen", "success", string.format("%s | x%d", info and M.targetSummary(info) or "egg", M._runs))
                            local hook = G.StealEggWebhook
                            if type(hook) == "table" and type(hook.notifySteal) == "function" then
                                pcall(hook.notifySteal, info)
                            end
                            local mon = G.StealEggMonitor
                            if type(mon) == "table" and type(mon.notifyLiveSteal) == "function" then
                                pcall(mon.notifyLiveSteal, info)
                            end
                        end
                        -- Instant chain sudah emit + webhook per telur. Loop ini
                        -- jangan kirim lagi, itu yang bikin notif dobel.
                    end
                    end
                    end
                end
            end
        end
        end
    end
    end

    if seq == G.__StealEggSeq then
        emit("Idle", "muted", M.idleDetail())
    end
    do
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "steal")
            pcall(d.Release, "claim")
            pcall(d.Release, "belt")
        end
    end
end

function M.setEnabled(on)
    on = on == true
    M.enabled = on
    if on then
        if G.__StealEggLoopOn == true and G.__StealEggWanted == true then
            EGG.setStealPromptHide(true)
            return
        end
        stopHold()
        G.__StealEggWanted = true
        EGG.setStealPromptHide(true)
        local Move = getMove()
        if Move and type(Move.ArmIntegrity) == "function" then
            pcall(Move.ArmIntegrity)
        end
        G.__StealEggClaiming = false
        G.__StealEggBusy = false
        G.__StealEggSeq = (tonumber(G.__StealEggSeq) or 0) + 1
        local seq = G.__StealEggSeq
        M._token = seq
        M._runs = 0
        dbg("LOOP", "ON seq=" .. tostring(seq))
        G.__StealEggLoopOn = true
        hookBelt()
        invokeTreadmill("AskDoff")
        M._farmingBelt = false
        if stealMode() ~= "teleport" then
            local sp = G.StealEggSpeed
            G.__StealEggVtScanFails = 0
            if type(sp) == "table" and type(sp.WaitArmed) == "function" then
                pcall(sp.WaitArmed, 2.2)
            elseif type(sp) == "table" and type(sp.Arm) == "function" then
                pcall(sp.Arm)
            end
        end
        task.spawn(function()
            loop(seq)
            if G.__StealEggSeq == seq then
                G.__StealEggLoopOn = false
                dbg("LOOP", "loop exit seq=" .. tostring(seq))
            end
        end)
        return
    end
    stopHold()
    EGG.setStealPromptHide(false)
    do
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "steal")
            pcall(d.Release, "claim")
            pcall(d.Release, "belt")
        end
    end
    -- Lepas Instant session supaya Place tidak stuck WaitÃƒâ€šÃ‚Â·steal (FarOn stale).
    pcall(function()
        if type(EGG.endFarSession) == "function" then
            EGG.endFarSession("steal-off")
        elseif type(EGG.restoreMove) == "function" then
            EGG.restoreMove("steal-off")
        end
    end)
    G.__StealEggFarOn = false
    G.__StealEggDecoyOn = false
    G.__StealEggTpHold = false
    G.__StealEggMoveQuiet = false
    local Move = getMove()
    if Move and type(Move.Stop) == "function" then
        pcall(Move.Stop)
    end
    G.__StealEggWanted = false
    G.__StealEggClaiming = false
    G.__StealEggBusy = false
    G.__StealEggStealFlow = false
    G.__StealEggLoopOn = false
    G.__StealEggPlaceWindow = false
    M._busy = false
    EGG.thawHomeFreeze("steal-off")
    G.__StealEggSeq = (tonumber(G.__StealEggSeq) or 0) + 1
    M._farmingBelt = false
    dbg("LOOP", "OFF")
    if M._status.text ~= "Done" then
        emit("Idle", "muted", M.idleDetail())
    end
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    if type(values["steal.wild.rules"]) == "table" then
        M.setRules(values["steal.wild.rules"])
    end
    if values["steal.wild.draft.areas"] ~= nil then
        M.draft.areas = Core.parseKeyMap(values["steal.wild.draft.areas"])
    end
    if values["steal.wild.draft.eggs"] ~= nil then
        M.draft.eggs = Core.parseKeyMap(values["steal.wild.draft.eggs"])
    end
    if values["steal.wild.draft.rarity"] ~= nil then
        M.draft.rarities = Core.parseKeyMap(values["steal.wild.draft.rarity"])
    end
    if values["steal.wild.draft.kgRule"] ~= nil then
        local kg, kgMode, kgRule = parseSignedRule(values["steal.wild.draft.kgRule"], values["steal.wild.draft.kgMode"])
        M.draft.kgRule = kgRule
        M.draft.kgMode = clampCompareMode(values["steal.wild.draft.kgMode"] or kgMode, EGG.DEFAULT_COMPARE_MODE)
    elseif values["steal.wild.draft.kgMode"] ~= nil then
        M.draft.kgMode = clampCompareMode(values["steal.wild.draft.kgMode"], EGG.DEFAULT_COMPARE_MODE)
    end
    if values["steal.wild.draft.rateRule"] ~= nil then
        local rate, rateMode, rateRule = parseSignedScaledRule(values["steal.wild.draft.rateRule"], values["steal.wild.draft.rateMode"])
        M.draft.rateRule = rateRule
        M.draft.rateMode = clampCompareMode(values["steal.wild.draft.rateMode"] or rateMode, EGG.DEFAULT_COMPARE_MODE)
    elseif values["steal.wild.draft.rateMode"] ~= nil then
        M.draft.rateMode = clampCompareMode(values["steal.wild.draft.rateMode"], EGG.DEFAULT_COMPARE_MODE)
    end
    if values["steal.wild.draft.priceRule"] ~= nil then
        local price, priceMode, priceRule = parseSignedScaledRule(values["steal.wild.draft.priceRule"], values["steal.wild.draft.priceMode"])
        M.draft.priceRule = priceRule
        M.draft.priceMode = clampCompareMode(values["steal.wild.draft.priceMode"] or priceMode, EGG.DEFAULT_COMPARE_MODE)
    elseif values["steal.wild.draft.priceMode"] ~= nil then
        M.draft.priceMode = clampCompareMode(values["steal.wild.draft.priceMode"], EGG.DEFAULT_COMPARE_MODE)
    end
    if values["steal.wild.draft.mutations"] ~= nil then
        M.draft.mutations = Core.parseKeyMap(values["steal.wild.draft.mutations"])
    end
    local order = EGG.clampGrabOrder(values["steal.wild.order"])
    if order then
        M.grabOrder = order
    end
    local moveMode = Core.dropdownValue(values["steal.wild.moveMode"])
    if type(moveMode) == "string" then
        moveMode = string.lower(moveMode)
        if moveMode == "auto" then
            M.speedMode = "manual"
            M.moveMode = "glide"
        elseif moveMode == "instant" or moveMode == "far" or moveMode == "decoy" or moveMode == "freeze" then
            M.moveMode = "teleport"
        elseif moveMode == "walk" or moveMode == "glide" or moveMode == "teleport" then
            M.moveMode = moveMode
        end
    end
    M.moveMode = workspace:GetAttribute("Event_AdminAbuse") == true and "teleport" or "walk"
    local tpAp = Core.dropdownValue(values["steal.wild.tpApproach"])
    if type(tpAp) == "string" then
        tpAp = string.lower(tpAp)
        if tpAp == "walk" then
            M.tpApproach = "walk"
        elseif tpAp == "glide" or tpAp == "snap" then
            M.tpApproach = "glide"
        end
    end
    local spdMode = Core.dropdownValue(values["steal.wild.speedMode"])
    if type(spdMode) == "string" then
        spdMode = string.lower(spdMode)
        if spdMode == "manual" or spdMode == "auto" then
            M.speedMode = spdMode
        end
    end
    local moveSpeed = tonumber(values["steal.wild.moveSpeed"])
    if moveSpeed then
        M.moveSpeed = math.clamp(math.floor(moveSpeed), 8, 5000)
    end
    if values["steal.wild.avoidTraps"] ~= nil then
        M.avoidTraps = Core.flagOn(values["steal.wild.avoidTraps"])
    end
    if values["steal.wild.avoidGuards"] ~= nil then
        M.avoidGuards = Core.flagOn(values["steal.wild.avoidGuards"])
    end
    if values["steal.wild.hitCarriers"] ~= nil then
        M.hitCarriers = Core.flagOn(values["steal.wild.hitCarriers"])
    end
    if values["steal.wild.autoTreadmill"] ~= nil then
        M.autoTreadmill = Core.flagOn(values["steal.wild.autoTreadmill"])
    end
    if values["steal.wild.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.wild.enabled"]))
    end
    local Move = getMove()
    if Move then
        if type(Move.SetMode) == "function" then
            pcall(Move.SetMode, M.moveMode)
        end
        if type(Move.SetSpeed) == "function" then
            pcall(Move.SetSpeed, M.moveSpeed)
        end
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues()
    hookBelt()
    if type(pre["steal.wild.rules"]) == "table" then
        M.setRules(pre["steal.wild.rules"])
    elseif not (M.rules and #M.rules > 0) then
        M.setRules({})
    end

    local body, _, statusApi = ui:CreateSection({
        title = "Wild Egg",
        expanded = true,
        status = {
        id = "steal.wild.status",
        persist = false,
        value = M._status.text,
        style = M._status.style,
        detail = M._status.detail,
        },
    })
    pcall(function()
        if type(getEggCmds()) == "table" then
            getSnapshotRecords()
        end
    end)
    if M.enabled ~= true then
        emit("Idle", "muted", M.idleDetail())
    elseif M._lastInfo then
        emitIfChanged(M._status.text, M._status.style, M.targetSummary(M._lastInfo))
    end

    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local statusGen = (tonumber(M._statusGen) or 0) + 1
    M._statusGen = statusGen
    task.spawn(function()
        while M._statusGen == statusGen do
            if M.enabled == true then
                task.wait(0.8)
            else
                pcall(function()
                    if type(GM.EggCmds) == "table" or type(getEggCmds()) == "table" then
                        getSnapshotRecords()
                    end
                    emitIfChanged("Idle", "muted", M.idleDetail())
                end)
                task.wait(2.5)
            end
        end
    end)

    local ruleApi
    local function persistRules()
        if ruleApi and type(ruleApi.set) == "function" then
            pcall(ruleApi.set, M.rules)
        end
        if M.enabled ~= true then
            emitIfChanged("Idle", "muted", M.idleDetail())
        end
    end
    local _, bindRules = ui:CreateRuleList(body, {
        id = "steal.wild.rules",
        title = "Saved Rules",
        searchPlaceholder = "Search rules...",
        emptyText = "Belum ada rule. Kosong = semua egg. Beberapa rule = OR.",
        visibleRows = 6,
        persist = true,
        getItems = function()
            return M.rules
        end,
        formatItem = function(rule)
            return M.formatRule(rule)
        end,
        onLoad = function(list)
            M.setRules(list)
        end,
        onToggle = function(rule, enabled)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            for _, item in ipairs(M.rules) do
                if tostring(item.id) == id then
                    item.enabled = enabled == true
                    break
                end
            end
            persistRules()
        end,
        onDelete = function(rule)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            local nextList = {}
            for _, item in ipairs(M.rules) do
                if tostring(item.id) ~= id then
                    nextList[#nextList + 1] = item
                end
            end
            M.rules = nextList
            persistRules()
        end,
    })
    ruleApi = bindRules

    local formApi
    local eggApi
    local _, bindForm = ui:CreateRuleForm(body, {
        id = "steal.wild.draft.modes",
        label = "Rule Fields",
        placeholder = "Pick fields...",
        hintText = "Pilih field, baru input muncul.",
        persist = true,
        modes = {
            { key = "zone", name = "Zone" },
            { key = "rarity", name = "Rarity" },
            { key = "egg", name = "Egg" },
            { key = "mutation", name = "Mutation" },
            { key = "kg", name = "Kg" },
            { key = "price", name = "Price $" },
            { key = "rate", name = "Earn $/s" },
        },
        onChanged = function()
            if eggApi and type(eggApi.refreshItems) == "function" then
                pcall(eggApi.refreshItems)
            end
        end,
    })
    formApi = bindForm

    local _, areaApi = ui:CreateRowDropdown(body, {
        id = "steal.wild.draft.areas",
        label = "Zone",
        mode = "multi",
        placeholder = "All zones",
        hintText = "Kosong = semua zone.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return M.listAreaItems()
        end,
        onChanged = function(a, b)
            M.draft.areas = Core.parseKeyMap(Core.dropdownValue(a, b))
            M.draft.eggs = {}
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
            if eggApi and type(eggApi.refreshItems) == "function" then
                pcall(eggApi.refreshItems)
            end
        end,
    })

    local _, rarityApi = ui:CreateRowDropdown(body, {
        id = "steal.wild.draft.rarity",
        label = "Rarity",
        mode = "multi",
        placeholder = "Any rarity",
        hintText = "Kosong = semua rarity.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return Core.RARITY_ITEMS
        end,
        onChanged = function(a, b)
            M.draft.rarities = Core.parseKeyMap(Core.dropdownValue(a, b))
        end,
    })

    local _, eggBind = ui:CreateRowDropdown(body, {
        id = "steal.wild.draft.eggs",
        label = "Egg Picker",
        mode = "multi",
        placeholder = "All eggs",
        hintText = "Kosong = semua egg di zone rule ini.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            if formApi and formApi.has("zone") then
                return M.listEggItems(M.draft.areas)
            end
            return M.listEggItems({})
        end,
        onChanged = function(a, b)
            M.draft.eggs = Core.parseKeyMap(Core.dropdownValue(a, b))
        end,
    })
    eggApi = eggBind

    local _, mutApi = ui:CreateRowDropdown(body, {
        id = "steal.wild.draft.mutations",
        label = "Mutation",
        mode = "multi",
        placeholder = "Any Mutation...",
        hintText = "Kosong = any. No Mutation = polos saja. Pilih mutasi = harus salah satu.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return M.listMutationItems()
        end,
        onChanged = function(a, b)
            M.draft.mutations = Core.parseKeyMap(Core.dropdownValue(a, b))
        end,
    })

    local kgWrap = wrapFieldStack(body)
    local _, kgModeApi = ui:CreateRowDropdown(kgWrap, {
        id = "steal.wild.draft.kgMode",
        label = "Kg mode",
        placeholder = "Mode",
        hintText = "Above = sama atau lebih besar. Below = sama atau lebih kecil.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.draft.kgMode or EGG.DEFAULT_COMPARE_MODE,
        getItems = function()
            return EGG.COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.draft.kgMode = clampCompareMode(Core.dropdownValue(a, b), EGG.DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, kgApi = ui:CreateRowInput(kgWrap, {
        id = "steal.wild.draft.kgRule",
        label = "Kg",
        initial = tostring(M.draft.kgRule or "0"),
        clearOnFocus = false,
        onChanged = function(text)
            M.draft.kgRule = unsignedRuleText(text)
        end,
    })
    local rateWrap = wrapFieldStack(body)
    local _, rateModeApi = ui:CreateRowDropdown(rateWrap, {
        id = "steal.wild.draft.rateMode",
        label = "Earn mode",
        placeholder = "Mode",
        hintText = "Above = sama atau lebih besar. Below = sama atau lebih kecil.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.draft.rateMode or EGG.DEFAULT_COMPARE_MODE,
        getItems = function()
            return EGG.COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.draft.rateMode = clampCompareMode(Core.dropdownValue(a, b), EGG.DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, rateApi = ui:CreateRowInput(rateWrap, {
        id = "steal.wild.draft.rateRule",
        label = "Earn $/s",
        initial = tostring(M.draft.rateRule or "0"),
        clearOnFocus = false,
        hintText = "k / m / b / t",
        onChanged = function(text)
            M.draft.rateRule = unsignedRuleText(text)
        end,
    })
    local priceWrap = wrapFieldStack(body)
    local _, priceModeApi = ui:CreateRowDropdown(priceWrap, {
        id = "steal.wild.draft.priceMode",
        label = "Price mode",
        placeholder = "Mode",
        hintText = "Above = sama atau lebih mahal. Below = sama atau lebih murah.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.draft.priceMode or EGG.DEFAULT_COMPARE_MODE,
        getItems = function()
            return EGG.COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.draft.priceMode = clampCompareMode(Core.dropdownValue(a, b), EGG.DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, priceApi = ui:CreateRowInput(priceWrap, {
        id = "steal.wild.draft.priceRule",
        label = "Price $",
        initial = tostring(M.draft.priceRule or "0"),
        clearOnFocus = false,
        hintText = "harga jual di Wild Info | k / m / b / t",
        onChanged = function(text)
            M.draft.priceRule = unsignedRuleText(text)
        end,
    })

    if formApi and type(formApi.attach) == "function" then
        formApi.attach("zone", areaApi, function()
            M.draft.areas = {}
            if areaApi and type(areaApi.clear) == "function" then
                pcall(areaApi.clear, true)
            end
        end)
        formApi.attach("rarity", rarityApi, function()
            M.draft.rarities = {}
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
        end)
        formApi.attach("egg", eggApi, function()
            M.draft.eggs = {}
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
        end)
        formApi.attach("mutation", mutApi, function()
            M.draft.mutations = {}
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
        end)
        formApi.attach("kg", { root = kgWrap }, function()
            M.draft.kgRule = "0"
            M.draft.kgMode = EGG.DEFAULT_COMPARE_MODE
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("rate", { root = rateWrap }, function()
            M.draft.rateRule = "0"
            M.draft.rateMode = EGG.DEFAULT_COMPARE_MODE
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("price", { root = priceWrap }, function()
            M.draft.priceRule = "0"
            M.draft.priceMode = EGG.DEFAULT_COMPARE_MODE
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
        end)
        pcall(formApi.apply)
    end

    ui:CreateRowButton(body, {
        text = "APPLY - Add Rule",
        kind = "primary",
        onClick = function()
            local modes = formApi and formApi.getModes and formApi.getModes() or {}
            local hasMode = false
            for _, on in pairs(modes) do
                if on == true then
                    hasMode = true
                    break
                end
            end
            if not hasMode then
                return
            end
            local rule = sanitizeRule({
                enabled = true,
                fields = modes,
                areas = modes.zone and M.draft.areas or {},
                eggs = modes.egg and M.draft.eggs or {},
                rarities = modes.rarity and M.draft.rarities or {},
                kgRule = modes.kg and M.draft.kgRule or "0",
                kgMode = modes.kg and M.draft.kgMode or EGG.DEFAULT_COMPARE_MODE,
                rateRule = modes.rate and M.draft.rateRule or "0",
                rateMode = modes.rate and M.draft.rateMode or EGG.DEFAULT_COMPARE_MODE,
                priceRule = modes.price and M.draft.priceRule or "0",
                priceMode = modes.price and M.draft.priceMode or EGG.DEFAULT_COMPARE_MODE,
                mutations = modes.mutation and M.draft.mutations or {},
            })
            M.rules[#M.rules + 1] = rule
            persistRules()
            M.draft = newDraft()
            if areaApi and type(areaApi.clear) == "function" then
                pcall(areaApi.clear, true)
            end
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, EGG.DEFAULT_COMPARE_MODE, true)
            end
            if eggApi and type(eggApi.refreshItems) == "function" then
                pcall(eggApi.refreshItems)
            end
        end,
    })

    ui:CreateRowDropdown(body, {
        id = "steal.wild.order",
        label = "Grab Order",
        placeholder = "Pick order",
        hintText = "Urutan egg yang cocok rule.",
        initial = M.grabOrder or "earn",
        clearable = false,
        preserveItemOrder = true,
        getItems = function()
            return Core.ORDER_ITEMS
        end,
        onChanged = function(a, b)
            local key = Core.dropdownValue(a, b)
            if key == "rarest" or key == "common" or key == "closest" or key == "kg" or key == "earn" or key == "price" then
                M.grabOrder = key
                if M.enabled ~= true then
                    emitIfChanged("Idle", "muted", M.idleDetail())
                end
            end
        end,
    })

    local actions = ui:CreateGroup(body)
    local speedInputApi
    local speedModeApi
    local lastSpeedCaption = nil

    local function parseSpeedMode(a, b)
        local key = Core.dropdownValue(a, b)
        key = string.lower(tostring(key or ""))
        if key == "manual" or key == "man" then
            return "manual"
        end
        if key == "auto" then
            return "auto"
        end
        return nil
    end

    local function setWidgetVisible(api, show)
        show = show == true
        if type(api) ~= "table" then
            return
        end
        if type(api.setVisible) == "function" then
            pcall(api.setVisible, show)
        end
        local root = api.root or api.row
        if typeof(root) == "Instance" then
            root.Visible = show
        end
    end

    local function usedSpeedNow()
        local n = select(1, resolveTravelSpeed(getMove()))
        n = tonumber(n) or 0
        return math.floor(n + 0.5)
    end

    local function refreshSpeedUi()
        local autoOn = speedMode() == "auto"
        setWidgetVisible(speedInputApi, autoOn ~= true)
        local caption = "Speed Mode"
        if autoOn == true then
            caption = "Speed Mode (speed " .. tostring(usedSpeedNow()) .. ")"
        end
        if caption ~= lastSpeedCaption then
            lastSpeedCaption = caption
            if speedModeApi and type(speedModeApi.setLabel) == "function" then
                pcall(speedModeApi.setLabel, caption)
            end
        end
    end

    local tpApproachApi
    local function refreshTpApproachUi()
        -- Instant mode: approach dropdown unused
        setWidgetVisible(tpApproachApi, false)
    end

    ui:CreateRowDropdown(actions, {
        id = "steal.wild.moveMode",
        label = "Move Mode",
        placeholder = "Glide",
        initial = M.moveMode or "glide",
        clearable = false,
        preserveItemOrder = true,
        getItems = function()
            return Core.MOVE_ITEMS
        end,
        onChanged = function(a, b)
            local key = tostring(Core.dropdownValue(a, b) or ""):lower()
            if key == "walk" then
                M.moveMode = "walk"
            elseif key == "teleport" or key == "instant" or key == "far" or key == "decoy" then
                M.moveMode = "teleport"
            elseif key == "glide" then
                M.moveMode = "glide"
            else
                return
            end
            local Move = getMove()
            if Move and type(Move.SetMode) == "function" then
                pcall(Move.SetMode, M.moveMode)
            end
            if Move and type(Move.SetSpeed) == "function" then
                pcall(Move.SetSpeed, M.moveSpeed)
            end
            refreshSpeedUi()
            refreshTpApproachUi()
        end,
    })

    local _, tpApproachApiRow = ui:CreateRowDropdown(actions, {
        id = "steal.wild.tpApproach",
        label = "Instant Move (unused)",
        placeholder = "Glide",
        initial = (M.tpApproach == "walk") and "walk" or "glide",
        clearable = false,
        preserveItemOrder = true,
        getItems = function()
            return Core.TP_APPROACH_ITEMS or {
                { key = "glide", name = "Glide" },
                { key = "walk", name = "Walk" },
            }
        end,
        onChanged = function(a, b)
            local key = Core.dropdownValue(a, b)
            if key == "walk" then
                M.tpApproach = "walk"
            else
                M.tpApproach = "glide"
            end
        end,
    })
    tpApproachApi = tpApproachApiRow
    refreshTpApproachUi()

    local _, speedModeApiRow = ui:CreateRowDropdown(actions, {
        id = "steal.wild.speedMode",
        label = "Speed Mode",
        placeholder = "Manual",
        initial = M.speedMode or "manual",
        clearable = false,
        preserveItemOrder = true,
        getItems = function()
            return Core.SPEED_MODE_ITEMS
        end,
        onChanged = function(a, b)
            local key = parseSpeedMode(a, b)
            if key == "manual" then
                M.speedMode = "manual"
            else
                M.speedMode = "auto"
            end
            refreshSpeedUi()
        end,
    })
    speedModeApi = speedModeApiRow

    local speedInputRow, _, _, speedInputApiRow = ui:CreateRowInput(actions, {
        id = "steal.wild.moveSpeed",
        label = "Move Speed (Rec 600-1000)",
        initial = tostring(M.moveSpeed or 600),
        clearOnFocus = false,
        onChanged = function(text)
            local n = tonumber(text)
            M.moveSpeed = math.clamp(math.floor(n or 600), 8, 5000)
            local Move = getMove()
            if Move and type(Move.SetSpeed) == "function" then
                pcall(Move.SetSpeed, M.moveSpeed)
            end
        end,
    })
    speedInputApi = speedInputApiRow
    if type(speedInputApi) == "table" and speedInputApi.row == nil then
        speedInputApi.row = speedInputRow
    elseif type(speedInputApi) ~= "table" and speedInputRow then
        speedInputApi = { row = speedInputRow, root = speedInputRow }
    end
    refreshSpeedUi()
    task.defer(refreshSpeedUi)

    local autoSpeedGen = (tonumber(M._autoSpeedGen) or 0) + 1
    M._autoSpeedGen = autoSpeedGen
    task.spawn(function()
        while M._autoSpeedGen == autoSpeedGen and GEN == G.__StealEggWildGen do
            refreshSpeedUi()
            task.wait(0.4)
        end
    end)

    ui:CreateRowToggle(actions, {
        id = "steal.wild.avoidTraps",
        label = "Avoid Traps",
        initial = M.avoidTraps == true,
        onChanged = function(on)
            M.avoidTraps = on == true
        end,
    })

    ui:CreateRowToggle(actions, {
        id = "steal.wild.avoidGuards",
        label = "Avoid Guards",
        initial = M.avoidGuards == true,
        onChanged = function(on)
            M.avoidGuards = on == true
        end,
    })

    ui:CreateRowToggle(actions, {
        id = "steal.wild.hitCarriers",
        label = "Hit Carriers",
        initial = M.hitCarriers == true,
        onChanged = function(on)
            M.hitCarriers = on == true
        end,
    })

    ui:CreateRowToggle(actions, {
        id = "steal.wild.autoTreadmill",
        label = "Auto Treadmill & Admin",
        persist = true,
        initial = M.autoTreadmill == true,
        onChanged = function(on)
            M.autoTreadmill = on == true
            if on ~= true then
                M._farmingBelt = false
            end
        end,
    })

    ui:CreateRowToggle(actions, {
        id = "steal.wild.enabled",
        label = "Enable Auto Steal",
        persist = true,
        initial = M.enabled == true,
        onChanged = function(on)
            M.setEnabled(on)
        end,
    })

    M.syncFrom(ui:GetValues())
    task.defer(function()
        if eggApi and type(eggApi.refreshItems) == "function" then
            pcall(eggApi.refreshItems)
        end
        if mutApi and type(mutApi.refreshItems) == "function" then
            pcall(mutApi.refreshItems)
        end
    end)
end

function M.Register(ui)
    M.RegisterSection(ui)
end


