        M = M,
        G = G,
        Core = Core,
        genAlive = function()
            return GEN == G.__StealEggWildGen
        end,
        dbg = dbg,
        distXZ = distXZ,
        emit = emit,
        ensureOffBelt = ensureOffBelt,
        findPrompt = findPrompt,
        fireStealPrompt = fireStealPrompt,
        getEggCmds = getEggCmds,
        getEggRecord = getEggRecord,
        getMove = getMove,
        getRoot = getRoot,
        isCarryingUid = isCarryingUid,
        isDead = isDead,
        loop = loop,
        nearestEgg = nearestEgg,
        recordActive = recordActive,
        recordIsDropped = recordIsDropped,
        recordPos = recordPos,
        requestCarry = requestCarry,
        resolveWorkspaceModel = resolveWorkspaceModel,
        stealMode = stealMode,
        stillHolding = stillHolding,
        worldPosition = worldPosition,
        xzNear = xzNear,
    }
    pcall(function()
        local I = G.StealEggInstant
        if type(I) == "table" and type(I.install) == "function" then
            I.install(G.StealEggInstantHooks)
        end
    end)
end

return M
 end,      required = true },
    -- Instant engine AFTER WildEgg (hooks). Luraph: features/instant_steal.lua
    { key = "Instant",   name = "Instant Steal", factory = function() -- Instant Steal — alur Max Earn (ImpulseContext + Forest + satu hop + setor).
-- WildEgg memanggil StealEggInstant. Kamera decoy on/off tetap milik Node.
-- Tidak hook Playback / tidak skip orig (itu hop 60s).

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Instant = {
    _ready = false,
    _ver = 21,
    camLock = false,
}

local function fail(why)
    if G.__StealEggMoveDebug == true or G.__StealEggFarDebug == true then
        pcall(print, "[StealEgg-Instant] " .. tostring(why))
    end
    return false
end

function Instant.isMode(mode)
    mode = tostring(mode or ""):lower()
    return mode == "teleport" or mode == "instant" or mode == "far" or mode == "decoy" or mode == "freeze"
end

function Instant.setCamLock(on)
    Instant.camLock = on == true
    G.__StealEggCamLock = Instant.camLock
    return Instant.camLock
end

function Instant.install(H)
    if type(H) ~= "table" or type(H.EGG) ~= "table" or type(H.M) ~= "table" then
        return fail("install: bad hooks")
    end
    local EGG = H.EGG
    local M = H.M
    local Core = H.Core or G.StealEggCore
    if type(Core) ~= "table" or type(Core.require) ~= "function" then
        return fail("missing Core")
    end
    local dbg = H.dbg
    local emit = H.emit
    local ensureOffBelt = H.ensureOffBelt
    local getEggCmds = H.getEggCmds
    local getEggRecord = H.getEggRecord
    local getRoot = H.getRoot
    local isCarryingUid = H.isCarryingUid
    local isDead = H.isDead
    local nearestEgg = H.nearestEgg
    local getMove = H.getMove
    local requestCarry = H.requestCarry
    local stealMode = H.stealMode
    local worldPosition = H.worldPosition
    local resolveWorkspaceModel = H.resolveWorkspaceModel
    local recordPos = H.recordPos
    local findPrompt = H.findPrompt
    local fireStealPrompt = H.fireStealPrompt
    local recordIsDropped = H.recordIsDropped
    if type(dbg) ~= "function" or type(emit) ~= "function" or type(getRoot) ~= "function"
        or type(isCarryingUid) ~= "function" or type(isDead) ~= "function"
        or type(requestCarry) ~= "function" or type(stealMode) ~= "function"
    then
        return fail("missing hook")
    end

    local CFG = {
        padPos = Vector3.new(515, 74, -363),
        forestPos = Vector3.new(597, 71, -317),
        planeY = 70.6,
        hopMax = 85,
        speedMult = 3.7,
        speedSafety = 0.85,
        speedMax = 5000,
        speedFloor = 60,
        travelGap = 0.06,
        windowLease = 20,
        guardTimeout = 2.2,
        guardOrbit = 1.8,
        hitRange = 2.0,
        selfStrike = true,
        strikeTries = 3,
        strikeWait = 0.35,
        ragdollMax = 4.0,
        carryBudget = 2.5,
        carryGap = 0.04,
        -- Diam di pad + Handoff. Jangan pin CFrame 7s (client di pad, server di egg).
        claimWait = 4.0,
        claimArrive = 8,
        -- Kalau server koreksi jauh dari pad, hop 85 ulang dari pos server.
        homeSalvage = 70,
        tpHomeWalk = false,
        tpHomeWalkMult = 3.7,
        regrabTries = 10,
        regrabWindow = 2.8,
        regrabRange = 800,
        regrabGap = 0.04,
        downedGrace = 3.0,
        guardSafe = 40,
        -- 0 = mati. Hop tambahan sambil gendong = jarak/tick naik = server drop.
        guardHop = 0,
        -- Filter area OFF (0). >0 = skip area yang guard-nya ≥ ratio × speed kita.
        guardBeatRatio = 0,
        hopCarry = 47,
    }
    EGG.padPos = CFG.padPos
    EGG.forestHint = CFG.forestPos
    EGG.farChainCount = math.clamp(math.floor(tonumber(EGG.farChainCount) or 3), 1, 3)
    EGG.guardTimeout = CFG.guardTimeout
    EGG.carryWindow = CFG.carryBudget
    EGG.carryGap = CFG.carryGap
    EGG.claimWait = CFG.claimWait
    EGG.claimArrive = CFG.claimArrive
    EGG.homeSalvage = CFG.homeSalvage
    EGG.sfCarryGap = EGG.carryGap
    EGG.sfFarCarryWindow = EGG.carryWindow
    EGG.sfClaimWait = EGG.claimWait
    EGG.dropRetry = math.max(1, math.floor(tonumber(EGG.dropRetry) or CFG.regrabTries))
    EGG.regrabRange = tonumber(EGG.regrabRange) or CFG.regrabRange
    EGG.regrabWindow = tonumber(EGG.regrabWindow) or CFG.regrabWindow

    local S = {}
    S._gcTried = G.__StealEggGcTried == true
    S.baitReady = false
    S.baitUid = nil
    S.touchedThisBatch = false
    S.preStageBusy = false
    S.stageForestBusy = false
    Instant.baitReady = false
    -- FPS meter ringan (EMA dt). Dipakai filter area: guard cepat vs FPS rendah.
    S.dtEma = 1 / 60
    pcall(function()
        if S.fpsConn then
            S.fpsConn:Disconnect()
        end
        S.fpsConn = RunService.Heartbeat:Connect(function(dt)
            if type(dt) == "number" and dt > 0 then
                S.dtEma = S.dtEma + (dt - S.dtEma) * 0.2
                G.__StealEggDtEma = S.dtEma
            end
        end)
    end)
    function Instant.fps()
        return 1 / math.max(S.dtEma, 0.001)
    end
    Instant._mobileLite = false
    G.__StealEggMobileLite = false
    dbg("FAR", "instant · max-earn ImpulseContext · cam " .. (Instant.camLock == true and "ON" or "OFF"))

    local function genAlive()
        if type(H.genAlive) == "function" then
            return H.genAlive() == true
        end
        return true
    end
    local function running(shouldRun)
        return type(shouldRun) ~= "function" or shouldRun() ~= false
    end
    local function isBaitUid(uid)
        return tostring(uid or ""):find("FirstAreaEgg_", 1, true) == 1
    end
    local function distXZ(a, b)
        if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then
            return math.huge
        end
        return ((a - b) * Vector3.new(1, 0, 1)).Magnitude
    end
    local function hopDestOk(from, dest)
        if typeof(dest) ~= "Vector3" or dest.X ~= dest.X then
            return false
        end
        if math.abs(dest.X) > 8000 or math.abs(dest.Z) > 8000 then
            return false
        end
        return true
    end
    local function onPlane(v)
        if typeof(v) ~= "Vector3" then
            return nil
        end
        return Vector3.new(v.X, CFG.planeY, v.Z)
    end
    local function padBase()
        -- Claim pad Forest/spawn, BUKAN SpawnPoint plot pribadi.
        return Vector3.new(515, 74, -363)
    end
    local function claimPadPos()
        if type(EGG.claimPadCFrame) == "function" then
            local ok, cf = pcall(EGG.claimPadCFrame)
            if ok and typeof(cf) == "CFrame" then
                local p = cf.Position
                if math.abs(p.X - 515) < 80 and math.abs(p.Z + 363) < 80 then
                    return Vector3.new(p.X, 74, p.Z)
            end
            end
        end
        return Vector3.new(515, 74, -363)
    end
    local function humanoid()
        local char = LP.Character
        return char and char:FindFirstChildOfClass("Humanoid") or nil
    end
    local function root()
        if type(getRoot) == "function" then
            local r = getRoot()
            if r then
                return r
            end
        end
        local c = LP.Character
        return c and c:FindFirstChild("HumanoidRootPart") or nil
    end

    Instant.camLock = false
    G.__StealEggCamLock = false
    local function camLockOn()
        if Instant.camLock == false or G.__StealEggCamLock == false then
            Instant.camLock = false
            G.__StealEggCamLock = false
            return false
        end
        return Instant.camLock == true or G.__StealEggCamLock == true
    end
    local hideParts = {}
    local hideConn = nil
    local camAnchor = nil
    local decoyModel = nil
    local decoyPinAt = 0
    local lastHideScan = 0
    local cachedHideList = {}
    local cachedHideChar = nil
    local camSubjCached = nil

    local function padCamPos()
        local p = padBase()
        return Vector3.new(p.X, p.Y, p.Z)
    end
    local function destroyCamProps()
        if hideConn then
            pcall(function()
                hideConn:Disconnect()
            end)
            hideConn = nil
        end
        for part, saved in pairs(hideParts) do
            pcall(function()
                if part.Parent and part:IsA("BasePart") then
                    part.LocalTransparencyModifier = 0
                    if type(saved) == "table" then
                        if saved.canCollide ~= nil then
                        part.CanCollide = saved.canCollide
                        end
                        if saved.canTouch ~= nil then
                            part.CanTouch = saved.canTouch
                        end
                        if saved.canQuery ~= nil then
                            part.CanQuery = saved.canQuery
                        end
                    end
                end
            end)
            hideParts[part] = nil
        end
        local char = LP.Character
        if char then
            for _, d in ipairs(char:GetDescendants()) do
                if d:IsA("BasePart") then
                    pcall(function()
                        d.LocalTransparencyModifier = 0
                    end)
                end
            end
        end
        if decoyModel and decoyModel.Parent then
            pcall(function()
                decoyModel:Destroy()
            end)
        end
        decoyModel = nil
        if camAnchor and camAnchor.Parent then
            pcall(function()
                camAnchor:Destroy()
            end)
        end
        camAnchor = nil
        pcall(function()
            local d = Workspace:FindFirstChild("__stealDecoy")
            if d then
                d:Destroy()
            end
            local a = Workspace:FindFirstChild("__camAnchor")
            if a then
                a:Destroy()
            end
        end)
    end
    local function ensureCamAnchor()
        local pos = padCamPos()
        local cf = CFrame.new(pos.X, pos.Y - 0.2, pos.Z)
        if camAnchor and camAnchor.Parent then
            camAnchor.CFrame = cf
            return camAnchor
        end
        local leftover = Workspace:FindFirstChild("__camAnchor")
        if leftover and leftover:IsA("BasePart") then
            camAnchor = leftover
            leftover.CFrame = cf
            return leftover
        end
        local anchor = Instance.new("Part")
        anchor.Name = "__camAnchor"
        anchor.Anchored = true
        anchor.CanCollide = false
        anchor.CanQuery = false
        anchor.CanTouch = false
        anchor.Transparency = 1
        anchor.Size = Vector3.new(2, 5, 2)
        anchor.CFrame = cf
        anchor.Parent = Workspace
        camAnchor = anchor
        return anchor
    end
    local function ensureDecoyShadow()
        local pos = padCamPos()
        local padCf = CFrame.new(pos)
        if decoyModel and decoyModel.Parent then
            local now = os.clock()
            if (now - decoyPinAt) > 0.8 then
                decoyPinAt = now
                pcall(function()
                    decoyModel:PivotTo(padCf)
                end)
            end
            return decoyModel.PrimaryPart
                or decoyModel:FindFirstChild("HumanoidRootPart")
                or ensureCamAnchor()
        end
        local model = Instance.new("Model")
        model.Name = "__stealDecoy"
        local hrp = Instance.new("Part")
        hrp.Name = "HumanoidRootPart"
        hrp.Size = Vector3.new(2, 2, 1)
        hrp.Transparency = 0.6
        hrp.Color = Color3.fromRGB(30, 30, 35)
        hrp.Material = Enum.Material.SmoothPlastic
        hrp.Anchored = true
        hrp.CanCollide = false
        hrp.CanTouch = false
        hrp.CanQuery = false
        hrp.CastShadow = false
        hrp.CFrame = padCf
        hrp.Parent = model
        local torso = Instance.new("Part")
        torso.Name = "Torso"
        torso.Size = Vector3.new(2, 2, 1)
        torso.Transparency = 0.65
        torso.Color = hrp.Color
        torso.Material = Enum.Material.SmoothPlastic
        torso.Anchored = true
        torso.CanCollide = false
        torso.CanTouch = false
        torso.CanQuery = false
        torso.CastShadow = false
        torso.CFrame = padCf * CFrame.new(0, 1.6, 0)
        torso.Parent = model
        local hum = Instance.new("Humanoid")
        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
        hum.WalkSpeed = 0
        hum.JumpPower = 0
        hum.Parent = model
        model.PrimaryPart = hrp
        model.Parent = Workspace
        decoyModel = model
        decoyPinAt = os.clock()
        return hrp
    end
    local function bodyParts(char)
        if cachedHideChar == char and #cachedHideList > 0 then
            return cachedHideList
        end
        cachedHideChar = char
        for i = #cachedHideList, 1, -1 do
            cachedHideList[i] = nil
        end
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA("BasePart") then
                cachedHideList[#cachedHideList + 1] = d
            end
        end
        return cachedHideList
    end
    local function applyPartHide(d, hrp)
        if not d or not d.Parent or not d:IsA("BasePart") then
            return
        end
        if hideParts[d] == nil then
            hideParts[d] = {
                canCollide = d.CanCollide,
                canTouch = d.CanTouch,
                canQuery = d.CanQuery,
            }
        end
        pcall(function()
            d.CanCollide = (d == hrp)
            d.LocalTransparencyModifier = 1
        end)
    end
    local function ensureHidden(force)
        if camLockOn() ~= true then
            return
        end
        if force ~= true and (os.clock() - lastHideScan) < 0.28 then
            return
        end
        lastHideScan = os.clock()
        local char = LP.Character
        if not char then
            return
        end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local list = bodyParts(char)
        for i = 1, #list do
            applyPartHide(list[i], hrp)
        end
    end
    function Instant.setAntiHit()
        G.__StealEggAntiHit = false
        return false
    end
    function Instant.pinCam()
        if camLockOn() ~= true then
            return
        end
        local cam = Workspace.CurrentCamera
        if not cam then
            return
        end
        local subj = camSubjCached
        if typeof(subj) ~= "Instance" or subj.Parent == nil then
            subj = ensureDecoyShadow()
            camSubjCached = subj
        end
        if cam.CameraSubject ~= subj or cam.CameraType ~= Enum.CameraType.Custom then
            pcall(function()
                cam.CameraType = Enum.CameraType.Custom
                if subj then
                    cam.CameraSubject = subj
                end
            end)
        end
    end
    local function startCamHide()
        if camLockOn() ~= true then
            G.__StealEggDecoyOn = false
            return
        end
        G.__StealEggDecoyOn = true
        camSubjCached = nil
        ensureCamAnchor()
        ensureDecoyShadow()
        ensureHidden(true)
        Instant.pinCam()
        if hideConn then
            return
        end
        local lastHideT, lastPinT = 0, 0
        hideConn = RunService.Heartbeat:Connect(function()
            if G.__StealEggDecoyOn ~= true and G.__StealEggFarOn ~= true then
                return
            end
            local now = os.clock()
            if (now - lastHideT) >= 0.28 then
                lastHideT = now
                ensureHidden(false)
            end
            if (now - lastPinT) >= 0.35 then
                lastPinT = now
                Instant.pinCam()
            end
        end)
    end
    local function stopCamHide()
        G.__StealEggDecoyOn = false
        camSubjCached = nil
        G.__StealEggAntiHit = false
        destroyCamProps()
    end
    function Instant.camFollow()
        if camLockOn() == true and (G.__StealEggDecoyOn == true or G.__StealEggFarOn == true) then
            Instant.pinCam()
            return
        end
        local cam = Workspace.CurrentCamera
        local hum = humanoid()
        if cam and hum then
            pcall(function()
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = hum
            end)
        end
    end

    -- Max Earn: ImpulseContext di record client. Playback native skip cek gerak,
    -- orig tetap jalan → tidak hop 60s.
    local function findRecord()
        local cached = S.rec
        if type(cached) == "table" then
            local ok, valid = pcall(function()
                return rawget(cached, "Evidence") ~= nil
            end)
            if ok and valid then
                return cached
            end
        end
        local cap = G.__StealEggAcRecord
        if type(cap) == "table" then
            local ok, valid = pcall(function()
                return rawget(cap, "Evidence") ~= nil
            end)
            if ok and valid then
                S.rec = cap
                return cap
            end
        end
        if S._gcTried == true then
            return S.rec
        end
        S._gcTried = true
        G.__StealEggGcTried = true
        -- Jangan getgc(true). Sapu heap = spike CPU beberapa detik. Record
        -- datang dari Playback stub → G.__StealEggAcRecord.
        return nil
    end
    local function writeWindow(rec)
        local now = os.clock()
        local r = root()
        local rag = 0
        if type(Instant.ragdollLeft) == "function" then
            local okR, n = pcall(Instant.ragdollLeft)
            if okR then
                rag = tonumber(n) or 0
            end
        end
        -- Saat ragdoll: Impulse HARUS tetap hidup. Early-return dulu = hop Forest→egg
        -- ditolak Playback, karakter kaku di 597.
        local origin = (r and r.Position) or Vector3.zero
        local hopFrom = G.__StealEggHopOrigin
        if typeof(hopFrom) == "Vector3" and r then
            if distXZ(r.Position, hopFrom) <= 28 then
                origin = hopFrom
            else
                G.__StealEggHopOrigin = nil
            end
        end
        rec.ImpulseContext = {
            Kind = "Impulse",
            StartedAt = now,
            ExpiresAt = now + math.max(CFG.windowLease, rag + 1.2),
            OriginPosition = origin,
            MaxHorizontalSpeed = 1e6,
            MaxVerticalSpeed = 1e6,
            MaxHorizontalDistance = 1e9,
            MaxUpwardDistance = 1e9,
            PreMovementSafeSample = rawget(rec, "LastValidatedGroundedSample")
                or rawget(rec, "LastObservedSample")
                or rawget(rec, "LastSample"),
        }
    end
    local function quietPlayback(rec)
        local r = root()
        if r == nil then
            return
        end
        local last = rawget(rec, "LastObservedSample")
        if type(last) ~= "table" then
            last = { Position = r.Position, CFrame = r.CFrame }
            pcall(function()
                rec.LastObservedSample = last
                rec.LastSample = last
            end)
        end
            pcall(function()
            last.Position = r.Position
            last.CFrame = r.CFrame
            if last.LinearVelocity ~= nil then
                last.LinearVelocity = Vector3.zero
            end
            if last.AssemblyLinearVelocity ~= nil then
                last.AssemblyLinearVelocity = Vector3.zero
            end
        end)
        -- Walk/glide: jangan CFrame ke TargetSample — itu rubber. MaxEarn
        -- cuma hapus koreksi. Teleport FAR tetap terima yank server.
        local cc = rawget(rec, "CorrectionContext")
        if type(cc) == "table" then
            local legs = G.__StealEggLegsWalk == true
            if legs ~= true then
                local w = G.StealEggWild
                local m = type(w) == "table" and string.lower(tostring(w.moveMode or "")) or ""
                legs = (m == "walk" or m == "glide")
                    and G.__StealEggFarOn ~= true
                    and G.__StealEggDecoyOn ~= true
            end
            if legs == true then
                pcall(function()
                    rec.CorrectionContext = nil
                end)
            else
                local ts = rawget(cc, "TargetSample")
                local tp = type(ts) == "table" and ts.Position or nil
                if typeof(tp) == "Vector3" then
                    local d = distXZ(r.Position, tp)
                    S.corrN = (tonumber(S.corrN) or 0) + 1
                    dbg("CORR", string.format("server koreksi #%d %s → %.0f,%.0f (Δ%.0f)",
                        S.corrN, tostring(rawget(cc, "Reason")), tp.X, tp.Z, d))
                    if d > 30 then
                        pcall(function()
                            r.CFrame = CFrame.new(tp.X, r.Position.Y, tp.Z)
                            r.AssemblyLinearVelocity = Vector3.zero
                            r.AssemblyAngularVelocity = Vector3.zero
                        end)
                        G.__StealEggServerCorrAt = os.clock()
                        G.__StealEggServerCorrPos = tp
                    end
                end
                pcall(function()
                    rec.CorrectionContext = nil
                end)
            end
        end
        if rawget(rec, "MovementMode") == "Correcting" then
        pcall(function()
                rec.MovementMode = "Trusted"
            end)
        end
        local ev = rawget(rec, "Evidence")
        if type(ev) == "table" and (tonumber(ev.Teleport) or 0) > 0 then
        pcall(function()
                ev.Teleport = 0
            end)
                    end
                end
    local function armWindow()
        if S.winConn then
            return true
        end
        -- Tunggu Playback nulis record (tanpa getgc). Reset spawn: 0.35s
        -- kalah race umpan. Record biasanya sudah ada; cap pendek.
        local tWait = os.clock()
        while (os.clock() - tWait) < 0.12 do
            if type(G.__StealEggAcRecord) == "table" or type(S.rec) == "table" then
                break
            end
            RunService.Heartbeat:Wait()
        end
        local rec = findRecord()
        if rec == nil then
            return false
        end
        writeWindow(rec)
        quietPlayback(rec)
        S.winConn = RunService.Heartbeat:Connect(function()
            local r = S.rec or G.__StealEggAcRecord
            if type(r) == "table" then
                S.rec = r
                writeWindow(r)
                quietPlayback(r)
            end
        end)
        dbg("WIN", "window kekebalan aktif")
        return true
    end
    local function disarmWindow()
        G.__StealEggLegsWalk = false
        if S.winConn then
            pcall(function()
                S.winConn:Disconnect()
            end)
            S.winConn = nil
        end
        if type(S.rec) == "table" then
            pcall(function()
                S.rec.ImpulseContext = nil
            end)
        end
    end
    function Instant.isWindow()
        return S.winConn ~= nil
    end
    function Instant.armMoveWindow()
        return armWindow() == true
    end
    -- Sama sisa setelah 1 steal teleport: HHT hidup + ImpulseContext, tanpa FarOn/Forest.
    function Instant.armMoveSession()
        if isDead() then
            return false
        end
        G.__StealEggHhtOff = false
        G.__StealEggMoveWin = true
        pcall(function()
            local sp = G.StealEggSpeed
            if type(sp) == "table" and type(sp.Arm) == "function" then
                sp.Arm()
            end
        end)
        local tWait = os.clock()
        while (os.clock() - tWait) < 0.45 do
            if type(G.__StealEggAcRecord) == "table" or type(S.rec) == "table" then
                break
            end
            RunService.Heartbeat:Wait()
        end
        return armWindow() == true
    end
    Instant.disarmWindow = disarmWindow

    local function hold(pos)
        local r = root()
        if r == nil or typeof(pos) ~= "Vector3" then
            return false
        end
        local from = r.Position
        local mag = Vector3.new(pos.X - from.X, 0, pos.Z - from.Z).Magnitude
        local rag = Instant.ragdollLeft() > 0.05
        -- Satu CFrame Forest→telur saat ragdoll. Mute Playback sampai mendarat.
        if rag and mag > 18 then
            G.__StealEggHopOrigin = from
            G.__StealEggInstantRagSnap = true
            local pulse = G.__StealEggPulseSnapMute
            if type(pulse) == "function" then
                pcall(pulse, 0.55)
            else
                G.__StealEggSnapMute = true
                G.__StealEggHhtSnapUntil = os.clock() + 0.55
            end
            task.delay(0.25, function()
                G.__StealEggInstantRagSnap = false
            end)
        end
        local h = humanoid()
        if h and h.Health > 0 then
            pcall(function()
                h.Sit = false
                h.Jump = false
                -- Jangan ChangeState(Running) saat ragdoll: memutus jendela FAR → mati.
                if Instant.ragdollLeft() > 0.05 then
                    return
                end
                h.PlatformStand = false
                h:Move(Vector3.zero, false)
                h:MoveTo(pos)
                h:ChangeState(Enum.HumanoidStateType.Running)
            end)
        end
        r.CFrame = CFrame.new(pos)
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
        Instant.camFollow()
                    return true
                end
    local function baseWalkSpeed()
        local h = humanoid()
        local live = h and tonumber(h.WalkSpeed) or nil
        if live and live > 0 then
            S.baseWs = live
        end
        return tonumber(S.baseWs) or live or 100
    end
    local function legalSpeed(mult)
        local v = baseWalkSpeed() * (tonumber(mult) or 1) * CFG.speedMult * CFG.speedSafety
        return math.clamp(v, CFG.speedFloor, CFG.speedMax)
    end
    local function carryMult()
        if type(S.carryState) == "table" and tonumber(S.carryState.SpeedMultiplier) then
            return tonumber(S.carryState.SpeedMultiplier)
        end
        if type(M._carry) == "table" and tonumber(M._carry.SpeedMultiplier) then
            return tonumber(M._carry.SpeedMultiplier)
        end
        return 1
    end
    local function carrySpeed()
        return legalSpeed(carryMult())
    end
    local function tpHomeSpeed()
        return math.clamp(baseWalkSpeed() * carryMult() * CFG.tpHomeWalkMult, 16, CFG.speedMax)
    end
    local function holdingLoot()
        local uid = tostring(S.grantUid or "")
        if uid ~= "" and not isBaitUid(uid) then
                        return true
                    end
        if type(isCarryingUid) == "function" and isCarryingUid() == true then
            local held = tostring(M._carry and M._carry.Uid or "")
            return held == "" or not isBaitUid(held)
        end
        return false
    end
    local function travelTo(dest, shouldRun, speed)
        dest = onPlane(dest)
        local r = root()
        if r == nil or dest == nil then
            return false
        end
        speed = tonumber(speed) or legalSpeed(1)
        local from = r.Position
        local total = distXZ(from, dest)
        local gap = CFG.travelGap
        -- Hop 85 sambil gendong = server drop. Cap 47 tanpa mute.
        local cap = tonumber(CFG.hopMax) or 85
        if holdingLoot() then
            cap = math.min(cap, tonumber(CFG.hopCarry) or 47)
        end
        -- 5 FPS: wait(gap 0.06) tetap 1 frame (~0.2s). speed×gap = hop 56 → 280 st/s (WS).
        -- Pakai dt nyata: hop = min(85, speed×dt) = 85 → ~425 st/s.
        local dtHop = tonumber(G.__StealEggDtEma) or gap
        if type(dtHop) ~= "number" or dtHop < gap then
            dtHop = gap
        end
        local step
        if Instant.ragdollLeft() > 0.12 then
            step = cap
        else
            step = math.max(4, math.min(cap, speed * dtHop))
        end
        local steerFn = type(M.steerPlot) == "function" and M.steerPlot or nil
        local function hopToward(nowPos)
            local p = dest
            if type(steerFn) == "function" then
                local okS, v = pcall(steerFn, nowPos, dest)
                if okS == true and typeof(v) == "Vector3" then
                    local to = Vector3.new(v.X - nowPos.X, 0, v.Z - nowPos.Z)
                    if to.Magnitude > 1 then
                        local u = to.Unit
                        local st = math.min(step, to.Magnitude)
                        local destFlat = Vector3.new(dest.X - nowPos.X, 0, dest.Z - nowPos.Z)
                        if destFlat.Magnitude > 1 then
                            destFlat = destFlat.Unit
                            local along = u:Dot(destFlat) * st
                            local latV = u * st - destFlat * along
                            if latV.Magnitude > 12 then
                                latV = latV.Unit * 12
                                local move = destFlat * st + latV
                                if move.Magnitude > 1 then
                                    u = move.Unit
                                end
                            end
                        end
                        p = Vector3.new(nowPos.X + u.X * st, CFG.planeY, nowPos.Z + u.Z * st)
                    end
                end
            else
                local to = Vector3.new(dest.X - nowPos.X, 0, dest.Z - nowPos.Z)
                if to.Magnitude > step then
                    local u = to.Unit
                    p = Vector3.new(nowPos.X + u.X * step, CFG.planeY, nowPos.Z + u.Z * step)
                end
            end
            return Vector3.new(p.X, CFG.planeY, p.Z)
        end
        if total <= step then
            hold(hopToward(from))
                return true
            end
        local hops = math.ceil(total / step)
        for i = 1, hops do
            if running(shouldRun) ~= true or isDead() then
                return false
            end
            local now = root()
            if now == nil then
                return false
            end
            hold(hopToward(now.Position))
            task.wait(gap)
        end
        local last = root()
        if last then
            hold(hopToward(last.Position))
        else
            hold(dest)
        end
        return true
    end

    local function goSteer(dest, shouldRun, reason, speed, dodgeUid, glideOnly)
        if typeof(dest) ~= "Vector3" then
            return false
        end
        dest = onPlane(dest) or dest
        -- Glide lawan ragdoll = freeze 3–5s. Bait Forest jangan dipaksa.
        if reason ~= "home" and Instant.ragdollLeft() > 0.05 then
            local rRag = root()
            return rRag ~= nil and distXZ(rRag.Position, dest) <= 18
        end
        local Move = type(getMove) == "function" and getMove() or G.StealEggMove
        speed = tonumber(speed) or legalSpeed(1)
        local ok
        if type(Move) == "table" and type(Move.GoTo) == "function" then
            pcall(function()
                Move.SetMode("glide")
                -- JANGAN Move.SetSpeed: itu menimpa angka Manual UI (M.speed),
                -- lalu WantWalkSpeed membaca 800/600, bukan 300 milik user (live).
                ok = Move.GoTo(CFrame.new(dest.X, dest.Y, dest.Z), {
                    mode = "glide",
                    uiMode = stealMode(),
                    speed = speed,
                    nativeWalkSpeed = true,
                    lockGlideSpeed = true,
                    reason = tostring(reason or "move"),
                    shouldRun = shouldRun,
                    steer = type(M.steerPlot) == "function" and M.steerPlot or nil,
                    skipRubberWait = true,
                    skipLandWait = true,
                    skipStall = true,
                    skipIntegrity = true,
                    -- forest-wait: timer sudah habis, state masih jatuh. Tanpa ini
                    -- glide skip tiap frame sampai timeout 8s (freeze di pad).
                    throughRagdoll = reason == "home" or reason == "forest-wait" or G.__StealEggClaiming == true,
                    arrive = reason == "home" and 8 or (reason == "forest-wait" and 10 or 12),
                    onTick = function()
                        if dodgeUid ~= nil and type(Instant.guardDodge) == "function" then
                            Instant.guardDodge(dodgeUid, dest)
                        end
                        Instant.camFollow()
                    end,
                })
            end)
        end
        -- forest-wait: jangan kunci TpHold. Pulang ke guard harus bisa jalan.
        if reason ~= "forest-wait" then
            G.__StealEggTpHold = true
            G.__StealEggMoveQuiet = true
        else
            G.__StealEggTpHold = false
            G.__StealEggMoveQuiet = false
        end
        if ok == true then
            return true
        end
        -- Prep reset: jangan fallback hop CFrame — itu yang gampang mati di Guard.
        if glideOnly == true then
            local h = humanoid()
            local r2 = root()
            if h and r2 then
                pcall(function()
                    h.Sit = false
                    h:MoveTo(Vector3.new(dest.X, dest.Y, dest.Z))
                end)
                local t0 = os.clock()
                while running(shouldRun) == true and (os.clock() - t0) < 6 do
                    if Instant.ragdollLeft() > 0.05 then
                return true
            end
                    r2 = root()
                    if r2 and distXZ(r2.Position, dest) <= 12 then
                return true
            end
                    task.wait(0.08)
                end
            end
            r2 = root()
            return r2 ~= nil and distXZ(r2.Position, dest) <= 16
        end
        if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
            return travelTo(dest, shouldRun, speed)
        end
        local r = root()
        return r ~= nil and distXZ(r.Position, dest) <= (tonumber(EGG.homeSalvage) or 40)
    end

    function Instant.ragdollLeft()
        local rt = LP:GetAttribute("RagdollEndTime")
        if type(rt) == "number" then
            local left = rt - Workspace:GetServerTimeNow()
            if left > 0 then
                return left
            end
        end
        local h = humanoid()
        if h and h:GetState() == Enum.HumanoidStateType.Physics then
            return 0.25
        end
        return 0
    end

    local function areaGuard(areaId)
        areaId = tostring(areaId or "")
        if areaId == "" then
            return nil
        end
        local function from(root)
            local areas = root and root:FindFirstChild("Areas")
            local zones = areas and areas:FindFirstChild("GuardAreas")
            local zone = zones and zones:FindFirstChild(areaId)
            if zone == nil then
                return nil
            end
            return zone:FindFirstChild("Guard") or zone:FindFirstChild("ForestGuardStaging")
        end
        return from(Workspace:FindFirstChild("World"))
            or from(Workspace:FindFirstChild("__OBJECTS"))
    end
    local function guardRootOf(areaId)
        local guard = areaGuard(areaId)
        if guard == nil then
            return nil
        end
        return guard:FindFirstChild("HumanoidRootPart")
            or guard:FindFirstChild("Collider")
            or guard.PrimaryPart
    end

    -- Guard target (server-side) kejar: WS × (1 + (d/20 − 1) × 0.5), maks 4×.
    -- Kena kalau XZ ≤ HitDistance (4–7). Kalau jaraknya menyusut < guardSafe,
    -- hop 100 st (time-based, tidak tergantung FPS) menjauh + ke arah pad.
    function Instant.guardDodge(uid, dest)
        uid = tostring(uid or "")
        if (tonumber(CFG.guardHop) or 0) <= 0 then
            return false
        end
        if uid == "" or isCarryingUid() ~= true then
            return false
        end
        local now = os.clock()
        if (now - (tonumber(S.dodgeAt) or 0)) < 0.25 then
            return false
        end
        local areaId = S.carryState and S.carryState.AreaId
        if areaId == nil and type(M._carry) == "table" then
            areaId = M._carry.AreaId
        end
        if areaId == nil and type(getEggRecord) == "function" then
            local rec = getEggRecord(uid)
            areaId = type(rec) == "table" and (rec.AreaId or rec.areaId) or nil
        end
        if areaId == nil or tostring(areaId) == "Forest" then
            return false
        end
        local guard = areaGuard(areaId)
        if guard == nil or guard:GetAttribute("GuardState") ~= "Chasing" then
            return false
        end
        local groot = guardRootOf(areaId)
        local r = root()
        if groot == nil or r == nil then
            return false
        end
        local d = distXZ(r.Position, groot.Position)
        if d > CFG.guardSafe then
            return false
        end
        S.dodgeAt = now
        local away = Vector3.new(r.Position.X - groot.Position.X, 0, r.Position.Z - groot.Position.Z)
        if away.Magnitude < 0.5 then
            away = Vector3.new(1, 0, 0)
        else
            away = away.Unit
        end
        local dir = away
        if typeof(dest) == "Vector3" then
            local toPad = Vector3.new(dest.X - r.Position.X, 0, dest.Z - r.Position.Z)
            if toPad.Magnitude > 1 then
                toPad = toPad.Unit
                -- Pad di belakang guard: menyamping dulu, jangan tabrak guard.
                if toPad:Dot(away) >= -0.2 then
                    dir = (toPad + away * 0.6).Unit
                    end
                end
            end
        local hop = CFG.guardHop
        local p = r.Position + dir * hop
        hold(Vector3.new(p.X, r.Position.Y, p.Z))
        dbg("DODGE", string.format("%s guard %.0fst · hop %.0f", tostring(areaId), d, hop))
        return true
    end

    function Instant.forestGuardRoot()
        local guard = areaGuard("Forest")
        if guard == nil then
                return nil
            end
            return guard:FindFirstChild("HumanoidRootPart")
                or guard:FindFirstChild("Collider")
                or guard:FindFirstChildWhichIsA("BasePart", true)
    end
    local function fireForestStrike(uid, guardCF)
        uid = tostring(uid or "")
        if uid == "" or typeof(guardCF) ~= "CFrame" then
            return false
        end
        local re = S._strikeRe
        if re == nil then
            local net = ReplicatedStorage:FindFirstChild("Packages")
            net = net and net:FindFirstChild("Networking")
            if net then
                re = net:FindFirstChild("RE/GuardPatrol/ForestStrike")
            end
            S._strikeRe = re or false
        end
        if not re then
            return false
        end
        return pcall(function()
            re:FireServer({ EggUid = uid, GuardCFrame = guardCF })
        end)
    end
    -- Zip pack: nest Slot terdekat. Dropped = cadangan (harus kepegang dulu).
    local function baitRecState(uid)
        if type(getEggRecord) ~= "function" then
            return "Slot"
        end
        local rec = getEggRecord(uid)
        if type(rec) ~= "table" then
            return "Slot"
        end
        return tostring(rec.State or "Slot")
    end
    local function findForestBait(near, maxDist)
        maxDist = tonumber(maxDist) or 60
        near = typeof(near) == "Vector3" and near or CFG.forestPos
        local held = tostring(M._carry and M._carry.Uid or "")
        if held:find("FirstAreaEgg_", 1, true) == 1 and isCarryingUid(held) == true then
            local pos = near
            if type(getEggRecord) == "function" then
                local rec = getEggRecord(held)
                if type(rec) == "table" then
                    local rp = rec.WorldPosition or rec.Position
                    if typeof(rp) == "Vector3" then
                        pos = rp
                    end
                end
            end
            return { uid = held, pos = pos }
        end
        local slotBest, slotD, anyBest, anyD = nil, maxDist + 1, nil, maxDist + 1
        local function consider(uid, pos)
            uid = tostring(uid or "")
            if uid == "" or typeof(pos) ~= "Vector3" then
                return
            end
            local d = (near - pos).Magnitude
            if d >= anyD and d >= slotD then
                return
            end
            local st = baitRecState(uid)
            if st == "Slot" and d < slotD then
                slotD, slotBest = d, { uid = uid, pos = pos }
            end
            if d < anyD then
                anyD, anyBest = d, { uid = uid, pos = pos }
            end
        end
        if type(EGG.pickForestNear) == "function" then
            local snap = EGG.pickForestNear(near, maxDist)
            if type(snap) == "table" and snap.uid then
                consider(snap.uid, snap.pos or near)
            end
        end
        local folder = Workspace:FindFirstChild("AreaEggSlotsClient")
        for _, inst in ipairs((folder or Workspace):GetChildren()) do
            local nm = inst.Name
            if type(nm) == "string"
                and nm:find("FirstAreaEgg_", 1, true) == 1
                and nm:find("Forest", 1, true)
            then
            local pos
            if inst:IsA("Model") then
                local ok, cf = pcall(function()
                    return inst:GetPivot()
                end)
                    pos = (ok and typeof(cf) == "CFrame") and cf.Position or nil
            elseif inst:IsA("BasePart") then
                pos = inst.Position
            end
                consider(nm, pos)
            end
        end
        return slotBest or anyBest
    end
    local function carryBait(uid)
        uid = tostring(uid or "")
        if uid == "" then
            return false
        end
        if isCarryingUid(uid) == true then
            return true
        end
        local rec = type(getEggRecord) == "function" and getEggRecord(uid) or nil
        local ok, a = pcall(requestCarry, uid, rec)
            if ok and a == true then
            return true
        end
        if ok and type(a) == "string" and string.find(a, "Already carrying", 1, true) then
            return isCarryingUid() == true
        end
        return false
    end
    local function emptyHands(why)
        dbg("DROP", tostring(why or "?"))
        pcall(function()
            local cmds = type(getEggCmds) == "function" and getEggCmds() or nil
            if type(cmds) == "table" and type(cmds.DropFieldEgg) == "function" then
                cmds.DropFieldEgg("PlayerRequest")
            end
        end)
        pcall(function()
        local es = Core.require("Client.EggState")
            if type(es) == "table" and type(es.DropFieldEgg) == "function" then
                es.DropFieldEgg("PlayerRequest")
            end
        end)
    end

    local function forestStand()
        local dest = CFG.forestPos
        local g = Instant.forestGuardRoot()
        local gpos = (g and g.Position) or dest
        local pad = CFG.padPos
        local away = Vector3.new(pad.X - gpos.X, 0, pad.Z - gpos.Z)
        if away.Magnitude < 1 then
            away = Vector3.new(-1, 0, 0)
        else
            away = away.Unit
        end
        -- Collider Forest 5×5 (setengah 2.5). Jangan stand di forestPos —
        -- itu pusat Guard, hop 85 ke situ = mati.
        return Vector3.new(gpos.X + away.X * 7, gpos.Y + 0.2, gpos.Z + away.Z * 7)
    end

    local function resetWallOpen()
        if G.__StealEggResetGo == true then
            return true
        end
        local ok, sealed
        pcall(function()
            local mod = Core.require("Client.AreaEggResetWall")
            if type(mod) == "table" and type(mod.IsSealed) == "function" then
                ok, sealed = pcall(mod.IsSealed)
            end
        end)
        if ok == true then
            return sealed ~= true
        end
            return true
        end

    -- Timer ragdoll sudah 0, tapi Humanoid masih Freefall/Ragdoll/Physics.
    -- Glide forest-wait menganggap itu airborne dan tidak melangkah sampai
    -- timeout minimal 8s. Itu freeze di pad setelah claim 1–2.
    local function wakeLegs()
        local rt = LP:GetAttribute("RagdollEndTime")
        if type(rt) == "number" and (rt - Workspace:GetServerTimeNow()) > 0.05 then
            return
        end
        local h = humanoid()
        local r = root()
        if h == nil then
            return
        end
        pcall(function()
            h.PlatformStand = false
            h.Sit = false
            local st = h:GetState()
            if st == Enum.HumanoidStateType.Physics
                or st == Enum.HumanoidStateType.Freefall
                or st == Enum.HumanoidStateType.FallingDown
                or st == Enum.HumanoidStateType.Ragdoll
                or st == Enum.HumanoidStateType.Flying
            then
                h:ChangeState(Enum.HumanoidStateType.Running)
            end
            if r then
                r.Anchored = false
            end
            if (tonumber(h.WalkSpeed) or 0) < 8 then
                h.WalkSpeed = tonumber(S.baseWs) or 16
            end
        end)
    end

    local function plantOnGuard()
        local stand = forestStand()
        local r = root()
        if r and distXZ(r.Position, stand) > 12 then
            wakeLegs()
            goSteer(stand, nil, "forest-wait", Instant.uiSpeed(), nil, true)
        end
        return Instant.forestGuardRoot()
    end

    local function retreatThenDrop(why)
        local rNow = root()
        if rNow then
            local pad = CFG.padPos
            local dir = Vector3.new(pad.X - rNow.Position.X, 0, pad.Z - rNow.Position.Z)
            if dir.Magnitude > 1 then
                dir = dir.Unit
                hold(Vector3.new(rNow.Position.X + dir.X * 40, rNow.Position.Y, rNow.Position.Z + dir.Z * 40))
                task.wait(0.08)
            end
        end
        if isCarryingUid() then
            emptyHands(why or "umpan gagal")
        end
        S.baitReady = false
        Instant.baitReady = false
        S.baitUid = nil
    end

    -- Glide ke tepi Guard (7st). Jangan hop/CFrame — gampang mendarat di collider.
    function Instant.stageForest(shouldRun)
        if isDead() then
            return false
        end
        local stand = forestStand()
        local r = root()
        if S.stageForestBusy == true then
            return r ~= nil and distXZ(r.Position, stand) <= 18
        end
        Instant.preArm()
        if Instant.ragdollLeft() > 0.05 then
            return true
        end
        if type(ensureOffBelt) == "function" then
            if ensureOffBelt(shouldRun) ~= true then
                emit("Belt", "warn", "stuck")
                return false
            end
        end
        r = root()
        if r == nil then
                return false
            end
        local dest = stand
        local why = "prep"
        if resetWallOpen() ~= true and distXZ(r.Position, stand) > 28 then
            dest = onPlane(claimPadPos()) or claimPadPos()
            why = "wait gate"
        end
        if distXZ(r.Position, dest) <= 12 then
            emit("Guard", "live", why)
            return Instant.ragdollLeft() > 0.12 or true
        end
        -- 5fps hop 85 ke stand 7st = masuk collider 5×5. Dekat: satu CFrame ke tepi.
        if distXZ(r.Position, dest) <= 48 then
            hold(dest)
            emit("Guard", "live", why)
            return Instant.ragdollLeft() > 0.12 or true
        end
        S.stageForestBusy = true
        emit("Guard", "live", why)
        wakeLegs()
        local ok = goSteer(dest, shouldRun, "forest-wait", Instant.uiSpeed(), nil, true)
        S.stageForestBusy = false
        return Instant.ragdollLeft() > 0.12 or ok == true
    end

    function Instant.preStage(shouldRun)
        if isDead() then
            return false
        end
        if Instant.ragdollLeft() > 0.05 then
            S.touchedThisBatch = true
            -- Jangan baitReady palsu: itu nahan di Forest tanpa hop.
            return true
        end
        if S.preStageBusy == true then
            return S.baitReady == true
        end
        local dest = CFG.forestPos
        local r = root()
        local held = tostring(M._carry and M._carry.Uid or "")
        if S.baitReady == true and isBaitUid(held) and isCarryingUid(held)
            and r and distXZ(r.Position, dest) < 48 then
            Instant.preArm()
            Instant.baitReady = true
            return true
        end
        -- Wall masih hitung: cuma siap di tepi, jangan TP/ambil bait.
        if resetWallOpen() ~= true then
            return Instant.stageForest(shouldRun) == true
        end
        S.preStageBusy = true
        Instant.preArm()
        if Instant.stageForest(shouldRun) ~= true then
            S.preStageBusy = false
            return false
        end
        r = root()
        local baitOk = false
        if r == nil then
            S.preStageBusy = false
                return false
            end
        local bait = findForestBait(dest, 80)
        if bait and isBaitUid(bait.uid) then
            emit("Guard", "live", "bait")
            S.baitUid = bait.uid
            -- Jangan gendong + nempel HRP di sini. Carry yang nunggu server
            -- sambil di dalam HitDistance = telur ke-4 mati.
            baitOk = true
        end
        S.baitReady = baitOk
        Instant.baitReady = baitOk
        dbg("TOUCH", string.format("preStage umpan=%s", tostring(baitOk and S.baitUid or "tidak ada")))
        S.preStageBusy = false
        return baitOk
    end

    local function raceStrike(shouldRun)
        if Instant.ragdollLeft() > 0.15 then
            return true
        end
        local dest = CFG.forestPos
        local bait = findForestBait(dest, 80)
        local baitUid = tostring(S.baitUid or "")
        if not isBaitUid(baitUid) then
            baitUid = bait and tostring(bait.uid or "") or ""
        end
        if not isBaitUid(baitUid) then
            return false, "umpan tidak kena"
        end
        S.baitUid = baitUid
        emit("Guard", "live", "bait")
        -- Max Earn: gendong di samping telur (+2.2), bukan di pusat HRP guard.
        local stand = (bait and typeof(bait.pos) == "Vector3") and (bait.pos + Vector3.new(2.2, 0, 2.2))
            or (dest + Vector3.new(1, 0, 1))
        local baitOk = isCarryingUid(baitUid) == true
        if baitOk ~= true then
            for _ = 1, 4 do
                if running(shouldRun) ~= true then
                    return false, "berhenti saat umpan"
                end
                hold(stand)
                task.wait(0.04)
                if carryBait(baitUid) or isCarryingUid(baitUid) then
                    baitOk = true
                    break
                end
                task.wait(0.06)
            end
        end
        if baitOk ~= true then
            return false, "umpan tidak kena"
        end
        S.baitReady = true
        Instant.baitReady = true
        emit("Guard", "live", "hit")
        if CFG.selfStrike then
            local tries = tonumber(CFG.strikeTries) or 3
            local waitS = tonumber(CFG.strikeWait) or 0.35
            for _ = 1, tries do
                if running(shouldRun) ~= true then
                    return false, "berhenti saat lapor pukulan"
                end
                local g = Instant.forestGuardRoot()
                if g then
                    fireForestStrike(baitUid, g.CFrame)
                end
                local tS = os.clock()
                while (os.clock() - tS) < waitS do
                    if Instant.ragdollLeft() > 0 or isDead() then
                break
                    end
                    RunService.Heartbeat:Wait()
            end
            if Instant.ragdollLeft() > 0 then
                break
            end
            end
        end
        local t0 = os.clock()
        local orbitAt = 0
        local timeout = tonumber(CFG.guardTimeout) or 2.2
        while Instant.ragdollLeft() <= 0 and (os.clock() - t0) < timeout do
            if running(shouldRun) ~= true then
                return false, "berhenti saat menunggu pukulan"
            end
            if isDead() then
                return false, "mati saat menunggu pukulan"
            end
            local g = Instant.forestGuardRoot()
            if g and (os.clock() - orbitAt) > 0.06 then
                orbitAt = os.clock()
                hold(g.Position + Vector3.new(0.55, 0.35, 0.55))
            end
            RunService.Heartbeat:Wait()
        end
        if isCarryingUid(baitUid) then
            emptyHands("umpan masih menempel")
        end
        if Instant.ragdollLeft() <= 0 then
            dbg("TOUCH", string.format("kena=false dt=%.2f", os.clock() - t0))
            return false, "penjaga tidak memukul"
        end
        local tA = os.clock()
        while (os.clock() - tA) < 0.5 do
            if Instant.ragdollLeft() > 0.05 or isDead() then
                break
            end
            RunService.Heartbeat:Wait()
        end
        if isDead() then
            return false, "mati saat menunggu pukulan"
        end
        dbg("TOUCH", string.format("kena=true dt=%.2f", os.clock() - tA))
        return true
    end

    local function softTouch(shouldRun)
        if Instant.ragdollLeft() > 0 then
            return true
        end
        Instant.preStage(shouldRun)
        return raceStrike(shouldRun)
    end

    local function askCarry(uid)
        uid = tostring(uid or "")
        local carryOk, carryErr
        pcall(function()
            carryOk, carryErr = requestCarry(uid, type(getEggRecord) == "function" and getEggRecord(uid) or nil)
        end)
        if carryOk == true then
            return true
        end
        local err = tostring(carryErr or "denied")
        if string.find(err, "Already carrying", 1, true) then
            return true
        end
        return false, err
    end

    local function eggWorldPos(uid)
        uid = tostring(uid or "")
        local model
        if type(resolveWorkspaceModel) == "function" then
            model = resolveWorkspaceModel(uid)
        end
        local pos
        if type(worldPosition) == "function" then
            pos = worldPosition(model)
        end
        if typeof(pos) ~= "Vector3" and type(recordPos) == "function" then
            pos = recordPos(type(getEggRecord) == "function" and getEggRecord(uid) or nil)
        end
        return pos
    end

    local function eggIsDropped(uid)
        uid = tostring(uid or "")
        local rec = type(getEggRecord) == "function" and getEggRecord(uid) or nil
        if type(recordIsDropped) == "function" then
            return recordIsDropped(rec) == true
        end
        return type(rec) == "table" and (rec.State == "Dropped")
    end

    -- Telur masih di slot/drop, atau kita yang bawa. Player lain gendong = taken.
    local function eggStillFree(uid)
        uid = tostring(uid or "")
        if uid == "" then
            return false
        end
        if type(isCarryingUid) == "function" and isCarryingUid(uid) == true then
            return true
        end
        local rec = type(getEggRecord) == "function" and getEggRecord(uid) or nil
        if type(rec) ~= "table" then
            return false
        end
        local st = tostring(rec.State or "")
        local cid = tonumber(rec.CarrierUserId)
        if st == "Carried" and cid and cid ~= 0 and cid ~= (LP and LP.UserId) then
            return false
        end
        if eggIsDropped(uid) then
            return true
        end
        if st == "Carried" then
            return cid == nil or cid == 0 or cid == (LP and LP.UserId)
        end
        return true
    end

    local function carryErrTaken(err)
        local msg = string.lower(tostring(err or ""))
        if msg == "" then
            return false
        end
        if string.find(msg, "already carrying", 1, true) then
            return false
        end
        return string.find(msg, "carried", 1, true) ~= nil
            or string.find(msg, "taken", 1, true) ~= nil
            or string.find(msg, "missing", 1, true) ~= nil
            or string.find(msg, "not found", 1, true) ~= nil
            or string.find(msg, "no longer", 1, true) ~= nil
            or string.find(msg, "doesn't exist", 1, true) ~= nil
            or string.find(msg, "does not exist", 1, true) ~= nil
    end

    local function replicaCarry()
        if type(S.carryState) == "table" then
            return S.carryState
        end
        local es
        pcall(function()
            es = Core.require("Client.EggState")
        end)
        if type(es) ~= "table" then
            return nil
        end
        for _, key in ipairs({ "GetCarry", "GetCarryState", "Get" }) do
            local fn = es[key]
            if type(fn) == "function" then
                local ok, st = pcall(fn, es)
                if ok and type(st) == "table" and (st.IsCarrying ~= nil or st.Uid ~= nil) then
                    return st
                end
            end
        end
        local raw = rawget(es, "Carry") or rawget(es, "Carrying") or rawget(es, "CarryState")
        if type(raw) == "table" then
            return raw
        end
        return nil
    end
    local function serverCarrying(uid)
        local st = replicaCarry()
        if type(st) ~= "table" or st.IsCarrying ~= true then
            return false
        end
        if uid == nil or tostring(uid) == "" then
            return true
        end
        return tostring(st.Uid or "") == tostring(uid)
    end
    local function waitServerCarry(uid, timeout)
        local limit = tonumber(timeout) or 0.35
        local t0 = os.clock()
        while (os.clock() - t0) < limit do
            if serverCarrying(uid) then
                return true
            end
            RunService.Heartbeat:Wait()
        end
        return serverCarrying(uid)
    end
    local function stillHasEgg(uid)
        uid = tostring(uid or "")
        if eggIsDropped(uid) then
            if tostring(S.grantUid or "") == uid then
                S.grantUid = nil
            end
            return false
        end
        if serverCarrying(uid) then
            return true
        end
        if type(isCarryingUid) == "function" and isCarryingUid(uid) == true then
            return true
        end
        if uid ~= "" and tostring(S.grantUid or "") == uid then
            return true
        end
                return false
            end
    local function hopToEgg(pos, shouldRun)
        local dest = onPlane(pos) or pos
        if typeof(dest) ~= "Vector3" then
                return false
            end
        local r = root()
        if r == nil then
            return false
        end
        local dist = distXZ(r.Position, dest)
        local near = tonumber(EGG.arrive) or 1.2
        if dist <= near then
                return true
            end
        local cap = tonumber(CFG.hopMax) or 85
        -- Ragdoll + tangan kosong: satu CFrame, lalu pin lagi kalau terlempar.
        if Instant.ragdollLeft() > 0.12 and holdingLoot() ~= true and dist > cap then
            return hold(dest)
        end
        if dist > cap then
            return travelTo(dest, shouldRun, Instant.uiSpeed()) == true
        end
        return hold(dest)
    end

    -- Telur terlepas di perjalanan: ambil di tempat drop. Jangan Forest / jangan pad.
    local function pickupDropped(uid, shouldRun)
        uid = tostring(uid or "")
        if uid == "" or isBaitUid(uid) then
            return false
        end
        M._preferUid = uid
        if stillHasEgg(uid) then
            return true
        end
        local r = root()
        if r == nil then
            return false
        end
        local pos = eggWorldPos(uid)
        local tFind = os.clock()
        while typeof(pos) ~= "Vector3" and (os.clock() - tFind) < 0.55 do
            if running(shouldRun) ~= true or isDead() then
            return false
        end
            RunService.Heartbeat:Wait()
            pos = eggWorldPos(uid)
        end
        if typeof(pos) ~= "Vector3" then
            dbg("REGRAB", "telur tidak ketemu uid=" .. uid:sub(1, 12))
            return false
        end
        local d = distXZ(r.Position, pos)
        dbg("REGRAB", string.format("ambil lagi uid=%s jarak %.0f", uid:sub(1, 12), d))
        emit("Steal", "live", "regrab")
        local dest = onPlane(pos) or pos
        hopToEgg(dest, shouldRun)
        local tries = math.max(1, math.floor(tonumber(EGG.dropRetry) or CFG.regrabTries))
        local win = tonumber(EGG.regrabWindow) or CFG.regrabWindow
        local cap = win + (tonumber(CFG.downedGrace) or 3)
        local t0 = os.clock()
        local n = 0
        local downed = 0
        while n < tries or (os.clock() - t0) < win do
            if running(shouldRun) ~= true or isDead() then
            return false
        end
            if stillHasEgg(uid) then
                dbg("REGRAB", "hasil true")
                return true
            end
            if (os.clock() - t0) >= cap then
                break
            end
            local p2 = eggWorldPos(uid)
            if typeof(p2) == "Vector3" then
                dest = onPlane(p2) or p2
                hopToEgg(dest, shouldRun)
            end
            if type(fireStealPrompt) == "function" then
                local model = type(resolveWorkspaceModel) == "function" and resolveWorkspaceModel(uid) or nil
                fireStealPrompt(type(findPrompt) == "function" and findPrompt(model, dest) or nil)
            end
            local got, err = askCarry(uid)
            n += 1
            if got then
                S.grantUid = uid
                if waitServerCarry(uid, 0.12) or stillHasEgg(uid) then
                    dbg("REGRAB", "hasil true")
            return true
        end
                dbg("REGRAB", "hasil true")
                return true
            elseif string.find(tostring(err or ""), "knocked down", 1, true) then
                downed += 1
                win = math.min(cap, math.max(win, (os.clock() - t0) + 0.45))
            end
            task.wait(tonumber(CFG.regrabGap) or CFG.carryGap)
        end
        local got = stillHasEgg(uid)
        dbg("REGRAB", string.format("hasil %s n=%d downed=%d", tostring(got), n, downed))
        return got
    end

    -- Claim plot = server. FieldEggRedeemVerdict datang sendiri kalau gendong
    -- sampai di pad. ForestHandoff Deposited itu guard naruh telur ke sarang,
    -- bukan setor pemain. Fire itu = "returned to its nest".
    function Instant.askForestHandoff(_uid)
        return false
    end

    local function stealOne(egg, shouldRun, retarget)
        local dest = onPlane(egg.pos) or egg.pos
        -- Retarget: telur ini sudah diambil pemain lain. Langsung ke telur
        -- rule berikutnya, jangan balik ke guard Forest.
        if retarget ~= true then
            if Instant.ragdollLeft() <= 0.15 then
                local touched, why = softTouch(shouldRun)
                if not touched then
                    return false, why
                end
                S.touchedThisBatch = true
            else
                S.touchedThisBatch = true
            end
            if Instant.ragdollLeft() <= 0.05 then
                return false, "ragdoll habis"
            end
        else
            S.touchedThisBatch = true
        end
        dest = onPlane(egg.pos) or egg.pos
        do
            local pLive
            if type(Instant.refreshChainTarget) == "function" then
                local _, p2 = Instant.refreshChainTarget(egg.uid, egg.pos)
                pLive = p2
            end
            if typeof(pLive) ~= "Vector3" then
                pLive = eggWorldPos(egg.uid)
            end
            if typeof(pLive) == "Vector3" then
                egg.pos = pLive
                dest = onPlane(pLive) or pLive
            end
        end
        if G.__StealEggFarOn == true and Instant.isWindow() ~= true then
            armWindow()
        end
        local r0 = root()
        if hopDestOk(r0 and r0.Position, dest) ~= true then
            dest = egg.pos
        end
        if hopDestOk(r0 and r0.Position, dest) ~= true then
            dbg("GO", string.format("dest sampah %s d=%.0f", tostring(dest), r0 and distXZ(r0.Position, dest) or -1))
            return false, "no-pos"
        end
        local stNow = replicaCarry()
        local held = tostring((type(stNow) == "table" and stNow.Uid) or (M._carry and M._carry.Uid) or "")
        if isBaitUid(held) then
            emptyHands("umpan sebelum loot")
        end
        emit("Steal", "live", tostring(egg.name or "egg"))
        hopToEgg(dest, shouldRun)
        if Instant.ragdollLeft() > 0.05 and isDead() ~= true then
            local tPin = os.clock()
            while Instant.ragdollLeft() > 0.05 and (os.clock() - tPin) < 0.45 do
                if running(shouldRun) ~= true or isDead() then
                            break
                        end
                hold(dest)
                        RunService.Heartbeat:Wait()
                    end
        end
        if isDead() then
            return false, "mati"
        end
        if eggStillFree(egg.uid) ~= true then
            M._preferUid = nil
            emit("Wait", "warn", "taken")
            return false, "taken"
        end
        local rSnap = root()
        dbg("GO", string.format("%s lompat eggΔ=%.0f padΔ=%.0f rag=%.2f",
            tostring(egg.name or "?"),
            rSnap and distXZ(rSnap.Position, dest) or -1,
            distXZ(padBase(), dest),
            Instant.ragdollLeft()))
        -- Spam RequestCarry sejak mendarat (MaxEarn). Diam nunggu ragdoll habis
        -- buang jendela hop pulang.
        local tC = os.clock()
        local msg = "tidak ada jawaban"
        local budget = CFG.ragdollMax + CFG.carryBudget
        local downed = 0
        while (os.clock() - tC) < budget do
            if running(shouldRun) ~= true then
                return false, "berhenti saat carry"
            end
            if stillHasEgg(egg.uid) then
                S.grantUid = tostring(egg.uid)
                G.__StealEggClaiming = true
                dbg("CARRY", string.format("%s replica dt=%.2f", tostring(egg.name or "?"), os.clock() - tC))
                return true
            end
            if eggStillFree(egg.uid) ~= true then
                M._preferUid = nil
                emit("Wait", "warn", "taken")
                return false, "taken"
            end
            local rNow = root()
            local near = tonumber(EGG.arrive) or 1.2
            if rNow == nil or distXZ(rNow.Position, dest) > near then
                hold(dest)
            end
            local got, err = askCarry(egg.uid)
            if got then
                S.grantUid = tostring(egg.uid)
                G.__StealEggClaiming = true
                dbg("CARRY", string.format("%s ok dt=%.2f downed=%d", tostring(egg.name or "?"), os.clock() - tC, downed))
                return true
            end
            msg = tostring(err)
            if carryErrTaken(msg) then
                M._preferUid = nil
                emit("Wait", "warn", "taken")
                return false, "taken"
            end
            if string.find(msg, "knocked down", 1, true) then
                    downed += 1
            elseif string.find(string.lower(msg), "closer", 1, true) then
                hopToEgg(dest, shouldRun)
            end
            task.wait(CFG.carryGap)
        end
        if stillHasEgg(egg.uid) then
            S.grantUid = tostring(egg.uid)
            G.__StealEggClaiming = true
            return true
        end
        dbg("DENY", string.format("%s gagal · %s · rag=%.2f", tostring(egg.name or egg.uid), tostring(msg), Instant.ragdollLeft()))
        return false, msg
    end

    local function walkTo(dest, shouldRun, speed, arrive)
        dest = onPlane(dest)
        if dest == nil then
            return false
        end
        arrive = tonumber(arrive) or 6
        speed = math.max(16, tonumber(speed) or legalSpeed(1))
        local r = root()
        if r == nil then
                return false
            end
        local t0 = os.clock()
        local lastD = distXZ(r.Position, dest)
        local budget = math.min(60, (lastD / math.max(16, math.min(speed, baseWalkSpeed()))) + 8)
        while true do
            if running(shouldRun) ~= true or isDead() then
                return false
            end
            local h = humanoid()
            r = root()
            if h == nil or r == nil then
                return false
            end
            local d = distXZ(r.Position, dest)
            if d <= arrive then
        pcall(function()
                    h:MoveTo(r.Position)
                end)
                return true
            end
            if d > lastD + 140 then
                return d <= 40
            end
            lastD = d
            if (os.clock() - t0) > budget then
                return d <= (tonumber(EGG.homeSalvage) or 40)
            end
            local useSpeed = d < math.max(60, arrive * 8) and math.min(speed, 120) or speed
            pcall(function()
                h.WalkSpeed = useSpeed
                h.PlatformStand = false
                h.Sit = false
                h.AutoRotate = true
                h:MoveTo(dest)
            end)
            Instant.camFollow()
            RunService.Heartbeat:Wait()
        end
    end
    local function padArrive()
        return tonumber(CFG.claimArrive) or 8
    end
    -- Pulang: glide Move (halus, dt×speed). Bukan travelTo hop 47/85 (patah + rubber).
    -- Jangan diam nunggu ragdoll: gerak pulang langsung, cara tetap sama.
    local function homeGlide(pad, shouldRun, uid)
        pad = onPlane(pad) or pad
        if typeof(pad) ~= "Vector3" then
            return false
        end
        local r = root()
        local arrive = padArrive()
        if r and distXZ(r.Position, pad) <= arrive then
            return true
        end
        local ok = goSteer(pad, shouldRun, "home", Instant.homeSpeed(), uid)
        if ok == true then
            return true
        end
        dbg("HOME", "glide gagal · walk · why=Move.GoTo false")
        return walkTo(pad, shouldRun, Instant.homeSpeed(), arrive)
    end

    local function serverCorrectedAway(pad)
        local rNow = root()
        if rNow == nil then
            return false
        end
        if (os.clock() - (tonumber(G.__StealEggServerCorrAt) or 0)) >= 1.5 then
            return false
        end
        return distXZ(rNow.Position, pad) > (tonumber(EGG.homeSalvage) or 40)
    end
    local function wobblePad(pad)
        local h = humanoid()
        local r = root()
        if h == nil or r == nil then
            return
        end
                pcall(function()
            h:Move(Vector3.zero, false)
            h:MoveTo(r.Position)
        end)
        Instant.camFollow()
    end
    local function claimHome(uid, shouldRun)
        uid = tostring(uid or "")
        if isBaitUid(uid) then
            return false
        end
        local pad = claimPadPos()
        G.__StealEggClaiming = true
        M._claimed = nil
        emit("Home", "live", "claim pad")
        local homeTries = math.max(1, math.floor(tonumber(EGG.homeTries) or 10))
        local moved = false
        local arrive = padArrive()
        for attempt = 1, homeTries do
            if running(shouldRun) ~= true or isDead() then
                G.__StealEggClaiming = false
                return false
            end
            if stillHasEgg(uid) ~= true then
                M._preferUid = uid
                if pickupDropped(uid, shouldRun) ~= true then
                    G.__StealEggClaiming = false
                    return false
                end
            end
            dbg("HOME", string.format("pulang pad %.0f,%.0f glide · %.0f fps", pad.X, pad.Z, Instant.fps()))
            moved = homeGlide(pad, function()
                if running(shouldRun) ~= true then
                    return false
                end
                return stillHasEgg(uid) == true
            end, uid) == true
            local rH = root()
            if rH and distXZ(rH.Position, pad) <= (tonumber(EGG.homeSalvage) or 70) then
                moved = true
            end
            if stillHasEgg(uid) then
                    break
                end
            M._preferUid = uid
            if pickupDropped(uid, shouldRun) ~= true then
                G.__StealEggClaiming = false
                return false
            end
            dbg("CLAIM", string.format("telur di tangan lagi · lanjut jalan (coba %d/%d)", attempt + 1, homeTries))
            moved = false
        end
        if stillHasEgg(uid) ~= true then
            G.__StealEggClaiming = false
            return false
        end
        local left = distXZ((root() and root().Position) or pad, pad)
        if moved ~= true and left <= (tonumber(EGG.homeSalvage) or 40) then
            moved = true
        end
        if moved ~= true then
            G.__StealEggClaiming = false
                return false
            end
        emit("Claim", "live", tostring((M._lastInfo and M._lastInfo.name) or "egg"))
        local t = os.clock()
        while (os.clock() - t) < CFG.claimWait do
            if running(shouldRun) ~= true then
                break
            end
            if serverCorrectedAway(pad) then
                local rNow = root()
                dbg("CLAIM", string.format("koreksi server · %.0f st dari pad · glide ulang", rNow and distXZ(rNow.Position, pad) or -1))
                G.__StealEggClaiming = false
                return false
            end
            local rPad = root()
            if rPad and distXZ(rPad.Position, pad) > arrive then
                homeGlide(pad, function()
                    if running(shouldRun) ~= true then
                return false
            end
                    return stillHasEgg(uid) == true
                end, uid)
            else
                wobblePad(pad)
            end
            Instant.askForestHandoff(uid)
            if M._claimed ~= nil then
                G.__StealEggClaiming = false
                M._preferUid = nil
                return true
            end
            if stillHasEgg(uid) ~= true then
                if eggIsDropped(uid) then
                    if pickupDropped(uid, shouldRun) ~= true then
                        G.__StealEggClaiming = false
                        return false
                    end
                    homeGlide(pad, function()
                        if running(shouldRun) ~= true then
                            return false
                        end
                        return stillHasEgg(uid) == true
                    end, uid)
                else
                    local r = root()
                    if r and distXZ(r.Position, pad) <= (tonumber(EGG.homeSalvage) or 40) then
                        G.__StealEggClaiming = false
                        M._preferUid = nil
                return true
            end
                    G.__StealEggClaiming = false
                    return false
                end
            end
            RunService.Heartbeat:Wait()
        end
        G.__StealEggClaiming = false
        G.__StealEggClaimCool = os.clock() + 4
        return M._claimed ~= nil
    end

    function Instant.beginFarSession()
        if isDead() then
                return false
            end
        G.__StealEggLeftEgg = false
        G.__StealEggHhtOff = false
        G.__StealEggHhtSnapUntil = 0
        G.__StealEggHoldUntil = 0
        G.__StealEggSnapMute = false
        G.__StealEggInstantRagSnap = false
        G.__StealEggLegsWalk = false
        S.grantUid = nil
        G.__StealEggFarOn = true
        G.__StealEggHomeFreeze = false
        M._homeFreeze = false
        do
            local sp = G.StealEggSpeed
            if type(sp) == "table" and type(sp.Arm) == "function" then
                pcall(sp.Arm)
            end
        end
        if not armWindow() then
            dbg("ERR", "record anti-cheat belum dari Playback (tanpa getgc)")
        end
        if camLockOn() == true then
            startCamHide()
            dbg("FAR", "begin session · cam lock + max-earn window")
        else
            stopCamHide()
            dbg("FAR", "begin session · cam follow + max-earn window")
        end
            return true
        end
    function Instant.preArm()
        if isDead() then
        return false
    end
        pcall(function()
            local sp = G.StealEggSpeed
            if type(sp) == "table" and type(sp.Arm) == "function" then
                sp.Arm()
            end
        end)
        return armWindow() == true
    end
    function Instant.endFarSession(why)
        local wasOn = G.__StealEggFarOn == true
        G.__StealEggFarOn = false
        G.__StealEggClaiming = false
        G.__StealEggHomeFreeze = false
        M._homeFreeze = false
        G.__StealEggTpHold = false
        G.__StealEggMoveQuiet = false
        G.__StealEggInstantRagSnap = false
        S.grantUid = nil
        disarmWindow()
        G.__StealEggMoveWin = false
        G.__StealEggHhtOff = false
        if type(EGG.clearFarHold) == "function" then
            EGG.clearFarHold(why or "end-session")
        end
        stopCamHide()
        pcall(function()
            local cam = Workspace.CurrentCamera
            local hum = humanoid()
            if cam and hum then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = hum
            end
            local r = root()
            if r then
                r.Anchored = false
            end
            if hum and hum.Health > 0 then
                hum.PlatformStand = false
                hum.Sit = false
                if tonumber(S.baseWs) then
                    hum.WalkSpeed = S.baseWs
                end
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end
        end)
        if wasOn then
            dbg("FAR", "end " .. tostring(why or "-"))
        end
        S.touchedThisBatch = false
        S.baitReady = false
        Instant.baitReady = false
        S.baitUid = nil
    end
    Instant.endDecoyTp = Instant.endFarSession
    Instant.thawHomeFreeze = Instant.endFarSession
    Instant.beginDecoyTp = Instant.beginFarSession
    Instant.freezeAtHome = Instant.beginFarSession
    Instant.restoreMove = Instant.endFarSession
    Instant.recoverAfterSnap = function() end
    Instant.recoverAfterSnapSettled = function() end

    pcall(function()
        LP.CharacterAdded:Connect(function()
            Instant.endFarSession("respawn")
            cachedHideChar = nil
            for i = #cachedHideList, 1, -1 do
                cachedHideList[i] = nil
            end
            hideParts = {}
        end)
    end)
    pcall(function()
        local es = Core.require("Client.EggState")
        if type(es) == "table" then
            if es.FieldClaimed then
                pcall(function()
                    es.FieldClaimed:Connect(function(st)
                        M._claimed = st
                        S.grantUid = nil
                    end)
                end)
            end
            if es.CarryChanged then
                pcall(function()
                    es.CarryChanged:Connect(function(st)
                        if type(st) == "table" then
                            S.carryState = st
                            if st.IsCarrying ~= true then
                                S.grantUid = nil
                            elseif st.Uid ~= nil then
                                S.grantUid = tostring(st.Uid)
                            end
                        else
                            S.carryState = { IsCarrying = false, Uid = nil }
                            S.grantUid = nil
                        end
                    end)
                end)
            end
        end
    end)

    function Instant.requestDrop(reason)
        emptyHands(reason or "PlayerRequest")
            return true
        end
    function Instant.dropUntilClear(why, budget)
        local t0 = os.clock()
        budget = tonumber(budget) or 0.4
        while serverCarrying() == true and (os.clock() - t0) < budget do
            emptyHands(why or "clear")
            task.wait(0.05)
        end
        return serverCarrying() ~= true
    end
    function Instant.isFarMode()
        return stealMode() == "teleport"
    end
    function Instant.holdAtEgg(pos)
        pos = onPlane(pos) or pos
        if Instant.ragdollLeft() > 0.15 then
            return hold(pos)
        end
        return hopToEgg(pos, nil)
    end
    function Instant.plantAtEgg(pos)
        return Instant.holdAtEgg(pos)
    end
    function Instant.snapFarY74(pos)
        return Instant.holdAtEgg(pos)
    end
    function Instant.farSnapTo(pos)
        return travelTo(pos, nil, legalSpeed(1))
    end
    function Instant.waitForestGuardHit(shouldRun)
        return softTouch(shouldRun) == true
    end
    function Instant.rushToForest(shouldRun)
        if type(ensureOffBelt) == "function" and ensureOffBelt(shouldRun) ~= true then
            emit("Belt", "warn", "still on treadmill")
            return false
        end
        return Instant.stageForest(shouldRun)
    end
    function Instant.uiSpeed()
        return legalSpeed(1)
    end
    -- Speed pulang = UI Move Speed (Auto = WS akun × 3.7, Manual = kotak).
    function Instant.homeSpeed()
        if CFG.tpHomeWalk == true then
            return tpHomeSpeed()
        end
        local v = carrySpeed()
        local Move = type(getMove) == "function" and getMove() or G.StealEggMove
        if type(Move) == "table" and type(Move.WantWalkSpeed) == "function" then
            local ok, ui = pcall(Move.WantWalkSpeed)
            if ok and tonumber(ui) and ui > 0 then
                v = ui
            end
        end
        return math.clamp(v, CFG.speedFloor, CFG.speedMax)
    end
    Instant.carryWalkSpeed = Instant.homeSpeed
    Instant.plantPadHard = function(pad)
        return travelTo(onPlane(pad) or pad, nil, Instant.uiSpeed())
    end
    Instant.burstExitSoftTouch = function()
        return true
        end
    Instant.walkHomeToPad = function(pad, shouldRun)
        local st = replicaCarry()
        local uid = tostring((type(st) == "table" and st.Uid) or M._preferUid or "")
        if isBaitUid(uid) then
            M._preferUid = nil
            uid = ""
        end
        if uid ~= "" and stillHasEgg(uid) then
            return claimHome(uid, shouldRun)
        end
        if uid ~= "" then
            M._preferUid = uid
            return pickupDropped(uid, shouldRun)
        end
        return goSteer(typeof(pad) == "Vector3" and pad or claimPadPos(), shouldRun, "home", Instant.uiSpeed())
    end
    -- Walk/glide pulang sambil gendong: sama Instant teleport home (window + goSteer).
    Instant.carryHome = function(pad, shouldRun)
        pad = onPlane(typeof(pad) == "CFrame" and pad.Position or pad) or pad
        if typeof(pad) ~= "Vector3" then
            pad = claimPadPos()
        end
        pcall(armWindow)
        local uid = tostring(M._preferUid or (M._carry and M._carry.Uid) or "")
        if uid ~= "" and stillHasEgg(uid) then
            return claimHome(uid, shouldRun) == true
        end
        return goSteer(pad, shouldRun, "home", Instant.homeSpeed(), uid ~= "" and uid or nil) == true
    end
    Instant.escapeHomeHops = Instant.walkHomeToPad
    Instant.claimFarPad = function(uid, shouldRun)
        return claimHome(uid, shouldRun)
    end
    Instant.carryRaceAt = function(uid, pos, shouldRun)
        uid = tostring(uid or "")
        if typeof(pos) == "Vector3" then
            hopToEgg(pos, shouldRun)
        end
        return pickupDropped(uid, shouldRun) == true
    end
    Instant.regrabDropped = pickupDropped
    Instant.retryDropped = pickupDropped
    Instant.waitRagdollDown = function()
        return Instant.ragdollLeft() <= 0.12
    end
    Instant.trustLandAt = Instant.holdAtEgg
    Instant.findFirstAreaBait = function()
        return findForestBait(CFG.forestPos, 80)
    end
    Instant.tryCarryFirstArea = function(uid)
        return carryBait(uid)
    end
    Instant.fireForestStrike = function(uid, g)
        local cf = typeof(g) == "CFrame" and g or (g and g.CFrame)
        return fireForestStrike(uid, cf)
    end

    local function bagFree()
        local egg = G.StealEggWild or EGG
        if type(egg) == "table" and type(egg.eggBagFree) == "function" then
            local ok, n = pcall(egg.eggBagFree)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
        local used, maxInv = 0, 115
        pcall(function()
            local Save = Core.require("Library.Client.Save")
            local data
            if type(Core) == "table" and type(Core.playerSave) == "function" then
                data = Core.playerSave()
            end
            if type(data) ~= "table" and type(Save) == "table" and type(Save.Get) == "function" then
                data = Save.Get()
            end
            if type(data) ~= "table" and type(Save) == "table" and type(Save.Peek) == "function" then
                data = Save.Peek()
            end
            local inv = type(data) == "table" and data.EggInventory
            if type(inv) == "table" then
                for _, rec in pairs(inv) do
                    if type(rec) == "table" then
                        used += 1
                    end
                end
            end
        end)
        return math.max(0, maxInv - used)
    end
    local function guardCfg(areaId)
        if type(S.guardDir) ~= "table" then
            S.guardDir = {}
            pcall(function()
                local Guards = require(ReplicatedStorage:WaitForChild("Data"):WaitForChild("Guards"))
                if type(Guards) == "table" and type(Guards.Directory) == "table" then
                    for k, v in pairs(Guards.Directory) do
                        S.guardDir[tostring(k)] = v
                    end
                end
            end)
        end
        return S.guardDir[tostring(areaId or "")]
    end
    -- Kecepatan pulang nyata = homeSpeed (sudah di bawah cap server).
    function Instant.reachSpeed()
        return Instant.homeSpeed()
    end
    -- Guard server: WS × (1 + (d/20 − 1) × 0.5), maks 4×. Kena kalau XZ ≤ 4–7.
    -- Jarak seimbang d = 20 × (2v/WS − 1). Butuh d ≥ ~16 → v ≥ 0.9 × WS.
    function Instant.areaBeatable(areaId)
        areaId = tostring(areaId or "")
        if areaId == "" or areaId == "Forest" then
            return true
        end
        if (tonumber(CFG.guardBeatRatio) or 0) <= 0 then
            return true
        end
        local cfg = guardCfg(areaId)
        local ws = type(cfg) == "table" and tonumber(cfg.WalkSpeed) or nil
        if ws == nil then
            return true
        end
        local v = Instant.reachSpeed()
        local ok = v >= ws * (tonumber(CFG.guardBeatRatio) or 0.9)
        if not ok then
            local now = os.clock()
            if (now - (tonumber(S.skipLogAt) or 0)) > 3 then
                S.skipLogAt = now
                dbg("SKIP", string.format("%s guard %.0f > kita %.0f st/s (%.0f fps) · lewati", areaId, ws, v, Instant.fps()))
            end
        end
        return ok
    end
    local function targetArea(t)
        local rec = type(t) == "table" and t.rec or nil
        if type(rec) == "table" then
            return rec.AreaId or rec.areaId
        end
        return type(t) == "table" and (t.areaId or t.area) or nil
    end

    -- Catatan live (ReadFieldEgg), bukan snapshot lama.
    -- Telur yang sudah diambil: record nil / bukan Slot. Jangan teleport ke koordinat cache.
    local function eggOnGround(id, rec)
        id = tostring(id or "")
        if id == "" then
            return false
        end
        if type(getEggRecord) ~= "function" then
            return true
        end
        local live = getEggRecord(id)
        if type(live) ~= "table" then
            if type(rec) == "table" then
                rec.State = "Claimed"
            end
            return false
        end
        local st = tostring(live.State or "")
        if st == "Slot" or st == "Dropped" then
            return true, live
        end
        if type(rec) == "table" then
            rec.State = st ~= "" and st or "Claimed"
        end
        return false
    end
    function Instant.nextChainFill(stolen, _want)
        stolen = type(stolen) == "table" and stolen or {}
        if type(nearestEgg) ~= "function" then
            return nil
        end
        local skip = {}
        for k, v in pairs(stolen) do
            skip[k] = v
        end
        for _ = 1, 40 do
            local fresh = select(1, nearestEgg({
                allowNoRoot = true,
                noParasiteFallback = true,
                skip = skip,
            }))
            if type(fresh) ~= "table" then
                return nil
            end
            local id = tostring(fresh.uid or (fresh.rec and fresh.rec.Uid) or "")
            if id == "" or isBaitUid(id) then
                return nil
            end
            local onGround, live = eggOnGround(id, fresh.rec)
            if onGround ~= true then
                skip[id] = true
            elseif typeof(fresh.pos) ~= "Vector3" then
                skip[id] = true
            elseif Instant.areaBeatable(targetArea(fresh)) then
                if type(live) == "table" and type(recordPos) == "function" then
                    local pLive = recordPos(live)
                    if typeof(pLive) == "Vector3" then
                        fresh.pos = pLive
                        fresh.rec = live
                    end
                end
                fresh.uid = id
                return fresh
            else
                skip[id] = true
            end
        end
        return nil
    end
    function Instant.refreshChainTarget(uid, pos)
        uid = tostring(uid or "")
        if uid == "" then
            return nil, nil
        end
        if eggStillFree(uid) ~= true then
            return nil, nil
        end
        local rec = type(getEggRecord) == "function" and getEggRecord(uid) or nil
        local p
        if type(recordPos) == "function" then
            p = recordPos(rec)
        end
        if typeof(p) ~= "Vector3" and type(worldPosition) == "function" then
            local model = type(resolveWorkspaceModel) == "function" and resolveWorkspaceModel(uid)
            p = worldPosition(model)
        end
        if typeof(p) ~= "Vector3" and typeof(pos) == "Vector3" then
            p = pos
        end
        return rec, p
    end
    function Instant.farChainRun(seq)
        if G.__StealEggWanted ~= true or seq ~= G.__StealEggSeq or not genAlive() or M.enabled ~= true then
            return false
        end
        if G.__StealEggBusy == true or G.__StealEggFarOn == true then
            return true
        end
        if type(M.beltYield) == "function" and M.beltYield() == true then
            return false
        end
        return true
    end

    function Instant.stealFarChain(shouldRun, seq, opts)
        opts = type(opts) == "table" and opts or {}
        local want = math.clamp(math.floor(tonumber(EGG.farChainCount) or 3), 1, 3)
        local probe = Instant.nextChainFill({}, 1)
        if type(probe) ~= "table" then
            dbg("FAR", "chain kosong")
            return false
        end
        dbg("Teleport", string.format("scan segar · %s",
            tostring(probe.info and probe.info.name or probe.uid)))
        if type(ensureOffBelt) == "function" and ensureOffBelt(shouldRun) ~= true then
            emit("Belt", "warn", "still on treadmill")
            return false
        end
        if Instant.beginFarSession() ~= true then
            emit("Wait", "warn", "session")
            return false
        end
        G.__StealEggSpawnGo = false
        do
            local free = bagFree()
            if free < want then
                want = math.max(0, free)
                if want <= 0 then
                    emit("Denied", "warn", "bag full")
                    if type(EGG.markBagFull) == "function" then
                        pcall(EGG.markBagFull)
                    else
                        G.__StealEggBagFullUntil = os.clock() + 8
                    G.__StealEggPlaceWindow = true
                        Instant.endFarSession("bag-full")
                    end
                    return false
                end
            end
        end
        local okCount = 0
        local stolen = {}
        S.touchedThisBatch = false
        for i = 1, want do
            if running(shouldRun) ~= true then
                break
            end
            if isDead() then
                Instant.endFarSession("dead")
                return okCount > 0
            end
            -- Ragdoll hidup: JANGAN bait / glide Forest. Itu freeze 3–5s.
            if Instant.ragdollLeft() > 0.05 then
                S.touchedThisBatch = true
            end
            if S.touchedThisBatch == true and Instant.ragdollLeft() > 0.05 then
                -- ragdoll masih ada, lanjut egg
            else
                S.touchedThisBatch = false
                if S.baitReady ~= true then
                    Instant.preStage(shouldRun)
                end
                if S.baitReady ~= true then
                    emit("Failed", "warn", "no bait")
                    Instant.endFarSession("no-bait")
                    G.__StealEggBaitMissUntil = os.clock() + 0.85
                    return false
                end
                local hit, why = raceStrike(shouldRun)
                S.touchedThisBatch = hit == true
                if hit ~= true then
                    emit("Failed", "warn", tostring(why or "no hit"))
                    G.__StealEggBaitMissUntil = os.clock() + 0.55
                    if i == 1 then
                        Instant.endFarSession("no-guard")
                        return false
                    end
                    break
                end
            end
            -- Pilih telur SETELAH ragdoll, dari snapshot yang sedang di memori.
            local target = Instant.nextChainFill(stolen, 1)
            local uid = tostring(target and target.uid or "")
            local pos = target and target.pos
            if type(target) == "table" and uid ~= "" then
                local rec, p2 = Instant.refreshChainTarget(uid, pos)
                if rec == nil or typeof(p2) ~= "Vector3" then
                    stolen[uid] = true
                    M._preferUid = nil
                    target = Instant.nextChainFill(stolen, 1)
                    uid = tostring(target and target.uid or "")
                    pos = target and target.pos
                elseif typeof(p2) == "Vector3" then
                    pos = p2
                    target.pos = p2
                    target.rec = rec or target.rec
                    end
                end
            if type(target) ~= "table" or uid == "" or typeof(pos) ~= "Vector3" then
                break
            end
            local summary = target.info and M.targetSummary and M.targetSummary(target.info) or uid
            M._lastInfo = target.info
            M._claimed = nil
            S.grantUid = nil
            local egg = {
                uid = uid,
                pos = pos,
                name = tostring(target.info and target.info.name or uid),
                dist = distXZ(padBase(), pos),
            }
            local ok, err = stealOne(egg, shouldRun)
            if ok ~= true and running(shouldRun) and isDead() ~= true then
                local lost = tostring(err) == "taken" or tostring(err) == "no-pos" or eggStillFree(uid) ~= true
                if lost then
                    emit("Wait", "warn", "taken")
            stolen[uid] = true
                    M._preferUid = nil
                    local hops = 0
                    while ok ~= true and hops < 4 and running(shouldRun) and isDead() ~= true do
                        hops += 1
                        local fill = Instant.nextChainFill(stolen, 1)
                        local fid = tostring(fill and fill.uid or "")
                        local fpos = fill and fill.pos
                        if type(fill) ~= "table" or fid == "" or typeof(fpos) ~= "Vector3" then
                            break
                        end
                        local rec2, p2 = Instant.refreshChainTarget(fid, fpos)
                        if rec2 == nil or typeof(p2) ~= "Vector3" then
                            stolen[fid] = true
                        else
                            uid = fid
                            pos = p2
                            egg = {
                                uid = uid,
                                pos = pos,
                                name = tostring(fill.info and fill.info.name or uid),
                                dist = distXZ(padBase(), pos),
                            }
                            M._lastInfo = fill.info
                            emit("Steal", "live", tostring(egg.name))
                            ok, err = stealOne(egg, shouldRun, true)
                            if ok ~= true then
                                stolen[uid] = true
                                if tostring(err) ~= "taken" and tostring(err) ~= "no-pos" and eggStillFree(uid) == true then
                                    break
                    end
                end
                        end
                        end
                    else
                    dbg("GO", "ulang target, jangan Forest")
                    ok, err = stealOne(egg, shouldRun)
                    if tostring(err) == "taken" then
                        stolen[uid] = true
                        M._preferUid = nil
                        ok = false
                    end
                end
            end
            if ok == true and stillHasEgg(uid) ~= true then
                S.grantUid = uid
                ok = true
            end
            if ok == true then
                stolen[uid] = true
                local claimed = claimHome(uid, shouldRun) == true
                local tries = 0
                while claimed ~= true and running(shouldRun) and isDead() ~= true
                    and stillHasEgg(uid) and tries < 4
                do
                    tries += 1
                    M._preferUid = uid
                    dbg("CLAIM", "claim belum kedaftar · telur masih di tangan · ulang " .. tries)
                    claimed = claimHome(uid, shouldRun) == true
                end
                if claimed ~= true and running(shouldRun) and isDead() ~= true
                    and eggIsDropped(uid)
                then
                    M._preferUid = uid
                    if pickupDropped(uid, shouldRun) == true then
                        dbg("CLAIM", "setor ulang setelah regrab")
                        claimed = claimHome(uid, shouldRun) == true
                end
            end
                if claimed then
                okCount += 1
                M._runs += 1
                    M._preferUid = nil
                    S.grantUid = nil
                    -- Jangan reset bait kalau ragdoll masih hidup: egg berikutnya
                    -- langsung hop, jangan muter Forest dulu.
                    if Instant.ragdollLeft() > 0.05 then
                        S.touchedThisBatch = true
                    else
                    S.touchedThisBatch = false
                    S.baitReady = false
                    Instant.baitReady = false
                    -- Pin sisa glide pulang. Kalau dibiarkan, glide Forest berikutnya diam.
                    G.__StealEggTpHold = false
                    G.__StealEggMoveQuiet = false
                    wakeLegs()
                    end
                emit("Stolen", "success", summary)
                elseif stillHasEgg(uid) then
                    M._preferUid = uid
                    emit("Home", "warn", "claim")
                elseif eggIsDropped(uid) then
                    M._preferUid = uid
                    S.grantUid = nil
                    emit("Steal", "warn", "dropped")
                else
                    emit("Home", "warn", "claim")
                end
            else
                if tostring(err) == "taken" then
                    stolen[uid] = true
                    M._preferUid = nil
                    S.grantUid = nil
                else
                    emit("Steal", "warn", tostring(err or "-"))
                    if stillHasEgg(uid) then
                        M._preferUid = uid
                    elseif eggIsDropped(uid) then
                        M._preferUid = uid
                        S.grantUid = nil
                    else
                        M._preferUid = nil
                        local st = replicaCarry()
                        local held = tostring(type(st) == "table" and st.Uid or "")
                        if isBaitUid(held) then
                            emptyHands("carry-bait")
            end
        end
                end
            end
        end
        Instant.endFarSession(okCount > 0 and "batch-done" or "batch-miss")
        dbg("FAR", string.format("batch done ok=%d/%d", okCount, want))
        return okCount > 0
    end

