    M.farSnapTo = Instant.farSnapTo
    M.isFarMode = Instant.isFarMode
    M.restoreMove = Instant.restoreMove

    Instant._ready = true
    G.StealEggInstant = Instant
    G.__StealEggInstantOn = true
    return true
end

do
    local H = G.StealEggInstantHooks
    if type(H) == "table" then
        Instant.install(H)
    end
end

return Instant
 end,       required = true },
    { key = "AutoSell",  name = "Auto Sell",     factory = function() -- Auto sell pet + egg (inventory) + rules
-- Remote game (Shared.Remotes), dipakai langsung tanpa nama alias:
--   PetSatchel.SellSelection { Assets = {uid}, Eggs = {uid} }  jual pilihan
--   PetSatchel.SellPet { uid }                                 barang dipegang
--   Haul.WriteAutoSell { [rarityId] = true }                   auto-sell menetas
-- PetSatchel.SellEveryPet sengaja TIDAK dipakai: itu tombol "sell all" milik
-- game, yang mengosongkan tas tanpa peduli rule maupun cadangan bahan Rift.
-- Hard skip: favorite / equipped pet / fuse / placed.
-- Held steal egg used to skip collect + abort sellByEquip ("held other") forever.
-- Unequip leftover AssetEgg before egg sell unless steal is carrying/claiming.
-- Pet: Ground / plot (turun treadmill dulu). Egg: remote bag, no walk, Steal boleh paralel.

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
