if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before AutoSell", 0)
end

G.__StealEggSellGen = (tonumber(G.__StealEggSellGen) or 0) + 1
local GEN = G.__StealEggSellGen

local NO_MUTATION = "No Mutation"
local DEFAULT_COMPARE_MODE = "below"
local COMPARE_ITEMS = {
    { key = "above", name = "Above" },
