G.StealEggSell = M

local tryRequire = Core.require
local dropdownValue = Core.dropdownValue
local parseKeyMap = Core.parseKeyMap
local eggCall = Core.eggCall

local Save, Network, Assets, RarityDir, AssetItemSerialization, EggItemUtil, AssetItemUtil, AssetGenerationUtil, Mutations, GetPriceValueForItem, PlotCmds
local Remotes

local function bindGame()
    Save = Save or tryRequire("Library.Client.Save")
    Network = Network or tryRequire("Library.Client.Network")
    -- Tabel remote milik game. Nama gaya lama ("AssetInventory: SellAsset")
    -- tidak ada lagi: folder ReplicatedStorage.Network sudah lenyap sama sekali,
    -- jadi keempat nama itu tidak pernah sampai ke server. Yang benar sekarang
    -- diambil langsung dari Shared.Remotes, cara yang sama seperti modul lain.
    Remotes = Remotes or tryRequire("Shared.Remotes")
    Assets = Assets or tryRequire("Directory.Assets")
    RarityDir = RarityDir or tryRequire("Directory.Rarity")
    AssetItemSerialization = AssetItemSerialization or tryRequire("Library.Util.AssetItemSerialization")
    EggItemUtil = EggItemUtil or tryRequire("Library.Util.EggItemUtil")
    AssetItemUtil = AssetItemUtil or tryRequire("Library.Util.AssetItemUtil")
    AssetGenerationUtil = AssetGenerationUtil or tryRequire("Library.Util.AssetGenerationUtil")
    Mutations = Mutations or tryRequire("Library.Modules.Mutations")
    GetPriceValueForItem = GetPriceValueForItem or tryRequire("Library.Util.GetPriceValueForItem")
    PlotCmds = PlotCmds or tryRequire("Library.Client.PlotCmds")
end

local savedHatchAuto = nil
local hatchPushed = false

local function assetDir()
    if type(Assets) ~= "table" then
        return nil
    end
    if type(Assets.Directory) == "table" then
        return Assets.Directory
    end
    return Assets
end

local function rarityTable()
    if type(RarityDir) ~= "table" then
        return nil
    end
    if type(RarityDir.Rarities) == "table" then
        return RarityDir.Rarities
    end
    if type(RarityDir.Directory) == "table" then
        return RarityDir.Directory
    end
    return RarityDir
end

local function emit(kind, text, style, detail)
    local st = M[kind]
    if type(st) ~= "table" then
        return
    end
    text = tostring(text or "Idle")
    detail = tostring(detail or "—")
    if text == "On" then
        detail = "—"
    elseif text == "Selling" then
        if string.find(string.lower(detail), "remote", 1, true)
            or string.find(string.lower(detail), "equip", 1, true)
            or string.find(string.lower(detail), "ground", 1, true) and not string.find(detail, "%d") then
            detail = "—"
        end
    elseif text == "Wait" then
        if string.find(string.lower(detail), "ground", 1, true) then
            detail = "Ground"
        elseif string.find(string.lower(detail), "dipegang", 1, true) or string.find(string.lower(detail), "held", 1, true) then
            detail = "holding"
        else
            detail = "—"
        end
    elseif text == "Failed" or text == "Error" then
        text = "Failed"
        detail = "—"
    elseif text == "Idle" then
        if string.find(string.lower(detail), "no match", 1, true) then
            detail = "no match"
        elseif string.find(string.lower(detail), "sold", 1, true) then
            local n = string.match(detail, "(%d+)")
            detail = n and ("sold " .. n) or "—"
        elseif string.find(string.lower(detail), "set rules", 1, true) then
            detail = "set rules"
        else
            detail = "—"
        end
    end
    st._status = {
        text = text,
        style = style or "muted",
        detail = detail,
    }
    local fn = st._onStatus
    if type(fn) == "function" then
        pcall(fn, st._status)
    end
end

function M.setPetStatusListener(fn)
    M.pet._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M.pet._status)
    end
end

function M.setEggStatusListener(fn)
    M.egg._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M.egg._status)
    end
end

local function getSave()
    bindGame()
    if type(Core) == "table" and type(Core.playerSave) == "function" then
        local ok, data = pcall(Core.playerSave, { wait = true })
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, data = pcall(Save.Get)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(Save) == "table" and type(Save.Cache) == "function" then
        local okC, bag = pcall(Save.Cache)
        if okC and type(bag) == "table" then
            local data = bag[LP]
            if type(data) == "table" then
                return data
            end
            local uid = tonumber(LP and LP.UserId) or 0
            for plr, rec in pairs(bag) do
                if type(rec) == "table" then
                    local id = 0
                    pcall(function()
                        id = tonumber(plr.UserId) or 0
                    end)
                    if uid ~= 0 and id == uid then
                        return rec
                    end
                end
            end
        end
    end
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get, LP, true)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function rarityOf(category)
    local dir = assetDir()
    local cfg = type(dir) == "table" and dir[category]
    if type(cfg) ~= "table" then
        cfg = type(dir) == "table" and dir[tostring(category)]
    end
    local r = type(cfg) == "table" and cfg.Rarity
    if type(r) ~= "table" then
        return 0, "", tostring(category)
    end
    local num = tonumber(r.RarityNumber) or 0
    local id = tostring(r._id or r.DisplayName or r.Name or "")
    local name = tostring(cfg.DisplayName or cfg.Name or cfg._id or category)
    return num, id, name
end

local function displayOf(category)
    local _, _, name = rarityOf(category)
    return name
end

local function mapHas(map)
    return type(map) == "table" and next(map) ~= nil
end

local function copyMap(value)
    return parseKeyMap(value)
end

local function mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function newRuleId()
    return "sr" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "dc", 1e33 },
        { "no", 1e30 },
        { "oc", 1e27 },
        { "sp", 1e24 },
        { "sx", 1e21 },
        { "qi", 1e18 },
        { "qa", 1e15 },
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

local function clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or ""))
    if fallback == "below" then
        return "below"
    end
    return "above"
end

local function unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

local function wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

local function parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or "above"), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(txt)
    end
    return n, clampCompareMode(explicitMode, "above"), unsignedRuleText(txt)
end

local function parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or "above"), (raw == "" and "0" or unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(raw)
    end
    return n, clampCompareMode(explicitMode, "above"), unsignedRuleText(raw)
end

local function isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

local function sanitizeRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = parseSignedRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "rarity", "name", "mutation", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        rarities = copyMap(rule.rarities),
        names = copyMap(rule.names),
        mutations = copyMap(rule.mutations),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
    }
end

local function sanitizeRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = sanitizeRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

local function enabledRules(st)
    local out = {}
    if type(st) ~= "table" or type(st.rules) ~= "table" then
        return out
    end
    for _, rule in ipairs(st.rules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    return out
end

local function setKindRules(kind, list)
    local st = M[kind]
    if type(st) ~= "table" then
        return {}
    end
    st.rules = sanitizeRules(list)
    return st.rules
end

local function mutationNames(data)
    local out, seen = {}, {}
    local function add(name)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        out[#out + 1] = name
    end
    if type(data) ~= "table" then
        return out
    end
    if type(data.Mutations) == "table" then
        for _, name in ipairs(data.Mutations) do
            add(name)
        end
        for _, name in pairs(data.Mutations) do
            if type(name) == "string" then
                add(name)
            end
        end
    end
    add(data.BaseMutation)
    return out
end

local function itemKg(kind, category, scale)
    scale = tonumber(scale) or 0
    category = tostring(category or "")
    if category == "" then
        return 0
    end
    if kind == "egg" and type(EggItemUtil) == "table" and type(EggItemUtil.GetWeightKgForScale) == "function" then
        local ok, kg = pcall(EggItemUtil.GetWeightKgForScale, category, scale)
        if ok then
            return tonumber(kg) or 0
        end
    end
    if type(AssetItemUtil) == "table" then
        local fn = AssetItemUtil.GetVisualWeightKg or AssetItemUtil.WeightKg
        if type(fn) == "function" then
            local ok, kg = pcall(fn, {
                Category = category,
                Scale = scale,
                Mutations = {},
            })
            if ok then
                return tonumber(kg) or 0
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local weight = type(cfg) == "table" and tonumber(cfg.ModelWeight) or 1
    return weight * math.max(scale, 0) ^ 3
end

local function eggToAsset(egg)
    if type(egg) ~= "table" then
        return nil
    end
    if type(EggItemUtil) == "table" and type(EggItemUtil.BuildAssetItemData) == "function" then
        local ok, item = pcall(EggItemUtil.BuildAssetItemData, egg)
        if ok and type(item) == "table" then
            return item
        end
    end
    return {
        Category = egg.AssetCategory,
        Scale = egg.AssetScale,
        Mutations = type(egg.Mutations) == "table" and egg.Mutations or {},
        BaseMutation = egg.BaseMutation,
        Gender = egg.AssetGender,
        EyeColor = egg.AssetEyeColor,
        ColorSeed = egg.AssetColorSeed,
        ColorIndex = egg.AssetColorIndex,
        Personality = egg.AssetPersonality,
        IsStolenDNA = egg.IsStolenDNA,
    }
end

local function sizeEarnMulti(scale)
    scale = tonumber(scale) or 0
    if scale <= 0 then
        return 0
    end
    if scale <= 5 then
        return scale ^ 1.85
    end
    return (scale / 5) ^ 1.2 * 19.637875755794113
end

local function mutEarnMulti(muts)
    if type(Mutations) == "table" then
        local fn = Mutations.GetTotalMutationsEarningMulti or Mutations.EarningsFor
        if type(fn) == "function" then
            local ok, n = pcall(fn, muts or {})
            if ok then
                return math.max(1, tonumber(n) or 1)
            end
        end
    end
    return 1
end

local function itemRate(assetData, saveData)
    if type(assetData) ~= "table" or type(assetData.Category) ~= "string" then
        return 0
    end
    if type(AssetGenerationUtil) == "table" then
        local rateFn = AssetGenerationUtil.GetRate or AssetGenerationUtil.RatePerSecond
        if type(rateFn) == "function" then
            local rebirth = type(saveData) == "table" and tonumber(saveData.Rebirth) or 0
            local passes = type(saveData) == "table" and saveData.Gamepasses or nil
            local products = type(saveData) == "table" and saveData.Products or nil
            local ok, n = pcall(rateFn, assetData, rebirth or 0, passes, products)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
        local mutOnly = AssetGenerationUtil.GetBaseRateMutationOnly or AssetGenerationUtil.MutationOnlyRatePerSecond
        if type(mutOnly) == "function" then
            local ok, n = pcall(mutOnly, assetData)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and dir[assetData.Category]
    local base = type(cfg) == "table" and tonumber(cfg.EarningRate) or 0
    local n = math.round(base * sizeEarnMulti(assetData.Scale) * mutEarnMulti(assetData.Mutations))
    return math.max(n, 0)
end

local function itemPrice(assetData, rate)
    if type(assetData) == "table" then
        if type(GetPriceValueForItem) == "function" then
            local ok, n = pcall(GetPriceValueForItem, assetData)
            if ok then
                local price = tonumber(n) or 0
                if price > 0 then
                    return price
                end
            end
        end
        if type(AssetItemUtil) == "table" then
            local fn = AssetItemUtil.SalePrice or AssetItemUtil.GetPriceValueForItem
            if type(fn) == "function" then
                local ok, n = pcall(fn, assetData)
                if ok then
                    local price = tonumber(n) or 0
                    if price > 0 then
                        return price
                    end
                end
            end
        end
    end
    return math.max(0, (tonumber(rate) or 0) * 100)
end

local function matchesName(category, names)
    if not mapHas(names) then
        return true
    end
    category = tostring(category or "")
    return names[category] == true or names[string.lower(category)] == true
end

local function matchesRarity(category, rarities)
    if not mapHas(rarities) then
        return true
    end
    local num, id = rarityOf(category)
    return rarities[tostring(num)] == true or rarities[id] == true or rarities[string.lower(id)] == true
end

local function matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "below" then
        return value <= n
    end
    return value >= n
end

local function matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if not mapHas(selected) then
        return true
    end
    local wantNone = false
    local hasPick = false
    for key, on in pairs(selected) do
        if on == true then
            if isNoMutationKey(key) then
                wantNone = true
            else
                hasPick = true
            end
        end
    end
    if wantNone and not hasPick then
        return not has
    end
        if hasPick then
            for i = 1, #names do
                local name = names[i]
                if type(Core.mutationPicked) == "function" then
                    if Core.mutationPicked(name, selected) then
                        return true
                    end
                elseif selected[name] == true or selected[string.lower(name)] == true then
                    return true
                end
            end
        if wantNone and not has then
            return true
        end
        return false
    end
    return true
end

local function ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

local function ruleMatches(rule, rec)
    if type(rule) ~= "table" or type(rec) ~= "table" then
        return false
    end
    if ruleFieldOn(rule, "name") and not matchesName(rec.category, rule.names) then
        return false
    end
    if ruleFieldOn(rule, "rarity") and not matchesRarity(rec.category, rule.rarities) then
        return false
    end
    if ruleFieldOn(rule, "kg") and not matchesSigned(rec.kg, rule.kg, rule.kgMode) then
        return false
    end
    if ruleFieldOn(rule, "rate") and not matchesSigned(rec.rate, rule.rate, rule.rateMode) then
        return false
    end
    if ruleFieldOn(rule, "price") and not matchesSigned(rec.price, rule.price, rule.priceMode) then
        return false
    end
    if ruleFieldOn(rule, "mutation") and not matchesMutation(rec.muts, rule) then
        return false
    end
    return true
end

local function hasMatchRule(st)
    return #enabledRules(st) > 0
end

local function clampKeepCount(n)
    n = math.floor(tonumber(n) or 0)
    if n < 0 then
        n = 0
    elseif n > 99 then
        n = 99
    end
    return n
end

local function itemMatches(rec, st)
    local rules = enabledRules(st)
    if #rules == 0 then
        return false
    end
    for _, rule in ipairs(rules) do
        if ruleMatches(rule, rec) then
            return true
        end
    end
    return false
end

local function selectedRarityIds(rarities)
    local out = {}
    if not mapHas(rarities) then
        return out
    end
    local dir = rarityTable()
    if type(dir) == "table" then
        for name, info in pairs(dir) do
            if type(info) == "table" then
                local num = tonumber(info.RarityNumber) or 0
                local id = tostring(info._id or name)
                if rarities[tostring(num)] == true or rarities[id] == true or rarities[tostring(name)] == true then
                    if id ~= "" then
                        out[id] = true
                    end
                end
            end
        end
    end
    if not next(out) then
        for _, item in ipairs(Core.RARITY_ITEMS) do
            if rarities[tostring(item.key)] == true then
                local label = tostring(item.name or "")
                local id = label:match("·%s*(.+)$") or label
                id = id:gsub("^%s+", ""):gsub("%s+$", "")
                if id ~= "" then
                    out[id] = true
                end
            end
        end
    end
    return out
end

local function unionRuleRarities(st)
    local merged = {}
    for _, rule in ipairs(enabledRules(st)) do
        if ruleFieldOn(rule, "rarity") and mapHas(rule.rarities) then
            for key, on in pairs(rule.rarities) do
                if on == true then
                    merged[tostring(key)] = true
                end
            end
        end
    end
    return merged
end

local function heldTool()
    local char = LP.Character
    return char and char:FindFirstChildWhichIsA("Tool")
end

local function heldUid()
    local tool = heldTool()
    if not tool then
        return nil
    end
    local uid = tool:GetAttribute("UID")
    if type(uid) == "string" and uid ~= "" then
        return uid
    end
    return nil
end

local function heldItemType()
    local tool = heldTool()
    return tool and tool:GetAttribute("ItemType")
end

-- Don't unequip/sell the egg steal is still carrying or claiming.
local function protectHeldEgg()
    if G.__StealEggClaiming == true then
        return true
    end
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild._carry) == "table" and wild._carry.IsCarrying == true then
        return true
    end
    return false
end

local function stealProtectUid()
    if not protectHeldEgg() then
        return nil
    end
    local wild = G.StealEggWild
    local uid = type(wild) == "table" and type(wild._carry) == "table" and wild._carry.Uid
    if uid ~= nil and tostring(uid) ~= "" then
        return tostring(uid)
    end
    return heldUid()
end

local function unequipHeldEgg()
    if protectHeldEgg() then
        return false
    end
    if heldItemType() ~= "AssetEgg" then
        return true
    end
    local uid = heldUid()
    if type(eggCall) == "function" then
        if uid then
            pcall(eggCall, "RequestUnequipTool", uid)
        end
        pcall(eggCall, "RequestUnequipTool")
    end
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
    local t0 = os.clock()
    while os.clock() - t0 < 0.9 do
        if heldItemType() ~= "AssetEgg" then
            return true
        end
        task.wait(0.04)
    end
    return heldItemType() ~= "AssetEgg"
end

local function isEquipped(uid, data)
    data = data or getSave()
    if type(data) ~= "table" or type(data.EquippedAssets) ~= "table" then
        return false
    end
    for _, v in pairs(data.EquippedAssets) do
        if tostring(v) == tostring(uid) then
            return true
        end
    end
    return false
end

local function deserializePet(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if raw.Category ~= nil then
        return raw
    end
    if type(AssetItemSerialization) == "table" then
        local fn = AssetItemSerialization.Deserialize or AssetItemSerialization.Decode
        if type(fn) == "function" then
            local ok, item = pcall(fn, raw)
            if ok and type(item) == "table" then
                return item
            end
        end
    end
    return nil
end

local function eggRecord(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if type(EggItemUtil) == "table" then
        local fn = EggItemUtil.DeserializeSavedEgg or EggItemUtil.Decode
        if type(fn) == "function" then
            local ok, egg = pcall(fn, raw)
            if ok and type(egg) == "table" then
                return egg
            end
        end
    end
    return raw
end

-- Keep per nama isi: pet = Category, telur = AssetCategory (pet di dalam,
-- bukan "Forest Egg" / nama area). Yang diplot / fuse tidak dihitung.
local function reservedKeepUids(kind, keepN)
    local reserved = {}
    if keepN <= 0 then
        return reserved
    end
    local data = getSave()
    local inv = data and (kind == "egg" and data.EggInventory or data.Inventory)
    if type(inv) ~= "table" then
        return reserved
    end
    local groups = {}
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        local category, rate
        if kind == "egg" then
            local egg = eggRecord(raw)
            if type(egg) == "table" and egg.Placement == nil then
                category = tostring(egg.AssetCategory or "")
                if category ~= "" then
                    rate = tonumber(itemRate(eggToAsset(egg), data)) or 0
                end
            end
        else
            local item = deserializePet(raw)
            if type(item) == "table" and item.InFuse ~= true and not isEquipped(uid, data) then
                category = tostring(item.Category or "")
                if category ~= "" then
                    rate = tonumber(itemRate(item, data)) or 0
                end
            end
        end
        if category ~= nil and category ~= "" then
            local g = groups[category]
            if g == nil then
                g = {}
                groups[category] = g
            end
            g[#g + 1] = {
                uid = uid,
                rate = rate or 0,
            }
        end
    end
    for _, g in pairs(groups) do
        table.sort(g, function(a, b)
            if a.rate == b.rate then
                return tostring(a.uid) < tostring(b.uid)
            end
            return a.rate > b.rate
        end)
        for i = 1, math.min(keepN, #g) do
            reserved[g[i].uid] = true
        end
    end
    return reserved
end

local function applyKeepCount(kind, items, st)
    local keepN = clampKeepCount(st and st.keepCount)
    if keepN <= 0 or type(items) ~= "table" or #items == 0 then
        return items
    end
    local reserved = reservedKeepUids(kind, keepN)
    local out = {}
    for i = 1, #items do
        local rec = items[i]
        if type(rec) == "table" and reserved[tostring(rec.uid or "")] ~= true then
            out[#out + 1] = rec
        end
    end
    table.sort(out, function(a, b)
        local ra = tonumber(a and a.rate) or 0
        local rb = tonumber(b and b.rate) or 0
        if ra == rb then
            return (tonumber(a and a.price) or 0) < (tonumber(b and b.price) or 0)
        end
        return ra < rb
    end)
    return out
end

local function collectKind(kind)
    local st = M[kind]
    local data = getSave()
    local inv = data and (kind == "egg" and data.EggInventory or data.Inventory)
    local out = {}
    if type(inv) ~= "table" then
        return out
    end
    local protectUid = kind == "egg" and stealProtectUid() or heldUid()
    if not hasMatchRule(st) then
        return out
    end
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        local rec
        if kind == "egg" then
            local egg = eggRecord(raw)
            if type(egg) == "table" and egg.Placement == nil and uid ~= protectUid then
                local category = tostring(egg.AssetCategory or "")
                local asset = eggToAsset(egg)
                local rate = itemRate(asset, data)
                rec = {
                    uid = uid,
                    category = category,
                    name = displayOf(category),
                    kg = itemKg("egg", category, egg.AssetScale),
                    rate = rate,
                    price = itemPrice(asset, rate),
                    muts = mutationNames(egg),
                    stolen = egg.IsStolenDNA == true,
                }
            end
        else
            local item = deserializePet(raw)
            if type(item) == "table" and item.IsFavorite ~= true and item.InFuse ~= true then
                if uid ~= protectUid and not isEquipped(uid, data) then
                    local fav = G.StealEggFavorite
                    local protected = false
                    if type(fav) == "table" and type(fav.protectsUid) == "function" then
                        local okp, hit = pcall(fav.protectsUid, uid)
                        protected = okp == true and hit == true
                    end
                    if not protected then
                    local category = tostring(item.Category or "")
                    local rate = itemRate(item, data)
                    rec = {
                        uid = uid,
                        category = category,
                        name = displayOf(category),
                        kg = itemKg("pet", category, item.Scale),
                        rate = rate,
                        price = itemPrice(item, rate),
                        muts = mutationNames(item),
                        stolen = item.IsStolenDNA == true,
                    }
                    end
                end
            end
        end
        if rec and rec.category ~= "" then
            local keepStolen = kind ~= "egg" and st.keepStolen == true and rec.stolen == true
            if not keepStolen then
                local keepIndex = false
                if kind == "egg" then
                    local idx = G.StealEggIndexComplete
                    if type(idx) == "table" and type(idx.shouldKeepEgg) == "function" then
                        local oki, keep = pcall(idx.shouldKeepEgg, rec.uid, rec.category)
                        keepIndex = oki == true and keep == true
                    end
                    if not keepIndex then
                        local rift = G.StealEggRift
                        if type(rift) == "table" and type(rift.shouldKeepEgg) == "function" then
                            local okr, keep = pcall(rift.shouldKeepEgg, rec.uid, rec.category)
                            keepIndex = okr == true and keep == true
                        end
                    end
                else
                    local rift = G.StealEggRift
                    if type(rift) == "table" and type(rift.shouldKeepPet) == "function" then
                        local okr, keep = pcall(rift.shouldKeepPet, rec.uid, rec.category)
                        keepIndex = okr == true and keep == true
                    end
                end
                if not keepIndex and itemMatches(rec, st) then
                    out[#out + 1] = rec
                end
            end
        end
    end
    return applyKeepCount(kind, out, st)
end

local function collectPets()
    return collectKind("pet")
end

local function collectEggs()
    return collectKind("egg")
end

local function inspectEgg(uid, raw, data)
    local egg = eggRecord(raw)
    if type(egg) ~= "table" then
        egg = type(raw) == "table" and raw or nil
    end
    if type(egg) ~= "table" then
        return nil
    end
    local category = tostring(egg.AssetCategory or egg.Category or "")
    if category == "" and type(raw) == "table" then
        category = tostring(raw.AssetCategory or raw.Category or "")
    end
    if category == "" then
        return nil
    end
    local asset = eggToAsset(egg)
    local rate = itemRate(asset, data)
    local rarityNum, rarityId, name = rarityOf(category)
    return {
        uid = tostring(uid or ""),
        category = category,
        name = name,
        rarity = rarityId,
        rarityNum = rarityNum,
        kg = itemKg("egg", category, egg.AssetScale),
        rate = rate,
        price = itemPrice(asset, rate),
        muts = mutationNames(egg),
        stolen = egg.IsStolenDNA == true,
        placed = egg.Placement ~= nil,
        state = egg.Placement ~= nil and "Plot" or "Bag",
    }
end

local function inspectPet(uid, raw, data)
    local item = deserializePet(raw)
    if type(item) ~= "table" then
        return nil
    end
    local category = tostring(item.Category or "")
    if category == "" then
        return nil
    end
    local rate = itemRate(item, data)
    local rarityNum, rarityId, name = rarityOf(category)
    local equipped = isEquipped(uid, data)
    return {
        uid = tostring(uid or ""),
        category = category,
        name = name,
        rarity = rarityId,
        rarityNum = rarityNum,
        kg = itemKg("pet", category, item.Scale),
        rate = rate,
        price = itemPrice(item, rate),
        muts = mutationNames(item),
        stolen = item.IsStolenDNA == true,
        favorite = item.IsFavorite == true,
        fuse = item.InFuse == true,
        equipped = equipped == true,
        state = equipped == true and "Equip" or "Bag",
    }
end

function M.listBagEggs()
    bindGame()
    local data = getSave()
    local bag = data and data.EggInventory
    local out = {}
    if type(bag) ~= "table" then
        return out
    end
    local n = 0
    for uid, raw in pairs(bag) do
        local info = inspectEgg(uid, raw, data)
        if info and info.placed ~= true then
            out[#out + 1] = info
        end
        n += 1
        if n % 40 == 0 then
            task.wait()
        end
    end
    return out
end

function M.listPlacedEggs()
    bindGame()
    local data = getSave()
    local bag = data and data.EggInventory
    local out = {}
    if type(bag) ~= "table" then
        return out
    end
    local n = 0
    for uid, raw in pairs(bag) do
        local info = inspectEgg(uid, raw, data)
        if info and info.placed == true then
            out[#out + 1] = info
        end
        n += 1
        if n % 40 == 0 then
            task.wait()
        end
    end
    return out
end

function M.listBagPets()
    bindGame()
    local data = getSave()
    local bag = data and data.Inventory
    local out = {}
