local function getHRP()
    local char = LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function getGround()
    local areas = nil
    if type(Core.objectsAreas) == "function" then
        local ok, found = pcall(Core.objectsAreas)
        if ok then
            areas = found
        end
    end
    if not areas then
        local objects = Workspace:FindFirstChild("__OBJECTS")
        areas = objects and objects:FindFirstChild("Areas")
    end
    local ground = areas and areas:FindFirstChild("Ground")
    if ground and ground:IsA("BasePart") then
        return ground
    end
    if ground and ground:IsA("Model") then
        return ground.PrimaryPart or ground:FindFirstChildWhichIsA("BasePart", true)
    end
    return nil
end

-- Character is standing on Workspace.__OBJECTS.Areas.Ground (not gliding / off-map).
local function isOnGround()
    local ground = getGround()
    local hrp = getHRP()
    if not ground or not hrp then
        return false
    end
    local rel = ground.CFrame:PointToObjectSpace(hrp.Position)
    local half = ground.Size * 0.5
    return math.abs(rel.X) <= half.X
        and math.abs(rel.Z) <= half.Z
        and rel.Y >= -half.Y - 8
        and rel.Y <= half.Y + 16
end

local function inLocalPlot()
    local hrp = getHRP()
    if not hrp then
        return false
    end
    local pos = hrp.Position
    if type(PlotCmds) ~= "table" then
        PlotCmds = tryRequire("Library.Client.PlotCmds")
    end
    if type(PlotCmds) == "table" then
        local fn = PlotCmds.IsWorldPositionWithinLocalPlotBounds or PlotCmds.ContainsLocalPoint
        if type(fn) == "function" then
            local ok, v = pcall(fn, pos)
            if ok and v == true then
                return true
            end
        end
        local dataFn = PlotCmds.GetPlotData or PlotCmds.ResolvePlot
        if type(dataFn) == "function" then
            local ok, data = pcall(dataFn)
            local folder = ok and type(data) == "table" and data.PlotFolder
            if typeof(folder) == "Instance" then
                local okBox, cf, size = pcall(function()
                    return folder:GetBoundingBox()
                end)
                if okBox and typeof(cf) == "CFrame" and typeof(size) == "Vector3" then
                    local localPos = cf:PointToObjectSpace(pos)
                    local half = size * 0.5
                    if math.abs(localPos.X) <= half.X and math.abs(localPos.Z) <= half.Z then
                        return true
                    end
                end
            end
        end
    end
    return false
end

local function onHubSide()
    local hrp = getHRP()
    if not hrp then
        return false
    end
    local line = type(Core.separationLine) == "function" and Core.separationLine() or nil
    local Guard = tryRequire("Library.Util.GuardAreaLookupUtil")
    local fn = type(Guard) == "table" and (Guard.IsPastLine or Guard.IsInGameplaySide)
    if typeof(line) == "Instance" and type(fn) == "function" then
        local ok, past = pcall(fn, line, hrp.Position)
        if ok and past ~= true then
            return true
        end
    end
    return false
end

local function onBelt()
    local w = G.StealEggWild
    if type(w) == "table" and type(w.isOnBelt) == "function" and w.isOnBelt() == true then
        return true
    end
    return G.__StealEggOnBelt == true
end

local function wildMod()
    local w = G.StealEggWild
    if type(w) == "table" then
        return w
    end
    return nil
end

-- Treadmill is inside the plot box, but sell from the belt gets throttled.
-- Game auto remounts if we still stand on TreadmillBottom after AskDoff.
local function onTreadmillPad()
    local w = wildMod()
    if type(w) == "table" and type(w.isOverTreadmillPad) == "function" then
        local ok, v = pcall(w.isOverTreadmillPad)
        if ok and v == true then
            return true
        end
    end
    return onBelt()
end

-- Pet: Ground / plot / hub, and not on the belt.
-- Egg: inventory remote, any area — no walk, no belt, Steal boleh jalan.
local function canSellHere()
    if onTreadmillPad() then
        return false
    end
    return isOnGround() == true or inLocalPlot() == true or onHubSide() == true
end

local function canSellEggHere()
    return true
end

local function borrowBelt(reason)
    local w = wildMod()
    if type(w) == "table" and type(w.borrowBelt) == "function" then
        local ok, v = pcall(w.borrowBelt, reason)
        return ok == true and v ~= false
    end
    return true
end

local function releaseBelt()
    local w = wildMod()
    if type(w) == "table" and type(w.releaseBelt) == "function" then
        pcall(w.releaseBelt)
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Release) == "function" then
        pcall(d.Release, "sell")
    end
end

local function goOffBelt(shouldRun)
    local w = wildMod()
    if type(w) == "table" and type(w.ensureInPen) == "function" then
        local ok, v = pcall(w.ensureInPen, "sell", shouldRun)
        return ok == true and v ~= false
    end
    return borrowBelt("sell")
end

-- Remote jual milik game ada tiga, dan perannya berbeda tajam:
--   SellSelection { Assets = {uid}, Eggs = {uid} } -> jual pilihan. Ini yang
--       dipakai panel Sell milik game, dan satu-satunya yang menerima daftar
--       kita apa adanya sehingga rule dan cadangan Rift tetap dihormati.
--   SellPet { uid }  -> hanya barang yang sedang dipegang.
--   SellEveryPet     -> ini "sell all" yang sebenarnya: niatnya mengosongkan
--       tas. TIDAK dipakai di sini, sebab sekali jalan ia melanggar rule dan
--       menghabiskan bahan resep Rift.
local function petSatchel(name)
    bindGame()
    local bag = type(Remotes) == "table" and Remotes.PetSatchel
    local rf = type(bag) == "table" and bag[name]
    return typeof(rf) == "Instance" and rf or nil
end

local function sellSelection(kind, uids)
    if type(uids) ~= "table" or #uids == 0 then
        return false, "empty"
    end
    local rf = petSatchel("SellSelection")
    if rf == nil then
        return false, "no SellSelection"
    end
    local payload = kind == "egg"
        and { Assets = {}, Eggs = uids }
        or { Assets = uids, Eggs = {} }
    local ok = pcall(function()
        rf:FireServer(payload)
    end)
    return ok, ok and nil or "fire fail"
end

local function sellHeld(uid)
    local rf = petSatchel("SellPet")
    if rf == nil then
        return false, "no SellPet"
    end
    return pcall(function()
        rf:FireServer({ uid })
    end)
end

local function stillHas(kind, uid)
    local data = getSave()
    local bag = kind == "egg" and (data and data.EggInventory) or (data and data.Inventory)
    if type(bag) ~= "table" then
        return false
    end
    if bag[uid] ~= nil then
        return true
    end
    local s = tostring(uid)
    if bag[s] ~= nil then
        return true
    end
    for k in pairs(bag) do
        if tostring(k) == s then
            return true
        end
    end
    return false
end

local function waitGone(kind, uids, timeout)
    local t0 = os.clock()
    timeout = tonumber(timeout) or 2.2
    while os.clock() - t0 < timeout do
        local left = 0
        for i = 1, #uids do
            if stillHas(kind, uids[i]) then
                left += 1
            end
        end
        if left == 0 then
            return #uids
        end
        task.wait(0.05)
    end
    local gone = 0
    for i = 1, #uids do
        if not stillHas(kind, uids[i]) then
            gone += 1
        end
    end
    return gone
end

local function waitHeld(uid, timeout)
    local t0 = os.clock()
    timeout = tonumber(timeout) or 0.9
    uid = tostring(uid or "")
    while os.clock() - t0 < timeout do
        if tostring(heldUid() or "") == uid then
            return true
        end
        task.wait(0.04)
    end
    return tostring(heldUid() or "") == uid
end

local function equipUid(uid)
    uid = tostring(uid or "")
    if uid == "" then
        return false
    end
    if type(eggCall) == "function" then
        pcall(eggCall, "RequestEquipTool", uid)
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not (char and hum) then
        return waitHeld(uid, 0.8)
    end
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") and tostring(tool:GetAttribute("UID")) == uid then
            return true
        end
    end
    local backpack = LP:FindFirstChild("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA("Tool") and tostring(tool:GetAttribute("UID")) == uid then
                pcall(function()
                    hum:EquipTool(tool)
                end)
                break
            end
        end
    end
    return waitHeld(uid, 0.9)
end

local function unequipIfHeld(uid)
    uid = tostring(uid or "")
    if tostring(heldUid() or "") ~= uid then
        return
    end
    if type(eggCall) == "function" then
        pcall(eggCall, "RequestUnequipTool", uid)
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function sellByEquip(kind, uids)
    local sold = 0
    local lastErr = nil
    for i = 1, #uids do
        if kind ~= "egg" and not canSellHere() then
            lastErr = "left Ground"
            break
        end
        local uid = uids[i]
        if stillHas(kind, uid) then
            local held = heldUid()
            local skip = false
            local protectUid = stealProtectUid()
            if held and held ~= uid then
                if protectUid and held == protectUid then
                    skip = true
                    lastErr = "held other"
                else
                    unequipHeldEgg()
                    held = heldUid()
                    if held and held ~= uid and heldItemType() == "AssetEgg" then
                        if protectUid and held == protectUid then
                            skip = true
                            lastErr = "held other"
                        end
                    end
                end
            end
            if not skip then
                held = heldUid()
                if held ~= uid and not equipUid(uid) then
                    lastErr = "equip fail"
                else
                    sellHeld(uid)
                    if waitGone(kind, { uid }, 1.6) > 0 then
                        sold += 1
                        lastErr = nil
                    else
                        unequipIfHeld(uid)
                        lastErr = "server keep"
                    end
                end
            end
            if i < #uids then
                task.wait(0.08)
            end
        end
    end
    if sold == 0 then
        return 0, lastErr or "server keep"
    end
    return sold, lastErr
end

local function sellChunk(kind, uids)
    if #uids == 0 then
        return 0, "empty"
    end
    -- Satu remote melayani pet maupun telur, dan hanya uid yang sudah lolos rule
    -- serta lolos cadangan Rift yang ikut masuk daftar.
    if sellSelection(kind, uids) == true then
        local gone = waitGone(kind, uids, 1.8)
        if gone > 0 then
            return gone, nil
        end
        -- Server menolak borongannya. Diulang satu-satu supaya penolakan pada
        -- satu barang tidak menahan sisanya yang sah.
        local sold = 0
        for i = 1, #uids do
            if sellSelection(kind, { uids[i] }) == true and waitGone(kind, { uids[i] }, 1.2) > 0 then
                sold += 1
            end
        end
        if sold > 0 then
            return sold, nil
        end
    end
    return sellByEquip(kind, uids)
end

local function sellBatch(kind, items)
    if #items == 0 then
        return 0, "empty"
    end
    if kind == "egg" then
        unequipHeldEgg()
    elseif not canSellHere() then
        return 0, "not on Ground"
    end
    emit(kind, "Selling", "live", "—")
    local uids = {}
    for i = 1, #items do
        uids[i] = items[i].uid
    end
    local chunk = 20
    local sold = 0
    local lastErr = nil
    for i = 1, #uids, chunk do
        if kind ~= "egg" and not canSellHere() then
            lastErr = "left Ground"
            break
        end
        local piece = {}
        for j = i, math.min(i + chunk - 1, #uids) do
            piece[#piece + 1] = uids[j]
        end
        local n, err = sellChunk(kind, piece)
        sold += n
        if n == 0 then
            lastErr = err
            if err == "held other" or err == "left Ground" then
                break
            end
        end
        if i + chunk <= #uids then
            task.wait(0.12)
        end
    end
    if sold == 0 then
        return 0, lastErr or "server keep"
    end
    return sold, lastErr
end

local function waitDelay(kind)
    local st = M[kind]
    local n = tonumber(st and st.delay) or 0.4
    n = math.clamp(n, 0.15, 5)
    task.wait(n)
end

local function unpackAutoState(a, b)
    if type(a) == "table" then
        return a
    end
    if a == true and type(b) == "table" then
        return b
    end
    return nil
end

-- Auto-sell bawaan game (per rarity, dijalankan server saat telur menetas)
-- dikendalikan lewat Haul, bukan lewat nama "Backpack: ..." yang sudah tidak
-- ada. Selama ini panggilannya jatuh ke ruang kosong, jadi pencabutan rarity
-- bahan Rift tidak pernah benar-benar terkirim.
local function haulAutoSell(write, payload)
    bindGame()
    local bag = type(Remotes) == "table" and Remotes.Haul
    local rf = type(bag) == "table" and bag[write and "WriteAutoSell" or "FetchAutoSell"]
    if typeof(rf) ~= "Instance" then
        return nil
    end
    local ok, a, b = pcall(function()
        if write then
            return rf:InvokeServer(payload)
        end
        return rf:InvokeServer()
    end)
    if not ok then
        return nil
    end
    return a, b
end

-- Auto-sell bawaan game bekerja per rarity dan dijalankan server saat telur
-- menetas, jadi pet resep bisa lenyap sebelum shouldKeepPet sempat ditanya.
-- Rarity yang memuat bahan resep Rift dicabut dari daftar; sisanya tetap dijual
-- cepat lewat jalur game.
local function dropRiftRarities(map)
    local rift = G.StealEggRift
    if type(rift) ~= "table" or rift.enabled ~= true or not next(map) then
        return map
    end
    local okReq, reqs = pcall(rift.requirements)
    if okReq ~= true or type(reqs) ~= "table" then
        return map
    end
    for _, cat in ipairs(reqs) do
        local _, id = rarityOf(tostring(cat))
        if id ~= "" then
            map[id] = nil
        end
    end
    return map
end

local function pushHatchAutoSell()
    local sellMode = M.pet.enabled == true
    local map = sellMode and dropRiftRarities(selectedRarityIds(unionRuleRarities(M.pet))) or {}
    if sellMode and not next(map) then
        if hatchPushed then
            haulAutoSell(true, type(savedHatchAuto) == "table" and savedHatchAuto or {})
            hatchPushed = false
            savedHatchAuto = nil
        end
        return
    end
    if sellMode and savedHatchAuto == nil then
        savedHatchAuto = unpackAutoState(haulAutoSell(false)) or {}
    end
    local send = map
    if not sellMode then
        send = type(savedHatchAuto) == "table" and savedHatchAuto or {}
    end
    haulAutoSell(true, send)
    hatchPushed = sellMode
    if M.pet.enabled ~= true then
        savedHatchAuto = nil
        hatchPushed = false
    end
end

local function idleHint(kind)
    if hasMatchRule(M[kind]) then
        return "no match"
    end
    return "set rules first"
end

local function syncFavBeforeSell()
    local fav = G.StealEggFavorite
    if type(fav) ~= "table" then
        return
    end
    if type(fav.flush) == "function" then
        pcall(fav.flush, "fav", 40)
        pcall(fav.flush, "unfav", 40)
    end
end

-- Sell egg/pet jalan sendiri. Tidak menunggu steal idle.
-- Claim dan event tetap menahan, karena keduanya memakai teleport.
local function stealHoldingSell()
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Owner) == "function" then
        local who = d.Owner()
        if who == "claim" or who == "event" then
            return true, who
        end
    end
    return false, nil
end

local function loopKind(kind)
    bindGame()
    local st = M[kind]
    if type(st) ~= "table" then
        return
    end
    local token = st._token
    local label = kind == "egg" and "egg" or "pet"
    while GEN == G.__StealEggSellGen and st.enabled == true and st._token == token do
        if kind == "egg" then
            unequipHeldEgg()
        end
        if kind ~= "egg" then
            syncFavBeforeSell()
        end
        local items = collectKind(kind)
        if #items == 0 then
            emit(kind, "Idle", "muted", idleHint(kind) .. " · sold " .. tostring(st._sold))
            if kind ~= "egg" then
                releaseBelt()
            end
            task.wait(0.8)
        elseif kind == "egg" then
            local held, why = stealHoldingSell()
            if held then
                emit(kind, "Wait", "warn", tostring(why or "busy"))
                task.wait(0.35)
            else
            local idxHold = false
            local idx = G.StealEggIndexComplete
            if type(idx) == "table" then
                if idx._busy == true then
                    idxHold = true
                elseif type(idx.hasPlacePending) == "function" then
                    local okp, pending = pcall(idx.hasPlacePending)
                    idxHold = okp and pending == true
                end
            end
            if idxHold then
                emit(kind, "Wait", "warn", "index")
                task.wait(0.4)
            else
            st._busy = true
            emit(kind, "Selling", "live", string.format("%d %s", #items, label))
            local n, err = sellBatch(kind, items)
            if n > 0 then
                st._sold += n
                emit(kind, "Sold", "success", string.format("+%d · total %d", n, st._sold))
            elseif err == "held other" then
                emit(kind, "Wait hold", "warn", "holding egg")
                task.wait(0.45)
            else
                emit(kind, "Failed", "error", tostring(err or "no sell"))
            end
            st._busy = false
            waitDelay(kind)
            end
            end
        else
            local held, why = stealHoldingSell()
            if held then
                emit(kind, "Wait", "warn", tostring(why or "busy"))
                task.wait(0.35)
            else
            local function stillSell()
                return GEN == G.__StealEggSellGen and st.enabled == true and st._token == token
            end
            if onBelt() or not canSellHere() then
                emit(kind, "Going", "live", "plot")
                goOffBelt(stillSell)
            end
            if not stillSell() then
                break
            end
            if onBelt() or not canSellHere() then
                emit(kind, "Wait", "warn", "need plot")
                task.wait(0.35)
            else
                st._busy = true
                emit(kind, "Selling", "live", string.format("%d %s", #items, label))
                local n, err = sellBatch(kind, items)
                if n > 0 then
                    st._sold += n
                    emit(kind, "Sold", "success", string.format("+%d · total %d", n, st._sold))
                elseif err == "held other" then
                    emit(kind, "Wait hold", "warn", "holding egg")
                    task.wait(0.45)
                elseif err == "on treadmill" then
                    emit(kind, "Wait", "warn", "on treadmill")
                elseif err == "not on Ground" or err == "left Ground" then
                    emit(kind, "Wait plot", "warn", "need plot")
                else
                    emit(kind, "Failed", "error", tostring(err or "no sell"))
                end
                st._busy = false
                waitDelay(kind)
            end
            end
        end
    end
    if st._token == token and st.enabled ~= true then
        emit(kind, "Idle", "muted", "sold " .. tostring(st._sold))
    end
    if M.pet.enabled ~= true and M.egg.enabled ~= true then
        releaseBelt()
    end
end

local function startKind(kind)
    local st = M[kind]
    st._token = (tonumber(st._token) or 0) + 1
    local token = st._token
    if st.enabled ~= true then
        st._loopOn = false
        return
    end
    st._loopOn = true
    task.spawn(function()
        loopKind(kind)
        if st._token == token then
            st._busy = false
            st._loopOn = false
        end
    end)
end

-- Dipanggil Auto Rift ketika resepnya berganti: rarity bahan yang baru harus
-- dicabut dari auto-sell bawaan game, dan rarity lama boleh dipakai lagi.
function M.refreshHatchAutoSell()
    pcall(pushHatchAutoSell)
end

function M.setPetEnabled(on)
    on = on == true
    if on then
        if M.pet.enabled == true and M.pet._loopOn == true then
            pcall(pushHatchAutoSell)
            return
        end
        M.pet.enabled = true
        pcall(pushHatchAutoSell)
        emit("pet", "On", "live", "scanning")
        startKind("pet")
        return
    end
    M.pet.enabled = false
    M.pet._loopOn = false
    M.pet._token = (tonumber(M.pet._token) or 0) + 1
    pcall(pushHatchAutoSell)
    if M.pet._status.text ~= "Sold" then
        emit("pet", "Idle", "muted", "sold " .. tostring(M.pet._sold))
    end
end

function M.setEggEnabled(on)
    on = on == true
    if on then
        if M.egg.enabled == true and M.egg._loopOn == true then
            return
        end
        M.egg.enabled = true
        emit("egg", "On", "live", "scanning")
        startKind("egg")
        return
    end
    M.egg.enabled = false
    M.egg._loopOn = false
    M.egg._token = (tonumber(M.egg._token) or 0) + 1
    if M.egg._status.text ~= "Sold" then
        emit("egg", "Idle", "muted", "sold " .. tostring(M.egg._sold))
    end
end

function M.setEnabled(on)
    M.setPetEnabled(on)
    M.setEggEnabled(on)
end

function M.Stop()
    M.setPetEnabled(false)
    M.setEggEnabled(false)
end

function M.sellPetsNow()
    if onBelt() or not canSellHere() then
        goOffBelt()
    end
    if onBelt() or not canSellHere() then
        emit("pet", "Wait", "warn", "need plot")
        releaseBelt()
        return 0, "ground"
    end
    local items = collectPets()
    if #items == 0 then
        emit("pet", "Idle", "warn", idleHint("pet"))
        releaseBelt()
        return 0, "empty"
    end
    emit("pet", "Selling", "live", tostring(#items) .. " pet")
    local n, err = sellBatch("pet", items)
    releaseBelt()
    if n > 0 then
        M.pet._sold += n
        emit("pet", "Sold", "success", string.format("+%d · total %d", n, M.pet._sold))
    else
        emit("pet", "Failed", "error", tostring(err or "no sell"))
    end
    return n, err
end

function M.sellEggsNow()
    unequipHeldEgg()
    local items = collectEggs()
    if #items == 0 then
        emit("egg", "Idle", "warn", idleHint("egg"))
        return 0, "empty"
    end
    emit("egg", "Selling", "live", tostring(#items) .. " egg")
    local n, err = sellBatch("egg", items)
    if n > 0 then
        M.egg._sold += n
        emit("egg", "Sold", "success", string.format("+%d · total %d", n, M.egg._sold))
    else
        emit("egg", "Failed", "error", tostring(err or "no sell"))
    end
    return n, err
end

local function inventoryNameItems(kind)
    bindGame()
    local seen = {}
    local items = {}
    local data = getSave()
    local bag = kind == "egg" and (data and data.EggInventory) or (data and data.Inventory)
    if type(bag) == "table" then
        for _, raw in pairs(bag) do
            local category
            if kind == "egg" then
                local egg = eggRecord(raw)
                category = egg and egg.AssetCategory
            else
                local item = deserializePet(raw)
                category = item and item.Category
            end
            category = tostring(category or "")
            if category ~= "" and not seen[category] then
                seen[category] = true
                local num, rarityId, name = rarityOf(category)
                local label = name
                if rarityId ~= "" then
                    label = name .. " · " .. rarityId
                elseif num > 0 then
                    label = name .. " · " .. tostring(num)
                end
                items[#items + 1] = { key = category, name = label, sort = num }
            end
        end
    end
    local catItems = Core.listEggItems()
    if type(catItems) == "table" then
        for _, egg in ipairs(catItems) do
            local key = tostring(egg.key or "")
            if key ~= "" and not seen[key] then
                seen[key] = true
                items[#items + 1] = { key = key, name = egg.name, sort = Core.eggRarityNumber(key) }
            end
        end
    end
    table.sort(items, function(a, b)
        if a.sort == b.sort then
            return tostring(a.name) < tostring(b.name)
        end
        return (tonumber(a.sort) or 0) < (tonumber(b.sort) or 0)
    end)
    return items
end

function M.listPetItems()
    return inventoryNameItems("pet")
end

function M.listEggItems()
    return inventoryNameItems("egg")
end

function M.listMutationItems()
    Mutations = Mutations or tryRequire("Library.Modules.Mutations")
    local items, seen = {}, {}
    local function add(name, label)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        items[#items + 1] = { key = name, name = tostring(label or name) }
    end
    if type(Mutations) == "table" then
        local listFn = Mutations.GetMutations or Mutations.All
        if type(listFn) == "function" then
            local ok, list = pcall(listFn)
            if ok and type(list) == "table" then
                for key, info in pairs(list) do
                    if type(info) == "table" then
                        local name = info.Id or info.Name or info._id or key
                        local label = ""
                        if type(info.Label) == "string" and info.Label ~= "" then
                            label = info.Label
                        elseif type(info.DisplayOverride) == "string" and info.DisplayOverride ~= "" then
                            label = info.DisplayOverride
                        end
                        if label == "" and type(Core.mutationLabel) == "function" then
                            label = Core.mutationLabel(name)
                        end
                        add(name, label ~= "" and label or name)
                    elseif type(key) == "string" then
                        add(key, key)
                    end
                end
            end
        end
        if #items == 0 then
            local names = Mutations.MutationNames or Mutations.IdSet
            if type(names) == "table" then
                for name in pairs(names) do
                    add(name, name)
                end
            end
        end
    end
    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    table.insert(items, 1, { key = NO_MUTATION, name = NO_MUTATION })
    return items
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    local units = {
        { 1e33, "Dc" },
        { 1e30, "No" },
        { 1e27, "Oc" },
        { 1e24, "Sp" },
        { 1e21, "Sx" },
        { 1e18, "Qi" },
        { 1e15, "Qa" },
        { 1e12, "T" },
        { 1e9, "B" },
        { 1e6, "M" },
        { 1e3, "k" },
    }
    for _, u in ipairs(units) do
        if abs >= u[1] then
            return string.format("%.1f%s", n / u[1], u[2])
        end
    end
    if abs >= 10 or n == math.floor(n) then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

local function fmtKg(n)
    n = tonumber(n) or 0
    if n >= 10 then
        return string.format("%.0fkg", n)
    end
    return string.format("%.1fkg", n)
end

local function rarityName(key)
    key = tostring(key or "")
    for _, item in ipairs(Core.RARITY_ITEMS) do
        if tostring(item.key) == key then
            local name = tostring(item.name or key)
            local pretty = name:match("·%s*(.+)$")
            return pretty or name
        end
    end
    return key
end

local function joinNames(keys, lookup, limit)
    limit = tonumber(limit) or 2
    if type(keys) ~= "table" or #keys == 0 then
        return nil
    end
    if #keys > limit then
        return tostring(#keys)
    end
    local names = {}
    for i, key in ipairs(keys) do
        names[i] = lookup and lookup(key) or key
    end
    return table.concat(names, ", ")
end

local function formatRule(kind, rule)
    rule = sanitizeRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    local nameKeys = mapKeyList(rule.names)
    local rarityKeys = mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = mapKeyList(rule.mutations)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            name = #nameKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = price > 0,
            mutation = #mutKeys > 0,
        }
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(joinNames(rarityKeys, rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.name then
        local label = kind == "egg" and "eggs" or "pets"
        if #nameKeys == 0 then
            add("All " .. label, "fruit")
        elseif #nameKeys > 2 then
            add(tostring(#nameKeys) .. " " .. label, "fruit")
        else
            add(joinNames(nameKeys, displayOf), "fruit")
        end
    end
    if fields.kg then
        if kg > 0 then
            if rule.kgMode == "below" then
                add("below " .. fmtKg(kg), "kg")
            else
                add("above " .. fmtKg(kg), "kg")
            end
        else
            add("Any kg", "kg")
        end
    end
    if fields.price then
        if price > 0 then
            if rule.priceMode == "below" then
                add("below $" .. fmtNum(price), "price")
            else
                add("above $" .. fmtNum(price), "price")
            end
        else
            add("Any $", "price")
        end
    end
    if fields.rate then
        if rate > 0 then
            if rule.rateMode == "below" then
                add("below " .. fmtNum(rate) .. "/s", "price")
            else
                add("above " .. fmtNum(rate) .. "/s", "price")
            end
        else
            add("Any earn", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            add("Any mut", "mut")
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = isNoMutationKey(key) and "Normal" or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    if #parts == 0 then
        add("Any " .. (kind == "egg" and "egg" or "pet"), "default")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    for _, kind in ipairs({ "pet", "egg" }) do
        local st = M[kind]
        local prefix = "steal.sell." .. kind
        if type(values[prefix .. ".rules"]) == "table" then
            setKindRules(kind, values[prefix .. ".rules"])
        end
        if values[prefix .. ".draft.rarity"] ~= nil then
            st.draft.rarities = parseKeyMap(values[prefix .. ".draft.rarity"])
        end
        if values[prefix .. ".draft.names"] ~= nil then
            st.draft.names = parseKeyMap(values[prefix .. ".draft.names"])
        end
        if values[prefix .. ".draft.mutations"] ~= nil then
            st.draft.mutations = parseKeyMap(values[prefix .. ".draft.mutations"])
        end
        if values[prefix .. ".draft.kgRule"] ~= nil then
            local kg, kgMode, kgRule = parseSignedRule(values[prefix .. ".draft.kgRule"], values[prefix .. ".draft.kgMode"])
            st.draft.kgRule = kgRule
            st.draft.kgMode = clampCompareMode(values[prefix .. ".draft.kgMode"] or kgMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.kgMode"] ~= nil then
            st.draft.kgMode = clampCompareMode(values[prefix .. ".draft.kgMode"], DEFAULT_COMPARE_MODE)
        end
        if values[prefix .. ".draft.rateRule"] ~= nil then
            local rate, rateMode, rateRule = parseSignedScaledRule(values[prefix .. ".draft.rateRule"], values[prefix .. ".draft.rateMode"])
            st.draft.rateRule = rateRule
            st.draft.rateMode = clampCompareMode(values[prefix .. ".draft.rateMode"] or rateMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.rateMode"] ~= nil then
            st.draft.rateMode = clampCompareMode(values[prefix .. ".draft.rateMode"], DEFAULT_COMPARE_MODE)
        end
        if values[prefix .. ".draft.priceRule"] ~= nil then
            local price, priceMode, priceRule = parseSignedScaledRule(values[prefix .. ".draft.priceRule"], values[prefix .. ".draft.priceMode"])
            st.draft.priceRule = priceRule
            st.draft.priceMode = clampCompareMode(values[prefix .. ".draft.priceMode"] or priceMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.priceMode"] ~= nil then
            st.draft.priceMode = clampCompareMode(values[prefix .. ".draft.priceMode"], DEFAULT_COMPARE_MODE)
        end
        local delay = tonumber(values[prefix .. ".delay"])
        if delay then
            st.delay = math.clamp(delay, 0.15, 5)
        end
        if values[prefix .. ".keepCount"] ~= nil then
            st.keepCount = clampKeepCount(values[prefix .. ".keepCount"])
        end
    end
    if values["steal.sell.pet.enabled"] ~= nil then
        M.setPetEnabled(Core.flagOn(values["steal.sell.pet.enabled"]))
    end
    if values["steal.sell.egg.enabled"] ~= nil then
        M.setEggEnabled(Core.flagOn(values["steal.sell.egg.enabled"]))
    end
end

local function registerKindSection(ui, kind, title)
    local st = M[kind]
