local function publicHatchDetail(text, detail)
    detail = tostring(detail or "")
    if detail == "" or detail == "—" or detail == "off" or detail == "auto hatch" then
        return "—"
    end
    local low = string.lower(detail)
    if string.find(low, "full", 1, true) or string.find(low, "too many", 1, true) or string.find(low, "many egg", 1, true) then
        return "plot full"
    end
    if string.find(low, "uid", 1, true) or string.find(low, "cframe", 1, true)
        or string.find(low, "remote", 1, true) or string.find(low, "invoke", 1, true) then
        return "—"
    end
    if text == "Idle" then
        if string.find(low, "no match", 1, true) then
            return "no match"
        end
        if string.find(low, "kosong", 1, true) or string.find(low, "empty", 1, true) then
            return "empty"
        end
        if string.find(low, "growing", 1, true) then
            return detail
        end
        if string.find(low, "hatched", 1, true) or string.find(low, "placed", 1, true) then
            return detail
        end
        if string.find(low, "ready", 1, true) then
            return "waiting"
        end
        return "—"
    end
    if text == "Denied" or text == "Error" then
        if string.find(low, "plot", 1, true) or string.find(low, "cannot place", 1, true) then
            return "need plot"
        end
        if string.find(low, "carry", 1, true) then
            return "carry"
        end
        if #detail <= 28 then
            return detail
        end
        return "—"
    end
    if #detail > 28 then
        local name = string.match(detail, "^%s*([^·]+)")
        name = name and (string.gsub(name, "%s+$", "")) or ""
        if name ~= "" and #name <= 28 then
            return name
        end
        return "—"
    end
    return detail
end

local function emit(text, style, detail)
    local rawText = tostring(text or "Idle")
    local pubText = rawText
    if rawText == "Denied" or rawText == "Error" then
        pubText = "Failed"
    end
    M._status = {
        text = pubText,
        style = style or "muted",
        detail = publicHatchDetail(rawText, detail),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setPlaceStatusListener(fn)
    M._onPlaceStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._placeStatus)
    end
end

local PLACE_DBG_DIR = (type(G.__StealEggSaveDir) == "string" and G.__StealEggSaveDir ~= "" and G.__StealEggSaveDir) or "NodeStealEgg"
local PLACE_DBG_FILE = PLACE_DBG_DIR .. "/place_debug.txt"
local placeDbgLogs = {}
local placeDbgSeq = 0
local placeDbgLast = 0

local function placeDbgSave()
    if typeof(writefile) ~= "function" then
        return
    end
    if os.clock() - placeDbgLast < 0.1 then
        return
    end
    placeDbgLast = os.clock()
    if type(makefolder) == "function" then
        pcall(makefolder, PLACE_DBG_DIR)
    end
    pcall(writefile, PLACE_DBG_FILE, table.concat(placeDbgLogs, "\n") .. "\n")
end

local function placeDbg(tag, msg)
    if G.__StealEggMoveDebug ~= true then
        return
    end
    placeDbgSeq += 1
    local line = string.format("[%0.3f #%d][%s] %s", os.clock(), placeDbgSeq, tostring(tag or "?"), tostring(msg or ""))
    local n = #placeDbgLogs
    if n >= 1200 then
        placeDbgLogs[1 + ((placeDbgSeq - 1) % 1200)] = line
    else
        placeDbgLogs[n + 1] = line
    end
    pcall(print, "[PLACE] " .. line)
    placeDbgSave()
    local fn = G.StealEggDbg
    if type(fn) == "function" then
        pcall(fn, "PLACE", tostring(tag or "?") .. " " .. tostring(msg or ""))
    end
end

G.StealEggPlaceDbg = placeDbg

local function v3s(p)
    if typeof(p) ~= "Vector3" then
        return "-"
    end
    return string.format("%.1f,%.1f,%.1f", p.X, p.Y, p.Z)
end

local lastPlaceDbgKey = ""
local lastPlaceDbgAt = 0

local function emitPlace(text, style, detail)
    local rawText = tostring(text or "Idle")
    local pubText = rawText
    if rawText == "Denied" or rawText == "Error" or rawText == "Failed" then
        pubText = "Wait"
    end
    local det = publicHatchDetail(rawText, detail)
    M._placeStatus = {
        text = pubText,
        style = style or "muted",
        detail = det,
    }
    -- Idle/Wait spam nenggelamkan steal_move_track (GOTO/SNAP hilang).
    local key = pubText .. "\0" .. tostring(det)
    local now = os.clock()
    local quietIdle = pubText == "Idle" or pubText == "Wait"
    local quiet = quietIdle and key == lastPlaceDbgKey and (now - lastPlaceDbgAt) < 12
    if quiet ~= true then
        lastPlaceDbgKey = key
        lastPlaceDbgAt = now
        placeDbg("status", pubText .. " · " .. tostring(det))
    end
    local fn = M._onPlaceStatus
    if type(fn) == "function" then
        pcall(fn, M._placeStatus)
    end
end

local function syncWildPlace(on)
    local Wild = G.StealEggWild
    if type(Wild) == "table" then
        Wild.place = on == true
    end
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    if abs >= 1e9 then
        return string.format("%.1fB", n / 1e9)
    end
    if abs >= 1e6 then
        return string.format("%.1fM", n / 1e6)
    end
    if abs >= 1e3 then
        return string.format("%.1fk", n / 1e3)
    end
    if abs >= 10 or n == math.floor(n) then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

local function fmtKg(n)
    n = tonumber(n) or 0
    if n >= 10 then
        return string.format("%.0fkg", n)
    end
    return string.format("%.1fkg", n)
end

local function fmtPrice(n)
    n = tonumber(n) or 0
    if n <= 0 then
        return "$0"
    end
    return "$" .. fmtNum(n)
end

local function fmtRate(n)
    return fmtNum(tonumber(n) or 0) .. "/s"
end

local function fmtDuration(sec)
    sec = tonumber(sec) or 0
    if sec <= 0 then
        return "Ready"
    end
    if type(FormatDurationSymbol) == "function" then
        local ok, text = pcall(FormatDurationSymbol, sec)
        if ok and type(text) == "string" and text ~= "" then
            return text
        end
    end
    sec = math.floor(sec + 0.5)
    local h = math.floor(sec / 3600)
    local m = math.floor((sec % 3600) / 60)
    local s = sec % 60
    if h > 0 then
        return string.format("%dh %dm", h, m)
    end
    if m > 0 then
        return string.format("%dm %ds", m, s)
    end
    return string.format("%ds", s)
end

local function mutLabel(muts)
    if type(muts) ~= "table" or #muts == 0 then
        return "Normal"
    end
    local names = {}
    for i, name in ipairs(muts) do
        names[i] = (type(Core.mutationLabel) == "function" and Core.mutationLabel(name)) or tostring(name)
    end
    if #names == 1 then
        return names[1]
    end
    return table.concat(names, "+")
end

local function describeEgg(rec)
    rec = type(rec) == "table" and rec or {}
    local WildEgg = G.StealEggWild
    if type(WildEgg) == "table" and type(WildEgg.describeRecord) == "function" then
        local ok, desc = pcall(WildEgg.describeRecord, rec)
        if ok and type(desc) == "table" then
            desc.uid = rec.Uid or rec.uid or desc.uid
            return desc
        end
    end
        local category = tostring(rec.AssetCategory or rec.category or "")
        local cat = Core.getCatalog and Core.getCatalog() or nil
        local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[category]
    return {
            category = category,
            name = (type(item) == "table" and item.name) or category,
            rarity = (type(item) == "table" and item.rarity) or "",
            rarityNum = (type(item) == "table" and tonumber(item.rarityNumber)) or 0,
            kg = 0,
            rate = 0,
        price = 0,
            muts = {},
        uid = rec.Uid or rec.uid,
    }
end

local NO_MUTATION = "No Mutation"
local DEFAULT_COMPARE_MODE = "above"
local COMPARE_ITEMS = {
    { key = "above", name = "Above" },
    { key = "below", name = "Below" },
}

local function newPlaceDraft()
    return {
        rarities = {},
        eggs = {},
        mutations = {},
        kgRule = "0",
        kgMode = DEFAULT_COMPARE_MODE,
        rateRule = "0",
        rateMode = DEFAULT_COMPARE_MODE,
        priceRule = "0",
        priceMode = DEFAULT_COMPARE_MODE,
    }
end

local function mapHas(map)
    return type(map) == "table" and next(map) ~= nil
end

local function copyMap(value)
    return parseKeyMap(value)
end

local function mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function newRuleId()
    return "pr" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

local function clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or ""))
    if fallback == "below" then
        return "below"
    end
    return "above"
end

local function unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

local function wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

local function parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(txt)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(txt)
end

local function parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), (raw == "" and "0" or unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(raw)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(raw)
end

local function isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

local function sanitizePlaceRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = parseSignedRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "rarity", "egg", "mutation", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        rarities = copyMap(rule.rarities),
        eggs = copyMap(rule.eggs or rule.names),
        mutations = copyMap(rule.mutations),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
    }
end

local function sanitizePlaceRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = sanitizePlaceRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

function M.setPlaceRules(list)
    M.placeRules = sanitizePlaceRules(list)
    return M.placeRules
end

local function enabledPlaceRules()
    local out = {}
    for _, rule in ipairs(M.placeRules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    return out
end

local function ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

local function matchesEggs(category, eggs)
    if not mapHas(eggs) then
        return true
    end
    category = tostring(category or "")
    return eggs[category] == true or eggs[string.lower(category)] == true
end

local function matchesRarity(rarityNum, rarityId, rarities)
    if not mapHas(rarities) then
        return true
    end
    rarityNum = tonumber(rarityNum) or 0
    rarityId = tostring(rarityId or "")
    return rarities[tostring(rarityNum)] == true
        or rarities[rarityId] == true
        or rarities[string.lower(rarityId)] == true
end

local function matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "below" then
        return value <= n
    end
    return value >= n
end

local function matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if not mapHas(selected) then
        return true
    end
    local wantNone = false
    local hasPick = false
    for key, on in pairs(selected) do
        if on == true then
            if isNoMutationKey(key) then
                wantNone = true
            else
                hasPick = true
            end
        end
    end
    if wantNone and not hasPick then
        return not has
    end
        if hasPick then
            for i = 1, #names do
                local name = names[i]
                if type(Core.mutationPicked) == "function" then
                    if Core.mutationPicked(name, selected) then
                        return true
                    end
                elseif selected[name] == true or selected[string.lower(tostring(name))] == true then
                    return true
                end
            end
        if wantNone and not has then
            return true
        end
        return false
    end
    return true
end

local function placeRuleMatches(rule, info)
    if type(rule) ~= "table" or type(info) ~= "table" then
        return false
    end
    if ruleFieldOn(rule, "egg") and not matchesEggs(info.category, rule.eggs) then
        return false
    end
    if ruleFieldOn(rule, "rarity") and not matchesRarity(info.rarityNum, info.rarity, rule.rarities) then
        return false
    end
    if ruleFieldOn(rule, "kg") and not matchesSigned(info.kg, rule.kg, rule.kgMode) then
        return false
    end
    if ruleFieldOn(rule, "rate") and not matchesSigned(info.rate, rule.rate, rule.rateMode) then
        return false
    end
    if ruleFieldOn(rule, "price") and not matchesSigned(info.price, rule.price, rule.priceMode) then
        return false
    end
    if ruleFieldOn(rule, "mutation") and not matchesMutation(info.muts, rule) then
        return false
    end
    return true
end

function M.placeAllowed(info)
    info = type(info) == "table" and info or {}
    local rules = enabledPlaceRules()
    if #rules == 0 then
        return true
    end
    info = type(info) == "table" and info or {}
    for _, rule in ipairs(rules) do
        if placeRuleMatches(rule, info) then
            return true
        end
    end
    return false
end

local function joinNames(keys, lookup)
    local names = {}
    for i, key in ipairs(keys) do
        names[i] = lookup and lookup(key) or key
    end
    if #names > 2 then
        return tostring(#names)
    end
    return table.concat(names, ", ")
end

local function rarityName(key)
    for _, item in ipairs(Core.RARITY_ITEMS or {}) do
        if tostring(item.key) == tostring(key) then
            return item.name
        end
    end
    return tostring(key)
end

local function eggNameOf(key)
    local cat = Core.getCatalog and Core.getCatalog() or nil
    local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[tostring(key)]
    if type(item) == "table" then
        return tostring(item.name or key)
    end
    return tostring(key)
end

function M.formatPlaceRule(rule)
    rule = sanitizePlaceRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    local eggKeys = mapKeyList(rule.eggs)
    local rarityKeys = mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = mapKeyList(rule.mutations)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            egg = #eggKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = price > 0,
            mutation = #mutKeys > 0,
        }
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(joinNames(rarityKeys, rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.egg then
        if #eggKeys == 0 then
            add("All eggs", "fruit")
        elseif #eggKeys > 2 then
            add(tostring(#eggKeys) .. " eggs", "fruit")
        else
            add(joinNames(eggKeys, eggNameOf), "fruit")
        end
    end
    if fields.kg then
        if kg > 0 then
            if rule.kgMode == "below" then
                add("<=" .. fmtKg(kg), "kg")
            else
                add(">=" .. fmtKg(kg), "kg")
            end
        else
            add("Any kg", "kg")
        end
    end
    if fields.price then
        if price > 0 then
            if rule.priceMode == "below" then
                add("$<=" .. fmtNum(price), "price")
            else
                add("$>=" .. fmtNum(price), "price")
            end
        else
            add("Any $", "price")
        end
    end
    if fields.rate then
        if rate > 0 then
            if rule.rateMode == "below" then
                add("earn <=" .. fmtNum(rate) .. "/s", "price")
            else
                add("earn >=" .. fmtNum(rate) .. "/s", "price")
            end
        else
            add("Any earn", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            add("Any mut", "mut")
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = isNoMutationKey(key) and "Normal" or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    if #parts == 0 then
        add("All eggs", "default")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

function M.placeIdleDetail()
    local fromServer = M._placeMaxFromServer == true or G.__StealEggPlaceMaxFromServer == true
    local cap = fromServer and (tonumber(M._placeMax) or tonumber(G.__StealEggPlaceMax)) or nil
    local n = tonumber(M._plotEggs)
    if type(n) ~= "number" then
        n = tonumber(M._placed) or 0
    end
    if type(cap) == "number" and cap > 0 then
        return tostring(n) .. "/" .. tostring(cap)
    end
    if n > 0 then
        return tostring(n) .. " on plot"
    end
    return "—"
end

local function listPlaceEggItems()
    if type(Core.listEggItems) == "function" then
        return Core.listEggItems({})
    end
    return {}
end

local function listPlaceMutationItems()
    local Wild = G.StealEggWild
    if type(Wild) == "table" and type(Wild.listMutationItems) == "function" then
        local ok, items = pcall(Wild.listMutationItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    local Sell = G.StealEggSell
    if type(Sell) == "table" and type(Sell.listMutationItems) == "function" then
        local ok, items = pcall(Sell.listMutationItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    return { { key = NO_MUTATION, name = NO_MUTATION } }
end

local function growthSpeed(rec)
    local n = tonumber(rec and rec.GrowthSpeedMultiplier)
    if n and n > 0 then
        return n
    end
    return 1
end

local function nightCredit(rec, now)
    if type(EggItemUtil) ~= "table" or type(EggItemUtil.GetCurrentNightGrowthCreditSeconds) ~= "function" then
        return 0
    end
    local ok, n = pcall(EggItemUtil.GetCurrentNightGrowthCreditSeconds, rec, now, growthSpeed(rec))
    if ok then
        return tonumber(n) or 0
    end
    return 0
end

local function growthAlpha(rec)
    if type(rec) ~= "table" or type(rec.Placement) ~= "table" then
        return 0
    end
    if rec.Placement.ReadyAt ~= nil then
        return 1
    end
    local now = Workspace:GetServerTimeNow()
    if type(EggItemUtil) == "table" and type(EggItemUtil.GetGrowthAlpha) == "function" then
        local ok, n = pcall(EggItemUtil.GetGrowthAlpha, rec, now, growthSpeed(rec), nightCredit(rec, now), LP)
        if ok then
            return math.clamp(tonumber(n) or 0, 0, 1)
        end
    end
    return 0
end

local function remainingSeconds(rec)
    if type(rec) ~= "table" or type(rec.Placement) ~= "table" then
        return 0
    end
    if rec.Placement.ReadyAt ~= nil or growthAlpha(rec) >= 1 then
        return 0
    end
    local now = Workspace:GetServerTimeNow()
    if type(EggItemUtil) == "table" and type(EggItemUtil.GetRemainingGrowthSeconds) == "function" then
        local ok, n = pcall(EggItemUtil.GetRemainingGrowthSeconds, rec, now, growthSpeed(rec), nightCredit(rec, now), LP)
        if ok then
            return math.max(0, tonumber(n) or 0)
        end
    end
    return 0
end

-- Game dump: ReadyAt set + GetGrowthAlpha >= 1. Don't hatch while still growing.
local function eggIsReady(rec)
    if type(rec) ~= "table" or type(rec.Placement) ~= "table" then
        return false
    end
    local uid = tostring(rec.Uid or "")
    if uid ~= "" and type(EggCmds) == "table" and type(EggCmds.IsLocalEggReady) == "function" then
        local ok, v = pcall(EggCmds.IsLocalEggReady, uid)
        if ok then
            return v == true
        end
    end
    if type(EggItemUtil) == "table" and type(EggItemUtil.IsGrowthReady) == "function" then
        local now = Workspace:GetServerTimeNow()
        local ok, v = pcall(EggItemUtil.IsGrowthReady, rec, now, growthSpeed(rec), nightCredit(rec, now), LP)
        if ok then
            return v == true
        end
    end
    if rec.Placement.ReadyAt ~= nil then
        return true
    end
    return growthAlpha(rec) >= 1
end

local function collectPlaced(map, out)
    if type(map) ~= "table" then
        return
    end
    local seen = {}
    for i = 1, #out do
        local rec = out[i]
        local id = type(rec) == "table" and tostring(rec.Uid or "") or ""
        if id ~= "" then
            seen[id] = true
        end
    end
    for uid, rec in pairs(map) do
        if type(rec) == "table" and type(rec.Placement) == "table" then
            -- Jangan tulis rec.Uid: Save/runtime egg sering frozen.
            -- Bungkus supaya hatch tetap dapat uid (tanpa ini Open Egg = no uid).
            local id = tostring((type(rec.Uid) == "string" and rec.Uid ~= "" and rec.Uid) or uid)
            if seen[id] ~= true then
                seen[id] = true
                out[#out + 1] = setmetatable({ Uid = id }, { __index = rec })
            end
        end
    end
end

local lastOwnerSync = 0
local placedCache, placedCacheAt = nil, 0
local unplacedCache, unplacedCacheAt = nil, 0
local pendingCache, pendingCacheAt, pendingCacheVal = nil, 0, false
local PLACED_CACHE_SEC = 0.25
local UNPLACED_CACHE_SEC = 0.35
local PENDING_CACHE_SEC = 0.4

local function invalidatePlaceCaches()
    placedCache = nil
    placedCacheAt = 0
    unplacedCache = nil
    unplacedCacheAt = 0
    pendingCache = nil
    pendingCacheAt = 0
    M._plotList = nil
end

local function placedRecords(force)
    if force ~= true and type(placedCache) == "table" and (os.clock() - placedCacheAt) < PLACED_CACHE_SEC then
        return placedCache
    end
    local out = {}
    local ok, map = eggCall("GetOwnerRuntimeRecords", LP.UserId)
    if ok then
        collectPlaced(map, out)
    end
    if #out == 0 and os.clock() - lastOwnerSync >= 12 then
        lastOwnerSync = os.clock()
        eggCall("RequestRuntimeSnapshot")
        ok, map = eggCall("GetOwnerRuntimeRecords", LP.UserId)
        if ok then
            collectPlaced(map, out)
        end
    end
    -- Selalu gabung Save: runtime kadang bolong (Boost FPS / snapshot)
    -- → grid mengira masih ada lubang → Place Light Dove diulang di tengah plot.
    if type(Save) == "table" and type(Save.Get) == "function" then
        local okS, data = pcall(Save.Get)
        if not (okS and type(data) == "table") then
            okS, data = pcall(Save.Get, LP, true)
        end
        if okS and type(data) == "table" then
            collectPlaced(data.EggInventory, out)
        end
    end
    placedCache = out
    placedCacheAt = os.clock()
    return out
end

local function plotLevel()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return 0
    end
    local ok, data = pcall(Save.Get)
    if ok and type(data) == "table" then
        return tonumber(data.BaseUpgradeLevel) or 0
    end
    return 0
end

local function clearPlaceMax()
    M._placeMax = nil
    M._placeMaxLv = nil
    M._placeMaxFromServer = nil
    G.__StealEggPlaceMax = nil
    G.__StealEggPlaceMaxLv = nil
    G.__StealEggPlaceMaxFromServer = nil
end

function M.rememberPlaceMax()
    -- Server-only: "You have too many eggs placed!". Never freeze current count
    -- just because the client grid ran out (that is what made Full · 4/4).
    local n = #placedRecords()
    M._plotEggs = n
    if n < 1 then
        return n
    end
    local lv = plotLevel()
    M._placeMax = n
    M._placeMaxLv = lv
    M._placeMaxFromServer = true
    G.__StealEggPlaceMax = n
    G.__StealEggPlaceMaxLv = lv
    G.__StealEggPlaceMaxFromServer = true
    return n
end

function M.placeCap()
    local fromServer = M._placeMaxFromServer == true or G.__StealEggPlaceMaxFromServer == true
    if fromServer ~= true then
        clearPlaceMax()
        return nil
    end
    local cap = tonumber(M._placeMax) or tonumber(G.__StealEggPlaceMax)
    local savedLv = tonumber(M._placeMaxLv) or tonumber(G.__StealEggPlaceMaxLv) or 0
    local lv = plotLevel()
    if type(cap) == "number" and lv > savedLv then
        clearPlaceMax()
        return nil
    end
    if type(cap) == "number" then
        M._placeMax = cap
        M._placeMaxLv = savedLv
        M._placeMaxFromServer = true
        G.__StealEggPlaceMax = cap
        G.__StealEggPlaceMaxLv = savedLv
        G.__StealEggPlaceMaxFromServer = true
    end
    return cap
end

function M.plotAtCap()
    bindGame()
    local n = #placedRecords()
    M._plotEggs = n
    local cap = M.placeCap()
    if type(cap) == "number" and cap >= 1 then
        return n >= cap, n, cap
    end
    -- Jangan nextPlaceCFrame / gridCapacity tiap tick idle — itu spike CPU.
    if type(M._geomFullUntil) == "number" and os.clock() < M._geomFullUntil then
        return true, n, tonumber(M._geomFullN) or n
    end
    return false, n, cap
end

local function enrich(rec)
    local info = describeEgg(rec)
    local alpha = growthAlpha(rec)
    local remain = remainingSeconds(rec)
    local ready = eggIsReady(rec)
    info.uid = tostring(rec.Uid or info.uid or "")
    info.alpha = alpha
    info.remain = remain
    info.ready = ready == true
    if info.ready then
        info.timeText = "Ready"
    elseif remain > 0 then
        info.timeText = fmtDuration(remain)
    else
        info.timeText = tostring(math.floor(math.clamp(alpha, 0, 1) * 100)) .. "%"
    end
    info.pct = math.floor(math.clamp(alpha, 0, 1) * 100)
    return info
end

function M.listPlotEggs()
    if type(M._plotList) == "table" and os.clock() - (M._plotListAt or 0) < 2.4 then
        return M._plotList
    end
    bindGame()
    local eggs = {}
    local ready, growing, totalPrice, totalRate, nextRemain = 0, 0, 0, 0, nil
    local mutTotals = {}
    for _, rec in ipairs(placedRecords()) do
        local info = enrich(rec)
        eggs[#eggs + 1] = info
        totalPrice = totalPrice + (tonumber(info.price) or 0)
        totalRate = totalRate + (tonumber(info.rate) or 0)
        if info.ready then
            ready = ready + 1
        else
            growing = growing + 1
            if nextRemain == nil or (tonumber(info.remain) or 0) < nextRemain then
                nextRemain = tonumber(info.remain) or 0
            end
        end
        local mutName = mutLabel(info.muts)
        local row = mutTotals[mutName]
        if not row then
            row = { name = mutName, count = 0, total = 0, rate = 0 }
            mutTotals[mutName] = row
        end
        row.count = row.count + 1
        row.total = row.total + (tonumber(info.price) or 0)
        row.rate = row.rate + (tonumber(info.rate) or 0)
    end
    table.sort(eggs, function(a, b)
        if a.ready ~= b.ready then
            return a.ready == true
        end
        local ra, rb = tonumber(a.remain) or 0, tonumber(b.remain) or 0
        if ra ~= rb then
            return ra < rb
        end
        local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
        if pa ~= pb then
            return pa > pb
        end
        return tostring(a.name or "") < tostring(b.name or "")
    end)
    local mutList = {}
    for _, row in pairs(mutTotals) do
        mutList[#mutList + 1] = row
    end
    table.sort(mutList, function(a, b)
        if a.name == "Normal" then
            return false
        end
        if b.name == "Normal" then
            return true
        end
        return tostring(a.name) < tostring(b.name)
    end)
    local result = {
        eggs = eggs,
        total = #eggs,
        ready = ready,
        growing = growing,
        value = totalPrice,
        rate = totalRate,
        nextRemain = nextRemain,
        mutations = mutList,
    }
    M._plotList = result
    M._plotListAt = os.clock()
    return result
end

local function eggLine(info, index)
    info = type(info) == "table" and info or {}
    local parts = { tostring(index) .. "." }
    if type(info.rarity) == "string" and info.rarity ~= "" then
        parts[#parts + 1] = info.rarity
    end
    parts[#parts + 1] = tostring(info.name or info.category or "egg")
    parts[#parts + 1] = mutLabel(info.muts)
    if (tonumber(info.kg) or 0) > 0 then
        parts[#parts + 1] = fmtKg(info.kg)
    end
    parts[#parts + 1] = fmtPrice(info.price)
    parts[#parts + 1] = fmtRate(info.rate)
    if info.ready then
        parts[#parts + 1] = "Ready"
    else
        parts[#parts + 1] = tostring(info.timeText or "?")
        parts[#parts + 1] = tostring(info.pct or 0) .. "%"
    end
    return table.concat(parts, " · ")
end

local function mutationSummary(mutList)
    mutList = type(mutList) == "table" and mutList or {}
    if #mutList == 0 then
        return "Mutations: —"
    end
    local lines = { "Total per mutasi:" }
    for i = 1, #mutList do
        local m = mutList[i]
        lines[#lines + 1] = string.format(
            "· %s  ·  x%d  ·  %s  ·  %s",
            tostring(m.name or "?"),
            tonumber(m.count) or 0,
            fmtPrice(m.total),
            fmtRate(m.rate)
        )
    end
    return table.concat(lines, "\n")
end

function M.formatSummary(data)
    data = type(data) == "table" and data or M.listPlotEggs()
    local nextText = "—"
    if (tonumber(data.ready) or 0) > 0 then
        nextText = "hatch now"
    elseif data.nextRemain ~= nil then
        nextText = fmtDuration(data.nextRemain)
    end
    return string.format(
        "Eggs: %d  ·  Ready: %d  ·  Growing: %d  ·  %s  ·  %s  ·  Next: %s",
        tonumber(data.total) or 0,
        tonumber(data.ready) or 0,
        tonumber(data.growing) or 0,
        fmtPrice(data.value),
        fmtRate(data.rate),
        nextText
    )
end

local function hatchOne(uid, label)
    uid = tostring(uid or "")
    if uid == "" then
        return false, "no uid"
    end
    emit("Hatch", "live", tostring(label or "—"))
    local ok, success, err = eggCall("RequestHatchEgg", uid)
    if not (ok and success == true) then
        return false, tostring((ok and (err or success)) or success or "denied")
    end
    local ok2, done, err2 = eggCall("RequestCompleteHatchEgg", uid)
    if ok2 and done == true then
        return true
    end
    return false, tostring((ok2 and (err2 or done)) or done or "complete failed")
end

local function hatchReady(limit)
    local data = M.listPlotEggs()
    local n = 0
    local lastErr
    if (tonumber(data.ready) or 0) <= 0 then
        return 0, nil, data
    end
    for _, info in ipairs(data.eggs) do
        if M.enabled ~= true and limit == nil then
            break
        end
        if GEN ~= G.__StealEggHatchGen then
            break
        end
        if info.ready == true then
            local ok, err = hatchOne(info.uid, info.name)
            if ok then
                n = n + 1
                M._hatched = (tonumber(M._hatched) or 0) + 1
                invalidatePlaceCaches()
                emit("Hatched", "success", tostring(info.name or "egg"))
                if limit and n >= limit then
                    break
                end
                local waitSec = math.clamp(tonumber(M.delay) or 0.1, 0.05, 5)
                local t0 = os.clock()
                while os.clock() - t0 < waitSec do
                    if M.enabled ~= true and limit == nil then
                        break
                    end
                    if GEN ~= G.__StealEggHatchGen then
                        break
                    end
                    task.wait(0.05)
                end
            else
                lastErr = err
                if tostring(err) ~= "not ready" then
                    emit("Denied", "warn", tostring(info.name or "egg") .. " · " .. tostring(err or "failed"))
            end
        end
    end
    end
    invalidatePlaceCaches()
    return n, lastErr, data
end

local function hatchLoop(token)
    bindGame()
    emit("On", "live", "auto hatch")
    while M.enabled == true and M._token == token and GEN == G.__StealEggHatchGen do
        local delay = math.clamp(tonumber(M.delay) or 0.1, 0.05, 5)
        -- Hatch tidak jalan ke pen / tidak Hold steal. Place yang goToPen.
        M._hatchBusy = true
        M._busy = true
        local ok, nOrErr, _, data = pcall(hatchReady)
        M._hatchBusy = false
        M._busy = false
        -- JANGAN restoreMove di sini. Hatch tidak gerak karakter; spam
        -- "hatch-done" sempat melepas TpHold di tengah FAR → telur jatuh.
        if not (M.enabled == true and M._token == token and GEN == G.__StealEggHatchGen) then
            break
        end
        if ok then
            local n = tonumber(nOrErr) or 0
            if n > 0 then
                emit("On", "live", "hatched " .. tostring(n))
            else
                if type(data) ~= "table" then
                    data = M.listPlotEggs()
                end
                if (tonumber(data.total) or 0) <= 0 then
                    emit("Idle", "muted", "empty")
                elseif (tonumber(data.ready) or 0) <= 0 then
                    local remain = tonumber(data.nextRemain)
                    if remain and remain > 0 then
                        emit("Idle", "muted", "growing · " .. fmtDuration(remain))
                    else
                        emit("Idle", "muted", "growing")
                    end
                    -- Growing: jangan poll 0.1s — listPlotEggs + remote = spike.
                    delay = math.max(delay, 0.45)
                end
            end
        else
            emit("Error", "error", tostring(nOrErr or "hatch failed"))
        end
        -- Cadence = Delay UI (bukan cap 0.35 / poll grow pendek).
        local t0 = os.clock()
        while os.clock() - t0 < delay do
            if M.enabled ~= true or M._token ~= token or GEN ~= G.__StealEggHatchGen then
                break
            end
            task.wait(0.08)
        end
    end
end

getPlotData = function()
    local w = G.StealEggWild
    if type(w) == "table" and type(w.getPlotData) == "function" then
        local ok, data = pcall(w.getPlotData)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(PlotCmds) ~= "table" then
        PlotCmds = tryRequire("Library.Client.PlotCmds")
    end
    local fn = type(PlotCmds) == "table" and (PlotCmds.GetPlotData or PlotCmds.ResolvePlot)
    if type(fn) ~= "function" then
        return nil
    end
    local ok, data = pcall(fn)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function wildMod()
    local w = G.StealEggWild
    if type(w) == "table" then
        return w
    end
    return nil
end

inPen = function()
    local w = wildMod()
    if type(w) ~= "table" or w._onBelt == true then
        return false
    end
    -- Instant: wajib di PetArea. Forest pad (515) / luar plot ≠ place-ready.
    local mode = tostring(w.moveMode or ""):lower()
    local instant = mode == "teleport" or mode == "instant" or mode == "far" or mode == "decoy"
    if type(w.isOnPetArea) == "function" then
        local ok, v = pcall(w.isOnPetArea)
        if ok and v == true then
            return true
        end
    end
    if instant then
        return false
    end
    -- Dulu mode walk masih menerima inPlotHome, yaitu di mana pun di dalam
    -- kotak plot. Itu tidak sejalan dengan ensureInPen yang menuntut PetArea,
    -- dan selisih itulah celahnya: turun dari treadmill sudah masuk kotak plot,
    -- jadi placeBatch berjalan sambil berdiri di sebelah pad, lalu game
    -- memasang kita balik ke treadmill. Sekarang kedua gerbang menuntut hal
    -- yang sama, yaitu benar-benar berada di PetArea.
    return false
end

local lastPlaceSnapAt = 0
local function placeSnap(tag)
    tag = tostring(tag or "")
    -- loop:tick tiap 0.25s + GetPlotData = spike. Debug saja, max 2.5s.
    if tag == "loop:tick" then
        local now = os.clock()
        if now - lastPlaceSnapAt < 2.5 then
            return
        end
        lastPlaceSnapAt = now
    end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local pos = root and root.Position
    local w = G.StealEggWild
    local data
    pcall(function()
        data = getPlotData()
    end)
    local slot, petPos
    if type(data) == "table" then
        slot = data.Slot
        if typeof(data.PetArea) == "Instance" then
            petPos = data.PetArea.Position
        end
    end
    local home, petA, pad
    if type(w) == "table" then
        if type(w.inPlotHome) == "function" then
            local ok, v = pcall(w.inPlotHome)
            home = ok and v
        end
        if type(w.isOnPetArea) == "function" then
            local ok, v = pcall(w.isOnPetArea)
            petA = ok and v
        end
        if type(w.isOverTreadmillPad) == "function" then
            local ok, v = pcall(w.isOverTreadmillPad)
            pad = ok and v
        end
    end
    local xz = -1
    if typeof(pos) == "Vector3" and typeof(petPos) == "Vector3" then
        xz = Vector3.new(pos.X - petPos.X, 0, pos.Z - petPos.Z).Magnitude
    end
    placeDbg(tag, string.format(
        "pos=%s xzPet=%.0f inPen=%s home=%s petArea=%s belt=%s pad=%s farm=%s hold=%s pBusy=%s sBusy=%s claim=%s slot=%s pet=%s",
        v3s(pos),
        xz,
        tostring(inPen()),
        tostring(home),
        tostring(petA),
        tostring(w and w._onBelt),
        tostring(pad),
        tostring(w and w._farmingBelt),
        tostring(G.__StealEggBeltHold),
        tostring(M._placeBusy),
        tostring(G.__StealEggBusy),
        tostring(G.__StealEggClaiming),
        tostring(slot),
        v3s(petPos)
    ))
end

goToPen = function(shouldRun)
    -- Place only. Hatch tidak memanggil ini.
    placeSnap("goToPen:start")
    local w = wildMod()
    local t0 = os.clock()
    if type(w) == "table" and type(w.ensureInPen) == "function" then
        local ok, v = pcall(w.ensureInPen, "place", shouldRun)
        placeDbg("goToPen:ensureInPen", string.format("ok=%s v=%s sec=%.2f", tostring(ok), tostring(v), os.clock() - t0))
        placeSnap("goToPen:afterEnsure")
        return ok == true and v == true
    end
    if type(w) == "table" and type(w.goHome) == "function" then
        local ok, dest = pcall(w.goHome, shouldRun)
        placeDbg("goToPen:goHome", string.format("ok=%s dest=%s sec=%.2f", tostring(ok), tostring(dest), os.clock() - t0))
        placeSnap("goToPen:afterHome")
        return ok == true
    end
    placeDbg("goToPen", "NO ensureInPen · wild=" .. tostring(type(w)))
    placeSnap("goToPen:afterEnsure")
    return inPen()
end

local function restoreAfterPlotWork(why)
    -- Place selesai: jangan ganggu FAR/claim/carry.
    if G.__StealEggFarOn == true
        or G.__StealEggDecoyOn == true
        or G.__StealEggClaiming == true
        or G.__StealEggBusy == true then
        return
    end
    local w = wildMod()
    if type(w) == "table" and type(w.isCarrying) == "function" then
        local ok, carrying = pcall(w.isCarrying)
        if ok and carrying == true then
            return
        end
    end
    if type(w) == "table" and type(w.restoreMove) == "function" then
        pcall(w.restoreMove, why or "place-done")
        return
    end
    local I = G.StealEggInstant
    if type(I) == "table" and type(I.restoreMove) == "function" then
        pcall(I.restoreMove, why or "place-done")
    end
end

local function releaseBelt()
    local w = wildMod()
    if type(w) == "table" and type(w.releaseBelt) == "function" then
        pcall(w.releaseBelt)
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Release) == "function" then
        pcall(d.Release, "place")
    end
    restoreAfterPlotWork("place-release")
end

-- Place cap is NOT in Save / Bases. Live dump:
--   Save: BaseUpgradeLevel, EggInventory (Placement = on plot). No MaxEggs.
--   Bases.MaxAssets = pet equip 7..18. Eggs.MAX_INVENTORY = 115 (bag).
--   Constants.MIN_PLACE_GRID_SIZE = 3 / SERVER_MIN_GRID_SIZE = 2.25 = min
--   CENTER gap for the ghost, not visual size. Telur besar (8-24 stud) cuma
--   model; server menolak overlap pusat, bukan overlap badan. Dulu typicalCell
--   memakai diameter visual → sel 22 stud → PetArea "penuh" lalu cuma coba
--   titik tengah (0,0). Grid 3 stud (ghost klien) juga nyisain 1 lubang:
--   server pakai 2.25 — telur terakhir ditolak / nahan di tengah plot.
local PLACE_GHOST = 3
local PLACE_MIN = 2.25
-- 1.0 = diameter ghost 3. Dulu 0.92 (need 2.76) jadi kandidat 2.8 stud
-- lolos klien, server (MIN_PLACE_GRID 3) tolak → retry tanpa nempel.
local PLACE_OVERLAP = 1
local PLACE_CELL = PLACE_GHOST

local function partAreaXZ(part)
    if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
        return 0
    end
    return part.Size.X * part.Size.Z
end

local bagPetArea = nil
local lastPlaceRefreshAt = 0

local function bestPetArea(data)
    if type(data) ~= "table" then
        return nil
    end
    local folder = data.PlotFolder
    local now = os.clock()
    if typeof(folder) == "Instance"
        and bagPetArea
        and bagPetArea.folder == folder
        and typeof(bagPetArea.part) == "Instance"
        and bagPetArea.part.Parent
        and now - (bagPetArea.at or 0) < 8
    then
        return bagPetArea.part
    end
    local best = data.PetArea
    local bestA = partAreaXZ(best)
    if typeof(folder) == "Instance" then
        for _, d in ipairs(folder:GetDescendants()) do
            if d.Name == "PetArea" and d:IsA("BasePart") then
                local a = partAreaXZ(d)
                if a > bestA then
                    best, bestA = d, a
                end
            end
        end
    end
    if typeof(best) == "Instance" and best:IsA("BasePart") then
        bagPetArea = { folder = folder, part = best, at = now }
        return best
    end
    return nil
end

local function eggLocalXZ(lcf)
    if typeof(lcf) == "CFrame" then
        return lcf.X, lcf.Z
    end
    if type(lcf) ~= "table" then
        return nil
    end
    local x = tonumber(lcf.X or lcf[1])
    local z = tonumber(lcf.Z or lcf[3])
    if x and z then
        return x, z
    end
    return nil
end

-- Disk: Save LocalCFrame + visual PlacedEggRenders di PetArea sendiri.
-- Visual dipakai kalau Save kosong / FPS sudah hide model (server slot tetap isi).
local function ownerEggDisks(data)
    local disks = {}
    local seen = {}
    local r = PLACE_GHOST * 0.5 * PLACE_OVERLAP
    local function add(x, z)
        x, z = tonumber(x), tonumber(z)
        if not x or not z then
            return
        end
        local key = string.format("%.1f:%.1f", x, z)
        if seen[key] then
            return
        end
        seen[key] = true
        disks[#disks + 1] = { x, z, r }
    end
    for _, rec in ipairs(placedRecords()) do
        local lcf = type(rec) == "table" and rec.Placement and rec.Placement.LocalCFrame
        local x, z = eggLocalXZ(lcf)
        if x then
            add(x, z)
        end
    end
    data = data or getPlotData()
    local center = data and data.CenterPoint
    local pet = bestPetArea(data)
    local folder = Workspace:FindFirstChild("PlacedEggRenders")
    if typeof(center) == "Instance" and typeof(folder) == "Instance" then
        local kids = folder:GetChildren()
        for i = 1, #kids do
            local kid = kids[i]
            local pos
            if kid:IsA("Model") then
                local ok, pv = pcall(function()
                    return kid:GetPivot().Position
                end)
                if ok then
                    pos = pv
                end
            elseif kid:IsA("BasePart") then
                pos = kid.Position
            end
            if typeof(pos) == "Vector3" then
                local onPet = true
                if typeof(pet) == "Instance" then
                    local lp = pet.CFrame:PointToObjectSpace(pos)
                    local h = pet.Size * 0.5
                    onPet = math.abs(lp.X) <= (h.X + 3) and math.abs(lp.Z) <= (h.Z + 3)
                end
                if onPet then
                    local loc = center.CFrame:PointToObjectSpace(pos)
                    add(loc.X, loc.Z)
                end
            end
        end
    end
    return disks
end

local function typicalCell(_center)
    return PLACE_CELL
end

local function collectPlaceDisks(data, extraSpots)
    local disks = ownerEggDisks(data)
    local fallbackR = PLACE_GHOST * 0.5 * PLACE_OVERLAP
    if type(extraSpots) == "table" then
        for i = 1, #extraSpots do
            local s = extraSpots[i]
            if type(s) == "table" then
                local x = tonumber(s[1] or s.x)
                local z = tonumber(s[2] or s.z)
                if x and z then
                    disks[#disks + 1] = { x, z, tonumber(s[3] or s.r) or fallbackR }
                end
            end
        end
    end
    return disks
end

local function diskBlocked(disks, px, pz, newR)
    -- Epsilon: raycast hit bisa geser 0.02, jangan anggap tetangga 3-stud kepentok.
    local pad = 0.06
    for i = 1, #disks do
        local d = disks[i]
        local dx = (d[1] or 0) - px
        local dz = (d[2] or 0) - pz
        local need = (d[3] or newR) + newR - pad
        if need > 0 and dx * dx + dz * dz < need * need then
            return true
        end
    end
    return false
end

local failSlots = {}
-- Dulu 40s: satu wave timeout ngeracun satu sisi plot, place cuma retry.
local FAIL_SLOT_SEC = 8
-- 3.2 stud ke dalam dari AABB PetArea = nempel pagar dalam, bukan tiang/gerbang.
local PLACE_INSET = 3.2

local function pruneFailSlots()
    local now = os.clock()
    local n = #failSlots
    local w = 0
    for i = 1, n do
        local s = failSlots[i]
        if type(s) == "table" and (now - (tonumber(s[3]) or 0)) < FAIL_SLOT_SEC then
            w += 1
            failSlots[w] = s
        end
    end
    for i = w + 1, n do
        failSlots[i] = nil
    end
end

local function failSlotKey(x, z)
    return string.format("%.2f:%.2f", math.floor(x * 20 + 0.5) / 20, math.floor(z * 20 + 0.5) / 20)
end

local function markFailSlot(x, z)
    x, z = tonumber(x), tonumber(z)
    if not x or not z then
        return
    end
    pruneFailSlots()
    local key = failSlotKey(x, z)
    for i = 1, #failSlots do
        local s = failSlots[i]
        if type(s) == "table" and failSlotKey(s[1], s[2]) == key then
            s[3] = os.clock()
            return
        end
    end
    failSlots[#failSlots + 1] = { x, z, os.clock() }
end

local function petCenterBounds(pet, center)
    local h = pet.Size * 0.5
    local minX, maxX, minZ, maxZ = math.huge, -math.huge, math.huge, -math.huge
    local cx = { -h.X, h.X }
    local cz = { -h.Z, h.Z }
    for i = 1, 2 do
        for j = 1, 2 do
            local w = pet.CFrame:PointToWorldSpace(Vector3.new(cx[i], 0, cz[j]))
            local loc = center.CFrame:PointToObjectSpace(w)
            minX = math.min(minX, loc.X)
            maxX = math.max(maxX, loc.X)
            minZ = math.min(minZ, loc.Z)
            maxZ = math.max(maxZ, loc.Z)
        end
    end
    return minX, maxX, minZ, maxZ
end

local function placePetArea(data)
    if type(data) == "table" and typeof(data.PetArea) == "Instance" and data.PetArea:IsA("BasePart") then
        return data.PetArea
    end
    return bestPetArea(data)
end

function M.gridCapacity(data)
    data = data or getPlotData()
    local pet = placePetArea(data)
    local center = data and data.CenterPoint
    if typeof(pet) ~= "Instance" or typeof(center) ~= "Instance" then
        return nil
    end
    local GRID = typicalCell(center)
    local minX, maxX, minZ, maxZ = petCenterBounds(pet, center)
    local nx = math.max(0, math.floor((maxX - minX - PLACE_INSET * 2) / GRID + 1e-4))
    local nz = math.max(0, math.floor((maxZ - minZ - PLACE_INSET * 2) / GRID + 1e-4))
    return (nx + 1) * (nz + 1)
end

function M.nextPlaceCFrame(data, extraSpots)
    if type(data) ~= "table" then
        return nil
    end
    local pet = placePetArea(data)
    local center = data.CenterPoint
    if typeof(pet) ~= "Instance" or typeof(center) ~= "Instance" then
        return nil
    end
    local GRID = typicalCell(center)
    local newR = PLACE_GHOST * 0.5 * PLACE_OVERLAP
    local extra = {}
    if type(extraSpots) == "table" then
        for i = 1, #extraSpots do
            extra[i] = extraSpots[i]
        end
    end
    pruneFailSlots()
    for i = 1, #failSlots do
        extra[#extra + 1] = failSlots[i]
    end
    local disks = collectPlaceDisks(data, extra)
    local h = pet.Size * 0.5
    local minX, maxX, minZ, maxZ = petCenterBounds(pet, center)
    minX += PLACE_INSET
    maxX -= PLACE_INSET
    minZ += PLACE_INSET
    maxZ -= PLACE_INSET
    if maxX < minX or maxZ < minZ then
        return nil
    end
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Include
    rayParams.FilterDescendantsInstances = { pet }
    rayParams.IgnoreWater = true
    local function tryXZ(lx, lz)
        local world = (center.CFrame * CFrame.new(lx, 0, lz)).Position
        local lp = pet.CFrame:PointToObjectSpace(world)
        if math.abs(lp.X) > (h.X - 1.35) or math.abs(lp.Z) > (h.Z - 1.35) then
            return nil
        end
        -- Sama game EggPlacementController: hit permukaan PetArea → ToObjectSpace.
        local hit = Workspace:Raycast(world + Vector3.new(0, 8, 0), Vector3.new(0, -16, 0), rayParams)
        if not hit or hit.Instance ~= pet then
            return nil
        end
        local cf = center.CFrame:ToObjectSpace(CFrame.new(hit.Position))
        if diskBlocked(disks, cf.X, cf.Z, newR) then
            return nil
        end
        return cf
    end
    -- Lattice nempel telur yang sudah ada, bukan sudut AABB (itu geser 1-2 stud
    -- → dist < 3 → Cannot place). Kalau plot kosong, origin = pagar dalam belakang-kiri.
    local ox, oz = minX, maxZ
    if #disks > 0 then
        local best = math.huge
        for i = 1, #disks do
            local d = disks[i]
            local score = (d[1] - minX) * (d[1] - minX) + (d[2] - maxZ) * (d[2] - maxZ)
            if score < best then
                best = score
                ox, oz = d[1], d[2]
            end
        end
    end
    local seen = {}
    local cands = {}
    local function consider(lx, lz)
        lx, lz = tonumber(lx), tonumber(lz)
        if not lx or not lz then
            return
        end
        if lx < minX - 0.05 or lz < minZ - 0.05 or lx > maxX + 0.05 or lz > maxZ + 0.05 then
            return
        end
        local key = string.format("%.2f:%.2f", lx, lz)
        if seen[key] then
            return
        end
        seen[key] = true
        local cf = tryXZ(lx, lz)
        if typeof(cf) ~= "CFrame" then
            return
        end
        local dx = math.min(cf.X - minX, maxX - cf.X)
        local dz = math.min(cf.Z - minZ, maxZ - cf.Z)
        local edge = math.min(dx, dz)
        cands[#cands + 1] = { cf, edge, -cf.Z, cf.X }
    end
    local ix0 = math.floor((minX - ox) / GRID - 1e-4)
    local ix1 = math.ceil((maxX - ox) / GRID + 1e-4)
    local iz0 = math.floor((minZ - oz) / GRID - 1e-4)
    local iz1 = math.ceil((maxZ - oz) / GRID + 1e-4)
    for ix = ix0, ix1 do
        for iz = iz0, iz1 do
            consider(ox + ix * GRID, oz + iz * GRID)
        end
    end
    -- Telur off-grid (player taruh manual): isi tetangga ±3-nya juga.
    for i = 1, #disks do
        local d = disks[i]
        consider(d[1] + GRID, d[2])
        consider(d[1] - GRID, d[2])
        consider(d[1], d[2] + GRID)
        consider(d[1], d[2] - GRID)
    end
    table.sort(cands, function(a, b)
        -- Pagar dalam dulu, belakang (Z besar) dulu, kiri ke kanan.
        if math.abs(a[2] - b[2]) > 0.45 then
            return a[2] < b[2]
        end
        if math.abs(a[3] - b[3]) > 0.2 then
            return a[3] < b[3]
        end
        return a[4] < b[4]
    end)
    if cands[1] then
        return cands[1][1]
    end
    for _ = 1, 24 do
        local cf = tryXZ(minX + math.random() * (maxX - minX), minZ + math.random() * (maxZ - minZ))
        if cf then
            return cf
        end
    end
    return nil
end

local function localPlaceCFrame(data, extraSpots)
    return M.nextPlaceCFrame(data, extraSpots)
end

local function eggRecord(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if type(EggItemUtil) == "table" and type(EggItemUtil.DeserializeSavedEgg) == "function" then
        local ok, egg = pcall(EggItemUtil.DeserializeSavedEgg, raw)
        if ok and type(egg) == "table" then
            return egg
        end
    end
    return raw
end

local function getSaveData()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get, LP, true)
    if ok and type(data) == "table" then
        return data
    end
    local ok2, data2 = pcall(Save.Get)
    if ok2 and type(data2) == "table" then
        return data2
    end
    local ok3, data3 = pcall(Save.Get, LP, false)
    if ok3 and type(data3) == "table" then
        return data3
    end
    return nil
end

local placedSkip = {}
local placeFailSkip = {}
local PLACED_SKIP_SEC = 8
local PLACE_FAIL_SKIP_SEC = 2.5

local function markPlacedUid(uid)
    uid = tostring(uid or "")
    if uid ~= "" then
        placedSkip[uid] = os.clock()
        placeFailSkip[uid] = nil
    end
    invalidatePlaceCaches()
end

local function markPlaceFailUid(uid)
    uid = tostring(uid or "")
    if uid ~= "" then
        placeFailSkip[uid] = os.clock()
    end
end

local function justPlacedUid(uid)
    local t = placedSkip[tostring(uid or "")]
    return type(t) == "number" and (os.clock() - t) < PLACED_SKIP_SEC
end

local function justFailedUid(uid)
    local t = placeFailSkip[tostring(uid or "")]
    return type(t) == "number" and (os.clock() - t) < PLACE_FAIL_SKIP_SEC
end

local function isAlreadyPlacedErr(err)
    if type(err) == "table" then
        err = err.Message or err.Error or err.message
    end
    local msg = string.lower(tostring(err or ""))
    return string.find(msg, "already placed", 1, true) ~= nil
        or string.find(msg, "already on plot", 1, true) ~= nil
end

local function eggIsOnPlot(egg)
    local p = type(egg) == "table" and egg.Placement
    if type(p) ~= "table" then
        return false
    end
    local x, z = eggLocalXZ(p.LocalCFrame)
    return x ~= nil and z ~= nil
end

local function listUnplacedEggs()
    if type(unplacedCache) == "table" and (os.clock() - (unplacedCacheAt or 0)) < UNPLACED_CACHE_SEC then
        return unplacedCache
    end
    local out = {}
    local data = getSaveData()
    local inv = type(data) == "table" and data.EggInventory
    if type(inv) ~= "table" then
        unplacedCache = out
        unplacedCacheAt = os.clock()
        return out
    end
    local held
    local char = LP.Character
    local tool = char and char:FindFirstChildWhichIsA("Tool")
    if tool then
        held = tostring(tool:GetAttribute("UID") or "")
    end
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        if not justPlacedUid(uid) then
            local egg = eggRecord(raw)
            -- Bag = tidak ada LocalCFrame plot. Placement table kosong ≠ sudah ditanam.
            if type(egg) == "table" and eggIsOnPlot(egg) ~= true then
                local info = describeEgg(egg)
                if type(info) == "table" then
                    info.uid = info.uid or uid
                end
                out[#out + 1] = {
                    uid = uid,
                    name = tostring(info and info.name or egg.AssetCategory or uid),
                    held = held ~= "" and uid == held,
                    failed = justFailedUid(uid),
                    info = info,
                }
            end
        end
    end
    table.sort(out, function(a, b)
        if a.held ~= b.held then
            return a.held == true
        end
        if a.failed ~= b.failed then
            return a.failed ~= true
        end
        return tostring(a.name) < tostring(b.name)
    end)
    unplacedCache = out
    unplacedCacheAt = os.clock()
    return out
end

function M.hasPlacePending()
    if type(pendingCache) == "boolean" and (os.clock() - (pendingCacheAt or 0)) < PENDING_CACHE_SEC then
        return pendingCacheVal
    end
    bindGame()
    if M.placeEnabled ~= true then
        pendingCache, pendingCacheAt, pendingCacheVal = true, os.clock(), false
        return false
    end
    -- Steal/monster masih ada kerja: jangan laporkan pending (hindari throttle steal).
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.canSideWork) == "function" then
        local oks, idle = pcall(wild.canSideWork)
        if not (oks == true and idle == true) then
            pendingCache, pendingCacheAt, pendingCacheVal = true, os.clock(), false
            return false
        end
    end
    -- Cap server saja (murah). Jangan nextPlaceCFrame penuh tiap belt tick.
    local n = #placedRecords()
    local cap = M.placeCap()
    if type(cap) == "number" and cap >= 1 and n >= cap then
        pendingCache, pendingCacheAt, pendingCacheVal = true, os.clock(), false
        return false
    end
    local yes = false
    for _, row in ipairs(listUnplacedEggs()) do
        if M.placeAllowed(row.info) then
            yes = true
            break
        end
    end
    pendingCache, pendingCacheAt, pendingCacheVal = true, os.clock(), yes
    return yes
end

local function isPlotFullErr(err)
    if type(err) == "table" then
        err = err.Message or err.Error or err.message
    end
    local msg = string.lower(tostring(err or ""))
    if msg == "" or msg == "nil" then
        return false
    end
    return string.find(msg, "full", 1, true) ~= nil
        or string.find(msg, "limit", 1, true) ~= nil
        or string.find(msg, "too many", 1, true) ~= nil
        or string.find(msg, "many egg", 1, true) ~= nil
end

-- Game (EggPlacementController): slot ditolak = "Cannot place egg here!".
-- Bukan cap angka. Kalau dihitung "belum penuh", Place Light Dove diulang
-- 3× InvokeServer — kadang ~1 menit di tengah plot.
local function isCannotPlaceErr(err)
    if type(err) == "table" then
        err = err.Message or err.Error or err.message
    end
    local msg = string.lower(tostring(err or ""))
    if msg == "" or msg == "nil" then
        return false
    end
    return string.find(msg, "cannot place", 1, true) ~= nil
        or string.find(msg, "can't place", 1, true) ~= nil
        or string.find(msg, "cant place", 1, true) ~= nil
        or string.find(msg, "no slot", 1, true) ~= nil
end

local PLACE_INVOKE_SEC = 8

local function placeInvoke(uid, cf)
    local done, ok, success, err = false, false, nil, nil
    task.spawn(function()
        ok, success, err = eggCall("RequestPlaceEgg", uid, cf)
        done = true
    end)
    local t0 = os.clock()
    while done ~= true and (os.clock() - t0) < PLACE_INVOKE_SEC do
        task.wait(0.05)
    end
    if done ~= true then
        return false, nil, "place timeout"
    end
    return ok, success, err
end

local function markGeomFull()
    M._geomFullUntil = os.clock() + 12
    M._geomFullN = #placedRecords()
    M._plotEggs = M._geomFullN
end

local function toastPlaceFull()
    local now = os.clock()
    if type(M._plotFullAt) == "number" and now - M._plotFullAt < 8 then
        return
    end
    M._plotFullAt = now
    local Msg = tryRequire("Client.Notifications.Message")
    if type(Msg) == "table" and type(Msg.Bottom) == "function" then
        pcall(Msg.Bottom, {
            Message = "You have too many eggs placed!",
            Time = 3,
            Color = Color3.fromRGB(255, 80, 80),
        })
    end
end

-- PlantEgg / AskPlaceEgg sering Wear ke Character. Lepas lagi supaya bag
-- tidak muncul di tangan (terutama saat place gagal / countdown reset).
local function placeProtectUid()
    if G.__StealEggBusy == true or G.__StealEggFarOn == true or G.__StealEggClaiming == true then
        local char = LP.Character
        local tool = char and char:FindFirstChildWhichIsA("Tool")
        if tool and tool:GetAttribute("ItemType") == "AssetEgg" then
            local uid = tostring(tool:GetAttribute("UID") or "")
            if uid ~= "" then
                return uid
            end
        end
    end
    local w = wildMod()
    if type(w) == "table" then
        if type(w.isCarrying) == "function" then
            local okc, yes = pcall(w.isCarrying)
            if okc == true and yes == true then
                local carry = type(w._carry) == "table" and w._carry.Uid
                if carry ~= nil and tostring(carry) ~= "" then
                    return tostring(carry)
                end
                local char = LP.Character
                local tool = char and char:FindFirstChildWhichIsA("Tool")
                if tool and tool:GetAttribute("ItemType") == "AssetEgg" then
                    local uid = tostring(tool:GetAttribute("UID") or "")
                    if uid ~= "" then
                        return uid
                    end
                end
            end
        end
        local stolen = type(w._stolen) == "table" and w._stolen.carryUid
        if stolen ~= nil and tostring(stolen) ~= "" then
            return tostring(stolen)
        end
    end
    return nil
end

local function unequipAfterPlace(uid)
    uid = tostring(uid or "")
    local protect = placeProtectUid()
    local char = LP.Character
    if not char then
        return
    end
    local tool = char:FindFirstChildWhichIsA("Tool")
    if not (tool and tool:GetAttribute("ItemType") == "AssetEgg") then
        return
    end
    local held = tostring(tool:GetAttribute("UID") or "")
    if held == "" then
        return
    end
    if protect and held == protect then
        return
    end
    if type(eggCall) == "function" then
        pcall(eggCall, "RequestUnequipTool", held)
        pcall(eggCall, "RequestUnequipTool")
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

-- Steal mau race reset (~FinalBlink 10s): jangan place dulu biar egg tidak naik ke tangan.
local function placeBlockedByReset()
    local w = wildMod()
    if type(w) ~= "table" or w.enabled ~= true or G.__StealEggWanted ~= true then
        return false
    end
    if G.__StealEggResetGo == true then
        return true
    end
    local cycle = tryRequire("Shared.Util.AreaEggCycle")
    if type(cycle) ~= "table" or type(cycle.SecondsUntilReset) ~= "function" then
        return false
    end
    local now = Workspace:GetServerTimeNow()
    local ok, sec = pcall(cycle.SecondsUntilReset, now)
    if ok ~= true or tonumber(sec) == nil or sec <= 0 then
        return false
    end
    return sec <= 12
end

local function placeOne(uid, label, used)
    uid = tostring(uid or "")
    if uid == "" then
        return false, "no uid"
    end
    local data = getPlotData()
    if not data then
        placeDbg("placeOne", "plot missing uid=" .. uid)
        return false, "plot missing"
    end
    if type(used) ~= "table" then
        used = {}
        for _, rec in ipairs(placedRecords()) do
            local lcf = type(rec) == "table" and rec.Placement and rec.Placement.LocalCFrame
            local x, z
            if typeof(lcf) == "CFrame" then
                x, z = lcf.X, lcf.Z
            elseif type(lcf) == "table" then
                x = tonumber(lcf.X or lcf[1])
                z = tonumber(lcf.Z or lcf[3])
            end
            if x and z then
                used[#used + 1] = { x, z }
            end
        end
    end
    local lastErr
    for _ = 1, 5 do
        local cf = localPlaceCFrame(data, used)
        if typeof(cf) ~= "CFrame" then
            markGeomFull()
            markPlaceFailUid(uid)
            unequipAfterPlace(uid)
            return false, lastErr or "no slot"
        end
        local lx = cf.Position.X
        local lz = cf.Position.Z
        used[#used + 1] = { lx, lz }
        emitPlace("Place", "live", tostring(label or "—"))
        local ok, success, err = placeInvoke(uid, cf)
        placeDbg("placeOne", string.format(
            "uid=%s label=%s ok=%s success=%s err=%s cf=%.2f,%.2f,%.2f",
            uid,
            tostring(label),
            tostring(ok),
            tostring(success),
            tostring(err),
            lx, cf.Position.Y, lz
        ))
        -- Server Wear sebelum/sesudah plant; selalu doff bag egg.
        task.wait(0.05)
        unequipAfterPlace(uid)
        if ok and success == true then
            invalidatePlaceCaches()
            -- OwnerRefreshed sudah rebuild visual. Refresh penuh = spike besar.
            local now = os.clock()
            if now - lastPlaceRefreshAt >= 2.5 then
                lastPlaceRefreshAt = now
                if type(PlacedEggRenderer) == "table" and type(PlacedEggRenderer.Refresh) == "function" then
                    pcall(PlacedEggRenderer.Refresh)
                end
            end
            markPlacedUid(uid)
            return true
        end
        if type(err) == "table" then
            lastErr = tostring(err.Message or err.Error or err.message or "place failed")
        elseif type(err) == "string" and err ~= "" then
            lastErr = err
        else
            lastErr = "place failed"
        end
        if isCannotPlaceErr(lastErr) then
            markFailSlot(lx, lz)
        end
        if isAlreadyPlacedErr(lastErr) then
            markPlacedUid(uid)
            unequipAfterPlace(uid)
            return true
        end
        if isPlotFullErr(lastErr) then
            pcall(M.rememberPlaceMax)
            markPlaceFailUid(uid)
            unequipAfterPlace(uid)
            return false, lastErr
        end
        if isCannotPlaceErr(lastErr) then
            -- Slot ditolak. Jangan cap "full" — masih ada kiri/kanan plot.
        end
    end
    unequipAfterPlace(uid)
    if lastErr == "no slot" then
        markGeomFull()
        markPlaceFailUid(uid)
    elseif isCannotPlaceErr(lastErr) then
        -- Slot-slot tepi sudah di failSlots. Egg ini boleh coba lagi.
    else
        markPlaceFailUid(uid)
    end
    return false, lastErr or "place failed"
end

local function usedPlaceSlots()
    local disks = ownerEggDisks(getPlotData())
    local used = {}
    for i = 1, #disks do
        used[i] = { disks[i][1], disks[i][2] }
    end
    return used
end

function M.placeSlotMap()
    bindGame()
    return usedPlaceSlots()
end

function M.placeForced(uid, label, used)
    bindGame()
    return placeOne(uid, label, used)
end

function M.hatchForced(uid, label)
    bindGame()
    return hatchOne(uid, label)
end

local function placeBatch()
    if M.plotAtCap() == true then
        return 0, "plot full"
    end
    if placeBlockedByReset() == true then
        unequipAfterPlace("")
        return 0, "reset"
    end
    local items = listUnplacedEggs()
    if #items == 0 then
        return 0, "no egg"
    end
    local data = getPlotData()
    if not data then
        return 0, "plot missing"
    end
    local used = usedPlaceSlots()
    local queue = {}
    local skipped = 0
    local cooling = 0
    for _, row in ipairs(items) do
        if M.placeAllowed(row.info) then
            if row.failed == true then
                cooling += 1
            else
                queue[#queue + 1] = row
            end
        else
            skipped += 1
        end
    end
    if #queue == 0 then
        if cooling > 0 then
            return 0, "retry"
        end
        if skipped > 0 then
            return 0, "no match"
        end
        return 0, "no egg"
    end
    local waveN = math.clamp(math.floor(tonumber(M.placeWave) or 1), 1, 8)
    local n = 0
    local lastErr
    local qi = 1
    local attempted = 0
    while qi <= #queue and attempted < waveN do
        if M.placeEnabled ~= true then
            break
        end
        if GEN ~= G.__StealEggHatchGen then
            break
        end
        do
            local w = wildMod()
            if type(w) == "table" and w.enabled == true and type(w.canSideWork) == "function" then
                local oks, idle = pcall(w.canSideWork)
                if not (oks == true and idle == true) then
                    lastErr = "steal"
                    break
                end
            end
            if G.__StealEggBusy == true or G.__StealEggFarOn == true or G.__StealEggClaiming == true then
                lastErr = "steal"
                break
            end
        end
        if M.plotAtCap() == true then
            lastErr = "plot full"
            break
        end
        local row = queue[qi]
        qi += 1
        attempted += 1
        emitPlace("Place", "live", tostring(row.name or "egg"))
        local ok, err = placeOne(row.uid, row.name, used)
        if ok == true then
            n += 1
            M._placed = (tonumber(M._placed) or 0) + 1
            emitPlace("Placed", "success", tostring(row.name or "egg"))
        else
            lastErr = err
            if isPlotFullErr(err) then
                pcall(M.rememberPlaceMax)
                return n, lastErr
            end
            if tostring(err) == "no slot" then
                return n, lastErr
            end
        end
        local waitSec = math.clamp(tonumber(M.placeDelay) or 0, 0, 5)
        if waitSec > 0 and qi <= #queue and attempted < waveN then
            local tW = os.clock()
            while os.clock() - tW < waitSec do
                if M.placeEnabled ~= true then
                    break
                end
                if G.__StealEggBusy == true or G.__StealEggFarOn == true then
                    break
                end
                task.wait()
            end
        end
    end
    if n <= 0 and lastErr == nil and skipped > 0 then
        return 0, "no match"
    end
    return n, lastErr
end

function M.placeWhileHome()
    if M.placeEnabled ~= true then
        return 0
    end
    bindGame()
    if M.plotAtCap() == true then
        return 0, "plot full"
    end
    local n, err = placeBatch()
    return n, err
end

local function placeLoop(token)
    bindGame()
    local function stillOn()
        return M.placeEnabled == true and M._placeToken == token and GEN == G.__StealEggHatchGen
    end

    local function sideGate()
        local wCarry = wildMod()
        local sideOk = true
        local waitWhy = "steal"
        if type(wCarry) == "table" and type(wCarry.canSideWork) == "function" then
            local oks, idle = pcall(wCarry.canSideWork)
            sideOk = oks == true and idle == true
            if sideOk ~= true then
                if G.__StealEggFarOn == true or G.__StealEggBusy == true then
                    waitWhy = "steal"
                elseif type(wCarry.isCarrying) == "function" then
                    local okc, yes = pcall(wCarry.isCarrying)
                    if okc == true and yes == true then
                        waitWhy = "carry"
                    end
                end
            end
        else
            local carrying = false
            if type(wCarry) == "table" and type(wCarry.isCarrying) == "function" then
                local okc, yes = pcall(wCarry.isCarrying)
                carrying = okc == true and yes == true
            end
            sideOk = carrying ~= true
                and G.__StealEggBusy ~= true and G.__StealEggFarOn ~= true
            if carrying then
                waitWhy = "carry"
            end
        end
        return sideOk, waitWhy
    end

    local function stealHasPickOutsideWindow()
        if G.__StealEggPlaceWindow == true then
            return false
        end
        local w = wildMod()
        if type(w) ~= "table" or w.enabled ~= true or G.__StealEggWanted ~= true then
            return false
        end
        if type(w.hasPick) ~= "function" then
            return false
        end
        local okp, hp = pcall(w.hasPick)
        return okp == true and hp == true
    end

    local function placeShouldRun()
        if stillOn() ~= true then
            return false
        end
        if G.__StealEggBusy == true or G.__StealEggClaiming == true then
            return false
        end
        if G.__StealEggFarOn == true or G.__StealEggDecoyOn == true then
            return false
        end
        if stealHasPickOutsideWindow() == true then
            return false
        end
        if placeBlockedByReset() == true then
            return false
        end
        local w = wildMod()
        if type(w) == "table" and type(w.canSideWork) == "function" then
            local oks, idle = pcall(w.canSideWork)
            return oks == true and idle == true
        end
        return true
    end

    while stillOn() do
        local row
        local bag = 0
        local cooling = 0
        for _, item in ipairs(listUnplacedEggs()) do
            bag += 1
            if M.placeAllowed(item.info) then
                if item.failed == true then
                    cooling += 1
                elseif row == nil then
                    row = item
                end
            end
        end

        if row == nil then
            M._placeBusy = false
            releaseBelt()
            if bag <= 0 then
                emitPlace("Idle", "muted", "empty")
            elseif cooling > 0 then
                emitPlace("Wait", "live", "retry")
            else
                emitPlace("Idle", "muted", "no match")
            end
            task.wait(cooling > 0 and 0.8 or 0.35)
        elseif M.plotAtCap() == true then
            M._placeBusy = false
            releaseBelt()
            emitPlace("Full", "warn", M.placeIdleDetail())
            task.wait(2)
        elseif G.__StealEggBusy == true or G.__StealEggClaiming == true then
            emitPlace("Wait", "live", "steal")
            task.wait(0.2)
        elseif placeBlockedByReset() == true then
            M._placeBusy = false
            releaseBelt()
            unequipAfterPlace("")
            emitPlace("Wait", "live", "reset")
            task.wait(0.35)
        else
            local sideOk, waitWhy = sideGate()
            if sideOk ~= true then
                M._placeBusy = false
                releaseBelt()
                emitPlace("Wait", "live", waitWhy)
                task.wait(0.35)
            elseif stealHasPickOutsideWindow() == true then
                M._placeBusy = false
                releaseBelt()
                emitPlace("Wait", "live", "steal")
                task.wait(0.25)
            else
                M._placeBusy = true
                local wBusy = wildMod()
                if type(wBusy) == "table" and type(wBusy.borrowBelt) == "function" then
                    pcall(wBusy.borrowBelt, "place")
                end
                placeDbg("loop", string.format(
                    "match=%s uid=%s bag=%d inPen=%s",
                    tostring(row.name),
                    tostring(row.uid),
                    bag,
                    tostring(inPen())
                ))
                placeSnap("loop:tick")

                if not inPen() then
                    emitPlace("Going", "live", "home")
                    goToPen(placeShouldRun)
                end
                if not stillOn() then
                    placeDbg("loop", "stillOn false after goHome")
                    break
                end

                if not inPen() then
                    M._placeBusy = false
                    releaseBelt()
                    emitPlace("Going", "live", "home")
                    placeDbg("loop", "skip batch · not inPen")
                    task.wait(0.3)
                else
                    local stillSide = true
                    if type(wBusy) == "table" and type(wBusy.canSideWork) == "function" then
                        local oks, idle = pcall(wBusy.canSideWork)
                        stillSide = oks == true and idle == true
                    end
                    if stillSide ~= true or stealHasPickOutsideWindow() == true then
                        M._placeBusy = false
                        releaseBelt()
                        emitPlace("Wait", "live", "steal")
                        task.wait(0.25)
                    else
                        local onBelt = false
                        local w = wildMod()
                        if type(w) == "table" then
                            if w._onBelt == true then
                                onBelt = true
                            elseif type(w.isOverTreadmillPad) == "function" then
                                local okp, vp = pcall(w.isOverTreadmillPad)
                                onBelt = okp == true and vp == true
                            end
                        end
                        placeDbg("loop:afterHome", "onBelt=" .. tostring(onBelt) .. " inPen=" .. tostring(inPen()))
                        if onBelt then
                            -- Jangan cuma nunggu: tendang belt lalu place.
                            emitPlace("Going", "live", "leave belt")
                            if type(w) == "table" then
                                if type(w.borrowBelt) == "function" then
                                    pcall(w.borrowBelt, "place")
                                end
                                if type(w.kickOffBelt) == "function" then
                                    pcall(w.kickOffBelt)
                                end
                                if type(w.ensureOffBelt) == "function" then
                                    pcall(w.ensureOffBelt, placeShouldRun)
                                end
                            end
                            task.wait(0.2)
                        else
                            local ok, nOrErr, lastErr = pcall(placeBatch)
                            placeDbg("loop:batch", string.format(
                                "pcall=%s n=%s err=%s",
                                tostring(ok),
                                tostring(nOrErr),
                                tostring(lastErr)
                            ))
                            if not stillOn() then
                                break
                            end
                            if not ok then
                                M._placeBusy = false
                                releaseBelt()
                                emitPlace("Going", "live", "home")
                                task.wait(0.4)
                            else
                                local n = tonumber(nOrErr) or 0
                                if isPlotFullErr(lastErr) then
                                    M._placeBusy = false
                                    releaseBelt()
                                    pcall(M.rememberPlaceMax)
                                    toastPlaceFull()
                                    emitPlace("Full", "warn", M.placeIdleDetail())
                                    task.wait(2)
                                elseif n > 0 then
                                    M._placeBusy = false
                                    releaseBelt()
                                else
                                    local msg = tostring(lastErr or "")
                                    M._placeBusy = false
                                    releaseBelt()
                                    if msg == "steal" then
                                        emitPlace("Wait", "live", "steal")
                                        task.wait(0.2)
                                    elseif msg == "no match" then
                                        emitPlace("Idle", "muted", "no match")
                                    elseif msg == "no egg" then
                                        emitPlace("Idle", "muted", "empty")
                                    elseif msg == "no slot" then
                                        emitPlace("Failed", "warn", "no slot")
                                        task.wait(2)
                                    elseif isCannotPlaceErr(lastErr) then
                                        emitPlace("Place", "live", "next")
                                        task.wait(0.12)
                                    elseif msg == "retry" then
                                        emitPlace("Wait", "live", "retry")
                                        task.wait(0.8)
                                    elseif msg == "plot missing" then
                                        emitPlace("Wait", "warn", "need plot")
                                        task.wait(0.4)
                                    elseif isAlreadyPlacedErr(lastErr) then
                                        emitPlace("Idle", "muted", "empty")
                                    else
                                        task.wait(0.25)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    M._placeBusy = false
    releaseBelt()
end

function M.setPlaceEnabled(on)
    on = on == true
    if on then
        if M.placeEnabled == true and M._placeLoopOn == true then
            syncWildPlace(true)
            return
        end
        M.placeEnabled = true
        syncWildPlace(true)
        M._placeToken = (tonumber(M._placeToken) or 0) + 1
        local token = M._placeToken
        M._placeLoopOn = true
        M._placeBusy = false
        placeDbg("setPlaceEnabled", "ON token=" .. tostring(token))
        task.spawn(function()
            while M.placeEnabled == true and M._placeToken == token and GEN == G.__StealEggHatchGen do
                local ok, err = pcall(placeLoop, token)
                if M._placeToken ~= token or M.placeEnabled ~= true then
                    break
                end
                if ok then
                    M._placeBusy = false
                    releaseBelt()
                    task.wait(0.2)
                else
                placeDbg("placeLoop:crash", tostring(err))
                M._placeBusy = false
                releaseBelt()
                task.wait(0.5)
                end
            end
            if M._placeToken == token then
                M._placeLoopOn = false
                M._placeBusy = false
                if M.placeEnabled ~= true then
                    emitPlace("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.placeEnabled = false
    M._placeLoopOn = false
    M._placeBusy = false
    syncWildPlace(false)
    releaseBelt()
    M._placeToken = (tonumber(M._placeToken) or 0) + 1
    emitPlace("Idle", "muted", "off")
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        M._hatchBusy = false
        M._busy = false
        -- Jangan nyentuh Place / Wild.place / ensureInPen — hatch remote-only.
        emit("On", "live", "auto hatch")
        task.spawn(function()
            hatchLoop(token)
            if M._token == token then
                M._loopOn = false
                M._hatchBusy = false
                M._busy = false
                if M.enabled ~= true then
                    emit("Idle", "muted", M._hatched > 0 and ("hatched " .. tostring(M._hatched)) or "—")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._hatchBusy = false
    M._busy = false
    M._token = (tonumber(M._token) or 0) + 1
    emit("Idle", "muted", "off")
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    if type(values["steal.place.rules"]) == "table" then
        M.setPlaceRules(values["steal.place.rules"])
    end
    if values["steal.place.draft.rarity"] ~= nil then
        M.placeDraft.rarities = parseKeyMap(values["steal.place.draft.rarity"])
    end
    if values["steal.place.draft.eggs"] ~= nil then
        M.placeDraft.eggs = parseKeyMap(values["steal.place.draft.eggs"])
    end
    if values["steal.place.draft.mutations"] ~= nil then
        M.placeDraft.mutations = parseKeyMap(values["steal.place.draft.mutations"])
    end
    if values["steal.place.draft.kgRule"] ~= nil then
        local kg, kgMode, kgRule = parseSignedRule(values["steal.place.draft.kgRule"], values["steal.place.draft.kgMode"])
        M.placeDraft.kgRule = kgRule
        M.placeDraft.kgMode = clampCompareMode(values["steal.place.draft.kgMode"] or kgMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.place.draft.kgMode"] ~= nil then
        M.placeDraft.kgMode = clampCompareMode(values["steal.place.draft.kgMode"], DEFAULT_COMPARE_MODE)
    end
    if values["steal.place.draft.rateRule"] ~= nil then
        local rate, rateMode, rateRule = parseSignedScaledRule(values["steal.place.draft.rateRule"], values["steal.place.draft.rateMode"])
        M.placeDraft.rateRule = rateRule
        M.placeDraft.rateMode = clampCompareMode(values["steal.place.draft.rateMode"] or rateMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.place.draft.rateMode"] ~= nil then
        M.placeDraft.rateMode = clampCompareMode(values["steal.place.draft.rateMode"], DEFAULT_COMPARE_MODE)
    end
    if values["steal.place.draft.priceRule"] ~= nil then
        local price, priceMode, priceRule = parseSignedScaledRule(values["steal.place.draft.priceRule"], values["steal.place.draft.priceMode"])
        M.placeDraft.priceRule = priceRule
        M.placeDraft.priceMode = clampCompareMode(values["steal.place.draft.priceMode"] or priceMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.place.draft.priceMode"] ~= nil then
        M.placeDraft.priceMode = clampCompareMode(values["steal.place.draft.priceMode"], DEFAULT_COMPARE_MODE)
    end
    local placeDelay = tonumber(values["steal.place.delay"])
    if placeDelay then
        M.placeDelay = math.clamp(placeDelay, 0, 5)
    end
    local placeWave = tonumber(values["steal.place.wave"])
    if placeWave then
        M.placeWave = math.clamp(math.floor(placeWave), 1, 8)
    end
    local delay = tonumber(values["steal.hatch.delay"])
    if delay then
        M.delay = math.clamp(delay, 0.05, 5)
    end
    if values["steal.place.enabled"] ~= nil then
        M.setPlaceEnabled(Core.flagOn(values["steal.place.enabled"]))
    else
        syncWildPlace(M.placeEnabled)
    end
    if values["steal.hatch.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.hatch.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local placeBody, _, placeStatusApi = ui:CreateSection({
        title = "Auto Place Egg",
        expanded = false,
        status = {
            id = "steal.place.status",
        persist = false,
            value = M._placeStatus.text,
            style = M._placeStatus.style,
            detail = M._placeStatus.detail,
        },
    })
    M.setPlaceStatusListener(function(st)
        placeStatusApi.set(st.text)
        placeStatusApi.setStyle(st.style)
        placeStatusApi.setDetail(st.detail)
    end)

    local ruleApi
    local function persistPlaceRules()
        if ruleApi and type(ruleApi.set) == "function" then
            pcall(ruleApi.set, M.placeRules)
        end
    end
    local _, bindRules = ui:CreateRuleList(placeBody, {
        id = "steal.place.rules",
        title = "Saved Rules",
        searchPlaceholder = "Search rules...",
        emptyText = "Belum ada rule. Kosong = semua egg di inventory.",
        visibleRows = 6,
        persist = true,
        getItems = function()
            return M.placeRules
        end,
        formatItem = function(rule)
            return M.formatPlaceRule(rule)
        end,
        onLoad = function(list)
            M.setPlaceRules(list)
        end,
        onToggle = function(rule, enabled)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            for _, item in ipairs(M.placeRules) do
                if tostring(item.id) == id then
                    item.enabled = enabled == true
                    break
                end
            end
            persistPlaceRules()
        end,
        onDelete = function(rule)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            local nextList = {}
            for _, item in ipairs(M.placeRules) do
                if tostring(item.id) ~= id then
                    nextList[#nextList + 1] = item
                end
            end
            M.placeRules = nextList
            persistPlaceRules()
        end,
    })
    ruleApi = bindRules

    local formApi
    local _, bindForm = ui:CreateRuleForm(placeBody, {
        id = "steal.place.draft.modes",
        label = "Rule Fields",
        placeholder = "Pick fields...",
        hintText = "Pilih Rarity / Egg / Mutation / Kg / Price / Earn, baru input muncul.",
        persist = true,
        modes = {
            { key = "rarity", name = "Rarity" },
            { key = "egg", name = "Egg" },
            { key = "mutation", name = "Mutation" },
            { key = "kg", name = "Kg" },
            { key = "price", name = "Price $" },
            { key = "rate", name = "Earn $/s" },
        },
    })
    formApi = bindForm

    local _, rarityApi = ui:CreateRowDropdown(placeBody, {
        id = "steal.place.draft.rarity",
        label = "Rarity",
        mode = "multi",
        placeholder = "Any rarity",
        hintText = "Kosong = semua rarity.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return Core.RARITY_ITEMS
        end,
        onChanged = function(a, b)
            M.placeDraft.rarities = parseKeyMap(dropdownValue(a, b))
        end,
    })

    local _, eggApi = ui:CreateRowDropdown(placeBody, {
        id = "steal.place.draft.eggs",
        label = "Egg",
        mode = "multi",
        placeholder = "All eggs",
        hintText = "Kosong = semua egg.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return listPlaceEggItems()
        end,
        onChanged = function(a, b)
            M.placeDraft.eggs = parseKeyMap(dropdownValue(a, b))
        end,
    })

    local _, mutApi = ui:CreateRowDropdown(placeBody, {
        id = "steal.place.draft.mutations",
        label = "Mutation",
        mode = "multi",
        placeholder = "Any Mutation...",
        hintText = "Kosong = any. No Mutation = polos saja.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return listPlaceMutationItems()
        end,
        onChanged = function(a, b)
            M.placeDraft.mutations = parseKeyMap(dropdownValue(a, b))
        end,
    })

    local kgWrap = wrapFieldStack(placeBody)
    local _, kgModeApi = ui:CreateRowDropdown(kgWrap, {
        id = "steal.place.draft.kgMode",
        label = "Kg mode",
        placeholder = "Mode",
        hintText = "Below = place yang lebih kecil. Above = place yang lebih besar.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.placeDraft.kgMode or DEFAULT_COMPARE_MODE,
        getItems = function()
            return COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.placeDraft.kgMode = clampCompareMode(dropdownValue(a, b), DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, kgApi = ui:CreateRowInput(kgWrap, {
        id = "steal.place.draft.kgRule",
        label = "Kg",
        initial = tostring(M.placeDraft.kgRule or "0"),
        clearOnFocus = false,
        onChanged = function(text)
            M.placeDraft.kgRule = unsignedRuleText(text)
        end,
    })

    local priceWrap = wrapFieldStack(placeBody)
    local _, priceModeApi = ui:CreateRowDropdown(priceWrap, {
        id = "steal.place.draft.priceMode",
        label = "Price mode",
        placeholder = "Mode",
        hintText = "Below = place yang lebih murah.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.placeDraft.priceMode or DEFAULT_COMPARE_MODE,
        getItems = function()
            return COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.placeDraft.priceMode = clampCompareMode(dropdownValue(a, b), DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, priceApi = ui:CreateRowInput(priceWrap, {
        id = "steal.place.draft.priceRule",
        label = "Price $",
        initial = tostring(M.placeDraft.priceRule or "0"),
        clearOnFocus = false,
        hintText = "k / m / b / t",
        onChanged = function(text)
            M.placeDraft.priceRule = unsignedRuleText(text)
        end,
    })

    local rateWrap = wrapFieldStack(placeBody)
    local _, rateModeApi = ui:CreateRowDropdown(rateWrap, {
        id = "steal.place.draft.rateMode",
        label = "Earn mode",
        placeholder = "Mode",
        hintText = "Below = place yang earn-nya lebih rendah.",
        clearable = false,
        persist = true,
        preserveItemOrder = true,
        initial = M.placeDraft.rateMode or DEFAULT_COMPARE_MODE,
        getItems = function()
            return COMPARE_ITEMS
        end,
        onChanged = function(a, b)
            M.placeDraft.rateMode = clampCompareMode(dropdownValue(a, b), DEFAULT_COMPARE_MODE)
        end,
    })
    local _, _, _, rateApi = ui:CreateRowInput(rateWrap, {
        id = "steal.place.draft.rateRule",
        label = "Earn $/s",
        initial = tostring(M.placeDraft.rateRule or "0"),
        clearOnFocus = false,
        hintText = "k / m / b / t",
        onChanged = function(text)
            M.placeDraft.rateRule = unsignedRuleText(text)
        end,
    })

    if formApi and type(formApi.attach) == "function" then
        formApi.attach("rarity", rarityApi, function()
            M.placeDraft.rarities = {}
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
        end)
        formApi.attach("egg", eggApi, function()
            M.placeDraft.eggs = {}
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
        end)
        formApi.attach("mutation", mutApi, function()
            M.placeDraft.mutations = {}
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
        end)
        formApi.attach("kg", { root = kgWrap }, function()
            M.placeDraft.kgRule = "0"
            M.placeDraft.kgMode = DEFAULT_COMPARE_MODE
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("price", { root = priceWrap }, function()
            M.placeDraft.priceRule = "0"
            M.placeDraft.priceMode = DEFAULT_COMPARE_MODE
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("rate", { root = rateWrap }, function()
            M.placeDraft.rateRule = "0"
            M.placeDraft.rateMode = DEFAULT_COMPARE_MODE
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        pcall(formApi.apply)
    end

    ui:CreateRowButton(placeBody, {
        text = "APPLY → Add Rule",
        kind = "primary",
        onClick = function()
            local modes = formApi and formApi.getModes and formApi.getModes() or {}
            local hasMode = false
            for _, on in pairs(modes) do
                if on == true then
                    hasMode = true
                    break
                end
            end
            if not hasMode then
            return
        end
            local rule = sanitizePlaceRule({
                enabled = true,
                fields = modes,
                rarities = modes.rarity and M.placeDraft.rarities or {},
                eggs = modes.egg and M.placeDraft.eggs or {},
                mutations = modes.mutation and M.placeDraft.mutations or {},
                kgRule = modes.kg and M.placeDraft.kgRule or "0",
                kgMode = modes.kg and M.placeDraft.kgMode or DEFAULT_COMPARE_MODE,
                rateRule = modes.rate and M.placeDraft.rateRule or "0",
                rateMode = modes.rate and M.placeDraft.rateMode or DEFAULT_COMPARE_MODE,
                priceRule = modes.price and M.placeDraft.priceRule or "0",
                priceMode = modes.price and M.placeDraft.priceMode or DEFAULT_COMPARE_MODE,
            })
            M.placeRules[#M.placeRules + 1] = rule
            persistPlaceRules()
            M.placeDraft = newPlaceDraft()
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end,
    })

    ui:CreateRowInput(placeBody, {
        id = "steal.place.wave",
        label = "Batch · eggs",
        persist = true,
        initial = tostring(M.placeWave or 1),
        clearOnFocus = false,
        hintText = "Berapa telur per putaran. Satu-satu ke server (bukan paralel).",
        onChanged = function(text)
            M.placeWave = math.clamp(math.floor(tonumber(text) or 1), 1, 8)
        end,
    })

    ui:CreateRowInput(placeBody, {
        id = "steal.place.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.placeDelay or 0.05),
        clearOnFocus = false,
        hintText = "Jeda antar telur. 0.05 aman; 0 = langsung.",
        onChanged = function(text)
            M.placeDelay = math.clamp(tonumber(text) or 0.05, 0, 5)
        end,
    })

    ui:CreateRowToggle(placeBody, {
        id = "steal.place.enabled",
        label = "Enable Auto Place Egg",
        persist = true,
        initial = M.placeEnabled == true,
        onChanged = function(on)
            M.setPlaceEnabled(on == true)
        end,
    })

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Hatch Egg",
        expanded = false,
        status = {
            id = "steal.hatch.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    local hatchGroup = ui:CreateGroup(body)
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    ui:CreateRowInput(hatchGroup, {
        id = "steal.hatch.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or 0.1),
        clearOnFocus = false,
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or 0.1, 0.05, 5)
        end,
    })

    ui:CreateRowToggle(hatchGroup, {
        id = "steal.hatch.enabled",
        label = "Enable Auto Hatch Egg",
        persist = true,
        initial = M.enabled == true,
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,        required = true },
    { key = "Mutation",  name = "Mutation",      factory = function() -- Auto Mutation: pakai consumable ke telur plot yang lolos rule.
-- Dump: Remotes.BossMastery.AskUseMutationConsumable(uid)
-- Item: Shard (MutationId Boss → Fractured) atau Scrambled (MutationId Scrambled).
-- Tool yang dipegang yang menentukan hasil. Peluang ~10%. Telur yang sudah
-- punya mutasi itu dilewati. Tanpa rule tersimpan tidak jalan.

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Mutation", 0)
end

G.__StealEggMutationGen = (tonumber(G.__StealEggMutationGen) or 0) + 1
local GEN = G.__StealEggMutationGen

local NO_MUTATION = "No Mutation"
local DEFAULT_COMPARE_MODE = "above"
local COMPARE_ITEMS = {
    { key = "above", name = "Above" },
    { key = "below", name = "Below" },
}
local DELAY_DEFAULT = 7
local DELAY_MIN = 1
local DELAY_MAX = 20
local BOSS_MUT = "Boss"
local SCRAMBLE_MUT = "Scrambled"
local SHARD_TOOL = "mutation consumable"
local SHARD_ITEM_TYPE = "MutationConsumable"
local KIND_ORDER = { "Boss", "Scrambled" }
-- Prompt game MaxActivationDistance = 7. Jaga di bawah itu sebelum invoke.
local NEAR_DIST = 6

local function newDraft()
    return {
        rarities = {},
        eggs = {},
        mutations = {},
        kgRule = "0",
        kgMode = DEFAULT_COMPARE_MODE,
        rateRule = "0",
        rateMode = DEFAULT_COMPARE_MODE,
        priceRule = "0",
        priceMode = DEFAULT_COMPARE_MODE,
    }
end

local M = {
    enabled = false,
    delay = DELAY_DEFAULT,
    items = { Boss = true, Scrambled = true },
    rules = {},
    draft = newDraft(),
    _token = 0,
    _loopOn = false,
    _used = 0,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggMutation
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.enabled = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggMutation = M

local tryRequire = Core.require
local parseKeyMap = Core.parseKeyMap
local dropdownValue = Core.dropdownValue
local Save, Remotes, EggItemUtil, Mutations

local function bindGame()
    Save = Save or tryRequire("Shared.Save") or tryRequire("Library.Client.Save")
    Remotes = Remotes or tryRequire("Shared.Remotes")
    EggItemUtil = EggItemUtil or tryRequire("Library.Util.EggItemUtil")
    Mutations = Mutations or tryRequire("Library.Modules.Mutations")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = type(fn) == "function" and fn or nil
    if M._onStatus then
        pcall(M._onStatus, M._status)
    end
end

local function getSave()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get)
    return ok and type(data) == "table" and data or nil
end

local function remote(bag, name)
    bindGame()
    local t = type(Remotes) == "table" and Remotes[bag]
    local rf = type(t) == "table" and t[name]
    if typeof(rf) == "Instance" then
        return rf
    end
    return nil
end

local function kindOn(kind)
    kind = tostring(kind or "")
    local items = M.items
    if type(items) ~= "table" or next(items) == nil then
        return true
    end
    return items[kind] == true
end

local function mutToolKind(t)
    if typeof(t) ~= "Instance" or not t:IsA("Tool") then
        return nil
    end
    if t:GetAttribute("ItemType") == SHARD_ITEM_TYPE then
        local id = tostring(t:GetAttribute("MutationId") or t:GetAttribute("MutationTemplate") or BOSS_MUT)
        if id == SCRAMBLE_MUT then
            return SCRAMBLE_MUT
        end
        return BOSS_MUT
    end
    local name = string.lower(tostring(t.Name or ""))
    if name:find("scrambled", 1, true) then
        return SCRAMBLE_MUT
    end
    if name:find(SHARD_TOOL, 1, true) or name:find("mutationconsumable", 1, true) then
        return BOSS_MUT
    end
    return nil
end

local function mutToolUses(t)
    local n = tonumber(t:GetAttribute("Uses"))
    if n and n > 0 then
        return math.floor(n)
    end
    local name = tostring(t.Name or "")
    local x = name:match("%[X(%d+)%]") or name:match("%[x(%d+)%]")
    return math.max(1, tonumber(x) or 1)
end

local function countBag(kind)
    kind = tostring(kind or BOSS_MUT)
    local n = 0
    local function eat(folder)
        if not folder then
            return
        end
        for _, t in ipairs(folder:GetChildren()) do
            if mutToolKind(t) == kind then
                n += mutToolUses(t)
            end
        end
    end
    eat(LP.Character)
    eat(LP:FindFirstChildOfClass("Backpack"))
    return n
end

function M.stock(kind)
    kind = tostring(kind or BOSS_MUT)
    local bag = countBag(kind)
    if bag > 0 then
        return bag
    end
    local data = getSave()
    if kind == SCRAMBLE_MUT then
        local sc = type(data) == "table" and (data.Scramble or data.DrScramble)
        local n = tonumber(sc and sc.MutationConsumables)
        if n == nil and type(G.StealEggScramble) == "table" then
            local snap = G.StealEggScramble._snap
            local st = type(snap) == "table" and snap.State
            n = tonumber(st and st.MutationConsumables)
        end
        return math.max(0, math.floor(n or 0))
    end
    local bm = type(data) == "table" and data.BossMastery
    return math.max(0, math.floor(tonumber(bm and bm.MutationConsumables) or 0))
end

-- Header status selalu menyebut sisa item supaya tidak perlu buka shop.
function M.stockDetail(extra)
    local bits = {}
    if kindOn("Boss") then
        bits[#bits + 1] = string.format("%d shard", M.stock("Boss"))
    end
    if kindOn(SCRAMBLE_MUT) then
        bits[#bits + 1] = string.format("%d scrambled", M.stock(SCRAMBLE_MUT))
    end
    if #bits == 0 then
        bits[1] = string.format("%d shard · %d scrambled", M.stock("Boss"), M.stock(SCRAMBLE_MUT))
    end
    local base = table.concat(bits, " · ")
    extra = tostring(extra or "")
    if extra == "" then
        return base
    end
    return base .. " · " .. extra
end

function M.successPct(kind)
    bindGame()
    local flags
    if kind == SCRAMBLE_MUT then
        flags = tryRequire("Shared.Flags.ScrambleMutationFlags")
        if type(flags) == "table" then
            local f = flags.SuccessPercent
            if type(f) == "table" and type(f.Get) == "function" then
                local ok, v = pcall(f.Get, f)
                if ok then
                    return math.clamp(tonumber(v) or 10, 0, 100)
                end
            end
        end
        return 10
    end
    flags = tryRequire("Shared.Flags.BossMasteryFlags")
    if type(flags) == "table" then
        local f = flags.MutationConsumableSuccessPercent
        if type(f) == "table" and type(f.Get) == "function" then
            local ok, v = pcall(f.Get, f)
            if ok then
                return math.clamp(tonumber(v) or 10, 0, 100)
            end
        end
    end
    return 10
end

function M.sectionTitle()
    return "Auto Mutation"
end

local function mapHas(map)
    return type(map) == "table" and next(map) ~= nil
end

local function copyMap(value)
    return parseKeyMap(value)
end

local function mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function newRuleId()
    return "mu" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

local function clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or ""))
    if fallback == "below" then
        return "below"
    end
    return "above"
end

local function unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

local function wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

local function parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(txt)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(txt)
end

local function parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), (raw == "" and "0" or unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(raw)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(raw)
end

local function isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

local function sanitizeRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = parseSignedScaledRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "rarity", "egg", "mutation", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        rarities = copyMap(rule.rarities),
        eggs = copyMap(rule.eggs or rule.names),
        mutations = copyMap(rule.mutations),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
    }
end

local function sanitizeRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = sanitizeRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

function M.setRules(list)
    M.rules = sanitizeRules(list)
    return M.rules
end

local function enabledRules()
    local out = {}
    for _, rule in ipairs(M.rules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    return out
end

local function ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

local function matchesEggs(category, eggs)
    if not mapHas(eggs) then
        return true
    end
    category = tostring(category or "")
    return eggs[category] == true or eggs[string.lower(category)] == true
end

local function matchesRarity(rarityNum, rarityId, rarities)
    if not mapHas(rarities) then
        return true
    end
    rarityNum = tonumber(rarityNum) or 0
    rarityId = tostring(rarityId or "")
    return rarities[tostring(rarityNum)] == true
        or rarities[rarityId] == true
        or rarities[string.lower(rarityId)] == true
end

local function matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "below" then
        return value <= n
    end
    return value >= n
end

local function matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if not mapHas(selected) then
        return true
    end
    local wantNone = false
    local hasPick = false
    for key, on in pairs(selected) do
        if on == true then
            if isNoMutationKey(key) then
                wantNone = true
            else
                hasPick = true
            end
        end
    end
    if wantNone and not hasPick then
        return not has
    end
    if hasPick then
        for i = 1, #names do
            local name = names[i]
            if type(Core.mutationPicked) == "function" then
                if Core.mutationPicked(name, selected) then
                    return true
                end
            elseif selected[name] == true or selected[string.lower(tostring(name))] == true then
                return true
            end
        end
        if wantNone and not has then
            return true
        end
        return false
    end
    return true
end

local function ruleMatches(rule, info)
    if type(rule) ~= "table" or type(info) ~= "table" then
        return false
    end
    if ruleFieldOn(rule, "egg") and not matchesEggs(info.category, rule.eggs) then
        return false
    end
    if ruleFieldOn(rule, "rarity") and not matchesRarity(info.rarityNum, info.rarity, rule.rarities) then
        return false
    end
    if ruleFieldOn(rule, "kg") and not matchesSigned(info.kg, rule.kg, rule.kgMode) then
        return false
    end
    if ruleFieldOn(rule, "rate") and not matchesSigned(info.rate, rule.rate, rule.rateMode) then
        return false
    end
    if ruleFieldOn(rule, "price") and not matchesSigned(info.price, rule.price, rule.priceMode) then
        return false
    end
    if ruleFieldOn(rule, "mutation") and not matchesMutation(info.muts, rule) then
        return false
    end
    return true
end

function M.allowed(info)
    info = type(info) == "table" and info or {}
    local rules = enabledRules()
    if #rules == 0 then
        return false
    end
    for _, rule in ipairs(rules) do
        if ruleMatches(rule, info) then
            return true
        end
    end
    return false
end

local function fmtKg(n)
    n = tonumber(n) or 0
    if n >= 100 then
        return string.format("%.0fkg", n)
    end
    if n >= 10 then
        return string.format("%.1fkg", n)
    end
    return string.format("%.2fkg", n)
end

local function fmtScaled(n, suffix)
    n = tonumber(n) or 0
    if n == math.floor(n) then
        return tostring(math.floor(n)) .. suffix
    end
    return string.format("%.1f%s", n, suffix)
end

local function fmtNum(n)
    n = tonumber(n) or 0
    if n >= 1e12 then
        return fmtScaled(n / 1e12, "t")
    end
    if n >= 1e9 then
        return fmtScaled(n / 1e9, "b")
    end
    if n >= 1e6 then
        return fmtScaled(n / 1e6, "m")
    end
    if n >= 1e3 then
        return fmtScaled(n / 1e3, "k")
    end
    return tostring(math.floor(n + 0.5))
end

local function joinNames(keys, nameOf)
    local parts = {}
    for i = 1, #keys do
        parts[i] = nameOf and nameOf(keys[i]) or keys[i]
    end
    return table.concat(parts, ", ")
end

local function rarityName(key)
    for _, item in ipairs(Core.RARITY_ITEMS or {}) do
        if tostring(item.key) == tostring(key) then
            return item.name
        end
    end
    return tostring(key)
end

local function eggNameOf(key)
    if type(Core.eggDisplayName) == "function" then
        local ok, n = pcall(Core.eggDisplayName, key)
        if ok and type(n) == "string" and n ~= "" then
            return n
        end
    end
    local cat = type(Core.getCatalog) == "function" and Core.getCatalog() or nil
    local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[tostring(key)]
    if type(item) == "table" then
        return tostring(item.name or key)
    end
    return tostring(key)
end

function M.formatRule(rule)
    rule = sanitizeRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    local eggKeys = mapKeyList(rule.eggs)
    local rarityKeys = mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = mapKeyList(rule.mutations)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            egg = #eggKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = price > 0,
            mutation = #mutKeys > 0,
        }
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(joinNames(rarityKeys, rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.egg then
        if #eggKeys == 0 then
            add("All eggs", "fruit")
        elseif #eggKeys > 2 then
            add(tostring(#eggKeys) .. " eggs", "fruit")
        else
            add(joinNames(eggKeys, eggNameOf), "fruit")
        end
    end
    if fields.kg then
        if kg > 0 then
            if rule.kgMode == "below" then
                add("<=" .. fmtKg(kg), "kg")
            else
                add(">=" .. fmtKg(kg), "kg")
            end
        else
            add("Any kg", "kg")
        end
    end
    if fields.price then
        if price > 0 then
            if rule.priceMode == "below" then
                add("$<=" .. fmtNum(price), "price")
            else
                add("$>=" .. fmtNum(price), "price")
            end
        else
            add("Any $", "price")
        end
    end
    if fields.rate then
        if rate > 0 then
            if rule.rateMode == "below" then
                add("earn <=" .. fmtNum(rate) .. "/s", "price")
            else
                add("earn >=" .. fmtNum(rate) .. "/s", "price")
            end
        else
            add("Any earn", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            add("Any mut", "mut")
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = isNoMutationKey(key) and "Normal"
                    or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    if #parts == 0 then
        add("All eggs", "default")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

local function listEggItems()
    if type(Core.listEggItems) == "function" then
        return Core.listEggItems({})
    end
    return {}
end

local function listMutationItems()
    local Wild = G.StealEggWild
    if type(Wild) == "table" and type(Wild.listMutationItems) == "function" then
        local ok, items = pcall(Wild.listMutationItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    return { { key = NO_MUTATION, name = NO_MUTATION } }
end

local function eggRecord(raw)
    if type(raw) ~= "table" then
        return nil
    end
    bindGame()
    if type(EggItemUtil) == "table" then
        local fn = EggItemUtil.DeserializeSavedEgg or EggItemUtil.Decode
        if type(fn) == "function" then
            local ok, egg = pcall(fn, raw)
            if ok and type(egg) == "table" then
                return egg
            end
        end
    end
    return raw
end

local function describeEgg(rec)
    rec = type(rec) == "table" and rec or {}
    local Wild = G.StealEggWild
    if type(Wild) == "table" and type(Wild.describeRecord) == "function" then
        local ok, desc = pcall(Wild.describeRecord, rec, true)
        if ok and type(desc) == "table" then
            desc.uid = rec.Uid or rec.uid or desc.uid
            return desc
        end
    end
    local category = tostring(rec.AssetCategory or rec.category or "")
    local cat = Core.getCatalog and Core.getCatalog() or nil
    local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[category]
    return {
        category = category,
        name = (type(item) == "table" and item.name) or category,
        rarity = (type(item) == "table" and item.rarity) or "",
        rarityNum = (type(item) == "table" and tonumber(item.rarityNumber)) or 0,
        kg = 0,
        rate = 0,
        price = 0,
        muts = {},
        uid = rec.Uid or rec.uid,
    }
end

local function mutCanon(name)
    name = tostring(name or "")
    if type(Core.canonicalMutation) == "function" then
        local ok, n = pcall(Core.canonicalMutation, name)
        if ok and type(n) == "string" and n ~= "" then
            name = n
        end
    end
    return string.lower(name)
end

local function hasTargetMut(muts, kind)
    if type(muts) ~= "table" then
        return false
    end
    local want = {}
    if kind == SCRAMBLE_MUT then
        want[string.lower(SCRAMBLE_MUT)] = true
    else
        want.boss = true
        want.fractured = true
    end
    for _, name in ipairs(muts) do
        local n = mutCanon(name)
        if want[n] == true then
            return true
        end
    end
    if kind ~= SCRAMBLE_MUT then
        if type(Mutations) == "table" and type(Mutations.Get) == "function" then
            local ok, spec = pcall(Mutations.Get, BOSS_MUT)
            local label = ok and type(spec) == "table" and string.lower(tostring(spec.DisplayName or "")) or ""
            if label ~= "" then
                for _, name in ipairs(muts) do
                    if mutCanon(name) == label then
                        return true
                    end
                end
            end
        end
    end
    return false
end

-- Posisi dunia telur: JANGAN percaya GetPivot mentah.
-- Client PlacedEggRenders kadang pivot-nya nyangkut di luar map / dekat origin
-- padahal Placement.LocalCFrame di save masih benar relatif CenterPoint plot.
-- Mutasi ikut pivot rusak → jalan ke "egg di luar map".
local PLOT_NEAR = 220

local function myPlotCenter()
    local W = G.StealEggWild
    if type(W) == "table" and type(W.getPlotData) == "function" then
        local ok, data = pcall(W.getPlotData)
        if ok and type(data) == "table" and typeof(data.CenterPoint) == "Instance" then
            return data.CenterPoint
        end
    end
    local plots = Workspace:FindFirstChild("Plots")
    if plots == nil then
        return nil
    end
    for _, folder in ipairs(plots:GetChildren()) do
        local sign = folder:FindFirstChild("PlotSign")
        local att = sign and sign:FindFirstChild("Attachment")
        local gui = att and att:FindFirstChild("YourBase")
        if gui then
            return folder:FindFirstChild("CenterPoint")
        end
    end
    return nil
end

local function localCFrameOf(egg)
    local lc = type(egg) == "table" and egg.Placement and egg.Placement.LocalCFrame
    if typeof(lc) == "CFrame" then
        return lc
    end
    if type(lc) ~= "table" then
        return nil
    end
    local a = {}
    for i = 1, 12 do
        a[i] = tonumber(lc[i])
    end
    if a[1] == nil or a[12] == nil then
        return nil
    end
    local ok, cf = pcall(CFrame.new, table.unpack(a, 1, 12))
    if ok and typeof(cf) == "CFrame" then
        return cf
    end
    return nil
end

local function nearPlot(pos, center)
    if typeof(pos) ~= "Vector3" or typeof(center) ~= "Instance" then
        return false
    end
    return (pos - center.Position).Magnitude <= PLOT_NEAR
end

local function eggPos(uid, egg)
    uid = tostring(uid or "")
    local center = myPlotCenter()
    local computed = nil
    if typeof(center) == "Instance" then
        local lcf = localCFrameOf(egg)
        if lcf ~= nil then
            local ok, world = pcall(function()
                return (center.CFrame * lcf).Position
            end)
            if ok and typeof(world) == "Vector3" and nearPlot(world, center) then
                computed = world
            end
        end
    end
    local folder = Workspace:FindFirstChild("PlacedEggRenders")
    local model = folder and folder:FindFirstChild(tostring(LP.UserId) .. "_" .. uid)
    local rendered = nil
    if model ~= nil then
        local ok, cf = pcall(function()
            return model:GetPivot()
        end)
        if ok and typeof(cf) == "CFrame" then
            rendered = cf.Position
        end
    end
    -- Model UserId_uid adalah telur sendiri. Radius 220 dari CenterPoint
    -- membuang telur sah di plot besar (live 379 stud) → status no match.
    if rendered ~= nil and (math.abs(rendered.X) > 20 or math.abs(rendered.Z) > 20) then
        return rendered
    end
    if computed ~= nil then
        return computed
    end
    -- Tanpa CenterPoint: render yang masuk akal saja (bukan origin / void jauh).
    if rendered ~= nil and typeof(center) ~= "Instance" then
        if math.abs(rendered.X) > 20 or math.abs(rendered.Z) > 20 then
            return rendered
        end
    end
    return nil
end

local function plotEggs()
    local Hatch = G.StealEggHatch
    if type(Hatch) == "table" and type(Hatch.listPlotEggs) == "function" then
        local ok, plot = pcall(Hatch.listPlotEggs)
        if ok and type(plot) == "table" and type(plot.eggs) == "table" and #plot.eggs > 0 then
            return plot.eggs
        end
    end
    local data = getSave()
    local inv = data and data.EggInventory
    local out = {}
    if type(inv) ~= "table" then
        return out
    end
    for uid, raw in pairs(inv) do
        local egg = eggRecord(raw)
        if type(egg) == "table" and type(egg.Placement) == "table" then
            local info = describeEgg(egg)
            info.uid = tostring(uid)
            out[#out + 1] = info
        end
    end
    return out
end

local function listTargets(kind)
    kind = tostring(kind or BOSS_MUT)
    local out = {}
    for _, info in ipairs(plotEggs()) do
        if type(info) == "table" then
            local uid = tostring(info.uid or info.Uid or "")
            info.uid = uid
            if uid ~= "" and hasTargetMut(info.muts, kind) ~= true and M.allowed(info) then
                info.pos = eggPos(uid, info)
                out[#out + 1] = info
            end
        end
    end
    table.sort(out, function(a, b)
        local ra, rb = tonumber(a.rarityNum) or 0, tonumber(b.rarityNum) or 0
        if ra ~= rb then
            return ra > rb
        end
        return (tonumber(a.kg) or 0) > (tonumber(b.kg) or 0)
    end)
    return out
end

local function dispatch()
    local d = G.StealEggDispatch
    return type(d) == "table" and d or nil
end

local function legsOwner()
    local d = dispatch()
    if d ~= nil and type(d.Owner) == "function" then
        local ok, who = pcall(d.Owner)
        if ok then
            return who
        end
    end
    return nil
end

-- Hop ke telur menarik badan, jadi mutation harus antre seperti fitur lain.
-- Ranknya paling rendah setelah belt: pekerjaan ini boleh menunggu selamanya.
local function holdLegs()
    local d = dispatch()
    if d == nil or type(d.Hold) ~= "function" then
        return true
    end
    local ok, got = pcall(d.Hold, "mutation")
    return ok == true and got == true
end

local function ownsLegs()
    local d = dispatch()
    if d == nil or type(d.Is) ~= "function" then
        return true
    end
    local ok, mine = pcall(d.Is, "mutation")
    return ok == true and mine == true
end

local function releaseLegs()
    local d = dispatch()
    if d ~= nil and type(d.Release) == "function" then
        pcall(d.Release, "mutation")
    end
end

local function stealBusy()
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.canSideWork) == "function" then
        local ok, idle = pcall(wild.canSideWork)
        if not (ok and idle == true) then
            return true
        end
    end
    if G.__StealEggBusy == true or G.__StealEggFarOn == true or G.__StealEggClaiming == true then
        return true
    end
    return false
end

local function heldTool()
    local char = LP.Character
    return char and char:FindFirstChildOfClass("Tool") or nil
end

local function toolKind(t)
    if typeof(t) ~= "Instance" or not t:IsA("Tool") then
        return nil
    end
    if t:GetAttribute("ItemType") ~= SHARD_ITEM_TYPE then
        local name = string.lower(tostring(t.Name or ""))
        if name:find("scrambled", 1, true) then
            return SCRAMBLE_MUT
        end
        if name:find(SHARD_TOOL, 1, true) or name:find("mutationconsumable", 1, true) then
            return BOSS_MUT
        end
        return nil
    end
    local id = tostring(t:GetAttribute("MutationId") or BOSS_MUT)
    if id == SCRAMBLE_MUT then
        return SCRAMBLE_MUT
    end
    return BOSS_MUT
end

local function isShardTool(t, kind)
    local got = toolKind(t)
    if got == nil then
        return false
    end
    if kind == nil then
        return true
    end
    return got == tostring(kind)
end

local function findShardTool(kind)
    local char = LP.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do
            if isShardTool(t, kind) then
                return t, true
            end
        end
    end
    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if isShardTool(t, kind) then
                return t, false
            end
        end
    end
    return nil, false
end

local function holdingShard(kind)
    local tool, held = findShardTool(kind)
    return held == true and tool ~= nil, tool
end

-- Server menolak dengan "Hold the Mutation Consumable first" selama toolnya masih
-- di ransel, jadi ini wajib sebelum invoke.
local function equipShard(kind)
    local tool, held = findShardTool(kind)
    if tool == nil then
        return false, kind == SCRAMBLE_MUT and "scrambled not in bag" or "shard not in bag"
    end
    if held then
        return true
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum == nil then
        return false, "no humanoid"
    end
    pcall(function()
        hum:UnequipTools()
    end)
    task.wait(0.05)
    pcall(function()
        hum:EquipTool(tool)
    end)
    for _ = 1, 20 do
        if tool.Parent == char then
            return true
        end
        task.wait(0.05)
    end
    return false, "equip failed"
end

local function restoreTool(prev)
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum == nil then
        return
    end
    if typeof(prev) == "Instance" and prev:IsA("Tool") and prev.Parent ~= nil and isShardTool(prev) ~= true then
        pcall(function()
            hum:EquipTool(prev)
        end)
        return
    end
    pcall(function()
        hum:UnequipTools()
    end)
end

-- Jangan CFrame-snap dari treadmill: server potong HP. Turun belt dulu.
local function leaveBelt()
    local W = G.StealEggWild
    if type(W) ~= "table" then
        return
    end
    G.__StealEggBeltHold = "mutation"
    if type(W._farmingBelt) == "boolean" then
        W._farmingBelt = false
    end
    if type(W.borrowBelt) == "function" then
        local ok, res = pcall(W.borrowBelt, "mutation")
        if ok and res == true then
            return
        end
    end
    -- borrow gagal (masih di pad): paksa doff + dorong lewat ensureOffBelt.
    if type(W.kickOffBelt) == "function" then
        pcall(W.kickOffBelt)
    end
    if type(W.ensureOffBelt) == "function" then
        pcall(W.ensureOffBelt, function()
            return M.enabled == true
        end)
    end
    G.__StealEggBeltHold = "mutation"
end

local function releaseBelt()
    -- Jangan panggil Wild.releaseBelt saat hold nil — itu no-op berbahaya
    -- kalau dipanggil tiap tick nomatch dan race dengan keepBeltOff.
    if G.__StealEggBeltHold ~= "mutation" then
        return
    end
    local W = G.StealEggWild
    if type(W) == "table" and type(W.releaseBelt) == "function" then
        pcall(W.releaseBelt)
    else
        G.__StealEggBeltHold = nil
    end
end

local function keepBeltOff()
    -- Tahan treadmill selama sesi mutation masih punya kerja.
    leaveBelt()
end

local function mutationHasWork()
    if M.enabled ~= true then
        return false
    end
    if #enabledRules() == 0 then
        return false
    end
    for _, kind in ipairs(KIND_ORDER) do
        if kindOn(kind) and M.stock(kind) > 0 and #listTargets(kind) > 0 then
            return true
        end
    end
    return false
end

local function myPos()
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    return hrp and hrp.Position or nil
end

local function nearEgg(pos)
    local p = myPos()
    return p ~= nil and (p - pos).Magnitude <= NEAR_DIST
end

-- Jalan glide ke telur. Bukan teleport: snap dari belt sering mati.
local function walkNearEgg(pos)
    if nearEgg(pos) then
        return true
    end
    keepBeltOff()
    task.wait(0.15)
    if nearEgg(pos) then
        return true
    end
    local Move = G.StealEggMove
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false, "no move"
    end
    local stand = Vector3.new(pos.X + 2.5, pos.Y, pos.Z + 2.5)
    local ok, why = Move.GoTo(CFrame.new(stand), {
        reason = "mutation",
        owner = "mutation",
        mode = "glide",
        speed = 600,
        skipLandWait = true,
        arrive = 3.5,
        shouldRun = function()
            return ownsLegs() == true and M.enabled == true
        end,
    })
    if type(Move.ApplyAccountWalkSpeed) == "function" then
        pcall(Move.ApplyAccountWalkSpeed)
    end
    if nearEgg(pos) then
        return true
    end
    if ok ~= true then
        return false, tostring(why or "walk failed")
    end
    return false, "still far from egg"
end

-- Balasan server berbentuk { Success, Mutated, Message }. Success = item
-- terpakai, Mutated = roll kena Fractured / Scrambled sesuai tool.
-- Belt TIDAK di-release di sini: treadmill baru boleh balik setelah sesi
-- mutation habis (no target / no item), bukan tiap 1 use.
local function invokeUse(uid, kind)
    kind = tostring(kind or BOSS_MUT)
    local rf = remote("BossMastery", "AskUseMutationConsumable")
    if rf == nil then
        return false, "no remote"
    end
    local data = getSave()
    local raw = type(data) == "table" and type(data.EggInventory) == "table" and data.EggInventory[uid]
    local egg = eggRecord(raw)
    local pos = eggPos(uid, egg)
    if pos == nil then
        return false, "egg not on plot"
    end
    keepBeltOff()
    local prev = heldTool()
    if holdLegs() ~= true then
        return false, "legs: " .. tostring(legsOwner() or "busy")
    end
    local okWalk, whyWalk = walkNearEgg(pos)
    if okWalk ~= true then
        releaseLegs()
        return false, whyWalk or "not near egg"
    end
    local okEquip, whyEquip = equipShard(kind)
    if okEquip ~= true then
        releaseLegs()
        restoreTool(prev)
        return false, whyEquip or "not holding item"
    end
    -- Pastikan masih dekat + item masih di tangan tepat sebelum invoke.
    if nearEgg(pos) ~= true then
        releaseLegs()
        restoreTool(prev)
        return false, "Get closer to the egg"
    end
    if holdingShard(kind) ~= true then
        releaseLegs()
        restoreTool(prev)
        return false, "Hold the Mutation Consumable first"
    end
    local ok, res = pcall(function()
        return rf:InvokeServer(uid)
    end)
    -- Jangan releaseLegs di sini. Lepas kaki = Auto Treadmill Hold("belt")
    -- langsung rebut → status Used rebutan treadmill antar shard.
    restoreTool(prev)
    keepBeltOff()
    if ok ~= true then
        return false, tostring(res or "invoke")
    end
    if type(res) == "table" then
        if res.Success == true then
            local hit = kind == SCRAMBLE_MUT and "SCRAMBLED" or "FRACTURED"
            return true, res.Mutated == true and hit or "fizzled"
        end
        return false, tostring(res.Message or "denied")
    end
    if res == true then
        return true
    end
    return false, tostring(res or "denied")
end

local function waitDelay(token)
    local sec = math.clamp(tonumber(M.delay) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
    local t0 = os.clock()
    while os.clock() - t0 < sec do
        if M.enabled ~= true or M._token ~= token or GEN ~= G.__StealEggMutationGen then
            return
        end
        -- Tetap tahan treadmill selama jeda antar shard.
        if G.__StealEggBeltHold ~= "mutation" then
            keepBeltOff()
        end
        task.wait(0.2)
    end
end

local function tick(token)
    if stealBusy() then
        emit("Wait", "warn", "steal")
        return "busy"
    end
    -- Jangan sampai memulai siklus kalau kaki jelas tidak akan kebagian: lebih
    -- baik diam daripada menyiapkan alat lalu ditolak di depan hop.
    local d = dispatch()
    if d ~= nil and type(d.Can) == "function" then
        local okCan, can = pcall(d.Can, "mutation")
        if okCan and can ~= true then
            emit("Wait", "warn", M.stockDetail("legs: " .. tostring(legsOwner() or "?")))
            return "busy"
        end
    end
    if #enabledRules() == 0 then
        emit("Idle", "muted", M.stockDetail("add rule"))
        return "norule"
    end
    local kind = nil
    local targets = nil
    for _, k in ipairs(KIND_ORDER) do
        if kindOn(k) and M.stock(k) > 0 then
            local list = listTargets(k)
            if #list > 0 then
                kind = k
                targets = list
                break
            end
        end
    end
    if kind == nil then
        if (kindOn("Boss") and M.stock("Boss") > 0) or (kindOn(SCRAMBLE_MUT) and M.stock(SCRAMBLE_MUT) > 0) then
            emit("Idle", "muted", M.stockDetail("no match"))
            return "nomatch"
        end
        emit("Idle", "muted", M.stockDetail("buy first"))
        return "empty"
    end
    keepBeltOff()
    local info = targets[1]
    local tag = kind == SCRAMBLE_MUT and "scrambled" or "shard"
    emit("Using", "live", M.stockDetail(tag .. " · " .. tostring(info.name or "egg")))
    local before = M.stock(kind)
    local ok, why = invokeUse(info.uid, kind)
    task.wait(0.4)
    if ok == true or M.stock(kind) < before then
        M._used += 1
        local note = tostring(why or "")
        emit("Used", "success", M.stockDetail(note ~= "" and note or tostring(info.name or "egg")))
        return "used"
    end
    emit("Fail", "error", M.stockDetail(tostring(why or "denied")))
    return "fail"
end

local function loop(token)
    while M.enabled == true and M._token == token and GEN == G.__StealEggMutationGen do
        local ok, why = pcall(tick, token)
        if ok ~= true then
            emit("Error", "warn", M.stockDetail(tostring(why)))
            why = "error"
        end
        if M.enabled ~= true or M._token ~= token then
            break
        end
        -- Selesai / tidak ada kerja → lepas kaki + treadmill boleh lagi.
        -- Masih ada target+shard → tahan legs+belt, jangan naik treadmill antar use.
        if why == "empty" or why == "norule" or why == "nomatch" or why == "busy" then
            releaseLegs()
            releaseBelt()
            local t0 = os.clock()
            local waitSec = why == "busy" and 0.35 or 2
            while os.clock() - t0 < waitSec do
                if M.enabled ~= true or M._token ~= token then
                    break
                end
                task.wait(0.25)
            end
        else
            if mutationHasWork() then
                if holdLegs() ~= true then
                    -- Steal/boss ambil kaki: tunggu, jangan remount belt dulu.
                    keepBeltOff()
                else
                    keepBeltOff()
                end
                waitDelay(token)
            else
                releaseLegs()
                releaseBelt()
                waitDelay(token)
            end
        end
    end
    releaseLegs()
    releaseBelt()
end

function M.hasWork()
    return mutationHasWork() == true
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        emit("On", "live", M.stockDetail())
        task.spawn(function()
            loop(token)
            if M._token == token then
                M._loopOn = false
                if M.enabled ~= true then
                    emit("Idle", "muted", M.stockDetail())
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._token = (tonumber(M._token) or 0) + 1
    -- Kalau dimatikan tepat saat jalan ke telur, kaki/belt bisa tertinggal.
    releaseLegs()
    releaseBelt()
    G.__StealEggTpHold = false
    emit("Idle", "muted", M.stockDetail())
end

function M.Stop()
    M.setEnabled(false)
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    if type(values["steal.mutation.rules"]) == "table" then
        M.setRules(values["steal.mutation.rules"])
    end
    if values["steal.mutation.draft.rarity"] ~= nil then
        M.draft.rarities = parseKeyMap(values["steal.mutation.draft.rarity"])
    end
    if values["steal.mutation.draft.eggs"] ~= nil then
        M.draft.eggs = parseKeyMap(values["steal.mutation.draft.eggs"])
    end
    if values["steal.mutation.draft.mutations"] ~= nil then
        M.draft.mutations = parseKeyMap(values["steal.mutation.draft.mutations"])
    end
    if values["steal.mutation.draft.kgRule"] ~= nil then
        local kg, kgMode, kgRule = parseSignedRule(values["steal.mutation.draft.kgRule"], values["steal.mutation.draft.kgMode"])
        M.draft.kgRule = kgRule
        M.draft.kgMode = clampCompareMode(values["steal.mutation.draft.kgMode"] or kgMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.mutation.draft.kgMode"] ~= nil then
        M.draft.kgMode = clampCompareMode(values["steal.mutation.draft.kgMode"], DEFAULT_COMPARE_MODE)
    end
    if values["steal.mutation.draft.rateRule"] ~= nil then
        local rate, rateMode, rateRule = parseSignedScaledRule(values["steal.mutation.draft.rateRule"], values["steal.mutation.draft.rateMode"])
        M.draft.rateRule = rateRule
        M.draft.rateMode = clampCompareMode(values["steal.mutation.draft.rateMode"] or rateMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.mutation.draft.rateMode"] ~= nil then
        M.draft.rateMode = clampCompareMode(values["steal.mutation.draft.rateMode"], DEFAULT_COMPARE_MODE)
    end
    if values["steal.mutation.draft.priceRule"] ~= nil then
        local price, priceMode, priceRule = parseSignedScaledRule(values["steal.mutation.draft.priceRule"], values["steal.mutation.draft.priceMode"])
        M.draft.priceRule = priceRule
        M.draft.priceMode = clampCompareMode(values["steal.mutation.draft.priceMode"] or priceMode, DEFAULT_COMPARE_MODE)
    elseif values["steal.mutation.draft.priceMode"] ~= nil then
        M.draft.priceMode = clampCompareMode(values["steal.mutation.draft.priceMode"], DEFAULT_COMPARE_MODE)
    end
    local delay = tonumber(values["steal.mutation.delay"])
    if delay then
        M.delay = math.clamp(delay, DELAY_MIN, DELAY_MAX)
    end
    if values["steal.mutation.items"] ~= nil then
        M.items = parseKeyMap(values["steal.mutation.items"])
    end
    if values["steal.mutation.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.mutation.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    if M.enabled ~= true then
        emit("Idle", "muted", M.stockDetail())
    end

    local body, _, statusApi = ui:CreateSection({
        title = M.sectionTitle(),
        expanded = false,
        status = {
            id = "steal.mutation.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    -- Saat loop mati tidak ada yang menyegarkan header, padahal shard bertambah
    -- lewat Auto Scramble shop. Poller ringan ini ikut mati bersama sectionnya.
    local statusSeq = (tonumber(G.__StealEggMutationStatusSeq) or 0) + 1
    G.__StealEggMutationStatusSeq = statusSeq
    task.spawn(function()
        while GEN == G.__StealEggMutationGen and statusSeq == G.__StealEggMutationStatusSeq do
            task.wait(5)
            if not (body and body.Parent) then
                return
            end
            if M.enabled ~= true then
                emit("Idle", "muted", M.stockDetail())
            end
        end
    end)

    local ruleApi
