        formatItem = function(rule)
            return M.formatRule(rule)
        end,
        onLoad = function(list)
            M.setRules(list)
        end,
        onToggle = function(rule, enabled)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            for _, item in ipairs(M.rules) do
                if tostring(item.id) == id then
                    item.enabled = enabled == true
                    break
                end
            end
            persistRules()
        end,
        onDelete = function(rule)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            local nextList = {}
            for _, item in ipairs(M.rules) do
                if tostring(item.id) ~= id then
                    nextList[#nextList + 1] = item
                end
            end
            M.rules = nextList
            persistRules()
        end,
    })
    ruleApi = bindRules

    local formApi
    local _, bindForm = ui:CreateRuleForm(body, {
        id = "steal.mutation.draft.modes",
        label = "Rule Fields",
        placeholder = "Pick fields...",
        hintText = "Pilih Rarity / Egg / Mutation / Kg / Price / Earn, baru input muncul.",
        persist = true,
        modes = {
            { key = "rarity", name = "Rarity" },
            { key = "egg", name = "Egg" },
            { key = "mutation", name = "Mutation" },
            { key = "kg", name = "Kg" },
            { key = "price", name = "Price $" },
            { key = "rate", name = "Earn $/s" },
        },
    })
    formApi = bindForm

    local _, rarityApi = ui:CreateRowDropdown(body, {
        id = "steal.mutation.draft.rarity",
