            end
        end)
        formApi.attach("egg", eggApi, function()
            M.draft.eggs = {}
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
        end)
        formApi.attach("mutation", mutApi, function()
            M.draft.mutations = {}
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
        end)
        formApi.attach("kg", { root = kgWrap }, function()
            M.draft.kgRule = "0"
            M.draft.kgMode = DEFAULT_COMPARE_MODE
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("price", { root = priceWrap }, function()
            M.draft.priceRule = "0"
            M.draft.priceMode = DEFAULT_COMPARE_MODE
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        formApi.attach("rate", { root = rateWrap }, function()
            M.draft.rateRule = "0"
            M.draft.rateMode = DEFAULT_COMPARE_MODE
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end)
        pcall(formApi.apply)
    end

    ui:CreateRowButton(body, {
        text = "APPLY → Add Rule",
        kind = "primary",
        onClick = function()
            local function liveText(api, fallback)
                if api and type(api.get) == "function" then
                    local ok, t = pcall(api.get)
                    if ok and type(t) == "string" then
                        t = (t:gsub("^%s+", ""):gsub("%s+$", ""))
                        if t ~= "" then
                            return t
                        end
                    end
                end
                return fallback
            end
            M.draft.kgRule = unsignedRuleText(liveText(kgApi, M.draft.kgRule))
            M.draft.priceRule = unsignedRuleText(liveText(priceApi, M.draft.priceRule))
            M.draft.rateRule = unsignedRuleText(liveText(rateApi, M.draft.rateRule))
            local modes = formApi and formApi.getModes and formApi.getModes() or {}
            local hasMode = false
            for _, on in pairs(modes) do
                if on == true then
                    hasMode = true
                    break
                end
            end
            local kgN = parseScaledNumber(M.draft.kgRule)
            local priceN = parseScaledNumber(M.draft.priceRule)
            local rateN = parseScaledNumber(M.draft.rateRule)
            if (tonumber(kgN) or 0) > 0 then
                modes.kg = true
            end
            if (tonumber(priceN) or 0) > 0 then
                modes.price = true
            end
            if (tonumber(rateN) or 0) > 0 then
                modes.rate = true
            end
            for _, on in pairs(modes) do
                if on == true then
                    hasMode = true
                    break
                end
            end
            if not hasMode then
                return
            end
            local rule = sanitizeRule({
                enabled = true,
                fields = modes,
                rarities = modes.rarity and M.draft.rarities or {},
                eggs = modes.egg and M.draft.eggs or {},
                mutations = modes.mutation and M.draft.mutations or {},
                kgRule = modes.kg and M.draft.kgRule or "0",
                kgMode = modes.kg and M.draft.kgMode or DEFAULT_COMPARE_MODE,
                rateRule = modes.rate and M.draft.rateRule or "0",
                rateMode = modes.rate and M.draft.rateMode or DEFAULT_COMPARE_MODE,
                priceRule = modes.price and M.draft.priceRule or "0",
                priceMode = modes.price and M.draft.priceMode or DEFAULT_COMPARE_MODE,
            })
            if type(rule) ~= "table" then
                return
            end
            M.rules[#M.rules + 1] = rule
            persistRules()
            M.draft = newDraft()
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
            if eggApi and type(eggApi.clear) == "function" then
                pcall(eggApi.clear, true)
            end
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
            if kgApi and type(kgApi.set) == "function" then
                pcall(kgApi.set, "0", true)
            end
            if kgModeApi and type(kgModeApi.setSelected) == "function" then
                pcall(kgModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
            if priceApi and type(priceApi.set) == "function" then
                pcall(priceApi.set, "0", true)
            end
            if priceModeApi and type(priceModeApi.setSelected) == "function" then
                pcall(priceModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
            if rateApi and type(rateApi.set) == "function" then
                pcall(rateApi.set, "0", true)
            end
            if rateModeApi and type(rateModeApi.setSelected) == "function" then
                pcall(rateModeApi.setSelected, DEFAULT_COMPARE_MODE, true)
            end
        end,
    })

    ui:CreateRowInput(body, {
        id = "steal.mutation.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or DELAY_DEFAULT),
        clearOnFocus = false,
        hintText = "Jeda antar pakai. Animasi game ~6 detik, default 7.",
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        end,
    })
    ui:CreateRowDropdown(body, {
        id = "steal.mutation.items",
        label = "Item",
        mode = "multi",
        placeholder = "Shard + Scrambled",
        hintText = "Shard = Fractured. Scrambled = mutasi Scrambled. Kosong = keduanya. Rule di atas tetap filter telur.",
        clearable = true,
        persist = true,
        preserveItemOrder = true,
        initial = M.items,
        getItems = function()
            return {
                { key = "Boss", name = string.format("Shard · Fractured · x%d", M.stock("Boss")) },
                { key = "Scrambled", name = string.format("Scrambled · x%d", M.stock(SCRAMBLE_MUT)) },
            }
        end,
        onChanged = function(a, b)
            M.items = parseKeyMap(dropdownValue(a, b))
        end,
    })
    ui:CreateRowToggle(body, {
        id = "steal.mutation.enabled",
        label = "Enable Auto Mutation",
        persist = true,
        initial = M.enabled == true,
        hintText = string.format("Pakai item terpilih ke telur plot yang lolos rule. Shard %d%% Fractured. Scrambled %d%% Scrambled.", M.successPct("Boss"), M.successPct(SCRAMBLE_MUT)),
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,    required = true },
    { key = "IndexComplete", name = "Index Complete", factory = function() -- Auto Completed Index: steal egg yang belum uncovered, lalu place + hatch sendiri.
-- Tidak menyalakan toggle Auto Place / Auto Hatch.

local Players = game:GetService("Players")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before IndexComplete", 0)
end

G.__StealEggIndexGen = (tonumber(G.__StealEggIndexGen) or 0) + 1
local GEN = G.__StealEggIndexGen

local DELAY_MIN = 0.1
local DELAY_MAX = 8
local DELAY_DEFAULT = 0.35

local M = {
    enabled = false,
    delay = DELAY_DEFAULT,
    _token = 0,
    _loopOn = false,
    _busy = false,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggIndexComplete
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.enabled = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggIndexComplete = M

local tryRequire = Core.require
local Save, Remotes, Network

local function bindGame()
    Save = Save or tryRequire("Library.Client.Save") or tryRequire("Shared.Save")
    Remotes = Remotes or tryRequire("Shared.Remotes")
    Network = Network or tryRequire("Library.Client.Network")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = type(fn) == "function" and fn or nil
    if M._onStatus then
        pcall(M._onStatus, M._status)
    end
end

local function getSave()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get)
    if ok and type(data) == "table" then
        return data
    end
    local ok2, data2 = pcall(Save.Get, LP, false)
    if ok2 and type(data2) == "table" then
        return data2
    end
    return nil
end

function M.isDiscovered(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    local data = getSave()
    local index = data and data.Index
    return type(index) == "table" and index[category] == true
end

function M.isMissing(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    return M.isDiscovered(category) ~= true
end

local function eggCategory(raw)
    if type(raw) ~= "table" then
        return ""
    end
    return tostring(raw.AssetCategory or raw.category or raw.Category or "")
end

function M.hasOwnedEgg(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return false
    end
    for _, raw in pairs(inv) do
        if eggCategory(raw) == category then
            return true
        end
    end
    return false
end

function M.hasPlacedEgg(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return false
    end
    for _, raw in pairs(inv) do
        if type(raw) == "table" and raw.Placement ~= nil and eggCategory(raw) == category then
            return true
        end
    end
    return false
end

function M.hasOwnedPet(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    local data = getSave()
    local inv = data and data.Inventory
    if type(inv) ~= "table" then
        return false
    end
    for _, raw in pairs(inv) do
        if eggCategory(raw) == category then
            return true
        end
    end
    return false
end

-- Steal hanya kalau index kosong DAN belum ada egg jenis itu di bag/plot (supaya tidak numpuk).
function M.needsSteal(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    if M.isMissing(category) ~= true then
        return false
    end
    if M.hasOwnedEgg(category) or M.hasOwnedPet(category) then
        return false
    end
    return true
end

function M.wantsIndexSteal()
    return M.enabled == true
end

local function eggName(category, rec)
    local wild = G.StealEggWild
    if type(rec) == "table" and type(wild) == "table" and type(wild.describeRecord) == "function" then
        local ok, info = pcall(wild.describeRecord, rec)
        if ok and type(info) == "table" then
            return tostring(info.name or info.category or category)
        end
    end
    local cat = Core.getCatalog and Core.getCatalog() or nil
    local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[tostring(category)]
    if type(item) == "table" and item.name then
        return tostring(item.name)
    end
    return tostring(category)
end

local function missingCount()
    local cat = Core.getCatalog and Core.getCatalog() or nil
    local eggs = type(cat) == "table" and cat.eggs
    if type(eggs) ~= "table" then
        return 0
    end
    local n = 0
    local seen = {}
    for _, row in ipairs(eggs) do
        local key = tostring(row and (row.key or row.category) or "")
        if key ~= "" and seen[key] ~= true then
            seen[key] = true
            if M.isMissing(key) then
                n += 1
            end
        end
    end
    return n
end

local function listBagMissing()
    local out = {}
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return out
    end
    local held
    local char = LP.Character
    local tool = char and char:FindFirstChildWhichIsA("Tool")
    if tool then
        held = tostring(tool:GetAttribute("UID") or "")
    end
    local best = {}
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        local egg = type(raw) == "table" and raw or nil
        if type(egg) == "table" and egg.Placement == nil then
            local category = eggCategory(egg)
            if category ~= "" and M.isMissing(category) and M.hasPlacedEgg(category) ~= true then
                local row = {
                    uid = uid,
                    category = category,
                    name = eggName(category, egg),
                    held = held ~= "" and uid == held,
                }
                local prev = best[category]
                if prev == nil or (row.held == true and prev.held ~= true) then
                    best[category] = row
                end
            end
        end
    end
    for _, row in pairs(best) do
        out[#out + 1] = row
    end
    table.sort(out, function(a, b)
        if a.held ~= b.held then
            return a.held == true
        end
        return tostring(a.name) < tostring(b.name)
    end)
    return out
end

-- Egg yang masih dibutuhkan index (1 di bag, belum di plot). Auto Sell jangan jual.
function M.shouldKeepEgg(uid, category)
    if M.enabled ~= true then
        return false
    end
    uid = tostring(uid or "")
    category = tostring(category or "")
    if uid == "" or category == "" then
        return false
    end
    if M.isMissing(category) ~= true then
        return false
    end
    if M.hasPlacedEgg(category) then
        return false
    end
    for _, row in ipairs(listBagMissing()) do
        if row.uid == uid and row.category == category then
            return true
        end
    end
    return false
end

function M.hasPlacePending()
    if M.enabled ~= true then
        return false
    end
    local Hatch = G.StealEggHatch
    if type(Hatch) == "table" and type(Hatch.plotAtCap) == "function" then
        local ok, full = pcall(Hatch.plotAtCap)
        if ok and full == true then
            return false
        end
    end
    return #listBagMissing() > 0
end

local function stealBusy()
    local wild = G.StealEggWild
    if type(wild) ~= "table" then
        return false
    end
    if wild._busy == true or G.__StealEggBusy == true or G.__StealEggClaiming == true then
        return true
    end
    local carry = wild._carry
    if type(carry) == "table" and carry.IsCarrying == true then
        return true
    end
    return false
end

local function sellEggBusy()
    local sell = G.StealEggSell
    return type(sell) == "table" and type(sell.egg) == "table" and sell.egg._busy == true
end

local function inPlot()
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.inPlotHome) == "function" then
        local ok, v = pcall(wild.inPlotHome)
        if ok then
            return v == true
        end
    end
    if type(wild) == "table" and type(wild.isOnPetArea) == "function" then
        local ok, v = pcall(wild.isOnPetArea)
        if ok and v == true then
            return true
        end
    end
    return false
end

local function goPlot(stillOn)
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.ensureInPen) == "function" then
        local ok, v = pcall(wild.ensureInPen, "index", stillOn)
        return ok == true and v ~= false
    end
    return true
end

local function redeem(category)
    bindGame()
    local bag = Remotes and Remotes.Codex
    local rf = bag and bag.AskRedeem
    if typeof(rf) == "Instance" and type(rf.InvokeServer) == "function" and category and category ~= "" then
        pcall(function()
            rf:InvokeServer(category)
        end)
    end
    local all = bag and bag.AskRedeemAll
    if typeof(all) == "Instance" and type(all.InvokeServer) == "function" then
        pcall(function()
            all:InvokeServer()
        end)
    elseif type(Network) == "table" and type(Network.Invoke) == "function" then
        pcall(Network.Invoke, "Index: RequestClaimAll")
    end
end

local function placeGapSec()
    local Hatch = G.StealEggHatch
    local n = type(Hatch) == "table" and tonumber(Hatch.placeDelay)
    return math.clamp(n or 0.35, 0.1, 5)
end

local function waitGap(stillOn, sec)
    sec = tonumber(sec) or 0
    if sec <= 0 then
        return
    end
    local t0 = os.clock()
    while os.clock() - t0 < sec do
        if type(stillOn) == "function" and stillOn() ~= true then
            return
        end
        task.wait(0.05)
    end
end

local function placeMissing(stillOn)
    local Hatch = G.StealEggHatch
    if type(Hatch) ~= "table" or type(Hatch.placeForced) ~= "function" then
        return 0, "hatch missing"
    end
    if type(Hatch.plotAtCap) == "function" then
        local ok, full = pcall(Hatch.plotAtCap)
        if ok and full == true then
            return 0, "plot full"
        end
    end
    local items = listBagMissing()
    if #items == 0 then
        return 0, "no egg"
    end
    -- Kunci steal hanya saat benar-benar place, bukan tiap tick Idle.
    M._busy = true
    if not goPlot(stillOn) then
        M._busy = false
        return 0, "need plot"
    end
    if inPlot() ~= true then
        M._busy = false
        return 0, "need plot"
    end
    local used
    if type(Hatch.placeSlotMap) == "function" then
        local okSlots, slots = pcall(Hatch.placeSlotMap)
        if okSlots == true and type(slots) == "table" then
            used = slots
        end
    end
    local n = 0
    for i, row in ipairs(items) do
        if stillOn() ~= true then
            break
        end
        emit("Place", "live", row.name)
        local ok, err = Hatch.placeForced(row.uid, row.name, used)
        if ok then
            n += 1
            emit("Placed", "success", row.name)
            if i < #items then
                waitGap(stillOn, placeGapSec())
            end
        else
            local msg = tostring(err or "")
            if string.find(string.lower(msg), "full", 1, true) then
                M._busy = false
                return n, "plot full"
            end
        end
    end
    M._busy = false
    return n, nil
end

local function hatchMissing(stillOn)
    local Hatch = G.StealEggHatch
    if type(Hatch) ~= "table" or type(Hatch.hatchForced) ~= "function" then
        return 0, "hatch missing"
    end
    if type(Hatch.listPlotEggs) ~= "function" then
        return 0, nil
    end
    local okList, data = pcall(Hatch.listPlotEggs)
    if not okList or type(data) ~= "table" or type(data.eggs) ~= "table" then
        return 0, nil
    end
    local n = 0
    local growing = 0
    for _, info in ipairs(data.eggs) do
        if stillOn() ~= true then
            break
        end
        local category = tostring(info.category or info.AssetCategory or "")
        if M.isMissing(category) then
            if info.ready == true then
                M._busy = true
                emit("Hatch", "live", tostring(info.name or category))
                local ok, err = Hatch.hatchForced(info.uid, info.name)
                M._busy = false
                if ok then
                    n += 1
                    emit("Hatched", "success", tostring(info.name or category))
                    redeem(category)
                    waitGap(stillOn, 0.1)
                else
                    emit("Wait", "warn", tostring(err or "hatch"))
                end
            else
                growing += 1
            end
        end
    end
    return n, growing
end

local function tick(stillOn)
    if stealBusy() then
        emit("Wait", "warn", "steal")
        return "busy"
    end
    if sellEggBusy() then
        emit("Wait", "warn", "sell")
        return "busy"
    end
    local placed, placeErr = placeMissing(stillOn)
    if stillOn() ~= true then
        return "off"
    end
    local hatched, growing = hatchMissing(stillOn)
    if stillOn() ~= true then
        return "off"
    end
    local left = missingCount()
    if placeErr == "plot full" then
        emit("Full", "warn", tostring(left) .. " missing")
        return "full"
    end
    if placeErr == "need plot" then
        emit("Wait", "warn", "need plot")
        return "plot"
    end
    if (tonumber(placed) or 0) > 0 or (tonumber(hatched) or 0) > 0 then
        emit("On", "live", tostring(left) .. " missing")
        return "ok"
    end
    if (tonumber(growing) or 0) > 0 then
        emit("Idle", "muted", "growing · " .. tostring(left) .. " missing")
        return "grow"
    end
    local wild = G.StealEggWild
    local stealOn = type(wild) == "table" and wild.enabled == true
    if stealOn then
        emit("Idle", "muted", tostring(left) .. " missing")
    else
        emit("Idle", "muted", "steal off · " .. tostring(left) .. " missing")
    end
    return "idle"
end

local function loop(token)
    local function stillOn()
        return M.enabled == true and M._token == token and GEN == G.__StealEggIndexGen
    end
    while stillOn() do
        -- Jangan kunci steal di tick Idle / growing. _busy hanya di place/hatch.
        M._busy = false
        local ok, why = pcall(tick, stillOn)
        M._busy = false
        local wild = G.StealEggWild
        if type(wild) == "table" and type(wild.releaseBelt) == "function" then
            pcall(wild.releaseBelt)
        end
        local d = G.StealEggDispatch
        if type(d) == "table" and type(d.Release) == "function" then
            pcall(d.Release, "index")
        end
        if stillOn() ~= true then
            break
        end
        local waitSec = math.clamp(tonumber(M.delay) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        if ok and why == "ok" then
            waitSec = 0.05
        elseif ok and (why == "busy" or why == "plot") then
            waitSec = 0.2
        elseif ok and why == "full" then
            waitSec = 2.5
        elseif ok and why == "grow" then
            waitSec = math.clamp(waitSec, 0.35, 1)
        end
        waitGap(stillOn, waitSec)
    end
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        emit("On", "live", "watching")
        task.spawn(function()
            loop(token)
            if M._token == token then
                M._loopOn = false
                if M.enabled ~= true then
                    emit("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._token = (tonumber(M._token) or 0) + 1
    emit("Idle", "muted", "off")
end

function M.Stop()
    M.setEnabled(false)
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["steal.indexComplete.delay"])
    if delay then
        M.delay = math.clamp(delay, DELAY_MIN, DELAY_MAX)
    end
    if values["steal.indexComplete.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.indexComplete.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Completed Index",
        expanded = true,
        status = {
            id = "steal.indexComplete.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local group = ui:CreateGroup(body)
    ui:CreateRowInput(group, {
        id = "steal.indexComplete.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or DELAY_DEFAULT),
        clearOnFocus = false,
        hintText = "Index ON: steal egg yang belum uncovered (meski rule Zone/Earn ON), lalu place+hatch sendiri. Plot full = skip place.",
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.indexComplete.enabled",
        label = "Enable Auto Completed Index",
        persist = true,
        initial = M.enabled == true,
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end, required = true },
    { key = "Scramble",  name = "Auto Scramble", factory = function() -- Auto Scramble (Dr. Scramble): ganti Auto Boss + Auto Rift.
-- Dump:
--   Remotes.Scramble.Request:InvokeServer("Snapshot" | "Discover" | "Vault" | "Shop")
--   Remotes.Scramble.Collect:FireServer({ dropId, ... })
--   Outbreak Window.Active → drone auto-swing (bat Activate, radius 12)
--   Quest: LostPart1/2 + DronePart1-3 → Discover → Vault "The Scrambler"
--   Shop: Samples + Quote + ShopSequence
-- Rank 90 (sama steal). Kaki hanya saat auto steal idle / no match.
-- Ada steal match → lepas kaki segera. Tidak wrap remote, tidak TP Instant, tidak HHT.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local Workspace = game:GetService("Workspace")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Scramble", 0)
end

G.__StealEggScrambleGen = (tonumber(G.__StealEggScrambleGen) or 0) + 1
local GEN = G.__StealEggScrambleGen

local DELAY_DEFAULT = 0.35
local DELAY_MIN = 0.05
local DELAY_MAX = 3
local SWING_GAP = 0.72
local DRONE_REACH = 12
local HIT_STAY = 7
local DROP_REACH = 8
local QUEST_REACH = 4
local QUEST_PROMPT = 14
local CLAIM_PULSES = 24
local PIN_SEC = 25
-- Lapangan: cap 280 + hop~24 (client test hub Z sampai pad cave hidup, rubber 0).
-- Speed steal 955 + steerAround nembus plot = GuardHit X~964. Pad: pelan meter terakhir.
-- Dalam cave: cap lebih rendah biar tidak nembus mesh.
local SPEED_CAP = 280
local CAVE_SPEED = 220
local PAD_NEAR = 14
local PAD_NEAR_SPEED = 200

local M = {
    enabled = false,
    autoBuy = false,
    shopWant = {},
    delay = DELAY_DEFAULT,
    _token = 0,
    _loopOn = false,
    _busy = false,
    _want = false,
    _snap = nil,
    _snapAt = 0,
    _drops = {},
    _swingAt = 0,
    _reqAt = 0,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggScramble
if type(prev) == "table" and prev ~= M then
    pcall(function()
        if type(prev.Stop) == "function" then
            prev.Stop()
        end
        prev.enabled = false
        prev._busy = false
        prev._want = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggScramble = M

local tryRequire = Core.require
local Remotes, Network

local function bindGame()
    Remotes = Remotes or tryRequire("Shared.Remotes") or tryRequire("Library.Client.Network")
    Network = Network or tryRequire("Library.Client.Network")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

local function dbg(tag, msg)
    local fn = G.StealEggDbg
    if type(fn) == "function" then
        pcall(fn, tag, msg)
    end
end

local function nowSrv()
    local ok, t = pcall(function()
        return Workspace:GetServerTimeNow()
    end)
    if ok and type(t) == "number" then
        return t
    end
    return os.clock()
end

local function hrp()
    local ch = LP and LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not ch or not hum or hum.Health <= 0 then
        return nil
    end
    return ch:FindFirstChild("HumanoidRootPart")
end

local function xzDist(a, b)
    if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then
        return 1e9
    end
    return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
end

local function flattenPos(pos)
    local here = hrp()
    if typeof(pos) ~= "Vector3" then
        return pos
    end
    if here and math.abs(pos.Y - here.Position.Y) > 12 then
        return Vector3.new(pos.X, here.Position.Y, pos.Z)
    end
    return pos
end

local function stillOn(token)
    return M.enabled == true and M._token == token and GEN == G.__StealEggScrambleGen
end

-- Nahan scramble HANYA kalau steal pegang telur / FAR / claim / gerbang reset.
-- Going·hub / treadmill / no match BUKAN match — itu yang bikin AFK "Wait steal"
-- padahal owner sudah scramble (status Going sisa + speed UI).
-- Wall reset: steal butuh kaki SEKARANG (Forest/DropWall). Jangan nunggu match.
local function stealResetRace()
    if G.__StealEggWanted ~= true then
        return false
    end
    if G.__StealEggResetGo == true then
        return true
    end
    local wild = G.StealEggWild
    if type(wild) ~= "table" or wild.enabled ~= true then
        return false
    end
    if type(wild.resetRace) == "function" then
        local ok, race = pcall(wild.resetRace)
        if ok == true and race == true then
            return true
        end
    end
    if type(wild.wallHold) == "function" then
        local okh, hold = pcall(wild.wallHold)
        if okh == true and hold == true then
            return true
        end
    end
    return false
end

local function stealBlocksScramble()
    if stealResetRace() == true then
        return true
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Is) == "function" then
        local ok, mine = pcall(d.Is, "scramble")
        if ok == true and mine == true then
            return false
        end
    end
    if G.__StealEggFarOn == true
        or G.__StealEggClaiming == true
        or G.__StealEggDecoyOn == true
        or G.__StealEggStealFlow == true
    then
        return true
    end
    if os.clock() < (tonumber(G.__StealEggClaimCool) or 0) then
        return true
    end
    local wild = G.StealEggWild
    if type(wild) ~= "table" then
        return false
    end
    if wild.enabled ~= true or G.__StealEggWanted ~= true then
        return false
    end
    if type(wild.isCarrying) == "function" then
        local okc, yes = pcall(wild.isCarrying)
        if okc == true and yes == true then
            return true
        end
    end
    local st = wild._status
    if type(st) == "table" then
        local t = tostring(st.text or "")
        if t == "Steal" or t == "Guard" or t == "Claim" or t == "Claiming" or t == "Hit" then
            return true
        end
    end
    return false
end

local function legsCheap(token)
    return stillOn(token) == true
        and stealBlocksScramble() ~= true
end

local function workOn(token)
    return stillOn(token) == true and stealBlocksScramble() ~= true
end

local function netFolder()
    local pkg = ReplicatedStorage:FindFirstChild("Packages")
    return pkg and pkg:FindFirstChild("Networking")
end

local function scrambleNet()
    bindGame()
    local s = Remotes and Remotes.Scramble
    if type(s) == "table" then
        return s
    end
    s = Network and Network.Scramble
    if type(s) == "table" then
        return s
    end
    local nw = netFolder()
    if not nw then
        return nil
    end
    return {
        Request = nw:FindFirstChild("RF/Scramble/Request"),
        Collect = nw:FindFirstChild("RE/Scramble/Collect"),
        Drops = nw:FindFirstChild("RE/Scramble/Drops"),
        RemoveDrops = nw:FindFirstChild("RE/Scramble/RemoveDrops"),
        Drones = nw:FindFirstChild("RE/Scramble/Drones"),
        State = nw:FindFirstChild("RE/Scramble/State"),
    }
end

local function invokeRequest(op, a, b)
    local net = scrambleNet()
    local rf = net and net.Request
    if type(rf) ~= "table" and typeof(rf) ~= "Instance" then
        return nil
    end
    if type(rf.InvokeServer) ~= "function" then
        return nil
    end
    local gap = os.clock() - (tonumber(M._reqAt) or 0)
    if gap < 0.18 then
        task.wait(0.18 - gap)
    end
    M._reqAt = os.clock()
    local ok, res = pcall(function()
        if b ~= nil then
            return rf:InvokeServer(op, a, b)
        end
        if a ~= nil then
            return rf:InvokeServer(op, a)
        end
        return rf:InvokeServer(op)
    end)
    if not ok then
        dbg("SCRAMBLE", "request fail " .. tostring(op) .. " " .. tostring(res))
        return nil
    end
    return res
end

local function applySnap(res)
    if type(res) ~= "table" then
        return M._snap
    end
    local snap = res.Snapshot or res
    if type(snap) ~= "table" then
        return M._snap
    end
    if type(snap.State) ~= "table" and type(res.State) == "table" then
        snap.State = res.State
    end
    M._snap = snap
    M._snapAt = os.clock()
    if type(snap.Drops) == "table" then
        for key, drop in pairs(snap.Drops) do
            if type(drop) == "table" then
                if drop.Id == nil and (type(key) == "string" or type(key) == "number") then
                    drop.Id = key
                end
                if drop.Id ~= nil then
                    M._drops[tostring(drop.Id)] = drop
                end
            end
        end
    end
    if type(snap.Drones) == "table" then
        M._droneSnap = snap.Drones
    end
    return snap
end

function M.kickSnap(force)
    if M._snapBusy == true then
        return
    end
    if os.clock() < (tonumber(G.__StealEggClaimCool) or 0) then
        return
    end
    if os.clock() < (tonumber(G.__StealEggSpawnCool) or 0) then
        return
    end
    local gap = 8
    if M.windowActive(M._snap) == true then
        gap = 5
    end
    if force ~= true then
        local age = os.clock() - (tonumber(M._snapAt) or 0)
        if type(M._snap) == "table" and age < gap then
            return
        end
    end
    M._snapBusy = true
    task.spawn(function()
        local res = invokeRequest("Snapshot")
        applySnap(res)
        M._snapBusy = false
    end)
end

function M.snapshot(force)
    -- Jangan InvokeServer di thread steal/claim. Cache + event saja.
    if type(M._snap) == "table" then
        if force == true then
            M.kickSnap(true)
        else
            M.kickSnap()
        end
        return M._snap
    end
    M.kickSnap(true)
    return M._snap
end

local function hookDrops()
    local net = scrambleNet()
    if type(net) ~= "table" then
        return
    end
    if M._netHooked == true then
        return
    end
    local ev = net.Drops
    if ev == nil and net.Collect == nil then
        return
    end
    M._netHooked = true
    local function eatDrop(drop)
        if type(drop) == "table" and drop.Id ~= nil then
            M._drops[tostring(drop.Id)] = drop
        end
    end
    if ev ~= nil then
        pcall(function()
            ev.OnClientEvent:Connect(function(payload)
                if type(payload) ~= "table" then
                    return
                end
                eatDrop(payload)
                local list = payload.Drops or payload
                if type(list) == "table" then
                    for _, drop in pairs(list) do
                        eatDrop(drop)
                    end
                end
            end)
        end)
    end
    local rm = net.RemoveDrops
    if rm ~= nil then
        pcall(function()
            rm.OnClientEvent:Connect(function(ids)
                if type(ids) ~= "table" then
                    return
                end
                for _, id in ipairs(ids) do
                    M._drops[tostring(id)] = nil
                end
            end)
        end)
    end
    local drones = net.Drones
    if drones ~= nil then
        pcall(function()
            drones.OnClientEvent:Connect(function(payload)
                if type(payload) == "table" then
                    M._droneSnap = payload
                end
            end)
        end)
    end
    local stEv = net.State
    if stEv ~= nil then
        pcall(function()
            stEv.OnClientEvent:Connect(function(payload)
                applySnap(payload)
            end)
        end)
    end
end

local function stateOf(snap)
    snap = type(snap) == "table" and snap or M._snap
    return type(snap) == "table" and type(snap.State) == "table" and snap.State or nil
end

function M.eventLive(snap)
    snap = type(snap) == "table" and snap or M._snap
    if type(snap) ~= "table" then
        return false
    end
    if snap.Ready ~= true or snap.Enabled ~= true or snap.WorldReady ~= true then
        return false
    end
    local ends = tonumber(snap.EventEndsAt)
    if ends == nil then
        return false
    end
    return nowSrv() < ends
end

function M.windowActive(snap)
    if Workspace:GetAttribute("ScrambleOutbreakActive") == true then
        return true
    end
    snap = type(snap) == "table" and snap or M._snap
    local w = type(snap) == "table" and snap.Window
    if type(w) ~= "table" then
        return false
    end
    if w.Active == true then
        return true
    end
    -- Game sering biarkan Active=false meski jam outbreak masih jalan.
    -- Tanpa ini scramble Idle "outbreak later" padahal drone sudah di lapangan.
    local now = nowSrv()
    local t0 = tonumber(w.StartsAt)
    local t1 = tonumber(w.EndsAt)
    if t0 and t1 and now >= t0 and now < t1 then
        return true
    end
    return false
end

function M.isLocked()
    if stealBlocksScramble() == true then
        return false
    end
    return M._busy == true
end

function M.shouldHoldHop()
    if M.enabled ~= true then
        return false
    end
    if M._busy == true then
        return true, "scramble", "farming"
    end
    if M.windowActive() == true then
        return true, "scramble", "outbreak"
    end
    return false
end

local function dispatch()
    return G.StealEggDispatch
end

local function holdLegs(on)
    local d = dispatch()
    if type(d) ~= "table" then
        return false
    end
    if on then
        if type(d.Hold) ~= "function" then
            return false
        end
        local ok, got = pcall(d.Hold, "scramble")
        return ok == true and got == true
    end
    if type(d.Release) == "function" then
        pcall(d.Release, "scramble")
    end
    return true
end

local function pinLegs(sec)
    local d = dispatch()
    if type(d) == "table" and type(d.Pin) == "function" then
        pcall(d.Pin, "scramble", tonumber(sec) or PIN_SEC)
    end
end

local function unpinLegs()
    local d = dispatch()
    if type(d) == "table" and type(d.Unpin) == "function" then
        pcall(d.Unpin, "scramble")
    end
end

local function stowBat()
    local ch = LP and LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function yieldToSteal()
    M._busy = false
    unpinLegs()
    holdLegs(false)
    stowBat()
    emit("Wait", "warn", "steal match")
end

function M.wantsWork()
    if M.enabled ~= true then
        return false
    end
    if stealBlocksScramble() == true then
        return false
    end
    if M._busy == true or M._want == true then
        return true
    end
    -- Outbreak hidup: jangan nunggu farmTick. Steal ON idle harus lepas kaki.
    return M.windowActive() == true
end

-- Sama Auto Steal: Speed tersimpan + glide CFrame XZ. Bukan walk/MoveTo.
local function stealMoveOpts(token, plant)
    local wild = G.StealEggWild
    local mv = G.StealEggMove
    local speed = 600
    if type(mv) == "table" and type(mv.WantWalkSpeed) == "function" then
        local ok, n = pcall(mv.WantWalkSpeed)
        if ok == true and tonumber(n) then
            speed = tonumber(n)
        end
    elseif type(wild) == "table" then
        speed = tonumber(wild.moveSpeed) or 600
    end
    speed = math.min(math.max(60, speed), SPEED_CAP)
    local arrive = tonumber(plant) or 8
    return {
        reason = "scramble",
        owner = "scramble",
        arrive = arrive,
        plantDist = arrive,
        mode = "glide",
        uiMode = "glide",
        speed = speed,
        nativeWalkSpeed = false,
        lockGlideSpeed = true,
        legalHop = false,
        skipRubberWait = false,
        skipStall = true,
        skipIntegrity = G.__StealEggVtQuiet == true,
        skipLandWait = false,
        shouldRun = function()
            return legsCheap(token) == true
        end,
    }
end

local function rawMove(pos, token, plant, flags)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    flags = type(flags) == "table" and flags or nil
    local should = function()
        return legsCheap(token) == true
    end
    local opts = stealMoveOpts(token, plant)
    opts.shouldRun = should
    opts.mode = "glide"
    opts.uiMode = "glide"
    opts.lockGlideSpeed = true
    opts.nativeWalkSpeed = false
    opts.legalHop = false
    opts.skipRubberWait = false
    opts.skipStall = true
    opts.skipLandWait = false
    opts.skipIntegrity = G.__StealEggVtQuiet == true
    local here = hrp()
    local inside = here ~= nil and here.Position.Y < 40
    local wild = G.StealEggWild
    if inside == true then
        -- Cave: lurus ke dest. steerAround sidestep nembus mesh.
        opts.steer = nil
        opts.speed = math.min(tonumber(opts.speed) or SPEED_CAP, CAVE_SPEED)
    else
        -- Hub Z dulu (plotGate). Jangan steerPlot/steerAround: sidestep ke plot = mati X~964.
        local steerFn = type(wild) == "table" and wild.plotGate
        opts.steer = type(steerFn) == "function" and steerFn or nil
    end
    if flags and flags.toPad == true and here ~= nil and xzDist(here.Position, pos) <= PAD_NEAR then
        opts.speed = math.min(tonumber(opts.speed) or SPEED_CAP, PAD_NEAR_SPEED)
        opts.steer = nil
    end
    if flags and tonumber(flags.landY) then
        opts.landY = flags.landY
    end
    local mv = G.StealEggMove
    local d = dispatch()
    if type(d) == "table" and type(d.GoTo) == "function" then
        local ok, res = pcall(d.GoTo, "scramble", CFrame.new(pos), opts)
        return ok == true and res == true
    end
    if type(mv) == "table" and type(mv.GoTo) == "function" then
        local ok, res = pcall(mv.GoTo, CFrame.new(pos), opts)
        return ok == true and res == true
    end
    return false
end

local function ragdollLeft()
    local rt = LP and LP:GetAttribute("RagdollEndTime")
    if type(rt) == "number" then
        local left = rt - nowSrv()
        if left > 0 then
            return left
        end
    end
    local ch = LP and LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if hum then
        local st = hum:GetState()
        if st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Freefall
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.Flying
        then
            return 0.2
        end
    end
    -- Knockback scrambled: ragdoll timer sudah 0 tapi masih di udara.
    if hrp and hrp.Position.Y > 90 then
        return 0.2
    end
    return 0
end

-- Kena knockback telur = ragdoll server. Glide yang memaksa Running tiap
-- frame melawan ragdoll = freeze 3–5 s. Tunggu sampai bangun dulu.
local function waitRagdoll(token, maxSec)
    local t0 = os.clock()
    while workOn(token) == true and ragdollLeft() > 0.05 and os.clock() - t0 < (maxSec or 6) do
        task.wait(0.1)
    end
    return ragdollLeft() <= 0.05
end

local function goTo(pos, token, plant, flags)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    if ragdollLeft() > 0.05 and not (flags and flags.keepRagdoll == true) then
        waitRagdoll(token, 6)
    end
    local t0 = os.clock()
    local got = rawMove(pos, token, plant, flags)
    if got ~= true or (os.clock() - t0) < 0.05 then
        task.wait(0.12)
    end
    return got
end

local function firePrompt(prompt)
    if typeof(prompt) ~= "Instance" or not prompt:IsA("ProximityPrompt") then
        return
    end
    local reach = QUEST_PROMPT
    local snap = M._snap
    local npc = type(snap) == "table" and type(snap.Interactions) == "table" and tonumber(snap.Interactions.NpcRadius)
    if npc and npc > reach then
        reach = npc
    end
    pcall(function()
        prompt.Enabled = true
        prompt.RequiresLineOfSight = false
        if (tonumber(prompt.MaxActivationDistance) or 0) < reach then
            prompt.MaxActivationDistance = reach
        end
    end)
    -- Jangan getconnections tiap tick: CPU spike. Satu fire + hold cukup.
    if typeof(fireproximityprompt) == "function" then
        pcall(fireproximityprompt, prompt, 1)
    end
    local hold = tonumber(prompt.HoldDuration) or 0
    pcall(function()
        prompt:InputHoldBegin()
    end)
    task.wait(math.max(0.08, hold + 0.05))
    pcall(function()
        prompt:InputHoldEnd()
    end)
end

-- Secret Cave: Entry pad di permukaan (E Enter). Egg/NPC/vault di dalam
-- (Y ~-120). Glide lurus ke hitbox = nabrak tembok. Harus pad dulu.
local function caveRoot()
    local function from(root)
        local zones = root and root:FindFirstChild("SecretZones")
        return zones and zones:FindFirstChild("Cave")
    end
    return from(Workspace:FindFirstChild("World"))
        or from(Workspace:FindFirstChild("__OBJECTS"))
end

local function caveTele()
    local cave = caveRoot()
    return cave and cave:FindFirstChild("Teleporter")
end

local function pointInPart(part, world)
    if not (part and part:IsA("BasePart") and typeof(world) == "Vector3") then
        return false
    end
    local lp = part.CFrame:PointToObjectSpace(world)
    local s = part.Size * 0.5
    return math.abs(lp.X) <= s.X + 12
        and math.abs(lp.Y) <= s.Y + 12
        and math.abs(lp.Z) <= s.Z + 12
end

local function inCave()
    local here = hrp()
    if not here then
        return false
    end
    local cave = caveRoot()
    local bounds = cave and cave:FindFirstChild("CaveBounds")
    if bounds and bounds:IsA("BasePart") then
        return pointInPart(bounds, here.Position)
    end
    return here.Position.Y < 40
end

local function posInCave(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local cave = caveRoot()
    local bounds = cave and cave:FindFirstChild("CaveBounds")
    if bounds and bounds:IsA("BasePart") then
        return pointInPart(bounds, pos)
    end
    return pos.Y < 40
end

-- Telur/part di dalam mountain: wajib pad Enter. Jangan glide lurus nabrak tembok.
local function needsCavePad(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    if posInCave(pos) == true then
        return true
    end
    if pos.Y < 45 then
        return true
    end
    return false
end

local function cavePrompt(wantEnter)
    local tele = caveTele()
    if not tele then
        return nil
    end
    local part = tele:FindFirstChild(wantEnter and "Entry" or "Exit")
    local att = part and part:FindFirstChild("SecretZoneInteraction")
    local pr = att and att:FindFirstChild("SecretZonePrompt")
    if pr and pr:IsA("ProximityPrompt") then
        return pr
    end
    if part then
        pr = part:FindFirstChildWhichIsA("ProximityPrompt", true)
        if pr then
            return pr
        end
    end
    return nil
end

local function caveStand(wantEnter)
    local tele = caveTele()
    if not tele then
        return nil
    end
    -- Enter: ExitTp = lantai di depan pintu (bukan collider Entry).
    -- Exit: EntryTp = spawn dalam cave, depan pintu Exit.
    local pad = tele:FindFirstChild(wantEnter and "ExitTp" or "EntryTp")
    if not (pad and pad:IsA("BasePart")) then
        pad = tele:FindFirstChild(wantEnter and "Entry" or "Exit")
    end
    if not (pad and pad:IsA("BasePart")) then
        return nil
    end
    return Vector3.new(pad.Position.X, pad.Position.Y + 3, pad.Position.Z)
end

local function ensureCave(token, wantInside)
    if inCave() == wantInside then
        return true
    end
    local stand = caveStand(wantInside)
    local prompt = cavePrompt(wantInside)
    if typeof(stand) ~= "Vector3" or not prompt then
        return inCave() == wantInside
    end
    emit("Pad", "live", wantInside and "Enter cave" or "Exit cave")
    M._cavePromptAt = M._cavePromptAt or 0
    for _ = 1, 4 do
        if workOn(token) ~= true then
            return false
        end
        if inCave() == wantInside then
            return true
        end
        local here = hrp()
        if here == nil or xzDist(here.Position, stand) > 8 then
            goTo(stand, token, 6, { toPad = true })
        end
        if ragdollLeft() > 0.05 then
            waitRagdoll(token, 4)
        end
        here = hrp()
        if here and xzDist(here.Position, stand) <= 12 then
            if (os.clock() - (tonumber(M._cavePromptAt) or 0)) >= 0.55 then
                M._cavePromptAt = os.clock()
                firePrompt(prompt)
            end
        end
        local t0 = os.clock()
        while workOn(token) == true and os.clock() - t0 < 1.8 do
            if inCave() == wantInside then
                task.wait(0.12)
                return true
            end
            task.wait(0.12)
        end
    end
    return inCave() == wantInside
end

local function ensureForPos(token, pos)
    if typeof(pos) ~= "Vector3" then
        return true
    end
    if needsCavePad(pos) then
        return ensureCave(token, true)
    end
    if inCave() then
        return ensureCave(token, false)
    end
    return true
end

local goToDirect = goTo
goTo = function(pos, token, plant, flags)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    flags = type(flags) == "table" and flags or nil
    -- Masih di plot / yard: pad tengah (StartArea) dulu, seperti steal spawn.
    -- Jangan lurus ke drone/part — T-plot + pagar = mati.
    if inCave() ~= true and (flags == nil or flags.skipHub ~= true) then
        local here = hrp()
        if here then
            local wild = G.StealEggWild
            local hubP = Vector3.new(515, 74, -363)
            if type(wild) == "table" and type(wild.hubPos) == "function" then
                local okH, v = pcall(wild.hubPos)
                if okH == true and typeof(v) == "Vector3"
                    and math.abs(v.X - hubP.X) < 90 and math.abs(v.Z - hubP.Z) < 90
                then
                    hubP = v
                end
            end
            local from = here.Position
            local atHub = xzDist(from, hubP) <= 22
            local destIsHub = xzDist(pos, hubP) <= 28
            local destOwn = false
            local ownYard = false
            if type(wild) == "table" and type(wild.inOwnPlot) == "function" then
                ownYard = wild.inOwnPlot(from, 80) == true
                destOwn = wild.inOwnPlot(pos, 48) == true
            end
            -- Hanya StartArea kalau masih di distrik plot. Off-road di lapangan
            -- scramble (X jauh, Z knock ±50) BUKAN yard — balik pad = telur lolos.
            local nearPlots = math.abs(from.X - hubP.X) < 520
            local needHub = ownYard == true or (nearPlots == true and math.abs(from.Z - hubP.Z) > 50)
            if atHub ~= true and destIsHub ~= true and destOwn ~= true and needHub == true then
                emit("Pad", "live", "hub")
                local hubStand = Vector3.new(hubP.X, from.Y, hubP.Z)
                local hubOk = goToDirect(hubStand, token, 12, { toPad = true, skipHub = true })
                here = hrp()
                if hubOk ~= true and (here == nil or xzDist(here.Position, hubP) > 36) then
                    return false
                end
            end
        end
    end
    if needsCavePad(pos) == true and inCave() ~= true then
        if ensureCave(token, true) ~= true then
            return false
        end
    elseif inCave() == true and needsCavePad(pos) ~= true then
        if ensureCave(token, false) ~= true then
            return false
        end
    end
    return goToDirect(pos, token, plant, flags)
end

local function modelPos(model)
    if typeof(model) ~= "Instance" then
        return nil
    end
    if model:IsA("Model") then
        local pp = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
        if pp then
            return pp.Position
        end
        local ok, pivot = pcall(function()
            return model:GetPivot()
        end)
        if ok and typeof(pivot) == "CFrame" then
            return pivot.Position
        end
    elseif model:IsA("BasePart") then
        return model.Position
    end
    return nil
end

local function questModels()
    local out = {}
    local ok, tagged = pcall(function()
        return CollectionService:GetTagged("ScrambleQuest")
    end)
    if ok ~= true or type(tagged) ~= "table" then
        return out
    end
    for _, inst in ipairs(tagged) do
        if typeof(inst) ~= "Instance" then
            continue
        end
        local model = inst
        if not model:IsA("Model") then
            model = inst:FindFirstAncestorOfClass("Model") or inst
        end
        local attr = model:GetAttribute("ScrambleQuestId") or inst:GetAttribute("ScrambleQuestId")
        if type(attr) ~= "string" or attr == "" then
            attr = model.Name
        end
        local pos
        if tostring(attr) == "EscapedExperiment" then
            local ip = model:FindFirstChild("InteractionPoint", true)
            if ip and ip:IsA("Attachment") then
                pos = ip.WorldPosition
            elseif ip and ip:IsA("BasePart") then
                pos = ip.Position
            end
        end
        local hit = model:FindFirstChild("Hitbox")
        pos = pos or (hit and hit:IsA("BasePart") and hit.Position) or modelPos(model)
        -- Escaped Experiment emang di bawah (Y ~-129). Jangan ratakan ke lantai
        -- pemain: itu bikin "sudah sampai" di atap kosong.
        if tostring(attr) ~= "EscapedExperiment" then
            pos = flattenPos(pos)
        end
        out[#out + 1] = { model = model, kind = tostring(attr), pos = pos }
    end
    return out
end

local function nearestQuest(kind)
    local here = hrp()
    local best, bestD
    for _, q in ipairs(questModels()) do
        if (kind == nil or q.kind == kind) and typeof(q.pos) == "Vector3" then
            local d = here and xzDist(here.Position, q.pos) or 0
            if bestD == nil or d < bestD then
                best, bestD = q, d
            end
        end
    end
    return best, bestD
end

local function batTool()
    local ch = LP and LP.Character
    if ch then
        for _, child in ipairs(ch:GetChildren()) do
            if child:IsA("Tool") and child:GetAttribute("IsBat") == true then
                return child
            end
        end
    end
    local bag = LP and LP:FindFirstChildOfClass("Backpack")
    if bag then
        for _, child in ipairs(bag:GetChildren()) do
            if child:IsA("Tool") and child:GetAttribute("IsBat") == true then
                return child, true
            end
        end
    end
    return nil
end

local function swingBat()
    if stealBlocksScramble() == true then
        return
    end
    local gap = os.clock() - (tonumber(M._swingAt) or 0)
    if gap < SWING_GAP then
        return
    end
    local tool, inBag = batTool()
    if not tool then
        return
    end
    if inBag == true then
        local ch = LP and LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(hum.EquipTool, hum, tool)
        end
        return
    end
    local cdEnd = tool:GetAttribute("CooldownEndTime")
    if type(cdEnd) == "number" and nowSrv() < cdEnd then
        return
    end
    if tool:GetAttribute("CooldownActive") == true then
        return
    end
    M._swingAt = os.clock()
    pcall(function()
        tool:Activate()
    end)
end

local function droneTargets()
    local out = {}
    local seen = {}
    local function consider(model)
        if typeof(model) ~= "Instance" or not model:IsA("Model") then
            return
        end
        if seen[model] then
            return
        end
        local hit = model:FindFirstChild("Hitbox")
        if not hit or not hit:IsA("BasePart") then
            return
        end
        local hp = hit:GetAttribute("Health")
        if type(hp) ~= "number" or hp <= 0 then
            return
        end
        local nm = tostring(model.Name)
        if not string.find(nm, "PersonalDrone_", 1, true)
            and not string.find(nm, "DroneVisual_", 1, true)
        then
            return
        end
        seen[model] = true
        local tier = model:GetAttribute("ScrambleTier") or hit:GetAttribute("ScrambleTier")
        out[#out + 1] = {
            model = model,
            hit = hit,
            pos = hit.Position,
            id = model.Name,
            tier = tostring(tier or ""),
        }
    end
    local folder = Workspace:FindFirstChild("ScrambleLocalVisuals")
    if folder then
        for _, child in ipairs(folder:GetChildren()) do
            consider(child)
        end
    end
    if #out == 0 then
        local pack = M._droneSnap
        local upserts = type(pack) == "table" and pack.Upserts
        if type(upserts) == "table" then
            for _, u in ipairs(upserts) do
                if type(u) == "table" and (u.OwnerUserId == nil or u.OwnerUserId == LP.UserId) then
                    local hp = tonumber(u.Health)
                    local cf = u.CFrame
                    if (hp == nil or hp > 0) and typeof(cf) == "CFrame" then
                        local tier = u.ScrambleTier
                        if tier == nil and type(u.Attributes) == "table" then
                            tier = u.Attributes.ScrambleTier
                        end
                        out[#out + 1] = {
                            model = nil,
                            hit = nil,
                            pos = cf.Position,
                            tier = tostring(tier or ""),
                            id = tostring(u.Id or ""),
                            hp = hp,
                        }
                    end
                end
            end
        end
    end
    return out
end

local function droneTierRank(tier)
    local t = string.lower(tostring(tier or ""))
    if string.find(t, "augmented", 1, true) then
        return 3
    end
    if string.find(t, "reactor", 1, true) then
        return 2
    end
    if string.find(t, "scrap", 1, true) then
        return 1
    end
    return 0
end

local function nearestDrone()
    -- Cache 0.4 s: droneTargets() FindFirstChild rekursif per model, dipanggil
    -- 2× per iterasi loop = spike CPU.
    local now = os.clock()
    if type(M._droneCache) == "table" and (now - (tonumber(M._droneCacheAt) or 0)) < 0.8 then
        return M._droneCache[1], M._droneCache[2]
    end
    local here = hrp()
    local best, bestD, bestR
    for _, d in ipairs(droneTargets()) do
        local dist = here and (here.Position - d.pos).Magnitude or 0
        local rank = droneTierRank(d.tier)
        if best == nil or rank > bestR or (rank == bestR and dist < bestD) then
            best, bestD, bestR = d, dist, rank
        end
    end
    M._droneCache = { best, bestD }
    M._droneCacheAt = now
    return best, bestD
end

local function biomeCenter(snap)
    snap = type(snap) == "table" and snap or M._snap
    local areas = type(snap) == "table" and snap.Areas
    local function guardFolder(root)
        local areasF = root and root:FindFirstChild("Areas")
        return areasF and areasF:FindFirstChild("GuardAreas")
    end
    local guard = guardFolder(Workspace:FindFirstChild("World"))
        or guardFolder(Workspace:FindFirstChild("__OBJECTS"))
    if not guard or type(areas) ~= "table" then
        return nil
    end
    for _, name in ipairs(areas) do
        local zone = guard:FindFirstChild(tostring(name))
        local bounds = zone and zone:FindFirstChild("Bounds")
        if bounds and bounds:IsA("BasePart") and zone:GetAttribute("ZoneHidden") ~= true then
            return bounds.Position
        end
    end
    return nil
end

local function decodeVec(v)
    if typeof(v) == "Vector3" then
        return v
    end
    if typeof(v) == "CFrame" then
        return v.Position
    end
    if type(v) == "table" then
        local x = tonumber(v.X) or tonumber(v[1])
        local y = tonumber(v.Y) or tonumber(v[2])
        local z = tonumber(v.Z) or tonumber(v[3])
        if x and y and z then
            return Vector3.new(x, y, z)
        end
    end
    return nil
end

local function dropPos(drop)
    if type(drop) ~= "table" then
        return nil
    end
    return decodeVec(drop.Position) or decodeVec(drop.Origin)
end

local function fireCollect(ids)
    if type(ids) ~= "table" or #ids == 0 then
        return false
    end
    local net = scrambleNet()
    local ev = net and net.Collect
    if ev == nil then
        return false
    end
    if type(ev.FireServer) == "function" then
        local ok = pcall(ev.FireServer, ev, ids)
        if ok then
            return true
        end
    end
    if typeof(ev) == "Instance" and ev:IsA("RemoteEvent") then
        return pcall(function()
            ev:FireServer(ids)
        end) == true
    end
    return false
end

local function dropReach(drop)
    local r = tonumber(drop and drop.Radius)
    if r == nil or r < 1 then
        r = DROP_REACH
    end
    return r
end

local function dropIdOf(drop)
    if type(drop) ~= "table" then
        return nil
    end
    if drop.Id ~= nil then
        return drop.Id
    end
    return nil
end

local function collectNear()
    local here = hrp()
    if not here then
        return false
    end
    local ids = {}
    local now = nowSrv()
    for id, drop in pairs(M._drops) do
        if type(drop) == "table" then
            local exp = tonumber(drop.ExpiresAt)
            if exp ~= nil and exp <= now then
                M._drops[id] = nil
            else
                local owner = drop.OwnerUserId
                local after = tonumber(drop.CollectAfter) or 0
                if (owner == nil or owner == LP.UserId) and now >= after then
                    local pos = dropPos(drop)
                    local reach = dropReach(drop)
                    if typeof(pos) == "Vector3" and (here.Position - pos).Magnitude <= reach then
                        local gid = dropIdOf(drop) or id
                        ids[#ids + 1] = gid
                        if #ids >= 8 then
                            break
                        end
                    end
                end
            end
        end
    end
    if #ids == 0 then
        return false
    end
    return fireCollect(ids)
end

local function worldPickups()
    local out = {}
    local folder = Workspace:FindFirstChild("ScrambleLocalVisuals")
    if not folder then
        return out
    end
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("Model") then
            local name = child.Name
            if string.find(name, "PersonalDrone_", 1, true) then
                continue
            end
            if child:FindFirstChild("Hitbox") then
                continue
            end
            if child:GetAttribute("ScrambleTier") ~= nil or child:GetAttribute("ScrambleAnimatedRig") == true then
                continue
            end
            local pos = modelPos(child)
            if typeof(pos) == "Vector3" then
                out[#out + 1] = { model = child, pos = pos, kind = "Part" }
            end
        end
    end
    return out
end

local function nearestDrop(preferPart)
    local here = hrp()
    local now = nowSrv()
    local best, bestD
    for _, drop in pairs(M._drops) do
        if type(drop) == "table" then
            local owner = drop.OwnerUserId
            local exp = tonumber(drop.ExpiresAt)
            local pos = dropPos(drop)
            if (owner == nil or owner == LP.UserId)
                and (exp == nil or exp > now)
                and typeof(pos) == "Vector3"
            then
                if preferPart ~= true or drop.Kind == "Part" then
                    local d = here and (here.Position - pos).Magnitude or 0
                    if bestD == nil or d < bestD then
                        best, bestD = drop, d
                    end
                end
            end
        end
    end
    if preferPart == true and best == nil and not next(M._drops) then
        for _, vis in ipairs(worldPickups()) do
            local d = here and (here.Position - vis.pos).Magnitude or 0
            if bestD == nil or d < bestD then
                best, bestD = vis, d
            end
        end
    end
    return best, bestD
end

-- Ambil part di tanah. Samples yang sudah di kaki ikut Collect. Jangan jalan
-- ke Samples jauh — itu yang nunda telur berikutnya.
local function pickupDrops(token)
    collectNear()
    local drop, dist = nearestDrop(true)
    if not drop then
        return false
    end
    local kind = tostring(drop.Kind or drop.kind or "")
    if kind ~= "Part" then
        return false
    end
    local pos = dropPos(drop) or drop.pos
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local reach = dropReach(drop)
    local now = nowSrv()
    local after = tonumber(drop.CollectAfter) or 0
    if drop.MagnetAt ~= nil then
        collectNear()
        return nearestDrop(true) ~= nil
    end
    if (tonumber(dist) or 999) > reach then
        emit("Part", "live", tostring(drop.PartId or "drop"))
        goTo(pos, token, math.max(3, reach * 0.45))
        collectNear()
        return nearestDrop(true) ~= nil
    end
    if now < after then
        task.wait(math.clamp(after - now, 0.02, 0.25))
    end
    local gid = dropIdOf(drop)
    if gid ~= nil then
        fireCollect({ gid })
    end
    collectNear()
    return nearestDrop(true) ~= nil
end

local function questPrompt(model, kind)
    if typeof(model) ~= "Instance" then
        return nil
    end
    if kind == "LostPart1" or kind == "LostPart2" then
        local named = model:FindFirstChild("ClaimLostPart", true)
        if named and named:IsA("ProximityPrompt") then
            return named
        end
    elseif kind == "EscapedExperiment" then
        local named = model:FindFirstChild("ScrambleTalk", true)
        if named and named:IsA("ProximityPrompt") then
            return named
        end
    end
    return model:FindFirstChildWhichIsA("ProximityPrompt", true)
end

local function lostOwned(id)
    local st = stateOf()
    local lost = type(st) == "table" and type(st.LostParts) == "table" and st.LostParts
    return type(lost) == "table" and lost[tostring(id)] == true
end

local function stayAndClaim(token, kind, ownedFn)
    local reach = QUEST_REACH
    local promptReach = QUEST_PROMPT
    for _ = 1, CLAIM_PULSES do
        if workOn(token) ~= true then
            yieldToSteal()
            return false
        end
        if type(ownedFn) == "function" and ownedFn() == true then
            return true
        end
        local q, dist = nearestQuest(kind)
        if not q or typeof(q.pos) ~= "Vector3" then
            emit("Wait", "warn", "no " .. tostring(kind))
            return false
        end
        -- LostPart di permukaan. Cave Enter untuk claim part sudah dihapus.
        if inCave() then
            ensureCave(token, false)
        end
        q, dist = nearestQuest(kind)
        if not q or typeof(q.pos) ~= "Vector3" then
            emit("Wait", "warn", "no " .. tostring(kind))
            return false
        end
        if (tonumber(dist) or 999) > reach then
            emit("Walk", "live", kind)
            goTo(flattenPos(q.pos), token, reach)
            q, dist = nearestQuest(kind)
        end
        if not q or (tonumber(dist) or 999) > promptReach then
            emit("Walk", "warn", string.format("%s %.0f", kind, tonumber(dist) or -1))
            return false
        end
        emit("Claim", "live", string.format("%s · %.1f", kind, tonumber(dist) or 0))
        firePrompt(questPrompt(q.model, kind))
        if typeof(q.model) == "Instance" then
            local extra = q.model:FindFirstChildWhichIsA("ProximityPrompt", true)
            if extra then
                firePrompt(extra)
            end
        end
        if kind == "LostPart1" or kind == "LostPart2" then
            applySnap(invokeRequest("Part", { Id = kind }))
        end
        task.wait(0.12)
        M.snapshot(true)
        if type(ownedFn) == "function" and ownedFn() == true then
            return true
        end
    end
    return type(ownedFn) == "function" and ownedFn() == true
end

local function doLostPart(token, id)
    if lostOwned(id) then
        return true
    end
    emit("Part", "live", id)
    return stayAndClaim(token, id, function()
        return lostOwned(id)
    end)
end

local function farmDrones(token)
    if stealBlocksScramble() == true then
        yieldToSteal()
        return false
    end
    if M.windowActive() ~= true then
        M._hitEgg = nil
        return false
    end
    local function alive(t)
        if type(t) ~= "table" then
            return false
        end
        if typeof(t.model) == "Instance" and t.model.Parent then
            local hit = t.hit
            if not (hit and hit.Parent) then
                hit = t.model:FindFirstChild("Hitbox")
                t.hit = hit
            end
            if hit and hit:IsA("BasePart") then
                t.pos = hit.Position
                local hp = hit:GetAttribute("Health")
                return type(hp) ~= "number" or hp > 0
            end
            return true
        end
        -- Snapshot drone (model tidak di-stream): tetap hidup selama ada pos + HP.
        if typeof(t.pos) == "Vector3" then
            local hp = tonumber(t.hp)
            return hp == nil or hp > 0
        end
        return false
    end
    local drone = M._hitEgg
    if alive(drone) ~= true then
        M._hitEgg = nil
        drone = nil
    end
    if not drone then
        drone = nearestDrone()
        if drone then
            M._hitEgg = drone
        end
    end
    if not drone then
        -- Jangan lari ke GuardAreas/hub. Visual sering kosong sebentar padahal
        -- telur scramble masih hidup — goTo biome = balik safezone.
        return false
    end
    local t0 = os.clock()
    local lastGo, lastGoAt = nil, 0
    local lastBetterAt = 0
    local lastEmit = ""
    local function emitHit(kind, detail)
        local key = kind .. tostring(detail or "")
        if key == lastEmit then
            return
        end
        lastEmit = key
        emit(kind, "live", detail)
    end
    local function goHit(pos)
        if typeof(pos) ~= "Vector3" then
            return false
        end
        if needsCavePad(pos) == true and inCave() ~= true then
            if ensureCave(token, true) ~= true then
                return false
            end
        end
        if ensureForPos(token, pos) ~= true then
            return false
        end
        if needsCavePad(pos) == true and inCave() ~= true then
            return false
        end
        local here = hrp()
        if here and (here.Position - pos).Magnitude <= DRONE_REACH then
            return true
        end
        -- Jangan goTo ulang tiap 0.14s: CFrame lawan trip sebelumnya = rubber.
        if typeof(lastGo) == "Vector3" and (lastGo - pos).Magnitude < 18 and (os.clock() - lastGoAt) < 0.85 then
            return true
        end
        lastGo = pos
        lastGoAt = os.clock()
        return goTo(pos, token, HIT_STAY)
    end
    while workOn(token) == true and os.clock() - t0 < 16 do
        if os.clock() - lastBetterAt >= 1.0 then
            lastBetterAt = os.clock()
            local better = nearestDrone()
            if better and droneTierRank(better.tier) > droneTierRank(drone and drone.tier) then
                drone = better
                M._hitEgg = better
            end
        end
        if typeof(drone.model) ~= "Instance" or drone.model.Parent == nil then
            M._droneCacheAt = 0
            local vis = nearestDrone()
            if vis and vis.model then
                drone = vis
                M._hitEgg = vis
            elseif typeof(drone.pos) == "Vector3" then
                emitHit("Egg", "find")
                goHit(drone.pos)
                task.wait(0.35)
                continue
            else
                M._hitEgg = nil
                drone = nearestDrone()
                if not drone then
                    return false
                end
                M._hitEgg = drone
            end
        end
        if alive(drone) ~= true then
            M._hitEgg = nil
            M._droneCacheAt = 0
            emitHit("Hit", "egg down")
            collectNear()
            local nxt = nearestDrone()
            if nxt then
                drone = nxt
                M._hitEgg = nxt
                t0 = os.clock()
                continue
            end
            return true
        end
        -- Kena knockback telur: tunggu ragdoll selesai, jangan goTo/swing
        -- (glide melawan ragdoll = freeze/lag 3–5 s).
        if ragdollLeft() > 0.05 then
            emitHit("Hit", "ragdoll")
            task.wait(0.1)
            continue
        end
        local pos = drone.pos
        local here = hrp()
        local dist = here and typeof(pos) == "Vector3" and (here.Position - pos).Magnitude or 999
        if dist > DRONE_REACH then
            emitHit("Egg", string.format("%.0f stud", dist))
            goHit(pos)
            task.wait(0.14)
        else
            emitHit("Hit", "egg")
            swingBat()
            task.wait(0.12)
        end
    end
    if stealBlocksScramble() == true then
        yieldToSteal()
    end
    return true
end

function M.listShopItems()
    local snap = M.snapshot()
    local items = {}
    local shop = type(snap) == "table" and snap.Shop
    if type(shop) ~= "table" then
        return items
    end
    for _, offer in ipairs(shop) do
        if type(offer) == "table" and offer.Id ~= nil then
            local label = tostring(offer.Label or offer.Id)
            local price = tonumber(offer.Price)
            items[#items + 1] = {
                key = tostring(offer.Id),
                name = price and string.format("%s · %s Samples", label, tostring(price)) or label,
            }
        end
    end
    return items
end

local function buyShop()
    if M.autoBuy ~= true then
        return
    end
    if not next(M.shopWant) then
        return
    end
    local snap = M._snap
    if M.eventLive(snap) ~= true then
        return
    end
    local st = stateOf(snap)
    local samples = type(st) == "table" and tonumber(st.Samples) or 0
    local seq = type(st) == "table" and tonumber(st.ShopSequence) or 0
    local shop = type(snap) == "table" and snap.Shop
    if type(shop) ~= "table" then
        return
    end
    for _, offer in ipairs(shop) do
        if type(offer) == "table" and M.shopWant[tostring(offer.Id)] == true then
            local price = tonumber(offer.Price) or 0
            if samples >= price and price > 0 then
                emit("Shop", "live", tostring(offer.Label or offer.Id))
                local res = invokeRequest("Shop", offer.Id, {
                    Quote = offer.Quote,
                    Sequence = seq,
                })
                applySnap(res)
                return
            end
        end
    end
end

local function farmTick(token)
    if stealBlocksScramble() == true then
        yieldToSteal()
        -- Pulang / dekat telur / habis claim: jangan Snapshot + scan drone.
        return 1.15
    end
    hookDrops()
    local outbreak = Workspace:GetAttribute("ScrambleOutbreakActive") == true
        or M.windowActive(M._snap) == true
    local snap = M._snap
    if type(snap) ~= "table" then
        M.kickSnap()
        snap = M._snap
    elseif outbreak == true and (os.clock() - (tonumber(M._snapAt) or 0)) > 8 then
        M.kickSnap()
    end
    local st = stateOf(snap)
    local needLost1 = false
    local needLost2 = false
    local droneHere = false
    if outbreak == true or (type(snap) == "table" and M.eventLive(snap) == true) then
        needLost1 = lostOwned("LostPart1") ~= true
        needLost2 = lostOwned("LostPart2") ~= true
        droneHere = nearestDrone() ~= nil
    end
    local needFarm = outbreak == true or M.windowActive(snap) == true or droneHere == true
    local want = needFarm == true or needLost1 == true or needLost2 == true
    M._want = want == true
    if stealBlocksScramble() == true then
        yieldToSteal()
        return 1.15
    end
    if want ~= true and M.eventLive(snap) ~= true then
        M._busy = false
        M._want = false
        holdLegs(false)
        emit("Idle", "muted", "event off")
        return 1.6
    end
    if want ~= true then
        M._busy = false
        M._want = false
        holdLegs(false)
        emit("Wait", "muted", "outbreak later")
        return 1.2
    end
    -- _busy dulu, baru Hold. Steal idle harus lihat ini lalu lepas kaki.
    M._busy = true
    if holdLegs(true) ~= true then
        emit("Wait", "warn", "need legs")
        return 0.15
    end
    pinLegs(PIN_SEC)
    local function afterWork()
        if stealBlocksScramble() == true then
            yieldToSteal()
        end
        return tonumber(M.delay) or DELAY_DEFAULT
    end
    buyShop()
    -- Outbreak: part dulu kalau telur part ada. 3/3 tetap farm sample.
    local droneN = type(st) == "table" and tonumber(st.DroneParts) or 0
    if needFarm then
        if pickupDrops(token) == true then
            return 0.05
        end
        if droneN < 3 then
            emit("Part", "live", string.format("DronePart %d/3", droneN + 1))
        else
            emit("Sample", "live", "outbreak")
        end
        farmDrones(token)
        return 0.22
    end
    if needLost1 then
        doLostPart(token, "LostPart1")
        return afterWork()
    end
    if needLost2 then
        doLostPart(token, "LostPart2")
        return afterWork()
    end
    M._busy = false
    M._want = false
    holdLegs(false)
    emit("Wait", "muted", "outbreak later")
    return 1.2
end

local function loop(token)
    hookDrops()
    while stillOn(token) do
        local waitSec = DELAY_DEFAULT
        local ok, err = pcall(function()
            waitSec = farmTick(token)
        end)
        if ok ~= true then
            dbg("SCRAMBLE", "tick " .. tostring(err))
            waitSec = 0.8
        end
        if stillOn(token) ~= true then
            break
        end
        task.wait(math.clamp(tonumber(waitSec) or DELAY_DEFAULT, DELAY_MIN, 3))
    end
    M._busy = false
    unpinLegs()
    holdLegs(false)
end

function M.setAutoBuy(on)
    M.autoBuy = on == true
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._want = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        emit("On", "live", "watching")
        task.spawn(function()
            M.kickSnap(true)
        end)
        task.spawn(function()
            loop(token)
            if M._token == token then
                M._loopOn = false
                M._busy = false
                if M.enabled ~= true then
                    emit("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._busy = false
    M._want = false
    M._token = (tonumber(M._token) or 0) + 1
    unpinLegs()
    holdLegs(false)
    emit("Idle", "muted", "off")
end

function M.Stop()
    M.setEnabled(false)
end

function M.infoText()
    local snap = M._snap
    if M.eventLive(snap) ~= true then
        return "Dr. Scramble event is off on this server."
    end
    local st = stateOf(snap) or {}
    local samples = tonumber(st.Samples) or 0
    local parts = tonumber(st.TotalParts)
    if parts == nil then
        local lost = 0
        if type(st.LostParts) == "table" then
            if st.LostParts.LostPart1 then
                lost += 1
            end
            if st.LostParts.LostPart2 then
                lost += 1
            end
        end
        parts = lost + (tonumber(st.DroneParts) or 0)
    end
    local w = type(snap) == "table" and snap.Window
    if type(w) == "table" and w.Active == true then
        local left = math.max((tonumber(w.EndsAt) or 0) - nowSrv(), 0)
        return string.format("OUTBREAK · %.0fs · %d/5 parts · %s Samples", left, parts, tostring(samples))
    end
    local nextAt = type(w) == "table" and tonumber(w.NextAt) or 0
    local untilNext = math.max(nextAt - nowSrv(), 0)
    return string.format("next outbreak %.0fs · %d/5 parts · %s Samples", untilNext, parts, tostring(samples))
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["auto.scramble.delay"])
    if delay then
        M.delay = math.clamp(delay, DELAY_MIN, DELAY_MAX)
    end
    if values["auto.scramble.shop.items"] ~= nil then
        M.shopWant = Core.parseKeyMap(values["auto.scramble.shop.items"])
    end
    if values["auto.scramble.shop.enabled"] ~= nil then
        M.setAutoBuy(Core.flagOn(values["auto.scramble.shop.enabled"]))
    end
    if values["auto.scramble.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["auto.scramble.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Scramble",
        expanded = false,
        status = {
            id = "auto.scramble.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local group = ui:CreateGroup(body)
    local _, infoLbl = ui:CreateRowLabel(group, {
        text = M.infoText(),
        style = "info",
        wrap = true,
    })
    G.__StealEggScrambleInfoSeq = (tonumber(G.__StealEggScrambleInfoSeq) or 0) + 1
    local infoSeq = G.__StealEggScrambleInfoSeq
    task.spawn(function()
        while GEN == G.__StealEggScrambleGen and infoSeq == G.__StealEggScrambleInfoSeq do
            pcall(function()
                if infoLbl and infoLbl.Parent then
                    infoLbl.Text = M.infoText()
                end
            end)
            if not (infoLbl and infoLbl.Parent) then
                break
            end
            task.wait(3)
        end
    end)

    ui:CreateRowInput(group, {
        id = "auto.scramble.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or DELAY_DEFAULT),
        clearOnFocus = false,
        hintText = "Jeda antar tick farm. Drone dihajar lewat ayunan bat di radius 12, seperti klien game.",
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "auto.scramble.enabled",
        label = "Enable Auto Scramble",
        persist = true,
        initial = M.enabled == true,
        hintText = "Rank 90. Ambil LostPart 1/2 di permukaan + DronePart 1–3 saat outbreak. Klaim 5/5 cave (NPC / Vault The Scrambler) tidak auto.",
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })
    ui:CreateRowDropdown(group, {
        id = "auto.scramble.shop.items",
        label = "Shop items · Samples",
        mode = "multi",
        placeholder = "Select items to buy...",
        hintText = "Dibayar dengan Samples. Mutation Consumable event masuk ke sini, bukan Boss Token lama.",
        clearable = true,
        persist = true,
        preserveItemOrder = true,
        initial = M.shopWant,
        getItems = function()
            return M.listShopItems()
        end,
        onChanged = function(a, b)
            M.shopWant = Core.parseKeyMap(Core.dropdownValue(a, b))
        end,
    })
    ui:CreateRowToggle(group, {
        id = "auto.scramble.shop.enabled",
        label = "Enable Auto Buy",
        persist = true,
        initial = M.autoBuy == true,
        hintText = "Beli item shop terpilih begitu Samples cukup. Tidak butuh kaki; jalan meski steal sedang aktif.",
        onChanged = function(on)
            M.setAutoBuy(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,   required = true },
    { key = "Rift",      name = "Auto Rift",     factory = function() -- Auto Rift: kumpulkan 3 pet bahan resep Rift, lalu tukar jadi telur Rift.
-- Bahan resep hanya diambil saat rule steal biasa tidak menemukan match
-- (penandaannya di wild_egg: info.riftOnly).

local Players = game:GetService("Players")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Rift", 0)
end

G.__StealEggRiftGen = (tonumber(G.__StealEggRiftGen) or 0) + 1
local GEN = G.__StealEggRiftGen

local DELAY_MIN = 0.5
local DELAY_MAX = 30
local DELAY_DEFAULT = 2
-- Satu siklus reset telur lapangan 300 detik. Dua siklus tanpa kategori yang
-- dicari berarti kategorinya memang jarang di zonanya, bukan cuma sial.
local STUCK_DEFAULT = 600
local STUCK_MIN = 60
local STUCK_MAX = 3600
local STATE_TTL = 5
-- needsSteal dipanggil untuk SETIAP record snapshot di nearestEgg, dan tiap
-- panggilan menyapu seluruh Inventory berikut Decode + MayEnterRift. Tanpa
-- cache pendek ini satu evaluasi snapshot jadi ribuan operasi.
local NEED_TTL = 1.5
-- Cadangan bahan resep yang SEDANG dibutuhkan. Auto Sell tetap ikut rulenya;
-- rift hanya menahan keepPerType ekor/butir per kategori resep, kelebihannya
-- tetap boleh dijual. Kategori lain tidak dilindungi rift.
local KEEP_PER_TYPE = 5
local KEEP_MIN = 0
local KEEP_MAX = 50
-- Himpunan uid yang dilindungi dipanggil PER ITEM oleh Auto Sell dan Fuse,
-- sedangkan menyusunnya harus menyapu Inventory berikut EggInventory. Tanpa
-- tahan sebentar, satu putaran jual berubah jadi ribuan sapuan.
local KEEP_TTL = 3
-- AskState pertama datang belakangan, jadi ada jendela di awal load ketika resep
-- belum diketahui. Selama jendela itu Auto Sell harus menahan diri, bukan
-- menjual bahan yang ternyata dibutuhkan. Kalau remote-nya memang tidak pernah
-- menjawab, tahan hanya selama ini lalu biarkan Auto Sell jalan normal.
local RECIPE_WAIT = 30

local M = {
    enabled = false,
    delay = DELAY_DEFAULT,
    stuckSec = STUCK_DEFAULT,
    autoRefresh = true,
    keepPerType = KEEP_PER_TYPE,
    _token = 0,
    _loopOn = false,
    _busy = false,
    _trades = 0,
    _state = nil,
    _stateAt = 0,
    _stateFetching = false,
    _need = {},
    _needAt = 0,
    _keepPets = nil,
    _keepEggs = nil,
    _keepSeen = nil,
    _keepUnknown = false,
    _reqSig = nil,
    _keepAt = 0,
    _stateOk = false,
    _seenAt = {},
    _startAt = 0,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggRift
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.enabled = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggRift = M

local tryRequire = Core.require
local Save, Remotes, Assets, AssetItems, Earn, FuseKernel, EggItemUtil, Tabs

local function bindGame()
    Save = Save or tryRequire("Shared.Save")
    Remotes = Remotes or tryRequire("Shared.Remotes")
    Assets = Assets or tryRequire("Data.Assets")
    AssetItems = AssetItems or tryRequire("Shared.Util.AssetItems")
    Earn = Earn or tryRequire("Shared.Util.AssetEarnings")
    FuseKernel = FuseKernel or tryRequire("Shared.Util.FuseKernel")
    EggItemUtil = EggItemUtil or tryRequire("Library.Util.EggItemUtil")
    Tabs = Tabs or tryRequire("Client.Tabs")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = type(fn) == "function" and fn or nil
    if M._onStatus then
        pcall(M._onStatus, M._status)
    end
end

local function getSave()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function riftRemote(name)
    bindGame()
    local bag = type(Remotes) == "table" and Remotes.Rift
    local rf = type(bag) == "table" and bag[name]
    if typeof(rf) == "Instance" then
        return rf
    end
    return nil
end

-- _stateAt dicatat pada setiap percobaan, bukan hanya yang berhasil: kalau
-- AskState gagal, panggilan berikutnya harus tetap menunggu. Tanpa itu satu
-- evaluasi snapshot bisa menembakkan satu InvokeServer per record telur.
function M.state(force)
    if force ~= true and (os.clock() - M._stateAt) < STATE_TTL then
        return M._state
    end
    M._stateAt = os.clock()
    local rf = riftRemote("AskState")
    if rf == nil then
        return M._state
    end
    local ok, st = pcall(function()
        return rf:InvokeServer()
    end)
    if ok and type(st) == "table" then
        M._state = st
        if type(st.Requirements) == "table" then
            M._stateOk = true
            -- Auto Sell menyaring auto-sell bawaan game per rarity bahan resep,
            -- jadi daftarnya harus disusun ulang tiap resepnya berganti. Ini
            -- dipasang di sini, bukan di dropKeepCache, karena cache itu juga
            -- gugur tiap menetas.
            local okSig, sig = pcall(table.concat, st.Requirements, "|")
            if okSig and sig ~= M._reqSig then
                M._reqSig = sig
                local sell = G.StealEggAutoSell or G.StealEggSell
                if type(sell) == "table" and type(sell.refreshHatchAutoSell) == "function" then
                    task.spawn(function()
                        pcall(sell.refreshHatchAutoSell)
                    end)
                end
            end
        end
    end
    return M._state
end

-- Dipanggil dari eggAllowed, yang jalan untuk setiap record snapshot di dalam
-- loop steal. Karena itu tidak boleh memblokir: kalau keadaannya basi,
-- penyegarannya dilempar ke thread lain dan pemanggil memakai salinan lama.
-- InvokeServer di sini akan menahan loop steal selama satu round trip server.
function M.requirements()
    if (os.clock() - M._stateAt) >= STATE_TTL and M._stateFetching ~= true then
        M._stateFetching = true
        task.spawn(function()
            M.state(true)
            M._stateFetching = false
        end)
    end
    local req = M._state and M._state.Requirements
    if type(req) ~= "table" then
        return {}
    end
    return req
end

function M.isRequired(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    for _, cat in ipairs(M.requirements()) do
        if tostring(cat) == category then
            return true
        end
    end
    return false
end

function M.categoryLabel(category)
    bindGame()
    category = tostring(category or "")
    local dir = type(Assets) == "table" and Assets.Directory
    local cfg = type(dir) == "table" and dir[category]
    local name = type(cfg) == "table" and tostring(cfg.DisplayName or "") or ""
    if name ~= "" then
        return name
    end
    return category
end

-- Pet yang tidak boleh disentuh Auto Sell maupun Auto Rift.
--
-- Hasil ukur di save hidup, dan ini penting: item di Inventory game ini TIDAK
-- punya field IsFavorite sama sekali (kuncinya cuma Category, ColorIndex,
-- ColorSeed, EyeColor, Gender, HasBeenFirstPlaced, InFuse, Mutations,
-- Personality, Scale), dan Save juga tidak memuat daftar favorit apa pun. Jadi
-- semua pemeriksaan "item.IsFavorite ~= true" yang berserakan di script ini
-- tidak pernah menyaring apa pun. Penanda favorit yang benar-benar bekerja
-- hanyalah aturan Auto Favorite lewat protectsUid, jadi itulah yang dipakai.
local function petLocked(uid, item)
    if type(item) == "table" and item.InFuse == true then
        return true
    end
    local fav = G.StealEggFavorite
    if type(fav) == "table" and type(fav.protectsUid) == "function" then
        local ok, hit = pcall(fav.protectsUid, uid)
        if ok and hit == true then
            return true
        end
    end
    return false
end

-- Kandidat korban untuk satu kategori. Cocoknya WAJIB lewat Category, bukan
-- nama tampilan: AssetId "Shark" tampil sebagai "Mutant Shark" sedangkan
-- "Finned Thresher" tampil sebagai "Shark", jadi cocok-nama akan menyerahkan
-- pet yang salah. Favorit dan pet ter-equip disaring seperti di GUI aslinya.
-- Yang dipulangkan yang penghasilan per detiknya paling kecil.
function M.victimFor(category, taken)
    category = tostring(category or "")
    if category == "" then
        return nil
    end
    bindGame()
    local data = getSave()
    local inv = data and data.Inventory
    if type(inv) ~= "table" then
        return nil
    end
    local equipped = {}
    if type(data.EquippedAssets) == "table" then
        for _, uid in pairs(data.EquippedAssets) do
            equipped[tostring(uid)] = true
        end
    end
    local best, bestRate
    for uid, item in pairs(inv) do
        uid = tostring(uid)
        -- petLocked ditaruh paling belakang supaya rantai and-nya menyaring
        -- kategori dulu: fungsi itu menyapu Save per panggilan, jadi tidak boleh
        -- kena setiap isi tas. Tanpa penjaga ini Auto Rift bisa menukarkan pet
        -- yang justru dilindungi Auto Favorite, sebab pemeriksaan IsFavorite di
        -- bawah tidak pernah benar-benar menyaring.
        local pass = type(item) == "table"
            and tostring(item.Category or "") == category
            and equipped[uid] ~= true
            and item.IsFavorite ~= true
            and (type(taken) ~= "table" or taken[uid] ~= true)
            and petLocked(uid, item) ~= true
        if pass and type(FuseKernel) == "table" and type(FuseKernel.MayEnterRift) == "function" then
            local okm, res = pcall(FuseKernel.MayEnterRift, uid, item)
            pass = okm == true and res == true
        end
        if pass then
            local rate = math.huge
            if type(AssetItems) == "table" and type(AssetItems.Decode) == "function"
                and type(Earn) == "table" and type(Earn.CatalogRatePerSecond) == "function"
            then
                local okd, dec = pcall(AssetItems.Decode, item)
                if okd then
                    local okr, r = pcall(Earn.CatalogRatePerSecond, dec)
                    if okr then
                        rate = tonumber(r) or math.huge
                    end
                end
            end
            if bestRate == nil or rate < bestRate then
                best, bestRate = uid, rate
            end
        end
    end
    return best, bestRate
end

function M.hasPet(category)
    return M.victimFor(category) ~= nil
end

-- Diukur pada save hidup: entri EggInventory sudah memuat AssetCategory dan
-- Placement tanpa perlu diurai, jadi ini bukan perbaikan bug melainkan
-- pengaman kalau bentuk simpanannya berubah — Auto Sell pun melewatkan entri
-- telur ke EggItemUtil dengan cara yang sama. Gagal urai berarti raw dipakai
-- apa adanya, bukan dianggap kosong.
local function eggRecord(raw)
    if type(raw) ~= "table" then
        return nil
    end
    bindGame()
    if type(EggItemUtil) == "table" then
        local fn = EggItemUtil.DeserializeSavedEgg or EggItemUtil.Decode
        if type(fn) == "function" then
            local ok, egg = pcall(fn, raw)
            if ok and type(egg) == "table" then
                return egg
            end
        end
    end
    return raw
end

local function eggCategory(raw)
    local egg = eggRecord(raw)
    if type(egg) ~= "table" then
        return ""
    end
    return tostring(egg.AssetCategory or egg.category or egg.Category or "")
end

-- Telur jenis ini sudah ada di tas atau sudah tertanam di plot. Dipakai supaya
-- satu kategori tidak di-steal berkali-kali padahal satu butir sudah cukup.
function M.hasEgg(category)
    category = tostring(category or "")
    if category == "" then
        return false
    end
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return false
    end
    for _, raw in pairs(inv) do
        if eggCategory(raw) == category then
            return true
        end
    end
    return false
end

-- Hasil per kategori disimpan sebentar karena jalur pemanggilnya panas.
-- Pulangannya: petnya belum ada, dan telurnya belum ada.
local function needCached(category)
    local now = os.clock()
    if (now - M._needAt) >= NEED_TTL then
        M._need = {}
        M._needAt = now
    end
    local hit = M._need[category]
    if hit ~= nil then
        return hit.pet, hit.egg
    end
    local pet = M.hasPet(category) ~= true
    local egg = M.hasEgg(category) ~= true
    M._need[category] = { pet = pet, egg = egg }
    return pet, egg
end

function M.dropNeedCache()
    M._need = {}
    M._needAt = 0
end

function M.needsSteal(category)
    if M.enabled ~= true then
        return false
    end
    category = tostring(category or "")
    if category == "" or M.isRequired(category) ~= true then
        return false
    end
    local noPet, noEgg = needCached(category)
    return noPet == true and noEgg == true
end

function M.wantsRiftSteal()
    return M.enabled == true
end

local function requiredSet()
    local set = {}
    for _, cat in ipairs(M.requirements()) do
        cat = tostring(cat or "")
        if cat ~= "" then
            set[cat] = true
        end
    end
    return set
end

local function itemEarn(item)
    if type(item) ~= "table" then
        return math.huge
    end
    if type(AssetItems) ~= "table" or type(AssetItems.Decode) ~= "function" then
        return math.huge
    end
    if type(Earn) ~= "table" or type(Earn.CatalogRatePerSecond) ~= "function" then
        return math.huge
    end
    local okd, dec = pcall(AssetItems.Decode, item)
    if not okd then
        return math.huge
    end
    local okr, r = pcall(Earn.CatalogRatePerSecond, dec)
    if okr then
        return tonumber(r) or math.huge
    end
    return math.huge
end

local function riftEligible(uid, item)
    if type(FuseKernel) ~= "table" or type(FuseKernel.MayEnterRift) ~= "function" then
        return true
    end
    local okm, res = pcall(FuseKernel.MayEnterRift, uid, item)
    return okm == true and res == true
end

-- Cadangan hanya untuk kategori resep yang sedang berlaku. Auto Sell tetap
-- mengikuti rulenya: pet/telur yang lolos rule dan bukan cadangan tetap dijual.
-- Plot (equip / Placement) mengurangi kuota, jadi kalau plot sudah 5, tas
-- tidak menahan lagi. Yang dilindungi Auto Favorite / Fuse tidak makan kuota.
-- Urutan uid stabil supaya cadangan tidak berganti tiap tick lalu habis dijual.
local function buildReserve()
    local pets, eggs = {}, {}
    local keep = math.floor(tonumber(M.keepPerType) or KEEP_PER_TYPE)
    if keep <= 0 or M.enabled ~= true then
        return pets, eggs
    end
    -- Setiap uid yang sempat dilihat, bukan cuma yang jadi cadangan. reserved()
    -- memakainya untuk tahu bahwa sebuah uid benar-benar baru, bukan sekadar
    -- tidak lolos kuota.
    local seen = {}
    -- Resep belum sampai: jangan pulangkan cadangan kosong, karena Auto Sell
    -- membaca itu sebagai "tidak ada yang perlu ditahan" lalu menghabiskan bahan
    -- resep sebelum rift sempat tahu apa yang dibutuhkan.
    local grace = (os.clock() - M._startAt) < RECIPE_WAIT
    local need = requiredSet()
    if next(need) == nil then
        return pets, eggs, M._stateOk ~= true and grace
    end
    local data = getSave()
    if type(data) ~= "table" then
        return pets, eggs, grace
    end

    local function pick(rowsByCat, plotByCat, out)
        for cat, rows in pairs(rowsByCat) do
            table.sort(rows, function(a, b)
                if a.rate ~= b.rate then
                    return a.rate < b.rate
                end
                return tostring(a.uid) < tostring(b.uid)
            end)
            local room = keep - (plotByCat[cat] or 0)
            for i = 1, math.min(room, #rows) do
                out[rows[i].uid] = true
            end
        end
    end

    local equipped = {}
    if type(data.EquippedAssets) == "table" then
        for _, uid in pairs(data.EquippedAssets) do
            equipped[tostring(uid)] = true
        end
    end
    local petFree, petPlot = {}, {}
    if type(data.Inventory) == "table" then
        for uid, item in pairs(data.Inventory) do
            uid = tostring(uid)
            seen[uid] = true
            local cat = type(item) == "table" and tostring(item.Category or "") or ""
            if cat ~= "" and need[cat] == true then
                if equipped[uid] == true then
                    petPlot[cat] = (petPlot[cat] or 0) + 1
                    -- Yang di plot ikut dilindungi, bukan cuma mengurangi kuota.
                    -- Uid-nya tidak berubah saat dilepas dari plot, jadi kalau
                    -- hanya dihitung, ada jeda sampai KEEP_TTL setelah unequip di
                    -- mana Auto Sell (delay 0.4s) bebas menjualnya.
                    pets[uid] = true
                elseif petLocked(uid, item) ~= true then
                    local list = petFree[cat]
                    if list == nil then
                        list = {}
                        petFree[cat] = list
                    end
                    list[#list + 1] = {
                        uid = uid,
                        rate = riftEligible(uid, item) and itemEarn(item) or math.huge,
                    }
                end
            end
        end
    end
    pick(petFree, petPlot, pets)

    local eggFree, eggPlot = {}, {}
    if type(data.EggInventory) == "table" then
        for uid, raw in pairs(data.EggInventory) do
            uid = tostring(uid)
            seen[uid] = true
            local egg = eggRecord(raw)
            local cat = eggCategory(raw)
            if cat ~= "" and need[cat] == true then
                if type(egg) == "table" and egg.Placement ~= nil then
                    eggPlot[cat] = (eggPlot[cat] or 0) + 1
                    eggs[uid] = true
                else
                    local list = eggFree[cat]
                    if list == nil then
                        list = {}
                        eggFree[cat] = list
                    end
                    list[#list + 1] = { uid = uid, rate = 0 }
                end
            end
        end
    end
    pick(eggFree, eggPlot, eggs)

    return pets, eggs, false, seen
end

-- uid/category opsional. Kalau diisi dan uid itu belum pernah terlihat saat
-- cadangan terakhir disusun, artinya barangnya baru masuk tas setelah snapshot.
-- Tanpa penyegaran paksa, Auto Sell (delay 0.4s) sempat menjual bahan resep yang
-- baru menetas di dalam jendela KEEP_TTL.
local function reserved(uid, category)
    local now = os.clock()
    local stale = M._keepPets == nil or (now - M._keepAt) >= KEEP_TTL
    if not stale and uid ~= nil and type(M._keepSeen) == "table" and M._keepSeen[tostring(uid)] ~= true then
        stale = requiredSet()[tostring(category or "")] == true
    end
    if stale then
        M._keepAt = now
        local pets, eggs, waiting, seen = buildReserve()
        M._keepPets, M._keepEggs, M._keepUnknown, M._keepSeen = pets, eggs, waiting == true, seen
    end
    return M._keepPets or {}, M._keepEggs or {}, M._keepUnknown == true
end

function M.dropKeepCache()
    M._keepPets = nil
    M._keepEggs = nil
    M._keepSeen = nil
    M._keepUnknown = false
    M._keepAt = 0
end

-- Benar kalau resepnya belum diketahui padahal Auto Rift menyala. Auto Sell dan
-- Fuse memakai ini untuk menahan diri sebentar, bukan menjual bahan resep.
function M.recipePending()
    if M.enabled ~= true then
        return false
    end
    local _, _, waiting = reserved()
    return waiting == true
end

-- Jumlah stok per kategori, dipakai UI dan log. Memulangkan tas, plot, total.
function M.stockOf(category)
    category = tostring(category or "")
    local data = getSave()
    if category == "" or type(data) ~= "table" then
        return 0, 0, 0
    end
    local equipped = {}
    if type(data.EquippedAssets) == "table" then
        for _, uid in pairs(data.EquippedAssets) do
            equipped[tostring(uid)] = true
        end
    end
    local bag, plot = 0, 0
    if type(data.Inventory) == "table" then
        for uid, item in pairs(data.Inventory) do
            if type(item) == "table" and tostring(item.Category or "") == category then
                if equipped[tostring(uid)] == true then
                    plot += 1
                else
                    bag += 1
                end
            end
        end
    end
    return bag, plot, bag + plot
end

-- Telur: Auto Sell jangan jual uid cadangan resep saja. Kelebihan tetap
-- mengikuti rule Auto Sell.
function M.shouldKeepEgg(uid, category)
    if M.enabled ~= true then
        return false
    end
    local _, eggs, waiting = reserved(uid, category)
    if waiting then
        return true
    end
    return eggs[tostring(uid or "")] == true
end

-- Pet: Auto Sell dan Fuse jangan ambil uid cadangan resep saja. Kelebihan
-- spesies resep yang lolos rule tetap dijual; spesies lain tidak dilindungi.
function M.shouldKeepPet(uid, category)
    if M.enabled ~= true then
        return false
    end
    local pets, _, waiting = reserved(uid, category)
    if waiting then
        return true
    end
    return pets[tostring(uid or "")] == true
end

function M.missingList()
    local out = {}
    for _, cat in ipairs(M.requirements()) do
        cat = tostring(cat)
        if needCached(cat) == true then
            out[#out + 1] = cat
        end
    end
    return out
end

function M.hasPlacePending()
    if M.enabled ~= true then
        return false
    end
    local Hatch = G.StealEggHatch
    if type(Hatch) == "table" and type(Hatch.plotAtCap) == "function" then
        local ok, full = pcall(Hatch.plotAtCap)
        if ok and full == true then
            return false
        end
    end
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return false
    end
    for _, raw in pairs(inv) do
        if type(raw) == "table" and raw.Placement == nil then
            local cat = eggCategory(raw)
            if cat ~= "" and M.isRequired(cat) and M.hasPet(cat) ~= true then
                return true
            end
        end
    end
    return false
end

local function stealBusy()
    local wild = G.StealEggWild
    if type(wild) ~= "table" then
        return false
    end
    if wild._busy == true or G.__StealEggBusy == true or G.__StealEggClaiming == true then
        return true
    end
    local carry = wild._carry
    if type(carry) == "table" and carry.IsCarrying == true then
        return true
    end
    return false
end

local function inPlot()
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.inPlotHome) == "function" then
        local ok, v = pcall(wild.inPlotHome)
        if ok and v == true then
            return true
        end
    end
    if type(wild) == "table" and type(wild.isOnPetArea) == "function" then
        local ok, v = pcall(wild.isOnPetArea)
        if ok and v == true then
            return true
        end
    end
    return false
end

local function goPlot(stillOn)
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.ensureInPen) == "function" then
        local ok, v = pcall(wild.ensureInPen, "rift", stillOn)
        return ok == true and v ~= false
    end
    return true
end

local function waitGap(stillOn, sec)
    sec = tonumber(sec) or 0
    if sec <= 0 then
        return
    end
    local t0 = os.clock()
    while os.clock() - t0 < sec do
        if type(stillOn) == "function" and stillOn() ~= true then
            return
        end
        task.wait(0.05)
    end
end

-- Telur bahan resep yang masih di tas, satu butir per kategori.
local function listBagNeeded()
    local out = {}
    local data = getSave()
    local inv = data and data.EggInventory
    if type(inv) ~= "table" then
        return out
    end
    local best = {}
    for uid, raw in pairs(inv) do
        if type(raw) == "table" and raw.Placement == nil then
            local cat = eggCategory(raw)
            if cat ~= "" and best[cat] == nil and M.isRequired(cat) and needCached(cat) == true then
                best[cat] = { uid = tostring(uid), category = cat, name = M.categoryLabel(cat) }
            end
        end
    end
    for _, row in pairs(best) do
        out[#out + 1] = row
    end
    table.sort(out, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    return out
end

local function placeNeeded(stillOn)
    local Hatch = G.StealEggHatch
    if type(Hatch) ~= "table" or type(Hatch.placeForced) ~= "function" then
        return 0, "hatch missing"
    end
    if type(Hatch.plotAtCap) == "function" then
        local ok, full = pcall(Hatch.plotAtCap)
        if ok and full == true then
            return 0, "plot full"
        end
    end
    local items = listBagNeeded()
    if #items == 0 then
        return 0, nil
    end
    M._busy = true
    if not goPlot(stillOn) or inPlot() ~= true then
        M._busy = false
        return 0, "need plot"
    end
    local used
    if type(Hatch.placeSlotMap) == "function" then
        local okSlots, slots = pcall(Hatch.placeSlotMap)
        if okSlots == true and type(slots) == "table" then
            used = slots
        end
    end
    local gap = math.clamp(tonumber(Hatch.placeDelay) or 0.35, 0.1, 5)
    local n = 0
    for i, row in ipairs(items) do
        if stillOn() ~= true then
            break
        end
        emit("Place", "live", row.name)
        local ok, err = Hatch.placeForced(row.uid, row.name, used)
        if ok then
            n += 1
            if i < #items then
                waitGap(stillOn, gap)
            end
        elseif string.find(string.lower(tostring(err or "")), "full", 1, true) then
            M._busy = false
            return n, "plot full"
        end
    end
    M._busy = false
    return n, nil
end

local function hatchNeeded(stillOn)
    local Hatch = G.StealEggHatch
    if type(Hatch) ~= "table" or type(Hatch.hatchForced) ~= "function"
        or type(Hatch.listPlotEggs) ~= "function"
    then
        return 0, 0
    end
    local okList, data = pcall(Hatch.listPlotEggs)
    if not okList or type(data) ~= "table" or type(data.eggs) ~= "table" then
        return 0, 0
    end
    local n, growing = 0, 0
    for _, info in ipairs(data.eggs) do
        if stillOn() ~= true then
            break
        end
        local cat = tostring(info.category or info.AssetCategory or "")
        if cat ~= "" and M.isRequired(cat) and needCached(cat) == true then
            if info.ready == true then
                M._busy = true
                emit("Hatch", "live", tostring(info.name or cat))
                local ok = Hatch.hatchForced(info.uid, info.name)
                M._busy = false
                if ok then
                    n += 1
                    -- Pet baru masuk Inventory: cache "belum punya" harus gugur
                    -- sekarang, jangan tunggu TTL.
                    M.dropNeedCache()
                    M.dropKeepCache()
                    waitGap(stillOn, 0.1)
                end
            else
                growing += 1
            end
        end
    end
    return n, growing
end

function M.finishReveal()
    local rf = riftRemote("AskFinishReveal")
    if rf ~= nil then
        pcall(function()
            rf:InvokeServer()
        end)
    end
end

-- Urutan Uid harus sejajar dengan urutan Requirements: server memasangkan
-- Uid ke-i dengan slot ke-i.
function M.tradeIn()
    local st = M.state(true)
    if type(st) ~= "table" then
        return false, "no state"
    end
    if st.Unlocked == false then
        return false, "locked"
    end
    -- Hadiah tukar sebelumnya belum ditutup: server menolak tukar berikutnya.
    if st.PendingReward == true then
        M.finishReveal()
        st = M.state(true) or st
    end
    local req = st.Requirements
    if type(req) ~= "table" or #req == 0 then
        return false, "no recipe"
    end
    local uids, taken = {}, {}
    for i, cat in ipairs(req) do
        cat = tostring(cat)
        local uid = M.victimFor(cat, taken)
        if uid == nil then
            return false, "missing " .. M.categoryLabel(cat)
        end
        taken[uid] = true
        uids[i] = uid
    end
    local rf = riftRemote("AskTradeIn")
    if rf == nil then
        return false, "remote"
    end
    local ok, res, why = pcall(function()
        return rf:InvokeServer(uids)
    end)
    if not ok then
        return false, tostring(res)
    end
    if res ~= true then
        return false, tostring(why or "ditolak")
    end
    M._trades += 1
    M.finishReveal()
    M._seenAt = {}
    M._startAt = os.clock()
    M.dropNeedCache()
    M.dropKeepCache()
    M.state(true)
    return true
end

-- Kategori yang tidak pernah muncul di lapangan selama stuckSec berarti memang
-- jarang di zonanya. Resepnya dikocok pakai jatah gratis harian saja; kalau
-- jatahnya habis, tunggu rotasi banner dan jangan beli refresh.
function M.maybeRefresh()
    if M.autoRefresh ~= true then
        return false
    end
    local st = M.state()
    if type(st) ~= "table" or (tonumber(st.FreeRefreshesRemaining) or 0) <= 0 then
        return false
    end
    local stuck = math.clamp(tonumber(M.stuckSec) or STUCK_DEFAULT, STUCK_MIN, STUCK_MAX)
    local now = os.clock()
    for _, cat in ipairs(M.requirements()) do
        cat = tostring(cat)
        if M.needsSteal(cat) then
            local seen = tonumber(M._seenAt[cat])
            if seen == nil then
                -- Belum pernah terlihat sejak fitur menyala: hitung dari jam mulai.
                seen = M._startAt
                M._seenAt[cat] = seen
            end
            if (now - seen) >= stuck then
                local rf = riftRemote("AskRefresh")
                if rf == nil then
                    return false
                end
                local ok, res = pcall(function()
                    return rf:InvokeServer()
                end)
                M._seenAt = {}
                M._startAt = now
                M.state(true)
                return ok == true and res == true, cat
            end
        end
    end
    return false
end

-- Catat kapan tiap kategori bahan resep terakhir terlihat di lapangan. Ini yang
-- membedakan "belum keluar undiannya" dari "memang tidak pernah spawn".
local function scanField()
    local ok, snap = Core.eggCall("GetAreaEggSnapshot")
    if not (ok and type(snap) == "table" and type(snap.Records) == "table") then
        return
    end
    local now = os.clock()
    for _, rec in pairs(snap.Records) do
        if type(rec) == "table" then
            local cat = tostring(rec.AssetCategory or rec.Category or "")
            if cat ~= "" and M.isRequired(cat) then
                M._seenAt[cat] = now
            end
        end
    end
end

local function tick(stillOn)
    local st = M.state()
    if type(st) ~= "table" then
        emit("Wait", "warn", "no state")
        return "idle"
    end
    if st.Unlocked == false then
        emit("Locked", "warn", "speed " .. tostring(st.UnlockSpeedPower or "?"))
        return "locked"
    end
    if st.PendingReward == true then
        M.finishReveal()
        st = M.state(true) or st
    end
    if #M.requirements() == 0 then
        emit("Wait", "warn", "no recipe")
        return "idle"
    end

    local missing = M.missingList()
    -- Bahan lengkap: tukar sekarang. Ini tidak butuh loop steal, jadi tidak
    -- perlu menunggu steal selesai.
    if #missing == 0 then
        M._busy = true
        emit("Trade", "live", tostring(#M.requirements()) .. " pet")
        local ok, why = M.tradeIn()
        M._busy = false
        if ok then
            emit("Traded", "success", "total " .. tostring(M._trades))
            return "ok"
        end
        emit("Denied", "warn", tostring(why))
        return "deny"
    end

    if stealBusy() then
        emit("Wait", "warn", "steal")
        return "busy"
    end

    scanField()
    local placed, placeErr = placeNeeded(stillOn)
    if stillOn() ~= true then
        return "off"
    end
    local hatched, growing = hatchNeeded(stillOn)
    if stillOn() ~= true then
        return "off"
    end

    local label = table.concat(missing, " · ")
    if placeErr == "plot full" then
        emit("Full", "warn", label)
        return "full"
    end
    if placeErr == "need plot" then
        emit("Wait", "warn", "need plot")
        return "plot"
    end
    if (tonumber(placed) or 0) > 0 or (tonumber(hatched) or 0) > 0 then
        emit("On", "live", label)
        return "ok"
    end

    local refreshed, cat = M.maybeRefresh()
    if refreshed then
        emit("Reroll", "live", "stuck · " .. M.categoryLabel(cat))
        return "ok"
    end

    if (tonumber(growing) or 0) > 0 then
        emit("Idle", "muted", "growing · " .. label)
        return "grow"
    end
    emit("Idle", "muted", "seeking " .. label)
    return "idle"
end

local function loop(token)
    local function stillOn()
        return M.enabled == true and M._token == token and GEN == G.__StealEggRiftGen
    end
    while stillOn() do
        M._busy = false
        local ok, why = pcall(tick, stillOn)
        M._busy = false
        if stillOn() ~= true then
            break
        end
        local waitSec = math.clamp(tonumber(M.delay) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        if ok and why == "ok" then
            waitSec = 0.2
        elseif ok and (why == "busy" or why == "plot") then
            waitSec = 0.35
        elseif ok and (why == "full" or why == "locked" or why == "deny") then
            waitSec = 5
        end
        waitGap(stillOn, waitSec)
    end
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        M._seenAt = {}
        M._startAt = os.clock()
        M.dropNeedCache()
        M.dropKeepCache()
        emit("On", "live", "watching")
        -- Isi keadaan lebih dulu supaya requirements() tidak memulangkan daftar
        -- kosong di tick pertama.
        task.spawn(function()
            M.state(true)
        end)
        task.spawn(function()
            loop(token)
            if M._token == token then
                M._loopOn = false
                if M.enabled ~= true then
                    emit("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._token = (tonumber(M._token) or 0) + 1
    emit("Idle", "muted", "off")
end

function M.Stop()
    M.setEnabled(false)
end

-- Mesin Rift memakai Tabs.Show("RiftTradeIn") di ProximityPrompt.
-- Tombol ini membuka GUI yang sama tanpa harus jalan ke mesin.
function M.showUi()
    bindGame()
    M.state(true)
    if type(Tabs) == "table" and type(Tabs.IsShowing) == "function" then
        local okShow, showing = pcall(Tabs.IsShowing, "RiftTradeIn")
        if okShow and showing == true then
            return true
        end
    end
    if type(Tabs) == "table" and type(Tabs.Show) == "function" then
        local ok, res = pcall(Tabs.Show, "RiftTradeIn")
        if ok then
            return true
        end
        return false, tostring(res or "Tabs.Show")
    end
    local pg = LP:FindFirstChild("PlayerGui")
    local gui = pg and pg:FindFirstChild("RiftTradeIn")
    if gui and gui:IsA("ScreenGui") then
        gui.Enabled = true
        return true
    end
    return false, "Tabs missing"
end

function M.recipeText()
    local st = M.state()
    if type(st) ~= "table" then
        return "Recipe: —"
    end
    local req = M.requirements()
    if #req == 0 then
        return "Recipe: —"
    end
    local parts = {}
    for _, cat in ipairs(req) do
        cat = tostring(cat)
        -- Stok tas/plot ditampilkan supaya terlihat apakah cadangan per tipe
        -- benar-benar tertahan, bukan cuma percaya bahwa Auto Sell menurut.
        local bag, plot = M.stockOf(cat)
        parts[#parts + 1] = string.format(
            "%s %d+%d%s",
            M.categoryLabel(cat), bag, plot,
            M.hasPet(cat) and " ✓" or ""
        )
    end
    return string.format(
        "%s → %s | %s",
        tostring(st.BannerDisplayName or st.BannerId or "?"),
        table.concat(parts, ", "),
        string.format("pity %s/%s · reroll %s",
            tostring(st.PityCount or 0), tostring(st.PityThreshold or 50),
            tostring(st.FreeRefreshesRemaining or 0))
    )
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["steal.rift.delay"])
    if delay then
        M.delay = math.clamp(delay, DELAY_MIN, DELAY_MAX)
    end
    local stuck = tonumber(values["steal.rift.stuck"])
    if stuck then
        M.stuckSec = math.clamp(stuck, STUCK_MIN, STUCK_MAX)
    end
    local keep = tonumber(values["steal.rift.keep"])
    if keep then
        M.keepPerType = math.clamp(math.floor(keep), KEEP_MIN, KEEP_MAX)
        M.dropKeepCache()
    end
    if values["steal.rift.autoRefresh"] ~= nil then
        M.autoRefresh = Core.flagOn(values["steal.rift.autoRefresh"])
    end
    if values["steal.rift.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.rift.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Rift",
        expanded = false,
        status = {
            id = "steal.rift.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local group = ui:CreateGroup(body)

    local _, recipeLbl = ui:CreateRowLabel(group, {
        text = M.recipeText(),
        style = "info",
        wrap = true,
    })
    G.__StealEggRiftRecipeSeq = (tonumber(G.__StealEggRiftRecipeSeq) or 0) + 1
    local recipeSeq = G.__StealEggRiftRecipeSeq
    task.spawn(function()
        while GEN == G.__StealEggRiftGen and recipeSeq == G.__StealEggRiftRecipeSeq do
            pcall(function()
                M.state(true)
                if recipeLbl and recipeLbl.Parent then
                    recipeLbl.Text = M.recipeText()
                end
            end)
            if not (recipeLbl and recipeLbl.Parent) then
                break
            end
            task.wait(5)
        end
    end)

    ui:CreateRowButton(group, {
        text = "Show UI Rift",
        onClick = function()
            local ok, why = M.showUi()
            if ok then
                emit("UI", "success", "Rift")
            else
                emit("UI", "warn", tostring(why or "fail"))
            end
        end,
    })

    ui:CreateRowInput(group, {
        id = "steal.rift.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or DELAY_DEFAULT),
        clearOnFocus = false,
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        end,
    })
    ui:CreateRowInput(group, {
        id = "steal.rift.stuck",
        label = "Reroll when stuck · sec",
        persist = true,
        initial = tostring(M.stuckSec or STUCK_DEFAULT),
        clearOnFocus = false,
        hintText = "An ingredient category that never shows up in the field for this long counts as stuck, then the recipe is rerolled using the free daily refreshes (2x).",
        onChanged = function(text)
            M.stuckSec = math.clamp(tonumber(text) or STUCK_DEFAULT, STUCK_MIN, STUCK_MAX)
        end,
    })
    ui:CreateRowInput(group, {
        id = "steal.rift.keep",
        label = "Keep per type",
        persist = true,
        initial = tostring(M.keepPerType or KEEP_PER_TYPE),
        clearOnFocus = false,
        hintText = "While Auto Rift is on, keep this many of each recipe pet/egg (bag + plot). Auto Sell still follows its rules: extras of those types, and every other type, still sell. 0 = no reserve.",
        onChanged = function(text)
            M.keepPerType = math.clamp(math.floor(tonumber(text) or KEEP_PER_TYPE), KEEP_MIN, KEEP_MAX)
            M.dropKeepCache()
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.rift.autoRefresh",
        label = "Auto Reroll when stuck",
        persist = true,
        initial = M.autoRefresh == true,
        onChanged = function(on)
            M.autoRefresh = on == true
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.rift.enabled",
        label = "Enable Auto Rift",
        persist = true,
        initial = M.enabled == true,
        hintText = "Recipe ingredients are stolen only when the normal Steal rules find no match, then placed and hatched on their own, then traded in.",
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,         required = true },
    { key = "Gear",      name = "Gear",          factory = function() -- Auto Gear tab: Equip Best Pet
-- Dump PetList (tombol game): Remotes.Haul.WearBest:InvokeServer() -> ok, err
-- FetchWearBestStatus hanya buat badge UI, bukan syarat equip. Jangan cek dulu:
-- status itu bisa "already best" sementara WearBest masih swap earn lebih tinggi.
-- Client + server debounce 5s. err = "DEBOUNCE" / "LOCKED" / message.

local Workspace = game:GetService("Workspace")
local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Gear", 0)
end

G.__StealEggGearGen = (tonumber(G.__StealEggGearGen) or 0) + 1
local GEN = G.__StealEggGearGen

local WEAR_COOLDOWN = 5
local DELAY_MIN = 5
local DELAY_MAX = 60
local DELAY_DEFAULT = 5
local REMOTE_WEAR = "Backpack: WearBest"

local M = {
    enabled = false,
    delay = DELAY_DEFAULT,
    _token = 0,
    _loopOn = false,
    _busy = false,
    _lastWear = 0,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggGear
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.enabled = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggGear = M

local tryRequire = Core.require
local Remotes, Network

local function bindGame()
    Remotes = Remotes or tryRequire("Shared.Remotes")
    Network = Network or tryRequire("Library.Client.Network")
end

local function haul()
    bindGame()
    local bag = Remotes and Remotes.Haul
    if type(bag) == "table" then
        return bag
    end
    bag = Network and Network.Haul
    if type(bag) == "table" then
        return bag
    end
    return nil
end

local function unpackInvoke(a, b)
    if type(a) == "table" then
        return a[1], a[2]
    end
    return a, b
end

local function invokeHaul(inst)
    if typeof(inst) ~= "Instance" or type(inst.InvokeServer) ~= "function" then
        return false, nil, nil
    end
    -- BackpackController packs InvokeServer returns; PetList reads unpacked.
    local ok, packed = pcall(function()
        return { inst:InvokeServer() }
    end)
    if not ok or type(packed) ~= "table" then
        return false, nil, nil
    end
    local a, b = unpackInvoke(packed[1], packed[2])
    return true, a, b
end

local function invokeNamed(name)
    if type(Network) ~= "table" or type(Network.Invoke) ~= "function" then
        return false, nil, nil
    end
    local ok, packed = pcall(function()
        return { Network.Invoke(name) }
    end)
    if not ok or type(packed) ~= "table" then
        return false, nil, nil
    end
    local a, b = unpackInvoke(packed[1], packed[2])
    return true, a, b
end

local function wearBest()
    local bag = haul()
    local called, a, b = invokeHaul(bag and bag.WearBest)
    if not called then
        called, a, b = invokeNamed(REMOTE_WEAR)
    end
    if not called then
        return false, "no remote"
    end
    return a == true, b
end

local function publicDetail(text, detail)
    detail = tostring(detail or "")
    if detail == "" or detail == "—" then
        return "—"
    end
    local low = string.lower(detail)
    if string.find(low, "remote", 1, true) or string.find(low, "invoke", 1, true)
        or string.find(low, "wearbest", 1, true) or string.find(low, "fetchwear", 1, true) then
        return "—"
    end
    if #detail > 28 then
        return "—"
    end
    return detail
end

local function emit(text, style, detail)
    local raw = tostring(text or "Idle")
    local pub = raw
    if raw == "Denied" or raw == "Error" then
        pub = "Failed"
    end
    M._status = {
        text = pub,
        style = style or "muted",
        detail = publicDetail(raw, detail),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = type(fn) == "function" and fn or nil
    if M._onStatus then
        pcall(M._onStatus, M._status)
    end
end

local function sellBusy()
    local sell = G.StealEggSell
    local pet = type(sell) == "table" and sell.pet
    return type(pet) == "table" and pet._busy == true
end

local function now()
    local t = Workspace.GetServerTimeNow
    if type(t) == "function" then
        local ok, n = pcall(t, Workspace)
        if ok and type(n) == "number" then
            return n
        end
    end
    return os.clock()
end

local function waitDelay()
    local n = tonumber(M.delay) or DELAY_DEFAULT
    if n < DELAY_MIN then
        n = DELAY_MIN
    elseif n > DELAY_MAX then
        n = DELAY_MAX
    end
    task.wait(n)
end

local function errLabel(err)
    err = tostring(err or "")
    local low = string.lower(err)
    if err == "DEBOUNCE" or err == "LOCKED" or string.find(low, "wait", 1, true) then
        return "cooldown"
    end
    if err == "" or err == "nil" then
        return "failed"
    end
    return err
end

local function equipOnce()
    if M._busy then
        return false, "busy"
    end
    if sellBusy() then
        emit("Wait", "warn", "sell running")
        return false, "sell"
    end
    local t = now()
    local remain = WEAR_COOLDOWN - (t - (tonumber(M._lastWear) or 0))
    if remain > 0.05 then
        emit("Wait", "warn", string.format("cd %.1fs", remain))
        return false, "cooldown"
    end
    -- Sama tombol game: stamp cooldown dulu, lalu WearBest. Tanpa FetchWearBestStatus.
    M._lastWear = t
    M._busy = true
    emit("Equip", "live", "best pet")
    local ok, err = wearBest()
    M._busy = false
    if ok then
        emit("Equipped", "success")
        return true
    end
    emit("Wait", "warn", errLabel(err))
    return false, err
end

local function loop(token)
    while M.enabled == true and M._token == token and G.__StealEggGearGen == GEN do
        if sellBusy() then
            emit("Wait", "warn", "sell running")
            task.wait(0.4)
        else
            equipOnce()
            if M.enabled ~= true or M._token ~= token then
                break
            end
            waitDelay()
        end
    end
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        emit("On", "live", "watching")
        task.spawn(function()
            loop(token)
            if M._token == token then
                M._loopOn = false
                if M.enabled ~= true then
                    emit("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._token = (tonumber(M._token) or 0) + 1
    emit("Idle", "muted", "off")
end

function M.Stop()
    M.setEnabled(false)
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["steal.gear.equipBest.delay"])
    if delay then
        M.delay = math.clamp(delay, DELAY_MIN, DELAY_MAX)
    end
    if values["steal.gear.equipBest.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.gear.equipBest.enabled"]))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Equip Best Pet",
        expanded = false,
        status = {
            id = "steal.gear.equipBest.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local group = ui:CreateGroup(body)
    ui:CreateRowInput(group, {
        id = "steal.gear.equipBest.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or DELAY_DEFAULT),
        clearOnFocus = false,
        hintText = "Min 5s · cooldown Equip Best di game.",
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or DELAY_DEFAULT, DELAY_MIN, DELAY_MAX)
        end,
    })

    ui:CreateRowToggle(group, {
        id = "steal.gear.equipBest.enabled",
        label = "Enable Auto Equip Best",
        persist = true,
        initial = M.enabled == true,
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,         required = true },
    { key = "Fuse",      name = "Fuse",          factory = function() -- Auto Fuse: 3 pet spesies sama → 1 egg
-- Dump: Fusery.LoadPet / EjectPet / BeginFuse / FinishReveal
-- FuseKernel: same Category, bukan favorite, bukan CannotFuse, harga = earn*180 * mut.
-- Size labels (AssetScale, same as game): BIG≥5 HUGE≥10 TITANIC≥25 GARGANTUAN≥45.

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Fuse", 0)
end

G.__StealEggFuseGen = (tonumber(G.__StealEggFuseGen) or 0) + 1
local GEN = G.__StealEggFuseGen

local CFG = {
    delayMin = 0.2,
    delayMax = 10,
    delayDefault = 0.4,
    keepDefault = 1,
    keepMax = 50,
    slots = 3,
    near = 14,
    eggMax = 115,
    compare = "below",
}
local COMPARE_ITEMS = {
    { key = "above", name = "Above" },
    { key = "below", name = "Below" },
}
local NO_MUTATION = "No Mutation"
local SIZE_ITEMS = {
    { key = "normal", name = "Normal", sort = 0 },
    { key = "big", name = "BIG", sort = 1 },
    { key = "huge", name = "HUGE", sort = 2 },
    { key = "titanic", name = "TITANIC", sort = 3 },
    { key = "gargantuan", name = "GARGANTUAN", sort = 4 },
}

local function newDraft()
    return {
        rarities = {},
        names = {},
        mutations = {},
        kgRule = "0",
        kgMode = CFG.compare,
        rateRule = "0",
        rateMode = CFG.compare,
        priceRule = "0",
        priceMode = CFG.compare,
        keep = CFG.keepDefault,
    }
end

local M = {
    enabled = false,
    delay = CFG.delayDefault,
    rules = {},
    sizes = { normal = true },
    draft = newDraft(),
    _token = 0,
    _loopOn = false,
    _busy = false,
    _fused = 0,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggFuse
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.enabled = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggFuse = M

local tryRequire = Core.require
local F = {}

function F.bind()
    F.Save = F.Save or tryRequire("Library.Client.Save")
    F.Network = F.Network or tryRequire("Library.Client.Network")
    F.Remotes = F.Remotes or tryRequire("Shared.Remotes")
    F.Assets = F.Assets or tryRequire("Directory.Assets")
    F.RarityDir = F.RarityDir or tryRequire("Directory.Rarity")
    F.AssetItems = F.AssetItems or tryRequire("Library.Util.AssetItemSerialization") or tryRequire("Library.Util.AssetItemUtil")
    F.AssetEarn = F.AssetEarn or tryRequire("Library.Util.AssetGenerationUtil")
    F.Mutations = F.Mutations or tryRequire("Library.Modules.Mutations")
    F.GetPrice = F.GetPrice or tryRequire("Library.Util.GetPriceValueForItem")
    F.Kernel = F.Kernel or tryRequire("Shared.Util.FuseKernel") or tryRequire("Library.Util.FuseKernelUtil")
    F.Eggs = F.Eggs or tryRequire("Shared.Types.Eggs") or tryRequire("Library.Types.Eggs")
end

function F.assetDir()
    local a = F.Assets
    if type(a) ~= "table" then
        return nil
    end
    if type(a.Directory) == "table" then
        return a.Directory
    end
    return a
end

function F.getSave()
    F.bind()
    local Save = F.Save
    if type(Save) == "table" and type(Save.Cache) == "function" then
        local okC, bag = pcall(Save.Cache)
        if okC and type(bag) == "table" then
            local data = bag[LP]
            if type(data) == "table" then
                return data
            end
        end
    end
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, data = pcall(Save.Get, LP, true)
        if ok then
            return data
        end
        ok, data = pcall(Save.Get)
        if ok then
            return data
        end
    end
    return nil
end

function F.publicDetail(text, detail)
    detail = tostring(detail or "")
    if detail == "" then
        return "—"
    end
    local low = string.lower(detail)
    if string.find(low, "remote", 1, true) or string.find(low, "invoke", 1, true)
        or string.find(low, "fusery", 1, true) or string.find(low, "uid", 1, true) then
        return "—"
    end
    if #detail > 28 then
        return "—"
    end
    return detail
end

function F.emit(text, style, detail)
    local raw = tostring(text or "Idle")
    local pub = raw
    if raw == "Denied" or raw == "Error" then
        pub = "Failed"
    end
    M._status = {
        text = pub,
        style = style or "muted",
        detail = F.publicDetail(raw, detail),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = type(fn) == "function" and fn or nil
    if M._onStatus then
        pcall(M._onStatus, M._status)
    end
end

function F.mapHas(map)
    return type(map) == "table" and next(map) ~= nil
end

function F.copyMap(value)
    return Core.parseKeyMap(value)
end

function F.mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

function F.newRuleId()
    return "fr" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

function F.clampKeep(n)
    n = math.floor(tonumber(n) or CFG.keepDefault)
    if n < 0 then
        n = 0
    elseif n > CFG.keepMax then
        n = CFG.keepMax
    end
    return n
end

function F.clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or CFG.compare))
    if fallback == "above" then
        return "above"
    end
    return "below"
end

function F.unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

function F.parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

function F.parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, F.clampCompareMode(explicitMode, signedBelow and "below" or CFG.compare), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), F.clampCompareMode(explicitMode, "below"), F.unsignedRuleText(txt)
    end
    return n, F.clampCompareMode(explicitMode, CFG.compare), F.unsignedRuleText(txt)
end

function F.parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = F.parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, F.clampCompareMode(explicitMode, signedBelow and "below" or CFG.compare), (raw == "" and "0" or F.unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), F.clampCompareMode(explicitMode, "below"), F.unsignedRuleText(raw)
    end
    return n, F.clampCompareMode(explicitMode, CFG.compare), F.unsignedRuleText(raw)
end

function F.isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

function F.sanitizeRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = F.parseSignedRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = F.parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = F.parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "rarity", "name", "mutation", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or F.newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        rarities = F.copyMap(rule.rarities),
        names = F.copyMap(rule.names),
        mutations = F.copyMap(rule.mutations),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
        keep = F.clampKeep(rule.keep),
    }
end

function F.sanitizeRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = F.sanitizeRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

function F.enabledRules()
    local out = {}
    for _, rule in ipairs(M.rules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    return out
end

function F.rarityOf(category)
    local dir = F.assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local r = type(cfg) == "table" and cfg.Rarity
    if type(r) ~= "table" then
        return 0, "", tostring(category)
    end
    local num = tonumber(r.RarityNumber) or 0
    local id = tostring(r._id or r.DisplayName or r.Name or "")
    local name = tostring(cfg.DisplayName or cfg.Name or cfg._id or category)
    return num, id, name
end

function F.displayOf(category)
    local _, _, name = F.rarityOf(category)
    return name
end

function F.cannotFuse(category)
    local dir = F.assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    return type(cfg) == "table" and cfg.CannotFuse == true
end

function F.mutationNames(data)
    local out, seen = {}, {}
    local function add(name)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        out[#out + 1] = name
    end
    if type(data) ~= "table" then
        return out
    end
    if type(data.Mutations) == "table" then
        for _, name in ipairs(data.Mutations) do
            add(name)
        end
        for _, name in pairs(data.Mutations) do
            if type(name) == "string" then
                add(name)
            end
        end
    end
    add(data.BaseMutation)
    return out
end

function F.itemKg(category, scale)
    scale = tonumber(scale) or 0
    local util = F.AssetItems
    if type(util) == "table" then
        local fn = util.GetVisualWeightKg or util.WeightKg
        if type(fn) == "function" then
            local ok, kg = pcall(fn, { Category = category, Scale = scale, Mutations = {} })
            if ok then
                return tonumber(kg) or 0
            end
        end
    end
    local dir = F.assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local weight = type(cfg) == "table" and tonumber(cfg.ModelWeight) or 1
    return weight * math.max(scale, 0) ^ 3
end

function F.itemRate(assetData, saveData)
    if type(assetData) ~= "table" then
        return 0
    end
    local earn = F.AssetEarn
    if type(earn) == "table" then
        local rateFn = earn.GetRate or earn.RatePerSecond
        if type(rateFn) == "function" then
            local rebirth = type(saveData) == "table" and tonumber(saveData.Rebirth) or 0
            local ok, n = pcall(rateFn, assetData, rebirth or 0, saveData and saveData.Gamepasses, saveData and saveData.Products)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    return 0
end

function F.itemPrice(assetData, rate)
    local getPrice = F.GetPrice
    if type(getPrice) == "function" then
        local ok, n = pcall(getPrice, assetData)
        if ok then
            return math.max(0, tonumber(n) or 0)
        end
    elseif type(getPrice) == "table" then
        local fn = getPrice.SalePrice or getPrice.GetPriceValueForItem
        if type(fn) == "function" then
            local ok, n = pcall(fn, assetData)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    return math.max(0, (tonumber(rate) or 0) * 100)
end

function F.matchesName(category, names)
    if not F.mapHas(names) then
        return true
    end
    category = tostring(category or "")
    return names[category] == true or names[string.lower(category)] == true
end

function F.matchesRarity(category, rarities)
    if not F.mapHas(rarities) then
        return true
    end
    local num, id = F.rarityOf(category)
    return rarities[tostring(num)] == true or rarities[id] == true or rarities[string.lower(id)] == true
end

function F.matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "above" then
        return value >= n
    end
    return value <= n
end

function F.matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if not F.mapHas(selected) then
        return true
    end
    local wantNone = false
    local hasPick = false
    for key, on in pairs(selected) do
        if on == true then
            if F.isNoMutationKey(key) then
                wantNone = true
            else
                hasPick = true
            end
        end
    end
    if wantNone and not hasPick then
        return not has
    end
        if hasPick then
            for i = 1, #names do
                local name = names[i]
                if type(Core.mutationPicked) == "function" then
                    if Core.mutationPicked(name, selected) then
                        return true
                    end
                elseif selected[name] == true or selected[string.lower(name)] == true then
                    return true
                end
            end
        if wantNone and not has then
            return true
        end
        return false
    end
    return true
end

function F.sizeKey(scale)
    scale = tonumber(scale) or 0
    if scale >= 45 then
        return "gargantuan"
    end
    if scale >= 25 then
        return "titanic"
    end
    if scale >= 10 then
        return "huge"
    end
    if scale >= 5 then
        return "big"
    end
    return "normal"
end

function F.sizeLabel(key)
    key = string.lower(tostring(key or ""))
    for _, item in ipairs(SIZE_ITEMS) do
        if item.key == key then
            return item.name
        end
    end
    return key
end

function F.matchesSize(size, sizes)
    if not F.mapHas(sizes) then
        return true
    end
    size = string.lower(tostring(size or "normal"))
    return sizes[size] == true or sizes[string.lower(size)] == true
end

function F.ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

function F.ruleMatches(rule, rec)
    if type(rule) ~= "table" or type(rec) ~= "table" then
        return false
    end
    if F.ruleFieldOn(rule, "name") and not F.matchesName(rec.category, rule.names) then
        return false
    end
    if F.ruleFieldOn(rule, "rarity") and not F.matchesRarity(rec.category, rule.rarities) then
        return false
    end
    if F.ruleFieldOn(rule, "kg") and not F.matchesSigned(rec.kg, rule.kg, rule.kgMode) then
        return false
    end
    if F.ruleFieldOn(rule, "rate") and not F.matchesSigned(rec.rate, rule.rate, rule.rateMode) then
        return false
    end
    if F.ruleFieldOn(rule, "price") and not F.matchesSigned(rec.price, rule.price, rule.priceMode) then
        return false
    end
    if F.ruleFieldOn(rule, "mutation") and not F.matchesMutation(rec.muts, rule) then
        return false
    end
    if not F.matchesSize(rec.size, M.sizes) then
        return false
    end
    return true
end

function F.firstRule(rec)
    for _, rule in ipairs(F.enabledRules()) do
        if F.ruleMatches(rule, rec) then
            return rule
        end
    end
    return nil
end

function F.isEquipped(uid, data)
    if type(data) ~= "table" or type(data.EquippedAssets) ~= "table" then
        return false
    end
    for _, v in pairs(data.EquippedAssets) do
        if tostring(v) == tostring(uid) then
            return true
        end
    end
    return false
end

function F.deserializePet(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if raw.Category ~= nil then
        return raw
    end
    local ser = F.AssetItems
    if type(ser) == "table" then
        local fn = ser.Deserialize or ser.Decode
        if type(fn) == "function" then
            local ok, item = pcall(fn, raw)
            if ok and type(item) == "table" then
                return item
            end
        end
    end
    return nil
end

function F.eggCount(data)
    local bag = type(data) == "table" and data.EggInventory
    if type(bag) ~= "table" then
        return 0
    end
    local n = 0
    for _ in pairs(bag) do
        n += 1
    end
    return n
end

function F.eggMax()
    local eggs = F.Eggs
    local n = type(eggs) == "table" and tonumber(eggs.MAX_INVENTORY)
    return n or CFG.eggMax
end

function F.slotUids(data)
    local out = {}
    local slots = type(data) == "table" and data.FusionSlots
    if type(slots) ~= "table" then
        return out
    end
    for i = 1, CFG.slots do
        local uid = slots[i]
        if uid ~= nil and uid ~= false and uid ~= "" then
            out[#out + 1] = tostring(uid)
        end
    end
    return out
end

function F.slotCount(data)
    return #F.slotUids(data)
end

function F.fusery()
    F.bind()
    local bag = F.Remotes and F.Remotes.Fusery
    if type(bag) == "table" then
        return bag
    end
    bag = F.Network and F.Network.Fusery
    if type(bag) == "table" then
        return bag
    end
    return nil
end

function F.invokeInst(inst, ...)
    if typeof(inst) ~= "Instance" or type(inst.InvokeServer) ~= "function" then
        return false, nil, nil, nil
    end
    local args = { ... }
    local ok, r1, r2, r3 = pcall(function()
        return inst:InvokeServer(table.unpack(args))
    end)
    if not ok then
        return false, nil, nil, nil
    end
    return true, r1, r2, r3
end

function F.invokeNamed(name, ...)
    local net = F.Network
    if type(net) ~= "table" or type(net.Invoke) ~= "function" then
        return false, nil, nil, nil
    end
    local ok, r1, r2, r3 = pcall(net.Invoke, name, ...)
    if not ok then
        return false, nil, nil, nil
    end
    return true, r1, r2, r3
end

function F.callFuse(method, named, ...)
    local bag = F.fusery()
    local called, a, b, c = F.invokeInst(bag and bag[method], ...)
    if not called then
        called, a, b, c = F.invokeNamed(named, ...)
    end
    if not called then
        return false, "no remote"
    end
    if type(a) == "table" then
        return a[1] == true, a[2], a[3]
    end
    return a == true, b, c
end

function F.loadPet(uid)
    return F.callFuse("LoadPet", "FuseMachine: InsertMob", uid)
end

function F.ejectPet(uid)
    return F.callFuse("EjectPet", "FuseMachine: RemoveMob", uid)
end

function F.beginFuse()
    return F.callFuse("BeginFuse", "FuseMachine: StartFuse")
end

function F.finishReveal()
    return F.callFuse("FinishReveal", "FuseMachine: CompleteReveal")
end

function F.confirmBriefing()
    F.callFuse("ConfirmBriefing", "FuseMachine: AcknowledgeInfo")
end

function F.machinePart()
    local objects = Workspace:FindFirstChild("__OBJECTS")
    local machines = objects and objects:FindFirstChild("Machines")
    local model = machines and machines:FindFirstChild("FuseMachine")
    if not model then
        return nil
    end
    local part = model:FindFirstChild("Machine")
    if part and part:IsA("BasePart") then
        return part
    end
    if model.PrimaryPart then
        return model.PrimaryPart
    end
    return model:FindFirstChildWhichIsA("BasePart", true)
end

function F.nearMachine()
    local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    local part = F.machinePart()
    if not hrp or not part then
        return false
    end
    local d = hrp.Position - part.Position
    return Vector3.new(d.X, 0, d.Z).Magnitude <= CFG.near
end

function F.moveMod()
    local loaded = G.StealEggLoaded
    if type(loaded) == "table" and type(loaded.Move) == "table" then
        return loaded.Move
    end
    return G.StealEggMove
end

function F.goMachine(shouldRun)
    if F.nearMachine() then
        return true
    end
    local part = F.machinePart()
    if not part then
        return false
    end
    local move = F.moveMod()
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Hold) == "function" then
        if d.Hold("fuse") ~= true then
            return F.nearMachine()
        end
    end
    if type(move) == "table" and type(move.GoTo) == "function" then
        pcall(move.GoTo, part.CFrame, {
            reason = "fuse",
            shouldRun = shouldRun,
            owner = "fuse",
        })
    end
    if type(d) == "table" and type(d.Release) == "function" then
        pcall(d.Release, "fuse")
    end
    return F.nearMachine()
end

function F.needsCloser(err)
    err = string.lower(tostring(err or ""))
    if err == "" then
        return false
    end
    return string.find(err, "clos", 1, true)
        or string.find(err, "far", 1, true)
        or string.find(err, "near", 1, true)
        or string.find(err, "distance", 1, true)
        or string.find(err, "machine", 1, true)
        or string.find(err, "prompt", 1, true)
        or string.find(err, "area", 1, true)
end

function F.otherBusy()
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.isStealBlocking) == "function" then
        local ok, hold = pcall(wild.isStealBlocking)
        if ok and hold == true then
            return true, "steal"
        end
    end
    local d = G.StealEggDispatch
    if type(d) == "table" and type(d.Owner) == "function" then
        local who = d.Owner()
        if who == "steal" or who == "claim" or who == "place" then
            return true, who
        end
    end
    local sell = G.StealEggSell
    if type(sell) == "table" then
        if type(sell.pet) == "table" and sell.pet._busy == true then
            return true, "sell"
        end
    end
    return false
end

function F.collectPets(data)
    local out = {}
    local inv = type(data) == "table" and data.Inventory
    if type(inv) ~= "table" then
        return out
    end
    local slotSet = {}
    for _, uid in ipairs(F.slotUids(data)) do
        slotSet[uid] = true
    end
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        local item = F.deserializePet(raw)
        if type(item) == "table" and item.IsFavorite ~= true then
            local category = tostring(item.Category or "")
            -- Pet bahan resep Rift disisihkan: kalau ikut di-fuse, rantai tukar
            -- Auto Rift kehilangan bahannya tepat sebelum setor.
            local riftHold = false
            local rift = G.StealEggRift
            if type(rift) == "table" and type(rift.shouldKeepPet) == "function" then
                local okr, keep = pcall(rift.shouldKeepPet, uid, category)
                riftHold = okr == true and keep == true
            end
            if category ~= "" and not riftHold and not F.cannotFuse(category) and not F.isEquipped(uid, data) then
                if item.InFuse == true and not slotSet[uid] then
                    -- already in another fuse bag
                else
                    local rate = F.itemRate(item, data)
                    local scale = tonumber(item.Scale) or 0
                    out[#out + 1] = {
                        uid = uid,
                        category = category,
                        name = F.displayOf(category),
                        scale = scale,
                        size = F.sizeKey(scale),
                        kg = F.itemKg(category, scale),
                        rate = rate,
                        price = F.itemPrice(item, rate),
                        muts = F.mutationNames(item),
                        inSlot = slotSet[uid] == true,
                    }
                end
            end
        end
    end
    return out
end

function F.betterThan(a, b)
    local as, bs = tonumber(a.scale) or 0, tonumber(b.scale) or 0
    if as ~= bs then
        return as > bs
    end
    local ak, bk = tonumber(a.kg) or 0, tonumber(b.kg) or 0
    if ak ~= bk then
        return ak > bk
    end
    local ar, br = tonumber(a.rate) or 0, tonumber(b.rate) or 0
    if ar ~= br then
        return ar > br
    end
    return (tonumber(a.price) or 0) > (tonumber(b.price) or 0)
end

function F.pickBatch(data)
    local rules = F.enabledRules()
    if #rules == 0 then
        return nil, "set rules"
    end
    local pets = F.collectPets(data)
    local groups = {}
    for _, rec in ipairs(pets) do
        local rule = F.firstRule(rec)
        if rule then
            local key = tostring(rule.id) .. ":" .. rec.category
            local g = groups[key]
            if not g then
                g = { category = rec.category, rule = rule, pets = {} }
                groups[key] = g
            end
            g.pets[#g.pets + 1] = rec
        end
    end
    local best
    for _, g in pairs(groups) do
        table.sort(g.pets, function(a, b)
            if F.betterThan(a, b) then
                return true
            end
            if F.betterThan(b, a) then
                return false
            end
            return tostring(a.uid) < tostring(b.uid)
        end)
        -- Keep = sisakan pet terbaik, tapi jangan sampai 3 bahan fuse gagal.
        -- keep=1 + 3 ekor dulu nge-block (sisa 2). Fuse 3 terlemah, keep sisanya.
        local keepWant = F.clampKeep(g.rule.keep)
        local canKeep = math.max(0, #g.pets - CFG.slots)
        local keep = math.min(keepWant, canKeep)
        local rest = {}
        for i = keep + 1, #g.pets do
            rest[#rest + 1] = g.pets[i]
        end
        if #rest >= CFG.slots then
            table.sort(rest, function(a, b)
                if F.betterThan(a, b) then
                    return false
                end
                if F.betterThan(b, a) then
                    return true
                end
                return tostring(a.uid) < tostring(b.uid)
            end)
            g.rest = rest
            if not best or #rest > #best.rest then
                best = g
            end
        end
    end
    if not best then
        return nil, "no match"
    end
    local batch = {}
    for i = 1, CFG.slots do
        batch[i] = best.rest[i]
    end
    return {
        category = best.category,
        name = F.displayOf(best.category),
        pets = batch,
        keep = F.clampKeep(best.rule.keep),
    }
end

function F.wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

function F.fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    if abs >= 1e12 then
        return string.format("%.1fT", n / 1e12)
    end
    if abs >= 1e9 then
        return string.format("%.1fB", n / 1e9)
    end
    if abs >= 1e6 then
        return string.format("%.1fM", n / 1e6)
    end
    if abs >= 1e3 then
        return string.format("%.1fK", n / 1e3)
    end
    if abs >= 10 then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

function F.fmtKg(n)
    return F.fmtNum(n) .. "kg"
end

function F.rarityName(key)
    for _, item in ipairs(Core.RARITY_ITEMS or {}) do
        if tostring(item.key) == tostring(key) then
            return tostring(item.name or key)
        end
    end
    return tostring(key)
end

function F.joinNames(keys, lookup)
    local names = {}
    for i, key in ipairs(keys) do
        names[i] = lookup and lookup(key) or key
    end
    return table.concat(names, ", ")
end

function F.formatRule(rule)
    rule = F.sanitizeRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    add("keep " .. tostring(rule.keep or CFG.keepDefault), "default")
    local nameKeys = F.mapKeyList(rule.names)
    local rarityKeys = F.mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = F.mapKeyList(rule.mutations)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            name = #nameKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = price > 0,
            mutation = #mutKeys > 0,
        }
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(F.joinNames(rarityKeys, F.rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.name then
        if #nameKeys == 0 then
            add("All pets", "fruit")
        elseif #nameKeys > 2 then
            add(tostring(#nameKeys) .. " pets", "fruit")
        else
            add(F.joinNames(nameKeys, F.displayOf), "fruit")
        end
    end
    if fields.kg then
        if kg > 0 then
            add((rule.kgMode == "above" and "above " or "below ") .. F.fmtKg(kg), "kg")
        else
            add("Any kg", "kg")
        end
    end
    if fields.price then
        if price > 0 then
            add((rule.priceMode == "above" and "above $" or "below $") .. F.fmtNum(price), "price")
        else
            add("Any $", "price")
        end
    end
    if fields.rate then
        if rate > 0 then
            add((rule.rateMode == "above" and "above " or "below ") .. F.fmtNum(rate) .. "/s", "price")
        else
            add("Any earn", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            add("Any mut", "mut")
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = F.isNoMutationKey(key) and "Normal" or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

function F.idleDetail()
    if #F.enabledRules() == 0 then
        return "set rules"
    end
    return "fused " .. tostring(M._fused)
end

function F.stillOn()
    return M.enabled == true and G.__StealEggFuseGen == GEN
end

function F.alignSlots(data, batch)
    local want = {}
    for _, rec in ipairs(batch.pets) do
        want[rec.uid] = rec
    end
    for _, uid in ipairs(F.slotUids(data)) do
        if not want[uid] then
            F.emit("Clear", "live", F.slotCount(data) .. "/" .. CFG.slots)
            F.ejectPet(uid)
            task.wait(0.08)
        end
    end
    data = F.getSave() or data
    local have = {}
    for _, uid in ipairs(F.slotUids(data)) do
        have[uid] = true
    end
    for _, rec in ipairs(batch.pets) do
        if not have[rec.uid] then
            F.emit("Load", "live", (F.slotCount(data) + 1) .. "/" .. CFG.slots)
            local ok, err = F.loadPet(rec.uid)
            if not ok then
                return false, tostring(err or "load failed")
            end
            task.wait(0.08)
            data = F.getSave() or data
        end
    end
    return F.slotCount(F.getSave() or data) >= CFG.slots
end

function F.step()
    F.bind()
    local data = F.getSave()
    if type(data) ~= "table" then
        F.emit("Wait", "warn", "no save")
        return
    end
    if data.FusionEggReward ~= false and data.FusionEggReward ~= nil then
        F.emit("Claim", "live", "egg")
        local ok = F.finishReveal()
        if ok then
            M._fused += 1
            F.emit("Fused", "success", "total " .. tostring(M._fused))
        else
            F.emit("Wait", "warn", "claim egg")
        end
        return
    end
    if data.FusionLocked == true then
        F.emit("Wait", "warn", "locked")
        return
    end
    if F.eggCount(data) >= F.eggMax() then
        F.emit("Wait", "warn", "egg full")
        return
    end
    local batch, why = F.pickBatch(data)
    if not batch then
        F.emit("Idle", "muted", why or F.idleDetail())
        return
    end
    local n = F.slotCount(data)
    F.emit("Load", "live", n .. "/" .. CFG.slots)
    local aligned, err = F.alignSlots(data, batch)
    if not aligned and F.needsCloser(err) then
        F.emit("Going", "live", "machine")
        if F.goMachine(F.stillOn) and F.stillOn() then
            aligned, err = F.alignSlots(F.getSave() or data, batch)
        end
    end
    if not aligned then
        F.emit("Wait", "warn", tostring(err or "slots"))
        return
    end
    if not F.stillOn() then
        return
    end
    data = F.getSave() or data
    F.emit("Fuse", "live", batch.name)
    local ok, err2, egg = F.beginFuse()
    if not ok and F.needsCloser(err2) then
        F.emit("Going", "live", "machine")
        if F.goMachine(F.stillOn) and F.stillOn() then
            ok, err2, egg = F.beginFuse()
        end
    end
    if not ok then
        F.emit("Wait", "warn", tostring(err2 or "fuse"))
        return
    end
    task.wait(0.2)
    local granted = F.finishReveal()
    if granted or egg then
        M._fused += 1
        F.emit("Fused", "success", batch.name)
    else
        F.emit("Wait", "warn", "reveal")
    end
end

function F.loop(token)
    F.confirmBriefing()
    while M.enabled == true and M._token == token and G.__StealEggFuseGen == GEN do
        local busy, why = F.otherBusy()
        if busy then
            F.emit("Wait", "warn", tostring(why or "busy"))
            task.wait(0.4)
        else
            M._busy = true
            local ok, err = pcall(F.step)
            M._busy = false
            if not ok then
                F.emit("Failed", "error", tostring(err))
            end
            if M.enabled ~= true or M._token ~= token then
                break
            end
            local d = tonumber(M.delay) or CFG.delayDefault
            if d < CFG.delayMin then
                d = CFG.delayMin
            elseif d > CFG.delayMax then
                d = CFG.delayMax
            end
            task.wait(d)
        end
    end
end

function M.setRules(list)
    M.rules = F.sanitizeRules(list)
    return M.rules
end

function M.setEnabled(on)
    on = on == true
    if on then
        if M.enabled == true and M._loopOn == true then
            return
        end
        M.enabled = true
        M._token = (tonumber(M._token) or 0) + 1
        local token = M._token
        M._loopOn = true
        F.emit("On", "live", F.idleDetail())
        task.spawn(function()
            F.loop(token)
            if M._token == token then
                M._loopOn = false
                if M.enabled ~= true then
                    F.emit("Idle", "muted", "off")
                end
            end
        end)
        return
    end
    M.enabled = false
    M._loopOn = false
    M._token = (tonumber(M._token) or 0) + 1
    F.emit("Idle", "muted", "off")
end

function M.Stop()
    M.setEnabled(false)
end

function M.listPetItems()
    F.bind()
    local seen, items = {}, {}
    local function add(category)
        category = tostring(category or "")
        if category == "" or seen[category] or F.cannotFuse(category) then
            return
        end
        seen[category] = true
        local num, rarityId, name = F.rarityOf(category)
        local label = name
        if rarityId ~= "" then
            label = name .. " · " .. rarityId
        elseif num > 0 then
            label = name .. " · " .. tostring(num)
        end
        items[#items + 1] = { key = category, name = label, sort = num }
    end
    local data = F.getSave()
    if type(data) == "table" and type(data.Inventory) == "table" then
        for _, raw in pairs(data.Inventory) do
            local item = F.deserializePet(raw)
            if type(item) == "table" then
                add(item.Category)
            end
        end
    end
    local catItems = Core.listEggItems and Core.listEggItems()
    if type(catItems) == "table" then
        for _, egg in ipairs(catItems) do
            add(egg.key)
        end
    end
    table.sort(items, function(a, b)
        if a.sort == b.sort then
            return tostring(a.name) < tostring(b.name)
        end
        return (tonumber(a.sort) or 0) < (tonumber(b.sort) or 0)
    end)
    return items
end

function M.listMutationItems()
    F.bind()
    local items, seen = {}, {}
    local function add(name, label)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        items[#items + 1] = { key = name, name = tostring(label or name) }
    end
    local Mutations = F.Mutations
    if type(Mutations) == "table" then
        local listFn = Mutations.GetMutations or Mutations.All
        if type(listFn) == "function" then
            local ok, list = pcall(listFn)
            if ok and type(list) == "table" then
                for key, info in pairs(list) do
                    if type(info) == "table" then
                        add(info.Name or info.Id or info._id or key, info.Label or info.DisplayOverride or info.Name or key)
                    elseif type(key) == "string" then
                        add(key, key)
                    end
                end
            end
        end
    end
    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    table.insert(items, 1, { key = NO_MUTATION, name = NO_MUTATION })
    return items
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    if type(values["steal.gear.fuse.rules"]) == "table" then
        M.setRules(values["steal.gear.fuse.rules"])
    end
    if values["steal.gear.fuse.draft.rarity"] ~= nil then
        M.draft.rarities = F.copyMap(values["steal.gear.fuse.draft.rarity"])
    end
    if values["steal.gear.fuse.draft.names"] ~= nil then
        M.draft.names = F.copyMap(values["steal.gear.fuse.draft.names"])
    end
    if values["steal.gear.fuse.draft.mutations"] ~= nil then
        M.draft.mutations = F.copyMap(values["steal.gear.fuse.draft.mutations"])
    end
    local sizes = values["steal.gear.fuse.sizes"]
    if sizes == nil then
        sizes = values["steal.gear.fuse.draft.sizes"]
    end
    if sizes ~= nil then
        M.sizes = F.copyMap(sizes)
        if not F.mapHas(M.sizes) then
            M.sizes = { normal = true }
        end
    end
    if values["steal.gear.fuse.draft.kgRule"] ~= nil then
        local kg, kgMode, kgRule = F.parseSignedRule(values["steal.gear.fuse.draft.kgRule"], values["steal.gear.fuse.draft.kgMode"])
        M.draft.kgRule = kgRule
        M.draft.kgMode = F.clampCompareMode(values["steal.gear.fuse.draft.kgMode"] or kgMode, CFG.compare)
    elseif values["steal.gear.fuse.draft.kgMode"] ~= nil then
        M.draft.kgMode = F.clampCompareMode(values["steal.gear.fuse.draft.kgMode"], CFG.compare)
    end
    if values["steal.gear.fuse.draft.rateRule"] ~= nil then
        local rate, rateMode, rateRule = F.parseSignedScaledRule(values["steal.gear.fuse.draft.rateRule"], values["steal.gear.fuse.draft.rateMode"])
        M.draft.rateRule = rateRule
        M.draft.rateMode = F.clampCompareMode(values["steal.gear.fuse.draft.rateMode"] or rateMode, CFG.compare)
    elseif values["steal.gear.fuse.draft.rateMode"] ~= nil then
        M.draft.rateMode = F.clampCompareMode(values["steal.gear.fuse.draft.rateMode"], CFG.compare)
    end
    if values["steal.gear.fuse.draft.priceRule"] ~= nil then
        local price, priceMode, priceRule = F.parseSignedScaledRule(values["steal.gear.fuse.draft.priceRule"], values["steal.gear.fuse.draft.priceMode"])
        M.draft.priceRule = priceRule
        M.draft.priceMode = F.clampCompareMode(values["steal.gear.fuse.draft.priceMode"] or priceMode, CFG.compare)
    elseif values["steal.gear.fuse.draft.priceMode"] ~= nil then
        M.draft.priceMode = F.clampCompareMode(values["steal.gear.fuse.draft.priceMode"], CFG.compare)
    end
    if values["steal.gear.fuse.draft.keep"] ~= nil then
        M.draft.keep = F.clampKeep(values["steal.gear.fuse.draft.keep"])
    end
    local delay = tonumber(values["steal.gear.fuse.delay"])
    if delay then
        M.delay = math.clamp(delay, CFG.delayMin, CFG.delayMax)
    end
    if values["steal.gear.fuse.enabled"] ~= nil then
        M.setEnabled(Core.flagOn(values["steal.gear.fuse.enabled"]))
    end
end

