-- Export
----------------------------------------------------------------
local G = (getgenv and getgenv()) or _G
G.AutoHopServer = M
G.AutoHopServerModule = M
G.StealEggAutoHop = M
_G.AutoHopServer = M
_G.AutoHopServerModule = M

return M
 end,      required = true },
    { key = "Rejoin",    name = "Rejoin",        factory = function() -- Rejoin current server + Auto Hop Player + Auto Hop Server (No Egg).

local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local HttpService = game:GetService("HttpService")
local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G

local Core = G.StealEggCore

G.__StealEggNoEggHopGen = (tonumber(G.__StealEggNoEggHopGen) or 0) + 1
local GEN = G.__StealEggNoEggHopGen

local WAIT_MIN, WAIT_MAX, WAIT_DEFAULT = 3, 60, 8
local VISITED_MAX = 20
local AVOID_WINDOW_SEC = 15
local AVOID_MAX = 200
local AVOID_SHARE_NAME = "avoid_users.json"
local TARGET_ITEMS = {
    { key = "quiet", name = "Quiet" },
    { key = "busy", name = "Busy" },
}

local M = {
    _busy = false,
    noEgg = false,
    waitSec = WAIT_DEFAULT,
    target = "quiet",
    _token = 0,
    _loopOn = false,
    _status = { text = "Off", style = "muted", detail = "—" },
    _onStatus = nil,
    avoidUsers = {},
    avoidOn = false,
    _avoidToken = 0,
    _avoidLoopOn = false,
    _avoidJobs = nil,
    _avoidStatus = { text = "Off", style = "muted", detail = "—" },
    _onAvoidStatus = nil,
}

local prev = G.StealEggRejoin
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev.noEgg = false
        prev._token = (tonumber(prev._token) or 0) + 999
        prev._loopOn = false
        prev.avoidOn = false
        prev._avoidToken = (tonumber(prev._avoidToken) or 0) + 999
        prev._avoidLoopOn = false
    end)
end
G.StealEggRejoin = M

local function hopMod()
    local hop = G.StealEggAutoHop or G.AutoHopServer
    if type(hop) == "table" then
        return hop
    end
    return nil
end

local function clampInt(v, lo, hi, fallback)
    local n = tonumber(v)
    if n == nil then
        return fallback
    end
    n = math.floor(n + 0.5)
    if n < lo then
        n = lo
    end
    if n > hi then
        n = hi
    end
    return n
end

local function flagOn(v)
    if type(Core) == "table" and type(Core.flagOn) == "function" then
        return Core.flagOn(v)
    end
    return v == true or v == 1 or tostring(v) == "true"
end

local function dropdownKey(a, b)
    if type(Core) == "table" and type(Core.dropdownValue) == "function" then
        return tostring(Core.dropdownValue(a, b) or "")
    end
    if a == "single" or a == "multi" then
        return tostring(b or "")
    end
    return tostring(b or a or "")
end

local function clampTarget(v)
    if type(v) == "table" then
        if v.busy == true or v.Busy == true or v[2] == true then
            return "busy"
        end
        if v.quiet == true or v.Quiet == true or v[1] == true then
            return "quiet"
        end
        for k, on in pairs(v) do
            if on == true or on == 1 or on == "true" then
                v = k
                break
            end
        end
    end
    v = string.lower(tostring(dropdownKey(v) or v or ""))
    if v == "busy" or v == "ramai" or v == "most" or v == "full" then
        return "busy"
    end
    return "quiet"
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Off"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

local function emitAvoid(text, style, detail)
    M._avoidStatus = {
        text = tostring(text or "Off"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onAvoidStatus
    if type(fn) == "function" then
        pcall(fn, M._avoidStatus)
    end
end

function M.setAvoidStatusListener(fn)
    M._onAvoidStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._avoidStatus)
    end
end

----------------------------------------------------------------
-- Visited JobIds (max 20, then wipe)
----------------------------------------------------------------
local FS_OK = (type(readfile) == "function" and type(writefile) == "function" and type(isfile) == "function")

local function saveDir()
    local dir = G.__StealEggSaveDir
    if type(dir) == "string" and dir ~= "" then
        return dir
    end
    return "NodeStealEgg"
end

local function ensureFolder(path)
    if type(makefolder) ~= "function" then
        return
    end
    if type(isfolder) == "function" and isfolder(path) then
        return
    end
    local parts = {}
    for seg in tostring(path):gmatch("[^/]+") do
        parts[#parts + 1] = seg
        local p = table.concat(parts, "/")
        if type(isfolder) ~= "function" or not isfolder(p) then
            pcall(function()
                makefolder(p)
            end)
        end
    end
end

local function playerFile(suffix)
    local name = tostring((LP and LP.Name) or "player")
    name = name:gsub("[^%w%-_.]", "_"):gsub("_+", "_")
    if name == "" or name == "_" then
        name = "player"
    end
    return saveDir() .. "/" .. name:sub(1, 48) .. suffix
end

local function visitedFile()
    return playerFile("_hop_noegg.json")
end

local function avoidFile()
    return playerFile("_hop_avoid.json")
end

local function decodeJson(s)
    local ok, t = pcall(function()
        return HttpService:JSONDecode(s)
    end)
    if ok and type(t) == "table" then
        return t
    end
    return nil
end

local function encodeJson(t)
    local ok, s = pcall(function()
        return HttpService:JSONEncode(t)
    end)
    if ok and type(s) == "string" then
        return s
    end
    return nil
end

local function loadJobs(path, maxN)
    local placeId = tonumber(game.PlaceId) or 0
    local jobs = {}
    if not FS_OK or not isfile(path) then
        return jobs, placeId
    end
    local ok, raw = pcall(readfile, path)
    if not ok or type(raw) ~= "string" or raw == "" then
        return jobs, placeId
    end
    local rec = decodeJson(raw)
    if type(rec) ~= "table" then
        return jobs, placeId
    end
    local savedPlace = tonumber(rec.placeId) or tonumber(rec.PlaceId) or 0
    if savedPlace ~= 0 and placeId ~= 0 and savedPlace ~= placeId then
        return jobs, placeId
    end
    local arr = rec.jobs or rec.jobIds or rec.visited
    if type(arr) ~= "table" then
        return jobs, placeId
    end
    local seen = {}
    for _, id in ipairs(arr) do
        id = tostring(id or "")
        if id ~= "" and not seen[id] then
            seen[id] = true
            jobs[#jobs + 1] = id
            if #jobs >= maxN then
                break
            end
        end
    end
    return jobs, placeId
end

local function saveJobs(path, jobs, placeId)
    if not FS_OK then
        return
    end
    ensureFolder(saveDir())
    local payload = encodeJson({
        placeId = tonumber(placeId) or tonumber(game.PlaceId) or 0,
        jobs = jobs or {},
    })
    if not payload then
        return
    end
    pcall(writefile, path, payload)
end

local function loadVisited()
    return loadJobs(visitedFile(), VISITED_MAX)
end

local function saveVisited(jobs, placeId)
    saveJobs(visitedFile(), jobs, placeId)
end

local function clearVisited()
    saveVisited({}, tonumber(game.PlaceId) or 0)
end

local function pushVisited(jobId)
    jobId = tostring(jobId or "")
    if jobId == "" then
        return loadVisited()
    end
    local jobs, placeId = loadVisited()
    for _, id in ipairs(jobs) do
        if id == jobId then
            return jobs, placeId
        end
    end
    if #jobs >= VISITED_MAX then
        jobs = {}
    end
    jobs[#jobs + 1] = jobId
    saveVisited(jobs, placeId)
    return jobs, placeId
end

----------------------------------------------------------------
-- Avoid-username JobIds: scratch memory for one search run.
-- Grows while we keep landing on occupied servers, wiped on success.
----------------------------------------------------------------
local function loadAvoidJobs()
    if FS_OK then
        return loadJobs(avoidFile(), AVOID_MAX)
    end
    local placeId = tonumber(game.PlaceId) or 0
    local cached = M._avoidJobs
    local jobs = {}
    if type(cached) ~= "table" or (tonumber(cached.placeId) or 0) ~= placeId then
        return jobs, placeId
    end
    for _, id in ipairs(cached.jobs or {}) do
        jobs[#jobs + 1] = tostring(id)
    end
    return jobs, placeId
end

local function saveAvoidJobs(jobs, placeId)
    placeId = tonumber(placeId) or tonumber(game.PlaceId) or 0
    M._avoidJobs = { placeId = placeId, jobs = jobs or {} }
    saveJobs(avoidFile(), jobs, placeId)
end

local function clearAvoidJobs()
    saveAvoidJobs({}, tonumber(game.PlaceId) or 0)
end

local function pushAvoidJob(jobId)
    jobId = tostring(jobId or "")
    if jobId == "" then
        return loadAvoidJobs()
    end
    local jobs, placeId = loadAvoidJobs()
    for _, id in ipairs(jobs) do
        if id == jobId then
            return jobs, placeId
        end
    end
    jobs[#jobs + 1] = jobId
    while #jobs > AVOID_MAX do
        table.remove(jobs, 1)
    end
    saveAvoidJobs(jobs, placeId)
    return jobs, placeId
end

----------------------------------------------------------------
-- Avoid-username list
----------------------------------------------------------------
local avoidSet = {}

local function normalizeName(v)
    local s = tostring(v or ""):gsub("[^%w_]", "")
    return string.lower(s)
end

local function shareFile()
    return saveDir() .. "/" .. AVOID_SHARE_NAME
end

local function loadShareNames()
    local out = {}
    if not FS_OK or not isfile(shareFile()) then
        return out
    end
    local ok, raw = pcall(readfile, shareFile())
    if not ok or type(raw) ~= "string" or raw == "" then
        return out
    end
    local rec = decodeJson(raw)
    if type(rec) ~= "table" then
        return out
    end
    local arr = rec
    if type(rec.users) == "table" then
        arr = rec.users
    elseif type(rec.names) == "table" then
        arr = rec.names
    end
    local seen = {}
    for _, v in ipairs(arr) do
        local name = normalizeName(v)
        if name ~= "" and not seen[name] then
            seen[name] = true
            out[#out + 1] = name
        end
    end
    return out
end

local function rebuildAvoidSet()
    local set = {}
    local me = normalizeName((LP and LP.Name) or "")
    for _, item in ipairs(M.avoidUsers) do
        if type(item) == "table" and item.enabled ~= false then
            local name = normalizeName(item.name or item.id or "")
            if name ~= "" and name ~= me then
                set[name] = true
            end
        end
    end
    for _, name in ipairs(loadShareNames()) do
        if name ~= me then
            set[name] = true
        end
    end
    avoidSet = set
end

local function avoidCount()
    local n = 0
    for _ in pairs(avoidSet) do
        n = n + 1
    end
    return n
end

-- Name match only. DisplayName is not unique and would trigger false hops.
local function firstAvoidMatch()
    local me = tostring((LP and LP.Name) or "")
    for _, pl in ipairs(Players:GetPlayers()) do
        local name = tostring(pl.Name or "")
        if name ~= me and avoidSet[normalizeName(name)] == true then
            return name
        end
    end
    return nil
end

function M.setAvoidUsers(list)
    local out = {}
    local seen = {}
    if type(list) == "table" then
        for _, item in ipairs(list) do
            local name, enabled
            if type(item) == "table" then
                name = normalizeName(item.name or item.username or item.user or item.text or item.id)
                enabled = item.enabled ~= false
            else
                name = normalizeName(item)
                enabled = true
            end
            if name ~= "" and not seen[name] then
                seen[name] = true
                out[#out + 1] = { id = name, enabled = enabled, name = name }
            end
        end
    end
    M.avoidUsers = out
    rebuildAvoidSet()
    return out
end

function M.formatAvoidUser(item)
    local name = ""
    local enabled = true
    if type(item) == "table" then
        name = tostring(item.name or item.id or "")
        enabled = item.enabled ~= false
    else
        name = tostring(item or "")
    end
    local parts = { { text = name, style = "zone" } }
    if name ~= "" and name == normalizeName((LP and LP.Name) or "") then
        parts[#parts + 1] = { text = "  (you)", style = "sep" }
    end
    return {
        id = name,
        enabled = enabled,
        parts = parts,
    }
end

----------------------------------------------------------------
-- Steal / hop helpers
----------------------------------------------------------------
local function stealOn()
    local wild = G.StealEggWild
    if type(wild) == "table" and wild.enabled == true then
        return true
    end
    return G.__StealEggWanted == true or G.__StealEggLoopOn == true
end

local function stealHold()
    local wild = G.StealEggWild
    if type(wild) == "table" and type(wild.shouldHoldHop) == "function" then
        local ok, hold, why, detail = pcall(wild.shouldHoldHop)
        if ok and hold == true then
            return true, tostring(why or "busy"), tostring(detail or why or "steal running")
        end
        return false
    end
    if G.__StealEggBusy == true or G.__StealEggClaiming == true then
        return true, "busy", "steal running"
    end
    return false
end

local function hopBusy()
    local hop = hopMod()
    if type(hop) ~= "table" or type(hop.GetStatus) ~= "function" then
        return false, false
    end
    local ok, st = pcall(hop.GetStatus, hop)
    if not ok or type(st) ~= "table" then
        return false, false
    end
    return st.sessionActive == true, st.inFlight == true
end

----------------------------------------------------------------
-- No-egg hop loop
----------------------------------------------------------------
local function startNoEggLoop()
    if M._loopOn then
        return
    end
    M._loopOn = true
    local token = M._token
    task.spawn(function()
        local emptySince = nil
        local lastFailAt = 0
        while GEN == G.__StealEggNoEggHopGen and token == M._token do
            local waitTick = 0.6
            if M.noEgg ~= true then
                emptySince = nil
                emit("Off", "muted", "—")
                break
            end

            local sessionOn, inFlight = hopBusy()
            if sessionOn then
                emptySince = nil
                emit(inFlight and "Teleporting" or "Hopping", "live", M.target == "busy" and "Busy" or "Quiet")
            elseif M.avoidOn == true then
                emptySince = nil
                emit("Paused", "muted", "avoid username")
            elseif stealOn() ~= true then
                emptySince = nil
                emit("Need steal", "warn", "—")
            else
                local hold, why, detail = stealHold()
                if hold then
                    emptySince = nil
                    if why == "eggs" then
                        emit("Egg found", "success", detail)
                    elseif why == "event" then
                        emit("Wait event", "warn", tostring(detail or "monster"))
                    elseif why == "sell" then
                        emit("Wait sell", "warn", "—")
                    elseif why == "place" then
                        emit("Wait place", "warn", "—")
                    elseif why == "carry" then
                        emit("Carrying", "live", "—")
                    elseif why == "boss" then
                        emit("Wait boss", "warn", tostring(detail or "boss"))
                    else
                        emit("Wait steal", "warn", "—")
                    end
                else
                    local waitSec = clampInt(M.waitSec, WAIT_MIN, WAIT_MAX, WAIT_DEFAULT)
                    if emptySince == nil then
                        emptySince = os.clock()
                    end
                    local left = math.ceil(waitSec - (os.clock() - emptySince))
                    if left > 0 then
                        emit("Wait " .. tostring(left) .. "s", "warn", M.target == "busy" and "Busy" or "Quiet")
                        waitTick = 0.4
                    elseif os.clock() - lastFailAt < 8 then
                        emit("Cooldown", "warn", "—")
                    else
                        local hop = hopMod()
                        if type(hop) ~= "table" or type(hop.ForceHopNow) ~= "function" then
                            emit("Missing", "error", "—")
                            waitTick = 1
                        else
                            local jobs = loadVisited()
                            emit("Hopping", "live", M.target == "busy" and "Busy" or "Quiet")
                            local ok, rs = hop.ForceHopNow("no_egg", {
                                allowDisabled = true,
                                preferMostPlayers = M.target == "busy",
                                preferLeastPlayers = M.target == "quiet",
                                extraVisited = jobs,
                                keepVisited = true,
                                maxCandidates = 12,
                            })
                            if ok then
                                pushVisited(tostring(game.JobId or ""))
                                emptySince = nil
                            else
                                lastFailAt = os.clock()
                                local err = string.lower(tostring(rs or ""))
                                if string.find(err, "no_candidates", 1, true) then
                                    clearVisited()
                                    emit("No server", "warn", "list cleared")
                                elseif string.find(err, "session_active", 1, true) then
                                    emit("Hopping", "live", "—")
                                elseif string.find(err, "cooldown", 1, true) then
                                    emit("Cooldown", "warn", "—")
                                else
                                    emit("Hop failed", "warn", "—")
                                end
                                emptySince = os.clock() - math.max(0, waitSec - 6)
                            end
                        end
                    end
                end
            end
            task.wait(waitTick)
        end
        if token == M._token then
            M._loopOn = false
        end
    end)
end

function M.setNoEgg(on)
    on = on == true
    local was = M.noEgg == true
    M.noEgg = on
    if on then
        if was ~= true or M._loopOn ~= true then
            M._token = (tonumber(M._token) or 0) + 1
            M._loopOn = false
            emit("On", "live", M.target == "busy" and "Busy" or "Quiet")
            startNoEggLoop()
        end
        return
    end
    if was then
        M._token = (tonumber(M._token) or 0) + 1
        M._loopOn = false
    end
    emit("Off", "muted", "—")
end

----------------------------------------------------------------
-- Avoid-username loop
----------------------------------------------------------------
local function startAvoidLoop()
    if M._avoidLoopOn then
        return
    end
    M._avoidLoopOn = true
    local token = M._avoidToken
    task.spawn(function()
        local jobId = nil
        local windowEnd = 0
        local settled = false
        local lastFailAt = nil
        local playerAddedConn = nil
        local function armPlayerWatch()
            if playerAddedConn then
                return
            end
            playerAddedConn = Players.PlayerAdded:Connect(function()
                -- Join belakangan / streaming: jangan stuck di Clear.
                if token == M._avoidToken and M.avoidOn == true then
                    settled = false
                    windowEnd = os.clock() + 3
                end
            end)
        end
        armPlayerWatch()
        while GEN == G.__StealEggNoEggHopGen and token == M._avoidToken do
            local waitTick = 0.5
            if M.avoidOn ~= true then
                emitAvoid("Off", "muted", "—")
                break
            end

            -- Fresh window on every server, so a surviving session stays correct too.
            local nowJob = tostring(game.JobId or "")
            if nowJob ~= jobId then
                jobId = nowJob
                windowEnd = os.clock() + AVOID_WINDOW_SEC
                settled = false
                lastFailAt = nil
            end

            local names = avoidCount()
            if names < 1 then
                emitAvoid("Empty", "warn", "no username")
                waitTick = 1.5
            else
                local found = firstAvoidMatch()
                local sessionOn, inFlight = hopBusy()
                if sessionOn then
                    -- Never settle mid-teleport; the list must survive the trip.
                    settled = false
                    emitAvoid(inFlight and "Teleporting" or "Hopping", "live", found or "—")
                    waitTick = 0.6
                elseif found ~= nil then
                    -- Masih ada / baru join setelah Clear: hop lagi.
                    -- Jangan cabut dari outbreak: ignoreStealHold hanya untuk steal,
                    -- bukan scramble.
                    settled = false
                    local eventHold = false
                    local scramble = G.StealEggScramble
                    if type(scramble) == "table" and type(scramble.shouldHoldHop) == "function" then
                        local okS, holdS = pcall(scramble.shouldHoldHop)
                        eventHold = okS == true and holdS == true
                    end
                    if eventHold ~= true then
                        local boss = G.StealEggBoss
                        if type(boss) == "table" and type(boss.shouldHoldHop) == "function" then
                            local okB, holdB = pcall(boss.shouldHoldHop)
                            eventHold = okB == true and holdB == true
                        end
                    end
                    if eventHold then
                        emitAvoid("Paused", "muted", "scramble")
                        waitTick = 0.8
                    elseif lastFailAt ~= nil and os.clock() - lastFailAt < 6 then
                        emitAvoid("Cooldown", "warn", found)
                        waitTick = 0.8
                    else
                        local hop = hopMod()
                        if type(hop) ~= "table" or type(hop.ForceHopNow) ~= "function" then
                            emitAvoid("Missing", "error", "—")
                            waitTick = 1
                        else
                            local jobs = pushAvoidJob(nowJob)
                            emitAvoid("Hopping", "live", found)
                            local ok, rs = hop.ForceHopNow("avoid_user", {
                                allowDisabled = true,
                                ignoreStealHold = true,
                                extraVisited = jobs,
                                keepVisited = true,
                                maxCandidates = 12,
                            })
                            if not ok then
                                lastFailAt = os.clock()
                                local err = string.lower(tostring(rs or ""))
                                if string.find(err, "no_candidates", 1, true) then
                                    -- Every candidate is already on the list; wipe or we deadlock.
                                    clearAvoidJobs()
                                    emitAvoid("No server", "warn", "list cleared")
                                elseif string.find(err, "session_active", 1, true) then
                                    emitAvoid("Hopping", "live", found)
                                elseif string.find(err, "cooldown", 1, true) then
                                    emitAvoid("Cooldown", "warn", found)
                                else
                                    emitAvoid("Hop failed", "warn", found)
                                end
                            end
                            waitTick = 0.8
                        end
                    end
                elseif settled then
                    emitAvoid("Clear", "muted", tostring(names) .. " watched")
                    waitTick = 1.2
                elseif os.clock() >= windowEnd then
                    settled = true
                    clearAvoidJobs()
                    emitAvoid("Clear", "muted", "server ok")
                    waitTick = 1.2
                else
                    local left = math.max(0, math.ceil(windowEnd - os.clock()))
                    emitAvoid("Scan " .. tostring(left) .. "s", "live", tostring(names) .. " watched")
                end
            end
            task.wait(waitTick)
        end
        if playerAddedConn then
            pcall(function()
                playerAddedConn:Disconnect()
            end)
            playerAddedConn = nil
        end
        if token == M._avoidToken then
            M._avoidLoopOn = false
        end
    end)
end

function M.setAvoidOn(on)
    on = on == true
    local was = M.avoidOn == true
    M.avoidOn = on
    G.__StealEggAvoidPause = on or nil
    if on then
        rebuildAvoidSet()
        -- Selalu pastikan loop hidup (bukan cuma saat toggle false→true).
        if M._avoidLoopOn ~= true then
            M._avoidToken = (tonumber(M._avoidToken) or 0) + 1
            emitAvoid("On", "live", tostring(avoidCount()) .. " watched")
            startAvoidLoop()
        elseif was ~= true then
            emitAvoid("On", "live", tostring(avoidCount()) .. " watched")
        end
        return
    end
    if was then
        M._avoidToken = (tonumber(M._avoidToken) or 0) + 1
        M._avoidLoopOn = false
        clearAvoidJobs()
    end
    emitAvoid("Off", "muted", "—")
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    -- Isi key hop/avoid yang belum ada saja — jangan timpa live ON dengan snapshot basi.
    local saved = G.__StealEggSavedConfig
    if type(saved) == "table" then
        for k, v in pairs(saved) do
            if type(k) == "string" and string.sub(k, 1, 9) == "misc.hop." and values[k] == nil then
                values[k] = v
            end
        end
    end
    local wait = tonumber(values["misc.hop.noegg.wait"])
    if wait then
        M.waitSec = clampInt(wait, WAIT_MIN, WAIT_MAX, M.waitSec)
    end
    local target = values["misc.hop.noegg.target"]
    if target ~= nil then
        M.target = clampTarget(dropdownKey(target))
    end
    if values["misc.hop.noegg.enabled"] ~= nil then
        M.setNoEgg(flagOn(values["misc.hop.noegg.enabled"]))
    end
    if type(values["misc.hop.avoid.users"]) == "table" then
        M.setAvoidUsers(values["misc.hop.avoid.users"])
    end
    if values["misc.hop.avoid.enabled"] ~= nil then
        M.setAvoidOn(flagOn(values["misc.hop.avoid.enabled"]))
    elseif M.avoidOn == true and M._avoidLoopOn ~= true then
        -- Enabled sudah true dari sesi sebelumnya / race: pastikan loop hidup.
        M.setAvoidOn(true)
    end
    local afk = G.StealEggAntiAfk or (G.StealEggLoaded and G.StealEggLoaded.AntiAfk)
    if type(afk) == "table" and type(afk.syncFrom) == "function" then
        pcall(afk.syncFrom, values)
    end
end

function M.bootFromSave(ui)
    local values = {}
    if type(ui) == "table" and type(ui.GetValues) == "function" then
        local ok, got = pcall(ui.GetValues, ui)
        if ok and type(got) == "table" then
            values = got
        end
    end
    M.syncFrom(values)
    local hop = hopMod()
    if type(hop) == "table" and type(hop.syncFrom) == "function" then
        pcall(hop.syncFrom, values)
    end
end

----------------------------------------------------------------
-- Rejoin now
----------------------------------------------------------------
function M.RejoinNow()
    if M._busy then
        return false, "busy"
    end
    M._busy = true
    G.__StealEggAllowTeleport = os.clock()

    local placeId = tonumber(game.PlaceId)
    local jobId = tostring(game.JobId or "")
    if not placeId or placeId <= 0 then
        M._busy = false
        return false, "place_id_invalid"
    end

    -- JobId ada: HANYA TeleportToPlaceInstance. Teleport(placeId) = server random.
    local ok, err
    if jobId ~= "" then
        ok, err = pcall(function()
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        end)
        if not ok then
            G.__StealEggAllowTeleport = os.clock()
            ok, err = pcall(function()
                TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
            end)
        end
    else
        ok, err = pcall(function()
            TeleportService:Teleport(placeId, LP)
        end)
    end

    if not ok then
        M._busy = false
        return false, tostring(err)
    end

    task.delay(8, function()
        M._busy = false
    end)
    return true
end

function M.Register(ui)
    ui:RegisterSubTab("misc", "rejoin", "Rejoin", function()
        ui:ClearSubContent()

        local pre = ui:GetValues() or {}
        M.syncFrom(pre)

        local bodyRejoin, _, statusApi = ui:CreateSection({
            title = "Rejoin",
            expanded = false,
