            style = "muted",
            },
        })
        local rejoinGroup = ui:CreateGroup(bodyRejoin)

        ui:CreateRowButton(rejoinGroup, {
            text = "Rejoin Now",
            kind = "primary",
            onClick = function()
                statusApi.set("Teleporting")
                statusApi.setStyle("live")
                local ok, err = M.RejoinNow()
                if ok then
                    statusApi.set("Sent")
                    statusApi.setStyle("success")
                    statusApi.setDetail("")
                else
                    statusApi.set("Failed")
                    statusApi.setStyle("error")
                    statusApi.setDetail("")
                end
            end,
        })

        local saved = ui:GetValues() or {}
