        if type(afk) == "table" and type(afk.IsReconnect) == "function" then
            reconnectOn = afk.IsReconnect() == true
        end
        if saved["misc.rejoin.reconnect"] ~= nil then
            reconnectOn = flagOn(saved["misc.rejoin.reconnect"])
        else
            local fileCfg = G.__StealEggSavedConfig
            if type(fileCfg) == "table" and fileCfg["misc.rejoin.reconnect"] ~= nil then
                reconnectOn = flagOn(fileCfg["misc.rejoin.reconnect"])
            end
        end

        ui:CreateRowToggle(rejoinGroup, {
            id = "misc.rejoin.reconnect",
