            hintText = "Semua prompt DC/kick: ErrorMessage, overlay CoreGui, kode 267/268/277–280/dll, shutdown server, prompt custom game. Bukan hop/leave yang kita sendiri (ClientInitiated / AFK teleport).",
            onChanged = function(on)
                local mod = G.StealEggAntiAfk or (G.StealEggLoaded and G.StealEggLoaded.AntiAfk)
                if type(mod) == "table" and type(mod.setReconnect) == "function" then
                    mod.setReconnect(on == true)
                end
            end,
        })
        if type(afk) == "table" and type(afk.setReconnect) == "function" then
            pcall(afk.setReconnect, reconnectOn)
        end

        local hop = hopMod()
        local hopCurrent = 1
        local hopMax = 1
        local hopDelay = 10
        local hopEnabled = false
        if hop then
            if type(hop.GetStatus) == "function" then
                local ok, st = pcall(hop.GetStatus, hop)
                if ok and type(st) == "table" then
                    hopCurrent = tonumber(st.currentMax) or hopCurrent
                    hopMax = tonumber(st.targetMax) or hopMax
                    hopDelay = tonumber(st.teleportDelay) or hopDelay
                end
            end
            hopEnabled = hop.IsRunning and hop:IsRunning() == true
            if G.AUTO_HOP_ENABLED == true then
                hopEnabled = true
            end
            hopCurrent = clampInt(G.AUTO_HOP_CURRENT_PLAYER or hopCurrent, 1, 7, hopCurrent)
            hopMax = clampInt(G.AUTO_HOP_MAX_PLAYER or hopMax, 1, 7, hopMax)
            hopDelay = clampInt(G.AUTO_HOP_TELEPORT_DELAY or hopDelay, 10, 600, hopDelay)
            if saved["misc.hop.current"] ~= nil then
                hopCurrent = clampInt(saved["misc.hop.current"], 1, 7, hopCurrent)
            end
            if saved["misc.hop.target"] ~= nil then
                hopMax = clampInt(saved["misc.hop.target"], 1, 7, hopMax)
            end
            if saved["misc.hop.delay"] ~= nil then
                hopDelay = clampInt(saved["misc.hop.delay"], 10, 600, hopDelay)
            end
            if saved["misc.hop.enabled"] ~= nil then
                hopEnabled = flagOn(saved["misc.hop.enabled"])
            end
        end

        local bodyHop, _, hopStatusApi = ui:CreateSection({
            title = "Auto Hop Player",
            expanded = false,
            status = {
                id = "misc.hop.status",
                persist = false,
                value = string.format("%s  %d/%d", hopEnabled and "On" or "Off", #Players:GetPlayers(), hopCurrent),
                style = hopEnabled and "live" or "muted",
            },
        })
        local hopGroup = ui:CreateGroup(bodyHop)

        local function applyHop()
            if not hop then
                return
            end
            if type(hop.SetCurrentPlayer) == "function" then
                pcall(hop.SetCurrentPlayer, hopCurrent)
            end
            if type(hop.SetMaxPlayer) == "function" then
                pcall(hop.SetMaxPlayer, hopMax)
            end
            if type(hop.SetTeleportDelay) == "function" then
                pcall(hop.SetTeleportDelay, hopDelay)
            end
            if type(hop.SetEnabled) == "function" then
                pcall(hop.SetEnabled, hopEnabled)
            end
        end

        ui:CreateRowInput(hopGroup, {
            id = "misc.hop.current",
            label = "Current Player Max",
            persist = true,
            initial = tostring(hopCurrent),
            clearOnFocus = false,
            onChanged = function(text)
                hopCurrent = clampInt(text, 1, 7, hopCurrent)
                applyHop()
            end,
        })

        ui:CreateRowInput(hopGroup, {
            id = "misc.hop.target",
            label = "Target Server Players",
            persist = true,
            initial = tostring(hopMax),
            clearOnFocus = false,
            onChanged = function(text)
                hopMax = clampInt(text, 1, 7, hopMax)
                applyHop()
            end,
        })

        ui:CreateRowInput(hopGroup, {
            id = "misc.hop.delay",
            label = "Hop Delay (sec)",
            persist = true,
            initial = tostring(hopDelay),
            clearOnFocus = false,
            onChanged = function(text)
                hopDelay = clampInt(text, 10, 600, hopDelay)
                applyHop()
            end,
        })

        ui:CreateRowToggle(hopGroup, {
            id = "misc.hop.enabled",
            label = "Enable Auto Hop",
            persist = true,
            initial = hopEnabled,
            onChanged = function(on)
                hopEnabled = on == true
                applyHop()
            end,
        })

        if not hop then
            hopStatusApi.set("Missing")
            hopStatusApi.setStyle("error")
            hopStatusApi.setDetail("")
        else
            applyHop()
            task.spawn(function()
                while hopStatusApi and bodyHop and bodyHop.Parent do
                    pcall(function()
                        local pc = #Players:GetPlayers()
                        if pc < 1 and Players.LocalPlayer then
                            pc = 1
                        end
                        local state = hopEnabled and "On" or "Off"
                        local style = hopEnabled and "live" or "muted"
                        if hopEnabled and type(hop.GetStatus) == "function" then
                            local ok, st = pcall(hop.GetStatus, hop)
                            if ok and type(st) == "table" then
                                pc = tonumber(st.playerCount) or pc
                                if pc < 1 then
                                    pc = 1
                                end
                                if st.inFlight == true then
                                    state = "Teleporting"
                                    style = "live"
                                elseif st.stealHold == true then
                                    state = tostring(st.stealHoldDetail or "Wait steal")
                                    style = "warn"
                                elseif st.sessionActive == true then
                                    state = "Hopping " .. tostring(st.candidateCount or 0)
                                    style = "live"
                                elseif (tonumber(st.delayRemaining) or 0) > 0 then
                                    state = string.format("Delay %ds", tonumber(st.delayRemaining) or 0)
                                    style = "warn"
                                elseif type(st.status) == "string" and st.status ~= "" and st.status ~= "idle" then
                                    state = st.status
                                    style = "warn"
                                else
                                    state = string.format("On %d/%d", pc, hopCurrent)
                                end
                            end
                        end
                        hopStatusApi.set(state)
                        hopStatusApi.setStyle(style)
                        hopStatusApi.setDetail("")
                    end)
                    task.wait(1)
                end
            end)
        end

        local bodyNoEgg, _, noEggStatusApi = ui:CreateSection({
            title = "Auto Hop Server (No Match Steal Rules)",
            expanded = false,
            status = {
                id = "misc.hop.noegg.status",
                persist = false,
                value = M._status.text,
                style = M._status.style,
                detail = M._status.detail,
            },
        })
        M.setStatusListener(function(st)
            noEggStatusApi.set(st.text)
            noEggStatusApi.setStyle(st.style)
            noEggStatusApi.setDetail(st.detail)
        end)

        local noEggGroup = ui:CreateGroup(bodyNoEgg)
        ui:CreateRowInput(noEggGroup, {
            id = "misc.hop.noegg.wait",
            label = "Wait · sec",
            persist = true,
            initial = tostring(M.waitSec or WAIT_DEFAULT),
            clearOnFocus = false,
            onChanged = function(text)
                M.waitSec = clampInt(text, WAIT_MIN, WAIT_MAX, M.waitSec)
            end,
        })
        ui:CreateRowDropdown(noEggGroup, {
            id = "misc.hop.noegg.target",
            label = "Target Server",
            persist = true,
            placeholder = "Quiet",
            hintText = "Quiet = sepi, Busy = ramai. Autosave langsung, tidak perlu pindah tab. Steal harus ON.",
            initial = M.target or "quiet",
            clearable = false,
            preserveItemOrder = true,
            getItems = function()
                return TARGET_ITEMS
            end,
            onChanged = function(a, b)
                local key = clampTarget(dropdownKey(a, b))
                M.target = key
            end,
        })
        ui:CreateRowToggle(noEggGroup, {
            id = "misc.hop.noegg.enabled",
            label = "Enable Auto Hop (If No Egg matching rules)",
            persist = true,
            initial = M.noEgg == true,
            onChanged = function(on)
                M.setNoEgg(on == true)
            end,
        })

        local avoidPre = ui:GetValues() or {}
        if type(avoidPre["misc.hop.avoid.users"]) == "table" then
            M.setAvoidUsers(avoidPre["misc.hop.avoid.users"])
        end

        local bodyAvoid, _, avoidStatusApi = ui:CreateSection({
            title = "Avoid Username (Same Server)",
            expanded = false,
            status = {
                id = "misc.hop.avoid.status",
                persist = false,
                value = M._avoidStatus.text,
                style = M._avoidStatus.style,
                detail = M._avoidStatus.detail,
            },
        })
        M.setAvoidStatusListener(function(st)
            avoidStatusApi.set(st.text)
            avoidStatusApi.setStyle(st.style)
            avoidStatusApi.setDetail(st.detail)
        end)

        local avoidApi
        local function persistAvoid()
            if avoidApi and type(avoidApi.set) == "function" then
                pcall(avoidApi.set, M.avoidUsers)
            end
        end

        local _, bindAvoid = ui:CreateRuleList(bodyAvoid, {
            id = "misc.hop.avoid.users",
            title = "Avoid List",
            searchPlaceholder = "Search username...",
            emptyText = "Belum ada username. Paste nama akun sendiri di bawah.",
            visibleRows = 6,
            persist = true,
            getItems = function()
                return M.avoidUsers
            end,
            formatItem = function(item)
                return M.formatAvoidUser(item)
            end,
            onLoad = function(list)
                M.setAvoidUsers(list)
            end,
            onToggle = function(item, enabled)
                local id = type(item) == "table" and tostring(item.id or "") or ""
                for _, row in ipairs(M.avoidUsers) do
                    if tostring(row.id) == id then
                        row.enabled = enabled == true
                        break
                    end
                end
                rebuildAvoidSet()
                persistAvoid()
            end,
            onDelete = function(item)
                local id = type(item) == "table" and tostring(item.id or "") or ""
                local nextList = {}
                for _, row in ipairs(M.avoidUsers) do
                    if tostring(row.id) ~= id then
                        nextList[#nextList + 1] = row
                    end
                end
                M.avoidUsers = nextList
                rebuildAvoidSet()
                persistAvoid()
            end,
        })
        avoidApi = bindAvoid

        local _, _, _, avoidAddApi = ui:CreateRowInput(bodyAvoid, {
            id = "misc.hop.avoid.add",
            label = "Add Username",
            persist = false,
            initial = "",
            clearOnFocus = false,
            hintText = "Bulk paste: pisah koma / spasi / newline. Nama sendiri diabaikan.",
        })

        local avoidGroup = ui:CreateGroup(bodyAvoid)

        local function mergeAvoidNames(names)
            local list = {}
            for _, row in ipairs(M.avoidUsers) do
                list[#list + 1] = row
            end
            for _, name in ipairs(names) do
                list[#list + 1] = name
            end
            local before = #M.avoidUsers
            M.setAvoidUsers(list)
            persistAvoid()
            return #M.avoidUsers - before
        end

        ui:CreateRowButton(avoidGroup, {
            text = "APPLY - Add Username",
            kind = "primary",
            onClick = function()
                local raw = ""
                if avoidAddApi and type(avoidAddApi.get) == "function" then
                    raw = tostring(avoidAddApi.get() or "")
                end
                local names = {}
                for token in raw:gmatch("[^,;%s]+") do
                    names[#names + 1] = token
                end
                mergeAvoidNames(names)
                if avoidAddApi and type(avoidAddApi.set) == "function" then
                    pcall(avoidAddApi.set, "", true)
                end
            end,
        })

        ui:CreateRowButton(avoidGroup, {
            text = "Import " .. AVOID_SHARE_NAME,
            onClick = function()
                mergeAvoidNames(loadShareNames())
            end,
        })

        ui:CreateRowToggle(avoidGroup, {
            id = "misc.hop.avoid.enabled",
            label = "Enable Avoid Username",
            persist = true,
            initial = M.avoidOn == true,
            onChanged = function(on)
                M.setAvoidOn(on == true)
            end,
        })

        M.syncFrom(ui:GetValues() or {})
    end, 1)

    -- Boot tanpa buka MISC: sync sekarang + retry (player list / save kadang telat).
    M.bootFromSave(ui)
    task.defer(function()
        M.bootFromSave(ui)
    end)
    task.delay(1.5, function()
        if GEN == G.__StealEggNoEggHopGen then
            M.bootFromSave(ui)
        end
    end)
end

return M
 end,        required = true },
    { key = "AntiAfk",   name = "Anti AFK",      factory = function() -- Anti AFK StealEgg — dump Game.AntiAFK + AfkProtection.
-- Dump Control: Idled p6>=60 → SubmitIdleState(true); p6>1080 → Teleport(placeId).
-- Dump Variant: max(os.clock-lastInput, Idled). <60 return; >=60 flag true;
--   1020 AskRescueHop; 1110 Teleport AfkRestore.
-- Reset dump (connectActivityInputs): InputBegan / MouseMovement / Touch / Gamepad
--   → markActive: os_clock_ret=now, u7=0, FireServer false. Bukan ClickButton2.

local Players = game:GetService("Players")
local GuiService = game:GetService("GuiService")
local TeleportService = game:GetService("TeleportService")
local UserInputService = game:GetService("UserInputService")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G

G.__StealEggAntiAfkGen = (tonumber(G.__StealEggAntiAfkGen) or 0) + 1
local GEN = G.__StealEggAntiAfkGen

local AFK_KEY = "AfkRestore"
local SCAN_SEC = 2
local PING_SEC = 8
local DC_RETRY_SEC = 12

local M = {
    _token = GEN,
    reconnect = true,
    _dcAt = 0,
    _lastWhy = nil,
    _lastSkip = nil,
    _ver = "hopfix11",
}

local prev = G.StealEggAntiAfk
if type(prev) == "table" and prev ~= M then
    pcall(function()
        prev._token = (tonumber(prev._token) or 0) + 999
        if prev.reconnect ~= nil then
            M.reconnect = prev.reconnect == true
        end
    end)
end
G.StealEggAntiAfk = M

G.__StealEggAntiAfkKeep = nil
G.__StealEggAntiAfkIdled = nil

local function alive()
    return G.StealEggAntiAfk == M and M._token == GEN
end

local function log(msg)
    local fn = G.StealEggDbg
    if type(fn) == "function" then
        pcall(fn, "ANTIAFK", msg)
    end
end

local function flagOn(v)
    local Core = G.StealEggCore
    if type(Core) == "table" and type(Core.flagOn) == "function" then
        return Core.flagOn(v) == true
    end
    return v == true or v == 1 or tostring(v) == "true"
end

local function isAfkData(data)
    return type(data) == "table" and data[AFK_KEY] == true
end

local function isBusy()
    if G.__StealEggBusy == true or G.__StealEggTpHold == true then
        return true
    end
    local wild = G.StealEggWildEgg or G.StealEggWild or (G.StealEggLoaded and G.StealEggLoaded.WildEgg)
    if type(wild) == "table" and type(wild.isCarrying) == "function" then
        local ok, carrying = pcall(wild.isCarrying)
        if ok and carrying == true then
            return true
        end
    end
    return false
end

local function ourHopFresh()
    local t = tonumber(G.__StealEggAllowTeleport)
    return t ~= nil and (os.clock() - t) < 10
end

local function softRejoin(kind)
    kind = tostring(kind or "")
    local placeId = tonumber(game.PlaceId) or 0
    if placeId <= 0 then
        return false
    end
    G.__StealEggAllowTeleport = os.clock()
    -- Server mati / experience ended: JobId lama sudah tidak ada.
    if kind == "shutdown" then
        local ok = pcall(function()
            TeleportService:Teleport(placeId, LP)
        end)
        return ok == true
    end
    local rj = G.StealEggRejoin or (G.StealEggLoaded and G.StealEggLoaded.Rejoin)
    if type(rj) == "table" and type(rj.RejoinNow) == "function" then
        local okCall, okRes = pcall(rj.RejoinNow)
        if okCall and okRes ~= false then
            return true
        end
    end
    local jobId = tostring(game.JobId or "")
    local ok = false
    if jobId ~= "" then
        ok = pcall(function()
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        end)
    end
    return ok == true
end

function M.setReconnect(on)
    M.reconnect = on == true
end

function M.IsReconnect()
    return M.reconnect == true
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local saved = G.__StealEggSavedConfig
    if type(saved) == "table" and saved["misc.rejoin.reconnect"] ~= nil then
        values["misc.rejoin.reconnect"] = saved["misc.rejoin.reconnect"]
    end
    if values["misc.rejoin.reconnect"] ~= nil then
        M.setReconnect(flagOn(values["misc.rejoin.reconnect"]))
    end
end

-- Hop/leave kita (ClientInitiated / AfkRestore) bukan DC.
-- Hanya teks kick / DC / shutdown sungguhan. Jangan sintetis "error code: N"
-- dari ErrorCode sembarang — itu yang bikin rejoin ~18 menit (AFK hop game).
local function dcVerdict(s)
    s = string.lower(tostring(s or ""))
    s = s:gsub("%s+", " ")
    if s == "" or s == "nil" then
        return false, "empty"
    end
    if string.find(s, "clientinitiated", 1, true)
        or string.find(s, "client initiated", 1, true)
        or string.find(s, "afkrestore", 1, true)
        or string.find(s, "isteleporting", 1, true)
        or string.find(s, "is teleporting", 1, true)
        or string.find(s, "previous teleport", 1, true)
        or string.find(s, "already teleporting", 1, true)
        or string.find(s, "teleport failed", 1, true)
        or string.find(s, "fetching save", 1, true)
    then
        return false, "ignore-init"
    end
    if string.find(s, "shutting down", 1, true)
        or string.find(s, "shut down", 1, true)
        or string.find(s, "server closed", 1, true)
        or string.find(s, "experience has ended", 1, true)
        or string.find(s, "experience ended", 1, true)
        or string.find(s, "this game has ended", 1, true)
        or string.find(s, "game has ended", 1, true)
        or string.find(s, "place has been closed", 1, true)
    then
        return true, "shutdown"
    end
    if string.find(s, "cheating", 1, true)
        or string.find(s, "bac-", 1, true)
        or string.find(s, "removed for", 1, true)
        or string.find(s, "exploit", 1, true)
        or string.find(s, "been kicked", 1, true)
        or string.find(s, "kicked from", 1, true)
        or string.find(s, "you were kicked", 1, true)
        or string.find(s, "you have been kicked", 1, true)
        or string.find(s, "you have been banned", 1, true)
        or string.find(s, "banned from", 1, true)
        or string.find(s, "please rejoin", 1, true)
        or string.find(s, "try rejoining", 1, true)
        or string.find(s, "rejoin the experience", 1, true)
        or string.find(s, "unauthorized", 1, true)
        or string.find(s, "anti cheat", 1, true)
        or string.find(s, "anticheat", 1, true)
    then
        return true, "kick"
    end
    if string.find(s, "error code", 1, true)
        or string.find(s, "disconnectconnectionlost", 1, true)
        or string.find(s, "disconnectnetworkerror", 1, true)
        or string.find(s, "disconnectclient", 1, true)
        or string.find(s, "lost connection", 1, true)
        or string.find(s, "connection lost", 1, true)
        or string.find(s, "disconnected", 1, true)
        or string.find(s, "koneksi terputus", 1, true)
        or string.find(s, "check your internet", 1, true)
        or string.find(s, "network error", 1, true)
        or string.find(s, "connection timed", 1, true)
        or string.find(s, "timed out", 1, true)
        or string.find(s, "idled out", 1, true)
        or string.find(s, "you were disconnected", 1, true)
    then
        return true, "dc"
    end
    return false, "ignore"
end

local function errorCodeIsNetworkDc()
    local code
    pcall(function()
        if type(GuiService.GetErrorCode) == "function" then
            code = GuiService:GetErrorCode()
        else
            code = GuiService.ErrorCode
        end
    end)
    if code == nil then
        return false
    end
    local name = string.lower(tostring(code))
    if string.find(name, "clientinitiated", 1, true) then
        return false
    end
    if string.find(name, "connectionlost", 1, true)
        or string.find(name, "networkerror", 1, true)
    then
        return true
    end
    local n = tonumber(code)
    if n == nil and typeof(code) == "EnumItem" then
        n = tonumber(code.Value)
    end
    return n == 277 or n == 278 or n == 279 or n == 280
end

local function tryDcRejoin(why)
    if alive() ~= true or M.reconnect ~= true then
        return
    end
    if ourHopFresh() then
        return
    end
    local text = tostring(why or "")
    local okText, reason = dcVerdict(text)
    if okText ~= true then
        M._lastSkip = (reason or "ignore") .. " · " .. text
        return
    end
    local now = os.clock()
    if now - (tonumber(M._dcAt) or 0) < DC_RETRY_SEC then
        return
    end
    M._dcAt = now
    M._lastWhy = text
    log("DC rejoin · " .. tostring(reason) .. " · " .. text)
    local function go()
        if alive() and M.reconnect == true then
            softRejoin(reason)
        end
    end
    if isBusy() then
        task.delay(2, go)
        return
    end
    go()
end

local SKIP_GUI = {
    NodeHubNeonUI = true,
    NodeHubDropdownOverlay = true,
    STEALEGG_PERF_HUD = true,
    Chat = true,
    ChatInputBar = true,
    BubbleChat = true,
}

local function overlayNameHit(name)
    name = string.lower(tostring(name or ""))
    -- Jangan PromptOverlay / RobloxPrompt: itu shop, friend, teleport UI.
    return string.find(name, "errorprompt", 1, true) ~= nil
        or string.find(name, "disconnect", 1, true) ~= nil
        or string.find(name, "connectionerror", 1, true) ~= nil
        or name == "error"
        or name == "kick"
        or name == "kicked"
end

local function visibleGui(inst)
    if typeof(inst) ~= "Instance" then
        return false
    end
    if inst:IsA("LayerCollector") then
        return inst.Enabled == true
    end
    if inst:IsA("GuiObject") then
        return inst.Visible == true
    end
    return true
end

local function collectPromptText(root, budget)
    budget = tonumber(budget) or 80
    local bits = {}
    local n = 0
    local ok, desc = pcall(function()
        return root:GetDescendants()
    end)
    if ok ~= true or type(desc) ~= "table" then
        return ""
    end
    for i = 1, #desc do
        if n >= budget then
            break
        end
        local d = desc[i]
        if typeof(d) == "Instance" and (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox")) then
            if visibleGui(d) then
                local t = d.Text
                if type(t) == "string" and #t >= 4 then
                    n += 1
                    bits[#bits + 1] = t
                end
            end
        end
    end
    return table.concat(bits, " ")
end

local function promptRoots()
    local roots = {}
    pcall(function()
        roots[#roots + 1] = game:GetService("CoreGui")
    end)
    pcall(function()
        if type(gethui) == "function" then
            local h = gethui()
            if typeof(h) == "Instance" then
                roots[#roots + 1] = h
            end
        end
    end)
    pcall(function()
        local pg = LP and LP:FindFirstChild("PlayerGui")
        if pg then
            roots[#roots + 1] = pg
        end
    end)
    return roots
end

local function scanDisconnectPrompts()
    local msg
    pcall(function()
        if type(GuiService.GetErrorMessage) == "function" then
            msg = GuiService:GetErrorMessage()
        else
            msg = GuiService.ErrorMessage
        end
    end)
    if type(msg) == "string" and msg ~= "" then
        tryDcRejoin(msg)
    end
    local code
    pcall(function()
        if type(GuiService.GetErrorCode) == "function" then
            code = GuiService:GetErrorCode()
        else
            code = GuiService.ErrorCode
        end
    end)
    if code ~= nil and errorCodeIsNetworkDc() then
        local name = string.lower(tostring(code))
        tryDcRejoin("lost connection " .. name)
    end
    local roots = promptRoots()
    for r = 1, #roots do
        local root = roots[r]
        local kids
        local okKids = pcall(function()
            kids = root:GetChildren()
        end)
        if okKids == true and type(kids) == "table" then
            for i = 1, #kids do
                local gui = kids[i]
                if typeof(gui) == "Instance" and not SKIP_GUI[gui.Name] and visibleGui(gui) then
                    if overlayNameHit(gui.Name) then
                        local body = collectPromptText(gui, 60)
                        if body ~= "" then
                            tryDcRejoin(body)
                        end
                    elseif root.Name == "PlayerGui" or (LP and gui:IsDescendantOf(LP)) then
                        local nm = string.lower(tostring(gui.Name))
                        if overlayNameHit(gui.Name)
                            or string.find(nm, "kick", 1, true)
                            or string.find(nm, "ban", 1, true)
                            or string.find(nm, "bac", 1, true)
                        then
                            local body = collectPromptText(gui, 40)
                            if body ~= "" then
                                tryDcRejoin(body)
                            end
                        end
                    end
                end
            end
        end
    end
end

