local function cloneFn(fn)
    local cf = clonefunction or clonefunc
    if type(cf) ~= "function" or type(fn) ~= "function" then
        return nil
    end
    local ok, c = pcall(cf, fn)
    if ok and type(c) == "function" then
        return c
    end
    return nil
end

-- clonefunction dulu, baru hook. Tanpa clone, orig sering = stub → overflow.
-- Kick/Teleport* tetap panggil asli (bukan stub kosong).
local function hookKeep(hf, fn, impl)
    if type(hf) ~= "function" or type(fn) ~= "function" or type(impl) ~= "function" then
        return
    end
    local asli = cloneFn(fn)
    if type(asli) ~= "function" then
        return
    end
    pcall(hf, fn, function(...)
        return impl(asli, ...)
    end)
end

-- Dump Control Teleport(placeId) di p6>1080 tanpa data. Rejoin Now / Auto Hop set AllowTeleport.
local function installTeleportBlock()
    if G.__StealEggAntiAfkTpHookVer == 4 then
        return
    end
    local hf = rawget(G, "hookfunction") or hookfunction or hookfunc
    if type(hf) ~= "function" then
        return
    end
    G.__StealEggAntiAfkTpHookVer = 4
    G.__StealEggAntiAfkTpHook = true

    pcall(function()
        hookKeep(hf, LP.Kick, function(asli, ...)
            return asli(...)
        end)
    end)

    pcall(function()
        hookKeep(hf, TeleportService.Teleport, function(asli, self, placeId, player, teleportData, ...)
            if alive() and isAfkData(teleportData) then
                return
            end
            if alive() and player == LP and not allowedTeleport() then
                return
            end
            return asli(self, placeId, player, teleportData, ...)
        end)
    end)

    pcall(function()
        hookKeep(hf, TeleportService.TeleportToPlaceInstance, function(asli, self, placeId, jobId, player, ...)
            if alive() and player == LP and not allowedTeleport() then
                return
            end
            return asli(self, placeId, jobId, player, ...)
        end)
    end)

    pcall(function()
        local old = TeleportService.TeleportAsync
        if type(old) ~= "function" then
            return
        end
        hookKeep(hf, old, function(asli, self, placeId, players, opts, ...)
            if alive() and opts ~= nil then
                local data = nil
                pcall(function()
                    if type(opts.GetTeleportData) == "function" then
                        data = opts:GetTeleportData()
                    end
                end)
                if data == nil then
                    pcall(function()
                        data = opts.TeleportData
                    end)
                end
                if isAfkData(data) then
                    return
                end
            end
            if alive() and not allowedTeleport() then
                return
            end
            return asli(self, placeId, players, opts, ...)
        end)
    end)
end

