    end)
    if touch == true then
        return false
    end
    local cam = workspace.CurrentCamera
    local loc
    pcall(function()
        loc = UserInputService:GetMouseLocation()
    end)
    local x = (loc and loc.X) or 400
    local y = (loc and loc.Y) or 300
    if x < 2 then
        x = 400
    end
    if y < 2 then
        y = 300
    end
    local vim = game:FindService("VirtualInputManager") or game:GetService("VirtualInputManager")
    if typeof(vim) == "Instance" and type(vim.SendMouseMoveEvent) == "function" then
        pcall(function()
            vim:SendMouseMoveEvent(x + 1, y, cam)
        end)
        pcall(function()
