-- Countdown hidup di getgenv yang sama dengan StealEgg. Bukan tebak.
-- Control: hop client = Idled p6>1080. 60s = analytics flag, bukan teleport.
-- Variant: 60s flag, 1020 AskRescueHop, 1110 AfkRestore.
task.spawn(function()
    local lastInput = os.clock()
    local lastP6, p6Hits = 0, 0
    local prevRemain = 60
    local job0 = tostring(game.JobId)
    pcall(function()
        UserInputService.InputBegan:Connect(function()
            lastInput = os.clock()
        end)
        UserInputService.InputChanged:Connect(function(inp)
            local t = inp and inp.UserInputType
            if t == Enum.UserInputType.MouseMovement
                or t == Enum.UserInputType.Touch
                or (t and string.find(t.Name, "Gamepad", 1, true))
            then
                lastInput = os.clock()
            end
        end)
        LP.Idled:Connect(function(sec)
            lastP6 = tonumber(sec) or 0
            p6Hits += 1
            log(string.format("Idled p6=%.1fs hits=%d", lastP6, p6Hits))
        end)
    end)
    while alive() do
        local clockIdle = os.clock() - lastInput
        local idle = math.max(clockIdle, lastP6)
        local r60 = 60 - idle
        local dir = "sama"
        if r60 < prevRemain - 0.2 then
            dir = "berkurang"
        elseif r60 > prevRemain + 0.2 then
            dir = "bertambah"
        end
        prevRemain = r60
        local job = tostring(game.JobId)
        M._idle = {
            idle = idle,
            remain60 = r60,
            dir = dir,
            clockIdle = clockIdle,
            idledP6 = lastP6,
            p6Hits = p6Hits,
            job = job,
            hopped = job ~= job0,
        }
        log(string.format(
            "idle=%.0fs remain60=%+.0fs (%s) p6=%.0f hopLeft=%+.0fs job=%s hop=%s far=%s",
            idle,
            r60,
            dir,
            lastP6,
            1020 - idle,
            job:sub(1, 8),
            tostring(job ~= job0),
            tostring(G.__StealEggFarOn == true)
        ))
        if job ~= job0 then
            log("JOB CHANGE " .. job0:sub(1, 8) .. " -> " .. job:sub(1, 8) .. string.format(" idle=%.0fs", idle))
            job0 = job
            lastInput = os.clock()
            lastP6, p6Hits, prevRemain = 0, 0, 60
        end
        task.wait(5)
    end
end)

return M
