local function fmtNum(n)
	n = tonumber(n) or 0
	local abs = math.abs(n)
	local units = {
		{ 1e15, "Qa" },
		{ 1e12, "T" },
		{ 1e9, "B" },
		{ 1e6, "M" },
		{ 1e3, "k" },
	}
	for _, u in ipairs(units) do
		if abs >= u[1] then
			return string.format("%.1f%s", n / u[1], u[2])
		end
	end
	if abs >= 10 or n == math.floor(n) then
		return string.format("%.0f", n)
	end
	return string.format("%.1f", n)
end

local function fmtKg(n)
	n = tonumber(n) or 0
	if n >= 10 then
		return string.format("%.0fkg", n)
	end
	return string.format("%.1fkg", n)
end

local function parseEarnMin(txt)
	txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
	if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
		txt = txt:sub(2)
	end
	if txt == "" or txt == "0" then
		return 0, "0"
	end
	local suffixes = {
		{ "qa", 1e15 },
		{ "t", 1e12 },
		{ "b", 1e9 },
		{ "m", 1e6 },
		{ "k", 1e3 },
	}
	for _, pair in ipairs(suffixes) do
		local suf, mult = pair[1], pair[2]
		if #txt > #suf and txt:sub(-#suf) == suf then
			local n = tonumber(txt:sub(1, -#suf - 1))
			if n and n > 0 then
				return n * mult, txt
			end
		end
	end
	local n = tonumber(txt)
	if n and n > 0 then
		return n, txt
	end
	return 0, "0"
end

local function mutText(muts)
	if type(muts) ~= "table" or #muts == 0 then
		return "Normal"
	end
	local names = {}
	for i, name in ipairs(muts) do
		if type(Core.mutationLabel) == "function" then
			names[i] = Core.mutationLabel(name)
		else
			names[i] = tostring(name)
		end
	end
	return table.concat(names, "+")
end

local function webhookUrl(raw)
	raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if raw == "" then
		return ""
	end
	if not string.find(raw, "discord.com/api/webhooks/", 1, true)
		and not string.find(raw, "discordapp.com/api/webhooks/", 1, true) then
		return ""
	end
	return raw
end

local function httpRequest()
	return (syn and syn.request)
		or (http and http.request)
		or http_request
		or request
		or (fluxus and fluxus.request)
end

local _imgCache = {}
local _postQ = {}
local _postOn = false
local IMG_WAIT = 1.2

local function httpGetJson(url, headers)
	local req = httpRequest()
	if type(req) ~= "function" then
		return nil
	end
	local ok, res = pcall(req, {
		Url = url,
		Method = "GET",
		Headers = type(headers) == "table" and headers or nil,
	})
	if not ok then
		return nil
	end
	local body = res and (res.Body or res.body)
	if type(body) ~= "string" or body == "" then
		return nil
	end
	local okj, data = pcall(HttpService.JSONDecode, HttpService, body)
	if okj and type(data) == "table" then
		return data
	end
	return nil
end

local function httpGetJsonWait(url, headers)
	local box = { data = nil, done = false }
	task.spawn(function()
		box.data = httpGetJson(url, headers)
		box.done = true
	end)
	local t0 = os.clock()
	while box.done ~= true and os.clock() - t0 < IMG_WAIT do
		task.wait(0.05)
	end
	return box.data
end

local function firstImageUrl(data)
	local row = type(data) == "table" and data.data and data.data[1]
	if type(row) ~= "table" then
		return nil
	end
	local st = tostring(row.state or "")
	if st ~= "" and st ~= "Completed" then
		return nil
	end
	local url = row.imageUrl
	if type(url) ~= "string" or not string.find(url, "^https://") then
		return nil
	end
	if not string.find(url, "rbxcdn.com", 1, true) then
		return nil
	end
	return url
end

local function nodeIcon()
	return NODE_ICON
end

local function postNow(payload)
	local url = webhookUrl(M.url)
	if url == "" then
		return false, "no url"
	end
	local req = httpRequest()
	if type(req) ~= "function" then
		return false, "no request"
	end
	local waitFor = POST_GAP - (os.clock() - (M._lastPost or 0))
	if waitFor > 0 then
		task.wait(waitFor)
	end
	local body = HttpService:JSONEncode(payload)
	local ok, res = pcall(req, {
		Url = url,
		Method = "POST",
		Headers = { ["Content-Type"] = "application/json" },
		Body = body,
	})
	M._lastPost = os.clock()
	local code = ok and tonumber(res and (res.StatusCode or res.status_code)) or 0
	if code == 204 or code == 200 then
		return true, nil
	end
	if code == 429 then
		local retry = tonumber(res and res.Headers and (res.Headers["Retry-After"] or res.Headers["retry-after"])) or 2
		if retry < 0.5 then
			retry = 0.5
		end
		if retry > 8 then
			retry = 8
		end
		task.wait(retry)
		ok, res = pcall(req, {
			Url = url,
			Method = "POST",
			Headers = { ["Content-Type"] = "application/json" },
			Body = body,
		})
		M._lastPost = os.clock()
		code = ok and tonumber(res and (res.StatusCode or res.status_code)) or 0
		if code == 204 or code == 200 then
			return true, nil
		end
	end
	return false, "http " .. tostring(code)
end

local function enqueuePost(payload, onDone, prepare)
	_postQ[#_postQ + 1] = { payload = payload, onDone = onDone, prepare = prepare }
	if _postOn == true then
		return
	end
	_postOn = true
	task.spawn(function()
		while #_postQ > 0 do
			local job = table.remove(_postQ, 1)
			if type(job.prepare) == "function" then
				pcall(job.prepare, job.payload)
			end
			local ok, err = postNow(job.payload)
			if type(job.onDone) == "function" then
				pcall(job.onDone, ok, err)
			end
		end
		_postOn = false
	end)
end

local function postPayload(payload, onDone, prepare)
	enqueuePost(payload, onDone, prepare)
	return true, nil
end

local function who()
	return (LP and (LP.DisplayName or LP.Name)) or "?"
end

local function whoTag()
	if not LP then
		return "Account"
	end
	local display = tostring(LP.DisplayName or LP.Name or "Account")
	local name = tostring(LP.Name or "")
	if name ~= "" and name ~= display then
		return display .. "  @" .. name
	end
	return display
end

local function playerAvatar()
	local id = tonumber(LP and LP.UserId) or 0
	if id <= 0 then
		return NODE_ICON
	end
	local key = "u" .. tostring(id)
	if _imgCache[key] == false then
		return NODE_ICON
	end
	if type(_imgCache[key]) == "string" then
		return _imgCache[key]
	end
	local data = httpGetJsonWait(
		"https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
			.. tostring(id)
			.. "&size=150x150&format=Png&isCircular=false"
	)
	local url = firstImageUrl(data)
	_imgCache[key] = url or false
	return url or NODE_ICON
end

local function isJunkTitle(n)
	n = string.lower(tostring(n or ""))
	if n == "" or n == "game" or n == "place" or n == "ugc" or n == "workspace" then
		return true
	end
	if string.find(n, "mencuri", 1, true) then
		return true
	end
	return false
end

local function gameTitle()
	if type(_imgCache.game) == "string" and not isJunkTitle(_imgCache.game) then
		return _imgCache.game
	end
	_imgCache.game = GAME_NAME
	return GAME_NAME
end

local function code(v)
	return "`" .. tostring(v) .. "`"
end

local function footerBlock()
	return {
		text = "NODE  ·  " .. gameTitle() .. "  ·  " .. os.date("%H:%M:%S"),
		icon_url = nodeIcon(),
	}
end

local function authorBlock()
	return {
		name = whoTag(),
		icon_url = NODE_ICON,
	}
end

local function spoiler(text)
	text = tostring(text or ""):gsub("|", "")
	if text == "" then
		return "||?||"
	end
	return "||" .. text .. "||"
end

local function field(name, value, inline)
	value = tostring(value or "")
	if value == "" then
		value = "—"
	end
	return {
		name = name,
		value = value,
		inline = inline ~= false,
	}
end

local function slotCount(level)
	level = tonumber(level) or 0
	bindGame()
	if type(Bases) == "table" then
		if type(Bases.GetAssetEquipCapacity) == "function" then
			local ok, n = pcall(Bases.GetAssetEquipCapacity, level)
			if ok and tonumber(n) then
				return tonumber(n)
			end
		end
		local cfg = Bases.BASES and Bases.BASES[level]
		if type(cfg) == "table" then
			return tonumber(cfg.MaxAssets) or 0
		end
	end
	return 0
end

local function treadmillMax()
	bindGame()
	if type(Treadmills) == "table" then
		if type(Treadmills.GetOrdered) == "function" then
			local ok, list = pcall(Treadmills.GetOrdered)
			if ok and type(list) == "table" then
				return #list
			end
		end
		if type(Treadmills.Directory) == "table" then
			local n = 0
			for _ in pairs(Treadmills.Directory) do
				n += 1
			end
			return n
		end
	end
	return 0
end

local function treadmillLevelText(level)
	level = tonumber(level) or 0
	local maxLv = treadmillMax()
	if maxLv > 0 then
		return string.format("%d/%d", level, maxLv)
	end
	return tostring(level)
end

local function speedText(data)
	local n = tonumber(data and data.SpeedPower) or 0
	bindGame()
	if type(TreadmillUtil) == "table" and type(TreadmillUtil.FormatSpeedPower) == "function" then
		local ok, s = pcall(TreadmillUtil.FormatSpeedPower, n)
		if ok and type(s) == "string" and s ~= "" then
			return s
		end
	end
	return fmtNum(n)
end

local function matchesStealRule(info)
	if type(info) ~= "table" then
		return false
	end
	local wild = G.StealEggWild
	if type(wild) ~= "table" or type(wild.ruleMatches) ~= "function" then
		return false
	end
	local rules = {}
	if type(wild.enabledRules) == "function" then
		local ok, list = pcall(wild.enabledRules)
		if not ok then
			return false
		end
		if type(list) == "table" then
			rules = list
		end
	end
	-- Rule ON = cuma yang match. Rule kosong / all-off = semua steal.
	if #rules == 0 then
		return true
	end
	for _, rule in ipairs(rules) do
		if wild.ruleMatches(rule, info) then
			return true
		end
	end
	return false
end

local function collectAccount()
	local data = getSave()
	local hatch = G.StealEggHatch
	local sell = G.StealEggSell
	local penLv = tonumber(data and data.BaseUpgradeLevel) or 0
	local slots = slotCount(penLv)
	local beltLv = tonumber(data and data.TreadmillUpgradeLevel) or 0

	local eggBag, eggPlot, petBag, equipN, equipRate = 0, 0, 0, 0, 0
	local eggBagRate, petBagRate, plotRate = 0, 0, 0
	if type(sell) == "table" then
		if type(sell.listBagEggs) == "function" then
			local ok, items = pcall(sell.listBagEggs)
			if ok and type(items) == "table" then
				eggBag = #items
				for _, info in ipairs(items) do
					if type(info) == "table" then
						eggBagRate += tonumber(info.rate) or 0
					end
				end
			end
		end
		if type(sell.listBagPets) == "function" then
			local ok, items = pcall(sell.listBagPets)
			if ok and type(items) == "table" then
				for _, info in ipairs(items) do
					if type(info) == "table" then
						if info.equipped == true then
							equipN += 1
							equipRate += tonumber(info.rate) or 0
						else
							petBag += 1
							petBagRate += tonumber(info.rate) or 0
						end
					end
				end
			end
		end
	end
	if type(hatch) == "table" then
		if type(hatch.listPlotEggs) == "function" then
			local ok, plot = pcall(hatch.listPlotEggs)
			if ok and type(plot) == "table" then
				if type(plot.eggs) == "table" then
					eggPlot = #plot.eggs
				elseif type(plot.count) == "number" then
					eggPlot = plot.count
				end
				plotRate = tonumber(plot.rate) or 0
			end
		end
	end
	-- Hatch describeRecord sering rate=0 buat egg plot. Pakai inspect Sell (sama kayak Egg Bag).
	if type(sell) == "table" and type(sell.listPlacedEggs) == "function" then
		local okp, placed = pcall(sell.listPlacedEggs)
		if okp and type(placed) == "table" and #placed > 0 then
			eggPlot = #placed
			plotRate = 0
			for _, info in ipairs(placed) do
				if type(info) == "table" then
					plotRate += tonumber(info.rate) or 0
				end
			end
		end
	end
	if (eggBag == 0 or eggPlot == 0) and type(data) == "table" then
		if eggBag == 0 and type(data.EggInventory) == "table" then
			local bag, plot = 0, 0
			for _, rec in pairs(data.EggInventory) do
				if type(rec) == "table" and rec.Placement ~= nil then
					plot += 1
				else
					bag += 1
				end
			end
			if eggBag == 0 then
				eggBag = bag
			end
			if eggPlot == 0 then
				eggPlot = plot
			end
		end
		if petBag == 0 and equipN == 0 and type(data.Inventory) == "table" then
			local n = 0
			for _ in pairs(data.Inventory) do
				n += 1
			end
			petBag = n
		end
	end

	local plotCap = nil
	if type(hatch) == "table" and type(hatch.placeCap) == "function" then
		local ok, cap = pcall(hatch.placeCap)
		if ok and tonumber(cap) then
			plotCap = tonumber(cap)
		end
	end

	local function countEarn(n, rate)
		n = tonumber(n) or 0
		rate = tonumber(rate) or 0
		if rate > 0 then
			return string.format("%d  ·  %s/s", n, fmtNum(rate))
		end
		return tostring(n)
	end

	local plotText = countEarn(eggPlot, plotRate)
	if plotCap and plotCap > 0 then
		if plotRate > 0 then
			plotText = string.format("%d/%d  ·  %s/s", eggPlot, plotCap, fmtNum(plotRate))
		else
			plotText = string.format("%d/%d", eggPlot, plotCap)
		end
	end

	return {
		pen = string.format("Lv %d  ·  %d slot", penLv, slots),
		treadmill = treadmillLevelText(beltLv),
		equip = string.format("%d/%d  ·  %s/s", equipN, slots, fmtNum(equipRate)),
		speed = speedText(data),
		eggBag = countEarn(eggBag, eggBagRate),
		petBag = countEarn(petBag, petBagRate),
		eggPlot = plotText,
	}
end

local function sendAccount()
	if M.account ~= true then
		return false, "off"
	end
	local snap = collectAccount()
	postPayload({
		username = "NODE",
		avatar_url = nodeIcon(),
		embeds = { {
			author = authorBlock(),
			title = "Track Account",
			color = COLOR_LINE,
			fields = {
				field("Pen", code(snap.pen), true),
				field("Treadmill", code(snap.treadmill), true),
				field("Speed", code(snap.speed), true),
				field("Equip Pet", code(snap.equip), true),
				field("Egg Bag", code(snap.eggBag), true),
				field("Pet Bag", code(snap.petBag), true),
				field("Egg Plot", code(snap.eggPlot), true),
			},
			footer = footerBlock(),
		} },
	}, function(ok, err)
		if ok then
			emit("Sent", "success", "account")
		else
			emit("Fail", "error", tostring(err or "account"))
		end
	end, function(payload)
		local embed = payload.embeds and payload.embeds[1]
		if type(embed) ~= "table" or type(embed.author) ~= "table" then
			return
		end
		embed.author.icon_url = playerAvatar()
	end)
	return true, nil
end

local function infoWaitSec()
	local min = tonumber(M.delayMin) or DELAY_DEFAULT
	if min < DELAY_MIN then
		min = DELAY_MIN
	end
	if min > DELAY_MAX then
		min = DELAY_MAX
	end
	return min * 60
end

local function ensureInfoLoop()
	if M._loopOn == true then
		return
	end
	M._token = (tonumber(M._token) or 0) + 1
	local token = M._token
	M._loopOn = true
	task.spawn(function()
		while GEN == G.__StealEggWebhookGen and token == M._token and M.account == true do
			task.wait(infoWaitSec())
			if GEN ~= G.__StealEggWebhookGen or token ~= M._token or M.account ~= true then
				break
			end
			pcall(sendAccount)
		end
		if token == M._token then
			M._loopOn = false
		end
	end)
end

function M.notifySteal(info)
	if M.steal ~= true then
		return
	end
	info = type(info) == "table" and info or {}
	if not matchesStealRule(info) then
		return
	end
	local rate = tonumber(info.rate) or 0
	local minEarn = tonumber(M.earnMin) or 0
	if minEarn > 0 and rate < minEarn then
		return
	end
	local parts = {}
	if type(info.rarity) == "string" and info.rarity ~= "" then
		parts[#parts + 1] = info.rarity
	end
	parts[#parts + 1] = tostring(info.name or info.category or "egg")
	parts[#parts + 1] = mutText(info.muts)
	if (tonumber(info.kg) or 0) > 0 then
		parts[#parts + 1] = fmtKg(info.kg)
	end
	if rate > 0 then
		parts[#parts + 1] = fmtNum(rate) .. "/s"
	end
	if type(info.areaName) == "string" and info.areaName ~= "" then
		parts[#parts + 1] = info.areaName
	end
	local line = table.concat(parts, " · ")
	local name = info.name or info.category or "steal"
	local embed = {
		author = authorBlock(),
		title = "Steal Egg",
		description = code(line),
		color = COLOR_LINE,
		footer = footerBlock(),
	}
	local payload = {
		username = "NODE",
		avatar_url = nodeIcon(),
		embeds = { embed },
	}
	if minEarn > 0 then
		payload.content = "@everyone"
		payload.allowed_mentions = { parse = { "everyone" } }
	end
	postPayload(payload, function(ok, err)
		if ok then
			emit("Sent", "success", name)
		else
			emit("Fail", "error", tostring(err or "steal"))
		end
	end, function(body)
		local em = body.embeds and body.embeds[1]
		if type(em) == "table" and type(em.author) == "table" then
			em.author.icon_url = playerAvatar()
		end
	end)
end

function M.setUrl(text)
	M.url = webhookUrl(text)
end

function M.setDelay(n)
	n = math.floor(tonumber(n) or DELAY_DEFAULT)
	if n < DELAY_MIN then
		n = DELAY_MIN
	end
	if n > DELAY_MAX then
		n = DELAY_MAX
	end
	M.delayMin = n
	if M.account == true then
		M._token = (tonumber(M._token) or 0) + 1
		M._loopOn = false
		ensureInfoLoop()
	end
	return n
end

function M.setEarn(text)
	local n, shown = parseEarnMin(text)
	M.earnMin = n
	M.earnText = shown
	return shown
end

function M.setSteal(on)
	M.steal = on == true
	if M.steal or M.account then
		emit(M.steal and "On" or "Account", "live", M.steal and "steal" or "account")
	else
		emit("Off", "muted", "—")
	end
end

function M.setAccount(on)
	local was = M.account == true
	M.account = on == true
	if M.account then
		emit("On", "live", "account")
		if was ~= true then
			task.spawn(function()
				pcall(sendAccount)
			end)
		end
		ensureInfoLoop()
		return
	end
	M._token = (tonumber(M._token) or 0) + 1
	M._loopOn = false
	if M.steal then
		emit("On", "live", "steal")
	else
		emit("Off", "muted", "—")
	end
end

function M.setEnabled(on)
	on = on == true
	M.setSteal(on)
	M.setAccount(on)
end

function M.Stop()
	M.steal = false
	M.account = false
	M._token = (tonumber(M._token) or 0) + 1
	M._loopOn = false
	emit("Off", "muted", "off")
end

function M.syncFrom(values)
	values = type(values) == "table" and values or {}
	if values["misc.webhook.url"] ~= nil then
		M.setUrl(values["misc.webhook.url"])
	end
	if values["misc.webhook.account.delay"] ~= nil then
		M.setDelay(values["misc.webhook.account.delay"])
	end
	if values["misc.webhook.steal"] ~= nil then
		M.setSteal(Core.flagOn(values["misc.webhook.steal"]))
	end
	if values["misc.webhook.account"] ~= nil then
		M.setAccount(Core.flagOn(values["misc.webhook.account"]))
	end
	if values["misc.webhook.steal.earn"] ~= nil then
		M.setEarn(values["misc.webhook.steal.earn"])
	end
end

function M.Register(ui)
	local pre = ui:GetValues() or {}
	M.syncFrom(pre)

	ui:RegisterSubTab("misc", "webhook", "Webhook", function()
		ui:ClearSubContent()
		local body, _, statusApi = ui:CreateSection({
			title = "Discord Webhook",
			expanded = true,
			status = {
				id = "misc.webhook.status",
				persist = false,
				value = M._status.text,
				style = M._status.style,
			},
		})
		if statusApi then
			M.setStatusListener(function(st)
				if statusApi.set then
					statusApi.set(st.text)
				end
				if statusApi.setStyle then
					statusApi.setStyle(st.style)
				end
				if statusApi.setDetail then
					statusApi.setDetail(st.detail)
				end
			end)
		end
		local group = ui:CreateGroup(body)
		ui:CreateRowInput(group, {
			id = "misc.webhook.url",
			label = "Webhook URL",
			persist = true,
			initial = M.url,
			clearOnFocus = false,
			placeholder = "https://discord.com/api/webhooks/...",
			hintText = "URL channel Discord kamu. Jangan share.",
			onChanged = function(text)
				M.setUrl(text)
			end,
		})
		ui:CreateRowToggle(group, {
			id = "misc.webhook.steal",
			label = "Steal Egg",
			persist = true,
			initial = M.steal == true,
			hintText = "Kirim hanya egg yang match rule Steal. Rule kosong = semua steal.",
			onChanged = function(on)
				M.setSteal(on == true)
			end,
		})
		ui:CreateRowInput(group, {
			id = "misc.webhook.steal.earn",
			label = "Earn min $/s",
			persist = true,
			initial = tostring(M.earnText or "0"),
			clearOnFocus = false,
			placeholder = "0",
			hintText = "0 = ikut filter rule Steal. 1b = hanya earn ≥1B, tag @everyone.",
			onChanged = function(text)
				return M.setEarn(text)
			end,
		})
		ui:CreateRowInput(group, {
			id = "misc.webhook.account.delay",
			label = "Info Delay (min)",
			persist = true,
			initial = tostring(M.delayMin or DELAY_DEFAULT),
			clearOnFocus = false,
			hintText = "Jeda kirim Info Account. Default 60 menit.",
			onChanged = function(text)
				local n = M.setDelay(text)
				return tostring(n)
			end,
		})
		ui:CreateRowToggle(group, {
			id = "misc.webhook.account",
			label = "Info Account",
			persist = true,
			initial = M.account == true,
			hintText = "Pen, Treadmill, Equip Pet total, Speed, egg/pet bag, egg plot. Kirim sekarang + tiap delay.",
			onChanged = function(on)
				M.setAccount(on == true)
			end,
		})
	end, 2)
end

return M
