        return prevHub
    end

    local HttpService = game:GetService("HttpService")
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local StatsService = game:GetService("Stats")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")

    -- PropertyChangedSignal:Wait() TIDAK return LocalPlayer (args kosong) → LP bisa nil
    local LP = Players.LocalPlayer
    if not LP then
        Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
        LP = Players.LocalPlayer
    end
    if not LP then
        LP = Players.PlayerAdded:Wait()
    end

    local function localPlayer()
        local p = Players.LocalPlayer
        if p then
            LP = p
            return p
        end
        return LP
    end

    local NodeHubWS = {
        __version = VERSION,
        _bridges = (type(prevHub) == "table" and type(prevHub._bridges) == "table") and prevHub._bridges or {},
        _applyUiHooks = (type(prevHub) == "table" and type(prevHub._applyUiHooks) == "table") and prevHub._applyUiHooks or {},
    }

    local function now()
        return os.time()
    end

    local function trim(s)
        s = tostring(s or "")
        return s:match("^%s*(.-)%s*$") or ""
    end

    local function safeToString(v, fallback)
        if v == nil then return fallback or "" end
        return tostring(v)
    end

    local function safeShort(v, maxLen, fallback)
        local s = safeToString(v, fallback or "")
        s = trim(s)
        maxLen = tonumber(maxLen) or 120
        if maxLen > 0 and #s > maxLen then
            s = s:sub(1, maxLen)
        end
        return s
    end

    local function normalizeScId(v)
        -- sc_id = id_code_list dari DB admin.
        -- Dibuat numeric-only agar aman untuk dipakai sebagai selector fitur modular di web.
        if v == nil then return nil end
        local s = trim(tostring(v or ""))
        if s == "" or s == "nil" then return nil end
        s = s:gsub("[^%d]", "")
        if s == "" then return nil end
        local n = tonumber(s)
        if not n or n < 1 then return nil end
        return math.floor(n)
    end

    local function firstNonEmpty(...)
        for i = 1, select('#', ...) do
            local v = select(i, ...)
            if v ~= nil then
                local s = trim(tostring(v))
                if s ~= "" and s ~= "nil" then
                    return v
                end
            end
        end
        return nil
    end

    local function jsonEncode(t)
        local ok, res = pcall(function()
            return HttpService:JSONEncode(t)
        end)
        if ok and type(res) == "string" then return res end
        return nil, res
    end

    local function jsonDecode(s)
        local ok, res = pcall(function()
            return HttpService:JSONDecode(s)
        end)
        if ok and type(res) == "table" then return res end
        return nil, res
    end

    local function urlEncode(s)
        s = tostring(s or "")
        local ok, res = pcall(function()
            return HttpService:UrlEncode(s)
        end)
        if ok and type(res) == "string" then return res end
        return s:gsub("([^%w%-_%.~])", function(c)
            return string.format("%%%02X", string.byte(c))
        end)
    end

    local function canFS()
        return type(readfile) == "function"
            and type(writefile) == "function"
            and type(isfile) == "function"
    end

    local function ensureFolder(path)
        if type(makefolder) ~= "function" then return end
        if type(path) ~= "string" or path == "" then return end
        local folder = path:match("^(.*)/[^/]+$") or path
        if folder == "" then return end
        local cur = ""
        for seg in folder:gmatch("[^/]+") do
            cur = (cur == "") and seg or (cur .. "/" .. seg)
            local exists = false
            if type(isfolder) == "function" then
                local ok, res = pcall(isfolder, cur)
                exists = ok and res == true
            end
            if not exists then
                pcall(makefolder, cur)
            end
        end
    end

    local function readJsonFile(path)
        if not canFS() or type(path) ~= "string" or path == "" then
            return nil, "fs_unavailable"
        end
        local okFile, exists = pcall(isfile, path)
        if not okFile or exists ~= true then
            return nil, "file_not_found"
        end
        local okRead, text = pcall(readfile, path)
        if not okRead or type(text) ~= "string" or text == "" then
            return nil, "read_failed"
        end
        return jsonDecode(text)
    end

    local function writeJsonFile(path, data)
        if not canFS() or type(path) ~= "string" or path == "" then
            return false, "fs_unavailable"
        end
        ensureFolder(path)
        local text, err = jsonEncode(data)
        if not text then
            return false, "json_encode_failed: " .. tostring(err)
        end
        local okWrite, writeErr = pcall(function()
            writefile(path, text)
        end)
        if not okWrite then
            return false, "write_failed: " .. tostring(writeErr)
        end
        return true, text
    end

    local function deleteFileSafe(path)
        if type(path) ~= "string" or path == "" then
            return false, "empty_path"
        end

        if type(isfile) == "function" then
            local okFile, exists = pcall(isfile, path)
            if okFile and exists ~= true then
                return true, "file_not_found"
            end
        end

        local deleteFn = nil
        if type(delfile) == "function" then
            deleteFn = delfile
        elseif type(deletefile) == "function" then
            deleteFn = deletefile
        end

        if type(deleteFn) ~= "function" then
            return false, "delete_unavailable"
        end

        local okDelete, deleteErr = pcall(deleteFn, path)
        if not okDelete then
            return false, tostring(deleteErr)
        end
        return true
    end

    local function looksLikePureConfig(t)
        if type(t) ~= "table" then return false end
        if type(t.main) == "table" then return true end
        if type(t.auto) == "table" or type(t.misc) == "table" then return true end
        if t.running ~= nil then return true end
        return false
    end

    local function normalizeConfigEnvelope(data)
        -- Tujuan:
        -- SAVE_FILE lokal harus berisi config murni:
        --   { main = {...}, running = false }
        --
        -- Data dari DB/Node kadang berbentuk wrapper:
        --   { config = { main = {...}, running = false }, meta = {...}, at = "..." }
        --
        -- Kalau wrapper ikut ditulis ke SAVE_FILE, GAG2 tidak menemukan data.main.misc,
        -- jadi UI berkedip tapi nilai toggle tidak berubah.
        if type(data) ~= "table" then
            return data, false
        end

        if looksLikePureConfig(data) then
            return data, false
        end

        if type(data.config) == "table" and looksLikePureConfig(data.config) then
            return data.config, true
        end

        if type(data.payload) == "table" and looksLikePureConfig(data.payload) then
            return data.payload, true
        end

        if type(data.data) == "table" and looksLikePureConfig(data.data) then
            return data.data, true
        end

        return data, false
    end

    local function safeFileNamePart(s)
        s = tostring(s or "player")
        s = s:gsub("[^%w%-_.]", "_")
        s = s:gsub("_+", "_")
        return s:sub(1, 48)
    end

    local function defaultGAG2SaveFile()
        return ("growagarden2/%s.json"):format(safeFileNamePart(LP and LP.Name or "player"))
    end

    local function resolveConfigSaveFile(path, namespace)
        if type(path) == "string" and path ~= "" then
            return path
        end

        local candidates = {
            G.__GAG2_SAVE_FILE,
            rawget(_G, "__GAG2_SAVE_FILE"),
            G.GAG2_SAVE_FILE,
            rawget(_G, "GAG2_SAVE_FILE"),
            G.SAVE_FILE,
            rawget(_G, "SAVE_FILE"),
        }

        for _, candidate in ipairs(candidates) do
            if type(candidate) == "string" and candidate ~= "" then
                return candidate
            end
        end

        if tostring(namespace or "") == "gag2" then
            return defaultGAG2SaveFile()
        end

        return path
    end

    local function nativeSha256(text)
        text = tostring(text or "")
        local candidates = {}

        if type(crypt) == "table" and type(crypt.hash) == "function" then
            candidates[#candidates + 1] = function() return crypt.hash(text, "sha256") end
            candidates[#candidates + 1] = function() return crypt.hash("sha256", text) end
        end

        if type(syn) == "table" and type(syn.crypt) == "table" and type(syn.crypt.hash) == "function" then
            candidates[#candidates + 1] = function() return syn.crypt.hash(text, "sha256") end
            candidates[#candidates + 1] = function() return syn.crypt.hash("sha256", text) end
        end

        if type(hash) == "function" then
            candidates[#candidates + 1] = function() return hash(text, "sha256") end
            candidates[#candidates + 1] = function() return hash("sha256", text) end
        end

        for _, fn in ipairs(candidates) do
            local ok, res = pcall(fn)
            if ok and type(res) == "string" then
                res = res:lower():gsub("%s+", "")
                if res:match("^[a-f0-9]+$") and #res == 64 then
                    return res
                end
            end
        end

        return nil
    end

    local function sha256(text, forceSoftware)
        text = tostring(text or "")
        if forceSoftware ~= true then
            local native = nativeSha256(text)
            if native then return native end
        end

        local bit = bit32
        if type(bit) ~= "table" then
            error("sha256 perlu crypt.hash/hash atau bit32 dari executor")
        end

        local band, bxor = bit.band, bit.bxor
        local bnot, rshift, rrotate = bit.bnot, bit.rshift, bit.rrotate
        local MOD = 4294967296

        local function add(...)
            local sum = 0
            for i = 1, select("#", ...) do
                sum = (sum + (select(i, ...) or 0)) % MOD
            end
            return sum
        end

        local function u32be(a, b, c, d)
            return ((a or 0) * 16777216 + (b or 0) * 65536 + (c or 0) * 256 + (d or 0)) % MOD
        end

        local function wordToBytes(n)
            return string.char(
                band(rshift(n, 24), 255),
                band(rshift(n, 16), 255),
                band(rshift(n, 8), 255),
                band(n, 255)
            )
        end

        local K = {
            0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
            0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
            0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
            0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
            0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
            0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
            0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
            0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
        }

        local h0,h1,h2,h3,h4,h5,h6,h7 =
            0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19

        local bitLen = #text * 8
        text = text .. string.char(0x80)
        while (#text % 64) ~= 56 do
            text = text .. string.char(0)
        end

        local high = math.floor(bitLen / MOD)
        local low = bitLen % MOD
        text = text .. wordToBytes(high) .. wordToBytes(low)

        for chunk = 1, #text, 64 do
            local w = {}
            for i = 0, 15 do
                local a,b,c,d = string.byte(text, chunk + i * 4, chunk + i * 4 + 3)
                w[i + 1] = u32be(a,b,c,d)
            end
            for i = 17, 64 do
                local s0 = bxor(rrotate(w[i - 15], 7), rrotate(w[i - 15], 18), rshift(w[i - 15], 3))
                local s1 = bxor(rrotate(w[i - 2], 17), rrotate(w[i - 2], 19), rshift(w[i - 2], 10))
                w[i] = add(w[i - 16], s0, w[i - 7], s1)
            end

            local a,b,c,d,e,f,g,h = h0,h1,h2,h3,h4,h5,h6,h7
            for i = 1, 64 do
                local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
                local ch = bxor(band(e, f), band(bnot(e), g))
                local temp1 = add(h, S1, ch, K[i], w[i])
                local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
                local maj = bxor(band(a, b), band(a, c), band(b, c))
                local temp2 = add(S0, maj)
                h, g, f, e, d, c, b, a = g, f, e, add(d, temp1), c, b, a, add(temp1, temp2)
            end

            h0,h1,h2,h3,h4,h5,h6,h7 =
                add(h0,a), add(h1,b), add(h2,c), add(h3,d),
                add(h4,e), add(h5,f), add(h6,g), add(h7,h)
        end

        return string.format("%08x%08x%08x%08x%08x%08x%08x%08x", h0,h1,h2,h3,h4,h5,h6,h7)
    end

    -- Dedicated resolve HMAC secret. Must match PHP MONITOR_RESOLVE_SECRET.
    local MONITOR_RESOLVE_SECRET = "nm_resolve_v1_K8mQ2wP9nR4tY6uA1sD7fH3jL5xC0vB"

    local function hexToRaw(hex)
        return (tostring(hex or ""):gsub("..", function(cc)
            return string.char(tonumber(cc, 16) or 0)
        end))
    end

    local function xorPad(block, xorVal)
        local t = {}
        for i = 1, #block do
            local b = string.byte(block, i)
            local x
            if type(bit32) == "table" and type(bit32.bxor) == "function" then
                x = bit32.bxor(b, xorVal)
            elseif type(bit) == "table" and type(bit.bxor) == "function" then
                x = bit.bxor(b, xorVal)
            else
                x = 0
                local aa, bb, bitv = b, xorVal, 1
                for _ = 1, 8 do
                    if (aa % 2) ~= (bb % 2) then
                        x = x + bitv
                    end
                    aa = math.floor(aa / 2)
                    bb = math.floor(bb / 2)
                    bitv = bitv * 2
                end
            end
            t[i] = string.char(x)
        end
        return table.concat(t)
    end

    local function hmacSha256(key, message)
        key = tostring(key or "")
        message = tostring(message or "")

        local blockSize = 64
        if #key > blockSize then
            key = hexToRaw(sha256(key, true))
        end
        if #key < blockSize then
            key = key .. string.rep("\0", blockSize - #key)
        end

        local inner = hexToRaw(sha256(xorPad(key, 0x36) .. message, true))
        return sha256(xorPad(key, 0x5c) .. inner, true)
    end

    local function randomNonceHex()
        if type(crypt) == "table" and type(crypt.generatebytes) == "function" then
            local ok, raw = pcall(crypt.generatebytes, 16)
            if ok and type(raw) == "string" then
                if #raw == 16 then
                    return (raw:gsub(".", function(c)
                        return string.format("%02x", string.byte(c))
                    end))
                end
                local hex = raw:lower():gsub("%s+", "")
                if hex:match("^[a-f0-9]+$") and #hex >= 32 then
                    return hex:sub(1, 32)
                end
            end
        end

        local guid = ""
        pcall(function()
            guid = HttpService:GenerateGUID(false)
        end)
        return sha256(tostring(guid) .. tostring(os.clock()) .. tostring(os.time()) .. tostring(math.random())):sub(1, 32)
    end

    local function httpPostJson(url, payload)
        local body = HttpService:JSONEncode(payload)
        local headers = {
            ["Content-Type"] = "application/json",
            ["Accept"] = "application/json",
        }
        local req = nil
        if type(syn) == "table" and type(syn.request) == "function" then
            req = syn.request
        elseif type(http) == "table" and type(http.request) == "function" then
            req = http.request
        elseif type(fluxus) == "table" and type(fluxus.request) == "function" then
            req = fluxus.request
        elseif type(http_request) == "function" then
            req = http_request
        elseif type(request) == "function" then
            req = request
        end

        if type(req) == "function" then
            local res = req({
                Url = url,
                url = url,
                Method = "POST",
                method = "POST",
                Headers = headers,
                headers = headers,
                Body = body,
                body = body,
                data = body,
            })
            if type(res) ~= "table" then
                error("http_post_bad_response")
            end
            return tostring(res.Body or res.body or res.Data or res.data or ""), tonumber(res.StatusCode or res.Status or res.status_code or res.status or 0) or 0
        end

        if type(game.HttpPost) == "function" then
            return tostring(game:HttpPost(url, body, "application/json") or ""), 200
        end

        error("no_http_post")
    end

    local function findWebSocketConnect()
        if type(WebSocket) == "table" and type(WebSocket.connect) == "function" then
            return function(url) return WebSocket.connect(url) end
        end
        if type(websocket) == "table" and type(websocket.connect) == "function" then
            return function(url) return websocket.connect(url) end
        end
        if type(syn) == "table" and type(syn.websocket) == "table" and type(syn.websocket.connect) == "function" then
            return function(url) return syn.websocket.connect(url) end
        end
        if type(WebSocket) == "function" then
            return function(url) return WebSocket(url) end
        end
        return nil
    end

    local function bindSignal(obj, fn)
        if obj == nil or type(fn) ~= "function" then
            return false, "empty"
        end

        local kind = type(obj)
        pcall(function()
            if typeof then
                kind = tostring(typeof(obj))
            end
        end)

        -- Pola executor yang paling umum: socket.OnMessage:Connect(fn)
        -- Dibuat pakai pcall supaya aman untuk userdata/custom signal.
        if kind == "RBXScriptSignal" then
            local ok, err = pcall(function()
                obj:Connect(fn)
            end)
            if ok then return true, "RBXScriptSignal:Connect" end
            return false, tostring(err)
        end

        local okGet, connectFn = pcall(function()
            return obj.Connect
        end)
        if okGet and type(connectFn) == "function" then
            local ok = pcall(function()
                obj:Connect(fn)
            end)
            if ok then return true, "Connect:colon" end

            ok = pcall(function()
                connectFn(obj, fn)
            end)
            if ok then return true, "Connect:dot_self" end

            ok = pcall(function()
                connectFn(fn)
            end)
            if ok then return true, "Connect:dot" end
        end

        local okGetLower, connectLower = pcall(function()
            return obj.connect
        end)
        if okGetLower and type(connectLower) == "function" then
            local ok = pcall(function()
                obj:connect(fn)
            end)
            if ok then return true, "connect:colon" end

            ok = pcall(function()
                connectLower(obj, fn)
            end)
            if ok then return true, "connect:dot_self" end

            ok = pcall(function()
                connectLower(fn)
            end)
            if ok then return true, "connect:dot" end
        end

        return false, kind
    end

    local function safeSendSocket(socket, text)
        if not socket or type(text) ~= "string" then
            return false, "invalid_socket_or_text"
        end

        if type(socket.Send) == "function" then
            local ok = pcall(function() socket:Send(text) end)
            if ok then return true end
            ok = pcall(function() socket.Send(text) end)
            if ok then return true end
        end

        if type(socket.send) == "function" then
            local ok = pcall(function() socket:send(text) end)
            if ok then return true end
            ok = pcall(function() socket.send(text) end)
            if ok then return true end
        end

        return false, "send_function_not_found"
    end

    local function safeCloseSocket(socket)
        if not socket then return end
        if type(socket.Close) == "function" then
            pcall(function() socket:Close() end)
            pcall(function() socket.Close() end)
        elseif type(socket.close) == "function" then
            pcall(function() socket:close() end)
            pcall(function() socket.close() end)
        end
    end

    local fpsState = { fps = 0, frames = 0, last = os.clock(), started = false }

    local function startFpsSampler()
        if fpsState.started then return end
        fpsState.started = true
        RunService.Heartbeat:Connect(function()
            fpsState.frames = fpsState.frames + 1
            local t = os.clock()
            local diff = t - fpsState.last
            if diff >= 1 then
                fpsState.fps = math.floor((fpsState.frames / diff) + 0.5)
                fpsState.frames = 0
                fpsState.last = t
            end
        end)
    end

    local function getMemoryMb()
        local ok, mb = pcall(function()
            return StatsService:GetTotalMemoryUsageMb()
        end)
        if ok and type(mb) == "number" then
            return math.floor(mb * 100) / 100
        end
        return nil
    end

    local function getPosition()
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local p = hrp.Position
        return {
            x = math.floor(p.X * 100) / 100,
            y = math.floor(p.Y * 100) / 100,
            z = math.floor(p.Z * 100) / 100,
        }
    end

    local function getHumanoidInfo()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then
            return { alive = false }
        end
        return {
            alive = hum.Health > 0,
            health = math.floor(hum.Health * 100) / 100,
            max_health = math.floor(hum.MaxHealth * 100) / 100,
            state = tostring(hum:GetState()),
        }
    end

    local function safeGameField(fieldName, fallback)
        local ok, res = pcall(function()
            return game[fieldName]
        end)
        if ok and res ~= nil then
            return res
        end
        return fallback
    end

    local function defaultStats(includePlayerList)
        startFpsSampler()

        local playerList = nil
        if includePlayerList == true then
            playerList = {}
            for _, p in ipairs(Players:GetPlayers()) do
                playerList[#playerList + 1] = {
                    user_id = p.UserId,
                    name = p.Name,
                    display_name = p.DisplayName,
                }
            end
        end

        local player = localPlayer()
        return {
            ts = now(),
            game = {
                place_id = safeGameField("PlaceId", 0),
                game_id = safeGameField("GameId", 0),
                job_id = safeGameField("JobId", ""),
                creator_id = safeGameField("CreatorId", 0),
            },
            server = {
                players = #Players:GetPlayers(),
                max_players = Players.MaxPlayers,
                player_list = playerList,
            },
            player = {
                user_id = player and player.UserId,
                userId = player and player.UserId,
                name = player and player.Name,
                username = player and player.Name,
                display_name = player and player.DisplayName,
                akun_game_id = player and tostring(player.UserId) or nil,
                akun_username = player and player.Name,
                team = player and player.Team and player.Team.Name or nil,
            },
            account = {
                user_id = player and player.UserId,
                userId = player and player.UserId,
                account_id = player and tostring(player.UserId) or nil,
                akun_game_id = player and tostring(player.UserId) or nil,
                username = player and player.Name,
                akun_username = player and player.Name,
                display_name = player and player.DisplayName,
            },
            local_player = {
                user_id = player and player.UserId,
                userId = player and player.UserId,
                name = player and player.Name,
                username = player and player.Name,
                display_name = player and player.DisplayName,
                akun_game_id = player and tostring(player.UserId) or nil,
                akun_username = player and player.Name,
                team = player and player.Team and player.Team.Name or nil,
                position = getPosition(),
                humanoid = getHumanoidInfo(),
            },
            position = getPosition(),
            performance = {
                fps = fpsState.fps,
                memory_mb = getMemoryMb(),
            },
            counters = {},
        }
    end

    ----------------------------------------------------------------
    -- GAG / generic asset collector
    -- Output dibuat mirip kebutuhan dashboard:
    -- stats.assets.overview.net_worth
    -- stats.assets.overview.sheckles
    -- stats.assets.overview.total_seeds
    -- stats.assets.items[]
    -- stats.assets.groups is RAM-only (for overview totals). Not sent on the wire.
    ----------------------------------------------------------------
    -- World normal = Sheckles; world Fall = Leaves (sama urutan AutoBuy._getMoney).
    local MONEY_STAT_NAMES = { "Leaves", "Sheckles", "Sheckle", "Money", "Cash", "Coins", "Coin" }
    local MONEY_ATTR_NAMES = { "Leaves", "Sheckles", "Sheckle", "Money", "Cash", "Coins" }

    local function parseNumberAny(v)
        if type(v) == "number" then return v end
        local raw = tostring(v or "")
        raw = raw:gsub(",", ""):gsub("%s+", "")
        if raw == "" then return nil end

        local lower = raw:lower()
        lower = lower:gsub("rp", ""):gsub("usd", "")
            :gsub("sheckles", ""):gsub("sheckle", "")
            :gsub("leaves", ""):gsub("leaf", "")
        lower = lower:gsub("[$¢₵]", "")

        local suffixMap = {
            k = 1e3, rb = 1e3, ribu = 1e3,
            m = 1e6, jt = 1e6, juta = 1e6,
            b = 1e9, t = 1e12,
        }

        local bestNum, bestSuffix = nil, nil
        for num, suffix in lower:gmatch("([%-]?%d+%.?%d*)([a-z]+)") do
            local mult = suffixMap[suffix]
            if mult then
                bestNum, bestSuffix = tonumber(num), suffix
            end
        end
        if bestNum then
            return bestNum * (suffixMap[bestSuffix] or 1)
        end

        local num = lower:match("[%-]?%d+%.?%d*")
        return tonumber(num)
    end

    local function formatShortNumber(n)
        n = tonumber(n) or 0
        local abs = math.abs(n)
        if abs >= 1e12 then return string.format("%.2fT", n / 1e12) end
        if abs >= 1e9 then return string.format("%.2fB", n / 1e9) end
        if abs >= 1e6 then return string.format("%.2fM", n / 1e6) end
        if abs >= 1e3 then return string.format("%.1fK", n / 1e3) end
        return tostring(math.floor(n))
    end

    local function readMoneyFromLeaderstats()
        -- leaderstats = angka penuh. Attribute kadang format pendek → salah hitung.
        local ls = LP:FindFirstChild("leaderstats")
        if ls then
            for _, name in ipairs(MONEY_STAT_NAMES) do
                local o = ls:FindFirstChild(name)
                if o and (o:IsA("IntValue") or o:IsA("NumberValue") or o:IsA("StringValue")) then
                    local v = parseNumberAny(o.Value)
                    if v ~= nil then
                        return v, name
                    end
                end
            end
        end

        for _, attrName in ipairs(MONEY_ATTR_NAMES) do
            local attr = LP:GetAttribute(attrName)
            local v = parseNumberAny(attr)
            if v ~= nil then
                return v, "attr:" .. attrName
            end
        end

        return nil, nil
    end

    local function isInsideOwnUi(inst)
        local cur = inst
        while cur do
            if cur.Name == "NodeHubNeonUI" or cur.Name == "NodeHubLoadingHost" or cur.Name == "NodeHubHostGui" then
                return true
            end
            cur = cur.Parent
        end
        return false
    end

    local function isGuiObjectVisible(inst)
        local cur = inst
        while cur do
            if cur:IsA("GuiObject") and cur.Visible == false then
                return false
            end
            cur = cur.Parent
        end
        return true
    end

    local function readMoneyFromGui()
        local pg = LP:FindFirstChild("PlayerGui")
        if not pg then return nil end

        local bestValue, bestScore = nil, -1
        for _, d in ipairs(pg:GetDescendants()) do
            if (d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox"))
                and not isInsideOwnUi(d)
                and isGuiObjectVisible(d) then
                local t = tostring(d.Text or "")
                local l = t:lower()
                local score = 0

                -- Prioritas tertinggi: teks currency yang benar-benar terlihat di HUD, contoh: 14.74K¢
                if l:find("¢", 1, true) or l:find("₵", 1, true) then
                    score = 100
                elseif l:find("sheck", 1, true) then
                    score = 80
                elseif l:find("leaf", 1, true) then
                    score = 80
                elseif l:find("$", 1, true) then
                    score = 40
                end

                if score > 0 then
                    local v = parseNumberAny(t)
                    if v ~= nil then
                        if score > bestScore then
                            bestScore, bestValue = score, v
                        elseif score == bestScore and bestValue == nil then
                            bestValue = v
                        end
                    end
                end
            end
        end

        return bestValue
    end

    local function callMoneyProvider(bridge)
        local providers = {}
        if bridge and type(bridge.getMoney) == "function" then providers[#providers + 1] = bridge.getMoney end
        if bridge and type(bridge.getSheckles) == "function" then providers[#providers + 1] = bridge.getSheckles end
        if type(G.__NODEHUB_GET_SHECKLES) == "function" then providers[#providers + 1] = G.__NODEHUB_GET_SHECKLES end
        if type(rawget(_G, "__NODEHUB_GET_SHECKLES")) == "function" then providers[#providers + 1] = rawget(_G, "__NODEHUB_GET_SHECKLES") end
        if type(G.__GAG2_GET_SHECKLES) == "function" then providers[#providers + 1] = G.__GAG2_GET_SHECKLES end
        if type(rawget(_G, "__GAG2_GET_SHECKLES")) == "function" then providers[#providers + 1] = rawget(_G, "__GAG2_GET_SHECKLES") end

        for _, fn in ipairs(providers) do
            local ok, value = pcall(fn, bridge)
            local n = parseNumberAny(value)
            if ok and n ~= nil then
                return n, "provider"
            end
        end
        return nil, nil
    end

    local function getSheckles(bridge)
        -- Sama AutoBuy: Leaves (Fall) / Sheckles (normal) dari leaderstats dulu.
        -- Provider opsional, lalu GUI fallback.
        local providerValue, providerSource = callMoneyProvider(bridge)
        if providerValue ~= nil then return providerValue, providerSource end

        local leader, leaderSrc = readMoneyFromLeaderstats()
        if leader ~= nil then return leader, leaderSrc or "leaderstats" end

        local guiValue = readMoneyFromGui()
        if guiValue ~= nil then return guiValue, "gui" end

        return 0, "empty"
    end

    local function getAutoGiftLikeModule()
        local names = {
            "AutoGiftModule", "AutoGift",
            "GiftMailModule", "GiftMail",
            "NormalGiftModule", "NormalGift",
        }

        for _, key in ipairs(names) do
            local v = G[key] or rawget(_G, key)
            if type(v) == "table" and type(v.BuildInventoryItems) == "function" then
                return v, key
            end
        end

        -- GAG2 sering baru expose module setelah ensure loaded.
        local ensureFn = G.__GAG2_ENSURE_LOADED_MODULE or rawget(_G, "__GAG2_ENSURE_LOADED_MODULE")
        if type(ensureFn) == "function" then
            for _, key in ipairs({ "AutoGift", "GiftMail", "NormalGift" }) do
                local ok, mod = pcall(ensureFn, key)
                if ok and type(mod) == "table" then
                    if type(mod.BuildInventoryItems) == "function" then
                        G[key] = mod
                        _G[key] = mod
                        if key == "AutoGift" then
                            G.AutoGiftModule = mod
                            _G.AutoGiftModule = mod
                        elseif key == "NormalGift" then
                            G.NormalGiftModule = mod
                            _G.NormalGiftModule = mod
                        end
                        return mod, key
                    end
                end
            end
        end

        return nil, nil
    end

    local function parseCountFromText(name, right)
        local n = parseNumberAny(right)
        if n ~= nil then return math.floor(n) end

        name = tostring(name or "")
        local c = name:match("[xX]%s*([%d%,%.]+)")
        if c then
            n = parseNumberAny(c)
            if n ~= nil then return math.floor(n) end
        end

        c = name:match("×%s*([%d%,%.]+)")
        if c then
            n = parseNumberAny(c)
            if n ~= nil then return math.floor(n) end
        end

        return 1
    end

    local function cleanItemName(name)
        name = tostring(name or "")
        -- Strip trailing stack counts: "x 3", "x 1.4k", "× 19.3K"
        name = name:gsub("%s*[xX]%s*[%d%,%.]+%s*[KkMmBbTt]?%s*$", "")
        name = name:gsub("%s*×%s*[%d%,%.]+%s*[KkMmBbTt]?%s*$", "")
        name = name:gsub("^%s+", ""):gsub("%s+$", "")
        return name
    end

    -- Fruit labels must not keep shop "Seed" suffix (Moon Bloom Seed → Moon Bloom).
    local function cleanFruitItemName(name)
        name = cleanItemName(name)
        name = name:gsub("%s+[Ss]eed%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
        return name
    end

    local function normalizeAssetCategory(category)
        category = tostring(category or "")
        if category == "HarvestedFruits" or category == "Fruits" or category == "Fruit" then
            return "fruits"
        end
        if category == "Seeds" or category == "Seed" then
            return "seeds"
        end
        if category == "Pets" or category == "Raccoons" or category == "Birds" then
            return "pets"
        end
        if category == "SeedPacks" or category == "SeedPack" then
            return "seed_packs"
        end
        if category == "Eggs" or category == "Egg" then
            return "eggs"
        end
        if category == "Props" or category == "Prop" then
            return "props"
        end
        if category == "Gear" or category == "Gears"
            or category == "Trowels" or category == "Sprinklers"
            or category == "WateringCans"
            or category == "EmptyPots" or category == "Crates"
            or category == "Gnomes" or category == "Mushrooms" then
            return "gear"
        end
        return category:lower()
    end

    local DEFAULT_ASSET_CATEGORIES = {
        "Seeds",
        -- HarvestedFruits: diisi collectFruitsByType (EspFruitBackpack), bukan AutoGift.
        "Pets",
        "Eggs",
        "SeedPacks",
        "Trowels",
        "Sprinklers",
        "WateringCans",
        "Props",
        "EmptyPots",
        "Crates",
        "Gnomes",
        "Mushrooms",
        "Raccoons",
    }

    local function assetValueOf(bridge, category, itemName, item)
        if bridge and type(bridge.assetValueProvider) == "function" then
            local ok, v = pcall(bridge.assetValueProvider, category, itemName, item, bridge)
            if ok and tonumber(v) then return tonumber(v) end
        end

        local cat = tostring(category or "")
        local isFruit = (cat == "HarvestedFruits" or cat == "Fruits" or cat == "Fruit")

        if type(item) == "table" then
            -- Grouped harvest: value sudah total per type dari EspFruitBackpack.
            if item.value_is_total == true or isFruit then
                local total = tonumber(item.total_value or item.value)
                if total and total > 0 then return total end
                if item.value_is_total == true then return 0 end
            end
            local total = tonumber(item.total_value)
            if total and total > 0 then return total end
            local v = tonumber(item.value or item.Value or item.Price or item.price)
            if v and v > 0 then return v end
            local per = tonumber(item.value_each or item.unit_value or item.UnitPrice or item.unitPrice or item.price_each)
            local cnt = tonumber(item.count or item.amount or 1) or 1
            if per and per > 0 then return per * cnt end
        end

        -- Non-fruit fallback only (fruit salah harga kalau unit×count di sini).
        if isFruit then
            return 0
        end

        return 0
    end

    -- Resolve rbxassetid the same way Backpack GUI assignToolData does.
    -- Fruit: FruitImages only (PlantImages is seed-shop art). Send IDs — never download images.
    local BIRD_ICON_ID = 80206395781273
    local _iconCache = {} -- "category|name" -> id or false
    local _sharedModCache = {}
    local _imageFolderCache = {} -- folderName -> Instance or false
    local _imageSetIndex = nil -- compactName -> numeric asset id

    local function parseAssetIdNumber(raw)
        if raw == nil then return nil end
        if type(raw) == "table" then
            return parseAssetIdNumber(raw.IMG or raw.Image or raw.ImageId or raw.Icon
                or raw.Value or raw.Id or raw.AssetId or raw.assetId)
        end
        if type(raw) == "number" then
            local n = math.floor(raw)
            if n > 0 then return n end
            return nil
        end
        local s = tostring(raw):match("^%s*(.-)%s*$") or ""
        if s == "" then return nil end
        local fromRbx = s:match("rbxassetid://(%d+)")
        if fromRbx then
            local n = tonumber(fromRbx)
            if n and n > 0 then return math.floor(n) end
        end
        local fromThumb = s:match("rbxthumb://[^%s\"']*id=(%d+)")
        if fromThumb then
            local n = tonumber(fromThumb)
            if n and n > 0 then return math.floor(n) end
        end
        if s:match("^%d+$") then
            local n = tonumber(s)
            if n and n > 0 then return math.floor(n) end
        end
        return nil
    end

    local function compactNameKey(s)
        return string.lower(tostring(s or "")):gsub("[%s_%-]+", "")
    end

    local function requireShared(name)
        local hit = _sharedModCache[name]
        if hit ~= nil and hit ~= false then
            return hit
        end
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local inst = sm and sm:FindFirstChild(name)
        if not inst and sm then
            inst = sm:FindFirstChild(name, true)
        end
        if not inst then
            return nil
        end
        local ok, mod = pcall(require, inst)
        if ok and mod ~= nil then
            _sharedModCache[name] = mod
            return mod
        end
        return nil
    end

    local function seedDataFolder(childName)
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local sd = sm and sm:FindFirstChild("SeedData")
        return sd and sd:FindFirstChild(childName)
    end

    -- 2D icon folders (PropImages, GearImages, …). Never use Mesh/Model AssetId.
    local function instanceAssetId(inst)
        if not inst then return nil end
        if inst:IsA("StringValue") or inst:IsA("IntValue") or inst:IsA("NumberValue") then
            return parseAssetIdNumber(inst.Value)
        end
        -- Skip Attribute AssetId: on 3D models that is the mesh, which Roblox thumbnails as PrivateImage.
        local id = parseAssetIdNumber(inst:GetAttribute("Image") or inst:GetAttribute("Icon"))
        if id then return id end
        if inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
            id = parseAssetIdNumber(inst.Image)
            if id then return id end
        end
        local child = inst:FindFirstChild("Image") or inst:FindFirstChild("Icon") or inst:FindFirstChild("IMG")
        if child and child ~= inst then
            return instanceAssetId(child)
        end
        return nil
    end

    local function imageFolder(folderName)
        local hit = _imageFolderCache[folderName]
        if hit ~= nil then
            return hit or nil
        end
        local function remember(inst)
            _imageFolderCache[folderName] = inst or false
            return inst
        end
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local sd = sm and sm:FindFirstChild("SeedData")
        local sharedData = ReplicatedStorage:FindFirstChild("SharedData")
        local resources = ReplicatedStorage:FindFirstChild("Resources")
        local candidates = {
            sm and sm:FindFirstChild(folderName),
            sd and sd:FindFirstChild(folderName),
            sharedData and sharedData:FindFirstChild(folderName),
            resources and resources:FindFirstChild(folderName),
            ReplicatedStorage:FindFirstChild("SeedData") and ReplicatedStorage.SeedData:FindFirstChild(folderName),
        }
        for i = 1, #candidates do
            if candidates[i] then return remember(candidates[i]) end
        end
        if sm then
            local deep = sm:FindFirstChild(folderName, true)
            if deep then return remember(deep) end
        end
        return remember(nil)
    end

    local function folderAssetId(folder, name)
        if not folder or name == nil or tostring(name) == "" then return nil end
        local inst = folder:FindFirstChild(tostring(name))
        if not inst then
            local want = string.lower(tostring(name))
            local wantCompact = compactNameKey(name)
            for _, child in ipairs(folder:GetChildren()) do
                if string.lower(child.Name) == want or compactNameKey(child.Name) == wantCompact then
                    inst = child
                    break
                end
            end
        end
        if not inst then return nil end
        return instanceAssetId(inst)
    end

    local function imageSetAssetId(name)
        if name == nil or tostring(name) == "" then return nil end
        if _imageSetIndex == nil then
            local idx = {}
            local function walk(node, hint)
                if type(node) == "string" or type(node) == "number" then
                    local id = parseAssetIdNumber(node)
                    if id and hint and hint ~= "" then
                        local compact = compactNameKey(hint)
                        if compact ~= "" then
                            idx[compact] = idx[compact] or id
                        end
                    end
                    return
                end
                if type(node) ~= "table" then return end
                local direct = node.Image or node.Icon or node.ImageId or node.IMG or node.Thumbnail or node.Value
                local id = parseAssetIdNumber(direct)
                local nameHint = tostring(hint or node.Name or node.name or node.Key or node.key or "")
                if id and nameHint ~= "" then
                    local compact = compactNameKey(nameHint)
                    if compact ~= "" then
                        idx[compact] = idx[compact] or id
                    end
                end
                for k, v in pairs(node) do
                    if type(k) == "string" or type(k) == "number" then
                        walk(v, tostring(k))
                    end
                end
            end
            local roots = {
                ReplicatedStorage:FindFirstChild("SharedModules"),
                ReplicatedStorage:FindFirstChild("Resources"),
                ReplicatedStorage:FindFirstChild("SharedData"),
            }
            for _, root in ipairs(roots) do
                local gis = root and root:FindFirstChild("GetImageSetData", true)
                if gis and gis:IsA("ModuleScript") then
                    local ok, data = pcall(require, gis)
                    if ok then walk(data, nil) end
                end
            end
            _imageSetIndex = idx
        end
        return _imageSetIndex[compactNameKey(name)]
    end

    local function findNamedChild(folder, name)
        if not folder or name == nil or tostring(name) == "" then return nil end
        local inst = folder:FindFirstChild(tostring(name))
        if inst then return inst end
        local want = string.lower(tostring(name))
        local wantCompact = compactNameKey(name)
        for _, child in ipairs(folder:GetChildren()) do
            if string.lower(child.Name) == want or compactNameKey(child.Name) == wantCompact then
                return child
            end
        end
        return nil
    end

    local function backpackAttrIconId(attrName, wantName)
        if not LP or wantName == nil or tostring(wantName) == "" then return nil end
        local wantCompact = compactNameKey(wantName)
        local function scan(container)
            if not container then return nil end
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") then
                    local attr = tool:GetAttribute(attrName)
                    if attr ~= nil and compactNameKey(attr) == wantCompact then
                        -- Backpack GUI uses BuildData.IMG for all Build tools; TextureId is the per-prop icon when set.
                        local id = parseAssetIdNumber(tool.TextureId)
                        if id then return id end
                        local icon = tool:FindFirstChild("Icon", true) or tool:FindFirstChild("Image", true)
                        id = instanceAssetId(icon)
                        if id then return id end
                    end
                end
            end
            return nil
        end
        return scan(LP:FindFirstChild("Backpack")) or scan(LP.Character)
    end

    local function propFolderAssetId(name)
        local folders = { "PropImages", "GearImages", "FenceImages", "CrateImages" }
        for i = 1, #folders do
            local id = folderAssetId(imageFolder(folders[i]), name)
            if id then return id end
        end
        return imageSetAssetId(name)
    end

    -- Only 2D ImageLabels on the prop model. Skip Mesh/Decal/AssetId (PrivateImage placeholders).
    local function propModelIconId(name)
        local assets = ReplicatedStorage:FindFirstChild("Assets")
        local folder = assets and assets:FindFirstChild("Props")
        local model = findNamedChild(folder, name)
        if not model then return nil end
        local id = parseAssetIdNumber(model:GetAttribute("Image") or model:GetAttribute("Icon"))
        if id then return id end
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("ImageLabel") or d:IsA("ImageButton") then
                local n = string.lower(d.Name)
                if n == "icon" or n == "image" or n == "img" or n == "thumbnail" then
                    id = parseAssetIdNumber(d.Image)
                    if id then return id end
                end
            end
        end
        return nil
    end

    local function rowsOf(mod)
        if type(mod) ~= "table" then return nil end
        if type(mod.Data) == "table" then return mod.Data end
        if type(mod.data) == "table" then return mod.data end
        return mod
    end

    local function namesEqual(nm, want, wantLow, wantCompact)
        if nm == nil then return false end
        nm = tostring(nm)
        return nm == want or string.lower(nm) == wantLow or compactNameKey(nm) == wantCompact
    end

    local function rowImageId(row, imageKeys)
        if type(row) ~= "table" then
            return parseAssetIdNumber(row)
        end
        for _, ik in ipairs(imageKeys) do
            local id = parseAssetIdNumber(row[ik])
            if id then return id end
        end
        return parseAssetIdNumber(row.IMG or row.Image or row.ImageId or row.Icon)
    end

    local function forEachRow(rows, fn)
        if type(rows) ~= "table" then return end
        local seen = {}
        local function visit(k, v)
            local mark = tostring(k) .. "\0" .. type(v)
            if seen[mark] then return end
            seen[mark] = true
            fn(k, v)
        end
        -- Luau generalized iteration (PropsFrame: for _, v in PropData.Data)
        pcall(function()
            for k, v in rows do
                visit(k, v)
            end
        end)
        for i, v in ipairs(rows) do
            visit(i, v)
        end
        for k, v in pairs(rows) do
            visit(k, v)
        end
    end

    local function findRowImage(mod, nameKeys, imageKeys, wantName)
        local rows = rowsOf(mod)
        if type(rows) ~= "table" or wantName == nil or tostring(wantName) == "" then return nil end
        local want = tostring(wantName)
        local wantLow = string.lower(want)
        local wantCompact = compactNameKey(want)
        local direct = rows[want]
        if direct == nil and wantCompact ~= "" then
            forEachRow(rows, function(k, row)
                if direct ~= nil then return end
                if namesEqual(k, want, wantLow, wantCompact) then
                    direct = row
                end
            end)
        end
        if direct ~= nil then
            local id = rowImageId(direct, imageKeys)
            if id then return id end
        end
        local found = nil
        forEachRow(rows, function(k, row)
            if found then return end
            if namesEqual(k, want, wantLow, wantCompact) then
                local id = rowImageId(row, imageKeys)
                if id then found = id return end
            end
            if type(row) == "table" then
                local nm = nil
                for _, nk in ipairs(nameKeys) do
                    if row[nk] ~= nil then
                        nm = tostring(row[nk])
                        break
                    end
                end
                if nm and namesEqual(nm, want, wantLow, wantCompact) then
                    local id = rowImageId(row, imageKeys)
                    if id then found = id end
                end
            end
        end)
        return found
    end

    local function getDataImage(mod, name)
        if type(mod) ~= "table" or name == nil or tostring(name) == "" then
            return nil
        end
        local getters = { mod.GetData, mod.getData, mod.Get, mod.Find }
        for i = 1, #getters do
            local fn = getters[i]
            if type(fn) == "function" then
                local calls = {
                    function() return fn(name) end,
                    function() return fn(mod, name) end,
                }
                for _, call in ipairs(calls) do
                    local ok, data = pcall(call)
                    if ok and data ~= nil then
                        local id = parseAssetIdNumber(
                            type(data) == "table" and (data.IMG or data.Image or data.ImageId or data.Icon) or data
                        )
                        if id then return id end
                    end
                end
            end
        end
        return nil
    end

    local function staticDataImage(mod)
        if type(mod) ~= "table" then return nil end
        local data = mod.Data
        if type(data) == "table" then
            return parseAssetIdNumber(data.IMG or data.Image)
        end
        return parseAssetIdNumber(mod.IMG or mod.Image)
    end

    local function itemNameVariants(itemName, category)
        local n = cleanItemName(itemName)
        if n == "" then return {} end
        local out, seen = {}, {}
        local function push(v)
            v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if v == "" or seen[v] then return end
            seen[v] = true
            out[#out + 1] = v
        end
        push(n)
        -- Strip trait/size suffixes from AutoGift/Webhook: "Big Bee ( Big )" / "Bee ( Gold , Big )"
        local noTraits = n
        while true do
            local stripped = noTraits:gsub("%s*%b()%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if stripped == noTraits or stripped == "" then break end
            noTraits = stripped
            push(noTraits)
        end
        local noSeed = noTraits:gsub("%s+[Ss]eed%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if noSeed ~= "" then push(noSeed) end
        -- Compact forms: "Big Bee" -> "BigBee" (matches some catalog/AssetName keys)
        for i = 1, #out do
            local compact = out[i]:gsub("[%s_%-]+", "")
            if compact ~= "" then push(compact) end
        end
        local cat = tostring(category or "")
        if (cat == "Seeds" or cat == "Seed") and not string.find(string.lower(noTraits), "seed", 1, true) then
            push(noTraits .. " Seed")
            if noSeed ~= "" and noSeed ~= noTraits then push(noSeed .. " Seed") end
        end
        return out
    end

    -- PropData.lua: IMG = SharedModules.PropImages:FindFirstChild(name).Value
    local function resolvePropDataImage(itemName, category)
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local folder = sm and sm:FindFirstChild("PropImages")
        if not folder then return nil end
        for _, variant in ipairs(itemNameVariants(itemName, category)) do
            local inst = folder:FindFirstChild(tostring(variant))
            if not inst then
                local want = string.lower(tostring(variant))
                local wantCompact = compactNameKey(variant)
                for _, child in ipairs(folder:GetChildren()) do
                    if string.lower(child.Name) == want or compactNameKey(child.Name) == wantCompact then
                        inst = child
                        break
                    end
                end
            end
            if inst then
                local raw = nil
                if inst:IsA("StringValue") or inst:IsA("IntValue") or inst:IsA("NumberValue") then
                    raw = inst.Value
                end
                local id = parseAssetIdNumber(raw)
                if id then return id end
            end
        end
        return nil
    end

    local function resolvePetAssetId(itemName)
        local plv = G.PetListView or rawget(_G, "PetListView")
        if type(plv) ~= "table" or type(plv.getPetIcon) ~= "function" then
            return nil
        end
        for _, variant in ipairs(itemNameVariants(itemName, "Pets")) do
            local ok, icon = pcall(plv.getPetIcon, variant)
            if ok then
                local id = parseAssetIdNumber(icon)
                if id then return id end
            end
        end
        return nil
    end

    local function extractAssetIdFromItemTable(item)
        if type(item) ~= "table" then return nil end
        local keys = {
            "asset_id", "assetId", "AssetId", "icon_id", "iconId", "IconId",
            "icon", "Image", "image", "ImageId", "image_id", "Thumbnail", "thumbnail",
            "TextureId", "textureId",
        }
        for _, k in ipairs(keys) do
            local id = parseAssetIdNumber(item[k])
            if id then return id end
        end
        return nil
    end

    local function resolveItemAssetId(category, itemName, item)
        local cat = tostring(category or "")
        local group = normalizeAssetCategory(cat)
        -- Props: ignore item.Image/AssetId — those are often 3D mesh ids (PrivateImage).
        if group ~= "props" then
            local fromItem = extractAssetIdFromItemTable(item)
            if fromItem then return fromItem end
        end

        local name = (group == "fruits") and cleanFruitItemName(itemName) or cleanItemName(itemName)
        if name == "" then return nil end

        local cacheKey = cat .. "|" .. name
        local cached = _iconCache[cacheKey]
        if cached ~= nil then
            return cached or nil
        end

        local function remember(id)
            -- Do not cache misses: PropData/SharedModules may not be ready on first stats tick.
            if id then
                _iconCache[cacheKey] = id
            end
            return id
        end

        if group == "fruits" then
            return remember(folderAssetId(seedDataFolder("FruitImages"), name))
        end

        if group == "seeds" then
            local folder = seedDataFolder("SeedImages")
            local id = folderAssetId(folder, name)
            if id then return remember(id) end
            local stripped = name:gsub("%s+[Ss]eed%s*$", "")
            if stripped ~= "" and stripped ~= name then
                id = folderAssetId(folder, stripped)
                if id then return remember(id) end
            else
                id = folderAssetId(folder, name .. " Seed")
                if id then return remember(id) end
            end
            return remember(nil)
        end

        if group == "pets" then
            if cat == "Birds" or cat == "Bird" then
                return remember(BIRD_ICON_ID)
            end
            if cat == "Raccoons" or cat == "Raccoon" then
                local id = findRowImage(requireShared("RaccoonData"), { "Name" }, { "IMG", "Image" }, name)
                if id then return remember(id) end
            end
            local petId = resolvePetAssetId(name)
            if petId then return remember(petId) end
            if type(item) == "table" and item.key and tostring(item.key) ~= name then
                petId = resolvePetAssetId(item.key)
                if petId then return remember(petId) end
            end
            return remember(nil)
        end

        if group == "eggs" then
            return remember(getDataImage(requireShared("EggData"), name))
        end

        if group == "seed_packs" then
            local id = getDataImage(requireShared("SeedPackData"), name)
                or getDataImage(requireShared("CornucopiaData"), name)
            return remember(id)
        end

        local id = nil
        if cat == "Sprinklers" or cat == "Sprinkler" then
            id = findRowImage(requireShared("SprinklerData"), { "SprinklerName", "Name" }, { "Image", "IMG" }, name)
        elseif cat == "Trowels" or cat == "Trowel" then
            id = staticDataImage(requireShared("TrowelData"))
        elseif cat == "WateringCans" or cat == "WateringCan" then
            id = findRowImage(requireShared("WateringcanData"), { "Name" }, { "Image", "IMG" }, name)
        elseif cat == "Mushrooms" or cat == "Mushroom" then
            id = findRowImage(requireShared("MushroomData"), { "Name" }, { "IMG", "Image" }, name)
                or propFolderAssetId(name)
        elseif cat == "Gnomes" or cat == "Gnome" then
            id = findRowImage(requireShared("GnomeData"), { "Name" }, { "IMG", "Image" }, name)
                or propFolderAssetId(name)
        elseif cat == "Crates" or cat == "Crate" then
            id = getDataImage(requireShared("CrateData"), name)
                or getDataImage(requireShared("ChestData"), name)
        elseif cat == "EmptyPots" or cat == "EmptyPot" then
            id = propFolderAssetId(name)
                or backpackAttrIconId("EmptyPot", name)
                or propModelIconId(name)
        elseif cat == "Props" or cat == "Prop" then
            id = resolvePropDataImage(itemName, cat)
            if not id and type(item) == "table" and item.key then
                id = resolvePropDataImage(item.key, cat)
            end
        else
            id = findRowImage(requireShared("SprinklerData"), { "SprinklerName", "Name" }, { "Image", "IMG" }, name)
                or findRowImage(requireShared("RakeData"), { "RakeName", "Name" }, { "Image", "IMG" }, name)
                or findRowImage(requireShared("WateringcanData"), { "Name" }, { "Image", "IMG" }, name)
                or findRowImage(requireShared("MushroomData"), { "Name" }, { "IMG", "Image" }, name)
                or findRowImage(requireShared("GnomeData"), { "Name" }, { "IMG", "Image" }, name)
                or findRowImage(requireShared("TeleporterData"), { "TeleporterName", "Name" }, { "Image", "IMG" }, name)
                or findRowImage(requireShared("MuffinData"), { "Name" }, { "IMG", "Image" }, name)
                or getDataImage(requireShared("SeedPackData"), name)
                or getDataImage(requireShared("EggData"), name)
                or getDataImage(requireShared("CrateData"), name)
                or getDataImage(requireShared("ChestData"), name)
                or getDataImage(requireShared("CornucopiaData"), name)
                or propFolderAssetId(name)
            if not id then
                local low = string.lower(name)
                if string.find(low, "shovel", 1, true) then
                    id = staticDataImage(requireShared("ShovelData"))
                elseif string.find(low, "trowel", 1, true) then
                    id = staticDataImage(requireShared("TrowelData"))
                elseif string.find(low, "crowbar", 1, true) then
                    id = staticDataImage(requireShared("CrowbarData"))
                elseif string.find(low, "build", 1, true) then
                    id = staticDataImage(requireShared("BuildData"))
                elseif string.find(low, "bird", 1, true) then
                    id = BIRD_ICON_ID
                end
            end
        end

        return remember(id)
    end

    -- Rarity string helpers (catalog lookups only — no invented tiers).
    local _shopRarityMap = nil

    local _KNOWN_RARITY = {
        common = "Common",
        uncommon = "Uncommon",
        rare = "Rare",
        epic = "Epic",
        legendary = "Legendary",
        mythic = "Mythic",
        mythical = "Mythic",
        super = "Super",
        prismatic = "Prismatic",
        divine = "Divine",
        exclusive = "Exclusive",
        transcendent = "Transcendent",
    }

    local function rarityKey(s)
        return string.lower(tostring(s or "")):gsub("[^a-z0-9]", "")
    end

    local function isCountLikeRarity(s)
        local low = string.lower(tostring(s or "")):gsub("^%s+", ""):gsub("%s+$", "")
        if low == "" then return true end
        -- AutoGift/shop "right" is often stack qty: "1.4k", "x 3.7k", "19.3K"
        if low:match("^x%s*[%d%.,]+%s*[kmbt]?$") then return true end
        if low:match("^[%d%.,]+%s*[kmbt]$") then return true end
        if low:match("^[%d%.,]+$") then return true end
        if tonumber(low) ~= nil then return true end
        return false
    end

    local function cleanRarityText(raw)
        if raw == nil then return nil end
        local s = tostring(raw):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return nil end
        -- Dropdown "right" often looks like "Legendary · 5000"
        local before = s:match("^(.-)%s*[·|]%s*")
        if before and before ~= "" then
            s = before:gsub("^%s+", ""):gsub("%s+$", "")
        end
        if s == "" or isCountLikeRarity(s) then return nil end
        local known = _KNOWN_RARITY[rarityKey(s)]
        if known then return known end
        -- Allow other catalog tiers, but reject mostly-numeric junk
        local low = string.lower(s)
        if low:match("%d") and not low:match("[a-z].*[a-z]") then return nil end
        return s
    end

    -- Explicit rarity fields only — never treat inventory `right` (stack count) as rarity.
    local function extractRarityFromItemTable(item)
        if type(item) ~= "table" then return nil end
        for _, k in ipairs({ "rarity", "Rarity", "DisplayRarity", "display_rarity" }) do
            local r = cleanRarityText(item[k])
            if r then return r end
        end
        local raw = item.raw
        if type(raw) == "table" then
            local r = cleanRarityText(raw.rarity or raw.Rarity or raw.DisplayRarity)
            if r then return r end
            if type(raw.raw) == "table" then
                r = cleanRarityText(raw.raw.Rarity or raw.raw.rarity)
                if r then return r end
            end
            -- Shop dropdown rows may put "Legendary · 5000" in right under raw
            r = cleanRarityText(raw.right)
            if r then return r end
        end
        -- Last resort: item.right only when it is a real tier (e.g. "Legendary · 5000")
        return cleanRarityText(item.right)
    end

    local function resolvePetRarity(itemName)
        local plv = G.PetListView or rawget(_G, "PetListView")
        if type(plv) ~= "table" or type(plv.getPetRarity) ~= "function" then
            return nil
        end
        for _, variant in ipairs(itemNameVariants(itemName, "Pets")) do
            local ok, rarity = pcall(plv.getPetRarity, variant)
            if ok then
                local r = cleanRarityText(rarity)
                if r then return r end
            end
        end
        return nil
    end

    local function resolveSeedFruitRarity(itemName, category)
        local fsv = G.FruitSellValue or rawget(_G, "FruitSellValue")
        if type(fsv) == "table" and type(fsv.getRarity) == "function" then
            for _, variant in ipairs(itemNameVariants(itemName, category)) do
                local ok, rarity = pcall(fsv.getRarity, variant)
                if ok then
                    local r = cleanRarityText(rarity)
                    if r then return r end
                end
            end
        end
        local plv = G.PlantListView or rawget(_G, "PlantListView")
        if type(plv) == "table" then
            if type(plv.findBySeedName) == "function" then
                for _, variant in ipairs(itemNameVariants(itemName, category)) do
                    local ok, info = pcall(plv.findBySeedName, variant)
                    if ok and type(info) == "table" then
                        local r = cleanRarityText(info.Rarity or info.rarity
                            or (type(info.raw) == "table" and (info.raw.Rarity or info.raw.rarity)))
                        if r then return r end
                    end
                end
            end
            -- Walk catalog once with compact/lower keys (same SeedData source as FSV)
            if type(plv.getCatalogMap) == "function" then
                local okMap, cmap = pcall(plv.getCatalogMap)
                if okMap and type(cmap) == "table" then
                    local want = {}
                    for _, variant in ipairs(itemNameVariants(itemName, category)) do
                        want[string.lower(variant)] = true
                        want[compactNameKey(variant)] = true
                    end
                    for seedName, info in pairs(cmap) do
                        local low = string.lower(tostring(seedName))
                        local compact = compactNameKey(seedName)
                        if want[low] or want[compact] then
                            if type(info) == "table" then
                                local r = cleanRarityText(info.Rarity or info.rarity
                                    or (type(info.raw) == "table" and (info.raw.Rarity or info.raw.rarity)))
                                if r then return r end
                            end
                        end
                        if type(info) == "table" then
                            local sn = tostring(info.SeedName or info.Name or "")
                            if sn ~= "" and (want[string.lower(sn)] or want[compactNameKey(sn)]) then
                                local r = cleanRarityText(info.Rarity or info.rarity
                                    or (type(info.raw) == "table" and (info.raw.Rarity or info.raw.rarity)))
                                if r then return r end
                            end
                        end
                    end
                end
            end
        end
        return nil
    end

    local function ingestShopRarityItems(map, items)
        if type(items) ~= "table" then return end
        for _, it in ipairs(items) do
            if type(it) == "table" then
                local r = nil
                if type(it.raw) == "table" then
                    r = cleanRarityText(it.raw.rarity or it.raw.Rarity
                        or (type(it.raw.raw) == "table" and (it.raw.raw.Rarity or it.raw.raw.rarity)))
                end
                if not r then r = cleanRarityText(it.rarity or it.Rarity) end
                -- `right` is often qty; cleanRarityText rejects count-like values
                if not r then r = cleanRarityText(it.right) end
                if r then
                    local key = tostring(it.key or "")
                    local name = tostring(it.name or ""):gsub("%s*[·|].*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if key ~= "" then
                        map[string.lower(key)] = r
                        map[compactNameKey(key)] = r
                    end
                    if name ~= "" then
                        map[string.lower(name)] = map[string.lower(name)] or r
                        map[compactNameKey(name)] = map[compactNameKey(name)] or r
                    end
                end
            end
        end
    end

    local function getShopRarityMap()
        if _shopRarityMap then return _shopRarityMap end
        local map = {}
        local slv = G.ShopListView or rawget(_G, "ShopListView")
        if type(slv) == "table" then
            for _, fnName in ipairs({
                "buildGearItems", "buildPropsItems", "buildCrateItems",
                "buildEggItems", "buildSeedPackItems",
            }) do
                local fn = slv[fnName]
                if type(fn) == "function" then
                    local ok, items = pcall(fn)
                    if ok then ingestShopRarityItems(map, items) end
                end
            end
        end
        _shopRarityMap = map
        return map
    end

    local function resolveShopCatalogRarity(itemName, category)
        local map = getShopRarityMap()
        for _, variant in ipairs(itemNameVariants(itemName, category)) do
            local r = map[string.lower(variant)] or map[compactNameKey(variant)]
            if r then return r end
        end
        return nil
    end

    local function resolveItemRarity(category, itemName, item)
        local cat = tostring(category or "")
        local group = normalizeAssetCategory(cat)
        local names = { tostring(itemName or "") }
        if type(item) == "table" and item.key and tostring(item.key) ~= tostring(itemName) then
            names[#names + 1] = tostring(item.key)
        end

        local function tryNames(resolver)
            for _, n in ipairs(names) do
                if n ~= "" then
                    local r = resolver(n)
                    if r then return r end
                end
            end
            return nil
        end

        -- Prefer the same catalog sources (FruitSellValue / PlantListView / shop / pets)
        -- before any inventory-row fields that may carry stack counts in `right`.
        local catalogRarity = nil
        if group == "pets" or cat == "Pets" or cat == "Raccoons" or cat == "Birds" then
            catalogRarity = tryNames(resolvePetRarity)
        elseif group == "seeds" or group == "fruits" then
            catalogRarity = tryNames(function(n) return resolveSeedFruitRarity(n, category) end)
        elseif group == "gear" or group == "eggs" or group == "seed_packs" then
            catalogRarity = tryNames(function(n) return resolveShopCatalogRarity(n, category) end)
        else
            catalogRarity = tryNames(function(n) return resolveSeedFruitRarity(n, category) end)
                or tryNames(function(n) return resolveShopCatalogRarity(n, category) end)
                or tryNames(resolvePetRarity)
        end
        if catalogRarity then return catalogRarity end

        return extractRarityFromItemTable(item)
    end

    local function addAssetItem(assets, bridge, category, itemName, key, count, item)
        local group = normalizeAssetCategory(category)
        count = math.max(0, tonumber(count) or 0)
        if count <= 0 then return end

        local value = assetValueOf(bridge, category, itemName, item)
        local assetId = resolveItemAssetId(category, itemName, item)
        local rarity = resolveItemRarity(category, itemName, item)

        local row = {
            category = category,
            group = group,
            key = tostring(key or itemName),
            name = tostring(itemName or key or ""),
            count = count,
            amount = count,
            value = value,
        }
        if type(item) == "table" and item.value_is_total == true then
            row.value_is_total = true
        end
        if type(item) == "table" and item.value_label then
            row.value_label = tostring(item.value_label)
        elseif value > 0 then
            row.value_label = formatShortNumber(value)
        end

        if assetId then
            row.asset_id = assetId
            row.icon = "rbxassetid://" .. tostring(assetId)
        end
        if rarity and rarity ~= "" then
            row.rarity = rarity
        end

        assets.items[#assets.items + 1] = row
        assets.groups[group] = assets.groups[group] or { count = 0, value = 0, items = {} }
        assets.groups[group].count = assets.groups[group].count + count
        assets.groups[group].value = assets.groups[group].value + value
        assets.groups[group].items[#assets.groups[group].items + 1] = row

        assets.total_items = assets.total_items + count
        assets.total_value = assets.total_value + value
    end

    local function collectFromAutoGiftModule(bridge, assets)
        local mod, modName = getAutoGiftLikeModule()
        if not mod then return false, "AutoGiftModule_not_found" end

        assets.source = modName

        local categories = bridge and type(bridge.assetCategories) == "table" and bridge.assetCategories or DEFAULT_ASSET_CATEGORIES

        if type(mod.GetCategoryDefs) == "function" then
            local ok, defs = pcall(mod.GetCategoryDefs, mod)
            if ok and type(defs) == "table" and #defs > 0 and not (bridge and type(bridge.assetCategories) == "table") then
                categories = {}
                for _, def in ipairs(defs) do
                    if type(def) == "table" and type(def.key) == "string" and def.key ~= "" then
                        categories[#categories + 1] = def.key
                    end
                end
            end
        end

        local readCount = 0

        for _, category in ipairs(categories) do
            -- Fruit value/type dihitung terpisah (FruitSellValue + backpack tools), bukan lewat AutoGift.
            local catNorm = tostring(category or "")
            if catNorm == "HarvestedFruits" or catNorm == "Fruits" or catNorm == "Fruit" then
                continue
            end

            local ok, items = pcall(function()
                return mod:BuildInventoryItems(category)
            end)

            if not ok or type(items) ~= "table" then
                ok, items = pcall(function()
                    return mod.BuildInventoryItems(category)
                end)
            end

            if ok and type(items) == "table" then
                for _, it in ipairs(items) do
                    if type(it) == "table" then
                        local rawName = it.name or it.label or it.display or it.DisplayName or it.key
                        local name = cleanItemName(rawName)
                        local count = tonumber(it.count or it.amount or it.quantity or it.qty)
                            or parseCountFromText(rawName, it.right)
                        if name ~= "" and count and count > 0 then
                            local tmp = {}
                            for k, v in pairs(it) do tmp[k] = v end
                            tmp.count = count
                            addAssetItem(assets, bridge, category, name, it.key or name, count, tmp)
                            readCount = readCount + 1
                        end
                    end
                end
            end
        end

        return readCount > 0, "items=" .. tostring(readCount)
    end

    -- Fruit per-type: HANYA EspFruitBackpack (badge S). AutoGift tidak ikut.
    local function collectFruitsByType(bridge, assets)
        if type(assets) ~= "table" then return false, "assets_invalid" end
        local ebp = G.EspFruitBackpack or rawget(_G, "EspFruitBackpack")
        if type(ebp) ~= "table" then
            return false, "EspFruitBackpack_missing"
        end

        local result = nil
        local getByType = ebp.GetValueByType or ebp.getValueByType
        if type(getByType) == "function" then
            local ok, res = pcall(getByType, ebp, { force = false })
            if not ok or type(res) ~= "table" then
                ok, res = pcall(getByType, { force = false })
            end
            if ok and type(res) == "table" and type(res.rows) == "table" then
                result = res
            end
        end

        -- Fallback ringan: Peek total saja (jangan ScanFruits+GetEntryPrice per buah = spike).
        if not result then
            local peek = ebp.PeekBackpackValue or ebp.peekBackpackValue
            if type(peek) == "function" then
                local okPeek, peekRes = pcall(peek, ebp)
                if not okPeek or type(peekRes) ~= "table" then
                    okPeek, peekRes = pcall(peek)
                end
                if okPeek and type(peekRes) == "table" and (tonumber(peekRes.total) or 0) > 0 then
                    assets.backpack_summary = {
                        source = "EspFruitBackpack.PeekBackpackValue",
                        fruits = tonumber(peekRes.count) or 0,
                        count = tonumber(peekRes.count) or 0,
                        value = tonumber(peekRes.total) or 0,
                        total = tonumber(peekRes.total) or 0,
                        ready = peekRes.ready == true,
                    }
                    return false, "GetValueByType_missing_used_peek"
                end
            end
            return false, "GetValueByType_failed"
        end

        if type(result) ~= "table" or type(result.rows) ~= "table" then
            return false, "GetValueByType_failed"
        end

        local espTotal = tonumber(result.total) or 0
        local espCount = tonumber(result.count) or 0
        local pricesPending = espCount > 0 and espTotal <= 0 and result.ready ~= true

        -- Harga belum siap: tetap kirim fruit rows (count) + peek total buat chip Backpack.
        -- Jangan abort — abort bikin payload tanpa fruit → web games detail wipe Fruits tab.
        if pricesPending then
            local peek = ebp.PeekBackpackValue or ebp.peekBackpackValue
            if type(peek) == "function" then
                local okPeek, peekRes = pcall(peek, ebp)
                if not okPeek or type(peekRes) ~= "table" then
                    okPeek, peekRes = pcall(peek)
                end
                if okPeek and type(peekRes) == "table" then
                    local peekTotal = tonumber(peekRes.total) or 0
                    local peekCount = tonumber(peekRes.count) or 0
                    if peekTotal > 0 then
                        espTotal = peekTotal
                        if peekCount > 0 then espCount = peekCount end
                        assets.backpack_summary = {
                            source = "EspFruitBackpack.PeekBackpackValue",
                            fruits = espCount,
                            count = espCount,
                            value = peekTotal,
                            total = peekTotal,
                            ready = peekRes.ready == true,
                        }
                    end
                end
            end
        end

        -- Buang fruit rows lama, ganti dari ESP.
        local kept = {}
        local removedCount, removedValue = 0, 0
        for _, row in ipairs(assets.items or {}) do
            if type(row) == "table" and normalizeAssetCategory(row.category or row.group) == "fruits" then
                removedCount += math.max(0, tonumber(row.count or row.amount) or 0)
                removedValue += math.max(0, tonumber(row.value or row.total_value) or 0)
            elseif type(row) == "table" then
                kept[#kept + 1] = row
            end
        end
        assets.items = kept
        assets.total_items = math.max(0, (tonumber(assets.total_items) or 0) - removedCount)
        assets.total_value = math.max(0, (tonumber(assets.total_value) or 0) - removedValue)
        if type(assets.groups) == "table" then
            assets.groups.fruits = { count = 0, value = 0, items = {} }
        end

        local n = 0
        local sumValue, sumCount = 0, 0
        for _, slot in ipairs(result.rows) do
            if type(slot) == "table" then
                local name = cleanFruitItemName(slot.name or slot.key or "")
                local cnt = math.floor(tonumber(slot.count) or 0)
                local val = math.floor(tonumber(slot.value or slot.total_value) or 0)
                if name ~= "" and cnt > 0 then
                    addAssetItem(assets, bridge, "HarvestedFruits", name, name, cnt, {
                        count = cnt,
                        amount = cnt,
                        value = val,
                        total_value = val,
                        value_is_total = true,
                        value_label = formatShortNumber(val),
                    })
                    n += 1
                    sumCount += cnt
                    sumValue += val
                end
            end
        end

        -- Overview/chip: prefer penjumlahan value per type (sumValue) kalau harga tipe siap.
        -- Peek hanya fallback saat prices pending / sum masih 0.
        if espCount <= 0 then espCount = sumCount end
        local peekTotal = 0
        do
            local peek = ebp.PeekBackpackValue or ebp.peekBackpackValue
            if type(peek) == "function" then
                local okPeek, peekRes = pcall(peek, ebp)
                if not okPeek or type(peekRes) ~= "table" then
                    okPeek, peekRes = pcall(peek)
                end
                if okPeek and type(peekRes) == "table" and peekRes.ready == true then
                    peekTotal = tonumber(peekRes.total) or 0
                    local pc = tonumber(peekRes.count) or 0
                    if pc > 0 then espCount = pc end
                end
            end
        end
        if peekTotal <= 0 then peekTotal = espTotal end
        local overviewFruitValue = 0
        if sumValue > 0 and not pricesPending then
            overviewFruitValue = sumValue
        elseif peekTotal > 0 then
            overviewFruitValue = peekTotal
        elseif sumValue > 0 then
            overviewFruitValue = sumValue
        end
        -- Jangan kirim value=0 ke overview kalau fruit masih ada (harga pending).
        if overviewFruitValue <= 0 and espCount > 0 then
            local prevOv = type(assets.overview) == "table" and tonumber(assets.overview.fruit_value_backpack) or 0
            if prevOv > 0 then overviewFruitValue = prevOv end
        end
        -- Count overview ikut sum tipe kalau sudah ada rows.
        if sumCount > 0 then espCount = sumCount end
        assets.backpack_summary = {
            source = tostring(result.source or "EspFruitBackpack"),
            fruits = espCount,
            count = espCount,
            value = overviewFruitValue,
            total = overviewFruitValue,
            ready = overviewFruitValue > 0,
            types_value = sumValue,
            peek_value = peekTotal,
            prices_pending = pricesPending == true or (espCount > 0 and overviewFruitValue <= 0),
        }
        assets.fruit_value_source = tostring(result.source or "EspFruitBackpack")
        assets.fruit_types_total_value = sumValue
        assets.fruit_types_total_count = sumCount
        local note = tostring(assets.source_note or "")
        if note ~= "" then note = note .. ";" end
        assets.source_note = note .. "fruit_value=EspFruitBackpack"
            .. (pricesPending and ";fruit_prices_pending" or "")
            .. (sumValue > 0 and peekTotal > sumValue * 1.25 and ";fruit_types_partial" or "")
        return n > 0, pricesPending and ("fruit_types_pending=" .. tostring(n)) or ("fruit_types=" .. tostring(n))
    end

    local function guessCategoryFromToolName(name)
        local l = tostring(name or ""):lower()
        if l:find("seed pack", 1, true) or l:find("seedpack", 1, true) then return "SeedPacks" end
        if l:find("seed", 1, true) then return "Seeds" end
        if l:find("egg", 1, true) then return "Eggs" end
        if l:find("pet", 1, true) then return "Pets" end
        if l:find("sprinkler", 1, true) or l:find("trowel", 1, true)
            or l:find("shovel", 1, true) or l:find("gear", 1, true)
            or l:find("pot", 1, true) then return "Gear" end
        return "HarvestedFruits"
    end

    local function collectFromBackpackTools(bridge, assets)
        local function scan(root)
            if not root then return end
            for _, inst in ipairs(root:GetChildren()) do
                if inst:IsA("Tool") then
                    local name = tostring(inst:GetAttribute("ItemName") or inst:GetAttribute("Seed") or inst:GetAttribute("Egg") or inst.Name or "")
                    local count = tonumber(inst:GetAttribute("Count") or inst:GetAttribute("Amount") or inst:GetAttribute("Quantity")) or parseCountFromText(name, nil) or 1
                    name = cleanItemName(name)
                    if name ~= "" then
                        local category = tostring(inst:GetAttribute("Category") or inst:GetAttribute("ItemCategory") or guessCategoryFromToolName(name))
                        addAssetItem(assets, bridge, category, name, inst:GetAttribute("UUID") or inst.Name, count, {
                            count = count,
                            value = tonumber(inst:GetAttribute("Value") or inst:GetAttribute("Price")) or nil,
                        })
                    end
                end
            end
        end

        scan(LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack"))
        scan(LP.Character)

        return #assets.items > 0, "tools=" .. tostring(#assets.items)
    end

    local function collectGardenSummary(bridge)
        local eg = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
        if type(eg) ~= "table" then
            return nil, "EspFruitGarden_not_found"
        end

        if type(eg.ListGardenFruitsByPlant) ~= "function" then
            return nil, "ListGardenFruitsByPlant_not_found"
        end

        -- Jangan force=true tiap assets tick (itu scan garden berat → CPU spike).
        local ok, result = pcall(function()
            return eg:ListGardenFruitsByPlant({ force = false })
        end)
        if not ok or type(result) ~= "table" then
            ok, result = pcall(function()
                return eg.ListGardenFruitsByPlant(eg, { force = false })
            end)
        end
        if not ok or type(result) ~= "table" then
            return nil, tostring(result or "garden_scan_failed")
        end

        local groups = {}
        if type(result.groups) == "table" then
            for _, g in ipairs(result.groups) do
                if type(g) == "table" then
                    groups[#groups + 1] = {
                        name = tostring(g.name or g.key or "Unknown"),
                        plants = tonumber(g.plants) or 0,
                        fruits = tonumber(g.count or g.fruits) or 0,
                        count = tonumber(g.count or g.fruits) or 0,
                        value = tonumber(g.total or g.value) or 0,
                        total = tonumber(g.total or g.value) or 0,
                    }
                end
            end
        end

        return {
            source = "EspFruitGarden",
            plants = tonumber(result.plants) or 0,
            fruits = tonumber(result.count or result.fruits) or 0,
            count = tonumber(result.count or result.fruits) or 0,
            types = #groups,
            value = tonumber(result.total or result.value) or 0,
            total = tonumber(result.total or result.value) or 0,
            groups = groups,
        }
    end

    local function collectBackpackSummary(bridge)
        local ebp = G.EspFruitBackpack or rawget(_G, "EspFruitBackpack")
        if type(ebp) ~= "table" then
            return nil, "EspFruitBackpack_not_found"
        end

        -- Ringan: pakai cache ESP saja. Jangan ScanFruits / Compute / GetEntryPrice di path stats.
        local peek = nil
        if type(ebp.PeekBackpackValue) == "function" then
            local ok, r = pcall(ebp.PeekBackpackValue, ebp)
            if not ok or type(r) ~= "table" then
                ok, r = pcall(ebp.PeekBackpackValue)
            end
            if ok and type(r) == "table" then peek = r end
        elseif type(ebp.peekBackpackValue) == "function" then
            local ok, r = pcall(ebp.peekBackpackValue)
            if ok and type(r) == "table" then peek = r end
        end

        if type(peek) ~= "table" or peek.ready ~= true then
            return nil, "backpack_cache_cold"
        end

        return {
            source = "EspFruitBackpack.Peek",
            fruits = tonumber(peek.count or peek.fruits) or 0,
            count = tonumber(peek.count or peek.fruits) or 0,
            value = tonumber(peek.total or peek.value) or 0,
            total = tonumber(peek.total or peek.value) or 0,
            ready = true,
        }
    end

    local function applyBackpackOverview(assets, backpackSummary, fruitCountFallback, fruitValueFallback)
        if type(assets) ~= "table" then return end
        if type(assets.overview) ~= "table" then assets.overview = {} end
        local ov = assets.overview
        local fruitCount = fruitCountFallback or 0
        local fruitValue = fruitValueFallback or 0
        if type(backpackSummary) == "table" then
            fruitCount = tonumber(backpackSummary.count or backpackSummary.fruits) or fruitCount
            fruitValue = tonumber(backpackSummary.value or backpackSummary.total) or fruitValue
            assets.backpack_summary = backpackSummary
        end
        ov.fruits_backpack = tonumber(ov.fruits_backpack) or fruitCount
        ov.fruit_value_backpack = tonumber(ov.fruit_value_backpack) or fruitValue
        ov.fruit_value_backpack_label = ov.fruit_value_backpack_label
            or formatShortNumber(ov.fruit_value_backpack)
    end

    local function normalizeCustomAssets(bridge, data)
        if type(data) ~= "table" then return nil end
        if type(data.assets) == "table" then data = data.assets end

        local assets = data
        if type(assets.items) ~= "table" then assets.items = {} end
        if type(assets.groups) ~= "table" then assets.groups = {} end

        local sheckles, source = getSheckles(bridge)
        assets.sheckles = tonumber(assets.sheckles) or sheckles or 0
        assets.sheckles_source = assets.sheckles_source or source or "unknown"
        assets.source = tostring(assets.source or "custom_provider")
        assets.ts = tonumber(assets.ts) or now()

        local totalItems = 0
        local totalValue = 0
        for _, item in ipairs(assets.items) do
            if type(item) == "table" then
                local count = tonumber(item.count or item.amount) or 0
                local value = tonumber(item.value or item.total_value) or 0
                totalItems = totalItems + count
                totalValue = totalValue + value
                if not cleanRarityText(item.rarity or item.Rarity) then
                    local r = resolveItemRarity(
                        item.category or item.group,
                        item.name or item.key,
                        item
                    )
                    if r then item.rarity = r end
                elseif not item.rarity and item.Rarity then
                    item.rarity = cleanRarityText(item.Rarity)
                end
            end
        end
        assets.total_items = tonumber(assets.total_items) or totalItems
        assets.total_value = tonumber(assets.total_value) or totalValue

        if type(assets.overview) ~= "table" then assets.overview = {} end
        assets.overview.sheckles = tonumber(assets.overview.sheckles) or assets.sheckles
        assets.overview.sheckles_label = assets.overview.sheckles_label or formatShortNumber(assets.overview.sheckles)
        assets.overview.total_items = tonumber(assets.overview.total_items) or assets.total_items
        assets.overview.inventory_value = tonumber(assets.overview.inventory_value) or assets.total_value
        assets.overview.net_worth = tonumber(assets.overview.net_worth) or (assets.sheckles + assets.total_value + (tonumber(assets.overview.garden_value) or 0))
        assets.overview.net_worth_label = assets.overview.net_worth_label or formatShortNumber(assets.overview.net_worth)

        -- Backpack fruit value (EspFruitBackpack) — fill if provider omitted it
        if assets.overview.fruit_value_backpack == nil then
            local bpSummary = select(1, collectBackpackSummary(bridge))
            local g = assets.groups
            local fruitCountFallback = (type(g) == "table" and g.fruits and g.fruits.count) or 0
            local fruitValueFallback = (type(g) == "table" and g.fruits and g.fruits.value) or 0
            applyBackpackOverview(assets, bpSummary, fruitCountFallback, fruitValueFallback)
        elseif not assets.overview.fruit_value_backpack_label then
            assets.overview.fruit_value_backpack_label = formatShortNumber(assets.overview.fruit_value_backpack)
        end

        return assets
    end

    local function collectCustomAssets(bridge)
        local providers = {}
        local mode = bridge and tostring(bridge.assetMode or "") or ""
        local stealEggMode = mode == "steal_egg"
        local function addProvider(fn)
            if type(fn) ~= "function" then return end
            for i = 1, #providers do
                if providers[i] == fn then return end
            end
            providers[#providers + 1] = fn
        end
        -- Steal Egg: pakai collector terbaru dari re-execute dulu.
        -- Bridge.getAssets sering masih function lama kalau WS helper skip install (version sama).
        if stealEggMode then
            addProvider(G.__NODEHUB_COLLECT_ASSETS)
            addProvider(rawget(_G, "__NODEHUB_COLLECT_ASSETS"))
        end
        if bridge then addProvider(bridge.getAssets) end
        if not stealEggMode then
            addProvider(G.__NODEHUB_COLLECT_ASSETS)
            addProvider(rawget(_G, "__NODEHUB_COLLECT_ASSETS"))
        end
        addProvider(G.__GAG2_COLLECT_ASSETS)
        addProvider(rawget(_G, "__GAG2_COLLECT_ASSETS"))

        local best, bestScore = nil, -1
        for _, fn in ipairs(providers) do
            local ok, data = pcall(fn, bridge)
            if ok and type(data) == "table" then
                local assets = normalizeCustomAssets(bridge, data)
                if type(assets) == "table" then
                    local ov = assets.overview
                    local score = 0
                    if type(ov) == "table" then
                        if type(ov.column_schema) == "table" then
                            score = score + 100 + #ov.column_schema
                        end
                        if type(ov.cards) == "table" then
                            score = score + #ov.cards
                        end
                    end
                    if score > bestScore then
                        best, bestScore = assets, score
                    elseif best == nil then
                        best, bestScore = assets, score
                    end
                    if stealEggMode ~= true then
                        return assets
                    end
                end
            end
        end
        return best
    end

    -- Fruit per-type live refresh: dipanggil tiap stats tick (meski assets cache hit)
    -- supaya chip + tab Fruits di web tidak macet 60 detik.
    local function refreshFruitAssetsLive(assets)
        if type(assets) ~= "table" then return false end
        local ebp = G.EspFruitBackpack or rawget(_G, "EspFruitBackpack")
        if type(ebp) ~= "table" then return false end

        local peekTotal, peekCount = 0, 0
        local peek = ebp.PeekBackpackValue or ebp.peekBackpackValue
        if type(peek) == "function" then
            local okPeek, peekRes = pcall(peek, ebp)
            if not okPeek or type(peekRes) ~= "table" then
                okPeek, peekRes = pcall(peek)
            end
            if okPeek and type(peekRes) == "table" then
                peekTotal = tonumber(peekRes.total) or 0
                peekCount = tonumber(peekRes.count) or 0
            end
        end

        local result = nil
        local getByType = ebp.GetValueByType or ebp.getValueByType
        if type(getByType) == "function" then
            local ok, res = pcall(getByType, ebp, { force = false })
            if not ok or type(res) ~= "table" then
                ok, res = pcall(getByType, { force = false })
            end
            if ok and type(res) == "table" and type(res.rows) == "table" then
                result = res
            end
        end

        local sumValue, sumCount, n = 0, 0, 0
        -- Jangan wipe fruit lama kalau GetValueByType belum ready / rows kosong sementara.
        local rowsReady = false
        if result and type(result.rows) == "table" then
            local rowN = #result.rows
            local cnt = tonumber(result.count) or 0
            if result.ready == true or rowN > 0 or cnt > 0 then
                rowsReady = true
            end
        end
        if rowsReady then
            local incomingSum = tonumber(result.total) or 0
            if incomingSum <= 0 then
                for _, slot in ipairs(result.rows) do
                    if type(slot) == "table" then
                        incomingSum = incomingSum + math.max(0, math.floor(tonumber(slot.value or slot.total_value) or 0))
                    end
                end
            end
            local prevFruitValue = 0
            for _, row in ipairs(assets.items or {}) do
                if type(row) == "table" and normalizeAssetCategory(row.category or row.group) == "fruits" then
                    prevFruitValue = prevFruitValue + math.max(0, tonumber(row.value or row.total_value) or 0)
                end
            end
            -- Harga pending (count ada, value 0): jangan timpa item yang sudah punya value.
            if incomingSum <= 0 and prevFruitValue > 0 then
                rowsReady = false
                sumValue = prevFruitValue
            end
        end
        if rowsReady then
            -- Replace fruit rows only; keep non-fruit items.
            local kept = {}
            for _, row in ipairs(assets.items or {}) do
                if type(row) == "table" and normalizeAssetCategory(row.category or row.group) ~= "fruits" then
                    kept[#kept + 1] = row
                end
            end
            assets.items = kept
            if type(assets.groups) ~= "table" then assets.groups = {} end
            assets.groups.fruits = { count = 0, value = 0, items = {} }

            -- Recompute totals without fruit contribution from old rows.
            local totalItems, totalValue = 0, 0
            for _, row in ipairs(kept) do
                totalItems = totalItems + math.max(0, tonumber(row.count or row.amount) or 0)
                totalValue = totalValue + math.max(0, tonumber(row.value) or 0)
            end
            assets.total_items = totalItems
            assets.total_value = totalValue

            for _, slot in ipairs(result.rows) do
                if type(slot) == "table" then
                    local name = cleanFruitItemName(slot.name or slot.key or "")
                    local cnt = math.floor(tonumber(slot.count) or 0)
                    local val = math.floor(tonumber(slot.value or slot.total_value) or 0)
                    if name ~= "" and cnt > 0 then
                        addAssetItem(assets, nil, "HarvestedFruits", name, name, cnt, {
                            count = cnt,
                            amount = cnt,
                            value = val,
                            total_value = val,
                            value_is_total = true,
                            value_label = formatShortNumber(val),
                        })
                        n = n + 1
                        sumCount = sumCount + cnt
                        sumValue = sumValue + val
                    end
                end
            end
        end

        local overviewVal = peekTotal
        if overviewVal <= 0 then overviewVal = sumValue end
        local overviewCount = peekCount
        if overviewCount <= 0 then overviewCount = sumCount end

        -- Jangan timpa chip/overview jadi 0 saat harga masih pending (count ada, value belum).
        if type(assets.overview) ~= "table" then assets.overview = {} end
        if overviewCount > 0 then
            assets.overview.fruits_backpack = overviewCount
        end
        if overviewVal > 0 then
            assets.backpack_summary = {
                source = "EspFruitBackpack.live",
                fruits = overviewCount,
                count = overviewCount,
                value = overviewVal,
                total = overviewVal,
                ready = true,
                types_value = sumValue,
                peek_value = peekTotal,
            }
            assets.fruit_types_total_value = sumValue
            assets.fruit_types_total_count = sumCount
            assets.overview.fruit_value_backpack = overviewVal
            assets.overview.fruit_value_backpack_label = formatShortNumber(overviewVal)
            return true
        end
        -- Harga belum siap: update count/types saja, pertahankan value lama kalau ada.
        if n > 0 then
            assets.fruit_types_total_count = sumCount
            if sumValue > 0 then
                assets.fruit_types_total_value = sumValue
            end
            local prevVal = tonumber(assets.overview.fruit_value_backpack) or 0
            if prevVal <= 0 and type(assets.backpack_summary) == "table" then
                prevVal = tonumber(assets.backpack_summary.value or assets.backpack_summary.total) or 0
            end
            if type(assets.backpack_summary) ~= "table" then
                assets.backpack_summary = {
                    source = "EspFruitBackpack.live.pending",
                    fruits = overviewCount,
                    count = overviewCount,
                    value = prevVal,
                    total = prevVal,
                    ready = prevVal > 0,
                    types_value = sumValue,
                    peek_value = peekTotal,
                }
            else
                assets.backpack_summary.fruits = overviewCount
                assets.backpack_summary.count = overviewCount
                assets.backpack_summary.types_value = sumValue
                assets.backpack_summary.peek_value = peekTotal
            end
            return true
        end
        return false
    end

    local function collectGameAssets(bridge)
        local customAssets = collectCustomAssets(bridge)
        if type(customAssets) == "table" then
            return customAssets
        end

        local sheckles, shecklesSource = getSheckles(bridge)
        local assets = {
            source = "generic",
            ts = now(),
            sheckles = sheckles,
            sheckles_source = shecklesSource,
            total_items = 0,
            total_value = 0,
            groups = {},
            items = {},
        }

        local okGift, giftMsg = collectFromAutoGiftModule(bridge, assets)
        if not okGift then
            collectFromBackpackTools(bridge, assets)
            assets.source_note = giftMsg
        end

        local okFruits, fruitsMsg = collectFruitsByType(bridge, assets)
        if not okFruits and fruitsMsg then
            assets.fruit_value_source_error = tostring(fruitsMsg)
        end

        local gardenSummary, gardenErr = collectGardenSummary(bridge)
        if type(gardenSummary) == "table" then
            assets.garden_summary = gardenSummary
        elseif gardenErr then
            assets.garden_summary_error = tostring(gardenErr)
        end

        -- Jangan timpa summary dari GetValueByType dengan Peek dingin.
        if type(assets.backpack_summary) ~= "table" then
            local backpackSummary, backpackErr = collectBackpackSummary(bridge)
            if type(backpackSummary) == "table" then
                assets.backpack_summary = backpackSummary
            elseif backpackErr then
                assets.backpack_summary_error = tostring(backpackErr)
            end
        end

        local g = assets.groups
        local seedCount = g.seeds and g.seeds.count or 0
        local fruitCount = g.fruits and g.fruits.count or 0
        local petCount = g.pets and g.pets.count or 0
        local gearCount = g.gear and g.gear.count or 0
        local seedPackCount = g.seed_packs and g.seed_packs.count or 0
        local eggCount = g.eggs and g.eggs.count or 0

        local seedValue = g.seeds and g.seeds.value or 0
        local fruitValue = g.fruits and g.fruits.value or 0
        local petValue = g.pets and g.pets.value or 0
        local gearValue = g.gear and g.gear.value or 0
        local seedPackValue = g.seed_packs and g.seed_packs.value or 0
        local eggValue = g.eggs and g.eggs.value or 0
        local garden = type(assets.garden_summary) == "table" and assets.garden_summary or {}
        local gardenPlants = tonumber(garden.plants) or 0
        local gardenFruits = tonumber(garden.fruits or garden.count) or 0
        local gardenTypes = tonumber(garden.types) or 0
        local gardenValue = tonumber(garden.value or garden.total) or 0

        if type(assets.backpack_summary) == "table" then
            fruitCount = tonumber(assets.backpack_summary.count or assets.backpack_summary.fruits) or fruitCount
            local summaryVal = tonumber(assets.backpack_summary.value or assets.backpack_summary.total) or 0
            local peekVal = tonumber(assets.backpack_summary.peek_value) or 0
            local typesVal = tonumber(assets.fruit_types_total_value) or 0
            -- Prioritas: peek ESP live → summary → sum tipe.
            if peekVal > 0 then
                fruitValue = peekVal
            elseif summaryVal > 0 then
                fruitValue = summaryVal
            elseif typesVal > 0 then
                fruitValue = typesVal
            end
        elseif tonumber(assets.fruit_types_total_value) and assets.fruit_types_total_value > 0 then
            fruitValue = tonumber(assets.fruit_types_total_value) or fruitValue
            fruitCount = tonumber(assets.fruit_types_total_count) or fruitCount
        end

        assets.overview = {
            sheckles = assets.sheckles,
            sheckles_label = formatShortNumber(assets.sheckles),

            net_worth = assets.sheckles + assets.total_value + gardenValue,
            net_worth_label = formatShortNumber(assets.sheckles + assets.total_value + gardenValue),

            total_seeds = seedCount,
            seed_value = seedValue,

            fruits_backpack = fruitCount,
            fruit_value_backpack = fruitValue,
            fruit_value_backpack_label = formatShortNumber(fruitValue),

            total_pets = petCount,
            pet_value_est = petValue,

            gear_count = gearCount,
            gear_value = gearValue,

            seed_packs = seedPackCount,
            seed_pack_value = seedPackValue,

            eggs = eggCount,
            egg_value = eggValue,

            garden_plants = gardenPlants,
            garden_fruits = gardenFruits,
            garden_types = gardenTypes,
            garden_value = gardenValue,
            garden_value_label = formatShortNumber(gardenValue),

            total_items = assets.total_items,
            inventory_value = assets.total_value,
        }

        return assets
    end

    -- Overview already computed from groups. Copy assets for WS/DB without duplicating items.
    local function assetsForWire(assets)
        if type(assets) ~= "table" then return assets end
        if assets.groups == nil then return assets end
        local out = {}
        for k, v in pairs(assets) do
            if k ~= "groups" then
                out[k] = v
            end
        end
        return out
    end

    local function makeUrl(baseUrl, wsId, authToken)
        baseUrl = trim(baseUrl)
        wsId = trim(wsId)
        authToken = trim(authToken)

        if baseUrl == "" then return nil, "connection_target_empty" end
        if wsId == "" then return nil, "ws_id_empty" end
        if authToken == "" then return nil, "auth_token_empty" end

        local url = baseUrl
        local hasId = url:find("{id}", 1, true) or url:find("{ws_id}", 1, true)
        local hasToken = url:find("{token}", 1, true) or url:find("{auth_token}", 1, true)

        -- Pakai function replacement, bukan string replacement.
        -- Alasannya: hasil urlEncode bisa mengandung "%" dan Lua gsub akan menganggap "%" sebagai capture.
        -- Kalau replacement string mengandung %4 / %2 dll, bisa error: invalid capture index.
        local encodedWsId = urlEncode(wsId)
        local encodedToken = urlEncode(authToken)

        url = url:gsub("{id}", function() return encodedWsId end)
        url = url:gsub("{ws_id}", function() return encodedWsId end)
        url = url:gsub("{token}", function() return encodedToken end)
        url = url:gsub("{auth_token}", function() return encodedToken end)

        if not hasId then
            local sep = url:find("?", 1, true) and "&" or "?"
            url = url .. sep .. "ws_id=" .. urlEncode(wsId)
        end

        if not hasToken then
            local sep = url:find("?", 1, true) and "&" or "?"
            url = url .. sep .. "auth_token=" .. urlEncode(authToken)
        end

        return url
    end

    local Bridge = {}
    Bridge.__index = Bridge


    ----------------------------------------------------------------
    -- V48 helper UI apply hook sederhana
    -- Tujuan:
    --   Web -> config_update -> saveFile/MAIN sudah masuk, lalu module prod
    --   cukup mendaftarkan function kecil untuk menyalin config ke local state/UI.
    -- Keamanan:
    --   Tidak menjalankan string/loadstring/eval dari server.
    --   Server hanya mengirim data config. Function yang dipanggil harus sudah
    --   ada di script production dan didaftarkan manual oleh developer.
    ----------------------------------------------------------------
    local function nodeHubUiNamespace(namespace)
        local s = trim(tostring(namespace or "default"))
        return s ~= "" and s or "default"
    end

    local function nodeHubUiSafePath(path)
        if type(path) ~= "string" then return false end
        path = trim(path)
        if path == "" or #path > 260 then return false end
        if path:find("__proto__", 1, true)
            or path:find("prototype", 1, true)
            or path:find("constructor", 1, true) then
            return false
        end
        for part in path:gmatch("[^%.]+") do
            if part == "" or not part:match("^[%w_]+$") then
                return false
            end
        end
        return true
    end

    local function nodeHubUiGetPath(root, path)
        if type(root) ~= "table" or not nodeHubUiSafePath(path) then return nil end
        local cur = root
        for part in path:gmatch("[^%.]+") do
            if type(cur) ~= "table" then return nil end
            cur = cur[part]
            if cur == nil then return nil end
        end
        return cur
    end

    local function nodeHubUiSetPath(root, path, value)
        if type(root) ~= "table" or not nodeHubUiSafePath(path) then
            return false, "invalid_path"
        end
        local parts = {}
        for part in path:gmatch("[^%.]+") do
            parts[#parts + 1] = part
        end
        if #parts <= 0 then return false, "empty_path" end
        local cur = root
        for i = 1, #parts - 1 do
            local k = parts[i]
            if type(cur[k]) ~= "table" then cur[k] = {} end
            cur = cur[k]
        end
        cur[parts[#parts]] = value
        return true
    end

    local function nodeHubUiCopy(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] then return seen[value] end
        local out = {}
        seen[value] = out
        for k, v in pairs(value) do
            out[nodeHubUiCopy(k, seen)] = nodeHubUiCopy(v, seen)
        end
        return out
    end

    local function nodeHubUiClearTable(t)
        if type(t) ~= "table" then return end
        for k in pairs(t) do t[k] = nil end
    end

    local function nodeHubUiMerge(target, source, replace)
        if type(target) ~= "table" then return false, "target_not_table" end
        if type(source) ~= "table" then return false, "source_not_table" end
        if replace == true then nodeHubUiClearTable(target) end
        for k, v in pairs(source) do
            if type(v) == "table" and type(target[k]) == "table" and replace ~= true then
                nodeHubUiMerge(target[k], v, false)
            else
                target[k] = nodeHubUiCopy(v)
            end
        end
        return true
    end

    local function nodeHubUiToArray(value)
        local out, seen = {}, {}
        local function add(v)
            if type(v) == "table" then
                v = firstNonEmpty(v.key, v.name, v.id, v.label, v.value)
            end
            local s = trim(tostring(v or ""))
            if s ~= "" and seen[s] ~= true then
                seen[s] = true
                out[#out + 1] = s
            end
        end

        if type(value) == "table" then
            for _, v in ipairs(value) do add(v) end
            if #out <= 0 then
                for k, v in pairs(value) do
                    if v == true or v == 1 or v == "true" then
                        add(k)
                    elseif type(v) == "table" then
                        add(v)
                    end
                end
            end
        elseif type(value) == "string" then
            local raw = value:gsub("\r\n", "\n"):gsub("\r", "\n")
            for token in (raw .. "\n"):gmatch("([^\n,]+)[\n,]") do
                add(token)
            end
        elseif value ~= nil then
            add(value)
        end
        return out
    end

    local function nodeHubUiToSelectedMap(value)
        local out = {}
        for _, item in ipairs(nodeHubUiToArray(value)) do
            out[item] = true
        end
        return out
    end

    local function nodeHubUiSetGlobal(name, value)
        name = trim(tostring(name or ""))
        if name == "" or #name > 140 or not name:match("^[%w_]+$") then
            return false, "invalid_global_name"
        end
        G[name] = value
        _G[name] = value
        return true
    end

    local function nodeHubUiCallGlobal(name, ...)
        name = trim(tostring(name or ""))
        if name == "" then return false, "empty_function_name" end
        local fn = G[name] or rawget(_G, name)
        if type(fn) ~= "function" then return false, "function_not_found:" .. name end
        local ok, res = pcall(fn, ...)
        if not ok then return false, tostring(res) end
        return true, res
    end

    local function nodeHubUiApplyApi()
        return {
            normalize = normalizeConfigEnvelope,
            copy = nodeHubUiCopy,
            deepCopy = nodeHubUiCopy,
            get = nodeHubUiGetPath,
            getPath = nodeHubUiGetPath,
            set = nodeHubUiSetPath,
            setPath = nodeHubUiSetPath,
            merge = nodeHubUiMerge,
            mergeTable = nodeHubUiMerge,
            array = nodeHubUiToArray,
            toArray = nodeHubUiToArray,
            selectedMap = nodeHubUiToSelectedMap,
            toSelectedMap = nodeHubUiToSelectedMap,
            setGlobal = nodeHubUiSetGlobal,
            setGlobalSelectedMap = function(name, value)
                return nodeHubUiSetGlobal(name, nodeHubUiToSelectedMap(value))
            end,
            callGlobal = nodeHubUiCallGlobal,
            readJsonFile = readJsonFile,
            writeJsonFile = writeJsonFile,
        }
    end

    local function nodeHubAddApplyUiHook(namespace, name, fn)
        namespace = nodeHubUiNamespace(namespace)
        if type(name) == "function" and fn == nil then
            fn = name
            name = "hook_" .. tostring(now())
        end
        if type(fn) ~= "function" then return false, "fn_not_function" end
        name = trim(tostring(name or ("hook_" .. tostring(now()))))
        if name == "" then name = "hook_" .. tostring(now()) end
        if #name > 80 then name = name:sub(1, 80) end

        NodeHubWS._applyUiHooks[namespace] = NodeHubWS._applyUiHooks[namespace] or {}
        NodeHubWS._applyUiHooks[namespace][#NodeHubWS._applyUiHooks[namespace] + 1] = {
            name = name,
            fn = fn,
        }
        return true, #NodeHubWS._applyUiHooks[namespace]
    end

    local function nodeHubRunApplyUiHooks(namespace, config, message, bridge)
        namespace = nodeHubUiNamespace(namespace)
        config = normalizeConfigEnvelope(config)
        local summary = {
            ok = true,
            namespace = namespace,
            at = now(),
            hooks = 0,
            global_hooks = 0,
            names = {},
            errors = {},
        }

        if type(config) ~= "table" then
            summary.ok = false
            summary.errors[#summary.errors + 1] = "config_not_table"
        else
            local api = nodeHubUiApplyApi()
            local buckets = {}
            if type(NodeHubWS._applyUiHooks["*"]) == "table" then
                buckets[#buckets + 1] = NodeHubWS._applyUiHooks["*"]
            end
            if type(NodeHubWS._applyUiHooks[namespace]) == "table" then
                buckets[#buckets + 1] = NodeHubWS._applyUiHooks[namespace]
            end

            for _, hooks in ipairs(buckets) do
                for _, item in ipairs(hooks) do
                    if type(item) == "table" and type(item.fn) == "function" then
                        local okHook, errHook = pcall(item.fn, config, message, bridge, api)
                        if okHook and errHook ~= false then
                            summary.hooks = summary.hooks + 1
                            summary.names[#summary.names + 1] = tostring(item.name or "hook")
                        else
                            summary.ok = false
                            summary.errors[#summary.errors + 1] = tostring(item.name or "hook") .. ":" .. tostring(errHook)
                        end
                    end
                end
            end

            local globalNames = {
                "__NODEHUB_WS_APPLY_UI",
                "__NODEHUB_WS_APPLY_UI_" .. namespace:upper():gsub("[^A-Z0-9_]", "_"),
            }
            if namespace == "gag2" then
                globalNames[#globalNames + 1] = "__GAG2_APPLY_UI_FROM_CONFIG"
                globalNames[#globalNames + 1] = "__GAG2_APPLY_REMOTE_UI"
            end

            for _, globalName in ipairs(globalNames) do
                local fn = G[globalName] or rawget(_G, globalName)
                if type(fn) == "function" then
                    local okGlobal, errGlobal = pcall(fn, config, message, bridge, api)
                    if okGlobal and errGlobal ~= false then
                        summary.global_hooks = summary.global_hooks + 1
                        summary.names[#summary.names + 1] = globalName
                    else
                        summary.ok = false
                        summary.errors[#summary.errors + 1] = globalName .. ":" .. tostring(errGlobal)
                    end
                end
            end
        end

        if type(bridge) == "table" then
            bridge._lastApplyUi = summary
        end
        G.__NODEHUB_WS_LAST_APPLY_UI = summary
        _G.__NODEHUB_WS_LAST_APPLY_UI = summary
        G["__NODEHUB_WS_LAST_APPLY_UI_" .. namespace:upper():gsub("[^A-Z0-9_]", "_")] = summary
        _G["__NODEHUB_WS_LAST_APPLY_UI_" .. namespace:upper():gsub("[^A-Z0-9_]", "_")] = summary
        return summary.ok == true, summary
    end

    function Bridge:UpdateOptions(opts)
        opts = type(opts) == "table" and opts or {}

        if opts.wsBaseUrl or opts.baseUrl then
            self.wsBaseUrl = safeToString(opts.wsBaseUrl or opts.baseUrl or self.wsBaseUrl)
        end
        if opts.authPassword or opts.deviceAuthPassword or opts.wsPassword then
            self.authPassword = safeToString(opts.authPassword or opts.deviceAuthPassword or opts.wsPassword or self.authPassword)
        end
        if opts.scriptName then self.scriptName = safeToString(opts.scriptName or self.scriptName) end
        if opts.saveFile ~= nil then self.saveFile = resolveConfigSaveFile(opts.saveFile, self.namespace) end
        if opts.defaultSaveFile ~= nil then self.defaultSaveFile = resolveConfigSaveFile(opts.defaultSaveFile, self.namespace) end
        if opts.settingsFile ~= nil or opts.trackStateFile ~= nil then
            self.settingsFile = opts.settingsFile or opts.trackStateFile
        end
        if opts.persistSettings ~= nil or opts.rememberWsId ~= nil then
            self.persistSettings = (opts.persistSettings == true or opts.rememberWsId == true)
        end
        if opts.persistTrackState ~= nil or opts.rememberTrackState ~= nil then
            -- V35: pisahkan file kecil khusus Track Server dari config script utama.
            -- persistSettings boleh false, tapi ws_id + status on/off tetap boleh diingat.
            self.persistTrackState = not (opts.persistTrackState == false or opts.rememberTrackState == false)
        end
        if opts.autoStartOnBoot ~= nil or opts.autoResumeTrack ~= nil then
            -- V35: auto execute tidak boleh menunggu section Track Server dibuka.
            self.autoStartOnBoot = not (opts.autoStartOnBoot == false or opts.autoResumeTrack == false)
        end
        if tonumber(opts.autoStartDelay) then
            self.autoStartDelay = tonumber(opts.autoStartDelay)
            if self.autoStartDelay < 0 then self.autoStartDelay = 0 end
        end
        if opts.gameName ~= nil then self.gameName = safeToString(opts.gameName or self.gameName or self.scriptName) end
        if opts.gameId ~= nil or opts.universeId ~= nil then self.gameId = safeShort(opts.gameId or opts.universeId, 80) end
        if opts.placeId ~= nil then self.placeId = safeShort(opts.placeId, 80) end
        if opts.accountId ~= nil or opts.akunGameId ~= nil or opts.akun_game_id ~= nil then
            self.accountId = safeShort(opts.accountId or opts.akunGameId or opts.akun_game_id, 80)
        end
        if opts.accountUsername ~= nil or opts.akunUsername ~= nil or opts.akun_username ~= nil then
            self.accountUsername = safeShort(opts.accountUsername or opts.akunUsername or opts.akun_username, 120)
        end
        local nextScId = normalizeScId(firstNonEmpty(
            opts.sc_id,
            opts.scId,
            opts.script_id,
            opts.scriptId,
            opts.id_code_list,
            opts.idCodeList,
            opts.code_list_id,
            opts.codeListId
        ))
        if nextScId ~= nil then
            local prevScId = self.scId
            self.scId = nextScId

            -- V37:
            -- Kalau bridge sudah auto boot/headless duluan tanpa sc_id,
            -- lalu UI/section belakangan memberi sc_id, langsung kirim stats baru.
            -- Ini membuat server menerima sc_id tanpa menunggu interval berikutnya.
            if prevScId ~= nextScId then
                self._scIdUpdatedAt = now()
                self:SavePrefs()
                if self.connected == true then
                    task.defer(function()
                        if self.connected == true then
                            self:SendStats("sc_id_update")
                        end
                    end)
                end
            end
        end
        self.sendDefaultConfigOnTrack = opts.sendDefaultConfigOnTrack ~= false
        if opts.sendDefaultConfigOnChange ~= nil then
            self.sendDefaultConfigOnChange = opts.sendDefaultConfigOnChange == true
        end

        if tonumber(opts.statsInterval) then
            self.statsInterval = tonumber(opts.statsInterval)
            if self.statsInterval < 2 then self.statsInterval = 2 end
        end

        self.useServerStatsInterval = opts.useServerStatsInterval ~= false
        self.includePlayerList = opts.includePlayerList == true
        self.autoReconnect = opts.autoReconnect ~= false
        self.restoreActive = opts.restoreActive == true

        self.collectAssets = opts.collectAssets == true or opts.assetMode == "gag2" or opts.assetMode == "growagarden"
        self.assetMode = safeToString(opts.assetMode or self.assetMode or "")
        self.assetCategories = type(opts.assetCategories) == "table" and opts.assetCategories or self.assetCategories
        self.assetValueProvider = type(opts.assetValueProvider) == "function" and opts.assetValueProvider or self.assetValueProvider
        self.assetsInterval = tonumber(opts.assetsInterval or self.assetsInterval or self.statsInterval) or self.statsInterval
        if self.assetsInterval < 2 then self.assetsInterval = 2 end
        if tonumber(opts.reconnectDelay) then self.reconnectDelay = tonumber(opts.reconnectDelay) end
        self.debug = opts.debug == true

        if type(opts.getConfig) == "function" then self.getConfig = opts.getConfig end
        if type(opts.getDefaultConfig) == "function" then self.getDefaultConfig = opts.getDefaultConfig end
        if type(opts.applyConfig) == "function" then self.applyConfig = opts.applyConfig end
        if type(opts.afterApply) == "function" then self.afterApply = opts.afterApply end
        if type(opts.getStats) == "function" then self.getStats = opts.getStats end
        if type(opts.getAssets) == "function" or type(opts.collectAssetsFn) == "function" then
            self.getAssets = opts.getAssets or opts.collectAssetsFn
        end
        if type(opts.getMoney) == "function" or type(opts.getSheckles) == "function" then
            self.getMoney = opts.getMoney
            self.getSheckles = opts.getSheckles
        end
        if type(opts.getIdentity) == "function" or type(opts.getGameAccount) == "function" then
            self.getIdentity = opts.getIdentity or opts.getGameAccount
        end
        if type(opts.onMessage) == "function" then self.onMessage = opts.onMessage end
        if type(opts.onCommand) == "function" then self.onCommand = opts.onCommand end
        if type(opts.onAutoGift) == "function" or type(opts.onAutoGiftCommand) == "function" then
            self.autoGiftHandler = opts.onAutoGift or opts.onAutoGiftCommand
        end
        if type(opts.onStatus) == "function" then self.onStatus = opts.onStatus end

        -- Jangan timpa wsId yang sudah terisi dengan string kosong.
        if opts.wsId ~= nil or opts.ws_id ~= nil then
            local nextWs = trim(safeToString(opts.wsId or opts.ws_id or ""))
            if nextWs ~= "" then
                self.wsId = nextWs
            end
        end

        return self
    end

    local function compactTrackStatus(bridge)
        if type(bridge) ~= "table" then
            return "OFF"
        end
        -- UI hanya ON/OFF. Detail tetap di status_detail / Debug.
        if trim(bridge.wsId) == "" then
            return "OFF"
        end
        if bridge.trackEnabled ~= true and bridge.active ~= true then
            return "OFF"
        end
        return "ON"
    end

    local function trackStatusFromPrefs(data)
        if type(data) ~= "table" then return false end
        local status = tostring(data.status or data.track_status or data.trackStatus or ""):lower()
        status = status:gsub("%s+", "")
        if status == "on" or status == "aktif" or status == "active" or status == "true" or status == "1" then
            return true
        end
        if status == "off" or status == "nonaktif" or status == "inactive" or status == "false" or status == "0" then
            return false
        end

        -- kompatibilitas file lama kalau pernah ada.
        return data.active == true or data.track_enabled == true or data.trackEnabled == true
    end

    function Bridge:SetStatus(text)
        text = tostring(text or "")
        self.status_detail = text
        self.status = compactTrackStatus(self)

        if type(self.onStatus) == "function" then
            pcall(self.onStatus, self.status, self, text)
        end

        local lbl = self._statusLabel
        if lbl and lbl.Parent then
            -- V35: status UI cukup ON/OFF. Detail teknis tetap ada di NodeHubWS.Debug().
            lbl.Text = "Status: " .. tostring(self.status or "OFF")
        end
    end

    function Bridge:LoadPrefs()
        if self.persistTrackState ~= true and self.persistSettings ~= true then
            -- V35: boleh dimatikan eksplisit dengan persistTrackState=false.
            deleteFileSafe(self.settingsFile)
            self.active = false
            self.trackEnabled = false
            return nil, "track_state_disabled"
        end

        local data = readJsonFile(self.settingsFile)
        if type(data) == "table" then
            if type(data.ws_id) == "string" and trim(self.wsId) == "" then
                self.wsId = data.ws_id
            end

            -- V38: sc_id boleh disimpan karena hanya ID module publik/internal untuk fitur modular.
            -- Tetap jangan pernah baca ws_base_url/auth/token dari file lokal.
            local savedScId = normalizeScId(firstNonEmpty(
                data.sc_id,
                data.scId,
                data.id_code_list,
                data.idCodeList,
                data.script_id,
                data.scriptId
            ))
            if savedScId ~= nil and self.scId == nil then
                self.scId = savedScId
            end

            -- V35: baca ws_id + status ON/OFF.
            -- Jangan pernah baca ws_base_url/auth/token dari file lokal.
            local on = trackStatusFromPrefs(data)
            if trim(self.wsId) == "" then on = false end
            self.active = on == true
            self.trackEnabled = on == true
            self._loadedTrackStatus = on and "on" or "off"
        end
        return data
    end

    function Bridge:SavePrefs()
        if self.persistTrackState ~= true and self.persistSettings ~= true then
            deleteFileSafe(self.settingsFile)
            return true, "track_state_disabled"
        end

        -- V38: file preferensi hanya menyimpan data kecil untuk auto execute.
        -- sc_id ikut disimpan agar headless/auto execute tetap bisa kirim ID module.
        -- Tidak menyimpan ws_base_url, auth token, auth password, URL koneksi,
        -- config script, stats, assets, atau payload lain.
        return writeJsonFile(self.settingsFile, {
            schema = "nodehub_ws_static_track_state_v38",
            namespace = self.namespace,
            ws_id = safeShort(self.wsId, 80),
            status = (self.trackEnabled == true or self.active == true) and "on" or "off",
            sc_id = normalizeScId(self.scId),
            ts = now(),
        })
    end

    function Bridge:BuildAuthToken()
        local wsId = trim(self.wsId)
        if wsId == "" then return nil, "ws_id_empty" end
        if trim(self.authPassword) == "" then return nil, "auth_empty" end

        local ok, tokenOrErr = pcall(function()
            return sha256(wsId .. tostring(self.authPassword or ""))
        end)

        if not ok or type(tokenOrErr) ~= "string" or #tokenOrErr ~= 64 then
            return nil, "sha256_failed: " .. tostring(tokenOrErr)
        end

        return tokenOrErr:lower()
    end

    function Bridge:GetIdentityPayload(extra)
        local custom = {}
        if type(self.getIdentity) == "function" then
            local ok, res = pcall(self.getIdentity, self)
            if ok and type(res) == "table" then
                custom = res
            end
        end

        if type(extra) == "table" then
            for k, v in pairs(extra) do
                if custom[k] == nil then custom[k] = v end
            end
        end

        local player = localPlayer()
        local customGame = type(custom.game) == "table" and custom.game or {}
        local customAccount = type(custom.account) == "table" and custom.account or type(custom.akun) == "table" and custom.akun or type(custom.game_account) == "table" and custom.game_account or {}
        local customPlayer = type(custom.player) == "table" and custom.player or {}
        local customMeta = type(custom.meta) == "table" and custom.meta or {}

        local gameId = safeShort(firstNonEmpty(
            custom.game_id,
            custom.gameId,
            custom.universe_id,
            custom.universeId,
            customGame.game_id,
            customGame.gameId,
            customGame.universe_id,
            customGame.universeId,
            customMeta.game_id,
            customMeta.gameId,
            self.gameId,
            safeGameField("GameId", 0)
        ), 80)

        local placeId = safeShort(firstNonEmpty(
            custom.place_id,
            custom.placeId,
            customGame.place_id,
            customGame.placeId,
            customMeta.place_id,
            customMeta.placeId,
            self.placeId,
            safeGameField("PlaceId", 0)
        ), 80)

        local gameName = safeShort(firstNonEmpty(
            custom.game_name,
            custom.gameName,
            customGame.game_name,
            customGame.gameName,
            customGame.name,
            customGame.title,
            customMeta.game_name,
            customMeta.gameName,
            self.gameName,
            self.scriptName
        ), 180)

        local accountId = safeShort(firstNonEmpty(
            custom.akun_game_id,
            custom.akunGameId,
            custom.account_id,
            custom.accountId,
            customAccount.akun_game_id,
            customAccount.akunGameId,
            customAccount.account_id,
            customAccount.accountId,
            customAccount.user_id,
            customAccount.userId,
            customPlayer.akun_game_id,
            customPlayer.account_id,
            customPlayer.user_id,
            customPlayer.userId,
            customMeta.akun_game_id,
            customMeta.account_id,
            self.accountId,
            player and player.UserId
        ), 80)

        local accountUsername = safeShort(firstNonEmpty(
            custom.akun_username,
            custom.akunUsername,
            custom.username,
            custom.user_name,
            customAccount.akun_username,
            customAccount.akunUsername,
            customAccount.username,
            customAccount.user_name,
            customAccount.name,
            customPlayer.akun_username,
            customPlayer.username,
            customPlayer.user_name,
            customPlayer.name,
            customMeta.akun_username,
            customMeta.username,
            customMeta.user_name,
            self.accountUsername,
            player and player.Name
        ), 120)

        local displayName = safeShort(firstNonEmpty(
            custom.display_name,
            custom.displayName,
            customAccount.display_name,
            customAccount.displayName,
            customPlayer.display_name,
            customPlayer.displayName,
            player and player.DisplayName
        ), 120)

        local scId = normalizeScId(firstNonEmpty(
            custom.sc_id,
            custom.scId,
            custom.script_id,
            custom.scriptId,
            custom.id_code_list,
            custom.idCodeList,
            custom.code_list_id,
            custom.codeListId,
            customGame.sc_id,
            customGame.scId,
            customGame.id_code_list,
            customGame.idCodeList,
            customMeta.sc_id,
            customMeta.scId,
            customMeta.id_code_list,
            customMeta.idCodeList,
            self.scId
        ))

        return {
            sc_id = scId,
            game_id = gameId,
            game_name = gameName,
            place_id = placeId,
            akun_game_id = accountId,
            akun_username = accountUsername,
            game = {
                sc_id = scId,
                game_id = gameId,
                gameId = gameId,
                universe_id = gameId,
                universeId = gameId,
                game_name = gameName,
                gameName = gameName,
                place_id = placeId,
                placeId = placeId,
                job_id = safeShort(safeGameField("JobId", ""), 120),
            },
            account = {
                sc_id = scId,
                akun_game_id = accountId,
                akun_username = accountUsername,
                account_id = accountId,
                accountId = accountId,
                user_id = accountId,
                userId = accountId,
                username = accountUsername,
                name = accountUsername,
                display_name = displayName,
            },
            player = {
                akun_game_id = accountId,
                akun_username = accountUsername,
                user_id = accountId,
                userId = accountId,
                username = accountUsername,
                name = accountUsername,
                display_name = displayName,
                team = player and player.Team and player.Team.Name or nil,
            },
            meta = {
                sc_id = scId,
                game_id = gameId,
                gameId = gameId,
                game_name = gameName,
                gameName = gameName,
                place_id = placeId,
                placeId = placeId,
                akun_game_id = accountId,
                akun_username = accountUsername,
                account_id = accountId,
                username = accountUsername,
            },
        }
    end

    function Bridge:ApplyIdentityToPacket(packet)
        if type(packet) ~= "table" then return packet end

        local identity = self:GetIdentityPayload()
        packet.sc_id = packet.sc_id or identity.sc_id
        packet.game_id = packet.game_id or identity.game_id
        packet.game_name = packet.game_name or identity.game_name
        packet.place_id = packet.place_id or identity.place_id
        packet.akun_game_id = packet.akun_game_id or identity.akun_game_id
        packet.akun_username = packet.akun_username or identity.akun_username

        if type(packet.game) ~= "table" then packet.game = {} end
        for k, v in pairs(identity.game) do
            if packet.game[k] == nil or packet.game[k] == "" then packet.game[k] = v end
        end

        if type(packet.account) ~= "table" then packet.account = {} end
        for k, v in pairs(identity.account) do
            if packet.account[k] == nil or packet.account[k] == "" then packet.account[k] = v end
        end

        if type(packet.player) ~= "table" then
            packet.player = {}
        end
        for k, v in pairs(identity.player) do
            if packet.player[k] == nil or packet.player[k] == "" then packet.player[k] = v end
        end

        if type(packet.meta) ~= "table" then packet.meta = {} end
        for k, v in pairs(identity.meta) do
            if packet.meta[k] == nil or packet.meta[k] == "" then packet.meta[k] = v end
        end

        return packet
    end

    function Bridge:GetConfigSnapshot()
        if type(self.getConfig) == "function" then
            local ok, data = pcall(self.getConfig, self)
            if ok and type(data) == "table" then
                return data
            end
            return nil, "getConfig_failed: " .. tostring(data)
        end

        if self.saveFile then
            local data, err = readJsonFile(self.saveFile)
            if type(data) == "table" then
                return normalizeConfigEnvelope(data)
            end
            return data, err
        end

        return {}, nil
    end

    function Bridge:GetDefaultConfigSnapshot()
        if type(self.getDefaultConfig) == "function" then
            local ok, data = pcall(self.getDefaultConfig, self)
            if ok and type(data) == "table" then
                return data
            end
            return nil, "getDefaultConfig_failed: " .. tostring(data)
        end

        if self.defaultSaveFile then
            local data = readJsonFile(self.defaultSaveFile)
            if type(data) == "table" then
                return data
            end
        end

        if self.saveFile then
            local data = readJsonFile(self.saveFile)
            if type(data) == "table" then
                local pure = normalizeConfigEnvelope(data)
                return pure
            end
        end

        return self:GetConfigSnapshot()
    end

    function Bridge:ApplyRemoteConfig(config, message)
        if type(config) ~= "table" then
            self._lastConfigApplyOk = false
            self._lastConfigApplyError = "config_not_table"
            return false, "config_not_table"
        end

        config = normalizeConfigEnvelope(config)

        self._remoteApplying = true
        G.__NODEHUB_WS_REMOTE_APPLYING = true
        G["__NODEHUB_WS_REMOTE_APPLYING_" .. self.namespace] = true

        local okApply, applyErr = pcall(function()
            if type(self.applyConfig) == "function" then
                local ok, err = self.applyConfig(config, message, self)
                if ok == false then
                    error(tostring(err or "applyConfig returned false"))
                end
            elseif self.saveFile then
                local okWrite, errWrite = writeJsonFile(self.saveFile, config)
                if okWrite ~= true then
                    error(tostring(errWrite))
                end
            end

            -- V48: Jalankan hook UI apply sederhana setelah config/save/runtime masuk,
            -- sebelum afterApply melakukan rebuild tab aktif.
            pcall(function()
                nodeHubRunApplyUiHooks(self.namespace, config, message, self)
            end)

            if type(self.afterApply) == "function" then
                self.afterApply(config, message, self)
            end
        end)

        task.delay(1, function()
            self._remoteApplying = false
            G.__NODEHUB_WS_REMOTE_APPLYING = nil
            G["__NODEHUB_WS_REMOTE_APPLYING_" .. self.namespace] = nil
        end)

        if not okApply then
            self._lastConfigApplyOk = false
            self._lastConfigApplyError = tostring(applyErr)
            self:SetStatus("remote apply failed")
            return false, tostring(applyErr)
        end

        self._lastConfigApplyOk = true
        self._lastConfigApplyError = nil
        self:SetStatus("remote config applied")
        return true
    end

    function Bridge:GetStatsSnapshot(payload)
        local base = defaultStats(self.includePlayerList)
        local identity = self:GetIdentityPayload()

        base.game = type(base.game) == "table" and base.game or {}
        for k, v in pairs(identity.game) do
            if base.game[k] == nil or base.game[k] == "" then base.game[k] = v end
        end
        base.account = identity.account
        base.player = type(base.player) == "table" and base.player or {}
        for k, v in pairs(identity.player) do
            if base.player[k] == nil or base.player[k] == "" then base.player[k] = v end
        end
        base.local_player = type(base.local_player) == "table" and base.local_player or {}
        for k, v in pairs(identity.player) do
            if base.local_player[k] == nil or base.local_player[k] == "" then base.local_player[k] = v end
        end
        base.meta = type(base.meta) == "table" and base.meta or {}
        for k, v in pairs(identity.meta) do
            if base.meta[k] == nil or base.meta[k] == "" then base.meta[k] = v end
        end

        if type(payload) == "table" then
            for k, v in pairs(payload) do
                base[k] = v
            end
        end

        if self.collectAssets == true then
            local t = os.clock()
            local stealEggAssets = tostring(self.assetMode or self.namespace or "") == "steal_egg"
            -- SAE chunk/partial: jangan cache assets antar tick.
            if (not stealEggAssets)
            and type(self._assetsCache) == "table"
            and tonumber(self._assetsCacheAt)
            and (t - self._assetsCacheAt) < (tonumber(self.assetsInterval) or self.statsInterval) then
                base.assets = self._assetsCache
            else
                local okAssets, assets = pcall(collectGameAssets, self)
                if okAssets and type(assets) == "table" then
                    if not stealEggAssets then
                        self._assetsCache = assets
                        self._assetsCacheAt = t
                    end
                    self._assetsJustRebuilt = true
                    base.assets = assets
                    base.counters = base.counters or {}
                    base.counters.asset_items = type(assets.items) == "table" and #assets.items or 0
                    base.counters.asset_source = tostring(assets.source or "")
                else
                    base.assets_error = tostring(assets)
                    base.counters = base.counters or {}
                    base.counters.asset_error = tostring(assets)
                end
            end
            -- Fruit live refresh HANYA saat assets baru di-build.
            if type(base.assets) == "table" and self._assetsJustRebuilt == true then
                self._assetsJustRebuilt = false
                pcall(refreshFruitAssetsLive, base.assets)
                base.counters = base.counters or {}
                base.counters.asset_items = type(base.assets.items) == "table" and #base.assets.items or 0
            elseif type(base.assets) == "table" then
                base.counters = base.counters or {}
                base.counters.asset_items = type(base.assets.items) == "table" and #base.assets.items or 0
            end
        end

        if type(self.getStats) == "function" then
            local ok, res = pcall(self.getStats, base, self)
            if ok and type(res) == "table" then
                -- V10: jangan sampai custom getStats menghilangkan assets yang sudah dikoleksi.
                if self.collectAssets == true and type(base.assets) == "table" and type(res.assets) ~= "table" then
                    res.assets = base.assets
                end
                res.counters = type(res.counters) == "table" and res.counters or {}
                if type(base.counters) == "table" then
                    if res.counters.asset_items == nil then res.counters.asset_items = base.counters.asset_items end
                    if res.counters.asset_source == nil then res.counters.asset_source = base.counters.asset_source end
                    if res.counters.asset_error == nil then res.counters.asset_error = base.counters.asset_error end
                end
                return res
            elseif not ok then
                base.custom_error = tostring(res)
            end
        end

        return base
    end

    function Bridge:SendPacket(packet)
        if type(packet) ~= "table" then return false, "packet_not_table" end

        packet.namespace = packet.namespace or self.namespace
        packet.ws_id = packet.ws_id or self.wsId
        packet.script = packet.script or self.scriptName
        packet.ts = packet.ts or now()
        packet = self:ApplyIdentityToPacket(packet)

        local text, err = jsonEncode(packet)
        if not text then return false, "json_encode_failed: " .. tostring(err) end

        return safeSendSocket(self.socket, text)
    end

    function Bridge:SendConfig(reason, force, payload)
        if self._remoteApplying == true then return false, "remote_applying" end
        if self.connected ~= true then return false, "not_connected" end

        local config = payload
        if type(config) ~= "table" then
            local err
            config, err = self:GetConfigSnapshot()
            if type(config) ~= "table" then
                return false, err or "config_empty"
            end
        end

        config = normalizeConfigEnvelope(config)

        local configJson = jsonEncode(config)
        if type(configJson) ~= "string" then
            return false, "config_encode_failed"
        end

        if force ~= true and configJson == self.lastSentConfigJson then
            return true, "same_config_skip"
        end

        local ok, sendErr = self:SendPacket({
            type = "config_sync",
            reason = reason or "manual",
            config = config,
            meta = {
                place_id = safeGameField("PlaceId", 0),
                job_id = safeGameField("JobId", ""),
                user_id = (localPlayer() and localPlayer().UserId),
                username = (localPlayer() and localPlayer().Name),
                script = self.scriptName,
                game_name = self.gameName or self.scriptName,
                sc_id = self.scId,
            },
        })

        if ok then
            self.lastSentConfigJson = configJson
            self:SetStatus("config sent")
        else
            self:SetStatus("config send failed")
        end

        return ok, sendErr
    end

    function Bridge:SendDefaultConfig(reason, force, payload)
        if self._remoteApplying == true then return false, "remote_applying" end
        if self.connected ~= true then return false, "not_connected" end

        local config = payload
        if type(config) ~= "table" then
            local err
            config, err = self:GetDefaultConfigSnapshot()
            if type(config) ~= "table" then
                return false, err or "default_config_empty"
            end
        end

        config = normalizeConfigEnvelope(config)

        local configJson = jsonEncode(config)
        if type(configJson) ~= "string" then
            return false, "default_config_encode_failed"
        end

        if force ~= true and configJson == self.lastSentDefaultConfigJson then
            return true, "same_default_config_skip"
        end

        local ok, sendErr = self:SendPacket({
            type = "default_config_sync",
            reason = reason or "track_start",
            config = config,
            meta = {
                place_id = safeGameField("PlaceId", 0),
                job_id = safeGameField("JobId", ""),
                user_id = (localPlayer() and localPlayer().UserId),
                username = (localPlayer() and localPlayer().Name),
                script = self.scriptName,
                game_name = self.gameName or self.scriptName,
                sc_id = self.scId,
            },
        })

        if ok then
            self.lastSentDefaultConfigJson = configJson
            self:SetStatus("default config sent")
        else
            self:SetStatus("default config send failed")
        end

        return ok, sendErr
    end

    function Bridge:ConfigFileChanged(path, reason)
        if self._remoteApplying == true then return false, "remote_applying" end
        if self.connected ~= true then return false, "not_connected" end

        path = path or self.saveFile
        local data = nil

        if type(path) == "string" and path ~= "" then
            data = readJsonFile(path)
        end

        if type(data) ~= "table" then
            local err
            data, err = self:GetConfigSnapshot()
            if type(data) ~= "table" then
                return false, err or "config_file_empty"
            end
        end

        return self:ConfigChanged(reason or "file_changed", data)
    end

    function Bridge:ConfigChanged(reason, payload)
        if self._remoteApplying == true then return false, "remote_applying" end
        if self.connected ~= true then return false, "not_connected" end

        self._configDebounce = self._configDebounce + 1
        local token = self._configDebounce

        task.delay(0.45, function()
            if token ~= self._configDebounce then return end

            -- V13:
            -- Saat config berubah, kirim dua jalur:
            -- 1) default_config_sync  -> data_config_default
            -- 2) config_sync          -> data_config_realtime
            --
            -- Payload yang dikirim tetap payload yang sama dengan SAVE_FILE.
            if self.sendDefaultConfigOnChange == true then
                self:SendDefaultConfig(reason or "changed", true, payload)
            end

            self:SendConfig(reason or "changed", false, payload)
        end)

        return true
    end

    function Bridge:SendStats(reason, requestId, payload)
        if self.connected ~= true then return false, "not_connected" end

        local slim = false
        if type(payload) == "table" and payload.skip_heavy_assets == true then
            slim = true
            payload = nil
        end

        local prevCollect = self.collectAssets
        if slim then
            self.collectAssets = false
        end
        local okSnap, statsOrErr = pcall(function()
            return self:GetStatsSnapshot(payload)
        end)
        if slim then
            self.collectAssets = prevCollect
        end
        local stats = (okSnap and type(statsOrErr) == "table") and statsOrErr or {}
        if slim and tostring(self.assetMode or self.namespace or "") == "steal_egg" then
            local mon = G.StealEggMonitor or rawget(_G, "StealEggMonitor")
            -- Slim tidak boleh menimpa inventory jadi 0. Pakai cache collect penuh.
            if type(mon) == "table" and type(mon._cache) == "table" then
                stats.assets = mon._cache
                stats.assets_error = nil
            elseif type(mon) == "table" and type(mon.collect) == "function" then
                local okFull, fullAssets = pcall(mon.collect)
                if okFull and type(fullAssets) == "table" then
                    stats.assets = fullAssets
                    stats.assets_error = nil
                end
            end
        end

        local lpNow = localPlayer()
        local localPlayerInfo = type(stats.local_player) == "table" and stats.local_player or {}
        local player = type(stats.player) == "table" and stats.player or {
            user_id = localPlayerInfo.user_id or (lpNow and lpNow.UserId),
            name = localPlayerInfo.name or (lpNow and lpNow.Name),
            display_name = localPlayerInfo.display_name or (lpNow and lpNow.DisplayName),
            team = localPlayerInfo.team,
        }

        local identity = self:GetIdentityPayload()
        local meta = type(stats.meta) == "table" and stats.meta or {}
        meta.reason = reason or "interval"
        meta.namespace = meta.namespace or self.namespace
        meta.script = meta.script or self.scriptName
        for k, v in pairs(identity.meta) do
            if meta[k] == nil or meta[k] == "" then meta[k] = v end
        end

        local assetsPayload = type(stats.assets) == "table" and stats.assets or nil
        if self.collectAssets == true and type(assetsPayload) ~= "table" then
            if tostring(self.assetMode or self.namespace or "") == "steal_egg" then
                local mon = G.StealEggMonitor or rawget(_G, "StealEggMonitor")
                if type(mon) == "table" and type(mon.collectSlim) == "function" then
                    local okSlim, slimAssets = pcall(mon.collectSlim)
                    if okSlim and type(slimAssets) == "table" then
                        assetsPayload = slimAssets
                    end
                end
            end
        end
        if self.collectAssets == true and type(assetsPayload) ~= "table" then
            assetsPayload = {
                source = "empty",
                source_note = tostring(stats.assets_error or "assets_empty"),
                ts = now(),
                sheckles = (select(1, getSheckles(self))),
                total_items = 0,
                total_value = 0,
                items = {},
                overview = {
                    sheckles = (select(1, getSheckles(self))),
                    sheckles_label = formatShortNumber((select(1, getSheckles(self)))),
                    net_worth = (select(1, getSheckles(self))),
                    net_worth_label = formatShortNumber((select(1, getSheckles(self)))),
                    total_seeds = 0,
                    fruits_backpack = 0,
                    fruit_value_backpack = 0,
                    fruit_value_backpack_label = "0",
                    total_pets = 0,
                    total_items = 0,
                    inventory_value = 0,
                    garden_value = 0,
                    garden_value_label = "0",
                },
            }
        end

        local overviewPayload = nil
        if type(assetsPayload) == "table" and type(assetsPayload.overview) == "table" then
            overviewPayload = assetsPayload.overview
        elseif self.collectAssets == true then
            overviewPayload = {}
        end

        local packet = {
            type = "stats",
            track = true,
            active = self.trackEnabled == true,
            request_id = requestId,
            reason = reason or "interval",
            status = stats.status or "online",
            sc_id = identity.sc_id,
            game_id = identity.game_id,
            game_name = identity.game_name,
            place_id = identity.place_id,
            akun_game_id = identity.akun_game_id,
            akun_username = identity.akun_username,
            account = identity.account,
            game = type(stats.game) == "table" and stats.game or {},
            player = player,
            server = type(stats.server) == "table" and stats.server or {},
            device = type(stats.device) == "table" and stats.device or {
                namespace = self.namespace,
                script = self.scriptName,
                sc_id = identity.sc_id,
                user_id = lpNow and lpNow.UserId,
                username = lpNow and lpNow.Name,
                akun_game_id = identity.akun_game_id,
                akun_username = identity.akun_username,
            },
            performance = type(stats.performance) == "table" and stats.performance or {},
            counters = type(stats.counters) == "table" and stats.counters or {},
            -- localPlayer = helper function, bukan tabel. Posisi dari snapshot / local_player.
            position = (type(stats.position) == "table" and stats.position)
                or (type(localPlayerInfo.position) == "table" and localPlayerInfo.position)
                or nil,
            assets = type(assetsPayload) == "table" and assetsForWire(assetsPayload) or assetsPayload,
            overview = overviewPayload,
            assets_error = stats.assets_error,
            meta = meta,
        }

        -- In-game putus (weather kick / rejoin pending): Offline for monitor presence.
        do
            local reasonLower = string.lower(tostring(reason or ""))
            local statusLower = string.lower(tostring(packet.status or ""))
            local pendingKick = (G.__WEATHER_KICK_REJOIN_PENDING == true)
                or (rawget(_G, "__WEATHER_KICK_REJOIN_PENDING") == true)
            if pendingKick
                or statusLower == "rejoining"
                or statusLower == "waiting"
                or string.find(reasonLower, "weather_kick", 1, true)
                or string.find(reasonLower, "weatherkick", 1, true)
                or string.find(reasonLower, "rejoin", 1, true)
            then
                packet.status = "offline"
                packet.meta = type(packet.meta) == "table" and packet.meta or {}
                packet.meta.game_state = "waiting"
                packet.meta.ingame = false
                if pendingKick and (packet.meta.reason == nil or packet.meta.reason == "") then
                    packet.meta.reason = "weather_kick"
                end
            end
        end


        if type(packet.game) == "table" then
            for k, v in pairs(identity.game) do
                if packet.game[k] == nil or packet.game[k] == "" then packet.game[k] = v end
            end
            if packet.game.game_name == nil and packet.game.gameName == nil then
                packet.game.game_name = self.gameName or self.scriptName
            end
        end
        if type(packet.player) == "table" then
            for k, v in pairs(identity.player) do
                if packet.player[k] == nil or packet.player[k] == "" then packet.player[k] = v end
            end
        end
        if type(packet.device) == "table" then
            packet.device.game_name = packet.device.game_name or self.gameName or self.scriptName
            packet.device.akun_game_id = packet.device.akun_game_id or identity.akun_game_id
            packet.device.akun_username = packet.device.akun_username or identity.akun_username
        end

        if type(packet.counters) == "table" then
            packet.counters.nodehub_helper_version = "2026-09-24-static-v85-sendstats-pos"
            if identity.sc_id ~= nil then
                packet.counters.sc_id = identity.sc_id
            end
            packet.counters.assets_payload_type = type(assetsPayload)
            packet.counters.overview_payload_type = type(overviewPayload)

            if type(assetsPayload) == "table" then
                packet.counters.asset_items = type(assetsPayload.items) == "table" and #assetsPayload.items or 0
                packet.counters.asset_source = tostring(assetsPayload.source or packet.counters.asset_source or "")

                local okAssetJson, assetJson = pcall(function()
                    return HttpService:JSONEncode(packet.assets)
                end)
                if okAssetJson and type(assetJson) == "string" then
                    packet.counters.assets_json_bytes = #assetJson
                end
            end
        end

        local ok, sendErr = self:SendPacket(packet)
        if ok then
            return true
        end
        -- Inventory/collect kadang tidak JSON-safe (userdata/inf). Jangan sampai
        -- identity snapshot hilang — dashboard butuh row + last_seen.
        if slim ~= true then
            packet.assets = {
                source = "encode_fallback",
                source_note = tostring(sendErr or "send_failed"),
                ts = now(),
                items = {},
            }
            packet.overview = type(packet.overview) == "table" and packet.overview or {}
            packet.assets_error = tostring(sendErr)
            return self:SendPacket(packet)
        end
        return false, sendErr
    end

    function Bridge:UploadInventoryHttp(assets)
        if type(assets) ~= "table" then
            return false, "assets_not_table"
        end
        local items = type(assets.items) == "table" and assets.items or {}
        if #items == 0 then
            return false, "items_empty"
        end

        local function slim(row)
            if type(row) ~= "table" then return row end
            local out = {
                category = row.category,
                group = row.group,
                key = row.key or row.uid,
                uid = row.uid or row.key,
                name = row.name,
                type = row.type or row.name,
                count = row.count or 1,
                rarity = row.rarity,
                kg = row.kg,
                equipped = row.equipped,
                favorite = row.favorite,
                state = row.state,
            }
            local mut = row.muts or row.mutation or row.mutations
            if mut ~= nil and mut ~= "" then
                out.muts = mut
                out.mutation = mut
            end
            local earn = row.earn or row.rate
            if earn ~= nil then out.earn = earn end
            if row.egg_name then out.egg_name = row.egg_name end
            if row.time_label then out.time_label = row.time_label end
            if row.asset_id then out.asset_id = row.asset_id end
            return out
        end

        local slimItems = {}
        for i = 1, #items do
            slimItems[i] = slim(items[i])
        end

        local authToken, authErr = self:BuildAuthToken()
        if not authToken then
            return false, authErr or "auth_token_failed"
        end

        local identity = self:GetIdentityPayload()
        local base = tostring(self.wsBaseUrl or "")
        local apiUrl = "https://appsoc.nodemonitor.io/api/device/inventory"
        if string.find(base, "127.0.0.1", 1, true) or string.find(base, "localhost", 1, true) then
            apiUrl = "http://127.0.0.1:3881/api/device/inventory"
        end

        local payload = {
            ws_id = self.wsId,
            auth_token = authToken,
            akun_game_id = identity.akun_game_id or (identity.player and identity.player.user_id),
            akun_username = identity.akun_username or (identity.player and identity.player.username),
            game_id = identity.game_id,
            place_id = identity.place_id,
            game_name = self.gameName or self.scriptName or "Steal An Egg",
            status = "online",
            reason = "http_inventory",
            assets = {
                source = "steal_egg.save",
                source_note = "http_inventory",
                sheckles = assets.sheckles,
                total_items = #slimItems,
                total_value = assets.total_value,
                items = slimItems,
                overview = assets.overview,
            },
            overview = assets.overview,
        }

        local body, status = nil, 0
        local ok, errOrBody = pcall(function()
            local b, s = httpPostJson(apiUrl, payload)
            body, status = b, s
            return b
        end)
        if not ok then
            return false, tostring(errOrBody)
        end
        if tonumber(status) ~= 200 then
            return false, "http_status_" .. tostring(status) .. ":" .. tostring(body)
        end
        return true, body
    end

    function Bridge:SendPresence(reason)
        if self.connected ~= true then return false, "not_connected" end
        local money = 0
        pcall(function()
            money = select(1, getSheckles(self)) or 0
        end)
        return self:SendPacket({
            type = "stats",
            track = true,
            active = self.trackEnabled == true,
            status = "online",
            reason = reason or "presence",
            assets = {
                source = "presence",
                source_note = "items_unchanged",
                items = {},
            },
            overview = {
                items_unchanged = true,
                cash = money,
                money = money,
            },
        })
    end

    function Bridge:StartStatsLoop()
        self._statsToken = self._statsToken + 1
        local token = self._statsToken
        self._statsStarted = true
        local stealEgg = tostring(self.assetMode or self.namespace or "") == "steal_egg"

        task.spawn(function()
            -- SAE HP: diam dulu setelah hello. Config/stats awal bikin ON/OFF.
            if stealEgg then
                task.wait(math.max(6.5, (tonumber(self.statsInterval) or 5) + 2))
            end
            while token == self._statsToken and self.trackEnabled == true do
                if self.connected == true then
                    local mon = stealEgg and (G.StealEggMonitor or rawget(_G, "StealEggMonitor"))
                    if stealEgg and type(mon) == "table" and type(mon._wireChunks) == "table" then
                        -- Sedang upload chunk: jangan ganggu dengan stats penuh.
                        pcall(function()
                            self:SendPresence("chunk_wait")
                        end)
                    else
                        self:SendStats("interval")
                    end
                end
                task.wait(self.statsInterval)
            end
            if token == self._statsToken then
                self._statsStarted = false
            end
        end)
    end

    function Bridge:SetTrack(on, opts)
        on = on == true
        opts = type(opts) == "table" and opts or {}
        local light = opts.light == true

        -- Boot spam EnsureTracked: jangan ulang SendConfig/SendStats penuh.
        if on == true
            and light == true
            and self.trackEnabled == true
            and self.active == true
            and self.connected == true
            and self._statsStarted == true
        then
            pcall(function()
                self:SendPacket({
                    type = "track_status",
                    active = true,
                    enabled = true,
                    track = true,
                    sc_id = self.scId,
                    reason = tostring(opts.reason or "ensure_light"),
                })
            end)
            self:SetStatus("active")
            return true, "already_tracking_light"
        end

        self.trackEnabled = on
        self.active = on
        self:SavePrefs()

        if self.connected == true then
            self:SendPacket({
                type = "track_status",
                active = on,
                enabled = on,
                track = on,
                sc_id = self.scId,
            })
        end

        if on then
            local stealEgg = tostring(self.assetMode or self.namespace or "") == "steal_egg"
            local deferHeavy = opts.deferHeavy == true or stealEgg == true
            if light ~= true and deferHeavy ~= true then
                if self.sendDefaultConfigOnTrack ~= false then
                    self:SendDefaultConfig("track_start", true)
                end
                self:SendConfig("track_start", true)
            end
            if self._statsStarted ~= true then
                self:StartStatsLoop()
            end
            if light ~= true and deferHeavy ~= true then
                self:SendStats("track_enabled")
            elseif light ~= true and deferHeavy == true then
                pcall(function()
                    self:SendPresence("connect_presence")
                end)
                local tok = self._connectToken
                -- SAE: jangan kirim config otomatis — HP putus (hello+config → ON/OFF).
                -- Config cukup manual / jarang.
                task.delay(stealEgg and 12 or 1.4, function()
                    if tok ~= self._connectToken or self.connected ~= true then return end
                    if stealEgg then
                        return
                    end
                    if self.sendDefaultConfigOnTrack ~= false then
                        self:SendDefaultConfig("track_start_deferred", true)
                    end
                    self:SendConfig("track_start_deferred", true)
                end)
                task.delay(stealEgg and 8 or 2.8, function()
                    if tok ~= self._connectToken or self.connected ~= true then return end
                    self:SendStats("track_enabled")
                end)
            end
            self:SetStatus("active")
        else
            self._statsToken = self._statsToken + 1
            self._statsStarted = false
            self:SetStatus("OFF")
        end
        return true
    end

    function Bridge:HandleCommand(message)
        if type(message) ~= "table" then
            return false, "message_not_table"
        end

        local commandName = tostring(message.command or message.name or message.type or "command")
        local payload = message.payload or message.data or message.config or message
        local ok, res, err

        if message.type == "auto_gift_command" then
            local handler = self.autoGiftHandler
                or (type(self.commandHandlers) == "table" and self.commandHandlers.auto_gift)
                or (type(self.commandHandlers) == "table" and self.commandHandlers.auto_gift_command)
            if type(handler) ~= "function" then
                local G2 = (getgenv and getgenv()) or _G
                handler = G2.__NODEHUB_WS_AUTO_GIFT_COMMAND
                    or rawget(_G, "__NODEHUB_WS_AUTO_GIFT_COMMAND")
                    or G2.__GAG2_AUTO_GIFT_COMMAND
                    or rawget(_G, "__GAG2_AUTO_GIFT_COMMAND")
            end
            if type(handler) ~= "function" then
                return false, "auto_gift_handler_not_found"
            end
            ok, res, err = pcall(handler, payload, message, self)
        else
            local handler = self.onCommand
            if type(self.commandHandlers) == "table" and type(self.commandHandlers[commandName]) == "function" then
                handler = self.commandHandlers[commandName]
            end
            if type(handler) ~= "function" then
                return false, "command_handler_not_found"
            end
            ok, res, err = pcall(handler, commandName, payload, message, self)
        end

        if not ok then
            return false, tostring(res)
        end
        if res == false then
            return false, tostring(err or "handler_returned_false")
        end
        return true, res
    end

    function Bridge:HandleMessage(raw)
        raw = tostring(raw or "")
        if raw == "" then return end

        local message = jsonDecode(raw)
        if type(message) ~= "table" then
            self:SetStatus("message")
            return
        end

        if type(self.onMessage) == "function" then
            local okCustom, stop = pcall(self.onMessage, message, raw, self)
            if okCustom and stop == true then return end
        end

        if message.type == "connected" then
            self:SetStatus(message.success == false and "server rejected" or "connected")
            return
        end

        if message.type == "error" then
            self:SetStatus("server error: " .. tostring(message.code or message.error or "unknown"))
            return
        end

        if message.type == "hello_ack" then
            if self.useServerStatsInterval == true and tonumber(message.stats_interval_ms) then
                local sec = tonumber(message.stats_interval_ms) / 1000
                if sec >= 2 then
                    self.statsInterval = sec
                    self:SavePrefs()
                end
            end
            self:SetStatus(message.success == true and "server ack" or "server rejected")
            return
        end

        if message.type == "track_status_ack" then
            self:SetStatus(message.active == true and "track active" or "track inactive")
            return
        end

        if message.type == "stats_ack" then
            self:SetStatus(message.db_saved == true and "stats saved" or "stats sent")
            return
        end

        if message.type == "config_sync_ack" then
            self:SetStatus(message.success == true and "config saved" or "config rejected")
            return
        end

        if message.type == "config_update"
        or message.type == "config_apply"
        or message.type == "apply_config" then
            self._lastConfigUpdateAt = now()
            self._lastConfigRequestId = message.request_id
            self:SetStatus("remote config received")
            local ok, err = self:ApplyRemoteConfig(message.config or message.payload or message.data, message)
            self._lastConfigApplyOk = ok == true
            self._lastConfigApplyError = ok and nil or tostring(err)
            self:SendPacket({
                type = "config_ack",
                request_id = message.request_id,
                success = ok == true,
                ok = ok == true,
                error = ok and nil or tostring(err),
            })
            return
        end

        if message.type == "get_config" then
            if tostring(self.assetMode or self.namespace or "") == "steal_egg" then
                -- HP SAE: balas config besar bikin putus. Skip auto.
                return
            end
            self:SendConfig("server_request", true)
            return
        end

        if message.type == "stats_request"
        or message.type == "get_stats"
        or message.type == "request_stats"
        or message.type == "refresh_stats"
        or message.type == "refresh_assets"
        or message.type == "asset_refresh"
        or message.type == "get_assets" then
            -- V26: manual refresh dari web harus ambil data asset terbaru, bukan cache interval sebelumnya.
            self._assetsCache = nil
            self._assetsCacheAt = 0
            self:SetStatus("refresh requested")
            self:SendStats(message.reason or "server_refresh", message.request_id)
            return
        end

        if message.type == "auto_gift_command"
        or message.type == "mail_controller_gift_command"
        or message.type == "mail_controller_gift_cancel"
        or message.type == "command" then
            self._lastCommandAt = now()
            self._lastCommandType = message.type
            self:SetStatus("command received")
            local ok, res = self:HandleCommand(message)
            self._lastCommandOk = ok == true
            self._lastCommandError = ok and nil or tostring(res)
            local ackType = "command_ack"
            if message.type == "auto_gift_command" then
                ackType = "auto_gift_ack"
            elseif message.type == "mail_controller_gift_command"
                or message.type == "mail_controller_gift_cancel" then
                -- Rich per-batch acks are sent by the MC module; this is a thin completion envelope.
                ackType = "mail_controller_gift_ack"
            end
            self:SendPacket({
                type = ackType,
                request_id = message.request_id,
                phase = (ackType == "mail_controller_gift_ack") and "handler_done" or nil,
                job_id = type(message.payload) == "table" and message.payload.job_id or nil,
                success = ok == true,
                ok = ok == true,
                error = ok and nil or tostring(res),
            })
            if ok then
                self:SetStatus(message.type == "auto_gift_command" and "auto gift received" or "command received")
            else
                self:SetStatus("command failed")
            end
            return
        end

        if message.type == "track" then
            self:SetTrack(message.enabled == true or message.active == true)
            return
        end

        if message.type == "ping" then
            self:SendPacket({
                type = "pong",
                request_id = message.request_id,
            })
            return
        end
    end

    local function extractSocketMessage(...)
        local n = select("#", ...)
        for i = 1, n do
            local v = select(i, ...)
            if type(v) == "string" and v ~= "" then
                return v
            end
        end

        for i = 1, n do
            local v = select(i, ...)
            if type(v) == "table" then
                for _, key in ipairs({ "Data", "data", "Message", "message", "Payload", "payload", "Text", "text" }) do
                    if type(v[key]) == "string" and v[key] ~= "" then
                        return v[key]
                    end
                end
            end
        end

        local first = select(1, ...)
        if first ~= nil then
            return tostring(first)
        end
        return ""
    end

    function Bridge:BindSocket(socket, isRetry)
        if not socket then
            self._socketMessageBound = false
            self._socketCloseBound = false
            self._socketMessageBoundVia = "no_socket"
            return false, false
        end

        if self._boundSocket == socket and self._socketMessageBound == true and isRetry ~= true then
            return true, self._socketCloseBound == true
        end

        local function onMessage(...)
            local msg = extractSocketMessage(...)
            self._lastRawMessageAt = now()
            self._lastRawMessagePreview = tostring(msg or ""):sub(1, 300)
            self:HandleMessage(msg)
        end

        local function onClosed()
            self.connected = false
            self:SetStatus("socket closed")
            if self.active == true and self.autoReconnect == true then
                self:SetStatus("reconnecting")
                self:ReconnectLater()
            end
        end

        local boundMessage = false
        local boundClose = false
        local messageVia = nil
        local closeVia = nil
        local attempts = {}

        local function trySignal(name, fn)
            if not socket or type(name) ~= "string" then return false end
            local okMember, member = pcall(function()
                return socket[name]
            end)
            if not okMember then
                attempts[#attempts + 1] = name .. ":read_error"
                return false
            end
            if member == nil then
                attempts[#attempts + 1] = name .. ":nil"
                return false
            end

            local okBind, via = bindSignal(member, fn)
            if okBind == true then
                attempts[#attempts + 1] = name .. ":" .. tostring(via or "signal")
                return true, tostring(via or "signal")
            end

            attempts[#attempts + 1] = name .. ":" .. tostring(via or "not_signal")
            return false
        end

        local function tryAssign(name, fn)
            if not socket or type(name) ~= "string" then return false end
            local okAssign = pcall(function()
                socket[name] = fn
            end)
            if okAssign == true then
                attempts[#attempts + 1] = name .. ":assigned"
                return true, "assigned"
            end
            attempts[#attempts + 1] = name .. ":assign_failed"
            return false
        end

        -- V29: Auto Gift action for GAG2 web command; keeps generic handler override safe.
-- V28: single Auto Gift command + safer asset/sheckles flow + refresh stats/assets.
-- V24: balik ke pola listener lama yang stabil dulu.
        -- Referensi lama executor: socket.OnMessage:Connect(fn) dan socket.MessageReceived:Connect(fn).
        for _, name in ipairs({ "OnMessage", "MessageReceived" }) do
            local ok, via = trySignal(name, onMessage)
            if ok then
                boundMessage = true
                messageVia = name .. ":" .. tostring(via or "signal")
                break
            end
        end

        -- Tambahan aman untuk executor lain, tapi tidak memanggil member sebagai function.
        if not boundMessage then
            for _, name in ipairs({ "OnData", "Message", "message", "onmessage" }) do
                local ok, via = trySignal(name, onMessage)
                if ok then
                    boundMessage = true
                    messageVia = name .. ":" .. tostring(via or "signal")
                    break
                end
            end
        end

        -- Fallback property callback. Ini hanya dipakai kalau signal tidak tersedia.
        if not boundMessage then
            for _, name in ipairs({ "OnMessage", "MessageReceived", "onmessage" }) do
                local ok, via = tryAssign(name, onMessage)
                if ok then
                    boundMessage = true
                    messageVia = name .. ":" .. tostring(via or "assigned")
                    break
                end
            end
        end

        for _, name in ipairs({ "OnClose", "Closed", "CloseEvent", "onclose" }) do
            local ok, via = trySignal(name, onClosed)
            if ok then
                boundClose = true
                closeVia = name .. ":" .. tostring(via or "signal")
                break
            end
        end

        if not boundClose then
            for _, name in ipairs({ "OnClose", "Closed", "onclose" }) do
                local ok, via = tryAssign(name, onClosed)
                if ok then
                    boundClose = true
                    closeVia = name .. ":" .. tostring(via or "assigned")
                    break
                end
            end
        end

        self._boundSocket = socket
        self._socketMessageBound = boundMessage == true
        self._socketCloseBound = boundClose == true
        self._socketMessageBoundVia = messageVia or "not_bound"
        self._socketCloseBoundVia = closeVia or "not_bound"
        self._socketMessageBindAttempts = table.concat(attempts, " | ")

        if not boundMessage then
            self:SetStatus("connected, receiver not ready")
        end

        return self._socketMessageBound, self._socketCloseBound
    end

    function Bridge:Connect(wsId)
        wsId = trim(wsId or self.wsId)
        if wsId == "" then
            self:SetStatus("ws_id empty")
            return false, "ws_id_empty"
        end

        self.wsId = wsId
        self.active = true
        self:SavePrefs()

        self._connectToken = self._connectToken + 1
        local token = self._connectToken

        if self.socket then
            safeCloseSocket(self.socket)
            self.socket = nil
        end

        local authToken, authErr = self:BuildAuthToken()
        if not authToken then
            self:SetStatus(authErr)
            return false, authErr
        end

        local url, urlErr = makeUrl(self.wsBaseUrl, self.wsId, authToken)
        if not url then
            self:SetStatus(urlErr)
            return false, urlErr
        end

        local connector = findWebSocketConnect()
        if not connector then
            self:SetStatus("connection api not found")
            return false, "connection_api_not_found"
        end

        self:SetStatus("connecting")

        local ok, sockOrErr = pcall(connector, url)
        if not ok or not sockOrErr then
            self.connected = false
            self:SetStatus("connect failed")
            if self.active == true and self.autoReconnect == true then
                self:ReconnectLater()
            end
            return false, tostring(sockOrErr)
        end

        if token ~= self._connectToken then
            safeCloseSocket(sockOrErr)
            return false, "connect_cancelled"
        end

        self.socket = sockOrErr
        self.connected = true
        self:BindSocket(self.socket)

        -- V29: Auto Gift action for GAG2 web command; keeps generic handler override safe.
-- V28: single Auto Gift command + safer asset/sheckles flow + refresh stats/assets.
-- V24: beberapa executor baru menyiapkan signal OnMessage setelah object socket jadi.
        -- Kalau bind pertama gagal, coba bind ulang beberapa kali tanpa mengubah alur lain.
        for _, delaySec in ipairs({ 0.15, 0.75, 2 }) do
            task.delay(delaySec, function()
                if token ~= self._connectToken then return end
                if self.socket ~= sockOrErr then return end
                if self.connected ~= true then return end
                if self._socketMessageBound == true then return end

                self._listenerRetryCount = (tonumber(self._listenerRetryCount) or 0) + 1
                self:BindSocket(self.socket, true)
            end)
        end

        self:SetStatus("connected")

        local player = localPlayer()
        self:SendPacket({
            type = "hello",
            version = "nodehub_ws_static_track_state_v69",
            meta = {
                namespace = self.namespace,
                script = self.scriptName,
                user_id = player and player.UserId,
                username = player and player.Name,
                sc_id = self.scId,
                place_id = safeGameField("PlaceId", 0),
                job_id = safeGameField("JobId", ""),
            },
        })

        -- SAE HP: jangan flood config+collect di detik pertama (socket putus → ON/OFF).
        -- Presence kecil dulu biar dashboard online, collect belakangan.
        if tostring(self.assetMode or self.namespace or "") == "steal_egg" then
            pcall(function()
                self:SendPresence("hello_presence")
            end)
            if self.trackEnabled == true then
                self:SetTrack(true, { deferHeavy = true })
            end
        else
            self:SendConfig("connect", true)
            if self.trackEnabled == true then
                self:SetTrack(true)
            end
        end

        return true
    end

    function Bridge:Disconnect()
        self.active = false
        self.trackEnabled = false
        self.connected = false
        self._statsStarted = false
        self._connectToken = self._connectToken + 1
        self._statsToken = self._statsToken + 1
        self:SavePrefs()

        if self.socket then
            safeCloseSocket(self.socket)
        end

        self.socket = nil
        self:SetStatus("OFF")
        return true
    end

    function Bridge:ReconnectLater()
        if self._reconnectQueued == true then
            return
        end
        self._reconnectQueued = true
        task.delay(self.reconnectDelay, function()
            self._reconnectQueued = false
            if self.active ~= true then return end
            if self.connected == true then return end
            self:SetStatus("reconnecting")
            local ok = self:Connect(self.wsId)
            if ok ~= false and self.active == true then
                task.delay(0.35, function()
                    if self.active == true and self.connected == true then
                        self:SetTrack(true)
                    end
                end)
            end
        end)
    end

    function Bridge:SetTrackToggleOff(silent)
        local api = self._trackToggleApi
        local setter = self._trackToggleSetter
        if type(api) == "table" then
            if type(api.setOff) == "function" then
                pcall(api.setOff, silent ~= false)
                return
            elseif type(api.set) == "function" then
                pcall(api.set, false, silent ~= false)
                return
            end
        end
        if type(setter) == "function" then
            pcall(setter, false, silent ~= false)
        end
    end

    function Bridge:SetActive(on)
        on = on == true
        if on then
            if trim(self.wsId) == "" then
                self.active = false
                self.trackEnabled = false
                self:SavePrefs()
                self:SetStatus("ws_id empty")
                self:SetTrackToggleOff(true)
                return false, "ws_id_empty"
            end
            self.active = true
            self.trackEnabled = true
            self:SavePrefs()
            -- Connect sukses sudah SetTrack. Jangan delay SetTrack buta.
            return self:Connect(self.wsId)
        else
            self:SetTrack(false)
            local token = self._connectToken
            task.delay(0.45, function()
                if token ~= self._connectToken then return end
                if self.active == false or self.trackEnabled == false then
                    self:Disconnect()
                end
            end)
        end
    end

    function Bridge:EnsureTracked(reason)
        if not (self.active == true or self.trackEnabled == true) then
            return false, "track_state_off"
        end
        if trim(self.wsId) == "" then
            return false, "ws_id_empty"
        end

        self._ensureTrackedReason = tostring(reason or "ensure_tracked")
        self._ensureTrackedAt = now()

        if self.connected == true then
            self:SetTrack(true, { light = true, reason = self._ensureTrackedReason })
            return true, "resent_while_connected_light"
        end

        if self._ensureConnectScheduled == true then
            return true, "connect_coalesced"
        end
        self._ensureConnectScheduled = true
        self.active = true
        self.trackEnabled = true
        self:SavePrefs()
        task.defer(function()
            task.wait(0.2)
            self._ensureConnectScheduled = false
            if not (self.active == true or self.trackEnabled == true) then return end
            if self.connected == true then return end
            self:Connect(self.wsId)
        end)
        return true, "connect_scheduled"
    end

    function Bridge:ScheduleEnsureTrackedRetries(reason)
        if self._ensureTrackedRetryScheduled == true then
            return true, "retry_already_scheduled"
        end
        if not (self.active == true or self.trackEnabled == true) then
            return false, "track_state_off"
        end

        self._ensureTrackedRetryScheduled = true
        local baseReason = tostring(reason or "ensure_retry")
        local delays = { 1.2, 3, 8, 15 }

        for i, delaySec in ipairs(delays) do
            task.delay(delaySec, function()
                if i >= #delays then
                    self._ensureTrackedRetryScheduled = false
                end
                if self.autoStartOnBoot == false then return end
                if not (self.active == true or self.trackEnabled == true) then return end
                if trim(self.wsId) == "" then return end

                if self.connected == true then
                    self:SetTrack(true, { light = true, reason = baseReason .. "_connected" })
                    self._ensureTrackedRetryScheduled = false
                    return
                end

                self:EnsureTracked(baseReason .. "_" .. tostring(i))
            end)
        end

        return true, "retry_scheduled"
    end

    function Bridge:ScheduleAutoResume(reason)
        -- V35:
        -- Auto execute harus bisa ON tanpa menunggu user membuka section Track Server.
        -- Fungsi ini aman dipanggil berkali-kali dari Setup/GAG2/Section.
        if self.autoStartOnBoot == false then
            return false, "auto_start_disabled"
        end

        if not (self.active == true or self.trackEnabled == true) then
            return false, "track_state_off"
        end

        if trim(self.wsId) == "" then
            self.active = false
            self.trackEnabled = false
            self:SavePrefs()
            self:SetStatus("ws_id empty")
            return false, "ws_id_empty"
        end

        -- Sudah connected → ping ringan saja (jangan SendConfig/SendStats ulang).
        if self.connected == true then
            self:SetTrack(true, { light = true, reason = tostring(reason or "auto_resume") })
            return true, "already_connected"
        end

        self._autoResumeReason = tostring(reason or "auto_execute")
        self:ScheduleEnsureTrackedRetries(self._autoResumeReason)

        if self._autoResumeScheduled == true then
            return true, "already_scheduled"
        end

        self._autoResumeScheduled = true

        local scheduledWsId = self.wsId
        local delaySec = tonumber(self.autoStartDelay) or 0.65
        if delaySec < 0 then delaySec = 0 end

        task.delay(delaySec, function()
            self._autoResumeScheduled = false

            if self.autoStartOnBoot == false then return end
            if not (self.active == true or self.trackEnabled == true) then return end
            if trim(self.wsId) == "" then
                self.active = false
                self.trackEnabled = false
                self:SavePrefs()
                self:SetStatus("ws_id empty")
                return
            end
            if scheduledWsId ~= nil and tostring(scheduledWsId) ~= "" and tostring(scheduledWsId) ~= tostring(self.wsId) then
                return
            end

            self._autoResumeLastAt = now()
            if self.connected == true then
                self:SetTrack(true)
                return
            end
            self:EnsureTracked(self._autoResumeReason or "auto_execute")
        end)

        return true, "scheduled"
    end

    local function newBridge(opts)
        opts = type(opts) == "table" and opts or {}

        local namespace = safeToString(opts.namespace or opts.name or "default", "default")
        local self = setmetatable({
            namespace = namespace,
            scriptName = safeToString(opts.scriptName or namespace),
            gameName = safeToString(opts.gameName or opts.scriptName or namespace),
            gameId = safeShort(opts.gameId or opts.universeId or safeGameField("GameId", 0), 80),
            placeId = safeShort(opts.placeId or safeGameField("PlaceId", 0), 80),
            accountId = safeShort(opts.accountId or opts.akunGameId or opts.akun_game_id or (LP and LP.UserId) or "0", 80),
            accountUsername = safeShort(opts.accountUsername or opts.akunUsername or opts.akun_username or (LP and LP.Name) or "unknown", 120),
            scId = normalizeScId(firstNonEmpty(
                opts.sc_id,
                opts.scId,
                opts.script_id,
                opts.scriptId,
                opts.id_code_list,
                opts.idCodeList,
                opts.code_list_id,
                opts.codeListId
            )),
            -- WS MODE DEFAULT: ganti string di or "..."  (LOCAL / PRODUCTION)
            -- LOCAL:      "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}"
            -- PRODUCTION: "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}"
            wsBaseUrl = safeToString(opts.wsBaseUrl or opts.baseUrl or "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}"), -- << PRODUCTION (aktif)
            authPassword = safeToString(opts.authPassword or opts.deviceAuthPassword or opts.wsPassword or ""),
            saveFile = resolveConfigSaveFile(opts.saveFile, namespace),
            defaultSaveFile = resolveConfigSaveFile(opts.defaultSaveFile or opts.saveFile, namespace),
            settingsFile = opts.settingsFile or opts.trackStateFile or ("nodehub_ws_static/" .. namespace .. "_" .. tostring(LP and LP.UserId or "unknown") .. ".json"),
            persistSettings = (opts.persistSettings == true or opts.rememberWsId == true),
            persistTrackState = not (opts.persistTrackState == false or opts.rememberTrackState == false),
            autoStartOnBoot = not (opts.autoStartOnBoot == false or opts.autoResumeTrack == false),
            autoStartDelay = tonumber(opts.autoStartDelay) or 0.65,
            statsInterval = tonumber(opts.statsInterval) or 5,
            reconnectDelay = tonumber(opts.reconnectDelay) or 5,
            active = false,
            connected = false,
            trackEnabled = false,
            restoreActive = opts.restoreActive == true,
            sendDefaultConfigOnTrack = opts.sendDefaultConfigOnTrack ~= false,
            wsId = safeToString(opts.wsId or ""),
            socket = nil,
            lastSentConfigJson = nil,
            lastSentDefaultConfigJson = nil,
            _connectToken = 0,
            _statsToken = 0,
            _configDebounce = 0,
            _remoteApplying = false,
            _statusLabel = nil,
            collectAssets = false,
            assetMode = "",
            assetCategories = nil,
            assetValueProvider = nil,
            getIdentity = nil,
            getAssets = nil,
            getMoney = nil,
            getSheckles = nil,
            onCommand = nil,
            autoGiftHandler = nil,
            commandHandlers = {},
            assetsInterval = tonumber(opts.assetsInterval or opts.statsInterval) or 5,
            _assetsCache = nil,
            _assetsCacheAt = 0,
        }, Bridge)

        if self.statsInterval < 2 then self.statsInterval = 2 end

        self:UpdateOptions(opts)
        self:LoadPrefs()
        -- NM_MONITOR / resolve: jangan biarkan file track lama (OFF) menimpa wsId yang baru dikirim.
        if opts.wsId ~= nil or opts.ws_id ~= nil then
            local nextWs = trim(safeToString(opts.wsId or opts.ws_id or ""))
            if nextWs ~= "" then
                self.wsId = nextWs
            end
        end
        if NodeHubWS.IsNMMonitorEnabled() == true and trim(self.wsId) ~= "" then
            self:SetStatus("OFF")
        else
            self:SetStatus("OFF")
        end
        self:ScheduleAutoResume("load_prefs")

        return self
    end

    function NodeHubWS.Setup(opts)
        opts = type(opts) == "table" and opts or {}
        local namespace = safeToString(opts.namespace or opts.name or "default", "default")

        local bridge = NodeHubWS._bridges[namespace]
        if type(bridge) == "table" then
            bridge:UpdateOptions(opts)
            -- V35: kalau bridge dibuat sebelum UI lengkap, opsi prod bisa datang belakangan.
            -- Jadwalkan auto resume lagi setelah opsi URL/auth/ws_id siap.
            if type(bridge.ScheduleAutoResume) == "function" then
                bridge:ScheduleAutoResume("setup_update")
            end
            return bridge
        end

        bridge = newBridge(opts)
        NodeHubWS._bridges[namespace] = bridge

        local globalName = "__NODEHUB_WS_" .. namespace:upper():gsub("[^A-Z0-9_]", "_")
        G[globalName] = bridge
        _G[globalName] = bridge

        return bridge
    end

    function NodeHubWS.Get(namespace)
        namespace = safeToString(namespace or "default", "default")
        return NodeHubWS._bridges[namespace]
    end

    function NodeHubWS.Section(ui, opts)
        opts = type(opts) == "table" and opts or {}

        -- FIX DUPLICATE UI:
        -- Kalau section Monitor Account untuk namespace + UI ini masih hidup,
        -- pakai section yang sudah ada. Jangan create row/toggle/listener ulang.
        local namespace = safeToString(opts.namespace or opts.name or "default", "default")
        local existingBridge = NodeHubWS._bridges[namespace]

        if type(existingBridge) == "table" and type(ui) == "table" then
            local existingBody = existingBridge._monitorSectionBody
            local existingSection = nil

            if typeof(existingBody) == "Instance" then
                existingSection = existingBody.Parent
            end

            if existingBridge._monitorSectionUi == ui
                and existingSection ~= nil
                and existingSection.Parent ~= nil
                and existingSection.Parent == ui.content then

                return existingBridge, existingBody
            end
        end

        local bridge = NodeHubWS.Setup(opts)

        if type(ui) ~= "table" or type(ui.CreateSection) ~= "function" then
            warn("[NodeHubWS] ui.CreateSection tidak ditemukan")
            return bridge, nil
        end

        local body = select(1, ui:CreateSection(opts.title or "Monitor Account", opts.defaultOpen == true))

        -- Simpan section aktif untuk dedupe kalau builder terpanggil ulang.
        bridge._monitorSectionUi = ui
        bridge._monitorSectionBody = body

        if type(ui.CreateRowLabel) == "function" then
            local _, label = ui:CreateRowLabel(
                body,
                "Status: " .. tostring(bridge.status or compactTrackStatus(bridge) or "OFF"),
                opts.desc,
                nil,
                opts.statusLabelStyle or "info"
            )
            bridge._statusLabel = label
        end

        if type(ui.CreateRowInput) == "function" then
            local inputRow = select(1, ui:CreateRowInput(
                body,
                opts.wsIdLabel or "WS ID / Monitor ID",
                bridge.wsId or "",
                function(value)
                    bridge.wsId = trim(value)
                    bridge:SavePrefs()
                end,
                false
            ))

            -- Buat input WS ID lebih terlihat dan tidak terlalu sempit.
            if opts.wideWsIdInput ~= false and inputRow then
                pcall(function()
                    local label = inputRow:FindFirstChild("Label", true)
                    local box = inputRow:FindFirstChild("Input", true)
                    if label and label:IsA("TextLabel") then
                        label.Size = UDim2.new(0.42, 0, 1, 0)
                        label.TextColor3 = Color3.fromRGB(255, 211, 0)
                        label.Font = Enum.Font.GothamMedium
                    end
                    if box and box:IsA("TextBox") then
                        bridge._wsIdBox = box
                        box.Size = UDim2.new(0.56, 0, 1, -5)
                        box.Position = UDim2.new(0.43, 0, 0, 3)
                        box.TextXAlignment = Enum.TextXAlignment.Left
                        box.TextSize = tonumber(opts.wsIdTextSize) or 10
                        box.PlaceholderText = opts.wsIdPlaceholder or "WSTA-XXXXXXXXXXXX"
                        box.ClipsDescendants = true
                        if trim(bridge.wsId) ~= "" then
                            box.Text = tostring(bridge.wsId)
                        end
                    end
                end)
            end
        end

        if type(ui.CreateRowToggle) == "function" then
            local setTrackToggle, trackToggleApi
            local _row
            _row, setTrackToggle, trackToggleApi = ui:CreateRowToggle(
                body,
                opts.toggleLabel or opts.trackLabel or "Aktifkan Monitor Account",
                bridge.trackEnabled == true or bridge.active == true or opts.defaultActive == true,
                function(on)
                    if on == true and trim(bridge.wsId) == "" then
                        bridge:SetStatus("ws_id empty")
                        task.defer(function()
                            if type(trackToggleApi) == "table" and type(trackToggleApi.setOff) == "function" then
                                pcall(trackToggleApi.setOff, true)
                            elseif type(setTrackToggle) == "function" then
                                pcall(setTrackToggle, false, true)
                            end
                        end)
                        return
                    end
                    bridge:SetActive(on == true)
                end
            )
            bridge._trackToggleSetter = setTrackToggle
            bridge._trackToggleApi = trackToggleApi

            -- V35: Section bukan lagi satu-satunya pemicu auto resume.
            -- Tetap dipanggil di sini agar toggle UI tersinkron kalau section sudah dibuka.
            -- Toggle CreateRowToggle TIDAK memanggil onChanged saat init — jadi harus
            -- paksa EnsureTracked kalau state file sudah ON tapi socket belum hidup.
            if type(bridge.ScheduleAutoResume) == "function" then
                bridge:ScheduleAutoResume("section_ready")
            end
            if (bridge.trackEnabled == true or bridge.active == true) and trim(bridge.wsId) ~= "" then
                task.defer(function()
                    if type(bridge.EnsureTracked) == "function" then
                        bridge:EnsureTracked("section_toggle_init")
                    elseif bridge.connected ~= true then
                        bridge:SetActive(true)
                    elseif type(bridge.SetTrack) == "function" then
                        bridge:SetTrack(true)
                    end
                end)
            end
        end

        -- Tombol manual optional.
        -- Default V7: tidak membuat tombol Send Stats Now, karena stats otomatis saat aktif
        -- dan otomatis saat Node mengirim stats_request.
        if (opts.showManualButtons == true or opts.showSendConfigButton == true) and type(ui.CreateRowToggle) == "function" then
            ui:CreateRowToggle(
                body,
                opts.sendConfigLabel or "Send Config Now",
                false,
                function(on)
                    if on ~= true then return end
                    bridge:SendConfig("manual_button", true)
                end,
                nil,
                nil,
                true
            )
        end

        if opts.showSendStatsButton == true and type(ui.CreateRowToggle) == "function" then
            ui:CreateRowToggle(
                body,
                opts.sendStatsLabel or "Send Stats Now",
                false,
                function(on)
                    if on ~= true then return end
                    bridge:SendStats("manual_button")
                end,
                nil,
                nil,
                true
            )
        end

        return bridge, body
    end

    function NodeHubWS.Rows(ui, parent, opts)
        opts = type(opts) == "table" and opts or {}
        local bridge = NodeHubWS.Setup(opts)

        if type(ui) ~= "table" or parent == nil then
            warn("[NodeHubWS] ui atau parent kosong")
            return bridge
        end

        if type(ui.CreateRowLabel) == "function" then
            local _, label = ui:CreateRowLabel(parent, "Status: " .. tostring(bridge.status or compactTrackStatus(bridge) or "OFF"), nil, nil, "info")
            bridge._statusLabel = label
        end

        if type(ui.CreateRowInput) == "function" then
            ui:CreateRowInput(parent, opts.wsIdLabel or "WS ID", bridge.wsId or "", function(value)
                bridge.wsId = trim(value)
                bridge:SavePrefs()
            end, false)
        end

        if type(ui.CreateRowToggle) == "function" then
            local setTrackToggle, trackToggleApi
            local _row
            _row, setTrackToggle, trackToggleApi = ui:CreateRowToggle(parent, opts.toggleLabel or opts.trackLabel or "Active WebSocket / Crown", bridge.trackEnabled == true or bridge.active == true, function(on)
                if on == true and trim(bridge.wsId) == "" then
                    bridge:SetStatus("ws_id empty")
                    task.defer(function()
                        if type(trackToggleApi) == "table" and type(trackToggleApi.setOff) == "function" then
                            pcall(trackToggleApi.setOff, true)
                        elseif type(setTrackToggle) == "function" then
                            pcall(setTrackToggle, false, true)
                        end
                    end)
                    return
                end
                bridge:SetActive(on == true)
            end)
            bridge._trackToggleSetter = setTrackToggle
            bridge._trackToggleApi = trackToggleApi

            if (bridge.trackEnabled == true or bridge.active == true) and trim(bridge.wsId) ~= "" then
                if type(bridge.ScheduleAutoResume) == "function" then
                    bridge:ScheduleAutoResume("rows_ready")
                end
                task.defer(function()
                    if type(bridge.EnsureTracked) == "function" then
                        bridge:EnsureTracked("rows_toggle_init")
                    elseif bridge.active == true or bridge.trackEnabled == true then
                        bridge:SetActive(true)
                    end
                end)
            end
        end

        return bridge
    end

    function NodeHubWS.ResolveConfigSaveFile(path, namespace)
        return resolveConfigSaveFile(path, namespace)
    end

    function NodeHubWS.DefaultGAG2SaveFile()
        return defaultGAG2SaveFile()
    end

    function NodeHubWS.SendConfig(namespace, reason, payload, force)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:SendConfig(reason or "manual", force == true, payload)
    end

    function NodeHubWS.SendDefaultConfig(namespace, reason, payload, force)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:SendDefaultConfig(reason or "track_start", force == true, payload)
    end

    function NodeHubWS.ExtractConfig(data)
        return normalizeConfigEnvelope(data)
    end

    function NodeHubWS.ReadConfigFile(path)
        local data, err = readJsonFile(path)
        if type(data) == "table" then
            return normalizeConfigEnvelope(data)
        end
        return data, err
    end

    function NodeHubWS.WriteConfigFile(path, data)
        return writeJsonFile(path, normalizeConfigEnvelope(data))
    end

    function NodeHubWS.SendConfigFromFile(namespace, path, reason, force)
        local data = NodeHubWS.ReadConfigFile(path)
        if type(data) ~= "table" then return false, "config_file_not_found_or_invalid" end
        return NodeHubWS.SendConfig(namespace, reason or "file_config", data, force == true)
    end

    function NodeHubWS.SendDefaultConfigFromFile(namespace, path, reason, force)
        local data = NodeHubWS.ReadConfigFile(path)
        if type(data) ~= "table" then return false, "config_file_not_found_or_invalid" end
        return NodeHubWS.SendDefaultConfig(namespace, reason or "file_default", data, force == true)
    end

    function NodeHubWS.SendAllConfigFromFile(namespace, path, reason, force)
        local data = NodeHubWS.ReadConfigFile(path)
        if type(data) ~= "table" then return false, "config_file_not_found_or_invalid" end
        NodeHubWS.SendDefaultConfig(namespace, reason or "file_all", data, force == true)
        return NodeHubWS.SendConfig(namespace, reason or "file_all", data, force == true)
    end

    function NodeHubWS.ConfigFileChanged(namespace, path, reason)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:ConfigFileChanged(path, reason or "file_changed")
    end

    function NodeHubWS.ConfigChanged(namespace, reason, payload)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:ConfigChanged(reason or "changed", payload)
    end

    function NodeHubWS.SendStats(namespace, reason, payload)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:SendStats(reason or "manual", nil, payload)
    end

    function NodeHubWS.RefreshStats(namespace, reason)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        bridge._assetsCache = nil
        bridge._assetsCacheAt = 0
        return bridge:SendStats(reason or "manual_refresh", nil, nil)
    end

    function NodeHubWS.SendInitialSync(namespace, reason)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end

        reason = reason or "manual_initial_sync"

        -- Kirim urutan yang sama seperti saat Track Server ON:
        -- 1) default_config_sync
        -- 2) config_sync
        -- 3) stats pertama
        bridge:SendDefaultConfig(reason, true)
        bridge:SendConfig(reason, true)
        bridge:SendStats(reason)

        return true
    end

    function NodeHubWS.ApplyConfig(namespace, config, message)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:ApplyRemoteConfig(config, message or { type = "manual_apply" })
    end

    function NodeHubWS.OnApplyUI(namespace, name, fn)
        return nodeHubAddApplyUiHook(namespace or "default", name, fn)
    end

    NodeHubWS.RegisterApplyUI = NodeHubWS.OnApplyUI
    NodeHubWS.OnRemoteApplyUI = NodeHubWS.OnApplyUI

    function NodeHubWS.RunApplyUI(namespace, config, message)
        local bridge = NodeHubWS.Get(namespace or "default")
        return nodeHubRunApplyUiHooks(namespace or "default", config, message or { type = "manual_apply_ui" }, bridge)
    end

    function NodeHubWS.IsRemoteApplying(namespace)
        if G.__NODEHUB_WS_REMOTE_APPLYING ~= true and rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING") ~= true then
            return false
        end
        if namespace == nil then return true end
        namespace = nodeHubUiNamespace(namespace)
        return G["__NODEHUB_WS_REMOTE_APPLYING_" .. namespace] == true
            or rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING_" .. namespace) == true
    end

    function NodeHubWS.GetConfigPath(config, path)
        return nodeHubUiGetPath(normalizeConfigEnvelope(config), path)
    end

    function NodeHubWS.SetConfigPath(config, path, value)
        return nodeHubUiSetPath(config, path, value)
    end

    function NodeHubWS.ToValueArray(value)
        return nodeHubUiToArray(value)
    end

    function NodeHubWS.ToSelectedMap(value)
        return nodeHubUiToSelectedMap(value)
    end

    function NodeHubWS.MergeTable(target, source, replace)
        return nodeHubUiMerge(target, source, replace == true)
    end

    function NodeHubWS.DeepCopy(value)
        return nodeHubUiCopy(value)
    end

    function NodeHubWS.GetSaveFile(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return nil, "bridge_not_found" end
        return bridge.saveFile
    end

    function NodeHubWS.GetIdentity(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return nil, "bridge_not_found" end
        return bridge:GetIdentityPayload()
    end

    function NodeHubWS.Debug(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return nil, "bridge_not_found" end
        return {
            version = NodeHubWS.__version,
            status = bridge.status,
            status_detail = bridge.status_detail,
            persist_track_state = bridge.persistTrackState == true,
            track_state_file = bridge.settingsFile,
            auto_start_on_boot = bridge.autoStartOnBoot ~= false,
            auto_resume_scheduled = bridge._autoResumeScheduled == true,
            auto_resume_reason = bridge._autoResumeReason,
            auto_resume_last_at = bridge._autoResumeLastAt,
            helper_auto_boot = bridge._helperAutoBoot == true,
            helper_auto_boot_reason = bridge._helperAutoBootReason,
            auto_boot_last_reason = __gag2AutoBootLastReason,
            connected = bridge.connected == true,
            active = bridge.active == true,
            track_enabled = bridge.trackEnabled == true,
            ws_id = bridge.wsId,
            sc_id = bridge.scId,
            sc_id_updated_at = bridge._scIdUpdatedAt,
            listener_bound = bridge._socketMessageBound == true,
            listener_via = bridge._socketMessageBoundVia,
            listener_attempts = bridge._socketMessageBindAttempts,
            listener_retry_count = bridge._listenerRetryCount,
            close_bound = bridge._socketCloseBound == true,
            close_via = bridge._socketCloseBoundVia,
            last_raw_message_at = bridge._lastRawMessageAt,
            last_raw_message_preview = bridge._lastRawMessagePreview,
            last_config_update_at = bridge._lastConfigUpdateAt,
            last_config_request_id = bridge._lastConfigRequestId,
            last_config_apply_ok = bridge._lastConfigApplyOk,
            last_config_apply_error = bridge._lastConfigApplyError,
            last_apply_ui = bridge._lastApplyUi,
            last_command_at = bridge._lastCommandAt,
            last_command_type = bridge._lastCommandType,
            last_command_ok = bridge._lastCommandOk,
            last_command_error = bridge._lastCommandError,
            identity = bridge:GetIdentityPayload(),
        }
    end

    function NodeHubWS.OnConfig(namespace, fn)
        local bridge = NodeHubWS.Setup({ namespace = namespace })
        bridge.applyConfig = fn
        return bridge
    end

    function NodeHubWS.OnStats(namespace, fn)
        local bridge = NodeHubWS.Setup({ namespace = namespace })
        bridge.getStats = fn
        return bridge
    end

    function NodeHubWS.OnCommand(namespace, name, fn)
        local bridge = NodeHubWS.Setup({ namespace = namespace })
        if type(name) == "function" then
            bridge.onCommand = name
            return bridge
        end
        bridge.commandHandlers = type(bridge.commandHandlers) == "table" and bridge.commandHandlers or {}
        if type(name) == "string" and type(fn) == "function" then
            bridge.commandHandlers[name] = fn
        end
        return bridge
    end

    function NodeHubWS.OnAutoGift(namespace, fn)
        local bridge = NodeHubWS.Setup({ namespace = namespace })
        bridge.autoGiftHandler = fn
        bridge.commandHandlers = type(bridge.commandHandlers) == "table" and bridge.commandHandlers or {}
        if type(fn) == "function" then
            bridge.commandHandlers.auto_gift = fn
            bridge.commandHandlers.auto_gift_command = fn
        end
        return bridge
    end

    function NodeHubWS.Active(namespace, on)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:SetActive(on == true)
    end

    function NodeHubWS.Connect(namespace, wsId)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:Connect(wsId)
    end

    function NodeHubWS.Disconnect(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return false, "bridge_not_found" end
        return bridge:Disconnect()
    end

    function NodeHubWS.CollectAssets(namespace)
        local bridge = NodeHubWS.Get(namespace) or NodeHubWS.Setup({ namespace = namespace or "default" })
        return collectGameAssets(bridge)
    end

    function NodeHubWS.FormatShortNumber(value)
        return formatShortNumber(value)
    end

    function NodeHubWS.TestStats(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return nil, "bridge_not_found" end
        return bridge:GetStatsSnapshot()
    end

    function NodeHubWS.TestConfig(namespace)
        local bridge = NodeHubWS.Get(namespace)
        if not bridge then return nil, "bridge_not_found" end
        return bridge:GetConfigSnapshot()
    end


    ----------------------------------------------------------------
    -- GAG2 Auto Gift action bridge
    -- Dipakai hanya untuk namespace GAG2 dan hanya jika script production
    -- belum memasang handler Auto Gift sendiri lewat opts.onAutoGift / NodeHubWS.OnAutoGift.
    ----------------------------------------------------------------
    local function giftNormText(s)
        s = tostring(s or ""):lower()
        s = s:gsub("%s*[xX×]%s*[%d%,%.]+%s*$", "")
        s = s:gsub("%s+seed$", "")
        s = s:gsub("[_%-%s]+", " ")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function getGAG2AutoGiftModule()
        local ag = G.AutoGiftModule or G.AutoGift or rawget(_G, "AutoGiftModule") or rawget(_G, "AutoGift")
        if type(ag) == "table" then
            return ag
        end

        local ensure = G.__GAG2_ENSURE_LOADED_MODULE or rawget(_G, "__GAG2_ENSURE_LOADED_MODULE")
        if type(ensure) == "function" then
            local ok, mod = pcall(ensure, "AutoGift")
            if ok and type(mod) == "table" then
                G.AutoGiftModule = mod
                G.AutoGift = mod
                _G.AutoGiftModule = mod
                _G.AutoGift = mod
                return mod
            end
        end

        return nil
    end

    local GIFT_CATEGORY_ALIAS = {
        seed = "Seeds", seeds = "Seeds",
        fruit = "HarvestedFruits", fruits = "HarvestedFruits", harvestedfruit = "HarvestedFruits", harvestedfruits = "HarvestedFruits", harvest = "HarvestedFruits",
        pet = "Pets", pets = "Pets",
        egg = "Eggs", eggs = "Eggs",
        seedpack = "SeedPacks", seedpacks = "SeedPacks", pack = "SeedPacks",
        gear = "Trowels", gears = "Trowels", tool = "Trowels", tools = "Trowels", trowel = "Trowels", trowels = "Trowels",
        sprinkler = "Sprinklers", sprinklers = "Sprinklers",
        wateringcan = "WateringCans", wateringcans = "WateringCans",
        prop = "Props", props = "Props",
        crate = "Crates", crates = "Crates",
        pot = "EmptyPots", pots = "EmptyPots", emptypot = "EmptyPots", emptypots = "EmptyPots",
    }

    local function getGAG2GiftCategoryDefs(ag)
        local defs = {}
        if type(ag) == "table" and type(ag.GetCategoryDefs) == "function" then
            local ok, res = pcall(function()
                return ag:GetCategoryDefs()
            end)
            if not ok or type(res) ~= "table" then
                ok, res = pcall(ag.GetCategoryDefs, ag)
            end
            if ok and type(res) == "table" then
                for _, def in ipairs(res) do
                    if type(def) == "table" and type(def.key) == "string" and def.key ~= "" then
                        defs[#defs + 1] = {
                            key = def.key,
                            label = tostring(def.label or def.name or def.key),
                        }
                    end
                end
            end
        end

        if #defs <= 0 then
            defs = {
                { key = "Seeds", label = "Seeds" },
                { key = "HarvestedFruits", label = "Harvested Fruits" },
                { key = "Pets", label = "Pets" },
                { key = "Eggs", label = "Eggs" },
                { key = "SeedPacks", label = "Seed Packs" },
                { key = "Trowels", label = "Trowels" },
                { key = "Sprinklers", label = "Sprinklers" },
                { key = "WateringCans", label = "Watering Cans" },
                { key = "Props", label = "Props" },
                { key = "EmptyPots", label = "Empty Pots" },
                { key = "Crates", label = "Crates" },
            }
        end
        return defs
    end

    local function compactGiftCategory(s)
        return giftNormText(s):gsub("[^%w]", "")
    end

    local function resolveGAG2GiftCategory(ag, rawCategory, rawGroup)
        local want = compactGiftCategory(firstNonEmpty(rawCategory, rawGroup, "Seeds"))
        local alias = GIFT_CATEGORY_ALIAS[want]
        local defs = getGAG2GiftCategoryDefs(ag)

        if alias then
            for _, def in ipairs(defs) do
                if def.key == alias then return def.key end
            end
            return alias
        end

        for _, def in ipairs(defs) do
            local k = compactGiftCategory(def.key)
            local l = compactGiftCategory(def.label)
            if want ~= "" and (want == k or want == l) then
                return def.key
            end
        end

        return tostring(rawCategory or "Seeds")
    end

    local function buildGAG2GiftItems(ag, catKey)
        if type(ag) ~= "table" or type(ag.BuildInventoryItems) ~= "function" then
            return {}
        end
        local ok, items = pcall(function()
            return ag:BuildInventoryItems(catKey)
        end)
        if ok and type(items) == "table" then return items end
        ok, items = pcall(ag.BuildInventoryItems, ag, catKey)
        if ok and type(items) == "table" then return items end
        return {}
    end

    local function giftItemKey(row)
        if type(row) ~= "table" then return tostring(row or "") end
        return tostring(row.key or row.id or row.name or row.label or row.display or "")
    end

    local function giftItemName(row)
        if type(row) ~= "table" then return tostring(row or "") end
        return tostring(row.name or row.label or row.display or row.key or row.id or "")
    end

    local function pickGAG2GiftPayloadItem(payload)
        if type(payload.item) == "table" then return payload.item end
        if type(payload.items) == "table" then
            for _, it in ipairs(payload.items) do
                if type(it) == "table" then return it end
            end
        end
        return nil
    end

    local function resolveGAG2GiftItem(ag, catKey, payloadItem)
        payloadItem = type(payloadItem) == "table" and payloadItem or {}
        local wantedKey = tostring(payloadItem.key or payloadItem.id or "")
        local wantedName = tostring(payloadItem.name or payloadItem.label or payloadItem.display or wantedKey or "")
        local wantedKeyNorm = giftNormText(wantedKey)
        local wantedNameNorm = giftNormText(wantedName)
        local items = buildGAG2GiftItems(ag, catKey)

        if wantedKeyNorm ~= "" then
            for _, row in ipairs(items) do
                if giftNormText(giftItemKey(row)) == wantedKeyNorm then
                    return giftItemKey(row), giftItemName(row), row
                end
            end
        end

        if wantedNameNorm ~= "" then
            for _, row in ipairs(items) do
                if giftNormText(giftItemName(row)) == wantedNameNorm then
                    return giftItemKey(row), giftItemName(row), row
                end
            end
        end

        if wantedNameNorm ~= "" then
            for _, row in ipairs(items) do
                local k = giftNormText(giftItemKey(row))
                local n = giftNormText(giftItemName(row))
                if k == wantedNameNorm or n == wantedNameNorm
                    or (k ~= "" and wantedNameNorm:find(k, 1, true))
                    or (n ~= "" and wantedNameNorm:find(n, 1, true))
                    or (wantedNameNorm ~= "" and k:find(wantedNameNorm, 1, true))
                    or (wantedNameNorm ~= "" and n:find(wantedNameNorm, 1, true)) then
                    return giftItemKey(row), giftItemName(row), row
                end
            end
        end

        return nil, nil, nil
    end

    local function getGAG2GiftRecipient(payload)
        local r = firstNonEmpty(
            payload.recipient,
            payload.recipient_username,
            payload.recipientUsername,
            payload.username,
            payload.target
        )
        r = trim(r or ""):gsub("^@", "")
        return r
    end

    local function getGAG2GiftSendMode(payload)
        local mode = tostring(firstNonEmpty(payload.mode, payload.send_mode, payload.sendMode, "total_item") or "total_item"):lower()
        mode = mode:gsub("%s+", "_")
        if mode == "total_value" or mode == "price" or mode == "price_rule" or mode == "value" or mode == "total_price" then
            return "price"
        end
        return "total"
    end

    local function getGAG2GiftLimit(payload)
        local v = firstNonEmpty(payload.limit_value, payload.limitValue, payload.limit, payload.value, payload.amount, payload.count, 1)
        v = tonumber(v) or 1
        if v < 1 then v = 1 end
        return math.floor(v)
    end

    local function getGAG2GiftStatus(ag)
        if type(ag) == "table" and type(ag.GetProfileStatus) == "function" then
            local ok, s = pcall(ag.GetProfileStatus, ag, "once")
            if ok and tostring(s or "") ~= "" then return tostring(s) end
        end
        return tostring(G.AUTO_GIFT_ONCE_STATUS or rawget(_G, "AUTO_GIFT_ONCE_STATUS") or "")
    end

    local function executeGAG2AutoGiftPayload(payload)
        payload = type(payload) == "table" and payload or {}

        -- V32:
        -- Simpan payload dari awal supaya kegagalan lookup/validasi tetap bisa diaudit dari console.
        G.__GAG2_LAST_AUTO_GIFT_COMMAND = payload
        _G.__GAG2_LAST_AUTO_GIFT_COMMAND = payload

        local function saveGiftResult(ok, stage, message, extra)
            local result = type(extra) == "table" and extra or {}
            result.ok = ok == true
            result.stage = tostring(stage or "unknown")
            result.error = ok and nil or tostring(message or "failed")
            result.message = ok and tostring(message or "ok") or nil
            result.at = now()
            G.__GAG2_LAST_AUTO_GIFT_RESULT = result
            _G.__GAG2_LAST_AUTO_GIFT_RESULT = result
            return result
        end

        local function fail(stage, message, extra)
            saveGiftResult(false, stage, message, extra)
            return false, tostring(message or stage or "failed")
        end

        local recipient = getGAG2GiftRecipient(payload)
        if recipient == "" then
            return fail("validate_recipient", "recipient_empty")
        end

        local payloadItem = pickGAG2GiftPayloadItem(payload)
        if type(payloadItem) ~= "table" then
            return fail("validate_item", "item_empty", { recipient = recipient })
        end

        local ag = getGAG2AutoGiftModule()
        if type(ag) ~= "table" then
            return fail("load_module", "AutoGift_module_not_loaded", { recipient = recipient })
        end

        if type(ag.ReloadCatalog) == "function" then
            pcall(ag.ReloadCatalog, ag, true)
        end

        local catKey = resolveGAG2GiftCategory(ag, payloadItem.category or payload.category, payloadItem.group or payload.group)
        local itemKey, itemName = resolveGAG2GiftItem(ag, catKey, payloadItem)
        if not itemKey or itemKey == "" then
            return fail("resolve_item", "item_not_found_in_" .. tostring(catKey) .. ": " .. tostring(payloadItem.name or payloadItem.key or "?"), {
                recipient = recipient,
                category = catKey,
                requested_item = tostring(payloadItem.name or payloadItem.key or ""),
            })
        end

        local defs = getGAG2GiftCategoryDefs(ag)
        local categories = {}
        local selected = {}
        local sendTotals = {}
        for _, def in ipairs(defs) do
            categories[def.key] = false
            selected[def.key] = {}
            sendTotals[def.key] = 1
        end
        categories[catKey] = true
        selected[catKey] = { [itemKey] = true }

        local sendMode = getGAG2GiftSendMode(payload)
        local limitValue = getGAG2GiftLimit(payload)
        if sendMode == "price" then
            sendTotals[catKey] = tonumber(payload.max_items) or 999999
        else
            sendTotals[catKey] = limitValue
        end

        local recipientUserId = math.floor(tonumber(payload.recipient_user_id or payload.recipientUserId) or 0)
        local recipientDisplay = tostring(payload.recipient_display or payload.recipientDisplay or recipient)

        -- V32 fix:
        -- Jangan ApplyConfig dengan recipient_user_id=0 sebelum LookupRecipient.
        -- Module AutoGift punya cooldown lookup; kalau config di-reset dulu, lookup bisa langsung gagal
        -- walaupun username sebenarnya valid. Lookup dilakukan dulu, lalu config final baru di-apply.
        if type(ag.LookupRecipient) == "function" and recipientUserId <= 0 then
            local function doLookup()
                return pcall(ag.LookupRecipient, ag, recipient)
            end

            local okLookup, lookupOk, lookupRes = doLookup()
            if not okLookup then
                return fail("lookup", "LookupRecipient_error: " .. tostring(lookupOk), {
                    recipient = recipient,
                    category = catKey,
                    item_key = itemKey,
                    item_name = itemName,
                })
            end

            local lookupId = tonumber(lookupRes) or tonumber(lookupOk) or 0
            local lookupSuccess = (lookupOk == true) or lookupId > 0

            -- Kalau kena cooldown internal module, tunggu sebentar lalu coba sekali lagi.
            if lookupSuccess ~= true then
                task.wait(1.08)
                okLookup, lookupOk, lookupRes = doLookup()
                if not okLookup then
                    return fail("lookup_retry", "LookupRecipient_error: " .. tostring(lookupOk), {
                        recipient = recipient,
                        category = catKey,
                        item_key = itemKey,
                        item_name = itemName,
                    })
                end
                lookupId = tonumber(lookupRes) or tonumber(lookupOk) or 0
                lookupSuccess = (lookupOk == true) or lookupId > 0
            end

            if lookupSuccess ~= true then
                return fail("lookup", "LookupRecipient_failed: " .. tostring(lookupRes or lookupOk or getGAG2GiftStatus(ag)), {
                    recipient = recipient,
                    category = catKey,
                    item_key = itemKey,
                    item_name = itemName,
                    lookup_ok = tostring(lookupOk),
                    lookup_result = tostring(lookupRes),
                    status = getGAG2GiftStatus(ag),
                })
            end

            if lookupId > 0 then
                recipientUserId = math.floor(lookupId)
            end

            if type(ag.GetConfig) == "function" then
                local okCfg, currentCfg = pcall(ag.GetConfig, ag)
                if okCfg and type(currentCfg) == "table" then
                    recipientUserId = math.floor(tonumber(currentCfg.recipient_user_id or recipientUserId) or recipientUserId)
                    recipientDisplay = tostring(currentCfg.recipient_display or recipientDisplay)
                    recipient = tostring(currentCfg.recipient_username or recipient)
                end
            end
        end

        local cfg = {
            enabled = true,
            auto_send = false,
            recipient_username = recipient,
            recipient_user_id = recipientUserId,
            recipient_display = recipientDisplay,
            categories = categories,
            selected = selected,
            send_totals = sendTotals,
            send_list_mode = "send_total",
            category_mode = "single",
            once_send_mode = sendMode,
            send_total = limitValue,
            skip_equipped = payload.skip_equipped ~= false,
            max_per_batch = math.floor(tonumber(payload.max_per_batch or payload.maxPerBatch) or 999999),
            delay_sec = tonumber(payload.delay_sec or payload.delaySec or 10) or 10,
            after_send_mode = tostring(payload.after_send_mode or payload.afterSendMode or "keep"),
            note = tostring(payload.note or "NodeMonitor"),
            harvest_price_threshold_pct = tonumber(payload.harvest_price_threshold_pct or 10) or 10,
            harvest_price_calc_mode = tostring(payload.harvest_price_calc_mode or "base"),
            auto_unfav = payload.auto_unfav == true or payload.autoUnfav == true,
        }

        if type(ag.StopSendJob) == "function" then
            pcall(ag.StopSendJob, ag)
        end

        if type(ag.ApplyConfig) ~= "function" then
            return fail("apply_config", "ApplyConfig_missing", {
                recipient = recipient,
                recipient_user_id = recipientUserId,
                category = catKey,
                item_key = itemKey,
                item_name = itemName,
            })
        end
        local okApply, errApply = pcall(ag.ApplyConfig, ag, cfg)
        if not okApply then
            return fail("apply_config", "ApplyConfig_error: " .. tostring(errApply), {
                recipient = recipient,
                recipient_user_id = recipientUserId,
                category = catKey,
                item_key = itemKey,
                item_name = itemName,
            })
        end

        if type(ag.CheckSendTotalAvailability) == "function" then
            local okAvail, avail, reason = pcall(ag.CheckSendTotalAvailability, ag, limitValue, sendMode == "price")
            if okAvail and avail == false then
                return fail("availability", tostring(reason or getGAG2GiftStatus(ag) or "not_available"), {
                    recipient = recipient,
                    recipient_user_id = recipientUserId,
                    category = catKey,
                    item_key = itemKey,
                    item_name = itemName,
                    mode = sendMode,
                    limit = limitValue,
                })
            end
        end

        if type(ag.StartSendJob) ~= "function" then
            return fail("start_job", "StartSendJob_missing", {
                recipient = recipient,
                recipient_user_id = recipientUserId,
                category = catKey,
                item_key = itemKey,
                item_name = itemName,
            })
        end
        if type(ag.IsSendJobRunning) == "function" then
            local okRunning, running = pcall(ag.IsSendJobRunning, ag)
            if okRunning and running == true then
                return fail("start_job", "send_job_already_running", {
                    recipient = recipient,
                    recipient_user_id = recipientUserId,
                    category = catKey,
                    item_key = itemKey,
                    item_name = itemName,
                })
            end
        end

        local okStart, started, reason = pcall(ag.StartSendJob, ag)
        if not okStart then
            return fail("start_job", "StartSendJob_error: " .. tostring(started), {
                recipient = recipient,
                recipient_user_id = recipientUserId,
                category = catKey,
                item_key = itemKey,
                item_name = itemName,
            })
        end
        if started ~= true then
            return fail("start_job", tostring(reason or getGAG2GiftStatus(ag) or "StartSendJob_failed"), {
                recipient = recipient,
                recipient_user_id = recipientUserId,
                category = catKey,
                item_key = itemKey,
                item_name = itemName,
                status = getGAG2GiftStatus(ag),
            })
        end

        saveGiftResult(true, "started", "started", {
            recipient = recipient,
            recipient_user_id = recipientUserId,
            recipient_display = recipientDisplay,
            category = catKey,
            item_key = itemKey,
            item_name = itemName,
            mode = sendMode,
            limit = limitValue,
        })

        return true, "started"
    end

    local function installGAG2AutoGiftActionHandler(bridge)
        if type(bridge) ~= "table" then return end

        G.__GAG2_AUTO_GIFT_EXECUTE = executeGAG2AutoGiftPayload
        _G.__GAG2_AUTO_GIFT_EXECUTE = executeGAG2AutoGiftPayload

        G.__GAG2_DEBUG_GIFT_ITEMS = function(category)
            local ag = getGAG2AutoGiftModule()
            if type(ag) ~= "table" then
                warn("AutoGift module not loaded")
                return nil
            end
            if type(ag.ReloadCatalog) == "function" then
                pcall(ag.ReloadCatalog, ag, true)
            end
            local catKey = resolveGAG2GiftCategory(ag, category or "Seeds")
            local items = buildGAG2GiftItems(ag, catKey)
            print("==== GIFT ITEMS:", catKey, "====")
            for i, row in ipairs(items) do
                if i > 80 then print("...more") break end
                print(i, "key=", giftItemKey(row), "| name=", giftItemName(row))
            end
            return items
        end
        _G.__GAG2_DEBUG_GIFT_ITEMS = G.__GAG2_DEBUG_GIFT_ITEMS

        if type(bridge.autoGiftHandler) == "function" then
            return
        end

        local handler = function(payload)
            local ok, res = executeGAG2AutoGiftPayload(payload)
            if ok then return true end
            return false, tostring(res)
        end
        bridge.autoGiftHandler = handler
        bridge.commandHandlers = type(bridge.commandHandlers) == "table" and bridge.commandHandlers or {}
        bridge.commandHandlers.auto_gift = handler
        bridge.commandHandlers.auto_gift_command = handler
    end

    function NodeHubWS.GAG2(ui, opts)
        opts = type(opts) == "table" and opts or {}
        opts.namespace = opts.namespace or "gag2"
        opts.scriptName = opts.scriptName or "Grow A Garden 2"
        opts.gameName = opts.gameName or "Grow A Garden 2"
        opts.title = opts.title or "Monitor Account"
        opts.defaultOpen = opts.defaultOpen == true
        opts.defaultActive = false
        opts.restoreActive = false
        -- V35: simpan file kecil khusus Track Server untuk auto execute.
        -- Isinya hanya ws_id + status on/off. URL/auth/config/stats tidak disimpan.
        opts.persistTrackState = opts.persistTrackState ~= false
        opts.persistSettings = opts.persistSettings == true
        opts.wsIdLabel = opts.wsIdLabel or "WS ID / Monitor ID"
        opts.toggleLabel = opts.toggleLabel or "Aktifkan Monitor Account"
        opts.showManualButtons = opts.showManualButtons == true
        opts.statsInterval = tonumber(opts.statsInterval) or 60
        opts.assetsInterval = tonumber(opts.assetsInterval) or opts.statsInterval
        opts.collectAssets = opts.collectAssets ~= false
        opts.assetMode = opts.assetMode or "gag2"
        opts.saveFile = resolveConfigSaveFile(opts.saveFile, "gag2")
        opts.defaultSaveFile = resolveConfigSaveFile(opts.defaultSaveFile or opts.saveFile, "gag2")
        opts.sendDefaultConfigOnTrack = opts.sendDefaultConfigOnTrack ~= false
        opts.sendDefaultConfigOnChange = opts.sendDefaultConfigOnChange ~= false

        local saveFile = opts.saveFile

        if type(opts.getConfig) ~= "function" then
            opts.getConfig = function()
                if type(saveFile) == "string" and saveFile ~= "" then
                    local data = readJsonFile(saveFile)
                    if type(data) == "table" then
                        return normalizeConfigEnvelope(data)
                    end
                end

                local main = G.MAIN or rawget(_G, "MAIN")
                if type(main) == "table" then
                    return {
                        running = false,
                        main = main,
                    }
                end

                return {
                    running = false,
                    main = {},
                }
            end
        end

        local function applyGAG2RemoteConfigToRuntime(config)
            if type(config) ~= "table" then
                return false, "config_not_table"
            end

            config = normalizeConfigEnvelope(config)

            -- 1) Simpan dulu ke file save.
            -- State.load() GAG2 membaca dari file ini, jadi local MAIN ikut berubah.
            if type(saveFile) == "string" and saveFile ~= "" then
                local okWrite, errWrite = writeJsonFile(saveFile, config)
                if okWrite ~= true then
                    return false, tostring(errWrite or "write_config_failed")
                end
            end

            local State = G.__GAG2_STATE or rawget(_G, "__GAG2_STATE")
            local loadedByState = false

            -- 2) Ini bagian paling penting.
            -- Jangan cuma set G.MAIN, karena UI GAG2 membaca local MAIN lewat State.getMain().
            -- State.load() akan memanggil loadSelectionsFromFile() dan sync module runtime.
            if type(State) == "table" and type(State.load) == "function" then
                local okLoad, errLoad = pcall(function()
                    return State.load()
                end)

                if okLoad == true then
                    loadedByState = true
                else
                    warn("[NodeHubWS] GAG2 State.load gagal:", tostring(errLoad))
                end
            end

            -- 3) Tambahan sync aman kalau fungsi tersedia.
            if type(State) == "table" then
                if type(State.syncAllMisc) == "function" then
                    pcall(function() State.syncAllMisc() end)
                end
                if type(State.syncAllAuto) == "function" then
                    pcall(function() State.syncAllAuto() end)
                end
                if type(State.getMain) == "function" then
                    local okMain, mainNow = pcall(function()
                        return State.getMain()
                    end)
                    if okMain and type(mainNow) == "table" then
                        G.MAIN = mainNow
                        _G.MAIN = mainNow
                    end
                end
            end

            -- 4) Fallback untuk script yang belum punya State.load().
            if loadedByState ~= true then
                local main = config.main or config
                if type(main) == "table" then
                    G.MAIN = main
                    _G.MAIN = main
                end
            end

            -- 5) Jalankan runtime sync yang sudah diregister module GAG2.
            -- Ini generic: module baru cukup expose __GAG2_SYNC_* tanpa hardcode path config di WS helper.
            local seenSync = {}

            local function runRegisteredSync(env)
                if type(env) ~= "table" then return end

                for key, fn in pairs(env) do
                    if type(key) == "string"
                        and string.sub(key, 1, 12) == "__GAG2_SYNC_"
                        and type(fn) == "function"
                        and seenSync[fn] ~= true then

                        seenSync[fn] = true
                        pcall(fn)
                    end
                end
            end

            runRegisteredSync(G)
            if _G ~= G then
                runRegisteredSync(_G)
            end

            -- 6) Paksa apply module misc yang memang memakai apply function.
            local applyFns = {
                "applyFruitBackpackEspModule",
                "applyFruitGardenEspModule",
                "applyPetFinderModule",
                "applyReduceFpsModule",
                "applyReduceLagModule",
                "applyHidePromptModule",
                "applyHideHarvestPromptModule",
                "applyHideLoadingModule",
                "applyCharacterModule",
                "applyAutoVulnModule",
            }

            for _, fnName in ipairs(applyFns) do
                local fn = G[fnName] or rawget(_G, fnName)
                if type(fn) == "function" then
                    pcall(fn)
                end
            end

            return true
        end

        G.__GAG2_NODEHUB_APPLY_REMOTE_CONFIG = applyGAG2RemoteConfigToRuntime
        _G.__GAG2_NODEHUB_APPLY_REMOTE_CONFIG = applyGAG2RemoteConfigToRuntime

        if type(opts.applyConfig) ~= "function" then
            opts.applyConfig = function(config)
                return applyGAG2RemoteConfigToRuntime(config)
            end
        end

        if type(opts.afterApply) ~= "function" then
            opts.afterApply = function(config)
                local function refreshUi()
                    if type(G.__GAG2_APPLY_UI_DEFAULTS) == "function" then
                        pcall(G.__GAG2_APPLY_UI_DEFAULTS)
                    end
                end

                -- Jangan rebuild subtab aktif: itu menyebabkan UI berkedip dan local-store lama
                -- dapat menimpa state remote. Refresh API yang sudah mounted saja.
                task.defer(refreshUi)
                task.delay(0.15, refreshUi)
            end
        end

        if type(opts.getStats) ~= "function" then
            opts.getStats = function(base)
                base.counters = type(base.counters) == "table" and base.counters or {}
                base.counters.script_alive = true
                base.counters.now = os.time()
                return base
            end
        end

        local bridge, body
        if type(ui) == "table" and type(ui.CreateSection) == "function" then
            bridge, body = NodeHubWS.Section(ui, opts)
        else
            -- V35: headless setup untuk auto execute.
            -- Bisa dipanggil lebih awal sebelum user membuka tab/section Track Server.
            bridge = NodeHubWS.Setup(opts)
            body = nil
        end

        if opts.installAutoGiftAction ~= false then
            installGAG2AutoGiftActionHandler(bridge)
        end

        if type(bridge) == "table" and type(bridge.ScheduleAutoResume) == "function" then
            bridge:ScheduleAutoResume(type(ui) == "table" and "gag2_ui" or "gag2_headless")
        end

        G.__GAG2_WS_CONFIG_CHANGED = function(payload, reason)
            if type(payload) == "table" then
                return NodeHubWS.ConfigChanged("gag2", reason or "save_config", payload)
            end

            if type(saveFile) == "string" and saveFile ~= "" then
                return NodeHubWS.ConfigFileChanged("gag2", saveFile, reason or "save_config")
            end

            return NodeHubWS.ConfigChanged("gag2", reason or "save_config", payload)
        end
        _G.__GAG2_WS_CONFIG_CHANGED = G.__GAG2_WS_CONFIG_CHANGED

        return bridge, body
    end

    local function getGAG2AutoBootDefaults()
        local defaults = G.__NODEHUB_WS_DEFAULTS
            or rawget(_G, "__NODEHUB_WS_DEFAULTS")
            or G.NODEHUB_WS_DEFAULTS
            or rawget(_G, "NODEHUB_WS_DEFAULTS")
            or {}

        if type(defaults) ~= "table" then defaults = {} end

        local wsBaseUrl = firstNonEmpty(
            defaults.wsBaseUrl,
            defaults.baseUrl,
            G.__NODEHUB_WS_BASE_URL,
            rawget(_G, "__NODEHUB_WS_BASE_URL"),
            G.NODEHUB_WS_BASE_URL,
            rawget(_G, "NODEHUB_WS_BASE_URL"),
            G.WS_BASE_URL,
            rawget(_G, "WS_BASE_URL"),
            -- WS MODE FALLBACK: aktifkan SATU baris di bawah (LOCAL / PRODUCTION)
            -- "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}" -- << LOCAL
            "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}" -- << PRODUCTION (aktif)
        )

        local authPassword = firstNonEmpty(
            defaults.authPassword,
            defaults.deviceAuthPassword,
            defaults.wsPassword,
            G.__NODEHUB_WS_AUTH_PASSWORD,
            rawget(_G, "__NODEHUB_WS_AUTH_PASSWORD"),
            G.NODEHUB_WS_AUTH_PASSWORD,
            rawget(_G, "NODEHUB_WS_AUTH_PASSWORD"),
            G.DEVICE_AUTH_PASSWORD,
            rawget(_G, "DEVICE_AUTH_PASSWORD"),
            G.WS_AUTH_PASSWORD,
            rawget(_G, "WS_AUTH_PASSWORD"),
            "sanken2"
        )

        local defaultScId = normalizeScId(firstNonEmpty(
            defaults.sc_id,
            defaults.scId,
            defaults.script_id,
            defaults.scriptId,
            defaults.id_code_list,
            defaults.idCodeList,
            defaults.code_list_id,
            defaults.codeListId,
            G.__NODEHUB_WS_SC_ID,
            rawget(_G, "__NODEHUB_WS_SC_ID"),
            G.NODEHUB_WS_SC_ID,
            rawget(_G, "NODEHUB_WS_SC_ID"),
            G.SC_ID,
            rawget(_G, "SC_ID"),
            G.ID_CODE_LIST,
            rawget(_G, "ID_CODE_LIST")
        ))

        local settingsFile = firstNonEmpty(
            defaults.trackStateFile,
            defaults.settingsFile,
            G.__NODEHUB_WS_TRACK_STATE_FILE,
            rawget(_G, "__NODEHUB_WS_TRACK_STATE_FILE"),
            G.NODEHUB_WS_TRACK_STATE_FILE,
            rawget(_G, "NODEHUB_WS_TRACK_STATE_FILE"),
            "nodehub_ws_static/gag2_" .. tostring(LP and LP.UserId or "unknown") .. ".json"
        )

        return {
            wsBaseUrl = tostring(wsBaseUrl or ""),
            authPassword = tostring(authPassword or ""),
            settingsFile = tostring(settingsFile or ""),
            namespace = tostring(defaults.namespace or "gag2"),
            scriptName = tostring(defaults.scriptName or "Grow A Garden 2"),
            gameName = tostring(defaults.gameName or "Grow A Garden 2"),
            scId = defaultScId,
        }
    end

    local function readGAG2SavedTrackState(settingsFile)
        local data = readJsonFile(settingsFile)
        if type(data) ~= "table" then
            return nil, false, "state_not_found"
        end

        local savedWsId = safeShort(firstNonEmpty(data.ws_id, data.wsId, data.monitor_id, data.monitorId), 80)
        local shouldOn = trackStatusFromPrefs(data)

        if trim(savedWsId) == "" then
            return data, false, "ws_id_empty"
        end

        if shouldOn ~= true then
            return data, false, "status_off"
        end

        return data, true, savedWsId
    end

    local __gag2AutoBootStarted = false
    local __gag2AutoBootLastReason = nil

    local function runGAG2DelayedAutoBoot(reason)
        local defaults = getGAG2AutoBootDefaults()
        local namespace = defaults.namespace or "gag2"
        local stealDefaults = G.__NODEHUB_WS_DEFAULTS
        if (type(stealDefaults) == "table" and tostring(stealDefaults.namespace or "") == "steal_egg")
            or type(NodeHubWS.Get("steal_egg")) == "table" then
            return false, "skip_steal_egg_client"
        end

        local existing = NodeHubWS.Get(namespace)
        if type(existing) == "table" then
            if type(existing.ScheduleAutoResume) == "function" then
                existing:ScheduleAutoResume(reason or "helper_delayed_boot_existing")
            end
            return true, existing.connected == true and "already_connected" or "existing_bridge"
        end

        -- NM_MONITOR: selalu resolve dari web. Jangan pakai Monitor ID lama dari file lokal.
        if NodeHubWS.IsNMMonitorEnabled() == true then
            local okBind, bindRes = NodeHubWS.TryNMMonitorBind({
                reason = tostring(reason or "helper_nm_fallback"),
                force = true,
                wsBaseUrl = defaults.wsBaseUrl,
                authPassword = defaults.authPassword,
                sc_id = defaults.scId,
                namespace = namespace,
                settingsFile = defaults.settingsFile,
                saveFile = resolveConfigSaveFile(nil, namespace),
            })
            if okBind == true then
                return true, "nm_monitor_bound"
            end
            return false, tostring(bindRes or "nm_monitor_bind_failed")
        end

        local state, canStart, savedWsIdOrReason = readGAG2SavedTrackState(defaults.settingsFile)
        if canStart ~= true then
            return false, tostring(savedWsIdOrReason or "track_state_off")
        end

        if trim(defaults.wsBaseUrl) == "" then
            return false, "ws_base_url_empty"
        end

        if trim(defaults.authPassword) == "" then
            return false, "auth_empty"
        end

        local opts = {
            namespace = namespace,
            scriptName = defaults.scriptName,
            gameName = defaults.gameName,
            sc_id = defaults.scId,
            wsId = tostring(savedWsIdOrReason),
            wsBaseUrl = defaults.wsBaseUrl,
            authPassword = defaults.authPassword,
            settingsFile = defaults.settingsFile,
            saveFile = resolveConfigSaveFile(nil, namespace),
            defaultSaveFile = resolveConfigSaveFile(nil, namespace),
            statsInterval = 60,
            assetsInterval = 60,
            useServerStatsInterval = false,
            persistTrackState = true,
            persistSettings = false,
            autoStartOnBoot = true,
            autoStartDelay = 0,
            collectAssets = true,
            assetMode = "gag2",
            sendDefaultConfigOnTrack = true,
            sendDefaultConfigOnChange = true,
            installAutoGiftAction = true,
        }

        local bridge = NodeHubWS.GAG2(nil, opts)
        if type(bridge) == "table" then
            bridge._helperAutoBoot = true
            bridge._helperAutoBootReason = tostring(reason or "helper_delayed_boot")
            return true, "bridge_created"
        end

        return false, "bridge_create_failed"
    end

    local function scheduleGAG2DelayedAutoBoot(opts)
        opts = type(opts) == "table" and opts or {}

        if opts.force ~= true and __gag2AutoBootStarted == true then
            return false, "already_scheduled"
        end

        __gag2AutoBootStarted = true
        __gag2AutoBootLastReason = tostring(opts.reason or "helper_load")

        local delaySec = tonumber(opts.delay or opts.delaySec or G.__NODEHUB_WS_AUTO_BOOT_DELAY or rawget(_G, "__NODEHUB_WS_AUTO_BOOT_DELAY")) or 15
        local maxAttempts = tonumber(opts.maxAttempts or opts.limit or G.__NODEHUB_WS_AUTO_BOOT_LIMIT or rawget(_G, "__NODEHUB_WS_AUTO_BOOT_LIMIT")) or 6
        local intervalSec = tonumber(opts.interval or opts.intervalSec or G.__NODEHUB_WS_AUTO_BOOT_INTERVAL or rawget(_G, "__NODEHUB_WS_AUTO_BOOT_INTERVAL")) or 5

        if delaySec < 0 then delaySec = 0 end
        if maxAttempts < 1 then maxAttempts = 1 end
        if maxAttempts > 20 then maxAttempts = 20 end
        if intervalSec < 1 then intervalSec = 1 end

        local function attempt(n)
            local ok, msg = runGAG2DelayedAutoBoot(__gag2AutoBootLastReason .. "_attempt_" .. tostring(n))
            local bridge = NodeHubWS.Get("gag2")
            local connected = type(bridge) == "table" and bridge.connected == true

            if connected == true then
                return
            end

            -- Retry ringan: jangan spam resolve berkali-kali.
            local retryable = tostring(msg or ""):match("state_not_found")
                or tostring(msg or ""):match("ws_base_url_empty")
                or tostring(msg or ""):match("auth_empty")
                or tostring(msg or ""):match("bridge_created")
                or tostring(msg or ""):match("existing_bridge")
                or tostring(msg or ""):match("http_failed")
                or tostring(msg or ""):match("resolve_cooldown")

            -- resolve_failed / key invalid: jangan retry loop (buang request).
            if tostring(msg or ""):match("key_invalid") or tostring(msg or ""):match("json_invalid") then
                retryable = false
            end

            if n < maxAttempts and retryable then
                task.delay(intervalSec, function()
                    attempt(n + 1)
                end)
            end
        end

        task.delay(delaySec, function()
            attempt(1)
        end)

        return true, "scheduled"
    end

    function NodeHubWS.ScheduleGAG2AutoBoot(opts)
        return scheduleGAG2DelayedAutoBoot(opts)
    end

    function NodeHubWS.GAG2AutoStart(opts)
        -- Shortcut headless untuk auto execute.
        -- Panggil ini di boot awal script dengan opsi yang sama seperti NodeHubWS.GAG2.
        return NodeHubWS.GAG2(nil, opts or {})
    end

    function NodeHubWS.IsNMMonitorEnabled()
        local env = (getgenv and getgenv()) or G
        local v = env.NM_MONITOR
        if v == true or v == 1 then return true end
        if type(v) == "string" then
            local low = string.lower(trim(v))
            return low == "true" or low == "1" or low == "yes" or low == "on"
        end
        return false
    end

    function NodeHubWS.GetNMScriptKey()
        local env = (getgenv and getgenv()) or G
        local key = env.NM_SCRIPT_KEY or env.script_key
            or G.NM_SCRIPT_KEY or rawget(_G, "NM_SCRIPT_KEY")
            or G.script_key or rawget(_G, "script_key")
        if type(key) == "string" and trim(key) ~= "" then
            return trim(key)
        end
        if type(getfenv) == "function" then
            for i = 2, 8 do
                local ok, e = pcall(getfenv, i)
                if ok and type(e) == "table" then
                    local v = e.script_key or e.NM_SCRIPT_KEY
                    if type(v) == "string" and trim(v) ~= "" then
                        return trim(v)
                    end
                end
            end
        end
        return ""
    end

    function NodeHubWS.ResolveMonitor(opts)
        opts = type(opts) == "table" and opts or {}
        local key = trim(tostring(opts.key or opts.script_key or NodeHubWS.GetNMScriptKey() or ""))
        if key == "" then
            return nil, "script_key_empty"
        end

        -- Cache sukses + cooldown gagal supaya boot retry tidak spam resolve.
        local cache = G.__NM_RESOLVE_CACHE
        if type(cache) ~= "table" then
            cache = {}
            G.__NM_RESOLVE_CACHE = cache
            _G.__NM_RESOLVE_CACHE = cache
        end
        local nowClock = os.clock()
        local cached = cache[key]
        local force = opts.force == true
        if not force and type(cached) == "table" then
            if type(cached.data) == "table" and (nowClock - (cached.at or 0)) < 300 then
                return cached.data, nil
            end
            if cached.failAt and (nowClock - cached.failAt) < 8 then
                return nil, tostring(cached.failErr or "resolve_cooldown")
            end
        end

        local env = (getgenv and getgenv()) or G
        local resolveUrl = trim(tostring(opts.resolveUrl or opts.resolve_url or env.NM_RESOLVE_URL or G.__NM_RESOLVE_URL or rawget(_G, "__NM_RESOLVE_URL") or ""))
        if resolveUrl ~= "" then
            resolveUrl = resolveUrl:gsub("%?.*$", "")
        else
            local base = trim(tostring(
                opts.resolveBase or opts.resolve_base
                or env.NM_RESOLVE_BASE or G.__NM_RESOLVE_BASE or rawget(_G, "__NM_RESOLVE_BASE")
                or ""
            ))
            if base == "" then
                -- base = "http://127.0.0.1:8080" -- << LOCAL
                base = "https://nodemonitor.io" -- << PRODUCTION (aktif)
            end
            base = base:gsub("/+$", "")
            resolveUrl = base .. "/user-monitor/resolve-monitor"
        end

        local lp = Players.LocalPlayer or LP
        if not lp then
            cache[key] = { failAt = nowClock, failErr = "player_not_ready" }
            return nil, "player_not_ready"
        end

        local userId = tonumber(lp.UserId) or 0
        local username = trim(tostring(lp.Name or ""))
        local placeId = tostring(game.PlaceId or "")
        local jobId = tostring(game.JobId or "")
        if placeId == "" then placeId = "-" end
        if jobId == "" then jobId = "-" end
        if userId <= 0 or username == "" then
            cache[key] = { failAt = nowClock, failErr = "player_not_ready" }
            return nil, "player_not_ready"
        end

        local ts = math.floor(tonumber(os.time()) or 0)
        local nonce = randomNonceHex()
        local canonical = table.concat({
            "1",
            tostring(math.floor(userId)),
            string.lower(username),
            placeId,
            jobId,
            tostring(ts),
            nonce,
            sha256(key, true),
        }, "|")
        local secret = trim(tostring(
            env.NM_RESOLVE_SECRET or G.__NM_RESOLVE_SECRET or rawget(_G, "__NM_RESOLVE_SECRET") or MONITOR_RESOLVE_SECRET
        ))
        local sig = hmacSha256(secret, canonical)

        local payload = {
            v = 1,
            script_key = key,
            user_id = math.floor(userId),
            username = username,
            place_id = placeId,
            job_id = jobId,
            ts = ts,
            nonce = nonce,
            sig = sig,
        }

        local ok, body = pcall(function()
            local resBody = httpPostJson(resolveUrl, payload)
            return resBody
        end)
        if not ok then
            cache[key] = { failAt = nowClock, failErr = "http_failed:" .. tostring(body) }
            return nil, "http_failed:" .. tostring(body)
        end

        local okJson, data = pcall(function()
            return HttpService:JSONDecode(tostring(body or ""))
        end)
        if not okJson or type(data) ~= "table" then
            cache[key] = { failAt = nowClock, failErr = "json_invalid" }
            return nil, "json_invalid"
        end
        if data.ok ~= true then
            local err = tostring(data.error or data.messages or "resolve_failed")
            cache[key] = { failAt = nowClock, failErr = err }
            return nil, err
        end
        if trim(tostring(data.ws_id or "")) == "" then
            cache[key] = { failAt = nowClock, failErr = "ws_id_empty" }
            return nil, "ws_id_empty"
        end

        cache[key] = { data = data, at = nowClock }
        return data, nil
    end

    function NodeHubWS.TryNMMonitorBind(opts)
        opts = type(opts) == "table" and opts or {}
        if NodeHubWS.IsNMMonitorEnabled() ~= true then
            return false, "nm_monitor_off"
        end

        -- Sudah bound + connected: jangan resolve ulang, tapi refresh collector.
        -- Jangan reuse bridge namespace lain (gag2 vs steal_egg) — itu bikin
        -- identity/stats ketuker atau socket saling replace.
        local ns = safeToString(opts.namespace or opts.name or "gag2", "gag2")
        local existing = NodeHubWS.Get(ns)
        if type(existing) == "table"
            and existing._nmMonitorBound == true
            and existing.connected == true
            and trim(tostring(existing.wsId or "")) ~= "" then
            if type(existing.UpdateOptions) == "function" then
                pcall(function()
                    existing:UpdateOptions(opts)
                end)
            elseif type(opts.getAssets) == "function" or type(opts.collectAssetsFn) == "function" then
                existing.getAssets = opts.getAssets or opts.collectAssetsFn
            end
            existing._assetsCache = nil
            existing._assetsCacheAt = 0
            return true, existing
        end

        local resolved, err = NodeHubWS.ResolveMonitor({
            key = opts.key or opts.script_key,
            script_key = opts.script_key or opts.key,
            resolveUrl = opts.resolveUrl or opts.resolve_url,
            resolve_url = opts.resolve_url or opts.resolveUrl,
            resolveBase = opts.resolveBase or opts.resolve_base,
            resolve_base = opts.resolve_base or opts.resolveBase,
            force = opts.force == true,
        })
        if type(resolved) ~= "table" then
            return false, tostring(err or "resolve_failed")
        end

        local defaults = getGAG2AutoBootDefaults()
        local bootOpts = {
            namespace = "gag2",
            scriptName = defaults.scriptName or "Grow A Garden 2",
            gameName = defaults.gameName or "Grow A Garden 2",
            sc_id = defaults.scId,
            wsBaseUrl = defaults.wsBaseUrl,
            authPassword = defaults.authPassword,
            settingsFile = defaults.settingsFile,
            saveFile = resolveConfigSaveFile(nil, "gag2"),
            defaultSaveFile = resolveConfigSaveFile(nil, "gag2"),
            statsInterval = tonumber(opts.statsInterval) or 60,
            assetsInterval = tonumber(opts.assetsInterval) or 60,
            useServerStatsInterval = false,
            persistTrackState = true,
            persistSettings = false,
            autoStartOnBoot = true,
            autoStartDelay = 0,
            collectAssets = true,
            assetMode = "gag2",
            sendDefaultConfigOnTrack = true,
            sendDefaultConfigOnChange = true,
            installAutoGiftAction = true,
        }

        for k, v in pairs(opts) do
            if k ~= "key" and k ~= "script_key" and k ~= "resolveUrl" and k ~= "resolve_url"
                and k ~= "resolveBase" and k ~= "resolve_base" and k ~= "reason" then
                bootOpts[k] = v
            end
        end

        bootOpts.wsId = tostring(resolved.ws_id)
        if trim(tostring(bootOpts.wsBaseUrl or "")) == "" and type(resolved.ws_url) == "string" and resolved.ws_url ~= "" then
            bootOpts.wsBaseUrl = resolved.ws_url
        end
        if trim(tostring(bootOpts.authPassword or "")) == "" then
            bootOpts.authPassword = firstNonEmpty(
                G.__NODEHUB_WS_AUTH_PASSWORD,
                rawget(_G, "__NODEHUB_WS_AUTH_PASSWORD"),
                "sanken2"
            )
        end

        local bridge = NodeHubWS.GAG2(nil, bootOpts)
        if type(bridge) ~= "table" then
            return false, "bridge_create_failed"
        end

        -- Pastikan wsId + track ON tersimpan meski bridge sudah ada sebelumnya.
        bridge.wsId = tostring(resolved.ws_id)
        bridge._nmMonitorBound = true
        bridge._nmMonitorReason = tostring(opts.reason or "nm_monitor_bind")
        if type(bootOpts.getAssets) == "function" or type(bootOpts.collectAssetsFn) == "function" then
            bridge.getAssets = bootOpts.getAssets or bootOpts.collectAssetsFn
        end
        bridge._assetsCache = nil
        bridge._assetsCacheAt = 0

        if type(bridge.SetTrack) == "function" then
            pcall(function()
                bridge:SetTrack(true)
            end)
        end
        if type(bridge.EnsureTracked) == "function" then
            pcall(function()
                bridge:EnsureTracked("nm_monitor_bind")
            end)
        elseif bridge.connected ~= true and type(bridge.Connect) == "function" then
            pcall(function()
                bridge:Connect(bootOpts.wsId)
            end)
        end

        -- Sync UI Track Server kalau section sudah kebuka.
        pcall(function()
            local box = bridge._wsIdBox
            if box and box:IsA("TextBox") then
                box.Text = tostring(bridge.wsId or "")
            end
            local api = bridge._trackToggleApi
            local setter = bridge._trackToggleSetter
            if type(api) == "table" and type(api.setOn) == "function" then
                api.setOn(true)
            elseif type(setter) == "function" then
                setter(true, true)
            end
            if bridge._statusLabel and bridge._statusLabel:IsA("TextLabel") then
                bridge._statusLabel.Text = "Status: " .. tostring(compactTrackStatus(bridge) or "ON")
