local function getSave()
	bindGame()
	if type(Save) ~= "table" or type(Save.Get) ~= "function" then
		return nil
	end
	local ok, data = pcall(Save.Get)
	if ok and type(data) == "table" then
		return data
	end
	local ok2, data2 = pcall(Save.Get, LP, false)
	if ok2 and type(data2) == "table" then
		return data2
	end
	return nil
