local function num(v)
	return tonumber(v) or 0
end

local function trim(s)
	return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function shortNum(n)
	n = num(n)
	local a = math.abs(n)
	if a >= 1e15 then
		return string.format("%.1fQa", n / 1e15)
	end
	if a >= 1e12 then
		return string.format("%.1fT", n / 1e12)
	end
	if a >= 1e9 then
		return string.format("%.1fB", n / 1e9)
	end
	if a >= 1e6 then
		return string.format("%.1fM", n / 1e6)
	end
	if a >= 1e3 then
		return string.format("%.1fk", n / 1e3)
	end
	if a >= 10 or n == math.floor(n) then
		return string.format("%.0f", n)
	end
	return string.format("%.1f", n)
end

local function speedLabel(power)
	power = num(power)
	if type(TreadmillUtil) == "table" and type(TreadmillUtil.FormatSpeedPower) == "function" then
		local ok, s = pcall(TreadmillUtil.FormatSpeedPower, power)
		if ok and type(s) == "string" and trim(s) ~= "" then
			return s
		end
	end
	return shortNum(power)
end

local function slotCount(level)
	level = num(level)
	bindGame()
	if type(Bases) == "table" then
		if type(Bases.GetAssetEquipCapacity) == "function" then
			local ok, n = pcall(Bases.GetAssetEquipCapacity, level)
			if ok and tonumber(n) then
				return tonumber(n)
			end
		end
		local cfg = Bases.BASES and Bases.BASES[level]
		if type(cfg) == "table" then
			return num(cfg.MaxAssets)
		end
	end
	return 0
end

local function treadmillMax()
	bindGame()
	if type(Treadmills) == "table" then
		if type(Treadmills.GetOrdered) == "function" then
			local ok, list = pcall(Treadmills.GetOrdered)
			if ok and type(list) == "table" then
				return #list
			end
		end
		if type(Treadmills.Directory) == "table" then
			local n = 0
			for _ in pairs(Treadmills.Directory) do
				n = n + 1
			end
			return n
		end
	end
	return 0
end

local function plotCap()
	local hatch = G.StealEggHatch
	if type(hatch) == "table" and type(hatch.placeCap) == "function" then
		local ok, cap = pcall(hatch.placeCap)
		if ok and tonumber(cap) then
			return tonumber(cap)
		end
	end
	return 0
end

local function countEarnLabel(n, rate)
	n = math.floor(num(n) + 0.5)
	rate = num(rate)
	if rate > 0 then
		return string.format("%d  ·  %s/s", n, shortNum(rate))
	end
	return tostring(n)
end

local function assetCfg(category)
	if category == nil or type(Core.assetConfig) ~= "function" then
		return nil
	end
	local ok, cfg = pcall(Core.assetConfig, category)
	if ok and type(cfg) == "table" then
		return cfg
	end
	return nil
end

local function displayName(category, cfg)
	cfg = cfg or assetCfg(category)
	if type(cfg) == "table" then
		local n = cfg.DisplayName or cfg.Name or cfg._id
		if n ~= nil and tostring(n) ~= "" then
			return tostring(n)
		end
	end
	return tostring(category or "")
end

local function rarityOf(category, cfg)
	cfg = cfg or assetCfg(category)
	local r = type(cfg) == "table" and cfg.Rarity
	local n = 0
	local id = ""
	if type(r) == "table" then
		n = num(r.RarityNumber)
		id = tostring(r._id or r.DisplayName or r.Name or "")
	end
	if n <= 0 and type(Core.eggRarityNumber) == "function" then
		n = num(Core.eggRarityNumber(category))
	end
	if id == "" then
		id = RARITY_NAME[n] or ""
	end
	return n, id
end

local function iconAssetId(cfg)
	if type(cfg) ~= "table" then
		return nil
	end
	local s = cfg.Icon
	if type(s) ~= "string" and type(cfg.Egg) == "table" then
		s = cfg.Egg.Icon
	end
	if type(s) ~= "string" then
		return nil
	end
	local id = s:match("rbxassetid://(%d+)") or s:match("^(%d+)$")
	if id and id ~= "" and id ~= "0" then
		return id
	end
	return nil
end

local function eggRecord(raw)
	if type(raw) ~= "table" then
		return nil
	end
	if raw.AssetCategory ~= nil or raw.Category ~= nil then
		return raw
	end
	if type(EggItemUtil) == "table" then
		local fn = EggItemUtil.DeserializeSavedEgg or EggItemUtil.Decode
		if type(fn) == "function" then
			local ok, egg = pcall(fn, raw)
			if ok and type(egg) == "table" then
				return egg
			end
		end
	end
	return raw
end

local function petRecord(raw)
	if type(raw) ~= "table" then
		return nil
	end
	if raw.Category ~= nil then
		return raw
	end
	if type(AssetItemSerialization) == "table" then
		local fn = AssetItemSerialization.Deserialize or AssetItemSerialization.Decode
		if type(fn) == "function" then
			local ok, item = pcall(fn, raw)
			if ok and type(item) == "table" then
				return item
			end
		end
	end
	return raw
end

local function eggToAsset(egg)
	if type(egg) ~= "table" then
		return nil
	end
	if type(EggItemUtil) == "table" and type(EggItemUtil.BuildAssetItemData) == "function" then
		local ok, item = pcall(EggItemUtil.BuildAssetItemData, egg)
		if ok and type(item) == "table" then
			return item
		end
	end
	return {
		Category = egg.AssetCategory or egg.Category,
		Scale = egg.AssetScale or egg.Scale,
		Mutations = type(egg.Mutations) == "table" and egg.Mutations or {},
		BaseMutation = egg.BaseMutation,
		Gender = egg.AssetGender or egg.Gender,
		EyeColor = egg.AssetEyeColor or egg.EyeColor,
		ColorSeed = egg.AssetColorSeed or egg.ColorSeed,
		ColorIndex = egg.AssetColorIndex or egg.ColorIndex,
		Personality = egg.AssetPersonality or egg.Personality,
		IsStolenDNA = egg.IsStolenDNA,
	}
end

local function sizeEarnMulti(scale)
	scale = num(scale)
	if scale <= 0 then
		return 0
	end
	if scale <= 5 then
		return scale ^ 1.85
	end
	return (scale / 5) ^ 1.2 * 19.637875755794113
end

local function mutEarnMulti(muts)
	if type(Mutations) == "table" then
		local fn = Mutations.GetTotalMutationsEarningMulti or Mutations.EarningsFor
		if type(fn) == "function" then
			local ok, n = pcall(fn, muts or {})
			if ok then
				return math.max(1, num(n))
			end
		end
	end
	return 1
end

local function itemRate(assetData, saveData)
	if type(assetData) ~= "table" or type(assetData.Category) ~= "string" then
		return 0
	end
	if type(AssetEarnings) == "table" then
		local rateFn = AssetEarnings.GetRate or AssetEarnings.RatePerSecond
		if type(rateFn) == "function" then
			local rebirth = type(saveData) == "table" and num(saveData.Rebirth) or 0
			local ok, n = pcall(rateFn, assetData, rebirth, saveData and saveData.Gamepasses, saveData and saveData.Products)
			if ok then
				return math.max(0, num(n))
			end
		end
	end
	local cfg = assetCfg(assetData.Category)
	local base = type(cfg) == "table" and num(cfg.EarningRate) or 0
	local n = math.floor(base * sizeEarnMulti(assetData.Scale) * mutEarnMulti(assetData.Mutations) + 0.5)
	return math.max(n, 0)
end

local function itemPrice(assetData, rate)
	if type(assetData) == "table" then
		if type(EggItemUtil) == "table" and type(EggItemUtil.SellPrice) == "function" then
			local ok, n = pcall(EggItemUtil.SellPrice, assetData)
			if ok then
				local price = num(n)
				if price > 0 then
					return price
				end
			end
		end
		if type(GetPriceValueForItem) == "function" then
			local ok, n = pcall(GetPriceValueForItem, assetData)
			if ok then
				local price = num(n)
				if price > 0 then
					return price
				end
			end
		end
		if type(AssetItems) == "table" then
			local fn = AssetItems.SalePrice or AssetItems.GetPriceValueForItem
			if type(fn) == "function" then
				local ok, n = pcall(fn, assetData)
				if ok then
					local price = num(n)
					if price > 0 then
						return price
					end
				end
			end
		end
	end
	return 0
end

local function mutationText(data)
	local names, seen = {}, {}
	local function add(name)
		name = tostring(name or "")
		if name == "" or name == "None" or seen[name] then
			return
		end
		seen[name] = true
		if type(Core.mutationLabel) == "function" then
			names[#names + 1] = Core.mutationLabel(name)
		else
			names[#names + 1] = name
		end
	end
	if type(data) == "table" then
		if type(data.Mutations) == "table" then
			for _, n in ipairs(data.Mutations) do
				add(n)
			end
			for _, n in pairs(data.Mutations) do
				if type(n) == "string" then
					add(n)
				end
			end
		end
		add(data.BaseMutation)
	end
	if #names == 0 then
		return "Normal"
	end
	return table.concat(names, "+")
end

local function itemKg(category, scale)
	category = tostring(category or "")
	scale = num(scale)
	if category == "" then
		return 0
	end
	if type(EggItemUtil) == "table" then
		local fn = EggItemUtil.WeightKgForScale or EggItemUtil.GetWeightKgForScale
		if type(fn) == "function" then
			local ok, kg = pcall(fn, category, scale)
			if ok then
				return math.max(0, num(kg))
			end
		end
	end
	local cfg = assetCfg(category)
	local weight = type(cfg) == "table" and num(cfg.ModelWeight)
	if weight <= 0 then
		weight = 1
	end
	return weight * math.max(scale, 0) ^ 3
end

local function fmtRemain(sec)
	sec = math.max(0, math.floor(num(sec) + 0.5))
	if sec <= 0 then
		return "Ready"
	end
	local h = math.floor(sec / 3600)
	local m = math.floor((sec % 3600) / 60)
	local s = sec % 60
	if h > 0 then
		return string.format("%dh %dm", h, m)
	end
	if m > 0 then
		return string.format("%dm %ds", m, s)
	end
	return string.format("%ds", s)
end

local function eggDisplayName(egg, petName)
	if type(EggItemUtil) == "table" then
		local fn = EggItemUtil.DisplayName or EggItemUtil.GetDisplayName
		if type(fn) == "function" then
			local ok, s = pcall(fn, egg)
			if ok and type(s) == "string" then
				s = trim(s)
				if s ~= "" and s ~= "Egg" then
					return s
				end
			end
		end
	end
	petName = trim(petName)
	if petName ~= "" then
		return petName .. " Egg"
	end
	return "Egg"
end

local function growthCurve(scale)
	scale = num(scale)
	if scale <= 2 then
		return 1
	end
	if scale <= 6 then
		return (scale / 2) ^ 1.389
	end
	return math.min((scale / 6) ^ 0.72 * 4.6, 20)
end

local function eggGrowthDuration(egg)
	local placed = type(egg) == "table" and egg.Placement
	if type(placed) == "table" then
		local stored = num(placed.GrowthDuration or egg.GrowthDuration)
		if stored > 0 then
			return stored
		end
	end
	local cfg = assetCfg(egg.AssetCategory or egg.Category)
	local eggCfg = type(cfg) == "table" and cfg.Egg
	local growthTime = type(eggCfg) == "table" and num(eggCfg.GrowthTime) or 0
	if growthTime <= 0 then
		return 0
	end
	if eggCfg.IgnoreSizeGrowthMultiplier then
		return growthTime
	end
	return growthTime * growthCurve(egg.AssetScale or egg.Scale)
end

local function eggNightCredit(egg, now, speed)
	if type(EggItemUtil) ~= "table" then
		return 0
	end
	local fn = EggItemUtil.GetCurrentNightGrowthCreditSeconds or EggItemUtil.CurrentNightCredit
	if type(fn) ~= "function" then
		return 0
	end
	local ok, n = pcall(fn, egg, now, speed)
	if ok then
		return math.max(0, num(n))
	end
	return 0
end

local function eggRemain(egg)
	if type(egg) ~= "table" or type(egg.Placement) ~= "table" then
		return nil
	end
	if egg.Placement.ReadyAt ~= nil then
		return 0
	end
	local now = 0
	pcall(function()
		now = Workspace:GetServerTimeNow()
	end)
	local speed = num(egg.GrowthSpeedMultiplier)
	if speed <= 0 then
		speed = 1
	end
	local night = eggNightCredit(egg, now, speed)
	if type(EggItemUtil) == "table" then
		local fn = EggItemUtil.GetRemainingGrowthSeconds or EggItemUtil.GrowthSecondsRemaining
		if type(fn) == "function" then
			local ok, n = pcall(fn, egg, now, speed, night, LP)
			if ok and n ~= nil then
				return math.max(0, num(n))
			end
		end
	end
	local placedAt = num(egg.Placement.PlacedAt)
	local dur = eggGrowthDuration(egg)
	local credit = num(egg.Placement.GrowthCreditSeconds)
	if placedAt > 0 and dur > 0 and now > 0 then
		return math.max(0, dur - credit - night - (now - placedAt) * speed)
	end
	return nil
end

local function appendSorted(src, items, totals)
	table.sort(src, function(a, b)
		if num(a.rarity_n) ~= num(b.rarity_n) then
			return num(a.rarity_n) > num(b.rarity_n)
		end
		if num(a.rate) ~= num(b.rate) then
			return num(a.rate) > num(b.rate)
		end
		return tostring(a.name) < tostring(b.name)
	end)
	for i = 1, math.min(#src, MAX_ITEMS - #items) do
		local row = src[i]
		items[#items + 1] = row
		totals.items = totals.items + num(row.count)
		totals.value = totals.value + num(row.value)
	end
end

local function equippedSet(data)
	local set = {}
	if type(data) ~= "table" or type(data.EquippedAssets) ~= "table" then
		return set
	end
	for _, uid in pairs(data.EquippedAssets) do
		set[tostring(uid)] = true
	end
	return set
end

local function bump(buckets, cat, key, add)
	if key == nil or key == "" then
		return
	end
	local row = buckets[key]
	if not row then
		row = {
			category = cat,
			group = string.lower(cat),
			key = tostring(key),
			name = add.name or tostring(key),
			count = 0,
			value = 0,
			rate = 0,
			rarity_n = 0,
			rarity = add.rarity or "",
			asset_id = add.asset_id,
			equipped = 0,
			favorite = 0,
		}
		buckets[key] = row
	end
	row.count = row.count + (add.count or 1)
	row.value = row.value + num(add.value)
	row.rate = row.rate + num(add.rate)
	if num(add.rarity_n) > row.rarity_n then
		row.rarity_n = num(add.rarity_n)
		if add.rarity and add.rarity ~= "" then
			row.rarity = add.rarity
		end
	end
	if add.equipped == true then
		row.equipped = row.equipped + 1
	end
	if add.favorite == true then
		row.favorite = row.favorite + 1
	end
	if not row.asset_id and add.asset_id then
		row.asset_id = add.asset_id
	end
end

local function flush(buckets, items, totals)
	local rows = {}
	for _, row in pairs(buckets) do
		rows[#rows + 1] = row
	end
	table.sort(rows, function(a, b)
		if a.rarity_n ~= b.rarity_n then
			return a.rarity_n > b.rarity_n
		end
		if a.value ~= b.value then
			return a.value > b.value
		end
		return tostring(a.name) < tostring(b.name)
	end)
	for i = 1, math.min(#rows, MAX_ITEMS - #items) do
		local row = rows[i]
		local out = {
			category = row.category,
			group = row.group,
			key = row.key,
			name = row.name,
			count = row.count,
			amount = row.count,
			value = row.value,
			value_is_total = true,
			value_label = shortNum(row.value),
		}
		if row.rate > 0 then
			out.rate = row.rate
		end
		if row.rarity ~= "" then
			out.rarity = row.rarity
		end
		if row.asset_id then
			out.asset_id = row.asset_id
			out.icon = "rbxassetid://" .. tostring(row.asset_id)
		end
		if row.equipped > 0 then
			out.equipped = row.equipped
		end
		if row.favorite > 0 then
			out.favorite = row.favorite
		end
		items[#items + 1] = out
		totals.items = totals.items + row.count
		totals.value = totals.value + row.value
	end
end

local function gearName(id)
	id = tostring(id or "")
	local dir = GearsDir
	if type(dir) == "table" then
		dir = dir.Directory or dir.GEARS or dir
		local cfg = type(dir) == "table" and (dir[id] or dir[tonumber(id)])
		if type(cfg) == "table" then
			return tostring(cfg.DisplayName or cfg.Name or cfg._id or id), iconAssetId(cfg)
		end
	end
	return id, nil
end

function M.collectFull()
	if GEN ~= G.__StealEggMonitorGen then
		return nil
	end
	local now = os.clock()
	if type(M._cache) == "table"
		and tostring(M._cache.source or "") == "steal_egg.save"
		and (now - (M._cacheAt or 0)) < CACHE_TTL
	then
		return M._cache
	end

	bindGame()
	local data = getSave()
	local money = type(data) == "table" and num(data.Money) or 0
	local rebirth = type(data) == "table" and num(data.Rebirth) or 0
	local speedPower = type(data) == "table" and num(data.SpeedPower) or 0
	local items = {}
	local totals = { items = 0, value = 0 }
	local eggBag, eggPlot, petN, petBag, gearN, trailN = 0, 0, 0, 0, 0, 0
	local eggBagValue, eggPlotValue, petValue = 0, 0, 0
	local eggBagRate, eggPlotRate, petBagRate, equipRate = 0, 0, 0, 0
	local equippedN = 0
	local topEarnName, topEarnRate = "", 0
	local deadline = now + 2.5
	local scanned = 0
	local SCAN_CAP = 2500

	if type(data) == "table" then
		local worn = equippedSet(data)

		local eggRows = {}
		if type(data.EggInventory) == "table" then
			for uid, raw in pairs(data.EggInventory) do
				scanned = scanned + 1
				if scanned > SCAN_CAP or os.clock() > deadline then
					break
				end
				local egg = eggRecord(raw)
				if type(egg) == "table" then
					local cat = tostring(egg.AssetCategory or egg.Category or "")
					if cat ~= "" then
						local placed = type(egg.Placement) == "table"
						if placed then
							eggPlot = eggPlot + 1
						else
							eggBag = eggBag + 1
						end
						local asset = eggToAsset(egg)
						local rate = itemRate(asset, data)
						local price = itemPrice(egg, rate)
						if price <= 0 then
							price = itemPrice(asset, rate)
						end
						if placed then
							eggPlotValue = eggPlotValue + price
							eggPlotRate = eggPlotRate + rate
						else
							eggBagValue = eggBagValue + price
							eggBagRate = eggBagRate + rate
						end
						local cfg = assetCfg(cat)
						local rn, rid = rarityOf(cat, cfg)
						local petName = displayName(cat, cfg)
						local eggName = eggDisplayName(egg, petName)
						local kg = itemKg(cat, egg.AssetScale or egg.Scale)
						local mut = mutationText(egg)
						local remain = placed and eggRemain(egg) or nil
						local ready = placed == true and remain ~= nil and remain <= 0
						local row = {
							category = "Eggs",
							group = "eggs",
							key = tostring(uid),
							uid = tostring(uid),
							name = eggName,
							egg_name = eggName,
							count = 1,
							amount = 1,
							value = price,
							value_is_total = false,
							value_label = shortNum(price),
							rarity_n = rn,
							kg = kg,
							scale = num(egg.AssetScale or egg.Scale),
							mutation = mut,
							mutations = mut,
							placed = placed,
							state = placed and "Plot" or "Bag",
						}
						if rate > 0 then
							row.rate = rate
							row.earn = rate
						end
						if rid ~= "" then
							row.rarity = rid
						end
						local icon = iconAssetId(cfg)
						if icon then
							row.asset_id = icon
							row.icon = "rbxassetid://" .. tostring(icon)
						end
						if kg > 0 then
							row.kg_label = string.format(kg >= 10 and "%.0f kg" or "%.1f kg", kg)
						end
						if placed then
							row.ready = ready
							row.time = remain or 0
							row.time_label = remain == nil and "—" or (ready and "Ready" or fmtRemain(remain))
							row.ready_label = row.time_label
						end
						eggRows[#eggRows + 1] = row
					end
				end
			end
		end
		appendSorted(eggRows, items, totals)

		local petRows = {}
		if type(data.Inventory) == "table" then
			for uid, raw in pairs(data.Inventory) do
				scanned = scanned + 1
				if scanned > SCAN_CAP or os.clock() > deadline then
					break
				end
				local pet = petRecord(raw)
				if type(pet) == "table" then
					local cat = tostring(pet.Category or "")
					if cat ~= "" then
						petN = petN + 1
						local rate = itemRate(pet, data)
						local price = itemPrice(pet, rate)
						petValue = petValue + price
						local eq = worn[tostring(uid)] == true
						if eq then
							equippedN = equippedN + 1
							equipRate = equipRate + rate
						else
							petBag = petBag + 1
							petBagRate = petBagRate + rate
						end
						local cfg = assetCfg(cat)
						local rn, rid = rarityOf(cat, cfg)
						local petName = displayName(cat, cfg)
						if rate > topEarnRate then
							topEarnRate = rate
							topEarnName = petName
						end
						local kg = itemKg(cat, pet.Scale)
						local mut = mutationText(pet)
						local row = {
							category = "Pets",
							group = "pets",
							key = tostring(uid),
							uid = tostring(uid),
							name = petName,
							type = petName,
							count = 1,
							amount = 1,
							value = price,
							value_is_total = false,
							value_label = shortNum(price),
							rarity_n = rn,
							kg = kg,
							scale = num(pet.Scale),
							mutation = mut,
							mutations = mut,
							muts = mut,
							equipped = eq and 1 or 0,
							favorite = pet.IsFavorite == true and 1 or 0,
							state = eq and "Equip" or "Bag",
						}
						if rate > 0 then
							row.rate = rate
							row.earn = rate
						end
						if rid ~= "" then
							row.rarity = rid
						end
						local icon = iconAssetId(cfg)
						if icon then
							row.asset_id = icon
							row.icon = "rbxassetid://" .. tostring(icon)
						end
						if kg > 0 then
							row.kg_label = string.format(kg >= 10 and "%.0f kg" or "%.1f kg", kg)
						end
						petRows[#petRows + 1] = row
					end
				end
			end
		end
		appendSorted(petRows, items, totals)

		local gearBuckets = {}
		if type(data.GearInventory) == "table" then
			for id, count in pairs(data.GearInventory) do
				count = math.floor(num(count))
				if count > 0 then
					gearN = gearN + count
					local name, icon = gearName(id)
					bump(gearBuckets, "Gears", tostring(id), {
						name = name,
						count = count,
						value = 0,
						asset_id = icon,
					})
				end
			end
		end
		flush(gearBuckets, items, totals)

		local trailBuckets = {}
		if type(data.TrailInventory) == "table" then
			for id, on in pairs(data.TrailInventory) do
				if on == true or num(on) > 0 then
					trailN = trailN + 1
					bump(trailBuckets, "Trails", tostring(id), {
						name = tostring(id),
						count = 1,
						value = 0,
						equipped = tostring(data.EquippedTrail or "") == tostring(id),
					})
				end
			end
		end
		flush(trailBuckets, items, totals)
	end

	local income = equipRate
	local netEarn = eggBagRate + eggPlotRate + petBagRate + equipRate
	local penLv = type(data) == "table" and num(data.BaseUpgradeLevel) or 0
	local beltLv = type(data) == "table" and num(data.TreadmillUpgradeLevel) or 0
	local slots = slotCount(penLv)
	local beltMax = treadmillMax()
	local plotCapN = plotCap()
	local treadmillLabel = beltMax > 0 and string.format("%d/%d", beltLv, beltMax) or tostring(math.floor(beltLv + 0.5))
	local equipLabel = string.format("%d/%d  ·  %s/s", equippedN, slots, shortNum(income))
	local plotLabel = countEarnLabel(eggPlot, eggPlotRate)
	if plotCapN > 0 then
		if eggPlotRate > 0 then
			plotLabel = string.format("%d/%d  ·  %s/s", eggPlot, plotCapN, shortNum(eggPlotRate))
		else
			plotLabel = string.format("%d/%d", eggPlot, plotCapN)
		end
	end
	local overview = {
		cash = money,
		money = money,
		sheckles = money,
		sheckles_label = shortNum(money),
		speed = speedPower,
		speed_power = speedPower,
		speed_label = speedLabel(speedPower),
		rebirth = rebirth,
		egg_count = eggBag,
		plot_egg_count = eggPlot,
		pet_count = petN,
		pet_bag_count = petBag,
		gear_count = gearN,
		trail_count = trailN,
		equipped_pets = equippedN,
		equip_slots = slots,
		income_per_sec = income,
		garden_value = income,
		garden_value_label = shortNum(income) .. "/s",
		egg_bag_value = eggBagValue,
		fruit_value_backpack = eggBagValue,
		fruit_value_backpack_label = shortNum(eggBagValue),
		total_items = totals.items,
		inventory_value = totals.value,
		net_worth = netEarn,
		net_worth_label = shortNum(netEarn) .. "/s",
		net_earn = netEarn,
		net_earn_label = shortNum(netEarn) .. "/s",
		top_earn_pet = {
			type = topEarnName,
			earn = topEarnRate,
		},
		top_earn = topEarnRate,
		top_earn_label = topEarnName ~= "" and (topEarnName .. "  ·  " .. shortNum(topEarnRate) .. "/s") or "-",
		pen_level = penLv,
		treadmill_level = beltLv,
		plot_cap = plotCapN,
		egg_plot_rate = eggPlotRate,
		egg_bag_rate = eggBagRate,
		pet_bag_rate = petBagRate,
		treadmill_max = beltMax,
		cards = {
			{ key = "income", label = "Earn /s", value = income, value_label = shortNum(income) .. "/s" },
			{
				key = "top_earn",
				label = "Top Earn",
				value = topEarnRate,
				fmt = "rate",
				value_label = topEarnName ~= "" and (topEarnName .. "  ·  " .. shortNum(topEarnRate) .. "/s") or "-",
			},
			{ key = "speed", label = "Speed", value = speedPower, value_label = speedLabel(speedPower) },
			{ key = "net_earn", label = "Net Earn /s", value = netEarn, value_label = shortNum(netEarn) .. "/s" },
			{ key = "cash", label = "Cash", value = money, value_label = shortNum(money) },
			{
				key = "egg_plot",
				label = "Egg Plot",
				value = eggPlot,
				cap = plotCapN,
				rate = eggPlotRate,
				fmt = plotCapN > 0 and (eggPlotRate > 0 and "n_cap_rate" or "n_cap") or "n_rate",
				value_label = plotLabel,
			},
			{ key = "equip", label = "Equip Pet", value = equippedN, cap = slots, rate = income, fmt = "n_cap_rate", value_label = equipLabel },
			{ key = "egg_bag", label = "Egg Bag", value = eggBag, rate = eggBagRate, fmt = "n_rate", value_label = countEarnLabel(eggBag, eggBagRate) },
			{ key = "pet_bag", label = "Pet Bag", value = petBag, rate = petBagRate, fmt = "n_rate", value_label = countEarnLabel(petBag, petBagRate) },
			{ key = "pen", label = "Pen", value = penLv, cap = slots, fmt = "lv_slot", value_label = string.format("Lv %d  ·  %d slot", penLv, slots) },
			{ key = "treadmill", label = "Treadmill", value = beltLv, cap = beltMax, fmt = beltMax > 0 and "n_cap" or "", value_label = treadmillLabel },
		},
	}
	local column_schema = {}
	for i = 1, #overview.cards do
		column_schema[i] = { key = overview.cards[i].key, label = overview.cards[i].label }
	end
	overview.column_schema = column_schema
	overview.sections = {
		{ key = "summary", label = "Summary", kind = "metrics" },
		{
			key = "pet",
			label = "Pets",
			kind = "items",
			category = "pets",
			fields = {
				{ key = "type", label = "Type", kind = "enum" },
				{ key = "earn", label = "Earn", kind = "num" },
				{ key = "mutation", label = "Mut", kind = "enum" },
				{ key = "kg", label = "Kg", kind = "num" },
				{ key = "equipped", label = "Equip", kind = "num" },
				{ key = "favorite", label = "Fav", kind = "num" },
			},
		},
		{
			key = "egg",
			label = "Eggs",
			kind = "items",
			category = "eggs",
			fields = {
				{ key = "egg_name", label = "Egg", kind = "enum" },
				{ key = "earn", label = "Earn", kind = "num" },
				{ key = "mutation", label = "Mut", kind = "enum" },
				{ key = "kg", label = "Kg", kind = "num" },
				{ key = "state", label = "State", kind = "enum" },
				{ key = "time_label", label = "Time", kind = "enum" },
			},
		},
		{
			key = "gear",
			label = "Gears",
			kind = "items",
			category = "gear",
			fields = {
				{ key = "type", label = "Type", kind = "enum" },
			},
		},
		{
			key = "trail",
			label = "Trails",
			kind = "items",
			category = "trails",
			fields = {
				{ key = "type", label = "Type", kind = "enum" },
				{ key = "equipped", label = "Equipped", kind = "enum" },
			},
		},
	}

	local assets = {
		source = "steal_egg.save",
		ts = os.time(),
		sheckles = money,
		total_items = totals.items,
		total_value = totals.value,
		items = items,
		overview = overview,
	}
	M._cache = assets
	M._cacheAt = now
	M._lastSave = assets
	return assets
end

function M.collectPartial()
	if GEN ~= G.__StealEggMonitorGen then
		return nil
	end
	local t0 = os.clock()
	bindGame()
	local data = getSave()
	if type(data) ~= "table" then
		local money = 0
		return {
			source = "steal_egg.partial",
			ts = os.time(),
			sheckles = money,
			total_items = 0,
			total_value = 0,
			items = {},
			overview = {
				cash = 0,
				money = 0,
				sheckles = 0,
				sheckles_label = "0",
				total_items = 0,
				cards = {
					{ key = "cash", label = "Cash", value = 0, value_label = "0" },
				},
				column_schema = {
					{ key = "cash", label = "Cash" },
				},
			},
		}
	end

	local st = M._partial
	local needReset = type(st) ~= "table"
		or st.gen ~= GEN
		or (tonumber(st.startedAt) or 0) + PARTIAL_REFRESH_SEC < t0
		or st.done == true and (tonumber(st.doneAt) or 0) + PARTIAL_REFRESH_SEC < t0
	if needReset then
		local petKeys, eggKeys = {}, {}
		if type(data.Inventory) == "table" then
			for uid in pairs(data.Inventory) do
				petKeys[#petKeys + 1] = tostring(uid)
			end
		end
		if type(data.EggInventory) == "table" then
			for uid in pairs(data.EggInventory) do
				eggKeys[#eggKeys + 1] = tostring(uid)
			end
		end
		st = {
			gen = GEN,
			startedAt = t0,
			phase = "pets",
			petKeys = petKeys,
			eggKeys = eggKeys,
			petIdx = 1,
			eggIdx = 1,
			items = {},
			worn = equippedSet(data),
			eggBag = 0,
			eggPlot = 0,
			petN = 0,
			petBag = 0,
			eggBagValue = 0,
			eggPlotValue = 0,
			petValue = 0,
			eggBagRate = 0,
			eggPlotRate = 0,
			petBagRate = 0,
			equipRate = 0,
			equippedN = 0,
			topEarnName = "",
			topEarnRate = 0,
			gearN = 0,
			trailN = 0,
			done = false,
		}
		M._partial = st
	end

	st.data = data
	local money = num(data.Money)
	local rebirth = num(data.Rebirth)
	local speedPower = num(data.SpeedPower)

	local function pushItem(row)
		if #st.items >= MAX_ITEMS then
			return
		end
		st.items[#st.items + 1] = row
	end

	-- Multi-slice dalam 1 collect + pump background → cepat selesai tanpa flood WS.
	local budgetEnd = t0 + PARTIAL_BUDGET_SEC
	while (st.phase ~= "done" and st.done ~= true) and os.clock() < budgetEnd do
		local deadline = math.min(budgetEnd, os.clock() + PARTIAL_SLICE_SEC)
		local processed = 0
		local phaseAt = tostring(st.phase or "")

	if st.phase == "pets" then
		while st.petIdx <= #st.petKeys and processed < PARTIAL_BATCH and os.clock() < deadline do
			local uid = st.petKeys[st.petIdx]
			st.petIdx = st.petIdx + 1
			processed = processed + 1
			local raw = data.Inventory and data.Inventory[uid]
			if raw == nil and data.Inventory then
				for k, v in pairs(data.Inventory) do
					if tostring(k) == uid then
						raw = v
						break
					end
				end
			end
			local pet = petRecord(raw)
			if type(pet) == "table" then
				local cat = tostring(pet.Category or "")
				if cat ~= "" then
					st.petN = st.petN + 1
					local rate = itemRate(pet, data)
					local price = itemPrice(pet, rate)
					st.petValue = st.petValue + price
					local eq = st.worn[uid] == true
					if eq then
						st.equippedN = st.equippedN + 1
						st.equipRate = st.equipRate + rate
					else
						st.petBag = st.petBag + 1
						st.petBagRate = st.petBagRate + rate
					end
					local cfg = assetCfg(cat)
					local rn, rid = rarityOf(cat, cfg)
					local petName = displayName(cat, cfg)
					if rate > st.topEarnRate then
						st.topEarnRate = rate
						st.topEarnName = petName
					end
					local kg = itemKg(cat, pet.Scale)
					local mut = mutationText(pet)
					local row = {
						category = "Pets",
						group = "pets",
						key = uid,
						uid = uid,
						name = petName,
						type = petName,
						count = 1,
						amount = 1,
						value = price,
						value_is_total = false,
						value_label = shortNum(price),
						rarity_n = rn,
						kg = kg,
						scale = num(pet.Scale),
						mutation = mut,
						mutations = mut,
						muts = mut,
						equipped = eq and 1 or 0,
						favorite = pet.IsFavorite == true and 1 or 0,
						state = eq and "Equip" or "Bag",
					}
					if rate > 0 then
						row.rate = rate
						row.earn = rate
					end
					if rid ~= "" then
						row.rarity = rid
					end
					local icon = iconAssetId(cfg)
					if icon then
						row.asset_id = icon
						row.icon = "rbxassetid://" .. tostring(icon)
					end
					if kg > 0 then
						row.kg_label = string.format(kg >= 10 and "%.0f kg" or "%.1f kg", kg)
					end
					pushItem(row)
				end
			end
		end
		if st.petIdx > #st.petKeys then
			st.phase = "eggs"
		end
	end

	if st.phase == "eggs" then
		while st.eggIdx <= #st.eggKeys and processed < PARTIAL_BATCH and os.clock() < deadline do
			local uid = st.eggKeys[st.eggIdx]
			st.eggIdx = st.eggIdx + 1
			processed = processed + 1
			local raw = data.EggInventory and data.EggInventory[uid]
			if raw == nil and data.EggInventory then
				for k, v in pairs(data.EggInventory) do
					if tostring(k) == uid then
						raw = v
						break
					end
				end
			end
			local egg = eggRecord(raw)
			if type(egg) == "table" then
				local cat = tostring(egg.AssetCategory or egg.Category or "")
				if cat ~= "" then
					local placed = type(egg.Placement) == "table"
					if placed then
						st.eggPlot = st.eggPlot + 1
					else
						st.eggBag = st.eggBag + 1
					end
					local asset = eggToAsset(egg)
					local rate = itemRate(asset, data)
					local price = itemPrice(egg, rate)
					if price <= 0 then
						price = itemPrice(asset, rate)
					end
					if placed then
						st.eggPlotValue = st.eggPlotValue + price
						st.eggPlotRate = st.eggPlotRate + rate
					else
						st.eggBagValue = st.eggBagValue + price
						st.eggBagRate = st.eggBagRate + rate
					end
					local cfg = assetCfg(cat)
					local rn, rid = rarityOf(cat, cfg)
					local petName = displayName(cat, cfg)
					local eggName = eggDisplayName(egg, petName)
					local kg = itemKg(cat, egg.AssetScale or egg.Scale)
					local mut = mutationText(egg)
					local remain = placed and eggRemain(egg) or nil
					local ready = placed == true and remain ~= nil and remain <= 0
					local row = {
						category = "Eggs",
						group = "eggs",
						key = uid,
						uid = uid,
						name = eggName,
						egg_name = eggName,
						count = 1,
						amount = 1,
						value = price,
						value_is_total = false,
						value_label = shortNum(price),
						rarity_n = rn,
						kg = kg,
						scale = num(egg.AssetScale or egg.Scale),
						mutation = mut,
						mutations = mut,
						muts = mut,
						placed = placed,
						state = placed and "Plot" or "Bag",
					}
					if rate > 0 then
						row.rate = rate
						row.earn = rate
					end
					if rid ~= "" then
						row.rarity = rid
					end
					local icon = iconAssetId(cfg)
					if icon then
						row.asset_id = icon
						row.icon = "rbxassetid://" .. tostring(icon)
					end
					if kg > 0 then
						row.kg_label = string.format(kg >= 10 and "%.0f kg" or "%.1f kg", kg)
					end
					if placed then
						row.ready = ready
						row.time = remain or 0
						row.time_label = remain == nil and "—" or (ready and "Ready" or fmtRemain(remain))
						row.ready_label = row.time_label
					end
					pushItem(row)
				end
			end
		end
		if st.eggIdx > #st.eggKeys then
			st.phase = "tail"
		end
	end

	if st.phase == "tail" then
		local gearBuckets, trailBuckets = {}, {}
		if type(data.GearInventory) == "table" then
			for id, count in pairs(data.GearInventory) do
				count = math.floor(num(count))
				if count > 0 then
					st.gearN = st.gearN + count
					local name, icon = gearName(id)
					bump(gearBuckets, "Gears", tostring(id), {
						name = name,
						count = count,
						value = 0,
						asset_id = icon,
					})
				end
			end
		end
		if type(data.TrailInventory) == "table" then
			for id, on in pairs(data.TrailInventory) do
				if on == true or num(on) > 0 then
					st.trailN = st.trailN + 1
					bump(trailBuckets, "Trails", tostring(id), {
						name = tostring(id),
						count = 1,
						value = 0,
						equipped = tostring(data.EquippedTrail or "") == tostring(id),
					})
				end
			end
		end
		local totals = { items = #st.items, value = 0 }
		for i = 1, #st.items do
			totals.value = totals.value + num(st.items[i].value)
		end
		flush(gearBuckets, st.items, totals)
		flush(trailBuckets, st.items, totals)
		st.totals = totals
		st.phase = "done"
		st.done = true
		st.doneAt = os.clock()
	end

		if st.done == true or st.phase == "done" then
			break
		end
		if processed == 0 and tostring(st.phase or "") == phaseAt then
			break
		end
	end

	local done = st.phase == "done" or st.done == true
	local income = st.equipRate
	local netEarn = st.eggBagRate + st.eggPlotRate + st.petBagRate + st.equipRate
	local penLv = num(data.BaseUpgradeLevel)
	local beltLv = num(data.TreadmillUpgradeLevel)
	local slots = slotCount(penLv)
	local beltMax = treadmillMax()
	local plotCapN = plotCap()
	local petTotal = #st.petKeys
	local eggTotal = #st.eggKeys
	local scanned = math.min(st.petIdx - 1, petTotal) + math.min(st.eggIdx - 1, eggTotal)
	local totalKeys = petTotal + eggTotal
	local note = done and "" or string.format("%d/%d", scanned, totalKeys)
	local equipLabel = string.format("%d/%d  ·  %s/s", st.equippedN, slots, shortNum(income))
	local plotLabel = countEarnLabel(st.eggPlot, st.eggPlotRate)
	if plotCapN > 0 then
		if st.eggPlotRate > 0 then
			plotLabel = string.format("%d/%d  ·  %s/s", st.eggPlot, plotCapN, shortNum(st.eggPlotRate))
		else
			plotLabel = string.format("%d/%d", st.eggPlot, plotCapN)
		end
	end
	local treadmillLabel = beltMax > 0 and string.format("%d/%d", beltLv, beltMax) or tostring(math.floor(beltLv + 0.5))
	local overview = {
		cash = money,
		money = money,
		sheckles = money,
		sheckles_label = shortNum(money),
		speed = speedPower,
		speed_power = speedPower,
		speed_label = speedLabel(speedPower),
		rebirth = rebirth,
		egg_count = st.eggBag,
		plot_egg_count = st.eggPlot,
		pet_count = st.petN,
		pet_bag_count = st.petBag,
		gear_count = st.gearN,
		trail_count = st.trailN,
		equipped_pets = st.equippedN,
		equip_slots = slots,
		income_per_sec = income,
		garden_value = income,
		garden_value_label = shortNum(income) .. "/s",
		egg_bag_value = st.eggBagValue,
		fruit_value_backpack = st.eggBagValue,
		fruit_value_backpack_label = shortNum(st.eggBagValue),
		total_items = #st.items,
		inventory_value = (st.totals and st.totals.value) or (st.petValue + st.eggBagValue + st.eggPlotValue),
		net_worth = netEarn,
		net_worth_label = shortNum(netEarn) .. "/s",
		net_earn = netEarn,
		net_earn_label = shortNum(netEarn) .. "/s",
		top_earn_pet = { type = st.topEarnName, earn = st.topEarnRate },
		top_earn = st.topEarnRate,
		top_earn_label = st.topEarnName ~= "" and (st.topEarnName .. "  ·  " .. shortNum(st.topEarnRate) .. "/s") or "-",
		pen_level = penLv,
		treadmill_level = beltLv,
		plot_cap = plotCapN,
		egg_plot_rate = st.eggPlotRate,
		egg_bag_rate = st.eggBagRate,
		pet_bag_rate = st.petBagRate,
		treadmill_max = beltMax,
		cards = {
			{ key = "income", label = "Earn /s", value = income, value_label = shortNum(income) .. "/s" },
			{
				key = "top_earn",
				label = "Top Earn",
				value = st.topEarnRate,
				fmt = "rate",
				value_label = st.topEarnName ~= "" and (st.topEarnName .. "  ·  " .. shortNum(st.topEarnRate) .. "/s") or "-",
			},
			{ key = "speed", label = "Speed", value = speedPower, value_label = speedLabel(speedPower) },
			{ key = "net_earn", label = "Net Earn /s", value = netEarn, value_label = shortNum(netEarn) .. "/s" },
			{ key = "cash", label = "Cash", value = money, value_label = shortNum(money) },
			{
				key = "egg_plot",
				label = "Egg Plot",
				value = st.eggPlot,
				cap = plotCapN,
				rate = st.eggPlotRate,
				fmt = plotCapN > 0 and (st.eggPlotRate > 0 and "n_cap_rate" or "n_cap") or "n_rate",
				value_label = plotLabel,
			},
			{ key = "equip", label = "Equip Pet", value = st.equippedN, cap = slots, rate = income, fmt = "n_cap_rate", value_label = equipLabel },
			{ key = "egg_bag", label = "Egg Bag", value = st.eggBag, rate = st.eggBagRate, fmt = "n_rate", value_label = countEarnLabel(st.eggBag, st.eggBagRate) },
			{ key = "pet_bag", label = "Pet Bag", value = st.petBag, rate = st.petBagRate, fmt = "n_rate", value_label = countEarnLabel(st.petBag, st.petBagRate) },
			{ key = "pen", label = "Pen", value = penLv, cap = slots, fmt = "lv_slot", value_label = string.format("Lv %d  ·  %d slot", penLv, slots) },
			{ key = "treadmill", label = "Treadmill", value = beltLv, cap = beltMax, fmt = beltMax > 0 and "n_cap" or "", value_label = treadmillLabel },
		},
	}
	local column_schema = {}
	for i = 1, #overview.cards do
		column_schema[i] = { key = overview.cards[i].key, label = overview.cards[i].label }
	end
	overview.column_schema = column_schema
	overview.sections = {
		{ key = "summary", label = "Summary", kind = "metrics" },
		{
			key = "pet",
			label = "Pets",
			kind = "items",
			category = "pets",
			fields = {
				{ key = "type", label = "Type", kind = "enum" },
				{ key = "earn", label = "Earn", kind = "num" },
				{ key = "mutation", label = "Mut", kind = "enum" },
				{ key = "kg", label = "Kg", kind = "num" },
				{ key = "equipped", label = "Equip", kind = "num" },
				{ key = "favorite", label = "Fav", kind = "num" },
			},
		},
		{
			key = "egg",
			label = "Eggs",
			kind = "items",
			category = "eggs",
			fields = {
				{ key = "egg_name", label = "Egg", kind = "enum" },
				{ key = "earn", label = "Earn", kind = "num" },
				{ key = "mutation", label = "Mut", kind = "enum" },
				{ key = "kg", label = "Kg", kind = "num" },
				{ key = "state", label = "State", kind = "enum" },
				{ key = "time_label", label = "Time", kind = "enum" },
			},
		},
		{
			key = "gear",
			label = "Gears",
			kind = "items",
			category = "gear",
			fields = { { key = "type", label = "Type", kind = "enum" } },
		},
		{
			key = "trail",
			label = "Trails",
			kind = "items",
			category = "trails",
			fields = {
				{ key = "type", label = "Type", kind = "enum" },
				{ key = "equipped", label = "Equipped", kind = "enum" },
			},
		},
	}

	local function takeWireChunk(fullItems, ov, cash)
		M._wireChunks = fullItems
		M._wireChunkAt = 1
		M._wireOverview = ov
		M._wireMoney = cash
		M.ensureChunkPump()
		return M.nextChunkAssets()
	end

	local assets
	if done then
		local full = {
			source = "steal_egg.save",
			ts = os.time(),
			sheckles = money,
			total_items = #st.items,
			total_value = overview.inventory_value,
			items = st.items,
			overview = overview,
		}
		M._lastSave = full
		local cycleId = tonumber(st.startedAt) or 0
		-- Prefer HTTP upload -- WS chunk di HP sering putus sebelum pet penuh.
		if M._wireDoneCycle == cycleId and type(M._wireChunks) ~= "table" then
			assets = {
				source = "steal_egg.partial",
				source_note = "items_unchanged",
				ts = os.time(),
				sheckles = money,
				total_items = 0,
				total_value = 0,
				items = {},
				overview = overview,
			}
		else
			local uploaded = false
			local nh = G.NodeHubWS or rawget(_G, "NodeHubWS")
			local bridge = type(nh) == "table" and type(nh.Get) == "function" and (nh.Get(NS) or nh.Get("steal_egg"))
			if type(bridge) == "table" and type(bridge.UploadInventoryHttp) == "function" then
				local okUp, upRes = pcall(function()
					return bridge:UploadInventoryHttp(full)
				end)
				if okUp == true and upRes == true then
					uploaded = true
					M._wireDoneCycle = cycleId
					M._wireChunks = nil
				end
			end
			if uploaded then
				assets = {
					source = "steal_egg.partial",
					source_note = "items_unchanged",
					ts = os.time(),
					sheckles = money,
					total_items = 0,
					total_value = 0,
					items = {},
					overview = overview,
				}
			elseif #st.items > WIRE_ITEM_CHUNK then
				assets = takeWireChunk(st.items, overview, money)
			else
				assets = full
				M._wireDoneCycle = cycleId
			end
		end
	else
		-- Wire ringan: tanpa items[]. Sections/schema tetap (supaya Overview SAE tidak loncat ke layout lain).
		if note ~= "" then
			overview.collect_progress = note
		end
		assets = {
			source = "steal_egg.partial",
			source_note = "items_unchanged",
			ts = os.time(),
			sheckles = money,
			total_items = 0,
			total_value = 0,
			items = {},
			overview = overview,
		}
	end
	M._cache = assets
	M._cacheAt = t0
	return assets
end

function M.nextChunkAssets()
	local all = M._wireChunks
	if type(all) ~= "table" or #all == 0 then
		return nil
	end
	local function slim(row)
		if type(row) ~= "table" then
			return row
		end
		local out = {
			category = row.category,
			group = row.group,
			key = row.key or row.uid,
			uid = row.uid or row.key,
			name = row.name,
			type = row.type or row.name,
			count = row.count or 1,
			rarity = row.rarity,
			kg = row.kg,
			equipped = row.equipped,
			favorite = row.favorite,
			state = row.state,
		}
		local mut = row.muts or row.mutation or row.mutations
		if mut ~= nil and mut ~= "" then
			out.muts = mut
			out.mutation = mut
		end
		local earn = row.earn or row.rate
		if earn ~= nil then
			out.earn = earn
		end
		if row.egg_name then
			out.egg_name = row.egg_name
		end
		if row.time_label then
			out.time_label = row.time_label
		end
		if row.asset_id then
			out.asset_id = row.asset_id
		end
		return out
	end
	local at = tonumber(M._wireChunkAt) or 1
	if at > #all then
		M._wireChunks = nil
		return M._lastSave
	end
	local slice = {}
	local last = math.min(at + WIRE_ITEM_CHUNK - 1, #all)
	for i = at, last do
		slice[#slice + 1] = slim(all[i])
	end
	local nextAt = last + 1
	local final = nextAt > #all
	M._wireChunkAt = nextAt
	local ov = M._wireOverview
	if type(ov) ~= "table" and type(M._lastSave) == "table" then
		ov = M._lastSave.overview
	end
	-- Overview di chunk: kartu saja, tanpa sections (hemat).
	local lightOv = nil
	if type(ov) == "table" then
		lightOv = {}
		for k, v in pairs(ov) do
			if k ~= "sections" then
				lightOv[k] = v
			end
		end
	end
	local assets = {
		source = final and "steal_egg.save" or "steal_egg.chunk",
		source_note = final and nil or "chunk_upload",
		ts = os.time(),
		sheckles = M._wireMoney,
		total_items = #all,
		total_value = type(M._lastSave) == "table" and M._lastSave.total_value or 0,
		items = slice,
		chunk_offset = at - 1,
		chunk_final = final or nil,
		overview = final and ov or lightOv,
	}
	if final then
		M._wireChunks = nil
		M._wireDoneCycle = (type(M._partial) == "table" and tonumber(M._partial.startedAt)) or os.clock()
		M._lastSave = {
			source = "steal_egg.save",
			ts = assets.ts,
			sheckles = assets.sheckles,
			total_items = #all,
			total_value = assets.total_value,
			items = all,
			overview = ov,
		}
		assets.overview = ov
	end
	M._cache = assets
	M._cacheAt = os.clock()
	return assets
end

function M.ensureChunkPump()
	if M._chunkPumpOn == true then
		return
	end
	M._chunkPumpOn = true
	task.spawn(function()
		while GEN == G.__StealEggMonitorGen do
			task.wait(CHUNK_PUMP_SEC)
			if type(M._wireChunks) == "table" then
				local nh = G.NodeHubWS or rawget(_G, "NodeHubWS")
				local bridge = type(nh) == "table" and type(nh.Get) == "function" and (nh.Get(NS) or nh.Get("steal_egg"))
				if type(bridge) == "table" and bridge.connected == true and type(bridge.SendStats) == "function" then
					pcall(function()
						bridge:SendStats("sae_chunk")
					end)
				end
			end
		end
		M._chunkPumpOn = false
	end)
end

function M.ensurePartialPump()
	if M._pumpOn == true then
		return
	end
	M._pumpOn = true
	task.spawn(function()
		while GEN == G.__StealEggMonitorGen do
			task.wait(PARTIAL_PUMP_SEC)
			local st = M._partial
			if type(st) == "table" and st.done ~= true and tostring(st.phase or "") ~= "done" then
				pcall(M.collectPartial)
			end
		end
		M._pumpOn = false
	end)
end

function M.collect()
	if tostring(COLLECT_MODE or "") == "full" then
		return M.collectFull()
	end
	if type(M._wireChunks) == "table" and (tonumber(M._wireChunkAt) or 1) <= #M._wireChunks then
		local chunked = M.nextChunkAssets()
		if type(chunked) == "table" then
			return chunked
		end
	end
	M.ensurePartialPump()
	return M.collectPartial()
end

function M.getMoney()
	local data = getSave()
	return type(data) == "table" and num(data.Money) or 0, "save.Money"
end

-- Jangan kirim kartu 0. Kalau cache collect penuh ada, pakai itu.
function M.collectSlim()
	if type(M._wireChunks) == "table" then
		local chunked = M.nextChunkAssets()
		if type(chunked) == "table" then
			return chunked
		end
	end
	if type(M._cache) == "table" and type(M._cache.overview) == "table" then
		return M._cache
	end
	if type(M._lastSave) == "table" and type(M._lastSave.overview) == "table" then
		return M._lastSave
	end
	return M.collect()
end

local function nodeHub()
	local nh = G.NodeHubWS or rawget(_G, "NodeHubWS")
	if type(nh) == "table" then
		return nh
	end
	return nil
end

local function fmtLiveNum(n)
	n = tonumber(n) or 0
	local abs = math.abs(n)
	local units = {
		{ 1e15, "Qa" },
		{ 1e12, "T" },
		{ 1e9, "B" },
		{ 1e6, "M" },
		{ 1e3, "k" },
	}
	for _, u in ipairs(units) do
		if abs >= u[1] then
			return string.format("%.1f%s", n / u[1], u[2])
		end
	end
	if abs >= 10 or n == math.floor(n) then
		return string.format("%.0f", n)
	end
	return string.format("%.1f", n)
end

local function fmtLiveKg(n)
	n = tonumber(n) or 0
	if n <= 0 then
		return ""
	end
	if n >= 10 then
		return string.format("%.0f kg", n)
	end
	return string.format("%.1f kg", n)
end

local function liveMutText(muts)
	if type(muts) ~= "table" or #muts == 0 then
		return "Normal"
	end
	local names = {}
	for i, name in ipairs(muts) do
		if type(Core.mutationLabel) == "function" then
			names[i] = Core.mutationLabel(name)
		else
			names[i] = tostring(name)
		end
	end
	return table.concat(names, "+")
end

local function liveLine(info)
	info = type(info) == "table" and info or {}
	local parts = {}
	if type(info.rarity) == "string" and info.rarity ~= "" then
		parts[#parts + 1] = info.rarity
	end
	parts[#parts + 1] = tostring(info.name or info.category or "egg")
	parts[#parts + 1] = liveMutText(info.muts)
	local kg = fmtLiveKg(info.kg)
	if kg ~= "" then
		parts[#parts + 1] = kg
	end
	return table.concat(parts, " · ")
end

function M.notifyLiveSteal(info)
	info = type(info) == "table" and info or {}
	local wild = G.StealEggWild
	if type(wild) == "table" and type(wild.infoMatchesEnabled) == "function" then
		local ok, yes = pcall(wild.infoMatchesEnabled, info)
		if not (ok and yes == true) then
			return false, "rule_mismatch"
		end
	end
	local nh = nodeHub()
	if type(nh) ~= "table" or type(nh.Get) ~= "function" then
		return false, "no_hub"
	end
	local bridge = nh.Get(NS) or nh.Get("steal_egg") or nh.Get("gag2")
	if type(bridge) ~= "table" or type(bridge.SendPacket) ~= "function" then
		return false, "no_bridge"
	end
	if bridge.connected ~= true then
		return false, "not_connected"
	end
	local placeId, gameId = "", ""
	pcall(function()
		placeId = tostring(game.PlaceId or "")
	end)
	pcall(function()
		gameId = tostring(game.GameId or "")
	end)
	local rate = tonumber(info.rate) or 0
	local packet = {
		type = "live_event",
		kind = "steal",
		title = "Steal Egg",
		account_label = tostring((LP and (LP.DisplayName or LP.Name)) or ""),
		akun_username = tostring((LP and LP.Name) or ""),
		line = liveLine(info),
		rate = rate > 0 and (fmtLiveNum(rate) .. "/s") or "",
		area = tostring(info.areaName or ""),
		place_id = placeId,
		game_id = gameId,
	}
	return bridge:SendPacket(packet)
end

local function savePath()
	local ui = G.StealEgg or G.StealEggUI
	if type(ui) == "table" and type(ui.savePath) == "string" and ui.savePath ~= "" then
		return ui.savePath
	end
	local dir = G.__StealEggSaveDir
	if type(dir) ~= "string" or dir == "" then
		dir = "NodeStealEgg"
	end
	local name = tostring((LP and LP.Name) or "player"):gsub("[^%w%-_.]", "_")
	return dir .. "/" .. name .. ".json"
end

local function getConfig()
	local ui = G.StealEgg or G.StealEggUI
	if type(ui) == "table" and type(ui.GetValues) == "function" then
		local ok, values = pcall(function()
			return ui:GetValues()
		end)
		if ok and type(values) == "table" then
			return values
		end
	end
	return {}
end

local function applyConfig(config)
	if type(config) ~= "table" then
		return false, "config_not_table"
	end
	local values = config.main or config.values or config
	if type(values) ~= "table" then
		return false, "values_not_table"
	end
	local ui = G.StealEgg or G.StealEggUI
	if type(ui) == "table" and type(ui.SetValues) == "function" then
		pcall(function()
			ui:SetValues(values, true)
		end)
	end
	local Loaded = G.StealEggLoaded
	if type(Loaded) == "table" then
		for _, key in ipairs({
			"WildEgg", "AutoSell", "Hatch", "Mutation", "IndexComplete", "Gear", "Fuse",
			"AutoHop", "Rejoin", "Webhook", "Move", "Fps", "Esp", "Upgrade",
			"Claim", "Event", "Favorite", "PerfHud",
		}) do
			local mod = Loaded[key]
			if type(mod) == "table" and type(mod.syncFrom) == "function" then
				pcall(mod.syncFrom, values)
			end
		end
	end
	return true
end

function M.opts(extra)
	local uid = tostring((LP and LP.UserId) or "unknown")
	local opts = {
		namespace = NS,
		scriptName = GAME_NAME,
		gameName = GAME_NAME,
		title = "Monitor Account",
		-- LOCAL
		-- wsBaseUrl = "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}",
		-- PRODUCTION (aktif) — dashboard https://nodemonitor.io
		wsBaseUrl = "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}",
		authPassword = "sanken2",
		statsInterval = STATS_SEC,
		assetsInterval = STATS_SEC,
		useServerStatsInterval = false,
		persistTrackState = true,
		sendDefaultConfigOnTrack = false,
		sendDefaultConfigOnChange = false,
		collectAssets = true,
		assetMode = "steal_egg",
		installAutoGiftAction = false,
		autoStartOnBoot = true,
		autoStartDelay = 0.8,
		saveFile = savePath(),
		settingsFile = "nodehub_ws_static/steal_egg_" .. uid .. ".json",
		getAssets = M.collect,
		collectAssetsFn = M.collect,
		getIdentity = function()
			local p = Players.LocalPlayer or LP
			if not p then
				return {}
			end
			return {
				akun_game_id = p.UserId,
				akun_username = p.Name,
				username = p.Name,
			}
		end,
		getMoney = M.getMoney,
		getSheckles = M.getMoney,
		getConfig = getConfig,
		getDefaultConfig = getConfig,
		applyConfig = applyConfig,
	}
	if extra and type(extra) == "table" then
		for k, v in pairs(extra) do
			opts[k] = v
		end
	end
	return opts
end

local function pushDefaults(opts)
	G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS or {}
	G.__NODEHUB_WS_DEFAULTS.wsBaseUrl = opts.wsBaseUrl
	G.__NODEHUB_WS_DEFAULTS.authPassword = opts.authPassword
	G.__NODEHUB_WS_DEFAULTS.namespace = NS
	G.__NODEHUB_WS_DEFAULTS.scriptName = GAME_NAME
	G.__NODEHUB_WS_DEFAULTS.gameName = GAME_NAME
	G.__NODEHUB_WS_DEFAULTS.settingsFile = opts.settingsFile
	_G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS
	G.__NODEHUB_WS_BASE_URL = opts.wsBaseUrl
	_G.__NODEHUB_WS_BASE_URL = opts.wsBaseUrl
	G.__NODEHUB_WS_AUTH_PASSWORD = opts.authPassword
	_G.__NODEHUB_WS_AUTH_PASSWORD = opts.authPassword
	G.__NODEHUB_COLLECT_ASSETS = M.collect
	_G.__NODEHUB_COLLECT_ASSETS = M.collect
	if string.find(tostring(opts.wsBaseUrl or ""), "127.0.0.1", 1, true)
		or string.find(tostring(opts.wsBaseUrl or ""), "localhost", 1, true) then
		G.__NM_RESOLVE_BASE = "http://127.0.0.1:8080"
		_G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE
		G.__NM_RESOLVE_URL = nil
		_G.__NM_RESOLVE_URL = nil
	else
		G.__NM_RESOLVE_BASE = "https://nodemonitor.io"
		_G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE
		G.__NM_RESOLVE_URL = nil
		_G.__NM_RESOLVE_URL = nil
	end
end

local function rebindLiveCollector(opts)
	local nh = nodeHub()
	if type(nh) ~= "table" then
		return
	end
	local seen = {}
	local function patch(bridge)
		if type(bridge) ~= "table" or seen[bridge] then
			return
		end
		seen[bridge] = true
		bridge.getAssets = M.collect
		bridge.collectAssetsFn = M.collect
		bridge.assetMode = "steal_egg"
		bridge.collectAssets = true
		bridge._assetsCache = nil
		bridge._assetsCacheAt = 0
		if type(bridge.UpdateOptions) == "function" then
			pcall(bridge.UpdateOptions, bridge, opts)
		end
	end
	if type(nh.Get) == "function" then
		patch(nh.Get(NS))
		patch(nh.Get("gag2"))
		patch(nh.Get("steal_egg"))
	end
	if type(nh._bridges) == "table" then
		for _, bridge in pairs(nh._bridges) do
			patch(bridge)
		end
	end
end

local function startBridge(nh, ui, opts)
	if type(nh.GAG2) ~= "function" then
		return nil
	end
	local ok, bridge = pcall(nh.GAG2, ui, opts)
	if ok and type(bridge) == "table" then
		M._bound = true
		rebindLiveCollector(opts)
		return bridge
	end
	return nil
end

function M.boot(ui)
	if GEN ~= G.__StealEggMonitorGen then
		return false
	end
	local opts = M.opts()
	pushDefaults(opts)
	rebindLiveCollector(opts)
	if M._bootOn == true then
		return true
	end
	M._bootOn = true
	M.ensurePartialPump()
	task.spawn(function()
		local started = false
		for _ = 1, 40 do
			if GEN ~= G.__StealEggMonitorGen then
				return
			end
			local nh = nodeHub()
			if type(nh) == "table" then
				local nmOn = type(nh.IsNMMonitorEnabled) == "function" and nh.IsNMMonitorEnabled() == true
				if nmOn == true and type(nh.TryNMMonitorBind) == "function" then
					local okCall, okBind = pcall(function()
						return nh.TryNMMonitorBind(opts)
					end)
					if okCall == true and (okBind == true or type(okBind) == "table") then
						started = true
						M._bound = true
						rebindLiveCollector(opts)
						break
					end
				else
					if startBridge(nh, nil, opts) then
						started = true
						break
					end
				end
			end
			task.wait(0.25)
		end
		if started ~= true then
			return
		end
		if type(ui) == "table" then
			pcall(function()
				local nh = nodeHub()
				if type(nh) == "table" then
					startBridge(nh, ui, opts)
				end
			end)
		end
		for _, delaySec in ipairs({ 2, 6 }) do
			task.delay(delaySec, function()
				if GEN ~= G.__StealEggMonitorGen then
					return
				end
				local nh = nodeHub()
				if type(nh) ~= "table" or type(nh.Get) ~= "function" then
					return
				end
				local bridge = nh.Get(NS)
				if type(bridge) ~= "table" then
					return
				end
				if not (bridge.trackEnabled == true or bridge.active == true) then
					return
				end
				if bridge.connected == true then
					return
				end
				if type(bridge.EnsureTracked) == "function" then
					pcall(function()
						bridge:EnsureTracked("stealegg_boot_" .. tostring(delaySec))
					end)
				end
			end)
		end
	end)
	return true
end

function M.attachUi(ui)
	if type(ui) ~= "table" then
		return
	end
	local opts = M.opts()
	pushDefaults(opts)
	rebindLiveCollector(opts)
	local nh = nodeHub()
	if type(nh) ~= "table" then
		return
	end
	startBridge(nh, ui, opts)
end

function M.Register(ui)
	M.boot(ui)
	if type(ui) ~= "table" or type(ui.RegisterSubTab) ~= "function" then
		return
	end
	ui:RegisterSubTab("misc", "monitor", "Monitor", function()
		ui:ClearSubContent()
		M.attachUi(ui)
	end, 3)
end

function M.syncFrom()
end

function M.Stop()
	M._bootOn = false
end

return M
 end,       required = true },
    { key = "MoveDbg",   name = "Debug Gerak",   factory = function() -- Debug Gerak — pelacak tarik-menarik kaki antar fitur.
--
-- Masalah yang dilacak: banyak fitur memakai kaki yang sama (steal, claim,
-- boss, place, index, sell, fuse, belt) tapi tidak semuanya lewat Dispatch.
-- Akibatnya perjalanan satu fitur bisa mati di tengah tanpa jejak. Modul ini
-- memasang bungkus di titik-titik sempitnya lalu mencatat garis waktunya.
--
-- Sengaja TIDAK memakai kait __namecall. Yang dibungkus cuma 7 fungsi di dua
-- tabel modul, dipanggil beberapa kali per detik, jadi ongkosnya tidak terasa.
-- Kait namecall harus memeriksa setiap pemanggilan metode di seluruh game dan
-- itu membuat game berat.

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}

local TAG = "STEALEGG_MOVE_DBG"
local RING = 300
local ORPHAN_SEC = 25
local HUD_TICK = 0.3

-- Cadangan kalau Dispatch versi lama belum membuka tabelnya. Yang dipakai
-- selalu Dispatch.RANK kalau ada, supaya angka di sini tidak pernah melenceng.
local RANK_FALLBACK = {
    claim = 100,
    steal = 90,
    scramble = 90,
    boss = 80,
    place = 50,
    index = 50,
    sell = 40,
    fuse = 40,
    belt = 10,
}

M.enabled = false
M.hud = false
M.verbose = false

M._log = {}
M._n = 0
M._trips = {}
M._serial = 0
M._tally = {}
M._starve = {}
M._armed = false
M._orig = nil
M._depth = 0
M._t0 = os.clock()

local gui, hudLbl, hudLoop, orphanLoop

do
    local prev = G.StealEggMoveDbg
    if type(prev) == "table" and prev ~= M and type(prev.Stop) == "function" then
        pcall(prev.Stop)
    end
    local pg = LP and LP:FindFirstChild("PlayerGui")
    local old = pg and pg:FindFirstChild(TAG)
    if old then
        pcall(old.Destroy, old)
    end
end

local function dispatch()
    local d = G.StealEggDispatch
    return type(d) == "table" and d or nil
end

local function move()
    local mv = G.StealEggMove
    return type(mv) == "table" and mv or nil
end

local function rankTable()
    local d = dispatch()
    local t = d and d.RANK
    return type(t) == "table" and t or RANK_FALLBACK
end

local function rankOf(who)
    return tonumber(rankTable()[tostring(who or "")]) or 0
end

local function ownerNow()
    local d = dispatch()
    if d == nil or type(d.Owner) ~= "function" then
        return nil
    end
    local ok, who = pcall(d.Owner)
    return ok and who or nil
end

-- Umur pegangan: Dispatch mencatat _owner.at tapi tidak pernah memakainya,
-- jadi pegangan yatim tidak punya batas waktu. Di sini dipakai untuk menuduh.
local function holdAge()
    local d = dispatch()
    local o = d and d._owner
    if type(o) ~= "table" then
        return nil
    end
    local at = tonumber(o.at)
    if at == nil then
        return nil
    end
    return os.clock() - at
end

local function rootPos()
    local char = LP and LP.Character
    local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
    return (hrp and hrp:IsA("BasePart")) and hrp.Position or nil
end

local function goalPos(goal)
    if typeof(goal) == "CFrame" then
        return goal.Position
    end
    if typeof(goal) == "Vector3" then
        return goal
    end
    return nil
end

local function distTo(pos)
    local at = rootPos()
    if typeof(at) ~= "Vector3" or typeof(pos) ~= "Vector3" then
        return nil
    end
    return (pos - at).Magnitude
end

local function callSite()
    if type(debug) ~= "table" or type(debug.info) ~= "function" then
        return 0
    end
    -- Naik sampai keluar dari modul ini. Bundle-nya satu berkas, jadi nomor
    -- baris adalah satu-satunya cara membedakan 8 pemanggil Move.Stop.
    for lvl = 3, 6 do
        local ok, ln = pcall(debug.info, lvl, "l")
        if ok and type(ln) == "number" and ln > 0 then
            return ln
        end
    end
    return 0
end

local function modeNow(mv, opts)
    local m = type(opts) == "table" and opts.mode or nil
    if m ~= nil and m ~= "" then
        return tostring(m)
    end
    if mv ~= nil and type(mv.GetMode) == "function" then
        local ok, got = pcall(mv.GetMode)
        if ok and got ~= nil then
            return tostring(got)
        end
    end
    return "-"
end

local function activeTrips()
    local out = {}
    for _, t in pairs(M._trips) do
        out[#out + 1] = t
    end
    table.sort(out, function(a, b)
        return (a.at or 0) < (b.at or 0)
    end)
    return out
end

local function bump(kind)
    M._tally[kind] = (tonumber(M._tally[kind]) or 0) + 1
end

local CONFLICT = {
    REBUT = true,
    DITOLAK = true,
    KELAPARAN = true,
    TUMPANG = true,
    ["TANPA-PEMILIK"] = true,
    DIPOTONG = true,
    YATIM = true,
    ["BUKAN-PEMILIK"] = true,
}

local function push(kind, who, detail)
    M._n += 1
    local rec = {
        i = M._n,
        t = os.clock() - M._t0,
        kind = tostring(kind),
        who = tostring(who or "-"),
        detail = tostring(detail or ""),
    }
    M._log[#M._log + 1] = rec
    if #M._log > RING then
        table.remove(M._log, 1)
    end
    if CONFLICT[rec.kind] then
        bump(rec.kind)
        -- Konflik selalu dicetak: itu inti bug yang sedang dicari.
        print(string.format("[GERAK] %6.2fs %-13s %-6s %s", rec.t, rec.kind, rec.who, rec.detail))
    elseif M.verbose == true then
        print(string.format("[gerak] %6.2fs %-13s %-6s %s", rec.t, rec.kind, rec.who, rec.detail))
    end
    return rec
end

M.push = push

--==========================================================================
-- Bungkus titik sempit
--==========================================================================

local function wrapDispatch(d)
    local o = {}

    o.Hold = d.Hold
    d.Hold = function(who)
        local before = ownerNow()
        local age = holdAge()
        local ok = o.Hold(who)
        who = tostring(who or "")
        if ok == true then
            if before ~= nil and before ~= who then
                push("REBUT", who, string.format(
                    "merebut dari %s (dipegang %.1fs) · rank %d > %d · perjalanan %s dibunuh",
                    tostring(before), age or -1, rankOf(who), rankOf(before), tostring(before)))
            elseif before == nil then
                push("hold", who, string.format("ambil kaki · rank %d", rankOf(who)))
            end
        else
            local sama = rankOf(who) == rankOf(before)
            push("DITOLAK", who, string.format(
                "ditolak · %s masih pegang %.1fs · rank %d %s %d%s",
                tostring(before), age or -1, rankOf(who),
                sama and "==" or "<=", rankOf(before),
                sama and " · rank SAMA tidak bisa merebut" or ""))
        end
        return ok
    end

    o.Release = d.Release
    d.Release = function(who)
        local before = ownerNow()
        local age = holdAge()
        local ok = o.Release(who)
        if ok == true and before ~= nil then
            push("release", tostring(before), string.format("lepas kaki setelah %.1fs", age or -1))
        elseif ok ~= true then
            push("release?", tostring(who), string.format("gagal lepas · pemilik %s", tostring(before)))
            -- Fitur melepas kaki yang bukan miliknya, berulang-ulang. Itu sidik
            -- jari loop yang berputar tanpa kerja: dia keluar lebih awal setiap
            -- putaran, tidak pernah sampai memanggil Hold. Dilaporkan sekali per
            -- 20s per fitur supaya tercatat di rekap, bukan cuma jadi banjir log.
            who = tostring(who or "-")
            local st = M._starve[who]
            if type(st) ~= "table" then
                st = { n = 0, at = 0 }
                M._starve[who] = st
            end
            st.n += 1
            if st.n >= 8 and (os.clock() - st.at) >= 20 then
                st.at = os.clock()
                push("KELAPARAN", who, string.format(
                    "berputar %d kali tanpa pernah Hold · %s pegang %.0fs · rank %d vs %d%s",
                    st.n, tostring(before), age or -1, rankOf(who), rankOf(before),
                    rankOf(who) > rankOf(before)
                        -- Penting: ini BUKAN bukti fitur terhalang. Rank-nya cukup
                        -- untuk merebut, jadi dia berhenti sebelum pintu — bisa
                        -- karena memang tidak ada kerja (misal tidak ada telur
                        -- cocok), bisa karena gerbang lain. Harus dicek terpisah.
                        and " · ranknya cukup merebut, jadi berhenti sebelum pintu: entah tidak ada kerja, entah ada gerbang lain"
                        or " · ranknya memang kalah"))
                st.n = 0
            end
        end
        return ok
    end

    o.GoTo = d.GoTo
    d.GoTo = function(who, dest, opts)
        push("disp.goto", tostring(who), string.format("minta jalan · %s",
            tostring(type(opts) == "table" and opts.reason or "-")))
        return o.GoTo(who, dest, opts)
    end

    o.Stop = d.Stop
    d.Stop = function(who)
        push("disp.stop", tostring(who), "minta berhenti")
        return o.Stop(who)
    end

    return o
end

local function wrapMove(mv)
    local o = {}

    o.GoTo = mv.GoTo
    mv.GoTo = function(goal, opts)
        opts = type(opts) == "table" and opts or {}
        local own = ownerNow()
        local want = opts.owner
        local reason = tostring(opts.reason or "-")
        local dest = goalPos(goal)
        local d0 = distTo(dest)

        M._serial += 1
        local id = M._serial
        local trip = {
            id = id,
            at = os.clock(),
            who = tostring(want or own or "?"),
            declared = want,
            reason = reason,
            mode = modeNow(mv, opts),
            speed = tonumber(opts.speed) or 0,
            dest = dest,
            d0 = d0,
            line = callSite(),
        }

        -- Perjalanan lain masih di udara: dua fitur menggerakkan satu badan.
        local live = activeTrips()
        if #live > 0 then
            local names = {}
            for _, t in ipairs(live) do
                names[#names + 1] = string.format("#%d %s/%s %.1fs", t.id, t.who, t.reason, os.clock() - t.at)
            end
            push("TUMPANG", trip.who, string.format(
                "#%d %s mulai padahal masih jalan: %s", id, reason, table.concat(names, " + ")))
        end

        -- owner nil = Move.GoTo tidak memeriksa pemilik dan Dispatch tidak
        -- menitipkan token shouldRun. Perjalanan ini tanpa pengawal.
        if want == nil then
            push("TANPA-PEMILIK", tostring(own or "nihil"), string.format(
                "#%d %s jalan tanpa opts.owner · tidak ada cek pemilik, tidak ada token · baris %d",
                id, reason, trip.line))
        end

        M._trips[id] = trip
        local ok, why = o.GoTo(goal, opts)
        M._trips[id] = nil

        local dt = os.clock() - trip.at
        local d1 = distTo(dest)
        trip.done = true

        if ok ~= true and tostring(why) == "not_owner" then
            push("BUKAN-PEMILIK", trip.who, string.format(
                "#%d %s ditolak Move · minta=%s pemilik=%s", id, reason, tostring(want), tostring(ownerNow())))
        elseif ok ~= true then
            local cut = trip.cutBy
            push(cut and "DIPOTONG" or "goto.gagal", trip.who, string.format(
                "#%d %s gagal (%s) setelah %.1fs · sisa %s dari %s studs%s",
                id, reason, tostring(why), dt,
                d1 and string.format("%.0f", d1) or "?",
                d0 and string.format("%.0f", d0) or "?",
                cut and (" · dipotong oleh " .. cut) or ""))
        else
            push("goto.ok", trip.who, string.format("#%d %s sampai %.1fs · %s studs",
                id, reason, dt, d0 and string.format("%.0f", d0) or "?"))
        end
        return ok, why
    end

    local function noteStop(label)
        local live = activeTrips()
        local d = dispatch()
        local pre = d and d._preempting == true
        local own = ownerNow()
        local line = callSite()
        if #live == 0 then
            push(label, tostring(own or "-"), string.format(
                "tidak ada perjalanan berjalan · baris %d", line))
            return
        end
        local names = {}
        for _, t in ipairs(live) do
            t.cutBy = string.format("%s(baris %d)", label, line)
            names[#names + 1] = string.format("#%d %s/%s", t.id, t.who, t.reason)
        end
        push("DIPOTONG", tostring(own or "-"), string.format(
            "%s di baris %d membunuh %s%s", label, line, table.concat(names, " + "),
            pre and " · sah: perebutan Dispatch" or " · BUKAN perebutan, panggilan lepas"))
    end

    o.Stop = mv.Stop
    mv.Stop = function(...)
        M._depth += 1
        if M._depth == 1 then
            noteStop("Move.Stop")
        end
        local a, b = o.Stop(...)
        M._depth -= 1
        return a, b
    end

    o.StopRaw = mv.StopRaw
    mv.StopRaw = function(...)
        M._depth += 1
        if M._depth == 1 then
            noteStop("Move.StopRaw")
        end
        local a, b = o.StopRaw(...)
        M._depth -= 1
        return a, b
    end

    return o
end

function M.arm()
    if M._armed == true then
        return true, "sudah"
    end
    local d = dispatch()
    local mv = move()
    if d == nil then
        return false, "Dispatch belum ada"
    end
    if mv == nil then
        return false, "Move belum ada"
    end
    M._orig = {
        d = d,
        mv = mv,
        disp = wrapDispatch(d),
        move = wrapMove(mv),
    }
    M._armed = true
    M._t0 = os.clock()
    push("armed", "-", "pelacak terpasang di Dispatch.Hold/Release/GoTo/Stop + Move.GoTo/Stop/StopRaw")
    return true
end

function M.disarm()
    local s = M._orig
    if M._armed ~= true or type(s) ~= "table" then
        M._armed = false
        return false
    end
    for k, fn in pairs(s.disp) do
        s.d[k] = fn
    end
    for k, fn in pairs(s.move) do
        s.mv[k] = fn
    end
    M._orig = nil
    M._armed = false
    M._trips = {}
    return true
end

--==========================================================================
-- Pembacaan keadaan
--==========================================================================

-- Apa yang sedang dikerjakan skrip saat ini.
function M.now()
    local own = ownerNow()
    local age = holdAge()
    local mv = move()
    local W = G.StealEggWild
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")

    local st = {
        owner = own,
        holdAge = age,
        trips = activeTrips(),
        mode = modeNow(mv, nil),
        speed = mv and tonumber(mv.speed) or nil,
        walkSpeed = hum and tonumber(hum.WalkSpeed) or nil,
        hp = hum and tonumber(hum.Health) or nil,
        onBelt = type(W) == "table" and W._onBelt == true,
        busy = G.__StealEggBusy == true,
        tpHold = G.__StealEggTpHold == true,
        quiet = G.__StealEggMoveQuiet == true,
        conflicts = 0,
    }
    for k, n in pairs(M._tally) do
        if CONFLICT[k] then
            st.conflicts += n
        end
    end
    return st
end

-- Satu baris ringkas: siapa pegang kaki dan sedang jalan ke mana.
function M.line()
    local st = M.now()
    local head
    if st.owner == nil then
        head = "kaki: bebas"
    else
        head = string.format("kaki: %s %.0fs", st.owner, st.holdAge or 0)
    end
    local job = "diam"
    local t = st.trips[1]
    if t ~= nil then
        local sisa = distTo(t.dest)
        job = string.format("%s/%s %s %.0f · sisa %s studs %.0fs",
            t.who, t.reason, t.mode, t.speed,
            sisa and string.format("%.0f", sisa) or "?",
            os.clock() - t.at)
        if #st.trips > 1 then
            job = job .. string.format(" (+%d TUMPANG)", #st.trips - 1)
        end
    end
    local flags = {}
    if st.busy then flags[#flags + 1] = "busy" end
    if st.tpHold then flags[#flags + 1] = "tpHold" end
    if st.quiet then flags[#flags + 1] = "quiet" end
    if st.onBelt then flags[#flags + 1] = "belt" end
    return string.format("%s · %s · ws=%s%s · konflik=%d",
        head, job,
        st.walkSpeed and string.format("%.0f", st.walkSpeed) or "?",
        #flags > 0 and (" · " .. table.concat(flags, ",")) or "",
        st.conflicts)
end

-- Garis waktu kejadian terakhir.
function M.dump(n)
    n = math.clamp(tonumber(n) or 40, 1, RING)
    local total = #M._log
    print("=== GARIS WAKTU GERAK (" .. tostring(math.min(n, total)) .. " dari " .. tostring(total) .. ") ===")
    for i = math.max(1, total - n + 1), total do
        local r = M._log[i]
        print(string.format("%6.2fs %-13s %-6s %s", r.t, r.kind, r.who, r.detail))
    end
    print("--- sekarang: " .. M.line())
    return total
end

-- Rekap tuduhan: jenis konflik apa yang paling sering, dan artinya.
function M.report()
    local ARTI = {
        REBUT = "fitur rank lebih tinggi merebut kaki · sah, tapi perjalanan lama mati",
        DITOLAK = "fitur tidak dapat kaki karena rank kalah atau SAMA · dia menganggur",
        KELAPARAN = "loop berputar tanpa pernah meminta kaki · BELUM tentu bug: cek dulu apakah fiturnya memang punya kerja",
        TUMPANG = "dua Move.GoTo jalan bersamaan di satu badan · saling tarik",
        ["TANPA-PEMILIK"] = "Move.GoTo tanpa opts.owner · lolos cek pemilik, tanpa token, bisa dibunuh siapa saja",
        DIPOTONG = "Move.Stop/StopRaw membunuh perjalanan yang sedang jalan",
        YATIM = "pegangan tidak dilepas padahal tidak ada yang jalan · Dispatch tidak punya batas waktu",
        ["BUKAN-PEMILIK"] = "Move menolak GoTo karena pemilik berubah di tengah",
    }
    local rows = {}
    for k, n in pairs(M._tally) do
        rows[#rows + 1] = { k = k, n = n }
    end
    table.sort(rows, function(a, b)
        return a.n > b.n
    end)
    print("=== REKAP KONFLIK GERAK (" .. string.format("%.0f", os.clock() - M._t0) .. "s) ===")
    if #rows == 0 then
        print("belum ada kejadian tercatat")
    end
    for _, r in ipairs(rows) do
        if CONFLICT[r.k] then
            print(string.format("%-14s %4d  %s", r.k, r.n, ARTI[r.k] or ""))
        end
    end
    print("")
    print("=== PRIORITAS ===")
    local pr = {}
    for who, rank in pairs(rankTable()) do
        pr[#pr + 1] = { who = who, rank = rank }
    end
    table.sort(pr, function(a, b)
        return a.rank > b.rank
    end)
    for _, p in ipairs(pr) do
        local mark = (ownerNow() == p.who) and "  <= pegang kaki" or ""
        print(string.format("%4d  %s%s", p.rank, p.who, mark))
    end
    print("catatan: place==index (50) dan sell==fuse (40) berank SAMA, jadi tidak bisa saling merebut")
    print("")
    print("--- sekarang: " .. M.line())
    return M._tally
end

function M.reset()
    M._log = {}
    M._n = 0
    M._tally = {}
    M._trips = {}
    M._starve = {}
    M._t0 = os.clock()
    return true
end

--==========================================================================
-- Pegangan yatim
--==========================================================================

local function startOrphan()
    if orphanLoop ~= nil then
        return
    end
    orphanLoop = task.spawn(function()
        local warned = nil
        local warnAt = 0
        while M.enabled == true do
            local own = ownerNow()
            local age = holdAge()
            if own ~= nil and age ~= nil and age > ORPHAN_SEC and #activeTrips() == 0 then
                -- Diulang tiap 30s selagi masih nyangkut. Kalau hanya sekali per
                -- pemilik, reset catatan membuat kemacetan yang masih berlangsung
                -- hilang dari rekap dan seolah tidak ada masalah.
                if warned ~= own or (os.clock() - warnAt) >= 30 then
                    warned = own
                    warnAt = os.clock()
                    local lapar = {}
                    for who, rank in pairs(rankTable()) do
                        if who ~= own and rank > rankOf(own) then
                            lapar[#lapar + 1] = who
                        end
                    end
                    push("YATIM", own, string.format(
                        "pegang kaki %.0fs tanpa perjalanan apa pun · yang seharusnya bisa merebut tapi diam: %s",
                        age, #lapar > 0 and table.concat(lapar, ",") or "-"))
                end
            else
                warned = nil
            end
            task.wait(2)
        end
        orphanLoop = nil
    end)
end

--==========================================================================
-- HUD
--==========================================================================

local function destroyHud()
    if hudLoop ~= nil then
        hudLoop = nil
    end
    if gui ~= nil then
        pcall(gui.Destroy, gui)
    end
    gui = nil
    hudLbl = nil
end

local function buildHud()
    destroyHud()
    local pg = LP and (LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui", 5))
    if pg == nil then
        return false
    end
    gui = Instance.new("ScreenGui")
    gui.Name = TAG
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 999
    gui.Parent = pg

    local frame = Instance.new("Frame")
    frame.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
    frame.BackgroundTransparency = 0.25
    frame.Position = UDim2.fromOffset(8, 92)
    frame.Size = UDim2.fromOffset(430, 56)
    frame.Parent = gui
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = frame
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(255, 211, 0)
    stroke.Thickness = 1
    stroke.Transparency = 0.4
    stroke.Parent = frame

    hudLbl = Instance.new("TextLabel")
    hudLbl.BackgroundTransparency = 1
    hudLbl.Size = UDim2.new(1, -12, 1, -8)
    hudLbl.Position = UDim2.fromOffset(6, 4)
    hudLbl.Font = Enum.Font.Code
    hudLbl.TextSize = 11
    hudLbl.TextColor3 = Color3.fromRGB(230, 230, 230)
    hudLbl.TextXAlignment = Enum.TextXAlignment.Left
    hudLbl.TextYAlignment = Enum.TextYAlignment.Top
    hudLbl.TextWrapped = true
    hudLbl.Text = "gerak: menunggu"
    hudLbl.Parent = frame
    return true
end

local function startHud()
    if buildHud() ~= true then
        return false
    end
    hudLoop = task.spawn(function()
        while M.hud == true and M.enabled == true do
            if hudLbl ~= nil then
                local st = M.now()
                local last = M._log[#M._log]
                hudLbl.Text = string.format("%s\nterakhir: %s %s %s",
                    M.line(),
                    last and last.kind or "-",
                    last and last.who or "-",
                    last and string.sub(last.detail, 1, 70) or "")
                if hudLbl ~= nil then
                    hudLbl.TextColor3 = st.conflicts > 0
                        and Color3.fromRGB(255, 170, 90)
                        or Color3.fromRGB(230, 230, 230)
                end
            end
            task.wait(HUD_TICK)
        end
        destroyHud()
    end)
    return true
end

--==========================================================================
-- Daur hidup
--==========================================================================

function M.setEnabled(on)
    on = on == true
    if on == M.enabled then
        return M.enabled
    end
    M.enabled = on
    if on then
        local ok, why = M.arm()
        if ok ~= true then
            M.enabled = false
            print("[GERAK] gagal pasang pelacak: " .. tostring(why))
            return false
        end
        startOrphan()
        if M.hud == true then
            startHud()
        end
        print("[GERAK] pelacak ON · konflik dicetak otomatis. MoveDbg.dump() garis waktu, MoveDbg.report() rekap.")
    else
        M.disarm()
        destroyHud()
        print("[GERAK] pelacak OFF")
    end
    return M.enabled
end

function M.setHud(on)
    M.hud = on == true
    if M.hud and M.enabled then
        startHud()
    elseif not M.hud then
        destroyHud()
    end
    return M.hud
end

function M.Stop()
    M.enabled = false
    M.hud = false
    M.disarm()
    destroyHud()
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local Core = G.StealEggCore
    local function flag(key)
        local v = values[key]
        if v == nil then
            return nil
        end
        if type(Core) == "table" and type(Core.flagOn) == "function" then
            return Core.flagOn(v)
        end
        return v == true
    end
    local h = flag("misc.gerak.hud")
    if h ~= nil then
        M.hud = h
    end
    local vb = flag("misc.gerak.verbose")
    if vb ~= nil then
        M.verbose = vb
    end
    local en = flag("misc.gerak.enabled")
    if en ~= nil then
        M.setEnabled(en)
    end
end

function M.Register(ui)
    M.syncFrom(ui:GetValues() or {})

    local body, _, statusApi = ui:CreateSection({
        title = "Debug Gerak",
        expanded = false,
        status = {
            id = "misc.gerak.status",
            persist = false,
            value = "Idle",
            style = "muted",
        },
    })
    local group = ui:CreateGroup(body)

    local _, lbl = ui:CreateRowLabel(group, M.line(), nil, nil, "info")

    ui:CreateRowButton(group, {
        text = "Status sekarang",
        onClick = function()
            local txt = M.line()
            if lbl then
                lbl.Text = txt
            end
            print("[GERAK] " .. txt)
            if statusApi then
                pcall(statusApi.set, M.enabled and "On" or "Off")
                pcall(statusApi.setDetail, txt)
            end
        end,
    })
    ui:CreateRowButton(group, {
        text = "Garis waktu (40 kejadian)",
        onClick = function()
            M.dump(40)
            if lbl then
                lbl.Text = M.line()
            end
        end,
    })
    ui:CreateRowButton(group, {
        text = "Rekap konflik + prioritas",
        onClick = function()
            M.report()
        end,
    })
    ui:CreateRowButton(group, {
        text = "Reset catatan",
        onClick = function()
            M.reset()
            print("[GERAK] catatan dikosongkan")
        end,
    })

    ui:CreateRowToggle(group, {
        id = "misc.gerak.hud",
        label = "Tempel HUD di layar",
        persist = true,
        initial = M.hud == true,
        hintText = "Dua baris di kiri atas: siapa pegang kaki, sedang jalan ke mana, dan kejadian terakhir.",
        onChanged = function(on)
            M.setHud(on)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "misc.gerak.verbose",
        label = "Cetak semua kejadian",
        persist = true,
        initial = M.verbose == true,
        hintText = "Mati = hanya konflik yang dicetak. Nyala = setiap hold, release, dan perjalanan ikut tercetak (ramai).",
        onChanged = function(on)
            M.verbose = on == true
        end,
    })
    ui:CreateRowToggle(group, {
        id = "misc.gerak.enabled",
        label = "Enable Debug Gerak",
        persist = true,
        initial = M.enabled == true,
        hintText = "Memasang pelacak di Dispatch dan Move. Tidak memakai kait namecall, jadi tidak membebani game.",
        onChanged = function(on)
            M.setEnabled(on)
            if statusApi then
                pcall(statusApi.set, on and "On" or "Off")
                pcall(statusApi.setStyle, on and "live" or "muted")
            end
            if lbl then
                lbl.Text = M.line()
            end
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

G.StealEggMoveDbg = M

return M
