function F.tryRequire(rel)
    local node = ReplicatedStorage
    for part in string.gmatch(rel, "[^%.]+") do
        node = node:FindFirstChild(part)
        if not node then
            return nil
        end
    end
    local ok, mod = pcall(require, node)
    if ok and type(mod) == "table" then
        return mod
    end
    return nil
end

function F.settingsCmds()
    return F.tryRequire("Shared.SettingsCmds") or F.tryRequire("Library.Client.SettingsCmds")
end

function F.findModule(name)
    local best, bestScore = nil, 0
    local function consider(inst)
        if not inst or inst.Name ~= name then
            return
        end
        if not inst:IsA("ModuleScript") then
            return
        end
        local rok, mod = pcall(require, inst)
        if not rok or type(mod) ~= "table" then
            return
        end
        local full = inst:GetFullName()
        local score = 2
        if string.find(full, "PlayerScripts", 1, true) then
            score = 3
        elseif string.find(full, "StarterPlayer", 1, true) then
            score = 1
        end
        if score > bestScore then
            best = mod
            bestScore = score
        end
    end
    local ps = LP and LP:FindFirstChild("PlayerScripts")
    if ps then
        for _, inst in ipairs(ps:GetDescendants()) do
            consider(inst)
        end
    end
    if bestScore >= 3 then
        return best
    end
    local ok, list = pcall(getloadedmodules)
    if ok and type(list) == "table" then
        for i = 1, #list do
            consider(list[i])
        end
    end
    return best
end

function F.isGround(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    if d:IsA("Terrain") then
        return true
    end
    local p = d
    for _ = 1, 16 do
        if not p or p == Workspace then
            break
        end
        if p:IsA("Terrain") or p.Name == "Terrain" or p.Name == "Ground" then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.isTrap(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 12 do
        if not p then
            break
        end
        local ok, tagged = pcall(function()
            return p:HasTag("PlacedTrap")
        end)
        if ok and tagged == true then
            return true
        end
        if p:GetAttribute("TrapActive") ~= nil then
            return true
        end
        if string.find(tostring(p.Name), "Trap", 1, true) then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.isClaim(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 12 do
        if not p then
            break
        end
        local n = p.Name
        if n == "LocalOfflineGeneratedMoneyPiles"
            or n == "LocalOfflineMoneyClaim"
            or n == "OfflineMoneyClaimArea"
            or n == "OfflineMoneyClaimBillboard"
        then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.refreshFieldUids()
    local now = os.clock()
    if now - (bag.fieldUidAt or 0) < 1.5 then
        return
    end
    bag.fieldUidAt = now
    table.clear(bag.fieldUid)
    local es = F.tryRequire("Client.EggState")
    if type(es) ~= "table" or type(es.ReadFieldEggs) ~= "function" then
        return
    end
    local ok, rows = pcall(es.ReadFieldEggs)
    if not ok or type(rows) ~= "table" then
        return
    end
    for i = 1, #rows do
        local rec = rows[i]
        if type(rec) == "table" and type(rec.Uid) == "string" then
            bag.fieldUid[rec.Uid] = true
        end
    end
end

function F.isAreaEggModel(model)
    if typeof(model) ~= "Instance" or not model:IsA("Model") then
        return false
    end
    local cached = bag.areaEggCache[model]
    if cached ~= nil then
        return cached
    end
    local ok = false
    local par = model.Parent
    if par and par.Name == "AreaEggSlotsClient" then
        ok = true
    elseif par == Workspace then
        if model:FindFirstChildOfClass("Humanoid") then
            ok = false
        elseif LP and model.Name == LP.Name then
            ok = false
        elseif model:FindFirstChild("CarryAreaEgg", true) then
            ok = true
        else
            F.refreshFieldUids()
            ok = bag.fieldUid[model.Name] == true or string.sub(model.Name, 1, 13) == "FirstAreaEgg_"
        end
    end
    bag.areaEggCache[model] = ok
    return ok
end

function F.localPlotFolder()
    local now = os.clock()
    if bag.localPlot and bag.localPlot.Parent and now - (bag.localPlotAt or 0) < 2 then
        return bag.localPlot
    end
    bag.localPlotAt = now
    bag.localPlot = nil
    -- Utama: PlotState / PlotCmds (stabil). Jangan andalkan YourBase saja —
    -- strip Billboard bisa bikin deteksi plot salah.
    local plotState = F.tryRequire("Client.PlotState")
    if type(plotState) == "table" then
        if type(plotState.ResolvePlot) == "function" then
            local ok, data = pcall(plotState.ResolvePlot, LP)
            if ok and type(data) == "table" and typeof(data.PlotFolder) == "Instance" then
                bag.localPlot = data.PlotFolder
                return bag.localPlot
            end
            if ok and typeof(data) == "Instance" then
                bag.localPlot = data
                return bag.localPlot
            end
        end
        if type(plotState.GetPlotData) == "function" then
            local ok, data = pcall(plotState.GetPlotData)
            if ok and type(data) == "table" and typeof(data.PlotFolder) == "Instance" then
                bag.localPlot = data.PlotFolder
                return bag.localPlot
            end
        end
    end
    local cmds = F.tryRequire("Library.Client.PlotCmds") or F.tryRequire("Shared.Client.PlotCmds")
    if type(cmds) == "table" then
        local fn = cmds.GetPlotData or cmds.ResolvePlot
        if type(fn) == "function" then
            local ok, data = pcall(fn)
            if ok and type(data) == "table" and typeof(data.PlotFolder) == "Instance" then
                bag.localPlot = data.PlotFolder
                return bag.localPlot
            end
        end
    end
    local plots = Workspace:FindFirstChild("Plots")
    if not plots then
        return nil
    end
    for _, folder in ipairs(plots:GetChildren()) do
        local sign = folder:FindFirstChild("PlotSign")
        local att = sign and sign:FindFirstChild("Attachment")
        local gui = att and att:FindFirstChild("YourBase")
        if gui and gui:IsA("BillboardGui") then
            bag.localPlot = folder
            return folder
        end
    end
    return nil
end

-- Bagian plot yang game + Place/Hatch butuh. JANGAN di-Destroy Boost FPS.
function F.isPlotStructure(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 16 do
        if not p or p == Workspace then
            break
        end
        local n = tostring(p.Name or "")
        local low = string.lower(n)
        if n == "PlotSign"
            or n == "YourBase"
            or n == "PetArea"
            or n == "CenterPoint"
            or n == "SpawnPoint"
            or n == "ToUpdate"
            or n == "DeliveryHitbox"
            or n == "ClaimHitbox"
            or string.find(low, "petarea", 1, true)
            or string.find(low, "yourbase", 1, true)
            or string.find(low, "spawn", 1, true)
            or string.find(low, "center", 1, true)
        then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.ownerIdOf(d)
    if typeof(d) ~= "Instance" then
        return nil
    end
    local p = d
    for _ = 1, 16 do
        if not p then
            break
        end
        local a = p:GetAttribute("OwnerUserId")
        if type(a) == "number" then
            return a
        end
        local n = tonumber(string.match(tostring(p.Name), "^(%d+)[:_]"))
        if n then
            return n
        end
        p = p.Parent
    end
    return nil
end

function F.worldPosOf(d)
    if typeof(d) ~= "Instance" then
        return nil
    end
    if d:IsA("Model") then
        local ok, pv = pcall(function()
            return d:GetPivot().Position
        end)
        if ok then
            return pv
        end
    end
    if d:IsA("BasePart") then
        return d.Position
    end
    local p = d:FindFirstChildWhichIsA("BasePart", true)
    return p and p.Position
end

-- Tanpa OwnerUserId: jangan Destroy telur yang masih di PetArea plot sendiri.
function F.onLocalPet(d)
    local mine = F.localPlotFolder()
    if typeof(mine) ~= "Instance" then
        return false
    end
    local pos = F.worldPosOf(d)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local pet = bag.localPet
    if typeof(pet) ~= "Instance" or not pet:IsDescendantOf(mine) then
        pet = mine:FindFirstChild("PetArea", true)
        bag.localPet = pet
    end
    if typeof(pet) ~= "Instance" or not pet:IsA("BasePart") then
        return false
    end
    local lp = pet.CFrame:PointToObjectSpace(pos)
    local h = pet.Size * 0.5
    return math.abs(lp.X) <= (h.X + 4) and math.abs(lp.Z) <= (h.Z + 4)
end

function F.isMine(d)
    -- PetArea plot sendiri = milik kita, meskipun OwnerUserId kosong (FPS pernah hide).
    if F.onLocalPet(d) then
        return true
    end
    local id = F.ownerIdOf(d)
    return type(id) == "number" and id == LP.UserId
end

function F.isPlacedEggTree(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 16 do
        if not p then
            break
        end
        if p.Name == "PlacedEggRenders" then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.isEgg(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 20 do
        if not p then
            break
        end
        if p.Name == "AreaEggSlotsClient" or p.Name == "StartArea" then
            return true
        end
        if p.Name == "PlacedEggRenders" then
            return F.isMine(d)
        end
        if p:IsA("Model") and F.isAreaEggModel(p) then
            return true
        end
        local nm = tostring(p.Name or "")
        if string.sub(nm, 1, 13) == "FirstAreaEgg_" or string.find(nm, "AreaEgg", 1, true) then
            return true
        end
        p = p.Parent
    end
    return false
end

-- Bagian world yang Instant/steal butuh: jangan di-Destroy Boost FPS.
function F.isStealCritical(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    local p = d
    for _ = 1, 24 do
        if not p then
            break
        end
        local n = p.Name
        if n == "GuardAreas"
            or n == "Forest"
            or n == "Guard"
            or n == "AreaEggSlotsClient"
            or n == "StartArea"
            or n == "DeliveryHitbox"
            or n == "InvisibleRenderSpace"
            or n == "SecretZones"
            or n == "Teleporter"
            or n == "DrScrambleEvent"
            or n == "SecretZonePrompt"
            or n == "SecretZoneInteraction"
        then
            return true
        end
        if type(n) == "string" then
            if string.sub(n, 1, 13) == "FirstAreaEgg_" then
                return true
            end
            if string.find(n, "ProximityPrompt", 1, true) then
                return true
            end
            if string.find(n, "SecretZone", 1, true) then
                return true
            end
        end
        if p:IsA("ProximityPrompt") then
            return true
        end
        p = p.Parent
    end
    return false
end

function F.isOtherGarden(d)
    if typeof(d) ~= "Instance" then
        return false
    end
    if F.isEgg(d) and not F.isPlacedEggTree(d) then
        return false
    end
    if F.isGround(d) or F.isTrap(d) or F.isClaim(d) then
        return false
    end
    local id = F.ownerIdOf(d)
    if type(id) == "number" then
        if id == 0 then
            return false
        end
        return id ~= LP.UserId
    end
    local mine = F.localPlotFolder()
    if not mine then
        return false
    end
    local plots = Workspace:FindFirstChild("Plots")
    local p = d
    for _ = 1, 16 do
        if not p or p == Workspace then
            break
        end
        if plots and p.Parent == plots then
            return p ~= mine
        end
        p = p.Parent
    end
    return false
end

function F.protected(d)
    return F.isGround(d)
        or F.isEgg(d)
        or F.isTrap(d)
        or F.isClaim(d)
        or F.isStealCritical(d)
        or F.isPlotStructure(d)
end

function F.kill(d)
    if typeof(d) ~= "Instance" or F.protected(d) then
        return
    end
    pcall(function()
        d:Destroy()
    end)
end

function F.killFx(d)
    if typeof(d) ~= "Instance" or not FX[d.ClassName] then
        return
    end
    if F.protected(d) then
        return
    end
    F.kill(d)
end

function F.makeStub(ownerUserId, uid, parent)
    local model = Instance.new("Model")
    model.Name = tostring(ownerUserId or 0) .. "_" .. tostring(uid or "")
    local root = Instance.new("Part")
    root.Name = "HumanoidRootPart"
    root.Size = Vector3.new(0.05, 0.05, 0.05)
    root.Transparency = 1
    root.Anchored = true
    root.CanCollide = false
    root.CanQuery = false
    root.CanTouch = false
    root.CastShadow = false
    root.Massless = true
    root.Parent = model
    model.PrimaryPart = root
    local center = Instance.new("Part")
    center.Name = "CENTER"
    center.Size = root.Size
    center.Transparency = 1
    center.Anchored = false
    center.CanCollide = false
    center.Massless = true
    center.Parent = model
    local weld = Instance.new("WeldConstraint")
    weld.Part0 = root
    weld.Part1 = center
    weld.Parent = center
    local ac = Instance.new("AnimationController")
    ac.Parent = model
    Instance.new("Animator").Parent = ac
    model:SetAttribute("UID", tostring(uid or ""))
    model:SetAttribute("OwnerUserId", tonumber(ownerUserId) or 0)
    if parent then
        model.Parent = parent
    end
    return model
end

function F.dummyComponent(record, owner, _pen, folder, _billboards, _movement, cf)
    record = type(record) == "table" and record or {}
    local oid = record.OwnerUserId
    if not oid and typeof(owner) == "Instance" then
        oid = owner.UserId
    end
    local model = F.makeStub(oid, record.UID, folder)
    if typeof(cf) == "CFrame" then
        pcall(function()
            model:PivotTo(cf)
        end)
    end
    -- Dideklarasikan dulu, baru diisi. Ditulis sebagai `local comp = {...}`,
    -- closure di dalam konstruktor tabelnya menangkap comp GLOBAL yang nil,
    -- sebab local-nya baru ada setelah pernyataan selesai. Akibatnya nyata di
    -- klien hidup: SetRuntimeRecord meledak "attempt to index nil with
    -- '_record'" setiap kali ActiveAssetsController merekonsiliasi plot.
    local comp
    comp = {
        Model = model,
        Record = record,
        _model = model,
        _record = record,
        GetModel = function()
            return model
        end,
        GetOwnerUserId = function()
            return tonumber(record.OwnerUserId) or tonumber(oid) or 0
        end,
        GetUid = function()
            return tostring(record.UID or "")
        end,
        GetRuntimeRecord = function()
            return record
        end,
        IsHidden = function()
            return true
        end,
        SetHidden = function()
        end,
        SetRuntimeRecord = function(_, rec)
            if type(rec) == "table" then
                record = rec
                comp._record = rec
                comp.Record = rec
            end
        end,
        SetAssetArea = function()
        end,
        Destroy = function()
            pcall(function()
                model:Destroy()
            end)
        end,
        _step = F.noop,
    }
    return setmetatable(comp, {
        __index = function()
            return F.noop
        end,
    })
end

function F.setGardenHook(on)
    local mod = F.findModule("AssetComponent")
    if type(mod) ~= "table" or type(mod.new) ~= "function" then
        return false
    end
    if on then
        if not mod.__StealEggLite then
            G.__StealEggLiteOrigNew = G.__StealEggLiteOrigNew or mod.new
            mod.__StealEggLite = true
            local orig = G.__StealEggLiteOrigNew
            mod.new = function(record, owner, pen, folder, billboards, movement, cf)
                if G.__StealEggLiteOn then
                    return F.dummyComponent(record, owner, pen, folder, billboards, movement, cf)
                end
                return orig(record, owner, pen, folder, billboards, movement, cf)
            end
        end
        return true
    end
    if mod.__StealEggLite and type(G.__StealEggLiteOrigNew) == "function" then
        mod.new = G.__StealEggLiteOrigNew
        mod.__StealEggLite = nil
    end
    return true
end

function F.hookItemDisplay(on)
    local targets = {
        { rel = "Shared.Modules.ItemDisplay", key = "CreateWanderingAssetModel" },
        { rel = "Library.Modules.ItemDisplay", key = "CreateWanderingAssetModel" },
        { rel = "Shared.Modules.AssetRigFactory", key = "BuildWandering" },
    }
    for i = 1, #targets do
        local spec = targets[i]
        local mod = F.tryRequire(spec.rel) or F.findModule((string.match(spec.rel, "[^%.]+$")))
        if type(mod) == "table" and type(mod[spec.key]) == "function" then
            if on then
                if not mod.__StealEggLite then
                    bag.origBuild[spec.rel] = bag.origBuild[spec.rel] or mod[spec.key]
                    mod.__StealEggLite = true
                    local orig = bag.origBuild[spec.rel]
                    mod[spec.key] = function(ownerUserId, uid, itemData, parent)
                        if G.__StealEggLiteOn then
                            return F.makeStub(ownerUserId, uid, parent)
                        end
                        return orig(ownerUserId, uid, itemData, parent)
                    end
                end
            elseif mod.__StealEggLite and type(bag.origBuild[spec.rel]) == "function" then
                mod[spec.key] = bag.origBuild[spec.rel]
                mod.__StealEggLite = nil
            end
        end
    end
end

function F.patchMethod(mod, key, stub)
    if type(mod) ~= "table" or type(mod[key]) ~= "function" then
        return false
    end
    local id = tostring(mod) .. "." .. key
    if bag.patched[id] then
        return true
    end
    bag.patched[id] = true
    -- hookfunction pada method game = BAC-8511. Cukup ganti isi tabel.
    mod[key] = stub
    return true
end

function F.noop()
end

function F.mutePreRender()
end

function F.patchCpu()
    local move = F.findModule("AssetMovementBatch")
    F.patchMethod(move, "_step", F.noop)
    F.patchMethod(move, "_flush", F.noop)
    local bulk = F.tryRequire("Client.BulkPartMotion") or F.findModule("BulkPartMotion")
    F.patchMethod(bulk, "Commit", F.noop)
    local occ = F.tryRequire("Client.ModelCameraOcclusion") or F.findModule("ModelCameraOcclusion")
    if type(occ) == "table" and type(occ.SetEnabled) == "function" then
        pcall(occ.SetEnabled, false)
    end
    -- Jangan Disable semua PreRender: UGI/Playback mati → hop 60s.
end

function F.setPetsHidden(on)
    local ctrl = F.findModule("ActiveAssetsController")
    if type(ctrl) == "table" and type(ctrl.SetAllPetsHidden) == "function" then
        pcall(ctrl.SetAllPetsHidden, on == true)
    end
end

function F.hookCreators()
end

function F.stripPart(d)
    if typeof(d) ~= "Instance" or not d:IsA("BasePart") or F.protected(d) then
        return
    end
    pcall(function()
        d.CastShadow = false
    end)
end

function F.queueWorkspaceFx()
    if bag.sweepOn == true then
        return
    end
    bag.sweepOn = true
    task.spawn(function()
        for i = 1, #SWEEP_FOLDERS do
            if G.__StealEggLiteOn ~= true then
                bag.sweepOn = nil
                return
            end
            local folder = Workspace:FindFirstChild(SWEEP_FOLDERS[i])
            if folder then
                local desc = folder:GetDescendants()
                for j = 1, #desc do
                    if G.__StealEggLiteOn ~= true then
                        bag.sweepOn = nil
                        return
                    end
                    local d = desc[j]
                    if FX[d.ClassName] then
                        F.killFx(d)
                    else
                        F.stripPart(d)
                    end
                    if j % 80 == 0 then
                        task.wait()
                    end
                end
            end
            task.wait()
        end
        bag.sweepOn = nil
    end)
end

function F.stopBones()
    local ps = LP and LP:FindFirstChild("PlayerScripts")
    local folder = ps and ps:FindFirstChild("SmartBone-Actors")
    if folder then
        local kids = folder:GetChildren()
        for i = 1, #kids do
            pcall(function()
                kids[i]:SendMessage("Destroy")
            end)
            F.kill(kids[i])
        end
    end
    local debugFolder = Workspace:FindFirstChild("SMARTBONE_DEBUGFOLDER")
    if debugFolder then
        F.kill(debugFolder)
    end
    for i = 1, #TAGS do
        local ok, list = pcall(function()
            return CollectionService:GetTagged(TAGS[i])
        end)
        if ok and type(list) == "table" then
            for j = 1, #list do
                local inst = list[j]
                if TAGS[i] == "RainbowPart" then
                    pcall(function()
                        CollectionService:RemoveTag(inst, TAGS[i])
                    end)
                elseif not F.protected(inst) then
                    F.kill(inst)
                end
            end
        end
    end
end

function F.stripPets(folder)
    if typeof(folder) ~= "Instance" then
        return
    end
    local kids = folder:GetChildren()
    for i = 1, #kids do
        local m = kids[i]
        if m:IsA("Model") and not F.protected(m) then
            F.enqueueKill(m)
        else
            F.killFx(m)
        end
    end
end

function F.placedEggRenderer()
    return F.tryRequire("Shared.Eggs.PlacedEggRenderer") or F.findModule("PlacedEggRenderer")
end

function F.eggRenderer()
    return F.tryRequire("Shared.Eggs.EggRenderer") or F.findModule("EggRenderer")
end

function F.ownerIdFromArgs(a, b)
    if type(a) == "number" then
        return a
    end
    if typeof(a) == "Instance" and a:IsA("Player") then
        return a.UserId
    end
    if type(a) == "table" then
        if type(a.OwnerUserId) == "number" then
            return a.OwnerUserId
        end
        if type(a.UserId) == "number" then
            return a.UserId
        end
    end
    if type(b) == "number" then
        return b
    end
    return nil
end

function F.wrapFire(signal, kind)
    if type(signal) ~= "table" or type(signal.Fire) ~= "function" then
        return false
    end
    if type(signal.__StealEggLiteFire) == "function" then
        return true
    end
    local orig = signal.Fire
    signal.__StealEggLiteFire = orig
    signal.Fire = function(self, a, b, ...)
        if G.__StealEggLiteOn == true and kind == "skip-other" then
            local id = F.ownerIdFromArgs(a, b)
            if type(id) == "number" and id ~= 0 and id ~= LP.UserId then
                return
            end
        end
        local r = orig(self, a, b, ...)
        if G.__StealEggLiteOn == true then
            if kind == "nuke-eggs" then
                F.nukeForeignEggs()
            elseif kind == "nuke-pets" then
                F.nukeForeignPets()
            end
        end
        return r
    end
    return true
end

function F.unwrapFire(signal)
    if type(signal) == "table" and type(signal.__StealEggLiteFire) == "function" then
        signal.Fire = signal.__StealEggLiteFire
        signal.__StealEggLiteFire = nil
    end
end

function F.hookEggVisual(on)
    local mod = F.eggRenderer()
    if type(mod) ~= "table" or type(mod.RenderVisual) ~= "function" then
        return false
    end
    if on then
        if not mod.__StealEggLite then
            bag.origRenderVisual = bag.origRenderVisual or mod.RenderVisual
            mod.__StealEggLite = true
            local orig = bag.origRenderVisual
            mod.RenderVisual = function(info, folder, collide)
                local oid = type(info) == "table" and tonumber(info.OwnerUserId)
                if G.__StealEggLiteOn and oid and oid ~= 0 and oid ~= LP.UserId then
                    local model = F.makeStub(oid, info.UID or info.Uid)
                    model.Parent = nil
                    return { Model = model }
                end
                return orig(info, folder, collide)
            end
        end
        return true
    end
    if mod.__StealEggLite and type(bag.origRenderVisual) == "function" then
        mod.RenderVisual = bag.origRenderVisual
        mod.__StealEggLite = nil
    end
    return true
end

function F.playerCount()
    local n = 0
    pcall(function()
        n = #Players:GetPlayers()
    end)
    return n
end

-- ≥3 player = tekanan tinggi: destroy langsung, jangan antri pelan.
function F.crowdHot()
    return F.playerCount() >= 3
end

function F.destroyForeignOwners(mod)
    if type(mod) ~= "table" or type(mod.DestroyOwner) ~= "function" then
        return
    end
    local list = Players:GetPlayers()
    for i = 1, #list do
        local plr = list[i]
        if plr ~= LP then
            pcall(mod.DestroyOwner, plr.UserId)
        end
    end
end

function F.nukeForeignEggs()
    F.destroyForeignOwners(F.placedEggRenderer())
    F.destroyForeignOwners(F.tryRequire("Shared.Eggs.PlacedEggBillboard") or F.findModule("PlacedEggBillboard"))
    local folder = Workspace:FindFirstChild("PlacedEggRenders")
    if folder then
        local kids = folder:GetChildren()
        for i = 1, #kids do
            local kid = kids[i]
            if not F.isMine(kid) then
                F.enqueueKill(kid)
            end
        end
    end
end

function F.nukeForeignPets()
    for i = 1, #PET_FOLDERS do
        local folder = Workspace:FindFirstChild(PET_FOLDERS[i])
        if folder then
            F.stripPets(folder)
        end
    end
end

-- Plot orang lain: HANYA bunuh FX. Jangan Destroy BasePart / Billboard / PetArea —
-- itu bikin deteksi plot salah (YourBase hilang) + Place/Hatch ke plot rusak.
function F.stripForeignPlots()
    local plots = Workspace:FindFirstChild("Plots")
    if not plots then
        return
    end
    local mine = F.localPlotFolder()
    -- Tanpa plot sendiri yang jelas: JANGAN strip apa pun (salah plot = hancurkan semua).
    if typeof(mine) ~= "Instance" then
        return
    end
    for _, folder in ipairs(plots:GetChildren()) do
        if folder ~= mine then
            F.queuePurge(folder, "plot")
        end
    end
end

function F.gateGardenCpu()
    local eggState = F.tryRequire("Client.EggState")
    local roster = F.tryRequire("Client.AssetRoster")
    local plotState = F.tryRequire("Client.PlotState")
    if type(eggState) == "table" then
        F.wrapFire(eggState.OwnerRefreshed, "skip-other")
        F.wrapFire(eggState.SnapshotRefreshed, "nuke-eggs")
    end
    if type(roster) == "table" then
        F.wrapFire(roster.OwnerRefreshed, "skip-other")
        F.wrapFire(roster.SnapshotRefreshed, "nuke-pets")
        F.wrapFire(roster.PenAreaChanged, "skip-other")
    end
    if type(plotState) == "table" then
        F.wrapFire(plotState.PlotChanged, "nuke-eggs")
    end
    local renderer = F.placedEggRenderer()
    if type(renderer) == "table" and type(renderer.Refresh) == "function" and type(renderer.__StealEggLiteRefresh) ~= "function" then
        local orig = renderer.Refresh
        renderer.__StealEggLiteRefresh = orig
        renderer.Refresh = function(...)
            local r = orig(...)
            if G.__StealEggLiteOn then
                F.nukeForeignEggs()
            end
            return r
        end
    end
    F.nukeForeignEggs()
    F.nukeForeignPets()
end

function F.ungateGardenCpu()
    local eggState = F.tryRequire("Client.EggState")
    local roster = F.tryRequire("Client.AssetRoster")
    local plotState = F.tryRequire("Client.PlotState")
    if type(eggState) == "table" then
        F.unwrapFire(eggState.OwnerRefreshed)
        F.unwrapFire(eggState.SnapshotRefreshed)
    end
    if type(roster) == "table" then
        F.unwrapFire(roster.OwnerRefreshed)
        F.unwrapFire(roster.SnapshotRefreshed)
        F.unwrapFire(roster.PenAreaChanged)
    end
    if type(plotState) == "table" then
        F.unwrapFire(plotState.PlotChanged)
    end
    pcall(F.hookEggVisual, false)
    local renderer = F.placedEggRenderer()
    if type(renderer) == "table" and type(renderer.__StealEggLiteRefresh) == "function" then
        renderer.Refresh = renderer.__StealEggLiteRefresh
        renderer.__StealEggLiteRefresh = nil
    end
end

function F.enqueueKill(inst)
    if typeof(inst) ~= "Instance" or F.protected(inst) then
        return
    end
    bag.heavyQueue[#bag.heavyQueue + 1] = inst
end

-- Sapu pohon besar per frame. GetDescendants sekaligus = spike 200–500ms di HP.
function F.queuePurge(inst, mode)
    if typeof(inst) ~= "Instance" then
        return
    end
    if mode ~= "char" and F.isStealCritical(inst) then
        return
    end
    bag.purge = bag.purge or {}
    bag.purge[#bag.purge + 1] = { inst = inst, mode = mode or "decor" }
end

function F.notePurge(d, mode)
    if typeof(d) ~= "Instance" then
        return false
    end
    if mode == "char" then
        if d.Name == "HumanoidRootPart" then
            return true
        end
        if FX[d.ClassName]
            or d:IsA("Accessory")
            or d:IsA("Shirt")
            or d:IsA("Pants")
            or d:IsA("ShirtGraphic")
            or d:IsA("CharacterMesh")
            or d:IsA("BodyColors")
            or d:IsA("Decal")
            or d:IsA("Texture")
            or d:IsA("BillboardGui")
            or d:IsA("SurfaceGui")
            or d:IsA("SpecialMesh")
            or (d:IsA("BasePart") and d.Name ~= "HumanoidRootPart")
            or d:IsA("MeshPart")
        then
            F.enqueueKill(d)
            return false
        end
        return true
    end
    if F.protected(d) or F.isStealCritical(d) then
        return false
    end
    if mode == "plot" then
        local junk = d.ClassName == "Pose" or d.ClassName == "Keyframe"
            or d.ClassName == "KeyframeSequence" or d.ClassName == "Bone"
        if junk or FX[d.ClassName] then
            F.enqueueKill(d)
            return false
        end
        if d:IsA("Decal") or d:IsA("Texture") then
            pcall(function()
                d.Transparency = 1
            end)
            return true
        end
        if d:IsA("BasePart") then
            pcall(function()
                d.CastShadow = false
            end)
        end
        return true
    end
    local junk = d.ClassName == "Pose" or d.ClassName == "Keyframe"
        or d.ClassName == "KeyframeSequence" or d.ClassName == "Bone"
    if junk or FX[d.ClassName] then
        F.enqueueKill(d)
        return false
    end
    if d:IsA("BasePart") then
        if d.CanCollide == true then
            pcall(function()
                d.CastShadow = false
            end)
            return true
        end
        F.enqueueKill(d)
        return false
    end
    if d:IsA("Decal") or d:IsA("Texture") or d:IsA("SurfaceAppearance") or d:IsA("SpecialMesh") then
        F.enqueueKill(d)
        return false
    end
    if (d:IsA("BillboardGui") or d:IsA("SurfaceGui")) and not F.isClaim(d) then
        F.enqueueKill(d)
        return false
    end
    return true
end

function F.stepPurge(deadline)
    local list = bag.purge
    if type(list) ~= "table" then
        return
    end
    local at = bag.purgeAt or 1
    while at <= #list and os.clock() < deadline do
        local job = list[at]
        local inst = job.inst
        if job.kids == nil then
            if typeof(inst) ~= "Instance" then
                at += 1
            else
                local go = F.notePurge(inst, job.mode)
                if go == true then
                    job.kids = inst:GetChildren()
                    job.i = 1
                else
                    at += 1
                end
            end
        elseif job.i > #job.kids then
            at += 1
        else
            local ch = job.kids[job.i]
            job.i += 1
            if typeof(ch) == "Instance" then
                list[#list + 1] = { inst = ch, mode = job.mode }
            end
        end
    end
    if at > 80 and at > (#list * 0.5) then
        local kept = {}
        for i = at, #list do
            kept[#kept + 1] = list[i]
        end
        bag.purge = kept
        bag.purgeAt = 1
    else
        bag.purgeAt = at
    end
end

function F.litePause()
    if G.__StealEggFarOn == true
        or G.__StealEggBusy == true
        or G.__StealEggClaiming == true
        or G.__StealEggDecoyOn == true
        or G.__StealEggDead == true
    then
        return true
    end
    if os.clock() < (tonumber(G.__StealEggSpawnCool) or 0) then
        return true
    end
    return os.clock() < (tonumber(G.__StealEggClaimCool) or 0)
end

function F.scanHeavy()
    if F.litePause() == true then
        return
    end
    bag.heavyQueue = bag.heavyQueue or {}
    F.nukeForeignPets()
    F.nukeForeignEggs()
end

function F.drainHeavy(deadline)
    if G.__StealEggLiteOn ~= true then
        return
    end
    local q = bag.heavyQueue
    if type(q) ~= "table" or #q == 0 then
        return
    end
    local limit = deadline or (os.clock() + 0.004)
    local n = 0
    while n < 24 and #q > 0 and os.clock() < limit do
        F.kill(table.remove(q))
        n += 1
    end
end

function F.startHeavy()
    bag.heavyOn = true
    bag.heavyQueue = {}
    F.scanHeavy()
    if bag.heavyDescConn then
        return
    end
    bag.heavyDescConn = Workspace.DescendantAdded:Connect(function(inst)
        if G.__StealEggLiteOn ~= true or bag.heavyOn ~= true then
            return
        end
        if F.litePause() == true then
            return
        end
        local n = (bag.descBurst or 0) + 1
        bag.descBurst = n
        if n > 32 then
            return
        end
        local par = inst.Parent
        if not par then
            return
        end
        if par.Name == "ClientRenderedAssets" or par.Name == "__DEBRIS" then
            if inst:IsA("Model") or FX[inst.ClassName] then
                F.enqueueKill(inst)
            end
            return
        end
        -- Hanya telur plot ORANG LAIN — jangan bunuh telur sendiri.
        if par.Name == "PlacedEggRenders" and inst:IsA("Model") and not F.isMine(inst) then
            F.enqueueKill(inst)
            return
        end
        -- Jangan bunuh FX workspace (scramble cave / claim = ratusan Particle/s).
    end)
    track(bag.heavyDescConn)
end

function F.nukeLocalChar()
    if F.litePause() == true then
        return
    end
    -- Char baru / respawn: GetDescendants + Destroy FX = freeze.
    if os.clock() - (tonumber(G.__StealEggCharAt) or 0) < 2.8 then
        return
    end
    local char = LP.Character
    if not char then
        return
    end
    local desc = char:GetDescendants()
    for i = #desc, 1, -1 do
        F.killFx(desc[i])
    end
end

