end

function F.disableSubBiomes()
    pcall(function()
        local vfx = Workspace:FindFirstChild("LightDarkSubBiomeVfx")
        if vfx then
            F.kill(vfx)
        end
    end)
    local ps = LP and LP:FindFirstChild("PlayerScripts")
    if not ps then
        return
    end
    pcall(function()
        for _, d in ipairs(ps:GetDescendants()) do
            if d.Name == "SubBiomes" and (d:IsA("LocalScript") or d:IsA("Script")) then
                d.Disabled = true
            end
        end
    end)
end

function F.stripOtherCharacters()
    local list = Players:GetPlayers()
    for i = 1, #list do
        local plr = list[i]
        if plr ~= LP then
            local char = plr.Character
            if char then
                local anim = char:FindFirstChild("Animate")
                if anim and anim:IsA("LocalScript") then
                    pcall(function()
                        anim.Disabled = true
                    end)
                end
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then
                    pcall(function()
                        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                        hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
                        hum.PlatformStand = hum.PlatformStand
                    end)
                    -- Matikan animator pemain lain (biaya CPU besar di HP).
                    local animator = hum:FindFirstChildOfClass("Animator")
                    if animator then
                        pcall(function()
                            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                                track:Stop(0)
                            end
                        end)
                        pcall(function()
                            animator:Destroy()
                        end)
                    end
                end
                F.queuePurge(char, "char")
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if hrp and hrp:IsA("BasePart") then
                    pcall(function()
                        hrp.LocalTransparencyModifier = 1
                        hrp.CastShadow = false
                    end)
                end
            end
        end
    end
end

function F.mutePetBillboards()
    local bill = F.findModule("AssetBillboardController")
    if type(bill) == "table" then
        F.patchMethod(bill, "Add", F.noop)
        F.patchMethod(bill, "AddBillboard", F.noop)
        F.patchMethod(bill, "Create", F.noop)
    end
end

