function F.purgeNonCollideDecor(root)
    F.queuePurge(root, "decor")
end

function F.stripWorldJunk()
    if G.__StealEggFarOn == true
        or G.__StealEggBusy == true
        or G.__StealEggClaiming == true
        or G.__StealEggDecoyOn == true
    then
        return
    end
    local root = Workspace:FindFirstChild("__OBJECTS")
    if root then
        -- Purge per-anak supaya Areas.GuardAreas tidak ikut.
        for _, ch in ipairs(root:GetChildren()) do
            if ch.Name == "Areas" then
                for _, areaCh in ipairs(ch:GetChildren()) do
                    if areaCh.Name ~= "GuardAreas" then
                        F.purgeNonCollideDecor(areaCh)
                    end
                end
            elseif ch.Name ~= "SecretZones" then
                F.purgeNonCollideDecor(ch)
            end
        end
    end
    local map = Workspace:FindFirstChild("Map")
    if map then
        F.purgeNonCollideDecor(map)
    end
    local world = Workspace:FindFirstChild("World")
    if world then
        for _, ch in ipairs(world:GetChildren()) do
            if ch.Name == "Areas" then
                for _, areaCh in ipairs(ch:GetChildren()) do
                    if areaCh.Name ~= "GuardAreas" then
                        F.purgeNonCollideDecor(areaCh)
                    end
                end
            elseif ch.Name ~= "SecretZones" then
                F.purgeNonCollideDecor(ch)
            end
        end
    end
end

function F.disableHeavyLocals()
    local function keepScript(n)
        n = string.lower(tostring(n or ""))
        return string.find(n, "egg", 1, true)
            or string.find(n, "plot", 1, true)
            or string.find(n, "guard", 1, true)
            or string.find(n, "scramble", 1, true)
            or string.find(n, "kernel", 1, true)
            or string.find(n, "platform", 1, true)
            or string.find(n, "prompt", 1, true)
            or string.find(n, "backpack", 1, true)
            or string.find(n, "placement", 1, true)
            or string.find(n, "shop", 1, true)
            or string.find(n, "index", 1, true)
            or string.find(n, "icon", 1, true)
            or string.find(n, "speed", 1, true)
            or string.find(n, "treadmill", 1, true)
            or string.find(n, "hotbar", 1, true)
            or string.find(n, "hud", 1, true)
            or string.find(n, "timer", 1, true)
            or string.find(n, "night", 1, true)
    end
    local function scrub(root)
        if not root then
            return
        end
        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("LocalScript") and HEAVY_LOCAL[d.Name] and d.Parent ~= nil then
                pcall(function()
                    d:Destroy()
                end)
            end
        end
    end
    scrub(LP and LP:FindFirstChild("PlayerScripts"))
    scrub(LP and LP:FindFirstChild("PlayerGui"))
    local function scrubVfx(root)
        if not root then
            return
        end
        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("LocalScript") and d.Disabled ~= true then
                local n = string.lower(d.Name)
                if string.find(n, "rainbow", 1, true)
                    or string.find(n, "worldfx", 1, true)
                    or string.find(n, "billboard", 1, true)
                    or string.find(n, "sunburst", 1, true)
                    or string.find(n, "playsprite", 1, true)
                    or string.find(n, "hoverbob", 1, true)
                    or string.find(n, "gradient", 1, true)
                    or string.find(n, "glitch", 1, true)
                    or string.find(n, "shimmer", 1, true)
                    or string.find(n, "confetti", 1, true)
                    or string.find(n, "shake", 1, true)
                    or string.find(n, "trail", 1, true)
                    or string.find(n, "parasite", 1, true)
                    or string.find(n, "leaderboard", 1, true)
                    or string.find(n, "sakura", 1, true)
                then
                    if not keepScript(n) then
                        pcall(function()
                            d.Disabled = true
                        end)
                    end
                end
            end
        end
    end
    scrubVfx(LP and LP:FindFirstChild("PlayerScripts"))
    scrubVfx(LP and LP:FindFirstChild("PlayerGui"))
end

function F.muteHeavyRender()
end

function F.throttleEngine()
    pcall(function()
        if typeof(Enum.ClientAnimatorThrottlingMode) == "Enum" then
            Workspace.ClientAnimatorThrottling = Enum.ClientAnimatorThrottlingMode.Enabled
        end
    end)
    pcall(function()
        settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
    end)
    pcall(function()
        -- Enum level mesh detail bervariasi antar client; coba dari rendah.
        local r = settings().Rendering
        if r.MeshPartDetailLevel ~= nil then
            local ok = pcall(function()
                r.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04
            end)
            if not ok then
                pcall(function()
                    r.MeshPartDetailLevel = Enum.MeshPartDetailLevel.DistanceBased
                end)
            end
        end
    end)
    pcall(function()
        local physics = settings().Physics
        if physics.AllowSleep ~= nil then
            physics.AllowSleep = true
        end
        physics.PhysicsEnvironmentalThrottle = Enum.EnviromentalPhysicsThrottle.Skip4
    end)
    pcall(function()
        UserSettings().GameSettings.SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1
    end)
end

-- PC = mobile: semua extra Lite sama. Jangan cabang Touch.
-- Berat (sekali saat ON / player join): world purge + mute render connections.
-- Ringan (periodik): cuma bersih pet/egg/char yang respawn — jangan GetDescendants dunia tiap 3s.
function F.applyLiteExtras()
    pcall(F.throttleEngine)
    pcall(F.stripWorldJunk)
    pcall(F.stripForeignPlots)
    pcall(F.disableHeavyLocals)
    pcall(F.muteHeavyRender)
    pcall(F.muteTreadmillVideo)
    pcall(F.disableSubBiomes)
    pcall(F.stripOtherCharacters)
    pcall(F.mutePetBillboards)
    pcall(F.nukeForeignEggs)
    pcall(F.nukeForeignPets)
    -- Panel admin sisa (script sudah putus) Active=true → Shop/Index/Egg tidak keklik.
    pcall(function()
        local ui = LP and LP:FindFirstChild("PlayerGui")
        local admin = ui and ui:FindFirstChild("ContentCreatorsAdminPanel")
        if admin and admin:IsA("LayerCollector") then
            admin.Enabled = false
        end
    end)
    bag.liteHeavyAt = os.clock()
end

-- Maintain periodik: biaya kecil. Spike 200ms tiap 3s = applyLiteExtras penuh di loop.
function F.maintainLite()
    if G.__StealEggLiteOn ~= true then
        return
    end
    if F.litePause() == true then
        return
    end
    pcall(F.nukeForeignEggs)
    pcall(F.nukeForeignPets)
    pcall(F.killPetsNow)
    pcall(F.stripOtherCharacters)
    if bag.localsOnce ~= true then
        bag.localsOnce = true
        pcall(F.disableHeavyLocals)
    end
    local now = os.clock()
    if (now - (bag.plotStripAt or 0)) >= 20 then
        bag.plotStripAt = now
        pcall(F.stripForeignPlots)
    end
end

-- Alias lama
F.applyMobileExtras = F.applyLiteExtras

function F.applyGraphics()
    pcall(function()
        Lighting.GlobalShadows = false
        Lighting.ShadowSoftness = 0
    end)
    pcall(function()
        settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
    end)
    pcall(function()
        UserSettings().GameSettings.SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1
    end)
    -- Jangan ubah Fog / ColorCorrection / Atmosphere (bikin biru / aneh).
    pcall(function()
        for _, ch in ipairs(Lighting:GetChildren()) do
            if ch:IsA("BloomEffect")
                or ch:IsA("SunRaysEffect")
                or ch:IsA("BlurEffect")
                or ch:IsA("DepthOfFieldEffect")
            then
                pcall(function()
                    ch.Enabled = false
                end)
            end
        end
    end)
    pcall(function()
        SoundService.Volume = 0
    end)
    -- Jangan setfpscap(0): unlimited FPS + Instant hop = freeze. Cap 10 tetap dari modul FPS.
end

function F.undoBlueTint()
    -- No-op: jangan sentuh fog / ColorCorrection / warna world.
end

function F.killPetsNow()
    local n = 0
    for i = 1, #PET_FOLDERS do
        local folder = Workspace:FindFirstChild(PET_FOLDERS[i])
        if folder then
            local kids = folder:GetChildren()
            for j = 1, #kids do
                pcall(function()
                    kids[j]:Destroy()
                end)
                n += 1
            end
        end
    end
    return n
end

function F.hookNow()
    pcall(F.setGardenHook, true)
    pcall(F.hookItemDisplay, true)
    pcall(F.gateGardenCpu)
    pcall(F.hookCreators)
    pcall(F.setPetsHidden, true)
    pcall(F.patchCpu)
    pcall(F.stopBones)
    pcall(F.queueWorkspaceFx)
    pcall(F.hookEggVisual, true)
    pcall(F.applyLiteExtras)
end

function F.start()
    G.__StealEggLiteOn = true
    pcall(F.killPetsNow)
    pcall(F.applyGraphics)
    pcall(F.undoBlueTint)
    pcall(F.hookNow)
    pcall(F.nukeLocalChar)

    if bag.hb then
        return
    end

    bag.starting = true
    F.startHeavy()

    for i = 1, #PET_FOLDERS do
        local folder = Workspace:FindFirstChild(PET_FOLDERS[i])
        if folder then
            F.stripPets(folder)
            track(folder.ChildAdded:Connect(function(child)
                if G.__StealEggLiteOn then
                    pcall(function()
                        child:Destroy()
                    end)
                end
            end))
        end
    end

    track(Workspace.ChildAdded:Connect(function(child)
        if G.__StealEggLiteOn ~= true then
            return
        end
        for i = 1, #PET_FOLDERS do
            if child.Name == PET_FOLDERS[i] then
                F.stripPets(child)
            end
        end
        if child.Name == "PlacedEggRenders" then
            pcall(F.nukeForeignEggs)
        end
    end))

    G.__StealEggFpsLifeGen = (tonumber(G.__StealEggFpsLifeGen) or 0) + 1
    local FPS_LIFE = G.__StealEggFpsLifeGen
    track(LP.CharacterRemoving:Connect(function()
        if G.__StealEggFpsLifeGen ~= FPS_LIFE then
            return
        end
        G.__StealEggSpawnCool = os.clock() + 4.5
    end))
    track(LP.CharacterAdded:Connect(function()
        if G.__StealEggFpsLifeGen ~= FPS_LIFE then
            return
        end
        -- Jangan GetDescendants+Destroy FX di frame spawn — itu freeze setelah mati.
        G.__StealEggSpawnCool = os.clock() + 3.2
    end))

    local function cutHeavyScript(inst)
        if G.__StealEggLiteOn ~= true then
            return
        end
        if F.litePause() == true then
            return
        end
        if inst:IsA("LocalScript") and HEAVY_LOCAL[inst.Name] then
            task.defer(function()
                if inst.Parent ~= nil then
                    pcall(function()
                        inst:Destroy()
                    end)
                end
            end)
        end
    end
    local psWatch = LP:FindFirstChild("PlayerScripts")
    local guiWatch = LP:FindFirstChild("PlayerGui")
    if psWatch then
        track(psWatch.DescendantAdded:Connect(cutHeavyScript))
    end
    if guiWatch then
        track(guiWatch.DescendantAdded:Connect(cutHeavyScript))
    end

    bag.hb = RunService.Heartbeat:Connect(function()
        bag.descBurst = 0
        if G.__StealEggLiteOn ~= true then
            return
        end
        if F.litePause() == true then
            return
        end
        local deadline = os.clock() + 0.004
        F.drainHeavy(deadline)
        F.stepPurge(deadline)
    end)

    -- Maintain ringan tiap 8–12s. JANGAN applyLiteExtras penuh di sini
    -- (GetDescendants + getconnections = spike ~200ms tiap 3s).
    if not bag.mobileSweep then
        bag.mobileSweep = true
        task.spawn(function()
            while G.__StealEggLiteOn == true and bag.mobileSweep == true do
                local waitSec = F.crowdHot() and 8 or 12
                task.wait(waitSec)
                if G.__StealEggLiteOn ~= true then
                    break
                end
                pcall(F.maintainLite)
            end
            bag.mobileSweep = nil
        end)
    end

    track(Players.PlayerAdded:Connect(function(plr)
        if G.__StealEggLiteOn ~= true then
            return
        end
        -- Player baru: maintain + strip plot sekali (bukan muteHeavyRender ulang).
        task.defer(function()
            if G.__StealEggLiteOn then
                pcall(F.maintainLite)
                pcall(F.stripForeignPlots)
            end
        end)
        track(plr.CharacterAdded:Connect(function()
            if G.__StealEggLiteOn then
                task.defer(F.stripOtherCharacters)
            end
        end))
    end))
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP then
            track(plr.CharacterAdded:Connect(function()
                if G.__StealEggLiteOn then
                    task.defer(F.stripOtherCharacters)
                end
            end))
        end
    end

    task.spawn(function()
        if not G.__StealEggLiteOn then
            bag.starting = nil
            return
        end
        local cmds = F.settingsCmds()
        if type(cmds) == "table" and type(cmds.Write) == "function" then
            pcall(cmds.Write, "HideOtherPets", true)
            pcall(cmds.Write, "HideSelfPets", true)
            pcall(cmds.Write, "DisableVideos", true)
        end
        for _ = 1, 12 do
            if not G.__StealEggLiteOn then
                break
            end
            local okHook = false
            pcall(function()
                okHook = F.setGardenHook(true) == true
            end)
            pcall(F.hookItemDisplay, true)
            if okHook then
                break
            end
            task.wait(0.25)
        end
        pcall(F.killPetsNow)
        pcall(F.applyLiteExtras)
        bag.starting = nil
    end)
end

function F.stop()
    bag.starting = nil
    bag.mobileSweep = nil
