local tryRequire = Core.require
local AssetEarn, EggItemUtil, AssetItems, Save, ItemDisplay, NumberFmt, AssetDir, Mutations
local getSave

local function bindGame()
    AssetEarn = AssetEarn or tryRequire("Library.Util.AssetGenerationUtil")
    EggItemUtil = EggItemUtil or tryRequire("Library.Util.EggItemUtil")
    AssetItems = AssetItems or tryRequire("Library.Util.AssetItemSerialization") or tryRequire("Library.Util.AssetItemUtil")
    Save = Save or tryRequire("Library.Client.Save")
    ItemDisplay = ItemDisplay or tryRequire("Shared.Modules.ItemDisplay") or tryRequire("Library.Modules.ItemDisplay")
    NumberFmt = NumberFmt or tryRequire("Packages.FormatNumber.Simple")
end

local function parseMutations(raw)
    if type(raw) == "table" then
        local out = {}
        for _, name in ipairs(raw) do
            if type(name) == "string" and name ~= "" and name ~= "None" then
                out[#out + 1] = name
            end
        end
        if #out > 0 then
            return out
        end
        for _, name in pairs(raw) do
            if type(name) == "string" and name ~= "" and name ~= "None" then
                out[#out + 1] = name
            end
        end
        return out
    end
    if type(raw) ~= "string" or raw == "" then
        return {}
    end
    local out = {}
    for part in string.gmatch(raw, "[^,]+") do
        local name = string.match(part, "^%s*(.-)%s*$")
        if name ~= "" and name ~= "None" then
            out[#out + 1] = name
        end
    end
    return out
end

local function attr(inst, name)
    if inst == nil then
        return nil
    end
    if type(inst) == "table" and type(inst.GetAttribute) == "function" then
        local ok, v = pcall(inst.GetAttribute, inst, name)
        if ok then
            return v
        end
    end
    if typeof(inst) == "Instance" then
        local ok, v = pcall(function()
            return inst:GetAttribute(name)
        end)
        if ok then
            return v
        end
    end
    return nil
end

local function toolKind(tool)
    if tool == nil then
        return nil
    end
    if type(tool) == "table" then
        if tool.IsVirtualEgg == true then
            return "egg"
        end
        if tool.IsVirtualAsset == true then
            return "pet"
        end
    elseif typeof(tool) == "Instance" then
        if not tool:IsA("Tool") then
            return nil
        end
    else
        return nil
    end
    local kind = attr(tool, "ItemType")
    if kind == "AssetEgg" then
        return "egg"
    end
    if kind == "Asset" or kind == "Pet" or kind == "Brainrot" then
        return "pet"
    end
    return nil
end

local function eggToAsset(egg)
    if type(egg) ~= "table" then
        return nil
    end
    if type(EggItemUtil) == "table" and type(EggItemUtil.BuildAssetItemData) == "function" then
        local ok, item = pcall(EggItemUtil.BuildAssetItemData, egg)
        if ok and type(item) == "table" then
            return item
        end
    end
    local category = egg.AssetCategory or egg.Category
    if type(category) ~= "string" or category == "" then
        return nil
    end
    local scale = tonumber(egg.AssetScale or egg.Scale) or 1
    if scale <= 0 then
        scale = 1
    end
    return {
        Category = category,
        Scale = scale,
        Mutations = parseMutations(egg.Mutations or egg.muts),
        BaseMutation = egg.BaseMutation,
        Gender = egg.AssetGender or egg.Gender,
        EyeColor = egg.AssetEyeColor or egg.EyeColor,
        ColorSeed = egg.AssetColorSeed or egg.ColorSeed,
        ColorIndex = egg.AssetColorIndex or egg.ColorIndex,
        Personality = egg.AssetPersonality or egg.Personality,
        IsStolenDNA = egg.IsStolenDNA,
    }
end

local function deserializePet(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if type(raw.Category) == "string" then
        return raw
    end
    if type(AssetItems) == "table" then
        local fn = AssetItems.Deserialize or AssetItems.Decode
        if type(fn) == "function" then
            local ok, item = pcall(fn, raw)
            if ok and type(item) == "table" then
                return item
            end
        end
    end
    return nil
end

local function itemFromTool(tool, kind)
    local data = attr(tool, "ItemData")
    if type(data) == "table" and type(data.Category) == "string" then
        return data
    end
    if kind == "egg" then
        local rec = attr(tool, "EggRecord")
        if type(rec) == "table" then
            return eggToAsset(rec)
        end
        if type(tool) == "table" and type(tool.AssetCategory) == "string" then
            return eggToAsset(tool)
        end
        local category = attr(tool, "AssetCategory") or attr(tool, "Category")
        if type(category) ~= "string" or category == "" then
            return nil
        end
        return eggToAsset({
            AssetCategory = category,
            AssetScale = attr(tool, "AssetScale") or attr(tool, "Scale") or 1,
            Mutations = parseMutations(attr(tool, "Mutations")),
            BaseMutation = attr(tool, "BaseMutation"),
        })
    end
    local category = attr(tool, "Category") or attr(tool, "AssetCategory")
    if type(category) ~= "string" or category == "" then
        return nil
    end
    local scale = tonumber(attr(tool, "Scale") or attr(tool, "AssetScale")) or 1
    if scale <= 0 then
        scale = 1
    end
    return {
        Category = category,
        Scale = scale,
        Mutations = parseMutations(attr(tool, "Mutations")),
        BaseMutation = attr(tool, "BaseMutation"),
        Gender = attr(tool, "Gender") or attr(tool, "AssetGender"),
        EyeColor = attr(tool, "EyeColor") or attr(tool, "AssetEyeColor"),
        ColorSeed = attr(tool, "ColorSeed") or attr(tool, "AssetColorSeed"),
        ColorIndex = attr(tool, "ColorIndex") or attr(tool, "AssetColorIndex"),
        Personality = attr(tool, "Personality") or attr(tool, "AssetPersonality"),
        IsStolenDNA = attr(tool, "IsStolenDNA"),
    }
end

local function assetDir()
    if type(AssetDir) == "table" then
        if type(AssetDir.Directory) == "table" then
            return AssetDir.Directory
        end
        return AssetDir
    end
    return nil
end

local function sizeEarnMulti(scale)
    scale = tonumber(scale) or 1
    if scale <= 0 then
        scale = 1
    end
    return scale
end

local function mutEarnMulti(muts)
    if type(Mutations) == "table" then
        local fn = Mutations.GetTotalMutationsEarningMulti or Mutations.EarningsFor
        if type(fn) == "function" then
            local ok, n = pcall(fn, muts or {})
            if ok then
                return math.max(1, tonumber(n) or 1)
            end
        end
    end
    return 1
end

local function normalizeAsset(assetData)
    if type(assetData) ~= "table" then
        return nil
    end
    local category = tostring(assetData.Category or assetData.AssetCategory or "")
    if category == "" then
        return nil
    end
    local scale = tonumber(assetData.Scale or assetData.AssetScale) or 1
    if scale <= 0 then
        scale = 1
    end
    local copy = {
        Category = category,
        Scale = scale,
        Mutations = parseMutations(assetData.Mutations or assetData.muts),
    }
    local baseMut = assetData.BaseMutation
    if type(baseMut) == "string" and baseMut ~= "" then
        copy.BaseMutation = baseMut
    end
    local g = assetData.Gender or assetData.AssetGender
    if g == "Male" or g == "Female" then
        copy.Gender = g
    end
    return copy
end

local function itemRate(assetData)
    assetData = normalizeAsset(assetData)
    if type(assetData) ~= "table" then
        return 0
    end
    local saveData = getSave()
    if type(AssetEarn) == "table" then
        -- Sama wild_egg/auto_sell: GetRate dulu (rebirth+pass). MutationOnly di HP
        -- sering assert Scale/Mutations → 0 semua kalau dipanggil sendirian.
        local rateFn = AssetEarn.GetRate or AssetEarn.RatePerSecond
        if type(rateFn) == "function" then
            local rebirth = type(saveData) == "table" and tonumber(saveData.Rebirth) or 0
            local passes = type(saveData) == "table" and saveData.Gamepasses or nil
            local products = type(saveData) == "table" and saveData.Products or nil
            local ok, n = pcall(rateFn, assetData, rebirth or 0, passes, products)
            if ok then
                local v = tonumber(n) or 0
                if v > 0 then
                    return v
                end
            end
        end
        local mutOnly = AssetEarn.GetBaseRateMutationOnly or AssetEarn.MutationOnlyRatePerSecond
        if type(mutOnly) == "function" then
            local ok, n = pcall(mutOnly, assetData)
            if ok then
                local v = tonumber(n) or 0
                if v > 0 then
                    return v
                end
            end
        end
        local catalog = AssetEarn.CatalogRatePerSecond
        if type(catalog) == "function" then
            local ok, n = pcall(catalog, assetData)
            if ok then
                local v = tonumber(n) or 0
                if v > 0 then
                    return v
                end
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and dir[assetData.Category]
    local base = type(cfg) == "table" and tonumber(cfg.EarningRate) or 0
    local n = math.round(base * sizeEarnMulti(assetData.Scale) * mutEarnMulti(assetData.Mutations))
    return math.max(n, 0)
end

local function petTitle(item)
    if type(item) ~= "table" then
        return ""
    end
    local name = tostring(item.Category or "")
    if type(ItemDisplay) == "table" and type(ItemDisplay.GetNameFromItemData) == "function" then
        local ok, n = pcall(ItemDisplay.GetNameFromItemData, item)
        if ok and type(n) == "string" and n ~= "" then
            name = n
        end
    end
    local w = nil
    if type(AssetItems) == "table" and type(AssetItems.WeightLabel) == "function" then
        local ok, label = pcall(AssetItems.WeightLabel, item)
        if ok and type(label) == "string" and label ~= "" then
            w = label
        end
    end
    if type(w) ~= "string" or w == "" then
        return name
    end
    return name .. " (" .. w .. ")"
end

local function eggTitle(rec)
    if type(rec) ~= "table" then
        return ""
    end
    if type(EggItemUtil) == "table" and type(EggItemUtil.DisplayNameWithWeight) == "function" then
        local ok, n = pcall(EggItemUtil.DisplayNameWithWeight, rec)
        if ok and type(n) == "string" and n ~= "" then
            return n
        end
    end
    return petTitle(eggToAsset(rec) or rec)
end

local function equippedSet(data)
    local out = {}
    if type(data) == "table" and type(data.EquippedAssets) == "table" then
        for _, uid in ipairs(data.EquippedAssets) do
            out[tostring(uid)] = true
        end
    end
    return out
end

local function slotTitle(slot)
    if typeof(slot) ~= "Instance" then
        return ""
    end
    local lbl = slot:FindFirstChild("ToolName", true)
    local name = ""
    if lbl and (lbl:IsA("TextLabel") or lbl:IsA("TextButton")) then
        name = tostring(lbl.Text or "")
    end
    local w = slot:FindFirstChild("Weight", true)
    local kg = ""
    if w and (w:IsA("TextLabel") or w:IsA("TextButton")) then
        kg = tostring(w.Text or "")
    end
    if name ~= "" and kg ~= "" and not string.find(name, kg, 1, true) then
        return name .. " (" .. kg .. ")"
    end
    return name
end

local function normTitle(s)
    s = string.lower(tostring(s or ""))
    s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("%s*%([^%)]*%)%s*$", "")
    return s
end

local function rememberTitle(byTitle, title, row)
    if type(title) ~= "string" or title == "" or type(row) ~= "table" then
        return
    end
    byTitle[title] = row
    local n = normTitle(title)
    if n ~= "" then
        byTitle[n] = row
    end
    if type(row.name) == "string" and row.name ~= "" then
        byTitle[row.name] = row
        local nn = normTitle(row.name)
        if nn ~= "" then
            byTitle[nn] = row
        end
    end
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    local units = {
        { 1e33, "Dc" },
        { 1e30, "No" },
        { 1e27, "Oc" },
        { 1e24, "Sp" },
        { 1e21, "Sx" },
        { 1e18, "Qi" },
        { 1e15, "Qa" },
        { 1e12, "T" },
        { 1e9, "B" },
        { 1e6, "M" },
        { 1e3, "k" },
    }
    for _, u in ipairs(units) do
        if abs >= u[1] then
            return string.format("%.1f%s", n / u[1], u[2])
        end
    end
    if abs >= 10 or n == math.floor(n) then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

local function fmtRate(n)
    n = tonumber(n) or 0
    if type(NumberFmt) == "table" and type(NumberFmt.FormatCompact) == "function" then
        local ok, s = pcall(NumberFmt.FormatCompact, n, ".#")
        if ok and type(s) == "string" and s ~= "" then
            if not (n > 0 and (s == "0" or s == "0.0")) then
                return s
            end
        end
    end
    return fmtNum(n)
end

getSave = function()
    if type(Core) == "table" and type(Core.playerSave) == "function" then
        local ok, data = pcall(Core.playerSave)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, data = pcall(Save.Get)
        if ok and type(data) == "table" then
            return data
        end
    end
    if type(Save) == "table" and type(Save.Cache) == "function" then
        local okC, bag = pcall(Save.Cache)
        if okC and type(bag) == "table" then
            local data = bag[LP]
            if type(data) == "table" then
                return data
            end
            local uid = tonumber(LP and LP.UserId) or 0
            for plr, rec in pairs(bag) do
                if type(rec) == "table" then
                    local id = 0
                    pcall(function()
                        id = tonumber(plr.UserId) or 0
                    end)
                    if uid ~= 0 and id == uid then
                        return rec
                    end
                end
            end
        end
    end
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, data = pcall(Save.Get, LP, true)
        if ok and type(data) == "table" then
            return data
        end
        ok, data = pcall(Save.Get)
        if ok and type(data) == "table" then
            return data
        end
        ok, data = pcall(Save.Get, LP, false)
        if ok and type(data) == "table" then
            return data
        end
    end
    return nil
end

local function bagLists()
    local now = os.clock()
    if now - (tonumber(M._bag.at) or 0) < BAG_TTL then
        return M._bag
    end
    local data = getSave()
    local eggs, pets, byTitle = {}, {}, {}
    local equipped = equippedSet(data)
    if type(data) == "table" then
        if type(data.EggInventory) == "table" then
            for uid, raw in pairs(data.EggInventory) do
                local rec = raw
                if type(EggItemUtil) == "table" then
                    local fn = EggItemUtil.DeserializeSavedEgg or EggItemUtil.Decode
                    if type(fn) == "function" then
                        local ok, egg = pcall(fn, raw)
                        if ok and type(egg) == "table" then
                            rec = egg
                        end
                    end
                end
                if type(rec) == "table" and rec.Placement == nil then
                    local asset = eggToAsset(rec)
                    local rarityNum = 0
                    if type(Core.eggRarityNumber) == "function" then
                        rarityNum = tonumber(Core.eggRarityNumber(rec.AssetCategory or rec.Category)) or 0
                    end
                    local row = {
                        uid = tostring(uid),
                        kind = "egg",
                        rate = itemRate(asset),
                        rarity = rarityNum,
                        name = tostring(rec.AssetCategory or rec.Category or ""),
                        kg = tonumber(rec.AssetScale or rec.Scale) or 0,
                        title = eggTitle(rec),
                    }
                    eggs[#eggs + 1] = row
                    rememberTitle(byTitle, row.title, row)
                end
            end
        end
        if type(data.Inventory) == "table" then
            for uid, raw in pairs(data.Inventory) do
                if equipped[tostring(uid)] == true then
                    -- Pet di plot: tidak ada di slot backpack. Jangan ikut index.
                    continue
                end
                local item = deserializePet(raw)
                if type(item) == "table" and item.InFuse ~= true then
                    local rate = itemRate(item)
                    local rarityNum = 0
                    if type(Core.eggRarityNumber) == "function" then
                        rarityNum = tonumber(Core.eggRarityNumber(item.Category)) or 0
                    end
                    local row = {
                        uid = tostring(uid),
                        kind = "pet",
                        rate = rate,
                        rarity = rarityNum,
                        name = tostring(item.Category or ""),
                        kg = tonumber(item.Scale) or 0,
                        favorite = item.IsFavorite == true,
                        title = petTitle(item),
                    }
                    pets[#pets + 1] = row
                    rememberTitle(byTitle, row.title, row)
                end
            end
        end
    end
    local function byRarityRate(a, b)
        if a.favorite ~= b.favorite then
            return a.favorite == true
        end
        if a.rarity ~= b.rarity then
            return a.rarity > b.rarity
        end
        if a.rate ~= b.rate then
            return a.rate > b.rate
        end
        return tostring(a.uid) < tostring(b.uid)
    end
    table.sort(eggs, byRarityRate)
    table.sort(pets, byRarityRate)
    local ttl = BAG_TTL
    if #eggs == 0 and #pets == 0 then
        ttl = 0.12
    end
    M._bag = { at = now - (BAG_TTL - ttl), egg = eggs, pet = pets, byTitle = byTitle }
    return M._bag
end

local function connFn(c)
    if c == nil then
        return nil
    end
    local fn = c.Function or c.fn
    if type(fn) == "function" then
        return fn
    end
    if type(c.getFunction) == "function" then
        local ok, f = pcall(c.getFunction, c)
        if ok and type(f) == "function" then
            return f
        end
    end
    return nil
end

local function eachUpvalue(fn, visit)
    if type(fn) ~= "function" then
        return
    end
    if type(getupvalues) == "function" then
        local ok, t = pcall(getupvalues, fn)
        if ok and type(t) == "table" then
            for k, v in pairs(t) do
                visit(k, v)
            end
        end
    end
    local dbg = debug
    if type(dbg) == "table" and type(dbg.getupvalue) == "function" then
        for i = 1, 24 do
            local ok, a, b = pcall(dbg.getupvalue, fn, i)
            if not ok then
                break
            end
            if b ~= nil then
                visit(a, b)
            elseif a ~= nil then
                visit(i, a)
            else
                break
            end
        end
    end
    if type(getupvalue) == "function" then
        for i = 1, 24 do
            local ok, val = pcall(getupvalue, fn, i)
            if ok and val ~= nil then
                visit(i, val)
            end
        end
    end
end

local function toolFromSlot(slot)
    if typeof(slot) ~= "Instance" or type(getconnections) ~= "function" then
        return nil
    end
    local ok, cons = pcall(getconnections, slot.MouseButton1Click)
    if not ok or type(cons) ~= "table" then
        return nil
    end
    local found = nil
    for i = 1, #cons do
        local fn = connFn(cons[i])
        if type(fn) == "function" then
            eachUpvalue(fn, function(_, val)
                if found or type(val) ~= "table" then
                    return
                end
                if val.Frame == slot and val.Tool ~= nil then
                    found = val.Tool
                end
            end)
        end
        if found then
            break
        end
    end
    return found
end

local function backpackGui()
    local pg = LP and LP:FindFirstChild("PlayerGui")
    if not pg then
        return nil
    end
    return pg:FindFirstChild("BackpackGui")
end

local function inventoryOpen(gui)
    if typeof(gui) ~= "Instance" or gui.Enabled ~= true then
        return false
    end
    local bp = gui:FindFirstChild("Backpack")
    local main = bp and bp:FindFirstChild("Main")
    local inv = main and main:FindFirstChild("Inventory")
    return inv ~= nil and inv.Visible == true
end

local function slotKind(slot)
    if attr(slot, "HasEggOverlay") == true then
        return "egg"
    end
    if attr(slot, "HasAssetOverlay") == true then
        return "pet"
    end
    return nil
end

local function collectSlots(gui)
    local out = {}
    if typeof(gui) ~= "Instance" then
        return out
    end
    local bp = gui:FindFirstChild("Backpack")
    local main = bp and bp:FindFirstChild("Main")
    local inv = main and main:FindFirstChild("Inventory")
    local root = inv and (inv:FindFirstChild("ScrollingFrame") or inv)
    if typeof(root) ~= "Instance" then
        return out
    end
    for _, inst in ipairs(root:GetChildren()) do
        if inst:IsA("GuiObject")
            and inst.Visible == true
            and attr(inst, "IsInventorySlot") == true
        then
            local kind = slotKind(inst)
            if kind then
                out[#out + 1] = inst
            end
        end
    end
    table.sort(out, function(a, b)
        local la = tonumber(a.LayoutOrder) or 0
        local lb = tonumber(b.LayoutOrder) or 0
        if la ~= lb then
            return la < lb
        end
        return a.AbsolutePosition.X < b.AbsolutePosition.X
            or (a.AbsolutePosition.X == b.AbsolutePosition.X and a.AbsolutePosition.Y < b.AbsolutePosition.Y)
    end)
    return out
end

local function destroyLabel(entry)
    if type(entry) ~= "table" then
        return
    end
    if entry.gui then
        pcall(function()
            entry.gui:Destroy()
        end)
    end
    entry.gui = nil
    entry.lbl = nil
end

local function clearAll()
    for slot, entry in pairs(M._labels) do
        destroyLabel(entry)
        M._labels[slot] = nil
    end
end

local STYLE = 4

local function paintChip(gui, lbl, slot)
    -- Offset px + UIScale HP = teks gede. Pakai Scale biar ikut ukuran slot.
    local slotH = (typeof(slot) == "Instance" and slot.AbsoluteSize and slot.AbsoluteSize.Y) or 80
    local compact = slotH < 78
    local z = (tonumber(slot.ZIndex) or 20) + 25
    gui.AnchorPoint = Vector2.new(0.5, 0)
    gui.Position = UDim2.new(0.5, 0, compact and 0.02 or 0.045, 0)
    gui.Size = UDim2.new(compact and 0.92 or 0.88, 0, compact and 0.20 or 0.19, 0)
    gui.BackgroundColor3 = COL_BG
    gui.BackgroundTransparency = 0.04
    gui.BorderSizePixel = 0
    gui.ZIndex = z
    gui:SetAttribute("EspStyle", STYLE)
    local corner = gui:FindFirstChildOfClass("UICorner")
    if not corner then
        corner = Instance.new("UICorner")
        corner.Parent = gui
    end
    corner.CornerRadius = UDim.new(0.32, 0)
    local stroke = gui:FindFirstChild("Stroke")
    if not stroke or not stroke:IsA("UIStroke") then
        if stroke then
            pcall(function()
                stroke:Destroy()
            end)
        end
        stroke = Instance.new("UIStroke")
        stroke.Name = "Stroke"
        stroke.Parent = gui
    end
    stroke.Color = COL_YELLOW
    stroke.Thickness = compact and 0.8 or 1.1
    stroke.Transparency = 0.22
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local pad = gui:FindFirstChildOfClass("UIPadding")
    if not pad then
        pad = Instance.new("UIPadding")
        pad.Parent = gui
    end
    pad.PaddingLeft = UDim.new(0.03, 0)
    pad.PaddingRight = UDim.new(0.03, 0)
    pad.PaddingTop = UDim.new(0.04, 0)
    pad.PaddingBottom = UDim.new(0.04, 0)
    lbl.BackgroundTransparency = 1
    lbl.Size = UDim2.fromScale(1, 1)
    lbl.ZIndex = z + 1
    lbl.Font = Enum.Font.GothamBold
    lbl.TextScaled = true
    lbl.TextColor3 = COL_YELLOW
    lbl.TextStrokeTransparency = 1
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local constraint = lbl:FindFirstChildOfClass("UITextSizeConstraint")
    if not constraint then
        constraint = Instance.new("UITextSizeConstraint")
        constraint.Parent = lbl
    end
    constraint.MinTextSize = 7
    constraint.MaxTextSize = compact and 12 or 13
end

local function ensureLabel(slot)
    local gui = slot:FindFirstChild(TAG)
    local lbl = gui and gui:FindFirstChild("Label")
    if gui and gui:IsA("Frame") and lbl and lbl:IsA("TextLabel") then
        if gui:GetAttribute("EspStyle") ~= STYLE then
            paintChip(gui, lbl, slot)
        end
        return gui, lbl
    end
    if gui then
        pcall(function()
            gui:Destroy()
        end)
    end
    gui = Instance.new("Frame")
    gui.Name = TAG
    gui.Parent = slot
    lbl = Instance.new("TextLabel")
    lbl.Name = "Label"
    lbl.Text = ""
    lbl.Parent = gui
    paintChip(gui, lbl, slot)
    return gui, lbl
end

local function liveOn()
    return G.__StealEggEspGen == GEN and M.enabled == true
end

local function rateForSlot(slot, kind, index)
    local title = slotTitle(slot)
    local bag = bagLists()
    if title ~= "" and type(bag.byTitle) == "table" then
        local row = bag.byTitle[title] or bag.byTitle[normTitle(title)]
        if type(row) == "table" then
            return tonumber(row.rate) or 0, row.kind or kind
        end
    end
    local tool = toolFromSlot(slot)
    local toolKindName = toolKind(tool)
    if toolKindName then
        kind = toolKindName
    end
    if tool then
        local asset = itemFromTool(tool, kind or "pet")
        local rate = itemRate(asset)
        if rate > 0 or asset ~= nil then
            return rate, kind
        end
    end
    if type(row) == "table" then
        return tonumber(row.rate) or 0, kind
    end
    return 0, kind
end

local function sweep()
    bindGame()
    local gui = backpackGui()
    if not inventoryOpen(gui) then
        clearAll()
        return
    end
    local slots = collectSlots(gui)
    local seen = {}
    local eggI, petI = 0, 0
    for i = 1, #slots do
        local slot = slots[i]
        local kind = slotKind(slot)
        if kind == "egg" then
            eggI += 1
        else
            petI += 1
        end
        local index = kind == "egg" and eggI or petI
        seen[slot] = true
        local entry = M._labels[slot]
        if type(entry) ~= "table" then
            entry = {}
            M._labels[slot] = entry
        end
        if not entry.gui or entry.gui.Parent ~= slot or not entry.lbl then
            destroyLabel(entry)
            local chip, lbl = ensureLabel(slot)
            entry.gui = chip
            entry.lbl = lbl
        end
        local now = os.clock()
        if (tonumber(entry.at) or 0) + RATE_TTL <= now or entry.kind ~= kind then
            local rate = rateForSlot(slot, kind, index)
            entry.at = now
            entry.kind = kind
            entry.text = fmtRate(rate) .. "/s"
        end
        if entry.lbl and entry.lbl.Text ~= entry.text then
            entry.lbl.Text = entry.text or ""
        end
    end
    for slot, entry in pairs(M._labels) do
        if seen[slot] ~= true or typeof(slot) ~= "Instance" or slot.Parent == nil then
            destroyLabel(entry)
            M._labels[slot] = nil
        end
    end
end

local function loop(token)
    M._loopOn = true
    while liveOn() and M._token == token do
        local ok, err = pcall(sweep)
        if not ok then
            warn("[StealEgg ESP] " .. tostring(err))
        end
        task.wait(SCAN_SEC)
    end
    if M._token == token then
        M._loopOn = false
        clearAll()
    end
end

function M.Stop()
    M._token += 1
    M._loopOn = false
    clearAll()
end

function M.setEnabled(on)
    on = on == true
    M.enabled = on
    if not on then
        M.Stop()
        return
    end
    if M._loopOn == true then
        return
    end
    M._token += 1
    local token = M._token
    task.spawn(function()
        loop(token)
    end)
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local v = values["misc.esp.backpack"]
    if v == nil then
        return
    end
    local on = v == true
    if type(Core.flagOn) == "function" then
        on = Core.flagOn(v)
    end
    M.setEnabled(on)
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body = ui:CreateSection({
        title = "ESP",
        expanded = false,
    })
    local group = ui:CreateGroup(body)
    ui:CreateRowToggle(group, {
        id = "misc.esp.backpack",
        label = "Enabled ESP Backpack",
        persist = true,
        hintText = "Tulis earn $/s di slot backpack (Eggs & Pets). Bukan di tangan.",
        initial = M.enabled == true,
        onChanged = function(on)
            M.setEnabled(on == true)
        end,
    })
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end,           required = true },
    { key = "Upgrade",   name = "Upgrade",       factory = function() -- Auto upgrade pen (base/plot) + pet slot + treadmill + trail shop. Cash only.
-- Dump:
--   Pen / slot: Pets UI "+1 EQUIP" = BaseUpgrade.PurchaseNextTier
--               = Homestead.AskBaseTierRaise (MaxAssets 7→18)
--               fallback Network "Plots: RequestBaseUpgrade"
--   Treadmill: Remotes.Treadmill.AskTierRaise:InvokeServer(next._id)
--              fallback "Treadmills: RequestUpgrade"
--   Trail:     Remotes.Trailwear.AskPurchase / AskChoose
--              fallback "Trails: RequestPurchase" / "Trails: RequestSelect"
-- Treadmill shop is locked until BaseUpgradeLevel > 0.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before AutoUpgrade", 0)
end

G.__StealEggUpgradeGen = (tonumber(G.__StealEggUpgradeGen) or 0) + 1
local GEN = G.__StealEggUpgradeGen

local M = {
    pen = false,
    slots = false,
    treadmill = false,
    trail = false,
    delay = 1.2,
    _token = 0,
    _loopOn = false,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggUpgrade
if type(prev) == "table" and prev ~= M then
    pcall(function()
        if type(prev.Stop) == "function" then
            prev.Stop()
        end
        prev.pen = false
        prev.slots = false
        prev.treadmill = false
        prev.trail = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggUpgrade = M

local tryRequire = Core.require
local Save, Network, Bases, Treadmills, Trails

local function bindGame()
    Save = Save or tryRequire("Library.Client.Save")
    Network = Network or tryRequire("Library.Client.Network")
    Bases = Bases or tryRequire("Data.Bases") or tryRequire("Directory.Bases")
    Treadmills = Treadmills or tryRequire("Data.Treadmills") or tryRequire("Directory.Treadmills")
    Trails = Trails or tryRequire("Data.Trails") or tryRequire("Directory.Trails")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

local function getSave()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get)
    if ok and type(data) == "table" then
        return data
    end
    local ok2, data2 = pcall(Save.Get, LP, false)
    if ok2 and type(data2) == "table" then
        return data2
    end
    return nil
end

local function fmtMoney(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    local sign = n < 0 and "-" or ""
    n = abs
    if n >= 1e12 then
        return sign .. string.format("%.1fT", n / 1e12)
    end
    if n >= 1e9 then
        return sign .. string.format("%.1fB", n / 1e9)
    end
    if n >= 1e6 then
        return sign .. string.format("%.1fM", n / 1e6)
    end
    if n >= 1e3 then
        return sign .. string.format("%.1fk", n / 1e3)
    end
    return sign .. string.format("%.0f", n)
end

local function netFolder()
    return ReplicatedStorage:FindFirstChild("Network")
end

local function findNet(name)
    local folder = netFolder()
    if not folder then
        return nil
    end
    local inst = folder:FindFirstChild(name)
    if inst then
        return inst
    end
    for _, ch in ipairs(folder:GetChildren()) do
        if ch.Name == name then
            return ch
        end
    end
    return nil
end

local function firePen()
    bindGame()
    local hs = Network and Network.Homestead
    local ev = hs and hs.AskBaseTierRaise
    if (typeof(ev) == "Instance" or type(ev) == "table") and type(ev.FireServer) == "function" then
        local ok = pcall(function()
            ev:FireServer()
        end)
        return ok == true
    end
    local inst = findNet("Plots: RequestBaseUpgrade")
    if inst and type(inst.FireServer) == "function" then
        local ok = pcall(function()
            inst:FireServer()
        end)
        return ok == true
    end
    if type(Network) == "table" and type(Network.Fire) == "function" then
        local ok = pcall(Network.Fire, "Plots: RequestBaseUpgrade")
        return ok == true
    end
    return false
end

local function invokeTreadmillUpgrade(id)
    bindGame()
    local tm = Network and Network.Treadmill
    local rf = tm and tm.AskTierRaise
    if (typeof(rf) == "Instance" or type(rf) == "table") and type(rf.InvokeServer) == "function" then
        local ok, a, b = pcall(function()
            return rf:InvokeServer(id)
        end)
        if ok then
            return a == true, b
        end
        return false, a
    end
    local inst = findNet("Treadmills: RequestUpgrade")
    if inst and type(inst.InvokeServer) == "function" then
        local ok, a, b = pcall(function()
            return inst:InvokeServer(id)
        end)
        if ok then
            return a == true, b
        end
        return false, a
    end
    if type(Network) == "table" and type(Network.Invoke) == "function" then
        local ok, a, b = pcall(Network.Invoke, "Treadmills: RequestUpgrade", id)
        if ok then
            return a == true, b
        end
        return false, a
    end
    return false, "remote missing"
end

local function invokeTrail(method, named, id)
    bindGame()
    local tw = Network and Network.Trailwear
    local rf = tw and tw[method]
    if (typeof(rf) == "Instance" or type(rf) == "table") and type(rf.InvokeServer) == "function" then
        local ok, a, b = pcall(function()
            if id ~= nil then
                return rf:InvokeServer(id)
            end
            return rf:InvokeServer()
        end)
        if ok then
            return a == true, b
        end
        return false, a
    end
    local inst = findNet(named)
    if inst and type(inst.InvokeServer) == "function" then
        local ok, a, b = pcall(function()
            if id ~= nil then
                return inst:InvokeServer(id)
            end
            return inst:InvokeServer()
        end)
        if ok then
            return a == true, b
        end
        return false, a
    end
    if type(Network) == "table" and type(Network.Invoke) == "function" then
        local ok, a, b
        if id ~= nil then
            ok, a, b = pcall(Network.Invoke, named, id)
        else
            ok, a, b = pcall(Network.Invoke, named)
        end
        if ok then
            return a == true, b
        end
        return false, a
    end
    return false, "remote missing"
end

local function trailDir()
    bindGame()
    if type(Trails) ~= "table" then
        return nil
    end
    if type(Trails.Directory) == "table" then
        return Trails.Directory
    end
    return Trails
end

local function trailOwned(data, id)
    local bag = type(data) == "table" and data.TrailInventory
    return type(bag) == "table" and bag[id] == true
end

local function shopTrails()
    local dir = trailDir()
    local list = {}
    if type(dir) ~= "table" then
        return list
    end
    for id, cfg in pairs(dir) do
        if type(cfg) == "table" and cfg.DisplayInShop ~= false then
            list[#list + 1] = {
                id = tostring(cfg._id or id),
                name = tostring(cfg.DisplayName or cfg._id or id),
                price = tonumber(cfg.Price) or 0,
                speed = tonumber(cfg.SpeedMultiplier) or 0,
            }
        end
    end
    table.sort(list, function(a, b)
        if a.price ~= b.price then
            return a.price < b.price
        end
        return a.speed < b.speed
    end)
    return list
end

local function nextPen(data)
    local level = tonumber(data and data.BaseUpgradeLevel) or 0
    local nxt = level + 1
    local cfg
    if type(Bases) == "table" and type(Bases.BASES) == "table" then
        cfg = Bases.BASES[nxt]
    end
    return nxt, cfg
end

local function nextTreadmill(data)
    local level = tonumber(data and data.TreadmillUpgradeLevel) or 0
    local nxt = level + 1
    local cfg
    if type(Treadmills) == "table" and type(Treadmills.GetByUpgradeLevel) == "function" then
        local ok, v = pcall(Treadmills.GetByUpgradeLevel, nxt)
        if ok then
            cfg = v
        end
    end
    return nxt, cfg
end

local function slotCount(level)
    level = tonumber(level) or 0
    if type(Bases) == "table" then
        if type(Bases.GetAssetEquipCapacity) == "function" then
            local ok, n = pcall(Bases.GetAssetEquipCapacity, level)
            if ok and tonumber(n) then
                return tonumber(n)
            end
        end
        local cfg = Bases.BASES and Bases.BASES[level]
        if type(cfg) == "table" then
            return tonumber(cfg.MaxAssets) or 0
        end
    end
    return 0
end

local function anyOn()
    return M.pen == true or M.slots == true or M.treadmill == true or M.trail == true
end

local function stillOn()
    return GEN == G.__StealEggUpgradeGen and anyOn()
end

local function tryPen(data)
    local nxt, cfg = nextPen(data)
    local tag = M.pen == true and "Pen" or "Slot"
    if type(cfg) ~= "table" then
        return "max", tag .. " max"
    end
    local cost = tonumber(cfg.Cost) or 0
    local money = tonumber(data.Money) or 0
    if money < cost then
        return "wait", "need $" .. fmtMoney(cost)
    end
    local before = tonumber(data.BaseUpgradeLevel) or 0
    local fromN = slotCount(before)
    local toN = slotCount(nxt)
    if M.slots == true then
        emit("Slot", "live", string.format("%d > %d", fromN, toN))
    else
        emit("Pen", "live", string.format("Lv %d > %d", before, nxt))
    end
    if not firePen() then
        return "fail", string.lower(tag) .. " remote"
    end
    local t0 = os.clock()
    while stillOn() and os.clock() - t0 < 6 do
        task.wait(0.25)
        local now = getSave()
        if now and (tonumber(now.BaseUpgradeLevel) or 0) > before then
            local lv = tonumber(now.BaseUpgradeLevel) or nxt
            if M.slots == true then
                emit("Slot", "success", "slot " .. tostring(slotCount(lv)))
                return "ok", "slot " .. tostring(slotCount(lv))
            end
            emit("Pen", "success", "Lv " .. tostring(lv))
            return "ok", "Lv " .. tostring(lv)
        end
    end
    return "wait", string.lower(tag) .. " pending"
end

local function tryTreadmill(data)
    local baseLv = tonumber(data.BaseUpgradeLevel) or 0
    if baseLv <= 0 then
        return "wait", "need pen first"
    end
    local nxt, cfg = nextTreadmill(data)
    if type(cfg) ~= "table" then
        return "max", "Treadmill max"
    end
    local id = cfg._id
    if id == nil or id == "" then
        return "fail", "no treadmill id"
    end
    local price = tonumber(cfg.Price) or 0
    local money = tonumber(data.Money) or 0
    if money < price then
        return "wait", "need $" .. fmtMoney(price)
    end
    local name = tostring(cfg.DisplayName or id)
    emit("Belt", "live", name)
    local ok, err = invokeTreadmillUpgrade(id)
    if ok == true then
        emit("Belt", "success", name)
        return "ok", name
    end
    return "fail", tostring(err or "treadmill fail")
end

local function tryTrail(data)
    local list = shopTrails()
    if #list == 0 then
        return "fail", "no trails"
    end
    local money = tonumber(data.Money) or 0
    local nextBuy
    local ownedN = 0
    local best
    for i = 1, #list do
        local item = list[i]
        if trailOwned(data, item.id) then
            ownedN += 1
            if not best or item.speed > best.speed then
                best = item
            end
        elseif not nextBuy then
            nextBuy = item
        end
    end
    if nextBuy then
        if money < nextBuy.price then
            return "wait", "need $" .. fmtMoney(nextBuy.price)
        end
        emit("Trail", "live", nextBuy.name)
        local ok, err = invokeTrail("AskPurchase", "Trails: RequestPurchase", nextBuy.id)
        if ok ~= true then
            return "fail", tostring(err or "trail buy")
        end
        local t0 = os.clock()
        while stillOn() and os.clock() - t0 < 4 do
            task.wait(0.2)
            local now = getSave()
            if now and trailOwned(now, nextBuy.id) then
                data = now
                break
            end
        end
        invokeTrail("AskChoose", "Trails: RequestSelect", nextBuy.id)
        emit("Trail", "success", nextBuy.name)
        return "ok", nextBuy.name
    end
    if best and tostring(data.EquippedTrail or "") ~= best.id then
        local ok = invokeTrail("AskChoose", "Trails: RequestSelect", best.id)
        if ok == true then
            emit("Trail", "success", best.name)
            return "ok", best.name
        end
    end
    if ownedN >= #list then
        return "max", "Trails max"
    end
    return "wait", "trail pending"
end

local function loop(token)
    while GEN == G.__StealEggUpgradeGen and token == M._token and stillOn() do
        bindGame()
        local data = getSave()
        if type(data) ~= "table" then
            emit("Wait", "warn", "save")
            task.wait(1)
        else
            local delay = math.clamp(tonumber(M.delay) or 1.2, 0.4, 8)
            local did = false
            if M.pen == true or M.slots == true then
                local st, detail = tryPen(data)
                if st == "ok" then
                    did = true
                    task.wait(delay)
                    data = getSave() or data
                elseif st == "max" and M.treadmill ~= true and M.trail ~= true then
                    emit("Idle", "muted", detail)
                elseif st == "wait" then
                    emit("Wait", "warn", detail)
                elseif st == "fail" then
                    emit("Failed", "error", detail)
                end
            end
            if M.treadmill == true and stillOn() and token == M._token then
                data = getSave() or data
                local st, detail = tryTreadmill(data)
                if st == "ok" then
                    did = true
                    task.wait(delay)
                    data = getSave() or data
                elseif st == "max" and M.pen ~= true and M.slots ~= true and M.trail ~= true then
                    emit("Idle", "muted", detail)
                elseif st == "wait" then
                    emit("Wait", "warn", detail)
                elseif st == "fail" then
                    emit("Failed", "error", detail)
                end
            end
            if M.trail == true and stillOn() and token == M._token then
                data = getSave() or data
                local st, detail = tryTrail(data)
                if st == "ok" then
                    did = true
                elseif st == "max" and M.pen ~= true and M.slots ~= true and M.treadmill ~= true then
                    emit("Idle", "muted", detail)
                elseif st == "wait" then
                    emit("Wait", "warn", detail)
                elseif st == "fail" then
                    emit("Failed", "error", detail)
                end
            end
            if not did then
                task.wait(delay)
            end
        end
    end
    if token == M._token and not anyOn() then
        emit("Idle", "muted", "off")
    end
    if token == M._token then
        M._loopOn = false
    end
end

local function ensureLoop()
    if M._loopOn == true then
        return
    end
    if not anyOn() then
        return
    end
    M._token = (tonumber(M._token) or 0) + 1
    local token = M._token
    M._loopOn = true
    emit("On", "live", "scanning")
    task.spawn(function()
        loop(token)
    end)
end

function M.setPen(on)
    M.pen = on == true
    if not anyOn() then
        M._token = (tonumber(M._token) or 0) + 1
        emit("Idle", "muted", "off")
        return
    end
    ensureLoop()
end

function M.setSlots(on)
    M.slots = on == true
    if not anyOn() then
        M._token = (tonumber(M._token) or 0) + 1
        emit("Idle", "muted", "off")
        return
    end
    ensureLoop()
end

function M.setTreadmill(on)
    M.treadmill = on == true
    if not anyOn() then
        M._token = (tonumber(M._token) or 0) + 1
        emit("Idle", "muted", "off")
        return
    end
    ensureLoop()
end

function M.setTrail(on)
    M.trail = on == true
    if not anyOn() then
        M._token = (tonumber(M._token) or 0) + 1
        emit("Idle", "muted", "off")
        return
    end
    ensureLoop()
end

function M.setEnabled(on)
    on = on == true
    M.setPen(on)
    M.setSlots(on)
    M.setTreadmill(on)
    M.setTrail(on)
end

function M.Stop()
    M.pen = false
    M.slots = false
    M.treadmill = false
    M.trail = false
    M._token = (tonumber(M._token) or 0) + 1
    M._loopOn = false
    emit("Idle", "muted", "off")
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["steal.gear.upgrade.delay"] or values["misc.upgrade.delay"])
    if delay then
        M.delay = math.clamp(delay, 0.4, 8)
    end
    local pen = values["steal.gear.upgrade.pen"]
    if pen == nil then
        pen = values["misc.upgrade.pen"]
    end
    if pen ~= nil then
        M.setPen(Core.flagOn(pen))
    end
    local slots = values["steal.gear.upgrade.slots"]
    if slots ~= nil then
        M.setSlots(Core.flagOn(slots))
    end
    local belt = values["steal.gear.upgrade.treadmill"]
    if belt == nil then
        belt = values["misc.upgrade.treadmill"]
    end
    if belt ~= nil then
        M.setTreadmill(Core.flagOn(belt))
    end
    local trail = values["steal.gear.upgrade.trail"]
    if trail ~= nil then
        M.setTrail(Core.flagOn(trail))
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body, _, statusApi = ui:CreateSection({
        title = "Auto Upgrade",
        expanded = false,
        status = {
            id = "steal.gear.upgrade.status",
            persist = false,
            value = M._status.text,
            style = M._status.style,
            detail = M._status.detail,
        },
    })
    M.setStatusListener(function(st)
        statusApi.set(st.text)
        statusApi.setStyle(st.style)
        statusApi.setDetail(st.detail)
    end)

    local group = ui:CreateGroup(body)
    ui:CreateRowInput(group, {
        id = "steal.gear.upgrade.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or 1.2),
        clearOnFocus = false,
        onChanged = function(text)
            M.delay = math.clamp(tonumber(text) or 1.2, 0.4, 8)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.gear.upgrade.pen",
        label = "Auto Pen",
        persist = true,
        initial = M.pen == true,
        onChanged = function(on)
            M.setPen(on == true)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.gear.upgrade.slots",
        label = "Auto Pet Slot",
        persist = true,
        initial = M.slots == true,
        onChanged = function(on)
            M.setSlots(on == true)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.gear.upgrade.treadmill",
        label = "Auto Treadmill",
        persist = true,
        initial = M.treadmill == true,
        onChanged = function(on)
            M.setTreadmill(on == true)
        end,
    })
    ui:CreateRowToggle(group, {
        id = "steal.gear.upgrade.trail",
        label = "Auto Trail Shop",
        persist = true,
        initial = M.trail == true,
        onChanged = function(on)
            M.setTrail(on == true)
        end,
    })

    M.syncFrom(ui:GetValues() or {})
end

function M.Register(ui)
    M.RegisterSection(ui)
end

return M
 end, required = true },
    { key = "Claim",     name = "Claim",         factory = function() -- Auto Claim — remote only, no walk.
-- Dump:
--   Codex.AskRedeemAll / AskRedeemLimitedEgg
--     fallback Index: RequestClaimAll / RequestClaimLimitedEggReward
--   AwayEarnings.FetchSummary + AskCollect { Kind = "Claim" }
--   GroupPerk.RedeemPerk(true) if not ClaimedGroupReward
--   FreeGifts: RequestClaim(giftId)  WaitTime + FreeGiftsClaimed
--   MonsterParasite.AskChestTake / AskChestClaim / AskChestRevealComplete

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local HttpService = game:GetService("HttpService")
local Workspace = game:GetService("Workspace")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G
local Core = G.StealEggCore
if type(Core) ~= "table" or type(Core.require) ~= "function" then
    error("[StealEgg] Core missing — stitch STEALEGG_CORE before Claim", 0)
end

G.__StealEggClaimGen = (tonumber(G.__StealEggClaimGen) or 0) + 1
local GEN = G.__StealEggClaimGen

local CFG = {
    delay = 2,
    groupId = 825735094,
}

local M = {
    index = false,
    offline = false,
    group = false,
    gifts = false,
    limited = false,
    chest = false,
    delay = CFG.delay,
    _token = 0,
    _loopOn = false,
    _status = { text = "Idle", style = "muted", detail = "—" },
    _onStatus = nil,
}

local prev = G.StealEggClaim
if type(prev) == "table" and prev ~= M then
    pcall(function()
        if type(prev.Stop) == "function" then
            prev.Stop()
        end
        prev.index = false
        prev.offline = false
        prev.group = false
        prev.gifts = false
        prev.limited = false
        prev.chest = false
        prev._token = (tonumber(prev._token) or 0) + 999
    end)
end
G.StealEggClaim = M

local tryRequire = Core.require
local Remotes, Network, Save, GiftsDir, Constants

local function bindGame()
    Remotes = Remotes or tryRequire("Shared.Remotes") or tryRequire("Library.Client.Network")
    Network = Network or tryRequire("Library.Client.Network")
    Save = Save or tryRequire("Library.Client.Save")
    GiftsDir = GiftsDir or tryRequire("Directory.FreeGifts")
    Constants = Constants or tryRequire("Shared.Globals.Constants") or tryRequire("Library.Globals.Constants")
end

local function emit(text, style, detail)
    M._status = {
        text = tostring(text or "Idle"),
        style = style or "muted",
        detail = tostring(detail or "—"),
    }
    local fn = M._onStatus
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

function M.setStatusListener(fn)
    M._onStatus = fn
    if type(fn) == "function" then
        pcall(fn, M._status)
    end
end

local function getSave()
    bindGame()
    if type(Save) ~= "table" or type(Save.Get) ~= "function" then
        return nil
    end
    local ok, data = pcall(Save.Get)
    if ok and type(data) == "table" then
        return data
    end
    local ok2, data2 = pcall(Save.Get, LP, false)
    if ok2 and type(data2) == "table" then
        return data2
    end
    return nil
end

local function fmtMoney(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    local sign = n < 0 and "-" or ""
    n = abs
    if n >= 1e12 then
        return sign .. string.format("%.1fT", n / 1e12)
    end
    if n >= 1e9 then
        return sign .. string.format("%.1fB", n / 1e9)
    end
    if n >= 1e6 then
        return sign .. string.format("%.1fM", n / 1e6)
    end
    if n >= 1e3 then
        return sign .. string.format("%.1fk", n / 1e3)
    end
    return sign .. string.format("%.0f", n)
end

local function findNet(name)
    local folder = ReplicatedStorage:FindFirstChild("Network")
    if not folder then
        return nil
    end
    local inst = folder:FindFirstChild(name)
    if inst then
        return inst
    end
    for _, ch in ipairs(folder:GetChildren()) do
        if ch.Name == name then
            return ch
        end
    end
    return nil
end

local function invokeRF(bag, method, named, arg)
    bindGame()
    local rf = type(bag) == "table" and bag[method]
    if (typeof(rf) == "Instance" or type(rf) == "table") and type(rf.InvokeServer) == "function" then
        local ok, a, b, c = pcall(function()
            if arg ~= nil then
                return rf:InvokeServer(arg)
            end
            return rf:InvokeServer()
        end)
        if ok then
            return true, a, b, c
        end
        return false, a
    end
    if type(named) == "string" then
        if type(Network) == "table" and type(Network.Invoke) == "function" then
            local ok, a, b, c
            if arg ~= nil then
                ok, a, b, c = pcall(Network.Invoke, named, arg)
            else
                ok, a, b, c = pcall(Network.Invoke, named)
            end
            if ok then
                return true, a, b, c
            end
        end
        local inst = findNet(named)
        if inst and type(inst.InvokeServer) == "function" then
            local ok, a, b, c = pcall(function()
                if arg ~= nil then
                    return inst:InvokeServer(arg)
                end
                return inst:InvokeServer()
            end)
            if ok then
                return true, a, b, c
            end
            return false, a
        end
    end
    return false, "remote missing"
end

local function okTrue(a)
    if type(a) == "table" then
        return a[1] == true
    end
    return a == true
end

local function recOk(a)
    if type(a) == "table" then
        return a.Success == true or a[1] == true
    end
    return a == true
end

local function anyOn()
    return M.index == true
        or M.offline == true
        or M.group == true
        or M.gifts == true
        or M.limited == true
        or M.chest == true
end

local function stillOn()
    return GEN == G.__StealEggClaimGen and anyOn()
end

local function tryIndex()
    bindGame()
    local bag = Remotes and Remotes.Codex
    emit("Index", "live", "claim all")
    local called, a, b = invokeRF(bag, "AskRedeemAll", "Index: RequestClaimAll")
    if not called then
        return "fail", "index remote"
    end
    if okTrue(a) then
        local n = 0
        if type(b) == "table" then
            n = #b
        end
        emit("Index", "success", n > 0 and (tostring(n) .. " claimed") or "claimed")
        return "ok", "index"
    end
    return "skip", "index none"
end

local function tryOffline()
    bindGame()
    local bag = Remotes and Remotes.AwayEarnings
    local called, summary = invokeRF(bag, "FetchSummary", nil)
    local amount = 0
    if called and type(summary) == "table" then
        amount = tonumber(summary.ClaimableAmount or summary.TotalAmount or summary.AwardedAmount) or 0
    end
    if amount <= 0 and called == true then
        return "skip", "offline none"
    end
    emit("Offline", "live", amount > 0 and ("$" .. fmtMoney(amount)) or "claim")
    local ok, a, _, c = invokeRF(bag, "AskCollect", nil, { Kind = "Claim" })
    if not ok then
        return "fail", "offline remote"
    end
    if not okTrue(a) then
        return "skip", "offline none"
    end
    local got = 0
    if type(c) == "table" then
        got = tonumber(c.AwardedAmount) or amount
    elseif type(a) == "table" then
        got = tonumber(a.AwardedAmount) or amount
    else
        got = amount
    end
    emit("Offline", "success", "$" .. fmtMoney(got))
    return "ok", "offline"
end

local function tryGroup()
    bindGame()
    local data = getSave()
    if type(data) == "table" and data.ClaimedGroupReward == true then
        return "max", "group done"
    end
    local gid = tonumber(Constants and Constants.GROUP_ID) or CFG.groupId
    local inGroup = false
    pcall(function()
        inGroup = LP:IsInGroup(gid) == true
    end)
    if inGroup ~= true then
        return "wait", "join group"
    end
    emit("Group", "live", "claim")
    local bag = Remotes and Remotes.GroupPerk
    local called, a = invokeRF(bag, "RedeemPerk", nil, true)
    if not called then
        return "fail", "group remote"
    end
    if okTrue(a) then
        emit("Group", "success", "claimed")
        return "ok", "group"
    end
    return "skip", "group denied"
end

local function giftList()
    bindGame()
    local out = {}
    local dir = GiftsDir
    local rows = type(dir) == "table" and (dir.SortedById or dir.Directory or dir)
    if type(rows) == "table" then
        for key, cfg in pairs(rows) do
            if type(cfg) == "table" then
                local id = tonumber(cfg.Id or key)
                if id then
                    out[#out + 1] = {
                        id = id,
                        wait = tonumber(cfg.WaitTime) or 0,
                    }
                end
            end
        end
    end
    if #out == 0 then
        for i = 1, 12 do
            out[i] = { id = i, wait = 0 }
        end
    end
    table.sort(out, function(a, b)
        return a.id < b.id
    end)
    return out
end

local function tryGifts()
    bindGame()
    local data = getSave() or {}
    local claimed = type(data.FreeGiftsClaimed) == "table" and data.FreeGiftsClaimed or {}
    local started = tonumber(data.FreeGiftsActiveStartedAt or data.FreeGiftsStartedAt) or 0
    local now = 0
    pcall(function()
        now = Workspace:GetServerTimeNow()
    end)
    if now <= 0 then
        now = os.time()
    end
    local elapsed = math.max(0, now - started)
    if started <= 0 then
        elapsed = tonumber(data.FreeGiftsTime) or elapsed
    end
    local n = 0
    for _, row in ipairs(giftList()) do
        if stillOn() ~= true then
            break
        end
        local key = tostring(row.id)
        if claimed[key] ~= true and claimed[row.id] ~= true then
            if row.wait > 0 and elapsed < row.wait then
                -- not ready
            else
                emit("Gifts", "live", "gift " .. key)
                local called, a = invokeRF(nil, nil, "FreeGifts: RequestClaim", row.id)
                if called and okTrue(a) then
                    n += 1
                    claimed[key] = true
                    task.wait(0.12)
                end
            end
        end
    end
    if n > 0 then
        emit("Gifts", "success", tostring(n) .. " gift")
        return "ok", "gifts"
    end
    return "skip", "gifts none"
end

local function tryLimited()
    bindGame()
    emit("Limited", "live", "index egg")
    local bag = Remotes and Remotes.Codex
    local called, a = invokeRF(bag, "AskRedeemLimitedEgg", "Index: RequestClaimLimitedEggReward")
    if not called then
        return "fail", "limited remote"
    end
    if okTrue(a) then
        emit("Limited", "success", "claimed")
        return "ok", "limited"
    end
    return "skip", "limited none"
end

local function hasChestTool()
    local function scan(folder)
        if not folder then
            return false
        end
        local kids = folder:GetChildren()
        for i = 1, #kids do
            local ch = kids[i]
            if ch:IsA("Tool") then
                if ch:GetAttribute("ItemType") == "MonsterChest" or ch.Name == "Monster Chest" then
                    return true
                end
            end
        end
        return false
    end
    return scan(LP.Character) or scan(LP:FindFirstChild("Backpack"))
end

local function monsterBag()
    bindGame()
    return Remotes and Remotes.MonsterParasite
end

local function tryChest()
    local bag = monsterBag()
    local opened = 0

    local called, snap = invokeRF(bag, "AskSnapshot")
    local state = nil
    if called and type(snap) == "table" then
        state = snap.State
    end
    if type(state) ~= "table" then
        local data = getSave()
        state = type(data) == "table" and data.MonsterParasite or nil
    end

    local pendingReward = type(state) == "table" and state.PendingReward
    if type(pendingReward) == "table" and type(pendingReward.OpeningId) == "string" then
        emit("Chest", "live", "reveal")
        local ok, a = invokeRF(bag, "AskChestRevealComplete", nil, pendingReward.OpeningId)
        if ok and recOk(a) then
            opened += 1
        end
    end

    local takeOk, takeRes = invokeRF(bag, "AskChestTake")
    local pending = tonumber(type(state) == "table" and state.PendingChests) or 0
    if recOk(takeRes) then
        pending = math.max(pending, 1)
    end
    if pending <= 0 and hasChestTool() then
        pending = 1
    end
    if pending <= 0 and opened <= 0 then
        return "skip", "chest none"
    end

    local rounds = math.clamp(pending, 1, 6)
    for i = 1, rounds do
        if stillOn() ~= true then
            break
        end
        emit("Chest", "live", "open " .. tostring(i))
        local guid = HttpService:GenerateGUID(false)
        local ok, a = invokeRF(bag, "AskChestClaim", nil, guid)
        if not ok or not recOk(a) then
            break
        end
        local oid = type(a) == "table" and a.OpeningId or guid
        task.wait(0.35)
        invokeRF(bag, "AskChestRevealComplete", nil, oid)
        opened += 1
        if type(a) == "table" then
            local left = tonumber(a.PendingChests)
            if type(left) == "number" and left <= 0 then
                break
            end
        end
        task.wait(0.15)
    end

    if opened > 0 then
        emit("Chest", "success", tostring(opened) .. " chest")
        return "ok", "chest"
    end
    return "skip", "chest none"
end

local JOBS = {
    { key = "index", fn = tryIndex },
    { key = "offline", fn = tryOffline },
    { key = "group", fn = tryGroup },
    { key = "gifts", fn = tryGifts },
    { key = "limited", fn = tryLimited },
    { key = "chest", fn = tryChest },
}

local function loop(token)
    while GEN == G.__StealEggClaimGen and token == M._token and stillOn() do
        bindGame()
        local delay = math.clamp(tonumber(M.delay) or CFG.delay, 0.8, 15)
        local did = false
        local waiting
        for i = 1, #JOBS do
            if stillOn() ~= true or token ~= M._token then
                break
            end
            local job = JOBS[i]
            if M[job.key] == true then
                local st, detail = job.fn()
                if st == "ok" then
                    did = true
                    task.wait(0.2)
                elseif st == "wait" then
                    waiting = detail
                elseif st == "fail" then
                    emit("Failed", "error", tostring(detail or job.key))
                    task.wait(0.4)
                end
            end
        end
        if not did then
            if waiting then
                emit("Wait", "warn", waiting)
            elseif stillOn() then
                emit("Idle", "muted", "nothing to claim")
            end
            task.wait(delay)
        else
            task.wait(delay)
        end
    end
    if token == M._token and not anyOn() then
        emit("Idle", "muted", "off")
    end
    if token == M._token then
        M._loopOn = false
    end
end

local function ensureLoop()
    if M._loopOn == true then
        return
    end
    if not anyOn() then
        return
    end
    M._token = (tonumber(M._token) or 0) + 1
    local token = M._token
    M._loopOn = true
    emit("On", "live", "scanning")
    task.spawn(function()
        loop(token)
    end)
end

local function setFlag(key, on)
    M[key] = on == true
    if not anyOn() then
        M._token = (tonumber(M._token) or 0) + 1
        emit("Idle", "muted", "off")
        return
    end
    ensureLoop()
end

function M.setIndex(on)
    setFlag("index", on)
end
function M.setOffline(on)
    setFlag("offline", on)
end
function M.setGroup(on)
    setFlag("group", on)
end
function M.setGifts(on)
    setFlag("gifts", on)
end
function M.setLimited(on)
    setFlag("limited", on)
end
function M.setChest(on)
    setFlag("chest", on)
end

function M.setEnabled(on)
    on = on == true
    M.setIndex(on)
    M.setOffline(on)
    M.setGroup(on)
    M.setGifts(on)
    M.setLimited(on)
    M.setChest(on)
end

function M.Stop()
    M.index = false
    M.offline = false
    M.group = false
    M.gifts = false
    M.limited = false
    M.chest = false
    M._token = (tonumber(M._token) or 0) + 1
    M._loopOn = false
    emit("Idle", "muted", "off")
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local delay = tonumber(values["steal.gear.claim.delay"])
    if delay then
        M.delay = math.clamp(delay, 0.8, 15)
    end
    local map = {
        index = "steal.gear.claim.index",
        offline = "steal.gear.claim.offline",
        group = "steal.gear.claim.group",
        gifts = "steal.gear.claim.gifts",
        limited = "steal.gear.claim.limited",
        chest = "steal.gear.claim.chest",
    }
    for key, id in pairs(map) do
        local v = values[id]
        if v ~= nil then
            setFlag(key, Core.flagOn(v))
        end
    end
end

function M.RegisterSection(ui)
    local pre = ui:GetValues() or {}
    M.syncFrom(pre)

    local body = ui:CreateSection({
        title = "Auto Claim",
        expanded = false,
    })

    local group = ui:CreateGroup(body)
    ui:CreateRowInput(group, {
        id = "steal.gear.claim.delay",
        label = "Delay · sec",
        persist = true,
        initial = tostring(M.delay or CFG.delay),
        clearOnFocus = false,
        onChanged = function(text)
