local function wrapFieldStack(parent)
    local wrap = Instance.new("Frame")
    wrap.Name = "FieldStack"
    wrap.BackgroundTransparency = 1
    wrap.BorderSizePixel = 0
    wrap.Size = UDim2.new(1, 0, 0, 0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y
    wrap.LayoutOrder = #parent:GetChildren() + 1
    wrap.Parent = parent
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, 8)
    list.Parent = wrap
    return wrap
end

local function publicDetail(text, detail)
    detail = tostring(detail or "")
    if detail == "" then
        return "—"
    end
    local low = string.lower(detail)
    if string.find(low, "remote", 1, true) or string.find(low, "uid", 1, true)
        or string.find(low, "favourite", 1, true) or string.find(low, "favorite", 1, true) and string.find(low, "write", 1, true) then
        return "—"
    end
    if #detail > 28 then
        return "—"
    end
    return detail
end

local function emit(kind, text, style, detail)
    local st = M[kind]
    if type(st) ~= "table" then
        return
    end
    text = tostring(text or "Idle")
    if text == "Denied" or text == "Error" then
        text = "Failed"
        detail = "—"
    elseif text == "Idle" then
        local low = string.lower(tostring(detail or ""))
        if string.find(low, "no match", 1, true) then
            detail = "no match"
        elseif string.find(low, "set rules", 1, true) then
            detail = "set rules"
        elseif string.find(low, "off", 1, true) then
            detail = "off"
        end
    end
    st._status = {
        text = text,
        style = style or "muted",
        detail = publicDetail(text, detail),
    }
    local fn = st._onStatus
    if type(fn) == "function" then
        pcall(fn, st._status)
    end
end

function M.setFavStatusListener(fn)
    M.fav._onStatus = type(fn) == "function" and fn or nil
    if M.fav._onStatus then
        pcall(M.fav._onStatus, M.fav._status)
    end
end

function M.setUnfavStatusListener(fn)
    M.unfav._onStatus = type(fn) == "function" and fn or nil
    if M.unfav._onStatus then
        pcall(M.unfav._onStatus, M.unfav._status)
    end
end

local function mapHas(map)
    return type(map) == "table" and next(map) ~= nil
end

local function copyMap(value)
    return parseKeyMap(value)
end

local function mapKeyList(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for key, on in pairs(map) do
        if on == true or on == 1 or on == "true" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function newRuleId()
    return "fv" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
end

local function clampCompareMode(mode, fallback)
    mode = string.lower(tostring(mode or ""))
    if mode == "above" or mode == "below" then
        return mode
    end
    fallback = string.lower(tostring(fallback or DEFAULT_COMPARE_MODE))
    if fallback == "below" then
        return "below"
    end
    return "above"
end

local function unsignedRuleText(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt:sub(1, 1) == "+" or txt:sub(1, 1) == "-" then
        txt = txt:sub(2)
    end
    if txt == "" then
        return "0"
    end
    return txt
end

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then
        return nil
    end
    local sign = 1
    if txt:sub(1, 1) == "+" then
        txt = txt:sub(2)
    elseif txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "t", 1e12 },
        { "b", 1e9 },
        { "m", 1e6 },
        { "k", 1e3 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then
                return n * mult * sign
            end
        end
    end
    local n = tonumber(txt)
    if n then
        return n * sign
    end
    return nil
end

local function parseSignedRule(txt, explicitMode)
    txt = tostring(txt or ""):gsub("%s+", ""):gsub(",", "")
    local signedBelow = txt:sub(1, 1) == "-"
    local n = tonumber(txt)
    if not n then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), "0"
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(txt)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(txt)
end

local function parseSignedScaledRule(txt, explicitMode)
    local raw = tostring(txt or ""):gsub("%s+", "")
    local signedBelow = raw:sub(1, 1) == "-"
    local n = parseScaledNumber(raw)
    if not n or n == 0 then
        return 0, clampCompareMode(explicitMode, signedBelow and "below" or DEFAULT_COMPARE_MODE), (raw == "" and "0" or unsignedRuleText(raw))
    end
    if n < 0 or signedBelow then
        return math.abs(n), clampCompareMode(explicitMode, "below"), unsignedRuleText(raw)
    end
    return n, clampCompareMode(explicitMode, DEFAULT_COMPARE_MODE), unsignedRuleText(raw)
end

local function isNoMutationKey(key)
    key = string.lower(tostring(key or ""))
    return key == "no mutation" or key == "none" or key == "normal"
end

local function sanitizeRule(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local kg, kgMode, kgRule = parseSignedRule(rule.kgRule, rule.kgMode)
    local rate, rateMode, rateRule = parseSignedScaledRule(rule.rateRule, rule.rateMode)
    local price, priceMode, priceRule = parseSignedScaledRule(rule.priceRule, rule.priceMode)
    local fields = {}
    local srcFields = type(rule.fields) == "table" and rule.fields or nil
    if srcFields then
        for _, key in ipairs({ "rarity", "name", "mutation", "size", "kg", "rate", "price" }) do
            if srcFields[key] == true or srcFields[key] == 1 or srcFields[key] == "true" then
                fields[key] = true
            end
        end
    end
    return {
        id = tostring(rule.id or newRuleId()),
        enabled = rule.enabled ~= false,
        fields = fields,
        rarities = copyMap(rule.rarities),
        names = copyMap(rule.names),
        mutations = copyMap(rule.mutations),
        sizes = copyMap(rule.sizes),
        kg = kg,
        kgMode = kgMode,
        kgRule = kgRule,
        rate = rate,
        rateMode = rateMode,
        rateRule = rateRule,
        price = price,
        priceMode = priceMode,
        priceRule = priceRule,
    }
end

local function sanitizeRules(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = sanitizeRule(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

local function enabledRules(st)
    local out = {}
    if type(st) ~= "table" or type(st.rules) ~= "table" then
        return out
    end
    for _, rule in ipairs(st.rules) do
        if type(rule) == "table" and rule.enabled ~= false then
            out[#out + 1] = rule
        end
    end
    return out
end

local function getSave()
    bindGame()
    if type(Save) == "table" and type(Save.Cache) == "function" then
        local okC, bag = pcall(Save.Cache)
        if okC and type(bag) == "table" then
            local data = bag[LP]
            if type(data) == "table" then
                return data
            end
        end
    end
    if type(Save) == "table" and type(Save.Get) == "function" then
        local ok, data = pcall(Save.Get, LP, true)
        if ok and type(data) == "table" then
            return data
        end
        ok, data = pcall(Save.Get)
        if ok then
            return data
        end
    end
    return nil
end

local function assetDir()
    local a = Assets
    if type(a) ~= "table" then
        return nil
    end
    if type(a.Directory) == "table" then
        return a.Directory
    end
    return a
end

local function rarityOf(category)
    local dir = assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local r = type(cfg) == "table" and cfg.Rarity
    if type(r) ~= "table" then
        return 0, "", tostring(category)
    end
    local num = tonumber(r.RarityNumber) or 0
    local id = tostring(r._id or r.DisplayName or r.Name or "")
    local name = tostring(cfg.DisplayName or cfg.Name or cfg._id or category)
    return num, id, name
end

local function displayOf(category)
    local _, _, name = rarityOf(category)
    return name
end

local function rarityName(key)
    for _, item in ipairs(Core.RARITY_ITEMS or {}) do
        if tostring(item.key) == tostring(key) then
            return tostring(item.name or key)
        end
    end
    return tostring(key)
end

local function deserializePet(raw)
    if type(raw) ~= "table" then
        return nil
    end
    if raw.Category ~= nil then
        return raw
    end
    if type(AssetItems) == "table" then
        local fn = AssetItems.Deserialize or AssetItems.Decode
        if type(fn) == "function" then
            local ok, item = pcall(fn, raw)
            if ok and type(item) == "table" then
                return item
            end
        end
    end
    return nil
end

local function mutationNames(data)
    local out, seen = {}, {}
    local function add(name)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        out[#out + 1] = name
    end
    if type(data) ~= "table" then
        return out
    end
    if type(data.Mutations) == "table" then
        for _, name in ipairs(data.Mutations) do
            add(name)
        end
        for _, name in pairs(data.Mutations) do
            if type(name) == "string" then
                add(name)
            end
        end
    end
    add(data.BaseMutation)
    return out
end

local function itemKg(category, scale)
    scale = tonumber(scale) or 0
    if type(AssetItems) == "table" then
        local fn = AssetItems.GetVisualWeightKg or AssetItems.WeightKg
        if type(fn) == "function" then
            local ok, kg = pcall(fn, { Category = category, Scale = scale, Mutations = {} })
            if ok then
                return tonumber(kg) or 0
            end
        end
    end
    local dir = assetDir()
    local cfg = type(dir) == "table" and (dir[category] or dir[tostring(category)])
    local weight = type(cfg) == "table" and tonumber(cfg.ModelWeight) or 1
    return weight * math.max(scale, 0) ^ 3
end

local function itemRate(assetData, saveData)
    if type(assetData) ~= "table" then
        return 0
    end
    if type(AssetEarn) == "table" then
        local rateFn = AssetEarn.GetRate or AssetEarn.RatePerSecond
        if type(rateFn) == "function" then
            local rebirth = type(saveData) == "table" and tonumber(saveData.Rebirth) or 0
            local ok, n = pcall(rateFn, assetData, rebirth or 0, saveData and saveData.Gamepasses, saveData and saveData.Products)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    return 0
end

local function itemPrice(assetData, rate)
    if type(GetPrice) == "function" then
        local ok, n = pcall(GetPrice, assetData)
        if ok then
            return math.max(0, tonumber(n) or 0)
        end
    elseif type(GetPrice) == "table" then
        local fn = GetPrice.SalePrice or GetPrice.GetPriceValueForItem
        if type(fn) == "function" then
            local ok, n = pcall(fn, assetData)
            if ok then
                return math.max(0, tonumber(n) or 0)
            end
        end
    end
    return math.max(0, (tonumber(rate) or 0) * 100)
end

local function sizeKey(scale)
    scale = tonumber(scale) or 0
    if scale >= 45 then
        return "gargantuan"
    end
    if scale >= 25 then
        return "titanic"
    end
    if scale >= 10 then
        return "huge"
    end
    if scale >= 5 then
        return "big"
    end
    return "normal"
end

local function sizeLabel(key)
    key = string.lower(tostring(key or ""))
    for _, item in ipairs(SIZE_ITEMS) do
        if item.key == key then
            return item.name
        end
    end
    return key
end

local function matchesName(category, names)
    if not mapHas(names) then
        return true
    end
    category = tostring(category or "")
    return names[category] == true or names[string.lower(category)] == true
end

local function matchesSize(size, sizes)
    if not mapHas(sizes) then
        return true
    end
    size = string.lower(tostring(size or "normal"))
    return sizes[size] == true
end

local function matchesRarity(category, rarities)
    if not mapHas(rarities) then
        return true
    end
    local num, id = rarityOf(category)
    return rarities[tostring(num)] == true or rarities[id] == true or rarities[string.lower(id)] == true
end

local function matchesSigned(value, n, mode)
    n = tonumber(n) or 0
    if n <= 0 then
        return true
    end
    value = tonumber(value) or 0
    if mode == "above" then
        return value >= n
    end
    return value <= n
end

local function matchesMutation(muts, rule)
    local names = type(muts) == "table" and muts or {}
    local has = #names > 0
    local selected = type(rule) == "table" and rule.mutations or nil
    if not mapHas(selected) then
        return true
    end
    local wantNone, hasPick = false, false
    for key, on in pairs(selected) do
        if on == true then
            if isNoMutationKey(key) then
                wantNone = true
            else
                hasPick = true
            end
        end
    end
    if wantNone and not hasPick then
        return not has
    end
        if hasPick then
            for i = 1, #names do
                local name = names[i]
                if type(Core.mutationPicked) == "function" then
                    if Core.mutationPicked(name, selected) then
                        return true
                    end
                elseif selected[name] == true or selected[string.lower(name)] == true then
                    return true
                end
            end
        if wantNone and not has then
            return true
        end
        return false
    end
    return true
end

local function ruleFieldOn(rule, key)
    local fields = type(rule) == "table" and rule.fields or nil
    if type(fields) ~= "table" then
        return true
    end
    local has = false
    for _, on in pairs(fields) do
        if on == true then
            has = true
            break
        end
    end
    if not has then
        return true
    end
    return fields[key] == true
end

local function ruleMatches(rule, rec)
    if type(rule) ~= "table" or type(rec) ~= "table" then
        return false
    end
    if ruleFieldOn(rule, "name") and not matchesName(rec.category, rule.names) then
        return false
    end
    if ruleFieldOn(rule, "rarity") and not matchesRarity(rec.category, rule.rarities) then
        return false
    end
    if ruleFieldOn(rule, "kg") and not matchesSigned(rec.kg, rule.kg, rule.kgMode) then
        return false
    end
    if ruleFieldOn(rule, "rate") and not matchesSigned(rec.rate, rule.rate, rule.rateMode) then
        return false
    end
    if ruleFieldOn(rule, "price") and not matchesSigned(rec.price, rule.price, rule.priceMode) then
        return false
    end
    if ruleFieldOn(rule, "mutation") and not matchesMutation(rec.muts, rule) then
        return false
    end
    if ruleFieldOn(rule, "size") and not matchesSize(rec.size, rule.sizes) then
        return false
    end
    return true
end

local function itemMatches(rec, st)
    local rules = enabledRules(st)
    if #rules == 0 then
        return false
    end
    for _, rule in ipairs(rules) do
        if ruleMatches(rule, rec) then
            return true
        end
    end
    return false
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    if abs >= 1e12 then
        return string.format("%.1fT", n / 1e12)
    end
    if abs >= 1e9 then
        return string.format("%.1fB", n / 1e9)
    end
    if abs >= 1e6 then
        return string.format("%.1fM", n / 1e6)
    end
    if abs >= 1e3 then
        return string.format("%.1fK", n / 1e3)
    end
    if abs >= 10 then
        return string.format("%.0f", n)
    end
    return string.format("%.1f", n)
end

local function fmtKg(n)
    return fmtNum(n) .. "kg"
end

local function joinNames(keys, lookup)
    local names = {}
    for i, key in ipairs(keys) do
        names[i] = lookup and lookup(key) or key
    end
    return table.concat(names, ", ")
end

local function formatRule(rule)
    rule = sanitizeRule(rule) or {}
    local parts = {}
    local function add(text, style)
        text = tostring(text or "")
        if text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    local nameKeys = mapKeyList(rule.names)
    local rarityKeys = mapKeyList(rule.rarities)
    local kg = tonumber(rule.kg) or 0
    local rate = tonumber(rule.rate) or 0
    local price = tonumber(rule.price) or 0
    local mutKeys = mapKeyList(rule.mutations)
    local sizeKeys = mapKeyList(rule.sizes)
    local fields = type(rule.fields) == "table" and rule.fields or nil
    local hasFields = false
    if type(fields) == "table" then
        for _, on in pairs(fields) do
            if on == true then
                hasFields = true
                break
            end
        end
    end
    if not hasFields then
        fields = {
            name = #nameKeys > 0,
            rarity = #rarityKeys > 0,
            kg = kg > 0,
            rate = rate > 0,
            price = price > 0,
            mutation = #mutKeys > 0,
            size = #sizeKeys > 0,
        }
    end
    if fields.rarity then
        if #rarityKeys > 2 then
            add(tostring(#rarityKeys) .. " rarity", "rarity")
        elseif #rarityKeys > 0 then
            add(joinNames(rarityKeys, rarityName), "rarity")
        else
            add("Any rarity", "rarity")
        end
    end
    if fields.name then
        if #nameKeys == 0 then
            add("All pets", "fruit")
        elseif #nameKeys > 2 then
            add(tostring(#nameKeys) .. " pets", "fruit")
        else
            add(joinNames(nameKeys, displayOf), "fruit")
        end
    end
    if fields.kg then
        if kg > 0 then
            add((rule.kgMode == "below" and "below " or "above ") .. fmtKg(kg), "kg")
        else
            add("Any kg", "kg")
        end
    end
    if fields.price then
        if price > 0 then
            add((rule.priceMode == "below" and "below $" or "above $") .. fmtNum(price), "price")
        else
            add("Any $", "price")
        end
    end
    if fields.rate then
        if rate > 0 then
            add((rule.rateMode == "below" and "below " or "above ") .. fmtNum(rate) .. "/s", "price")
        else
            add("Any earn", "price")
        end
    end
    if fields.mutation then
        if #mutKeys == 0 then
            add("Any mut", "mut")
        else
            local labels = {}
            for _, key in ipairs(mutKeys) do
                labels[#labels + 1] = isNoMutationKey(key) and "Normal" or ((type(Core.mutationLabel) == "function" and Core.mutationLabel(key)) or key)
            end
            if #labels > 2 then
                add(tostring(#labels) .. " mut", "mut")
            else
                add(table.concat(labels, ", "), "mut")
            end
        end
    end
    if fields.size then
        if #sizeKeys == 0 then
            add("Any size", "kg")
        elseif #sizeKeys > 2 then
            add(tostring(#sizeKeys) .. " size", "kg")
        else
            add(joinNames(sizeKeys, sizeLabel), "kg")
        end
    end
    if #parts == 0 then
        add("All pets", "default")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

local function collectPets(kind)
    bindGame()
    local st = M[kind]
    local want = kind == "fav"
    local out = {}
    if #enabledRules(st) == 0 then
        return out
    end
    local data = getSave()
    local inv = type(data) == "table" and data.Inventory
    if type(inv) ~= "table" then
        return out
    end
    for uid, raw in pairs(inv) do
        uid = tostring(uid)
        local item = deserializePet(raw)
        if type(item) == "table" and item.InFuse ~= true then
            local isFav = item.IsFavorite == true
            if isFav == want then
                -- already in the desired state
            else
                local category = tostring(item.Category or "")
                if category ~= "" then
                    local rate = itemRate(item, data)
                    local rec = {
                        uid = uid,
                        category = category,
                        name = displayOf(category),
                        kg = itemKg(category, item.Scale),
                        size = sizeKey(item.Scale),
                        rate = rate,
                        price = itemPrice(item, rate),
                        muts = mutationNames(item),
                    }
                    if itemMatches(rec, st) then
                        out[#out + 1] = rec
                    end
                end
            end
        end
    end
    return out
end

local function writeFavourite(uid, on)
    bindGame()
    uid = tostring(uid or "")
    if uid == "" then
        return false, "no uid"
    end
    on = on == true
    local ev = Remotes and Remotes.PetSatchel and Remotes.PetSatchel.WriteFavourite
    if ev and type(ev.FireServer) == "function" then
        local ok, err = pcall(function()
            ev:FireServer(uid, on)
        end)
        if ok then
            return true
        end
        return false, tostring(err)
    end
    if type(Network) == "table" and type(Network.Fire) == "function" then
        local ok = pcall(Network.Fire, "AssetInventory: SetFavorite", uid, on)
        if ok then
            return true
        end
    end
    return false, "no remote"
end

function M.protectsUid(uid)
    uid = tostring(uid or "")
    if uid == "" or M.fav.enabled ~= true then
        return false
    end
    if #enabledRules(M.fav) == 0 then
        return false
    end
    bindGame()
    local data = getSave()
    local inv = type(data) == "table" and data.Inventory
    if type(inv) ~= "table" then
        return false
    end
    local raw = inv[uid] or inv[tonumber(uid)]
    local item = deserializePet(raw)
    if type(item) ~= "table" or item.InFuse == true then
        return false
    end
    local category = tostring(item.Category or "")
    if category == "" then
        return false
    end
    local rate = itemRate(item, data)
    local rec = {
        uid = uid,
        category = category,
        name = displayOf(category),
        kg = itemKg(category, item.Scale),
        size = sizeKey(item.Scale),
        rate = rate,
        price = itemPrice(item, rate),
        muts = mutationNames(item),
    }
    return itemMatches(rec, M.fav) == true
end

function M.flush(kind, maxN)
    kind = kind == "unfav" and "unfav" or "fav"
    local st = M[kind]
    if type(st) ~= "table" or st.enabled ~= true then
        return 0
    end
    maxN = tonumber(maxN) or 32
    if maxN < 1 then
        maxN = 1
    elseif maxN > 80 then
        maxN = 80
    end
    local want = kind == "fav"
    local n = 0
    while n < maxN do
        local list = collectPets(kind)
        if #list == 0 then
            break
        end
        local rec = list[1]
        local ok = writeFavourite(rec.uid, want)
        if not ok then
            break
        end
        n += 1
        st._done = (tonumber(st._done) or 0) + 1
        task.wait(0.08)
    end
    return n
end

local function stillOn(kind, token)
    local st = M[kind]
    return type(st) == "table" and st.enabled == true and st._token == token and G.__StealEggFavGen == GEN
end

local function idleDetail(kind)
    local st = M[kind]
    if #enabledRules(st) == 0 then
        return "set rules"
    end
    if (tonumber(st._done) or 0) > 0 then
        return (kind == "fav" and "faved " or "unfaved ") .. tostring(st._done)
    end
    return "—"
end

local function step(kind)
    local st = M[kind]
    local want = kind == "fav"
    local verb = want and "Fav" or "Unfav"
    if #enabledRules(st) == 0 then
        emit(kind, "Idle", "muted", "set rules")
        return
    end
    local list = collectPets(kind)
    if #list == 0 then
        emit(kind, "Idle", "muted", "no match")
        return
    end
    local rec = list[1]
    emit(kind, verb, "live", rec.name)
    local ok, err = writeFavourite(rec.uid, want)
    if ok then
        st._done = (tonumber(st._done) or 0) + 1
        emit(kind, "Done", "success", rec.name)
    else
        emit(kind, "Failed", "error", tostring(err or "remote"))
    end
end

local function loop(kind, token)
    while stillOn(kind, token) do
        local ok, err = pcall(step, kind)
        if not ok then
            emit(kind, "Failed", "error", tostring(err))
        end
        if not stillOn(kind, token) then
            break
        end
        local d = tonumber(M[kind].delay) or 0.35
        if d < 0.15 then
            d = 0.15
        elseif d > 5 then
            d = 5
        end
        task.wait(d)
    end
end

local function setEnabled(kind, on)
    local st = M[kind]
    on = on == true
    if on then
        if st.enabled == true and st._loopOn == true then
            return
        end
        st.enabled = true
        st._token = (tonumber(st._token) or 0) + 1
        local token = st._token
        st._loopOn = true
        emit(kind, "On", "live", idleDetail(kind))
        task.spawn(function()
            loop(kind, token)
            if st._token == token then
                st._loopOn = false
                if st.enabled ~= true then
                    emit(kind, "Idle", "muted", "off")
                end
            end
        end)
        return
    end
    st.enabled = false
    st._loopOn = false
    st._token = (tonumber(st._token) or 0) + 1
    emit(kind, "Idle", "muted", "off")
end

function M.setFavEnabled(on)
    setEnabled("fav", on)
end

function M.setUnfavEnabled(on)
    setEnabled("unfav", on)
end

function M.Stop()
    setEnabled("fav", false)
    setEnabled("unfav", false)
end

function M.listPetItems()
    local sell = G.StealEggSell
    if type(sell) == "table" and type(sell.listPetItems) == "function" then
        local ok, items = pcall(sell.listPetItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    bindGame()
    local seen, items = {}, {}
    local data = getSave()
    local bag = type(data) == "table" and data.Inventory
    if type(bag) == "table" then
        for _, raw in pairs(bag) do
            local item = deserializePet(raw)
            local category = tostring(item and item.Category or "")
            if category ~= "" and not seen[category] then
                seen[category] = true
                local num, rarityId, name = rarityOf(category)
                local label = name
                if rarityId ~= "" then
                    label = name .. " · " .. rarityId
                end
                items[#items + 1] = { key = category, name = label, sort = num }
            end
        end
    end
    table.sort(items, function(a, b)
        if a.sort == b.sort then
            return tostring(a.name) < tostring(b.name)
        end
        return (tonumber(a.sort) or 0) < (tonumber(b.sort) or 0)
    end)
    return items
end

function M.listMutationItems()
    local sell = G.StealEggSell
    if type(sell) == "table" and type(sell.listMutationItems) == "function" then
        local ok, items = pcall(sell.listMutationItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    bindGame()
    local items, seen = {}, {}
    local function add(name, label)
        name = tostring(name or "")
        if name == "" or name == "None" or seen[name] then
            return
        end
        seen[name] = true
        items[#items + 1] = { key = name, name = tostring(label or name) }
    end
    if type(Mutations) == "table" then
        local listFn = Mutations.GetMutations or Mutations.All
        if type(listFn) == "function" then
            local ok, list = pcall(listFn)
            if ok and type(list) == "table" then
                for key, info in pairs(list) do
                    if type(info) == "table" then
                        add(info.Name or info.Id or info._id or key, info.Label or info.DisplayOverride or info.Name or key)
                    elseif type(key) == "string" then
                        add(key, key)
                    end
                end
            end
        end
    end
    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    table.insert(items, 1, { key = NO_MUTATION, name = NO_MUTATION })
    return items
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    for _, kind in ipairs({ "fav", "unfav" }) do
        local st = M[kind]
        local prefix = kind == "fav" and "steal.fav" or "steal.unfav"
        if type(values[prefix .. ".rules"]) == "table" then
            st.rules = sanitizeRules(values[prefix .. ".rules"])
        end
        if values[prefix .. ".draft.rarity"] ~= nil then
            st.draft.rarities = copyMap(values[prefix .. ".draft.rarity"])
        end
        if values[prefix .. ".draft.names"] ~= nil then
            st.draft.names = copyMap(values[prefix .. ".draft.names"])
        end
        if values[prefix .. ".draft.mutations"] ~= nil then
            st.draft.mutations = copyMap(values[prefix .. ".draft.mutations"])
        end
        if values[prefix .. ".draft.sizes"] ~= nil then
            st.draft.sizes = copyMap(values[prefix .. ".draft.sizes"])
        end
        if values[prefix .. ".draft.kgRule"] ~= nil then
            local kg, kgMode, kgRule = parseSignedRule(values[prefix .. ".draft.kgRule"], values[prefix .. ".draft.kgMode"])
            st.draft.kgRule = kgRule
            st.draft.kgMode = clampCompareMode(values[prefix .. ".draft.kgMode"] or kgMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.kgMode"] ~= nil then
            st.draft.kgMode = clampCompareMode(values[prefix .. ".draft.kgMode"], DEFAULT_COMPARE_MODE)
        end
        if values[prefix .. ".draft.rateRule"] ~= nil then
            local rate, rateMode, rateRule = parseSignedScaledRule(values[prefix .. ".draft.rateRule"], values[prefix .. ".draft.rateMode"])
            st.draft.rateRule = rateRule
            st.draft.rateMode = clampCompareMode(values[prefix .. ".draft.rateMode"] or rateMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.rateMode"] ~= nil then
            st.draft.rateMode = clampCompareMode(values[prefix .. ".draft.rateMode"], DEFAULT_COMPARE_MODE)
        end
        if values[prefix .. ".draft.priceRule"] ~= nil then
            local price, priceMode, priceRule = parseSignedScaledRule(values[prefix .. ".draft.priceRule"], values[prefix .. ".draft.priceMode"])
            st.draft.priceRule = priceRule
            st.draft.priceMode = clampCompareMode(values[prefix .. ".draft.priceMode"] or priceMode, DEFAULT_COMPARE_MODE)
        elseif values[prefix .. ".draft.priceMode"] ~= nil then
            st.draft.priceMode = clampCompareMode(values[prefix .. ".draft.priceMode"], DEFAULT_COMPARE_MODE)
        end
        local delay = tonumber(values[prefix .. ".delay"])
        if delay then
            st.delay = math.clamp(delay, 0.15, 5)
        end
        if values[prefix .. ".enabled"] ~= nil then
            setEnabled(kind, Core.flagOn(values[prefix .. ".enabled"]))
        end
    end
end

local function registerKindSection(ui, kind, title)
    local st = M[kind]
    local prefix = kind == "fav" and "steal.fav" or "steal.unfav"
    local body, _, statusApi = ui:CreateSection({
        title = title,
        expanded = false,
        status = {
            id = prefix .. ".status",
            persist = false,
            value = st._status.text,
            style = st._status.style,
            detail = st._status.detail,
        },
    })
    local pre = ui:GetValues() or {}
    if type(pre[prefix .. ".rules"]) == "table" then
        st.rules = sanitizeRules(pre[prefix .. ".rules"])
    end
    local setListener = kind == "fav" and M.setFavStatusListener or M.setUnfavStatusListener
    setListener(function(status)
        statusApi.set(status.text)
        statusApi.setStyle(status.style)
        statusApi.setDetail(status.detail)
    end)

    local ruleApi
    local function persistRules()
        if ruleApi and type(ruleApi.set) == "function" then
            pcall(ruleApi.set, st.rules)
        end
    end
    local _, bindRules = ui:CreateRuleList(body, {
        id = prefix .. ".rules",
        title = "Saved Rules",
        searchPlaceholder = "Search rules...",
        emptyText = "Belum ada rule.",
        visibleRows = 6,
        persist = true,
        getItems = function()
            return st.rules
        end,
        formatItem = formatRule,
        onLoad = function(list)
            st.rules = sanitizeRules(list)
        end,
        onToggle = function(rule, enabled)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            for _, item in ipairs(st.rules) do
                if tostring(item.id) == id then
                    item.enabled = enabled == true
                    break
                end
            end
            persistRules()
        end,
        onDelete = function(rule)
            local id = type(rule) == "table" and tostring(rule.id or "") or ""
            local nextList = {}
            for _, item in ipairs(st.rules) do
                if tostring(item.id) ~= id then
                    nextList[#nextList + 1] = item
                end
            end
            st.rules = nextList
            persistRules()
        end,
    })
    ruleApi = bindRules

    local formApi
    local _, bindForm = ui:CreateRuleForm(body, {
        id = prefix .. ".draft.modes",
        label = "Rule Fields",
        placeholder = "Pick fields...",
        hintText = "Pet / Rarity / Mutation / Size / Kg / Price / Earn.",
        persist = true,
        modes = {
            { key = "name", name = "Pet" },
            { key = "rarity", name = "Rarity" },
            { key = "mutation", name = "Mutation" },
            { key = "size", name = "Size" },
            { key = "kg", name = "Kg" },
            { key = "price", name = "Price $" },
            { key = "rate", name = "Earn $/s" },
        },
    })
    formApi = bindForm

    local _, rarityApi = ui:CreateRowDropdown(body, {
        id = prefix .. ".draft.rarity",
        label = "Rarity",
        mode = "multi",
        placeholder = "Any rarity",
        hintText = "Kosong = semua rarity.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return Core.RARITY_ITEMS
        end,
        onChanged = function(a, b)
            st.draft.rarities = parseKeyMap(dropdownValue(a, b))
        end,
    })
    local _, nameApi = ui:CreateRowDropdown(body, {
        id = prefix .. ".draft.names",
        label = "Pet",
        mode = "multi",
        placeholder = "All pets",
        hintText = "Kosong = semua spesies.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return M.listPetItems()
        end,
        onChanged = function(a, b)
            st.draft.names = parseKeyMap(dropdownValue(a, b))
        end,
    })
    local _, mutApi = ui:CreateRowDropdown(body, {
        id = prefix .. ".draft.mutations",
        label = "Mutation",
        mode = "multi",
        placeholder = "Any Mutation...",
        hintText = "Kosong = any. No Mutation = polos saja.",
        clearable = true,
        preserveItemOrder = true,
        getItems = function()
            return M.listMutationItems()
        end,
