                pcall(rarityApi.clear, true)
            end
        end)
        formApi.attach("name", nameApi, function()
            st.draft.names = {}
            if nameApi and type(nameApi.clear) == "function" then
                pcall(nameApi.clear, true)
            end
        end)
        formApi.attach("mutation", mutApi, function()
            st.draft.mutations = {}
            if mutApi and type(mutApi.clear) == "function" then
