            end
        end)
        formApi.attach("size", sizeApi, function()
            st.draft.sizes = {}
            if sizeApi and type(sizeApi.clear) == "function" then
                pcall(sizeApi.clear, true)
            end
        end)
        formApi.attach("kg", { root = kgWrap }, function()
            st.draft.kgRule = "0"
