    ui:CreateRowButton(body, {
        text = "APPLY → Add Rule",
        kind = "primary",
        onClick = function()
            local modes = formApi and formApi.getModes and formApi.getModes() or {}
            local hasMode = false
            for _, on in pairs(modes) do
                if on == true then
                    hasMode = true
                    break
                end
            end
            if not hasMode then
                return
            end
            local rule = sanitizeRule({
                enabled = true,
                fields = modes,
                rarities = modes.rarity and st.draft.rarities or {},
                names = modes.name and st.draft.names or {},
                mutations = modes.mutation and st.draft.mutations or {},
                sizes = modes.size and st.draft.sizes or {},
                kgRule = modes.kg and st.draft.kgRule or "0",
                kgMode = modes.kg and st.draft.kgMode or DEFAULT_COMPARE_MODE,
                rateRule = modes.rate and st.draft.rateRule or "0",
                rateMode = modes.rate and st.draft.rateMode or DEFAULT_COMPARE_MODE,
                priceRule = modes.price and st.draft.priceRule or "0",
                priceMode = modes.price and st.draft.priceMode or DEFAULT_COMPARE_MODE,
            })
            st.rules[#st.rules + 1] = rule
            persistRules()
            st.draft = newDraft()
            if rarityApi and type(rarityApi.clear) == "function" then
                pcall(rarityApi.clear, true)
            end
            if nameApi and type(nameApi.clear) == "function" then
                pcall(nameApi.clear, true)
            end
            if mutApi and type(mutApi.clear) == "function" then
                pcall(mutApi.clear, true)
            end
            if sizeApi and type(sizeApi.clear) == "function" then
                pcall(sizeApi.clear, true)
            end
