local Players = game:GetService("Players")
local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}

local TAG = "STEALEGG_PERF_HUD"

local running = false

do
    local prev = G.StealEggPerfHud or G.PerfHud
    if type(prev) == "table" and prev ~= M and type(prev.Stop) == "function" then
        pcall(prev.Stop, prev)
    end
end

local function wipeOverlay()
    local function zap(root)
        if typeof(root) ~= "Instance" then
            return
        end
        local old = root:FindFirstChild(TAG)
        if old then
            pcall(function()
                old:Destroy()
            end)
        end
    end
    pcall(function()
        zap(LP and LP:FindFirstChild("PlayerGui"))
    end)
    pcall(function()
        if type(gethui) == "function" then
            zap(gethui())
        end
    end)
    pcall(function()
        zap(game:GetService("CoreGui"))
    end)
end

wipeOverlay()

local function enabled()
    if G.PERF_HUD_ENABLED == false or rawget(_G, "PERF_HUD_ENABLED") == false then
        return false
    end
    return true
end

local function writeEnabled(on)
    G.PERF_HUD_ENABLED = on == true
    _G.PERF_HUD_ENABLED = on == true
end

local function sessionStart()
    local job = tostring(game.JobId or "")
    if G.__StealEggHudJob ~= job or type(G.__StealEggHudT0) ~= "number" then
        G.__StealEggHudJob = job
        G.__StealEggHudT0 = os.clock()
    end
    return G.__StealEggHudT0
end

function M.Start()
    running = true
    writeEnabled(true)
    sessionStart()
    wipeOverlay()
    return true
end

function M.Stop()
    running = false
    writeEnabled(false)
    wipeOverlay()
end

function M.SetEnabled(a, b)
    local on = a
    if type(a) == "table" then
        on = b
    end
    on = (on == true)
    writeEnabled(on)
    if on then
        return M.Start()
    end
    M.Stop()
    return false
end

function M.IsEnabled()
    return running == true and enabled()
end

function M.syncFrom(values)
    values = type(values) == "table" and values or {}
    local v = values["misc.fps.hud"]
    if v == nil then
        if enabled() then
            M.Start()
        else
            M.Stop()
        end
        return
    end
    local on = v == true
    local Core = G.StealEggCore
    if type(Core) == "table" and type(Core.flagOn) == "function" then
        on = Core.flagOn(v)
    end
    M.SetEnabled(on)
end

M.start = M.Start
M.stop = M.Stop

G.StealEggPerfHud = M
G.PerfHud = M
G.PERF_HUD_ENABLED = (G.PERF_HUD_ENABLED ~= false)
_G.PERF_HUD_ENABLED = (rawget(_G, "PERF_HUD_ENABLED") ~= false)

return M

