return M
 end,     required = true },
    { key = "InfoTabs",  name = "Info Tabs",     factory = function() -- Main tab INFO
-- Sub tab Wild: egg per area. Plot: egg di plot. Egg/Pet: backpack (+ pet ter-equip).

local M = {}

local DEFAULT_SCAN_SEC = 8
local PAUSE_POLL_SEC = 0.5
local MAX_EGGS_PER_AREA = 24
local MAX_BAG_GROUPS = 32
local MAX_BAG_ROWS = 10
local MAX_MUT_LINES = 12
local SNAP_SYNC_SEC = 20

function M.Register(ui, Loaded)
    Loaded = type(Loaded) == "table" and Loaded or {}
    local G = (getgenv and getgenv()) or _G
    local Core = Loaded.Core or G.StealEggCore
    local WildEgg = Loaded.WildEgg or G.StealEggWild
    if type(Core) ~= "table" or type(Core.eggCall) ~= "function" then
        error("InfoTabs butuh Core — cek shortcode STEALEGG_CORE", 0)
    end

    local dropdownValue = Core.dropdownValue

    ui:RegisterMainTab("info", "INFO", 3)

    local function clampScanSec(n)
        n = math.floor(tonumber(n) or DEFAULT_SCAN_SEC)
        if n < 1 then
            n = 1
        end
        if n > 30 then
            n = 30
        end
        return n
    end

    local function fmtNum(n)
        n = tonumber(n) or 0
        local abs = math.abs(n)
        if abs >= 1e9 then
            return string.format("%.1fB", n / 1e9)
        end
        if abs >= 1e6 then
            return string.format("%.1fM", n / 1e6)
        end
        if abs >= 1e3 then
            return string.format("%.1fk", n / 1e3)
        end
        if abs >= 10 or n == math.floor(n) then
            return string.format("%.0f", n)
        end
        return string.format("%.1f", n)
    end

    local function fmtKg(n)
        n = tonumber(n) or 0
        if n >= 10 then
            return string.format("%.0fkg", n)
        end
        return string.format("%.1fkg", n)
    end

    local function fmtPrice(n)
        n = tonumber(n) or 0
        if n <= 0 then
            return "$0"
        end
        return "$" .. fmtNum(n)
    end

    local function mutLabel(muts)
        if type(muts) ~= "table" or #muts == 0 then
            return "Normal"
        end
        local names = {}
        for i, name in ipairs(muts) do
            names[i] = (type(Core.mutationLabel) == "function" and Core.mutationLabel(name)) or tostring(name)
        end
        if #names == 1 then
            return names[1]
        end
        return table.concat(names, "+")
    end

    local function mutationKey(raw)
        local s = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then
            return "Normal"
        end
        local low = string.lower(s)
        if low == "none" or low == "normal" or low == "nomutation" then
            return "Normal"
        end
        return s
    end

    local function describeEgg(rec)
        if type(WildEgg) == "table" and type(WildEgg.describeRecord) == "function" then
            local ok, desc = pcall(WildEgg.describeRecord, rec)
            if ok and type(desc) == "table" then
                desc.state = tostring(rec and rec.State or "Slot")
                desc.uid = rec and rec.Uid or desc.uid
                return desc
            end
        end
        local category = tostring(rec and (rec.AssetCategory or rec.category) or "")
        local cat = Core.getCatalog and Core.getCatalog() or nil
        local item = type(cat) == "table" and type(cat.byKey) == "table" and cat.byKey[category]
        local rate = 0
        if type(item) == "table" then
            rate = tonumber(item.rate) or 0
        end
        return {
            category = category,
            areaId = tostring(rec and (rec.AreaId or rec.areaId) or ""),
            name = (type(item) == "table" and item.name) or category,
            rarity = (type(item) == "table" and item.rarity) or "",
            rarityNum = (type(item) == "table" and tonumber(item.rarityNumber)) or 0,
            areaName = tostring(rec and (rec.AreaId or rec.areaId) or ""),
            kg = 0,
            rate = rate,
            price = rate * 100,
            muts = {},
            state = tostring(rec and rec.State or "Slot"),
            uid = rec and rec.Uid or nil,
        }
    end

    local function eggLine(info, index)
        info = type(info) == "table" and info or {}
        local parts = {}
        if index then
            parts[#parts + 1] = tostring(index) .. "."
        end
        if type(info.rarity) == "string" and info.rarity ~= "" then
            parts[#parts + 1] = info.rarity
        end
        parts[#parts + 1] = tostring(info.name or info.category or "egg")
        parts[#parts + 1] = mutLabel(info.muts)
        if (tonumber(info.kg) or 0) > 0 then
            parts[#parts + 1] = fmtKg(info.kg)
        end
        parts[#parts + 1] = fmtPrice(info.price)
        if (tonumber(info.rate) or 0) > 0 then
            parts[#parts + 1] = fmtNum(info.rate) .. "/s"
        end
        if info.ready == true then
            parts[#parts + 1] = "Ready"
        elseif type(info.timeText) == "string" and info.timeText ~= "" then
            parts[#parts + 1] = info.timeText
            if tonumber(info.pct) ~= nil then
                parts[#parts + 1] = tostring(info.pct) .. "%"
            end
        else
            local state = tostring(info.state or "")
            if info.equipped ~= true and state ~= "" and state ~= "Slot" and state ~= "Bag" then
                parts[#parts + 1] = state
            end
        end
        if info.equipped == true then
            parts[#parts + 1] = "Equip"
        end
        if info.favorite == true then
            parts[#parts + 1] = "Fav"
        end
        if info.stolen == true then
            parts[#parts + 1] = "Stolen"
        end
        return table.concat(parts, " · ")
    end

    local lastWildSync = 0
    local function snapshotRecords()
        if os.clock() - lastWildSync >= SNAP_SYNC_SEC then
            lastWildSync = os.clock()
            if type(WildEgg) ~= "table" or WildEgg.enabled ~= true then
                Core.eggCall("RequestAreaEggSnapshot")
            end
        end
        local ok, snap = Core.eggCall("GetAreaEggSnapshot")
        if ok and type(snap) == "table" and type(snap.Records) == "table" then
            return snap.Records
        end
        return {}
    end

    local function areaOrderMap()
        local map = {}
        local items = type(Core.listAreaItems) == "function" and Core.listAreaItems() or {}
        for i, area in ipairs(items) do
            if type(area) == "table" then
                map[tostring(area.key)] = i
                map[tostring(area.name)] = i
            end
        end
        return map
    end

    local function sortEggs(list, mode)
        mode = tostring(mode or "price")
        table.sort(list, function(a, b)
            if mode == "kg" then
                local ka, kb = tonumber(a.kg) or 0, tonumber(b.kg) or 0
                if ka ~= kb then
                    return ka > kb
                end
            elseif mode == "rate" then
                local ra, rb = tonumber(a.rate) or 0, tonumber(b.rate) or 0
                if ra ~= rb then
                    return ra > rb
                end
            elseif mode == "rarity" then
                local ra, rb = tonumber(a.rarityNum) or 0, tonumber(b.rarityNum) or 0
                if ra ~= rb then
                    return ra > rb
                end
            elseif mode == "name" then
                local na, nb = tostring(a.name or ""), tostring(b.name or "")
                if na ~= nb then
                    return na < nb
                end
            else
                local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
                if pa ~= pb then
                    return pa > pb
                end
            end
            local ra, rb = tonumber(a.rarityNum) or 0, tonumber(b.rarityNum) or 0
            if ra ~= rb then
                return ra > rb
            end
            return tostring(a.name or "") < tostring(b.name or "")
        end)
    end

    local function scanWild(sortMode)
        local records = snapshotRecords()
        local order = areaOrderMap()
        local byArea = {}
        local groups = {}
        local totalPrice, totalRate, count = 0, 0, 0
        local mutTotals = {}

        for _, rec in ipairs(records) do
            if type(rec) == "table" then
                local state = tostring(rec.State or "Slot")
                if state ~= "Claimed" then
                    local info = describeEgg(rec)
                    local areaKey = tostring(info.areaId or rec.AreaId or "?")
                    local areaName = tostring(info.areaName or areaKey)
                    local group = byArea[areaKey]
                    if not group then
                        group = {
                            key = areaKey,
                            name = areaName,
                            eggs = {},
                            count = 0,
                            total = 0,
                            rate = 0,
                            sortOrder = order[areaKey] or order[areaName] or 80,
                        }
                        byArea[areaKey] = group
                        groups[#groups + 1] = group
                    end
                    group.eggs[#group.eggs + 1] = info
                    group.count = group.count + 1
                    group.total = group.total + (tonumber(info.price) or 0)
                    group.rate = group.rate + (tonumber(info.rate) or 0)
                    count = count + 1
                    totalPrice = totalPrice + (tonumber(info.price) or 0)
                    totalRate = totalRate + (tonumber(info.rate) or 0)

                    local mutName = mutationKey(mutLabel(info.muts))
                    local mutRow = mutTotals[mutName]
                    if not mutRow then
                        mutRow = { name = mutName, count = 0, total = 0 }
                        mutTotals[mutName] = mutRow
                    end
                    mutRow.count = mutRow.count + 1
                    mutRow.total = mutRow.total + (tonumber(info.price) or 0)
                end
            end
        end

        for _, group in ipairs(groups) do
            sortEggs(group.eggs, sortMode)
            if #group.eggs > MAX_EGGS_PER_AREA then
                group.hidden = #group.eggs - MAX_EGGS_PER_AREA
            end
        end

        table.sort(groups, function(a, b)
            if a.sortOrder == b.sortOrder then
                return tostring(a.name) < tostring(b.name)
            end
            return a.sortOrder < b.sortOrder
        end)

        local mutList = {}
        for _, row in pairs(mutTotals) do
            mutList[#mutList + 1] = row
        end
        table.sort(mutList, function(a, b)
            local ta, tb = tonumber(a.total) or 0, tonumber(b.total) or 0
            if ta ~= tb then
                return ta > tb
            end
            if a.name == "Normal" then
                return false
            end
            if b.name == "Normal" then
                return true
            end
            return tostring(a.name) < tostring(b.name)
        end)

        return {
            groups = groups,
            count = count,
            areas = #groups,
            total = totalPrice,
            rate = totalRate,
            mutations = mutList,
        }
    end

    local function formatMutationSummary(mutList)
        mutList = type(mutList) == "table" and mutList or {}
        if #mutList == 0 then
            return "Mutations: —"
        end
        local lines = { "Total per mutasi:" }
        local n = math.min(#mutList, MAX_MUT_LINES)
        for i = 1, n do
            local m = mutList[i]
            lines[#lines + 1] = string.format(
                "· %s  ·  x%d  ·  %s",
                tostring(m.name or "?"),
                tonumber(m.count) or 0,
                fmtPrice(m.total)
            )
        end
        if #mutList > n then
            lines[#lines + 1] = string.format("· … +%d mutasi lain", #mutList - n)
        end
        return table.concat(lines, "\n")
    end

    local function isWildTab()
        return ui.activeMainKey == "info" and ui.activeSubKey == "wild"
    end

    local function isPlotTab()
        return ui.activeMainKey == "info" and ui.activeSubKey == "plot"
    end

    local function fmtDuration(sec)
        sec = tonumber(sec) or 0
        if sec <= 0 then
            return "Ready"
        end
        sec = math.floor(sec + 0.5)
        local h = math.floor(sec / 3600)
        local m = math.floor((sec % 3600) / 60)
        local s = sec % 60
        if h > 0 then
            return string.format("%dh %dm", h, m)
        end
        if m > 0 then
            return string.format("%dm %ds", m, s)
        end
        return string.format("%ds", s)
    end

    local function scanPlot(sortMode)
        local Hatch = Loaded.Hatch or G.StealEggHatch
        if type(Hatch) ~= "table" or type(Hatch.listPlotEggs) ~= "function" then
            return {
                groups = {},
                count = 0,
                ready = 0,
                growing = 0,
                total = 0,
                rate = 0,
                mutations = {},
                error = "Hatch module tidak ke-load",
            }
        end
        local raw = Hatch.listPlotEggs()
        raw = type(raw) == "table" and raw or {}
        local eggs = type(raw.eggs) == "table" and raw.eggs or {}
        local byName = {}
        local groups = {}
        for i = 1, #eggs do
            local info = eggs[i]
            if type(info) == "table" then
                local key = tostring(info.category or info.name or "?")
                local name = tostring(info.name or key)
                local group = byName[key]
                if not group then
                    group = {
                        key = key,
                        name = name,
                        eggs = {},
                        count = 0,
                        total = 0,
                        rate = 0,
                        ready = 0,
                        growing = 0,
                        rarityNum = tonumber(info.rarityNum) or 0,
                    }
                    byName[key] = group
                    groups[#groups + 1] = group
                end
                group.eggs[#group.eggs + 1] = info
                group.count += 1
                group.total += tonumber(info.price) or 0
                group.rate += tonumber(info.rate) or 0
                if info.ready == true then
                    group.ready += 1
                else
                    group.growing += 1
                end
                local rn = tonumber(info.rarityNum) or 0
                if rn > (tonumber(group.rarityNum) or 0) then
                    group.rarityNum = rn
                end
            end
        end
        for _, group in ipairs(groups) do
            sortEggs(group.eggs, sortMode)
            if #group.eggs > MAX_EGGS_PER_AREA then
                group.hidden = #group.eggs - MAX_EGGS_PER_AREA
            end
        end
        table.sort(groups, function(a, b)
            if sortMode == "name" then
                return tostring(a.name) < tostring(b.name)
            elseif sortMode == "kg" then
                local ka = tonumber(a.eggs[1] and a.eggs[1].kg) or 0
                local kb = tonumber(b.eggs[1] and b.eggs[1].kg) or 0
                if ka ~= kb then
                    return ka > kb
                end
            elseif sortMode == "rate" then
                if a.rate ~= b.rate then
                    return a.rate > b.rate
                end
            elseif sortMode == "rarity" then
                if a.rarityNum ~= b.rarityNum then
                    return a.rarityNum > b.rarityNum
                end
            else
                if a.total ~= b.total then
                    return a.total > b.total
                end
            end
            return tostring(a.name) < tostring(b.name)
        end)
        return {
            groups = groups,
            count = tonumber(raw.total) or #eggs,
            ready = tonumber(raw.ready) or 0,
            growing = tonumber(raw.growing) or 0,
            total = tonumber(raw.value) or 0,
            rate = tonumber(raw.rate) or 0,
            nextRemain = raw.nextRemain,
            mutations = raw.mutations or {},
        }
    end

    local function groupBagItems(items, sortMode)
        items = type(items) == "table" and items or {}
        local byName = {}
        local groups = {}
        local totalPrice, totalRate = 0, 0
        local mutTotals = {}
        for i = 1, #items do
            local info = items[i]
            if type(info) == "table" then
                local key = tostring(info.category or info.name or "?")
                local name = tostring(info.name or key)
                local group = byName[key]
                if not group then
                    group = {
                        key = key,
                        name = name,
                        eggs = {},
                        count = 0,
                        total = 0,
                        rate = 0,
                        rarityNum = tonumber(info.rarityNum) or 0,
                    }
                    byName[key] = group
                    groups[#groups + 1] = group
                end
                group.eggs[#group.eggs + 1] = info
                group.count += 1
                group.total += tonumber(info.price) or 0
                group.rate += tonumber(info.rate) or 0
                local rn = tonumber(info.rarityNum) or 0
                if rn > (tonumber(group.rarityNum) or 0) then
                    group.rarityNum = rn
                end
                totalPrice += tonumber(info.price) or 0
                totalRate += tonumber(info.rate) or 0
                local mutName = mutLabel(info.muts)
                local row = mutTotals[mutName]
                if not row then
                    row = { name = mutName, count = 0, total = 0, rate = 0 }
                    mutTotals[mutName] = row
                end
                row.count += 1
                row.total += tonumber(info.price) or 0
                row.rate += tonumber(info.rate) or 0
            end
        end
        local mutList = {}
        for _, row in pairs(mutTotals) do
            mutList[#mutList + 1] = row
        end
        table.sort(mutList, function(a, b)
            if a.total ~= b.total then
                return a.total > b.total
            end
            return tostring(a.name) < tostring(b.name)
        end)
        for _, group in ipairs(groups) do
            sortEggs(group.eggs, sortMode)
            if #group.eggs > MAX_BAG_ROWS then
                group.hidden = #group.eggs - MAX_BAG_ROWS
            end
        end
        table.sort(groups, function(a, b)
            if sortMode == "name" then
                return tostring(a.name) < tostring(b.name)
            elseif sortMode == "kg" then
                local ka = tonumber(a.eggs[1] and a.eggs[1].kg) or 0
                local kb = tonumber(b.eggs[1] and b.eggs[1].kg) or 0
                if ka ~= kb then
                    return ka > kb
                end
            elseif sortMode == "rate" then
                if a.rate ~= b.rate then
                    return a.rate > b.rate
                end
            elseif sortMode == "rarity" then
                if a.rarityNum ~= b.rarityNum then
                    return a.rarityNum > b.rarityNum
                end
            else
                if a.total ~= b.total then
                    return a.total > b.total
                end
            end
            return tostring(a.name) < tostring(b.name)
        end)
        local hiddenGroups, hiddenCount = 0, 0
        if #groups > MAX_BAG_GROUPS then
            for i = MAX_BAG_GROUPS + 1, #groups do
                hiddenGroups += 1
                hiddenCount += tonumber(groups[i].count) or 0
            end
            local keep = {}
            for i = 1, MAX_BAG_GROUPS do
                keep[i] = groups[i]
            end
            groups = keep
        end
        return {
            groups = groups,
            count = #items,
            total = totalPrice,
            rate = totalRate,
            mutations = mutList,
            hiddenGroups = hiddenGroups,
            hiddenCount = hiddenCount,
        }
    end

    local function scanBagEggs(sortMode)
        local AutoSell = Loaded.AutoSell or G.StealEggSell
        if type(AutoSell) ~= "table" or type(AutoSell.listBagEggs) ~= "function" then
            return { groups = {}, count = 0, total = 0, rate = 0, mutations = {}, error = "AutoSell tidak ke-load" }
        end
        local ok, items = pcall(AutoSell.listBagEggs)
        if not ok then
            return { groups = {}, count = 0, total = 0, rate = 0, mutations = {}, error = tostring(items) }
        end
        return groupBagItems(items, sortMode)
    end

    local function scanBagPets(sortMode)
        local AutoSell = Loaded.AutoSell or G.StealEggSell
        if type(AutoSell) ~= "table" or type(AutoSell.listBagPets) ~= "function" then
            return { groups = {}, count = 0, total = 0, rate = 0, mutations = {}, equipped = {}, error = "AutoSell tidak ke-load" }
        end
        local ok, items = pcall(AutoSell.listBagPets)
        if not ok then
            return { groups = {}, count = 0, total = 0, rate = 0, mutations = {}, equipped = {}, error = tostring(items) }
        end
        items = type(items) == "table" and items or {}
        local equipped, bag = {}, {}
        local eqPrice, eqRate = 0, 0
        for i = 1, #items do
            local info = items[i]
            if type(info) == "table" and info.equipped == true then
                equipped[#equipped + 1] = info
                eqPrice += tonumber(info.price) or 0
                eqRate += tonumber(info.rate) or 0
            elseif type(info) == "table" then
                bag[#bag + 1] = info
            end
        end
        sortEggs(equipped, sortMode)
        local data = groupBagItems(bag, sortMode)
        data.equipped = equipped
        data.equippedCount = #equipped
        data.equippedTotal = eqPrice
        data.equippedRate = eqRate
        data.bagCount = #bag
        data.count = #items
        data.total += eqPrice
        data.rate += eqRate
        return data
    end

    local function isInfoSub(subKey)
        return ui.activeMainKey == "info" and ui.activeSubKey == subKey
    end

    ui:RegisterSubTab("info", "wild", "Wild", function()
        ui:ClearSubContent()

        local gen = (tonumber(G.__STEALEGG_INFO_WILD_GEN) or 0) + 1
        G.__STEALEGG_INFO_WILD_GEN = gen

        local saved = ui:GetValues() or {}
        local scanSec = clampScanSec(saved["info.wild.scanSec"] or DEFAULT_SCAN_SEC)
        local sortMode = tostring(dropdownValue(saved["info.wild.sort"]) or "price")
        if sortMode ~= "price" and sortMode ~= "kg" and sortMode ~= "rate" and sortMode ~= "rarity" and sortMode ~= "name" then
            sortMode = "price"
        end
        local enabled = (type(Core.flagOn) == "function" and Core.flagOn(saved["info.wild.enabled"])) or saved["info.wild.enabled"] == true

        local areaPool = {}
        local emptyUi = nil

        local function stillLive(anchor)
            if G.__STEALEGG_INFO_WILD_GEN ~= gen then
                return false
            end
            if not anchor or not anchor.Parent then
                return false
            end
            return true
        end

        local function wrapLabel(lbl)
            if not lbl then
                return
            end
            lbl.TextWrapped = true
            lbl.TextTruncate = Enum.TextTruncate.None
            lbl.TextYAlignment = Enum.TextYAlignment.Top
            lbl.AutomaticSize = Enum.AutomaticSize.Y
            lbl.Size = UDim2.new(1, 0, 0, 0)
            local row = lbl.Parent
            if row and row:IsA("GuiObject") then
                row.AutomaticSize = Enum.AutomaticSize.Y
                row.Size = UDim2.new(1, 0, 0, 0)
            end
        end

        local function ensureEmpty()
            if emptyUi and emptyUi.section and emptyUi.section.Parent then
                return emptyUi
            end
            local body = ui:CreateSection("Eggs", true)
            local row, lbl = ui:CreateRowLabel(body, "Tidak ada egg di area.", nil, nil, "info")
            emptyUi = {
                section = body and body.Parent,
                body = body,
                row = row,
                lbl = lbl,
            }
            return emptyUi
        end

        local function ensureArea(key, name)
            key = tostring(key or name or "?")
            local entry = areaPool[key]
            if entry and entry.section and entry.section.Parent and entry.body and entry.body.Parent then
                return entry
            end
            local body = ui:CreateSection(tostring(name or key), false)
            local section = body and body.Parent
            local titleLbl = section and section:FindFirstChild("Header")
            titleLbl = titleLbl and titleLbl:FindFirstChild("Title")
            local infoRow, infoLbl = ui:CreateRowLabel(body, "", nil, nil, "info")
            local emptyRow, emptyLbl = ui:CreateRowLabel(body, "Kosong.", nil, nil, "info")
            if emptyRow then
                emptyRow.Visible = false
            end
            entry = {
                section = section,
                body = body,
                titleLbl = titleLbl,
                infoLbl = infoLbl,
                infoRow = infoRow,
                emptyLbl = emptyLbl,
                emptyRow = emptyRow,
                eggRows = {},
                eggLbls = {},
            }
            areaPool[key] = entry
            return entry
        end

        local function ensureEggLabel(entry, index)
            local lbl = entry.eggLbls[index]
            local row = entry.eggRows[index]
            if lbl and lbl.Parent and row and row.Parent then
                row.Visible = true
                return lbl
            end
            row, lbl = ui:CreateRowLabel(entry.body, {
                text = "",
                style = "list",
                wrap = true,
            })
            entry.eggRows[index] = row
            entry.eggLbls[index] = lbl
            return lbl
        end

        local bodySummary = ui:CreateSection("Wild Info", true)
        local _, summaryLbl = ui:CreateRowLabel(
            bodySummary,
            enabled and "Scanning…" or "Disabled — scan di-pause.",
            nil,
            nil,
            "accent"
        )
        local mutRow, mutLbl = ui:CreateRowLabel(bodySummary, "Mutations: —", nil, nil, "info")
        wrapLabel(mutLbl)

        ui:CreateRowDropdown(bodySummary, {
            id = "info.wild.sort",
            label = "Sort",
            mode = "single",
            persist = true,
            placeholder = "Price",
            initial = sortMode,
            getItems = function()
                return {
                    { key = "price", name = "Price" },
                    { key = "kg", name = "Kg" },
                    { key = "rate", name = "$/s" },
                    { key = "rarity", name = "Rarity" },
                    { key = "name", name = "Name" },
                }
            end,
            onChanged = function(a, b)
                local key = tostring(dropdownValue(a, b) or "price")
                if key == "price" or key == "kg" or key == "rate" or key == "rarity" or key == "name" then
                    sortMode = key
                end
            end,
        })

        ui:CreateRowInput(bodySummary, {
            id = "info.wild.scanSec",
            label = "Refresh (sec)",
            persist = true,
            initial = tostring(scanSec),
            onChanged = function(txt)
                scanSec = clampScanSec(txt)
            end,
        })

        local function setEnabled(on)
            enabled = on == true
        end

        local _, _, enableApi = ui:CreateRowToggle(bodySummary, {
            id = "info.wild.enabled",
            label = "Enable Wild Info",
            persist = true,
            initial = enabled,
            onChanged = function(on)
                setEnabled((type(Core.flagOn) == "function" and Core.flagOn(on)) or on == true)
                if not stillLive(summaryLbl) then
                    return
                end
                if enabled then
                    summaryLbl.Text = "Enabled — scanning…"
                else
                    summaryLbl.Text = "Disabled — scan di-pause."
                end
            end,
        })
        if enableApi and type(enableApi.get) == "function" then
            local ok, v = pcall(enableApi.get)
            if ok then
                enabled = (type(Core.flagOn) == "function" and Core.flagOn(v)) or v == true
            end
        end

        ui:CreateRowButton(bodySummary, {
            text = "Refresh now",
            kind = "primary",
            onClick = function()
                G.__STEALEGG_INFO_WILD_FORCE = gen
            end,
        })

        do
            local empty = ensureEmpty()
            if empty.lbl then
                empty.lbl.Text = enabled
                    and "Memuat list egg…"
                    or ("Nyalakan Enabled untuk scan (setiap " .. tostring(scanSec) .. " detik).")
            end
        end

        local function renderResults(data)
            if not stillLive(summaryLbl) or not isWildTab() then
                return
            end
            data = type(data) == "table" and data or {}
            local groups = type(data.groups) == "table" and data.groups or {}
            local count = tonumber(data.count) or 0
            local areas = tonumber(data.areas) or #groups
            local err = data.error

            if err and tostring(err) ~= "" and count <= 0 then
                summaryLbl.Text = "Error: " .. tostring(err)
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = "Mutations: —"
                    wrapLabel(mutLbl)
                end
            else
                summaryLbl.Text = string.format(
                    "Eggs: %d  ·  Areas: %d  ·  %s  ·  %s/s",
                    count,
                    areas,
                    fmtPrice(data.total),
                    fmtNum(data.rate)
                )
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = formatMutationSummary(data.mutations)
                    wrapLabel(mutLbl)
                end
            end

            if not stillLive(summaryLbl) or not isWildTab() then
                return
            end

            if #groups == 0 then
                for _, entry in pairs(areaPool) do
                    if entry.section then
                        entry.section.Visible = false
                    end
                end
                local empty = ensureEmpty()
                if empty.section then
                    empty.section.Visible = true
                end
                if empty.lbl then
                    empty.lbl.Text = "Tidak ada egg di area."
                end
                return
            end

            if emptyUi and emptyUi.section then
                emptyUi.section.Visible = false
            end

            local seen = {}
            for gi = 1, #groups do
                if not stillLive(summaryLbl) or not isWildTab() then
                    return
                end
                local g = groups[gi]
                local key = tostring(g.key or g.name or "?")
                seen[key] = true
                local title = string.format(
                    "%s  ·  x%d  ·  %s  ·  %s/s",
                    tostring(g.name or key),
                    tonumber(g.count) or 0,
                    fmtPrice(g.total),
                    fmtNum(g.rate)
                )
                local info = string.format(
                    "Eggs: %d  ·  Value: %s  ·  %s/s",
                    tonumber(g.count) or 0,
                    fmtPrice(g.total),
                    fmtNum(g.rate)
                )
                local entry = ensureArea(key, g.name)
                if entry.section then
                    entry.section.Visible = true
                    entry.section.LayoutOrder = 100 + gi
                end
                if entry.titleLbl then
                    entry.titleLbl.Text = title
                end
                if entry.infoLbl then
                    entry.infoLbl.Text = info
                end

                local eggs = type(g.eggs) == "table" and g.eggs or {}
                local showN = math.min(#eggs, MAX_EGGS_PER_AREA)
                if showN == 0 then
                    if entry.emptyRow then
                        entry.emptyRow.Visible = true
                    end
                    if entry.emptyLbl then
                        entry.emptyLbl.Text = "Kosong."
                    end
                    for i = 1, #entry.eggRows do
                        if entry.eggRows[i] then
                            entry.eggRows[i].Visible = false
                        end
                    end
                else
                    if entry.emptyRow then
                        entry.emptyRow.Visible = false
                    end
                    for i = 1, showN do
                        local lbl = ensureEggLabel(entry, i)
                        if lbl then
                            lbl.Text = eggLine(eggs[i], i)
                        end
                    end
                    if (tonumber(g.hidden) or 0) > 0 then
                        local extra = ensureEggLabel(entry, showN + 1)
                        if extra then
                            extra.Text = string.format("… +%d egg lain", g.hidden)
                        end
                        showN = showN + 1
                    end
                    for i = showN + 1, #entry.eggRows do
                        if entry.eggRows[i] then
                            entry.eggRows[i].Visible = false
                        end
                    end
                end
            end

            for key, entry in pairs(areaPool) do
                if not seen[key] and entry.section then
                    entry.section.Visible = false
                end
            end
        end

        task.spawn(function()
            while stillLive(summaryLbl) do
                if not isWildTab() then
                    task.wait(PAUSE_POLL_SEC)
                elseif not enabled and G.__STEALEGG_INFO_WILD_FORCE ~= gen then
                    if summaryLbl and summaryLbl.Parent then
                        local txt = tostring(summaryLbl.Text or "")
                        if txt == "" or string.find(txt, "scanning", 1, true) or string.find(txt, "Memuat", 1, true) then
                            summaryLbl.Text = "Disabled — scan di-pause."
                        end
                    end
                    task.wait(PAUSE_POLL_SEC)
                else
                    local force = G.__STEALEGG_INFO_WILD_FORCE == gen
                    if force then
                        G.__STEALEGG_INFO_WILD_FORCE = nil
                    end
                    local ok, data = pcall(scanWild, sortMode)
                    if not stillLive(summaryLbl) then
                        return
                    end
                    if isWildTab() and (enabled or force) then
                        if ok then
                            renderResults(data)
                        else
                            renderResults({
                                groups = {},
                                count = 0,
                                areas = 0,
                                total = 0,
                                rate = 0,
                                mutations = {},
                                error = tostring(data or "scan gagal"),
                            })
                        end
                    end
                    if not enabled then
                        task.wait(PAUSE_POLL_SEC)
                    else
                        local untilAt = os.clock() + scanSec
                        while os.clock() < untilAt do
                            if not stillLive(summaryLbl) then
                                return
                            end
                            if not isWildTab() or not enabled then
                                break
                            end
                            if G.__STEALEGG_INFO_WILD_FORCE == gen then
                                break
                            end
                            task.wait(PAUSE_POLL_SEC)
                        end
                    end
                end
            end
        end)
    end, 1)

    ui:RegisterSubTab("info", "plot", "Plot", function()
        ui:ClearSubContent()

        local gen = (tonumber(G.__STEALEGG_INFO_PLOT_GEN) or 0) + 1
        G.__STEALEGG_INFO_PLOT_GEN = gen

        local saved = ui:GetValues() or {}
        local scanSec = clampScanSec(saved["info.plot.scanSec"] or DEFAULT_SCAN_SEC)
        local sortMode = tostring(dropdownValue(saved["info.plot.sort"]) or "price")
        if sortMode ~= "price" and sortMode ~= "kg" and sortMode ~= "rate" and sortMode ~= "rarity" and sortMode ~= "name" then
            sortMode = "price"
        end
        local enabled = (type(Core.flagOn) == "function" and Core.flagOn(saved["info.plot.enabled"])) or saved["info.plot.enabled"] == true

        local namePool = {}
        local emptyUi = nil

        local function stillLive(anchor)
            if G.__STEALEGG_INFO_PLOT_GEN ~= gen then
                return false
            end
            if not anchor or not anchor.Parent then
                return false
            end
            return true
        end

        local function wrapLabel(lbl)
            if not lbl then
                return
            end
            lbl.TextWrapped = true
            lbl.TextTruncate = Enum.TextTruncate.None
            lbl.TextYAlignment = Enum.TextYAlignment.Top
            lbl.AutomaticSize = Enum.AutomaticSize.Y
            lbl.Size = UDim2.new(1, 0, 0, 0)
            local row = lbl.Parent
            if row and row:IsA("GuiObject") then
                row.AutomaticSize = Enum.AutomaticSize.Y
                row.Size = UDim2.new(1, 0, 0, 0)
            end
        end

        local function ensureEmpty()
            if emptyUi and emptyUi.section and emptyUi.section.Parent then
                return emptyUi
            end
            local body = ui:CreateSection("Eggs", true)
            local row, lbl = ui:CreateRowLabel(body, "Plot kosong · 0 egg.", nil, nil, "info")
            emptyUi = {
                section = body and body.Parent,
                body = body,
                row = row,
                lbl = lbl,
            }
            return emptyUi
        end

        local function ensureGroup(key, name)
            key = tostring(key or name or "?")
            local entry = namePool[key]
            if entry and entry.section and entry.section.Parent and entry.body and entry.body.Parent then
                return entry
            end
            local body = ui:CreateSection(tostring(name or key), false)
            local section = body and body.Parent
            local titleLbl = section and section:FindFirstChild("Header")
            titleLbl = titleLbl and titleLbl:FindFirstChild("Title")
            local infoRow, infoLbl = ui:CreateRowLabel(body, "", nil, nil, "info")
            local emptyRow, emptyLbl = ui:CreateRowLabel(body, "Kosong.", nil, nil, "info")
            if emptyRow then
                emptyRow.Visible = false
            end
            entry = {
                section = section,
                body = body,
                titleLbl = titleLbl,
                infoLbl = infoLbl,
                infoRow = infoRow,
                emptyLbl = emptyLbl,
                emptyRow = emptyRow,
                eggRows = {},
                eggLbls = {},
            }
            namePool[key] = entry
            return entry
        end

        local function ensureEggLabel(entry, index)
            local lbl = entry.eggLbls[index]
            local row = entry.eggRows[index]
            if lbl and lbl.Parent and row and row.Parent then
                row.Visible = true
                return lbl
            end
            row, lbl = ui:CreateRowLabel(entry.body, {
                text = "",
                style = "list",
                wrap = true,
            })
            entry.eggRows[index] = row
            entry.eggLbls[index] = lbl
            return lbl
        end

        local bodySummary = ui:CreateSection("Plot Info", true)
        local _, summaryLbl = ui:CreateRowLabel(
            bodySummary,
            enabled and "Scanning…" or "Disabled — scan di-pause.",
            nil,
            nil,
            "accent"
        )
        local _, mutLbl = ui:CreateRowLabel(bodySummary, "Mutations: —", nil, nil, "info")
        wrapLabel(mutLbl)

        ui:CreateRowDropdown(bodySummary, {
            id = "info.plot.sort",
            label = "Sort",
            mode = "single",
            persist = true,
            placeholder = "Price",
            initial = sortMode,
            getItems = function()
                return {
                    { key = "price", name = "Price" },
                    { key = "kg", name = "Kg" },
                    { key = "rate", name = "$/s" },
                    { key = "rarity", name = "Rarity" },
                    { key = "name", name = "Name" },
                }
            end,
            onChanged = function(a, b)
                local key = tostring(dropdownValue(a, b) or "price")
                if key == "price" or key == "kg" or key == "rate" or key == "rarity" or key == "name" then
                    sortMode = key
                end
            end,
        })

        ui:CreateRowInput(bodySummary, {
            id = "info.plot.scanSec",
            label = "Refresh (sec)",
            persist = true,
            initial = tostring(scanSec),
            onChanged = function(txt)
                scanSec = clampScanSec(txt)
            end,
        })

        local function setEnabled(on)
            enabled = on == true
        end

        local _, _, enableApi = ui:CreateRowToggle(bodySummary, {
            id = "info.plot.enabled",
            label = "Enable Plot Info",
            persist = true,
            initial = enabled,
            onChanged = function(on)
                setEnabled((type(Core.flagOn) == "function" and Core.flagOn(on)) or on == true)
                if not stillLive(summaryLbl) then
                    return
                end
                if enabled then
                    summaryLbl.Text = "Enabled — scanning…"
                else
                    summaryLbl.Text = "Disabled — scan di-pause."
                end
            end,
        })
        if enableApi and type(enableApi.get) == "function" then
            local ok, v = pcall(enableApi.get)
            if ok then
                enabled = (type(Core.flagOn) == "function" and Core.flagOn(v)) or v == true
            end
        end

        ui:CreateRowButton(bodySummary, {
            text = "Refresh now",
            kind = "primary",
            onClick = function()
                G.__STEALEGG_INFO_PLOT_FORCE = gen
            end,
        })

        do
            local empty = ensureEmpty()
            if empty.lbl then
                empty.lbl.Text = enabled
                    and "Memuat egg plot…"
                    or ("Nyalakan Enabled untuk scan (setiap " .. tostring(scanSec) .. " detik).")
            end
        end

        local function renderResults(data)
            if not stillLive(summaryLbl) or not isPlotTab() then
                return
            end
            data = type(data) == "table" and data or {}
            local groups = type(data.groups) == "table" and data.groups or {}
            local count = tonumber(data.count) or 0
            local err = data.error
            local nextText = "—"
            if (tonumber(data.ready) or 0) > 0 then
                nextText = "hatch now"
            elseif data.nextRemain ~= nil then
                nextText = fmtDuration(data.nextRemain)
            end

            if err and tostring(err) ~= "" and count <= 0 then
                summaryLbl.Text = "Error: " .. tostring(err)
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = "Mutations: —"
                    wrapLabel(mutLbl)
                end
            else
                summaryLbl.Text = string.format(
                    "Eggs: %d  ·  Ready: %d  ·  Growing: %d  ·  %s  ·  %s/s  ·  Next: %s",
                    count,
                    tonumber(data.ready) or 0,
                    tonumber(data.growing) or 0,
                    fmtPrice(data.total),
                    fmtNum(data.rate),
                    nextText
                )
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = formatMutationSummary(data.mutations)
                    wrapLabel(mutLbl)
                end
            end

            if not stillLive(summaryLbl) or not isPlotTab() then
                return
            end

            if #groups == 0 then
                for _, entry in pairs(namePool) do
                    if entry.section then
                        entry.section.Visible = false
                    end
                end
                local empty = ensureEmpty()
                if empty.section then
                    empty.section.Visible = true
                end
                if empty.lbl then
                    empty.lbl.Text = "Plot kosong · 0 egg."
                end
                return
            end

            if emptyUi and emptyUi.section then
                emptyUi.section.Visible = false
            end

            local seen = {}
            for gi = 1, #groups do
                if not stillLive(summaryLbl) or not isPlotTab() then
                    return
                end
                local g = groups[gi]
                local key = tostring(g.key or g.name or "?")
                seen[key] = true
                local title = string.format(
                    "%s  ·  x%d  ·  %s  ·  %s/s",
                    tostring(g.name or key),
                    tonumber(g.count) or 0,
                    fmtPrice(g.total),
                    fmtNum(g.rate)
                )
                local info = string.format(
                    "Eggs: %d  ·  Ready: %d  ·  Growing: %d  ·  Value: %s",
                    tonumber(g.count) or 0,
                    tonumber(g.ready) or 0,
                    tonumber(g.growing) or 0,
                    fmtPrice(g.total)
                )
                local entry = ensureGroup(key, g.name)
                if entry.section then
                    entry.section.Visible = true
                    entry.section.LayoutOrder = 100 + gi
                end
                if entry.titleLbl then
                    entry.titleLbl.Text = title
                end
                if entry.infoLbl then
                    entry.infoLbl.Text = info
                end

                local eggs = type(g.eggs) == "table" and g.eggs or {}
                local showN = math.min(#eggs, MAX_EGGS_PER_AREA)
                if showN == 0 then
                    if entry.emptyRow then
                        entry.emptyRow.Visible = true
                    end
                    if entry.emptyLbl then
                        entry.emptyLbl.Text = "Kosong."
                    end
                    for i = 1, #entry.eggRows do
                        if entry.eggRows[i] then
                            entry.eggRows[i].Visible = false
                        end
                    end
                else
                    if entry.emptyRow then
                        entry.emptyRow.Visible = false
                    end
                    for i = 1, showN do
                        local lbl = ensureEggLabel(entry, i)
                        if lbl then
                            lbl.Text = eggLine(eggs[i], i)
                        end
                    end
                    if (tonumber(g.hidden) or 0) > 0 then
                        local extra = ensureEggLabel(entry, showN + 1)
                        if extra then
                            extra.Text = string.format("… +%d egg lain", g.hidden)
                        end
                        showN = showN + 1
                    end
                    for i = showN + 1, #entry.eggRows do
                        if entry.eggRows[i] then
                            entry.eggRows[i].Visible = false
                        end
                    end
                end
            end

            for key, entry in pairs(namePool) do
                if not seen[key] and entry.section then
                    entry.section.Visible = false
                end
            end
        end

        task.spawn(function()
            while stillLive(summaryLbl) do
                if not isPlotTab() then
                    task.wait(PAUSE_POLL_SEC)
                elseif not enabled and G.__STEALEGG_INFO_PLOT_FORCE ~= gen then
                    if summaryLbl and summaryLbl.Parent then
                        local txt = tostring(summaryLbl.Text or "")
                        if txt == "" or string.find(txt, "scanning", 1, true) or string.find(txt, "Memuat", 1, true) then
                            summaryLbl.Text = "Disabled — scan di-pause."
                        end
                    end
                    task.wait(PAUSE_POLL_SEC)
                else
                    local force = G.__STEALEGG_INFO_PLOT_FORCE == gen
                    if force then
                        G.__STEALEGG_INFO_PLOT_FORCE = nil
                    end
                    local ok, data = pcall(scanPlot, sortMode)
                    if not stillLive(summaryLbl) then
                        return
                    end
                    if isPlotTab() and (enabled or force) then
                        if ok then
                            renderResults(data)
                        else
                            renderResults({
                                groups = {},
                                count = 0,
                                ready = 0,
                                growing = 0,
                                total = 0,
                                rate = 0,
                                mutations = {},
                                error = tostring(data or "scan gagal"),
                            })
                        end
                    end
                    if not enabled then
                        task.wait(PAUSE_POLL_SEC)
                    else
                        local untilAt = os.clock() + scanSec
                        while os.clock() < untilAt do
                            if not stillLive(summaryLbl) then
                                return
                            end
                            if not isPlotTab() or not enabled then
                                break
                            end
                            if G.__STEALEGG_INFO_PLOT_FORCE == gen then
                                break
                            end
                            task.wait(PAUSE_POLL_SEC)
                        end
                    end
                end
            end
        end)
    end, 2)

    local function registerBagTab(cfg)
        ui:RegisterSubTab("info", cfg.subKey, cfg.label, function()
