                label = "Refresh (sec)",
                persist = true,
                initial = tostring(scanSec),
                onChanged = function(txt)
                    scanSec = clampScanSec(txt)
                end,
            })

            local function setEnabled(on)
                enabled = on == true
            end

            local _, _, enableApi = ui:CreateRowToggle(bodySummary, {
                id = cfg.idEnabled,
                label = cfg.enableLabel,
                persist = true,
                initial = enabled,
                onChanged = function(on)
                    setEnabled((type(Core.flagOn) == "function" and Core.flagOn(on)) or on == true)
                    if not stillLive(summaryLbl) then
                        return
                    end
                    if enabled then
                        summaryLbl.Text = "Enabled — scanning…"
                    else
                        summaryLbl.Text = "Disabled — scan di-pause."
                    end
                end,
            })
            if enableApi and type(enableApi.get) == "function" then
                local ok, v = pcall(enableApi.get)
                if ok then
                    enabled = (type(Core.flagOn) == "function" and Core.flagOn(v)) or v == true
                end
            end

            ui:CreateRowButton(bodySummary, {
                text = "Refresh now",
                kind = "primary",
                onClick = function()
                    G[forceKey] = gen
                end,
            })

            if cfg.showEquipped == true then
                local bodyEq = ui:CreateSection("Equipped", true)
                local infoRow, infoLbl = ui:CreateRowLabel(bodyEq, "Equip: 0", nil, nil, "info")
                local emptyRow, emptyLbl = ui:CreateRowLabel(bodyEq, "Tidak ada pet ter-equip.", nil, nil, "info")
                equipUi = {
                    section = bodyEq and bodyEq.Parent,
                    body = bodyEq,
                    infoLbl = infoLbl,
                    infoRow = infoRow,
                    emptyLbl = emptyLbl,
                    emptyRow = emptyRow,
                    eggRows = {},
                    eggLbls = {},
                }
            end

            do
                local empty = ensureEmpty()
                if empty.lbl then
                    empty.lbl.Text = enabled
                        and cfg.loadingText
                        or ("Nyalakan Enabled untuk scan (setiap " .. tostring(scanSec) .. " detik).")
                end
            end

            local function renderEquipped(data)
                if not equipUi or not stillLive(summaryLbl) or not isInfoSub(cfg.subKey) then
                    return
                end
                local list = type(data.equipped) == "table" and data.equipped or {}
                if equipUi.infoLbl then
                    equipUi.infoLbl.Text = string.format(
                        "Equip: %d  ·  %s  ·  %s/s",
                        #list,
                        fmtPrice(data.equippedTotal),
                        fmtNum(data.equippedRate)
                    )
                end
                local showN = math.min(#list, MAX_BAG_ROWS)
                if showN == 0 then
                    if equipUi.emptyRow then
                        equipUi.emptyRow.Visible = true
                    end
                    if equipUi.emptyLbl then
                        equipUi.emptyLbl.Text = "Tidak ada pet ter-equip."
                    end
                    for i = 1, #equipUi.eggRows do
                        if equipUi.eggRows[i] then
                            equipUi.eggRows[i].Visible = false
                        end
                    end
                    return
                end
                if equipUi.emptyRow then
                    equipUi.emptyRow.Visible = false
                end
                for i = 1, showN do
                    local lbl = ensureEggLabel(equipUi, i)
                    if lbl then
                        lbl.Text = eggLine(list[i], i)
                    end
                end
                if #list > showN then
                    local extra = ensureEggLabel(equipUi, showN + 1)
                    if extra then
                        extra.Text = string.format("… +%d pet lain", #list - showN)
                    end
                    showN = showN + 1
                end
                for i = showN + 1, #equipUi.eggRows do
                    if equipUi.eggRows[i] then
                        equipUi.eggRows[i].Visible = false
                    end
                end
            end

            local function renderResults(data)
                if not stillLive(summaryLbl) or not isInfoSub(cfg.subKey) then
                    return
                end
                data = type(data) == "table" and data or {}
                local groups = type(data.groups) == "table" and data.groups or {}
                local count = tonumber(data.count) or 0
                local err = data.error

                if err and tostring(err) ~= "" and count <= 0 then
                    summaryLbl.Text = "Error: " .. tostring(err)
                    if mutLbl and mutLbl.Parent then
                        mutLbl.Text = "Mutations: —"
                        wrapLabel(mutLbl)
                    end
                else
                    local line = cfg.summaryLine(data)
                    if (tonumber(data.hiddenGroups) or 0) > 0 then
                        line = line .. string.format(
                            "  ·  +%d jenis",
                            tonumber(data.hiddenGroups) or 0
                        )
                    end
                    summaryLbl.Text = line
                    if mutLbl and mutLbl.Parent then
                        mutLbl.Text = formatMutationSummary(data.mutations)
                        wrapLabel(mutLbl)
                    end
                end

                if not stillLive(summaryLbl) or not isInfoSub(cfg.subKey) then
                    return
                end

                if cfg.showEquipped == true then
                    renderEquipped(data)
                end

                if #groups == 0 then
                    for _, entry in pairs(namePool) do
                        if entry.section then
                            entry.section.Visible = false
                        end
                    end
                    local empty = ensureEmpty()
                    if empty.section then
                        empty.section.Visible = true
                    end
                    if empty.lbl then
                        if cfg.showEquipped == true and (tonumber(data.equippedCount) or 0) > 0 then
                            empty.lbl.Text = "Backpack kosong · 0 " .. cfg.unit .. "."
                        else
                            empty.lbl.Text = cfg.emptyText
                        end
                    end
                    return
                end

                if emptyUi and emptyUi.section then
                    emptyUi.section.Visible = false
                end

                local seen = {}
                local content = ui.content
                local prevAuto
                if content then
                    prevAuto = content.AutomaticCanvasSize
                    content.AutomaticCanvasSize = Enum.AutomaticSize.None
                end
                for gi = 1, #groups do
                    if gi > 1 and (gi - 1) % 3 == 0 then
                        task.wait()
                        if not stillLive(summaryLbl) or not isInfoSub(cfg.subKey) then
                            if content then
                                content.AutomaticCanvasSize = prevAuto or Enum.AutomaticSize.Y
                            end
                            return
                        end
                    end
                    local g = groups[gi]
                    local key = tostring(g.key or g.name or "?")
                    seen[key] = true
                    local title = string.format(
                        "%s  ·  x%d  ·  %s  ·  %s/s",
                        tostring(g.name or key),
                        tonumber(g.count) or 0,
                        fmtPrice(g.total),
                        fmtNum(g.rate)
                    )
                    local info = string.format(
                        "%s: %d  ·  Value: %s  ·  %s/s",
                        cfg.groupTitle,
                        tonumber(g.count) or 0,
                        fmtPrice(g.total),
                        fmtNum(g.rate)
                    )
                    local entry = ensureGroup(key, g.name)
                    if entry.section then
                        entry.section.Visible = true
                        entry.section.LayoutOrder = 100 + gi
                    end
                    if entry.titleLbl then
                        entry.titleLbl.Text = title
                    end
                    if entry.infoLbl then
                        entry.infoLbl.Text = info
                    end

                    local eggs = type(g.eggs) == "table" and g.eggs or {}
                    local showN = math.min(#eggs, MAX_BAG_ROWS)
                    if showN == 0 then
                        if entry.emptyRow then
                            entry.emptyRow.Visible = true
                        end
                        if entry.emptyLbl then
                            entry.emptyLbl.Text = "Kosong."
                        end
                        for i = 1, #entry.eggRows do
                            if entry.eggRows[i] then
                                entry.eggRows[i].Visible = false
                            end
                        end
                    else
                        if entry.emptyRow then
                            entry.emptyRow.Visible = false
                        end
                        for i = 1, showN do
                            local lbl = ensureEggLabel(entry, i)
                            if lbl then
                                lbl.Text = eggLine(eggs[i], i)
                            end
                        end
                        if (tonumber(g.hidden) or 0) > 0 then
                            local extra = ensureEggLabel(entry, showN + 1)
                            if extra then
                                extra.Text = string.format("… +%d %s lain", g.hidden, cfg.unit)
                            end
                            showN = showN + 1
                        end
                        for i = showN + 1, #entry.eggRows do
                            if entry.eggRows[i] then
                                entry.eggRows[i].Visible = false
                            end
                        end
                    end
                end
                if content then
                    content.AutomaticCanvasSize = prevAuto or Enum.AutomaticSize.Y
                end

                for key, entry in pairs(namePool) do
                    if not seen[key] and entry.section then
                        entry.section.Visible = false
                    end
                end
            end

            task.spawn(function()
                task.wait()
                local emptyTries = 0
                while stillLive(summaryLbl) do
                    if not isInfoSub(cfg.subKey) then
                        task.wait(PAUSE_POLL_SEC)
                    else
                        local force = G[forceKey] == gen
                        if force then
                            G[forceKey] = nil
                        end
                        local count = 0
                        if isInfoSub(cfg.subKey) and (enabled or force) then
                            local ok, data = pcall(cfg.scan, sortMode)
                            if not ok then
                                data = { groups = {}, count = 0, total = 0, rate = 0, mutations = {}, error = tostring(data) }
                            end
                            count = tonumber(data and data.count) or 0
                            if isInfoSub(cfg.subKey) and (enabled or force) then
                                renderResults(data)
                            end
                        end
                        if not enabled then
                            task.wait(PAUSE_POLL_SEC)
                        else
                            -- Profile belum ready: jangan nunggu scanSec 8s sambil 0.
                            local gap = scanSec
                            if count <= 0 and emptyTries < 24 then
                                emptyTries += 1
                                gap = 0.4
                            else
                                emptyTries = 0
                            end
                            local untilAt = os.clock() + gap
                            while os.clock() < untilAt do
                                if not stillLive(summaryLbl) then
                                    return
                                end
                                if not isInfoSub(cfg.subKey) or not enabled then
                                    break
                                end
                                if G[forceKey] == gen then
                                    break
                                end
                                task.wait(PAUSE_POLL_SEC)
                            end
                        end
                    end
                end
            end)
        end, cfg.order)
    end

    registerBagTab({
        subKey = "egg",
        label = "Egg",
        order = 3,
        genKey = "__STEALEGG_INFO_EGG_GEN",
        forceKey = "__STEALEGG_INFO_EGG_FORCE",
        idSort = "info.egg.sort",
        idScan = "info.egg.scanSec",
        idEnabled = "info.egg.enabled",
        summaryTitle = "Bag Egg",
        enableLabel = "Enable Egg Info",
        groupTitle = "Eggs",
        unit = "egg",
        emptyText = "Backpack kosong · 0 egg.",
        loadingText = "Memuat egg backpack…",
        scan = scanBagEggs,
        summaryLine = function(data)
            return string.format(
                "Eggs: %d  ·  %s  ·  %s/s",
                tonumber(data.count) or 0,
                fmtPrice(data.total),
                fmtNum(data.rate)
            )
        end,
    })

    registerBagTab({
        subKey = "pet",
        label = "Pet",
        order = 4,
        genKey = "__STEALEGG_INFO_PET_GEN",
        forceKey = "__STEALEGG_INFO_PET_FORCE",
        idSort = "info.pet.sort",
        idScan = "info.pet.scanSec",
        idEnabled = "info.pet.enabled",
        summaryTitle = "Bag Pet",
        enableLabel = "Enable Pet Info",
        groupTitle = "Pets",
        unit = "pet",
        emptyText = "Backpack kosong · 0 pet.",
        loadingText = "Memuat pet backpack…",
        showEquipped = true,
        scan = scanBagPets,
        summaryLine = function(data)
            return string.format(
                "Pets: %d  ·  Equip: %d  ·  Bag: %d  ·  %s  ·  %s/s",
                tonumber(data.count) or 0,
                tonumber(data.equippedCount) or 0,
                tonumber(data.bagCount) or 0,
                fmtPrice(data.total),
                fmtNum(data.rate)
            )
        end,
    })

    G.StealEggInfo = M
end

return M
 end,     required = true },
}

local function hasUnreplacedShortcode(s)
    return tostring(s or ""):find("%%%[%[%[", 1, false) ~= nil
end

local function isLoadedModule(mod)
    return type(mod) == "table" and next(mod) ~= nil
end

local function runFactory(def)
    local ok, res = pcall(def.factory)
    if not ok then
        local err = tostring(res)
        if hasUnreplacedShortcode(err) or tostring(def.factory):find("%%%[%[%[", 1, false) then
            return false, "shortcode belum di-stitch -- pakai main_local.lua / main_ui.php"
        end
        return false, "factory error: " .. err
    end
    if type(res) ~= "table" then
        return false, "module bukan table"
    end
    return true, res
end

local Loaded = {}

local function loadDef(def)
    local ok, modOrErr = runFactory(def)
    if ok then
        Loaded[def.key] = modOrErr
        return true
    elseif def.required then
        failBoot(("required module failed: %s | %s"):format(tostring(def.name), tostring(modOrErr)))
    else
        warnlog("Optional skip:", def.name, tostring(modOrErr))
        Loaded[def.key] = {}
    end
    return false
end

-- UI dulu (MainUI/Core/Speed/Move), baru fitur game.
local SHELL = { MainUI = true, Core = true, Speed = true, Move = true }
for _, def in ipairs(MODULE_DEFS) do
    if SHELL[def.key] then
        loadDef(def)
    end
end

local MainUI = Loaded.MainUI
if type(MainUI) ~= "table" or type(MainUI.new) ~= "function" then
    failBoot("MainUI.new tidak ada")
end

local savePath = playerSavePath()
local ui = MainUI.new({
    title = "| STEAL EGG V1 | discord.gg/nodehub",
    savePath = savePath,
    autosave = true,
})

local savedFile = nil
ui._suppressAutosave = true
pcall(function()
    local okLoad, data = ui:Load(savePath)
    if okLoad == true and type(data) == "table" then
        savedFile = data
        G.__StealEggSavedConfig = data
    end
end)

pcall(function()
    task.wait()
end)

for _, def in ipairs(MODULE_DEFS) do
    if not SHELL[def.key] then
        loadDef(def)
    end
end

local AutoTabs = Loaded.AutoTabs
if type(AutoTabs) == "table" and type(AutoTabs.Register) == "function" then
    AutoTabs.Register(ui, Loaded)
else
    failBoot("AutoTabs.Register tidak ada")
end

local MiscTabs = Loaded.MiscTabs
if type(MiscTabs) == "table" and type(MiscTabs.Register) == "function" then
    MiscTabs.Register(ui, Loaded)
else
    failBoot("MiscTabs.Register tidak ada")
end

local InfoTabs = Loaded.InfoTabs
if type(InfoTabs) == "table" and type(InfoTabs.Register) == "function" then
    InfoTabs.Register(ui, Loaded)
else
    failBoot("InfoTabs.Register tidak ada")
end

-- Apply saved settings immediately. Subtab builders only run when that tab
-- is opened, so Sell / Egg / Hop used to stay idle until the user clicked in.
-- Hanya isi key yang belum ada di GetValues/_config -- jangan timpa live
-- toggle ON dengan snapshot boot yang sudah basi.
local function applySaved()
    local values = ui:GetValues() or {}
    local snap = G.__StealEggSavedConfig
    if type(snap) ~= "table" then
        snap = savedFile
    end
    if type(snap) == "table" then
        for k, v in pairs(snap) do
            if values[k] == nil then
                values[k] = v
            end
        end
    end
    G.__StealEggSavedConfig = values
    savedFile = values
    for _, key in ipairs({ "WildEgg", "AutoSell", "Hatch", "Mutation", "IndexComplete", "Scramble", "Rift", "Gear", "Fuse", "AutoHop", "Rejoin", "AntiAfk", "Webhook", "Monitor", "Move", "Dispatch", "Fps", "Esp", "Upgrade", "Claim", "Favorite", "PerfHud" }) do
        local mod = Loaded[key]
        if type(mod) == "table" and type(mod.syncFrom) == "function" then
            pcall(mod.syncFrom, values)
        end
    end
end
applySaved()

G.StealEgg = ui
G.StealEggUI = ui
G.StealEggLoaded = Loaded
G.NodeNeonUI = ui
G.MainUI = MainUI
G.__STEALEGG_READY = true
pcall(function()
    print("[STEAL EGG] stitch", tostring(G.__StealEggStitchAt or "no-stamp (bukan hasil main_ui.php)"))
end)

-- Tab Steal setelah hub ready. Apply lagi setelah widget terpasang.
local function finishBoot()
    pcall(function()
        ui:SetActiveMainTab("auto")
    end)
    applySaved()
    local Monitor = Loaded.Monitor
    if type(Monitor) == "table" and type(Monitor.boot) == "function" then
        pcall(Monitor.boot, ui)
    end
    ui._suppressAutosave = false
end
local later = (task and (task.defer or task.spawn)) or spawn
if type(later) == "function" then
    later(finishBoot)
else
    finishBoot()
end

return ui
